-- Generated by tools/import-quest-texts.js. Fixed priority: WowVoice > CatQuest > Wayfarer.
-- CatQuest: Cathey (daniilcathey), https://t.me/catheyco. Wayfarer: installed voice packs.
WowVoiceQuestTexts = { schemaVersion = 1, sourceVersion = "0.5.0", entries = {
    ["2a"] = { common = "Могучий гиппогриф Острокоготь был убит, и коготь этой свирепой твари – свидетельство вашей победы. Сенани Громосерд на заставе Расщеплённого Древа несомненно пожелает увидеть этот трофей – доказательство ваших деяний." },
    ["2c"] = { male = "Очень впечатляет... коготь Острокогтя непросто добыть! Тебе везёт в охоте! Острый Удар давно донимал батраков с лесозаготовок, когда они пытались добраться сюда, на заставу Расщеплённого Древа. Несомненно, скоро разойдётся весть, что именно ты прикончил чудовище, и множество песен в твою честь будет распеваться у костров и на лесопильнях по всему Ясеневому лесу!", female = "Очень впечатляет... коготь Острокогтя непросто добыть! Тебе везёт в охоте! Острый Удар давно донимал батраков с лесозаготовок, когда они пытались добраться сюда, на заставу Расщеплённого Древа. Несомненно, скоро разойдётся весть, что именно ты прикончила чудовище, и множество песен в твою честь будет распеваться у костров и на лесопильнях по всему Ясеневому лесу!" },
    ["5a"] = { common = "Я прячусь в этом призрачном городе несколько недель и не ел ничего, кроме трав и кореньев! Страшно хочется нормальной еды, и я за неё хорошо заплачу. Устрой мне пир, и не пожалеешь. Говорят, что шеф-повар Груаль в таверне \"Алый ворон\" делает превосходные тёмные пирожки с крабами..." },
    ["5c"] = { common = "Значит, тебе нужны пирожки с крабами? Что ж, могу испечь..." },
    ["6a"] = { male = "Гаррик Тихокрад – головорез, который уже много недель не даёт покоя нашим крестьянам и торговцам. Недавно его видели у лачуги возле виноградников, что к востоку от аббатства, за мостом. Принесёшь мне голову этого негодяя – получишь награду! Но будь осторожен. Гаррик собрал разбойничью шайку. До него непросто будет добраться.", female = "Гаррик Тихокрад – головорез, который уже много недель не даёт покоя нашим крестьянам и торговцам. Недавно его видели у лачуги возле виноградников, что к востоку от аббатства, за мостом. Принесёшь мне голову этого негодяя – получишь награду! Но будь осторожна. Гаррик собрал разбойничью шайку. До него непросто будет добраться." },
    ["6c"] = { male = "Ха! Ты его прикончил! Ты оказал большую услугу Элвину и заслуживаешь хорошей награды!", female = "Ха! Ты его прикончила! Ты оказала большую услугу Элвину и заслуживаешь хорошей награды!" },
    ["6p"] = { common = "Ты нашёл шайку Гаррика? Неужто мы, наконец, избавились от этого бандита?" },
    ["7a"] = { common = "Первое твоё задание, – это зачистка. Северные леса наводнили кобольды. Ступай туда и уничтожь столько кобольдов-вредителей, сколько сможешь. Сократи их число, чтобы в один прекрасный день мы смогли вытеснить их из Североземья." },
    ["7c"] = { common = "Славная работа. Эти кобольды – воры и трусы, но когда их много, они становятся опасны. А людям Штормграда лишняя угроза не нужна. Примите мою благодарность за хорошую работу." },
    ["7p"] = { common = "Как проходит охота, путник? Ты нашёл и уничтожил этих паразитов?" },
    ["8a"] = { male = "Эй, приятель! Сделай одолжение для парня, который более чем достаточно бился с безмозглыми зомби и пауками! У меня тут есть письмецо, которое нужно доставить в Брилл... хозяйке таверны Ренни-как-её-там. Неважно, какая у неё там фамилия! Да и в любом случае, Брилл – это славное уютное местечко, полное жертв чумы, пытающихся как-то выжить в этом мире. Ты и сам сможешь там отдохнуть, если захочешь. По крайней мере, ты должен туда заглянуть... ну а за доставку письма я тебе хорошенько заплачу.", female = "Эй, подруга! Сделай одолжение для парня, который более чем достаточно бился с безмозглыми зомби и пауками! У меня тут есть письмецо, которое нужно доставить в Брилл... хозяйке таверны Ренни-как-её-там. Неважно, какая у неё там фамилия! Да и в любом случае, Брилл – это славное уютное местечко, полное жертв чумы, пытающихся как-то выжить в этом мире. Ты и сама сможешь там отдохнуть, если захочешь. По крайней мере, ты должна туда заглянуть... ну а за доставку письма я тебе хорошенько заплачу." },
    ["8c"] = { common = "Ого! Письмо? Отличная новость! Я давно жду весточки от моей старушки-матери из Могильника. Она настоящая святая – моя мать. Как она там поживает... Что? Слишком фальшивлю? Не купился? Ну так отстань... тебе абсолютно не обязательно знать, от кого это письмо. Давай, давай, иди отсюда! Возвращайся, когда будет что потратить... бродяга. И вообще, приходи сюда отдохнуть, когда устанешь от своих многодневных приключений или другой подобной глупости." },
    ["9a"] = { common = "Взгляните, во что превратилось это место! Когда-то эти земли населяли честные крестьяне. Но проклятые воры выжили отсюда всех. Только не меня! Однако угодья захватили големы – дозорные полей. Если вы готовы поработать, я попросил бы вас пойти и убить двадцать таких големов. Возвращайтесь за оплатой, когда всё будет сделано. Когда расправитесь с теми, что обитают на моём поле, зачистите поля и моих соседей тоже." },
    ["9c"] = { common = "Отличная работа, дружище. Вы полностью отработали свою плату. Кто знает, может быть, Западный Край снова расцветёт." },
    ["10a"] = { common = "Ох, это ужасно! Я послал моего лучшего помощника, младшего геодезиста Холстомера в пустыню, на юго-восток отсюда. Именно там располагается Зияющая бездна. Вот, а теперь он пропал, и в последнем докладе шла речь о странных насекомых. Неужели они наводнили уже два основных района пустыни? Прошу тебя, доберись до Зияющей бездны и поищи там Холстомера! Его... или хотя бы оборудование. Боюсь, больше от бедняги ничего и не осталось." },
    ["10c"] = { common = "Юный Холстомер был хорошим гоблином. Будем надеяться, что его кончина не напрасна, и собранные перед смертью сведения не пропали даром. Похоже, от этих жуков надо ждать неприятностей. Они слишком хитры, но все исследования указывают на то, что эти твари находятся под влиянием третьей стороны! Коли так, беда грозит не только Прибамбасску, но и всей пустыне!" },
    ["11a"] = { common = "На границах Элвиннского леса появились гноллы – звероподобные твари, которым попросту нечего делать в этих краях. К югу от сторожевой башни была замечена большая группа этих существ: их слишком много, чтобы мы сумели с ними справиться. Хуже того: на востоке, у Озера Каменных Столбов, тоже обнаружили гноллов. Армия Штормграда будет благодарна любому, кто поможет справиться с этой угрозой. В доказательство своей победы принеси мне раскрашенные нарукавные повязки гноллов." },
    ["11c"] = { common = "О, вижу, ты слов на ветер не бросаешь! Прими нашу благодарность." },
    ["12a"] = { common = "У народного ополчения есть лишь одна цель: защитить земли Западного Края и вернуть в них мир. К сожалению, приходится это делать путём кровопролития. Один из моих разведчиков сообщил о группе звероловов из Братства Справедливости, наводящих на местных жителей ужас и панику. У меня есть сообщения, что звероловов Братства замечали около Рудника Янго к северо-западу отсюда, а также неподалёку от фермы Мольсена и тыквенной фермы Хмуроброва. Если ты хочешь присоединиться к ополчению, убей пятнадцать звероловов и пятнадцать контрабандистов из Братства Справедливости, а затем возвращайся ко мне." },
    ["12c"] = { common = "Отличная работа. Мой разведчик был свидетелем твои доблестных деяний. Пока что с тобой очень приятно иметь дело." },
    ["13a"] = { male = "Шайка злобных погромщиков из Братства Справедливости разбойничает близ Прииска на Золотом Берегу, Луноречья и усадьбы Алекстона. Народное ополчение не потерпит этого. Разберись с этим немедленно, и пусть весь Западный Край узнает о силе Света. Золотой карьер находится неподалёку от побережья, к западу от башни. В качестве следующего этапа твоего обучения я хочу, чтобы ты убил пятнадцать погромщиков и пятнадцать мошенников из Братства Справедливости.", female = "Шайка злобных погромщиков из Братства Справедливости разбойничает близ Прииска на Золотом Берегу, Луноречья и усадьбы Алекстона. Народное ополчение не потерпит этого. Разберись с этим немедленно, и пусть весь Западный Край узнает о силе Света. Золотой карьер находится неподалёку от побережья, к западу от башни. В качестве следующего этапа твоего обучения я хочу, чтобы ты убила пятнадцать погромщиков и пятнадцать мошенников из Братства Справедливости." },
    ["13c"] = { common = "Ваша значимость для народного ополчения была подкреплена вашими смелыми действиями." },
    ["14a"] = { common = "Некоторые члены Братства Справедливости от нас ускользнули. Один из моих разведчиков, которому я очень доверяю, сообщает, что члены этого братства грабят и разоряют деревни вплоть до Южного Западного Края. Мы считаем, что они скрываются в Холмах Разбойничьих Кинжалов, замышляя новые бесчинства. Убей этих негодяев от имени народного ополчения." },
    ["14c"] = { common = "Я покинул разорённые земли Лордерона, вернувшись на свою родину... и застал её в столь же ужасном состоянии. Но для Западного Края ещё есть надежда. Проявленная тобой доблесть доказала, что ты с честью служишь нашему делу. С огромной гордостью я принимаю тебя в ряды народного ополчения. Да воссияет над тобой Свет!" },
    ["15a"] = { common = "Мои разведчики доносят, что в эти края проникло гораздо больше кобольдов, чем мы рассчитывали. Группа кобольдов-рабочих разбила лагерь близ Рудника Горного Эха к северу отсюда. Отправляйся к шахте и уничтожь их. Насколько нам известно, кобольдов там много... Убей-ка десяток, посмотри, сколько ещё осталось, и доложи мне." },
    ["15c"] = { male = "Меня тревожат сообщения о кобольдах на нашем руднике. К добру это не приведёт. Вот, это твоя награда. Когда будешь готов, приходи ко мне. Буду рад, если ты согласишься предпринять ещё одну вылазку...", female = "Меня тревожат сообщения о кобольдах на нашем руднике. К добру это не приведёт. Вот, это твоя награда. Когда будешь готова, приходи ко мне. Буду рад, если ты согласишься предпринять ещё одну вылазку..." },
    ["15p"] = { common = "Ты был в руднике? Готов доложить об успехах?" },
    ["17a"] = { common = "Мне рассказали о недавно открытом растении, грибе-малиновике. Этот гриб растёт целыми колониями на раскопках Ульдамана, в самой глубине. Наверное, встречается ещё где-то, но мне известно только одно место. Мне хотелось бы изучить возможности его применения в алхимии, и здесь-то ты мне и пригодишься. Отыщи эти грибы и принеси мне дюжину. Только учти: они могут выпустить облако ядовитых спор, если ты их случайно встряхнёшь. Если выполнишь моё поручение, я сделаю для тебя один из моих знаменитых восстановительных эликсиров!" },
    ["17c"] = { male = "Молодец, ты снова показал, на что способен! Эти грибы мне очень пригодятся для исследований! А теперь, как я и обещал, можешь насладиться вкусом одного из моих восстановительных составов из личных запасов... Если ты тоже увлекаешься алхимией, мы можем вдобавок поговорить и о других делах. В любом случае, благодарю за помощь!", female = "Молодец, ты снова показала, на что способна! Эти грибы мне очень пригодятся для исследований! А теперь, как я и обещал, можешь насладиться вкусом одного из моих восстановительных составов из личных запасов... Если ты тоже увлекаешься алхимией, мы можем вдобавок поговорить и о других делах. В любом случае, благодарю за помощь!" },
    ["18a"] = { common = "Тут возле Североземья недавно новая воровская шайка завелась. Зовут себя Братством Справедливости. Видели их за рекой, на востоке. Не знаю, что у них на уме, но наверняка ничего хорошего! Принеси мне их банданы, и в награду получишь оружие." },
    ["18c"] = { male = "Ага, вижу, ты вернулся не с пустыми руками. Армия Штормграда ценит твою помощь.", female = "Ага, вижу, ты вернулась не с пустыми руками. Армия Штормграда ценит твою помощь." },
    ["18p"] = { common = "Ну, добыл мне банданы?" },
    ["19a"] = { common = "Вестники и отступники из клана Чёрной горы постоянно устраивают засады на дороге между городом и крепостью Каменной Стражи. Их предводитель – орк по имени Тарил'зун. Он уже натворил достаточно дел. Принеси мне его голову!" },
    ["19c"] = { common = "Тарил'зун был жестоким и коварным орком. Ты молодчина – я знаю, справиться с ним было нелегко. Вот твоя награда." },
    ["20a"] = { common = "К нам явились орки Чёрной Горы из Пылающих степей и захватили крепость Каменной стражи. Они грабят области к северу от Озёр, и жители тех земель бежали в город, набились в него, словно сельди в бочку. Помоги Приозерью избавиться от этой угрозы. Перебей орков Чёрной Горы и принеси в доказательство десять иззубренных топоров. Хотя орки теснят нас с севера, до нас доходили вести об их появлении и в юго-восточной части Красногорья. Если встретишь их – убивай без колебаний." },
    ["20c"] = { common = "Что ж, чем меньше орков, тем лучше. Большое тебе спасибо." },
    ["21a"] = { common = "Данные твоей предыдущей разведки подтвердились – на Руднике Горного Эха необходимо провести зачистку. Возвращайся на рудник и помоги очистить его от кобольдов. Время дорого. Чем дольше кобольды безнаказанно пробудут в руднике, тем сильнее они закрепятся в Североземье." },
    ["21c"] = { male = "Ты снова заслужил мою похвалу и благодарность армии Штормграда. В руднике ещё достаточно кобольдов, но я отправлю других новобранцев бороться с ними. Для тебя имеются другие поручения.", female = "Ты снова заслужила мою похвалу и благодарность армии Штормграда. В руднике ещё достаточно кобольдов, но я отправлю других новобранцев бороться с ними. Для тебя имеются другие поручения." },
    ["21p"] = { common = "Я знаю, это поганая работа, путник, но её необходимо выполнить ради безопасности Североземья. Ты готов предоставить отчёт?" },
    ["22a"] = { common = "Лук очищен. Чеснок раздавлен. Розмарин измельчён. Основа выпечена. Укроп нарезан. Соус вымешан до гладкости. Всё, что мне ещё нужно для моего знаменитого пирога – это восемь кусков печени жутеклыка!" },
    ["22c"] = { male = "Замечательные куски! Большое тебе спасибо! Мы с фермером Сальденом устроим сегодня настоящий праздник. А это – для тебя, за труды. У тебя ведь не было мысли, что герой вроде тебя останется без угощения, а?", female = "Замечательные куски! Большое тебе спасибо! Мы с фермером Сальденом устроим сегодня настоящий праздник. А это – для тебя, за труды. У тебя ведь не было мысли, что героиня вроде тебя останется без угощения, а?" },
    ["23a"] = { common = "Вот лапа могучего медведя Топтыжня – ваш трофей этого этапа охоты. На лапе есть маленький знак – месяц. Смысл этого знака покрыт тайной. Эту лапу надо отнести Сенани Громовое Сердце на заставу Расщеплённого Древа, чтобы доказать, что вы одолели могучую тварь, тем самым завершив этот этап охоты." },
    ["23c"] = { male = "О, лапа Топтыжня! Твои навыки меня впечатлили, герой. Говорят, он многих убил. Месяц на его лапе ясно говорит о том, что его обучали ночные эльфы, которые рыщут по Ясеневому лесу. Топтыжень был одним из самых могучих медведей, которых только можно сыскать в этих краях. Убить такую тварь – истинное испытание воли и решимости. Твои предки гордились бы тобой!", female = "О, лапа Топтыжня! Твои навыки меня впечатлили, героиня. Говорят, он многих убил. Месяц на его лапе ясно говорит о том, что его обучали ночные эльфы, которые рыщут по Ясеневому лесу. Топтыжень был одним из самых могучих медведей, которых только можно сыскать в этих краях. Убить такую тварь – истинное испытание воли и решимости. Твои предки гордились бы тобой!" },
    ["24a"] = { common = "Некогда стремительный Тенумбра лежит у ваших ног. Вы победили. Голова убитого ночного саблезуба – достойный трофей этой схватки в ходе охоты. Сенани Громосерд на заставе Расщеплённого Древа захочет увидеть ваш трофей и наградить вас за этот этап охоты." },
    ["24c"] = { common = "Победа в Ашенвальской охоте! Отлично! Голова Тенумбры, вне всякого сомнения, – достойный трофей столь впечатляющей схватки. Дикий нрав Тенумбры был хорошо известен на заставе. Из-за этого чудовища любое путешествие от Зорамского взморья на запад, особенно пешком, было рискованным. Благодаря тебе этой угрозы больше не существует." },
    ["25a"] = { male = "Если хочешь принести пользу, то почему бы тебе не разобраться с ситуацией у Туннеля Когтя? Сообщение между Ясеневым лесом и Каменным Когтем замерло из-за того, что из озера лезет всякая дрянь и нападает на всё, что только подойдёт поближе... то есть, на всё, что на дороге. Но куда лучше простой разборки с элементалями воды будет вот что – разведай-ка беседку на озере Мистраль – ту, с которой открывается отличный вид на соседний форт Альянса. Ну, готов принести пользу?", female = "Если хочешь принести пользу, то почему бы тебе не разобраться с ситуацией у Туннеля Когтя? Сообщение между Ясеневым лесом и Каменным Когтем замерло из-за того, что из озера лезет всякая дрянь и нападает на всё, что только подойдёт поближе... то есть, на всё, что на дороге. Но куда лучше простой разборки с элементалями воды будет вот что – разведай-ка беседку на озере Мистраль – ту, с которой открывается отличный вид на соседний форт Альянса. Ну, готова принести пользу?" },
    ["25c"] = { common = "Да я слышал, как что-то пролетело по озеру подобно пыльной буре Степей. По звуку мы сможем найти пригодный наблюдательный пункт, чтобы присматривать за нашими друзьями из Альянса. Да, только если будем сидеть тихо... Похоже, от тебя тут больше толку не будет – сообщение между здешними местами и Каменным Когтем налажено. Возьми вот это – заслужил." },
    ["26a"] = { male = "Я с удовольствием наблюдал за твоими успехами. Ты непременно станешь знаменитым защитником природы. Пришла пора тебе узнать побольше об одном из многих аспектов животных, способность обращаться в которых даровал нам Кенарий. Об аспекте, который даёт тебе власть над водой. Для этого тебе следует отправиться в селение Ночная Гавань на Лунной поляне и поговорить с Дендритом Блеском Звёзд из Круга Кенария. Он будет твоим наставником.", female = "Я с удовольствием наблюдал за твоими успехами. Ты непременно станешь знаменитой защитницей природы. Пришла пора тебе узнать побольше об одном из многих аспектов животных, способность обращаться в которых даровал нам Кенарий. Об аспекте, который даёт тебе власть над водой. Для этого тебе следует отправиться в селение Ночная Гавань на Лунной поляне и поговорить с Дендритом Блеском Звёзд из Круга Кенария. Он будет твоим наставником." },
    ["26c"] = { common = "Мой поклон юному друиду. Пришла пора тебе познать наш водный облик. В нём ты сможешь свободно и сколько угодно перемещаться в воде. Этот аспект будет для тебя полезным инструментом и благословением... Но прежде чем овладеть этой способностью, её надо заслужить. Тебе предстоит пройти два испытания. Первое – испытание твоей способности работать под тяжестью воды. Второе – испытание твоей решимости познать аспекты самого облика. Готовься – время испытания пришло." },
    ["27a"] = { male = "Я с удовольствием наблюдал за твоими успехами. Ты непременно станешь знаменитым защитником природы. Пришла пора тебе узнать побольше об одном из многих аспектов животных, способность обращаться в которых даровал нам Кенарий. Об аспекте, который даёт тебе власть над водой. Для этого тебе следует отправиться в селение Ночная Гавань на Лунной поляне и поговорить там с Дендритом Блеском Звёзд из Круга Кенария. Он будет твоим наставником.", female = "Я с удовольствием наблюдал за твоими успехами. Ты непременно станешь знаменитой защитницей природы. Пришла пора тебе узнать побольше об одном из многих аспектов животных, способность обращаться в которых даровал нам Кенарий. Об аспекте, который даёт тебе власть над водой. Для этого тебе следует отправиться в селение Ночная Гавань на Лунной поляне и поговорить там с Дендритом Блеском Звёзд из Круга Кенария. Он будет твоим наставником." },
    ["27c"] = { common = "Мой поклон юному друиду. Пришла пора тебе познать наш водный облик. В нём ты сможешь свободно и сколько угодно перемещаться в воде. Этот аспект будет для тебя полезным инструментом и благословением... Но прежде чем овладеть этой способностью, её надо заслужить. Тебе предстоит пройти два испытания. Первое – испытание твоей способности работать под тяжестью воды. Второе – испытание твоей решимости познать аспекты самого облика. Готовься – время испытания пришло." },
    ["28a"] = { common = "Вот твоё первое испытание – исследуй глубины озера Элуны и найди безделушку святилища. Она быстро разрушается, так что не медля отнеси её к святилищу Ремулоса. Используй эту безделушку в святилище, а затем поговори там с Таджарри – это одна из самых доверенных хранительниц Лунной поляны. На всё испытание тебе даётся ограниченное количество времени, и возможно, тебе придётся соревноваться с другими друидами, которые тоже ищут безделушки. Быстрота ума и ловкость тела помогут тебе добиться успеха. Удачи тебе." },
    ["28c"] = { male = "Что же, сдаётся мне, ещё один друид успешно прошёл Испытание Озера! Хвалю тебя, мой юный друг. Как я уже сказала, моё имя Таджарри. Мой долг и привилегия – оберегать Лунную поляны и, в особенности, это святилище. Хранитель Ремул наставляет Круг Кенария в деле сохранения природы и равновесия, а его святилище – мощный вклад в это дело. Использовав здесь безделушку, ты отдал дань уважения этому месту.", female = "Что же, сдаётся мне, ещё один друид успешно прошёл Испытание Озера! Хвалю тебя, мой юный друг. Как я уже сказала, моё имя Таджарри. Мой долг и привилегия – оберегать Лунную поляны и, в особенности, это святилище. Хранитель Ремул наставляет Круг Кенария в деле сохранения природы и равновесия, а его святилище – мощный вклад в это дело. Использовав здесь безделушку, ты отдала дань уважения этому месту." },
    ["29a"] = { common = "Вот твоё первое испытание – исследуй глубины озера Элуны и найди безделушку святилища. Она быстро разрушается, так что не медля отнеси её к святилищу Ремулоса. Используй эту безделушку в святилище, а затем поговори там с Таджарри – это одна из самых доверенных хранительниц Лунной поляны. На всё испытание тебе даётся ограниченное количество времени, и возможно, тебе придётся соревноваться с другими друидами, которые тоже ищут безделушки. Быстрота ума и ловкость тела помогут тебе добиться успеха. Удачи тебе." },
    ["29c"] = { male = "Что же, сдаётся мне, ещё один друид успешно прошёл Испытание Озера! Хвалю тебя, мой юный друг. Как я уже сказала, моё имя Таджарри. Мой долг и привилегия – оберегать Лунную поляны и, в особенности, это святилище. Хранитель Ремул наставляет Круг Кенария в деле сохранения природы и равновесия, а его святилище – мощный вклад в это дело. Использовав здесь безделушку, ты отдал дань уважения этому месту.", female = "Что же, сдаётся мне, ещё один друид успешно прошёл Испытание Озера! Хвалю тебя, мой юный друг. Как я уже сказала, моё имя Таджарри. Мой долг и привилегия – оберегать Лунную поляны и, в особенности, это святилище. Хранитель Ремул наставляет Круг Кенария в деле сохранения природы и равновесия, а его святилище – мощный вклад в это дело. Использовав здесь безделушку, ты отдала дань уважения этому месту." },
    ["30a"] = { common = "Вот твоё второе испытание – тебе понадобятся две половинки подвески Морского Льва. Одна половинка черпает мощь из ловкости аспекта морского льва, скользящего в бездне вод, вторая черпает силу из невероятной выносливости аспекта морского льва. Друидов привлекают обе эти черты, олицетворяющие аспект их водного облика. Поговори с жителями Лунной поляны, чтобы узнать, где могут находиться эти половинки, и принеси их, чтобы соединить. Сделав это, отнеси подвеску Дендриту Блеску Звёзд." },
    ["30c"] = { male = "Ты прошёл испытание Морского Льва. Прими мои поздравления. Каждый шаг на пути обретения этой подвески должен был показать тебе, насколько важны ловкость и выносливость в перемещениях под водой. Одно не существует без другого, и эти качества нельзя обрести без желания принять аспект морского льва. Запомни хорошенько этот урок и полагайся на него, когда научишься принимать водный облик.", female = "Ты прошла испытание Морского Льва. Прими мои поздравления. Каждый шаг на пути обретения этой подвески должен был показать тебе, насколько важны ловкость и выносливость в перемещениях под водой. Одно не существует без другого, и эти качества нельзя обрести без желания принять аспект морского льва. Запомни хорошенько этот урок и полагайся на него, когда научишься принимать водный облик." },
    ["31a"] = { male = "Ты завершил обучение, которое проходят все начинающие друиды прежде, чем они смогут принимать водный облик. Теперь возвращайся к своему наставнику, Тюраку Руническому Тотэму в Громовой Утёс. Покажи ему свою подвеску и докажи, что ты готов усвоить его уроки. Он завершит твоё обучение, благодаря которому ты станешь единым с водой. Доброго тебе пути, юный друид. Мы ещё встретимся.", female = "Ты завершила обучение, которое проходят все начинающие друиды прежде, чем они смогут принимать водный облик. Теперь возвращайся к своему наставнику, Тюраку Руническому Тотэму в Громовой Утёс. Покажи ему свою подвеску и докажи, что ты готова усвоить его уроки. Он завершит твоё обучение, благодаря которому ты станешь единой с водой. Доброго тебе пути, юный друид. Мы ещё встретимся." },
    ["31c"] = { male = "Великолепно. Твои предки могут гордиться твоими успехами! Ты готов принять водный облик, и я с радостью научу тебя этому. Прими также эту вещицу в знак признания твоих успехов в двух испытаниях. Надеюсь, тебе будет приятно присоединить её к своему снаряжению защитника Природы и хранителя равновесия.", female = "Великолепно. Твои предки могут гордиться твоими успехами! Ты готова принять водный облик, и я с радостью научу тебя этому. Прими также эту вещицу в знак признания твоих успехов в двух испытаниях. Надеюсь, тебе будет приятно присоединить её к своему снаряжению защитника Природы и хранителя равновесия." },
    ["32a"] = { common = "Вот твой отчёт. Прошу тебя, отнеси его кому-нибудь, сведущему в такого рода вопросах. Я слышал про учёного-тролля по имени Зилзибин Барабанный Бой. Он посвятил много времени изучению форм жизни, встречающихся лишь в Азероте; он и историк заодно! Если ты хочешь, чтобы кто-то объяснил, что именно происходит и как это прекратить, обратись к нему. Нам любая помощь не помешает. Его дом находится во втором ряду Волока в Оргриммаре." },
    ["32c"] = { common = "Что до твоего отчёта... да, я уже встречался с этими тварями. Рудознатец правильно поступил, отправив это письмо и тебя ко мне. Эти существа мигом пожрут всю пустыню Танарис; они представляют собой одну из величайших опасностей, с которой только можно столкнуться. Знакомься – это силитиды. Так зовутся странные насекомые, которые служат величайшему злу, грозящему и Орде, и Альянсу. Жаль, что нам не хватило ума понять это раньше." },
    ["33a"] = { common = "Ненавижу этих мерзких лесных волков! Но я бы не прочь полакомиться бифштексами из волчатины... Принеси мне жёсткой волчатины, и в обмен я предложу тебе что-нибудь полезное. Убей несколько лесных волков и молодых волков, что водятся в североземских лесах, и принеси мне их мясо." },
    ["33c"] = { male = "Ну, ты на славу постарался! Прямо не терпится поджарить волчатинки... У меня есть кое-что интересное для тебя – выбирай!", female = "Ну, ты на славу постаралась! Прямо не терпится поджарить волчатинки... У меня есть кое-что интересное для тебя – выбирай!" },
    ["33p"] = { common = "Эй, путник! Я уж проголодался… Ты принёс волчатину?" },
    ["34a"] = { common = "Мой сад снова разграблен и вытоптан. И я знаю, кто это сделал! Это проклятый вепрь, которого маршал Маррис прозвал Грубобрюхом. Теперь мне долго не удастся посадить нарциссы. Они загублены! И во всём виноват мерзкий кабан. Положи конец этому паразиту! Принеси мне его клык, и я с удовольствием вознагражу тебя. Говорят, он пасётся в полях на юго-западе от Озёр, но порой заходит и сюда, в мой сад." },
    ["34c"] = { male = "Наконец-то моему саду ничего не грозит! Спасибо тебе, ты оказал мне большую услугу. Теперь мой сад расцветёт с небывалой пышностью!", female = "Наконец-то моему саду ничего не грозит! Спасибо тебе, ты оказала мне большую услугу. Теперь мой сад расцветёт с небывалой пышностью!" },
    ["35a"] = { common = "Если ты думаешь, что слухи о мурлоках могут оказаться правдой, отправляйся к восточному мосту Элвиннского леса и поговори со стражником Томасом. Он уже неделю несёт стражу у моста и должен знать, что там происходит на самом деле. Принеси мне его отчёт." },
    ["35c"] = { common = "Да, это правда: мурлоки поселились в реках и на их берегах в западной части леса. Мы не знаем, почему они пришли сюда, но их следует остерегаться: они агрессивны и довольно умны." },
    ["36a"] = { common = "Никогда я не думала, что наступит день, когда я покину ферму. Но поля кишат разбойниками, и для нас теперь тут слишком опасно. Как только фермер Хмуробров починит повозку, мы отправимся в путь. Может быть, ты окажешь мне услугу? Я напишу рецепт похлёбки Западного Края, а ты отнесёшь его Сальме Сальден вон на ту ферму – она сразу за развилкой дороги." },
    ["36c"] = { common = "Эта Верна всегда была такой милой девушкой. Нам будет её не хватать здесь, в Западном Крае, но, только между нами, в душе она – городская жительница, и Штормград – местечко как раз для неё. Ладно, хватит сплетничать! Начнём же готовить похлёбку Западного Края!" },
    ["37a"] = { common = "Несколько дней назад мы отправили на обследование берегов реки двух наших стражей, Рольфа и Малакаи; ни один из них до сих пор не вернулся. Чтобы составить полный отчёт, мне нужно выяснить, что с ними случилось. Отправляйся на север вдоль реки и разыщи стражей... или хотя бы их останки." },
    ["37c"] = { common = "Хотя на трупе мало что осталось, рядом с ним оказался медальон с надписью \"Камень пехотинца Малакаи\"." },
    ["38a"] = { common = "Помоги мне сварить похлёбку Западного Края! Мне нужны для неё следующие ингредиенты: Три куска жилистого мяса стервятника Три рыла жутеклыка Три глаза мурлока Три окры" },
    ["38c"] = { common = "Окра отлично загустит бульон! А теперь мы просто добавим жилистого мяса стервятника, несколько глаз мурлока и эти вкуснейшие рыла жутеклыка. И вот всё готово! За оказанную помощь, я предлагаю тебе отведать первую порцию похлёбки Западного Края." },
    ["39a"] = { common = "Нужно сообщить маршалу Дугхану о смерти Малакаи и Рольфа. Наши войска на востоке Элвиннского леса не смогут справиться с мурлоками. Я знаю, лишних солдат у нас нет, но, может, Дугхан пришлёт хоть какую-то помощь..." },
    ["39c"] = { common = "Да, вести невесёлые... Людей у нас и так немного, а теперь, когда мурлоки прикончили Рольфа и Малакаи, будет и вовсе несладко. Если положение не изменится к лучшему, боюсь, к концу недели бои будут идти уже в Златоземье..." },
    ["40a"] = { common = "В Элвиннском лесу появилась новая напасть. Мурлоки поднялись вверх по рекам в восточной части леса, они распугивают рыбу и нападают на мирных жителей. Я предупреждал маршала Дугхана, но его больше беспокоит нашествие гноллов и бандитов. Мурлоков он вообще не принимает в расчёт. Я прошу тебя, поговори с Дугханом и постарайся убедить его послать отряд на восток!" },
    ["40c"] = { common = "Да, верно, я говорил с Реми. Поверь, я очень высоко ценю его как торговца, но все отчёты о появлении мурлоков на востоке крайне недостоверны. Я понимаю твою тревогу, но пока не будут получены надёжные сведения о мурлоках, никаких войск на восток я посылать не стану." },
    ["45a"] = { common = "При осмотре местности были обнаружены запутанные следы, ведущие на восток вдоль берега Озера Каменных Столбов. В отдалении видно поселение мурлоков. Возможно, именно здесь и окончил свой путь Рольф..." },
    ["45c"] = { common = "На шее трупа вы находите медальон с надписью \"Пехотинец Рольф Хартфорд\"." },
    ["46a"] = { common = "Армия Штормграда назначила награду за мурлоков – скрытней и добытчиков. Убей их и принеси мне их плавники: армия хорошо за это заплатит. Мурлоки построили селение на Озере Каменных Столбов – это к северу отсюда; ещё одно селение расположено на юге – там, где русло реки разделяется надвое." },
    ["46c"] = { common = "Что у нас тут? Плавники? Отлично! Маршал Дугхан обеспокоен мурлоками, поселившимися на востоке леса. Он будет рад узнать, что ситуация под контролем. Твоя помощь в этом деле была просто неоценимой." },
    ["47a"] = { common = "Кобольды в этих местах иногда носят с собой Золотую пыль. Достань мне этой пыли, и я дам за неё лучшую цену в городе! Лучшую цену в городе! Кобольдов можно найти на юге, на руднике Подземных глубин, или на северо-востоке, рядом с Яшмовой шахтой." },
    ["47c"] = { common = "Благодарю за пыль. Вот твои деньги... А вот и маленький подарочек от моих друзей. Возможно, он тебе пригодится... Да, пригодится." },
    ["48a"] = { common = "Где-то в южных краях, там, где вьётся лоза Есть колодец с водой, что чиста как слеза. Бьёт священной воды одинокий ручей, Будь же другом, скорей, отправляйся за ней!" },
    ["48c"] = { common = "И-ик! Хо-хо!" },
    ["49a"] = { common = "Как прекрасна янтарная россыпь зерна! Словно жаром костра пропиталась она. Чтобы вышел наш пенный напиток хорош, Ты ячмень мне добудь, кукурузу и рожь." },
    ["49c"] = { common = "И-ик! Хо-хо!" },
    ["50a"] = { common = "Прочь дремота и лень! Встану я поутру, Замешаю зерно и в сусло разотру, Сплавить куб перегонный - и будет добро! Только истинных свойств подойдёт серебро." },
    ["50c"] = { common = "И-ик! Хо-хо!" },
    ["51a"] = { common = "Хочешь, друг мой, на брагу взглянуть? - так и быть! Нам осталось лишь только её процедить. Ветвь смоковницы даст нам немного угля, Будет хмельный напиток светлей янтаря!" },
    ["51c"] = { common = "И-ик! Хо-хо!" },
    ["52a"] = { common = "Приветствую. Чем дальше от Златоземья, тем агрессивнее становятся дикие звери: на Лесопилку Восточной долины постоянно нападают волки и медведи. Хочешь нам помочь?" },
    ["52c"] = { common = "Я так тебе благодарен!.. Похоже, в этом лесу поселилось что-то, что гонит зверей прямо на нас. Что бы там ни было, хотел бы я, чтобы оно не покидало леса..." },
    ["53a"] = { common = "Вот медовая брага готова вполне, Словно солнце играет в её глубине! Мы в дубовый бочонок её разольём, А потом насладимся напитком вдвоём!" },
    ["53c"] = { common = "Углём отфильтровано, вызрело в бочке, Восторг, упоение в каждом глоточке. Поднимем же тост за тебя, за меня И за сладкий напиток цвета янтаря!" },
    ["54a"] = { male = "Ты – герой, чья верность интересам Североземья ни для кого не является тайной. Теперь тебе поручается защита Элвиннского леса. Если ты принимаешь это поручение, то вот бумаги, которые я подготовил для отправки маршалу Дугхану в Златоземье. Златоземье находится на южном тракте, за пограничными воротами.", female = "Ты – героиня, чья верность интересам Североземья ни для кого не является тайной. Теперь тебе поручается защита Элвиннского леса. Если ты принимаешь это поручение, то вот бумаги, которые я подготовил для отправки маршалу Дугхану в Златоземье. Златоземье находится на южном тракте, за пограничными воротами." },
    ["54c"] = { male = "Что же, тут говорится, что ты был назначен полномочным представителем маршалов Штормграда. Прими мои поздравления. И удачи тебе... Охранять Элвинн - это непростая работа. Да ещё когда большая часть армии занимается непонятно чем по приказу какого-то аристократишки! В наши мрачные времена политика - дело тёмное...", female = "Что же, тут говорится, что ты была назначена полномочным представителем маршалов Штормграда. Прими мои поздравления. И удачи тебе... Охранять Элвинн - это непростая работа. Да ещё когда большая часть армии занимается непонятно чем по приказу какого-то аристократишки! В наши мрачные времена политика - дело тёмное..." },
    ["54p"] = { common = "У тебя сообщение от маршала Макбрайда? Североземье по сравнению с Элвиннским лесом — мирный сад, но мне любопытно, о чём пишет Макбрайд. Дайте-ка мне бумаги…" },
    ["55a"] = { male = "Морбент Скверн прячется в своём доме на вершине холма на востоке, рядом с кладбищем Вороньего холма. Пора положить конец его бесчинствам в наших землях… Примени против него Проклятье Морбента, оно обратит в прах всю его защитную магию. Убей его. Убей негодяя и избавь нас от его гнусных козней. Стань орудием возмездия, герой Сумеречного леса.", female = "Морбент Скверн прячется в своём доме на вершине холма на востоке, рядом с кладбищем Вороньего холма. Пора положить конец его бесчинствам в наших землях… Примени против него Проклятье Морбента, оно обратит в прах всю его защитную магию. Убей его. Убей негодяя и избавь нас от его гнусных козней. Стань орудием возмездия, героиня Сумеречного леса." },
    ["55c"] = { male = "Морбент Скверн убит. Тёмные всадники по-прежнему топчут наши земли, но всё же мы одержали победу, хотя и неполную. Я надеялся на это вопреки всему. Ты совершил невозможное, и легенды о тебе будут ходить во всему Сумеречному лесу. Ступай. Быть может, судьба вновь приведёт тебя ко мне...", female = "Морбент Скверн убит. Тёмные всадники по-прежнему топчут наши земли, но всё же мы одержали победу, хотя и неполную. Я надеялся на это вопреки всему. Ты совершила невозможное, и легенды о тебе будут ходить во всему Сумеречному лесу. Ступай. Быть может, судьба вновь приведёт тебя ко мне..." },
    ["56a"] = { male = "Я – командир Ночного дозора, и мой долг – охранять покой жителей Темнолесья. Солдаты Штормграда оставили свои посты, предоставив нас самим себе. Если ты готов на подвиги, помоги нам! Отправляйся в Застывшие сады на юге от Темнолесья и убей восемь скелетов-воинов и восемь магов-скелетов. Мы должны дать отпор нежити!", female = "Я – командир Ночного дозора, и мой долг – охранять покой жителей Темнолесья. Солдаты Штормграда оставили свои посты, предоставив нас самим себе. Если ты готова на подвиги, помоги нам! Отправляйся в Застывшие сады на юге от Темнолесья и убей восемь скелетов-воинов и восемь магов-скелетов. Мы должны дать отпор нежити!" },
    ["56c"] = { common = "Великолепно. За верную службу народу Темнолесья тебе полагается награда." },
    ["57a"] = { common = "Я получила сведения о появлении нежити в наших лесах! Если ты не боишься, отправляйся на кладбище Вороньего холма и убей пятнадцать скелетов-губителей и пятнадцать ужасных скелетов. Также говорят, что скелеты появились и к югу от Темнолесья, на Безмятежном кладбище. Мы должны изгнать нежить из Сумеречного леса!" },
    ["57c"] = { male = "Народ Темнолесья благодарит тебя. Ты доказал свою преданность Ночному дозору.", female = "Народ Темнолесья благодарит тебя. Ты доказала свою преданность Ночному дозору." },
    ["58a"] = { common = "Обстановка на Вороньем холме не улучшилась. Безопасность Темнолесья – в твоих руках. У нас не хватает стражей для обеспечения безопасности города. Придётся тебе снова отправиться на Вороний холм и уничтожить двадцать распространителей чумы в восточном мавзолее." },
    ["58c"] = { common = "Я благодарю тебя, от лица народа Темнолесья и от себя, как главы Ночного дозора, за храбрость и преданность общему делу. Да озарит Свет твой путь!" },
    ["59a"] = { common = "Твои хитроумие и доблесть должны быть вознаграждены. Я приготовил для тебя знак: он пригодится для какой-нибудь части доспехов. Отнеси его Саре Тимберлейн на Лесопилку Восточной долины: она изготовит для тебя броню, или что там тебе будет нужно. Мне хотелось бы надеяться, что новые доспехи помогут тебе, в защите Элвиннского леса от врагов. Лесозаготовки находятся к востоку от сторожевого поста Томаса." },
    ["59c"] = { male = "Ага, вот и знак! Благодарю. Можешь выбрать любой доспех, какой тебе нужен. Желаю удачи, герой! Надеюсь, новый доспех тебе пригодится.", female = "Ага, вот и знак! Благодарю. Можешь выбрать любой доспех, какой тебе нужен. Желаю удачи, героиня! Надеюсь, новый доспех тебе пригодится." },
    ["60a"] = { male = "Приветствую тебя, добрый путник! Не найдётся ли у тебя свободной минутки? Мы с братом держим аптеку в Штормграде; так вот, мне тут понадобились большие свечи. Воск нужен, понимаешь? Я вот и думаю: может, ты мне поможешь? Свечи можно достать у кобольдов, а кобольдов, по слухам, в Элвиннских рудниках видимо-невидимо: и в руднике Подземных глубин к югу отсюда, и в Яшмовой шахте на востоке... Может, прогуляешься туда и раздобудешь для меня свечи?", female = "Приветствую тебя, прекрасная госпожа! Не найдётся ли у тебя свободной минутки? Мы с братом держим аптеку в Штормграде; так вот, мне тут понадобились большие свечи. Воск нужен, понимаешь? Я вот и думаю: может, ты мне поможешь? Свечи можно достать у кобольдов, а кобольдов, по слухам, в Элвиннских рудниках видимо-невидимо: и в руднике Подземных глубин к югу отсюда, и в Яшмовой шахте на востоке... Может, прогуляешься туда и раздобудешь для меня свечи?" },
    ["60c"] = { common = "Ну что, пришлось попотеть? Спасибо за свечи! А вот и твоя награда..." },
    ["61a"] = { common = "В Штормграде мой брат Морган ждёт посылки со свечами. У меня нет времени съездить туда самому, но если ты окажешь нам эту услугу, Морган хорошо тебе заплатит. Вот, я тут упаковал свечи. А Моргана найти несложно, он работает в Торговом квартале Штормграда, в аптеке Песта." },
    ["61c"] = { common = "Вот плата за услугу... Кстати, можешь тут пока осмотреться: уверен, у нас наверняка найдётся какое-нибудь зелье или безделушка, которые тебе пригодятся..." },
    ["62a"] = { common = "Рудник в Североземье – не единственная головная боль. До меня дошли известия о том, что и на элвиннском руднике Подземных глубин поселились кобольды. Нужно исследовать рудник и подтвердить эти известия или опровергнуть их. Я буду ждать отчёта. Рудник расположен к югу от Златоземья, между фермами Стоунфилд и Маклур." },
    ["62c"] = { common = "Скверные вести. И что дальше? Может, драконы?! Похоже, придётся усилить охрану рудника. Спасибо тебе. И подожди, не уходи... возможно, у меня найдётся для тебя ещё одно задание." },
    ["63a"] = { common = "На побережье Серебряного Бора, к западу от Гробницы, находится святилище, осквернённое чумой. Духи перестали разговаривать с нашим народом, и тебе предстоит победить воплощение воды и очистить купель. Возьми браслеты элементалей и остатки зелья Брин и помести их в жаровню. Этот ритуал позволит призвать чистого духа, с которым можно будет поговорить. Принеси мне доказательство того, что моё задание выполнено, и в награду я дам тебе тотэм." },
    ["63c"] = { common = "Вы помещаете браслеты в жаровню и выливаете в огонь оставшиеся капли зелья Брин. Пламя потрескивает, а вы начинаете проговаривать простые слова, которым вас обучила Ислен..." },
    ["64a"] = { common = "Это было ужасно! Верна разбудила меня, когда услышала гвалт в поле. Поля были полны хулиганья. Мы бежали в спешке, и я забыл взять с собой карманные часы. Папаша Верны подарил мне эти часы в день нашей с ней свадьбы, и мне прямо нехорошо от мысли, что ими могли завладеть те воры. Я оставил часы в доме, в платяном шкафу. Ищи тыквенную ферму к западу отсюда – ты её не пропустишь. Если вернёшь мне мои часы, я буду очень признателен!" },
    ["64c"] = { male = "Мои часы! Благодарю тебя, любезный господин! Мы всего лишь бедные фермеры, потерявшие свою землю, но прошу тебя, прими эту награду в знак нашей признательности.", female = "Мои часы! Благодарю тебя, любезная госпожа! Мы всего лишь бедные фермеры, потерявшие свою землю, но прошу тебя, прими эту награду в знак нашей признательности." },
    ["65a"] = { male = "Группа негодяев, ответственных за то, что честные люди покидают Западный Край, зовёт себя Братством Справедливости. Мне нужно, чтобы ты проник в эту бандитскую шайку. Нам нужно узнать, кто её главарь, и где они прячутся. В деревне Приозерье, в таверне, обитает некий Вилли, который мне кое-чем обязан. Отправляйся в деревню Приозерье, что расположена в Красногорье, к востоку от Элвиннского леса, и всё разузнай.", female = "Группа негодяев, ответственных за то, что честные люди покидают Западный Край, зовёт себя Братством Справедливости. Мне нужно, чтобы ты проникла в эту бандитскую шайку. Нам нужно узнать, кто её главарь, и где они прячутся. В деревне Приозерье, в таверне, обитает некий Вилли, который мне кое-чем обязан. Отправляйся в деревню Приозерье, что расположена в Красногорье, к востоку от Элвиннского леса, и всё разузнай." },
    ["65c"] = { common = "Так значит, тебя послал Камнегрив? Что ж, я перед ним в долгу." },
    ["66a"] = { common = "Вчера ночью меня охватил беспричинный ужас. Я почувствовала, что моя внучка Алисса оказалась в страшной опасности. Я разложила карты... и со стола на меня взглянула Смерть. Погрузившись в длительный и тяжкий транс, я сумела разгадать эту тёмную тайну. Мне открылось имя: Сталван. Отыщи клерка в городской Ратуше и постарайся побольше разузнать об этом Сталване. Я опасаюсь за всех нас." },
    ["66c"] = { common = "А, так тебя послала мадам Ева..." },
    ["67a"] = { common = "Сталван, значит? Дай-ка погляжу в журнал. Сталван... Сталван... Ну-ка... А, вот он! У меня есть запись о некоем господине Сталване Мистмантле. Последний адрес – Лунореченская школа. Но это было так давно! Окажи любезность, дай знать, если выяснишь что-либо об этом типе. Записи должны содержаться в порядке." },
    ["67c"] = { common = "Старый сундук со скрипом открывается..." },
    ["68a"] = { common = "Вы находите в старом сундуке пыльное неотосланное письмо." },
    ["68c"] = { common = "Занятно. Значит, этот тип всё же побывал в Луноречье. Странно, что письмо так и не доставили. Тем не менее я обновлю записи в журнале." },
    ["69a"] = { common = "Боже мой! Сразу и не заметил. В журнале, точно под первым адресом Сталвана, написан ещё один адрес, частично вычеркнутый. Похоже, он направлялся в таверну \"Гордость льва\" в Златоземье. Можешь поискать сведения там." },
    ["69c"] = { common = "Сталван? Знакомое имя." },
    ["70a"] = { common = "Имя Сталван мне знакомо. А, вспомнил. Много лет назад ненастной ночью в трактир явился гонец, искавший убежища от непогоды. Около полуночи этот человек, бледный от страха, сбежал вниз по лестнице в пижаме и исчез. Второпях он оставил письма в сундуке на втором этаже. За ними он так и не вернулся. Осталось одно, от этого Сталвана. Адресовано оно в район каналов Штормграда. Можешь прочитать." },
    ["70c"] = { common = "А ты не робкого десятка, раз решился доставить это." },
    ["71a"] = { common = "Теперь, когда вы нашли оба медальона, отнесите их к мосту и отдайте стражнику Томасу: он должен узнать о смерти обоих стражей." },
    ["71c"] = { common = "Увы, мои худшие опасения подтвердились. Мурлоки – это угроза, с которой придётся считаться..." },
    ["72a"] = { common = "Мой отец был сторожем в этом поместье задолго до меня. Ему-то и пришлось вытирать кровь после того убийства. Но это к делу не относится. Последние деньги треста Кременника давно иссякли. А теперь и последние семейные ценности отправляются прямиком на аукцион. Проклятые сборщики налогов!.. Пожалуй, если ты хочешь узнать побольше, можешь порыться в этом барахле. Кто знает, что тебе попадётся." },
    ["72c"] = { common = "Вы медленно снимаете крышку с ящика..." },
    ["74a"] = { common = "Внутри ящика вы находите много разных вещей: пыльные фамильные ценности, портрет, несколько охотничьих трофеев и старые книги. Уже на самом дне, под глиняной вазой, вам попадается страница, вырванная из дневника." },
    ["74c"] = { common = "Я едва разбираю буквы, но почерк напоминает мне о... Да, я видел что-то подобное до того, как моё зрение окончательно испортилось." },
    ["75a"] = { common = "Когда я только приехал сюда, в сундуке на втором этаже лежала кипа пергаментов. Как-то раз я их просмотрел, но потом зрение стало не то, и я махнул на них рукой. Окажи любезность слепому старику, поищи в сундуке наверху что-нибудь, что сможет помочь тебе разузнать о Сталване. Мне кажется, там была выцветшая страница с интересными записями. Принеси её мне, и я помогу тебе по мере сил." },
    ["75c"] = { common = "Это она!" },
    ["76a"] = { common = "Благодаря тебе мы знаем, что рудник Подземных глубин заполонили кобольды. Но нам нужен разведчик, чтобы выяснить, что творится в Яшмовой шахте. Отправляйся туда и доложи мне, если обнаружишь кобольдов. Иди на восток по дороге, пока не доберёшься до Башни Азоры, оттуда поверни на север, и у подножия гор отыщешь шахту." },
    ["76c"] = { common = "Кобольды в Яшмовой шахте? Так это правда? Проклятье! Дела идут всё хуже и хуже! Конечно, я благодарен тебе за информацию, но лучше бы мы ошибались..." },
    ["77a"] = { common = "Я понял, про какую тару говорил Дран Дрофферс, у меня такая есть. Я помогу тебе разлить \"Медовую зыбь\" по бутылкам, чтобы этот грубиян, отец Мальтона, остался доволен. Но, разумеется, не бесплатно – взамен я хочу две бутылки \"Зыби\" для себя. Бутылки можно найти в ящиках на заброшенной базе Орды у Осклизлой скалы. Достать их будет нелегко, потому что в руинах кишмя кишат слизнюки и пиявки, и, говорят, у них там есть какой-то предводитель, что-то вроде верховного слизнюка. Но другого способа нет – придётся тебе идти на базу и искать полные бутылки." },
    ["77c"] = { common = "Отличная работа. Я очень рад, что напиток не испортился – нет ничего хуже на вкус, чем негодная медовуха. Погоди минутку, магии нужно время, чтобы подействовать на этот ценный груз. Хотя, на самом деле, никакой магии тут нет – я всего лишь перелью эту \"Медовую Зыбь\" в новые бутылки, и тогда этот напиток превратится в величайшее сокровище!" },
    ["78a"] = { common = "Я знаю, кто мог бы тебе помочь. Когда я служил в страже Штормграда, мы порой пропускали по стаканчику в темнолесской таверне \"Алый ворон\". Её хозяин Смиттс всегда был знатоком преданий. Покажи ему эту страницу, посмотрим, что он скажет." },
    ["78c"] = { common = "Клянусь Светом! Я узнаю этот почерк!" },
    ["79a"] = { common = "Я много лет следил за легендами, ходящими об этом Сталване. Когда несколько лет назад нескольких заезжих аристократов нашли мёртвыми, мы с Хаггардом решили расследовать это дело. Я отыскал несколько заляпанных грязью страниц, но мы так и не нашли связи между ними и этим лесным сумасшедшим. Найденные тобой улики подтверждают его вину. Немедленно отнеси эту страницу командиру Чернодрев и расскажи ей о добытых сведениях!" },
    ["79c"] = { male = "Надо же, ты оказался настоящим сыщиком, герой.", female = "Надо же, ты оказалась настоящим сыщиком, героиня." },
    ["80a"] = { common = "Я давно присматриваюсь к этому Сталвану. Но если эта страница написана той же самой рукой, то его вина несомненно доказана. За долгие годы службы клерк Далтри стал настоящим экспертом по различению почерков. Покажи ему эту страницу, проверь, совпадает ли почерк с росписью в журнале." },
    ["80c"] = { common = "Несомненно! Почерк на этой странице совпадает с подписью в журнале." },
    ["81a"] = { common = "Я позаботился о том, чтобы ничего не пропало – ни медовуха из бочонка, ни лишние бутылки. Не то чтобы я так уж тепло относился к Драну, но нет ничего хуже, чем когда пропадает выпивка! Вот, держи. Доставь этот бочонок Драну Дрофферсу в его забегаловку в Оргриммаре. Да, и пожалуйста, не забудь передать привет Мальтону. Скажи, что если он соскучится по отличной выпивке и великолепным собутыльникам, то мы будем в восторге от его визита." },
    ["81c"] = { common = "Ну-ка, ну-ка, надо ещё посмотреть, что там в этом бочонке! Да, похоже, всё цело. Ну, вот твоя плата за доставку. Я выручу впятеро больше, когда продам её у себя в таверне! Хы-хы! Ну, а эти лишние бутылки \"Медовой зыби\" из Внутренних земель прибережём для особых случаев. Надо попробовать смешать её с шампанским. Назовём это... медованским!" },
    ["82a"] = { common = "Все эти сообщения о жуках... нам известно, что они опустошают пруды в Ядовитом улье. А НЕИЗВЕСТНО нам... всё остальное. Для начала надо узнать, кто наш враг! Ступай в Ядовитый улей и добудь части тел проклятущих насекомых Сентипаар. Отнеси их алхимику Пестычинсу, пусть повозится. Если уж он возьмётся за работу, скоро мы обо всём узнаем!" },
    ["82c"] = { common = "Неплохая работа – я немедленно примусь за анализ этих частей! Сразу скажу одно – таких насекомых я ещё не видел. Такое впечатление, что ими управляет какая-то чуждая сила. Немедленно поговори с Рудознатцем; ситуация серьёзная, ему без сомнений понадобится твоя помощь! Не знаю точно, но скорее всего речь снова пойдёт о насекомых пустыни Танарис!" },
    ["83a"] = { common = "В Североземье Братство Справедливости носит маски из холстины; в Элвиннском лесу они предпочитают лён, который мог бы принести мне гораздо большую пользу... и прибыль. Принеси мне красные повязки, а я сделаю из них кое-что полезное для тебя. Лагеря братства разбросаны по всему Элвиннскому лесу." },
    ["83c"] = { common = "Отличные повязки, даром что ткань грубовата... Вот, держи!" },
    ["84a"] = { common = "Вот, держи. Отдай этот пирог Билли, да не забудь сказать, что я желаю ему подавиться!" },
    ["84c"] = { common = "М-м, вкуснятина! Пирог что надо! Похоже, ко мне возвращается память..." },
    ["85a"] = { common = "Я потеряла ожерелье. Сдаётся мне, его стащил этот беспризорник Билли Маклур! Вечно он шастает по виноградникам, как крыса какая-то! Если решишь его искать, то сходи на виноградники, это к востоку отсюда. Пожалуйста, разыщи моё ожерелье, порадуй старуху-вдову!" },
    ["85c"] = { common = "Чего-чего она там потеряла? Какое такое ожерелье? Не брал я его, даже в глаза не видел, и вообще я не вор какой-нибудь! Может, я и знаю, кто мог это сделать... Вот только вспоминать на голодный желудок сложно, в голове мутится." },
    ["86a"] = { common = "Может, если бы я получил пирог, то смог бы вспомнить, у кого сейчас это твоё ожерелье. Кстати... Говорят, у тётушки Бернис получаются отличные пироги со свининой. Я вот что думаю: принеси ей кабаньего мяса – около ферм кабанов ошивается видимо-невидимо – и попроси испечь для тебя пирог." },
    ["86c"] = { common = "Хоть мясо и жестковато, его можно потушить на медленном огне и приготовить отличную начинку для пирога!" },
    ["87a"] = { common = "Я играл около рудника Подземных глубин и, похоже, уронил... М-м... В смысле, я там видел ожерелье этой самой дамы. Представления не имею, как оно туда попало; я тут ни при чём! В общем, короче, я видел, как здоровенный кобольд с золотыми зубами схватил ожерелье и скрылся в руднике. Если отыщешь этого кобольда, найдёшь и ожерелье, точно тебе говорю!" },
    ["87c"] = { common = "Моё ожерелье! Оно нашлось! О, дорогуша, спасибо, спасибо! Вот, держи. Это принадлежало моему мужу; \"счастливая вещица\" – он всегда так говорил. Если бы только он взял это с собой в последний поход!.." },
    ["88a"] = { common = "У семейства Бреквеллов имеется свинья. Не простая, а призовая, по кличке – ты только представь себе! – Принцесса. И эта громадная гора сала то и дело пробирается на мой огород! Чтобы пожирать мои овощи! Так вот, прежде чем эта скотина доберётся до полей... словом, Принцесса должна умереть! Принеси мне её ошейник в доказательство того, что это свершилось, а взамен получишь кое-что полезное. Принцессу держат на тыквенной ферме Бреквеллов: это к востоку от фермы Маклуров. Разберись с ней прежде, чем она проголодается и вернётся сюда!" },
    ["88c"] = { common = "Счастье-то какое! Эта хавронья была такой громадной, что в один присест сожрала бы весь наш урожай! Я так тебе благодарна! Взгляни: что-нибудь из этого тебе, надеюсь, подойдёт?" },
    ["89a"] = { common = "Из-за последнего нашествия орков нам пришлось переплавить весь металл на пули, мечи и доспехи. Мы посылали в Штормград за новыми поставками, но отряд гноллов Красногорья разграбил обоз и сбежал в холмы за Приозерьем. Нам не хватает материалов на ремонт моста. Если ты принесёшь мне пять железных пик и пять железных клепок, я прикажу тебя наградить. За дело!" },
    ["89c"] = { common = "Отличная работа. Мы можем продолжить восстановление моста. Ещё немного, и закончим." },
    ["90a"] = { common = "Моё коронное блюдо – пряные котлеты из волчатины! Разумеется, я могу тебе их пожарить, но для этого мне понадобятся кое-какие продукты. Раздобудь десять постных волчьих боков. В лесу волков полно, и добыть мясо будет несложно. Кстати, тебе ещё повезло – буквально на днях мне пришёл очередной груз травяных приправ Штормграда, так что от тебя мне понадобится только сама волчатина." },
    ["90c"] = { common = "Отличная работа! Наслаждайся вкуснятиной – приправленной котлетой из волчатины!" },
    ["91a"] = { common = "В восточных предгорьях нашего края обосновался враг Штормграда. С помощью тайной магии этот негодяй по имени Моргант сеет ужас и страдания в нашем городе и окрестностях. Он прибрал под свою руку гноллов из стаи Темношкуров, и они исполняют его повеления. Согласно Закону Озёр, пособничество врагу королевства карается смертью. Гноллов следует уничтожить! Принеси мне десять подвесок Темношкуров и получишь награду." },
    ["91c"] = { common = "Суд Озёр благодарит тебя за помощь правосудию. Помогая претворить в жизнь законы Королевства, ты способствуешь установлению справедливости в наших землях." },
    ["92a"] = { common = "Я бы с радостью сделала для тебя гуляш по-красногорски, но есть небольшое затруднение. Во время недавнего вторжения орков мне пришлось кормить целый отряд солдат Штормграда, и все кладовые опустели... Хотя если ты снабдишь меня всеми необходимыми продуктами, я уж расстараюсь! Принеси мне пять кусков жёсткого мяса кондора, пять рыл больших жутевепрей и пять порций хрустящего паучьего мяса." },
    ["92c"] = { common = "Молодец. И какие отличные куски! А вот и моё коронное блюдо – гуляш по-красногорски." },
    ["93a"] = { common = "Открою тебе тайну: тёмные пирожки с \"крабами\" делаются из паучьих лапок! Понимаю, эта новость может быть для тебя неприятной, но пирожки получаются вкусные и ароматные – отличная закуска! Принеси мне липкие паучьи лапки, и я испеку для тебя пирожочки. Говорят, что лучшие лапки у ядовитых кругопрядов. Они плетут паутины на севере, между холмами и рекой." },
    ["93c"] = { common = "О, отличные лапки! Дай-ка я замариную их особым составом, – не подсматривай! – потом хорошенько подрумяню на сковородке… И хотя тёмные пирожки с крабами – моё коронное блюдо и рецептом я делиться не готов, вот тебе рецепт блюда не хуже." },
    ["94a"] = { common = "Мой соперник Моргант – волшебник, наделённый великой силой, но лишённый сердечной доброты. Он обосновался в башне Илгалара, что в Красногорье. Я нашёл способ следить за ним при помощи Ока Азоры. Однако Око не даёт возможности проникнуть в его мысли. Для такого дела мне потребуется помощь. Если ты согласишься помогать мне, возьми амулет Азоры и отнеси его к башне Илгалара. Амулет нужно положить под статую льва рядом с башней. Если это будет сделано, то с помощью силы Азоры я смогу проникнуть в замыслы Морганта." },
    ["94c"] = { male = "Вы кладёте амулет Азоры в углубление, и он словно бы врастает в камень. Вы слышите голос Теокрита: Прими мою благодарность, юный путник. Отныне ты сможешь говорить со мной посредством этого амулета. После того как я проникну в мысли моего соперника, у меня будет для тебя новое задание.", female = "Вы кладёте амулет Азоры в углубление, и он словно бы врастает в камень. Вы слышите голос Теокрита: Прими мою благодарность, юная путница. Отныне ты сможешь говорить со мной посредством этого амулета. После того как я проникну в мысли моего соперника, у меня будет для тебя новое задание." },
    ["95a"] = { common = "Раньше я работал на одной из ферм на юго-востоке... а потом тёмные всадники спустились с перевала Мёртвого Ветра и перебили всю мою семью, пока я был в отлучке! Вернувшись, я увидел неподалёку от амбара неясную фигуру человека, который что-то закапывал. Он успел сбежать от меня, а задерживаться я не мог, потому что преследовал тёмных всадников. Так я и не узнал, что там спрятано. Если ты можешь выяснить, что закопал в землю этот незнакомец, я буду очень признателен. Поищи возле старого пня, рядом с амбаром." },
    ["95c"] = { common = "Вы находите кучу торопливо накиданной земли. Похоже, кто-то хотел что-то спрятать... а времени у него не хватало." },
    ["96a"] = { common = "Возьми осколок. Возьми его и даруй жизнь. Даруй жизнь и пойми. Пойми, что вода – это жизнь... А порча – конец жизни. Оберегай и даруй жизнь силой воды." },
    ["96c"] = { common = "А вот и доказательство твоих свершений, как я и просила. Я рада, что могу первой поздравить тебя с успехом и вручить тебе этот... Тотэм воды. Пусть он служит тебе верой и правдой. Удачи! Следующее испытание ожидает тебя нескоро, поэтому учись хорошенько. Чистая вода не только вдыхает новую жизнь в раненых, но может также оказывать и другие эффекты. Когда найдёшь время, поговори с наставником шаманов. Может быть, у него найдутся для тебя новые заклинания." },
    ["97a"] = { common = "Немедленно сообщи командиру Чернодрев, что почерки совпадают! Её подозрения подтвердились!" },
    ["97c"] = { common = "Я так и знала! Отличная работа!" },
    ["98a"] = { male = "Сталван Мистмантл вёл порочную жизнь. От его руки погибли многие невинные люди. Несомненно, он виновен в бесчисленных преступлениях, а теперь угрожает и нашему Темнолесью. Лишь Свету известно, что за гнусные злодеяния он готовит. Ступай в его дом к северу от города, герой, и покончи со Сталваном раз и навсегда. Приведя мой приговор в исполнение, отправляйся к мадам Еве и покажи ей его фамильное кольцо. В конце концов именно её предчувствие позволило нам раскрыть это тёмное преступление. Благодаря ей в Темнолесье стало безопаснее.", female = "Сталван Мистмантл вёл порочную жизнь. От его руки погибли многие невинные люди. Несомненно, он виновен в бесчисленных преступлениях, а теперь угрожает и нашему Темнолесью. Лишь Свету известно, что за гнусные злодеяния он готовит. Ступай в его дом к северу от города, героиня, и покончи со Сталваном раз и навсегда. Приведя мой приговор в исполнение, отправляйся к мадам Еве и покажи ей его фамильное кольцо. В конце концов именно её предчувствие позволило нам раскрыть это тёмное преступление. Благодаря ей в Темнолесье стало безопаснее." },
    ["98c"] = { male = "Знаю, Сталван мёртв. Я ощутила волну надежды, пробежавшую по осквернённому лесу. Сумеречный лес раз и навсегда освободился от кровожадной твари. Мою радость омрачает лишь мысль о тех, кто пал жертвой этого чудовища. А ты отважен и хитёр, герой.", female = "Знаю, Сталван мёртв. Я ощутила волну надежды, пробежавшую по осквернённому лесу. Сумеречный лес раз и навсегда освободился от кровожадной твари. Мою радость омрачает лишь мысль о тех, кто пал жертвой этого чудовища. А ты отважна и хитра, героиня." },
    ["99a"] = { common = "По мере того, как растёт моё понимание магии Аругала, растёт и моё презрение к этому злосчастному глупцу. Я уже почти закончил исследование его так называемого \"лекарственного зелья\". У меня будет полная информация, когда я узнаю, какие чары служат причиной странностей, происходящих в деревне Погребальных Костров. Днём живущие там крестьяне выглядят по-человечески. Но когда солнце заходит, деревенский люд превращается в воргенов Лунного Гнева. Мне нужно извлечь энергию из заколдованных кандалов, надетых на крестьян Аругалом. Принеси мне шесть заколдованных кандалов из деревни Погребальных Костров." },
    ["99c"] = { common = "Твоя настойчивость весьма похвальна. С помощью информации, которую ты помог мне собрать, Аругал падёт, и вся его безрассудная магия развеется. Браво." },
    ["100a"] = { common = "Отзвучали последние слова заклятья, и вас ослепляет вспышка света. Звуки капель, падающих на пламя, стихают, и вас переполняет радость: ведь осквернённые духи вокруг вас уничтожены." },
    ["100c"] = { common = "Спасибо тебе. Спасибо шаманам. Порча отступает, но жизнь продолжает увядать. Пусть шаманы охраняют жизнь." },
    ["101a"] = { male = "По лесу расползается тление и порча, и все мы вынуждены позаботиться о самозащите. Ветер несёт мне вести о великой опасности, поджидающей тебя в ближайшем будущем. Если ты желаешь оградить себя от неё, благородный герой, принеси мне десять клыков вурдалаков, десять пальцев скелетов и пять фиалов паучьего яда. Тогда я создам тотэм Кары, который будет наносить урон тем, кто попытается напасть на тебя.", female = "По лесу расползается тление и порча, и все мы вынуждены позаботиться о самозащите. Ветер несёт мне вести о великой опасности, поджидающей тебя в ближайшем будущем. Если ты желаешь оградить себя от неё, благородная героиня, принеси мне десять клыков вурдалаков, десять пальцев скелетов и пять фиалов паучьего яда. Тогда я создам тотэм Кары, который будет наносить урон тем, кто попытается напасть на тебя." },
    ["101c"] = { male = "Ты поступил мудро. Этот тотэм Кары защитит тебя от зла, таящегося по всему Азероту и за его пределами. Если тебе будет что-то угрожать, возьми тотэм в руку – и его магическая аура защитит тебя. Не теряй мужества, прекрасный герой. Тебе оно понадобится, ибо я чувствую – грядёт немало кровопролитных сражений.", female = "Ты поступила мудро. Этот тотэм Кары защитит тебя от зла, таящегося по всему Азероту и за его пределами. Если тебе будет что-то угрожать, возьми тотэм в руку – и его магическая аура защитит тебя. Не теряй мужества, прекрасная героиня. Тебе оно понадобится, ибо я чувствую – грядёт немало кровопролитных сражений." },
    ["102a"] = { common = "Штормград отвернулся от нас. Злобный ветер несчастий носится по равнинам Западного Края. Это была моя родина, и я не отвернусь от местных жителей, решивших остаться здесь. Мы, бывшие фермеры, намерены постоять за себя. Твоё задание, если ты за него возьмёшься, будет состоять в том, чтобы патрулировать луга Западного Края. Выследи и убей мерзких гноллов, которые, похоже, действуют заодно с ворами из Мёртвых копей. Принеси мне восемь лап гноллов, и я вознагражу тебя за проявленное мужество." },
    ["102c"] = { common = "Хорошая работа. Если на стороне народного ополчения будут такие смельчаки, как ты, Западный Край сможет когда-нибудь вновь стать процветающей житницей, какой был когда-то. Пожалуйста, прими эту награду в знак признательности за твои усилия." },
    ["103a"] = { common = "Ночь, когда погибла семья смотрителя маяка, была ужасной. Я беспомощно наблюдал за происходившим, поскольку сам Старый Мрачноглаз вёл нападавших. Но что случилось, то случилось, и теперь жизнь моряков, плавающих по Великому морю и близко подходящих к опасным прибрежным рифам – моя забота. Поддерживать огонь маяка оказалось некому, и эта обязанность легла на мои плечи. Помогите мне поддержать огонь факела – принесите пять фляг масла, собрав их с сельскохозяйственных големов." },
    ["103c"] = { male = "Хвала тебе, смелый герой. Рифы побережья Западного Края будут освещены благодаря твоим трудам. Множество жизней будет спасено, пока горит факел. Меня постигла бессмысленная смерть на этом самом побережье. Мой долг в иной жизни – следить, чтобы никто не повторил моей судьбы.", female = "Хвала тебе, смелый героиня. Рифы побережья Западного Края будут освещены благодаря твоим трудам. Множество жизней будет спасено, пока горит факел. Меня постигла бессмысленная смерть на этом самом побережье. Мой долг в иной жизни – следить, чтобы никто не повторил моей судьбы." },
    ["104a"] = { common = "Когда моя жизнь оборвалась на скалах, я и понятия не имел, что уготовано мне на том свете. Маяк той ночью не светил, поскольку Старый Мрачноглаз перепугал семью смотрителя, и они убежали. Потом они вернулись и вновь зажгли пламя, но Мрачноглаз заставил более слабых духом мурлоков атаковать маяк вместе с ним. Во второй раз семье смотрителя не повезло, и вся она погибла у меня на глазах. Убейте Старого Мрачноглаза, если увидите его на берегу, принесите мне одну из его чешуй, и я вознагражу вас." },
    ["104c"] = { common = "Итак, это злобное чудовище, Мрачноглаз, мертво. Хорошая работа. Вы своими руками прервали одну жизнь, но, возможно, тем самым спасли множество других. Великое море, само по себе исполненное угрозы, станет этой ночью чуточку безопаснее благодаря вашему героическому деянию." },
    ["105a"] = { common = "Увы, пришло время напасть на Андорал и изгнать оттуда лича! Злобный Араж Призыватель обосновался в самом сердце руин. Его охраняют многочисленные воины Плети, рассеянные по всему центру бывшего города, а самого Аража охраняют сильнейшие бойцы. Без многочисленных помощников тебе нечего и думать одержать над ним верх. Убей Аража и принеси мне его кристалл-талисман!" },
    ["105c"] = { common = "Ты сделал это! Аража… лич повержен! В этот день, ты совершил большую услугу для Орды, путник. Твоя храбрость и настойчивость, являются свидетельством того, что значит быть героем. Пожалуйста — прими это в знак благодарности!" },
    ["106a"] = { common = "За что мне это наказание? Моё сердце отдано Томми Джо Стоунфилду, я жить без него не могу, но наши родители – заклятые враги! Я не только встретиться – даже взглянуть на него не могу! Пожалуйста, отнеси Томми Джо это письмо. Он обычно бывает у реки к западу от фермы Стоунфилдов, а сама ферма – тоже к западу отсюда..." },
    ["106c"] = { common = "Я больше не могу жить в разлуке с ней! Я должен увидеть её!" },
    ["107a"] = { common = "Бьюсь об заклад, у Вильяма Песта найдётся зелье, которое поможет соединить наших юных влюблённых! Вот, держи: отнесёшь эту записку Вильяму. Найдёшь его в Златоземье, в таверне \"Гордость льва\"." },
    ["107c"] = { common = "У меня просто сердце разрывается, как подумаю об этих бедных детках, Мэйбелл и Томми Джо. Ах, молодость... Весна... Любовь... Думаю, я смогу им чем-нибудь помочь. Погоди-ка, дай подумать..." },
    ["109a"] = { male = "Похоже, герой, тебе довелось побывать не в одном бою... Думаю, тебе стоит явиться с докладом к Гриану Камнегриву. Он возглавляет ополчение, защищающее фермерские земли Западного Края. Думаю, твоя помощь ему не помешает. Обычно его можно найти в башне, что на Сторожевом холме, у дороги, в самом сердце Западного Края.", female = "Похоже, героиня, тебе довелось побывать не в одном бою... Думаю, тебе стоит явиться с докладом к Гриану Камнегриву. Он возглавляет ополчение, защищающее фермерские земли Западного Края. Думаю, твоя помощь ему не помешает. Обычно его можно найти в башне, что на Сторожевом холме, у дороги, в самом сердце Западного Края." },
    ["109c"] = { common = "А, так это мой друг тебя сюда отправил? С его стороны это большая любезность. Что ж... Монархия Штормграда больше не поддерживает нас. Остаётся полагаться на ополчение. Если ты хочешь сражаться за свободу вместе с нами, я буду рад этому." },
    ["110a"] = { common = "Мне понадобится время на изучение оборудования Холстомера... и на приведение в порядок его дел. Ох, печёнкой чую, не последняя это потеря, проклятые жуки ещё покажут нам, где раки зимуют! Поговори, пожалуйста, с алхимиком Пестычинсом, узнай, как проходят исследования частей насекомых. Если всё готово, принести мне результаты." },
    ["110c"] = { common = "Да, результаты готовы. Они, мягко говоря, неприятные. К сожалению, наши подозрения подтвердились, и насекомых контролирует неведомая сила. И не только неведомая, но и злобная. Этих насекомых превратили в настоящих опустошителей. Я такого ещё не видел!" },
    ["111a"] = { common = "Прошу тебя, поговори с моей бабулей. Если кто и может сделать так, чтобы мы с Мейбелл были вместе, так это она. Бабуля сейчас дома – это к востоку отсюда..." },
    ["111c"] = { common = "Пока наши семьи враждуют, у Томми Джо и Мэйбелл вряд ли есть шансы; но, может, мы дадим им возможность хоть немного побыть вместе. Хм... Что бы придумать..." },
    ["112a"] = { common = "Да, я могу приготовить для Мэйбелл напиток невидимости, чтобы она могла убежать с Виноградников Маклура к своему Томми Джо. Но для этого мне нужен хрустальный фукус. Эти водоросли растут в океане, и мурлокам иногда удаётся добыть их. Может, у тех, что живут на берегах Хрустального Озера, найдётся нужный компонент. А озеро найти просто: нужно только пойти на восток от Златоземья." },
    ["112c"] = { common = "Ага, вот и фукус! Отлично, просто отлично! А теперь погоди минутку: сейчас напиток будет готов." },
    ["113a"] = { common = "Старший геодезист Рудознатец должен немедленно увидеть мой отчёт. Более того... его должны увидеть все, кто умеет читать. Серьёзная опасность грозит не только Танарису и Прибамбасску, но если сидеть, сложа руки, то и всему южному Калимдору. Да что там, всему Азероту – эти твари не собираются останавливаться. Пусть Рудознатец сделает копию моего отчёта, распространи её среди всех своих союзников. Пусть все узнают об этом!" },
    ["113c"] = { male = "Спасибо за доставку отчёта, младший геодезист путник; вот плата за верную службу Водной компании Прибамбасска. Хотя я не слишком люблю делиться информацией задарма с теми, кто мог бы заплатить за неё звонкой монетой, но Пестычинса я знаю много лет. Если он советует рассказать о нашествии насекомых всем и каждому, да будет так. Подожди немного, и я сделаю копию.", female = "Спасибо за доставку отчёта, младший геодезист путница; вот плата за верную службу Водной компании Прибамбасска. Хотя я не слишком люблю делиться информацией задарма с теми, кто мог бы заплатить за неё звонкой монетой, но Пестычинса я знаю много лет. Если он советует рассказать о нашествии насекомых всем и каждому, да будет так. Подожди немного, и я сделаю копию." },
    ["114a"] = { common = "Отнеси этот напиток невидимости юной Мэйбелл. Его действия хватит на то, чтобы девушка успела встретиться с Томми Джо." },
    ["114c"] = { common = "Мне так стыдно, что приходится обманывать свою семью... Но я не могу отказаться от Томми! Благодарю тебя. Как только подвернётся случай, я выпью этот напиток и найду способ пробраться к моему любимому. А в дополнение к словам благодарности прими вот это." },
    ["115a"] = { common = "Орки из клана Чёрной Горы позвали на помощь чародеев, а те принесли с собой источники тёмной силы – полуночные сферы. Чародеи наносят чувствительные удары по защитникам Красногорья, и мы должны как можно скорее лишить их столь мощного оружия. Добудь для меня полуночные сферы. Ты найдёшь их у чародеев Чёрной Горы. Я придумаю, как избавиться от Сфер, чтобы мир стал лучше и чище!" },
    ["115c"] = { common = "Благодарю тебя. Я немедленно прикажу уничтожить эту мерзость." },
    ["116a"] = { common = "У меня возникло небольшое затруднение. Ещё немного, и все бутылки опустеют, а поставок алкоголя давно не было. Проклятые орки. Не хочешь подзаработать? Принеси мне бочонок громоварского светлого от Мрачнобуха Громовара из Западного Края, бочонок \"Мерло\" из Штормграда, бутылку самогона из Темнолесья и бурдюк со сладким ромом из Златоземья, и я тебя непременно награжу." },
    ["116c"] = { common = "Отличная работа! Я представляю, сколько дорог тебе пришлось исходить, чтобы принести мне такое количество первосортных напитков. Завсегдатаи трактира будут счастливы! Моя жена неплохая рукодельница. Прошу, прими плащ, сшитый ею, в знак моей признательности." },
    ["117a"] = { common = "Торопись, мой друг, и иди побыстрей, Чтоб нашего пойла отведать скорей. Оно ближе к пиву – не спутаешь с кашей, Но нужен нам хмель, чтоб сварить пойло наше." },
    ["117c"] = { common = "Хмель, и ячмень, и дрожжи, и солод - От вкуса кидает то в жар, то в холод. Не надо просить и не надо молить, Ведь можно себе из бочонка налить!" },
    ["118a"] = { common = "Я потратил так много железа на доспехи и оружие для стражников Штормграда, что теперь его не хватает даже на подковы для лошадей! Отнеси эту записку кузнецу Аргусу в Златоземье, я хочу попросить его прислать мне партию подков." },
    ["118c"] = { common = "Так старому Вернеру нужны подковы, да?!" },
    ["119a"] = { common = "Ладно, так и быть, пошлю ему пятьдесят подков… Вот они, уже упакованы, осталось только доставить! Передай Вернеру, что с ним приятно иметь дело. Пусть не забудет прочитать записку, прикреплённую к ящику!" },
    ["119c"] = { male = "Спасибо, ты здорово мне помог. Что это? Аргус приложил к ящику записку... Что?! Аргус хочет ПЛАТЫ? Пф! Ладно, спасибо за помощь.", female = "Спасибо, ты здорово мне помогла. Что это? Аргус приложил к ящику записку... Что?! Аргус хочет ПЛАТЫ? Пф! Ладно, спасибо за помощь." },
    ["120a"] = { male = "Тяжёлые настали времена, герой. Город в непрерывной осаде. Если из Штормграда не пришлют подкрепление, нам не выстоять. Я доверяю тебе важнейшее письмо. Отнеси его в Штормград генералу Маркусу Джонатану. И поскорее возвращайся с вестями – неважно, добрыми или злыми. Спеши!", female = "Тяжёлые настали времена, героиня. Город в непрерывной осаде. Если из Штормграда не пришлют подкрепление, нам не выстоять. Я доверяю тебе важнейшее письмо. Отнеси его в Штормград генералу Маркусу Джонатану. И поскорее возвращайся с вестями – неважно, добрыми или злыми. Спеши!" },
    ["120c"] = { male = "Вольно, герой. Чиновник Соломон – благородный человек. Его слова много для меня значат. Я поговорю с королём и объясню ему ситуацию. Заверьте доброго судью, что он получит поддержку армии Штормграда. Я вышлю подкрепление, как только получу приказ Его Величества.", female = "Вольно, героиня. Чиновник Соломон – благородный человек. Его слова много для меня значат. Я поговорю с королём и объясню ему ситуацию. Заверьте доброго судью, что он получит поддержку армии Штормграда. Я вышлю подкрепление, как только получу приказ Его Величества." },
    ["121a"] = { male = "Пока я жду ответа от короля, хочу, чтобы ты отнёс это письмо мировому судье Соломону. Свободен, герой!", female = "Пока я жду ответа от короля, хочу, чтобы ты отнесла это письмо мировому судье Соломону. Свободна, героиня!" },
    ["121c"] = { male = "Благодарю тебя, герой. В знак признательности Озёр и Штормграда прими эти деньги. Хотя, признаться, смысл этого письма туманен. Что-то неладно в нашем королевстве. Боюсь, это не конец, а начало войны.", female = "Благодарю тебя, героиня. В знак признательности Озёр и Штормграда прими эти деньги. Хотя, признаться, смысл этого письма туманен. Что-то неладно в нашем королевстве. Боюсь, это не конец, а начало войны." },
    ["122a"] = { common = "В обмен на подковы Аргус из Златоземья просит брюшную чешую чёрных дракончиков. Если ты добудешь мне шесть лоскутов чешуи, я смогу расплатиться с Аргусом... И для тебя что-нибудь сделаю. Чёрных дракончиков можно отыскать к югу от Озёр, но им не сидится на одном месте. Проще всего высматривать их, направляясь по другим делам, и охотиться по случаю." },
    ["122c"] = { common = "Спасибо! Теперь я смогу расплатиться с Аргусом..." },
    ["123a"] = { common = "На этом листке – расписание поставок золота из рудников в Элвиннском лесу. Поставки расписаны по дням и часам, а в качестве получателя указан некий \"Вымогатель\". Судя по всему, Вымогатель обосновался неподалёку от тыквенного поля Бреквеллов в восточной части Элвиннского леса. Похоже, это важные сведения. Было бы неплохо сообщить их маршалу Дугхану: он сейчас в Златоземье." },
    ["123c"] = { common = "Хм... Я слышал об этом \"Вымогателе\", вот только не знаю, на кого он работает. Должен тебя поблагодарить: расписание поможет нам разгадать эту тайну..." },
    ["124a"] = { common = "Будто нам одних орков мало! А теперь вдоль хребта рядом с моими стойлами шастают громилы и мистики гноллов и при случае воруют лошадей… Если ты сможешь избавить меня от этих проходимцев, мы с лошадьми будем весьма признательны." },
    ["124c"] = { common = "Благодарю тебя за помощь!" },
    ["125a"] = { common = "Мне не помешала бы помощь. Наш город в осаде, и достать припасы и оборудование всё труднее. Мои инструменты везли из Златоземья в фургоне, но мост был уничтожен. Мы перегрузили их в лодку, но тут орки пробили её снарядом из катапульты! И вот невезенье, ящик опустился на самое дно озера. Достань его, и я щедро вознагражу тебя." },
    ["125c"] = { common = "Отличная работа! Я уж и не надеялся вновь увидеть свои инструменты." },
    ["126a"] = { common = "Гноллы по-прежнему здесь. Я слышу, как они завывают, охотясь в холмах над Приозерьем. И один из них воет громче других – это Изувой, их вождь. Стоит его прикончить, и вся стая разбежится! Убей его и принеси в доказательство отрубленную лапу. Соблюдай осторожность, этот гнолл заслуженно возглавляет целую стаю. Он совсем не прост..." },
    ["126c"] = { common = "И снова благодарю тебя за помощь. Штормград еле-еле справляется с орками, у них не хватает солдат, чтобы защищать Красногорье от напастей вроде гноллов." },
    ["127a"] = { male = "Застывшее озеро славится пятнистой рыбой-луной. На неё всегда есть спрос... А мой запас подходит к концу! Принеси мне штук десять рыбин, и я хорошо за них заплачу. Если ты сам не умеешь удить, то... Попытайся отнять рыбу у мурлоков!", female = "Застывшее озеро славится пятнистой рыбой-луной. На неё всегда есть спрос... А мой запас подходит к концу! Принеси мне штук десять рыбин, и я хорошо за них заплачу. Если ты сама не умеешь удить, то... Попытайся отнять рыбу у мурлоков!" },
    ["127c"] = { common = "Иметь с тобой дело – одно удовольствие, дружище!" },
    ["128a"] = { common = "Мы должны уничтожить клан Чёрной Горы. Враг вторгся в наши земли. Эти горы по праву принадлежат королю Штормграда. До нас дошли сведения, что главы всех видов войск клана называются воителями. Их можно отыскать в северном лагере, к западу от дороги, ведущей в Пылающие степи. Мировой судья Соломон распорядился перебить этих гнусных тварей. Убей пятнадцать воителей из клана Чёрной Горы и возвращайся ко мне." },
    ["128c"] = { male = "Вижу, ты доблестно сражался с кланом Чёрной Горы, герой. Ты оказал нашему городу неоценимую услугу.", female = "Вижу, ты доблестно сражалась с кланом Чёрной Горы, героиня. Ты оказала нашему городу неоценимую услугу." },
    ["129a"] = { common = "Можешь оказать мне услугу? Я приготовила обед для стражника Паркера, но он ушёл на дежурство... Он-то может постоять за себя, но простой горожанке вроде меня не стоит соваться в те края. Если ты отнесёшь ему обед, я бесплатно тебя накормлю! Паркер патрулирует участок дороги, ведущей в Сумеречный лес." },
    ["129c"] = { common = "Спасибо, вкусно и сытно покушать я люблю. Хранить Приозерье от нападений орков и гноллов нелегко!" },
    ["130a"] = { common = "Если ты всё равно идёшь к Дарси, не отнесёшь ли ей от меня цветы? Букетик можно приобрести у травницы в Приозерье, в западной части города. Только когда будешь покупать цветы… не говори травнице Марти, от кого они и кому..." },
    ["130c"] = { male = "Тебе нужен букет цветов? Ты вроде бы у нас недавно... уже нашёл даму сердца? Понимаю, мне не следует совать нос не в своё дело, но приятно видеть витающую в воздухе любовь... особенно в такие опасные времена.", female = "Тебе нужен букет цветов? Ты вроде бы у нас недавно... уже нашла даму сердца? Понимаю, мне не следует совать нос не в своё дело, но приятно видеть витающую в воздухе любовь... особенно в такие опасные времена." },
    ["131a"] = { common = "Вот и букет. Я выбрала для тебя нарциссы. Мои любимые цветы!" },
    ["131c"] = { male = "Какая прелесть! Надо поскорее поставить их в воду! Но... это любимые цветы Марти. Неужели Паркер послал тебя за букетом к этой ревнивой мегере? Ты ведь не сказал, для кого они? Иначе не удивлюсь, если она их отравила. Нет-нет, ты ни в чём не виноват. Большое спасибо! А вот и твой обед.", female = "Какая прелесть! Надо поскорее поставить их в воду! Но... это любимые цветы Марти. Неужели Паркер послал тебя за букетом к этой ревнивой мегере? Ты ведь не сказала, для кого они? Иначе не удивлюсь, если она их отравила. Нет-нет, ты ни в чём не виновата. Большое спасибо! А вот и твой обед." },
    ["132a"] = { common = "То, о чём я хочу вам рассказать, может стоить мне жизни. Бандиты из Братства Справедливости замышляют что-то крупномасштабное. Последнее, что я слышал, – что они действуют заодно со всякими гноллами, кобольдами и даже гоблинами. Отнеси эту записку Камнегриву. В ней разъясняется всё, что я знаю на эту тему." },
    ["132c"] = { common = "Эх!.. Надо было сгноить этого мошенника, когда у меня был шанс. Но эта информация действительно очень важна. Хорошая работа." },
    ["133a"] = { common = "Я живу вдали от города, никто меня не защищает, и даже странно, как это меня до сих пор не сожрали вурдалаки и мертвяки! Только вчера несколько костеглодов ломились ко мне в дом!.. Я хочу сделать особую фигурку – что-то вроде пугала для этой нежити. Для этого мне понадобится несколько рёбер вурдалаков. Их можно добыть, убивая плотоядов, костеглодов, мозгоедов, гнилую нежить и распространителей чумы. Принеси мне рёбра, и я дам тебе несколько монет." },
    ["133c"] = { common = "О, спасибо. Это наверняка сработает!" },
    ["134a"] = { common = "Несколько недель назад я собирал травы вдали от дома, и на меня напал отряд огров! Я сбежал, бросив свой ящик с ценными инструментами и травами. Прогнав меня, они вернулись к своему кургану в южной части Сумеречного леса. Думаю, они оставили мой ящик неподалёку от кургана. Прошу тебя, верни мне ящик, без него я как без рук." },
    ["134c"] = { common = "Хвала Нек... то есть ТЕБЕ! Ты более чем заслуживаешь награды. Ага! Как я счастлив! Впереди много радостных ночей!" },
    ["135a"] = { common = "Интересно, что имел в виду Вилли, когда упомянул о Каменщиках. Оговорился или проговорился? Могут ли разбойники из Братства Справедливости быть связаны с Каменщиками? Только один человек должен знать наверняка: Матиас Шоу, глава ШРУ. Покажите ему записку Вилли и посмотрите, сможет ли он пролить свет на эту тайну. Если вам не сразу удастся найти Шоу, поищите в Казармах в Старом городе." },
    ["135c"] = { common = "Это дело может оказаться сложнее, чем полагает Камнегрив." },
    ["136a"] = { common = "Если ты читаешь это – значится, старина капитан Сандерс уже покоится на дне. Так что моё сокровище теперь может стать твоим, главное – следуй подсказкам. Сначала найди мой сундучок. Его, должно быть, уже наполовину песком занесло, а находится он на западном побережье Западного Края рядом с обломками корабля. Обломков-то там много, но ржавый якорь на берегу – только один. Найди этот якорь, и ты найдёшь мой сундучок. Загляни внутрь за следующей подсказкой." },
    ["136c"] = { common = "Сундучок медленно, со скрипом, открывается. Кажется, ничего в нём нет, кроме песка и воды. Постойте-ка! Проворно выползает маленький крабик, а в клешнях у него – следующая подсказка!" },
    ["138a"] = { common = "Ключ к поиску сокровища таков: \"Отличная работа, приятель! Теперь тебе идти на восток. На восток в холмы, на восток к дороге. Ищи на обочине дороги развалины старого очага. Там найдёшь старую бочку, в которой и будет следующий ключ\"." },
    ["138c"] = { male = "Отличная работа, охотник за сокровищами!", female = "Отличная работа, охотница за сокровищами!" },
    ["139a"] = { common = "Обыскивая бочку, вы обнаруживаете ещё один кусок пергамента. На нём написано: \"А теперь от этой бочки поверни к северу. Прямо, как ворон летит, иди, пока не наткнёшься на пустой кувшин рядом с одинокой ветряной мельницей на прибрежных утёсах. Осмотри кувшин внимательно – может, и найдёшь то, что ищешь\"." },
    ["139c"] = { male = "Ты на пути к главному призу, искатель сокровищ!", female = "Ты на пути к главному призу, искательница сокровищ!" },
    ["140a"] = { male = "Конечно же, глубоко внутри старого кувшина лежит ещё одна подсказка к поиску сокровища Сандерса. Чернила кое-где расплылись, а бумага отдаёт виски, но кое-что вам удалось разобрать: \"Раз уж ты нашёл мой старый кувшин из-под виски, значит, ты близко подобрался к сокровищу! Иди от бутылки на запад и спустись к берегу. Доберёшься до воды – не останавливайся! Плыви, пока не найдёшь остров, где и находится мой сундук с сокровищем!", female = "Конечно же, глубоко внутри старого кувшина лежит ещё одна подсказка к поиску сокровища Сандерса. Чернила кое-где расплылись, а бумага отдаёт виски, но кое-что вам удалось разобрать: \"Раз уж ты нашла мой старый кувшин из-под виски, значит, ты близко подобралась к сокровищу! Иди от бутылки на запад и спустись к берегу. Доберёшься до воды – не останавливайся! Плыви, пока не найдёшь остров, где и находится мой сундук с сокровищем!" },
    ["140c"] = { common = "Петли на крышке старого сундука заржавели, но поддаются. Вы с усилием открываете сундук и забираете сокровище. Поздравляем!" },
    ["141a"] = { common = "Гильдию каменщиков возглавлял человек по имени Эдвин ван Клиф. Именно он занимался восстановлением Штормграда после разорения его орками во время Первой войны. Должно быть, ван Клиф и его люди остались недовольны тем, как с ними обошёлся король, когда восстановление города было завершено. Это могло бы объяснить пару вещей. Я тут расписал всё более подробно для вашего начальства в Западном Крае. Сразу же отправляйтесь туда и передайте ему документ!" },
    ["141c"] = { common = "Эдвин ван Клиф... Мне хорошо известно это имя. Обидно думать, что этот трудолюбивый и талантливый человек мог превратиться в такого мерзавца. Мне понадобятся дополнительные доказательства, чтобы я поверил в это." },
    ["142a"] = { male = "Нам нужно выяснить местонахождение Убежища Братства Справедливости. путник, мой разведчик сообщает, что на дороге между Луноречьем, Прииском на Золотом Берегу и Рудником Янго видели вестника из Братства Справедливости. Я хочу, чтобы вы его поймали. Если он окажет сопротивление, убейте его и принесите мне то, что будет у него найдено.", female = "Нам нужно выяснить местонахождение Убежища Братства Справедливости. путница, мой разведчик сообщает, что на дороге между Луноречьем, Прииском на Золотом Берегу и Рудником Янго видели вестника из Братства Справедливости. Я хочу, чтобы вы его поймали. Если он окажет сопротивление, убейте его и принесите мне то, что будет у него найдено." },
    ["142c"] = { common = "Вот явное доказательство того, что ими верховодит ван Клиф. Теперь всё, что нам нужно узнать, – это где прячутся бандиты братства. Нам тут немного повезло, пока вас не было. Мы поймали вора, пытавшегося украсть повозку Сальдена. Он пообещал навести нас на убежище бандитов в обмен на жизнь. Я прошу вас защитить его, чтобы предатель братства мог указать, где находится убежище. Возвращайтесь ко мне, когда выясните местонахождение убежища." },
    ["143a"] = { common = "Что-то странное происходит в армии Штормграда, подкрепления всё нет и нет. К сожалению, мы не можем позволить себе ждать. Нельзя же сидеть сложа руки и не пытаться позвать соседей на помощь, пока доблестные воины Приозерья погибают один за другим. Говорят, в Западном Крае создано народное ополчение. Отнеси мою просьбу о помощи его предводителю, Гриану Камнегриву. Может быть, его люди помогут нам продержаться до подхода королевских отрядов." },
    ["143c"] = { male = "Добрый вестник, ты хорошо послужил своему господину.", female = "Добрая вестница, ты хорошо послужила своему господину." },
    ["144a"] = { male = "Меня очень огорчило письмо мирового судьи Соломона. К сожалению, он не ведает о войне, начавшейся в Западном Крае, иначе не ждал бы помощи от нас. Нам самим без ополчения не обойтись, потому что Штормград бросил нас на произвол судьбы. Отнеси мой ответ в Красногорье, герой, и передай своему хозяину, что я скорблю всем сердцем о гибели отважных бойцов.", female = "Меня очень огорчило письмо мирового судьи Соломона. К сожалению, он не ведает о войне, начавшейся в Западном Крае, иначе не ждал бы помощи от нас. Нам самим без ополчения не обойтись, потому что Штормград бросил нас на произвол судьбы. Отнеси мой ответ в Красногорье, героиня, и передай своему хозяину, что я скорблю всем сердцем о гибели отважных бойцов." },
    ["144c"] = { male = "Что сказать, вести недобрые. Я и не подозревал, что у Камнегрива трудности, схожие с нашими. Что же отвлекает армию Штормграда от защиты её собственных земель? Впрочем, зря я об этом говорю вслух. Вот, вестник. Прими эти монеты в знак благодарности за верную службу городу. Быть может, скоро ты мне снова понадобишься.", female = "Что сказать, вести недобрые. Я и не подозревал, что у Камнегрива трудности, схожие с нашими. Что же отвлекает армию Штормграда от защиты её собственных земель? Впрочем, зря я об этом говорю вслух. Вот, вестница. Прими эти монеты в знак благодарности за верную службу городу. Быть может, скоро ты мне снова понадобишься." },
    ["145a"] = { common = "И снова мне нужна твоя помощь. Я написал письмо лорду Чернодреву, прося его прислать нам на помощь обученных бойцов Ночного дозора на защиту Озёр. Надо как можно скорее доставить моё послание. Действуй осторожно. Лорд Чернодрев – мэр города Темнолесья, расположенного в сердце Сумеречного леса. Не сходи с дороги." },
    ["145c"] = { common = "Благодарю за проделанный путь. Вести и верно важные." },
    ["146a"] = { common = "Не знай я мирового судью Соломона лично, решил бы, что он сошёл с ума. Послать в Приозерье Ночной дозор, потому что Штормград отказал в помощи? Мы и создали его, когда земли наводнила нечистая магия, а Штормград бросил нас на произвол судьбы. Если я пошлю в Приозерье Ночной дозор, то наш город падёт, едва лишь Дозор доберётся до края леса. Отнеси мой ответ своему господину в Приозерье." },
    ["146c"] = { male = "Во имя Света! Армия Штормграда отступила из Западного Края. И Дозор не сможет защищать Темнолесье? Здесь таится предательство. Как же так? О, я забыл отблагодарить тебя за услуги, герой. Прими вот эту плату. А теперь извини меня. Что-то творится в Штормграде, и я должен докопаться до сути.", female = "Во имя Света! Армия Штормграда отступила из Западного Края. И Дозор не сможет защищать Темнолесье? Здесь таится предательство. Как же так? О, я забыл отблагодарить тебя за услуги, героиня. Прими вот эту плату. А теперь извини меня. Что-то творится в Штормграде, и я должен докопаться до сути." },
    ["147a"] = { common = "Если Вымогатель забирает золото с наших рудников, значит, он обворовывает королевство! Он должен предстать перед судом – а мне понадобится то кольцо, которое упоминалось в записке. Возможно, оно поможет нам узнать, на кого работает этот Вымогатель... Здесь написано, что Вымогатель скрывается на тыквенном поле Бреквеллов. Попробуй поискать его там." },
    ["147c"] = { common = "Так тебе удалось его найти? Отлично, просто прекрасно! Больше он ничего не будет \"вымогать\" на Элвиннских шахтах! А это кольцо... О, очень интересно! Это кольцо древнего братства Каменщиков Штормграда. С чего бы это мелкому воришке носить кольцо гильдии? И как вышло, что Братство Справедливости добывает золото на наших рудниках? Непростые вопросы, верно? Надеюсь, когда-нибудь мы узнаем ответ." },
    ["148a"] = { male = "Как же быть несчастному старику?.. Мне нужно привезти кое-что из Темнолесья, но деревня так далеко, а я стар и слаб... Мне не добраться до цели. Не мог бы ты отправиться в Темнолесье и привезти мне нить из призрачных волос? Её можно приобрести у мадам Евы, которая живёт на центральной площади города.", female = "Как же быть несчастному старику?.. Мне нужно привезти кое-что из Темнолесья, но деревня так далеко, а я стар и слаб... Мне не добраться до цели. Не могла бы ты отправиться в Темнолесье и привезти мне нить из призрачных волос? Её можно приобрести у мадам Евы, которая живёт на центральной площади города." },
    ["148c"] = { common = "А, так тебе нужна нить из призрачных волос? Боюсь, мои запасы иссякли, но я могу сделать ещё... Если ты принесёшь мне призрачные волосы." },
    ["149a"] = { male = "На старой ферме, в холмах к югу от Темнолесья, живёт несчастное привидение по имени Слепая Мэри. Возьми этот призрачный гребень и попроси Слепую Мэри расчесать волосы. Потом принеси гребень обратно, и я сниму с него призрачные волосы, необходимые для нити. Будь осторожен, рядом с домом бродит множество тёмных тварей.", female = "На старой ферме, в холмах к югу от Темнолесья, живёт несчастное привидение по имени Слепая Мэри. Возьми этот призрачный гребень и попроси Слепую Мэри расчесать волосы. Потом принеси гребень обратно, и я сниму с него призрачные волосы, необходимые для нити. Будь осторожна, рядом с домом бродит множество тёмных тварей." },
    ["149c"] = { common = "Что это? Гребень? Какая прелесть! И он спокойно скользит по моим волосам, хотя они давно сбились в ужасный слипшийся колтун. Ах, мне бы в зеркало посмотреться..." },
    ["150a"] = { common = "Мурлоки начинают нас беспокоить. Всё больше мурлокских рыбаков селится вдоль побережья Озера Безмолвия и вовсю ловит рыбу! Надо изгнать их, пока они не опустошили всё озеро! Убей побольше мурлоков! Принеси мне восемь их плавников, и я найду, чем тебе отплатить..." },
    ["150c"] = { common = "Молодец. Надеюсь, тебе не слишком солоно пришлось. Странно, что они ушли так далеко от моря. Хотелось бы знать, отчего они сбежали..." },
    ["151a"] = { male = "Бедная старая Савраска! Несчастная лошадка так устала от непосильного труда и бесчисленных лишений... Я её покормила перед тем, как уехать с фермы, но мы не ожидали, что повозка сломается по дороге. Я была бы вам очень благодарна, сэр, если бы вы могли принести ей несколько горстей овса с окрестных полей. Уверена, что вы найдёте овёс на любой ферме в Западном Крае, если только сумеете увернуться от этих ужасных машин, которые буйствуют на полях. К юго-западу отсюда расположено несколько фермерских хозяйств.", female = "Бедная старая Савраска! Несчастная лошадка так устала от непосильного труда и бесчисленных лишений... Я её покормила перед тем, как уехать с фермы, но мы не ожидали, что повозка сломается по дороге. Я была бы вам очень благодарна, леди, если бы вы могли принести ей несколько горстей овса с окрестных полей. Уверена, что вы найдёте овёс на любой ферме в Западном Крае, если только сумеете увернуться от этих ужасных машин, которые буйствуют на полях. К юго-западу отсюда расположено несколько фермерских хозяйств." },
    ["151c"] = { common = "Огромное тебе спасибо! Бедная старая Савраска будет просто счастлива!" },
    ["152a"] = { male = "Ты, должно быть, видел все эти обломки кораблей вдоль побережья. Великое море и в самом деле очень сурово. Береговую линию Западного Края нужно держать чистой, чтобы моряки, если приплывут к нашим берегам, были в безопасности. На сегодняшний день мурлоки являются большой проблемой... Разберись с ними – убей семь волноловов, семь воинов, семь оракулов и семь береговиков, – и награда будет ждать тебя.", female = "Ты, должно быть, видела все эти обломки кораблей вдоль побережья. Великое море и в самом деле очень сурово. Береговую линию Западного Края нужно держать чистой, чтобы моряки, если приплывут к нашим берегам, были в безопасности. На сегодняшний день мурлоки являются большой проблемой... Разберись с ними – убей семь волноловов, семь воинов, семь оракулов и семь береговиков, – и награда будет ждать тебя." },
    ["152c"] = { common = "Хорошая работа. У тебя отличные боевые навыки! Благодаря тебе побережье Западного Края стало более безопасным местом." },
    ["153a"] = { common = "В Братстве Справедливости идёт постоянная кипучая деятельность. Я уже долго слежу за их передвижениями. Между прочим, я заметил, что многих бандитов можно опознать по красным кожаным банданам. Принесите мне пятнадцать таких бандан, и я позабочусь о том, чтобы вы получили вознаграждение." },
    ["153c"] = { common = "Хорошая работа. Пожалуйста, примите один из этих предметов в качестве оплаты за ваши труды." },
    ["154a"] = { common = "НЕТ!!! Убери его, убери от меня этот гребень! Я чудовище, меня больше никто не назовёт прекрасной!" },
    ["154c"] = { common = "Ну, из этого выйдет целая катушка нити из призрачных волос, да ещё и останется несколько прядей. Прими эти монеты в уплату за лишние пряди." },
    ["155a"] = { male = "Так Камнегрив считает, что такой слабый герой сможет меня защитить? А ведь придётся. Возьми-ка с собой пару-тройку друзей. Ты же знаешь, что делать, да? Ты прикрываешь мою спину, а я веду тебя к убежищу Братства Справедливости. Держись ко мне поближе. Бандиты братства охотятся за моей головой. Если нас увидят вместе, они попытаются меня убить. Дай мне знать, когда ты и друзья, которых ты соберёшь, будут готовы идти.", female = "Так Камнегрив считает, что такая слабая героиня сможет меня защитить? А ведь придётся. Возьми-ка с собой пару-тройку друзей. Ты же знаешь, что делать, да? Ты прикрываешь мою спину, а я веду тебя к убежищу Братства Справедливости. Держись ко мне поближе. Бандиты братства охотятся за моей головой. Если нас увидят вместе, они попытаются меня убить. Дай мне знать, когда ты и друзья, которых ты соберёшь, будут готовы идти." },
    ["155c"] = { male = "Великолепно, сэр путник! Теперь, когда мы знаем, где прячется ван Клиф, – он наш!", female = "Великолепно, леди путница! Теперь, когда мы знаем, где прячется ван Клиф, – он наш!" },
    ["156a"] = { common = "Если ты принесёшь мне несколько цветков гнили, я сделаю для тебя сок зомби. Цветки гнили растут в самых странных местах. Например, в черепах ужасных скелетов и скелетов-губителей... хотя я лично туда не заглядывал! Кладбище Вороньего холма и Безмятежное кладбище кишмя кишат этими скелетами. Заодно ты и нас от них избавишь. Темнолесье будет тебе весьма признательно." },
    ["156c"] = { male = "Отлично, ты сумел добыть цветки гнили. А я расскажу Альтее Чернодрев из Ночного дозора, что тебе удалось уничтожить несколько скелетов. Ночной дозор охраняет покой Темнолесья, и им нелегко приходится. Разумеется, вести о добровольцах, помогающих остановить нашествие нечисти, будут отрадой для всех.", female = "Отлично, ты сумела добыть цветки гнили. А я расскажу Альтее Чернодрев из Ночного дозора, что тебе удалось уничтожить несколько скелетов. Ночной дозор охраняет покой Темнолесья, и им нелегко приходится. Разумеется, вести о добровольцах, помогающих остановить нашествие нечисти, будут отрадой для всех." },
    ["157a"] = { common = "Вот тебе нитки. Им можно найти тысячи способов применения – от связывания злых духов до зашивания жизни в бездушные предметы." },
    ["157c"] = { male = "Великолепно! Она прекрасно подойдёт… Вот, дражайший путник, прими это в уплату за благороднейший поступок.", female = "Великолепно! Она прекрасно подойдёт… Вот, дражайший путница, прими это в уплату за благороднейший поступок." },
    ["158a"] = { common = "Мне нужна бутылка особого напитка – сока зомби. У хозяина темнолесской таверны \"Алый ворон\" Смиттса наверняка найдётся лишняя бутылочка. Торопись. Ночи стоят холодные, и мне не терпится снова наполнить жилы огнём." },
    ["158c"] = { common = "Значит, тебе нужен сок зомби? Хм... это довольно крепкий напиток, обычно его у меня не заказывают." },
    ["159a"] = { male = "А вот и сок зомби… Будь с ним осторожен. Он такой крепкий, что мёртвого поднимет!", female = "А вот и сок зомби… Будь с ним осторожна. Он такой крепкий, что мёртвого поднимет!" },
    ["159c"] = { common = "Тысяча благодарностей. Твоя глу... то есть твоя доброта согрела сердце старика! Вот, друг, прими это в знак моей благодарности." },
    ["160a"] = { male = "Отнеси эту записку Элло Чернодреву, мэру Темнолесья. Мы с ним старые друзья... И когда он прочитает это и узнает, что ты для меня сделал... не сомневаюсь, он будет счастлив не меньше меня! Ха-ха-ха!!!", female = "Отнеси эту записку Элло Чернодреву, мэру Темнолесья. Мы с ним старые друзья... И когда он прочитает это и узнает, что ты для меня сделала... не сомневаюсь, он будет счастлив не меньше меня! Ха-ха-ха!!!" },
    ["160c"] = { common = "Элло рассматривает письмо... Что это за язык? Похоже, какой-то древний... Не могу его прочитать." },
    ["161a"] = { common = "Если мои подозрения верны, то это взрывчатый порошок. Его следует показать специалистам, чтобы выяснить, с чем именно мы имеем дело. Ашлана Камнехмыла направили в полк, охраняющий Дун Модр и мост Тандола. Путь предстоит нелёгкий и опасный. Пройди через врата Альгаза, по дороге, ведущей через Болотину, и отыщи Камнехмыла в Дун Модре. Советую не сходить с дороги и не задерживаться." },
    ["161c"] = { common = "Да, старина Плотина не зря беспокоится." },
    ["162a"] = { common = "Прошу тебя, отнеси этот отчёт кому-нибудь, сведущему в такого рода вопросах. Я слышал про одну ночную эльфийку по имени Грацина Сила Духа. Она посвятила много времени изучению форм жизни, встречающихся лишь в Азероте; она и историк заодно! Если ты хочешь, чтобы кто-то объяснил, что именно происходит и как это прекратить, обратись к ней. Нам любая помощь не помешает. Говорят, она сейчас в храме Луны в Дарнассе." },
    ["162c"] = { common = "Что до твоего отчёта... мы, ночные эльфы, знаем, о каком ужасе идёт речь. Рудознатец правильно поступил, отправив свой отчёт и тебя ко мне. Эти существа мигом пожрут всю пустыню Танарис; они представляют собой одну из величайших опасностей, с которой только можно столкнуться. Знакомься – это силитиды. Так зовутся странные насекомые, которые служат величайшему злу, грозящему и Орде, и Альянсу. Жаль, что нам не хватило ума понять это раньше." },
    ["163a"] = { common = "Что-то неладно на Вороньем холме. Калор клянётся, что он заметил кого-то – или что-то – в одном из домов. Две ночи подряд он видел крадущиеся тени, а на третью – свет в одном из окон. Если тебя и в самом деле беспокоит безопасность Темнолесья, выясни, что за чудовище скрывается на Вороньем холме." },
    ["163c"] = { common = "Нет! Прошу, не убивай меня! Это всего лишь я... Трясунчик! Они повсюду... Мне не скрыться! Чудовища на Вороньем холме? Н-н-нет... не может быть. Всего лишь безвредный Трясунчик." },
    ["164a"] = { common = "Ты знаешь Свена? Вот кто настоящий служитель Света! Он и его последователи стоят лагерем в северо-западной части Сумеречного леса. Увы, их так мало, что некого отправить за припасами в город. Не поможешь ли ты ему?" },
    ["164c"] = { common = "Припасы нам очень пригодятся. Семья Кэрвинов не оставляет нас без помощи. Вот, прими награду за труды." },
    ["165a"] = { common = "Одно время в город частенько приходил старик и покупал припасы, но в последнее время я его не видела. Он живёт в хижине рядом с кладбищем Вороньего холма, если я верно запомнила. Не навестишь ли ты его? Вдруг с ним что-то случилось?" },
    ["165c"] = { common = "Илана Карвин? Хе-хе, да, разумеется, Карвин. Нет, со мной всё в порядке, но мне трудновато ходить в город. Дороги нынче опасные, а я не молодею. Может, ты окажешь старику пару услуг?" },
    ["166a"] = { common = "Осталось одно, последнее задание. Эдвин ван Клиф должен умереть. Хотя меня печалит сам факт вынесения человеку смертного приговора, для всего народа Западного Края будет гораздо лучше, если ван Клиф упокоится навечно. Принесите мне голову этого негодяя, когда с ним будет покончено." },
    ["166c"] = { common = "Вы проявили удивительную храбрость. Народное ополчение благодарит вас за службу народу Западного Края. Смерть ван Клифа станет началом конца для Братства Справедливости. Надеюсь, недалёк тот прекрасный день, когда мир вновь снизойдёт на эту честную землю. Честь имею, сэр!" },
    ["167a"] = { common = "Мы находились в обширных шахтах Западного Края, скрытых глубоко под землями Луноречья. Понятия не имею, откуда явились эти мерзкие вороватые вонючки. Так или иначе – туннель обрушился на нас. Мне удалось выбраться, но остальные... о них я ничего не знаю. Вдруг тебе повезёт больше, чем мне? Я ищу своего брата. Он всегда носил значок Лиги Исследователей. Если ты не найдёшь брата, постарайся найти хотя бы его значок." },
    ["167c"] = { common = "Мои подозрения оправдались. Бедный мой брат... Что ж, благодарю. Определённость лучше загадок, даже если она лишает надежды." },
    ["168a"] = { common = "Многие из моих друзей погибли в тот роковой день, когда обрушился штрек. Если тебя как-нибудь занесёт в ту шахту в Луноречье, пожалуйста, постарайся добыть что-то, что поможет их опознать. А если найдёшь их карточки Союза шахтёров, принеси их мне, я отправлю их семьям погибших." },
    ["168c"] = { common = "Спасибо тебе. Твоя помощь в посмертном успокоении жертв этой чудовищной трагедии была неоценимой. Их семьи будут тебе признательны." },
    ["169a"] = { common = "Розыск! Гат'Илзогг, вождь клана Чёрной Горы, разыскивается за нападение на крепость Каменной Стражи и набеги на окрестности Приозерья. Гат'Илзогг крайне опасен. По последним сведениям, он находится в недавно захваченной крепости и замышляет новые преступления против Королевства. Нашествие орков должно быть остановлено любой ценой. Храбрец, доставивший голову Гат'Илзогга мировому судье Соломону, будет щедро вознаграждён." },
    ["169c"] = { common = "Великолепная работа! Гат'Илзогг вёл своих громил в бой, и они убивали ни в чём не повинных людей. Мы отомстили ему. Это первый шаг на пути возвращения крепости королевству Штормграда!" },
    ["170a"] = { male = "Надеюсь, ты оказался здесь не случайно, герой. Не буду лукавить: после недавнего нападения троггов для нас любая помощь – дар небес. Я слышал, что эти мерзавцы теперь повсюду лезут – ну и до Холодной долины тоже добрались. Говорят, их полно в горах на юго-востоке и возле замёрзшего озера. Так ведь и это ещё не всё! Недавно они напали на наш лагерь на западе и разгромили его! Нам и так воинов не хватает, а тут ещё эти гады... Послушай, приятель, может, ты нам поможешь? Боюсь, иначе нам троггов не одолеть...", female = "Надеюсь, ты оказалась здесь не случайно, героиня. Не буду лукавить: после недавнего нападения троггов для нас любая помощь – дар небес. Я слышал, что эти мерзавцы теперь повсюду лезут – ну и до Холодной долины тоже добрались. Говорят, их полно в горах на юго-востоке и возле замёрзшего озера. Так ведь и это ещё не всё! Недавно они напали на наш лагерь на западе и разгромили его! Нам и так воинов не хватает, а тут ещё эти гады... Послушай, подруга, может, ты нам поможешь? Боюсь, иначе нам троггов не одолеть..." },
    ["170c"] = { common = "Если повсюду происходит то же, что и здесь, у нас, то, клянусь бородой Магни, нас ждёт большая беда! Остаётся надеяться, что король и Совет придумают, что делать с этими проклятыми троггами, иначе нам конец." },
    ["172a"] = { common = "Ты хочешь помочь сиротам? Да благословят тебя боги! Твоя помощь во время Детской недели будет очень кстати! Вот, возьми эту свистульку. Действовать она будет недолго – до конца Детской недели. Свистни в неё – и появится сирота, за которым ты обещаешь присматривать. Свистни ещё раз – ребёнок уйдёт. Прошу тебя, пользуйся свистулькой почаще, не забывай своего подопечного! Для детей это так важно..." },
    ["172c"] = { male = "Заг-заг! Меня зовут Грент. Ты теперь мой опекун, да? Ты ищешь приключений, совсем как мои мама с папой! Наша попечительница говорит, что они с честью погибли в бою! Я так рад с тобой познакомиться! А мы теперь будем всё делать вместе? Мне столько всего хочется сделать, а попечительница говорила, ты мне в эту неделю будешь всё равно как старший брат. Вот здорово!", female = "Заг-заг! Меня зовут Грент. Ты теперь моя опекунша, да? Ты ищешь приключений, совсем как мои мама с папой! Наша попечительница говорит, что они с честью погибли в бою! Я так рад с тобой познакомиться! А мы теперь будем всё делать вместе? Мне столько всего хочется сделать, а попечительница говорила, ты мне в эту неделю будешь всё равно как старшая сестра. Вот здорово!" },
    ["173a"] = { male = "На Сумеречный лес наступают силы тьмы, и цель мастера Кэрвина – борьба с этим злом. Благодаря нашим усилиям народ Темнолесья живёт в безопасности. Ты считаешь, что достоин вступить в наши ряды? Когда-то я был таким же, как ты. Меня раздражало самодовольство Дозора, и я стал соратником мастера Кэрвина. Если ты хочешь показать, на что способен, то слова тебе не помощники. Выступи против воргенов-тенеткачей Ночной Погибели в Светлой роще – светлой, ха! – и Гниющем саду.", female = "На Сумеречный лес наступают силы тьмы, и цель мастера Кэрвина – борьба с этим злом. Благодаря нашим усилиям народ Темнолесья живёт в безопасности. Ты считаешь, что достойна вступить в наши ряды? Когда-то я был таким же, как ты. Меня раздражало самодовольство Дозора, и я стал соратником мастера Кэрвина. Если ты хочешь показать, на что способна, то слова тебе не помощники. Выступи против воргенов-тенеткачей Ночной Погибели в Светлой роще – светлой, ха! – и Гниющем саду." },
    ["173c"] = { male = "Твои успехи впечатляют. Похоже, ты на многое способен. Пожалуй, твоим талантам следует найти более достойное применение. Впрочем, вот что интересно... Воргены появились словно из ниоткуда. Но, с другой стороны, в наши границы вторглось такое количество странных существ, что это не самая большая проблема.", female = "Твои успехи впечатляют. Похоже, ты на многое способна. Пожалуй, твоим талантам следует найти более достойное применение. Впрочем, вот что интересно... Воргены появились словно из ниоткуда. Но, с другой стороны, в наши границы вторглось такое количество странных существ, что это не самая большая проблема." },
    ["174a"] = { common = "Один мой друг, гном по имени Ког, обещал мне помочь создать устройство, которое позволит изучать звёзды. Уверен, что есть и иные объяснения творящемуся в лесу, чем магическое вмешательство. Принеси мне бронзовую трубку, изготовленную искусным инженером. Согласно чертежам Кога, это шаг номер один." },
    ["174c"] = { common = "Великолепно! Первый шаг мы сделали успешно!" },
    ["175a"] = { common = "Согласно чертежам Кога, мне нужно отыскать способ отражать свет. Помнится, есть у нас одна особа по имени Мэри, которая вечно таскает с собой зеркальце. Может быть, ты отыщешь её и она одолжит нам свою отражающую поверхность? Кажется, она когда-то жила в южной части Сумеречного леса." },
    ["175c"] = { common = "Всё верно, у меня некогда было зеркальце." },
    ["176a"] = { common = "Разыскивается: Дробитель В юго-западной части Элвиннского леса поселился могучий гнолл по прозванию Дробитель. Несмотря на все усилия, поймать его так и не удалось. Армия Штормграда назначила за этого гнолла щедрую награду. Чтобы получить её, необходимо представить маршалу Дугхану доказательства смерти Дробителя." },
    ["176c"] = { common = "Ха! Отличная работа! А я уже было думал, что никому не под силу совладать с этим чудовищем! Вот твоя награда, а с ней прими и мою благодарность: этот гнолл у нас уже вот где сидел!" },
    ["177a"] = { common = "Зеркальце было одним из моих главных сокровищ... но потом со мной случилось несчастье. После этого я зашвырнула стекляшку за амбар. Одно время там бродил Невменяемый Вурдалак. Может быть, он утащил моё зеркальце. Говорят, что теперь эта тварь живёт на Безмятежном кладбище." },
    ["177c"] = { common = "Шедеврально! Это непременно сработает. Я глубоко признателен!" },
    ["178a"] = { common = "*До вас доносится бесплотный голос...* Не пугайся. Я Теокрит, верховный маг башни Азоры в Элвиннском лесу. При помощи этой подвески гноллы из стаи Темношкуров общаются со своим повелителем Моргантом. Я потратил много времени на то, чтобы тоже научиться вещать через эти подвески. Если ты слышишь моё сообщение, значит заклинание сработало. Принеси мне эту подвеску, и я щедро вознагражу тебя." },
    ["178c"] = { common = "Благодарю тебя. Я передал это сообщение через подвески Темношкуров несколько недель назад и полагал, что заклинание не сработало. Оказывается, в конечном итоге оно достигло по меньшей мере некоторых из них. Хочется верить, что рано или поздно я научусь посылать таким образом боевые заклинания и обездвиживать тех гноллов, которые носят эти подвески. К сожалению, до этого ещё очень далеко." },
    ["179a"] = { common = "Ну-ка, ну-ка, что тут у нас?.. Холодновато в наших краях, верно? Готов спорить, у тебя всё время мёрзнут руки. Ну, угадал? Я скажу, что тебе нужно: пара хороших тёплых перчаток. Ну да, душа у меня добрая, так что замёрзнуть я тебе не дам. Только вот есть одно условие. Принеси мне волчьего мяса – и мы, считай, в расчёте. Справедливо, как думаешь? Мне – мясо, а уж я-то позабочусь о том, чтобы у тебя пальцы больше не мёрзли. Ну, что скажешь?" },
    ["179c"] = { common = "О! Прекрасно! Волчье мясо – это то, что надо!.. Не беспокойся, свою часть сделки я выполню честно. Вот, посмотри, что из этого тебе подойдёт." },
    ["180a"] = { common = "Разыскивается: лейтенант Фангор Глава гнолльской стаи Темношкуров, соратник Морганта, врага Города и Королевства. По приказу чиновника Соломона подлый предатель Штормграда приговаривается к смерти. Тот, кто приведёт приговор в исполнение, должен в доказательство принести лапу Фангора мировому судье Соломону." },
    ["180c"] = { male = "Значит, злобный лейтенант Фангор мёртв? Прекрасно. Ты удивительно храбрый герой. Городской совет Приозерья благодарит тебя за помощь.", female = "Значит, злобный лейтенант Фангор мёртв? Прекрасно. Ты удивительно храбрая героиня. Городской совет Приозерья благодарит тебя за помощь." },
    ["181a"] = { common = "Для завершения работы не хватает только одного предмета. Согласно чертежам Кога, нам нужна линза. Единственную подходящую линзу в наших краях будет нелегко достать. В кургане на юге Сумеречного леса живёт огр по имени Ззарк'Вул. Если сможешь, принеси мне его монокль, и я использую его вместо линзы!" },
    ["181c"] = { common = "Наконец-то! Устройство для изучения звёзд готово! Спасибо тебе. Я могу продолжить исследования..." },
    ["182a"] = { common = "Нас с моим братом Сениром отправили в Дун Морог, чтобы разведать, действительно ли там объявились тролли, и насколько серьёзна эта угроза. Совету хватает хлопот с троггами, лишние проблемы им ни к чему. Насколько я видел, тролли здесь не слишком хорошо закрепились; в основном они живут в южной пещере. Как по мне, тут и армия не нужна: несколько крепких бойцов вполне управятся. Может, и ты решишь поучаствовать в этом деле? Не за так, конечно: у меня есть что тебе предложить." },
    ["182c"] = { common = "Проклятые тролли! Да не озарит их Извечный Свет! Шумно дышит; немного успокаивается. Эти негодяи ввалились ко мне ночью и украли мои записи! У меня хватило ума не доверять этому негодному подмастерь..." },
    ["183a"] = { common = "Нет ничего лучше охоты на диких вепрей, верно? Правда, здесь, в Холодной долине, их расплодилось столько, что весь интерес пропадает. Их и загонять не надо – они злые, как демоны, и сами бросаются прямо на охотника. Я бы даже сказал, что этих злобных свиней так много, что и охотиться-то стало опасно... Короче говоря, я буду благодарен, если ты поможешь мне прикончить хотя бы нескольких кабанов." },
    ["183c"] = { common = "Отлично, просто отлично! Теперь я могу спокойно отдох... М-м... Заняться охотой. Благодарю за помощь." },
    ["184a"] = { common = "Вот бумага, дающая право на расширение фермерских владений в Западном Крае. Она подписана Теодором Хмуробровом и его женой, Верной Хмуробров. На обороте документа торопливо нацарапаны слова: \"Мы нажали на Хмуроброва и получили от него нужную бумагу. Если тебе захочется заполучить один из участков, она тебе пригодится. С Хмуробровами проблем не предвидится: я видел, как они покидают Западный Край, у них как раз телега сломалась.\" Наверное, Хмуробровы были бы рады получить этот документ назад..." },
    ["184c"] = { common = "Ты представить не можешь, как мы тебе благодарны! Конечно, сейчас в этих краях приличным людям не место, но, может, времена переменятся, и тогда нам нужно будет предъявить эту бумагу на право владения землёй. Конечно, многого я предложить не могу, но возьми хотя бы вот это..." },
    ["185a"] = { common = "Когда я была маленькой девочкой, отец научил меня искусству охоты на тигров. Молодых зверей гораздо проще выслеживать и убивать. Поэтому начнём с простого. Молодые тигры часто забредают к лагерю экспедиции. Постарайся выследить и убить несколько зверей." },
    ["185c"] = { common = "Неплохо. Пора тебе двигаться дальше." },
    ["186a"] = { male = "А ты учишься, герой. Посмотрим, как ты справишься со взрослыми кошками. На сей раз тебе предстоит убить десять тигров Тернистой долины.", female = "А ты учишься, героиня. Посмотрим, как ты справишься со взрослыми кошками. На сей раз тебе предстоит убить десять тигров Тернистой долины." },
    ["186c"] = { male = "Впечатляюще, герой. Ты делаешь успехи.", female = "Впечатляюще, героиня. Ты делаешь успехи." },
    ["187a"] = { male = "Поднимем ставки. Докажи, что сможешь убить десять старых тигров Тернистой долины. Справишься – и я признаю, что ты готов к последнему испытанию, после которого я объявлю тебя великим охотником на тигров в присутствии мастера Эрнестуэя. Старые тигры Тернистой долины неуловимы для врага и безжалостны в схватке.", female = "Поднимем ставки. Докажи, что сможешь убить десять старых тигров Тернистой долины. Справишься – и я признаю, что ты готова к последнему испытанию, после которого я объявлю тебя великим охотником на тигров в присутствии мастера Эрнестуэя. Старые тигры Тернистой долины неуловимы для врага и безжалостны в схватке." },
    ["187c"] = { male = "Очень, очень неплохо. Думаю, ты почти готов.", female = "Очень, очень неплохо. Думаю, ты почти готова." },
    ["188a"] = { male = "Вот твоё последнее испытание. Мы уже много недель выслеживаем эту хитрую тигрицу, прозванную Син'Далл. Интересно, сможешь ли ты сделать то, что не удавалось ни одному герою – выследить и убить Син'Далл. Принеси мне её лапу в доказательство своего подвига. Даже выследить её – непростая задача.", female = "Вот твоё последнее испытание. Мы уже много недель выслеживаем эту хитрую тигрицу, прозванную Син'Далл. Интересно, сможешь ли ты сделать то, что не удавалось ни одному героине – выследить и убить Син'Далл. Принеси мне её лапу в доказательство своего подвига. Даже выследить её – непростая задача." },
    ["188c"] = { common = "Впечатляюще, должна сказать! Ты великий Охотник на тигров!" },
    ["189a"] = { male = "Проклятые тролли! Они постоянно убивают наших агентов! Я потерял в стычках с ними лучших своих бойцов. Цена операции всё растёт и растёт! Как я объясню это барону Ревилгазу? Решительные действия нас спасут... Думай, Кебок... Тебя назначили на эту должность не за безделье... Придумал! Тебя...путник зовут, да? Ты ведь мне поможешь? А уж я заплачу! Предлагаю сделку... ты принесёшь мне уши пятнадцати троллей из племени Кровавого Скальпа, а я дам тебе денег.", female = "Проклятые тролли! Они постоянно убивают наших агентов! Я потерял в стычках с ними лучших своих бойцов. Цена операции всё растёт и растёт! Как я объясню это барону Ревилгазу? Решительные действия нас спасут... Думай, Кебок... Тебя назначили на эту должность не за безделье... Придумал! Тебя...путница зовут, да? Ты ведь мне поможешь? А уж я заплачу! Предлагаю сделку... ты принесёшь мне уши пятнадцати троллей из племени Кровавого Скальпа, а я дам тебе денег." },
    ["189c"] = { common = "Отлично, отлично. Это временно решит проблему… *Он принимается бормотать себе что-то под нос насчёт огромных издержек…* Что? Ты всё ещё здесь? Награда? А, да... Разумеется, бери... этого должно с лихвой хватить." },
    ["190a"] = { common = "Если ты хочешь отправиться на охоту вместе с нами под предводительством Хеминга, докажи, что умеешь выслеживать пантер. Не бойся, начнём с простого. Для примера убей десять молодых пантер. Выследить их – только полдела..." },
    ["190c"] = { common = "Доброе начало!" },
    ["191a"] = { male = "А теперь задача потруднее. Если ты хочешь доказать, что достоин общаться с настоящими охотниками, убей десять пантер. С этими ребятами не так легко справиться, они посильнее молодых зверей, с которыми тебе приходилось сталкиваться прежде.", female = "А теперь задача потруднее. Если ты хочешь доказать, что достойна общаться с настоящими охотниками, убей десять пантер. С этими ребятами не так легко справиться, они посильнее молодых зверей, с которыми тебе приходилось сталкиваться прежде." },
    ["191c"] = { common = "Великолепно!" },
    ["192a"] = { common = "Усложняем задание. Настоящий охотник сможет одолеть даже тенебрюхих пантер, самых опасных в Тернистой долине. Докажи, что сможешь прикончить десять таких тварей. Если тебе покажется, что их трудно выслеживать, попробуй для начала убить одну..." },
    ["192c"] = { common = "Молодец!" },
    ["193a"] = { male = "Тебе почти удалось доказать, что ты великий охотник на пантер. И всё же остаётся одна пантера по имени Баг'тира. Добудь её клык, и моё уважение тебе обеспечено!", female = "Тебе почти удалось доказать, что ты великая охотница на пантер. И всё же остаётся одна пантера по имени Баг'тира. Добудь её клык, и моё уважение тебе обеспечено!" },
    ["193c"] = { male = "Итак, великая Баг'тира мертва! Браво. Ты и правда могучий герой!", female = "Итак, великая Баг'тира мертва! Браво. Ты и правда могучая героиня!" },
    ["194a"] = { male = "Значит, ты считаешь себя превосходным охотником? Проверим. Ступай в джунгли и подстрели десять ящеров Тернистой долины. Посмотрим, как ты справишься с крупной дичью. И нет, я не скажу, где их искать! Первая половина испытания – поиски зверя.", female = "Значит, ты считаешь себя превосходной охотницей? Проверим. Ступай в джунгли и подстрели десять ящеров Тернистой долины. Посмотрим, как ты справишься с крупной дичью. И нет, я не скажу, где их искать! Первая половина испытания – поиски зверя." },
    ["194c"] = { common = "Неплохо, старина!" },
    ["195a"] = { common = "А теперь я задам тебе задачку, посмотрим, придётся ли она тебе по вкусу. Отправляйся в джунгли и добудь десять ящеров-кнутохвостов. Увидим, хватит ли тебе пороху!" },
    ["195c"] = { common = "Именно так и появляются трофеи над камином! Неплохая охота!" },
    ["196a"] = { male = "Посмотрим, как ты справишься со следующим испытанием. Здесь живут хитрые ящеры, мы зовём их тропическими ловцами. Их гораздо труднее выследить и убить, чем другие виды, с которыми тебе пришлось столкнуться. Убей десять тропических ловцов, и я соглашусь, что из тебя ещё выйдет настоящий охотник.", female = "Посмотрим, как ты справишься со следующим испытанием. Здесь живут хитрые ящеры, мы зовём их тропическими ловцами. Их гораздо труднее выследить и убить, чем другие виды, с которыми тебе пришлось столкнуться. Убей десять тропических ловцов, и я соглашусь, что из тебя ещё выйдет настоящая охотница." },
    ["196c"] = { common = "Хо-хо!!! У нас есть настоящий убийца ящеров! Неплохо, старина!" },
    ["197a"] = { common = "Ну, раз ты ходишь в джунгли как к себе домой, дай-ка я расскажу тебе о свирепом ящере, которого даже мне не удалось убить. Ажек называет этого хитрого ящера Тетис. Если ты хочешь показать подлинное мастерство, убей Тетис и принеси мне его коготь. Этот подвиг не удался ещё ни одному охотнику!" },
    ["197c"] = { male = "Великий путник, убийца ящеров! Неплохо звучит, а?", female = "Великая путница, убийца ящеров! Неплохо звучит, а?" },
    ["198a"] = { common = "Хммм. У меня и правда есть для тебя дело. Лейтенант Дорен и его последователи там, на севере, регулярно получают от нас поставки еды и оборудования. Пришло время доставить очередную партию, а, учитывая нападения троллей, никто не хочет за это браться. Лагерь Дорена располагается на северо-западе от дороги у входа в Тернистую долину из Сумеречного леса. Отнеси эту посылку рядовому Торсену, а если его нет в лагере, значит, он дежурит на юге от него. Он займётся этими припасами. Учти, если ты провалишь задание, придётся тебе возместить мои затраты." },
    ["198c"] = { common = "Эти мины помогут нам защититься от этого зверя, Курцена, и его людей. Спасибо за доставку. Если тебе нужна работа, может быть, я смогу помочь тебе. И тебе не придётся иметь дело с гоблинами, а?" },
    ["199a"] = { common = "Вы берёте образец странно пахнущего порошка." },
    ["199c"] = { common = "Это тревожная находка, мягко говоря!" },
    ["200a"] = { common = "Если Курцену известна тайна Торсена, значит, в наши ряды затесался шпион. Необходимо выяснить, откуда просочилась информация! Связным Торсена в лагере Курцена был букмекер Герод. Герод работает снабженцем у Курцена, и знает всё о его лагере. Если удастся добыть его записи, быть может, мы узнаем, как накрыли Торсена. Когда мы служили в войсках Курцена, кабинет букмекера располагался на верхнем этаже единственного двухэтажного дома в лагере. Скорее всего, его записи по-прежнему там." },
    ["200c"] = { common = "Вы находите записи букмекера Герода. Среди них: список поставок в лагерь, запросы от полковника Курцена и различные письма." },
    ["201a"] = { common = "Мне сообщили о группе охотников, разбивших лагерь вверх по реке от рудника Торговой Компании возле озера Назферити. Я бы не придал этому значения, но говорят, будто один из тамошних охотников – сам Хеминг Эрнестуэй. Мне не верится, но у него настолько высокие связи, если ты понимаешь о чём я, что лучше заранее обезопасить себя. Почему бы тебе не заглянуть в этот лагерь и не разузнать, что они замышляют?" },
    ["201c"] = { common = "Хмм, значит у меня были точные сведения, как обычно. Любопытно. Кажется, они не представляют для нас опасности, но быть может, им нужны наши превосходные товары. Хммм..." },
    ["202a"] = { male = "И снова ты показал нам, на что способен. Кажется, талантов тебя не меньше, чем у самого Курцена! Это может спасти нас, горстку повстанцев...если ты сможешь выступить против Курцена и одержать над ним верх! Он управляет своими людьми из глубин Схрона. Ступай в эту пещеру, пробейся сквозь ряды её защитников, и одолей Курцена и его ближайших приспешников. Прощай. Ты – наша последняя надежда.", female = "И снова ты показала нам, на что способна. Кажется, талантов тебя не меньше, чем у самого Курцена! Это может спасти нас, горстку повстанцев...если ты сможешь выступить против Курцена и одержать над ним верх! Он управляет своими людьми из глубин Схрона. Ступай в эту пещеру, пробейся сквозь ряды её защитников, и одолей Курцена и его ближайших приспешников. Прощай. Ты – наша последняя надежда." },
    ["202c"] = { male = "Я не смёл верить вестям, но ты несёшь нам доказательство того, что... Курцен и его главные сторонники повержены. Ты спас нас всех! Джунгли полны различных угроз, но никто не мог сравниться с жестоким и умным Курценом. Теперь, когда его нет, мы можем вздохнуть спокойнее.", female = "Я не смёл верить вестям, но ты несёшь нам доказательство того, что... Курцен и его главные сторонники повержены. Ты спасла нас всех! Джунгли полны различных угроз, но никто не мог сравниться с жестоким и умным Курценом. Теперь, когда его нет, мы можем вздохнуть спокойнее." },
    ["203a"] = { common = "Мы решительно проигрываем полковнику Курцену. Он не только блестящий тактик – его войска превосходят нас в численности в десять раз! Чтобы выжить, нам придётся прибегнуть к его же подлой тактике. Проберись в лагерь на востоке и убей как можно больше его бойцов. И скройся до прибытия подкрепления." },
    ["203c"] = { common = "Отлично. Потеря опытных бойцов вынудит его ослабит натиск на наш лагерь. А ты не боишься быть на нашей стороне, зная, какие силы выступают против нас??" },
    ["204a"] = { common = "Чтобы получить шанс выстоять против Курцена, нам необходимо лишить его лекарей. Он собрал немало целителей, которые лечат его войска зельями из джунглей и травят наших бойцов экстрактами ядовитого папоротника. Нам и самим нужны эти составы, чтобы изучить их и создать свои собственные. Обыщи посёлок Курцена – лекарства находятся у его целителей и партизан, а экстракты скорее всего хранятся в ящиках с припасами." },
    ["204c"] = { common = "Молодец. Эти лекарства помогут нам выжить и сохранить боеспособность. А при помощи экстракта мы создадим собственные снадобья." },
    ["205a"] = { common = "Пока я изучаю принесённые тобой прорисовки, собери для меня принадлежности злой магии троллей. Тебе придётся проникнуть в земли племени Дробителей Черепов, второго племени на далёком юге, и добыть фетиши у их знахарей и мистиков." },
    ["205c"] = { common = "Спасибо. Я изучу эти фетиши и пойму, они ли причина того, что Курцен обратился ко злу." },
    ["206a"] = { common = "Хотя Курцен и мёртв, зло, соблазнившее его, живёт! Вот что мне удалось выяснить: огрский маг – Май'Зот – живёт в огрском кургане в восточных горах Тернистой долины. Говорят, что он пользуется магией, овладевающей разумом, и я не сомневаюсь, что Май'Зот виноват в падении Курцена. Пока он жив, зло будет расползаться, и может даже появиться второй Курцен. Убей его и принеси мне его Око Разума, артефакт, позволяющий ему творить тёмные дела." },
    ["206c"] = { common = "Ага! Тебе удалось убить его! На стороне добра действуют великие силы! Да не ослабеет твоя рука! Я исследую Око Разума и попытаюсь придумать, как пользоваться им во благо. Если это невозможно... его следует уничтожить." },
    ["207a"] = { common = "Когда-то полковник Курцен был великим и благородным человеком – я хочу выяснить, что заставило его свернуть с пути истинного! Должно быть, он находится под воздействием магии троллей. Надо изучить древние легенды, чтобы убедиться в этом. В руинах тролльских городов в Тернистой долине спрятаны четыре таблички. Мне необходимо их добыть и прочесть! Перерисуй с них все отметки и принеси рисунки мне. Первая табличка находится в Руинах Бал'лал, вторая – на Коварном рифе, а третья и четвёртая – в Руинах Зул'Кунды." },
    ["207c"] = { common = "Спасибо. Я изучу твои рисунки и попытаюсь выяснить, есть ли связь между троллями и злом, одолевшим полковника Курцена." },
    ["208a"] = { male = "Ты достоин занять место среди нас. И на полях битвы в Лордероне, и в глубоких джунглях, мне редко приходилось видеть столь умелое обращение с оружием. Тебе удалось убить свирепого Син'Далла, неуловимую Баг'тиру и коварного Тетиса. Осталось одно – добыть голову короля Бангалаша. Давненько я точу зуб на этого белого тигра и оказался здесь именно ради него. Убей короля Бангалаша, и мы признаем, что тебе нет равных в искусстве охоты.", female = "Ты достойна занять место среди нас. И на полях битвы в Лордероне, и в глубоких джунглях, мне редко приходилось видеть столь умелое обращение с оружием. Тебе удалось убить свирепого Син'Далла, неуловимую Баг'тиру и коварного Тетиса. Осталось одно – добыть голову короля Бангалаша. Давненько я точу зуб на этого белого тигра и оказался здесь именно ради него. Убей короля Бангалаша, и мы признаем, что тебе нет равных в искусстве охоты." },
    ["208c"] = { male = "Отлично сработано! Здорово! Поздравляю, ты преуспел там, где другие потерпели поражение. Видеть тебя в рядах нашего охотничьего отряда – это честь для меня. Отныне никто не усомнится в твоём искусстве охотника и следопыта. Ура тебе! Ура!", female = "Отлично сработано! Здорово! Поздравляю, ты преуспела там, где другие потерпели поражение. Видеть тебя в рядах нашего охотничьего отряда – это честь для меня. Отныне никто не усомнится в твоём искусстве охотника и следопыта. Ура тебе! Ура!" },
    ["209a"] = { common = "Убивать тигров и добывать их клыки на экспорт в южные моря – трудно и дорого. К счастью, мы придумали способ обрабатывать простые рого-подобные предметы и изготавливать неотличимые подделки. Лучше всего, как ни смешно, подходят клыки троллей из племени Дробителей Черепов. Ш-ш-ш, спокойно, чем меньше знает покупатель, тем крепче он спит, верно? Принеси мне побольше таких клыков, чтобы мы могли подготовить ежемесячную поставку!" },
    ["209c"] = { common = "А, хорошо, хорошо! Хотя ты мог бы получше счистить... Ну, неважно, неважно что. Спасибо, благодаря тебе у нас возрастёт производительность и доходы! Хорошо, хорошо, а теперь перейдём к следующему делу..." },
    ["210a"] = { common = "Готовка по большей части лежит на мне. И она доставляла мне много хлопот, пока я не купил механический горшок у одного гоблина в Пиратской бухте. Это чудо какое-то! Он сэкономил мне много часов... Пока не сломался! Может, ты отнесёшь его назад к продавцу, в ремонт? Продавца зовут Кразек." },
    ["210c"] = { common = "А, вижу, разбитый горшок Кразека! Отличное устройство, но иногда выходят из строя пружины или шестерни. Посмотрим, что случилось с этой штукой… Ага! Заржавел паровой агрегат, полетел сальник, а у надувателя отломились зубья. Странно, как тут умудрялись хотя бы варить репу! Могу ли я это починить? Разумеется! Но не за бесплатно. Бесплатный бывает только сыр в мышеловке..." },
    ["211a"] = { common = "Увы, пришло время напасть на Андорал и изгнать оттуда лича! Злобный Араж Призыватель обосновался в самом сердце руин. Его охраняют многочисленные воины Плети, рассеянные по всему центру бывшего города, а самого Аража охраняют сильнейшие бойцы. Без многочисленных помощников тебе нечего и думать одержать над ним верх. Убей Аража и принеси мне его кристалл-талисман!" },
    ["211c"] = { common = "Свершилось! Араж… этот лич наконец-то пал! Сегодня ты оказал огромную услугу Альянсу. Храбрость и упорство — спутники подлинного героизма. Прошу тебя, прими это в знак нашей благодарности. Пусть все знают, что благодаря тебе Альянс одержал победу!" },
    ["212a"] = { common = "Одно из моих коронных блюд – мороженый василиск под соусом винегрет из лайма. Проблема лишь в том, что... Это мясо не подлежит хранению, а ведь я должен приготовить это блюдо сегодня вечером – на день рождения одного благородного господина! Если сможете, принесите мне охлаждённый окорок только что убитого ледоглазого василиска, а я организую специально для вас царскую трапезу! Ледоглазые василиски обитают в дюнах на северо-западе Тернистой долины, так что путь вам предстоит неблизкий. И не задерживайтесь по дороге!" },
    ["212c"] = { common = "О, вот это окорочок! Большое, просто огромное спасибо! А теперь попрошу меня простить, мне нужно быстренько нарубить мясо, замариновать его и сервировать для банкета." },
    ["213a"] = { common = "Он слишком далеко зашёл! Мало того, что этот Гелриз теснит управляющих, назначенных торговыми олигархами, теперь он попытался обвести вокруг пальца знаменитейшего пирата! Ревилгаз заявил, что не потерпит такого, и велел любым способом решить проблему. Любым способом? Я выбираю кражу. Геологов Торговой компании, работающих рядом с озером Назферити, заинтересовали странные синие кристаллы, найденные в руднике. Принеси мне образцы этих камней, и меня не волнует, что тебе придётся сделать с геологами для выполнения задания." },
    ["213c"] = { common = "Любопытно. Огранка кристаллов говорит только о том, что они собираются пользоваться ими в качестве горючего или катализатора. Большего сказать я не могу. Образцы необходимо показать старшему химику Хихиканту." },
    ["214a"] = { common = "Не секрет, что красные банданы являются отличительным знаком бандитов из Братства Справедливости. Но мы узнали, что материал, из которого они изготовлены, указывает на ранг члена братства. Я рассказываю вам об этом, потому что хочу, чтобы вы устранили как можно больше бандитов высокого ранга. Обладающих наивысшим рангом, без сомнения, можно найти в тайном убежище ван Клифа. Когда справитесь с заданием, принесите мне десять красных шёлковых бандан в доказательство их смерти – и будете вознаграждены. Желаю удачи." },
    ["214c"] = { male = "Отличная работа путник! От имени народного ополчения я благодарю вас за ваши усилия. Вскоре с помощью таких смельчаков, как вы, мы вернём эту землю её народу.", female = "Отличная работа путница! От имени народного ополчения я благодарю вас за ваши усилия. Вскоре с помощью таких смельчаков, как вы, мы вернём эту землю её народу." },
    ["215a"] = { male = "Спасибо, что спас меня. Понимаю, как это выглядит... но позволь мне объяснить. Лейтенант Дорен поручил мне снова завербоваться к Курцену, чтобы следить за его солдатами и предоставлять столь необходимые сведения повстанцам. Ты видел, чем обернулась для меня попытка проникнуть в лагерь Курцена. Я думал, что это - мой шанс... Ещё раз спасибо за спасение. Это была тайная миссия, никому о ней не говори. Но лейтенант Дорен может всё объяснить.", female = "Спасибо, что спасла меня. Понимаю, как это выглядит... но позволь мне объяснить. Лейтенант Дорен поручил мне снова завербоваться к Курцену, чтобы следить за его солдатами и предоставлять столь необходимые сведения повстанцам. Ты видела, чем обернулась для меня попытка проникнуть в лагерь Курцена. Я думал, что это - мой шанс... Ещё раз спасибо за спасение. Это была тайная миссия, никому о ней не говори. Но лейтенант Дорен может всё объяснить." },
    ["215c"] = { common = "Да, Торсен сказал тебе правду. Только помалкивай об этом. Одно время мы, повстанцы, были слепо преданы полковнику Курцену. Но сейчас он перешёл на сторону зла, и наша верность обратилась в ненависть. Если кто-нибудь узнает, что рядовой Торсен имел дело с людьми Курцена, однажды утром мы можем найти его с перерезанным горлом. Насколько мне известно, о задании Торсена знала только сержант Йохва и я. И кто-то ещё. Предатель." },
    ["216a"] = { common = "Эти фурболги Колючего Меха мешают нашему продвижению! Деревня Колючего Меха, что лежит на востоке, преграждает нам путь к заставе Расщеплённого Древа. Это на дороге, что идёт в обход деревни Астранаар. Если мы не будем её контролировать, Альянс получит дополнительный путь для вторжения. Мы должны заткнуть эту дыру! Иди в деревню Колючего Меха да устрой фурболгам прореживание. Выполнишь задачу – получишь награду, но важнее будет то, что ты выполнишь свой долг перед Ордой!" },
    ["216c"] = { male = "Отлично, герой, отлично! Я буду продолжать посылать отряды истреблять этих фурболгов, но по крайней мере я могу рассчитывать, что ещё одна дорога расчищена от сил Альянса. Теперь завоевание Ясеневого леса Ордой пойдёт полным ходом! Ты заслужил свою награду, герой! Честь и слава тебе!", female = "Отлично, героиня, отлично! Я буду продолжать посылать отряды истреблять этих фурболгов, но по крайней мере я могу рассчитывать, что ещё одна дорога расчищена от сил Альянса. Теперь завоевание Ясеневого леса Ордой пойдёт полным ходом! Ты заслужила свою награду, герой! Честь и слава тебе!" },
    ["217a"] = { male = "Наши разведчики обнаружили предводителя троггов. Похоже, этих тварей привёл к озеру Лок Модан их вождь по имени Громаг. Его хорошо охраняют. Два элитных стража, Скрежетун и Буян, ни на шаг от него не отходят. Если ты уверен в своих силах, можешь возглавить операцию по ликвидации Громага и его громил. Если нам удастся прикончить вождя троггов, то появится шанс загнать проклятых тварей обратно под землю.", female = "Наши разведчики обнаружили предводителя троггов. Похоже, этих тварей привёл к озеру Лок Модан их вождь по имени Громаг. Его хорошо охраняют. Два элитных стража, Скрежетун и Буян, ни на шаг от него не отходят. Если ты уверена в своих силах, можешь возглавить операцию по ликвидации Громага и его громил. Если нам удастся прикончить вождя троггов, то появится шанс загнать проклятых тварей обратно под землю." },
    ["217c"] = { male = "Превосходно! Ты вернул надежду Лок Модану. Громаг мёртв, и у нас появилась надежда изгнать троггов из наших земель.", female = "Превосходно! Ты вернула надежду Лок Модану. Громаг мёртв, и у нас появилась надежда изгнать троггов из наших земель." },
    ["218a"] = { common = "Мои записи! Они уволокли в свою мерзкую пещеру мои записи! Здоровенный громила, весь разрисованный с головы до ног... Жаль, я не смог разглядеть его получше! Послушай, тебе ведь уже приходилось иметь дело с троллями? Может, ты сумеешь вернуть мои драгоценные записи?.." },
    ["218c"] = { common = "Великолепно! Словами не передать, как я благодарен! Мои записи, наконец-то!.. Да к тому же, похоже, троллей Холодной долины удалось-таки обуздать, так что больше беспокоиться не о чем. Кстати, послушай: я скоро закончу своё донесение – так, может, ты поработаешь курьером и доставишь его моему братцу Сениру?" },
    ["219a"] = { common = "Наконец-то, сторонники Альянса! Помогите... Пожалуйста... Последнее, что я помню – как орки окружили наш отряд. Меня ударили по затылку, и в глазах потемнело. А теперь я пленник в этой пещере. Спасите меня, я тяжело ранен. Мне понадобится помощь, чтобы добраться до города... Пожалуйста... Вы моя последняя надежда..." },
    ["219c"] = { male = "Ты отлично послужил Королевству, герой. Благодарю тебя за помощь капралу Кеешану. Одному ему не удалось бы сбежать от орков Чёрной Горы. Подобная храбрость заслуживает великой награды.", female = "Ты отлично послужила Королевству, героиня. Благодарю тебя за помощь капралу Кеешану. Одному ему не удалось бы сбежать от орков Чёрной Горы. Подобная храбрость заслуживает великой награды." },
    ["220a"] = { common = "Прежде чем дать тебе в награду следующий тотэм, Ислен поручит тебе ещё одно задание. Для этого понадобится фиал с водой, который я дал тебе. Ступай, поговори с ней. Мы ещё встретимся." },
    ["220c"] = { common = "А, фиал с водой, созданной и благословлённой Брин и добытой тобой, ни больше ни меньше. Жидкость в этом фиале необходима для создания сапты, но годится и для других целей. При помощи этой сапты ты сможешь разглядеть водных духов в святилище в Серебряном бору, к югу от Подгорода. Что же до оставшихся капель... о них я расскажу тебе потом. Не боишься долгого пути?" },
    ["221a"] = { male = "Может, ты заметил крупных воргенов, бродящих по лесу в компании тенеткачей? Судя по всему, большую часть воргенских сил и составляют эти самые вестники Тьмы. Странствуя по лесу, я узнал, что они захватили и Гниющий сад на юго-западе от города. Эти воргены сильнее тех, с которыми тебе уже пришлось столкнуться. Будь осторожен.", female = "Может, ты заметила крупных воргенов, бродящих по лесу в компании тенеткачей? Судя по всему, большую часть воргенских сил и составляют эти самые вестники Тьмы. Странствуя по лесу, я узнал, что они захватили и Гниющий сад на юго-западе от города. Эти воргены сильнее тех, с которыми тебе уже пришлось столкнуться. Будь осторожна." },
    ["221c"] = { male = "Ты достойно выступил против вестников Тьмы. Но, похоже, ряды их нескончаемы. На место убитых становятся всё новые и новые воргены. Что за злая сила притягивает их сюда? Зачем они явились терзать наш несчастный город... Я возлагаю надежду на мастера Кэрвина. Не сомневаюсь, он разберётся с этой проблемой.", female = "Ты достойно выступила против вестников Тьмы. Но, похоже, ряды их нескончаемы. На место убитых становятся всё новые и новые воргены. Что за злая сила притягивает их сюда? Зачем они явились терзать наш несчастный город... Я возлагаю надежду на мастера Кэрвина. Не сомневаюсь, он разберётся с этой проблемой." },
    ["222a"] = { common = "Твои прежние достижения наводят меня на мысль, что ты можешь схватиться с сильнейшими из воргенов, наводнивших наши леса. Самими опасными из всех оказались Ярые Клыки и нечистые воргены. Они живут рядом с пещерами и в руднике на юге. Зарево их костров видно издалека." },
    ["222c"] = { male = "Честно говоря, я не верил, что ты справишься с этой задачей, но ты воистину могучий герой. Более того, если ты хочешь официально присоединиться к борьбе мастера Кэрвина, я с радостью напишу тебе рекомендательное письмо.", female = "Честно говоря, я не верил, что ты справишься с этой задачей, но ты воистину могучая героиня. Более того, если ты хочешь официально присоединиться к борьбе мастера Кэрвина, я с радостью напишу тебе рекомендательное письмо." },
    ["223a"] = { common = "Вот. Отнеси это письмо мастеру Кэрвину. *Он отдаёт вам поблекший пергамент.* Если к нам потянутся такие, как ты, в отряде будет больше людей, чем в Ночном дозоре! Быть может, тогда мы завершим работу, которую сейчас делаем с большим трудом." },
    ["223c"] = { male = "Прости за холодный приём, ты ведь понимаешь, что я очень занятой человек. Вижу, ты произвёл впечатление на Калора. Уверяю тебя, это нелегко. Так или иначе, он рекомендует принять тебя в наши ряды. Вокруг полно ненадёжных людей, а нам нужна помощь тех, на кого можно положиться. Мы бьёмся против демонов, нежити и их пособников. Не теряй бдительности, осторожности и не доверяй никому, кто не хочет нам помочь. Да озарит тебя Свет!", female = "Прости за холодный приём, ты ведь понимаешь, что я очень занятой человек. Вижу, ты произвела впечатление на Калора. Уверяю тебя, это нелегко. Так или иначе, он рекомендует принять тебя в наши ряды. Вокруг полно ненадёжных людей, а нам нужна помощь тех, на кого можно положиться. Мы бьёмся против демонов, нежити и их пособников. Не теряй бдительности, осторожности и не доверяй никому, кто не хочет нам помочь. Да озарит тебя Свет!" },
    ["224a"] = { male = "Мы должны защитить озеро Лок! Множество королевских солдат проливает кровь в далёких землях, а наш родной край в опасности. Трогги полезли изо-всех щелей! Нашествие троггов грозит безопасности Стальгорна. Пора истребить мерзких мутантов! Нам нужна твоя помощь, отважный искатель приключений. Ступай и устрани нависшую над нами угрозу. Убей десять троггов из племени Камнедробов и десять разведчиков из племени Камнедробов и возвращайся.", female = "Мы должны защитить озеро Лок! Множество королевских солдат проливает кровь в далёких землях, а наш родной край в опасности. Трогги полезли изо-всех щелей! Нашествие троггов грозит безопасности Стальгорна. Пора истребить мерзких мутантов! Нам нужна твоя помощь, отважная искательница приключений. Ступай и устрани нависшую над нами угрозу. Убей десять троггов из племени Камнедробов и десять разведчиков из племени Камнедробов и возвращайся." },
    ["224c"] = { male = "Молодчина! Ты проявил немалое мужество на поле боя. Побольше таких, как ты, и мы победим троггов. Ты славно послужил королю Магни. Если тебе по нраву такие свершения, поговори с горным пехотинцем Булыжным Карьером. Капитан дал ему непростое задание. Уверен, ему понадобится помощь. Поговори с Булыжным Карьером, он сейчас в башне.", female = "Молодчина! Ты проявила немалое мужество на поле боя. Побольше таких, как ты, и мы победим троггов. Ты славно послужила королю Магни. Если тебе по нраву такие свершения, поговори с горным пехотинцем Булыжным Карьером. Капитан дал ему непростое задание. Уверен, ему понадобится помощь. Поговори с Булыжным Карьером, он сейчас в башне." },
    ["225a"] = { common = "Надпись на древнем могильном камне гласит: МОРГАН ЛАДИМОР *При внимательном рассмотрении вы замечаете, что могилу недавно раскапывали, и большая часть земли насыпана заново...*" },
    ["225c"] = { common = "Морган Ладимор? А-а-а, да, разумеется. У него долгая и печальная история. Я знал его до того, как он ушёл на войну, но с тех пор ни разу не видел. Он был добрым и благородным человеком, но окончил свою жизнь плохо. Подожди-ка, я дам тебе вещь, которая поведает его историю лучше, чем я..." },
    ["226a"] = { common = "Нас со Свеном ждут трудные времена, учитывая, что на востоке поселился Некромант. Мы здесь совсем одни, приходится самим добывать себе еду. Такое впечатление, что всякий раз, как я возвращаюсь в лагерь, неся добычу, за мной увязывываются лютые волки. Что и говорить, жить здесь опасно! Но если ты избавишь нас хотя бы от части волков, нам станет полегче. Они живут на севере и на востоке отсюда, возле реки." },
    ["226c"] = { male = "О, хорошо. Ты здорово проредил волчью стаю, и если хищники перестанут нас преследовать, мы сможем заняться Морбентом Скверном. Вот, возьми в награду взрывпакеты. Их делают в городе, и Свену недавно выделили целую партию.", female = "О, хорошо. Ты здорово проредила волчью стаю, и если хищники перестанут нас преследовать, мы сможем заняться Морбентом Скверном. Вот, возьми в награду взрывпакеты. Их делают в городе, и Свену недавно выделили целую партию." },
    ["227a"] = { common = "*Он роется на полках и вытаскивает книгу в кожаном переплёте.* Если хочешь узнать побольше, спроси Альтею, она занималась... проблемами... возникшими с ним в последнее время." },
    ["227c"] = { male = "Морган Ладимор? Никогда о нём не слышала... А, ты о Мор'Ладиме! Ты не знаешь его историю? Что ж, я объясню тебе вкратце. По Сумеречному лесу бродит неупокоенный мертвец, зовущий себя Мор'Ладимом. Судя по всему, это восставшее из могилы тело Моргана Ладимора, о котором ты, кажется, уже слышал. Он доставил нам массу неприятностей – начиная от нападения на патрульных и заканчивая убийствами простых людей. Она смеривает вас взглядом. Кажется, ты смог бы помочь ему упокоиться с миром.", female = "Морган Ладимор? Никогда о нём не слышала... А, ты о Мор'Ладиме! Ты не знаешь его историю? Что ж, я объясню тебе вкратце. По Сумеречному лесу бродит неупокоенный мертвец, зовущий себя Мор'Ладимом. Судя по всему, это восставшее из могилы тело Моргана Ладимора, о котором ты, кажется, уже слышала. Он доставил нам массу неприятностей – начиная от нападения на патрульных и заканчивая убийствами простых людей. Она смеривает вас взглядом. Кажется, ты смогла бы помочь ему упокоиться с миром." },
    ["228a"] = { common = "Разведчики сообщают, что Мор'Ладим бродит по кладбищу. Мы похоронили его за домом на холме, знаешь, где это? Больше я тебе ничем помочь не могу... Разве что пожелать удачи." },
    ["228c"] = { male = "Ты убил его? Это великий подвиг! Прими благодарность от имени народа Темнолесья и Ночного дозора. Ах, да... Осталось ещё одно дело...", female = "Ты убила его? Это великий подвиг! Прими благодарность от имени народа Темнолесья и Ночного дозора. Ах, да... Осталось ещё одно дело..." },
    ["229a"] = { common = "Надо было предупредить тебя раньше… Как бы тебе сказать… Морган думал, что у него погибла вся семья, но его дочь, Сара Ладимор, жива и служит в Ночном дозоре. Её всегда беспокоили... обстоятельства... связанные с гибелью её отца. Быть может, ты сообщишь ей о случившемся." },
    ["229c"] = { common = "Да? Мой отец… Она опускает глаза. Жаль... что я не могу ничего для него сделать... Ах, если бы я поговорила с ним до того, как..." },
    ["230a"] = { common = "Порывшись в груде земли, вы находите небольшую книгу, перепачканную грязью. На ней нет заглавия, зато в ней содержатся сведения, необходимые Свену." },
    ["230c"] = { common = "Свен прочитывает несколько страниц и захлопывает книгу. Этот таинственный незнакомец – свидетель смерти моей семьи! У меня столько вопросов к этому человеку... Узнать бы, кто он!" },
    ["231a"] = { common = "Возьми это кольцо и отнеси на его могилу. Может быть... может быть, он поймёт, что я жива и никто не винит его в случившемся. *Со слезами на глазах она снимает кольцо с правой руки и отдаёт вам.* И... спасибо." },
    ["231c"] = { male = "В шорохе ветра слышится призрачный голос... Что это?.. Сара? Неужели она жива? Камень с сердца… путник. Возьми мой меч, Принцип. Моя душа упокоилась, и он более мне не нужен. Он был выкован во имя добра, а я оказался не достоин владеть им. Быть может, ты сможешь нести Свет вместо меня. Лиз, любовь моя...", female = "В шорохе ветра слышится призрачный голос... Что это?.. Сара? Неужели она жива? Камень с сердца… путница. Возьми мой меч, Принцип. Моя душа упокоилась, и он более мне не нужен. Он был выкован во имя добра, а я оказался не достоин владеть им. Быть может, ты сможешь нести Свет вместо меня. Лиз, любовь моя..." },
    ["232a"] = { common = "Королевскому фармацевтическому обществу нужна твоя помощь. Слушай внимательно, поскольку, если мой план удастся, мы оба окажемся в выгодном положении. Согласна, аптекарь Чанн... немного тронутый... но его исследования приносят свои плоды, если попадают в руки к умному человеку. К счастью, я как раз из таких. Отнеси этот заказ Алессандро Лусе, хозяину \"Тысячи мелочей Синей Луны\", он даст тебе набор для полевых испытаний. Принеси его мне, и я расскажу тебе подробнее о задании." },
    ["232c"] = { common = "А, так Зинг нужен набор для полевых испытаний? Жаль, что она не решилась осчастливить меня своим визитом. Ладно, сейчас я подготовлю набор." },
    ["233a"] = { male = "Не думаю, что ты горишь желанием мне помочь, парень, но у меня тут целая куча писем, а времени на доставку нет. Это всё для Талина Остроглаза. Его лагерь – у замёрзшего озера, к западу отсюда. Ну что, может, доставишь ему почту?", female = "Не думаю, что ты горишь желанием мне помочь, красотка, но у меня тут целая куча писем, а времени на доставку нет. Это всё для Талина Остроглаза. Его лагерь – у замёрзшего озера, к западу отсюда. Ну что, может, доставишь ему почту?" },
    ["233c"] = { common = "Благодарю тебя, я уже давно ждал этих писем... Конечно, они не все для меня. Вот это, скажем, для Грелина Белоборода. Он тут неподалёку живёт, может, зайдёшь к нему?" },
    ["234a"] = { common = "Если мне память не изменяет, лагерь Грелина находится дальше по дороге, на юго-восток отсюда. Не сомневаюсь, он будет рад этому посланию." },
    ["234c"] = { common = "Здорово! Я уже давно не получал весточки из Стальгорна." },
    ["235a"] = { common = "Внимание, молодые герои! Вас ждут дикие чащи Ясеневого леса! Орде удалось закрепиться в землях к северу от Степей. И два наших форпоста – застава Расщеплённого Древа и застава Зорамского взморья – бьются во славу Орды! Те, кто жаждет подвигов, могут отправиться туда. Запомните: Сенани Громосерд находится на заставе Расщеплённого Древа, к северу от Степей. Она ждёт желающих принять участие в большой охоте!" },
    ["235c"] = { male = "Добро пожаловать на новое пограничье. Ясеневый лес – край неограниченных возможностей, где юному герою вроде тебя выпадает шанс показать себя. Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть. Как понимаю, ты здесь для того, чтобы побольше узнать об охоте. Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать.", female = "Добро пожаловать на новое пограничье. Ясеневый лес – край неограниченных возможностей, где юному героине вроде тебя выпадает шанс показать себя. Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть. Как понимаю, ты здесь для того, чтобы побольше узнать об охоте. Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать." },
    ["237a"] = { male = "Горный пехотинец Кремневик превозносит тебя до небес, герой. Поэтому я хочу доверить тебе очень важное задание. Мы не должны ослаблять натиск на троггов, пока наши братья-дворфы не вернутся с войны. Отправляйся в южные холмы и убей десять головоломов из племени Камнедробов и десять ясновидцев из племени Камнедробов. Это поможет нам выиграть время. Когда выполнишь задание, возвращайся.", female = "Горный пехотинец Кремневик превозносит тебя до небес, героиня. Поэтому я хочу доверить тебе очень важное задание. Мы не должны ослаблять натиск на троггов, пока наши братья-дворфы не вернутся с войны. Отправляйся в южные холмы и убей десять головоломов из племени Камнедробов и десять ясновидцев из племени Камнедробов. Это поможет нам выиграть время. Когда выполнишь задание, возвращайся." },
    ["237c"] = { male = "Ты прекрасно справился с заданием, герой! Сам король может гордиться тобой. К сожалению, обещанное подкрепление так и не подошло. Фронт обагрен кровью воинов Альянса. Вести о потерях наполняют горечью моё сердце... Так пусть же эти жертвы будут не напрасны! Мы должны с честью выдержать невзгоды и вернуть Альянсу былую славу. Поговори с горным пехотинцем Стеноломом, он даст тебе новое задание. Ты нужен нам как никогда.", female = "Ты прекрасно справилась с заданием, героиня! Сам король может гордиться тобой. К сожалению, обещанное подкрепление так и не подошло. Фронт обагрен кровью воинов Альянса. Вести о потерях наполняют горечью моё сердце... Так пусть же эти жертвы будут не напрасны! Мы должны с честью выдержать невзгоды и вернуть Альянсу былую славу. Поговори с горным пехотинцем Стеноломом, он даст тебе новое задание. Ты нужна нам как никогда." },
    ["238a"] = { common = "Я подготовил набор. Не сомневаюсь, аптекарю Зинг не терпится его получить. Отнеси посылку как можно скорее и сообщи ей, что я запишу стоимость набора на счёт Общества. Кроме того, передай ей мой пламенный привет. Ну же, не стой как истукан. Простым курьерам не ведом отдых, а?" },
    ["238c"] = { common = "Хорошо – приятно работать с теми, кто старается не тратить моё время попусту. Когда я закончу с набором, ты сможешь двинуться в путь. Набор пригодится для сбора необходимых данных. Я попытаюсь закончить побыстрее. А пока ждёшь, можешь обдумать, что возьмёшь с собой в пустыню. Да, именно в пустыню." },
    ["239a"] = { common = "Гарнизон западной границы докладывает об усилении активности гноллов и грабителей. Они просят, чтобы мы прислали подкрепление из Штормграда... Но у нас не хватает людей! Твоя помощь не была бы лишней. Поговори с заместителем судьи Рейнером: он сейчас находится в гарнизоне у Западного ручья. Рейнер скажет тебе, что делать. Гарнизон расположен к западу отсюда: иди по дороге, а потом, когда перейдёшь через речушку по мосту, сверни направо." },
    ["239c"] = { common = "Тебя что, маршал Дугхан сюда послал? Ну... Ты, конечно, не солдат, но маршалу я доверяю. У нас тут сложилась, скажем так, напряжённая ситуация. Надеюсь, ты сумеешь нам помочь." },
    ["240a"] = { common = "А вот и пирожки с \"крабами\" а-ля Груал!" },
    ["240c"] = { common = "Ага! Спасибо. Как раз то, что нужно. А вот и твоя плата за услугу!" },
    ["243a"] = { common = "Ты отправишься в пустыню Танарис изучать состав тканей василисков, скорпидов и гиен. Добудь образцы тканей и проверь их при помощи этого набора; подозреваю, что не все окажутся удачными. Мне нужно по восемь образцов каждого вида. Кроме того, у гоблинов Прибамбасска есть источники энергии, необходимые для работы изменённого набора. Поговори с главным инженером Чепухастером и добудь у него источник энергии. Без образцов ткани можешь не возвращаться." },
    ["243c"] = { male = "А, наши источники энергии четыре тысячи семьсот одиннадцать-ФТЗ! Обычно мы пользуемся ими для электрификации колодцев, но БЛАГОДАРЯ ПРОКЛЯТЫМ КОЧЕВНИКАМ энергии у нас в избытке. Не вопрос, я могу добыть тебе источник энергии, для каких бы гнусных научных целей он тебе ни понадобился. А, думаешь, я ни о чём не догадался? Как бы не так. Но это тебе дорого обойдётся, герой. В Прибамбасске ничто не достаётся даром.", female = "А, наши источники энергии четыре тысячи семьсот одиннадцать-ФТЗ! Обычно мы пользуемся ими для электрификации колодцев, но БЛАГОДАРЯ ПРОКЛЯТЫМ КОЧЕВНИКАМ энергии у нас в избытке. Не вопрос, я могу добыть тебе источник энергии, для каких бы гнусных научных целей он тебе ни понадобился. А, думаешь, я ни о чём не догадался? Как бы не так. Но это тебе дорого обойдётся, героиня. В Прибамбасске ничто не достаётся даром." },
    ["244a"] = { male = "Привет тебе, герой. Мне приказано охранять этот участок дороги. Хотя сейчас здесь безопасно, к северу и к востоку отсюда я видел лагеря гноллов. В Приозерье должны узнать о том, что гноллы собирают армию! Сообщи об этом заместителю судьи Фелдону. Уверен, он заплатит тебе за принесённые вести. Фелдон обычно обходит территорию к югу от моста по дороге в Приозерье.", female = "Привет тебе, героиня. Мне приказано охранять этот участок дороги. Хотя сейчас здесь безопасно, к северу и к востоку отсюда я видел лагеря гноллов. В Приозерье должны узнать о том, что гноллы собирают армию! Сообщи об этом заместителю судьи Фелдону. Уверен, он заплатит тебе за принесённые вести. Фелдон обычно обходит территорию к югу от моста по дороге в Приозерье." },
    ["244c"] = { common = "К Элвиннскому лесу подбираются гноллы Красногорья? Похоже, скоро они доберутся и до наших земель. И тогда не только Приозерье окажется в осаде! Возьми плату за вести, хоть они и скверные. И время сейчас неподходящее, ведь мы ничего не сможем противопоставить новой угрозе." },
    ["245a"] = { male = "Привет тебе, герой. Наверное, ты видел пауков на западной границе? Эти восьминогие чудища нам не по зубам, а командир не может отпустить солдат так далеко от Темнолесья. Мне неловко просить тебя о помощи, но, кажется, тебе удалось бы с ними разобраться. Не могу обещать тебе большую награду, но одарю, чем смогу, если ты поможешь извести этих гадов. Мой тебе совет: остерегайся их яда.", female = "Привет тебе, героиня. Наверное, ты видела пауков на западной границе? Эти восьминогие чудища нам не по зубам, а командир не может отпустить солдат так далеко от Темнолесья. Мне неловко просить тебя о помощи, но, кажется, тебе удалось бы с ними разобраться. Не могу обещать тебе большую награду, но одарю, чем смогу, если ты поможешь извести этих гадов. Мой тебе совет: остерегайся их яда." },
    ["245c"] = { common = "А! Ты вернулся. И на первый взгляд – в целости и сохранности. Разумеется, Ночной дозор весьма тебе признателен. Я обещал вознаградить тебя, и обещание своё выполняю. Держи." },
    ["246a"] = { common = "У нас нет лишних людей, но с гноллами, о которых ты говоришь, надо что-то делать. Поищи их в южной части Красногорья. Убей, кого сможешь, и сообщи мне об их общем числе и степени угрозы, которую они представляют для города. Гноллы стоят лагерем вдоль южной дороги. Сделай это ради армии Штормграда, и получишь награду." },
    ["246c"] = { male = "Заместитель судьи Фелдон слушает ваш отчёт. Значит, там собралось немало гноллов, и, судя по всему, они весьма сильны. Должно быть, тебе нелегко было собрать эти сведения. Что ж, мы благодарим тебя за помощь. Если ты ещё не беседовал с маршалом Маррисом и мировым судьёй Соломоном, непременно обратись к ним. Дела у нас идут всё хуже; не сомневаюсь, эти двое найдут тебе работу.", female = "Заместитель судьи Фелдон слушает ваш отчёт. Значит, там собралось немало гноллов, и, судя по всему, они весьма сильны. Должно быть, тебе нелегко было собрать эти сведения. Что ж, мы благодарим тебя за помощь. Если ты ещё не беседовала с маршалом Маррисом и мировым судьёй Соломоном, непременно обратись к ним. Дела у нас идут всё хуже; не сомневаюсь, эти двое найдут тебе работу." },
    ["247c"] = { common = "Путник, тебе удалось убить всех трёх зверей, которые наводили страх на Ясеневый Лес. Ты принёс мне надлежащие доказательства их смерти, нет никаких сомнений в твоей силе и упорстве. Кровь охотника течёт по твоим венам, и ты заслуживаешь похвалы! Пожалуйста, прими это в знак поздравления совершенных деяний в Ясеневом лесу. Пусть твои предки оберегают тебя!" },
    ["248a"] = { common = "Я наблюдал за башней Илгалара и понял, что Моргант враждует с орками крепости Каменной Стражи. Не знаю, что за этим кроется, но ты можешь помочь мне приоткрыть завесу тайны. Возьми ещё один амулет Азоры и отнеси его на вершину уцелевшей башни рядом с крепостью. Отыщи подходящее место для амулета и спрячь его там. Для этой цели прекрасно подойдёт сундук или кувшин." },
    ["248c"] = { common = "Это подходящий сосуд для амулета Азоры. Он позволит Теокриту проникнуть в помыслы обитателей крепости Каменной Стражи." },
    ["249a"] = { male = "Ценой долгих усилий я раскрыл планы Морганта. Он ищет Косу Элуны... и быть может, уже отыскал её! Коли так, то скоро Красногорье, а следом и всё королевство Штормграда почувствует его тёмную мощь. Я не готов выступить против Морганта, но, боюсь, терять время нельзя. Ты должен войти в башню Илгалара и бросить ему вызов. Одолей злодея, принеси мне его подвеску Тени, и королевство тебя не забудет.", female = "Ценой долгих усилий я раскрыл планы Морганта. Он ищет Косу Элуны... и быть может, уже отыскал её! Коли так, то скоро Красногорье, а следом и всё королевство Штормграда почувствует его тёмную мощь. Я не готов выступить против Морганта, но, боюсь, терять время нельзя. Ты должна войти в башню Илгалара и бросить ему вызов. Одолей злодея, принеси мне его подвеску Тени, и королевство тебя не забудет." },
    ["249c"] = { male = "Ты сделал великое дело. Чернокнижник Моргант повержен, и Штормград избавлен от великой опасности. Смиренно прошу принять эту награду. Я пожелал бы тебе мира, выпади нам жить в мирные времена. Вместо этого желаю удачи в ожидающих тебя испытаниях и победы в предстоящих боях.", female = "Ты сделала великое дело. Чернокнижник Моргант повержен, и Штормград избавлен от великой опасности. Смиренно прошу принять эту награду. Я пожелал бы тебе мира, выпади нам жить в мирные времена. Вместо этого желаю удачи в ожидающих тебя испытаниях и победы в предстоящих боях." },
    ["250a"] = { male = "Хвала небесам, что хоть кого-то волнует наша дамба. Будто мало нам разрушенного моста Тандола и разграбленного Дун Модра! Не сомневаюсь, следующей целью Чёрного Железа станет именно Дамба. Большую часть охраны отослали биться за Альянс, в том числе моего старшего инспектора. Потому-то ты мне и нужен. Я заметил сапёров из клана Чёрного железа неподалёку от восточной части дамбы. Разведай обстановку и возвращайся с уликами.", female = "Хвала небесам, что хоть кого-то волнует наша дамба. Будто мало нам разрушенного моста Тандола и разграбленного Дун Модра! Не сомневаюсь, следующей целью Чёрного Железа станет именно Дамба. Большую часть охраны отослали биться за Альянс, в том числе моего старшего инспектора. Потому-то ты мне и нужна. Я заметил сапёров из клана Чёрного железа неподалёку от восточной части дамбы. Разведай обстановку и возвращайся с уликами." },
    ["250c"] = { common = "В подозрительной бочке содержится странно пахнущий порошок." },
    ["251a"] = { common = "Отнесите записку Шире Фон-Инди. Он знает множество языков и не чужд древним искусствам – если кто и может перевести это послание, то это он." },
    ["251c"] = { common = "Шира принимается за перевод записки..." },
    ["252a"] = { common = "О небо! Если то, о чём сказано в этой записке – правда, то Аберкромби сделал нечто... невообразимое. Отнеси-ка переведённую записку Элло. И поторопись, поскольку я боюсь, что это чудовище уже ковыляет к городу..." },
    ["252c"] = { male = "Элло читает письмо... и бледнеет на глазах. Затем он поднимает на вас взгляд. Хотя ты помогал Аберкромби по доброте душевной, именно ты обрёк наш город на гибель. Элло погружается в раздумья...", female = "Элло читает письмо... и бледнеет на глазах. Затем он поднимает на вас взгляд. Хотя ты помогала Аберкромби по доброте душевной, именно ты обрекла наш город на гибель. Элло погружается в раздумья..." },
    ["253a"] = { common = "Бальзамировщиком в наших краях давно пугают детей. Когда-то он был добрым алхимиком, но смерть любимой жены Элизы лишила его рассудка. Чтобы вернуть её к жизни, он прибег к тёмной магии и даже вложил в грудь мёртвой супруги собственное сердце. Это оживило Элизу... но её сразило проклятие – она возжелала человеческой плоти, и Бальзамировщику пришлось закопать её обратно. Всё его могущество заключено в сердце. Отыщи могилу Элизы, извлеки из неё сердце и принеси его мне, пока оно бьётся. Если тебе удастся выполнить это, то сила Бальзамировщика иссякнет." },
    ["253c"] = { common = "Получилось! Магия этого сердца защитит нас от зла Бальзамировщика и послужит могущественным талисманом Темнолесью. Ты совершил подвиг во имя нашего народа. Мы тебя не забудем." },
    ["255a"] = { male = "Пройдёт два месяца, прежде чем из Стальгорна к нам на подмогу направят горстку солдат, да ещё два месяца они будут до нас добираться! И мало того, что наш город остался без защиты, но раскоп и дамба – дамба! – тоже в опасности. Похоже, у меня нет выбора. Придётся искать наёмников. Как насчёт тебя? На первый взгляд ты подходишь, герой. На северном берегу озера разбила лагерь группа огров. Может быть, ты избавишь наш город от опасности?", female = "Пройдёт два месяца, прежде чем из Стальгорна к нам на подмогу направят горстку солдат, да ещё два месяца они будут до нас добираться! И мало того, что наш город остался без защиты, но раскоп и дамба – дамба! – тоже в опасности. Похоже, у меня нет выбора. Придётся искать наёмников. Как насчёт тебя? На первый взгляд ты подходишь, героиня. На северном берегу озера разбила лагерь группа огров. Может быть, ты избавишь наш город от опасности?" },
    ["255c"] = { common = "Прекрасные новости! Я и народ Телсамара глубоко признательны тебе. Ведь если нам удастся разобраться с ограми, мы сможем заняться троггами." },
    ["256a"] = { common = "По приказу магистрата Телсамара: Чок-сул, обвиняемый в организации нападений на город Телсамар, Каменную дамбу и раскоп, приговаривается к смерти любым из возможных способов. Вознаграждение получит тот, кто предоставит в Магистрат доказательства смерти Чок-сула. В последний раз обвиняемого видели в лагере огров в северо-восточной части озера Лок Модан." },
    ["256c"] = { male = "Ой! Что это? И зачем ты притащил её… Боги!.. Это она? Ну, разрази меня гром, неужели это голова проклятого огра? Вот это улов! Что ж, награда и благодарность от имени всего народа Телсамара достаются тебе по праву!", female = "Ой! Что это? И зачем ты притащила её… Боги!.. Это она? Ну, разрази меня гром, неужели это голова проклятого огра? Вот это улов! Что ж, награда и благодарность от имени всего народа Телсамара достаются тебе по праву!" },
    ["257a"] = { common = "Думаешь тягаться с Дэрилом Смелым? Не советую! Разумеется, отговаривать тебя я не буду. Вот испытание, которое тебе явно не по силам. Не огорчайся, если ничего не выйдет. Неподалёку от озера Лок Модан свила гнёзда стая канюков. Почему бы не подстрелить несколько тварей? Знаешь что, если ты справишься с моим заданием за пятнадцать минут, я отдам тебе свой лук или ружьё. *Он с презрением осматривает вас.* Всё равно тебе нечего терять." },
    ["257c"] = { common = "Что? Получилось?! Послушай добрый совет, пусть успех не кружит тебе голову. Я хочу сказать, любой безусый паренёк с луком справился бы с такими... небольшими существами. Надеюсь, тебе не слишком нравится убивать канюков, м-м-м? Не хотелось бы, чтобы они стали исчезающим видом. Что ж, э-э-э... Пусть не говорят, что Дэрил Смелый не держит своё слово." },
    ["258a"] = { male = "путник Батькович, да? Вижу, ты лопаешься от гордости за выполненное задание, а? Я же говорил, что это легко. А вот попробуй поохотиться на кабанов. Верь мне, это тебе не поросята из Холодной долины, с ними надо поосторожнее. На сей раз даю тебе двенадцать минут. Не расстраивайся, если ничего не выйдет. Я тебе рубаху с собственного плеча отдам, если ты справишься! Я не рассказывал, как получил свой знаменитый шрам? Нет? Это было два года назад...", female = "путница Батьковна, да? Вижу, ты лопаешься от гордости за выполненное задание, а? Я же говорил, что это легко. А вот попробуй поохотиться на кабанов. Верь мне, это тебе не поросята из Холодной долины, с ними надо поосторожнее. На сей раз даю тебе двенадцать минут. Не расстраивайся, если ничего не выйдет. Я тебе рубаху с собственного плеча отдам, если ты справишься! Я не рассказывал, как получил свой знаменитый шрам? Нет? Это было два года назад..." },
    ["258c"] = { male = "Похоже, тебе несладко пришлось. Видно, кабаны задали тебе изрядную трёпку, да? Не беспокойся, я никому не расскажу о твоём поражении. Тебе и без досужих болтунов тяжело. О! Ты умудрился убить кабанов? Я... что ж... хочу сказать, ничего удивительного! Любой ребёнок смог бы... Обещание? Какое ещё обещание?", female = "Похоже, тебе несладко пришлось. Видно, кабаны задали тебе изрядную трёпку, да? Не беспокойся, я никому не расскажу о твоём поражении. Тебе и без досужих болтунов тяжело. О! Ты умудрилась убить кабанов? Я... что ж... хочу сказать, ничего удивительного! Любой ребёнок смог бы... Обещание? Какое ещё обещание?" },
    ["261a"] = { common = "Буду откровенен. Мы ведём войну с нечистью. Это зло, уничтожающее наш народ и оскверняющее нашу землю. Нежить нужно остановить, пока это возможно, иначе весь мир погрузится во мрак. Мы поклялись сражаться до последней капли крови, не щадя ни жизни, ни души. Ты с нами? Тогда яви своё мужество и докажи свою доблесть: убей опустошителей-отрёкшихся, бродящих по Пустошам на юге, в Долине Костей. Сделай это, и братство Алого ордена примет тебя." },
    ["261c"] = { common = "Тебе удалось доказать свою решимость. Братство Алого ордена благодарит тебя. Если тебя не страшит то, что ради правого дела приходится убивать, причём часто и много, тогда тебе с нами по пути." },
    ["262a"] = { male = "Я должен узнать, кто таился в тени в ту ночь, когда была убита моя семья! Прошу тебя, помоги мне. Ты не раз творил настоящие чудеса. Выясни, кто это был. Мне нужно узнать его тайны! Я рассказал тебе всё, что мог, но возьми эту книгу, обнаруженную на ферме. Может быть, кто-то в городе опознает её, и мы выясним имя владельца?", female = "Я должен узнать, кто таился в тени в ту ночь, когда была убита моя семья! Прошу тебя, помоги мне. Ты не раз творила настоящие чудеса. Выясни, кто это был. Мне нужно узнать его тайны! Я рассказал тебе всё, что мог, но возьми эту книгу, обнаруженную на ферме. Может быть, кто-то в городе опознает её, и мы выясним имя владельца?" },
    ["262c"] = { common = "Хмм... Кто-то совсем недавно держал эту книгу в руках. Этот человек одержим жаждой мести. Но увы, следы на ней, по крайней мере следы первого владельца, едва различимы. Я могу сказать одно: он не из Темнолесья." },
    ["263a"] = { male = "Горные пехотинцы уверяют, что ты силён и отважен. Нам нужен путник вроде тебя. Мы никак не можем справиться с троггами. Всех бойцов отозвали на фронт, и мы остались без защиты. Но раз среди нас появился закалённый в боях герой, то может быть, нам удастся выстоять. Убей десять шаманов из племени Камнедробов и десять костегрызов из племени Камнедробов. Посмотрим, не преувеличены ли слухи о твоей доблести, о Гроза троггов.", female = "Горные пехотинцы уверяют, что ты сильна и отважна. Нам нужна путница вроде тебя. Мы никак не можем справиться с троггами. Всех бойцов отозвали на фронт, и мы остались без защиты. Но раз среди нас появилась закалённая в боях героиня, то может быть, нам удастся выстоять. Убей десять шаманов из племени Камнедробов и десять костегрызов из племени Камнедробов. Посмотрим, не преувеличены ли слухи о твоей доблести, о Гроза троггов." },
    ["263c"] = { male = "Я сразу понял, что Стальгорн будет тобой гордиться. Ты славно послужил королю Магни. Теперь, доказав, что ты верный защитник Королевства, можешь поговорить с капитаном. Может быть, он посвятит тебя в наши более насущные проблемы. Хвала тебе.", female = "Я сразу понял, что Стальгорн будет тобой гордиться. Ты славно послужила королю Магни. Теперь, доказав, что ты верная защитница Королевства, можешь поговорить с капитаном. Может быть, он посвятит тебя в наши более насущные проблемы. Хвала тебе." },
    ["264a"] = { common = "Гад такой! Бросил меня ради своего клятого похода! Понимаете ли, \"Свет превыше всего, ибо он единственная наша защита от нежити!\" А как же дети?! А я?! Много ночей я терпеливо ждала его... я всегда была второй после его чёртового долга! И посмотрите, теперь на плоды борьбы за \"справедливость\"! Он мёртв, а на меня обрушилось всё то, чему он пытался помешать! Возьмите этот хлам и положите на его могилу в Гробнице. Мне не нужен больше этот мусор... и он сам тоже!" },
    ["264c"] = { common = "Вы кладёте дешёвую безделушку на могилу, и драгоценный камень в ней заметно тускнеет. Когда вы поднимаетесь, чтобы уйти, вы смотрите на подвеску – она лежит, тусклая и мёртвая, в руках вырезанного на надгробной плите изображения. Ваши мысли прерывает порыв холодного ветра, пронёсшегося по Гробнице. На мгновение всё вокруг вас замирает." },
    ["265a"] = { common = "Вот твоя книга, желаю удачи в расследовании. Если ты расспросишь других горожан, они могут рассказать тебе что-нибудь ценное. Я же скажу одно: хотя автор этой книги не из нашего города, тетрадь для неё он купил здесь." },
    ["265c"] = { common = "Ах, да. Я продал эту тетрадь одному сомнительному типу. Он не представился, но явно нервничал, дёргался, то и дело оглядывался через плечо. Надеюсь, что смог тебе помочь..." },
    ["266a"] = { common = "Вот твоя книга, желаю удачи в расследовании. Советую заглянуть в таверну. Если человек, о котором ты говоришь, останавливался у нас в городе, скорее всего его кто-то видел." },
    ["266c"] = { common = "Ах да, эту книгу я помню. Её владелец снимал комнату на несколько дней и вечерами засиживался в баре, всё писал. Город он покинул в спешке, бормоча под нос, что его преследует... что-то. В последний раз я видел его на дороге, ведущей на запад. Кажется, он собирался искать новое укрытие. Первое, что ему встретится на западе, – это Вороний холм..." },
    ["267a"] = { male = "герой, не знаю, слышал ли ты о новой угрозе, нависшей над землями дворфов. Внутренние войска отправили на фронт, на охране осталась лишь горстка воинов. Мой полк приставлен к Вратам, и я не могу отойти от них, поскольку мы опасаемся вторжения врагов. И всё же необходимо усилить натиск на троггов, заселивших холмы. Если это задание тебе по плечу, проведи вылазку в их стан. Принеси в доказательство своих свершений восемь каменных зубов троггов.", female = "героиня, не знаю, слышала ли ты о новой угрозе, нависшей над землями дворфов. Внутренние войска отправили на фронт, на охране осталась лишь горстка воинов. Мой полк приставлен к Вратам, и я не могу отойти от них, поскольку мы опасаемся вторжения врагов. И всё же необходимо усилить натиск на троггов, заселивших холмы. Если это задание тебе по плечу, проведи вылазку в их стан. Принеси в доказательство своих свершений восемь каменных зубов троггов." },
    ["267c"] = { male = "Отличная работа. Ты оказал всем дворфам великую услугу, защищая наши земли. Сам король Магни Бронзобород может гордиться тобой!", female = "Отличная работа. Ты оказала всем дворфам великую услугу, защищая наши земли. Сам король Магни Бронзобород может гордиться тобой!" },
    ["268a"] = { common = "Я лишь наполовину успел закончить книгу, найденную тобой. Мне пришлось оставить её на ферме Свена во время поспешного бегства… Вот. Отнеси Свену все мои записи. Здесь подробно рассказывается о случившемся на ферме. Хотя единственным моим сокровищем в последние несколько недель были только эти записи, я охотно расстанусь с ними, лишь бы не вставать на пути Свена!" },
    ["268c"] = { common = "Записи многое проясняют. Теперь мне ясно, что следует искать тёмных всадников! Я встречал их в Сумеречном лесу и видел, как они говорят с чародеем Морбентом Скверном у Покинутой усадьбы." },
    ["269a"] = { common = "Отправляйся в Штормград и поговори с епископом Фартингом в Соборе Света. Отдай ему записи Трясунчика и сообщи, что собираешься бросить вызов Морбенту Скверну. Хоть Штормград и бросил Темнолесье на произвол судьбы, Фартинг – добрая душа и мудрый человек. Он поможет тебе спасти нас. Тебя ждёт много опасностей... Однако поспеши. С каждым часом в Сумеречном лесу сгущается тьма." },
    ["269c"] = { common = "Епископ изучает записи... Зло нашло лазейку в и без того обложенный со всех сторон Сумеречный лес. Хвала Свету, что отыскался герой вроде тебя. Но прежде чем смело двинуться навстречу испытаниям, тебе следует хорошо подготовиться... Некромант Морбент Скверн всегда был необычайно силён, а чтобы стать неуязвимым, наложил на себя могучие чары. Тебе не одолеть его без оружия, способного пробиться сквозь эти преграды." },
    ["270a"] = { common = "Много лет назад Третья флотилия Кул-Тираса затонула у берегов Болотины, огромной топи к северу от дворфийского королевства Стальгорна. Одно из судов было нагружено светлой сталью. Этот металл представляет для нас большую ценность, поскольку изготовленное из него оружие и доспехи разят врагов силой святой истины. Если вы собираетесь противостоять Морбенту Скверну, вам именно такое оружие и понадобится. Отправляйтесь в Гавань Менетилов и переговорите с моим коллегой-дворфом по имени Глорин Стальной Лоб. Если утерянный груз ещё можно найти – он сообразит, где нужно искать." },
    ["270c"] = { male = "Светлая сталь – и впрямь драгоценный металл, но всё говорит за то, что задание у тебя не из лёгких. Ты проделал длинный путь, братишка. Если тебе сильно повезёт, ты можешь найти то, что ищешь. А если раздобудешь металл – я знаю, кто сможет выковать подходящее оружие против того некроманта в Сумеречном лесу, о котором ты говоришь.", female = "Светлая сталь – и впрямь драгоценный металл, но всё говорит за то, что задание у тебя не из лёгких. Ты проделала длинный путь, сестрёнка. Если тебе сильно повезёт, ты можешь найти то, что ищешь. А если раздобудешь металл – я знаю, кто сможет выковать подходящее оружие против того некроманта в Сумеречном лесу, о котором ты говоришь." },
    ["271a"] = { common = "Не хочешь отплатить Его Смелости? Вынуждена признать, что Дэрил в самом деле многое умеет. Год назад весь Приют странников охотился на огромного медведя, но ни одному смельчаку не посчастливилось его одолеть. Тогда Дэрил решил выступить против зверя сам. Разумеется, он ничего не добился, да ещё и получил этот уродливый шрам над глазом. Убей медведя, и не сомневаюсь, что даже Дэрил ненадолго лишится дара речи. Старину Черношкура можно отыскать в логове в холмах над Телсамаром." },
    ["271c"] = { common = "Э... что это? Судя по всему, медвежья голова. Он невольно проводит пальцем по старому шраму. Что ж, интересная добыча. Не тот ли самый медведь... Он умолкает и начинает заметно дрожать. О, скорее убери её! Убери отсюда эту страшную штуку!" },
    ["272a"] = { common = "Вот твоё второе испытание – тебе понадобятся две половинки подвески Морского Льва. Одна половинка черпает мощь из ловкости аспекта морского льва, скользящего в бездне вод, вторая черпает силу из невероятной выносливости аспекта морского льва. Друидов привлекают обе эти черты, олицетворяющие аспект их водного облика. Поговори с жителями Лунной поляны, чтобы узнать, где могут находиться эти половинки, и принеси их, чтобы соединить. Сделав это, отнеси подвеску Дендриту Блеску Звёзд." },
    ["272c"] = { male = "Ты прошёл испытание Морского Льва. Прими мои поздравления. Каждый шаг на пути обретения этой подвески должен был показать тебе, насколько важны ловкость и выносливость в перемещениях под водой. Одно не существует без другого, и эти качества нельзя обрести без желания принять аспект морского льва. Запомни хорошенько этот урок и полагайся на него, когда научишься принимать водный облик.", female = "Ты прошла испытание Морского Льва. Прими мои поздравления. Каждый шаг на пути обретения этой подвески должен был показать тебе, насколько важны ловкость и выносливость в перемещениях под водой. Одно не существует без другого, и эти качества нельзя обрести без желания принять аспект морского льва. Запомни хорошенько этот урок и полагайся на него, когда научишься принимать водный облик." },
    ["273a"] = { common = "Ещё не поздно, ты можешь поискать Хальдора. Вряд ли он ушёл далеко; Миран и Сайан – крепкие ребята, но под грузом бочек ходят не слишком быстро. Они пошли к раскопу обычной дорогой – на юг от города, вдоль берега озера. Найти их будет несложно, если они ещё не добрались до места назначения." },
    ["273c"] = { common = "Хм, жалкой засаде Чёрного Железа не помешать мне доставить товар! Но Сайан... Никогда бы не подумал, что он сторонник этих предателей. Я с ним почти год работаю... должно быть, что-то упустил. Ладно, подумаю об этом позже." },
    ["274a"] = { common = "Это не простой взрывчатый порошок. Только взгляни на эти крошечные серебристые кристаллы. А характерный запах! Ясно, как день – это сефорий. Сам по себе он безобиден, но, намокнув, может взорвать весь Стальгорн! Химическую реакцию можно нейтрализовать, смешав четыре компонента: паучий яд, толчёный кристалл Могроша, слезу кроколиска и нейтрализующий коллоид. Расскажи об этом Плотине, пока не поздно!" },
    ["274c"] = { common = "Нейтрализующий коллоид? Для сефория? О небо!" },
    ["275a"] = { common = "Болотину лихорадит, и я не знаю почему. Трясинные ползуны набирают силу. Это болезненные, гнойные нарывы на теле земли! И чтобы исцелить её, нужно загнать трясинных ползунов обратно в болота, откуда они вылезли. Ползуны водятся у водоёмов в Болотине." },
    ["275c"] = { common = "Скоро раны на теле земли затянутся, и лихорадка спадёт. Я благодарю тебя и вручаю небольшой подарок..." },
    ["276a"] = { common = "Многие годы гноллы из стаи Мохошкуров мирно жили в Болотине, но теперь их поголовье увеличилось. Они вытаптывают наши прекрасные луга и вырубают лес на дрова! Чтобы спасти природу нашего края, придётся истребить часть гноллов. Убей пятнадцать гноллов из стаи Мохошкуров и десять полукровок из стаи Мохошкуров. Они водятся на юге, возле дворфийских Врат Альгаза. Когда справишься с заданием, вернись ко мне." },
    ["276c"] = { male = "Теперь наши земли спасены! Признаться, раньше я с недоверием относился к вашему брату... но твой подвиг, герой, заставил меня задуматься. Спасибо тебе!", female = "Теперь наши земли спасены! Признаться, раньше я с недоверием относился к вашему брату... но твой подвиг, героиня, заставил меня задуматься. Спасибо тебе!" },
    ["277a"] = { common = "Гноллы из стаи Мохошкуров вырубают деревья Болотины и жгут древесину, греясь у костров. Я этого не потерплю! Отбери у гноллов их кремни, которыми они высекают огонь. Кремни есть у всего клана, кроме мелких гноллов и полукровок из стаи Мохошкуров." },
    ["277c"] = { common = "Спасибо. Я раскрошу их в порошок и выброшу в море, и их уже никогда не используют для того, чтобы жечь живую древесную плоть." },
    ["278a"] = { common = "Немедленно принимайся за сбор материалов для нейтрализации взрывчатки. Паучий яд ты найдёшь у пауков у озера Лок Модан. Слезу кроколиска можно отыскать там же. А вот заполучить кристалл Могроша будет нелегко. Такие кристаллы добывают огры, живущие к северо-востоку отсюда, но и у огров они водятся нечасто. Мы должны разминировать творение Чёрного Железа! Как только соберёшь все материалы, сразу же возвращайся, и я подготовлю состав." },
    ["278c"] = { common = "Наконец-то!" },
    ["279a"] = { common = "Мурлоки выходят из морских глубин и строят свои поселения на побережье. Они нападают на наших рыбаков и торговцев, и это уже переходит всякие границы. Их надо остановить. Один из этих мурлоков, Жрун, придумал устраивать засады на наших купцов на дорогах. На мурлоков из племени Синежабрых нет никакой управы. Творят, что хотят, а потом прячутся в ближайших поселениях, и всё – их уже не достать. Наши торговцы в опасности, и мы готовы хорошо заплатить тому, кто возьмётся их защищать. Жрун промышляет в речном заливе к северу отсюда. Принеси мне его голову, а заодно перебей его сородичей." },
    ["279c"] = { male = "Отлично! Вот твои деньги, ты честно их заработал, выполнив все обязательства.", female = "Отлично! Вот твои деньги, ты честно их заработала, выполнив все обязательства." },
    ["280a"] = { common = "Я только сегодня видел мятежников Чёрного Железа, которые тащили к Дамбе большую бочку. И рядом со мной не было ни одного горного пехотинца, поэтому никто их не остановил! Боюсь, они заложили сефорий у основания Дамбы, и она того и гляди взлетит на воздух! Дай-ка я смешаю все компоненты. Вот, у меня получилась нейтрализующая смесь. Скорее, возьми смесь и залей её в бочку, пока не поздно. Торопись!" },
    ["280c"] = { common = "Вы вливаете нейтрализующую смесь, и из бочки доносится слабое шипение." },
    ["281a"] = { common = "Не так давно мурлоки напали на торговый корабль \"Слепая принцесса\". Корабль удалось спасти, но эти подлые твари растащили почти весь груз, в том числе и одну очень ценную вещь, статуэтку Теренаса Менетила. Её надо вернуть во что бы то ни стало. Обыщи поселение мурлоков на побережье. Ищи сундуки, ящики, бочки – всё, что может быть связано с украденным грузом. Найди статуэтку Менетила и верни её мне." },
    ["281c"] = { common = "Сундук отсырел, он весь исцарапан – это явно следы от когтей. Вы открываете сундук. Внутри – размокшая гнилая солома. Можно предположить, что здесь спрятана некая ценная вещь, требующая бережного обращения. Вы разгребаете солому... ...и находите несколько бутылок из красного стекла." },
    ["282a"] = { common = "Я собирался послать своего ученика к брату Сениру с отчётом, но парень он не слишком надёжный, а мне нужен кто-то, на кого действительно можно положиться. Ну, то есть, конечно, если ты не будешь возражать. Хм-м. Чтобы добраться до Караноса, тебе придётся пройти по тоннелю. Перед тем как зайти в тоннель, заскочи к горному пехотинцу Талосу и поговори с ним – в тоннеле полным-полно троггов. Сначала тебе нужно вернуться по дороге к Старой Наковальне, а потом направиться на восток. Рядом с тоннелем Талос и стоит – найти его будет несложно." },
    ["282c"] = { common = "Хм. Ну что ж, если Белобород послал тебя в Дун Морог по важному делу, то не мне тебя останавливать, верно? С другой стороны, пару советов-то я могу тебе дать..." },
    ["283a"] = { common = "Бочка негромко шипит." },
    ["283c"] = { male = "Огромное спасибо! Ты спас Каменную дамбу. Без твоей помощи террористы Чёрного Железа непременно разрушили бы это знаменитое сооружение. Королевство и Альянс гордятся тобой, отважный герой! Дамба снова в безопасности... по крайней мере, пока...", female = "Огромное спасибо! Ты спасла Каменную дамбу. Без твоей помощи террористы Чёрного Железа непременно разрушили бы это знаменитое сооружение. Королевство и Альянс гордятся тобой, отважная героиня! Дамба снова в безопасности... по крайней мере, пока..." },
    ["284a"] = { common = "Вы обыскиваете всё поселение мурлоков в этом районе, но статуэтки Менетила здесь нет. Может быть, стоит проверить ближайшие несколько жилищ к северу и северо-востоку отсюда?" },
    ["284c"] = { common = "Эту бочку, похоже, никто не трогал. Вы открываете её... Запах валит вас с ног. Сыр слегка заплесневел, но он вполне съедобен!" },
    ["285a"] = { common = "Вы обыскиваете ещё несколько жилищ мурлоков. Вот досада – опять ничего! ...Но вы уверены, что всё получится. Статуэтка Менетила наверняка где-то здесь, в одном из жилищ к северу." },
    ["285c"] = { common = "Бочка наполовину утоплена в грязи и мокрой траве..." },
    ["286a"] = { common = "Вы достаёте бочку из грязи, открываете её и видите серебряную статуэтку, укрытую соломой. Фигурка изображает юного длинноволосого паладина с воздетым над головою молотом. Это, должно быть, и есть статуэтка Менетилова! Теперь вам надо вернуть её Карлу Борану в Гавань Менетилов." },
    ["286c"] = { male = "Капитан \"Слепой принцессы\" будет очень доволен, когда узнает, что мы сумели вернуть ценный груз. Ты сослужил нам хорошую службу и получишь обещанную награду. Радостно сознавать, что в этом мире ещё есть надёжные люди, на которых можно положиться, и особенно – в такое тяжёлое и неспокойное время.", female = "Капитан \"Слепой принцессы\" будет очень доволен, когда узнает, что мы сумели вернуть ценный груз. Ты сослужила нам хорошую службу и получишь обещанную награду. Радостно сознавать, что в этом мире ещё есть надёжные люди, на которых можно положиться, и особенно – в такое тяжёлое и неспокойное время." },
    ["287a"] = { common = "Я не успеваю с донесением, и твоя помощь, мне бы пригодилась. Я сумел узнать, где засели тролли, но их там было столько, что я побоялся лезть туда. Вот что мне нужно... Спустись в пещеру, порыскай там, прибей пару-другую троллей и возвращайся ко мне. Отправляйся из Караноса по северной дороге. Когда перейдёшь через мост, следуй на запад по замёрзшей реке, пока не доберёшься до Заледеневшего озера. На западном берегу обнаружишь Посёлок Пивоваров. Форт Мерзлогривов находится к юго-западу от него." },
    ["287c"] = { common = "А! Я так и думал, что тебе будет несложно найти это место, ведь мои указания были предельно чётки... Дай-ка мне закончить донесение. Он приносит бумагу и что-то быстро на ней пишет. Вот! Ха-ха, теперь это совсем забавно... Думаю, ты не откажешься помочь мне ещё разок?" },
    ["288a"] = { common = "Когда-то я был первым помощником на \"Владычице\", линейном корабле кул-тирасской Третьей флотилии. Обречённой флотилии... Во время последнего плавания на нас напали красные драконы. А ими правили орки! У нас не было ни единого шанса спастись от драконьего огня, и все корабли были сожжены и потоплены у побережья. Я один уцелел в этом кошмаре. Ох, как же раскалывается голова! Погоди, сейчас я выпью чего-нибудь, немного приду в себя и продолжу." },
    ["288c"] = { common = "Вот! И голова не болит, и язык развязался. Спасибо, приятель!" },
    ["289a"] = { common = "*Приободрившись, Фитсиммонс продолжает рассказывать...* Я единственный уцелевший из всех матросов злополучной Кул-Тирасской Третьей флотилии, погибшей у северного побережья. И хотя я последний из команды, чьё сердце бьётся и кто ещё дышит, я не единственный, кто ещё бродит по земле! На одном из наших кораблей хранилось великое, ужасное сокровище, и его потусторонняя зловещая сила держит души моих собратьев и не даёт им покинуть гниющие остовы кораблей. Если ты сможешь их освободить, тогда, может быть, они избавятся от проклятия." },
    ["289c"] = { common = "Багодарю тебя. И прими благодарность моих несчастных собратьев." },
    ["290a"] = { common = "Чтобы избавиться от проклятия и освободить моих верных товарищей, нужно найти и очистить эту... проклятую штуковину... спрятанную на моём корабле! Не знаю, что это такое, знаю только, что эта штука хранится в корабельном сейфе, а ключ от сейфа – у капитана Халиндора. Старина капитан снится мне до сих пор. Я знаю, он сейчас на \"Отважном\" – нашем несчастном корабле. Постарайся добыть ключ от сейфа, открой его и возьми эту вещь. Потом отнеси её в город и отдай жрецу Глорину Стальному Лбу." },
    ["290c"] = { common = "Ключ насквозь проржавел, но замок открылся без труда." },
    ["291a"] = { male = "Замечательно! Отнеси моё донесение сенатору Бэрину Краснокамню. Он мрачный тип, постарайся не заразиться от него унынием. Ты найдёшь его в Стальгорне, в палате, где король Магни вершит суд. Что? Не знаешь дороги в Стальгорн? От Караноса возьми к северу, перейди мост, затем иди по восточной дороге – там по обе стороны штандарты – и вверх по склону горы. Кстати, будь добр, не говори о том, как ты мне помогал. Понимаешь, я не хочу, чтобы подумали, будто я тут не тружусь в поте лица.", female = "Замечательно! Отнеси моё донесение сенатору Бэрину Краснокамню. Он мрачный тип, постарайся не заразиться от него унынием. Ты найдёшь его в Стальгорне, в палате, где король Магни вершит суд. Что? Не знаешь дороги в Стальгорн? От Караноса возьми к северу, перейди мост, затем иди по восточной дороге – там по обе стороны штандарты – и вверх по склону горы. Кстати, будь добра, не говори о том, как ты мне помогала. Понимаешь, я не хочу, чтобы подумали, будто я тут не тружусь в поте лица." },
    ["291c"] = { common = "Он быстро просматривает донесение. По приказу КОРОЛЯ!? Магни совсем спятил! И ещё этот проклятый Белобород... Значит, взял дела в свои руки? Сенат этому не обрадуется, вовсе не обрадуется. Что, ты ещё здесь? Иди отсюда, пока я охрану не вызвал!" },
    ["292a"] = { common = "Внутри сундука лежит тёмный шар, источающий зловещее свечение. Это и есть то сокровище, о котором говорил Фитсиммонс: проклятое Око Палета. Отнесите проклятое Око Палета дворфийскому жрецу Глорину Стальному Лбу в Гавань Менетилов. Попросите его снять проклятие с Ока." },
    ["292c"] = { male = "Око Палета? Поразительно! Хмм... с ним явно что-то не так. Говоришь, ты нашёл его среди обломков судна? Это многое объясняет! Но как же Око попало на корабль Третьей флотилии?.. Неудивительно, что этот Фитсиммонс так перепугался. Проклятое Око Палета кого угодно выбьет из колеи.", female = "Око Палета? Поразительно! Хмм... с ним явно что-то не так. Говоришь, ты нашла его среди обломков судна? Это многое объясняет! Но как же Око попало на корабль Третьей флотилии?.. Неудивительно, что этот Фитсиммонс так перепугался. Проклятое Око Палета кого угодно выбьет из колеи." },
    ["293a"] = { common = "Я не могу снять проклятие с Ока Палета. Это людское творение, и поэтому тебе следует направиться в Штормград. Найди того, кто сумеет тебе помочь. Обратись к архиепископу Бенедикту. Он главный в Соборе Света Штормграда, и сможет дать тебе наставления. Надеюсь, у тебя всё получится." },
    ["293c"] = { common = "Это Око Палета. Определённо, оно видело много скорбей и печалей... может быть, стало свидетелем некоей ужасной, поистине ужасной трагедии. Сейчас я очищу его, ибо Очи созданы для того, чтобы сиять ярким светом, и их сила становится опасной, если они запятнаны порчей." },
    ["294a"] = { common = "Придётся признать, что положение отчаянное. Когда мы раскопали эти кости, ящеры немедленно атаковали нас. Многие из братьев были разорваны на месте, а мы с Меррин и бедолагой геологом оказались в ловушке здесь, наверху. Помоги очистить Болотину от ящеров. Крапчатые ящеры и крапчатые крикуны водятся к западу от этого утёса. Убей по десять тварей каждого вида. Это будет началом моей мести." },
    ["294c"] = { common = "Я понимаю, что убийство – грязная и опасная работа. Но если бы я не поклялся остаться рядом с геологом и Меррин, я бы и сам отправился с тобой." },
    ["295a"] = { common = "Пора нанести им сокрушительный удар. Внизу бродят стаи крапчатых смертехватов и крапчатых острозубов. Убей по десять гадов каждого вида!" },
    ["295c"] = { male = "Ты не представляешь, как ты мне помог!", female = "Ты не представляешь, как ты мне помогла!" },
    ["296a"] = { common = "Пока тебя не было, я заметил, что среди этих тварей есть один выдающийся экземпляр. Он крупнее остальных и отличается особой свирепостью. Могу поклясться, что он – их вожак, это он привёл их сюда и подначил разорить шахту. Сослужи мне последнюю службу. Зарлозуба надо предать правосудию. А если принять во внимание тяжесть его преступлений, правосудие здесь может быть только одно: смерть на месте! Убей его и в доказательство принеси мне один из его когтей." },
    ["296c"] = { male = "Спасибо. Мы не забудем того, что ты сделал для нас. Сколько ни в чём не повинных дворфов полегло в этой злосчастной шахте – а ведь они просто трудились на своих местах. Но ты отомстил за наших безвинно погибших братьев, и теперь ящеры дважды подумают, прежде чем нападать на владения короля Магни.", female = "Спасибо. Мы не забудем того, что ты сделала для нас. Сколько ни в чём не повинных дворфов полегло в этой злосчастной шахте – а ведь они просто трудились на своих местах. Но ты отомстила за наших безвинно погибших братьев, и теперь ящеры дважды подумают, прежде чем нападать на владения короля Магни." },
    ["297a"] = { common = "Незадолго до появления в раскопе троггов мы обнаружили множество странных резных идолов. Изучить их мы не успели, потому что вскоре после этого трогги вытеснили нас из развалин! А идолы оказывают на этих тварей странное воздействие – превращают их в берсерков! Отбей идолов у троггов и принеси мне – я хочу их изучить. Идолов ты найдёшь у троггов – а их в раскопе более чем достаточно." },
    ["297c"] = { male = "Ты добыл их! Хвалю! И хотя там полно троггов-берсерков, ты, кажется, не сильно пострадал. Я буду с интересом следить за твоей судьбой... Ты подаёшь надежды.", female = "Ты добыла их! Хвалю! И хотя там полно троггов-берсерков, ты, кажется, не сильно пострадала. Я буду с интересом следить за твоей судьбой... Ты подаёшь надежды." },
    ["298a"] = { common = "Мне нужно отправить в Телсамар отчёт о ходе работ и запрос на получение нового груза пороха! Вот мой отчёт. Отнеси его Джерну Шлеморогу, он наш представитель в Телсамаре. Задание не сложное, но достаточно важное." },
    ["298c"] = { common = "Ха! У Железняка проблемы с троггами. Интересно, порох ему нужен для продолжения раскопок или для войны с этими тварями... Так или иначе, он будет потрачен не зря! Но вот что странно, несколько недель назад я послал ему немало пороха. Интересно, куда он делся." },
    ["299a"] = { male = "Перед самым вторжением я обнаружил скрижаль с письменами, именуемую скрижалью Гоаз. Несколько кусков отломилось, и в четырёх местах текст обрывается. Там говорится о некоем \"замысле богов\" и о \"проклятом пророчестве\". Боюсь, у нас мало времени. Я уже слишком стар, чтобы сражаться с этими тварями в раскопе. Но ты молод и полон сил. Обыщи раскоп и найди четыре недостающих фрагмента скрижали – Адос, Модр, Голм и Неру. Ищи среди древних артефактов или там, где почва разрыхлена. Найди эти фрагменты и принеси их сюда, и, быть может, тогда я сумею расшифровать письмена и разгадать эту тайну!", female = "Перед самым вторжением я обнаружил скрижаль с письменами, именуемую скрижалью Гоаз. Несколько кусков отломилось, и в четырёх местах текст обрывается. Там говорится о некоем \"замысле богов\" и о \"проклятом пророчестве\". Боюсь, у нас мало времени. Я уже слишком стар, чтобы сражаться с этими тварями в раскопе. Но ты молода и полна сил. Обыщи раскоп и найди четыре недостающих фрагмента скрижали – Адос, Модр, Голм и Неру. Ищи среди древних артефактов или там, где почва разрыхлена. Найди эти фрагменты и принеси их сюда, и, быть может, тогда я сумею расшифровать письмена и разгадать эту тайну!" },
    ["299c"] = { male = "Итак, скрижаль Гоаз восстановлена! Ты хорошо потрудился. Будем надеяться, теперь я сумею расшифровать письмена титанов. Я уже разбираю новые слова! Э... тут написано: \"Древние боги... томятся в цепях под землёй\". Похоже, грядут грандиозные перемены.", female = "Итак, скрижаль Гоаз восстановлена! Ты хорошо потрудилась. Будем надеяться, теперь я сумею расшифровать письмена титанов. Я уже разбираю новые слова! Э... тут написано: \"Древние боги... томятся в цепях под землёй\". Похоже, грядут грандиозные перемены." },
    ["301a"] = { common = "Мы не можем выдать Сталекруту новую партию взрывчатого порошка без одобрения Стальгорна. Тебе придётся отнести его отчёт в штаб-квартиру Лиги Исследователей. Вот он. Отдай его геологу Грозовой Вершине, да не забудь сразу отскочить в сторону. Грозовая Вершина – горячая голова. Его совсем не порадуют новости о медленном продвижении работ. Грозовую Вершину можно найти в Зале исследователей." },
    ["301c"] = { common = "Проклятый Железняк! Я послал ему целый воз пороха ещё неделю назад, но он не потрудился упомянуть об этом в отчёте. Так... куда делся порох?!?" },
    ["302a"] = { male = "Если Сталекруту нужен порох, то, именем короля Магни, он его получит! Я уже отправил вестника в Телсамар с соответствующим приказом Джерну Шлеморогу. Он подготовит груз пороха и прочих припасов для Сталекрута. И ещё одно: я хочу, чтобы ты лично проследил за доставкой груза. Последний груз не добрался до адресата, поэтому держи ушки на макушке и смотри в оба.", female = "Если Сталекруту нужен порох, то, именем короля Магни, он его получит! Я уже отправил вестника в Телсамар с соответствующим приказом Джерну Шлеморогу. Он подготовит груз пороха и прочих припасов для Сталекрута. И ещё одно: я хочу, чтобы ты лично проследила за доставкой груза. Последний груз не добрался до адресата, поэтому держи ушки на макушке и смотри в оба." },
    ["302c"] = { male = "Что? Грозовая Вершина хочет, чтобы ты лично проследил за доставкой груза к Железняку? Я... думаю, это неплохая идея, но беда в том, что Хальдар и носильщики, Миран и Сайан, уже вышли. Вы чуть-чуть разминулись, я отправил их совсем недавно.", female = "Что? Грозовая Вершина хочет, чтобы ты лично проследила за доставкой груза к Железняку? Я... думаю, это неплохая идея, но беда в том, что Хальдар и носильщики, Миран и Сайан, уже вышли. Вы чуть-чуть разминулись, я отправил их совсем недавно." },
    ["303a"] = { common = "Война свирепствует повсюду: и в наших краях, и в чужих землях тоже. Пока наши могучие воины не щадят своих жизней, сражаясь во имя Альянса вдали от дома, на наших собственных землях бесчинствуют дворфы Чёрного Железа. Они разрушили один из мостов Тандола, потом пал и Дун Модр. Тебе нужно собрать добровольцев и сдержать натиск врагов. Если сумеешь убить десять дворфов Чёрного Железа, пять проходчиков, пять саботажников и пять подрывников, тогда, может быть, мы и продержимся до подхода подкрепления. И поторопись! У нас мало времени." },
    ["303c"] = { male = "Ты всё сделал как надо, герой. Ты доказал свою доблесть и преданность королю Магни, за что тебе честь и хвала! Боевой дух Чёрного Железа подорван, и у нас появилась возможность выгнать их с нашей земли навсегда... если этот треклятый резерв всё-таки подойдёт...", female = "Ты всё сделала как надо, героиня. Ты доказала свою доблесть и преданность королю Магни, за что тебе честь и хвала! Боевой дух Чёрного Железа подорван, и у нас появилась возможность выгнать их с нашей земли навсегда... если этот треклятый резерв всё-таки подойдёт..." },
    ["304a"] = { male = "Сколько наших полегло в битве при Дун Модре! Мой родной брат погиб, когда обрушился западный мост Тандола. Да, дворфы Чёрного Железа – те ещё бестии. Чёртово племя, шайка головорезов. Рогго сумел разузнать, что их предводитель в Болотине – некий чернокнижник по имени Балгарас Нечистый. Трус и мерзавец, каких поискать. Посылает на битву своих солдат, а сам прячется у себя в лагере на Зловещем холме, к юго-востоку отсюда. Разыщи этого подлого слизняка, убей его, принеси мне его ухо, и получишь награду, герой.", female = "Сколько наших полегло в битве при Дун Модре! Мой родной брат погиб, когда обрушился западный мост Тандола. Да, дворфы Чёрного Железа – те ещё бестии. Чёртово племя, шайка головорезов. Рогго сумел разузнать, что их предводитель в Болотине – некий чернокнижник по имени Балгарас Нечистый. Трус и мерзавец, каких поискать. Посылает на битву своих солдат, а сам прячется у себя в лагере на Зловещем холме, к юго-востоку отсюда. Разыщи этого подлого слизняка, убей его, принеси мне его ухо, и получишь награду, героиня." },
    ["304c"] = { male = "Ну, вот и всё. Балгарас Нечистый мёртв. И хотя смерть мерзавца не воскресит наших безвинно погибших братьев, тем, кто уцелел, будет гораздо спокойнее. Теперь, когда Балгараса нет, мы без труда справимся с Чёрным Железом. Хотя надо поторопиться. Истребить этих гадов под корень, пока у них не появился новый предводитель! Ты сослужил нам добрую службу, герой.", female = "Ну, вот и всё. Балгарас Нечистый мёртв. И хотя смерть мерзавца не воскресит наших безвинно погибших братьев, тем, кто уцелел, будет гораздо спокойнее. Теперь, когда Балгараса нет, мы без труда справимся с Чёрным Железом. Хотя надо поторопиться. Истребить этих гадов под корень, пока у них не появился новый предводитель! Ты сослужил нам добрую службу, героиня." },
    ["305a"] = { common = "Ты, должно быть, тот самый разведчик, которого мне обещал Длинная Коса? Знаешь... как-то мне неспокойно на сердце. Моя благоверная, Меррин, работает в изыскательской группе на раскопе Вельгара. Писала мне каждую неделю, весь прошлый месяц. А теперь вдруг пропала. Уже две недели ни слуху, ни духу. Наверняка что-то случилось! Длинная Коса обещал, что, если я вскорости не получу никаких известий, он пришлёт мне разведчика, который проверит, что стало с экспедицией. Как я понимаю, ты и есть этот разведчик. Разыщи Меррин на раскопе к востоку отсюда!" },
    ["305c"] = { male = "Слава богам, ты нас нашёл!", female = "Слава богам, ты нас нашла!" },
    ["306a"] = { common = "Это было ужасно! Мы обнаружили несколько очень редких артефактов. Пока мы занимались раскопками, нам всё чаще и чаще начали попадаться огромные кости. Всё случилось внезапно. На нас напали крапчатые ящеры, их было значительно больше, чем нас. Почти все наши погибли в неравной схватке. Остались только мы трое. Ормер – он такой храбрый, настоящий герой, – спас меня и проспектора, он прикрывал нас, пока мы бежали в укрытие. А теперь мы в ловушке, и вся наша работа пропала! Вот, отнеси эту записку моему дорогому Таррелу. Я ему всё написала подробно. Он разберётся." },
    ["306c"] = { common = "Какая ужасная новость! Это счастье, что уцелели хотя бы трое. Когда же закончится эта череда злоключений?! Когда же наконец подданные короля Магни забудут, что значит жить в постоянном страхе?!" },
    ["307a"] = { common = "Рудник у Серебряного ручейка давно выработан. Лига рудокопов превратила его в склад, но теперь туда забрались кобольды и наложили свои грязные лапы на дворфийские инструменты! Рано или поздно мы искореним этих паразитов, но Лига хочет спасти оборудование, пока в шахту не спустились воины и не разнесли всё к демонам. Задача твоя не из простых – помощники тебе не помешают. Оборудование находится в ящиках лиги Рудокопов, разбросанных по всему руднику." },
    ["307c"] = { common = "Там много кобольдов? Жду не дождусь приказа очистить от них рудник. Как подумаю, что они там хозяйничают, аж киплю весь!" },
    ["309a"] = { common = "Что ж, в путь? Для начала надо доставить Железняку порох. Вес немалый, а здесь небезопасно – кто знает, что ещё замышляют дворфы Чёрного Железа. С тобой мне будет куда спокойнее." },
    ["309c"] = { common = "О, слава Свету, вот мой порох. Но новости и верно тревожные. Только подумать, что находятся сторонники Чёрного Железа, способные снабдить их первосортными материалами для выполнения гнусных замыслов. Но над этим пусть поломает голову кто-нибудь другой и не сегодня. А я найду этому пороху отличное применение." },
    ["310a"] = { common = "Не могу не признать, эти Громовары делают славные напитки. Но они должны понять, что не только у них это хорошо получается! Может, ты поможешь преподать им урок... Вот, возьми-ка этот бочонок жгучего пива Ячменоваров. Проберись в подвал \"Громоварки\" в Караносе и подмени один бочонок их громового эля. И посмотрим, не скажут ли их заказчики, что моё пиво лучше, чем Громоваров! Если бочонки охраняются, тебе придётся отвлечь стражу..." },
    ["310c"] = { common = "Вы быстро ставите бочонок жгучего пива Ячменоваров, что дала вам Марлетта, среди бочек громового эля." },
    ["311a"] = { common = "Подсунув бочонок жгучего пива Марлетты в подвал в подвал \"Громоварки\" в Караносе, вы хватаете бочонок громового эля в качестве доказательства..." },
    ["311c"] = { common = "Неплохо! Тебе, небось, нелегко было проскользнуть мимо их охраны? Да всё равно – прими мою благодарность, и если когда-нибудь тебе понадобится крепкое пивко с огоньком, вспомни Ячменевцев!" },
    ["312a"] = { common = "У меня был месячный запас вяленой солонины на зиму. Я запер его в ларь, чтобы медведи не добрались. Но пока я охотился на оленей, этот изверг, Старый Ледобород, уволок мой мясной ларь! Он не смог, однако, взломать ториевый замок. Но я же с голоду помру, если не верну своё мясо! Ты вроде посильнее меня будешь. Может, сумеешь вернуть мой запас? Нога моя совсем плоха – мне не суметь быстро забраться в пещеру и утащить оттуда ларь." },
    ["312c"] = { common = "Какая же ты добрая душа! Благодаря твоей отваге я не подохну с голоду, когда начнутся зимние бури." },
    ["313a"] = { male = "Управлять осадным орудием не каждому по плечу. Тут нужна железная хватка и стальные нервы! К счастью, у меня есть и то, и другое! А у тебя? Кишка-то не тонка? Хочешь показать мне, на что ты способен? Ладно... Я хочу сделать свою машинку, Троллеукладчика, малость поудобнее. Не добудешь ли ты мне охапку грив вендиго из Серой берлоги, что к западу от Караноса? Эти гривы будут прекрасной прокладкой для кабины Троллеукладчика!", female = "Управлять осадным орудием не каждому по плечу. Тут нужна железная хватка и стальные нервы! К счастью, у меня есть и то, и другое! А у тебя? Кишка-то не тонка? Хочешь показать мне, на что ты способна? Ладно... Я хочу сделать свою машинку, Троллеукладчика, малость поудобнее. Не добудешь ли ты мне охапку грив вендиго из Серой берлоги, что к западу от Караноса? Эти гривы будут прекрасной прокладкой для кабины Троллеукладчика!" },
    ["313c"] = { male = "О, эти гривы мне очень пригодятся! Ты крепкий орешек, герой, бьюсь об заклад, я о тебе ещё услышу!", female = "О, эти гривы мне очень пригодятся! Ты крепкий орешек, героиня, бьюсь об заклад, я о тебе ещё услышу!" },
    ["314a"] = { common = "Мы услышали шум среди ночи. Поутру не досчитались в отаре двух баранов. Эта подлая тварь Вагаш покушается на наше единственное добро! Поскольку большая часть армии короля Магни сражается в дальних краях за дело Альянса, некому приструнить этого Вагаша. Может, тебе достанет отваги найти эту тварь и прикончить? Принеси мне его клык, и я тебя награжу. Вагаш рыщет как раз вон над тем выгоном, но предупреждаю: это смертельно опасная тварюга." },
    ["314c"] = { common = "Отлично! Верон будет так рад этой доброй вести! Убить Вагаша – дело непростое. Сдаётся мне, настанет день – и ты будешь сражаться вместе с воинами короля Магни на передовой Альянса!" },
    ["315a"] = { common = "Я тут по делу, а дело моё – создать самый лучший портер! Я знаю, я смогу – пивоварение у меня в крови. Просто надо составить правильный рецепт... Тролльское племя Мерзлогривов высоко в восточных холмах выращивает одну травку, звездолист называется. Они используют её в странных ритуалах своего племени. Нам, дворфам, она не особо нужна, но у неё неповторимый вкус... И я хочу поэкспериментировать с ней при варении пива! Добудь мне немного звездолиста – его можно \"отнять\" у ясновидцев племени Мерзлогривов или стянуть из тролльских корзинок с травами." },
    ["315c"] = { common = "Великолепно! Прямо не терпится испробовать эту травку в одном из моих рецептов. Думаю, вот в этом она особенно хорошо пойдёт..." },
    ["317a"] = { common = "Я веду подготовку к выполнению боевого задания Осадной бригады. Дело будет долгим, и мне нужно укомплектовать мой паровик провизией на месяц. Так что пока ребята из Стальной Решётки работают с моим танком, не отправишься ли ты на охоту? Мне нужен мех, чтобы сделать кровать, и кабанина для еды. Кабаны – на мясо, медведи – на мех... Этих животных можно найти в снежных полях к югу от Серого логова." },
    ["317c"] = { male = "Клянусь бородой Магни, ты славно поохотился! Спасибо тебе.", female = "Клянусь бородой Магни, ты славно поохотилась! Спасибо тебе." },
    ["318a"] = { common = "Регольд Ячменовар не боится экспериментировать со своим варевом. Продукт эксперимента порой хорош на вкус, а порой нет, а иногда... самого крепкого дворфа уложит в стельку. Редгольд живёт в Посёлке Пивоваров, к западу от Караноса, и один из его напитков, \"Вечное сияние\", – как раз то, что мне надо. Он согреет меня в пути. И... этот благословенный напиток горит так, что я могу залить его в топку паровика – и будет такой силовой импульс! Эта тактическая уловка помогала мне выбираться из многих переделок." },
    ["318c"] = { common = "Толступузу нужно \"Вечное сияние\"? Ну, ладно." },
    ["319a"] = { male = "У меня есть бочонок \"Вечного сияния\", но... не мог бы ты оказать мне услугу? Посёлку Пивоваров не помешала бы помощь в борьбе против дикого зверья, что бродит вокруг. Иногда они подходят слишком близко... Мы не боимся этих медведей, кошек и кабанов – ни один уважающий себя дворф не станет их бояться, – но если бы ты взял это зверьё на себя, у нас было бы больше времени на ремесло и пивоварение.", female = "У меня есть бочонок \"Вечного сияния\", но... не могла бы ты оказать мне услугу? Посёлку Пивоваров не помешала бы помощь в борьбе против дикого зверья, что бродит вокруг. Иногда они подходят слишком близко... Мы не боимся этих медведей, кошек и кабанов – ни один уважающий себя дворф не станет их бояться, – но если бы ты взяла это зверьё на себя, у нас было бы больше времени на ремесло и пивоварение." },
    ["319c"] = { common = "Спасибо тебе. Славно будет заняться ремеслом без этого рыка да хрюканья за околицей!" },
    ["320a"] = { common = "Вот твоя бочка \"Вечного сияния\". И спасибо тебе за охоту." },
    ["320c"] = { common = "Ух ты! Пожалуй, открою-ка я его прямо сейчас да попробую..." },
    ["321a"] = { common = "Эти обломки погибших кораблей – останки Кул-Тирасской Третьей флотилии, сожжённой и потопленной красными драконами во время последней Великой войны. Флотилия вышла из Лордерона, и с ней шёл эльфийский боевой корабль – \"Орлик\". Он вёз груз светлостали и присоединился к Третьей флотилии, ища покровительства и защиты. По иронии судьбы, он был потоплен теми же драконами, от которых пытался спастись... Ладно, краткий исторический экскурс будем считать завершённым. \"Орлик\" затонул к югу от Гавани Менетилов. Если найдёшь светлосталь, принеси её мне." },
    ["321c"] = { common = "Сундук весь размок, его обшивка сломана. На стенках внутри и снаружи видны глубокие следы когтей... как будто в нём шарились мурлоки и унесли все сокровища. Но в самом дальнем углу завалялся один-единственный слиток светлостали. К несчастью, этого мало. Для того чтобы выковать достойное оружие, вам нужно больше." },
    ["322a"] = { male = "В Квартале Дворфов Штормграда есть оружейник, мастер по светлостали. Зовут его Гриманд Элмор. Металл, который ты нашёл, я упакую в сундук. Отнеси его Гриманду и расскажи ему свою историю. Я уверен, он не откажет тебе в помощи и изготовит оружие – оружие, которого убоится сам Морбент Скверн!", female = "В Квартале Дворфов Штормграда есть оружейник, мастер по светлостали. Зовут его Гриманд Элмор. Металл, который ты нашла, я упакую в сундук. Отнеси его Гриманду и расскажи ему свою историю. Я уверен, он не откажет тебе в помощи и изготовит оружие – оружие, которого убоится сам Морбент Скверн!" },
    ["322c"] = { common = "Да, занятный рассказ. И светлосталь! Я уже много лет не работал с этим материалом. Для меня это будет великая честь. А когда всё закончится, ты непременно зайди ко мне и расскажи о своей битве с некромантом. Но не будем опережать события. Первым делом -оружие, которым ты сокрушишь Морбента Скверна..." },
    ["323a"] = { common = "Морбент Скверн – могущественный некромант и союзник тёмных всадников. Я не могу послать тебя на битву с ним, не испытав прежде твою силу. Храбрость твою я не подвергаю сомнению, но если ты в самом деле хочешь выступить против некроманта, сразись сначала с его приспешниками." },
    ["323c"] = { common = "Без сомнения, в бою тебе нет равных. Благодаря твоей решимости мы сможем положить конец деяниям Морбента Скверна!" },
    ["324a"] = { common = "Вы забрали слиток светлостали из отсыревшего сундука, но похоже, что остальные слитки растащили мурлоки. Найдите мурлоков-налётчиков у остова \"Орлика\" и отберите у них светлосталь." },
    ["324c"] = { common = "Ага, вот и материал! Ну что, пора бы пустить его в дело, а?" },
    ["325a"] = { male = "Вот оружие против твоего врага. путник, иди и сражайся. Удачи тебе, возвращайся со славой!", female = "Вот оружие против твоего врага. путница, иди и сражайся. Удачи тебе, возвращайся со славой!" },
    ["325c"] = { common = "О, это именно то, что сразит Морбента Скверна! Отлично! Готовься. Скверн теперь – не жилец." },
    ["328a"] = { common = "Хотя в записях нет ни слова о рядовом Торсене, в кожаном переплёте одной из книг Герода обнаруживается маленький латунный ключ. Повнимательнее изучив записи, вы находите упоминания \"надёжного сейфа\". Этот сейф спрятан внутри Схрона, системы пещер позади посёлка Курцена. Если найти его, быть может, удастся разрешить загадку обнаружения Торсена." },
    ["328c"] = { common = "Открыв сейф, вы понимаете, что именно здесь Герод хранил самые ценные монеты и прочие вещи." },
    ["329a"] = { common = "Среди ценностей в сундуке оказывается грязная, торопливо написанная записка. Это сведения о рядовом Торсене – где он патрулирует, с кем он говорит и как проводит время среди повстанцев. Записка подписана лишь одной буквой – М. Ясно одно, её автор очень близко знаком с Торсеном, а это значит, что предатель – среди повстанцев." },
    ["329c"] = { common = "Спасибо. Эта записка позволит нам вычислить и уничтожить предателя!" },
    ["330a"] = { common = "Принесённая тобой записка подписана просто \"-М\".. Не пойму, что это значит. Но... в записке также говорится, что этот человек дежурил вместе с Торсеном на прошлой неделе. Значит, он и есть предатель! Иди к капралу Сетману. Он занимается составлением расписания и скажет, кто дежурил с Торсеном." },
    ["330c"] = { common = "А, да, я могу узнать. Посмотрим... на прошлой неделе… ... Да, с Торсеном дежурил рядовой Мерль. Всю прошлую неделю у них совпадало расписание дежурств." },
    ["331a"] = { common = "Не просил ли лейтенант Дорен доложить ему о собранной информации по дежурствам?" },
    ["331c"] = { common = "Мне больно слышать, что нас предал Мерль. Он был храбрым солдатом, и мне казалось, что верным. С другой стороны, хорошо, что мы его нашли – с таким шпионом в наших рядах... мы недолго продержались бы против полковника Курцена." },
    ["332a"] = { common = "Если тебя интересует вино, так лучшее вино в Штормграде продаёт семейство Галлина! Это недалеко – в Торговом квартале, неподалёку от городских каналов. Возьми этот талон, отнеси его моей сестре Сюзетте и получишь бутылку нашего знаменитого \"Пино нуар\". Не пожалеешь!" },
    ["332c"] = { male = "Вы знакомы с Ренато? В таком случае - только для вас, мсье... Бутылка нашего особого \"Пино нуар\"! Такого вы не попробуете больше нигде во всём Азероте!", female = "Вы знакомы с Ренато? В таком случае - только для вас, мадам... Бутылка нашего особого \"Пино нуар\"! Такого вы не попробуете больше нигде во всём Азероте!" },
    ["333a"] = { common = "Кажется, мы уже встречались. Наверное, насчёт покупки брони и походной одежды. Кстати, ожидается суровая зима... А сегодня меня постигло настоящее огорчение: раскупили всю вязаную одежду. Мне нужна ещё одна партия от нашего поставщика. Если ты отнесёшь это послание Реме Шнайдер в ателье \"Канал\", моя признательность будет весьма велика." },
    ["333c"] = { common = "Говорят, бизнес Харлана пошёл в гору. Хорошие новости, хотя… хотелось бы мне знать, для чего вдруг понадобилось столько брони. Неужели где-то поблизости скоро случится война? Благородные господа ничего не говорят нам об этом! Ну что ж, спасибо тебе за помощь. Вот твоя плата, и я надеюсь, что с заказом Харлана всё хорошо." },
    ["334a"] = { male = "Мой сын Турман – ученик в суконной лавке Ларсона в квартале магов. Он сегодня торопился, а потому забыл иголки и ножницы. Конечно, герой вроде вас едва ли станет заниматься такой ерундой, но, понимаете, без своих инструментов Турман не сможет работать... Прошу вас! Отнесите моему сыну его швейные принадлежности! Лавка Ларсона – один из двух магазинов одежды в Квартале магов, и стоит она прямо рядом с Башней магов.", female = "Мой сын Турман – ученик в суконной лавке Ларсона в квартале магов. Он сегодня торопился, а потому забыл иголки и ножницы. Конечно, героиня вроде вас едва ли станет заниматься такой ерундой, но, понимаете, без своих инструментов Турман не сможет работать... Прошу вас! Отнесите моему сыну его швейные принадлежности! Лавка Ларсона – один из двух магазинов одежды в Квартале магов, и стоит она прямо рядом с Башней магов." },
    ["334c"] = { common = "Ох, блин покровный! А я так надеялся, что забытые инструменты помогут мне увильнуть от работы. А теперь всё-таки придётся помочь Ларсону с шитьём... Ну, ладно: делу – время, потехе – час..." },
    ["335a"] = { common = "Лорд Вишлок наделал немалого переполоху среди Благородных домов. Он прознал о наших делах и теперь собирается добиться полного расследования. У меня есть план, согласно которому можно занять Вишлока другим делом, но понадобится твоя помощь. Есть один цветочек под названием \"слеза Тиллоа\", он растёт в садах Сталвана поблизости от Темнолесья. Ещё мне понадобится мускусный корень, который можно найти только у подножия Каменной дамбы в Болотине." },
    ["335c"] = { common = "Отлично! Это ровно то, что нужно!" },
    ["336a"] = { common = "У лорда Вишлока, как у всех людей, есть свои маленькие слабости. Например, он совсем не дурак выпить. Удивительное лицемерие! Старый ханжа целыми днями сражается с заведениями вроде нашего, а ночи напролёт проводит наверху, да ещё и не платит по счёту. Ну, посмотрим, как ему понравится придуманный мной специально для него напиток: портер \"Чёрный Коготь\"! С ног сбивает – точно тебе говорю! Отнеси ему это пойло и посмотри, придётся ли оно лорду по вкусу. Старый хмырь наверняка шатается вокруг Зала просителей." },
    ["336c"] = { common = "Спасибо за чудесный портер! Вот, возьми пару монет. А теперь иди прочь и не мешай мне дегустировать!" },
    ["337a"] = { common = "Хотя обложка книги исцарапана и заляпана грязью, на корешке всё ещё можно прочитать заглавие – \"История Штормграда\". Открыв её, вы видите на первой странице печать библиотеки Штормграда. Похоже, кто-то взял почитать эту книгу, да так и не вернул..." },
    ["337c"] = { common = "О небо! Этой книги не видели на полках со времён восстановления Штормграда. Конечно, её придётся реставрировать, она в плохом состоянии, но я с радостью помещу её в нашу коллекцию редких книг. Благодарю вас, господин. Прошу, примите плату за возвращение книги!" },
    ["338a"] = { common = "Господин Эрнестуэй так расстроится, когда узнает об этом! Он доверил мне гранки романа \"Зелёные холмы Тернистой долины\". Всё шло хорошо, но по лагерю пронёсся сильный порыв ветра и разметал страницы! Большую часть мне удалось собрать, но многие страницы унесло в джунгли. Найди все страницы, и мы снова соберём четыре главы. Я сам всё разложу! Когда соберёшь все четыре главы, возвращайся." },
    ["338c"] = { male = "Ты избавил меня от многих хлопот. Не знаю, как и благодарить тебя. Вскоре книги господина Эрнестуэя появятся в библиотеках по всему свету!", female = "Ты избавила меня от многих хлопот. Не знаю, как и благодарить тебя. Вскоре книги господина Эрнестуэя появятся в библиотеках по всему свету!" },
    ["339a"] = { common = "Первая глава была необычайно интересной. Мастер Эрнестуэй предваряет рассказ знакомством со своими товарищами по охоте, в том числе и со мной! Но речь не об этом. Посмотрим, каких страниц не хватает. Кажется, страницы один, четыре, шесть и восемь всё ещё в джунглях!" },
    ["339c"] = { common = "Наконец-то! Глава I собрана!" },
    ["340a"] = { common = "Вторая глава представляла собой сплошные увлекательные рассказы про охоту на пантер и тигров. Так и хочется самому себе наподдать за то, что упустил страницы! Мне удалось собрать почти всё, кроме десять, одиннадцать, четырнадцать и шестнадцать." },
    ["340c"] = { male = "Вторая глава полностью собрана! Молодец!", female = "Вторая глава полностью собрана! Умница!" },
    ["341a"] = { common = "Глава III была моей любимой. В ней рассказывается о том, как сэр Эрлгедин и леди Руак впервые подстрелили зверя из дворфийского ружья. А какое захватывающее у неё окончание! Похоже, нам недостаёт страниц восемнадцать, двадцать, двадцать один и двадцать четыре. Они должны быть где-то неподалёку..." },
    ["341c"] = { common = "Уф! Отличная работа. Теперь у нас есть вся глава III!" },
    ["342a"] = { common = "А, Глава IV, захватывающий финал! И как она закончилась! Нам не хватает всего лишь трёх страниц этой главы. А именно – двадцать пять, двадцать шесть и двадцать семь. Стоит найти их – и последняя глава готова." },
    ["342c"] = { common = "Великолепно! Глава IV готова!" },
    ["343a"] = { common = "Я готовлю важную лекцию по стойкости духа и хотел бы освежить в памяти несколько мест из важной работы в области металлургии, \"Как закалялось железо\". Копия этой книги должна быть в Королевской библиотеке Крепости Штормграда. Не могли бы вы заказать её для меня? Да осенит вас благодать Света! Королевская библиотека очень велика, но старший библиотекарь, Милтон Сноп, знает каталог как свои пять пальцев. Поговорите с ним, он принесёт для вас книгу." },
    ["343c"] = { common = "Металлургия? Да, конечно, у нас много книг по данной отрасли знаний, и мы будем рады помочь брату Кристофу в подготовке лекции! Какая же книга его интересует?" },
    ["344a"] = { common = "\"Как закалялось железо\"? Конечно, я знаю такую книгу. Отличная книга, лет двадцать назад написанная дворфом-горняком Маргульфом Благгоном. Он много времени провёл в горах Каз Модана, добывая руду. Отличный парень! Но о чём это я? Ах, да... \"Как закалялось железо\"! Боюсь, что книга отправилась в Аббатство Североземья. Хранитель тамошней библиотеки, брат Пакстон, хотел сделать с неё копию для своей коллекции. Уж сколько тому месяцев минуло... Интересно, почему он её задерживает." },
    ["344c"] = { common = "Коллега Шиф потерял свою книгу? Мда, неловко вышло... Книга действительно у меня, но я не закончил её переписывать, так что мне пока что нужен оригинал!" },
    ["345a"] = { common = "Я как раз собирался закончить свою работу над копией \"Как закалялось железо\", но... Я пользуюсь только чернилами своего собственного изготовления. Они не текут, не выцветают и очень быстро сохнут. Увы, высыхают они тоже слишком быстро! Последняя моя бутылка чернил никуда не годится, а я ещё не успел закончить работу… и сделать ещё чернил я не могу! Для изготовления чернил мне нужна ретбанская руда из Красногорья. Штейгер Ослоу из Озёр – мой верный поставщик…" },
    ["345c"] = { male = "Чего тебе надо? Ты, может, не замечаешь, но мы здесь немного заняты – и укрепления строим, и Приозерье латаем после нападения орков. Если тебе сдалась ретбанская руда, добудь её сам!", female = "Чего тебе надо? Ты, может, не замечаешь, но мы здесь немного заняты – и укрепления строим, и Приозерье латаем после нападения орков. Если тебе сдалась ретбанская руда, добудь её сама!" },
    ["346a"] = { common = "Я закончил перепись и могу вернуть оригинал \"Как закалялось железо\". Спасибо за помощь, и передай, пожалуйста, Милтону мои извинения за долгую задержку." },
    ["346c"] = { common = "Это она! Спасибо! Да пребудет над тобой вечный сияющий Свет!" },
    ["346p"] = { common = "Тебе удалось найти книгу?" },
    ["347a"] = { common = "Ретбанская руда получила своё название по имени первооткрывателя, Барта Ретбана. Выплавленный металл мягче железа, но руда имеет приятный тёмный цвет, и многие переписчики используют её для изготовления чернил. Добыть руду можно в пещерах Ретбана к северу отсюда. К сожалению, постоянные нападения орков отвлекают нас от добычи руды, и запасы наши иссякли. Скажу тебе ещё вот что... Красногорские гноллы недавно поселились в пещерах Ретбана, и их работяги как раз добывают там руду. Так что если тебе нужна руда... ты знаешь, как добыть её." },
    ["347c"] = { common = "О, благодарю! Я наконец-то смогу приготовить чернила и закончить свою работу над копией \"Как закалялось железо\"! Благодарю тебя!" },
    ["347p"] = { common = "Как там моя ретбанская руда?" },
    ["348a"] = { common = "Плохо... Мне... Т-т-т-ак п-п-лохо. П-подцепил.. Лихорадку Тернистой Д-долины... смертельный вирус… ...единственное лекарство... это... съесть сердце М-м-м-мок-ка Д-дикаря... неуловимой белой гориллы… ... Ищи знахаря Унбагва в с-с-скрытой пещере на южном мыслу... ...спеши... умираю... умру..." },
    ["348c"] = { common = "...сила возвращается.. Где я? В Пиратской бухте? Ох! Мне снился странный сон… ...слабость не полностью прошла..." },
    ["350a"] = { common = "Марзон наверняка поддерживает контакт с Братством Справедливости, и у него есть выход на Лесковара... Теперь, когда ван Клиф и Тредд погибли, Лесковара будет нелегко посадить на скамью подсудимых, потому что без их показаний твоё свидетельство ничего не будет значить; стоит также принять во внимание благородное происхождение и хорошие связи Лесковара. Ему, в сущности, наплевать на закон. Тебе понадобится помощь. Я, увы, оказать её не могу, но знаю того, кто может нам помочь. Найди Триаса в Торговом квартале." },
    ["350c"] = { common = "Опять Шоу?! Совести у него нет!.. Братство Справедливости, говорите? Да вы просто мешок с хорошими новостями! Скажите ещё, что Смертокрыл воскрес и напал на город... Ну, ладно, выкладывайте всё по порядку. И не пропускайте ни единой детали. Я хочу знать всё." },
    ["351a"] = { common = "Вы находите какой-то странный яйцевидный металлический предмет. Повозившись с кнопками, вы пробуждаете яйцо, и оно превращается в гномский робот! Изнутри доносится голос. \"Меня зовут Карлс, и мой автономный робот потерялся! За его находку полагается награда! Прошу, отнесите этот маяк к роботу. Я уже вычислил координаты. Он сломался возле Зияющей бездны в Танарисе.\"" },
    ["351c"] = { common = "Вы помещаете яйцо... аварийный маяк... внутрь цыплёнка... робота. Изнутри робота доносится жужжание и скрип – он пытается встреть. Когда робот оживает, изнутри доносится голос Карлса: \"По крайней мере, КПХ-семнадцать/TN работает, но нуждается в серьёзном ремонте! Он слишком тяжёлый, чтобы унести отсюда... впрочем, у меня есть идея. Не хотите присмотреть за ним?\"" },
    ["353a"] = { common = "Грозовая Вершина – уважаемый клан дворфов, известный своими изысканными и утончёнными вкусами. Неудивительно, что Грингер Грозовая Вершина, горный пехотинец Стальгорна, обратился ко мне, когда ему понадобилось оружие. Заказ выполнен, но Грингер служит далеко отсюда, в Лок Модане. Если вы собираетесь на север, не возьмётесь ли доставить груз? По моим последним данным, горный пехотинец Грозовая Вершина остановился в северной сторожевой башне в Лок Модане." },
    ["353c"] = { common = "Ага! Так Гриманд всё-таки закончил мой топор! Мне уже не терпится опробовать его на троггах и кобольдах! Благодарю. Эта посылка проделала такой долгий путь... Вот, примите это в благодарность за ваши услуги." },
    ["354a"] = { common = "Семья Агамондов была самой преуспевающей в Тирисфальских лесах. Я работал на их мельницах... ещё до чумы. Когда Плеть явилась в первый раз, Агамонды укрепили свой дом и уговорили всех работников остаться и помогать им держать оборону. А мы были дураками, но дураками преданными... Из-за гордыни Агамондов мы стали нежитью, а сами они служат Плети! Сослужи Отрёкшимся службу – убей Агамондов, ставших жертвами Чумы, и принеси мне их останки." },
    ["354c"] = { male = "Месть сладка, не правда ли? Ты заметил хоть какие-то признаки свободной воли в Агамондах, когда убивал их? Надеюсь, что да. Надеюсь, они почувствовали страх, прежде чем упокоились навсегда. Конечно, глупо на это надеяться, но тем не менее.", female = "Месть сладка, не правда ли? Ты заметила хоть какие-то признаки свободной воли в Агамондах, когда убивала их? Надеюсь, что да. Надеюсь, они почувствовали страх, прежде чем упокоились навсегда. Конечно, глупо на это надеяться, но тем не менее." },
    ["355a"] = { male = "Ты принёс мне останки Агамондов и утолил мою жажду мести. Но мельницы этой проклятой семейки всё ещё представляют собой угрозу не только для меня, но и для всех Отрёкшихся. Я рассказал мировому судье Севрену о твоих действиях против Агамондов, и он хочет поговорить с тобой лично.", female = "Ты принесла мне останки Агамондов и утолила мою жажду мести. Но мельницы этой проклятой семейки всё ещё представляют собой угрозу не только для меня, но и для всех Отрёкшихся. Я рассказал мировому судье Севрену о твоих действиях против Агамондов, и он хочет поговорить с тобой лично." },
    ["355c"] = { common = "Коулман хорошо отзывался о тебе, и рассказал о твоём успешном походе на мельницы Агамондов. Отрёкшимся ещё раз нужна твоя помощь..." },
    ["356a"] = { common = "Защитники Бастиона, охраняющие Тирисфаль со стороны Чумных земель, постоянно начеку, но порой Плеть проскальзывает мимо них. Наш успех на Бастионе зависит от битвы на один фронт: мы не можем допустить атаки с тыла и уж конечно не можем лишить наших защитников линии поставки припасов. Помоги Бастиону. Отправляйся на восток и убей любого приспешника Плети, которого встретишь. Особое внимание обрати на усадьбу Балнира на востоке – там настоящее гнездо Плети." },
    ["356c"] = { common = "Очень хорошо. Благодаря вашим усилиям Плеть ещё долго не осмелится сунуться сюда. Я отправлю лестный отзыв моему начальнику, исполнителю Зуганду." },
    ["357a"] = { common = "На острове посреди озера Ясноводного, что к северу отсюда, обитает лич. Сам он - свободный Отрёкшийся, но считает, что мы, да и вся остальная нежить, до сих пор находимся под контролем Плети, и велел своим прислужникам атаковать любого, кто приблизится. Но раз он Отрёкшийся, он понадобится Королеве. А если он ещё и специалист в некромантии, то его умения нам... весьма пригодятся. Чтобы понять, кто он и что умеет, мне нужно заглянуть в его книгу заклинаний. Прокрадись в его лагерь, достань её, и принеси мне." },
    ["357c"] = { male = "Прекрасно. Я изучу эту книгу и узнаю многое об этом личе. Ты сослужил королеве добрую службу. Бетор открывает книгу и внимательно смотрит на её сияющие страницы… Невероятно! Добытая тобой книга принадлежит не кому иному, как Гюнтеру Чародею! Гюнтер и при жизни был искусным некромантом. До нашествия Плети мы были добрыми товарищами и братьями по оружию. Судя по книге, после смерти он достиг ещё большего могущества. Его искусство могло бы нам очень пригодиться.", female = "Прекрасно. Я изучу эту книгу и узнаю многое об этом личе. Ты сослужила королеве добрую службу. Бетор открывает книгу и внимательно смотрит на её сияющие страницы… Невероятно! Добытая тобой книга принадлежит не кому иному, как Гюнтеру Чародею! Гюнтер и при жизни был искусным некромантом. До нашествия Плети мы были добрыми товарищами и братьями по оружию. Судя по книге, после смерти он достиг ещё большего могущества. Его искусство могло бы нам очень пригодиться." },
    ["358a"] = { common = "Братские могилы к юго-востоку от фермы Гаррена были вырыты, чтобы справиться с... внушительным количеством смертей в Тирисфале после прихода Чумы. Тела в этих могилах ещё не превратились в нежить, но теперь Плеть подослала гноллов-Гнилошкуров, чтобы они воровали из могил трупы и пополняли ими ряды их армии. Это недопустимо! У тебя будет два задания: перебить гноллов-Гнилошкуров возле братских могил и фермы Гаррена, а также отобрать у них бальзамирующую лимфу, поддерживающую в них жизнь." },
    ["358c"] = { male = "Отличная работа! Если силы Плети решили, что могут направлять этих мертвецов на нас, то они жестоко ошиблись. Что же касается жидкости, которую ты собрал с рабов Гнилошкуров, её изучат наши аптекари. Возможно, они откроют какой-то секрет, который поможет нам в войне. Словом, ты отлично справился. Но война продолжается, и у тебя будет ещё много шансов проявить себя перед Отрёкшимися.", female = "Отличная работа! Если силы Плети решили, что могут направлять этих мертвецов на нас, то они жестоко ошиблись. Что же касается жидкости, которую ты собрала с рабов Гнилошкуров, её изучат наши аптекари. Возможно, они откроют какой-то секрет, который поможет нам в войне. Словом, ты отлично справилась. Но война продолжается, и у тебя будет ещё много шансов проявить себя перед Отрёкшимися." },
    ["359a"] = { common = "Мне нужен свежий отчёт с восточной базы наших стражей смерти. Я хочу знать, не проникли ли новые силы Плети за Бастион, в Тирисфаль. На границе с Чумными землями нужно постоянно смотреть в оба! Нельзя, чтобы Плеть устроила здесь ещё одну крепость. Иди по дороге на юг, а на развилке сверни на восток, к базе. Поговори со стражем смерти Линнеей, у неё есть вся нужная мне информация." },
    ["359c"] = { common = "Севрену нужен отчёт? Ну что же, защитники Бастиона сдерживают силы Плети, но часть из них всё же проникает время от времени. Плеть видели к востоку от нашей базы, возле Усадьбы Балнира." },
    ["360a"] = { common = "Теперь возвращайся к мировому судье Севрену с той информацией, что я дала вам. Он очень ждёт её, так что поспеши. А если встретишь по пути приспешников Плети – немедленно убей их! Нечего им шастать по нашим землям." },
    ["360c"] = { common = "Неприятно слышать, что Плеть просачивается через Бастион. Король-лич и его слуги не собираются сдаваться. Но и мы не уступим. Мы не позволим ему захватить нас снова!" },
    ["361a"] = { common = "Это письмо, написанное Турманом, старшим сыном Грегора Агамонда. Оно адресовано Иветте Фартинг, но, похоже, так до неё и не добралось..." },
    ["361c"] = { common = "О... мой бедный Тармен! Я ведь просила его уйти с этих мельниц со мной и моим отцом, но его преданность семье оказалась сильнее... Так я и знала! Я знала, что Брэнд желает ему зла! Будь прокляты эти Чума и Плеть! Лицо Иветты смягчается. Но стенания – удел слабых. Я Отрёкшаяся, у меня есть свои цели, и любовь не входит в их число. Спасибо за то, что принесли мне письмо от некогда любимого человека, теперь я хотя бы знаю, что с ним сталось. Но та жизнь для меня окончена. Навсегда." },
    ["362a"] = { common = "Девлин Агамонд был младшим из двух сыновей в семье, и более непохожих братьев найти было невозможно. Турман был высоким и учтивым, а его младший брат – слабым и острым на язык. Когда мельницы Агамондов пали во время нашествия Чумы, я не удивился, услышав, что Девлин погиб одним из первых. На дороге, ведущей к мельницам Агамондов, до сих пор можно услышать его безумное бормотание. Я собираю останки Агамондов, и для полной коллекции мне не хватает лишь бедного Девлина. Найди его, уничтожь и принеси мне его кости." },
    ["362c"] = { common = "Спасибо. Кости Девлина станут отличным украшением для моего плаща. Если что-то может согреть моё холодное сердце, то это мысль о том, что Агамондов больше нет. Они предали меня и мою семью, когда пришла Чума – а теперь я клянусь, что растопчу их кости ногами!" },
    ["363a"] = { male = "Ты вовремя пришёл в себя. Мы собирались уже швырнуть тебя в огонь вместе с остальными, но, похоже, тебе посчастливилось избежать этой участи. Меня зовут Мордо, я смотритель склепа Могильника. А ты больше не раб Короля-лича. Поговори с жрецом Тьмы Сарвисом в часовне у подножья холма, он расскажет тебе о том, что тебе нужно знать.", female = "Ты вовремя пришла в себя. Мы собирались уже швырнуть тебя в огонь вместе с остальными, но, похоже, тебе посчастливилось избежать этой участи. Меня зовут Мордо, я смотритель склепа Могильника. А ты больше не рабыня Короля-лича. Поговори с жрецом Тьмы Сарвисом в часовне у подножья холма, он расскажет тебе о том, что тебе нужно знать." },
    ["363c"] = { common = "А, ещё один живой мертвец! Должно быть, это настоящий шок – очнуться в склепе, в котором тебя встречает лишь холод... и Мордо. Я всё это читаю по твоему лицу. Позволь мне объяснить тебе наше... эээ... положение. Нас освободила из-под контроля Короля-лича наша новая предводительница, Леди Сильвана. Тёмная Госпожа руководит нами в войне против ненавистной армии Плети и цепляющихся за эту землю людей, преследующих нас, словно ищейки." },
    ["364a"] = { common = "Мы, Отрёкшиеся, ведём войну против армии Плети, ведомой Королём-личом: против поднятых некромантией войск нежити, против злобных зверей севера и истерзанных призраков. Северную часть деревни оккупировали безмозглые твари Плети, их нужно уничтожить. Сокруши их, не давая пощады, пусть они и были прежде нашими братьями и сёстрами. Падшие – всего лишь рабы Короля-лича." },
    ["364c"] = { common = "Жаль, что нельзя привлечь Плеть на нашу сторону, её несметные полчища пришлись бы как нельзя кстати в предстоящих битвах. Но так как договориться с ними нельзя, нам остаётся лишь уничтожить их." },
    ["365a"] = { male = "Кто это тут? Новенький, да ещё и герой? Если хочешь проявить себя перед Тёмной Госпожой, придётся следовать обычаям Отрёкшихся. К западу отсюда есть ферма. Люди растекаются по этой земле, как плесень по трупу. К тому же Алый орден постоянно ходит дозором возле своей башни. Преподай этим ничтожествам урок и укради у них десять их драгоценных тыкв. Как наберёшь десяток, отнеси их аптекарю Юхану в Брилл.", female = "Кто это тут? Новенькая, да ещё и героиня? Если хочешь проявить себя перед Тёмной Госпожой, придётся следовать обычаям Отрёкшихся. К западу отсюда есть ферма. Люди растекаются по этой земле, как плесень по трупу. К тому же Алый орден постоянно ходит дозором возле своей башни. Преподай этим ничтожествам урок и укради у них десять их драгоценных тыкв. Как наберёшь десяток, отнеси их аптекарю Юхану в Брилл." },
    ["365c"] = { male = "Ты хорошо справился с заданием, герой, и тем самым доказал, что достоин примкнуть к армии Тёмной Госпожи.", female = "Ты хорошо справилась с заданием, героиня, и тем самым доказала, что достойна примкнуть к армии Тёмной Госпожи." },
    ["366a"] = { common = "Давным-давно Гюнтер, я и Тул Коготь Ворона, который стал теперь некромантом Плети, дружили и состояли в Кирин-Торе – сообществе магов Даларана. Мы с Гюнтером оба пали жертвами Чумы, но я полагал, что он так и сгинул в небытие или встал под знамёна Короля-лича. Я рад, что он остался свободным. Мы должны привлечь его на свою сторону. Я наложил на эту книгу заклинание, которое докажет ему, что я тоже свободен от Короля-лича. Надеюсь, что, убедившись в этом, он станет одним из нас." },
    ["366c"] = { male = "Моя книга?! Так это ты украл её! Но... что это за новые чары на ней... Бетор? Он в Лордероне? Если он всё ещё \"жив\", то, может быть, ему тоже удалось вырваться из холодных объятий Короля-лича...", female = "Моя книга?! Так это ты украла её! Но... что это за новые чары на ней... Бетор? Он в Лордероне? Если он всё ещё \"жив\", то, может быть, ему тоже удалось вырваться из холодных объятий Короля-лича..." },
    ["367a"] = { common = "Леди Сильвана обратилась к Королевскому фармацевтическому обществу. Тёмная Госпожа считает, что при помощи наших знаний и новейшей магии мы сумеем найти ключ к свержению Артаса. Она хочет, чтобы мы вывели новую чуму – смертоноснее любой болезни Азерота, чтобы она уничтожила всю армию Артаса. В своих изысканиях я обнаружил, что для этого потребуется кровь животных. Принеси мне пять склянок крови пса тьмы, чтобы я мог провести эксперимент." },
    ["367c"] = { male = "Ты хорошо справился. Благодарю тебя за старание.", female = "Ты хорошо справилась. Благодарю тебя за старание." },
    ["368a"] = { male = "Пока ты собирал для меня образцы, я провёл исследования и обнаружил, что для должного распространения этой болезни потребуются и другие реагенты. Отравить какую-нибудь одну жалкую жертву – это ерунда, а вот отравить весь мир будет куда сложнее. Мне потребуется пять чешуек мурлоков из племени Злобного Плавника. Их можно найти на берегу к северу или к западу.", female = "Пока ты собирала для меня образцы, я провёл исследования и обнаружил, что для должного распространения этой болезни потребуются и другие реагенты. Отравить какую-нибудь одну жалкую жертву – это ерунда, а вот отравить весь мир будет куда сложнее. Мне потребуется пять чешуек мурлоков из племени Злобного Плавника. Их можно найти на берегу к северу или к западу." },
    ["368c"] = { common = "Отличная чешуя. Именно то, что мне нужно для микстуры." },
    ["369a"] = { common = "Пока вы были заняты сборами, я обнаружил в одном из своих фолиантов старинный текст, в котором сказано, что древняя чума унесла тысячи невинных жизней. Позже открыли, что возбудитель болезни сохранился благодаря яду ночных кругопрядов. Принесите мне немного яда злобных ночных кругопрядов, чтобы я мог закончить эксперимент. Хочу посмотреть, как среагирует ядовитый элемент с моим новым составом. Говорят, что этих пауков можно найти в Восточных Тирисфальских лесах." },
    ["369c"] = { common = "Да, этот яд великолепно подойдёт! Я уже добавил всё остальное в мой состав и вскипятил его. Наконец-то я испытаю эту смертельно опасную смесь!" },
    ["370a"] = { common = "В документах палача Аррена содержится информация, нужная нам для того, чтобы истребить всех людей в наших землях. Судя по этим данным, Алый орден прислал в заброшенную башню на юго-западе от Брилла капитана Перрина с людьми. Убей Перрина, трёх ревнителей и трёх миссионеров, а потом доложи мне о своём успехе." },
    ["370c"] = { male = "Тёмная Госпожа, без сомнения, обрадуется смерти капитана Перрина. Вы хорошо исполнили свой долг, герой.", female = "Тёмная Госпожа, без сомнения, обрадуется смерти капитана Перрина. Вы хорошо исполнили свой долг, героиня." },
    ["371a"] = { common = "У нас до сих пор война, а Алый орден набирает силу. В отчёте палача Аррена сказано, что его участники под предводительством капитана Вакона совершают набеги из разрушенной башни в юго-восточном Тирисфале, близ фермы Балнира. Убей Вакона и пять келейников из Алого ордена – это должно нанести ордену сокрушающий удар!" },
    ["371c"] = { common = "Смерть капитана Вакона значительно замедлит продвижение Алого ордена по Тирисфалю. Но есть и другие угрозы." },
    ["372a"] = { common = "Алый орден совершает набеги из своей разрушенной башни в северном Тирисфале, за могилой Фаола. Согласно нашей информации, отвечает за эти набеги жестокий капитан Мелраш. Я даю вам особенное и очень важное задание – убить Мелраша и двух его телохранителей во имя Тёмной Госпожи." },
    ["372c"] = { male = "Вы отлично справились, герой. Чем больше на стороне Отрёкшихся таких безжалостных бойцов, как вы, тем ближе наша победа и свержение Артаса. У меня хорошие предчувствия на ваш счёт.", female = "Вы отлично справились, героиня. Чем больше на стороне Отрёкшихся таких безжалостных бойцов, как вы, тем ближе наша победа и свержение Артаса. У меня хорошие предчувствия на ваш счёт." },
    ["373a"] = { common = "Обыскав труп Эдвина ван Клифа, вы находите, среди прочих предметов, неотправленное письмо. Адрес таков: \"Баросу Алекстону, главному архитектору Штормграда, в Ратуша на Соборной Площади\". Оно кажется написанным совсем недавно, и печать ещё свежая…" },
    ["373c"] = { common = "Эдвин ван Клиф, говорите? Я бы скорее ждал письма от своей покойной бабушки... Так это вы его убили? Извините, конечно, но я сильно удивлён. В молодые годы он был просто непревзойдённым бойцом. Ну, дайте-ка взглянуть, что он мне там написал после стольких лет... Барос рассматривает письмо. Эх, Эдвин… годы не изменили тебя ни на каплю. Всё такой же идеалист и романтик. Представляете, ему было всё равно, кому мстить. Месть попросту поглотила его. Но, кажется, я его понимаю…" },
    ["374a"] = { male = "Палач Зуганд сказал, что тебе уже приходилось убивать членов Алого ордена. Тирисфальские леса так и кишат ими. Вариматрас, подручный Тёмной Госпожи, лично следит за тем, чтобы это азеротское отребье – раса людей – было стёрто с лица земли. Здесь, в Тирисфальских лесах, обосновалась особо неприятная группа людей – Алый орден. Помоги нам истребить их, герой. Принеси мне десять алых перстней в доказательство твоей верности Вариматрасу и Тёмной Госпоже.", female = "Палач Зуганд сказал, что тебе уже приходилось убивать членов Алого ордена. Тирисфальские леса так и кишат ими. Вариматрас, подручный Тёмной Госпожи, лично следит за тем, чтобы это азеротское отребье – раса людей – было стёрто с лица земли. Здесь, в Тирисфальских лесах, обосновалась особо неприятная группа людей – Алый орден. Помоги нам истребить их, героиня. Принеси мне десять алых перстней в доказательство твоей верности Вариматрасу и Тёмной Госпоже." },
    ["374c"] = { male = "Вариматрас будет гордиться тобой. Ты отлично служишь своим лидерам, герой.", female = "Вариматрас будет гордиться тобой. Ты отлично служишь своим лидерам, героиня." },
    ["375a"] = { common = "Так холодно... Чума Нежити расползается по моим венам, как клубок ледяных змей, и скоро я впаду в беспамятство. Но никакой злой рок не помешает мне нести службу нашей Тёмной Госпоже. Когда прозвучал зов, я шила мешки для павших солдат великой армии Сильваны. Теперь мои руки дрожат от холода. Если ты принесёшь мне пять шкурок сумеречницы и грубую нить, я сошью себе одеяло. Помоги мне, чтобы я могла и дальше служить нашему делу." },
    ["375c"] = { common = "Спасибо за заботу. Надеюсь, когда-нибудь слух о твоей храбрости дойдёт и до Сильваны..." },
    ["376a"] = { male = "В мои обязанности входит присмотр за нашими ранеными воинами, пошив доспехов и одежды и любая помощь жрецу Тьмы Сарвису, какая может потребоваться. Похоже, и ты будешь записан к нему на службу... он поручит тебе охоту на безмозглых тварей Плети, насколько я его знаю. В общем, если ты хочешь остаться в целости и сохранности – а я не сомневаюсь, что это так – может, я смогу помочь. У меня заканчиваются запасы лап и крыльев, и если ты принесёшь мне немного, я найду для тебя какой-нибудь доспех. К югу отсюда волков-падальщиков и летучих мышей предостаточно.", female = "В мои обязанности входит присмотр за нашими ранеными воинами, пошив доспехов и одежды и любая помощь жрецу Тьмы Сарвису, какая может потребоваться. Похоже, и ты будешь записана к нему на службу... он поручит тебе охоту на безмозглых тварей Плети, насколько я его знаю. В общем, если ты хочешь остаться в целости и сохранности – а я не сомневаюсь, что это так – может, я смогу помочь. У меня заканчиваются запасы лап и крыльев, и если ты принесёшь мне немного, я найду для тебя какой-нибудь доспех. К югу отсюда волков-падальщиков и летучих мышей предостаточно." },
    ["376c"] = { common = "Спасибо. Держи этот доспех. Надеюсь, тебе он послужит лучше, чем тому бедолаге, что носил его последним…" },
    ["377a"] = { common = "Мало того, что столица бросила Темнолесье на произвол судьбы, теперь Благородные дома плюнули на решение городского совета Темнолесья и заточили Декстрена Варда в тюрьму Штормграда – вместо того, чтобы обезглавить злодея по приказу лорда Чернодрева. Вард продавал тела с кладбища Морбенту Скверну. Подобное преступление карается смертью. И всё же Штормград объявил Варда своим пленником. Убей Варда в тюрьме Штормграда, принеси мне его руку, и я тебя вознагражу." },
    ["377c"] = { male = "Так значит, Декстрен Вард наконец-то расплатился за свои преступления против человечества? Чем меньше швали, тем лучше, я так считаю. Хвала тебе, друг мой! Ты не только утешил семьи покойных, ты преподал наглядный урок продажным бюрократам из Благородных домов. Штормград должен прислушиваться к нашему голосу, или мы восстанем против его тирании.", female = "Так значит, Декстрен Вард наконец-то расплатился за свои преступления против человечества? Чем меньше швали, тем лучше, я так считаю. Хвала тебе, друг мой! Ты не только утешила семьи покойных, ты преподала наглядный урок продажным бюрократам из Благородных домов. Штормград должен прислушиваться к нашему голосу, или мы восстанем против его тирании." },
    ["378a"] = { male = "Ты доказал свою преданность королю Магни, герой. И ты, так же как я, ненавидишь мерзавцев Чёрного Железа всем сердцем. Я бы сам взялся за эту работу, но я дал слово чести и должен быть рядом с Длинной Косой. Рогго говорит, что у него есть доподлинные доказательства: это Кам Гневливый организовал нападение на мост Тандола. А это значит, что Кам виноват в гибели брата Длинной Косы. Пока что Кама Гневливого держат в тюрьме Штормграда. Но такие, как он, не достойны того, чтобы жить. Убей его. Ради Грима! Принеси мне его голову!", female = "Ты доказала свою преданность королю Магни, героиня. И ты, так же как я, ненавидишь мерзавцев Чёрного Железа всем сердцем. Я бы сам взялся за эту работу, но я дал слово чести и должен быть рядом с Длинной Косой. Рогго говорит, что у него есть доподлинные доказательства: это Кам Гневливый организовал нападение на мост Тандола. А это значит, что Кам виноват в гибели брата Длинной Косы. Пока что Кама Гневливого держат в тюрьме Штормграда. Но такие, как он, не достойны того, чтобы жить. Убей его. Ради Грима! Принеси мне его голову!" },
    ["378c"] = { male = "Стало быть, Кам Гневливый на собственной шкуре узнал, каково это – принять мучительную смерть? Хорошо. С этими негодяями из клана Чёрного Железа только так и надо. Отлично потрудился, герой. Жертвы атаки на мост Тандола – это не первые и не последние невинные жертвы в нашем мире, объятом смятением и раздираемым войнами. Но теперь семьи погибших хотя бы утешатся тем, что предатель наказан. Брат Длиннокоса отомщён.", female = "Стало быть, Кам Гневливый на собственной шкуре узнал, каково это – принять мучительную смерть? Хорошо. С этими негодяями из клана Чёрного Железа только так и надо. Отлично потрудился, героиня. Жертвы атаки на мост Тандола – это не первые и не последние невинные жертвы в нашем мире, объятом смятением и раздираемым войнами. Но теперь семьи погибших хотя бы утешатся тем, что предатель наказан. Брат Длиннокоса отомщён." },
    ["379a"] = { common = "Тебе нужен источник силы. Могу помочь. Что я хочу взамен? Пить! Принеси мне пять бурдюков с водой Скитальцев Пустыни, и я дам тебе четыре тысячи семьсот одиннадцать-FTZ. Знаешь, где взять эти меха? Попробуй попросить их у кочевников Скитальцев Пустыни! Потом расскажешь, что из этого вышло." },
    ["379c"] = { common = "Отлично, вот тебе источник энергии. Честно говоря, он создан совсем не для исследовательского набора вроде этого, поэтому у тебя будет не так уж много времени, а потом все данные кирдыкнутся! Как только соберёшь, всё, что нужно, принеси эту штуковину мне, чтобы я отключил её как надо. У тебя не больше двух часов на всё про всё. Если ты не успеешь, я, конечно, продам тебе ещё один источник энергии. Ключевое слово – продам!" },
    ["380a"] = { common = "Одна из наших самых серьёзных проблем – это добыча природных ресурсов, необходимых для выживания. Золота было очень мало даже во времена расцвета Альянса. К северо-западу отсюда есть золотой рудник, но он весь кишит пауками. Нам нужно золото из рудника, но мы не можем его добывать, пока там везде бегают эти членистоногие твари. У меня не так много рабочих рук для этой задачи, так что придётся действовать постепенно. Отправляйся туда – может быть, ты сможешь чем-то помочь нам." },
    ["380c"] = { male = "Ну что же, для начала неплохо. Очистка всей территории займёт несколько недель или даже месяцев. А после этого, нам придётся пойти туда с факелами, чтобы сжечь паутину. Ты отлично справился, я уверен, что подыщу для тебя ещё какую-нибудь работёнку.", female = "Ну что же, для начала неплохо. Очистка всей территории займёт несколько недель или даже месяцев. А после этого, нам придётся пойти туда с факелами, чтобы сжечь паутину. Ты отлично справилась, я уверен, что подыщу для тебя ещё какую-нибудь работёнку." },
    ["381a"] = { male = "Тебе будет приятно узнать, что у нас, кажется, наметился неплохой прогресс на руднике, не в последнюю очередь благодаря твоим усилиям. Теперь мы можем позаботится и о других делах. Мои разведчики доложили, что подразделение Алого ордена разбивает лагерь к юго-востоку отсюда. Алый орден – достойная презрения организация, ведущая охоту на нас. Они не успокоятся, пока не истребят всю нежить, независимо от того, принадлежит ли эта нежить к армии Плети или нет. Мы должны первыми нанести удар! Будь осторожен, нечестивое рвение делает их опасными противниками.", female = "Тебе будет приятно узнать, что у нас, кажется, наметился неплохой прогресс на руднике, не в последнюю очередь благодаря твоим усилиям. Теперь мы можем позаботится и о других делах. Мои разведчики доложили, что подразделение Алого ордена разбивает лагерь к юго-востоку отсюда. Алый орден – достойная презрения организация, ведущая охоту на нас. Они не успокоятся, пока не истребят всю нежить, независимо от того, принадлежит ли эта нежить к армии Плети или нет. Мы должны первыми нанести удар! Будь осторожна, нечестивое рвение делает их опасными противниками." },
    ["381c"] = { common = "Если б только они послушались доводов разума, а? Может быть, мы могли бы уговорить их всё серьёзно обсудить... Как же! Идиоты, ослеплённые светом..." },
    ["382a"] = { common = "В сообщениях от моего начальства в Брилле упоминается, что агент Алого ордена направляется из их монастыря к Могильнику. Судя по этим сообщениям, гонец несёт важную информацию. Я не знаю подробностей, но что бы у него ни оказалось, мы должны это перехватить! А ты, наиболее квалифицированная особа, которую я могу послать на это задание. Найди гонца и принеси мне информацию, которую тебе удастся найти." },
    ["382c"] = { male = "Хмм... Ну-ка, посмотрим, что ты там нашёл... Аррен пробегает глазами документы, принесённые вами. Новости об их успехах в борьбе с нами... Ценности не имеют. Донесения разведки... Новые приказы... \"Продолжайте организацию лагеря около разрушенного города...\" Ничего такого, о чём мы не знали бы... А это ещё что? Карта местонахождения некоторых полевых командиров и агентов! Это можно будет использовать.", female = "Хмм... Ну-ка, посмотрим, что ты там нашла... Аррен пробегает глазами документы, принесённые вами. Новости об их успехах в борьбе с нами... Ценности не имеют. Донесения разведки... Новые приказы... \"Продолжайте организацию лагеря около разрушенного города...\" Ничего такого, о чём мы не знали бы... А это ещё что? Карта местонахождения некоторых полевых командиров и агентов! Это можно будет использовать." },
    ["383a"] = { male = "Вот это нужно отнести моему начальнику, палачу Зуганду, в Брилл. Обладая этой информацией, он сможет нанести решающий удар по Алому ордену. Ты сильно помог нам здесь, в Могильнике, но мне нужно, чтобы кто-то доставил эти сведения Зуганду, и я уверен, что у него для тебя найдётся более серьёзная работа. Иди по дороге из Могильника на север. Вскоре после того, как дойдёшь до Тирисфаля, наткнёшься на перекрёсток. Сверни на восток и продолжай идти в том же направлении. По дороге как раз и будет поместье \"Остывший очаг\".", female = "Вот это нужно отнести моему начальнику, палачу Зуганду, в Брилл. Обладая этой информацией, он сможет нанести решающий удар по Алому ордену. Ты сильно помогла нам здесь, в Могильнике, но мне нужно, чтобы кто-то доставил эти сведения Зуганду, и я уверен, что у него для тебя найдётся более серьёзная работа. Иди по дороге из Могильника на север. Вскоре после того, как дойдёшь до Тирисфаля, наткнёшься на перекрёсток. Сверни на восток и продолжай идти в том же направлении. По дороге как раз и будет поместье \"Остывший очаг\"." },
    ["383c"] = { male = "О, прекрасно! Ты отлично потрудился, добывая эту информацию. Хмм... Имена офицеров в Тирисфальских лесах… Представь, какой удар мы можем нанести по боевому духу этих фанатиков, если убьём всех их лидеров одним стремительным ударом.", female = "О, прекрасно! Ты отлично потрудилась, добывая эту информацию. Хмм... Имена офицеров в Тирисфальских лесах… Представь, какой удар мы можем нанести по боевому духу этих фанатиков, если убьём всех их лидеров одним стремительным ударом." },
    ["384a"] = { common = "Завсегдатаи моей таверны больше всего любят кабаньи рёбрышки в пиве! Беда в том, что местный охотник, который снабжал меня кабанятиной, теперь завербован в королевскую армию, чтобы помочь Альянсу. Может, ты мне поможешь? Если принесёшь мне шесть рёбер скального вепря и \"Болтливое пиво\" вон из той таверны, я открою тебе фамильный рецепт моих знаменитых рёбрышек в пиве, не говоря уж о дармовой порции! Вся соль – в пиве!" },
    ["384c"] = { common = "Сварено пиво, разлито по кружкам, Эй, не деритесь, друзья и подружки! Каждому выделим по половине Вкуснейшей порции рёбрышек в пиве!" },
    ["385a"] = { common = "Многие охотники приезжают к озеру Лок Модан поохотиться на знаменитых кроков. Всегда находятся торговцы, скупающие кроколисковые шкуры на одежду или доспехи, а есть и любители кроколискового мяса. Мы тоже зарабатываем на этом, но не слишком много, потому что кроколисков не так просто одолеть, и к тому же они поселились на островах посреди озера Лок. Но если хочешь отправиться на охоту, я не стану тебя отговаривать. Это действительно незабываемо. Я и сам в своё время..." },
    ["385c"] = { male = "Ты отлично поохотился. За хорошую работу и платят хорошо!", female = "Ты отлично поохотилась. За хорошую работу и платят хорошо!" },
    ["386a"] = { common = "Таргорр Ужасный служил под началом Гат'Илзогга старшим палачом и даже среди жестоких орков отличался особой кровожадностью. По его прихоти отважных бойцов Королевства подвергали страшным пыткам. Его взяли в плен и поместили в тюрьму Штормграда, приговорив к смертной казни. Но происходит что-то странное. Один из знатных людей запретил его казнить. Уверен, дело нечисто. Положи конец Таргорру Ужасному. Отправляйся в тюрьму и обезглавь его, пока мы не пали жертвой предательства." },
    ["386c"] = { common = "Наконец-то Таргорр Ужасный получил по заслугам. Я рад, что злодей угодил в лапы Смерти. Молодец. Иной раз подлинное правосудие можно отыскать лишь за стенами залов суда, вдали от замутнённого взора политиканов." },
    ["387a"] = { common = "Бунт должен быть подавлен! И ты мне в этом поможешь. Если станет известно, что в тюрьме случился бунт, я потеряю работу. Это исключительная подлость! Самое важное сейчас – немедленно взять тюрьму под контроль. Ради безопасности Штормграда. Наказание за бунт в тюрьме – смертная казнь. Убей несколько этих отщепенцев, это даст урок всем остальным, и ситуация войдёт в норму." },
    ["387c"] = { male = "Ты отлично проявил себя в тюрьме. Эта проблема куда сложнее, чем выглядит на первый взгляд, но ты отлично поработал, и я тебе очень благодарен.", female = "Ты отлично проявила себя в тюрьме. Эта проблема куда сложнее, чем выглядит на первый взгляд, но ты отлично поработала, и я тебе очень благодарен." },
    ["388a"] = { common = "Кровь моя стынет в жилах от ужасного горя... Мой внук Мак… он был такой чудесный мальчик. Всего четырнадцать лет. Когда армия ушла на фронт, он счёл, что должен защитить город. Он был охранником в тюрьме, куда прибыла партия заключённых из Братства Справедливости. Мак наказал некоторых заключённых за порчу шерстяного одеяла, из которого они изготовили головные повязки, знаки их банды. За это он получил нож в спину. Я хочу мести. Принесите мне десять этих проклятых шерстяных бандан. Они цвета крови..." },
    ["388c"] = { common = "Значит, из-за этих жалких тряпиц они убили моего Мака... Ужасная, нелепая смерть!.. Увы, мне не дано изменить прошлое. Но я благодарна вам, за то что вам удалось воздать по заслугам убийцам моего внука." },
    ["389a"] = { common = "Ван Клиф и я были членами гильдии каменщиков. Это мы восстанавливали Штормград после войны. Когда мы закончили работу, вельможи отказались платить нам за неё. Руководителям гильдии предложили места на государственной службе, но ван Клиф отказался, потому что превыше всего ценил интересы гильдии. Он поднял мятеж и покинул город, поклявшись отомстить. Его лейтенант, Базиль Тредд, много знает о планах своего командира. Базиль содержится в плену в тюрьме." },
    ["389c"] = { common = "Чего, во имя Света, тебе надо? Не видишь, тут и без тебя проблем хватает? Базиль Тредд?! Какое тебе дело до этого мерзавца? Или ты – из его поганых кровавых соратничков? Не будь у меня тут все камеры заняты, я бы тебя точно засунул в одну из них!" },
    ["391a"] = { common = "Скажу тебе сразу: я тебе ни капли не доверяю. Но в нынешней ситуации это не особо важно. Что от тебя требуется: иди и поговори с Треддом. Если ты и вправду на нашей стороне, убей его и принеси мне его голову. А если ты на их стороне и не вернёшься вовремя, то будешь долго, долго гнить заживо…" },
    ["391c"] = { common = "Без Тредда бунтовщики станут куда более управляемыми. Посмотрим... Должен сказать, я уже через полчаса решил, что больше тебя не увижу… но, надо признать, я в тебе ошибся. Думаю, тебе не удалось из него ничего вытянуть... А вот я знаю пару вещей насчёт деятельности Тредда, которые тебя могут заинтересовать." },
    ["392a"] = { common = "Во время первого года заключения Тредда никто его не навещал. Мне казалось, что братство отказалось от него, поскольку он стал бесполезен. Но пару месяцев назад его стали постоянно навещать – раз, два в неделю. Посетитель был весьма странный. Такой тихий тип. У меня возникли подозрения, но все его документы были в полном порядке. Согласно документам, звали его Мелик; вот его описание. Не думаю, что он ещё когда-нибудь придёт к Тредду." },
    ["392c"] = { common = "Мелик? Нет, это имя мне незнакомо и даже ни на какие мысли не наводит. Это может быть кто угодно! Бывший каменщик, один из членов Братства Справедливости... Хотя если он тесно связан с ними, как предполагает Телуотер, кто-нибудь может опознать его. Мне нужно подумать." },
    ["393a"] = { common = "Знаете ли, мне так ничего и не пришло в голову. Зато я придумал, кто может нам помочь; если так и случится, я буду гордиться собой, но не стоит на это закладываться. Матиас Шоу из ШРУ – его можно найти в казармах Старого города. Шоу знает все уголки и закоулки этого города, всю его подноготную и тайные делишки. Если кто-то и знает, о ком речь, то только он." },
    ["393c"] = { common = "Что это? Да, думаю, что знаю этого человека, но его зовут вовсе не Мелик. Наёмные убийцы носят много масок, зовутся множеством имён и забывают их, как только они становятся не нужны. Этот человек также известен под именем Марзон; вероятно, это его очередной псевдоним. В общем, он – наёмный убийца, и я о нём довольно много знаю. Марзон сейчас работает на Грегора Лесковара – человека с репутацией, дурной даже для коррумпированного лорда Штормграда." },
    ["394a"] = { common = "Найдите Шоу в Старом городе. Дайте ему знать, что с Лесковаром покончено, и о вашей причастности к заговору лордов против города. Я думаю, он будет рад, что среди горожан Штормграда есть ещё герои. Думаю, он отправит вас на встречу с принцем или другим лордом. Не позволяйте им запудрить вам мозги. Власть имущие думают, что могут творить в городе что угодно, но пока они не всесильны." },
    ["394c"] = { male = "Значит, мёртв? Ты скор на расправу. Не хотел бы я стать твоим врагом. Смеётся и кладёт руку вам на плечо. Не прими за осуждение. Я же глава наёмных убийц, как я могу осуждать тебя за чистое убийство? По правде сказать, ты оказал людям Штормграда огромную услугу, и я благодарю тебя за это.", female = "Значит, мёртв? Ты скора на расправу. Не хотел бы я стать твоим врагом. Смеётся и кладёт руку вам на плечо. Не прими за осуждение. Я же глава наёмных убийц, как я могу осуждать тебя за чистое убийство? По правде сказать, ты оказала людям Штормграда огромную услугу, и я благодарю тебя за это." },
    ["395a"] = { common = "Ах, да... Пока тебя не было, приходил Алекстон, хотел с тобой поговорить. Должно быть, это касалось Братства Справедливости. Позволь дать тебе совет: на твоём месте я бы по первой просьбе рассказал обо всём произошедшем в подробностях. Но при этом упомяни, что Лесковара сразила именно твоя рука. Можешь мне верить – я на таких вещах собаку съел. А что касается Триаса... ну, не говори о нём. Никогда. Если сможешь." },
    ["395c"] = { common = "Приятно тебя видеть снова. Мне довелось услышать о недавней кончине лорда Грегора Лесковара. Значит, твоя миссия оказалась успешной. Я щедро награжу тебя за спасение и меня, и многих прочих от мести ван Клифа." },
    ["396a"] = { common = "Я готовлю донесение для короля. Надеюсь, ты сумеешь преподнести его величеству всё в лучшем виде. Не переживай так, король обязательно оценит твоё благородное служение народу Штормграда и достойно наградит тебя. Срок твоей аудиенции близок, так что поторопись, чтобы не опоздать в Крепость Штормграда." },
    ["396c"] = { male = "Я щедро награжу вас за службу Штормграду. Если ван Клиф преуспел в своих махинациях, то у нас ещё будет немало трудностей. Этого мы должны избежать. Возьмите этот жетон в знак королевской благосклонности, герой.", female = "Я щедро награжу вас за службу Штормграду. Если ван Клиф преуспел в своих махинациях, то у нас ещё будет немало трудностей. Этого мы должны избежать. Возьмите этот жетон в знак королевской благосклонности, героиня." },
    ["397a"] = { male = "Я слышал, что Лорд Вишлок в восторге от напитка. Ты нам здорово помог. Теперь чернокнижники Штормграда смогут заниматься своим делом без помех. За свою службу ты получишь достойный подарок. Поговори с Згги, моим слугой.", female = "Я слышал, что Лорд Вишлок в восторге от напитка. Ты нам здорово помогла. Теперь чернокнижники Штормграда смогут заниматься своим делом без помех. За свою службу ты получишь достойный подарок. Поговори с Згги, моим слугой." },
    ["397c"] = { male = "Хозяин дал подарок для путник. Згги хотел бы оставить его себе, но Згги знает, что будет, если предать хозяина.", female = "Хозяин дал подарок для путница. Згги хотел бы оставить его себе, но Згги знает, что будет, если предать хозяина." },
    ["398a"] = { common = "Разыскивается: Червеглаз! Ужасное даже по меркам гноллов чудовище – Червеглаз – приговорён к смерти за его преступления против Отрёкшихся. Этот гнусный злодей воровал трупы для армии Короля-лича. Червеглаза видели близ Фермы Гаррена, к северу от Брилла. Город Брилл предлагает награду всякому, кто сумеет прикончить негодяя и предъявить палачу Зуганду его лапу. Милосердие – удел слабых." },
    ["398c"] = { common = "Наконец-то Червеглаз получил по заслугам. Пусть твой поступок запомнится всем, кто захочет навредить нашему народу! Благодарю тебя от имени всего города Брилла." },
    ["399a"] = { common = "С тех пор как я мальчишкой работал на ферме в Западном Крае, прошла целая вечность. Говорят, нельзя вернуться в прошлое – и это верно. Дважды верно, если говорить обо-мне – ведь мой родной дом был разграблен ворами и сожжён. Я спросил у отца о судьбе некоторых моих вещей, например, о моём первом компасе. Отец не мог его захватить при бегстве, но сказал, что компас спрятан где-то на ферме. Усадьба Алекстона расположена к западу от Сторожевого холма. Может быть, ты найдёшь мой компас?" },
    ["399c"] = { common = "Благодарю вас! Совершенно бесполезная вещь, не считая воспоминаний... Нет слов, как я благодарен за то, что принесли мне этот предмет; вам, конечно, трудно понять цену памяти о Западном Крае. Возьмите это в знак моей признательности..." },
    ["400a"] = { common = "Белдин Сталежар владеет местной ремонтной мастерской, и он лучший техник по осадным машинам! Но своего инструмента он не жалеет. Могу побиться об заклад, его тангенциальные вращатели выходят из строя быстрее, чем мы успеваем поставлять ему новые! Мы только что выполнили его очередной заказ. Если ты его доставишь, я уверен, мастер заплатит тебе за труды. Ты сможешь найти Сталежара к северо-востоку от Караноса. Кстати, это излюбленное местечко ветеранов-водителей осадных машин, так что держи ухо востро, когда там будешь, – вдруг какая работёнка подвернётся." },
    ["400c"] = { male = "У тебя мои инструменты? Отлично, парень, отлично! Я только что сломал последний зубчатый храповик, и мне нужен другой, чтобы закончить ремонт осадной машины для пилота Камнекожца. Славно, что ты принёс мне эти инструменты. Вот, возьми эти деньги; спасибо!", female = "У тебя мои инструменты? Отлично, девчушка, отлично! Я только что сломал последний зубчатый храповик, и мне нужен другой, чтобы закончить ремонт осадной машины для пилота Камнекожца. Славно, что ты принесла мне эти инструменты. Вот, возьми эти деньги; спасибо!" },
    ["401a"] = { common = "Я почти закончил работу над переводом записки. Она будет готова через несколько минут." },
    ["401c"] = { common = "Ну вот. Готово… Вокруг воцаряется душная тишина, словно на лес опустился тёмный тяжёлый полог..." },
    ["404a"] = { common = "Плеть проникла в Тирисфальские леса и заполонила всю местность к западу от Брилла, возле старого моста. Отправляйся туда и загони этих гниющих мертвецов обратно в землю, откуда они вылезли. Разбросай их кости и принеси их гнилые когти – за них ты получишь награду от стражей смерти." },
    ["404c"] = { common = "Отличная работа. Жаль, я не видел, как ты расправляешься с этими гнусными тварями!" },
    ["405a"] = { male = "Бетор Ледострел, высокопоставленный и могущественный маг из Подгорода, что к югу отсюда, приказал мне прислать ему того, кто готов бороться с Плетью. Ты, как раз подходишь для этого. Отнеси эти приказы Бетору, а он расскажет, в чём состоит твоя миссия. Деталей я не знаю, могу сказать лишь то, что речь пойдёт о вербовке заблудшего лича. Это очень опасное дело. Приготовься как следует, герой. Не подведи нас. Бетора можно найти в квартале Магов Подгорода.", female = "Бетор Ледострел, высокопоставленный и могущественный маг из Подгорода, что к югу отсюда, приказал мне прислать ему того, кто готов бороться с Плетью. Ты, как раз подходишь для этого. Отнеси эти приказы Бетору, а он расскажет, в чём состоит твоя миссия. Деталей я не знаю, могу сказать лишь то, что речь пойдёт о вербовке заблудшего лича. Это очень опасное дело. Приготовься как следует, героиня. Не подведи нас. Бетора можно найти в квартале Магов Подгорода." },
    ["405c"] = { common = "А, так тебя прислал мировой судья Севрен. Тогда да, дело у нас с тобой очень важное. Уверен, Севрен выбрал того, кто справится с моим заданием, но… ладно, посмотрим." },
    ["407a"] = { common = "Безвредные тыковки, да? Это только так кажется. Если мы хотим победить силы Артаса на севере и нашествие людей на юге, нам нужно извлечь всю пользу из нашего дара нежития. Чуть-чуть смекалки, и простая тыква превратится в шпиона Тёмной Госпожи. С помощью моей последней формулы эта тыква станет лакомым блюдом. Вот недавно мы поймали ещё одного ревнителя из Алого ордена, сейчас он сидит в погребе таверны \"Петля Висельника\". Иди, отнеси ему эту тыкву." },
    ["407c"] = { common = "Благословенный Свет! Наконец-то еда! Сладенькая тыквочка..." },
    ["408a"] = { male = "Мельницы Агамондов превратились в крепость Плети. Самая важная точка – это семейная усыпальница Агамондов, где устроил штаб их местный лидер, скелет, которого называют капитаном Дарголом. С помощью некромантии он поднял предков рода Агамондов и собирается использовать их против нас. Ты не должен допустить этого. Отправляйся в склеп Агамондов и убей их неупокоенных предков. А заодно принеси мне череп капитана Даргола.", female = "Мельницы Агамондов превратились в крепость Плети. Самая важная точка – это семейная усыпальница Агамондов, где устроил штаб их местный лидер, скелет, которого называют капитаном Дарголом. С помощью некромантии он поднял предков рода Агамондов и собирается использовать их против нас. Ты не должна допустить этого. Отправляйся в склеп Агамондов и убей их неупокоенных предков. А заодно принеси мне череп капитана Даргола." },
    ["408c"] = { common = "Твои действия нанесли Плети ощутимый удар! И твоя победа не будет забыта ни Отрёкшимися, ни врагами. Продолжай бороться вместе с нами, и когда-нибудь мы изгоним Короля-лича из Азерота!" },
    ["409a"] = { male = "Ты говоришь, что неподвластен воле Короля-лича, и чары, которые Бетор наложил на мою книгу, это подтверждают. Но прежде чем я поверю тебе,ты должен доказать то, что являешься врагом Плети. На южном берегу этого острова находится старый окровавленный алтарь, которым пользуется адепт Плети – Лилит Нефара. Возьми из этого ящика манящую свечу, зажги её на алтаре, и Лилит пробудится. Убей её, и я поверю, что ты – враг Короля-лича.", female = "Ты говоришь, что неподвластна воле Короля-лича, и чары, которые Бетор наложил на мою книгу, это подтверждают. Но прежде чем я поверю тебе,ты должна доказать то, что являешься врагом Плети. На южном берегу этого острова находится старый окровавленный алтарь, которым пользуется адепт Плети – Лилит Нефара. Возьми из этого ящика манящую свечу, зажги её на алтаре, и Лилит пробудится. Убей её, и я поверю, что ты – враг Короля-лича." },
    ["409c"] = { common = "Невероятно! Ты убил Лилит Нефару и тем самым доказал, что являешься врагом Плети! Я думал, что я – единственный из нежити, обладающий свободой воли, но теперь вижу, что есть и другие, кто не поддался влиянию Короля-лича." },
    ["411a"] = { common = "Отнеси этот самоцвет Пустоты моему старому товарищу Бетору. С его помощью мы сможем общаться, а мне очень многое надо ему сказать." },
    ["411c"] = { male = "Ты убедил его присоединиться к нам! Это огромная радость для всех Отрёкшихся. Я доложу об этом Тёмной Госпоже.", female = "Ты убедила его присоединиться к нам! Это огромная радость для всех Отрёкшихся. Я доложу об этом Тёмной Госпоже." },
    ["412a"] = { common = "При дальнейшем анализе гномреганской ситуации оказалось, что нам не только не удалось извести троггов, но мы случайно превратили большую часть представителей нашей расы в ужасающих, безмозглых, злобных лепрогномов! Мы с Оззи намерены направить в обратную сторону ужасный эффект лепры при помощи нашего последнего изобретения – перенаправлятора. Эта машина почти закончена, но нам чрезвычайно нужны зубцы рестабилизации и гиромеханические шестерни. Добудь их у лепрогномов, которые обитают около Гномрегана, и принеси нам!" },
    ["412c"] = { common = "Эти гиромеханические шестерни и зубцы рестабилизации прекрасно подходят к чертежу Оззи для устройства Перенаправления. Как только я залью гидросмазку во внутренние клапаны сгорания, подкручу кривохраповик и повышу вязкость электрогуммигеля, раса гномов будет возрождена." },
    ["413a"] = { common = "Хотелось бы мне, чтобы мой братец Велларт попробовал свежего \"Мерцающего портера\". Он горный пехотинец, их расквартировали в южной сторожевой башне, одной из двух на границе с озером Лок Модан. Может, он и не такой пивовар, как остальные Ячменовары, но своё пиво он любит, и я знаю, что это тоже ему понравится. Не отнесёшь ему вот этот бочонок \"Мерцающего портера\"?" },
    ["413c"] = { common = "Горный пехотинец Ячменовар пробует \"Мерцающий портер\"... Ох-х. Аж искры из глаз! Кажется, я даже в темноте видеть могу!" },
    ["414a"] = { common = "Я бы и ещё отхлебнул \"Мерцающего портера\" с пивоварни моего братца – забористое же пойло! Но я хочу, чтобы мой приятель-пехотинец попробовал его. Зовут парня Кэдрелл, и он обычно патрулирует дорогу через Телсамар в озере Лок Модан. Чтобы добраться до Телсамара, иди на юго-восток через туннель, затем на развилке возьми на северо-восток. И по той дороге иди прямо до Телсамара. Отдай горному пехотинцу Кэдреллу этот бочонок \"Мерцающего портера\", и посмотрим, что он скажет!" },
    ["414c"] = { common = "Ну-с, попробуем... Клянусь бородой Магни! Аж голова кругом пошла! И в теле лёгкость необыкновенная. Сейчас полечу, как птичка!" },
    ["415a"] = { male = "Регольд Ячменовар, что живёт в Посёлке Пивоваров, спрашивал про тебя. Он хочет поговорить с тобой про своё новое пиво... Сказал вроде, что ты ему помог. Можешь самолично вернуться в Посёлок Пивоваров и спросить, что ему надо. Может, тебя дармовая выпивка ждёт...", female = "Регольд Ячменовар, что живёт в Посёлке Пивоваров, спрашивал про тебя. Он хочет поговорить с тобой про своё новое пиво... Сказал вроде, что ты ему помогла. Можешь самолично вернуться в Посёлок Пивоваров и спросить, что ему надо. Может, тебя дармовая выпивка ждёт..." },
    ["415c"] = { male = "Помнишь тот звездолист, что ты принёс мне? Ну так я его использовал в новых рецептах, над которыми работал, и в одном случае вышло просто великолепно! Вот, попробуй и скажи, как пошло...", female = "Помнишь тот звездолист, что ты принесла мне? Ну так я его использовал в новых рецептах, над которыми работал, и в одном случае вышло просто великолепно! Вот, попробуй и скажи, как пошло..." },
    ["416a"] = { common = "К западу отсюда началось настоящее нашествие. Эти крысы, кобольды-туннельщики, обосновались в предгорьях, устроили там свои логовища и оскверняют нашу прекрасную землю! Их необходимо истребить. Перебей их как можно больше, принеси в доказательство уши и получишь награду. Кобольды-туннельщиков поселились к западу от Телсамара вдоль горных склонов." },
    ["416c"] = { common = "Фу! Когда я просил принести уши, я не подозревал, что они так дурно пахнут! Прими награду. Молодчина." },
    ["417a"] = { common = "Хилдельв пишет в своём журнале, что подвергся нападению Паршивого Когтя, \"огромного медведя-ледолапа\". Он отогнал тварь, но та успела страшно изранить его. Судя по состоянию трупа Хилдельва, Паршивый Коготь, видимо, вернулся и добил его. В журнале Хилдельв записал своё последнее пожелание: \"Отомстить Паршивому Когтю.\"" },
    ["417c"] = { common = "Злая весть. Хилдельв был хорошим другом. Жаль, что не довелось мне с тобой пойти на этого Паршивого Когтя! Спасибо тебе. Пилоты Осадной бригады Стальгорна тебя не забудут." },
    ["418a"] = { male = "Едоки в Телсамаре не переводятся – ещё бы, детей полным-полно, после трудового дня работники ужинать хотят. Мы славимся кровяными колбасками... Но ты ведь их ещё не пробовал? Нет? Что же, у нас принято отрабатывать еду, и не думаю, что за красивые глазки тебе сделают исключение. Мне понадобится медвежатина, кишки кабана на оболочки и паучья лимфа для остроты. Добудь всё это, а уж Видра сготовит всё в лучшем виде!", female = "Едоки в Телсамаре не переводятся – ещё бы, детей полным-полно, после трудового дня работники ужинать хотят. Мы славимся кровяными колбасками... Но ты ведь их ещё не пробовала? Нет? Что же, у нас принято отрабатывать еду, и не думаю, что за красивые глазки тебе сделают исключение. Мне понадобится медвежатина, кишки кабана на оболочки и паучья лимфа для остроты. Добудь всё это, а уж Видра сготовит всё в лучшем виде!" },
    ["418c"] = { common = "Поверь, со стороны готовка выглядит куда сложнее, чем на деле, но... Хоть я и не встречала никого, кому бы захотелось научиться делать колбаски, но на всякий случай рецептик я тебе всё же дам. Бери! Ешь, пока рот свеж!" },
    ["419a"] = { common = "Мой друг и напарник, пилот Осадного орудия Мори Хилдельв, пропал в этих холмах. Мы искали там редкую руду, необходимую для высококачественного пороха, и во время поисков мы загнали его танк на крутой холм и он сломался! Хилдельв, по-прежнему уверенный, что руда в тех горах есть, оставил меня охранять наши танки, а сам пошёл дальше пешком. Прошло уже несколько дней, а я слышал ночью какой-то звериный вой в холмах. Мори – парень-кремень, но мне тревожно. Прошу тебя, найди его." },
    ["419c"] = { common = "Перед вами труп дворфа – изуродованный, застывший и сильно обглоданный горными хищниками. В руке он сжимает записную книжку с грубо нацарапанными записями Мори Хилдельва. Труп одет во всё ещё превосходно сохранившийся жилет бригадира. Эта мрачная сцена показывает, где встретил свой конец пилот Осадной машины." },
    ["420a"] = { common = "Трогги, поселившиеся в тоннелях, крайне враждебны: они без раздумий нападают на любого, кто только осмелится туда сунуться. С другой стороны, что-то мне подсказывает, что у тебя хватит сил и умения, чтобы с ними справиться. Если тебе хочется побеседовать с Сениром, то его можно отыскать в Караносе. А добраться туда и вовсе просто: пройдёшь весь тоннель насквозь, а дальше шагай себе по дороге до самого до города Караноса." },
    ["420c"] = { common = "А что это у нас тут такое? О, донесение от моего братца! Хм-м... Говорил я ему, нечего поминать королевское имя всуе, да только станет он меня слушать! С другой стороны, кое-кому в Совете не мешает попортить кровь. Ха! Как бы то ни было, думаю, мне нужно и своё донесение отправить в Стальгорн. Как-то запоздал я с этим делом. Всё этот проклятый холод! Слушай, если тебе это интересно, у меня скоро может найтись для тебя кое-какая работёнка..." },
    ["421a"] = { common = "Леди Сильвана поручила Вариматрасу завоевать земли людей и дворфов к югу. Но этот идиот Аругал – даларанский шарлатан, а ныне проклятая тварь из крепости Тёмного Клыка – позволил своей бездумной магии нанести ущерб стратегической цитадели Серебряного бора. Мне нужен кто-то, искушённый в воинском деле, чтобы разрубить узел, завязанный Аругалом. Убейте пять белоголовов Лунной Ярости и докажите, что вы – тот, кого я ищу. Этих мерзких зверей легко можно встретить у самой дороги, внизу под холмом." },
    ["421c"] = { male = "Вы сослужили мне хорошую службу, герой. Для меня очевидно, что вы будете достойным помощником – я готовлюсь избавить Серебряный бор от проклятья Аругала.", female = "Вы сослужили мне хорошую службу, героиня. Для меня очевидно, что вы будете достойным помощником – я готовлюсь избавить Серебряный бор от проклятья Аругала." },
    ["422a"] = { common = "Для меня загадка, каким образом Аругал вообще был принят в Кирин Тор. Его знания касательно применения заклинаний были просто мыльным пузырём. Сейчас важно точно выяснить, какую магию применил Аругал, чтобы я мог использовать её против него и обеспечить владычество Тёмной Госпожи в Серебряном бору. Вначале Аругал останавливался на пшеничной ферме, что к северу от моста. Один из стражей смерти сообщил о том, что видел какие-то книги с заклинаниями, но не сумел их заполучить. Добудьте для меня ту из этих книг, которая называется \"Зелье Аругала\"." },
    ["422c"] = { male = "Да, это именно та книга, которую я искал, герой. Если ваша приверженность делу Тёмной Госпожи не ослабела, вас ждёт неплохое будущее среди Отрёкшихся.", female = "Да, это именно та книга, которую я искал, героиня. Если ваша приверженность делу Тёмной Госпожи не ослабела, вас ждёт неплохое будущее среди Отрёкшихся." },
    ["423a"] = { common = "Изучив деятельность Аругала я понял, что мои наихудшие подозрения верны. Старый хрыч был недостоин даже ночные горшки выносить в Даларане, не говоря уж о том, чтобы представлять Кирин Тор в самый трудный час. Идиоты! Для усиления своей никудышной магии Аругал использовал заколдованные предметы. В первую очередь я должен изучить эти предметы. Отправляйтесь в путь и убивайте обжор Лунной Ярости и тёмных духов Лунной Ярости, пока не наберёте достаточного для моих исследований количества их заколдованных наручей. Эти злобные создания обитают к северу и к востоку отсюда." },
    ["423c"] = { male = "Надеюсь, что смогу выжать достаточно энергии из столь ограниченного количества материала. Вероятно, мне следовало поручить вам добыть больше наручей. Тем не менее, вы отменно проявили себя, собирая эти, герой.", female = "Надеюсь, что смогу выжать достаточно энергии из столь ограниченного количества материала. Вероятно, мне следовало поручить вам добыть больше наручей. Тем не менее, вы отменно проявили себя, собирая эти, героиня." },
    ["424a"] = { common = "Мне потребуется больше времени на раскрытие тёмных тайн чар Аругала,чем я думал. Но тем временем мне нужно, чтобы вы помогли разрешить одну небольшую проблему, которую обнаружили наши разведчики. Похоже, Аругал распространил свою магию на Серебряный рудник, находящийся в холмах к юго-востоку отсюда. Этот рудник стал бы ценным ресурсом для Вариматраса. Я хочу, чтобы вы снесли голову с плеч поражённому скверной старшине рудника Мрачнону Белёсому. После его смерти рудник будет нашим." },
    ["424c"] = { common = "Великолепно. Рудник обеспечит нас отменными ресурсами для наших сил по мере нашего продвижения по Серебряному бору и далее по Азероту." },
    ["425a"] = { common = "Нам с моим братом Квинном было поручено провести рекогносцировку в Серебряном бору и отчитаться перед верховным палачом Хадриком. Но далеко продвинуться мы не сумели: когда мы проходили через эту ферму, нас атаковал вурдалак Ивар Нечистый. Нам удалось уйти от Ивара, но он успел как следует приложить Квинна. Мой брат поправляется от зелья, что вы ему дали, но Ивар может вернуться раньше, чем Квинн совсем встанет на ноги. Убейте Ивара, чтобы Квинн мог спокойно поправляться. Обычно Ивар торчит в том амбаре – поджидает, когда я утрачу бдительность." },
    ["425c"] = { common = "О, спасибо. Я очень благодарна вам. Я упомяну ваше имя в отчёте, который направлю своему вышестоящему начальству." },
    ["426a"] = { common = "Плеть пытается основать базу на мельницах Агамондов. Если им это удастся, они продолжат свои нападения в Тирисфале. Поступил приказ уничтожить всю Плеть на мельницах. Отправляйся туда и собери зазубренные рёбра костетрясов-солдат и костеголовых солдат, а также почерневшие черепа мрачнооких скелетов-заклинателей. Чтобы добраться до мельниц, иди по дороге на запад. После того как перейдёшь мост, поверни на север, и скоро увидишь ветряные мельницы." },
    ["426c"] = { common = "Твои старания не прошли даром! Я не буду благодарить тебя за исполнение долга, но стражи смерти Тирисфаля навсегда запомнят твоё имя!" },
    ["427a"] = { male = "Документы, которые прислал палач Аррен, приблизят переломный момент в нашей битве с мерзким Алым орденом. Теперь мы знаем расположение всех их баз в Тирисфальских лесах. Но у стражей смерти есть заботы и поважнее: армия Короля-лича растёт с каждой ночью. Нам нужен кто-то такой \"инициативный\", как ты, чтобы навсегда покончить с Алым орденом. Докажи мне, что способен служить Тёмной Госпоже: отправляйся на запад, к башне за фермой Соллидена, и убей десять воинов из Алого ордена.", female = "Документы, которые прислал палач Аррен, приблизят переломный момент в нашей битве с мерзким Алым орденом. Теперь мы знаем расположение всех их баз в Тирисфальских лесах. Но у стражей смерти есть заботы и поважнее: армия Короля-лича растёт с каждой ночью. Нам нужен кто-то такой \"инициативный\", как ты, чтобы навсегда покончить с Алым орденом. Докажи мне, что способна служить Тёмной Госпоже: отправляйся на запад, к башне за фермой Соллидена, и убей десять воинов из Алого ордена." },
    ["427c"] = { male = "Замечательно, герой. Ваши боевые умения не вызывают сомнений.", female = "Замечательно, героиня. Ваши боевые умения не вызывают сомнений." },
    ["428a"] = { common = "Пару недель назад двое наших стражей смерти – Ран и Квинн Йорик, ушли на разведывательное задание в северный Серебряный бор. С тех пор от них не было никаких известий. Они могли стать жертвами Плети, но даже если это так, мне нужно подтверждение. Найдите этих стражей смерти. Их первой целью была разведка на полях в северной части Серебряного бора. Начните свои поиски там." },
    ["428c"] = { common = "Вы нашли нас! Ещё чуть-чуть – и было бы уже поздно..." },
    ["429a"] = { common = "Моего брата Квинна серьёзно ранил вурдалак Ивар Нечистый. Боюсь, без алхимической помощи он теперь не исцелится. Я мало что понимаю в лекарском искусстве, но знаю, что наши аптекари умеют варить целительные зелья из обесцвеченных сердец воргов. Добудь такие сердца и отнеси их аптекарю Ренферрелу в гробницу к югу отсюда. Потом возвращайся с зельем. Множество воргов водится на пути к Саду Мальдена, что к востоку." },
    ["429c"] = { common = "Ренферрел берёт у вас сердца. Меня тревожит известие о том, что наши стражи смерти потерпели неудачу в своей миссии. Будем надеяться, что таких неудач будет немного. Я сейчас дам зелье, но вот вам рецепт – если стражам смерти понадобится дальнейшая помощь, быть может, вы сами сможете им её оказать." },
    ["430a"] = { common = "Вот зелье, которое должно помочь Квинну Йорику поправиться. А теперь, простите, мне нужно продолжить одно очень важное дело..." },
    ["430c"] = { common = "Квинн выпивает зелье. Да, я чувствую его действие. Вскоре я снова смогу передвигаться. Вы оказали мне большую услугу." },
    ["432a"] = { common = "Эти проклятые Светом трогги перевернули всё моё рабочее место! Ты только глянь, ещё одну бочку пороха разворотили! Ох, прямо руки чешутся спуститься к ним да головы поотрывать! Всех бы поубивал! Но здоровье не позволяет, да ещё это потрясение и злость... Они ничего мне не оставили! Я бы сам их перебил, да рука уже не так тверда! Иди в карьер и перебей грязных тварей! Я заплачу! Ты только задай им шороху, перебей их!" },
    ["432c"] = { common = "Ох, на душе полегчало... Но я не успокоюсь, пока все трогги не будут уничтожены! Все до единого!" },
    ["433a"] = { common = "Будучи членом Сената и Лиги Исследователей, я взял на себя заботу об искоренении троггской заразы, наводнившей наши земли. Они ни за что ни про что разнесли карьер Гол'Болар. Чем глубже мы копаем, тем больше их лезет наружу, уничтожая наше оборудование и выгоняя горняков из шахт. У нас нет выбора, кроме как истребить их как можно больше, отстроиться заново и вернуться к работе. Если вы поможете мне разобраться с троггами, я с радостью возмещу вам затраты времени." },
    ["433c"] = { common = "Это только начало. Надеюсь, мы сможем воспользоваться преимуществом, и выделим небольшой контингент горных пехотинцев для защиты этого района. Тогда мы сможем начать восстановление инфраструктуры и вернуть горняков к работе. Спасибо тебе за помощь." },
    ["434a"] = { male = "Сейчас я переодену своего робота-шпиона, и он отправится на аудиенцию к Лесковару. Гвардия пропустит его без особых проблем. Пока ты собирал для меня материалы, я дал Марзону идейку, которую он непременно захочет обсудить с Лесковаром. Я даже подкинул ему пару ложных слухов. Лесковар отпустит свою охрану и будет дожидаться Марзона в саду. Начинай действовать, как только они заведут разговор о Братстве Справедливости. Убей обоих до возвращения гвардейцев! После этого поговори с Триасом.", female = "Сейчас я переодену своего робота-шпиона, и он отправится на аудиенцию к Лесковару. Гвардия пропустит его без особых проблем. Пока ты собирала для меня материалы, я дал Марзону идейку, которую он непременно захочет обсудить с Лесковаром. Я даже подкинул ему пару ложных слухов. Лесковар отпустит свою охрану и будет дожидаться Марзона в саду. Начинай действовать, как только они заведут разговор о Братстве Справедливости. Убей обоих до возвращения гвардейцев! После этого поговори с Триасом." },
    ["434c"] = { male = "Сделано? Отлично. путник, благодарю вас за посильное участие. Вы оказали Штормовому Оплоту не одну услугу. С вашего позволения, я буду приглядывать за вами: вы можете славно послужить делу Альянса. Постарайтесь ни во что не вляпаться.", female = "Сделано? Отлично. путница, благодарю вас за посильное участие. Вы оказали Штормовому Оплоту не одну услугу. С вашего позволения, я буду приглядывать за вами: вы можете славно послужить делу Альянса. Постарайтесь ни во что не вляпаться." },
    ["435a"] = { common = "Волки там, снаружи, никуда не уйдут, и они злобно смотрят на меня каждый раз, когда я выхожу из двери. Должно быть, они невероятно голодны, раз смогли счесть меня пищей. Я должен доложиться своей коллеге, стражу смерти Ран Йорик. Но чтобы добраться до Ран, мне нужна помощь против этих волков. Пожалуйста, проводите меня! Волков здесь очень много, так что наши шансы будут выше, если у вас есть готовые помочь друзья..." },
    ["435c"] = { common = "Спасибо за помощь. Я боялась, что Эрланда погубили опасности Серебряного бора. Но я вижу, что благодаря вашей помощи этого не произошло." },
    ["436a"] = { common = "Геолог Сталекрут возглавляет раскопки в древних руинах к востоку от озера. В последнее время дело продвигается медленно – и это учитывая, сколько мы послали туда припасов! Сталекрут – надёжный, честный дворф, который прежде всего болеет за результат, потому-то я и думаю, что кто-то решил ему помешать. Отправляйся к раскопкам Сталекрута и обратись к Магмару Рудоколу. Он ведёт отчётность по раскопкам и сможет объяснить, чем вызвана задержка. Чтобы отыскать раскопки, обогни озеро с юга и направляйся на восток." },
    ["436c"] = { common = "Значит, Джерн хочет узнать, чем вызвана задержка? Железняк как раз пишет подробный отчёт о своих последних достижениях, но я буду краток. Дело в троггах!!!" },
    ["437a"] = { common = "Первые отчёты наших разведчиков в Серебряном бору говорят о том, что Гнилошкуры устроили базу на заброшенном поле к северу отсюда – на Мёртвом поле. Мы посылали против них небольшие группы, но им каждый раз помогала банши Плеть Ночи, которая своей магией обращала наших воинов в бегство. Мы хотим уничтожить Плеть Ночи. Отправляйтесь на Мёртвое поле и атакуйте Гнилошкуров. Убивайте их до тех пор, пока не покажется Плеть Ночи, а затем убейте и её. Сущность банши обратится в прах. Принесите мне этот прах в доказательство её смерти." },
    ["437c"] = { common = "Я слышал о вашем успешном набеге на гноллов-гнилошкуров, а эта сущность является доказательством смерти банши Плеть ночи. Сегодня Король-лич потерял ещё одного прислужника. Вы становитесь ещё более ценным союзником в глазах Отрёкшихся." },
    ["438a"] = { common = "Мы обнаружили ещё одно место, где угнездилась Плеть: это старая переправа. Переправа находится к востоку от Гробницы, и её патрулируют многочисленные гноллы-гнилошкуры и различная нежить. Полагаю, Плеть захватила это место неспроста. Отправляйтесь к старой переправе и выясните, в чём там дело." },
    ["438c"] = { common = "В лодке находится куча спелёнутых мёртвых тел. А если смотреть на восток через озеро Лордамер, то напротив видна пристань на острове Фенриса. Должно быть, разгадку этой тайны стоит искать на острове." },
    ["439a"] = { common = "Из кучи трупов торчит обнажённая рука. Это рука женщины – тронутая чумой, но относительно свежая. На пальце надето кольцо. Вы снимаете кольцо и, осмотрев его, обнаруживаете гравировку: \"Делии\"." },
    ["439c"] = { common = "Говорите, это кольцо было надето на палец недавно погибшей женщины? Видимо, тело было поднято из общей могилы в Тирисфале, не иначе. Должно быть, гноллы-гнилошкуры таскают эти трупы на остров Фенриса!" },
    ["440a"] = { common = "Если хотите найти мужа или возлюбленного Делии – того, кто подарил ей кольцо... поговорите с мировым судьёй Севреном в Брилле. У него должны быть записи о недавних смертях и, если повезёт, он сможет выяснить, кто такая Делия. Но я бы на это не рассчитывал. Тот, кто подарил ей кольцо, вероятно, уже мёртв. Или, если он стал нежитью, то, возможно, ему больше нет дела до Делии." },
    ["440c"] = { common = "Некая Делия жила в Брилле не так давно. Она была похоронена в общей могиле, но, если верить вашим словам, её тело, должно быть, похитили гноллы из стаи Гнилошкуров и утащили в Серебряный бор. Стая Гнилошкуров, как и вся Плеть, должна быть уничтожена. Я верю, что ты предпримешь к этому надлежащие шаги." },
    ["441a"] = { common = "У Делии был муж по имени Роли, проживающий ныне в Подгороде. Если кольцо действительно принадлежало Делии, которая жила здесь, в Брилле, то Роли узнает его. Найти Роли вы можете в Торговом квартале Подгорода." },
    ["441c"] = { common = "Да, это вещица моей жены. Её постигла та же участь, что и всех, кому не удалось пережить эти суровые времена. Меня не трогает её смерть, как не трогает и ваш рассказ о похищении её тела. Подобные чувства давно остыли во мне. Но желание всё ещё клокочет в моём мёртвом сердце. Желание отомстить." },
    ["442a"] = { male = "А теперь настало время для нападения на оплот силы Плети в Серебряном бору: остров Фенриса. Ты снова должен добраться до острова и уничтожить Тула Когтя Ворона. Мне нужна его голова! Я посылаю тебя на смертельно опасное задание, но выполнить его – жизненно важная задача. Ты должен выйти победителем!", female = "А теперь настало время для нападения на оплот силы Плети в Серебряном бору: остров Фенриса. Ты снова должна добраться до острова и уничтожить Тула Когтя Ворона. Мне нужна его голова! Я посылаю тебя на смертельно опасное задание, но выполнить его – жизненно важная задача. Ты должна выйти победительницей!" },
    ["442c"] = { common = "Смерть Тула Когтя Ворона – значимое событие. Ренферрел рассказывает, что потоки энергии, которые вы высвободили при уничтожении Тула, ощущались аж до Гробницы. Твои действия получили большой резонанс у Отрёкшихся. Твоя ценность в наших глазах растёт." },
    ["443a"] = { common = "Прежде чем мы совершим нападение на остров Фенриса, мы должны понять, кто стоит за Гнилошкурами. Наши аптекари считают, что их особенности связаны со странной жидкостью, текущей по их жилам. Отправляйся на остров Фенриса, к востоку от старой переправы, и собери лимфу гноллов-гнилошкуров, которых вы там встретите. Образцы нужны аптекарю Ренферрелу, который стоит неподалёку от Гробницы." },
    ["443c"] = { common = "Отлично. Эта лимфа поможет нам понять природу гноллов-гнилошкуров, а также сможет показать нам, в чём их слабость... ...если она у них есть..." },
    ["444a"] = { male = "Я выпарил лимфу, которую ты принёс мне, и разложил её на основные компоненты. Мои выводы ещё не окончательные, но я определил, что для изготовления этой лимфы пользовались как чернокнижием, так и некромантией. Пока я продолжу её изучение, я прошу тебя отнести один образец Бетору Ледострелу в Подгород. Бетор – не фармацевт, но его знание магии может помочь нам раскрыть тайну Гнилошкуров. Иди же. Бетора ты найдёшь в Квартале Магов Подгорода.", female = "Я выпарил лимфу, которую ты принесла мне, и разложил её на основные компоненты. Мои выводы ещё не окончательные, но я определил, что для изготовления этой лимфы пользовались как чернокнижием, так и некромантией. Пока я продолжу её изучение, я прошу тебя отнести один образец Бетору Ледострелу в Подгород. Бетор – не фармацевт, но его знание магии может помочь нам раскрыть тайну Гнилошкуров. Иди же. Бетора ты найдёшь в Квартале Магов Подгорода." },
    ["444c"] = { common = "Эта субстанция наполнена могучими заклинаниями, с некоторыми из которых я не сталкивался вот уже долгое время... Секундочку – мне придётся воспользоваться проясняющим заклинанием..." },
    ["445a"] = { male = "Время – это непозволительная роскошь для тех, кто служит леди Сильване. Ты это, конечно, уже и сам понял. Я состою в Королевском фармацевтическом обществе и в мои обязанности входит обмен знаниями с коллегами, чтобы однажды нашими совместными усилиями появилась новая чума, которую так желает получить Тёмная Госпожа. Отнеси эти находки аптекарю Ренферрелу – его можно найти в Гробнице, это поселение в Серебряном бору. Если идти из Брилла – то на юг, а если из Подгорода – на юго-запад.", female = "Время – это непозволительная роскошь для тех, кто служит леди Сильване. Ты это, конечно, уже и сама поняла. Я состою в Королевском фармацевтическом обществе и в мои обязанности входит обмен знаниями с коллегами, чтобы однажды нашими совместными усилиями появилась новая чума, которую так желает получить Тёмная Госпожа. Отнеси эти находки аптекарю Ренферрелу – его можно найти в Гробнице, это поселение в Серебряном бору. Если идти из Брилла – то на юг, а если из Подгорода – на юго-запад." },
    ["445c"] = { male = "А, как хорошо, что аптекарь Юхан прислал мне результаты своих исследований! Здесь, в Серебряном бору, происходит столько всего, что я совсем забыл про материалы из Лордерона и с Тирисфальских лесов. Кстати, надо бы поскорей отправить те образцы в Некрополь... Прости, Топот. Задержись в Серебряном бору чуть подольше, такой герой, как ты, всегда нам пригодится.", female = "А, как хорошо, что аптекарь Юхан прислал мне результаты своих исследований! Здесь, в Серебряном бору, происходит столько всего, что я совсем забыл про материалы из Лордерона и с Тирисфальских лесов. Кстати, надо бы поскорей отправить те образцы в Некрополь... Прости, Топот. Задержись в Серебряном бору чуть подольше, такая героиня, как ты, всегда нам пригодится." },
    ["446a"] = { common = "Эта лимфа была создана моим давним коллегой, Тулом Когтем Ворона. До великой войны он был молодым и многообещающим магом, но когда вошёл в силу Король-лич, Тул предал своих братьев и перешёл на сторону Плети. Я и не думал, что он всё ещё жив, и уж тем более – что он возглавляет набеги Гнилошкуров на нас! Я знаю многие из его заклинаний и могу помочь сварить зелье для того, чтобы им противостоять. Отнеси этот свиток обратно к аптекарю Ренферрелу. Там содержатся заклятья, необходимые для изготовления зелья." },
    ["446c"] = { common = "Этот свиток весь пронизан могущественной магией. Я никогда не использовал таких сил в зельях... это будет сильнодействующая микстура, и она должна сослужить тебе хорошую службу, если ты решишься атаковать Тула в его крепости на острове Фенриса." },
    ["447a"] = { common = "Силы Артаса неисчислимы. Но с Новой чумой мы могли бы раз и навсегда покончить как с армией Плети, так и с людьми. Мои исследования показали, что паучья кровь в соединении с токсином, извлечённом из сердца бешеного медведя, даёт смертельно опасный эликсир. Собери необходимые субстанции с пауков из Струящейся Тьмы к северо-западу отсюда и с медведей, бродящих по Серебряному бору. Принеси реагенты в Подгород мастеру-аптекарю Фаранеллу из Королевского фармацевтического общества." },
    ["447c"] = { common = "Аптекарь Ренферрел правильно сделал, что послал вас ко мне. Эти образцы действительно будут весьма полезны. Я немедленно начну изучить их отравляющие и инфицирующие свойства." },
    ["448a"] = { common = "Прежде чем вы нападёте на остров Фенриса, доложитесь верховному палачу Хадрику. У него может быть дополнительная информация о том, что вам понадобится." },
    ["448c"] = { common = "Если то, что говорит Бетор, – правда, то Тул Коготь Ворона представляет собой силу, с которой нужно разобраться, причём разобраться срочно. В качестве помощи можете подобрать себе что-нибудь из нашего здешнего арсенала..." },
    ["449a"] = { common = "Хотя раны Квинна заживают, я хотела бы доставить наш отчёт верховному палачу Хадрику как можно скорее. В нём содержится информация, которая жизненно важна для захвата Серебряного бора Отрёкшимися." },
    ["449c"] = { common = "Я не ожидал ни такого количества Плети, с каким мы столкнулись в Серебряном бору, ни проблем, которые возникли перед стражами смерти в ходе разведывательной операции. Ваша помощь нашим стражам смерти просто неоценима. Вы заслуживаете похвалы." },
    ["450a"] = { common = "Вы можете ещё послужить Королевскому фармацевтическому обществу. Когда Аругал навёл на лес свою никчёмную магию, он наложил проклятие на одного из наших самых многообещающих сотрудников, аптекаря Берарда. Ставший безвольным слугой Аругала, теперь Берард для нас бесполезен. Но его находки могут быть ценными. Он изучал древнюю чуму, давным-давно погубившую всякую жизнь в озере Лордамер. Раздобудьте записи Берарда из его кабинета в таверне деревни Погребальных Костров и принесите аптекарю Ренферрелу." },
    ["450c"] = { common = "Записи аптекаря Берарда! В смелости вам не откажешь. Теперь давайте посмотрим, чем занимался Берард прежде, чем сошёл с ума..." },
    ["451a"] = { common = "Согласно записям Берарда, мох озёрных тихоходов и озёрных ползунов может оказаться полезным для решения нашей задачи по изготовлению новой отравы. Эти твари обитают на островах на озере Лордамер на востоке. Он также упоминает об очень редкой субстанции – твёрдой опухоли, обнаруженной им у мурлока из племени Злобного Плавника. Очевидно, эта опухоль столь редка, что Берарду удалось раздобыть лишь одну. Соберите образцы моха, а также редкую твёрдую опухоль и отнесите их мастеру-аптекарю Фаранеллу в Подгород." },
    ["451c"] = { male = "Потеря Берарда – серьёзный удар для Королевского фармацевтического общества. Но благодаря вашим стараниям и усердным исследованиям аптекаря Ренферрела разработки Берарда по-прежнему будут полезны делу Тёмной Госпожи. Мы находимся на пороге чего-то великого путник. Если бы вы не были столь искусны в военном деле, я пригласил бы вас вступить в члены нашего Общества.", female = "Потеря Берарда – серьёзный удар для Королевского фармацевтического общества. Но благодаря вашим стараниям и усердным исследованиям аптекаря Ренферрела разработки Берарда по-прежнему будут полезны делу Тёмной Госпожи. Мы находимся на пороге чего-то великого путница. Если бы вы не были столь искусны в военном деле, я пригласил бы вас вступить в члены нашего Общества." },
    ["452a"] = { common = "Вы очень вовремя добрались сюда! Совет деревни Погребальных Костров вернётся в любой момент. Аругалу же есть чем заняться в крепости. Он использует совет как марионеток, чтобы держать лишённых разума и воли приспешников в деревне под своим полным контролем. Но я уверена, что без руководства совета деревни Погребальных Костров сыновья Аругала взбунтовались бы против своего хозяина. Я не могу справиться со всем в этим в одиночку. Мне нужна ваша помощь. Вместе мы сможем погубить совет, на благо леди Сильваны." },
    ["452c"] = { common = "Вы бились достойно настоящего последователя Тёмной Госпожи. Теперь, когда члены Совета мертвы, может быть, мы сможем восстановить контроль над этой деревней раз и навсегда и выбить Аругала из крепости Тёмного Клыка. Честь имею!" },
    ["453a"] = { common = "Удачи. Надеюсь, ты найдёшь этого парня, причём живым. Сбежав за пределы Темнолесья, он мог пасть жертвой диких зверей." },
    ["453c"] = { common = "Трясунчик вздыхает... Да, автор этой книги – я. Сумел-таки отыскать меня? Но если ты прочитаешь мои записи, то узнаешь только половину истории!" },
    ["454a"] = { common = "До этого... случая мы всё время таскали туда-сюда бочки с порохом. Теперь придётся поделить работу: Миран понесёт часть бочек, а я присмотрю за остальными. Мне не хочется отпускать Мирана одного. Когда он соберётся в путь, проводи, пожалуйста, его." },
    ["454c"] = { male = "Добрый день, герой. Ты проводишь меня до раскопа? Отлично... После случая с Сайаном и его компанией я не знаю, чего и ждать от клана Чёрного Железа. Я почти готов, осталось только кое-что проверить. Когда ты соберёшься в путь, скажи мне об этом.", female = "Добрый день, героиня. Ты проводишь меня до раскопа? Отлично... После случая с Сайаном и его компанией я не знаю, чего и ждать от клана Чёрного Железа. Я почти готов, осталось только кое-что проверить. Когда ты соберёшься в путь, скажи мне об этом." },
    ["455a"] = { common = "Орки из клана Драконьей Пасти бесчинствуют по всей Болотине. А сейчас они двинулись на Дун Альгаз! Нельзя допустить, чтобы они здесь закрепились, иначе Лок Модан будет отрезан от Гавани Менетилов, нашего порта и крепости в Болотине. Попытайся прорваться сквозь Дун Альгаз в Болотине и убей столько орков, сколько сумеешь! Чем больше, тем лучше! Об исполнении доложишь Валстагу Сталезубу в Гавани Менетилов. Найти Менетилов несложно: пройдёшь через Дун Альгаз, потом – по дороге на север, а на развилке свернёшь на запад. Мы очень надеемся на тебя. Не подведи нас." },
    ["455c"] = { common = "Да, нехорошие новости! Как я понимаю, орки Драконьей Пасти всерьёз вознамерились двинуться на Альгаз. Обычно они сидят у себя на холмах и никуда не суются. Что их сподвигло идти на Альгаз? Для меня это загадка... Спасибо. Может быть, нам понадобится твоя помощь, когда мы пойдём разбираться с орками." },
    ["456a"] = { male = "Мои приветствия. Я – Опекун Илталайн. Здесь, в Тенистой долине, я слежу за поддержанием природного равновесия. Весенние дожди в этом году были очень сильными, и от этого одни лесные существа благоденствуют, а другие страдают. К несчастью, ночные саблезубы и щетинистые вепри слишком расплодились. Тенистая долина не может их прокормить. Юный герой, помоги нам – сократи численность вепрей и саблезубов ради сохранения природного равновесия.", female = "Мои приветствия. Я – Опекун Илталайн. Здесь, в Тенистой долине, я слежу за поддержанием природного равновесия. Весенние дожди в этом году были очень сильными, и от этого одни лесные существа благоденствуют, а другие страдают. К несчастью, ночные саблезубы и щетинистые вепри слишком расплодились. Тенистая долина не может их прокормить. Юная героиня, помоги нам – сократи численность вепрей и саблезубов ради сохранения природного равновесия." },
    ["456c"] = { male = "Ты хорошо исполнил свой долг.", female = "Ты хорошо исполнила свой долг." },
    ["457a"] = { common = "Сокращение численности молодых особей, обитающих в Тенистой долине – это неплохо для начала, однако нужно выполнить ещё некоторую работу. Лесные ресурсы истощатся слишком быстро, если не решить эту проблему. Охота на диких зверей – это зло, необходимое для блага всех тех, кто обитает в этих землях. Отправляйся в лес и убивай облезлых ночных саблезубов и щетинистых вепрей ради равновесия." },
    ["457c"] = { male = "Твои дела доказывают твою преданность природе. Поверь, герой, несмотря на твою юность уже заметно, что тебя ждёт блестящее будущее.", female = "Твои дела доказывают твою преданность природе. Поверь, героиня, несмотря на твою юность уже заметно, что тебя ждёт блестящее будущее." },
    ["458a"] = { male = "Какая отрада, что ты здесь, герой. Шёпот лесных духов донёс до моего слуха странные вести. Таинственная защитница леса, Тариндрелла, вернулась в Тенистую долину. Много лет эту дриаду не видели в лесах Калимдора. Что-то определённо не так, если она вновь появилась в этих землях. Найди Тариндреллу и узнай, что привело её в наши рощи. Кто-то из Стражей сообщил о том, что её видели к юго-западу от Альдрассила.", female = "Какая отрада, что ты здесь, героиня. Шёпот лесных духов донёс до моего слуха странные вести. Таинственная защитница леса, Тариндрелла, вернулась в Тенистую долину. Много лет эту дриаду не видели в лесах Калимдора. Что-то определённо не так, если она вновь появилась в этих землях. Найди Тариндреллу и узнай, что привело её в наши рощи. Кто-то из Стражей сообщил о том, что её видели к юго-западу от Альдрассила." },
    ["458c"] = { male = "Я вижу, тебе удалось найти меня, юный ночной эльф! Друид Мелитар мудро поступил, отправив тебя сюда. Тебе ещё многому нужно научиться. Я так понимаю, ваш народ любит книги. Можешь взять одну из них, чтобы углубить свои познания.", female = "Я вижу, тебе удалось найти меня, юная ночной эльф! Друид Мелитар мудро поступил, отправив тебя сюда. Тебе ещё многому нужно научиться. Я так понимаю, ваш народ любит книги. Можешь взять одну из них, чтобы углубить свои познания." },
    ["459a"] = { common = "Непонятное зло затаилось в лесу Тельдрассила. Взгляни на холмы, где некогда обитали мирные фурболги. Они покинули свои дома и объединились в племя Кривой Сосны. Лишь порча, вызванная зловещим мхом Скверны, могла быть причиной подобного изменения. Грелли и греллиды кишат в округе, представляя собой угрозу для жителей Тенистой долины. Напади на этих бесов, и узнай, действительно ли они подпали под чары зловещего мха Скверны." },
    ["459c"] = { male = "Твоё служение обитателям Тенистой долины достойно награды. Однако мои опасения подтвердились. Если даже грелли попали под влияние мха Скверны, то можно вообразить, что случилось с фурболгами племени Кривой Сосны, некогда жившими здесь. герой, если будешь в Доланааре, отыщи мудрого друида Атридаса Медвежью Шкуру. Он, как и мы, печётся о благополучии леса.", female = "Твоё служение обитателям Тенистой долины достойно награды. Однако мои опасения подтвердились. Если даже грелли попали под влияние мха Скверны, то можно вообразить, что случилось с фурболгами племени Кривой Сосны, некогда жившими здесь. героиня, если будешь в Доланааре, отыщи мудрого друида Атридаса Медвежью Шкуру. Он, как и мы, печётся о благополучии леса." },
    ["460a"] = { common = "На вид ты не похож на гнилошкура. Это хорошо. А то я уже потерял надежду... Меня зовут Аларик, когда-то я был доверенным слугой и телохранителем Тула. Он использовал свою магию для \"защиты\" меня от Чумы Нежити, но вместо этого его заклинание повергло меня в нежитие – состояние, из которого я не могу уйти. А после создания этих проклятых гнилошкурых гноллов Туле обезглавил меня... и отдал гноллам мою голову в качестве игрушки! Пожалуйста, воссоедини меня с телом. Я уверен, что гноллы закопали его в Крепости Фенриса, возле стойл, в ничем не примечательной могиле." },
    ["460c"] = { common = "Спасибо. Я опасался, что гноллы изуродовали моё тело. Приятно узнать, что это не так." },
    ["461a"] = { common = "Я знаю об одной тайной нише в крепости, где хранится дорогой сердцу Тула и его давних коллег предмет. В ней также лежит нечто, что вы можете счесть полезным для себя. Возьмите меня туда! Углубление в стене находится в юго-западной башне крепости, позади пыльной полки. Возьмите моё тело, а сапоги оставьте здесь. Они мне всё равно не по ноге..." },
    ["461c"] = { common = "Вот мы и на месте, здесь открыто. Оставьте меня здесь. Лучшие дни моей жизни я провёл в этой крепости, и мысль об упокоении в этих стенах умиротворяет меня. Хорошенько закройте нишу – я не хочу, чтобы эти гнилошкуры нашли меня. Ах, да, и возьмите вот это. Вы это заслужили." },
    ["463a"] = { male = "Ты ведь слышал рассказы о Зелёном Страже? Я даже подозреваю, что ты и разыскать его хочешь. Если так, то скажу тебе, что это чистое безумие! Впрочем, не мне тебя отговаривать: хочешь найти верную смерть – пожалуйста, милости просим. Он живёт на болотах, к востоку от развилки на дороге, ведущей в Дун Модр. Рыщет там на пару с кроколисками... и прочими тварями. Оставь-ка свои денежки мне – покойникам они всё равно не нужны. Да и Зелёный Дядя может обломать зуб о твои золотые, когда будет перекусывать тебя надвое... Ты ведь не хочешь, чтобы бедняга потом мучился?", female = "Ты ведь слышала рассказы о Зелёном Страже? Я даже подозреваю, что ты и разыскать его хочешь. Если так, то скажу тебе, что это чистое безумие! Впрочем, не мне тебя отговаривать: хочешь найти верную смерть – пожалуйста, милости просим. Он живёт на болотах, к востоку от развилки на дороге, ведущей в Дун Модр. Рыщет там на пару с кроколисками... и прочими тварями. Оставь-ка свои денежки мне – покойникам они всё равно не нужны. Да и Зелёный Дядя может обломать зуб о твои золотые, когда будет перекусывать тебя надвое... Ты ведь не хочешь, чтобы бедняга потом мучился?" },
    ["463c"] = { male = "Что это за букашка ко мне пожаловала? Корни и папоротники говорят, что ты пришёл с добрым умыслом... Меня по-разному называют, но не на всякое имя я откликаюсь. Зови меня Ретиль. А теперь внемли... Здешние земли уже давно страдают от множества недугов, и я поручу тебе исцелить их.", female = "Что это за букашка ко мне пожаловала? Корни и папоротники говорят, что ты пришла с добрым умыслом... Меня по-разному называют, но не на всякое имя я откликаюсь. Зови меня Ретиль. А теперь внемли... Здешние земли уже давно страдают от множества недугов, и я поручу тебе исцелить их." },
    ["464a"] = { common = "К концу Второй войны клан орков Драконьей Пасти потерял власть над красными драконами и был почти уничтожен. Драконы припомнили им всё, гнали бывших хозяев аж до самого Грим Батола. Затем орки скрылись в горах к востоку от раскопа Вельгара. Отсидевшись в горах, они вновь набрали силу и теперь разбили лагерь к северо-востоку от Менетила. Напади на этот лагерь, внеси панику в ряды орков. В доказательство содеянного принеси мне боевые знамёна клана." },
    ["464c"] = { common = "Отличная работа. Ныне клан Драконьей Пасти уж не тот, что в былые времена, когда оркам служили драконы. Но всё равно они опасные противники. Кланом Драконьей Пасти руководит Нек'рош, сын Некросса – бывшего главы клана. Некросс владел могущественными заклинаниями, с помощью которых он управлял красными драконами. Но когда его силы иссякли... ну, ты уже знаешь эту историю. Некросс погиб, а его сын поклялся отомстить драконам, убившим его отца." },
    ["465a"] = { male = "Пока ты сражался с кланом Драконьей Пасти, мы получили сведения об их планах. Нек'рош строит катапульты и планирует взять Менетил в осаду! А у нас тем временем вовсю идёт битва при Дун Альгаз, и подкрепления ждать неоткуда! Уничтожь катапульты, прошу тебя. Они стоят в лагере Драконьей Пасти. Возьми вот этот трут. Пробейся к катапультам и подожги их. После этого найди и убей Нек'роша. Этот паршивец уже своё отжил...", female = "Пока ты сражалась с кланом Драконьей Пасти, мы получили сведения об их планах. Нек'рош строит катапульты и планирует взять Менетил в осаду! А у нас тем временем вовсю идёт битва при Дун Альгаз, и подкрепления ждать неоткуда! Уничтожь катапульты, прошу тебя. Они стоят в лагере Драконьей Пасти. Возьми вот этот трут. Пробейся к катапультам и подожги их. После этого найди и убей Нек'роша. Этот паршивец уже своё отжил..." },
    ["465c"] = { common = "Вы подносите трут к катапульте и высекаете искру... Пламя охватывает катапульту и мигом перекидывается на другие!" },
    ["466a"] = { common = "Я слышал о редком виде руды – огневите. Его добывают в Болотине, в пещере к северо-западу от Врат Альгаза. Огневит очень неустойчив – чуть что, сразу взрывается. Однако я уверен, что если правильно его выплавить, то можно делать из него мощнейшие снаряды для пушек! Раздобудь для меня огневитовую руду, а я пока поищу добровольца, который согласится принять участие в опытах. Ах да, чтобы добыть руду, тебе нужны познания в горном деле. Если у тебя нет необходимых знаний, то... отправь в шахту кого-нибудь из знакомых рудокопов!" },
    ["466c"] = { common = "Как раз столько, сколько нужно для экспериментов! Молодец, я в тебя верил! Тут же отправлю материал на изучение. Надеюсь, что мой доброволец хотя бы до первых результатов доживёт!" },
    ["467a"] = { common = "Пилот Камнекожиц любит свою осадную машину, как и все пилоты осадных машин! И он всегда рад найти новый способ повысить огневую мощь своих орудий. До него дошли слухи о редкой руде, и он ищет кого-нибудь, кто добудет её. И если тебе уже не терпится взяться за это дело, то найди Камнекожица в посёлке Сталежара в Дун Мороге и спроси, чего он хочет." },
    ["467c"] = { male = "Привет. Ты тут по моему делу, да? Приятно видеть, как молодой герой рвётся на поиски приключений!", female = "Привет. Ты тут по моему делу, да? Приятно видеть, как молодая героиня рвётся на поиски приключений!" },
    ["468a"] = { common = "Горный пехотинец Рокхар ищет добровольцев для похода через Дун Альгаз в Болотину! Если желаете омыть сапоги в болотной жиже и снискать приключений на свою голову – поговорите со Скальным Панцирником в Дун Альгаз. Это к северу отсюда, по дороге за сторожевой башней." },
    ["468c"] = { common = "Паладин, ни больше, ни меньше! Желаешь отправиться с нами в разведку? Отлично! Надеюсь, у тебя есть всё необходимое снаряжение, потому что эта \"разведка\" может обернуться и кое-чем похуже..." },
    ["469a"] = { male = "Привет тебе, странник! Не лежит ли твой путь в сторону Менетила? Если нет, то знай, что там можно передохнуть, сделать покупки и пропустить пару пинт. Прелестный городок! Ну а если ты как раз туда и направляешься, то я бы хотел передать с оказией стопку кроколисковых шкур для кожевника Джеймса Халлорана. Я бы и сам отнёс их, но дома последнее время то свара, то скандал. Не хочу попадаться жене на глаза.", female = "Привет тебе, путешественница! Не лежит ли твой путь в сторону Менетила? Если нет, то знай, что там можно передохнуть, сделать покупки и пропустить пару пинт. Прелестный городок! Ну а если ты как раз туда и направляешься, то я бы хотел передать с оказией стопку кроколисковых шкур для кожевника Джеймса Халлорана. Я бы и сам отнёс их, но дома последнее время то свара, то скандал. Не хочу попадаться жене на глаза." },
    ["469c"] = { common = "Хмм, да это же от Эйнара, да? Не вижу его уж который день, а шкуры присылает исправно. Опять поцапался со своей благоверной, к бабке не ходи! Надо бы подослать жену к Сиде – поговорить, чтобы та не выживала мужа из дому..." },
    ["470a"] = { male = "Каждую неделю я хожу к Гробнице Железноборода, и в этот раз всё было как всегда, но вдруг на меня напали омерзительные хлюпающие слизнюки! Я так растерялась... Я бросила в одного из них сумку, но он взял и засосал её! Мне едва хватило времени, чтобы сбежать. А в сумке-то мои вещи! Я даже не знаю, какой из этих гадов её сожрал – они все одинаковые! Гробница Железноборода находится к северо-востоку отсюда, возле Дун Модра. Спасибо, что согласился помочь!", female = "Каждую неделю я хожу к Гробнице Железноборода, и в этот раз всё было как всегда, но вдруг на меня напали омерзительные хлюпающие слизнюки! Я так растерялась... Я бросила в одного из них сумку, но он взял и засосал её! Мне едва хватило времени, чтобы сбежать. А в сумке-то мои вещи! Я даже не знаю, какой из этих гадов её сожрал – они все одинаковые! Гробница Железноборода находится к северо-востоку отсюда, возле Дун Модра. Спасибо, что согласилась помочь!" },
    ["470c"] = { common = "Спасибо большущее! Я-то боялась, что её больше не вернуть! *Она вытряхивает из склизкой сумки содержимое и собирает мелочь в кучку.* Хм, чего-то я здесь самого нужного и не вижу... посмотри, может, тебе что-нибудь отсюда пригодится." },
    ["471a"] = { common = "Недавно я отправил помощника на болото за шкурами гигантских болотных кроколисков. Он не вернулся обратно, и я отправился на поиски... Скажем так: зрелище было не для слабонервных. Лекарь говорит, что мальчик выживет, и слава богу, но у меня-то работа стоит! Если у тебя есть желание поохотиться на кроколисков, я препятствовать не стану – особенно после того, что они сделали с моим помощником. Кроколиски водятся на побережье к северу отсюда, за поселением мурлоков." },
    ["471c"] = { common = "Хмм... не думаю, что ты захочешь наняться ко мне в помощники, так ведь? Хе-хе-хе! Да шучу я. Староват ты для этого, да и заметно, что у тебя на роду совсем другое написано. Благодарю тебя за помощь. Шкуры отменные – как раз подойдут мне для работы!" },
    ["472a"] = { male = "Дворфы Чёрного Железа захватили Дун Модр! Я тяжело ранен, герой. Почти все мои однополчане погибли! Подонки из клана Чёрного Железа набросились на нас, не успели мы оправиться после взрыва. Наш командир, Длинная Коса, протрубил сигнал к отступлению. Во время бегства мне в спину попал топорик. Я потерял сознание... Очнулся уже в Менетиле, но меня волнует судьба остальных солдат. Надежда умирает последней... Может быть, Длинная Коса тоже спасся! Иди в Дун Модр и отыщи его, путник!", female = "Дворфы Чёрного Железа захватили Дун Модр! Я тяжело ранен, героиня. Почти все мои однополчане погибли! Подонки из клана Чёрного Железа набросились на нас, не успели мы оправиться после взрыва. Наш командир, Длинная Коса, протрубил сигнал к отступлению. Во время бегства мне в спину попал топорик. Я потерял сознание... Очнулся уже в Менетиле, но меня волнует судьба остальных солдат. Надежда умирает последней... Может быть, Длинная Коса тоже спасся! Иди в Дун Модр и отыщи его, путница!" },
    ["472c"] = { male = "Какие новости из Менетила принёс нам добрый герой? Так-так-так, значит, тебя зовут путник. Приятно познакомиться. Что ж, весть добрая. Слава Свету, что молодой Харло выжил. Ранение у него было очень тяжёлое, и нам пришлось отправить его в город на единственном уцелевшем скакуне. Однако в целом ситуация безнадёжная: Дун Модр пал, а от нашего славного полка остались лишь воспоминания.", female = "Какие новости из Менетила принёс нам добрый героиня? Так-так-так, значит, тебя зовут путница. Приятно познакомиться. Что ж, весть добрая. Слава Свету, что молодой Харло выжил. Ранение у него было очень тяжёлое, и нам пришлось отправить его в город на единственном уцелевшем скакуне. Однако в целом ситуация безнадёжная: Дун Модр пал, а от нашего славного полка остались лишь воспоминания." },
    ["473a"] = { common = "Орки из клана Драконьей Пасти совсем озверели. Им уже мало одного Альгаза. Капитан Крепкий Кулак просил направлять к нему всех, кто готов оказать нам содействие в войне против орков. Он сейчас в крепости, в зале Войны." },
    ["473c"] = { male = "Валстаг вкратце рассказал мне о твоих победах над орками Драконьей Пасти в Дун Альгазе. Ты – достойный герой. Нам такие нужны. И у меня уже есть для тебя поручение.", female = "Валстаг вкратце рассказал мне о твоих победах над орками Драконьей Пасти в Дун Альгазе. Ты – достойная героиня. Нам такие нужны. И у меня уже есть для тебя поручение." },
    ["474a"] = { common = "Катапульты сожжены. Теперь найди и убей вождя Нек'роша." },
    ["474c"] = { male = "Чистая работа. Ты нанёс сокрушительный удар оркам из клана Драконьей Пасти. Они ещё не скоро оправятся от него. К тому же их катапульты больше не угрожают Гавани Менетил. Ты – достойный герой, а Стальгорн не забывает о героях! Вот твоя награда.", female = "Чистая работа. Ты нанесла сокрушительный удар оркам из клана Драконьей Пасти. Они ещё не скоро оправятся от него. К тому же их катапульты больше не угрожают Гавани Менетил. Ты – достойная героиня, а Стальгорн не забывает о героях! Вот твоя награда." },
    ["475a"] = { common = "Ветер тревоги веет над лесом. Гэролас Талветрен служит Великим смотрителем за спящими друидами-воронами в обители Бен'этиль. Его долг – обеспечивать их безопасность, дабы их уговор с Изерой оставался в силе. Но вести от Гэроласа что-то задерживаются, и я начинаю волноваться. Отправляйся на восток в Деревню Звёздного Ветра – мне нужен отчёт Гэроласа, дабы я был спокоен, узнав, что мои братья и сёстры спят спокойно." },
    ["475c"] = { common = "Хвала лесным духам, ты здесь! Я знал, что Атридас забеспокоится и пришлёт помощь." },
    ["476a"] = { male = "Племя Кривой Сосны поражено порчей! Эти некогда мирные фурболги обратились против покровителей леса. Они подстерегли меня в засаде, когда я выходил из обители Бен'этиль и разграбили Деревню Звёздного Ветра. Их вождь, Урсал Изверг, затмевает их разум при помощи мха Скверны. Я слишком изранен, чтобы донести до Атридаса эти страшные вести. Теперь это придётся сделать тебе, юный герой. Остаётся только надеяться, что безумные фурболги Кривой Сосны ещё не уничтожили Бен'этиль!", female = "Племя Кривой Сосны поражено порчей! Эти некогда мирные фурболги обратились против покровителей леса. Они подстерегли меня в засаде, когда я выходил из обители Бен'этиль и разграбили Деревню Звёздного Ветра. Их вождь, Урсал Изверг, затмевает их разум при помощи мха Скверны. Я слишком изранен, чтобы донести до Атридаса эти страшные вести. Теперь это придётся сделать тебе, юная героиня. Остаётся только надеяться, что безумные фурболги Кривой Сосны ещё не уничтожили Бен'этиль!" },
    ["476c"] = { common = "Клянусь звёздами! Воистину тревожные вести!" },
    ["477a"] = { common = "Как вы, должно быть, знаете, в деревне Янтарная Мельница окопалась враждебная группа людей. Она держится там в основном за счёт поддержки, которую они получают от волшебников Даларана. Я не знаю, что они замышляют, но сам по себе интерес, проявленный ими к захолустной деревушке вроде Янтарной Мельницы, показывает, что она имеет немаленькое значение. Они отправляют повозкой из Хилсбрада сундуки. Многое из привезённого складируется в небольшом лагере к северу от деревни Погребальных Костров. Раздобудьте содержимое одного такого сундука и принесите мне." },
    ["477c"] = { common = "*С любопытством открыв крышку ящика, вы находите в нём множество тщательно упакованных предметов. На самом верху лежит связка пожелтевших от времени карт, на которых, судя по всему, изображено Серебряный бор и другие области западного Лордерона. Под картами обнаруживается подвеска таинственно-волшебного вида.*" },
    ["478a"] = { common = "*Вы быстро вытаскиваете подвеску из сундука и кладёте крышку на место.*" },
    ["478c"] = { common = "Карты и эта... эта подвеска? Интересно. Очевидно, что волшебники Даларана почему-то интересуются Янтарной мельницей, но их цель по-прежнему остаётся неизвестной. Может быть, Далар сможет выяснить, что они там ищут." },
    ["479a"] = { common = "Далар пытается выяснить, каков источник магической силы этих волшебников. А пока что нам нужно замедлить их прогресс любым путём... Маги, окудники и заступники, несомненно, носят такие подвески. Добудьте их. Чтобы добраться до Янтарной Мельницы, идите на юг по главной дороге, а на развилке сверните на восток." },
    ["479c"] = { common = "Далар выяснил, что несмотря на замедление, процесс плетения чар зашёл уже далеко. Некий очень могущественный волшебник направляет магическую энергию. Его нужно как можно скорее остановить." },
    ["480a"] = { common = "Верховный маг огромной силы отвечает за реактивацию энергетического узла. Они уже далеко зашли, так что единственный способ их остановить – это убить его. Это будет тяжело – безусловно, его защищают многочисленные маги и охранники. Вам надо пойти и разобраться с ним, быстро. Когда он будет мёртв, принесите мне его посох. Идите немедленно." },
    ["480c"] = { common = "Магия волшебников рассеивается, и энергетические узлы вновь засыпают. Ваши усилия оказались плодотворными, и мы сумели нанести нашим врагам и могучим волшебникам Даларана серьёзный удар. Однако нужно не терять бдительности – ведь источник энергии находится совсем близко... Нужно разрабатывать планы на будущее." },
    ["481a"] = { common = "Отнесите подвеску Далару Ткачу Рассвета – может быть, он сможет пролить какой-то свет на планы волшебников." },
    ["481c"] = { common = "Интересно – похоже, новые махинации Кирин-Тора. Это могущественный артефакт. Такие часто использовали могучие волшебники Кирин-Тора для передачи магической энергии. То, что они так много таких вещиц доставляют в Янтарную Мельницу, указывает на то, что затевается что-то серьёзное. Посмотрим, сумею ли я проникнуть сквозь защиту и поточнее разузнать об их намерениях." },
    ["482a"] = { common = "Конечно! Как же я мог забыть? Янтарная Мельница была одним из мест, отмеченных магами Кирин Тора, и примечательна тем, что на территории деревни находится спящий энергетический узел. Волшебники, должно быть, планируют реактивировать узел и использовать его энергию для какой-то более серьёзной цели. Мы не можем позволить этому случиться... Чтобы активировать энергии этого места, понадобится много сил, и мы можем осложнить им задачу, стащив у волшебников подвески. Передайте эту информацию Алистеру, он спланирует дальнейшие действия." },
    ["482c"] = { common = "Вы принесли тревожные вести. Если Далар прав – а у меня нет оснований думать иначе – мы должны действовать быстро. Мне нужно выработать совместно с ним план нашей атаки. А тем временем нужно замедлить их прогресс." },
    ["483a"] = { common = "Захватчиков Кривой Сосны видели в обители Бен'этиль на западе, они крушили там всё подряд. Спящие друиды никогда не смогут выйти из Изумрудного Сна – они даже не понимают, в какую западню угодили, – если мы только им не поможем. Тонкий ритуал спячки нельзя нарушить без реликвий Пробуждения. Отправляйся в обитель и найди талисман Когтя Ворона, Чёрное перо, Небесный сапфир и руну Размещения. Друиды хранят их в священных ларцах. Принеси их мне, и я подготовлю ритуал пробуждения." },
    ["483c"] = { male = "Тебе удалось это сделать, юный герой! Славно! И как раз вовремя.", female = "Тебе удалось это сделать, юная героиня! Славно! И как раз вовремя." },
    ["484a"] = { male = "Ты, наверное, слышал обо-мне. Я Джеймс Халлоран, кожевник. Выделанные мною кроколисковые шкуры расходятся по всему миру! Уже встречался с Эйнаром? Он – один из охотников, приносящих мне шкуры. В последнее время у меня осталось мало мягких шкур, а их можно снять только с молодых кроколисков. Учитывая обстоятельства, я готов заплатить высокую цену за стопку шкур. Молодые кроколиски обитают в водах прямо за городом.", female = "Ты, наверное, слышала обо-мне. Я Джеймс Халлоран, кожевник. Выделанные мною кроколисковые шкуры расходятся по всему миру! Уже встречалась с Эйнаром? Он – один из охотников, приносящих мне шкуры. В последнее время у меня осталось мало мягких шкур, а их можно снять только с молодых кроколисков. Учитывая обстоятельства, я готов заплатить высокую цену за стопку шкур. Молодые кроколиски обитают в водах прямо за городом." },
    ["484c"] = { common = "Отлично, превосходно! Прекрасные шкуры! Надо немедленно замочить их... но перед этим я хотел бы попросить тебя ещё об одной услуге. Думаю, ты справишься." },
    ["485a"] = { common = "Вы обнаружили странный металлический предмет яйцевидной формы. Когда вы нажали на какую-то кнопку, яйцо вдруг ожило, открылось и превратилось в непонятный механизм, который проскрежетал механическим голосом: \"Меня зовут Карлс Пропеллерз, и мой автономный робот повреждён. Просьба найти робота, вставить в него этот маяк, а потом вернуть мне за вознаграждение\". \"Я вычислил координаты робота – он попал в аварию в устье реки близ Осклизлой скалы\"." },
    ["485c"] = { common = "Вы помещаете яйцевидный аварийный маяк в механического цыплёнка. С гудением и жужжанием робот поднимается на ноги, после чего из его механических внутренностей слышится голос Карлса: \"Что ж, по крайней мере, OOX-девять/HL работает, но ему требуется капитальный ремонт! Он тяжёлый, и нести его ты не сможешь, но вообще у меня есть одна мысль... Не хочешь ли присмотреть за ним ещё немного?\"" },
    ["486a"] = { common = "Настало время спасти друидов-воронов. Если сейчас мы потерпим неудачу, их сон станет вечным. Я подготовлю реликвии Пробуждения и совершу обряд. Но чтобы у меня всё получилось, тварь, виновная в их злоключениях, должна быть уничтожена. Только тогда ритуал может быть выполнен. Это Урсал Изверг разрушил дело наших братьев, и теперь он должен заплатить за свои злодеяния ради их освобождения. Отправляйся в Лагерь у Кривой Сосны на юго-западе и убей его." },
    ["486c"] = { male = "Ты проявил себя как весьма достойный и способный герой. человек, следующий путём чести столь же неустанно, как ты, обязательно обретёт великую славу в этом мире. Да будут благосклонны к тебе лесные духи всюду, куда бы ни завели тебя твои странствия.", female = "Ты проявила себя как весьма достойная и способная героиня. человек, следующий путём чести столь же неустанно, как ты, обязательно обретёт великую славу в этом мире. Да будут благосклонны к тебе лесные духи всюду, куда бы ни завели тебя твои странствия." },
    ["487a"] = { male = "Дорогу в Дарнасс нужно охранять. Путники, направляющиеся из Доланаара в Дарнасс, рассказывают о варварских нападениях поражённых порчей фурболгов из племени Кривой Сосны. Каждый день из Дарнасса и в Дарнасс поступают грузы и важные сообщения. Мы не можем допустить, чтобы шайка этих мерзостных тварей угрожала путникам. Возьмись же за оружие во имя священного леса, герой. Их логово находится где-то под этим наблюдательным пунктом. Убей шесть душителей из племени Кривой Сосны и возвращайся ко мне.", female = "Дорогу в Дарнасс нужно охранять. Путники, направляющиеся из Доланаара в Дарнасс, рассказывают о варварских нападениях поражённых порчей фурболгов из племени Кривой Сосны. Каждый день из Дарнасса и в Дарнасс поступают грузы и важные сообщения. Мы не можем допустить, чтобы шайка этих мерзостных тварей угрожала путникам. Возьмись же за оружие во имя священного леса, героиня. Их логово находится где-то под этим наблюдательным пунктом. Убей шесть душителей из племени Кривой Сосны и возвращайся ко мне." },
    ["487c"] = { male = "Ты славно послужил доброму народу Доланаара и Дарнасса, отважный герой. От имени всех часовых Тельдрассила воздаю тебе хвалу.", female = "Ты славно послужила доброму народу Доланаара и Дарнасса, отважная героиня. От имени всех часовых Тельдрассила воздаю тебе хвалу." },
    ["488a"] = { male = "Вижу, ты работёнку ищешь? Хе-хе, ни дня не проходит без того, чтобы я не поручил какое-нибудь дельце наивному юнцу... вроде тебя. Видишь ли, я могу осчастливить тебя такими вещицами, что тебе и не снились. Но за это ты кое-что мне принесёшь. Мне часто бывают нужны определённые... ингредиенты. Принеси три клыка ночного саблезуба, три пера островной совы и три мотка паутины чащобного тенётника. И пусть это всё останется между нами, герой.", female = "Вижу, ты работёнку ищешь? Хе-хе, ни дня не проходит без того, чтобы я не поручил какое-нибудь дельце наивной девчушке... вроде тебя. Видишь ли, я могу осчастливить тебя такими вещицами, что тебе и не снились. Но за это ты кое-что мне принесёшь. Мне часто бывают нужны определённые... ингредиенты. Принеси три клыка ночного саблезуба, три пера островной совы и три мотка паутины чащобного тенётника. И пусть это всё останется между нами, героиня." },
    ["488c"] = { male = "Ха-ха! Хорошая работёнка! Кто бы мог подумать, что на меня, Зенна Грязное Копыто, будет работать герой? Я даже мечтать об этом не мог! Но раз уж так вышло... Наш милый мир полон неожиданностей. Обманули дурака на четыре кулака!", female = "Ха-ха! Хорошая работёнка! Кто бы мог подумать, что на меня, Зенна Грязное Копыто, будет работать героиня? Я даже мечтать об этом не мог! Но раз уж так вышло... Наш милый мир полон неожиданностей. Обманули дурака на четыре кулака!" },
    ["489a"] = { male = "Совет Леса узнал, что ты помог Зенну Грязному Копыту! Этот сатир – враг леса! И ты, как герой, должен бы понимать, что оскверняешь лес, убивая созданий Природы! Ты должен искупить свою вину перед Советом, если хочешь оставаться другом Тельдрассилу! Преподай Грязному Копыту урок – и заслужишь прощение. Есть такие шишки Скверны – это семена, падающие с деревьев. Они испускают зелёный дым. Скорми несколько штук Грязному Копыту. Он подумает, что ему предлагают что-то вкусненькое.", female = "Совет Леса узнал, что ты помогла Зенну Грязному Копыту! Этот сатир – враг леса! И ты, как героиня, должна бы понимать, что оскверняешь лес, убивая созданий Природы! Ты должна искупить свою вину перед Советом, если хочешь оставаться другом Тельдрассилу! Преподай Грязному Копыту урок – и заслужишь прощение. Есть такие шишки Скверны – это семена, падающие с деревьев. Они испускают зелёный дым. Скорми несколько штук Грязному Копыту. Он подумает, что ему предлагают что-то вкусненькое." },
    ["489c"] = { common = "Ну что ты за лапочка! Я знал, что ты мне ещё пригодишься!" },
    ["490a"] = { common = "По приказу часовых я назначаю награду за головы фурболгов из племени Кривой Сосны. Это враги леса. Скверна лишила их рассудка, и теперь они угрожают нашему народу и лесным жителям. Мы отблагодарим всякого, кто защитит Тельдрассил от этой напасти. Только принеси их клыки в качестве доказательства. Больше всего фурболгов собралось в лощине Бен'этиль на западе от Доланаара и с южной стороны от дороги, а также в деревне Звёздного Ветра на востоке." },
    ["491a"] = { common = "Туле как-то рассказывал мне, что давным-давно он вместе с двумя товарищами создал магический жезл, сплетя его из трёх принадлежащих им ученических жезлов. Он был символом их дружбы, и, хотя Тул презрел её, с жезлом он расстаться не мог и не желал отдавать его другим. Поэтому он выкрал жезл и спрятал его в крепости Фенриса. Здесь. Отнесите жезл Бетору Ледострелу, одному из прежних друзей Тула. Я уверен, он будет рад его получить." },
    ["491c"] = { common = "... Что это?! У Туле был наш Сплетённый жезл? Я думал, он пропал, когда наша дружба пошла прахом, и Туле примкнул к Королю-личу! Должно быть, он не обращался к силе жезла, потому что если бы он сделал это, я бы почувствовал. И хорошо, что Тул не использовал жезл... Это удивительная находка. Я признателен за неё, и вознагражу тебя." },
    ["492a"] = { common = "Страж смерти сообщил, что недавно был захвачен ещё один дворф-горный пехотинец. Стражи смерти обычно сажают пленных в погреб таверны \"Петля Висельника\", где им оказывается \"достойный приём\". Почему бы вам не пойти и не угостить пленника специальным напитком, который я приготовил? В нём есть небольшая примесь того, что Тёмная Госпожа готовит для всего Азерота." },
    ["492c"] = { common = "Ах, наконец-то питьё! Хоть это и не \"Болтливое пиво\", но я рад хоть чем-то промочить горло." },
    ["493a"] = { common = "Тёмная Госпожа давит на Королевское фармацевтическое общество, чтобы оно поскорее разработало Новую чуму. Мы упорно трудимся и добились значительного прогресса. Мы уверены, что успех был бы достигнут значительно быстрее, если бы мы могли распространять информацию среди членов общества. Поэтому я хотел бы, чтобы вы доставили мои последние находки аптекарю Лидону в Мельницу Таррен – небольшой городок, расположенный в предгорьях Хилсбрада. Путь туда неблизкий. Направляйтесь на юг и держитесь поближе к дорогам. Строго следуйте дорожным указателям!" },
    ["493c"] = { common = "А, отлично. Я в высшей степени уважаю аптекаря Ренферрела. Сгораю от нетерпения начать изучение его работы." },
    ["494a"] = { male = "Молчи и слушай, герой. Меня направили сюда для наблюдением за городом Хилсбрадом. У меня разведывательная миссия. А тебе необходимо срочно отнести вести верховному палачу Дарталии в Мельницу Таррен. Скажи, что страж смерти Леш передала следующие слова: \"Крик ворона на западе манит.\" Ступай по дороге на восток и обращай внимание на знаки. Торопись! Ступай в Мельницу Таррен со всей возможной скоростью!", female = "Молчи и слушай, героиня. Меня направили сюда для наблюдением за городом Хилсбрадом. У меня разведывательная миссия. А тебе необходимо срочно отнести вести верховному палачу Дарталии в Мельницу Таррен. Скажи, что страж смерти Леш передала следующие слова: \"Крик ворона на западе манит.\" Ступай по дороге на восток и обращай внимание на знаки. Торопись! Ступай в Мельницу Таррен со всей возможной скоростью!" },
    ["494c"] = { common = "Крик ворона на западе манит? Отличные новости! Пора напасть на Хилсбрад. Мы сможем воплотить наш план уничтожения жизни. Вариматрас будет доволен." },
    ["495a"] = { common = "Муг'тола и его отряд огров отправили в долину Альтерака за короной Воли для леди Сильваны. К сожалению, вместо того чтобы принести её королеве, этот идиот решил её примерить... наверное, огры не могут устоять перед блестящими побрякушками. Его необдуманный поступок привёл к неприятным последствиям. Корона Воли позволила Муг'толу воспротивиться заклинанию подчинения, наложенному на него леди Сильваной. Тёмная Госпожа хочет, чтобы это стало уроком для остальных. Отправляйся на мельницу Таррен в Хилсбраде и поговори с лейтенантом Мелизарой." },
    ["495c"] = { common = "Тебя прислала Шарлиндра? Ну хорошо. Вскоре ты поймёшь, что я не терплю пустой болтовни. Муг'тол – наглец, и с ним мы разберёмся быстро, тщательно и безжалостно." },
    ["496a"] = { common = "Ах, ещё один мерзкий день на мельнице Таррен. От этого чистого воздуха у меня сразу портится настроение. Чем скорее мы заразим здешних людей, тем лучше. Я провожу исследования различных смертоносных веществ, чтобы использовать их в моих составах, но собрать все времени не хватило. Если ты хочешь принести пользу, добудь для меня следующее: десять языков серых медведей и очень редкую и труднодоступную лимфу паука-охотника. Медведи и пауки-охотники живут рядом с мельницей Таррен." },
    ["496c"] = { male = "Отличные компоненты. Что ж, ты умудрился внести хоть немного радости в мой тоскливый день. Благодарю тебя.", female = "Отличные компоненты. Что ж, ты умудрилась внести хоть немного радости в мой тоскливый день. Благодарю тебя." },
    ["498a"] = { common = "Вождь послал нас с ребятами, чтобы добыть кое-что из Дарнхольда и разведать, что представляет собой так называемый Синдикат. Мы пошли к Дарнхольду, поглядели, что к чему, тут на нас и напал большой отряд людей. Мы бились изо-всех сил, но они сильно превосходили нас числом. В конце концов нескольких из нас взяли в плен, но мне удалось сбежать. Дарнхольд находится на юго-востоке отсюда, по ту сторону реки. Там держат Друлла и Тог'тара, освободи их." },
    ["498c"] = { common = "Значит, люди собирались поработить наших воинов? Мы ещё им покажем! Похоже, они захватили Гол'дира, нашего вождя, и держат его в другом месте. Его тоже необходимо отыскать и спасти. Впрочем, пока неизвестно, где он… Когда у нас появится хоть какая-то зацепка, я немедленно скажу об этом тебе." },
    ["499a"] = { common = "Мне понадобится совсем немного времени для создания того, что я хочу наречь эликсиром Страдания. Вот, готово! Ах, ничто не доставляет столько радости в этих проклятых холмах, как принесение страдания в мир. Посмотрим, достигнут ли желанный эффект. Дай попробовать моему помощнику Ампи то, что Тёмная Госпожа готовит людям и созданиям Плети." },
    ["499c"] = { common = "Квак!" },
    ["500a"] = { common = "Огры из клана Раздробленного Хребта раскопали курган в Альтеракских горах, неподалёку от разрушенного города. Разведчики доносят, что они и сами руины захватили. Мы не дадим им там вольготно расположиться; если они решат, что хорошо устроились, то следующим шагом спустятся с холмов и окажутся прямо рядом с нами! Ступай на север, в Альтеракские горы и убей побольше огров. Принеси мне грязные бабки – кости, которые они таскают с собой, и получишь неплохую награду." },
    ["500c"] = { common = "Отлично. Должно быть, тебе пришлось зарубить целые полчища, чтобы набрать столько костей. Теперь они к нам не сунутся. По крайней мере, некоторое время." },
    ["501a"] = { common = "О... Луга Хилсбрада полны цветов, воздух свеж и приятен. Меня от этого просто тошнит! Я смотрю в мутное окно и мечтаю о наступлении дня, когда Новая чума принесёт в мир заслуженную смерть! Но как бы мне ни хотелось сидеть и мечтать – прежде всего приказы Тёмной Госпожи. Помоги мне! В результате исследований я обнаружил, что из крови горного льва можно создать великолепный напиток смерти. Принеси мне немного крови, и мы повеселимся." },
    ["501c"] = { common = "Отличная работа." },
    ["502a"] = { common = "Ах, ничто так не радует, как запах свежей крови в предгорьях! Смешаем капелюшку этого и щепотку того, и пойдёт веселье! Из этой крови я сделаю эликсир Боли. Если мои вычисления верны, то этот состав порадует леди Сильвану. Надо его испытать. Отнеси этот эликсир на самую северную ферму Хилсбрадских полей, что на юго-западе. Посмотрим, как моё \"угощение\" понравится собачке фермера Рея, Стэнли." },
    ["502c"] = { common = "Вы наливаете немного эликсира в ладонь и протягиваете её Стэнли." },
    ["503a"] = { common = "Судя по добытым тобой документам, Гол'дира держат на большой базе Синидиката, расположенной на севере, вероятно, в Альтеракских горах. Он уж очень давно томится там в плену, пора освободить его." },
    ["503c"] = { common = "Спасибо. По приказу Вождя я вёл экспедицию из Дуротара, но, как видишь, наши планы несколько нарушились. Меня держали в плену в этом городе, заставляя работать – таскать тяжести и копать… Впрочем, неважно, что мне пришлось вынести. Куда важнее сведения, которые тебе необходимо доставить тем, кто сейчас возглавляет нашу группу." },
    ["504a"] = { male = "Ты уже померился силой с ограми Раздробленного Хребта, а теперь я хочу нанести им настоящий удар… Ступай в руины Альтерака и отыщи там наёмников из клана Раздробленного Хребта. Убей побольше этих тварей – только так им можно показать, что лучше держаться подальше от земель Альянса.", female = "Ты уже померилась силой с ограми Раздробленного Хребта, а теперь я хочу нанести им настоящий удар… Ступай в руины Альтерака и отыщи там наёмников из клана Раздробленного Хребта. Убей побольше этих тварей – только так им можно показать, что лучше держаться подальше от земель Альянса." },
    ["504c"] = { male = "Очень хорошо. Вот награда. Кстати, охотясь на огров ты видел город Альтерак. Как он выглядит? Боюсь, что скверно. Огры не славятся своей чистоплотностью. К счастью, благодаря твоим усилиям они будут держаться подальше от Южнобережья.", female = "Очень хорошо. Вот награда. Кстати, охотясь на огров ты видела город Альтерак. Как он выглядит? Боюсь, что скверно. Огры не славятся своей чистоплотностью. К счастью, благодаря твоим усилиям они будут держаться подальше от Южнобережья." },
    ["505a"] = { common = "Меня недавно назначили чиновником в Южнобережье. Моего предшественника убили, и виновников так и не нашли. Впрочем, расследование показало, что скорее всего их нанял Синдикат – группа воров под командованием злодеев-дворян, бывшей знати павшего королевства Альтерак. Лагерь Синдиката расположен на севере от занимаемой Ордой мельницы Таррен. Убей всех членов Синдиката, которых встретишь там." },
    ["505c"] = { common = "Спасибо. Хотя, быть может, они всё ещё шныряют неподалёку, будем надеяться, что некоторые из убитых воров и бандитов принимали участие в убийстве прежнего чиновника. Но даже если и нет, Синдикат – позор этой земли и человеческой расы. Смерть этих бандитов и воров – добрая весть для всего Южнобережья." },
    ["506a"] = { common = "День или два назад ко мне пришёл главарь этого Синдиката. Его звали Алиден Перенольд, и он нарёк себя лордом этих земель. Он поверил мне свои планы о порабощении орков, выступивших против него, как и планировал его отец и учитель, ненавистный Блэкмур. Куда важнее то, что он привёл с собой свою любовницу, девочку-тростинку по имени Элиза. У неё на шее висело ожерелье, который жаждет заполучить Вождь. Ступай, мне пора уходить, когда я закончу свои дела в лагере." },
    ["506c"] = { common = "Надо же, какие наглецы эти люди! Мы покажем им, что орки не сдаются! Отныне это будет нашей целью наравне с тем украшением, которое стремится заполучить наш Вождь. Похоже, одной цели без другой не достичь." },
    ["507a"] = { common = "Очевидно, что Перенольда необходимо убить, избавив мир от его гнусной сущности. Его поместье расположено к северу отсюда, на берегах озера Лордамер. Твой долг, добыть медальон для Вождя и вернуться сюда." },
    ["507c"] = { common = "Нет, прошу вас, не убивайте меня! Я не хотела причинять зло вашему народу, он взял меня против воли! Пожалуйста... Пощадите меня!" },
    ["508a"] = { common = "Ожерелье? Конечно же, можешь его забрать... Да, забирай! Мне не нужны воспоминания о нём... Просто оставь меня в покое..." },
    ["508c"] = { male = "Странно, что вождь пошёл на такие затраты ради этой мелочи. Я не всегда понимаю его мотивы, но я последую за ним, каковы бы ни были его приказы. Ты отлично поработал, и я не сомневаюсь, что вождь будет рад услышать о твоём успехе.", female = "Странно, что вождь пошёл на такие затраты ради этой мелочи. Я не всегда понимаю его мотивы, но я последую за ним, каковы бы ни были его приказы. Ты отлично поработала, и я не сомневаюсь, что вождь будет рад услышать о твоём успехе." },
    ["509a"] = { common = "Новый день, новый эликсир. Если бы я тут командовал, я бы позволил Плети и жалким людишкам сцепиться между собой. Им и так нравится убивать друг друга. Увы, Тёмная Госпожа хочет ускорить процесс, так почему бы не скрасить унылые дни распространением смерти и болезней по стране. Вот мой план: иди-ка ты во Владение Нетандера на юге от мельницы Таррен и на востоке от реки и Южнобережья. Принеси мне шесть цветков Грязного Рыла для нового эликсира." },
    ["509c"] = { common = "А, отвратительная вонь цветков Грязного Рыла. Хоть для чего-то эти грязные гноллы годятся." },
    ["510a"] = { common = "Среди документов вы находите список необходимых припасов. В их число входят самые простые вещи (еда, оружие, одежда) и несколько необычные (маски, масло, яд). Впрочем, более всего привлекает внимание срочность запроса – согласно документу, доставить всё необходимое следует как можно скорее, чтобы \"выполнить важную миссию, нацеленную против Южнобережья\"." },
    ["510c"] = { common = "Малеб изучает документы. Дурные вести. Судя по сведениям, содержащимся в этих документах, и последним действиям Синдиката, эта банда головорезов объявила войну Южнобережью." },
    ["511a"] = { common = "Одно из писем на столе зашифровано." },
    ["511c"] = { common = "Что это? Минуточку... Дай-ка взглянуть поближе. ... Хм, никогда не встречался с таким шифром, но, признаться, в этой области я не очень сведущ." },
    ["512a"] = { common = "Боюсь, что главари Синдиката жаждут гибели Южнобережья. Мы должны нанести удар первыми, пока они не успели воплотить свои планы. Отправляйся в руины Странбрада, в северной части Альтеракских гор. Мы полагаем, что именно там находится штаб-квартира Синдиката. Нам известно, что эту шайку головорезов возглавляет бывшая знать Альтерака. Дворяне скрываются среди прочих посланников Синдиката, но отличить их можно по перстням-печаткам. Разумеется, прежде необходимо их убить. Принеси мне эти перстни." },
    ["512c"] = { male = "Лишившись знатных предводителей, Синдикат утратит волю к действию, превратившись в обычную банду разбойников. Ты хорошо послужил Альянсу.", female = "Лишившись знатных предводителей, Синдикат утратит волю к действию, превратившись в обычную банду разбойников. Ты хорошо послужила Альянсу." },
    ["513a"] = { male = "Я уже решил, что ещё один день пройдёт без капли радости, но тут ты принёс мне цветки Грязного Рыла. Для начала я смешаю их и сделаю отличный состав. Потом нам понадобится помощь мастера-аптекаря Фаранелла из Подгорода. Он должен добавить туда коллоид разложения и тогда-то самое веселье и начнётся! Вот возьми этот состав Грязного Рыла и немедленно отнеси его мастеру-аптекарю Фаранеллу.", female = "Я уже решил, что ещё один день пройдёт без капли радости, но тут ты принесла мне цветки Грязного Рыла. Для начала я смешаю их и сделаю отличный состав. Потом нам понадобится помощь мастера-аптекаря Фаранелла из Подгорода. Он должен добавить туда коллоид разложения и тогда-то самое веселье и начнётся! Вот возьми этот состав Грязного Рыла и немедленно отнеси его мастеру-аптекарю Фаранеллу." },
    ["513c"] = { male = "Тебя послал аптекарь Лидон? Что ж ты сразу не сказал! Невзирая на угрюмый нрав, аптекарь Лидон – один из наших самых преданных и умелых сотрудников. Он прислал состав Грязного Рыла, какой умница! Я знаю, что замышляет наш друг из Хилсбрада. И мне нравится ход его мысли. Тёмная Госпожа порадуется наступлению новой чумы.", female = "Тебя послал аптекарь Лидон? Что ж ты сразу не сказала! Невзирая на угрюмый нрав, аптекарь Лидон – один из наших самых преданных и умелых сотрудников. Он прислал состав Грязного Рыла, какой умница! Я знаю, что замышляет наш друг из Хилсбрада. И мне нравится ход его мысли. Тёмная Госпожа порадуется наступлению новой чумы." },
    ["514a"] = { common = "У меня есть коллега из Стальгорна, который может расшифровать это письмо. Ступай в Библиотеку в Зале Исследователей Стальгорна и поговори с геологом Грозовой Вершиной. Скажи ему, что тебя прислал я и покажи письмо. Если кто и может прочитать это во всех землях к северу от пика Чёрной горы, то это он." },
    ["514c"] = { common = "А, шифровка! Да, тут я спец. Дай-ка взглянуть…" },
    ["515a"] = { common = "Состав Грязного Рыла? Гениально! Почему мне не пришло это в голову? Пожалуй, я добавлю свой коллоид разложения в эту хитрую смесь. Чтобы активировать отраву в смеси, Лидону понадобится крепкое зелье тролльей крови, немного чешуи наги из клана Пронзающего Гребня и глаза мурлоков из клана Рваный Плавник с южного берега Хилсбрада. Когда ты принесёшь ему все составляющие, он мигом всё сделает. Ох, как мне не терпится узнать о результатах его эксперимента!" },
    ["515c"] = { common = "У меня даже голова закружилась от возбуждения! Какой эксперимент! Ты мне очень помог. Мы будем сеять болезнь и смерть по всем этим землям!" },
    ["516a"] = { common = "Я получил сообщение, что группа нежити спряталась и готовит атаку против нас. Вооружённые этой информацией, мы можем повернуть всё другой стороной и напасть первыми, подавив их планы в самом зародыше. К сожалению, моя информация весьма обрывочная. Говорят, они скрываются в месте, называемом Погибель Берена. Точное местонахождение неизвестно, но, похоже, это пещера где-то в холмах, недалеко от участка, занятого даларанскими волшебниками. Я доверяю вашей изобретательности. Отыщите их и нанесите им поражение." },
    ["516c"] = { common = "Если наши разведчики и агенты продолжат предоставлять столь же ценную информацию, как эта, мы в мгновение ока очистим наши земли от армии Плети Короля-лича." },
    ["517a"] = { common = "Пришло время испытать новый эликсир. Но зачем же тратить хорошую, очень заразную болезнь на простых лягушек и собак? Давай устроим настоящее веселье во имя леди Сильваны. Ступай в Дун Гарок. Знаешь, это казармы, где вечно шныряют эти дворфики. Укради у них бочонок землекопского крепкого. Получив эту бочку, я устрою весёлую вечеринку!" },
    ["517c"] = { common = "Наконец-то! Теперь мы готовы действовать!" },
    ["518a"] = { common = "Муг'тол и огры Раздробленного Хребта захватили руины Альтерака. Наказать их всерьёз будет нелегко, если не проредить сначала ряды огров. А уж потом мы продолжим. Ясно? Отлично. Выполняй." },
    ["518c"] = { common = "Снег стал алым от крови огров, но мы не должны останавливаться, пока не втопчем дух и тело огров Раздробленного Хребта в грязь и снег." },
    ["519a"] = { common = "Тарг, Навозер и Гломмус – лейтенанты Муг'Тола. Они верны ему, хотя кто там разберёт, что вынуждает огров быть верными. Принеси мне их головы, и нам останется отрубить башку Муг'Толу вместе с короной." },
    ["519c"] = { common = "...а я-то думала, что для начала огры зверски воняют. Когда ты принесёшь мне голову Муг'Тола, я прикажу отнести её вместе с этими на пики Альтерака. Неплохой памятник тем, кто идёт против воли Тёмной Госпожи." },
    ["520a"] = { common = "Лейтенанты Муг'Тола мертвы, и нам остаётся только убить его самого и забрать корону Воли. Нет сомнений, ему не захочется с ней расставаться. Скорее всего, он ждёт тебя, учитывая... уменьшение числа его товарищей. Отыщи Муг'Тола и принеси мне его голову вместе с короной. Положим конец сопротивлению Раздробленного Хребта." },
    ["520c"] = { male = "Ты с честью выполнил свой долг. Голова Муг'Тола украсит высочайшую вершину среди руин Альтерака, и стражи смерти сотрут с лица земли остатки клана Раздробленного Хребта.", female = "Ты с честью выполнила свой долг. Голова Муг'Тола украсит высочайшую вершину среди руин Альтерака, и стражи смерти сотрут с лица земли остатки клана Раздробленного Хребта." },
    ["521a"] = { common = "Остаётся отнести корону Воли Шарлиндре в Подгород. Она уж передаст её леди Сильване. Но даже не думай воспользоваться ей в личных целях. Пусть тебе послужит уроком судьба Муг'Тола." },
    ["521c"] = { common = "Так значит, этой реликвией воспользовался огр, чтобы не исполнять волю Тёмной Госпожи… Странно, когда в такой небольшой вещи заключается великая сила. Которая попала в такие неуклюжие руки. Молодец. Я отнесу корону леди Сильване и доложу ей о твоих подвигах." },
    ["522a"] = { common = "Это контракт на убийство мирового судьи Генри Малеба. Он был опечатан красным воском с характерным оттиском кольца." },
    ["522c"] = { common = "Малеб изучает контракт. Теперь мне понятна подоплёка последнего нападения на Южнобережье. Наверное, Синдикат хочет добраться до меня, как и до моего предшественника!" },
    ["523a"] = { common = "Добытый тобой контракт был подписан бароном Вардусом, дворянином из бывшего королевства Альтерака, прославившегося холодным сердцем и необычайной жестокостью. Неудивительно, что за этим стоял барон. Отыщи его. Отыщи и сверши над ним суд. Должно быть, он прячется в одном из убежищ Синдиката – руинах Странбрада или долине на севере оттуда." },
    ["523c"] = { male = "Спасибо. У меня на душе полегчало, когда ты вышиб дух из этого злодея!", female = "Спасибо. У меня на душе полегчало, когда ты вышибла дух из этого злодея!" },
    ["524a"] = { common = "За соседней дверью стражи смерти держат нескольких заложников-фермеров. Верховный палач Дарталия подозревает, что среди них скрывается один из военных-стратегов. Очевидно, его нашли мёртвым в Чумных землях. Дарталия всегда заботится обо-мне и решила передать пленников мне в руки. Пора устроить этим фермерам вечеринку. Ох, повеселимся! Поставь гниющий бочонок на ковёр у них в комнате. Чумной напиток для всех!" },
    ["524c"] = { common = "Вы ставите гниющий бочонок на пыльный ковёр." },
    ["525a"] = { common = "Я расшифровал письмо, но не знаю, что с ним дальше делать. Вы нашли его у воров в предгорьях Альтерака? Очень странно... Надо доставить это письмо магистрату Южнобережья. Хотя письмо и зашифровано, это ближайший город к горам Альтерака, и если назревает какая-то опасность, то они должны об этом узнать." },
    ["525c"] = { common = "Малеб читает письмо. Это расшифровка письма, найденного вами в лагере Синдиката? Оно написано не вором, и даже не альтеракским аристократом. Похоже, у Синдиката есть связи с другими силами, и мне страшно подумать, что это за силы могут быть." },
    ["526a"] = { male = "Ты нашёл только один слиток светлостали – этого не хватит, чтобы выковать что-нибудь стоящее. Вернись и поищи ещё слитки. Думается, их растащили мурлоки, разграбившие корабль.", female = "Ты нашла только один слиток светлостали – этого не хватит, чтобы выковать что-нибудь стоящее. Вернись и поищи ещё слитки. Думается, их растащили мурлоки, разграбившие корабль." },
    ["526c"] = { male = "А, ты нашёл их! Теперь давай эту светосталь скуем в что-нибудь полезное?", female = "А, ты нашла их! Теперь давай эту светосталь скуем в что-нибудь полезное?" },
    ["527a"] = { male = "Когда говоришь со мной, стой по стойке \"смирно\", герой. Я нахожусь под прямым командованием Вариматраса. Наша задача – сдерживать распространение людей, покуда аптекари работают над составом новой чумы. По нашим сведениям город Хилсбрад очень уязвим. Твоё первое задание – прервать снабжение едой и прочим. Отправляйся на запад. Устрой налёт на самые северные фермы Хилсбрадских полей. И казни землевладельцев, фермеров Рея и Гетца.", female = "Когда говоришь со мной, стой по стойке \"смирно\", героиня. Я нахожусь под прямым командованием Вариматраса. Наша задача – сдерживать распространение людей, покуда аптекари работают над составом новой чумы. По нашим сведениям город Хилсбрад очень уязвим. Твоё первое задание – прервать снабжение едой и прочим. Отправляйся на запад. Устрой налёт на самые северные фермы Хилсбрадских полей. И казни землевладельцев, фермеров Рея и Гетца." },
    ["527c"] = { male = "Вольно, герой. Вижу, ты вернулся из боя. Мне доложили, что ты хорошо показал себя в Хилсбраде.", female = "Вольно, героиня. Вижу, ты вернулась из боя. Мне доложили, что ты хорошо показала себя в Хилсбраде." },
    ["528a"] = { male = "Слухи о нападении на северные фермы вызвали панику среди населения. Великолепно. Наши стражи смерти докладывают о крестьянах южного Хилсбрада, бегущих в поля. Эти глупцы надеются укрыться в садах, избежав гибели. Покажи им, как они заблуждаются. Возвращайся в Хилсбрадские поля и отыщи там трусливых крестьян. Рази их направо и налево во имя Тёмной Госпожи. Свободен!", female = "Слухи о нападении на северные фермы вызвали панику среди населения. Великолепно. Наши стражи смерти докладывают о крестьянах южного Хилсбрада, бегущих в поля. Эти глупцы надеются укрыться в садах, избежав гибели. Покажи им, как они заблуждаются. Возвращайся в Хилсбрадские поля и отыщи там трусливых крестьян. Рази их направо и налево во имя Тёмной Госпожи. Свободна!" },
    ["528c"] = { common = "Смерть всё крепче сжимает костлявую руку на горле Хилсбрада. Битва идёт хорошо." },
    ["529a"] = { common = "Люди Хилсбрада оказывают нам неожиданное сопротивление. Кажется, проблема в кузнеце, снабжающем горожан оружием. Необходимо прервать цепь снабжения. Убей кузнеца Верринтана вместе с учениками и возвращайся с партией железа. Нам оно пригодится, когда мы одержим победу над Хилсбрадом и нападём на Южнобережье." },
    ["529c"] = { male = "Задание выполнено, герой. И, надо сказать, выполнено на славу.", female = "Задание выполнено, героиня. И, надо сказать, выполнено на славу." },
    ["530a"] = { common = "Когда-то Валдред был моим лучшим другом, а потом убил мою жену. Горевать я уже не способен, но до сих пор жажду мести. Если ты убьёшь Валдреда и принесёшь мне его проклятые руки, я тебя награжу. По последним слухам, он был у Стены Седогрива в южном Серебряном бору. Небось, пытается сбежать в королевство Гильнеас." },
    ["530c"] = { common = "А, хорошо. Этими руками была убита моя жена, Делия. С тех пор я думал только о мести, и вот ты стал моим оружием. Возьми кольцо, которое вернул мне ранее. Делия так давно умерла, что я не нуждаюсь в этой безделушке. Лучше я оставлю себе эти руки в память о предательстве друга." },
    ["531a"] = { common = "Ради всего святого! Не приноси в Приют такое... это негигиенично, неприлично, не... не... негигиенично! Скорее убери её отсюда! Никому здесь не нужны твои страхолюдные трофеи!" },
    ["531c"] = { male = "Спасибо, что помог мне выполнить мой маленький план. Я много месяцев жаждала проучить этого надутого самовлюблённого мальчишку, а теперь нам это удалось! Вот, возьми, ты это заслужил.", female = "Спасибо, что помогла мне выполнить мой маленький план. Я много месяцев жаждала проучить этого надутого самовлюблённого мальчишку, а теперь нам это удалось! Вот, возьми, ты это заслужила." },
    ["532a"] = { common = "В Хилсбраде царит паника. Думаю, он скоро падёт. Но мы не должны ослаблять натиск, пока последние человеческие отродья не изжиты из этих холмов навеки. Невзирая на колоссальные потери, люди держатся вокруг своих вождей и не кладут оружия. Мы должны уничтожить их главу, чиновника Бернсайда, и весь городской совет. Заодно уничтожь и их главный документ, Хилсбрадское официальное объявление. И раз уж на то пошло, укради и городскую книгу регистрации." },
    ["532c"] = { male = "Вести о твоих победах в Хилсбраде быстро разносятся. Отличная работа, герой.", female = "Вести о твоих победах в Хилсбраде быстро разносятся. Отличная работа, героиня." },
    ["533a"] = { common = "Наконец-то до нас дошли сведения о местопребывании Гол'дира. Люди постоянно меняли места его заключения, но мы смогли сузить область поиска до большого лагеря Синдиката на севере отсюда. Ступай туда, и заполучи все доступные сведения." },
    ["533c"] = { common = "Наконец-то мы знаем, где держат Гол'дира. В лагере неподалёку отсюда. Будем надеяться, что на сей раз они не успеют подготовиться как прошлый раз, когда нас застали в расплох." },
    ["535a"] = { male = "Гр-рр... Раненый, умирающий, но не опускающий оружия. Не сомневаюсь, ты всё равно убьёшь меня, но если бы ты принёс мне немного эля из Южнобережья – вы ведь такое тоже пьёте? – я расскажу тебе то, что ты хочешь знать.", female = "Гр-рр... Раненый, умирающий, но не опускающий оружия. Не сомневаюсь, ты всё равно убьёшь меня, но если бы ты принесла мне немного эля из Южнобережья – вы ведь такое тоже пьёте? – я расскажу тебе то, что ты хочешь знать." },
    ["535c"] = { common = "Принимая во внимание мою неминуемую смерть – думаю, могу с уверенностью сказать, что это самый вкусный напиток в моей жизни... Вот, возьми – когда я помру, мне это всё равно не понадобится. Ну, слушай!" },
    ["536a"] = { common = "Меня перевели в Южнобережье из городской стражи Штормграда. Непонятно, как тут вообще люди живут... А как воняет со стороны пристани и днём и ночью! Да ещё старый Редпат на мою голову... Он хочет, чтобы я занялся мурлоками. Ха! Я едва могу заставить себя подойти к этим рыбам-переросткам на Западном побережье. Если ты разберёшься с ними вместо меня, я буду очень признателен." },
    ["536c"] = { common = "Надеюсь, этого хватит, чтобы убедить Крассена, что я – ха! – выполняю его приказы и избавляю Южнобережье от страшной и ужасной угрозы, жутких мурлоков! Нет ничего страшнее ярости рыбы-переростка!" },
    ["537a"] = { common = "Это письмо от существа, называющего себя Нагазом, членом сообщества Недремлющего Аргуса. Не знаю, что это за Аргус, но если он в союзе с Синдикатом, то представляет собой угрозу. Отыщи Нагаза и упомянутых в письме тёмных магов Недремлющего Аргуса. Найди их и убей. Ищи их в Высокогорье, на севере от Странбрада, где позиции Синдиката сильнее всего. Если повезёт, ты найдёшь там послов Недремлющего Аргуса." },
    ["537c"] = { male = "Молодец. Не хотелось бы, чтобы Недремлющий Аргус присоединился к Синдикату. Хотя тебе и удалось убить их главаря в этих землях, ясно, что Нагаз был чьим-то слугой. Похоже, Недремлющий Аргус пустил корни по всему нашему континенту. Или по всему миру.", female = "Умница. Не хотелось бы, чтобы Недремлющий Аргус присоединился к Синдикату. Хотя тебе и удалось убить их главаря в этих землях, ясно, что Нагаз был чьим-то слугой. Похоже, Недремлющий Аргус пустил корни по всему нашему континенту. Или по всему миру." },
    ["538a"] = { common = "Доброго дня вам. Если вы не против долгого путешествия, то у меня для вас найдётся задание, которое поможет пополнить библиотеку Штормграда. Вместе со старым королевством Альтерака во время войны погибла и огромнейшая библиотека. Жаль, что город разрушен, но вдвойне жаль, что пропал бесценный кладезь знаний! Мы должны восстановить всё, что можем. Южнобережье – ближайший к руинам Альтерака город. Отправляйтесь туда и поговорите с Хранителем мудрости Диббсом. Он направит вас к руинам, может быть, там вы сумеете найти книги..." },
    ["538c"] = { common = "Да, конечно, я помню Милтона. Такой типичный книжный червь, будь он здоров... И он совершенно прав. Руины Альтерака по-прежнему полны драгоценных документов, которые находятся под угрозой исчезновения! Теперь-то в Альтераке обитают огры, а их совершенно не волнуют памятники культуры..." },
    ["539a"] = { common = "Согласно регистрационной книге Хилсбрада, Лазуритовый рудник находится в руках Альянса. Более того, львиную долю руды, идущей на вооружение Альянса, добывают именно там. Хотя мы нанесли решительный удар по городу Хилсбраду, Альянс изо-всех сил защищает свой рудник. Рудник расположен на юге от Хилсбрада. Ступай туда и убей штейгера, человека по имени Бондс. Убей и его горняков. Альянс надолго запомнит этот урок." },
    ["539c"] = { common = "Тёмная Госпожа будет рада услышать, что у неё появился новый рудник, который поможет вооружить её бойцов." },
    ["540a"] = { common = "Мерзкие огры поселились в руинах Альтерака, и мне дурно при мысли, что они делают с драгоценными книгами из библиотеки. Спаси всё, что можно! Ступай в руины Альтерака и поищи там манускрипты, украденные ограми. Собери всё, что сможешь и принеси мне. Больше всего меня интересует одна книга – \"Рука Гри'лека\". В ней содержится древняя мудрость троллей, о которой я жажду узнать, а последняя копия этой книги находилась именно в руинах Альтерака." },
    ["540c"] = { common = "А, вот они! Великолепно! Я немедленно примусь за изучение \"Руки Гри'лека\"." },
    ["541a"] = { male = "Дворфы пришли на помощь людям? Проклятые мелкие твари! Что ж, испытаем силу так называемого Альянса. Посмотрим, решатся ли эти недорослики помогать людям, когда почувствуют наш гнев. Мы отлично знаем, где скрывается их цитадель в этих краях. Они построили свои казармы в юго-восточной части Хилсбрада, рядом со стеной Торадина. Это местечко зовётся Дун Гарок. Последняя цель этой битвы – осадить Дун Гарок, герой. Глава дворфов, капитан Железная Гора, должен умереть.", female = "Дворфы пришли на помощь людям? Проклятые мелкие твари! Что ж, испытаем силу так называемого Альянса. Посмотрим, решатся ли эти недорослики помогать людям, когда почувствуют наш гнев. Мы отлично знаем, где скрывается их цитадель в этих краях. Они построили свои казармы в юго-восточной части Хилсбрада, рядом со стеной Торадина. Это местечко зовётся Дун Гарок. Последняя цель этой битвы – осадить Дун Гарок, героиня. Глава дворфов, капитан Железная Гора, должен умереть." },
    ["541c"] = { common = "Твои подвиги на поле битвы достойны высочайшей хвалы." },
    ["542a"] = { common = "Мне понадобится время на изучение \"Руки Гри'лека\", хотя я не сомневаюсь, что Милтону не терпится вернуть книги в коллекцию Штормграда. Вот книги, добытые тобой в руинах Альтерака. Они уже упакованы и каталогизированы. Отнеси их Милтону Снопу в Штормград, он несомненно будет тебе признателен." },
    ["542c"] = { common = "О небо! Глазам своим не верю! Неужели они пережили падение Альтерака? И всех этих огров! Спасибо. Огромное спасибо! Вы помогли нам сохранить человеческие знания, и прибавили великолепия Королевской библиотеке Штормграда." },
    ["543a"] = { common = "Тиара Перенольда – старая семейная реликвия одного из древнейших семейств Альтерака, входившего в правящие круги до падения королевства. Говорят, что её изготовили мастера Стальгорна, украсив лучшими изумрудами. Когда Альтерак пал, тиара была утеряна, хотя поговаривали, что огрский маг Грел'борг Скряга нашёл её и теперь пытается разыскать на руинах Альтерака другие сокровища. Мы надеемся, что вы отыщете тиару." },
    ["543c"] = { common = "О, чудесно. Конечно, тиару нужно почистить, но вы, прямо-таки превзошли сами себя. Я велю привести тиару в порядок и немедленно помещу её в нашу сокровищницу. Примите мою благодарность за пополнение коллекции семейных реликвий." },
    ["544a"] = { common = "Я прибыл в Мельницу Таррен с исследовательскими целями, а пришлось разрешать кризис. Видишь ли, четверо Отрёкшихся несколько месяцев назад бежали из Подгорода. Они предали своих братьев, но что ещё хуже... они украли кое-что у Тёмной Госпожи. Эти воры вломились в надёжное хранилище и похитили четыре артефакта, необходимых нашим аптекарям для исследований. Сильвана жаждет вернуть эти артефакты. Воры бежали из Подгорода в Даларан, и волшебники спрятали их в Лордамерских выселках." },
    ["544c"] = { male = "Ты оказал Отрёкшимся огромную услугу. Нам очень не хватало этих артефактов. Хорошо, что Кеган и другие предатели получили по заслугам.", female = "Ты оказала Отрёкшимся огромную услугу. Нам очень не хватало этих артефактов. Хорошо, что Кеган и другие предатели получили по заслугам." },
    ["545a"] = { common = "Волшебники Даларана создали вокруг сердца своего города огромный магический купол. Некоторые говорят, что он призван защитить город от опасностей, которыми полнятся наши дни, другие же уверяют, будто волшебники захотели работать и строить планы в тишине и покое. Мне лично наплевать, зачем соорудили этот купол. Меня интересуют развалины на окраинах города, где могут быть спрятаны ценные магические предметы. К сожалению, все окрестности патрулируют волшебники и порабощённые ими элементали. Итак, напади на них и возвращайся, когда существенно сократишь их число." },
    ["545c"] = { common = "Замечательно. Теперь в руинах можно спокойно поискать артефакты, если быть осторожным. Спасибо." },
    ["546a"] = { common = "Я слышал, что Дарталия призвала тебя в строй, чтобы выступить против людей Хилсбрада. Как я завидую… Пока ты там развлекаешься – убиваешь людей, грабишь города, запугиваешь невинных – я торчу здесь, на страже мельницы Таррен. Может, ты смилостивишься над старым стражем смерти? Видишь, я собираю коллекцию человеческих черепов, а тебе предстоит убить немало смертных. Набери в ходе битвы тридцать черепов, принеси мне, и я тебе хорошо заплачу." },
    ["546c"] = { common = "Превосходные черепа! И какие красивые! Вот тебе обещанная плата!" },
    ["547a"] = { common = "Верховный палач Дарталия послала меня наблюдать за Дун Гароком издалека. Я разбил лагерь подальше от дворфов. Но пришло утро, мне нужно было вскипятить воду, и я пошёл за дровами. Вернувшись, я обнаружил, что мои вещи пропали. Очевидно, ко мне заглянули дворфийские разведчики из Дун Гарока и украли их. Мне нужен мой меч! Если ты сможешь вернуть его, я буду очень признателен. Там так много дворфов... будет нелегко понять, кто же из них вор." },
    ["547c"] = { male = "Ты нашёл его! Ах, как приятно чувствовать в руке знакомую рукоять. Премного благодарен!", female = "Ты нашла его! Ах, как приятно чувствовать в руке знакомую рукоять. Премного благодарен!" },
    ["549a"] = { common = "По приказу леди Сильваны все члены организации, именуемой Синдикат, приговариваются к смертной казни. Всех пленных казнят. В настоящий момент организация собирает силы в руинах крепости Дарнхольд на юго-востоке от мельницы Таррен. Всем, предоставившим доказательства своих подвигов верховному палачу Дарталии, будет дарована щедрая награда." },
    ["549c"] = { male = "Великолепно, герой. Такими темпами мы мигом очистим эти земли от синдикатской швали.", female = "Великолепно, героиня. Такими темпами мы мигом очистим эти земли от синдикатской швали." },
    ["550a"] = { male = "Поскольку ты проявил немалое мужество и стойкость в битве за Хилсбрад, я написала это рекомендательное письмо, описывающее твой героизм. Пусть его прочитает высшее командование. Отнеси моё письмо Вариматрасу в Подгород. Можешь гордиться собой, герой.", female = "Поскольку ты проявила немалое мужество и стойкость в битве за Хилсбрад, я написала это рекомендательное письмо, описывающее твой героизм. Пусть его прочитает высшее командование. Отнеси моё письмо Вариматрасу в Подгород. Можешь гордиться собой, героиня." },
    ["550c"] = { male = "Так это ты знаменитый герой, нанёсший сокрушительный удар по силам Альянса в Предгорьях Хилсбрада? Вести о твоих славных подвигах дошли до Подгорода. Если ты и впредь будешь проявлять подобный героизм, то тебя ожидает великое будущее в рядах бойцов Тёмной Госпожи. Хотя наша главная проблема – наступление с севера Плети Короля-лича, человеческий вопрос тоже не решён и мешает строить планы битвы. Однако ты сумел доказать, что люди могут пасть. И они падут.", female = "Так это ты знаменитая героиня, нанёсшая сокрушительный удар по силам Альянса в Предгорьях Хилсбрада? Вести о твоих славных подвигах дошли до Подгорода. Если ты и впредь будешь проявлять подобный героизм, то тебя ожидает великое будущее в рядах бойцов Тёмной Госпожи. Хотя наша главная проблема – наступление с севера Плети Короля-лича, человеческий вопрос тоже не решён и мешает строить планы битвы. Однако ты сумела доказать, что люди могут пасть. И они падут." },
    ["551a"] = { common = "На этот пергамент наложено заклинание, из-за чего надписи на нём невозможно расшифровать. Вы можете разобрать только одно слово вверху страницы: Нагаз" },
    ["551c"] = { common = "Опять зашифрованные записки? Хотел бы я уметь разгадывать шифры, чтобы разобрать все странные фрагменты записей, что доходят к нам из Альтерака. Но боюсь, мне не хватает знаний." },
    ["552a"] = { common = "Мастер Гелькулар почти превратился в Короля Мёртвых, когда его ритуальное логово в холмах обнаружила разъярённая толпа людей и зверски убила его. Хуже того, они похоронили моего учителя на кладбище Южнобережья. Немыслимое неуважение к великому волшебнику. Я его ученик, и хочу отомстить ненавистному городу. Первым делом нам понадобится жезл Гелькулара. Его ритуальное логово захватили йети. Жезл несомненно находится у одного из них." },
    ["552c"] = { male = "Ты нашёл его! Великолепно!", female = "Ты нашла его! Великолепно!" },
    ["553a"] = { common = "Вот, возьми Гелькуларов жезл. Он тебе понадобится. Гелькулар создал для своего заклятья три церемониальных погребальных костра. Пламя Азеля и пламя Вераза находятся в Пещерах предгорий. Пламя Узеля находится в пещере выше по склону, в северной части гор. Гелькуларов жезл необходимо зарядить в каждом из этих костров. Завершив ритуал, вонзи жезл в гробницу Гелькулара в Южнобережье, надёжно охраняемом человеческом городе на юге. Мы отомстим!" },
    ["553c"] = { common = "Из-под земли доносится глухой грохот." },
    ["554a"] = { common = "Геолог Грозовая Вершина – мастер дешифрования и декодирования. Если ты отнесёшь найденный пергамент ему, то при удачном стечении обстоятельств он сможет его прочитать. В настоящий момент Грозовая Вершина работает в штаб-квартире Геологов в Стальгорне. Если увидишь его, сообщи о нашем разговоре – в последнее время я много работы на него свалил." },
    ["554c"] = { common = "Мудрое решение. Всё равно я не верю, что у других учёных хватит умения, чтобы перевести этот свиток. А если он окажется интересным, не бойся – я непременно пошлю за тобой." },
    ["555a"] = { common = "Ты скоро поймёшь, что в Южнобережье готовят лучше, чем во всех землях к северу от Штормграда! Скажем, возьмём мой секретный рецепт черепахового супа. Иногда ко мне захаживают из самого Темнолесья, чтобы насладиться миской-другой. Правда, в последнее время, мне не удавалось его сварить. Я бы сам пошёл к озеру Лордамер у Даларана и поохотился на тамошних хрустогрызов, но это слишком опасно. Если ты принесёшь мне черепашьего мяса и смягчающих пряностей, я мигом сварю этой вкуснятины." },
    ["555c"] = { common = "Все будут в восторге – здесь снова подают нежный черепаховый суп шеф-повара Джессена!" },
    ["556a"] = { common = "Волшебники Даларана славятся своей связью с элементалями, могущественными созданиями из других измерений, которыми они управляют при помощи магических талисманов. Волхв Сиянье Бездны хотел бы изучить эти талисманы. Ступай на земли даларанских волшебников на западе от Хилсбрада и собери несколько талисманов. Такие талисманы носят многие жители Даларана, но я советую поискать их в выселках. Это гораздо безопаснее." },
    ["556c"] = { common = "Отличные талисманы. Хотя, кажется, из них немного выдохлась магия, оно и к лучшему. Пусть для начала наш колдун поэкспериментирует на менее активных образцах. Спасибо." },
    ["557a"] = { common = "Пока что колдун изучает каменные талисманы, но вскоре ему понадобится и другая часть – браслеты, связующие Стихии. Элементали носят их на запястье, что заставляет их выполнять волю мага. Убей побольше духов в руинах Даларана и собери с них браслеты Земли, и колдун будет доволен." },
    ["557c"] = { common = "Тебе удалось их найти. Надеюсь, элементали, с которых сняты эти браслеты не очень сопротивлялись? Хм... После смерти у меня атрофировалось не только сердце, но и чувство юмора заодно. Что ж, спасибо. Служа колдуну, служишь и Тёмной Госпоже, да." },
    ["559a"] = { male = "Ты не поверишь, Крассена не устроили все убитые нами – не скромничай, ты тоже приложил к этому руку. Теперь он хочет от меня доказательств их смерти. Чтобы я отрубил холодные склизские мурлочьи головы и принёс пред его очи!", female = "Ты не поверишь, Крассена не устроили все убитые нами – не скромничай, ты тоже приложила к этому руку. Теперь он хочет от меня доказательств их смерти. Чтобы я отрубил холодные склизские мурлочьи головы и принёс пред его очи!" },
    ["559c"] = { common = "Ох, во имя Света! С них же течёт на землю какая-то дрянь. Я к ним не притронусь! Рыбу ещё можно терпеть, но если у неё вырастают ноги и она ходит взад-вперёд... Я рыбы уже несколько недель не ел, и поверь мне, в Южнобережье это означает жизнь впроголодь." },
    ["560a"] = { common = "Знаешь, мне даже прикасаться к этим головам не хочется... Раз уж они у тебя, отнеси их Крассену от моего имени, а?" },
    ["560c"] = { male = "Так ты мальчик на посылках у Фаррена? Если ты помог ему добыть эти головы, большое тебе спасибо. Южнобережье нуждается в защитниках.", female = "Так ты девочка на посылках у Фаррена? Если ты помогла ему добыть эти головы, большое тебе спасибо. Южнобережье нуждается в защитниках." },
    ["561a"] = { common = "Пожалуйста, сообщи лейтенанту Оринелю, что я хотел бы, чтобы он занялся нагами, заселившими Восточное побережье. Когда он добьётся результатов, пусть лично доложит о них мне." },
    ["561c"] = { common = "Наги, значит. Похоже, Крассен получил те же сведения, что и я... Ха! Он не сможет возвыситься благодаря мне. Позволь объяснить." },
    ["562a"] = { common = "Мой бывший наставник из городской стражи Штормграда послал мне сообщение, что верховное командование Альянса обоспокоено появление наг. По слухам, тот, кто хорошо проявит себя в этой области, получит повышение – или, по крайней мере, новое назначение. Есть одна проблема... я не могу справиться с нагами. Разумеется, прекратить пьяную драку или скрутить воинственного вора я могу, но наги мне не по зубам. Помоги мне!" },
    ["562c"] = { common = "Разобравшись с нагами в Южнобережье, я могу не сомневаться в новом назначении. Я вернусь обратно в Штормград... И больше не увижу этот забытый Светом порт." },
    ["563a"] = { common = "Мне будет легко добиться, чтобы моё донесение прочитали. Новый капитан стражи, майор Самуэльсон, был моим учителем ещё в Штормграде. Ему не составит труда перевести меня обратно в столицу. Но придётся попросить тебя отнести моё донесение ему... Главное, чтобы старина Крассен ничего не узнал." },
    ["563c"] = { male = "Что такое? А... Значит, мой внимательный ученик занялся проблемой наг Южнобережья. Спасибо, что принёс это мне, я непременно приму это во внимание, пересматривая назначения в следующем месяце.", female = "Что такое? А... Значит, мой внимательный ученик занялся проблемой наг Южнобережья. Спасибо, что принесла это мне, я непременно приму это во внимание, пересматривая назначения в следующем месяце." },
    ["564a"] = { common = "Ничто так не злит меня так, как потеря отличных коней. И поверь, эти назойливые мертвяки, синдикатские бандюги и прочие ни на что не годные негодяи, лишили нас множества лошадок. Но я готов поклясться могилой моего прадедушки, что главный враг коней – горные львы Альтерака. Вечно осложняют мою жизнь! Ты считаешь себя героем? Тогда пойди, разберись с ними!" },
    ["564c"] = { common = "Отличные новости! Надо было сразу же найти нормального героя войны, чтобы он разобрался со зверюгами. Твой папка гордился бы тобой." },
    ["565a"] = { male = "Я, великий Бартоло, сделаю для тебя знаменитый во всём Альянсе, да и во всём мире, плащ из меха йети! Обыщи весь белый свет, и нигде прекрасней нет! Что, что я слышу, маленький герой? \"Бартоло, твои плащи лучше всех!\" Да, да! Мне не раз это говорили. Бартоло нужен рулон шерсти, плащ жителя холмов от искусного кожевника, тонкая нить и мех йети, конечно! Принеси мне все составляющие, и ты станешь счастливым обладателем одного из моих плащей!", female = "Я, великий Бартоло, сделаю для тебя знаменитый во всём Альянсе, да и во всём мире, плащ из меха йети! Обыщи весь белый свет, и нигде прекрасней нет! Что, что я слышу, маленькая героиня? \"Бартоло, твои плащи лучше всех!\" Да, да! Мне не раз это говорили. Бартоло нужен рулон шерсти, плащ жителя холмов от искусного кожевника, тонкая нить и мех йети, конечно! Принеси мне все составляющие, и ты станешь счастливым обладателем одного из моих плащей!" },
    ["565c"] = { common = "Пришло время для колдовской работы Бартоло! Мне не нужен ни посох волшебника, ни жезл мага. Ведь я, великий Бартоло, творю чудеса при помощи простой иглы и нити!" },
    ["566a"] = { common = "По приказу верховного палача Дарталии, человек по имени барон Вардус разыскивается по обвинению в многочисленных преступлениях против Отрёкшихся. Вардус является высокопоставленным членом преступной организации Синдикат. В последний раз его видели в Высокогорье Альтеракских гор, к северу от мельницы Таррен. Он приговаривается к смертной казни. Для получения награды необходимо предоставить доказательства его гибели верховному палачу Дарталии." },
    ["566c"] = { common = "Ты отлично работаешь. Барон Вардус мёртв, и число главарей Синдиката стало меньше. Недолго им осталось лютовать." },
    ["567a"] = { common = "Внимание: вооружены и очень опасны! Следующие люди из Хилсбрада объявлены вне закона, и верховный палач Дарталия предлагает награду за их головы: Клерк Гораций Белоконь. Разыскивается за убийство стража смерти Томма. Горожанин Вилкс. Разыскивается за убийство аптекаря Эли. Шахтёр Хакетт. Разыскивается за убийство стража смерти Фрая. Фермерша Калаба. Разыскивается за нападение из засады на караван с припасами из Подгорода. Все перечисленные преступники скрываются, и найти их нелегко. Награда будет выдана при предъявлении доказательств их смерти." },
    ["567c"] = { male = "Да ты неплохой охотник за головами, герой.", female = "Да ты неплохой охотник за головами, героиня." },
    ["568a"] = { male = "Тром'ка, герой! Ты на удивление вовремя оказался в Гром'голе. Как командир лагеря Вождя, я обязан защищать всех сторонников Орды в этих джунглях. Наша цель – обеспечить бесперебойное снабжение Каменора, а некоторые обитатели здешних мест нам мешают. Я поручаю тебе сократить численность ящеров рядом с Гром'голом. Добившись заметных успехов, возвращайся, и я дам тебе новое задание.", female = "Тром'ка, героиня! Ты на удивление вовремя оказалась в Гром'голе. Как командир лагеря Вождя, я обязан защищать всех сторонников Орды в этих джунглях. Наша цель – обеспечить бесперебойное снабжение Каменора, а некоторые обитатели здешних мест нам мешают. Я поручаю тебе сократить численность ящеров рядом с Гром'голом. Добившись заметных успехов, возвращайся, и я дам тебе новое задание." },
    ["568c"] = { male = "Ты исполнил свой долг с честью, герой.", female = "Ты исполнила свой долг с честью, героиня." },
    ["569a"] = { common = "Отправляясь в джунгли, мы не собирались воевать с местными племенами. Главное – снабжение Каменора. Увы, возник ряд сложностей. Местные огры заняли руины Мизжа на юго-востоке от Гром'гола. Невзирая на многочисленные предупреждения, они продолжают нападать на наши караваны. Я приказываю тебе разобраться с этими упёртыми ограми. Отправляйся в развалины и попытайся выбить их оттуда. По крайней мере, преподай им хороший урок." },
    ["569c"] = { male = "Отлично. Ты с честью послужил вождю.", female = "Отлично. Ты с честью послужила вождю." },
    ["570a"] = { male = "Орда должна узнать о силе магии джунглей и подчинить её себе. Мне уже удалось добиться успеха, и я могу пользоваться могучими заклинаниями. Я сделаю для тебя особую вещь, отважный герой. Принеси мне когти тенебрюхих пантер и клык тигрицы. Учти, что клык должен быть безупречно ровным. Эти твари разгуливают по всем джунглям, но тебе не придётся далеко ходить – просто перейди реку рядом с руинами Мизжа на юго-востоке.", female = "Орда должна узнать о силе магии джунглей и подчинить её себе. Мне уже удалось добиться успеха, и я могу пользоваться могучими заклинаниями. Я сделаю для тебя особую вещь, отважная героиня. Принеси мне когти тенебрюхих пантер и клык тигрицы. Учти, что клык должен быть безупречно ровным. Эти твари разгуливают по всем джунглям, но тебе не придётся далеко ходить – просто перейди реку рядом с руинами Мизжа на юго-востоке." },
    ["570c"] = { common = "Ты превосходно знаешь джунгли. Отличная добыча! Я возблагодарю духов за то, что они пожертвовали таких зверей на благо Орды." },
    ["571a"] = { common = "Следующий компонент будет нелегко найти. Чтобы связать перья, когти и чистый клык, мне понадобится волшебный шнурок. Нам подойдёт лишь сухожилие старой гориллы. Его можно добыть только у старых горилл из Мглистой долины. Они кормятся к востоку от Пиратской Бухты. Только сухожилие должно быть в идеальном состоянии. Быть может, тебе понадобится убить нескольких зверей, чтобы понять, что именно мне нужно, но результат того стоит." },
    ["571c"] = { common = "Превосходное сухожилие. Твои усилия скоро окупятся." },
    ["572a"] = { common = "То, что тебе удалось добыть у зверей из семейства кошачьих – лишь первое, что требуется для создания могущественного зачарованного предмета. Меж тем украшения джунглей, усиленные при помощи моих ритуалов, неплохо послужат тебе в деле помощи Орде и Вождю. Теперь же собери для меня перья тропических ловцов. Эти твари как правило прикрепляют перья на лапы. На юге от Гром'гола, недалеко от большой арены, есть такое племя ящеров." },
    ["572c"] = { common = "Великолепно. Я немедленно их подготовлю." },
    ["573a"] = { common = "Остаётся лишь одно составляющее, и я смогу наложить чары на колье. К югу отсюда, близко от западного побережья, высоко над утёсами, располагается Святой источник. Он вызывает множество конфликтов среди религиозных учёных. Все расы Азерота утверждают, что воды освящены именно для их народа. Вот моё последнее поручение: принеси мне воду Святого источника. Соблюдай осторожность. Сейчас его окрестности захватили наги. С ними тоже следует разобраться." },
    ["573c"] = { male = "Ты принёс мне воду Святого источника, и я могу наложить чары на церемониальное колье. Носи его с гордостью, во имя Вождя и мощи Орды.", female = "Ты принесла мне воду Святого источника, и я могу наложить чары на церемониальное колье. Носи его с гордостью, во имя Вождя и мощи Орды." },
    ["574a"] = { common = "Теперь, после сокращения численности регулярных войск Курцена, тебе придётся вступить в схватку с его особыми отрядами. Они либо выбираются в лес и убивают наших солдат, либо отсиживаются позади посёлка Курцена, в пещере, называемой Схрон. Я знакома со многими воинами Курцена, и все они отличаются прекрасной подготовкой, верностью и жестокостью. Задание непростое. Если ты сможешь их одолеть, доложи об этом лейтенанту Дорену, моему командиру. Он захочет услышать об этом из первых уст." },
    ["574c"] = { common = "Сержант Йохва поверила в твои способности, а я поверил ей. Мы и надеяться не могли на подобный удар по силам Курцена. Я боялся, что мы, повстанцы, совсем одни, и не сможем справиться с гениальным полковником. Быть может, теперь у нас есть надежда." },
    ["575a"] = { common = "\"Лучший мастер-кожевник Южных морей и старого и нового мира.\" Вот как меня называют! Меня! Дриззлика! Лучшим коже... Кхе-кхе. Короче. Мои товары славятся по всему свету как наилучшие по мнению всех экспертов! Я только что получил заказ от директора Ридлвокса из Союза ремонтников на дюжину его любимых превосходных сапог. Не скрою, это самая популярная модель. Чтобы приступить к раскройке, мне нужны шкуры кроколисков. Их можно добыть у реки в северной части Тернистой долины." },
    ["575c"] = { common = "Эти шкуры отлично подойдут. Качество не слишком важно, учитывая, что они идут на внутреннюю отделку сапог, главное, чтобы носить было удобно. Если шкуры жестковаты, я вымочу их в тигриной крови. Вот они, секреты мастерства, да?" },
    ["576a"] = { common = "Стой! Кто идёт? Аррр, кому я нужен без волшебного глаза. Мало того, что я лишился зрения в бою! Но тогда мне свезло, и один волшебник зачаровал для меня особый стеклянный глаз, и я снова мог видеть. А вчера на меня по дороге накинулись пираты Кровавого Паруса и отобрали у меня глаз! Кажется, эти типы чувствуют себя в Пиратской бухте как дома. Не поможешь старому морскому волку вернуть зрение?" },
    ["576c"] = { male = "Лопни моя селезёнка! Разрази меня гром! Ты нашёл мой прекрасный глаз! Проверим, годится ли он по-прежнему. Хо! Я вижу, вижу!!!", female = "Лопни моя селезёнка! Разрази меня гром! Ты нашла мой прекрасный глаз! Проверим, годится ли он по-прежнему. Хо! Я вижу, вижу!!!" },
    ["577a"] = { common = "Что ж, я раскроил основу сапог, получается превосходно, но на подбой шкур не хватит. \"Что же делать, Дриззлик?\" – спросишь ты. К счастью, ты говоришь со мной, и я скажу тебе, как мы поступим! Подбой всё равно никто не видит, поэтому мы используем более толстую и дешёвую шкуру кроков с озера Назферити." },
    ["577c"] = { common = "Мои сапоги не хуже колбасы. Выглядят отлично, на вкус прекрасны. Я говорю, что внутри сверхкачественное мясо и приправы, и вы едите их с удовольствием. Так куда приятнее – и вкуснее – если не заглядывать внутрь." },
    ["578a"] = { common = "Если правду говорят о гоблине-маге и элементалях воды, живущих на острове, значит я могу заполучить Камень Приливов! Найди этот остров... И выясни, что происходит. И если ты хочешь узнать подробнее о Камне Приливов, отнеси эту записку в библиотеку Штормграда, они найдут тебе книгу, в которой я впервые прочитал эту легенду. Неужели Газбан в самом деле нашёл Камень?.." },
    ["578c"] = { common = "Значит, легенды не лгут! Немыслимо! Теперь надо отыскать способ одолеть проклятье Камня Приливов, если мы хотим найти его. Проклятья – дело магов. Значит, надо обратиться к одному из них." },
    ["580a"] = { common = "На подходе к Отвесным скалам, как раз в тот момент, когда старые добрые Внутренние земли показались на горизонте, нас настигла жуткая буря. Мы думали – всё, нам каюк, море нас проглотит. Но старый Алкач знает, что такое жидкая храбрость! У кэпа был ящик портвейна \"Пупелливербос\", который мы взяли трофеем у одного пирата по пути в Штормград. В общем, когда с Внутренних земель налетел шторм, я налёг на грог. И тут шхуну захлестнула большая волна и смыла бутылки за борт. Кэп всыплет мне по первое число, если ты не поможешь их найти." },
    ["580c"] = { male = "Лопни моя селезёнка! Ты нашёл грог кэпа! Я по гроб жизни тебе обязан, друг. Похоже, снаружи разыгрался шторм. Пока он не пройдёт, я согрею нутро грогом из одной из этих славных бутылочек...", female = "Лопни моя селезёнка! Ты нашла грог кэпа! Я по гроб жизни тебе обязан, подруга. Похоже, снаружи разыгрался шторм. Пока он не пройдёт, я согрею нутро грогом из одной из этих славных бутылочек..." },
    ["581a"] = { common = "Нас постиг злой рок. И коснулось это младшего сына моего вождя. Как у нас и заведено, мы отдали его на воспитание племени Гурубаши в Зул'Гурубе, но после того, как племя Чёрного Копья последовало за орком Траллом, бедняга Йеннику оказался потерян для нас. Меня прислали в Тернистую долину из далёкого Оргриммара на поиски сына вождя. Я думаю, он в руках племени Кровавого Скальпа. Если ты хочешь помочь мне, напади на них. Они живут к северу отсюда. Собери их клыки и принеси мне." },
    ["581c"] = { common = "Отличные клыки. Значит, у тебя хватило сил на сражение с племенем Кровавого Скальпа. И это очень хорошо, потому что охота далеко не закончена." },
    ["582a"] = { common = "Мы должны узнать, мёртв ли Йеннику. Убей как можно больше охотников за головами из клана Кровавого Скальпа и забери у них сушёные головы. Набери как можно больше голов, и я осмотрю их, чтобы убедиться, что среди них нет головы Йеннику. Если племя Кровавого Скальпа убило Йеннику, да падёт шестьсот-летнее проклятье на душу их предводителя, Ган'зулаха! Ступай. Охотников за головами можно найти в Руинах Зуулдая и Зул'Кунды, в северной части побережья." },
    ["582c"] = { common = "Спасибо. Я осмотрю эти головы и узнаю, пал ли бедняга Йеннику под ударом топора охотника за головами." },
    ["583a"] = { male = "Добро пожаловать в Тернистую долину! Быть может, ты не знаешь об этом, но этот дворф – единственный и неповторимый Хеминг Эрнестуэй, прославленный герой Альянса и великий охотник на крупную дичь. Он не слишком жалует гостей, но на твою долю, кажется, выпало немало приключений, герой? Хеминг и сам многое повидал – может, вы с ним найдёте общий язык. Ступай, поговори с ним. Вдруг он научит тебя охотничьим хитростям.", female = "Добро пожаловать в Тернистую долину! Быть может, ты не знаешь об этом, но этот дворф – единственный и неповторимый Хеминг Эрнестуэй, прославленный герой Альянса и великий охотник на крупную дичь. Он не слишком жалует гостей, но на твою долю, кажется, выпало немало приключений, героиня? Хеминг и сам многое повидал – может, вы с ним найдёте общий язык. Ступай, поговори с ним. Вдруг он научит тебя охотничьим хитростям." },
    ["583c"] = { male = "Приятно познакомиться. Давно в наши края не забредал герой. Я здесь с одной-единственной целью – поймать крупного и хитрого зверя. Раз ты, так сказать, личность героическая, может, захочешь принять участие в охоте? Впрочем, сначала покажи, на что способен. Я научу тебя охотиться на ящеров. Ажек – на тигров. А сэр Эрлгедин – мастер выслеживать пантер. Покажи нам своё искусство, и сможешь принять участие в большой охоте.", female = "Приятно познакомиться. Давно в наши края не забредал героиня. Я здесь с одной-единственной целью – поймать крупного и хитрого зверя. Раз ты, так сказать, личность героическая, может, захочешь принять участие в охоте? Впрочем, сначала покажи, на что способен. Я научу тебя охотиться на ящеров. Ажек – на тигров. А сэр Эрлгедин – мастер выслеживать пантер. Покажи нам своё искусство, и сможешь принять участие в большой охоте." },
    ["584a"] = { common = "Я не нашёл Йеннику среди голов, хвала Великому Змею за это. Но мы не сильно продвинулись в наших поисках. Необходимо выяснить правду, и, боюсь, она известна лишь вождю племени Кровавого Скальпа и его знахарю. Они враги племени Чёрного Копья, и просто так говорить не будут, поэтому мы должны вырвать правду из их мёртвых губ! Принеси мне головы Ган'зулаха и Неззилока Зловещего и помести их в этот котёл. Эти тролли живут в глубине руин Зул'Кунды. Принеси их головы... а уж говорить мы их заставим." },
    ["584c"] = { common = "Вы кладёте в котёл головы Ган'зулаха и Неззилока..." },
    ["585a"] = { male = "Голова Неззилока начинает говорить. Это правда. Я знаю, куда увели дитя племени Чёрного Копья. Ты одолел меня и связал мой дух, но я всё равно не буду говорить даром! Племя Кровавого Скальпа враждует с племенем Дробителей Черепов. Чтобы добиться от меня ответа, укради три трофейных черепа у племени Дробителей Черепов и положи их к нам, чтобы мой дух обрёл рабов в Пустоте. Один череп возьми в Балиа'ма, другой – в Зиата'джаи, а последний – в Зулмамбве.", female = "Голова Неззилока начинает говорить. Это правда. Я знаю, куда увели дитя племени Чёрного Копья. Ты одолела меня и связала мой дух, но я всё равно не буду говорить даром! Племя Кровавого Скальпа враждует с племенем Дробителей Черепов. Чтобы добиться от меня ответа, укради три трофейных черепа у племени Дробителей Черепов и положи их к нам, чтобы мой дух обрёл рабов в Пустоте. Один череп возьми в Балиа'ма, другой – в Зиата'джаи, а последний – в Зулмамбве." },
    ["585c"] = { male = "Да. Ты сослужил мне добрую службу. Когда мой дух освободится, я войду в Пустоту и обрету трёх отличных слуг! Ты – гордость своего клана, герой, и умилостивил меня.", female = "Да. Ты сослужила мне добрую службу. Когда мой дух освободится, я войду в Пустоту и обрету трёх отличных слуг! Ты – гордость своего клана, героиня, и умилостивила меня." },
    ["586a"] = { male = "*Голова Ган'зулаха начинает говорить.* Будь ты проклят! И будь прокляты твои предки!!! Лишь кровь и месть остудят мою ярость, поэтому если ты этого добиваешься, то... сделай вот что: Отправляйся в сердце владений Дробителей Черепов на востоке. Убей самых лютых воинов, и если выживешь... брось вызов их вождю, Анатеку Жестокому. Ха! Принеси мне его разбитую броню, если сможешь! Да оторвёт он у тебя руки и ноги и бросит медленно гнить. Да станешь ты добычей падальщиков!", female = "*Голова Ган'зулаха начинает говорить.* Будь ты проклята! И будь прокляты твои предки!!! Лишь кровь и месть остудят мою ярость, поэтому если ты этого добиваешься, то... сделай вот что: Отправляйся в сердце владений Дробителей Черепов на востоке. Убей самых лютых воинов, и если выживешь... брось вызов их вождю, Анатеку Жестокому. Ха! Принеси мне его разбитую броню, если сможешь! Да оторвёт он у тебя руки и ноги и бросит медленно гнить. Да станешь ты добычей падальщиков!" },
    ["586c"] = { male = "Мне не хочется верить тебе, но увы, ты несомненно выполнил моё задание. Теперь, когда Анатек пал, гнев мой поостыл. Твоя сила приведёт тебя к великим свершениям. Но однажды... Мы встретимся в Пустоте, и снова померяемся силой. Я буду ждать тебя.", female = "Мне не хочется верить тебе, но увы, ты несомненно выполнила моё задание. Теперь, когда Анатек пал, гнев мой поостыл. Твоя сила приведёт тебя к великим свершениям. Но однажды... Мы встретимся в Пустоте, и снова померяемся силой. Я буду ждать тебя." },
    ["587a"] = { male = "Ах, жизнь моряцкая! Не скажу, что она хороша, но это моя жизнь. Пришвартовавшись в порту, я люблю выпить бутылочку грога и нюхнуть хорошего табачку. Вредные привычки, но что за пират без пороков, а? Только представь, как я был разочарован, узнав, что местный травник распродал весь товар. Говорит, мол, новую поставку перехватили эти проклятые пираты Кровавого Паруса. Готов поспорить, что бесстрашный герой вроде тебя сможет убедить их поделиться товаром, а?", female = "Ах, жизнь моряцкая! Не скажу, что она хороша, но это моя жизнь. Пришвартовавшись в порту, я люблю выпить бутылочку грога и нюхнуть хорошего табачку. Вредные привычки, но что за пират без пороков, а? Только представь, как я был разочарован, узнав, что местный травник распродал весь товар. Говорит, мол, новую поставку перехватили эти проклятые пираты Кровавого Паруса. Готов поспорить, что бесстрашная героиня вроде тебя сможет убедить их поделиться товаром, а?" },
    ["587c"] = { common = "Отличная работа! И я даже в море отплыть не успел! Не знаю даже, как тебя благодарить." },
    ["588a"] = { male = "Неззилок говорит. Ты сумел угодить и мне, и вождю, и я скажу тебе то, что ты хочешь знать… Юный Йеннику навеки потерян для своего клана. Его забрал к себе знахарь Занзил Отверженный. Теперь Занзил полностью подчинил себе его тело и душу, и лишь сильнейшая магия может освободить его. Ты такой магией не владеешь, герой. Быть может, племя Чёрного Копья, ваши союзники, могло бы подарить надежду на спасение Йеннику. Но лично я сомневаюсь.", female = "Неззилок говорит. Ты сумела угодить и мне, и вождю, и я скажу тебе то, что ты хочешь знать… Юный Йеннику навеки потерян для своего клана. Его забрал к себе знахарь Занзил Отверженный. Теперь Занзил полностью подчинил себе его тело и душу, и лишь сильнейшая магия может освободить его. Ты такой магией не владеешь, героиня. Быть может, племя Чёрного Копья, ваши союзники, могло бы подарить надежду на спасение Йеннику. Но лично я сомневаюсь." },
    ["588c"] = { common = "Занзил Отверженный?? Если Йеннику и правда попал в руки этого тролля, могущественного и злого знахаря, то надежды почти нет. Почти. Не больше букашечки. Но малая надежда лучше, чем совсем никакой." },
    ["589a"] = { common = "Легенды повествуют о драгоценном камне, сокрытом в самом сердце Тернистой долины. Мы зовём его Оком Разума, и он хранит в себе великую мощь. Если добыть этот камень, быть может, удастся вернуть Йеннику из тьмы. Я попрошу духов джунглей помочь нам в поисках Ока Разума. Тем временем отправляйся в рудник Хрустальной шахты на юго-востоке отсюда и добудь пульсирующие синие осколки из железозубых василисков. Осколки встречаются очень редко, но без их магии мы не сможем подчинить себе Око Разума." },
    ["589c"] = { common = "Молодец. Эти осколки правильной формы, и я уже слышу их голос. Пока тебя не было, я говорил с духами джунглей. Теперь я знаю, где находится Око Разума… ...И кто его охраняет." },
    ["590a"] = { male = "Что? ЧТО?! Денег хочешь? Не должен я тебе никаких денег. Письмо? Какое письмо? Может, ещё и подерёмся? Ну, приятель, давай! Вот ещё, деньги я должен...", female = "Что? ЧТО?! Денег хочешь? Не должен я тебе никаких денег. Письмо? Какое письмо? Может, ещё и подерёмся? Ну, подружка, давай! Вот ещё, деньги я должен..." },
    ["590c"] = { male = "Невероятно! Какое мастерство! А я-то думал, ты будешь лёгкой добычей. Да, хорошенько ты меня отделал. Вот обещанные деньги... правда, не столько, сколько я сказал сначала, но должен же я был немного приврать.", female = "Невероятно! Какое мастерство! А я-то думал, ты будешь лёгкой добычей. Да, хорошенько ты меня отделала. Вот обещанные деньги... правда, не столько, сколько я сказал сначала, но должен же я был немного приврать." },
    ["591a"] = { common = "Око Разума находится у огра-мага на востоке отсюда, в глубине холма Мош'Огг. Этого мага зовут Май'Зот, и я помню его с тех пор, как племя Чёрного Копья обитало в Тернистой долине. Он жесток и силён. А если у него есть Око Разума, тем могущественней его магия. Вступи с бой с Май'Зотом и отними у него Око Разума. Задание опасное, но лишь так мы можем надеяться спасти Йеннику." },
    ["591c"] = { male = "Тебе удалось добыть Око? Твою силу должно воспевать в легендах! Кроме того, добывая око ты одолел Май'Зота и отправил его в Пустоту. Вот почему духи молчали о нём. Хорошо, что он покинул мир плоти и крови, но боюсь, что теперь, в царстве духов он снова захватит власть. Впрочем, об этом будем беспокоиться в другой раз. А теперь я проведу ритуал, чтобы приспособить Око Разума для наших нужд...", female = "Тебе удалось добыть Око? Твою силу должно воспевать в легендах! Кроме того, добывая око ты одолела Май'Зота и отправила его в Пустоту. Вот почему духи молчали о нём. Хорошо, что он покинул мир плоти и крови, но боюсь, что теперь, в царстве духов он снова захватит власть. Впрочем, об этом будем беспокоиться в другой раз. А теперь я проведу ритуал, чтобы приспособить Око Разума для наших нужд..." },
    ["592a"] = { common = "Я превратил Око Разума в самоцвет Души. Он послужит двоякой цели: оглуши при его помощи Йеннику, а затем помести самоцвет ему на голову, чтобы поймать его душу. Потом отнеси камень Нимбойе. Йеннику живёт у Занзила Отверженного, в руинах Абораза на Хрустальном взморье далёкого мыса Тернистой долины." },
    ["592c"] = { male = "Победа! Ты освободил Йеннику от воли Занзила и выполнил задание, которое я считал безнадёжным. Наше племя будет воспевать твоё имя, и мы на каменных плитах напишем повесть о тебе, чтобы она никогда не забылась.", female = "Победа! Ты освободила Йеннику от воли Занзила и выполнила задание, которое я считал безнадёжным. Наше племя будет воспевать твоё имя, и мы на каменных плитах напишем повесть о тебе, чтобы она никогда не забылась." },
    ["594a"] = { common = "Записка написана красивым почерком. В ней значится: Любому, кто может мне помочь. Прошу тебя, не оставь меня в нужде. Великий Небогрив держит меня в плену на острове в Южных морях. По ночам я смотрю на чужие звёзды, полускрытые листвой деревьев, но в самую хорошую погоду на северо-западе я вижу Южное взморье и большие корабли на юго-западе. Молю тебя, мой будущий спаситель, помоги мне." },
    ["594c"] = { male = "Ты явился, чтобы освободить меня?", female = "Ты явилась, чтобы освободить меня?" },
    ["595a"] = { male = "Ты не прочь подзаработать, а, приятель? Понять не могу, зачем сухопутной крысе вроде тебя понадобилось помогать Разбойникам Черноводья, но не гнать же тебя в шею! Мы только что бросили якорь в Пиратской бухте, и уже прослышали, что наши соперники – гнусные, подлые пираты Кровавого Паруса – пустили корни в южной части Тернистой долины. Все мои ребята слишком увлеклись грогом и девками! А мне нужен разведчик. Осмотри залив на севере от Пиратской бухты рядом с Гибельным берегом и расскажи мне, что там творится.", female = "Ты не прочь подзаработать, а, подружка? Понять не могу, зачем сухопутной крысе вроде тебя понадобилось помогать Разбойникам Черноводья, но не гнать же тебя в шею! Мы только что бросили якорь в Пиратской бухте, и уже прослышали, что наши соперники – гнусные, подлые пираты Кровавого Паруса – пустили корни в южной части Тернистой долины. Все мои ребята слишком увлеклись грогом и девками! А мне нужен разведчик. Осмотри залив на севере от Пиратской бухты рядом с Гибельным берегом и расскажи мне, что там творится." },
    ["595c"] = { common = "На крышке бочки лежит карта, на которой торопливо нацарапана пара слов, и несколько монет." },
    ["596a"] = { common = "Меня послали в Гром'гол на помощь Нимбойе, но... У меня здесь свои дела. Племя Кровавого Скальпа – наш заклятый враг. Трофеи, собранные с врагов, дают власть над ними. Ты можешь помочь нашему племени, открыв охоту на врага. Племя Кровавого Скальпа живёт на севере отсюда. Убей побольше троллей этого племени и забери у них ожерелья Кровавых костей. Собери как можно больше, и я награжу тебя." },
    ["596c"] = { common = "А, замечательно. Я сварю их, высосу из них силу и сотру в порошок, и дух наших врагов ослабеет! Вот. Возьми это в знак благодарности." },
    ["597a"] = { common = "На карте Пиратской бухты нарисован красный крестик именно там, где вы стоите. Ниже имеется подпись: \"Разбейте здесь лагерь и сидите тихо. Не нападайте, пока не получите сигнал с южного командного поста. Если заметите кого постороннего, сразу убивайте.\"" },
    ["597c"] = { male = "Конечно, я помню тебя, герой. Вижу, ты уже вернулся из разведки...", female = "Конечно, я помню тебя, героиня. Вижу, ты уже вернулась из разведки..." },
    ["598a"] = { male = "Раз ты принёс трофеи от племени Кровавого Скальпа, у меня есть для тебя другое задание. На юго-востоке живёт племя Дробителей Черепов, и мы воевали с ними много лет. Хотя племя Чёрного Копья давно не живёт в Тернистой долине, мы не забыли раздоров с Дробителями Черепов. Так что начни на них охоту. Собери побольше ожерельев расколотых костей и принеси их мне. Помоги нам, и заслужишь признательность племени Чёрного Копья.", female = "Раз ты принесла трофеи от племени Кровавого Скальпа, у меня есть для тебя другое задание. На юго-востоке живёт племя Дробителей Черепов, и мы воевали с ними много лет. Хотя племя Чёрного Копья давно не живёт в Тернистой долине, мы не забыли раздоров с Дробителями Черепов. Так что начни на них охоту. Собери побольше ожерельев расколотых костей и принеси их мне. Помоги нам, и заслужишь признательность племени Чёрного Копья." },
    ["598c"] = { common = "Велика твоя сила, раз тебе удалось заполучить эти ожерелья. Клан Дробителей Черепов пал под твоими ударами, как молодые ростки под тяжёлыми шагами василиска! Хвала твоим деяниям." },
    ["599a"] = { common = "Лопни моя селезёнка! Значит, пираты Кровавого Паруса собираются напасть на Пиратскую бухту? Вот наглость-то! Этот город испокон века был в руках Пиратов Черноводья! Значит, дела обстоят хуже, чем я думал. Немедленно расскажи об этом командиру флота Морскому Рогу! Этот старый морской волк шатается где-то по городу..." },
    ["599c"] = { male = "Пираты Кровавого Паруса собираются напасть на Пиратскую бухту? С тем же успехом они могут сразу сброситься с Отвесных скал. И всё же ты оказал моему флоту большую услугу, передав мне эти сведения. Прими благодарность Разбойников Черноводья.", female = "Пираты Кровавого Паруса собираются напасть на Пиратскую бухту? С тем же успехом они могут сразу сброситься с Отвесных скал. И всё же ты оказала моему флоту большую услугу, передав мне эти сведения. Прими благодарность Разбойников Черноводья." },
    ["600a"] = { common = "Торговая Компания ведёт операции в Тернистой долине, которые не дают трудолюбивым гоблинам вроде меня честно зарабатывать деньги! Пожалуйста, помоги мне! Торговая Компания обосновалась возле Хрустальной шахты к северу отсюда. Внутрь они проникнуть не могут из-за злобных василисков, но всё равно умудряются добывать Поющие кристаллы в ближайших холмах. Отбери у них эти кристаллы, показав тем самым, что джунгли им не принадлежат. И.. э... принеси в доказательство сами кристаллы!" },
    ["600c"] = { male = "Отлично! Чудесно! Я за них много выручу!!! Торговая Компания сунулась не в те джунгли, а? Нам всем станет лучше, если они уберутся отсюда, верно? Спасибо. Ты сделал доброе дело.", female = "Отлично! Чудесно! Я за них много выручу!!! Торговая Компания сунулась не в те джунгли, а? Нам всем станет лучше, если они уберутся отсюда, верно? Спасибо. Ты сделала доброе дело." },
    ["601a"] = { common = "Элементалей воды несомненно призвал Газбан, гоблин-волшебник, который нашёл Камень Приливов, если верить слухам. Мы знаем, что обретший этот камень оказывается проклят, и с тех пор то существует, то нет... Быть может, удастся снять проклятье. Один даларанский маг может исследовать следы магии на браслетах элементалей. Отправляйся на остров и принеси несколько штук." },
    ["601c"] = { common = "Я не могу определить навскидку, какие из этих браслетов подойдут, но хотя бы один должен сгодиться. Отнеси их в Даларан, пусть на них посмотрит маг. Не могу же я, в самом деле, уехать из Пиратской бухты ради какого-то старого мага? Не то, чтобы я беспокоился, что кто-то попытается занять моё место и стать новым бароном. Никто не посмеет встать на пути у Ревилгаза." },
    ["602a"] = { common = "Насколько я знаю, маги Даларана заняты восстановлением своего разрушенного города. Несомненно, один из них найдёт время посмотреть на браслеты. Я знаю про магов одно – они не смогут устоять перед возможностью разгадать запутанную магическую головоломку. Возьми сумку с браслетами элементалей воды и узнай, не прольют ли они свет на проклятье Камня. Лучше всего обратиться к верховному магу Ансарему Руноплету. Я уже имел с ним дело, и его знания велики." },
    ["602c"] = { common = "Камень Приливов? Очень интересно. Быть может, вас это удивит – несколько лет назад я написал книгу, посвящённую легендам империи Гурубаши. Я знаю об этом камне довольно много. По крайней мере, на одном из этих браслетов я вижу остатки магии, которые явно поддаются анализу. Посмотрим..." },
    ["603a"] = { common = "Маг, который владеет Камнем, может умножить его силу при помощи некой точки фокуса... вроде алтаря. Чтобы не допустить этого, необходим предмет равной силы. Как ни странно, я знаю одну очень подходящую вещь: древний кинжал, ещё одну из тролльских реликвий. Только есть... небольшая проблема. Я нашёл этот кинжал, странствуя по Тернистой долине, и отдал его своей своевольной дочери, которая сбежала в Пиратскую бухту и стала пираткой." },
    ["603c"] = { common = "Мой кинжал? Ты издеваешься? Ты хочешь услышать, как я превратилась из лучшего бойца на ножах в Пиратской бухте в посмешище для всех пиратов? Я проиграла схватку с одним из пиратов Кровавого Паруса – они редкие мерзавцы! – и он забрал мой кинжал в качестве трофея. Одним острым языком славу бойца не поддержишь..." },
    ["604a"] = { common = "Кразз высоко ценит твою преданность Разбойникам Черноводья. Я доверяю тебе задание, очень важное для нашего флота. Проникни на так называемый южный командный пост, который пираты Кровавого Паруса основали на Диком взморье. Разграбь весь лагерь и принеси мне их карты и записи приказов. Так мы выясним, что замышляют эти ублюдки." },
    ["604c"] = { common = "Отлично. Теперь, когда их планы нам известны, это лишь вопрос времени. Подумать только, эти глупцы бросили якорь недалеко от мыса." },
    ["605a"] = { common = "Поющие кристаллы добывают только в Тернистой долине, и некоторые покупатели готовы немало за них отсыпать. Кому их толкнуть, мне ясно, но проклятая Торговая Компания не даёт собирать кристаллы честным предпринимателям вроде меня. Я хочу тебя нанять. Василиски Тернистой долины питаются этими кристаллами. Благодаря им у них прочная шкура, и иногда из неё можно добыть качественные кристаллы. Годится шкура любого василиска, но на северном побережье, южнее Зул'Кунды, они не такие свирепые." },
    ["605c"] = { common = "Ага! Отличные осколки. То, что надо! Вот твоя доля, и... с тобой приятно иметь дело." },
    ["606a"] = { common = "Вот кого я терпеть не могу, так это тех, кто не отдаёт карточные долги! Мне задолжали несколько партнёров по игре. Не поможешь собрать с них мзду? Во-первых, есть Филипп \"Трусишка\", который вечно торчит у причала. Он проиграл мне кругленькую сумму на прошлой неделе, и я хочу её получить! Только для этого надо его хорошенько припугнуть. Ступай, поохоться на старых горилл из Мглистой долины. Набери из них потрохов и отнеси Трусишке. Только не говори, что они обезьяньи, пусть в штаны со страху наложит!" },
    ["606c"] = { common = "Ох! Откуда у вас это? Нет, не говорите. Я не хочу знать! Кто вас прислал? Морской волк?" },
    ["607a"] = { common = "Вот, возьмите этот кошель и отнесите его Морскому Волку. И передайте, что я собирался ему заплатить! Клянусь!!! Я всего лишь немного перебрал и заблудился по пути, и... знаете, как бывает. Он поймёт – не нужно применять силу!" },
    ["607c"] = { male = "Хе-хе, отличная работа! И как, сильно Трусишка перетрусил, когда ты показал ему потроха? Ха! Я читаю его как раскрытую книгу! Играя с ним в карты, нельзя не выиграть! Спасибо за помощь. Пришёл твой черёд получить плату...", female = "Хе-хе, отличная работа! И как, сильно Трусишка перетрусил, когда ты показала ему потроха? Ха! Я читаю его как раскрытую книгу! Играя с ним в карты, нельзя не выиграть! Спасибо за помощь. Пришёл твой черёд получить плату..." },
    ["608a"] = { male = "Ну и наглец этот Фираллон! Он бы и Озеро Хрустальное на лодке не переплыл, куда ему вести против нас весь свой флот! Пираты Кровавого Паруса поплатятся за свою беспечность. Теперь мы знаем все их планы и нападём первыми. Хотя зачем посылать целый флот, если хватит отряда отважных искателей приключений? путник, возьми с собой самых опытных бойцов, ступай на место высадки Фираллона и лиши пиратов Кровавого Паруса всех командиров. Весь флот отправится на дно следом за ними...", female = "Ну и наглец этот Фираллон! Он бы и Озеро Хрустальное на лодке не переплыл, куда ему вести против нас весь свой флот! Пираты Кровавого Паруса поплатятся за свою беспечность. Теперь мы знаем все их планы и нападём первыми. Хотя зачем посылать целый флот, если хватит отряда отважных искателей приключений? путница, возьми с собой самых опытных бойцов, ступай на место высадки Фираллона и лиши пиратов Кровавого Паруса всех командиров. Весь флот отправится на дно следом за ними..." },
    ["608c"] = { common = "Ах, что за великий день для Разбойников Черноводья! Трижды ура тебе!" },
    ["609a"] = { common = "Список сокращается, но должники всё ещё остались. Далее идут Моури \"Деревянная Нога\" Вилкинс, Джон-Джон Ворон и Чаки \"Недотёпа\". Эти паршивые собаки просрочили платежи на много месяцев, я-то думал, они поэтому из города сбежали! Потом, правда, мне сказали, что их прокляли и заколдовали, и они бродят по развалинам в джунглях. Но меня их судьба не волнует – мне бы своё вернуть! Их видели на северо-востоке отсюда, в руинах Абораза и руинах Жубуваля. Отыщи их и забери у них мои вещи." },
    ["609c"] = { common = "Отлично! За это я выручу кругленькую сумму, особенно за то, что спрятано внутри ноги Моури! Спасибо! Надеюсь, эти трое усвоили урок: никогда не ставь на кон то, что не можешь отдать. Может быть, они поняли это слишком поздно... Но надо было думать, с кем садишься играть." },
    ["610a"] = { common = "Так тебя прислал мой ОТЕЦ? Я думала, старик давно махнул на меня рукой. Это он виноват, что я сбежала. С чего он взял, что я только и мечтаю о скучной жизни среди заплесневелых книг и седых, горбатых и надутых магов! Если тебе нужен мой кинжал, можешь отобрать его у \"Красавчика\" Дункана, одного из пиратов Кровавого Паруса. Приставь ему нож к спине, и он с радостью отдаст тебе мой клинок." },
    ["610c"] = { common = "Тебе удалось одолеть Дункана? Значит, ты не совсем салага, как кажется с первого взгляда. Пожалуй, это означает и то, что мне не стоит в ближайшее время вызывать тебя на бой!" },
    ["611a"] = { male = "Значит, ты ищешь какой-то алтарь? Я не так хорошо разбираюсь в развалинах, как мой отец, но мне приходилось слышать о затонувшем городе троллей рядом с островом, про который ты спрашивал. Посмотри там. Ты вернул мне нож, поэтому можешь пока им воспользоваться... но не забудь принести его обратно, когда закончишь дела!", female = "Значит, ты ищешь какой-то алтарь? Я не так хорошо разбираюсь в развалинах, как мой отец, но мне приходилось слышать о затонувшем городе троллей рядом с островом, про который ты спрашивала. Посмотри там. Ты вернула мне нож, поэтому можешь пока им воспользоваться... но не забудь принести его обратно, когда закончишь дела!" },
    ["611c"] = { common = "Поразительно! Камень Приливов! Он займёт достойное место в моей коллекции древних артефактов троллей. Видишь, создаётся впечатление, что это и есть окаменевший прилив? Великолепно!" },
    ["613a"] = { common = "Проклятье! Этот Моури поставил на свою ногу замок, и я не могу её открыть! Его сокровища внутри, и именно их он мне должен! Мне необходим ключ, чтобы вскрыть этот замок. Мори нередко играл в кости с ограми Мош'Огг у них на холме на северо-востоке. Он успел рассказать мне, что ему пришлось спасаться бегством после прошлой игры, потому что больно много выиграл. Может быть, его ключ у огров. Но если так, придётся убить целую толпу, чтобы его отыскать..." },
    ["613c"] = { male = "Ты нашёл его! Тысяча благодарностей. Ты мне так помог! Вот, возьми – ты заработал это сполна!", female = "Ты нашла его! Тысяча благодарностей. Ты мне так помогла! Вот, возьми – ты заработала это сполна!" },
    ["615c"] = { common = "Привет, привет, путник. Капитан рассказал мне, что ты собирался найти Неголаша, верно?" },
    ["616a"] = { common = "Барон Ревилгаз велел мне не упускать слухов о странных событиях и местах в округе Пиратской бухты и всей Тернистой долины. Обычно я не придаю большого значения историям про призраков и прочую чушь, но моряки в таверне говорили об острове элементалей недалеко от побережья. Мол, там духи Воды и сумасшедший призрак гоблина. Если тебе встретится Ревилгаз, перескажешь ему эту историю?" },
    ["616c"] = { common = "Интересно. Кажется, я недавно читал книгу, в которой говорилось о чём-то в этом духе… А, разумеется, легенды троллей. Если Кразек говорит правду, то вскоре к моей коллекции древних артефактов и реликвий добавится Камень Приливов." },
    ["617a"] = { common = "Ищешь работу? Если ты не боишься трудностей, могу тебе предложить одно дельце. У меня есть дружбан, Гроу, который зашибает бешеные деньги, продавая то, что наги называют стеблями акириса. Это очень ценная морская водоросль. Он за неё отлично платит. Притащи мне десять стеблей этой травки, и мы сторгуемся. Наги живут на берегу к северу отсюда." },
    ["617c"] = { male = "Молодец. Не так уж трудно было добыть десять стеблей акириса, а? Я вполне сочувствую нагам, но каждый как-то должен зарабатывать на жизнь.", female = "Умница. Не так уж трудно было добыть десять стеблей акириса, а? Я вполне сочувствую нагам, но каждый как-то должен зарабатывать на жизнь." },
    ["618a"] = { common = "Неголаш – великан-обжора. Когда они уничтожили наш корабль, Неголаш бросился прямиком на кухню. В отличие от его товарищей, команда его не очень интересовала. Ему хотелось вина... и жареных крылышек канюка. Это моё коронное блюдо, рецепт я привёз из самих Бесплодных земель! Если ты хочешь приманить великана, добудь вина и кучу крылышек канюка. Сложи их в нашу старую шлюпку, которая причалена на юго-востоке отсюда. Когда Неголаш почует запах еды, он непременно явится!" },
    ["618c"] = { male = "Ты забрал саблю у Неголаша! Я не верил, что мне повезёт! Встретив тебя, моя удача вернулась, без сомнения! Спасибо! И если я когда-нибудь заполучу новый корабль, и ты захочешь прокатиться, то ты будешь на нём почётным гостем.", female = "Ты забрала саблю у Неголаша! Я не верил, что мне повезёт! Встретив тебя, моя удача вернулась, без сомнения! Спасибо! И если я когда-нибудь заполучу новый корабль, и ты захочешь прокатиться, то ты будешь на нём почётной гостьей." },
    ["621a"] = { common = "Занзил Отверженный и его приспешники живут в руинах Жубуваля и Абораза, на северо-востоке от Пиратской бухты. Его изгнали из племени. Почему? Ну… Занзил научился подчинять себе разум других, и его страшатся собственные командиры. Он заставляет своих приспешников принимать смесь из тропических растений, которые подавляют их волю и укрепляют тела. Эта смесь пригодилась бы и другим, желающим подчинить себе других. Принеси мне образцы этой смеси, я найду им применение." },
    ["621c"] = { common = "А, отлично! Вот твоя плата. И ещё немного сверх... за молчание." },
    ["622a"] = { common = "Пока тебя не было, я починил твой горшок и даже приделал к нему свисток. Больше того, смотри! На дне появился новый нож, который запросто рубит кости! Да-да, теперь этот горшок – настоящая радость повара! Не сомневаюсь, владелец будет доволен." },
    ["622c"] = { common = "Готово! Чудесно, я могу готовить обед! Большое спасибо. Надеюсь, в Пиратской бухте с тобой ничего не случилось. Там всякое бывает... Говорят, иногда гоблины утаскивают пьяных моряков на галеры, приковывают цепями и увозят неизвестно куда..." },
    ["623a"] = { male = "Раз уж ты здесь, я тебе вот что скажу. Пока тебя не было, я получил послание от Гроу. Его очень порадовала последняя поставка, и клиент немедленно захотел получить ещё акириса. Я собираюсь в Терамор не раньше, чем через неделю, но если ты не против двинуть в путь прямо сейчас, почему бы тебе не отвезти товар? Хочешь поприключаться? Ты знаешь, где находятся Пылевые топи? Только будь осторожен, в Тераморе может быть опасно.", female = "Раз уж ты здесь, я тебе вот что скажу. Пока тебя не было, я получил послание от Гроу. Его очень порадовала последняя поставка, и клиент немедленно захотел получить ещё акириса. Я собираюсь в Терамор не раньше, чем через неделю, но если ты не против двинуть в путь прямо сейчас, почему бы тебе не отвезти товар? Хочешь поприключаться? Ты знаешь, где находятся Пылевые топи? Только будь осторожна, в Тераморе может быть опасно." },
    ["623c"] = { male = "Что?! Мне некогда с тобой трепаться, герой. Если ты собираешься попусту тратить моё время, лучше сразу убирайся. Что? Тебя прислал Блоудс, да? *Капер Грой внимательно рассматривает свёрток.* Неплохо, неплохо. Ещё один свёрток – и клиент будет счастлив. Думаю, следующий вопрос будет про деньги, а? Ну разумеется! Вот, бери монеты и совет в придачу: убирайся-ка подобру-поздорову.", female = "Что?! Мне некогда с тобой трепаться, героиня. Если ты собираешься попусту тратить моё время, лучше сразу убирайся. Что? Тебя прислал Блоудс, да? *Капер Грой внимательно рассматривает свёрток.* Неплохо, неплохо. Ещё один свёрток – и клиент будет счастлив. Думаю, следующий вопрос будет про деньги, а? Ну разумеется! Вот, бери монеты и совет в придачу: убирайся-ка подобру-поздорову." },
    ["624a"] = { common = "Есть мост, изукрашен резьбою, красивый на нём узор К востоку от Мёртвого Ветра и к югу от Красногорья Под ним тебя ждёт подсказка ль, улика ль – как назовёшь. И будет на Болоте Печали лежать, пока не найдёшь." },
    ["624c"] = { common = "Намокший пергамент даёт вам новую подсказку..." },
    ["625a"] = { common = "Калимдор далёкий ждёт тебя давно, Где надеждам к сроку сбыться не дано. Ты в Степях почуешь вкус пыли на губах, Ну а в топях пылевых – лишь печаль и страх. Но на юго-запад путь тебя манит, Мрак пещеры тайну для тебя хранит." },
    ["625c"] = { common = "Вы находите заплесневелый свиток." },
    ["626a"] = { common = "Спеши же в славный Лордерон! Давно тебя он ждёт. Там с мором, гибелью и тьмой сражается народ. Пусть не страшит тебя война и битвы шум и гам — Зато задание своё исполнить сможешь там. Вот берег Внутренних земель, где шумный водопад, Там, там под водами его тебя ждёт дивный клад!" },
    ["626c"] = { common = "Вы открываете сундук, чтобы обнаружить…" },
    ["627a"] = { common = "В Теснине Сухоусов - далеко на севере, в нагорье Арати - есть пещера. Там добывают редкие полезные ископаемые – кровавые камни. Да, они там не лучшего качества, но даже самые плохие кровавые камни высоко ценятся... теми, кто знает что с ними делать. Я – знаю. Я починю твой разбитый горшок, но пока я работаю над ним, принеси мне образцы кровавого камня. Если ты принесёшь их достаточно, я награжу тебя. Ах, да, если ты не умеешь добывать полезные ископаемые... попроси кого-нибудь помочь тебе!" },
    ["627c"] = { male = "А, великолепно! Ты оказал мне большую услугу. Вот твоя плата...", female = "А, великолепно! Ты оказала мне большую услугу. Вот твоя плата..." },
    ["628a"] = { common = "Подбой готов, осталось сделать верхний слой. На него идут только наилучшие шкуры взрослых кроколисков. Они крепче и представляют собой лучшую основу для узоров, которыми славится линия превосходных сапог. Хотя найти эту ценную шкуру нелегко, мне подходит лишь шкура старого солоноводного кроколиска. Эти твари выходят лишь на защиту молоди, поэтому может понадобиться убить несколько молодых зверей, чтобы выманить нужного." },
    ["628c"] = { common = "Здорово! Благодаря твоей помощи я выполню этот заказ и отправлю его директору Ридлвоксу на следующем корабле в Нижнюю шахту. Быстрее, чем обещал! Я сделал лишнюю пару, возьми её за работу. Всё за счёт Дриззлика. И помни, если нужны тебе сапоги, к Дриззлику ты поскорей прибеги!" },
    ["629a"] = { common = "Давным-давно вода затопила древний город троллей рядом с Гибельным берегом. Мы зовём это место Коварным рифом, потому что в развалинах поселились мурлоки, которые нападают на всех, кто осмелится приблизиться. Среди руин есть древняя табличка, повествующая о древнем герое троллей, Гри'леке. Это сказание священно в племени Чёрного Копья, и хотя сама табличка слишком велика и её не унесёшь, я хочу получить хотя бы осколок, чтобы поместить его в святилище в нашем новом городе, Оргриммаре." },
    ["629c"] = { common = "Хорошо. Когда я вернусь в Оргриммар, этот осколок будет помещён в священное место. Он будет напоминать нам о силе и чести Гри'лека. Спасибо. Твои деяния говорят о крепнущей дружбе с племенем Чёрного Копья." },
    ["630a"] = { common = "Путник, ты и те, кого ты сможешь позвать мне на помощь — моя последняя надежда. Меня держит в плену великий Король Мукла. Он повелевает зверями на этом острове, и они держат меня здесь помимо моей воли на этой цепи. Если ты сможешь убить моего мучителя и отыскать ключ к кандалам, я буду навеки у тебя в долгу. Я часто слышу шаги Короля Муклы на юго-восточной стороне острова. Соблюдай осторожность, справиться с ним нелегко." },
    ["630c"] = { common = "Путник, ты спас меня от большого позора. Если бы у меня была возможность, я бы хотела предложить тебе место среди моего племени. Но, я всё же могу предложить тебе этот перстень, за твоё мужество и благородство которое ты показал" },
    ["631a"] = { common = "Я помню, как горы содрогнулись от ужаснейшего взрыва. Не слабо рвануло, скажу я тебе! На мосту Тандола погибли лучшие из наших солдат. Длинная Коса говорит, что дворфы Чёрного Железа ещё заплатят нам за всё до конца этой войны. Но сейчас у нас отчаянное положение, подкрепления всё нет и нет. Длинная Коса отправил Ржавого Засова на разведку к восточному мосту – посмотреть, можно ли защитить мост теми силами, которые сейчас у нас есть. Прошло уже несколько дней. Мы не можем отправить солдат на поиски – Дун Модр осаждён... Быть может, ты согласишься поискать нашего разведчика?" },
    ["631c"] = { common = "Вы натыкаетесь на труп дворфа. На шлёме отчётливо видна надпись: \"Эбенезер Ржавый Засов\"." },
    ["632a"] = { common = "Кажется, бедняга Ржавый Засов попал в засаду дворфов Чёрного Железа. Возле его остывшего тела лежит клочок пергамента. Расскажите Рагу Каменщику о случившемся и передайте ему пергамент." },
    ["632c"] = { common = "Какой ужас... Бедный, бедный Эбенезер." },
    ["633a"] = { male = "Во имя Света, только не это! Бедняга Ржавый Засов. Ты меня опечалил. Но его жертва будет не напрасной! В пергаменте сказано, что Кам Гневливый – тот, кто организовал нападение, – приказал заложить взрывчатку под мостом Тандола на границе с нагорьем Арати. Если ему удастся очередная диверсия, то мы лишимся поставок с севера! Взрыв нужно предотвратить. Сделай всё возможное, чтобы спасти мост Тандола, и возвращайся ко мне. Ты – наша единственная надежда.", female = "Во имя Света, только не это! Бедняга Ржавый Засов. Ты меня опечалила. Но его жертва будет не напрасной! В пергаменте сказано, что Кам Гневливый – тот, кто организовал нападение, – приказал заложить взрывчатку под мостом Тандола на границе с нагорьем Арати. Если ему удастся очередная диверсия, то мы лишимся поставок с севера! Взрыв нужно предотвратить. Сделай всё возможное, чтобы спасти мост Тандола, и возвращайся ко мне. Ты – наша единственная надежда." },
    ["633c"] = { male = "Мост спасён! Ты помог не только мне и королю Магни, но и всему народу Каз Модана! Теперь нужно продержаться до прибытия подкрепления...", female = "Мост спасён! Ты помогла не только мне и королю Магни, но и всему народу Каз Модана! Теперь нужно продержаться до прибытия подкрепления..." },
    ["634a"] = { male = "Я попрошу тебя о ещё одном одолжении, герой. Мы ожидаем подкрепление из Стальгорна. Рогго принёс сведения о лагере воинов Альянса к северу отсюда. Они расположились на нагорье Арати, возле Опорного пункта. Отправься туда и отыщи капитана Ниалс. Спроси у очаровательного капитана, не выделит ли Альянс нам отряд солдат, чтобы помочь отбить Дун Модр и мост Тандола.", female = "Я попрошу тебя о ещё одном одолжении, героиня. Мы ожидаем подкрепление из Стальгорна. Рогго принёс сведения о лагере воинов Альянса к северу отсюда. Они расположились на нагорье Арати, возле Опорного пункта. Отправься туда и отыщи капитана Ниалс. Спроси у очаровательного капитана, не выделит ли Альянс нам отряд солдат, чтобы помочь отбить Дун Модр и мост Тандола." },
    ["634c"] = { common = "Передай мои соболезнования Длинной Косе и его солдатам. Я искренне опечалена вестью о трагедии на мосту Тандола и падении Дун Модра... Но знайте, что и Стромгард пал! Именно поэтому мы сейчас стоим у Опорного пункта. Впереди – битва за наш великий город. Долг и честь не позволяют мне покинуть нагорье до тех пор, пока над Стромгардом не взовьётся гордое знамя нашего короля! Придётся Длинной Косе обходиться своими силами..." },
    ["635a"] = { common = "Осколок пульсирует у вас в руках… Вам кажется, что он молит о чём-то, пытается передать послание того, кто нуждается в вашей помощи. Вам является видение – в северных горах Арати из земли торчит сияющий кристалл. Вас так и тянет к этому месту." },
    ["635c"] = { common = "Кристалл пульсирует, будто в него заключена живая сила." },
    ["637a"] = { common = "Промокший и потрёпанный конверт разваливается в руках, и в ладонях остаётся письмо на нескольких страницах. Каждая буковка выведена с удивительной аккуратностью. Письмо адресовано некой миссис Саре Баллу из Стальгорна. Оно начинается: \"Дорогая Сара...\"" },
    ["637c"] = { male = "Неужели ты видел моего Салли подо льдом? Прошу, скажи, что это не так! Дай-ка я прочитаю, что он написал...", female = "Неужели ты видела моего Салли подо льдом? Прошу, скажи, что это не так! Дай-ка я прочитаю, что он написал..." },
    ["638a"] = { common = "Торас Троллебой мёртв, а Стромгард разрушен. Вол'джин велел мне приложить все усилия, чтобы вырвать легендарный меч Трол'калар из рук людей. Тогда мы сможем воспользоваться им в грядущих битвах с троллями Зул'Гуруба. Зенгу, один из наших опытных охотников, отправился в Павший Молот в северо-восточной части нагорья Арати, чтобы проследить за этим." },
    ["638c"] = { male = "Как дела, герой? Вол'джин дал нам непростое задание, и если ты хочешь предложить свою помощь, мы с радостью её примем.", female = "Как дела, героиня? Вол'джин дал нам непростое задание, и если ты хочешь предложить свою помощь, мы с радостью её примем." },
    ["639a"] = { common = "В древние времена тролли воевали с Араторской империей и нашим самым могучим противником, лордом Игнеусом Стромским по прозвищу Троллебой. Он бросался в бой с мечом Трол'каларом в руке – \"убийцей троллей\", на их древнем наречии. Но теперь сыновья Троллебоя ослабели, а цитадель их разрушена. Меч защищён несколькими печатями, которые были распределены между выжившими защитниками Стромгарда, и мы должны их отыскать. Первую из печатей захватил Синдикат, должно быть, она находится у одного из их людей в Стромгарде." },
    ["639c"] = { common = "Отлично! Это хорошее начало для сбора всех печатей, которые нам понадобятся, чтобы извлечь Трол'калар из могилы Троллебоя." },
    ["640a"] = { common = "Могила Тораса Троллебоя защищена тремя печатями, первую из которых вы уже раздобыли у Синдиката. Остальные две достать будет сложнее, поскольку ими владеет гораздо более сильное ополчение Стромгарда. Печать Торадина была разделена на одиннадцать частей сыном Тораса Галеном, а потом он распределил эти фрагменты между стромгардскими защитниками Соберите фрагменты и принесите их Тор'гану, троллю-шаману, – он сможет восстановить целостность печати." },
    ["640c"] = { common = "А, так вам нужно воссоздать печать! Это будет не слишком сложно... все фрагменты на месте, а магическую структуру будет легко преобразовать. Пожалуй, вам бы лучше закрыть глаза." },
    ["641a"] = { common = "Восстановление прошло без сучка и задоринки. Теперь печать можно использовать, чтобы отпереть могилу Троллебоя. Верните печать Зенгу. Несомненно, у него найдутся ещё для вас задания." },
    ["641c"] = { common = "Мы на полпути к тому, чтобы извлечь Трол'калар из могилы Троллебоя. Мы не вполне уверены в том, где находится третья печать, поскольку владеющие ею, похоже, много передвигаются по нагорью Арати. Но я верю, что вам удастся её отыскать." },
    ["642a"] = { common = "Меня зовут Мизраэль. Я принцесса духов земли, и мои пленители – гиганты – поймали меня в ловушку глубоко под нагорьем Арати. С миром на поверхности я могу говорить только при помощи этих кристаллов. Пожалуйста, помоги мне. У союзников гигантов – кобольдов из племени Сухоусов – есть такие же кристаллы, они находятся в Теснине Сухоусов, к востоку отсюда. Чтобы объединить их силу, нужно отобрать у кобольдов крупицы Мощи Мизраэли. Прошу тебя, помоги мне!" },
    ["642c"] = { common = "Ах, тебе удалось активировать те кристаллы. Я уже чувствую, что начинаю приходить в себя! Но, увы, до свободы ещё далеко..." },
    ["643a"] = { common = "Хотя принц едва ли может похвастаться властью над Стромгардом, не говоря уж обо всём нагорье Арати, тем не менее он разъезжает с остатками своей кавалерии по всей области. Я не могу сказать, зачем он это делает, но кто поймёт, как мыслят эти люди? Какова бы ни была причина, более важно то, что он отдал одну из своих печатей лейтенанту Храброзову, командиру кавалерии. Найдите его и принесите мне эту печать." },
    ["643c"] = { common = "Потеря командира кавалерийского отряда станет серьёзным ударом для стромгардских защитников. К тому же – что ещё лучше – это значит, что нам осталось найти лишь одну печать, чтобы заполучить себе Трол'калар." },
    ["644a"] = { common = "Последняя из печатей, необходимых, чтобы отпереть могилу Тораса Троллебоя, хранится у его сына. Он обитает в Стромгарде, в часовне, в том районе, что контролируется ополчением. У принца Галена хорошая охрана, да и сам он боец не промах, так что это задание может оказаться наиболее сложным." },
    ["644c"] = { male = "Удачный денёк, герой. Кровь рода Троллебоев больше не будет беспокоить мой народ, и печати, необходимые для извлечения Трол'калара, теперь у нас в руках. Скоро, очень скоро мы ударим по ненавистным троллям Зул'Гуруба.", female = "Удачный денёк, героиня. Кровь рода Троллебоев больше не будет беспокоить мой народ, и печати, необходимые для извлечения Трол'калара, теперь у нас в руках. Скоро, очень скоро мы ударим по ненавистным троллям Зул'Гуруба." },
    ["645a"] = { common = "Что это? Когда четыре печати оказались вместе, они соединились, образовав единую печать. Нет сомнений, что она сможет разбить охранные заклинания, наложенные на могилу Троллебоя. Останки Троллебоя захоронены в святилище позади часовни в Стромгарде. Принесите же Трол'калар." },
    ["645c"] = { common = "При совмещении линий на верхней стороне могилы Троллебоя с сияющими линиями печати Игнеуса вспышка света поглощает печать, и легендарный меч Трол'калар освобождается из каменных объятий." },
    ["646a"] = { common = "Медленно угасает свет. Меч Трол'калар, упрятанный в каменные ножны, освобождён." },
    ["646c"] = { male = "Поколениями силы Штрома и Аратора истребляли троллей. Теперь их величайшее оружие – в наших руках. Больше мы не будем топтаться на месте во влажных лесах Зул'Гуруба. Ты оказал нам серьёзную помощь, и тролли Чёрного Копья в долгу перед тобой. Я позабочусь о том, чтобы меч был доставлен Нимбойе в Гром'гол.", female = "Поколениями силы Штрома и Аратора истребляли троллей. Теперь их величайшее оружие – в наших руках. Больше мы не будем топтаться на месте во влажных лесах Зул'Гуруба. Ты оказала нам серьёзную помощь, и тролли Чёрного Копья в долгу перед тобой. Я позабочусь о том, чтобы меч был доставлен Нимбойе в Гром'гол." },
    ["647a"] = { common = "Ох, и хлебнул я вчера самогона! Знай Длиннокос, что я отрубился на посту, он оторвал бы мне голову. Башка раскалывается, жуть. И в ушах гремит, будто осадные орудия вокруг грохочут. Ой-ой, а времени сколько! Я обещал мастеру-пивовару Бочкопузу из Южнобережья вернуть должок своим самогоном. А осталось до истечения срока действия долга всего пятнадцать минут! Отнеси ему самогон, будь другом! И поскорее!" },
    ["647c"] = { common = "Ах, ничто не греет так, как глоток самогона Туманника Маккрила! А я-то думал, что этот паразит опять просрочит платёж. Спасибо, дружище! Огромное тебе спасибо!" },
    ["648a"] = { common = "Из динамика снова слышится искажённый помехами голос гнома: \"Мне необходимо перегнать КПХ-семнадцать/TN в просторное и безопасное место, чтобы провести длительную процедуру наладки. Проводите робота из того места, где вы его обнаружили, в... ну, скажем, в Порт Картеля! Это самое подходящее место, и там достаточно просторно, чтобы подготовить аппарат к новому полёту. Проводите робота в порт, а затем сообщите об этом мне. Я живу в Пиратской бухте, меня зовут Карлс Пропеллерз. Конец связи!\"" },
    ["648c"] = { common = "А, так это вы великий спаситель КПХ-семнадцать/TN! У меня просто слов нет, настолько я вам благодарен! Моя серия автономных роботов постоянно нуждается в усовершенствованиях, однако ваша помощь сберегла мне немало часов кропотливой работы, и дорогостоящих деталей вдобавок! Прошу вас, выбирайте любую из этих готовых моделей. Ещё раз спасибо вам! Мы с моими роботами – ваши должники!" },
    ["649a"] = { common = "Хочу я поручить тебе одно дельце. Если ты любишь добрую медовуху, как и я, оно тебе понравится. Медовуха! Это напиток, балда! На заброшенной заставе Орды хранится запас \"Медовой зыби\" Внутренних земель. Такого славного пойла нынче больше не делают! Один из этих балбесов, дружков Мальтона, знает туда дорогу. Сходи к нему, принеси бочонок медовухи и ещё пару бутылок мне лично. Поговори с Мальтоном, он тебе всё расскажет." },
    ["649c"] = { common = "А, это насчёт медовухи, которая нужна папаше? Он собирается торговать ею в таверне. За настоящую \"Медовую зыбь\" можно выручить много денег... Я знаю того, кто может её добыть. Он живёт во Внутренних землях. Но вот какая штука: он того... эльф он. Высший. Но ты не бойся, он хороший высший эльф, он не из Альянса. То есть он хороший, как выпьет. А это дело он любит. Очень любит." },
    ["650a"] = { common = "Отправляйся к эльфу по имени Гилверадин Ловчий Солнца. Он так разбирается в винах, что умеет по запаху определить не только сорт вина, но и какого оно урожая! Он может прислать медовуху. Шесть бутылок на продажу, две отцу... а может, и больше – он не откажется! В общем, забери медовуху и возвращайся сюда. Гилверадин живёт неподалёку от пристанища Высших эльфов во Внутренних землях. С эльфами этими лучше не связываться, уж поверь мне!" },
    ["650c"] = { common = "А, ты знаешь Мальтона? Он мой старинный собутыльник! Понимаешь, я нашёл средство, преодолевающее все искусственные границы и условности. Это – выпивка! Если бы разумные существа выпивали, вместо того чтобы воевать, мир сделался бы куда лучше и чище. Впрочем, боюсь, ты здесь не затем, чтобы слушать лекции о благословенных свойствах алкоголя." },
    ["651a"] = { common = "Четыре связывающих камня разбросаны по нагорью Арати. Эти камни пригвоздили меня к земле. Чтобы оковы исчезли, нужно снять замок с самого мощного из них – с Внутреннего связывающего камня. А чтобы это сделать, придётся собрать ключи с остальных трёх камней. Эти камни охраняют стражи, но если у тебя хватит ума – или удачи, – тебе удастся найти возможность их нейтрализовать." },
    ["651c"] = { male = "Голос Мизраэли доносится из камня. Ты смог это сделать! Ты открыл замки! Я чувствую, как спадают мои оковы, и свобода всё ближе. Ты мой благородный спаситель, герой путник!", female = "Голос Мизраэли доносится из камня. Ты смогла это сделать! Ты открыла замки! Я чувствую, как спадают мои оковы, и свобода всё ближе. Ты моя благородная спасительница, героиня путница!" },
    ["652a"] = { male = "Открыв замки связывающих камней, ты освободил меня от большей части моих оков, но кое-что ещё удерживает меня. Это ключ-камень, который ты видишь среди других камней круга. А ключ от него держит при себе один из моих пленителей, каменный страж Фозрук. Вы должны заполучить у Фозрука этот ключ, который каменные стражи называют Жезлом Порядка, и использовать его для открытия ключ-камня. Вы так много сделали, чтобы мне помочь... Ещё немножко... и моя благодарность потрясёт все земные устои!", female = "Открыв замки связывающих камней, ты освободила меня от большей части моих оков, но кое-что ещё удерживает меня. Это ключ-камень, который ты видишь среди других камней круга. А ключ от него держит при себе один из моих пленителей, каменный страж Фозрук. Вы должны заполучить у Фозрука этот ключ, который каменные стражи называют Жезлом Порядка, и использовать его для открытия ключ-камня. Вы так много сделали, чтобы мне помочь... Ещё немножко... и моя благодарность потрясёт все земные устои!" },
    ["652c"] = { common = "Вы вставляете жезл в краеугольный камень. Земля под вами начинает дрожать..." },
    ["653a"] = { male = "*Говорит Мизраэль.* Свободна! Я СВОБОДНА! Я могу теперь набирать силу, скрывшись от моих пленителей. Потому что, если бы я предстала перед ними сейчас, они бы наверняка пересилили меня и вновь заключили бы в оковы. Но в должный час я пойду против гигантов, и они ещё пожалеют о том, что отняли у меня свободу! Вы благородный союзник. Через некоторое время мне вновь понадобится ваша помощь. Когда я буду готова, нужно, чтобы вы призвали меня на поверхность. Поговорите с Герриком Костохватом. Он обитает в Стальгорне, в Заброшенном гроте. Он знает, как меня можно призвать.", female = "*Говорит Мизраэль.* Свободна! Я СВОБОДНА! Я могу теперь набирать силу, скрывшись от моих пленителей. Потому что, если бы я предстала перед ними сейчас, они бы наверняка пересилили меня и вновь заключили бы в оковы. Но в должный час я пойду против гигантов, и они ещё пожалеют о том, что отняли у меня свободу! Вы благородная союзница. Через некоторое время мне вновь понадобится ваша помощь. Когда я буду готова, нужно, чтобы вы призвали меня на поверхность. Поговорите с Герриком Костохватом. Он обитает в Стальгорне, в Заброшенном гроте. Он знает, как меня можно призвать." },
    ["653c"] = { male = "Добро пожаловать, герой. Госпожа сообщила мне о вашем приближении, и если мы хотим вернуть её на поверхность, нам нужно многое обсудить.", female = "Добро пожаловать, героиня. Госпожа сообщила мне о вашем приближении, и если мы хотим вернуть её на поверхность, нам нужно многое обсудить." },
    ["654a"] = { common = "Вы подключаете источник энергии, и набор для полевых испытаний начинает светиться и вибрировать. Похоже, он работает как надо. По словам главного инженера Чепухастера, у вас есть два часа на сборы образцов в пустыне Танарис. Если вы не успеете справиться за это время, то потеряете все данные и придётся купить ещё один источник энергии. Выполнив задание, возвращайтесь к Чепухастеру." },
    ["654c"] = { common = "Ну ладно, на удаление источника энергии мне понадобится пара секунд. После этого можешь делать всё, что захочешь, не боясь потерять данные." },
    ["655a"] = { common = "Воспоминания по-прежнему ярки, как будто это было вчера... Так много лет без надежды, прикованный к этому ужасному месту деревом и сталью. И вот наконец появился вождь. Молот Рока в своих полуночных доспехах, высоко поднят его боевой молот. Это было... слишком ужасно... что удар труса мог сразить нашего величайшего героя. Враг наскочил сзади и пронзил его копьём... Я упал на колени. Какая могла быть надежда? Какая ещё может быть надежда..." },
    ["655c"] = { common = "А, вы говорите о Гор'муле. Да, судя по вашим словам, похоже, он так и не оправился от смерти Молота Рока. Гор'муль был пленником здесь, когда Тралл и Оргрим вели битву за освобождение лагеря, но когда затряслась земля и наши братья сбежали, его оставили там. Лишённый малейшего проблеска надежды, он скитался, затерянный, в одиночестве, пока мы не вернулись сюда, чтобы вновь поселиться в Павшем Молоте." },
    ["656a"] = { common = "Вы должны нанести поражение Мизраэли прежде, чем она обретёт полную силу. Если вы этого не сделаете, то, как только она наберёт достаточно сил, она кинется на своих пленителей! Есть такие, кто считает, что может её контролировать, но если её можно контролировать, с чего было гигантам с самого начала заковывать её в цепи? Потрясающая логика, да? Чтобы сразить Мизраэль, призовите её у её кристаллов, где вы в первый раз говорили с ней. Нанесите ей поражение и заберите её мистические оковы, а потом подсоедините их к кристаллам Мизраэли. Сделайте так – и она вновь будет поймана в ловушку." },
    ["656c"] = { common = "Как только мистические оковы были положены вокруг кристаллов, нечеловеческий вой раздался снизу. Крик сопровождался рычанием. Кристаллы Мизраэли больше не вызывают чувства тепла и защиты, как раньше. Теперь они излучают открытую угрозу... как если бы существо внизу, под ними, исходило злобой, вырывающейся наружу." },
    ["657a"] = { common = "*Кви начинает просматривать папку.* Это в самом деле интересно! Похоже, аптекарь Йорель проводил здесь, на ферме Го-Шека, какие-то смертельно опасные эксперименты. Я не знаю точно, какое это имеет отношение к Хилсбраду, но Фину не понравится, если мы проигнорируем такое дело. Мы тут столкнулись с орками в ваше отсутствие, и теперь я не настолько хорошо себя чувствую, чтобы отправиться на помощь к Кинелори. Но если вы не против, проводите её к ферме, где она собирается выкрасть результаты исследований, которые Йорель так и не отослал пока на Мельницу Таррен." },
    ["657c"] = { common = "Если это успокоит Фина, я уничтожу каждого из Отрёкшихся поодиночке. Он столько сделал для нас с тех пор, как началась чума. Мы и не надеялись, что когда-нибудь у нас снова будут друзья или семья. Когда будете готовы, дайте мне знать. Мы тотчас же двинемся в путь." },
    ["658a"] = { common = "Так вас Фин послал узнать, как мы тут? Неудивительно – он слишком много беспокоится. Мы уже много дней наблюдаем за этой фермой, и Кин уверяет, что недавно видела гонца, выходящего из вон того маленького домика с южной стороны. Она любительница поболтать, но я всегда доверяю её ощущениям, когда мы бываем в опасных местах. А вы часом не следопыт, а? Мы думаем, что гонец может относить записки в деревню Мельница Таррен. Если бы мы могли заполучить эти документы, это пролило бы свет на события в Хилсбраде." },
    ["658c"] = { common = "Отлично! Посмотрим, о чём тут идёт речь..." },
    ["659a"] = { common = "Приветствую, приятно познакомиться. Я руковожу группой смельчаков, расследующих странные происшествия в этом районе. Моим родственникам в Хилсбраде недавно пришлось избавиться от своей собаки Стэнли, потому что животное таинственным образом выросло до невообразимых размеров и стало кидаться на каждого прохожего. Я уверен, что тут замешана нежить, и мы ищем доказательства. Две моих спутницы, Кви и Кинелори, отправились к ферме Го'Шека, что находится на Нагорье Арати, и давно не подавали о себе вестей. Найдёте их? А то я начинаю беспокоиться." },
    ["659c"] = { common = "Постарайся быть как можно незаметнее, путник. Оркам не слишком нравится, когда за ними шпионят, а их тут больше, чем видно невооружённым глазом." },
    ["660a"] = { common = "Ладно. Если вы готовы, то и я тоже. Попробуем?" },
    ["660c"] = { common = "Вы оказали нам огромную услугу. Благодарю вас. Надеюсь, Кин не доставила вам слишком много хлопот. Она очень дружелюбна, но может быть и смертельно опасной, если вы её враг." },
    ["661a"] = { common = "После ночной гулянки в таверне Кинелори выглядела похуже, чем сейчас. Видно, вы неплохо её защищали. То, что она принесла с фермы, должно как минимум дать Фину представление о том, что происходит здесь, в Арати. Для того чтобы удоствоериться, что после вашей атаки не последует ответного удара, мы здесь ненадолго задержимся. Вы не откажетесь отправиться обратно в Южнобережье и поговорить с Фином?" },
    ["661c"] = { common = "Итак, эти две баламутки в конечном счёте – в полном порядке? Ха-ха, рад слышать. Благодарю вас за вести об их местонахождении и состоянии – меня в высшей степени радует, что они ещё живы; обе они – мои близкие подруги и незаменимые спутницы в путешествиях. Но... более важна моя благодарность за вашу помощь. Вот, примите это вместе с благодарностью от всей нашей группы. Если посчастливится, мы выясним, что затевают Отрёкшиеся, и положим конец их замыслам." },
    ["662a"] = { common = "О'Брин повёл корабли в бухту. Мы были уверены, что именно здесь будет найдено сокровище. \"Вестник\" причалил нормально, но когда \"Девичья Блажь\" и \"Дух Серебряного бора\" приблизились к берегу, вода начала быстро понижаться. Страннейшая вещь, я такого в жизни не видал! Те два корабля налетели на что-то... нечто вроде храма в рифе. Оба быстро затонули – это была настоящая трагедия. Нужно найти судовые журналы и карты обоих кораблей, прежде чем мы отчалим. Мы не можем оставить эту информацию доступной для любопытных глаз!" },
    ["662c"] = { common = "Известие о том, что теперь эти сведения в безопасности, немного успокоит наше начальство в Пиратской бухте. Хорошая работа." },
    ["663a"] = { male = "Ой, кого видит Лоло! Это ж крошка-герой! Лоло всегда начеку! Добро пожаловать в бухту Фальдира. Капитан О'Брин сказал, что мы задержимся тут лишь на несколько часов. Ровно настолько, сколько потребуется, чтобы добыть сокровище и отчалить обратно в Пиратскую бухту. Но Лоло думает, мы тут надолго засели. Из нашей эскадры мы потеряли два корабля. Беднягу \"Дух Серебряного бора\" и несчастную \"Девичью Блажь\". На дне морском они теперь! Лоло думает, вам бы переговорить с капитаном О'Брином, если вы тут и дальше слоняться собираетесь.", female = "Ой, кого видит Лоло! Это ж крошка-героиня! Лоло всегда начеку! Добро пожаловать в бухту Фальдира. Капитан О'Брин сказал, что мы задержимся тут лишь на несколько часов. Ровно настолько, сколько потребуется, чтобы добыть сокровище и отчалить обратно в Пиратскую бухту. Но Лоло думает, мы тут надолго засели. Из нашей эскадры мы потеряли два корабля. Беднягу \"Дух Серебряного бора\" и несчастную \"Девичью Блажь\". На дне морском они теперь! Лоло думает, вам бы переговорить с капитаном О'Брином, если вы тут и дальше слоняться собираетесь." },
    ["663c"] = { common = "Хей, дружище. Ну и жуть же была. Морской Рог отнимет у меня корабль, если проведает, что тут произошло. Одна из этих хитрых профессорских штучек указала на то, что поблизости от этой бухты лежит давно утерянный клад. Я привёл \"Вестник\" к берегу, чтобы причалить, и сигнализировал \"Духу Серебряного бора\" и \"Девичьей Блажи\", чтобы они сделали то же самое. А потом вдруг море загрохотало. Вода понизилась, и оба корабля разбились, врезавшись в риф. Но это был не просто риф. Что-то было там, внизу... Помогите моей команде, и получите неплохое вознаграждение." },
    ["664a"] = { common = "Ох, жизнь – ужасная штука. Я должен бы покоиться в водяной могиле, а не сидеть здесь у огня, наслаждаясь свежим воздухом. Команда не жалела сил, чтобы спасти мою прекрасную \"Девичью Блажь\". Да упокоятся ребята в мире, благословенны их сердца. О'Брину удалось выбраться на берег, а нам не повезло. Море просто опрокинулось на нас, клянусь вам. Вот мы плывём – и вот следующая волна обрушивается на нас. А эти твари! Они убили всех, кто выжил. Подлое нагово отродье. Я вырубился и пришёл в себя уже здесь. Я жажду их мерзкой холодной крови!" },
    ["664c"] = { common = "Славно потрудились. Эти твари получили по заслугам. Хотя ничто не вернёт мне мой корабль и мою команду, смерть этих наг даёт хоть какое-то утешение." },
    ["665a"] = { common = "Теперь, когда мы настоящие полноценные разбойники Черноводья, мы должны помочь мистеру О'Брину разыскать пропавшее эльфийское сокровище. Почти невозможно найти драгоценные камни в море без посторонней помощи. Доктор сконструировал специальные очки, которые должны помочь. Ему нужно зарядить эти очки энергией, извлечённой из заколдованного камня в пещере, расположенной выше по холму. Но эта пещера проклята! Когда мы подошли к ней, на нас напали. Защитите меня, и я смогу вытянуть энергию из камня и направить её в очки." },
    ["665c"] = { common = "Теперь очки работают превосходно! Отличная работа." },
    ["666a"] = { common = "Сокровища так долго лежали на дне морском, что покрылись известковым налётом, превратившись в большой камень. Но сила, влитая в эти очки, позволит вам легко определить их местонахождение. Маленькая гномья ловкость делает большие дела! Возьмите эти очки Ловца сокровищ, посмотрите, может, вам удастся собрать какие-то из утерянных сокровищ для капитана О'Брина. Я бы и сам поплыл туда, но... эм... ну, у меня есть серьёзные научные задачи, требующие срочного решения на надёжной, сухой земле... да... вот." },
    ["666c"] = { common = "Великолепно! Капитан будет очень доволен! Погодите, вот ещё весть долетит до флотовладельца Морского Рога!.." },
    ["667a"] = { common = "Это плохо. Похоже, клан Пронзающего Гребня готовится к нападению. Наги известны своей жестокостью в бою. Они не остановятся, пока я не умру. Не то чтобы я ценил свою жизнь выше, чем жизни членов команды, но вы должны помочь защитить меня. Я единственный, кто знает морские пути, – команда просто не сможет вернуться в Пиратскую бухту без меня. Наги придут с моря. Мне нужно, чтобы вы оставались здесь, со мной, чтобы отразить их атаку. Займите место у пушки и оттесните их. Готовы?" },
    ["667c"] = { male = "Мы пережили их атаку! Без вас, нам бы это не удалось. Мы отчалим, как только поднимется прилив. Если бы вы не были столь многообещающей героической личностью, я предложил бы вам место в своей команде. Но, конечно, вас ждёт рыбка покрупнее. Несмотря на то, что вы всего лишь герой...", female = "Мы пережили их атаку! Без вас, нам бы это не удалось. Мы отчалим, как только поднимется прилив. Если бы вы не были столь многообещающей героической личностью, я предложил бы вам место в своей команде. Но, конечно, вас ждёт рыбка покрупнее. Несмотря на то, что вы всего лишь героиня..." },
    ["668a"] = { common = "Не будем заставлять капитана О'Брина ждать. Он захочет первым увидеть эти драгоценности. В конце концов, для того мы и здесь! А через нескольо недель сотрудничества с этими пиратами мы с профессором поняли, что на нашем здоровье самым пагубным образом может сказаться, если нас застанут придерживающими их сокровища. Вот, отнесите всё О'Брину." },
    ["668c"] = { common = "Так, значит, коротышки в конце концов оказались полезными? Я знал, что мы этих мальчиков-с-пальчик не напрасно взяли с собой!" },
    ["669a"] = { common = "Командир флота Морской Рог захочет сразу же услышать о нашей находке. Но, как видите, мы пока не в том положении, чтобы сняться отсюда. Не только прилив очень низок, но ещё и эти проклятые твари, которым мы помешали, бдительно следят за нашими передвижениями. Вы оказали бы большую услугу Пиратам Черноводья, если бы смогли сообщить флотовладельцу Морскому Рогу в Пиратскую бухту, что мы отыскали сокровища и работаем над тем, чтобы достать ещё. А этот образчик отвезите ему в качестве доказательства." },
    ["669c"] = { common = "А, узнаю старого доброго Мураша О'Брина! Я знал, что это подходящий капитан для такого задания!" },
    ["670a"] = { common = "Слушайте, у вас лицо искателя приключений. Мой флот застрял в Пиратской бухте, пока мы не загрузимся. Там, да и не только там, творятся тёмные делишки, а мне нужно доставить кое-какую секретную корреспонденцию Мурашу О'Брину, пришвартовавшемуся к побережью Арати. Могу ли я доверить вам доставку этого сообщения в целости и сохранности и надеяться на вашу готовность хранить это задание в секрете?" },
    ["670c"] = { common = "Спасибо, что проделали такой долгий и опасный путь. Благодарю вас от имени разбойников Черноводья." },
    ["671a"] = { common = "Я почувствовал что-то странное в воздухе... ощущение, будоражащее мою кровь. У меня возникли подозрения. Я твёрдо решил найти источник беспокойства и обнаружил на западе, у Северного поместья, остаточные следы призыва демона. Когда я приблизился, кровь буквально вскипела, и ярость разгорелась во мне. На земле я заметил амулет из кровавого камня, какими пользуются, вызывая демона. Однако магическая сила найденного мной камня была уже полностью исчерпана. Мне нужен для изучения другой образец, но я не рискую возвращаться в поместье. Можете ли вы принести мне оттуда несколько амулетов?" },
    ["671c"] = { common = "Выявление истинных намерений Синдиката отнимет у меня некоторое время, но их очевидное сотрудничество с тёмными демоническими силами меня беспокоит. Я расскажу вам, когда разузнаю." },
    ["672a"] = { common = "Мы пытались успокоить его, развеселить, рассказывать ему истории о нашем огромном городе Оргриммаре на Калимдоре, но его ничто не трогало. Истории о нашем молодом вожде, Тралле, который носит доспехи и молот Оргрима... но, быть может... Может быть! Демонстрация нашей новообретённой шаманской магии могла бы дать ему луч надежды. Попробовать стоит! Мы могли бы сделать для него маленькую вещицу, да... Принесите мне несколько глаз раптора, и я посмотрю, что можно сделать." },
    ["672c"] = { common = "Отлично. Духи ящеров, от которых взяты эти глаза, предоставят носящему этот амулет свою силу." },
    ["673a"] = { common = "У меня нет сомнений, что в стенах Стромгарда засел могущественный чернокнижник. Время от времени, используя обладающую магической энергией реликвию, этот чернокнижник призывал в больших количествах ужасных демонов. Мы должны отнять у него этот источник энергии. Найдите чернокнижника и убейте его. Принесите мне магический объект, который найдёте при нём, чем бы он ни оказался. Я предприму шаги по разрушению реликвии и прослежу, чтобы её мощь больше не использовалась для осквернения этой земли." },
    ["673c"] = { common = "Мои бессонные ночи наконец сменятся спокойным сном, когда я разрушу эту сферу. Спасибо вам. Это леденящее напоминание о той ужасной власти, которую демоны имели над орками, прежде чем Адский Крик освободил их от проклятья." },
    ["674a"] = { common = "Вот, отнесите этот амулет Гор'мулю и посмотрите, пробудит ли сила ящера в нём тот боевой огонь, который некогда пылал в его крови." },
    ["674c"] = { common = "Что это? Отполированный кусок кости... Что мне пользы от полированной косточки? Разве безделушка способна вернуть Орде её былую славу?" },
    ["675a"] = { common = "*Гор'муль бросает амулет на землю.* Вас Тор'ган послал, да? Тьфу... Никак не могу понять, почему он жалеет меня. В сострадании мне было отказано, когда мне не позволили умереть вместе с моим вождём во время боя. Жестокий удар судьбы настиг меня..." },
    ["675c"] = { common = "Вижу, что не сработало. Тем не менее я чувствую, что демонстрация силы шаманов может помочь Гор'мулю вернуть веру в себя. Сила амулета была недостаточно велика, чтобы показать ему нашу новообретённую мощь." },
    ["676a"] = { male = "Слабаки... Все они слабаки. А ты, герой, куда смотришь? Думаешь, особенный? Проверим? На форт Павший Молот напали враги. Если не помочь нашим, им не устоять. Впрочем, не спеши. Прежде надо испытать твоё искусство. На северо-востоке от Стромгарда в Арати есть курган, который заселило огрское племя Тяжёлого Кулака. Когда одолеешь тамошних огров и мародёров, доложи об этом Драму Жёлчному в Павшем Молоте.", female = "Слабаки... Все они слабаки. А ты, героиня, куда смотришь? Думаешь, особенная? Проверим? На форт Павший Молот напали враги. Если не помочь нашим, им не устоять. Впрочем, не спеши. Прежде надо испытать твоё искусство. На северо-востоке от Стромгарда в Арати есть курган, который заселило огрское племя Тяжёлого Кулака. Когда одолеешь тамошних огров и мародёров, доложи об этом Драму Жёлчному в Павшем Молоте." },
    ["676c"] = { common = "Значит, ты думаешь, что тебе хватит сил помочь Павшему Молоту? Да будет так. Сальный послал тебя в огрский курган или в надежде, что ты там погибнешь, или полагая, что сможешь помочь нам. Так или иначе, ты здесь, а мне нужны солдаты. Натиск на наш форт не ослабевает. Если ты собираешься остаться в Павшем Молоте, то отдохни, а потом приходи ко мне. Чего-чего, а сражений на твою долю хватит." },
    ["677a"] = { common = "Тролли племени Сухокожих и огры клана Тяжёлого Кулака с нагорья Арати стакнулись, чтобы выжить нас с этой земли, но мы не собираемся уступать ни им, ни кому угодно другому. Мы убьём их и покажем, что и мы здесь – у себя дома. Тролли позорно бежали от нас; огры сожрали бы нас и спали бы на наших шкурах, если бы мы им позволили, – этим тварям не должно жить. Мы начнём атаковать троллей Сухокожих к югу отсюда. Убивай их пачками и возвращайся только тогда, когда их поселения будут залиты кровью." },
    ["677c"] = { common = "Я вижу боевые отметины на твоих доспехах, и пот струится по твоему лбу. Неплохо, в самом деле неплохо." },
    ["678a"] = { common = "Твоя сила очевидна. Теперь посмотрим, как ты справишься с настоящим врагом. У клана Тяжёлого Кулака есть логово к юго-востоку отсюда по направлению к дворфийскому мосту, и, если я не ошибаюсь, их молотобойцы и маги должны стать для тебя более серьёзным испытанием – по крайней мере, для нас они таковым являются по сию пору. Убей столько огров, сколько сможешь, и возвращайся ко мне во плоти, если добьёшься успеха, или в виде призрака, если потерпишь неудачу. В любом случае я воздам хвалу твоей стойкости в бою." },
    ["678c"] = { common = "Ты не слабее кодо, а твоя готовность к битве достойна восхищения." },
    ["679a"] = { common = "Зверю вот-вот отрубят голову... и всё же для решающего удара требуется огромная сила. Уверен, именно ты можешь помочь нам нанести этот последний мощный удар. Руководящие этими атаками устроили своё логово прямо в руинах Стромгарда – вот яркий пример человеческой слабости... Найди и убей вождей клана Тяжёлого Кулака и их прислужников-шаманов, пытающихся выжить нас с этих земель." },
    ["679c"] = { common = "Твой народ может гордиться тобой. Угроза сильно уменьшилась, и я уверен, что мы начнём процветать здесь, на этом нагорье." },
    ["680a"] = { male = "Вы отлично служите моему мужу, герой, но он не знает, почему Павший Молот подвергается атакам. Ор'Калар – пешка в руках Муг'Тола в Стромгарде – яро ненавидит моего мужа и ничего так не желает, как его смерти – за то, что тот нанёс ему поражение много лет назад. Мои гадатели сообщают, что Ор'Калар устроил для мужа ловушку, поэтому я скрыла от него, что огр объявился в этих землях. Мой муж ринется сломя голову, если узнает о местонахождении огра, а я хотела бы попросить вашей помощи в убийстве этой твари.", female = "Вы отлично служите моему мужу, героиня, но он не знает, почему Павший Молот подвергается атакам. Ор'Калар – пешка в руках Муг'Тола в Стромгарде – яро ненавидит моего мужа и ничего так не желает, как его смерти – за то, что тот нанёс ему поражение много лет назад. Мои гадатели сообщают, что Ор'Калар устроил для мужа ловушку, поэтому я скрыла от него, что огр объявился в этих землях. Мой муж ринется сломя голову, если узнает о местонахождении огра, а я хотела бы попросить вашей помощи в убийстве этой твари." },
    ["680c"] = { common = "Вы оказали мне огромную услугу. Знайте, что жизнь моего мужа и безопасность Павшего Молота ещё на некоторое время защищены благодаря вашим деяниям. Пожалуйста, примите это в качестве награды за вашу смелость." },
    ["681a"] = { common = "Мы ведём войну за Стромгард и терпим в ней поражение. Мы делим наш некогда великий город с ограми и Синдикатом, каждая группировка бьётся с другой, и конца этому не видно. Но наши силы иссякают, в то время как силы наших врагов – растут. Нам нужна помощь из Южнобережья, но есть проблемы с доставкой припасов, поскольку Синдикат контролирует территорию между нами. Иди на базу Синдиката в Северном поместье и перебей там всех. Тогда, может быть, давление на наши транспортные пути ослабеет, и доставлять припасы станет проще." },
    ["681c"] = { common = "Очень хорошо. Со смертью этих членов Синдиката нам должно стать полегче получать припасы из Южнобережья. Быть может, у нас ещё есть надежда." },
    ["682a"] = { common = "Синдикат в Стромгарде воюет с силами нашего ополчения. Чтобы побудить толпу биться с нашими более дисциплинированными войсками, руководство Синдиката объявило о награде за убийство наших солдат, предлагая золото за каждый знак Стромгарда, снятый с убитых ополченцев. Мы хотим вернуть себе эти знаки – не можем же мы позволить головорезам брать трофеи с тел наших героически погибших ребят! Отправляйтесь в район Стромгарда, контролируемый Синдикатом, и отберите у их бойцов наши знаки." },
    ["682c"] = { common = "Спасибо вам. Мы известим семьи этих погибших солдат о том, что они пали в бою. Это будут печальные вести, и всё же это лучше знать о судьбе любимых людей, чем томиться неизвестностью." },
    ["683a"] = { male = "У меня есть к вам маленькая просьба. Возьмите прошение, которое я написала на имя нашего великого государя стальгорнского, короля Магни Бронзоборода. Это небольшой труд для такого, как ты, славного героя. Мне в моём горе сейчас трудно будет предстать перед королём. Ты понимаешь меня.", female = "У меня есть к вам маленькая просьба. Возьмите прошение, которое я написала на имя нашего великого государя стальгорнского, короля Магни Бронзоборода. Это небольшой труд для такой, как ты, славной девы. Мне в моём горе сейчас трудно будет предстать перед королём. Ты понимаешь меня." },
    ["683c"] = { common = "Подожите минутку, я прочту письмо..." },
    ["684a"] = { common = "Назначена награда за голову Марез Клобук, высокопоставленной советницы и агента Синдиката. В последний раз её видели на контролируемой Синдикатом территории Стромгарда. Награду можно будет получить у капитана Ниалс. Предупреждение: Марез – опытная и коварная чернокнижница, замеченная в связях с демонами. Вооружена и очень опасна!" },
    ["684c"] = { common = "Вы справились с Марез Клобук? Отличная работа. В самом деле отличная! Марез была серьёзной угрозой стромгардским защитникам, и ходят слухи, что она служила посредницей между Синдикатом и какими-то другими, тёмными силами. Мы рады узнать, что она больше не будет строить козни против нас." },
    ["685a"] = { common = "Ополчение Стромгарда уведомляет о назначении награды за головы лорда Соколиного Шлема и его телохранителя Отто. Соколиный Шлем руководит деятельностью Синдиката на нагорье Арати, и его смерть внесла бы большую сумятицу. Его телохранитель Отто, хотя и не является стратегической целью, представляет собой опасного противника, на счету которого – смерть десятков наших воинов. Награды за их головы можно получить у капитана Ниалс." },
    ["685c"] = { common = "Лорд Соколиный Шлем и Отто? Отлично! Вот ваша награда. Я с радостью выплачиваю её." },
    ["686a"] = { male = "Вряд ли добрые дворфские вдовы вроде госпожи Баллу понимают, что нам приходится терпеть тяготы войны ради высшего блага нашего народа. Гибель её мужа, как и гибель всех дворфов, что сражаются за дело Альянса, тяжким бременем лежит на моей душе. Мне не под силу вернуть её супруга из Круговерти Пустоты, но я могу хотя бы почтить его память. Я намерен заказать главному каменотёсу Стальгорна Мраморщику памятник в честь Салли Баллу. Отправляйтесь к нему сейчас же и передайте мои слова, герой. Вы будете моим вестником.", female = "Вряд ли добрые дворфские вдовы вроде госпожи Баллу понимают, что нам приходится терпеть тяготы войны ради высшего блага нашего народа. Гибель её мужа, как и гибель всех дворфов, что сражаются за дело Альянса, тяжким бременем лежит на моей душе. Мне не под силу вернуть её супруга из Круговерти Пустоты, но я могу хотя бы почтить его память. Я намерен заказать главному каменотёсу Стальгорна Мраморщику памятник в честь Салли Баллу. Отправляйтесь к нему сейчас же и передайте мои слова, героиня. Вы будете моим вестником." },
    ["686c"] = { common = "Значит, вас послал лично король Магни Бронзобород? Подумать только! Стало быть, дело важное!" },
    ["687a"] = { common = "Тельдарин Заблудший некогда был членом нашего ордена Сумеречного Молота. Однако он сошёл с ума и отверг наше учение. Перед побегом он украл свиток Мизраэли! Мы не смогли поймать его, но ходят слухи, что он совсем спятил и прячется в Бесплодных землях. Чтобы переманить на нашу сторону Госпожу, необходимо найти свиток. А для этого – найти Тельдарина." },
    ["687c"] = { common = "Привет. Привет, привет, привет, привет, привет, ПРИВЕТ! Прости... Нет, не прощай! Не груби мне! О нет, это бред сумасшедшего. Но иногда моё единственное утешение – в безумии." },
    ["688a"] = { male = "*Говорит Мизраэль.* Свободна! Я СВОБОДНА! Я могу теперь набирать силу, скрывшись от моих пленителей. Потому что, если бы я предстала перед ними сейчас, они бы наверняка пересилили меня и вновь заключили бы в оковы. Но в должный час я пойду против гигантов, и они ещё пожалеют о том, что отняли у меня свободу! Вы благородный союзник. Через некоторое время мне вновь понадобится ваша помощь. Когда я буду готова, нужно, чтобы вы призвали меня на поверхность. Поговорите с Заруком в Павшем Молоте. Он знает, как меня можно призвать.", female = "*Говорит Мизраэль.* Свободна! Я СВОБОДНА! Я могу теперь набирать силу, скрывшись от моих пленителей. Потому что, если бы я предстала перед ними сейчас, они бы наверняка пересилили меня и вновь заключили бы в оковы. Но в должный час я пойду против гигантов, и они ещё пожалеют о том, что отняли у меня свободу! Вы благородная союзница. Через некоторое время мне вновь понадобится ваша помощь. Когда я буду готова, нужно, чтобы вы призвали меня на поверхность. Поговорите с Заруком в Павшем Молоте. Он знает, как меня можно призвать." },
    ["688c"] = { male = "Добро пожаловать, герой. Госпожа сообщила мне о вашем приближении, и если мы хотим вернуть её на поверхность, нам нужно многое обсудить.", female = "Добро пожаловать, героиня. Госпожа сообщила мне о вашем приближении, и если мы хотим вернуть её на поверхность, нам нужно многое обсудить." },
    ["689a"] = { common = "Значит, наш добрый король решил построить памятник в честь солдата по имени Салли Баллу? И вы говорите, что бедный парень погиб на мосту Тандола? Да будет когда-нибудь мир в Азероте? Как бы то ни было, любое поручение нашего государя – дело первостепенной важности. Чтобы возвести действительно впечатляющий памятник на века, мне нужен самый лучший камень. Отправляйся на Холм Дарроу в Хилсбрад и привези мне альтеракского гранита." },
    ["689c"] = { common = "Замечательно! Лучше, чем я представить мог! А воображение у меня, между прочим..." },
    ["690a"] = { common = "Приветствую вас. Вы похожи на искателя приключений, а у меня как раз есть задание, требующее склонности к авантюрам. Верховный маг Трелан, мой первый наставник, не так давно бежал из Стромгарда, что на нагорье Арати, и просил меня помочь ему вернуть несколько предметов, которые он там оставил. Город был осаждён, и Трелан попытался защитить Башню Аратора, но потерпел неудачу. У меня на нагорье есть агенты, но они просили дополнительной помощи. Вы согласитесь мне помочь?" },
    ["690c"] = { common = "Так вас, значится, Малин прислал? А мне без разницы, пусть хоть сам Мурадин восстанет из мёртвых и умчит вас отсюда на драконе... Я занят! Если вам что-нибудь нужно, обратитесь к Кретьену." },
    ["691a"] = { common = "Верховный маг Малин послал нас со Скуэрто собирать для него реагенты. Я был в полном замешательстве и не знал, как приступить к делу, но теперь, когда вы здесь, думаю, моя проблема решена. Вот что мне нужно: клыки троллей из племени Сухокожих, лекарские сумки клана Сухокожих и нож тёмного охотника. Не могли бы вы добыть это всё для меня? Племя Сухокожих обитает к юго-востоку от Арати." },
    ["691c"] = { common = "Невероятно! Теперь я понимаю, почему Малин попросил вас присоединиться к нам – вы отлично потрудились! Такими темпами мы со Скуэрто очень скоро двинемся обратно в Штормград! Я уверен, что мой спутник-дворф вернулся с разведки из Крепости Тяжёлого Кулака; пообщайтесь с ним, когда будет время. По нему заметно, что он затеял с ограми потасовку. Впрочем, не говорите ему об этом: он очень чувствителен к критике его навыков разведчика." },
    ["692a"] = { common = "Свиток Мизраэли... Свиток Мизраэли?! Нет, уверяю вас, не стоит даже думать о нём! Его магия может вытащить Мизраэль на поверхность, и если вы это сделаете, нам грозит беда! Или... может быть, уже слишком поздно. Может быть, она уже свободна. Может быть, она уже собирается с силами, прежде чем обрушиться на нас. Если так, свиток вам НЕПРЕМЕННО ПОНАДОБИТСЯ! ...как ужасно, что он уничтожен. Спятившие элементали похитили его и разорвали на клочки, а теперь дерутся за них. Но если бы вам удалось собрать эти фрагменты, может быть, нам удалось бы восстановить свиток..." },
    ["692c"] = { common = "А, вы их нашли! Отличная работа! Это, может, единственный наш шанс противостоять злу, которое несёт Мизраэль! Дайте-ка я найду мой степлер – посмотрим, смогу ли я соединить эти клочки..." },
    ["693a"] = { common = "Здорово. Я выяснил, где оказалась первая вещь Трелана: Коргреш держит её в Зале Тяжёлого Кулака. И судя по тому, как он кидался в своих потоками льда, чтобы заставить их держать строй, он, должно быть, уже близко подошёл к пониманию того, как использовать мощь жезла на полную катушку. Чтобы добраться до Зала Тяжёлого Кулака, нужно идти на юг отсюда, а затем на восток от моста Тандола. Найдите этого огра и отберите у него жезл. А за время вашего отсутствия я соображу, что нам делать со Стромгардом." },
    ["693c"] = { common = "Блестяще. Один предмет найден, и, по моему списку, осталось ещё три. Все они находятся в Стромгарде. Передохните и восстановите силы – следующий этап моего плана потребует немного больше времени и усилий. Возвращайтесь ко мне, плотно покушав и отдохнув." },
    ["694a"] = { common = "Все отдохнули? Вот наш следующий шаг: огры так и кишат вокруг башни Аратора в Стромгарде. Необходимо активировать защитные возможности башни, если вы хотите иметь хоть малейший шанс выстоять против них. Чтобы это сделать, нам понадобится несколько самоцветов, на которые наложил лапы шаман клана Тяжёлого Кулака. Он стянул их из башни, но радость его преждевременна – камни недолго будут в его власти. Добудьте один из самоцветов и принесите его Кретьену – он знает заклинание, которое нужно наложить на эти камни, чтобы они работали как ключи." },
    ["694c"] = { common = "Вы меня просто поражаете. Снова отличная работа. Минутку, я применю подходящее заклинание, чтобы заколдовать самоцвет, и всё будет готово." },
    ["695a"] = { common = "Вот. Самоцвет нужно только прижать к одному из пьедесталов у основания башни, чтобы активировать её защитные силы. Используйте его, когда будете готовы войти в башню и искать остальные принадлежащие Трелану предметы. Удачи вам. Я буду ждать вашего возвращения в лагере. Ах да, перед уходом поговорите со Скуэрто: он расскажет вам обо всём, что нужно." },
    ["695c"] = { common = "Хорошо, хорошо. Если нас ничего больше не держит, может быть, начнём?" },
    ["696a"] = { male = "Вот что тебе нужно найти: талисман Трелана, сферу Трелана да угольный агат Трелана. Все эти три предмета должны быть в сундуках в башне, и ты спокойненько откроешь эти сундуки; главное – берегись огров. Защитники башни не будут ими заниматься; придётся тебе своё оружие держать наготове. Эти огры сообразят, что ты там и пытаешься обокрасть их – ясное дело, они решат задать тебе взбучку. Будь осторожен – и удачи!", female = "Вот что тебе нужно найти: талисман Трелана, сферу Трелана да угольный агат Трелана. Все эти три предмета должны быть в сундуках в башне, и ты спокойненько откроешь эти сундуки; главное – берегись огров. Защитники башни не будут ими заниматься; придётся тебе своё оружие держать наготове. Эти огры сообразят, что ты там и пытаешься обокрасть их – ясное дело, они решат задать тебе взбучку. Будь осторожна – и удачи!" },
    ["696c"] = { common = "Никого лучше Малин и найти не мог в помощь нам. Потрясающая работа! Он будет рад увидеть, каким ошеломляющим успехом увенчалась наша миссия." },
    ["697a"] = { common = "Отвезите это письмо обратно в Штормград и скажите Малину, что мы с Кретьеном скоро будем дома. Он хорошо вознаградит вас за помощь нам, в этом-то я не сомневаюсь. Доброго пути!" },
    ["697c"] = { common = "*Верховный маг Малин вскрывает письмо, и глаза его расширяются.* Светом клянусь, вам удалось! Трелан будет очень доволен. Я уверен, Кретьен и Скуэрто так же, как и я, радуются своему предстоящему возвращению в Штормград. Благодарю вас. Пожалуйста, примите это как помощь в ваших странствиях." },
    ["698a"] = { male = "Я стараюсь добыть припасы для нашего поста на побережье, к востоку отсюда. Ток'Кар делает, что может, но после несения караульной службы и приготовления пищи для солдат, времени у него остаётся немного. Они любят мясо острозубов, но у меня до сих пор не было возможности отправить им новую партию. Ты не мог бы помочь? Молодые острозубые кроколиски не так вкусны, как взрослые особи, так что дай им ещё год-другой подрасти.", female = "Я стараюсь добыть припасы для нашего поста на побережье, к востоку отсюда. Ток'Кар делает, что может, но после несения караульной службы и приготовления пищи для солдат, времени у него остаётся немного. Они любят мясо острозубов, но у меня до сих пор не было возможности отправить им новую партию. Ты не могла бы помочь? Молодые острозубые кроколиски не так вкусны, как взрослые особи, так что дай им ещё год-другой подрасти." },
    ["698c"] = { common = "Прекрасно! Свежее мясо к ужину! Спасибо. Нынешний вечерок будет куда приятнее прошлого – мы наедимся досыта. Пускай Дар – орк на морду ужасный, зато добрый внутри." },
    ["699a"] = { common = "Мурлоки на побережье представляют опасность, поэтому нас послали сюда отразить эту угрозу Каменору или, если силы врага окажутся слишком велики, поднять тревогу. Отдыхать нам особо некогда, и мы не откажемся от твоей помощи. Из когтей острозубого крепкохвата выходит неплохое оружие, если выделать их должным образом. Раздобудь немного для нас, и ты получишь оружие нашей работы в благодарность за свежее мясо и хорошую компанию." },
    ["699c"] = { male = "Рад видеть тебя живым и здоровым. Эти когти нам весьма пригодятся, ведь чем больше оружия у нас будет в момент атаки, тем лучше. Начну работу над твоим экземпляром как можно скорее, много времени это не займёт, я уже наловчился его изготавливать.", female = "Рад видеть тебя живой и здоровой. Эти когти нам весьма пригодятся, ведь чем больше оружия у нас будет в момент атаки, тем лучше. Начну работу над твоим экземпляром как можно скорее, много времени это не займёт, я уже наловчился его изготавливать." },
    ["700a"] = { common = "Ах, какой прекрасный камень доставляют из Лордерона! Как жаль, что этот край лежит в разрухе. Но памятник получился весьма хорош! Думаю, король будет очень им доволен. Теперь же, будьте добры, пошлите государю весть, что памятник выполнен, как он и просил." },
    ["700c"] = { common = "Гранит – такая малость по сравнению с жизнью достойного дворфа. Но ни один дворф в этом мире не вечен. Будем надеяться, что этот мемориал станет напоминанием будущим поколениям великого Азерота. Мы никогда не забудем, что за них отдали жизнь отважные солдаты вроде Салли Баллу." },
    ["701a"] = { common = "При наличии дополнительных компонентов я смогу изготовить предмет, который наделит Гор'муля коварством ящера! Когда сила ящера проникнет в Гор'муля, он узнает о нашем новом могуществе, и спящий в его душе воин снова пробудится! Для того чтобы создать предмет и соответствующее заклинание, мне потребуются сердца ящеров." },
    ["701c"] = { common = "Да, эти отлично подойдут. Я перенесу силу и дух ящеров в эту сферу. Она наделит Гор'муля огненной силой и разумом ящеров." },
    ["702a"] = { common = "Возьмите эту сферу и используйте её энергию, чтобы дух ящера вселился в Гор'муля. Уверен, это взбодрит его дух и откроет новые горизонты жизни. Когда он вернётся в нормальное состояние, мы сможем разъяснить ему, в каком положении находится нынче Орда, и тогда в наших непрекращающихся войнах мы сможем получить поддержку великого воина." },
    ["702c"] = { common = "По крайней мере, на сей раз – что-то интересное. Оно излучает странную силу..." },
    ["703a"] = { common = "О, жареные крылышки канюка, я их просто обожаю! Такие нежные, сочные, с густым соусом, ммм... Стоит только почуять запах, просто слюнки текут! Я прекрасно их готовлю – пальчики оближешь, как раз собирался сварганить их сегодня на ужин, но... У меня есть всё, кроме основного ингредиента – крылышек! Добудешь мне крылышек – может, поделюсь рецептом!" },
    ["703c"] = { common = "О, я примусь за готовку прямо сейчас! А вот тебе и рецепт, вдруг тоже придёт настроение покулинарничать." },
    ["704a"] = { common = "Последний рапорт от Эгмонда был весьма тревожен, возможно, бедняги уже нет в живых! Он сообщил, что его землекопы обнаружили некие \"древние погребальные урны\" на раскопках близ Ульдамана. Боюсь, эта находка привлекла внимание троггов, так же как и идолы, найденные мною здесь. Мне нужно получить эти урны для исследований. Отправляйся к раскопкам Ульдамана, собери урны и возвращайся ко мне" },
    ["704c"] = { male = "Отличная работа! Упорный труд и толика удачи помогут нам выяснить, как связаны трогги с этими древними артефактами. Сегодня ты оказал геологам неоценимую помощь! Твои усилия не будут забыты. Как и бедняга Эгмонд, вечная ему память...", female = "Отличная работа! Упорный труд и толика удачи помогут нам выяснить, как связаны трогги с этими древними артефактами. Сегодня ты оказала геологам неоценимую помощь! Твои усилия не будут забыты. Как и бедняга Эгмонд, вечная ему память..." },
    ["705a"] = { common = "Бесплодные земли – неприятное местечко, кишащее коварными хищниками и стервятниками. Жуткое, жуткое местечко, особенно для маленького гоблина. Чтобы выжить, приходится постоянно изворачиваться. У меня есть секрет изготовления световых бомб. Я использую их, чтобы отпугивать хищников. Сейчас у меня заканчивается запас ингридиентов, а именно: порошок синего жемчуга. Добудь мне его, и вознаграждение не заставит себя ждать. Надеюсь, обувь у тебя прочная? Синий жемчуг можно найти в раковинах моллюсков на Коварном рифе. Да-да, том самом Коварном рифе в Тернистой долине!" },
    ["705c"] = { common = "Отличный жемчуг! Теперь надо смолоть его в порошок, смешать тут кое с чем... Ну, берегитесь стервятники! Я припас для вас бомбы!" },
    ["706a"] = { common = "В бытность мою учеником Феранора Железной Лапы, я перенял у него технику усиления оружия с помощью наложения огненных чар. Слыхал, Феранор нынче работает в кузне при охотничьем отряде в Лордероне. Не буду пока забивать тебе голову подробностями, скажу только, что для наведения чар требуется очень редкий ингредиент – кровь из ещё бьющегося сердца детёныша чёрного дракона. Мне надо занять себя чем-то в ожидании распоряжений из Стальгорна, так что если принесёшь мне сердце, я продемонстрирую тебе своё умение. Драконов найдёшь в долине Летлор." },
    ["706c"] = { common = "О, это прекрасно подойдёт! Сейчас я немного поработаю над твоим оружием. И оно будет разить без пощады!" },
    ["707a"] = { common = "Я получил отче геолога Сталекрута о ходе раскопок в Лок Модане. Ему нужен курьер для осуществления контроля за другими нашими земляными работами. Больше ничего сказать не могу, но если желаешь ноги поразмять, отправляйся к Сталекруту." },
    ["707c"] = { common = "Значит, тебя послал Грозовая Вершина, да? Хорошо. У меня есть для тебя важное поручение..." },
    ["708a"] = { common = "Поверхность этого металлического чёрного ящика изъедена ржавчиной, как будто его погружали в кислоту – похоже, он долго пролежал в желудке гигантского кондора. На днище ящика выбит какой-то символ и надпись под ним: \"Орудие #девятнадцать – Осадная бригада Стальгорна\"." },
    ["709a"] = { common = "О небеса милосердные! Сама судьба стучится в двери! Помяните моё слово! Рок! Фатум! Нет, я не могу более ничего сказать... Не могу поминать их имён, чтобы они не услышали меня! Но если нам удастся хотя бы узнать о них больше... Может, мы сможем противостоять им! Может быть... Иди в Ульдаман – проклятье, я всё же произнёс это! Найди табличку...табличку Рьюнэха. Да, найди её! Не заставляй меня повторять! Она там, в глубине, в древнем сундуке, более древнем, чем любая доселе найденная работа дворфов." },
    ["709c"] = { common = "О, судьба милосердна к нам! Благодарю тебя! Возможно, нам удастся спастись!" },
    ["710a"] = { common = "Здесь, в Бесплодных землях, мне пришлось приостановить работу над моим последним изобретением – оковами Стихий. Когда они будут закончены, то позволят вызывать ещё более мощных элементалей и управлять ими.Чтобы продолжить работу, мне нужны маленькие осколки камня, чтобы опробовать на них некоторые новые заклинания и механизмы. Маленькие осколки камня, которые можно собрать с младших каменных элементалей, как раз подойдут. Они водятся к западу отсюда, сбегай-ка туда быстренько." },
    ["710c"] = { common = "Это будет превосходно. Спасибо. Хм, в них больше песка, чем я ожидал. Нужно отрегулировать коэффициент трения. Нет, подожди. Они должны всё ещё быть уязвимы к маслу льда. Бормоча себе, Лотвиль кладёт кулак на ладонь его другой руки и смотрит на них, как будто очарованный." },
    ["711a"] = { male = "Ты уже проявил себя более способным, чем все мои ученики вместе взятые. Теперь мне потребуется сила твоих мускулов. У каменных элементалей при должной осторожности можно найти большие каменные глыбы. Они достаточно велики и твёрды, чтобы отколоть от них куски, удобные для исследования. Ты найдёшь их у подножия гор к западу или юго-востоку отсюда. Можешь не торопиться, я пока займусь исследованием более мелких кусочков, которые ты принёс мне.", female = "Ты уже проявила себя более способной, чем все мои ученики вместе взятые. Теперь мне потребуется сила твоих мускулов. У каменных элементалей при должной осторожности можно найти большие каменные глыбы. Они достаточно велики и твёрды, чтобы отколоть от них куски, удобные для исследования. Ты найдёшь их у подножия гор к западу или юго-востоку отсюда. Можешь не торопиться, я пока займусь исследованием более мелких кусочков, которые ты принесла мне." },
    ["711c"] = { common = "Просто замечательно! Я было думал, что мне придётся нанять дюжину тауренов, чтобы они принесли всё это мне." },
    ["712a"] = { male = "Мне нужно, чтобы ты принёс мне ещё кое-что – браслеты каменных элементалей. Полагаю, с помощью этих браслетов можно оценить прочность моих кандалов. В магическом кристалле я видел нескольких каменных элементалей к юго-западу отсюда. Недалеко от них я заметил ещё и нескольких огров. Принеси-ка мне пять браслетов, чтобы было с запасом. Мой Серво славится умением перепутывать все реагенты и результаты исследований.", female = "Мне нужно, чтобы ты принесла мне ещё кое-что – браслеты каменных элементалей. Полагаю, с помощью этих браслетов можно оценить прочность моих кандалов. В магическом кристалле я видел нескольких каменных элементалей к юго-западу отсюда. Недалеко от них я заметил ещё и нескольких огров. Принеси-ка мне пять браслетов, чтобы было с запасом. Мой Серво славится умением перепутывать все реагенты и результаты исследований." },
    ["712c"] = { male = "Ты когда-нибудь думал стать исследовательским ассистентом? Нет? Я не уверен, что справлюсь здесь без твоих способностей. Ум, любопытство, и сила - всё это в тебе есть.", female = "Ты когда-нибудь думала стать исследовательским ассистентом? Нет? Я не уверен, что справлюсь здесь без твоих способностей. Ум, любопытство, и сила - всё это в тебе есть." },
    ["713a"] = { common = "Послушай, я расскажу тебе о масле льда – это лучшее средство для того, чтобы уберечь мотор или механизмы от перегрева. Его охлаждающая способность просто потрясает, а его долговечность в качестве смазочного материала просто не имеет равных. И это ещё не всё: оно позволяет сохранять чары на магических предметах. Мне нужен сосуд этого масла, чтобы усилить магический потенциал кандалов моей работы и сделать их достаточно мощными, чтобы вызванный нами дух не прикончил нас на месте. Брокин, мой друг-гоблин, научит тебя, как изготовить масло. Ты найдёшь его в долине Альтерака." },
    ["713c"] = { common = "Изумительно! Оно будет идеальным охладителем для моих новых браслетов. Если чары не продержаться век, тогда я отдам все мои вещи Серво. Всё собрание магов испугается после того, как я окончу это дело. Просто подожди и увидишь." },
    ["714a"] = { male = "Ты справился со своей работой выше всяких похвал. *Мысли Лотвила явно витают где-то в его экспериментах.* Будешь у нас в Караносе, приходи ко мне работать, приму в любое время с распростёртыми... Оп-ля! Лови-лови, скорей! Да, спасибо. А сейчас мне нужна всего лишь одна малость. Довольно маленькая штуковина, но очень важная: гирохронатом. Если сможешь мне его добыть, я, наконец, смогу закончить этот эксперимент.", female = "Ты справилась со своей работой выше всяких похвал. *Мысли Лотвила явно витают где-то в его экспериментах.* Будешь у нас в Караносе, приходи ко мне работать, приму в любое время с распростёртыми... Оп-ля! Лови-лови, скорей! Да, спасибо. А сейчас мне нужна всего лишь одна малость. Довольно маленькая штуковина, но очень важная: гирохронатом. Если сможешь мне его добыть, я, наконец, смогу закончить этот эксперимент." },
    ["714c"] = { common = "ХА! Лотвиль отбирает у тебя гирохронатом. Отлично! Мы почти у цели! Нет, в самом деле! Это же мой самый приоритетный проект! Дай-ка я засуну эту штуку в положенное ей место, и ты увидишь плоды моих – наших! – трудов! Сейчас, надо только немного подождать... пару секунд... или минут... или часов... Ладно, разберёмся." },
    ["715a"] = { male = "Полагаю, все задачи, поставленные перед тобой Лотвилом, вскоре покажутся тебе очень простыми по сравнению с тем, что ждёт впереди. С другой стороны, ты доказал свою приверженность наукам, которые так чтит Лотвил. Не поможешь ли ты, в таком случае, и мне? Мне необходимо лечебное зелье и зелье невидимости. Похоже, и то, и другое может мне вскоре понадобиться, если Лотвил продолжит в том же духе. Взамен я дам тебе рецепт зелья, разработанный мной во время обучения у Лотвила. Рецепт основан на сведениях, собранных им во время экспериментов здесь, в Бесплодных землях.", female = "Полагаю, все задачи, поставленные перед тобой Лотвилом, вскоре покажутся тебе очень простыми по сравнению с тем, что ждёт впереди. С другой стороны, ты доказала свою приверженность наукам, которые так чтит Лотвил. Не поможешь ли ты, в таком случае, и мне? Мне необходимо лечебное зелье и зелье невидимости. Похоже, и то, и другое может мне вскоре понадобиться, если Лотвил продолжит в том же духе. Взамен я дам тебе рецепт зелья, разработанный мной во время обучения у Лотвила. Рецепт основан на сведениях, собранных им во время экспериментов здесь, в Бесплодных землях." },
    ["715c"] = { common = "ДА! Я имею в виду, спасибо. Это поможет тебе в странствиях по Бесплодным землям." },
    ["716a"] = { male = "Я знаю, каким скупым бывает Лотвил, поэтому хочу сам вознаградить тебя за труды. Возможно, мой подарок даже поможет тебе защититься от того, что сулит это его новое изобретение... Я собрал все неиспользованные камни, которые ты принёс и смогу сделать из них прекрасные наручи, которые наверняка тебе понадобятся. Разумеется, они будут магическими. Но мне потребуются украшенные узором бронзовые наручи, созданные кузнецом, чтобы я смог закончить работу.", female = "Я знаю, каким скупым бывает Лотвил, поэтому хочу сам вознаградить тебя за труды. Возможно, мой подарок даже поможет тебе защититься от того, что сулит это его новое изобретение... Я собрал все неиспользованные камни, которые ты принесла и смогу сделать из них прекрасные наручи, которые наверняка тебе понадобятся. Разумеется, они будут магическими. Но мне потребуются украшенные узором бронзовые наручи, созданные кузнецом, чтобы я смог закончить работу." },
    ["716c"] = { common = "Держи. Примерь эти." },
    ["717a"] = { common = "Сейчас уже очевидно, что мы не можем быть уверены, что Чернохлыст и Гематус заключены в Летлоре надёжно. Там обосновались чёрные драконы, кроме того, этим ограм удалось завладеть знаком Земли – а это значит, что требуются куда более серьёзные меры. Драконье узилище заперто тремя рунными камнями, которые можно заполучить только с помощью знака Земли. Камни нужны, чтобы сломать печать на узилище. Сломай печать и сделай так, чтобы драконы упокоились навек." },
    ["717c"] = { common = "Кирин Тор больше не будет беспокоиться по поводу грозных пленников Летлора. Я сообщу об этом своему господину. Красус, несомненно, будет доволен." },
    ["718a"] = { male = "В спешке покидая Ульдаман, мы были вынуждены бросить не одну повозку и ящик с припасами. Местные огры из лагеря Кош набросились на них, как стервятники на падаль. Хотя воняют огры не лучше... чем падаль, я имею в виду. В общем, они растащили все наши обозы с оружием и прочим скарбом и... Короче, мне даже неловко об этом говорить, но мы тут остались слегка совсем без еды... Не мог ли бы ты нам помочь?", female = "В спешке покидая Ульдаман, мы были вынуждены бросить не одну повозку и ящик с припасами. Местные огры из лагеря Кош набросились на них, как стервятники на падаль. Хотя воняют огры не лучше... чем падаль, я имею в виду. В общем, они растащили все наши обозы с оружием и прочим скарбом и... Короче, мне даже неловко об этом говорить, но мы тут остались слегка совсем без еды... Не могла ли бы ты нам помочь?" },
    ["718c"] = { common = "О, благодарю тебя! Мы тут, надо сказать, уж было песок есть подумывали. Ну да это дело прошлое. Сегодня будем пировать, как короли!" },
    ["719a"] = { male = "Будь осторожен! Повсюду шныряют дворфы Чёрного Железа – видимо, из клана Кузни Теней. Они только что напали на наш раскоп и почитай всех там вырезали, включая моего шефа Тяжелоступа. Я едва ноги унёс. Раскоп прямо к северу отсюда. Я вот прикидываю, как бы выручить оттуда часть наших припасов, особенно мою счастливую кирку. Как думаешь – сумеешь помочь? Наверняка кто-нибудь из этих гадов Чёрного Железа спёр мою кирку!", female = "Будь осторожна! Повсюду шныряют дворфы Чёрного Железа – видимо, из клана Кузни Теней. Они только что напали на наш раскоп и почитай всех там вырезали, включая моего шефа Тяжелоступа. Я едва ноги унёс. Раскоп прямо к северу отсюда. Я вот прикидываю, как бы выручить оттуда часть наших припасов, особенно мою счастливую кирку. Как думаешь – сумеешь помочь? Наверняка кто-нибудь из этих гадов Чёрного Железа спёр мою кирку!" },
    ["719c"] = { male = "Ты спас меня, герой. Рад, что нашёлся кто-то, способный преподать Тенегорну урок.", female = "Ты спасла меня, героиня. Рад, что нашёлся кто-то, способный преподать Тенегорну урок." },
    ["720a"] = { common = "Куском мела на карте нацарапаны слова.\"Рейдол, они уводят меня в Ульдаман. Пришли помощь! -Тяжелоступ\"" },
    ["720c"] = { common = "Тяжелоступ жив?! Это поразительно!" },
    ["721a"] = { common = "Ты сможешь разыскать его? Ты разыщешь Тяжелоступа? Проклятые дворфы из Кузни Теней схватили его, чтобы выпытать, что он знает о раскопках поселения титанов. Если это случится, весь Стальгорн будет в большой опасности! Дворфы Чёрного Железа уже давно разыскивают способы сотворения могущественных големов. Конечно, такова была цель и Тяжелоступа, но это только для того, чтобы остановить Чёрную Сталь! Возможно, они сохранят ему жизнь, пока не вытянут из него все секреты. Поспеши, быть может, его ещё удастся спасти!" },
    ["721c"] = { male = "О, я так ослабел... кашляет Подойди ко мне, герой? Тебя прислал Рейдол? Клянусь Мурадином, парень вовсе не так туп, как кажется.кашляет", female = "О, я так ослабел... кашляет Подойди ко мне, героиня? Тебя прислал Рейдол? Клянусь Мурадином, парень вовсе не так туп, как кажется.кашляет" },
    ["722a"] = { male = "Тебе не занимать смелости, раз ты явился за мной в Ульдаман, герой. Если в самом деле хочешь помочь старику Тяжелоступу... *кашляет*... Найди мне мой амулет. Это Чернотень... Его забрал Магреган Чернотень. Он здесь, в развалинах, я знаю... Этот амулет приведёт их... *кашляет* прямо к свиткам, если их не остановить... Всё в твоих руках! Пожалуйста... верни амулет. Если свитки попадут к ним в лапы, Чёрное Железо сможет создавать ещё более мощных големов. Я знаю, я это нутром чую!", female = "Тебе не занимать смелости, раз ты явилась за мной в Ульдаман, героиня. Если в самом деле хочешь помочь старику Тяжелоступу... *кашляет*... Найди мне мой амулет. Это Чернотень... Его забрал Магреган Чернотень. Он здесь, в развалинах, я знаю... Этот амулет приведёт их... *кашляет* прямо к свиткам, если их не остановить... Всё в твоих руках! Пожалуйста... верни амулет. Если свитки попадут к ним в лапы, Чёрное Железо сможет создавать ещё более мощных големов. Я знаю, я это нутром чую!" },
    ["722c"] = { common = "Ха!кхе, кхе Я знал, что ты справишься! сморкается Отличная работа.кашляет" },
    ["723a"] = { common = "Тяжелоступ едва дышит и, собрав последние силы, произносит слова. Найди Рейдола! Передай ему мой амулет... кашляет Он знает, что делать. кашляет Он знает, я искал истоки происхождения нашего народа, кашляет знает и то, что целью моей жизни было остановить клан Кузни Теней. Нельзя позволить, чтобы они нашли свитки... кашляет" },
    ["723c"] = { common = "Амулет Тяжелоступа! Если раньше в моём сердце ещё теплилась надежда, что он жив, то теперь ничто не снимет с моей души этот камень. Этот амулет – дело всей его жизни. Нельзя допустить, чтобы его смерть была напрасной!" },
    ["724a"] = { common = "К кому же обратиться за советом... Историк Карник! Конечно! Он сейчас в Стальгорне – он точно сможет помочь! Он искал потерянные артефакты вместе с Тяжелоступом в Ульдамане. Полагаю, в Кузне Теней прознали, что эти двое располагают тайными сведениями. Сообщи Карнику о том, как погиб Тяжелоступ, и передай ему амулет – а он расскажет, что делать дальше." },
    ["724c"] = { male = "О, а вот это совсем другой разговор! Возможно, ты ещё не осознал всей серьёзности происходящего, ведь так? Мы оплачем Тяжелоступа позже. Сейчас я объясню тебе, почему этот амулет так важен.", female = "О, а вот это совсем другой разговор! Возможно, ты ещё не осознала всей серьёзности происходящего, ведь так? Мы оплачем Тяжелоступа позже. Сейчас я объясню тебе, почему этот амулет так важен." },
    ["725a"] = { male = "Беги, найди советника Белграма как можно скорее. Расскажи ему, что видел, и спроси, что нам делать дальше. Отдашь ему эту записку, я изложил в ней всё как можно подробней. А я пока побеседую с духом Тяжелоступа. Возможно, ему известно нечто, что сможет помочь нам пресечь безумные действия Тенегорнских прихвостней в Бесплодных землях. Теперь нам остаётся только молиться.", female = "Беги, найди советника Белграма как можно скорее. Расскажи ему, что видела, и спроси, что нам делать дальше. Отдашь ему эту записку, я изложил в ней всё как можно подробней. А я пока побеседую с духом Тяжелоступа. Возможно, ему известно нечто, что сможет помочь нам пресечь безумные действия Тенегорнских прихвостней в Бесплодных землях. Теперь нам остаётся только молиться." },
    ["725c"] = { common = "А, весточка от историка Карника. Прекрасно. Для него у меня всегда найдётся минутка. Советник Белграм разворачивает записку и погружается в чтение." },
    ["726a"] = { common = "*Когда советник Белграм дочитывает письмо до конца, его глаза в ужасе расширяются* Это дурные вести... Пожалуйста, вернись к историку Карнику и извести его именем короля, что он должен действовать быстро и рассудительно. Он должен остановить Кузню Теней в Бесплодных землях." },
    ["726c"] = { common = "Ты действуешь по этому делу с поспешностью, которая сделала бы честь и королю! Хорошо. Я знаю, что делать с Кузней Теней. Их силы в Ульдамане будут рассеяны, если мы поразим их в самое сердце – ударим по крепости Ангор." },
    ["727a"] = { common = "Эта табличка говорит о многом. И всё же этого недостаточно! Есть книга – древняя книга Йагина. Те, от кого я бежал... Они хранят эту книгу и самые мудрые из них изучают её. Она содержит обширные знания, и в ней можно найти ключ к спасению! Отправляйся к Геррику Костохвату. Ты найдёшь его в лавке в Стальгорне, в Заброшенном гроте. Покажешь ему эту печать, и он примет тебя за своего. Попроси у него книгу Йагина и принеси её мне." },
    ["727c"] = { male = "О, рад видеть тебя брат.", female = "О, рад видеть тебя сестра." },
    ["728a"] = { common = "Эта табличка говорит о многом. И всё же этого недостаточно! Есть книга – древняя книга Йагина. Те, от кого я бежал... Они хранят эту книгу, и самые мудрые из них изучают её. Она содержит обширные знания, и в ней можно найти ключ к спасению! Отправляйся к хранителю Бел'дугуру в Лордерон. Покажешь ему эту печать, и он примет тебя за своего. Попроси у него книгу Йагина и принеси её мне." },
    ["728c"] = { male = "Будь осторожен, герой. Многие на этом свете сомневаются в праведности наших дел. И многие из них сделали бы всё возможное, чтобы уничтожить нас! Ты должен всегда сохранять бдительность, осторожность и терпение...", female = "Будь осторожена, героиня. Многие на этом свете сомневаются в праведности наших дел. И многие из них сделали бы всё возможное, чтобы уничтожить нас! Ты должна всегда сохранять бдительность, осторожность и терпение..." },
    ["729a"] = { common = "Мне была оказана большая честь, когда мастер Седоус назначил меня работать под руководством великого геолога Сомнамбулера. В академии в Стальгорне все знают о грандиозных открытиях Сомнамбулера. Но геолог довольно... ммм... рассеян... порой кажется, что он не от мира сего. Мы обнаружили признаки некогда крупного поселения. Из-под земли выскочили ужасные големы и заполонили весь раскоп. Но Сомнамбулер, казалось, так ничего и не заметил. Я побежала обратно в Аубердин за помощью. Прошу тебя, отправляйся на юг и посмотри, всё ли в порядке с геологом!" },
    ["729c"] = { male = "Это ты, Холли? Мне нужна помощь, надо подолбить этот камень. Передай-ка мне мою щётку для камня – мне кажется, я тут что-то вижу. Ой, да ты не Холли! Вряд ли ты видел мою щётку для камня... А, забудь об этом! Я обещал Лиге, что отошлю им ту таинственную окаменелость, что я нашёл. Куда же делась Холли? Так много нужно сделать! И где ж эта таинственная окаменелость... и моя щётка... и Холли... И ты кто будешь... правда, это неважно, если ты хочешь помочь. Дай знать, когда сможешь начать поиски.", female = "Это ты, Холли? Мне нужна помощь, надо подолбить этот камень. Передай-ка мне мою щётку для камня – мне кажется, я тут что-то вижу. Ой, да ты не Холли! Вряд ли ты видела мою щётку для камня... А, забудь об этом! Я обещал Лиге, что отошлю им ту таинственную окаменелость, что я нашёл. Куда же делась Холли? Так много нужно сделать! И где ж эта таинственная окаменелость... и моя щётка... и Холли... И ты кто будешь... правда, это неважно, если ты хочешь помочь. Дай знать, когда сможешь начать поиски." },
    ["730a"] = { male = "Приятно видеть! герой, интересующийся великими археологическими чудесами нашего мира! Часто наши друзья из Альянса считают нашу работу чем-то вроде развлечения. Многие просто отказываются понимать. Великая, могущественная сила угрожает всему Азероту – от Лордерона до Калимдора. Меня очень беспокоит судьба группы, которую я отправил на Тёмные берега. От них уже несколько недель ни слова. Отправляйся в Аубердин и узнай, где они предположительно могут находиться.", female = "Приятно видеть! героиня, интересующаяся великими археологическими чудесами нашего мира! Часто наши друзья из Альянса считают нашу работу чем-то вроде развлечения. Многие просто отказываются понимать. Великая, могущественная сила угрожает всему Азероту – от Лордерона до Калимдора. Меня очень беспокоит судьба группы, которую я отправил на Тёмные берега. От них уже несколько недель ни слова. Отправляйся в Аубердин и узнай, где они предположительно могут находиться." },
    ["730c"] = { common = "Как же здорово, что главный археолог Седой Ус прислал вас..." },
    ["731a"] = { male = "Итак, Холли... А, да, верно, ты же не Холли. А где Холли? Ай, ладно, это к делу не относится. Мы должны найти эту щётку для камня... то есть я имею в виду таинственную окаменелость! Мы должны найти эту окаменелость. Лига исследователей в Дарнассе захочет узнать, чем я тут занимаюсь. Дай мне знать, когда будешь готов, и начнём поиски этой щётки... ну, то есть окаменелости! Мы найдём какой-нибудь документ, чтобы в Лиге остались довольны. Так что, готов?", female = "Итак, Холли... А, да, верно, ты же не Холли. А где Холли? Ай, ладно, это к делу не относится. Мы должны найти эту щётку для камня... то есть я имею в виду таинственную окаменелость! Мы должны найти эту окаменелость. Лига исследователей в Дарнассе захочет узнать, чем я тут занимаюсь. Дай мне знать, когда будешь готова, и начнём поиски этой щётки... ну, то есть окаменелости! Мы найдём какой-нибудь документ, чтобы в Лиге остались довольны. Так что, готова?" },
    ["731c"] = { common = "Слава звёздам, геолог Сомнамбулер в безопасности! Я же говорила тебе, какой он рассеянный. Не могу поверить, что он твёрдо хочет остаться там, где рядом повсюду рыщут жуткие твари!" },
    ["732a"] = { male = "Сигрун сказал, что ты оказал ему неоценимую помощь. Возможно, мне она тоже понадобится. Меня прислал сюда мой господин, Красус из Кирин Тора, чтобы прекратить беспорядки в низине Летлор. Я не имею права разглашать поставленные передо мной задачи, но можешь не сомневаться – они имеют самое первостепенное значение. Шайка бродячих огров, которых видели близ лагеря Бофф, украла предмет, именуемый знаком Земли. Мне необходимо вернуть этот предмет. Принеси его мне, и я расскажу тебе больше.", female = "Сигрун сказал, что ты оказала ему неоценимую помощь. Возможно, мне она тоже понадобится. Меня прислал сюда мой господин, Красус из Кирин Тора, чтобы прекратить беспорядки в низине Летлор. Я не имею права разглашать поставленные передо мной задачи, но можешь не сомневаться – они имеют самое первостепенное значение. Шайка бродячих огров, которых видели близ лагеря Бофф, украла предмет, именуемый знаком Земли. Мне необходимо вернуть этот предмет. Принеси его мне, и я расскажу тебе больше." },
    ["732c"] = { male = "Ты принёс знак, – это очень хорошая весть! Знак Земли был создан дворфами Чёрного Железа из Крепости Ангор, чтобы заключить в узилище двух беспощадных драконов-помощников Смертокрыла – близнецов Бича Тьмы и Гематуса.", female = "Ты принесла знак, – это очень хорошая весть! Знак Земли был создан дворфами Чёрного Железа из Крепости Ангор, чтобы заключить в узилище двух беспощадных драконов-помощников Смертокрыла – близнецов Бича Тьмы и Гематуса." },
    ["733a"] = { common = "Да, туго нам придётся, если мы не сможем раздобыть материалов для возведения простейших укреплений и других нужд. Заметил я, что у огров в этих землях полно металлолома. Возможно, легенды об осадных машинах, применявшихся в Бесплодных землях, не так уж далеки от истины... В общем, проспектор очень беспокоится за состояние нашего маленького лагеря, так что надо приниматься за работу как можно скорее. Главный лагерь огров расположен рядом с Гротом Гнилобрюхих, к западу отсюда. Учти – расстояние приличное!" },
    ["733c"] = { common = "Спасибо! Думаю, это поможет нам дотянуть до распоряжения из Стальгорна или Лиги Исследователей. Эх, добыть бы теперь соли для закалки оружия..." },
    ["734a"] = { common = "Пекрасно, прекрасно... *Лотвил на секунду отрывает взгляд от кандалов* Сбегай-ка к Люсьену. Мне нужен зубец#пять. Принеси его мне." },
    ["734c"] = { common = "Зубец #пять, что? Да уж, это не приведёт ни к чему хорошему." },
    ["735a"] = { common = "Книга Йагина, да? Вы хотите написать в ней новую главу о нас? Ну да, не мне спрашивать. Я помогу вам – у меня как раз есть дополнительный экземпляр. Мы ведь должны друг другу помогать, не так ли? Только так мы добьёмся успеха. Мне нужны три предмета силы. Принесите их мне – и получите книгу. Названий преметов я вам не скажу – нас могут подслушивать. Но я их вам напишу." },
    ["735c"] = { male = "На вас можно положиться, герой. Воистину, вам предстоит вписать новую главу в книгу нашего ордена, и я уверен, что это будут славные страницы.", female = "На вас можно положиться, героиня. Воистину, вам предстоит вписать новую главу в книгу нашего ордена, и я уверен, что это будут славные страницы." },
    ["736a"] = { male = "Тебе нужна книга Йагина? Планируешь собрать своё стадо? Ну, разумеется... и я с удовольствием помогу тебе, брат. Взамен я также попрошу тебя о помощи. Мне нужны три предмета силы. Принеси их – и книга будет твоей. Назвать вслух эти предметы я не могу, но запишу их. Добудь мне всё, что я укажу в списке. Если справишься с этим, значит, ты действительно достоин начать новую главу в истории нашего ордена.", female = "Тебе нужна книга Йагина? Планируешь собрать своё стадо? Ну, разумеется... и я с удовольствием помогу тебе, сестра. Взамен я также попрошу тебя о помощи. Мне нужны три предмета силы. Принеси их – и книга будет твоей. Назвать вслух эти предметы я не могу, но запишу их. Добудь мне всё, что я укажу в списке. Если справишься с этим, значит, ты действительно достойна начать новую главу в истории нашего ордена." },
    ["736c"] = { male = "Поразительно! Ты обладаешь или великим искусством, или удачей, иначе тебе не удалось бы добыть эти реликвии. Так или иначе, ты очень помог нам.", female = "Поразительно! Ты обладаешь или великим искусством, или удачей, иначе тебе не удалось бы добыть эти реликвии. Так или иначе, ты очень помогла нам." },
    ["737a"] = { common = "У меня есть для тебя книга. Думаю, не стоит говорить, что с ней нужно обращаться очень бережно. И непременно держать подальше от рук врагов. В этой книге содержится много секретов... Опасных секретов!" },
    ["737c"] = { common = "Вот она! О, проблеск надежды! Быть может, твои труды принесли нам спасение! Тебе нужно поставить памятник! Воздвигнуть святилище! Славить твоё имя в сказаниях, пока у детей твоих детей не родятся правнуки! Если только... Если только ОНИ ещё не вырвались на свободу. Потому что если это случится, можешь забыть о детях. Если ОНИ вырвались на свободу, мы все пойдём на корм червям." },
    ["738a"] = { common = "Проспектор Эгмонд вёл раскопки в Бесплодных землях, на юго-западе. Я говорю \"вёл\", потому что, к несчастью, от него нет вестей уже не одну неделю. Его нужно найти. В последний раз его видели на самом южном раскопе Бесплодных земель – он расположен за Крепостью Ангор. Думаю, стоит начать поиски там." },
    ["738c"] = { common = "Должно быть, этот скелет принадлежит Эгмонду. Его кости изломаны и выбелены солнцем." },
    ["739a"] = { common = "Следы Эгмонда уводят на запад. Судя по кровавым следам на камнях и песке, дворф полз на коленях. И здесь он умер. Под правой рукой мертвеца еле виднеется слово, нацарапанное на куске песчаника. \"Мурдалок,\" – гласит надпись." },
    ["739c"] = { common = "Это горькая весть! Он был силён и славно управлялся с молотом. Не сомневаюсь, прежде чем он пал от лап троггов, он уничтожил не одну мерзкую тварь." },
    ["741a"] = { common = "Так геолог хочет отослать эту таинственную окаменелость Лиге исследователей в Дарнасс? Мне не хотелось бы уезжать с Тёмных берегов без него. Вот, отвезите эту таинственную окаменелость главному археологу Седоусу в Дарнасс." },
    ["741c"] = { common = "Ух ты! Только геолог Сомнамбулер мог сделать такое открытие!" },
    ["742a"] = { common = "Внимание, молодые герои! Вас ждут дикие чащи Ясеневого леса! Орде удалось закрепиться в землях к северу от Степей. И два наших форпоста – застава Расщеплённого Древа и застава Зорамского взморья – бьются во славу Орды! Те, кто жаждет подвигов, могут отправиться туда. Запомните: Сенани Громосерд находится на заставе Расщеплённого Древа, к северу от Степей. Она ждёт желающих принять участие в большой охоте!" },
    ["742c"] = { male = "Добро пожаловать на новое пограничье. Ясеневый лес – край неограниченных возможностей, где юному герою вроде тебя выпадает шанс показать себя. Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть. Как понимаю, ты здесь для того, чтобы побольше узнать об охоте. Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать.", female = "Добро пожаловать на новое пограничье. Ясеневый лес – край неограниченных возможностей, где юному героине вроде тебя выпадает шанс показать себя. Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть. Как понимаю, ты здесь для того, чтобы побольше узнать об охоте. Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать." },
    ["743a"] = { male = "Спасибо, что выбрал время поговорить со мной. Я Руул, воин и учитель. Пришло время пройти испытания и покинуть Мулгор. Если ты хочешь проверить свою силу, вызови на бой гарпий Неистовства Ветра, живущих на юго-востоке. Они гнездятся вдоль гребня гор в стороне от дороги. Эти гарпии – вечные враги тауренов Мулгора. По схватке с ними мы будем судить о твоей силе.", female = "Спасибо, что выбрала время поговорить со мной. Я Руул, воин и учитель. Пришло время пройти испытания и покинуть Мулгор. Если ты хочешь проверить свою силу, вызови на бой гарпий Неистовства Ветра, живущих на юго-востоке. Они гнездятся вдоль гребня гор в стороне от дороги. Эти гарпии – вечные враги тауренов Мулгора. По схватке с ними мы будем судить о твоей силе." },
    ["743c"] = { male = "Молодец. Похоже, ты готов двинуться дальше. Попутного тебе ветра!", female = "Молодец. Похоже, ты готова двинуться дальше. Попутного тебе ветра!" },
    ["744a"] = { common = "Вскоре мой брат предстанет перед вождём Кровавым Копытом, и мне выпала большая честь сделать для него головной убор. Мне хотелось бы попросить тебя об одолжении – надо сделать одно дело, пока я буду красить эти кожаные полоски. Я просто не успею добыть достаточное количество перьев – так не поможешь ли ты мне в этом? Перья нужной величины можно найти у гарпий, что живут далеко на севере и северо-западе от Громового Утёса. Мне нужно всего-то шесть лазурных и шесть бронзовых перьев, чтобы закончить работу." },
    ["744c"] = { common = "Спасибо за помощь. Моё участие в церемонии в честь моего брата почти закончено. От меня требуется только подарить ему этот убор и быть свидетелем." },
    ["745a"] = { common = "Нашей земле причиняют боль раздоры её обитателей. Я надеюсь, что тебе не суждено видеть столько войн, сколько выпало мне. И всё же я вынужден просить тебя вступить в бой. Благодаря этому ты поймёшь, что малая угроза, если не искоренить её, со временем разрастается. Гноллы-бледногривы поселились на юге от нашей деревни и в пещере на западе. Они не обращают внимания на наши попытки договориться и без жалости убивают животных Мулгора. Слова бессильны остановить их." },
    ["745c"] = { common = "Хорошо, что ты отнёсся к моему заданию со всей серьёзностью. Очень важно уважать землю и её обитателей. Жизнь и смерть – это вечный цикл... Необходимость. Одно не может существовать без другого. Обдумай это хорошенько и никогда не забывай." },
    ["746a"] = { common = "К северо-западу отсюда дворфы готовятся к раскопкам. Они думают, что тайны скрыты глубоко в земле, и это правда, но у неё надо учиться, а не осквернять бесконечными ямами. Собери инструменты дворфов, уничтожь их и принеси мне. Ломать инструменты можно в кузнице, которая есть в Громовом Утёсе, но подойдёт любая, даже та, что находится в дворфийском лагере." },
    ["746c"] = { common = "Спасибо. Звери Мулгора успокоятся. И, если будет на то воля духов, дворфы познают, что бурение земли – не лучший путь к обретению знаний." },
    ["747a"] = { male = "Ты выглядишь весьма многообещающе, и тебе будет предоставлена возможность проявить себя перед племенем. Возможно, вскоре тебя позовут в Громовой Утёс. Но прежде чем это случится, тебе придётся доказать моему отцу, вождю Соколиному Ветру, что ты достоин этой чести. На плато Красного Облака предметом особой гордости является охотничье мастерство. Таурены охотятся ради выживания и для забавы. Сейчас в племени кончается запас мяса, кроме того, нам нужны перья для украшения одежды. Покажи, на что ты способен, – поохоться на равнинных долгоногов и принеси мяса в деревню.", female = "Ты выглядишь весьма многообещающе, и тебе будет предоставлена возможность проявить себя перед племенем. Возможно, вскоре тебя позовут в Громовой Утёс. Но прежде чем это случится, тебе придётся доказать моему отцу, вождю Соколиному Ветру, что ты достойна этой чести. На плато Красного Облака предметом особой гордости является охотничье мастерство. Таурены охотятся ради выживания и для забавы. Сейчас в племени кончается запас мяса, кроме того, нам нужны перья для украшения одежды. Покажи, на что ты способна, – поохоться на равнинных долгоногов и принеси мяса в деревню." },
    ["747c"] = { common = "Таурены Нараче благодарят тебя. Я уверен, ты достигнешь больших высот." },
    ["748a"] = { common = "Гоблины и их прислужники отравили наши священные колодцы! Это недопустимо. Для очищения колодцев придётся создать тотэмы, а ты пойдёшь с ними к колодцам и проведёшь очищающие ритуалы. Начнём мы с колодца Заиндевевшего Копыта. Земля сама поможет нам. Принеси мне лапы койотов и когти взрослых долгоногов. Эти звери живут на юго-западе." },
    ["748c"] = { common = "Молодец. Я вплету силу принесённых тобой вещей в тотэм Очищения." },
    ["749a"] = { common = "Несколько дней назад мы наткнулись на охраняемый караван Торговой компании, следовавший вдоль северного берега озера Каменного Быка. В предыдущей битве мы потеряли двоих, поэтому на сей раз мы напали без промедления и уничтожили караван. Мы бросили их ящики с припасами, полагая, что наши факелы уничтожат всё ценное, но учитывая, что возле сожжённых телег видели мародёров Торговой компании, похоже, мы ошиблись. Быть может, ты сходишь к каравану и посмотришь, что в ящиках?" },
    ["749c"] = { common = "Все стороны ящика опечатаны знаками рудникового отдела Торговой Компании. Сбоку прикреплены пометки, что содержимое должно быть обработано на одном из центральных заводов компании." },
    ["750a"] = { common = "Любой искушённый в охоте таурен понимает, что её смысл не заключается в убийстве любой подвернувшейся добычи. Живущие на равнине звери обеспечивают нас всем необходимым для выживания. Ты произведёшь впечатление на старейшин, если принесёшь им несколько шкур горных пум – они у нас очень высоко ценятся! Нашим детям нужна одежда, да и шатры пора подлатать." },
    ["750c"] = { common = "Таурены из Нараче благодарят тебя за твои дары. Твоё охотничье искусство будет высоко цениться в Громовом Утёсе." },
    ["751a"] = { common = "Приоткрыв крышку, вы видите плотно упакованную руду и минералы – новое свидетельство деятельности Торговой компании в Мулгоре. Поверх руды и минералов лежит пачка бумаг. Со стороны восточных предгорий доносятся звуки работы и к небу поднимается дым от больших костров." },
    ["751c"] = { common = "Похоже, Торговая Компания в самом деле замыслила лишить нас всех природных ресурсов. Хорошо знать это наверняка, пожалуй, пришло время действовать." },
    ["752a"] = { common = "Все члены племени живут вместе в мире и гармонии. Мы преданы друг другу и отвечаем друг за друга. Я обращаюсь к тебе со скромной просьбой. Моя матушка сегодня отправилась за водой к источнику к юго-востоку от Нараче. С тех пор прошло довольно много времени. Не поищешь ли ты её, пока я занимаюсь делами племени?" },
    ["752c"] = { male = "Ты проделал такой путь, только чтобы оказать услугу старушке? Да, похоже, ты чтишь традиции нашего народа. Вот, возьми себе одно из этих учебных пособий – из него ты узнаешь, как ещё можно помочь сообществу.", female = "Ты проделала такой путь, только чтобы оказать услугу старушке? Да, похоже, ты чтишь традиции нашего народа. Вот, возьми себе одно из этих учебных пособий – из него ты узнаешь, как ещё можно помочь сообществу." },
    ["753a"] = { male = "В своей жизни я прошла немало дорог, и мои старые ноги уже не так быстры, как раньше. Я ещё могу принести пользу своему племени – просто иногда мне требуется чуть больше времени. Думаю, ты достойный герой. Набери-ка кувшин воды из колодца и отнеси его моему сыну, вождю Лагеря Нараче. Помни, иногда выполнение даже самых скромных просьб может помочь заслужить уважение старейшин.", female = "В своей жизни я прошла немало дорог, и мои старые ноги уже не так быстры, как раньше. Я ещё могу принести пользу своему племени – просто иногда мне требуется чуть больше времени. Думаю, ты достойная героиня. Набери-ка кувшин воды из колодца и отнеси его моему сыну, вождю Лагеря Нараче. Помни, иногда выполнение даже самых скромных просьб может помочь заслужить уважение старейшин." },
    ["753c"] = { male = "Ты принёс мне этот кувшин по просьбе Великой матери Соколиный Ветер. Твоя готовность помочь другим и желание обеспечить тауренов Лагеря Нараче всем необходимым вселяет в меня уверенность, что придёт день, когда мы будем гордиться тобой в Громовом Утёсе.", female = "Ты принесла мне этот кувшин по просьбе Великой матери Соколиный Ветер. Твоя готовность помочь другим и желание обеспечить тауренов Лагеря Нараче всем необходимым вселяет в меня уверенность, что придёт день, когда мы будем гордиться тобой в Громовом Утёсе." },
    ["754a"] = { common = "Я создал тотэм для очищения колодца Заиндевевшего Копыта. Отнеси его туда и произведи ритуал очищения. Колодец находится на юго-востоке, и его охраняют мерзкие гоблины! Дело непростое, но кому-то придётся его сделать, иначе мы не сможем брать там воду. Удачи тебе." },
    ["754c"] = { male = "До меня только что дошли вести о твоём деянии – звери уже спешат к колодцу на водопой. Ты оказал большую услугу нашему краю. И всему народу тауренов.", female = "До меня только что дошли вести о твоём деянии – звери уже спешат к колодцу на водопой. Ты оказала большую услугу нашему краю. И всему народу тауренов." },
    ["755a"] = { male = "Твоя готовность выполнить скромную просьбу таурена из Нараче и твоё желание обрести новые знания весьма похвальны. Не сомневаюсь, придёт день, и тебя, герой, назовут одним из величайших. Но сначала ты должен пройти три обряда Матери-Земли. Первым испытанием будет Обряд Силы. Отправляйся к провидцу Серой Пасти и скажи ему, что тебя прислал вождь Соколиный Ветер. Обиталище провидца сокрыто в холмах к югу от Лагеря Нараче.", female = "Твоя готовность выполнить скромную просьбу таурена из Нараче и твоё желание обрести новые знания весьма похвальны. Не сомневаюсь, придёт день, и тебя, героиня, назовут одной из величайших. Но сначала ты должна пройти три обряда Матери-Земли. Первым испытанием будет Обряд Силы. Отправляйся к провидцу Серой Пасти и скажи ему, что тебя прислал вождь Соколиный Ветер. Обиталище провидца сокрыто в холмах к югу от Лагеря Нараче." },
    ["755c"] = { common = "Тебя прислал вождь Соколиный Ветер? Обряды Матери-Земли гораздо сложнее, чем кажутся на первый взгляд..." },
    ["756a"] = { common = "Для создания Тотэма очищения колодца Громового Рога тебе понадобятся когти хищников мулгорских равнин. Придётся тебе убить несколько охотников прерий и пум плоскогорья и принести мне их когти. Живут эти звери на востоке и на западе." },
    ["756c"] = { common = "Спасибо. Чтобы создать следующий очищающий тотэм, тебе придётся постичь, в чём разница между убийством ради пропитания и бессмысленной жестокостью. Гоблинам же не дано понять разницу между захватом земли и жизнью в гармонии с ней." },
    ["757a"] = { male = "Обряды Матери-Земли проходит каждый юный таурен, чтобы заслужить уважение старейшин Громового Утёса. Сначала ты должен пройти обряд Силы. Чтобы выдержать это испытание, ты должен доказать свою храбрость, убивая врагов племени. Воины клана Вздыбленная Щетина из Ежевичной лощины вторгаются в земли нашего племени. Они нападают на наших охотников и грабят деревню по ночам. Покажи свою доблесть, убив негодяев, и принеси вождю Лагеря Нараче их пояса в качестве доказательства.", female = "Обряды Матери-Земли проходит каждый юный таурен, чтобы заслужить уважение старейшин Громового Утёса. Сначала ты должна пройти обряд Силы. Чтобы выдержать это испытание, ты должна доказать свою храбрость, убивая врагов племени. Воины клана Вздыбленная Щетина из Ежевичной лощины вторгаются в земли нашего племени. Они нападают на наших охотников и грабят деревню по ночам. Покажи свою доблесть, убив негодяев, и принеси вождю Лагеря Нараче их пояса в качестве доказательства." },
    ["757c"] = { male = "Ты прошёл первый из обрядов Матери-Земли. Племя гордится тобой!", female = "Ты прошла первый из обрядов Матери-Земли. Племя гордится тобой!" },
    ["758a"] = { common = "Тотэм готов. Тебе остаётся лишь провести ритуал очищения. Ступай к колодцу Громового Рога на севере от деревни и проведи ритуал с помощью тотэма очищения. После этого возвращайся ко мне. И да пребудут с тобой духи." },
    ["758c"] = { common = "Предки клана Громового Рога явились ко мне во сне и восхваляли тебя за очищение их колодца. Они просили передать тебе это в знак признательности…" },
    ["759a"] = { common = "Тебе осталось очистить лишь один колодец, названный в часть племени Буйногривых. Для этого тебе понадобятся зубы лютого хищника, могучего волка прерий. Ступай на север, убей его и возвращайся. Могучие волки прерий водятся неподалёку от славного города Громового Утёса." },
    ["759c"] = { common = "Замечательно. Увы, нашей земле приходится приносить в жертву своих детей, и я исполняюсь печали и гордости." },
    ["760a"] = { male = "Духи говорят, что ты успешно очистил колодцы Заиндевевшего Копыта и Громового Рога, юный герой. Тотэм Буйногривых готов, и ты можешь приступить к выполнению последнего задания. Колодец Буйногривых расположен на севере от Громового Утёса. Проведи ритуал! Избавь нашу землю от гоблинского яда! Пусть вода вновь станет чистой.", female = "Духи говорят, что ты успешно очистила колодцы Заиндевевшего Копыта и Громового Рога, юная героиня. Тотэм Буйногривых готов, и ты можешь приступить к выполнению последнего задания. Колодец Буйногривых расположен на севере от Громового Утёса. Проведи ритуал! Избавь нашу землю от гоблинского яда! Пусть вода вновь станет чистой." },
    ["760c"] = { male = "Ты справился! Наши колодцы снова чисты, а земля исцелена. Деревня Кровавого Копыта признательна тебе. Пусть ветер шепчет о твоих подвигах сотни лет, а воды Мулгора остаются чистыми навек.", female = "Ты справилась! Наши колодцы снова чисты, а земля исцелена. Деревня Кровавого Копыта признательна тебе. Пусть ветер шепчет о твоих подвигах сотни лет, а воды Мулгора остаются чистыми навек." },
    ["761a"] = { common = "Перепелятники – хитрые птицы. Их нелегко найти и убить. Связка перьев перепелятника – всё равно что медаль для охотника, говорящая о его уме и решимости. Если ты хочешь взяться за это задание, ступай на равнины и убей нескольких перепелятников. Принеси мне их перья, и прославь свой клан этой победой. Перепелятники живут по всему Мулгору, но заметить их могут лишь очень зоркие глаза, а догнать – лишь резвые копыта." },
    ["761c"] = { male = "Я знаю, набрать достаточно перьев было нелегко. Но тем самым ты показал, на что способен. Хорошо, что ты живёшь у нас в деревне.", female = "Я знаю, набрать достаточно перьев было нелегко. Но тем самым ты показала, на что способна. Хорошо, что ты живёшь у нас в деревне." },
    ["762a"] = { common = "Посол Инфернус был отправлен в Крепость Ангор самим Рагнаросом, чтобы надзирать за поисками потерянных артефактов Кузней Теней в Ульдамане. Нам и без того было непросто, а теперь я даже боюсь предположить, сколько артефактов они смогут найти и использовать против Стальгорна! Задача проста! Возвращайся в Бесплодные земли и уничтожь посла Инфернуса. Как только ты выполнишь это задание, возвращайся к советнику Белграму с доказательством своего успеха. Теперь всё в твоих руках!" },
    ["762c"] = { common = "Твоя преданность Стальгорну и народу дворфов не будет забыта. Благодарю тебя за помощь. Я извещу историка Карника о твоих успехах письмом и отправлю рабочих в Бесплодные земли, чтобы они возобновили работы на раскопках как можно скорее. Ещё раз благодарю тебя. Прежде чем ты уйдёшь, выполни ещё одну просьбу от имени короля Бронзоборода." },
    ["763a"] = { male = "Чтобы продолжить прохождение обрядов Матери-Земли, ты должен пройти ещё два испытания. Тебе бы не помешало поднабраться опыта. Отправляйся в Деревню Кровавого Копыта и найди вождя Бейна Кровавого Копыта, сына Кэрна. Там ты сможешь продолжить свои тренировки и завоевать расположение старейшин Громового Утёса. Отнеси этот тотэм Бейну. Он узнает мою руку в этой резьбе и поможет тебе в твоём путешествии. Следуй по дороге из Лагеря Нараче, да поспеши. И не уходи далеко от дороги – заблудишься!", female = "Чтобы продолжить прохождение обрядов Матери-Земли, ты должна пройти ещё два испытания. Тебе бы не помешало поднабраться опыта. Отправляйся в Деревню Кровавого Копыта и найди вождя Бейна Кровавого Копыта, сына Кэрна. Там ты сможешь продолжить свои тренировки и завоевать расположение старейшин Громового Утёса. Отнеси этот тотэм Бейну. Он узнает мою руку в этой резьбе и поможет тебе в твоём путешествии. Следуй по дороге из Лагеря Нараче, да поспеши. И не уходи далеко от дороги – заблудишься!" },
    ["763c"] = { male = "О, весточка от моего старого друга, вождя Соколиного Ветра! Смотри-ка, он пишет мне, что ты герой особой породы!", female = "О, весточка от моего старого друга, вождя Соколиного Ветра! Смотри-ка, он пишет мне, что ты героиня особой породы!" },
    ["764a"] = { common = "Теперь понятно, почему в Мулгоре появилось много сотрудников и оборудования Торговой компании. Эти гоблины... Компания слишком быстро растёт, не жди добра. Как говорят, гоблинам палец в рот не клади. Маленькие жадины. К несчастью для их деловых операций, таурены не согласны терпеть их присутствие в своих землях. Ступай в их рудник на северо-востоке от разграбленного каравана и преподай им урок." },
    ["764c"] = { common = "Думаю, такой намёк невозможно не понять, а? Торговая Компания не будет впредь так легко относиться к тауренам или заносчиво полагать, будто мы без лишних слов позволим похищать наши полезные ископаемые." },
    ["765a"] = { male = "Согласно документам, которые ты отыскал в караване, Торговая компания разработала несколько планов, как изгнать нас из наших земель, чтобы они могли беспрепятственно их разграбить. Мне тошно слышать, на какую низость они готовы пойти ради достижения цели. Я хочу уничтожить того, кто разработал эти планы. Его зовут бригадир Шумовик, он сейчас в руднике Торговой компании на востоке от разграбленного каравана. Принеси мне его планшет, посмотрим, нет ли в нём чего полезного.", female = "Согласно документам, которые ты отыскала в караване, Торговая компания разработала несколько планов, как изгнать нас из наших земель, чтобы они могли беспрепятственно их разграбить. Мне тошно слышать, на какую низость они готовы пойти ради достижения цели. Я хочу уничтожить того, кто разработал эти планы. Его зовут бригадир Шумовик, он сейчас в руднике Торговой компании на востоке от разграбленного каравана. Принеси мне его планшет, посмотрим, нет ли в нём чего полезного." },
    ["765c"] = { common = "Ярость немного отступила при вести о гибели злодея Шумовика. Я пороюсь в его личных вещах, посмотрю, нет ли там дополнительных сведений о ближайших планах Торговой Компании. Спасибо за помощь." },
    ["766a"] = { common = "Дедушка рассказывал мне истории о столкновениях с долгоногом Маззраначем. О его красных, как у демона, глазах, острых, как бритва, когтях и ядовитых укусах. И вот ирония судьбы – он встретился мне во время странствий по равнинам и здорово укусил меня за плечо. Мой дед ничуть не преувеличил, описывая это жуткое создание. Теперь мне нужны редкие части животных, чтобы вылечить воспалённую рану: сердце койота, бедро пумы, чешуя равнинного долгонога и потроха перепелятника. Торопись, время не ждёт." },
    ["766c"] = { common = "А, спасибо. Из этих компонентов я сделаю лекарство, которое остановит распространение инфекции и излечит меня. Я обязан тебе жизнью. Но пронзительный крик Маззранача и блеск его безжалостного клюва мне никогда не забыть… Будь осторожен во время своих странствий." },
    ["767a"] = { common = "Обряд прозрения, один из обрядов Матери-Земли, поможет тебе завоевать уважение старейшин Громового Утёса. Наш народ твёрдо усвоил, что кормящая нас земля – священна. Чтобы принять участие в этом ритуальном прозрении, поговори с духовным вождём деревни, Зарельманом Две Луны." },
    ["767c"] = { male = "Я предчувствовал, что ты придёшь ко мне, герой. Я всегда узнаю тех, кто пытается пройти обряды Матери-Земли.", female = "Я предчувствовал, что ты придёшь ко мне, героиня. Я всегда узнаю тех, кто пытается пройти обряды Матери-Земли." },
    ["768a"] = { male = "Привет тебе, юноша. У тебя так горят глаза, что готов поспорить – тебе не терпится вернуться на равнины и поохотиться. Да принесёшь ты честь своему клану! Я работаю со шкурами животных – шью из них одежду и доспехи для народа Громового Утёса. Если принесёшь мне добытые на охоте шкуры, я что-нибудь и для тебя сошью.", female = "Привет тебе, девица. У тебя так горят глаза, что готов поспорить – тебе не терпится вернуться на равнины и поохотиться. Да принесёшь ты честь своему клану! Я работаю со шкурами животных – шью из них одежду и доспехи для народа Громового Утёса. Если принесёшь мне добытые на охоте шкуры, я что-нибудь и для тебя сошью." },
    ["768c"] = { common = "Ах, какая кожа! Из неё выйдут отличные товары. Вот. Возьми в знак благодарности..." },
    ["769a"] = { common = "Эти кодо из Мулгора – твари крепкие и упрямые, а мы такие качества уважаем. Если ты дока в кожевничестве и хочешь научиться делать сумки из шкуры кодо, то принеси мне необходимые для моего дела припасы. И тогда я поделюсь с тобой своими знаниями." },
    ["769c"] = { common = "Добро. Спасибо. Моё сердце распирает от гордости, когда я вижу молодёжь, взыскующую мастерства в кожевничестве!" },
    ["770a"] = { common = "На потрёпанной шкуре Призрачного Воя по-прежнему виден след от ужасной раны, полученной во время сражений волка с Пылающим Легионом. Может быть, следует рассказать кому-нибудь в Деревне Кровавого Копыта о кончине Призрачного Воя..." },
    ["770c"] = { male = "Глазам своим стариковским не верю! Тебе удалось одолеть Призрачного Воя? Ты вырос в моих глазах, юный герой. Оказывается, ты превосходный охотник! Позволь предложить тебе кое-что. Мне уже не выйти на тропу охоты, но я почту за честь, если ты примешь моё оружие. Пусть оно не знает промаха и дарует тебе славу. Будем надеяться, что дух Призрачного Воя упокоился с миром.", female = "Глазам своим стариковским не верю! Тебе удалось одолеть Призрачного Воя? Ты вырос в моих глазах, юная героиня. Оказывается, ты превосходная охотница! Позволь предложить тебе кое-что. Мне уже не выйти на тропу охоты, но я почту за честь, если ты примешь моё оружие. Пусть оно не знает промаха и дарует тебе славу. Будем надеяться, что дух Призрачного Воя упокоился с миром." },
    ["771a"] = { common = "Чтобы пройти обряд Прозрения, тебе придётся собрать некоторые реагенты для создания воды Провидцев. Мне понадобятся камни, которых полно вокруг источников Мулгора. Я смешаю их с янтарным семенем, что роняют могучие деревья нашей земли. В этих реагентах содержится магия, и если сварить их и выпить отвар перед костром племени, тебе явится видение. Следуй за ним, и оно приведёт тебя к следующему этапу священного обряда." },
    ["771c"] = { male = "Вижу, ты научился собирать дань с нашей священной земли. Мне понадобится совсем немного времени, чтобы приготовить воду Провидцев.", female = "Вижу, ты научилась собирать дань с нашей священной земли. Мне понадобится совсем немного времени, чтобы приготовить воду Провидцев." },
    ["772a"] = { common = "Я вручаю тебе воду Провидцев. Выпей её перед костром племени. Когда священные воды вольются в тебя, из огня навстречу тебе шагнёт видение. После этого следуй за ним навстречу своей судьбе..." },
    ["772c"] = { male = "Не бойся, герой. Ты успешно прошёл Обряд прозрения.", female = "Не бойся, героиня. Ты успешно прошла Обряд прозрения." },
    ["773a"] = { male = "Чтобы завоевать признание старейшин Громового Утёса, тебе следует пройти Обряд мудрости. Ты уже прошёл Обряд прозрения, и духи Красных скал благословят тебя силой предков. Лишь те, кто испили воды Провидцев, могут обрести это благословение. Ступай на восток от Громового Утёса, к Красным скалам, и отыщи там дух предков.", female = "Чтобы завоевать признание старейшин Громового Утёса, тебе следует пройти Обряд мудрости. Ты уже прошла Обряд прозрения, и духи Красных скал благословят тебя силой предков. Лишь те, кто испили воды Провидцев, могут обрести это благословение. Ступай на восток от Громового Утёса, к Красным скалам, и отыщи там дух предков." },
    ["773c"] = { male = "Ты приложил много стараний, чтобы пройти обряды Матери-Земли. Мы, духи предков – память о могучих тауренах, отдавшие жизни за великий город Громовой Утёс. Итак, я передаю тебе почётную обязанность хранить его от бед. Ты прошёл Обряд мудрости, юный герой. Отныне ты можешь с гордостью войти в Громовой Утёс.", female = "Ты приложила много стараний, чтобы пройти обряды Матери-Земли. Мы, духи предков – память о могучих тауренах, отдавшие жизни за великий город Громовой Утёс. Итак, я передаю тебе почётную обязанность хранить его от бед. Ты прошла Обряд мудрости, юная героиня. Отныне ты можешь с гордостью войти в Громовой Утёс." },
    ["775a"] = { male = "Отныне тебя будут почитать в стенах нашего великого города. Прошедший обряды Матери-Земли заслуживает такой чести. Выполни последнее задание, отыщи благородного вождя Кэрна Кровавого Копыта, живущего на вершине высочайшего плато в Громовом Утёсе.", female = "Отныне тебя будут почитать в стенах нашего великого города. Прошедшая обряды Матери-Земли заслуживает такой чести. Выполни последнее задание, отыщи благородного вождя Кэрна Кровавого Копыта, живущего на вершине высочайшего плато в Громовом Утёсе." },
    ["775c"] = { male = "Привет тебе, юный герой. Вижу, тебе удалось отыскать дорогу ко мне.", female = "Привет тебе, юный героиня. Вижу, тебе удалось отыскать дорогу ко мне." },
    ["776a"] = { male = "Ты прошёл обряды Матери-Земли и заслужил достойное место среди жителей Громового Утёса. Чтобы сохранить это таким трудом заработанное место, тебе придётся и дальше служить своему народу. Мы охотники. Внизу, в Мулгоре, есть могучий кодо по имени Арра'чея. Выследи и убей его, проявив своё искусство охотника, и принеси мне рог Арра'чеи.", female = "Ты прошла обряды Матери-Земли и заслужила достойное место среди жителей Громового Утёса. Чтобы сохранить это таким трудом заработанное место, тебе придётся и дальше служить своему народу. Мы охотники. Внизу, в Мулгоре, есть могучий кодо по имени Арра'чея. Выследи и убей его, проявив своё искусство охотника, и принеси мне рог Арра'чеи." },
    ["776c"] = { male = "Отлично! Добрая охота. Я пошлю отряд за тушей кодо, чтобы забрать шкуру и мясо. Ты оказал своему народу услугу.", female = "Отлично! Добрая охота. Я пошлю отряд за тушей кодо, чтобы забрать шкуру и мясо. Ты оказала своему народу услугу." },
    ["777a"] = { common = "Ну, теперь за дело! Я буду здесь...в укрытии. Если хочешь, можешь присоединиться." },
    ["777c"] = { common = "Ага, прекрасно! Отойди-ка в сторонку и наблюдай, как вершится история! *Лотвил вновь погружается в работу.*" },
    ["778a"] = { male = "Ха! Сделано! Люсьен, Серво, время пришло! Ты готов стать свидетелем запуска в эксплуатацию совершенной смеси алхимии, инженерной науки и древних тайн? Сейчас я призову могущественного элементаля. Это величайший день для всех нас!", female = "Ха! Сделано! Люсьен, Серво, время пришло! Ты готова стать свидетельницей запуска в эксплуатацию совершенной смеси алхимии, инженерной науки и древних тайн? Сейчас я призову могущественного элементаля. Это величайший день для всех нас!" },
    ["778c"] = { common = "Спасибо! Ну и денёк! Не думал я, что так получится. Хорошо, что с помощью магии мне удалось загнать тварь туда, откуда она появилась... Вот, это миллионная доля моей благодарности..." },
    ["780a"] = { common = "Боевые вепри из Ежевичной лощины, что к востоку отсюда, вторгаются в охотничьи угодья нашего племени. Их натаскивают свинобразы из племени Дыбогривов, наши заклятые враги. Пойди и покажи гнусным тварям, кто хозяин в этих землях! Мы сварим из их боков и рыл славную похлёбку для наших детишек!" },
    ["780c"] = { common = "Прекрасно! Мы сварим отличную похлёбку, а для проклятых дыбогривов потеря нескольких боевых вепрей послужит уроком." },
    ["781a"] = { common = "Внимательно изучив карту, вы понимаете, что перед вами не что иное, как план нападения клана Дыбогривов на Лагерь Нараче. Вождь Соколиный Ветер непременно должен об этом узнать!" },
    ["781c"] = { male = "Это действительно тревожные вести! Но с этой информацией мы сможем призвать наших братьев из Деревни Кровавого Копыта, чтобы остановить нападение. Ты спас жизни многих тауренов.", female = "Это действительно тревожные вести! Но с этой информацией мы сможем призвать наших братьев из Деревни Кровавого Копыта, чтобы остановить нападение. Ты спасла жизни многих тауренов." },
    ["782a"] = { common = "От союзника Орды времён Второй войны, дракона Смертокрыла мы знаем, что два его лейтенанта, Чернохлыст и Гематус, были заточены в долине Летлор. Чтобы отстоять честь Орды и не допустить предательства, мы должны заставить замолчать наших растленных бывших союзников! Мы наняли Тогруна и его шайку огров-наёмников, чтобы они помогли нам получить знак Земли – ключ, необходимый, чтобы открыть драконье узилище. Но Тогрун предал нас, забрав знак себе. Отправляйся в лагерь Бофф и отбери знак!" },
    ["782c"] = { common = "Теперь, когда от То'груна остался лишь голый скелет, обглоданный стервятниками и выбеленный солнцем и ветром, огры, лишённые главаря, рассеются по пустыне. Так малая победа принесла с собой великую! Знак Земли снова у нас, и мы сможем отомкнуть узилище чёрных драконов в долине Летлор. Мы спасём их от уготованного им вечного заключения, хотя и свершим их судьбу!" },
    ["783a"] = { male = "Надеюсь, ты готов к подвигам, герой, поскольку для тебя есть дело здесь, в Североземье. И я имею в виду не мирные сельские заботы. Стража Штормграда с трудом поддерживает здесь мир: слишком многие из нас находятся в дальних краях, а тревожных вестей меньше не становится. И потому мы надеемся на помощь всех, кто готов защитить свой дом и своих близких. Если ты готов откликнуться на призыв, то поговори с моим командиром, маршалом Макбрайдом. Он здесь, в аббатстве у меня за спиной.", female = "Надеюсь, ты готова к подвигам, героиня, поскольку для тебя есть дело здесь, в Североземье. И я имею в виду не мирные сельские заботы. Стража Штормграда с трудом поддерживает здесь мир: слишком многие из нас находятся в дальних краях, а тревожных вестей меньше не становится. И потому мы надеемся на помощь всех, кто готов защитить свой дом и своих близких. Если ты готова откликнуться на призыв, то поговори с моим командиром, маршалом Макбрайдом. Он здесь, в аббатстве у меня за спиной." },
    ["783c"] = { common = "Отлично. Ещё один доброволец. В эти дни у нас много таких, как ты. Надеюсь, нам хватит бойцов. Землям людей угрожают внешние враги, потому большая часть наших сил направлена к рубежам. И из-за этого бандитские шайки вольготно чувствуют себя в наших землях. Нам приходится воевать на много фронтов... Готовьтся к долгой войне." },
    ["784a"] = { common = "Люди из Кул-Тираса, ведомые адмиралом Праудмуром, вторглись в Дуротар, нарушив договор, который вождь заключил с Джайной Праудмур несколько лет назад, чтобы одолеть Архимонда. Вторжение людей удалось отбить, крепость Тирагард пала. Но не так давно подкрепление под командой лейтенанта Бенедикта вновь захватило эту крепость. Нашей родине снова грозит опасность! Эти люди совершенно не чтут договоров! Покажи свою доблесть. Отправляйся на юг, в крепость Тирагард, и уничтожь непрошеных гостей." },
    ["784c"] = { male = "Твоя отвага скоро станет известна всем, герой! Вести о твоей победе в крепости Тирагард, наверное, уже достигли Оргриммара.", female = "Твоя отвага скоро станет известна всем, героиня! Вести о твоей победе в крепости Тирагард, наверное, уже достигли Оргриммара." },
    ["785a"] = { common = "Тралл – весьма мудрый и благородный лидер. Его навыки дипломата могут сравниться лишь с его отвагой на поле брани. Тролли из племени Чёрного Копья оказались бесценными союзниками для всего орочьего рода. И мы, из верности и чести, заключили с ними договор о взаимной обороне. И вот вождь приказал удостовериться, что нашим друзьям в деревне Сен'джин ничто не угрожает. Один из их самых опытных разведчиков, Лар Ночной Клык, охраняет их западные пределы. Разыщи Лара и спроси, не нужна ли ему помощь." },
    ["786a"] = { male = "Говори потише, герой! Кентавры из племени Колкар совсем близко, вон там, к западу от Утёса Колкара. Прошлой ночью, когда они отправились в набег, мне удалось пробраться в их лагерь, и там я обнаружил, что эти грязные твари замышляют нанести тройной удар по позициям троллей и орков Дуротара! Нельзя допустить, чтобы они это сделали! Достаточно ли ты храбр, чтобы напасть на Утёс Колкара и уничтожить их планы? Я заметил, что они хранятся у трёх лидеров кентавров.", female = "Говори потише, героиня! Кентавры из племени Колкар совсем близко, вон там, к западу от Утёса Колкара. Прошлой ночью, когда они отправились в набег, мне удалось пробраться в их лагерь, и там я обнаружил, что эти грязные твари замышляют нанести тройной удар по позициям троллей и орков Дуротара! Нельзя допустить, чтобы они это сделали! Достаточно ли ты храбра, чтобы напасть на Утёс Колкара и уничтожить их планы? Я заметил, что они хранятся у трёх лидеров кентавров." },
    ["786c"] = { male = "Конечно, если кентавры осмелятся напасть на нас, Орда сумеет их одолеть. Но, предотвратив нападение, мы избавили наших могучих воинов от возможных потерь. А кровопролитий в эти смутные времена и без того хватает. Ты хорошо послужил своему народу, герой.", female = "Конечно, если кентавры осмелятся напасть на нас, Орда сумеет их одолеть. Но, предотвратив нападение, мы избавили наших могучих воинов от возможных потерь. А кровопролитий в эти смутные времена и без того хватает. Ты хорошо послужила своему народу, героиня." },
    ["787a"] = { male = "Тром'ка, герой! Меня зовут Эйтригг. Тралл поручил мне следить за обучением рекрутов. Орда уже не такая, как раньше. Некогда я оставил её: мне не нравилось растущее влияние прихвостней Пылающего Легиона, которые рвались к власти. Во время изгнания я попал в плен к людям, но вождь меня спас. Он поделился со мной своей мечтой о Новой Орде, свободной от влияния демонов. Я выслушал его – и вернулся. Горнек скажет тебе, что делать дальше.", female = "Тром'ка, героиня! Меня зовут Эйтригг. Тралл поручил мне следить за обучением рекрутов. Орда уже не такая, как раньше. Некогда я оставил её: мне не нравилось растущее влияние прихвостней Пылающего Легиона, которые рвались к власти. Во время изгнания я попал в плен к людям, но вождь меня спас. Он поделился со мной своей мечтой о Новой Орде, свободной от влияния демонов. Я выслушал его – и вернулся. Горнек скажет тебе, что делать дальше." },
    ["787c"] = { common = "Ещё один из новобранцев Эйтригга, хм? В каком плачевном положении мы оказались, если это лучшее, что может произвести Орда. Неважно. К тому времени, когда мы решим, что вы готовы покинуть Долину, вы будете гордиться собой." },
    ["788a"] = { male = "Вот тебе первое поручение, чтобы ты набрался опыта и показал себя. Конечно, можно было бы отправить тебя в Степи охотиться на кодо, но нам лишние покойники ни к чему. Пожалуй, тебе стоит начать с пятнистых вепрей, которые обитают к северу отсюда.", female = "Вот тебе первое поручение, чтобы ты набралась опыта и показала себя. Конечно, можно было бы отправить тебя в Степи охотиться на кодо, но нам лишние покойники ни к чему. Пожалуй, тебе стоит начать с пятнистых вепрей, которые обитают к северу отсюда." },
    ["788c"] = { male = "Ну что ж, неплохо. Но не задирай носа: грядут бои с куда более серьёзными врагами. Однако ты показал себя достойным бойцом. В следующем испытании тебе придётся встретиться с более опасным противником, так что дополнительная защита не помешает.", female = "Ну что ж, неплохо. Но не задирай носа: грядут бои с куда более серьёзными врагами. Однако ты показала себя достойным бойцом. В следующем испытании тебе придётся встретиться с более опасным противником, так что дополнительная защита не помешает." },
    ["789a"] = { common = "Ядовитое жало скорпиона губит всех – и могучих воинов, и неопытных новичков. К северо-западу отсюда водится множество этих членистоногих. Принеси мне десять их хвостов, чтобы доказать свою воинскую доблесть. Из яда жал скорпионов можно изготовить противоядие. Мы всегда держим его под рукой, специально для неосторожных юнцов вроде тебя... Но тебе-то оно не понадобится, а?" },
    ["789c"] = { male = "Запомни раз и навсегда: любой противник, будь он мал или велик, может оказаться для тебя последним! В бою победа или поражение зависят от многого. Ну что ж! Я научил тебя всему, чему мог. Ты оказался хорошим учеником. Я буду с интересом следить за твоей карьерой.", female = "Запомни раз и навсегда: любой противник, будь он мал или велик, может оказаться для тебя последним! В бою победа или поражение зависят от многого. Ну что ж! Я научил тебя всему, чему мог. Ты оказалась хорошим учеником. Я буду с интересом следить за твоей карьерой." },
    ["790a"] = { male = "герой! А я уж думаю, помру тут, никто и не узнает... Я охотился в долине на скорпидов, и попался мне один, особенно злобный. Я бросился на него и сумел разрубить ему клешню, когда та собиралась укоротить мне ногу. А вот жало застигло меня врасплох. Оно вонзилось мне в грудь, хлынула кровь... Прошу тебя, смой с меня позор! Убей этого скорпида! Я сражался с ним на плато, к югу отсюда...", female = "героиня! А я уж думаю, помру тут, никто и не узнает... Я охотился в долине на скорпидов, и попался мне один, особенно злобный. Я бросился на него и сумел разрубить ему клешню, когда та собиралась укоротить мне ногу. А вот жало застигло меня врасплох. Оно вонзилось мне в грудь, хлынула кровь... Прошу тебя, смой с меня позор! Убей этого скорпида! Я сражался с ним на плато, к югу отсюда..." },
    ["790c"] = { common = "Да, убить его мне не удалось, но ранил я его серьёзно. Пожалуй, мне есть чем гордиться. И это единственное, что утешает меня перед смертью. Как подумаю, как мало я сделал в жизни, такая злость берёт!" },
    ["791a"] = { common = "Старость сделала меня бесполезным в бою. Теперь я служу Орде иным путём. Я сижу здесь, на вышине, и смотрю, не появятся ли враги. Но по мере того, как наши силы растут, мне всё реже и реже приходится трубить в сигнальный рог. А чтобы проводить время с пользой, я изготовляю разные вещи для молодых сильных воинов, которые защищают теперь нашу родину. Я могу сделать тебе сумку для пожитков. Если такая вещь будет для тебя полезна, принеси мне отрез холста – эта ткань в ходу у людей и кентавров." },
    ["791c"] = { common = "Отлично! Такая сумка пригодится любому хорошему бойцу. Я отдаю честь твоей силе и решимости умереть во имя Орды!" },
    ["792a"] = { male = "Что ж, герой, надеюсь, у нас ты многому научишься. Меня послали сюда, чтобы я стала твоей наставницей, но оказывается, здесь не всё ладно! В долине Испытаний обосновался клан Пылающего Клинка. Эти твари скрываются в пещере на северо-востоке, и их злобные фамильяры выбираются оттуда и сеют хаос. Итак, вот твоё первое задание в борьбе с Пылающим Клинком: перебей их столько, сколько сумеешь, и, если выживешь, возвращайся ко мне.", female = "Что ж, героиня, надеюсь, у нас ты многому научишься. Меня послали сюда, чтобы я стала твоей наставницей, но оказывается, здесь не всё ладно! В долине Испытаний обосновался клан Пылающего Клинка. Эти твари скрываются в пещере на северо-востоке, и их злобные фамильяры выбираются оттуда и сеют хаос. Итак, вот твоё первое задание в борьбе с Пылающим Клинком: перебей их столько, сколько сумеешь, и, если выживешь, возвращайся ко мне." },
    ["792c"] = { common = "Спасибо тебе! Да, злобные фамильяры для воинов клана Пылающего Клинка – всего лишь ручные зверушки, однако же твой успех предсказывает тебе великие дела!" },
    ["793a"] = { male = "Печать Земли удерживают три рунных камня, сокрытые в долине Летлор. Один спрятан в алмазном столпе, другой – в опаловом, третий – в аметистовом. С помощью знака Земли ты сможешь извлечь рунные камни и разрушить печать Земли. Но будь осторожен, Чернохлыст и Гематус очень опасны. Ты должен убить их и принести мне их наручники. Долина расположена к востоку от Бесплодных земель. Не теряй бдительности – в низине множество драконов!", female = "Печать Земли удерживают три рунных камня, сокрытые в долине Летлор. Один спрятан в алмазном столпе, другой – в опаловом, третий – в аметистовом. С помощью знака Земли ты сможешь извлечь рунные камни и разрушить печать Земли. Но будь осторожна, Чернохлыст и Гематус очень опасны. Ты должна убить их и принести мне их наручники. Долина расположена к востоку от Бесплодных земель. Не теряй бдительности – в низине множество драконов!" },
    ["793c"] = { common = "Чёрные драконы вступают в союз с отступниками – орками Чёрной Горы. И тех, и других должно вернуть в лоно Орды или уничтожить. Теперь, когда мы покончили с Гематусом и Чернохлыстом, мы можем обратить взор на запад, на пик Чёрной Горы." },
    ["794a"] = { common = "С помощью ворожбы я узнала, что в глубине грота Пылающего Клинка находится мощный магический предмет. Его стерегут звери и чёрная магия. Этот предмет – медальон Пылающего Клинка. Твоя очередная задача – найти его и отнять у ковена. Но берегись: медальон может оказаться в руках одного из членов ковена, и этот чернокнижник будет куда могущественнее, чем фамильяры, с которыми тебе уже доводилось встречаться! Ступай. Грот находится к северо-западу отсюда." },
    ["794c"] = { common = "Он у тебя! Молодец! Теперь у нас есть возможность вытеснить приспешников Пылающего Клинка из Долины Испытаний. Но, боюсь, этот грот – не единственный их оплот в наших землях. Так что эта встреча с ними была не последней." },
    ["804a"] = { male = "То, что ты сделал ради меня, заставило меня воспрянуть духом. Я ещё повоюю! Но пока что мне не добраться до Логова без посторонней помощи. Прошу тебя, сходи в Логово, расскажи Горнеку, что я здесь. Может, он сумеет мне помочь.", female = "То, что ты сделала ради меня, заставило меня воспрянуть духом. Я ещё повоюю! Но пока что мне не добраться до Логова без посторонней помощи. Прошу тебя, сходи в Логово, расскажи Горнеку, что я здесь. Может, он сумеет мне помочь." },
    ["804c"] = { common = "Судя по твоему описанию, этим скорпионом был не кто иной, как Саркот! Неудивительно, что Хана'зуа с ним не справился. Не тревожься о нём, помощь уже в пути. Однако, нужно сказать, я тебя зауважал. Неужели тебе действительно удалось одолеть Саркота? Это немалый подвиг, тебе есть чем гордиться. А твоя готовность сражаться по просьбе незнакомца тем более делает тебе честь." },
    ["805a"] = { common = "Твои испытания в борьбе с Пылающим Клинком подошли к концу... по крайней мере тут, в нашей Долине. Но я прошу тебя отнести известие о том, что ты теперь знаешь. Ступай в тролльскую деревню Сен'джин, отыщи там мастера Гадрина. Отправляйся на восток, на развилке поверни направо. Расскажи Гадрину о чернокнижниках из клана Пылающего Клинка и о том, что они уже проникли в долину Испытаний. Узнай, не видно ли их в Сен'джине. Ступай, и не медли в пути! Боюсь, появление Пылающего Клинка в долине – это только первая ласточка..." },
    ["805c"] = { common = "Хм... Как это всё не вовремя! Нет, у нас в Сен'джине Пылающего Клинка пока не видно, однако на побережье, на островах Эхо, обосновалось иное зло. Орки – друзья племени Чёрного Копья. Верные друзья. Мы хотели бы помочь оркам, но... сейчас нам самим нужна помощь!" },
    ["806a"] = { common = "Нельзя допустить, чтобы Пылающий Клинок закрепился в Дуротаре! Нужно уничтожить этих чернокнижников, прежде чем распространяемое ими зло расползётся по нашей земле! Я провёл расследование и выяснил, что один из чернокнижников из клана Пылающего Клинка, гоблин по имени Пшикс Черношквал, обосновался на Громовом хребте к северо-западу отсюда. Там он и его приспешники сеют хаос! Найди Пшикса, убей его и принеси мне его коготь в качестве доказательства." },
    ["806c"] = { male = "Ага! Ты его убил! Твой клан может гордиться тобой. Благодаря тебе в Дуротаре стало одним приспешником зла меньше.", female = "Ага! Ты его убила! Твой клан может гордиться тобой. Благодаря тебе в Дуротаре стало одним приспешником зла меньше." },
    ["808a"] = { common = "Я слышу голос моего брата, Миншины. Он взывает ко мне из снов. Его захватил в плен Залазан, чернокнижник с островов Эха на востоке. И теперь Миншина мёртв. Но смерть не принесла ему свободы! Залазан заточил дух Миншины внутри его собственного черепа. В снах я вижу его рядом с другими черепами, в магическом кругу на самом большом из островов Эха. Пока его душа находится в этом месте, она обречена на вечные страдания. Прошу тебя, отыщи этот круг и похить череп Миншины. Принеси его мне. Освободи его!" },
    ["808c"] = { common = "Спасибо! Тебе удалось спасти Миншину! Дух моего брата избавлен от рабства!" },
    ["809a"] = { common = "Со времён последней великой войны, когда Пылающий Легион потерпел поражение, я ищу источники демонической порчи, что воздействует на общество орков. И принесённый тобой ошейник подтверждает мои опасения! Он принадлежит Пылающему Клинку, культу, объединённому вокруг предмета, который наделён демонической силой. Этот предмет называется Демоново Семя, и находится он в Степях, на вершине Багрового Тумана. Его необходимо уничтожить! Отправляйся на Дальнюю заставу на границе Степей, к западу, и поговори с моим помощником, Ак'Зелотом. Он скажет тебе, что делать дальше." },
    ["809c"] = { common = "Вот как? Нииру хочет, чтобы Демоново семя было уничтожено? Странно… Что ж, хорошо. Если такова его воля, я расскажу тебе, как уничтожить семя." },
    ["812a"] = { common = "А... Ты как нельзя вовремя! Надеюсь на твоё проворство. Я сражался с несколькими ядохвостами, и один из них смог меня ужалить. Я чувствую, как слабею с каждой секундой... Боюсь, мне осталось не больше часа. Мне срочно нужна твоя помощь! Коргхан из Оргриммара умеет изготовлять противоядие. Найди его... Быстрее! Долго мне не протянуть. Ищи его в расселине Теней." },
    ["812c"] = { common = "Ты спас мне жизнь! Спасибо тебе. Прошу тебя, возьми эту вещь. Денег за неё не выручишь, но, надеюсь, она пригодится тебе в странствиях. Судя по тому, что ты говоришь, мне она пригодится нескоро. Кор'гхан подвергнет меня ещё множеству своих ритуалов, пока я не сумею показать, на что способен. Снова охотиться на вепрей, собирать хвосты скорпидов... вздыхает" },
    ["813a"] = { common = "Ядохвосты – одни из опаснейших скорпидов в Дуротаре! Со стороны Ринага было очень глупо охотиться на них, не имея при себе противоядия. Впрочем, сейчас его вразумлять уже поздно. Принеси мне несколько ядовитых желёз ядохвоста от любых ядохвостов, каких найдёшь у входа в Оргриммар, и я сделаю ему противоядие. Торопись! Одному из наших нужна твоя помощь!" },
    ["813c"] = { common = "Вот противоядие. Отнеси его поскорее Ринагу, да смотри, осторожнее!" },
    ["815a"] = { common = "Ба! А я и позабыл, что надо готовить завтрак. Слушай, сбегай-ка, раздобудь мне по-быстрому несколько яиц кнутохвостов, как минимум три штуки. Имей в виду, кровопалые кнутохвосты – твари свирепые и вполне могут убить, защищая свою кладку. Иногда они зарывают яйца слишком глубоко, чтобы их можно было беспрепятственно раздобыть, но если ты отправишься на острова Эха, к юго-востоку от деревни Сен'джин, там эти яйца лежат повсюду." },
    ["815c"] = { common = "Ну, может, ты и слабак но уж ловкости и проворства тебе не занимать! На вот, возьми за труды и проваливай. Мне готовить надо!" },
    ["816a"] = { common = "Прошу тебя, может, хоть ты сумеешь мне помочь? Мой сын, Крон, несколько дней тому назад отправился на охоту и до сих пор не вернулся! Он ушёл на запад, в Степи, охотиться на кроколисков у реки Строптивой. Я опасаюсь худшего… Крон могуч, но гордость и упрямство всегда доводили его до беды. Я попросила его не охотиться на кроколисков, потому что они злобны и коварны! А он рассвирепел и хлопнул дверью. Если не сумеешь отыскать его – узнай хотя бы, что с ним случилось... даже если тебе придётся заглянуть в брюхо каждому кроколиску на берегах Строптивой!" },
    ["816c"] = { common = "Ох, сыночек... милый мой сыночек… Что ж, я не знала судьбы своего сына и потому терзалась понапрасну. Теперь же я хоть смогу его оплакать… Спасибо тебе. Прошу тебя, возьми этот плащ. Я-то собиралась подарить его Крону, когда он вернётся с добычей... А теперь, зная, что он погиб, я даже не смогу смотреть на него." },
    ["817a"] = { common = "У нас в большом ходу шкуры дуротарского тигра. Чего только из них не делают! И одеяла, и доспехи, и шатры. Вот почему мы охотимся на этих животных, но не истребляем их. В общем, пришла пора в очередной раз сократить поголовье. Наши потребности растут, и запасов не хватает. Мне нужны новые шкуры. Принеси мне четыре шкуры дуротарских тигров, и получишь награду. Эти кошки водятся на островах к югу отсюда." },
    ["817c"] = { common = "Молодец! Благодаря твоей помощи наш народ не останется без доспехов и не будет страдать от холода, когда наступит зима. Спасибо тебе." },
    ["818a"] = { male = "Да, глаза меня порой подводят, но всё же пока я вижу достаточно отчётливо. И всё чаще приходится прибегать к помощи алхимии, чтобы творить заклинания, которые прежде давались мне без труда. И я не беру учеников. Нет нынче достойных ни среди троллей, ни среди орков. Что? Ты достоин? Ну да, конечно... Это ты так думаешь. Мне нужны кое-какие компоненты. Сумеешь ли ты их добыть? Мне нужны невредимые глаза макрур и слизь крабов, которые водятся к югу отсюда. Вот принеси мне их, потом поговорим.", female = "Да, глаза меня порой подводят, но всё же пока я вижу достаточно отчётливо. И всё чаще приходится прибегать к помощи алхимии, чтобы творить заклинания, которые прежде давались мне без труда. И я не беру учеников. Нет нынче достойных ни среди троллей, ни среди орков. Что? Ты достойна? Ну да, конечно... Это ты так думаешь. Мне нужны кое-какие компоненты. Сумеешь ли ты их добыть? Мне нужны невредимые глаза макрур и слизь крабов, которые водятся к югу отсюда. Вот принеси мне их, потом поговорим." },
    ["818c"] = { common = "Отличная работа! Ты молодец!" },
    ["819a"] = { common = "Маленькая табличка на торце одной из бочек гласит: \"Чэнь Буйный Портер – Да будет ваш дух горяч, а кружка – полной.\"" },
    ["819c"] = { male = "Ну, я… Это был один из бочонков Чэня Буйного Портера. Давным-давно он путешествовал вместе с Рексаром. Я не видел его и не слышал о нём с незапамятных времён. Спасибо, что ты принёс мне этот бочонок.", female = "Ну, я… Это был один из бочонков Чэня Буйного Портера. Давным-давно он путешествовал вместе с Рексаром. Я не видел его и не слышал о нём с незапамятных времён. Спасибо, что ты принесла мне этот бочонок." },
    ["821a"] = { common = "Хочешь попробовать напиток, придуманный Чэнем? Ах, до чего же хорош! Чэнь передал рецепт моему наставнику, ну а он – мне. Только для него понадобится несколько компонентов. Но он того стоит! Принеси мне пять клыков равнинного льва, пять почек долгонога и один рог рокочущей ящерицы. Из них выйдет прекрасный портер. Все эти составляющие нетрудно отыскать в Степях." },
    ["821c"] = { common = "Ха-ха... Вот уж не думал, что снова сварю этот напиток! Прямо ностальгия охватила. Сразу вспомнилось, как я наварил троггского пойла. Спасибо. От воспоминаний даже на душе посветлело." },
    ["822a"] = { common = "Отличный напиток, а? Я научился у Чэня ещё одному рецепту. Хочешь узнать? Много времени он не отнимает, а в жизни пригодится. Принеси мне пять грозовых желёз любых грозошкуров, один слюнную железу грозового змея от больших грозовых змеев и печень кодо от любого из кодо Степей. Вставляет – не то слово. Это эль трогга, о котором я уже говорил." },
    ["822c"] = { common = "Ха-ха! Я знал, что ты не откажешься от этого напитка. Приходи, я ещё тебе сварю. Главное – приноси всё необходимое." },
    ["823a"] = { male = "У нас, в деревне Сен'джин, конечно, есть свои проблемы, и твоя помощь нам бы не помешала. Так что спасибо тебе. Однако принесённые тобой вести об Пылающем Клинке сулят неприятности всем. В Колючем Холме есть один орк, Оргнил Душегрыз, в обязанности которого входит охранять Дуротар от таких напастей, как Пылающий Клинок. Ступай к Оргнилу и расскажи ему о нашем положении и о том, что ты узнал в долине Испытаний. Ему нужно это знать. Колючий Холм находится к северу отсюда.", female = "У нас, в деревне Сен'джин, конечно, есть свои проблемы, и твоя помощь нам бы не помешала. Так что спасибо тебе. Однако принесённые тобой вести об Пылающем Клинке сулят неприятности всем. В Колючем Холме есть один орк, Оргнил Душегрыз, в обязанности которого входит охранять Дуротар от таких напастей, как Пылающий Клинок. Ступай к Оргнилу и расскажи ему о нашем положении и о том, что ты узнала в долине Испытаний. Ему нужно это знать. Колючий Холм находится к северу отсюда." },
    ["823c"] = { common = "Да? Тебе есть, о чём доложить? Ну так рассказывай, чего ты ждёшь?!" },
    ["824a"] = { common = "Служители Земли – сообщество шаманов, посвятивших себя изучению и охране Стихий. Они забыли о безумных древних богах, древних легендах и преданиях больше, чем большинство учёных вообще знало. Повезло тебе, что я знаю кое-кого из Служителей Земли тут, в Ясеневом лесу. Иди в форт Зорам'гар на Зорамское взморье и покажи Дже'неу Санкри свою находку. Если кто и поймёт, что это за шар, так это он." },
    ["824c"] = { common = "Этот шар... волнует он меня. Многие из наиболее могучих элементалей черпают силу и энергию при помощи таких устройств. Найти такую штуку неповреждённой – одно дело, а вот настолько осквернённой – совсем другое. Я прослежу, чтобы этот шар как следует изучили Служители Земли. Возможно, мы сумеем положить конец такому осквернению Стихий. Прошу – прими это в награду за то, что принёс нам этот шар для изучения." },
    ["825a"] = { common = "Один из моих лучших разведчиков принёс сообщение, что обломки кораблей Праудмура всё ещё плавают около побережья Дуротара, к востоку от крепости Тирагард. Ни для кого не секрет, что люди, будучи в союзе с этими маленькими уродцами, гномами, неплохо овладели механикой. Нам нужно знать всё о нашем предполагаемом противнике! К тому же, эти знания пригодятся и нашему народу. Сплавай к обломкам, и добудь мне инструменты Альянса." },
    ["825c"] = { male = "Ты успешно выполнил поручение, герой. Я позабочусь о том, чтобы эти инструменты отправились в Оргриммар с ближайшим караваном. Молодец!", female = "Ты успешно выполнила поручение, героиня. Я позабочусь о том, чтобы эти инструменты отправились в Оргриммар с ближайшим караваном. Молодец!" },
    ["826a"] = { common = "Знахарь Залазан живёт на островах Эха на востоке. Эти острова мы когда-то называли родиной… А теперь он оттуда посылает троллей на материк, досаждая нашему народу и переманивая на свою сторону всё новых приспешников. Его нужно остановить! Уничтожь Залазана и его слуг – бывших троллей из племени Чёрного Копья, ныне потерянных для нас! Принеси мне его голову – и я буду знать, что владычеству зла пришёл конец." },
    ["826c"] = { common = "Залазана больше нет, наше племя снова может спать спокойно! Спасибо. Племя Чёрного Копья многим тебе обязано. Если тебя мучает какой-нибудь недуг, обратись к моему помощнику, Бом'бею, который находится позади меня. Он силён в магии вуду…" },
    ["827a"] = { common = "Пылающий Клинок захватил пещеру к востоку от Оргриммара, известную как скала Черепа. Сектанты совершают там свои гнусные обряды и сжигают собственную плоть обжигающими ошейниками. Я подозреваю, что, нося эти ошейники, фанатики вступают в резонанс с демоническими силами. Но чтобы в этом убедиться, мне необходимо изучить несколько таких ошейников. Ступай к скале Черепа и отбери у фанатиков, которых там найдёшь, их ошейники. Принеси их мне, и я раскрою их тайну!" },
    ["827c"] = { common = "Отлично! В этих ошейниках и таится секрет Пылающего Клинка. И я его раскрою!" },
    ["828a"] = { common = "Один из наших шаманов, Маргоз, многое знает о клане Пылающего Клинка. Как-то он рассказывал о пещере, которая называется скала Черепа, в горах у самого Оргриммара. Там окопалась большая шайка сектантов из клана Пылающего Клинка. Прежде чем отправиться к скале Черепа, поговори с Маргозом. Он мудр, и к его советам стоит прислушиваться. Ты найдёшь его на северо-востоке, между побережьем и Сухой лощиной. Следуй его советам, но, что бы он ни сказал, я прошу тебя – уничтожь этих сектантов!" },
    ["828c"] = { male = "Здравствуй. До меня дошли слухи о твоём появлении и о твоих подвигах в Дуротаре. Ты – многообещающий герой. Не сворачивай с этого пути, и великое будущее будет ждать тебя!", female = "Здравствуй. До меня дошли слухи о твоём появлении и о твоих подвигах в Дуротаре. Ты – многообещающая героиня. Не сворачивай с этого пути, и великое будущее будет ждать тебя!" },
    ["829a"] = { common = "Принесённые тобой обжигающие ошейники – это мощные инструменты демонов. И распознать их происхождение мне, как шаману, не под силу. Нужно, чтобы на них взглянул чернокнижник. Отнеси один обжигающий ошейник Нииру Огненному Клинку. Он искусный чернокнижник, но утверждает, что использует свою силу лишь затем, чтобы вредить демонам, а ещё говорит, что его оккультные исследования идут на пользу Орде. Правда это или нет, а его помощь нам ещё может понадобиться в борьбе с последователями демонов в Дуротаре. Нииру можно найти в Оргриммаре, в Расселине Теней." },
    ["829c"] = { common = "О! Откуда у тебя это? Тебя прислал ко мне славный Маргоз из Колючего Холма, верно? Ну-ка, дай взглянуть..." },
    ["830a"] = { common = "Вы открываете потрёпанный и выгоревший конверт и обнаруживаете документ официального вида. На нём – печать адмирала Праудмура. Похоже, это что-то важное. Может быть, Га'току, командиру Колючего Холма, эта информация пригодится..." },
    ["830c"] = { common = "Ничего хорошего это не предвещает... Очень хорошо, что ты принёс это мне." },
    ["831a"] = { common = "Людям верить нельзя. Мы сражались плечом к плечу с ними, но в глубине души знали, что рано или поздно они нас предадут. Адмирал Праудмур был убит, но этого оказалось недостаточно, чтобы остановить предательство. Этот подлый человечишка успел изложить свои планы на бумаге, прежде чем встретил заслуженную смерть. Его наследие не пропадёт даже со смертью Бенедикта. Кто знает, когда следующая волна людей Праудмура обрушится на наши берега? Эти приказы нужно немедленно доставить в Оргриммар, Назгрелу! Ты найдёшь его в зале приёмов Тралла." },
    ["831c"] = { male = "О, сколько раз я умолял вождя не доверять людям! Однако тут речь не о личной гордости. Ты достойно послужил Орде, герой. А теперь извини, мне нужно немедленно поговорить об этом с Траллом!", female = "О, сколько раз я умолял вождя не доверять людям! Однако тут речь не о личной гордости. Ты достойно послужила Орде, героиня. А теперь извини, мне нужно немедленно поговорить об этом с Траллом!" },
    ["832a"] = { male = "Слова из амулета плавно перетекают в ваш разум. Газз'уз! Газз'уз, докладывай! О том, что ты нашёл в Скале Черепа, уже стало известно. Готовься к нападению! Говори, Газз'уз! Говори, или я позабочусь о том, чтобы о твоём присутствии стало известно Нииру Огненному Клинку, а уж он-то тебя не пощадит! С Нииру тебе лучше не связываться... Газз'уз, ты меня слышишь?", female = "Слова из амулета плавно перетекают в ваш разум. Газз'уз! Газз'уз, докладывай! О том, что ты нашла в Скале Черепа, уже стало известно. Готовься к нападению! Говори, Газз'уз! Говори, или я позабочусь о том, чтобы о твоём присутствии стало известно Нииру Огненному Клинку, а уж он-то тебя не пощадит! С Нииру тебе лучше не связываться... Газз'уз, ты меня слышишь?" },
    ["832c"] = { male = "Нииру разглядывает Око Пылающей Тени. Любопытно. Так ты говоришь, голос упоминал моё имя? Я, конечно, известен как непримиримый враг противников нашего вождя, но всё же странно, что голос назвал именно меня. Тем более странно, что название секты, у членов которой ты нашёл этот амулет, так похоже на мою фамилию. Надо изучить эту подвеску. Изучить и поразмыслить над тем, что значит это сообщение. Спасибо, что сообщил мне об этом. Ты оказал своему народу серьёзную услугу.", female = "Нииру разглядывает Око Пылающей Тени. Любопытно. Так ты говоришь, голос упоминал моё имя? Я, конечно, известен как непримиримый враг противников нашего вождя, но всё же странно, что голос назвал именно меня. Тем более странно, что название секты, у членов которой ты нашла этот амулет, так похоже на мою фамилию. Надо изучить эту подвеску. Изучить и поразмыслить над тем, что значит это сообщение. Спасибо, что сообщила мне об этом. Ты оказала своему народу серьёзную услугу." },
    ["833a"] = { male = "Лишь самых доблестных тауренов хоронят в Красных скалах, на нашем священном кладбище. Эта честь выпадает лишь величайшим воинам, основавшим и защищавшим Громовой Утёс, и тем, кто отдал свои жизни на благо племени и вождей. Похоже, теперь на эту священную землю пала тень. Могилы оскверняет отряд злоумышленников из племени Дыбогривов, а я слишком стар, чтобы отогнать их. Против них поможет только сила, герой.", female = "Лишь самых доблестных тауренов хоронят в Красных скалах, на нашем священном кладбище. Эта честь выпадает лишь величайшим воинам, основавшим и защищавшим Громовой Утёс, и тем, кто отдал свои жизни на благо племени и вождей. Похоже, теперь на эту священную землю пала тень. Могилы оскверняет отряд злоумышленников из племени Дыбогривов, а я слишком стар, чтобы отогнать их. Против них поможет только сила, героиня." },
    ["833c"] = { male = "Молодец. Ты проучил племя Дыбогривов. Теперь они дважды подумают, прежде чем осквернять святые для нас места.", female = "Молодец. Ты проучила племя Дыбогривов. Теперь они дважды подумают, прежде чем осквернять святые для нас места." },
    ["834a"] = { common = "Я – Резлак, один из ребят Газлоу. Шеф послал меня на помощь оркам в Дуротаре. Всё бы хорошо, если бы не проблемы с караванами. Точнее, с охраной караванов. Как ты думаешь, можно ли работать, когда караваны всё время грабят? Последний караван – они мне клялись, что он-то уж точно дойдёт! – перехватили гарпии Пыльного Ветра в... как же его... Каньоне Колючего Ветра! А мне этот груз позарез нужен, я без него как без рук! Ступай по большому каньону на юг, там будет расселина, идущая с запада на восток..." },
    ["834c"] = { common = "О, то что надо! Наши припасы! Замечательно. Я смогу снова взяться за работу, как только найду кого-нибудь, кто донесёт мне эти мешки." },
    ["835a"] = { common = "Газлоу мне как-то сказал: \"Резлак, запомни одну вещь: если хочешь, чтобы что-то было сделано хорошо, сделай это сам\". Мы не можем и дальше терять караваны. Я вынужден взять дело в собственные руки. Сухая лощина находится в восточной части Каньона Колючего Ветра. Если перебить всех тамошних гарпий, дороги станут безопасными. Разумеется, Газлоу учил меня и другому: \"За соответствующую плату тебе сделают что угодно\". Ну что, возьмёшься?" },
    ["835c"] = { common = "Ну всё, теперь нашим караванам больше ничто не угрожает! Наконец-то я вздохну свободно. Твоя помощь пришлась как нельзя вовремя: со следующим караваном мне должны прислать партию занятных безделушек! Ты, своё дело знаешь. Обратись к моему шефу в Кабестане. У него наверняка найдётся для тебя работёнка. Ах да, не беспокойся, разумеется, я тебе заплачу за труды!" },
    ["836a"] = { common = "Из робота снова раздаётся голос гнома: \"Нужно вывести OOX-девять/HL на открытое и безопасное место, чтобы он мог взять нужный разбег и взлететь. У него есть система маскировки, но она, похоже, повреждена, поэтому вам придётся проводить цыплёнка до... ну, скажем, до побережья за Обзорными скалами! Местность там тихая и открытая, так что разбежаться он сумеет\". \"Пожалуйста, проводите робота на берег, а потом загляните ко мне в Пиратскую бухту. Карлс Пропеллерз, конец связи\"." },
    ["836c"] = { male = "О, да ты просто спас моего робота КПХ-девять/HL! Я прям даже не знаю, как тебя благодарить! Моих автономных роботов ещё совершенствовать и совершенствовать, но ты избавил меня от многих лишних часов работы, а также от расходов! Пожалуйста, выбери себе что-нибудь в награду. Спасибо тебе ещё раз, я и мои роботы навеки у тебя в долгу.", female = "О, да ты просто спасла моего робота КПХ-девять/HL! Я прям даже не знаю, как тебя благодарить! Моих автономных роботов ещё совершенствовать и совершенствовать, но ты избавила меня от многих лишних часов работы, а также от расходов! Пожалуйста, выбери себе что-нибудь в награду. Спасибо тебе ещё раз, я и мои роботы навеки у тебя в долгу." },
    ["837a"] = { common = "Когда мы поселились здесь, свинобразы Иглогривых владели большей частью этих земель и оказались сущей напастью! Большую их часть нам мало-помалу удалось вытеснить, но в некоторых районах они окопались прочно. Однако, с нас довольно! Ради нашей безопасности мы не можем больше терпеть присутствие Иглогривых в наших землях. Их лагеря – к западу отсюда. Они часто прячутся в зарослях колючек. Сегодня мы вытесним их из Дуротара – а завтра, глядишь, и из всего Калимдора!" },
    ["837c"] = { common = "Я расскажу всем, что Иглогривы прогнаны со своих обжитых мест, и что их жилища надо сжечь. Теперь, когда племя Иглогривых изгнано из Дуротара, границы нашей новой родины станут значительно безопаснее." },
    ["838a"] = { common = "На острове Каэр Дарроу располагается Некроситет — школа, которая одновременно служит цитаделью Плети. В её недрах наши враги спокойно проводят исследования, делаясь всё сильнее. Путь преграждают двери, и без подходящего ключа внутрь не войти. Аптекарь Дитерс многое знает о Некроситете и придумал, как достать ключ. Ты зарекомендовал себя как человека с большими способностями, поэтому я доверяю тебе это задание. Обсуди подробности с аптекарем." },
    ["838c"] = { common = "Да, герой, Верховный палач упоминал, что тебе можно доверять в вопросе о ключе. Не давно я посвятил время исследованию Некроситета, я верю, я знаю способ, который позволит тебе отпереть входную дверь. Это будет нелёгкой задачей. Но ты не из тех, кто боится трудностей." },
    ["840a"] = { male = "Хм, слабаком тебя не назовёшь… Послушай, моему приятелю Каргалу нужны новобранцы для службы в Степях. Ты ведь хочешь принести пользу Орде? Ну вот, это твой шанс. Передай Каргалу это письмо о найме – возможно, он его подпишет.", female = "Хм, слабенькой тебя не назовёшь… Послушай, моему приятелю Каргалу нужны новобранцы для службы в Степях. Ты ведь хочешь принести пользу Орде? Ну вот, это твой шанс. Передай Каргалу это письмо о найме – возможно, он его подпишет." },
    ["840c"] = { common = "А, так тебя Такрин прислал? Он отличный разведчик, не знаю даже, что бы я без него делал… Письмо-то я подпишу, но на самом деле воины нам нужны не здесь, а в Перекрёстке." },
    ["841a"] = { male = "Дай-ка я угадаю – ты не успел осуществить свой страшный замысел, губительный для мироздания. Нет, ещё лучше... Ты уронил его в песок! Короче, в любом случае я могу продать тебе ещё один источник энергии. Только на сей раз он обойдётся в десять, да, ДЕСЯТЬ, бурдюков с водой Скитальцев Пустыни! Времена настали тяжёлые, а источники энергии не растут на деревьях! Хм, а что, если росли бы? Может, нам сконструировать дерево источников энергии...", female = "Дай-ка я угадаю – ты не успела осуществить свой страшный замысел, губительный для мироздания. Нет, ещё лучше... Ты уронила его в песок! Короче, в любом случае я могу продать тебе ещё один источник энергии. Только на сей раз он обойдётся в десять, да, ДЕСЯТЬ, бурдюков с водой Скитальцев Пустыни! Времена настали тяжёлые, а источники энергии не растут на деревьях! Хм, а что, если росли бы? Может, нам сконструировать дерево источников энергии..." },
    ["841c"] = { common = "Ладно, вот ещё один источник энергии. Очень советую применить его по назначению, если не хочешь добыть для меня ещё десять мехов воды." },
    ["842a"] = { male = "Отнеси это подписанное письмо о найме в Перекрёсток. Там всем заправляет – Сергра Чёрный Шип, лопни её шкура! Противная шаманка, заговорит тебя до посинения, прежде чем даст сделать что-нибудь толковое. Тралл уверен, что она замечательная, но мне что-то так не кажется. Так что разбирайся сам, парень...", female = "Отнеси это подписанное письмо о найме в Перекрёсток. Там всем заправляет – Сергра Чёрный Шип, лопни её шкура! Противная шаманка, заговорит тебя до посинения, прежде чем даст сделать что-нибудь толковое. Тралл уверен, что она замечательная, но мне что-то так не кажется. Так что разбирайся сама, детка..." },
    ["842c"] = { common = "Ладно. Не хочешь есть свой хлеб в Орде даром? Что ж, дел у нас предостаточно. Просто слушай внимательно и делай, что тебе скажут. Имей в виду, я по глазам вижу, что у тебя на уме. Наглости я не спущу! Тралл самолично заявил, что в Орде женщины во всём будут наравне с вами, мужиками. Только попробуй проявить ко мне неуважение – узнаешь, почём фунт лиха!" },
    ["843a"] = { common = "Ныне я брожу по дорогам родного края в одиночестве. Дворфы Бейл Модана не чтят моих границ. Они постоянно устраивают взрывы, после которых остаются огромные ямы, а шумные механизмы разрывают мои холмы. Земли, некогда приютившие и питавшие моё племя, захвачены вредоносными дворфами. Все попытки решить дело миром провалились. Пришло время для решительных действий. Выгони дворфов из раскопа в Бейл Модане и принеси мне записи Хазгорма, их главаря." },
    ["843c"] = { common = "Хазгорм заслужил свою судьбу. Мне нисколько его не жаль. Он явился в наши края незванным. Быть может, его смерть послужит предостережением тем, кто пытается нарушить наш покой. Дай-ка я изучу записи этого дворфа..." },
    ["844a"] = { common = "Первое задание будет совсем простым. Равнинные долгоноги, живущие к востоку отсюда, разоряют наши продовольственные склады – просто сил уже нет! Перебей несколько долгоногов и принеси мне их клювы." },
    ["844c"] = { common = "Хорошо. Долгоногов перебили, и нам будет проще доставлять продовольствие. Надеюсь, и ты кое-чему научился, потому что следующая дичь не такая смирная, как долгоноги..." },
    ["845a"] = { common = "Хотя жевры – не самые страшные звери в Степях, они посильнее равнинных долгоногов. Не беспокойся, в своё время тебе и покрупнее дичь достанется, но пока тебе ещё надо малость поточить зубки. Поохоться на жевр на севере и на юге и собери их копыта. Принеси их мне, и, быть может, в следующий раз мы дадим тебе задание посерьёзнее." },
    ["845c"] = { common = "Неплохо. У жевр сильные ноги. Одного меткого удара достаточно, чтобы отшвырнуть таурена в сторону! Похоже, в тебе тоже силы хватает. Ну что, готов пройти настоящее испытание?" },
    ["846a"] = { common = "Очевидно, что шахтёры не могут обойтись без взрывчатки и шумных землеройных машин. Мы думаем, что скоро туда направят нового старшину. Пусть проклятые дворфы отведают собственного угощения. Согласно схемам, если смешать нитроглицерин с древесной сердцевиной и натриевой селитрой, получится взрывной заряд. Все компоненты есть у ружейников, солдат и офицеров из Крепости. Собери всё необходимое и принеси мне. Я создам заряд, который дворфы не скоро забудут!" },
    ["846c"] = { male = "Вижу, ты зря времени не терял, герой. Очень скоро дворфов ожидает неприятный сюрприз!", female = "Вижу, ты зря времени не терял, героиня. Очень скоро дворфов ожидает неприятный сюрприз!" },
    ["847a"] = { common = "Эта... эта сила... Это и есть мощь шаманов, которую Тор'Ган пытался мне показать? Должен сказать, весьма интересно. Скажите Тор'Гану, что он меня убедил... на данный момент. Я выслушаю то, что он хочет мне сказать." },
    ["847c"] = { common = "Когда чары спадут, я поговорю с Гор'мулем. Благодарю вас за помощь в возвращении Гор'муля к жизни. Я не сомневаюсь, что и он очень благодарен вам." },
    ["848a"] = { common = "Оазисы Степей таят в себе тайну. В их водах разлита энергия жизни, питающая и укрепляющая растения и животных. И меняющая их. Неподалёку от этих оазисов растёт вид грибов, чьи споры мы, аптекари Лордерона, используем при создании снадобий. Принеси мне эти споры – и благодарность наша будет велика." },
    ["848c"] = { common = "Ах, да. Прекрасный материал. Действенный. Я из Отрёкшихся, а мы исполняем свои обещания. Вот твоё вознаграждение." },
    ["849a"] = { common = "Изучив схемы Хазгорма, можно без труда создать взрывчатку. Ну вот, готово. А теперь, я дам тебе особое задание. Возьми взрывчатку и подорви летающую машину в Бейл Модане. Эта машина не просто играет ключевую роль в снабжении раскопок, она служит и для военных целей. И что ещё важнее – она воплощение мощи дворфов и оскорбление памяти моего племени. Выполни это задание, и я буду гордиться тобой! Ну и награду ты тоже получишь." },
    ["849c"] = { common = "Отличная работа. В Громовом Утёсе тебя будут чтить как защитника священных земель тауренов и поборника исчезнувшего племени." },
    ["850a"] = { common = "Сотни лет кентавры вставали на пути тауренов. В последнее время клан Колкар начал всерьёз грозить безопасности Степей. Раньше им мешала побеждать их собственная неорганизованность, но недавно среди них появились новые вожди. Они создали из своих сородичей войско. Чтобы сохранить наши земли, мы должны убить вождей кентавров. Принеси мне голову Барака Кодобоя. Он живёт в лагере неподалёку от Забытых прудов на севере. Когда одержишь над ним верх, возвращайся." },
    ["850c"] = { common = "Молодец. Кентавры – примитивные и грубые создания, но некоторым из них была дарована мудрость и умение вести в бой. Они-то опаснее прочих. Барак таким и был. Хорошо, что он мёртв." },
    ["851a"] = { common = "Кентавр Верог Дервиш бродит по Пустошам, и найти его будет нелегко. Живёт же он в командном шатре кентавров, в Застывшем оазисе на юго-востоке. Быть может, удастся заманить его туда. Отправляйся в Застывший оазис и напади на кентавров рядом с командным шатром. Это опасно, но если убить достаточно кентавров, кто-нибудь поднимет тревогу и явится Верог. Принеси мне его голову, и я помещу её рядом с головой Барака Кодобоя." },
    ["851c"] = { male = "Замечательно. Видно, ты взбаламутил кентавров – стражи заметили необычную активность неподалёку от Застывшего оазиса. Наверное, это твоя работа. Можешь гордиться своим подвигом. Ты необыкновенно отважен.", female = "Замечательно. Видно, ты взбаламутила кентавров – стражи заметили необычную активность неподалёку от Застывшего оазиса. Наверное, это твоя работа. Можешь гордиться своим подвигом. Ты необыкновенно отважна." },
    ["852a"] = { male = "Хэрзул Кровавая Отметина – глава кентаврского клана Колкар в Степях. Он свиреп, жёсток и хитёр. Одолев его, ты нанесёшь серьёзный урон всем Колкар, а значит, они станут меньше угрожать нам. Итак, убей его. Принеси мне его голову, как принёс головы Барака и Верога. Он управляет своим народом из Цветущего оазиса на юге.", female = "Хэрзул Кровавая Отметина – глава кентаврского клана Колкар в Степях. Он свиреп, жёсток и хитёр. Одолев его, ты нанесёшь серьёзный урон всем Колкар, а значит, они станут меньше угрожать нам. Итак, убей его. Принеси мне его голову, как принесла головы Барака и Верога. Он управляет своим народом из Цветущего оазиса на юге." },
    ["852c"] = { male = "Хвала тебе. Хотя кентаврам не хватает дисциплины, чтобы обрушить свою ярость на врагов, как орки, они всё равно свирепые противники. Одержав над ними верх, ты доказал свою доблесть.", female = "Хвала тебе. Хотя кентаврам не хватает дисциплины, чтобы обрушить свою ярость на врагов, как орки, они всё равно свирепые противники. Одержав над ними верх, ты доказала свою доблесть." },
    ["853a"] = { common = "Я сделал эмульсию из принесённых тобой спор, и теперь мне нужно доставить её моей коллеге, аптекарю Заме. Если ты отнесёшь ей мою посылку, она предложит тебе на выбор что-нибудь из своего запаса алхимических товаров. Она живёт в Прудах Видений, пещере, расположенной ниже обиталища шаманов Громового Утёса. Путь к этой пещере хорошо скрыт, но начинается он на Вершине духов. Поспеши. Эмульсия хранится не очень долго, потому надо вскрыть и использовать её до того, как она испортится." },
    ["853c"] = { male = "А, споры, которые Хелбрим собрал в Степях. Он заручился твоей помощью при сборе? Хорошо. Эмульсия не успела испортиться, видать, ты время зря не тратил. Молодец, герой.", female = "А, споры, которые Хелбрим собрал в Степях. Он заручился твоей помощью при сборе? Хорошо. Эмульсия не успела испортиться, видать, ты время зря не тратил. Молодец, героиня." },
    ["854a"] = { male = "Я знал, что ты придёшь, юный герой. Хотя, пожалуй, ты уже не так юн. Думаю, тебе пора двинуться вглубь этих земель. Я чую, что тебе предстоят великие свершения. Ступай в Перекрёсток. Наша судьба тесно связана с судьбой орков, а им нужна помощь. Иди по дороге на восток, а потом сверни на север, к Перекрёстку. Отыщи Торка в стенах города, ибо с ним пребывает благословение Матери-Земли.", female = "Я знал, что ты придёшь, юная героиня. Хотя, пожалуй, ты уже не так юна. Думаю, тебе пора двинуться вглубь этих земель. Я чую, что тебе предстоят великие свершения. Ступай в Перекрёсток. Наша судьба тесно связана с судьбой орков, а им нужна помощь. Иди по дороге на восток, а потом сверни на север, к Перекрёстку. Отыщи Торка в стенах города, ибо с ним пребывает благословение Матери-Земли." },
    ["854c"] = { common = "Я рад, что нам на помощь прибыли союзники из самого Громового Утёса. Добро пожаловать!" },
    ["855a"] = { common = "Клан Колкар угрожает завоеваниям Орды в Степях. Мы должны сократить численность их войск. В связи с этим у меня есть для тебя задание. Отправляйся в земли Колкар, перебей их воинов и принеси мне их наручи. Возвращайся с трофеями, и Орда тебя наградит." },
    ["855c"] = { common = "Неплохо. Уверен, тебе удалось вселить страх в выживших кентавров. Если Колкар не полные идиоты, теперь они успокоятся и прекратят наступление. К сожалению, вряд ли им на это хватит ума. Что весьма плохо. Плохо для них, разумеется." },
    ["857a"] = { common = "Она была у меня в руках! В этих самых руках! И я хочу вернуть её! Вернуть, говорю! Её откопали эти грязные землекопы... и как она была прекрасна. Её назвали слеза Лун. Первое серьёзное открытие в Бейл Модане. Она должна достаться мне! Мне, говорю! Генерал Двукосса позавидовал силе, которую она мне давала, и запер её в Крепости. Сказал, что эта вещь проклята. Дурак! Её хотели заполучить и другие, мне пришлось их остановить. А этот ублюдок Двукосса прогнал меня. А я хочу её вернуть. Вернуть, говорю!" },
    ["857c"] = { common = "Наконец-то сила снова со мной! Со мной, говорю!" },
    ["858a"] = { common = "Тебя случайно не Пароклапан прислал? У меня проблемы. Я запрыгнул внутрь, не подумав, что для запуска резака нужен ключ. Один из операторов спросил меня, всё ли в порядке, и я впал в панику! Вместо того чтобы сказать, что я потерял ключ, я заявил, что резак неисправен. Надо поскорее выбираться отсюда! Поднимись в комнату управления на вышке, у бригадира должен быть ключ от резака. Выручи меня!" },
    ["858c"] = { common = "Ага, похоже, ключ подходит. Ну-ка, знаю ли я, как управлять этой штуковиной… Хм... Управление вращением... Этот рычаг отвечает за скорость и равновесие... Управление манипулятором. Ну и ну! Поверить не могу, что Торговая Компания создала устройство, которое настолько лучше нашего. Надо доставить этот резак в Кабестан!" },
    ["860a"] = { common = "Ежели хочешь вступить на путь охотника, то тогда тебе надо идти в Степи. Тамошние твари упрямы и яростны. Охотясь там, ты многому научишься, и дух твой окрепнет. Поговори с Сергрой Чёрный Шип. Она будет первой твоей наставницей в Степях. Сергра сейчас в Перекрёстке. Чтобы туда добраться, иди на восток от Деревни Кровавого Копыта прямиком в Степи, затем на развилке сверни на север. И по дороге держи ухо востро – Степи весьма опасны для неопытных и беспечных." },
    ["860c"] = { common = "Хочешь охотиться в Степях? Глаза у тебя горячие и молодые. Они ещё не окосели от выслеживания добычи на тутошних пыльных равнинах. Но ты не бойся. Мы закалим твоё тело и дух! И растолкуем, что охота – не просто выслеживание и добыча. Готовься. Твой путь начинается прямо сейчас." },
    ["861a"] = { male = "Вижу, ты любишь путешествовать. Когда-то и меня обуревала жажда странствий… Странствий и охоты. Ведь охота – первая доблесть таурена. Если ты в самом деле желаешь избрать путь охотника, Мелор Каменное Копыто поможет тебе сделать первые шаги. Он живёт в Громовом Утёсе, на вершине Охотников. Чтобы показать свою решимость и умения, принеси ему когти хищника плоскогорья. Эти звери сильны и хитры – подходящая добыча для молодого героя, избравшего путь охотника.", female = "Вижу, ты любишь путешествовать. Когда-то и меня обуревала жажда странствий… Странствий и охоты. Ведь охота – первая доблесть таурена. Если ты в самом деле желаешь избрать путь охотника, Мелор Каменное Копыто поможет тебе сделать первые шаги. Он живёт в Громовом Утёсе, на вершине Охотников. Чтобы показать свою решимость и умения, принеси ему когти хищника плоскогорья. Эти звери сильны и хитры – подходящая добыча для молодой героини, избравшей путь охотника." },
    ["861c"] = { common = "Скорн Белое Облако – мудрый таурен. Он посвятил охоте много лет, и хотя уже слаб телом, дух его по-прежнему бодр. Мы высоко чтим его. Если тебя и правда прислал Скорн, то он разглядел в тебе будущего охотника. Добыть же эти когти было непросто, я знаю. Быть может, тебе пора вступить на избранный путь." },
    ["862a"] = { male = "Должно быть, герою вроде тебя в Степях голодно. Я вот постоянно хочу есть. Знаешь, приготовлю-ка я тебе отличную похлёбку. Для этого мне понадобится несколько пещерных крыс. Похоже, эти грязные дворфы в Бейл Модане увлечены празднованием. Так что ступай в Бейл Модан, это на юге, и принеси мне несколько пещерных крыс. Тебе не стать закалённым бойцом, пока не набьёшь руку на крысах! Ха-ха!", female = "Должно быть, героине вроде тебя в Степях голодно. Я вот постоянно хочу есть. Знаешь, приготовлю-ка я тебе отличную похлёбку. Для этого мне понадобится несколько пещерных крыс. Похоже, эти грязные дворфы в Бейл Модане увлечены празднованием. Так что ступай в Бейл Модан, это на юге, и принеси мне несколько пещерных крыс. Тебе не стать закалённым бойцом, пока не набьёшь руку на крысах! Ха-ха!" },
    ["862c"] = { common = "Обычно я не ем этих грызунов, пока они такие... такие... свежие. Им надо полежать несколько недель, чтобы мяско стало с душком. Но ты, похоже, голоден. Дай-ка я сварю тебе похлёбку из пещерных крыс. Ну вот, готово. Кушай на здоровье!" },
    ["863a"] = { common = "Полагаю, я буду учиться по ходу дела... Вряд ли это так сложно. Тут пара кнопок, там рычаг-другой. Ну что, поехали?" },
    ["863c"] = { common = "Надеюсь, нам удастся найти что-нибудь ценное в этом поломанном образце резака... Время на исходе! Я отправлю спасательную экспедицию на помощь к Визлкранку. А, вот тебе за труды." },
    ["864a"] = { common = "Ну вот, источник энергии извлечён, и твои данные сохранились. Что ж, счастливого пути и всё такое. Надеюсь, зловещий научный эксперимент удался. *Гоблин отворачивается от вас и погружается в дела Водной компании Прибамбасска. Вы кладёте запечатанный набор для испытаний в надёжное место и готовитесь отбыть в Подгород. Вас и запечатанный набор ждёт аптекарь Зинг.*" },
    ["864c"] = { male = "Я немедленно займусь анализом данных. Быть может, безумие Чанна обернётся моей гениальностью. Что до тебя... Ты мне полезен, а я хорошо обращаюсь с полезными существами. Прими эту вещь, эти монетки, а в придачу к ним – мою благодарность. Заглядывай время от времени – думаю, что мы ещё поработаем вместе.", female = "Я немедленно займусь анализом данных. Быть может, безумие Чанна обернётся моей гениальностью. Что до тебя... Ты мне полезна, а я хорошо обращаюсь с полезными существами. Прими эту вещь, эти монетки, а в придачу к ним – мою благодарность. Заглядывай время от времени – думаю, что мы ещё поработаем вместе." },
    ["865a"] = { common = "Ящеры Степей умнее, чем прочие. Мне кажется, весь ум в рогах! Если так, эти рога можно стереть в порошок и сделать из них \"умный напиток\". Я мог бы продавать его за баснословные деньги!!! Ты можешь мне помочь. Принеси мне целые рога ящерочешуйчатых смертехватов. Они живут в южной части Степей и на севере, рядом с границей Ясеневого леса." },
    ["865c"] = { common = "Здорово, тебе удалось их добыть! Остаётся стереть рога в порошок, смешать с вином и..." },
    ["866a"] = { common = "Таких трав, как в Степях, нет нигде. Свойства у них по большей части те же, но вода оазисов оказывает на них особое влияние, и они всё же отличаются от подобных им, хоть и не сильно. Я хочу выяснить, в чём же состоит разница... и нельзя ли ей воспользоваться! Если ты владеешь искусством травничества, собери для меня образцы корней растений Степей, и я сравню их с травами из других регионов." },
    ["866c"] = { male = "Да-да, замечательно! Из этих корней я выращу травы и смогу изучить их. Надеюсь отыскать в них новые свойства. Скрытые ценные свойства... И не беспокойся – ты узнаешь об этом первым. Потому что в таком случае мне понадобится много корней!", female = "Да-да, замечательно! Из этих корней я выращу травы и смогу изучить их. Надеюсь отыскать в них новые свойства. Скрытые ценные свойства... И не беспокойся – ты узнаешь об этом первой. Потому что в таком случае мне понадобится много корней!" },
    ["867a"] = { common = "Нет сил терпеть нападения на наши караваны со съестными припасами. Пора сократить число проклятых гарпий, перерезав горло десятку-другому. Я пробрался к их гнёздам и выяснил, кто есть кто. Начать надо с низов, а потом постепенно пробиваться наверх. Для начала займись гарпиями и разбойницами из стаи Зачарованного Крыла, поселившимися на северо-западе, и принеси мне восемь когтей Зачарованного Крыла. Будет уже неплохо..." },
    ["867c"] = { common = "Прекрасные когти. Чудные. Отличная работа. Надеюсь, в ближайшем будущем мне снова доведётся полюбоваться на твою работу." },
    ["868a"] = { common = "Эй. Меня отправили в Перекрёсток присматривать за этими землями и сообщать начальству в Оргриммаре, что тут творится. В частности, мне велено наблюдать за насекомовидными тварями на юге в Полях Великанов. Нам о них почти ничего не известно, а я хотел бы узнать о них побольше. Кажется, они умнее обычных животных. Возьми вспарывающий коготь и принеси несколько яиц этих тварей из их курганов, но будь осторожнее: они нападут на тебя, если заметят, что ты творишь." },
    ["868c"] = { common = "Порадовал ты меня. Молодец. Вот твоя награда..." },
    ["869a"] = { common = "Недавно из сторожевой башни был похищен груз серебра. Он предназначался в уплату стражам Перекрёстка, и его необходимо вернуть. Самое странное... одного из воров мы поймали с поличным. И... это оказался ящер! Немыслимо! Не знаю, зачем ящерам серебро. Мне всё равно: главное, чтобы у нас не воровали. Пусть сдохнут! Отправляйся на охоту в Степи. Принеси мне их головы!" },
    ["869c"] = { male = "Тебе удалось избавить нас от ящеров! Спасибо. Ты – достойный герой.", female = "Тебе удалось избавить нас от ящеров! Спасибо. Ты – достойный героиня." },
    ["870a"] = { common = "Давным-давно Степи были цветущим садом, полным жизни. Но этих земель коснулась карающая десница войны и катаклизма, обратив их в высохшую пустыню. Это наполняет моё сердце грустью, но так уж получилось. Впрочем, в последние годы в Степях образовалось несколько новых оазисов, а в них появилась жизнь. Мы, друиды, чувствуем, что из глубины к поверхности рвётся какая-то сила. Мы должны обнаружить её источник. Отправляйся к Забытым прудам, к северу от Перекрёстка. Отыщи в воде источник силы и возвращайся сюда." },
    ["870c"] = { common = "Там есть расселина, из которой выходят пузырьки газа? Странно. Может быть, это и есть ответ на наши вопросы, но уверенности нет. Впрочем, хоть какая-то зацепка. Спасибо, что нашёл её." },
    ["871a"] = { common = "Все свинобразы – наши враги. Просто одни из них причиняют нам больше неприятностей, чем другие. Клан Иглогривых в последнее время нередко нападает на наши караваны из Дуротара, и терпеть это нет больше сил. Мои разведчики ищут главарей, но тем временем чем больший урон мы нанесём эти свиньям, тем лучше. Ступай на северо-восток, по направлению к Дуротару. Ты легко отыщешь их логова среди огромных колючих побегов, исходящих из земли. Отыщи их и убей, кого сможешь." },
    ["871c"] = { common = "Отличная работа. Мерзавцы-иглоривы наконец-то научатся считаться с мощью Орды." },
    ["872a"] = { common = "Один из разведчиков своими глазами видел нападение на караван из Дуротара. Естественно, виноваты свинобразы из племени Иглогривых. Возглавляет нападения Криниг Грознорыл. Его видели на северо-востоке отсюда, южнее дороги на Дуротар. Пока Криниг жив, покоя не будет. Но чтобы окончательно прекратить разбой, надо как следует унизить мерзких иглогривов. Убей Кринига Грознорыла и его приспешников и принеси мне его клык." },
    ["872c"] = { common = "Молодец. Криниг мёртв, и число нападений на караваны сократится. Твой народ должен гордиться тобой." },
    ["873a"] = { male = "Великий Иша Авак – повелитель этих вод. Велика его сила, несокрушима гордость. Народ побережья страшится его, ибо он поглотил многих из их числа. Но я не боюсь его. Я благодарен провидению за то, что он есть. Бросить ему вызов – высокая честь, ибо он достойный противник. Если ты готов, плыви на поиски Иши Авака, Рока Глубин. Его дух содержится в сердце, и услышав, как оно бьётся, можно узнать многое о своей судьбе.", female = "Великий Иша Авак – повелитель этих вод. Велика его сила, несокрушима гордость. Народ побережья страшится его, ибо он поглотил многих из их числа. Но я не боюсь его. Я благодарен провидению за то, что он есть. Бросить ему вызов – высокая честь, ибо он достойный противник. Если ты готова, плыви на поиски Иши Авака, Рока Глубин. Его дух содержится в сердце, и услышав, как оно бьётся, можно узнать многое о своей судьбе." },
    ["873c"] = { common = "Теперь вы с Иши Аваком едины. Его дух живёт в тебе. Он таится в твоих глазах… Глазах, которые однажды научатся видеть." },
    ["874a"] = { male = "Ты поохотился на многих зверей Степей. Дух твой твёрд. Но охотник должен быть готов ко всему, его не смутит никакой путь. Горы и болота не испугают его. И даже море. Найди мою сестру, Марен. Она охотится на огромных водных тварей на побережье и многому научит тебя. Ищи её с осторожностью, потому что побережье Степей захвачено людьми.", female = "Ты поохотилась на многих зверей Степей. Дух твой твёрд. Но охотник должен быть готов ко всему, его не смутит никакой путь. Горы и болота не испугают его. И даже море. Найди мою сестру, Марен. Она охотится на огромных водных тварей на побережье и многому научит тебя. Ищи её с осторожностью, потому что побережье Степей захвачено людьми." },
    ["874c"] = { male = "Тебя прислал мой брат? Должно быть, ты произвёл на него впечатление. А если тебя зауважал Джорн, то и я буду уважать. Желаешь ли ты сделать следующий шаг на пути охотника?", female = "Тебя прислал мой брат? Должно быть, ты произвела на него впечатление. А если тебя зауважал Джорн, то и я буду уважать. Желаешь ли ты сделать следующий шаг на пути охотника?" },
    ["875a"] = { male = "Ха-ха-ха. Ещё захотелось? Отлично, приятно слышать. На сей раз я хочу, чтобы ты убил несколько лейтенантов гарпий в Сухих холмах. Лейтенантами бывают только душегубки из стаи Зачарованного Крыла. Их можно отличить от других по характерным кольцам. Неприятные твари, да ещё и приспешников их там полно. Убей шестерых и нанеси мощный удар по этому бабьему царству. И пусть подыхают долго и мучительно. Это научит их не связываться с Ордой.", female = "Ха-ха-ха. Ещё захотелось? Отлично, приятно слышать. На сей раз я хочу, чтобы ты убила несколько лейтенантов гарпий в Сухих холмах. Лейтенантами бывают только душегубки из стаи Зачарованного Крыла. Их можно отличить от других по характерным кольцам. Неприятные твари, да ещё и приспешников их там полно. Убей шестерых и нанеси мощный удар по этому бабьему царству. И пусть подыхают долго и мучительно. Это научит их не связываться с Ордой." },
    ["875c"] = { common = "Прекрасная работа, дружище. Думаю, ты достигнешь высокого положения в Орде." },
    ["876a"] = { male = "Ты так хорошо справился с лейтенантами и приспешниками, что я хочу дать тебе ещё одно поручение. Серена Кровавое Перо – сестра гарпии по имени Кровавое Перо, которую давным-давно прикончил Рексар. Очевидно, что нападения на обозы Орды обусловлены желанием отомстить за смерть сестры. Перережь ей горло и принеси мне её голову. Я хочу прибить её на переднюю телегу следующего каравана... Пусть проклятые гарпии задумаются, прежде чем снова нападать на нас.", female = "Ты так хорошо справилась с лейтенантами и приспешниками, что я хочу дать тебе ещё одно поручение. Серена Кровавое Перо – сестра гарпии по имени Кровавое Перо, которую давным-давно прикончил Рексар. Очевидно, что нападения на обозы Орды обусловлены желанием отомстить за смерть сестры. Перережь ей горло и принеси мне её голову. Я хочу прибить её на переднюю телегу следующего каравана... Пусть проклятые гарпии задумаются, прежде чем снова нападать на нас." },
    ["876c"] = { common = "ХА! Молодец! Отличная работа... Я не был уверен, что ты справишься с заданием, но, оказывается, ты головорез, каких поискать. Ещё раз спасибо за избавление от нашествия гарпий. Вот награда, используй её с умом." },
    ["877a"] = { common = "Быть может, и в других оазисах Степей есть расселины вроде той, что тебе удалось обнаружить в Забытых прудах? Коли так, скорее всего именно эти расселины – источник жизни оазисов. Надо проверить. Вот, возьми эти семена. Сейчас они мёртвые и бесплодные. Отнеси их в Застывший оазис на юго-востоке. Если там есть расселина, помести в неё семена... и понаблюдай." },
    ["877c"] = { common = "Удивительное открытие! Я дал тебе иссохшие, мёртвые семена. Значит, то, что таится в этих оазисах, создаёт жизнь из ничего! Необходимо исследовать это явление повнимательнее..." },
    ["878a"] = { common = "Отомсти моим врагам. *фыркает* Помоги Кривозубу и Иглогривым, ослабив племя Дыбогривов. Оба племени духовно связаны с землёй и её мощью. *фыркает* Она дарует нам силу, необходимую для всего... и прежде всего – для войны. Если ты в самом деле хочешь узнать, кто причинил Торку и Орде так много страданий, помоги Кривозубу! Напади на духовных вождей Дыбогривов на севере; подорви их мощь, чтобы Иглогривые одолели своих соперников и покорили Степи." },
    ["878c"] = { male = "Да-да... Меня должна переполнять радость, фыркает ведь племя Дыбогривов испытало ту же боль, что и мой народ, герой. Но нет, радости нет места. фыркает Ты помогаешь своим, и они чтят тебя. Кривозуб помогает своим – и что же? Они отвернулись от него. Его забыли, оставили гнить в клетке! Я помогал им даже из-за решётки, но никто не пришёл мне на помощь!", female = "Да-да... Меня должна переполнять радость, фыркает ведь племя Дыбогривов испытало ту же боль, что и мой народ, героиня. Но нет, радости нет места. фыркает Ты помогаешь своим, и они чтят тебя. Кривозуб помогает своим – и что же? Они отвернулись от него. Его забыли, оставили гнить в клетке! Я помогал им даже из-за решётки, но никто не пришёл мне на помощь!" },
    ["879a"] = { male = "Из Лабиринтов вышли трое моих соплеменников, чтобы возглавить набеги на Орду, герой. *фыркает* Они отличаются жестокостью и хитростью, и если одолеть их, то в Перекрёстке и в большей части Степей воцарится мир... *фыркает* по крайней мере, племя Иглогривых не будет на вас нападать. *фыркает* Имена этих главарей – Нак, Куз и Лок Оркобой. Они укрылись на юге Степей. Один из них заклинатель, другой следопыт, а главный из них – тот, кого называют Оркобоем – *фыркает* воин. Убей их, герой, как они убили меня.", female = "Из Лабиринтов вышли трое моих соплеменников, чтобы возглавить набеги на Орду, героиня. *фыркает* Они отличаются жестокостью и хитростью, и если одолеть их, то в Перекрёстке и в большей части Степей воцарится мир... *фыркает* по крайней мере, племя Иглогривых не будет на вас нападать. *фыркает* Имена этих главарей – Нак, Куз и Лок Оркобой. Они укрылись на юге Степей. Один из них заклинатель, другой следопыт, а главный из них – тот, кого называют Оркобоем – *фыркает* воин. Убей их, героиня, как они убили меня." },
    ["879c"] = { male = "Дело сделано. Кривозуб считает, уж лучше так. *фыркает* Надо было убедиться *фыркает*, что я мёртв, а не бросать меня здесь, во всеми забытой клетке. Тебе осталось лишь одно дело, герой.", female = "Дело сделано. Кривозуб считает, уж лучше так. *фыркает* Надо было убедиться *фыркает*, что я мёртв, а не бросать меня здесь, во всеми забытой клетке. Тебе осталось лишь одно дело, героиня." },
    ["880a"] = { common = "Ты рассказываешь невероятные вещи. Источник свойств этих оазисов явно сторонний. Или, быть может, вообще потусторонний. Я хочу узнать, какое влияние расселины оказывают на зверей, приходящих на водопой. Убей несколько оазисных хрустогрызов в Цветущем и Застывшем оазисах. Принеси мне их панцири, и я их пристально изучу." },
    ["880c"] = { common = "Спасибо. Изучая обитателей различных мест, узнаешь немало о самих местах. Посмотрим, о чём нам поведают панцири. Прошу тебя, прими благодарность за помощь... Быть может, эти монеты тебе не помешают. Мне они уже не нужны." },
    ["881a"] = { common = "Ичияки, Белый Туман на языке тауренов, король кошачьих саванны. Он подкрадывается к жертвам так незаметно, что его уподобили белому туману, стелящемуся над землёй. Убивает он одним ударом – жертва не успевает ни испугаться, ни ощутить боли. Таурены говорят, что он воплощает собой милосердие и смерть. Ты узнаешь это на своём опыте, потому что я отправляю тебя охотиться на Ичияки. Его логово располагается на северо-востоке от Перекрёстка, среди костей огромного кодо. Ступай. Добравшись до логова, протруби в этот рог. Протруби в рог, и он явится на зов." },
    ["881c"] = { male = "Тебе удалось одолеть Ичияки, и хотя ему больше не суждено охотиться в саванне, дух его отныне пребудет с тобой. Он научит тебя обретать силу в хитрости, а честь в милосердии. Перед тобой долгий путь, герой. Хочется верить, что ты далеко пойдёшь.", female = "Тебе удалось одолеть Ичияки, и хотя ему больше не суждено охотиться в саванне, дух его отныне пребудет с тобой. Он научит тебя обретать силу в хитрости, а честь в милосердии. Перед тобой долгий путь, героиня. Хочется верить, что ты далеко пойдёшь." },
    ["882a"] = { male = "Ишамухал, или Копьезуб, – самый страшный из всех яркочешуйчатых ящеров Степей. Он охотится не ради еды и не для удовольствия. Охота – его страсть. Он убивает потому, что сам убийца по природе. Именно о его природе тебе и предстоит узнать многое, ибо твой путь теперь поведёт тебя по когтистым следам Ишамухала. Начинай охоту. Убей его излюбленную добычу – жевру – и принеси его тушу к мёртвому дереву на северо-западе от Кабестана. Ишамухал почует тушу и явится на её запах. Будь готов к его появлению.", female = "Ишамухал, или Копьезуб, – самый страшный из всех яркочешуйчатых ящеров Степей. Он охотится не ради еды и не для удовольствия. Охота – его страсть. Он убивает потому, что сам убийца по природе. Именно о его природе тебе и предстоит узнать многое, ибо твой путь теперь поведёт тебя по когтистым следам Ишамухала. Начинай охоту. Убей его излюбленную добычу – жевру – и принеси его тушу к мёртвому дереву на северо-западе от Кабестана. Ишамухал почует тушу и явится на её запах. Будь готова к его появлению." },
    ["882c"] = { common = "Клык – всего лишь символ, но символ очень важных вещей. Теперь в тебе есть сила Ишамухала. Пользуйся ей, но соблюдай умеренность. Отныне это твоя ноша. И это великая честь." },
    ["883a"] = { common = "Копыто Лакота'мани – символ силы великого кодо." },
    ["883c"] = { common = "Лакота'мани на нашем языке означает \"Землекрушитель\", ибо шаги его громоподобны. Теперь он пребывает с тобой, к тебе перешло всё его мужество. Отныне ты не побоишься встретиться с любой опасностью. Верь в себя. Верь в себя, Землекрушитель." },
    ["884a"] = { common = "При касании от хвоста Оватанки летят искры." },
    ["884c"] = { male = "Имя рокочущей ящерицы Оватанки на языке тауренов означает \"синяя молния\", ведь о её стремительности не стоит судить по размеру. Говорят, что Оватанку некогда поразила молния, и, напитавшись гневом небес, она стала воистину неутомимой. Ныне её неутомимость передалась тебе. Теперь ты не отстал бы от Оватанки.", female = "Имя рокочущей ящерицы Оватанки на языке тауренов означает \"синяя молния\", ведь о её стремительности не стоит судить по размеру. Говорят, что Оватанку некогда поразила молния, и, напитавшись гневом небес, она стала воистину неутомимой. Ныне её неутомимость передалась тебе. Теперь ты не отстала бы от Оватанки." },
    ["885a"] = { common = "Пера Ваште Пауни больно касаться." },
    ["885c"] = { male = "Грозовой змей нечасто встречается в Степях, и его смерть может означать большую удачу или тяжкий рок. Но смерть Ваште Пауни, что на языке тауренов означает \"кусающий дух\", не значит ни то, ни другое... Или оба сразу. Боль, испытанная тобой во время охоты на это существо, знакома всем, кто достигает величия великой ценой. Внутренние терзания же – следствие сожалений. Впрочем, я вижу, что ты справился с этими искушениями и познал, что сожаления обращаются в мудрость и лишь через страдания можно обрести силу. Ты многое познал.", female = "Грозовой змей нечасто встречается в Степях, и его смерть может означать большую удачу или тяжкий рок. Но смерть Ваште Пауни, что на языке тауренов означает \"кусающий дух\", не значит ни то, ни другое... Или оба сразу. Боль, испытанная тобой во время охоты на это существо, знакома всем, кто достигает величия великой ценой. Внутренние терзания же – следствие сожалений. Впрочем, я вижу, что ты справилась с этими искушениями и познала, что сожаления обращаются в мудрость и лишь через страдания можно обрести силу. Ты многое познала." },
    ["886a"] = { common = "Друиды Громового Утёса ощущают странную силу, просачивающуюся в Степи к, востоку от Мулгора. Мы отправили найти источник этой силы Тонгу Рунического Тотэма, но, похоже, ему нужна помощь. Отправляйся в Степи и поговори с Тонгой. Он будет в Перекрёстке. Иди туда по дороге на восток от Деревни Кровавого Копыта. Как попадёшь в Степи, сверни на развилке на север. И продолжай идти, пока не упрёшься в Перекрёсток. С дороги не сходи, ибо Степи – край суровый." },
    ["886c"] = { male = "Мои собратья в Громовом Утёсе мудро поступили, прислав тебя сюда, юный герой. Ибо тайну Степей мне в одиночку не раскрыть. Будем надеяться, что с твоей помощью мы найдём ответ на наш вопрос.", female = "Мои собратья в Громовом Утёсе мудро поступили, прислав тебя сюда, юный героиня. Ибо тайну Степей мне в одиночку не раскрыть. Будем надеяться, что с твоей помощью мы найдём ответ на наш вопрос." },
    ["887a"] = { common = "Жаль, что вице-адмиралу Греззлику не удалось добиться безопасности в наших водах для торговых кораблей. В торговый флот вложено столько денег, что я просто зверею, когда пираты как нечего делать нападают на мои корабли и похищают товары! Говорят, что флибустьеры Южных морей разбили лагерь к югу отсюда. Они мне как бельмо на глазу, и если ими не хочет заняться Греззлик, может быть, ты поможешь избавиться от них?" },
    ["887c"] = { common = "Молодец, малыш. Побольше таких подвигов, и у меня станет одной проблемой меньше. Хочется верить, что они решат перенести свой лагерь. Остаётся одно – вернуть украденные товары!" },
    ["888a"] = { common = "Хоть я и хотел бы вернуть все товары, думаю, это невозможно. Но некоторые из них мне очень нужны! Как видишь, моя обсерватория почти готова, но ей не хватает двух малых линз. Первая из них прибыла с караваном из Дуротара, но вторую везли на корабле, который ограбили пираты. Кроме того, до меня так и не дошла партия сапог от Дриззлика из Пиратской бухты! Ступай в пиратский лагерь и поищи их." },
    ["888c"] = { common = "Я так рад, что вернул своё добро! Спасибо за помощь. Знаешь, мне пригодились бы помощники вроде тебя. Если понадобится работа, не забывай, что Газлоу неплохо платит!" },
    ["890a"] = { common = "Я уже сто лет жду последнего заказа из Пиратской бухты! Наверняка его перехватили флибустьеры, но на всякий случай сходи в порт и спроси у Дыбоволоса, вдруг товары без моего ведома отнесли на склад? Вот, отнеси мою учётную книжку Головокружилкинсу, пусть сверит со своими записями." },
    ["890c"] = { common = "А, так тебя прислал Газлоу? Минутку, дай-ка я загляну в свои записи, надо убедиться, что я не отправил товар Газлоу куда-то не туда. Небось, он ждёт поставку сапог от Дриззлика..." },
    ["891a"] = { common = "Вот и ещё один мой корабль захватили рьяные людишки из крепости Северной стражи! Пора разобраться с этими мерзавцами. Их паранойя перешла все мыслимые границы. Эти безрассудные любители спускать курок стреляют во всё, что движется. Отправляйся на юг вдоль Торгового побережья, найди их крепость и брось вызов их силе. Принести в доказательство собственных подвигов медали их солдат. И во имя моего флота, убей капитана Гордостанную и её рьяных канониров!" },
    ["891c"] = { common = "Ах, какая жалость, праведные пушки Альянса умолкли. Ты получишь награду за помощь. Как бы теперь выручить тела наших погибших..." },
    ["892a"] = { common = "У меня в записях всё в порядке. Ступай к Газулу и скажи, что ему не повезло. Не удивлюсь, если его товары прибрали к рукам пираты. Я ничем не могу ему помочь. А, да... Скажи, что у меня есть для него кое-что из Нижней шахты, пусть приходит и забирает." },
    ["892c"] = { common = "Вот непруха... Наверняка это корсары... Дыбоволос тут ни при чём, я уверен, он не стал бы так меня обманывать. В конце концов, он получает деньги за доставку. Похоже, мне придётся вернуть себе кое-какие товары. Что скажешь?" },
    ["893a"] = { common = "Хотя говорят, что у свинобразов племени Иглогривых за Полями Великанов нет искусных кузнецов, они научились делать серьёзное оружие. Мне хотелось бы получить несколько образцов, чтобы изучить их технику работы. Если ты стремишься к подвигам во славу Орды, добудь для меня их оружие. Мне понадобятся кинжал, жезл и щит. Этого вполне хватит!" },
    ["893c"] = { common = "Прекрасные, прекрасные образцы. Свинобразы куда более умелый народ, чем мне казалось. Вот, возьми это и убирайся. Мне надо получше изучить это оружие. Похоже, мы недооценивали врага, а такие ошибки недопустимы." },
    ["894a"] = { common = "Торговая Компания устроила к северу отсюда, в юго-западной части Нефтяного болота, небольшой исследовательский центр. Я не очень хорошо представляю, чем они занимаются, но до меня дошли сведения, что они проводят эксперименты со штукой под названием \"самофланж\". Что ещё за самофланж? Как бы то ни было, я хочу исследовать его, а значит, мне надо его заполучить. Мне удалось достать копию их руководства пользователя. Почитай его, там наверняка написано, как вытащить самофланж из терминала." },
    ["894c"] = { common = "На панели управления в беспорядке разбросаны кнопки, рычаги и мигающие лампочки. Судя по маленькому индикатору, устройство работает в оптимальном режиме, а контрольные клапаны один-три открыты. В нижнем правом углу панели управления имеется небольшая замочная скважина." },
    ["895a"] = { common = "РОЗЫСК! Разыскивается Барон Дольноберег, капитан \"Безрассудной\". Капитан Дольноберег из Гильнеаса водит корабли корсаров Южного моря. Он разыскивается по обвинению в пиратских нападениях. Предоставленные останки должны быть пригодны для опознания! - Газул." },
    ["895c"] = { common = "А! Вот какое у тебя дело. Знаешь, я однажды видел \"Безрассудную\" в открытом море. Впечатляющий корабль. Или судно? Эти моряки так придираются к словам! В общем, она так скользила по водной глади, что дух захватывало. Я рад, что её проклятый капитан перестанет тревожить мои корабли." },
    ["896a"] = { common = "Хозяин причала в таком оживлённом порту, как Кабестан, держит руку на пульсе происходящего. Я в курсе всего товарообмена между нашим городом и Пиратской бухтой. Последние слухи касаются Каменного карьера, принадлежащего Торговой Компании, что на северо-востоке от Нефтяного болота. Один из шахтёров нашёл изумруд размером с твой кулак. Я знаю несколько покупателей на такой товар и готов поделиться с тобой комиссией." },
    ["896c"] = { common = "Только посмотри, какой он огромный! Теперь мы разбогатеем! Ну-ка, судя по расценкам на драгоценные камни, я могу прикинуть твою долю... Пятьдесят процентов, будь спок! Посчитаем... Да, примерно так. С тобой приятно иметь дело." },
    ["897a"] = { common = "Это странное, похожее на насекомое существо выглядит так, будто попало в Степи случайно." },
    ["897c"] = { common = "Не могу ничего сказать о природе этого зверя, ведь духа его и след простыл. Но ты верно говоришь, он не из Степей. Боюсь, наш народ ожидают испытания… А пока готовься к худшему. Будем надеяться, что со временем мы разгадаем тайну этого существа." },
    ["898a"] = { common = "Наконец-то! Кто-то пришёл мне на помощь! Поверить не могу, что тебе удалось пройти мимо стражей. Фанатики из Терамора совсем спятили. Они потопили наш корабль и меня, единственного выжившего, взяли в плен. Меня назвали врагом и угрозой безопасности Альянса. Я! Угроза великому и могучему Альянсу? Я был матросом на грузовом судне, возившем самогон из Кабестана в Пиратскую бухту. Довольно болтать. Ты ведь поможешь мне вернуться в Кабестан? Скажи, когда решишь тронуться в путь, и мы совершим побег." },
    ["898c"] = { male = "Подумать только, мы полагали, что Огненный Цветок давно погиб! Ты заслужил уважение всех Тало'данских каперов.", female = "Подумать только, мы полагали, что Огненный Цветок давно погиб! Ты заслужила уважение всех Тало'данских каперов." },
    ["899a"] = { male = "Быть может, тебе знакома мука неопределённости, а может, и нет. Но знай: каждый день я стою здесь от восхода до заката и выискиваю взглядом этих чудовищ. Я убил всех людей-свиней, которые попались мне на пути, но так и не смог утолить ненависть. Быть может, мне стоило идти не на север к Перекрёстку, а в Таурахо. Ты, герой, мог бы мне помочь. Убей их. Убей как можно больше тварей. Принеси мне их клыки, и мы вместе попируем на их могилах.", female = "Быть может, тебе знакома мука неопределённости, а может, и нет. Но знай: каждый день я стою здесь от восхода до заката и выискиваю взглядом этих чудовищ. Я убил всех людей-свиней, которые попались мне на пути, но так и не смог утолить ненависть. Быть может, мне стоило идти не на север к Перекрёстку, а в Таурахо. Ты, героиня, могла бы мне помочь. Убей их. Убей как можно больше тварей. Принеси мне их клыки, и мы вместе попируем на их могилах." },
    ["899c"] = { common = "Воин, ты отнёсся к моему заданию серьёзно, спасибо тебе за это. Хотя жажда мести не утолена, я могу хотя бы улыбаться при мысли о том, что и иглогривы испытали ту же боль, что и я." },
    ["900a"] = { common = "В настоящий момент открыты три контрольных клапана. Суда по надписям на панели управления, их надо закрыть, прежде чем выключать прибор." },
    ["900c"] = { common = "Лампочки, относящиеся к трём управляющим клапанам, медленно гаснут. Зелёный огонёк становится жёлтым, и теперь можно повернуть рычажок, выключающий прибор. Клапаны закрыты, и терминал можно отключить." },
    ["901a"] = { common = "Прибор выключен, и вы можете открыть панель управления и достать самофланж из терминала. Всё бы хорошо, но чтобы отпереть терминал, нужен ключ." },
    ["901c"] = { common = "Повернув ключ в замке, вы открываете панель управления. В верхней части терминала гаснет красная лампочка. Теперь он полностью обесточен." },
    ["902a"] = { common = "Под панелью управления оказывается мешанина проводов, ламп и прочих загадочных механических объектов – кажется, большая часть там вообще не нужна. Отодвинув их в сторону и сунув руку поглубже, вы находите самофланж. Одного рывка хватает, чтобы вытащить его из паза." },
    ["902c"] = { common = "Это... Э... Любопытно... Да. Я пошлю его в Союз ремонтников Нижней шахты. Не сомневаюсь, что эту штуку исследуют и поймут, для чего она нужна. Впрочем, сначала надо самому посмотреть что к чему..." },
    ["903a"] = { common = "Пришло время поохотиться на тех, кто может постоять за себя. Хищники саванны, живущие в Степях – сильные звери. Сильные, могучие, хитрые и опасные. Их можно найти в высокой траве на юго-западе от Перекрёстка. Соблюдай осторожность, иначе можешь неожиданно превратиться из охотника в дичь." },
    ["903c"] = { common = "А, вижу, ты времени даром не терял, а прятался в траве, выслеживая хищников. Как ты думаешь, пришло ли время встретиться лицом к лицу с сильнейшим из них?" },
    ["905a"] = { common = "Что ж, теперь твоя задача усложняется. Сначала тебе надо победить свою добычу, а потом отыскать её логово. Я предлагаю поохотиться на яркочешуйчатых ящеров, живущих на юге. Убей их и забери перья. Отнеси перья в их гнёзда на юго-западе от Застывшего оазиса. Покажи их сородичам, что ты не боишься!" },
    ["905c"] = { male = "Значит, ты побывал возле гнёзд и поместил в них перья? На это требуется немало мужества. Ты чувствуешь, что стал сильнее? Выглядишь ты куда крепче, чем в тот миг, когда явился сюда в первый раз. Думаю, Степи сыграли в этом свою роль.", female = "Значит, ты побывала возле гнёзд и поместила в них перья? На это требуется немало мужества. Ты чувствуешь, что стала сильнее? Выглядишь ты куда крепче, чем в тот миг, когда явилась сюда в первый раз. Думаю, Степи сыграли в этом свою роль." },
    ["906a"] = { male = "Отнеси голову Лока Торку на Перекрёсток, герой. *фыркает* Он-то без слов должен знать, что случилось с моим племенем; ха, он ни за что не поверит, что Кривозуб помог в *фыркает* таких вещах. Но я не сомневаюсь, что он наградит тебя за совершённый подвиг. *фыркает* Пока я сижу в этой клетке, я и дальше буду благословлять тебя силой Агамаггана. Пока же прощай.", female = "Отнеси голову Лока Торку на Перекрёсток, героиня. *фыркает* Он-то без слов должен знать, что случилось с моим племенем; ха, он ни за что не поверит, что Кривозуб помог в *фыркает* таких вещах. Но я не сомневаюсь, что он наградит тебя за совершённый подвиг. *фыркает* Пока я сижу в этой клетке, я и дальше буду благословлять тебя силой Агамаггана. Пока же прощай." },
    ["906c"] = { common = "Тебе удалось найти главаря племени Иглогривых и собственноручно убить его? Поразительно. У меня нет слов, но это не значит, что я не благодарен тебе. Жители Перекрёстка должны уважать твою силу. Должен признать, я считал, что возглавляет налёты на наши обозы другой свинобраз. Ещё раз спасибо." },
    ["907a"] = { common = "Пришло время выступить против рокочущих ящериц. Они столь огромны, что земля дрожит под их шагами. Сражаясь с ними, соблюдай осторожность: один неверный шаг – и они стопчут тебя. Ящерицы живут в южной части Степей. Их называют грозорылами, грозошкурами и громоголовами. Возвращайся ко мне с победой." },
    ["907c"] = { common = "Я рад, что ты принёс доказательство своего торжества. И особенно здорово, что у тебя все кости остались целы." },
    ["913a"] = { male = "Грозовой змей – лютый зверь. И всё же ты уже готов бросить ему вызов. Ступай, отыщи его и принеси мне крылья в доказательство успешной охоты. Выполни моё задание, и твоё обучение подойдёт к концу.", female = "Грозовой змей – лютый зверь. И всё же ты уже готова бросить ему вызов. Ступай, отыщи его и принеси мне крылья в доказательство успешной охоты. Выполни моё задание, и твоё обучение подойдёт к концу." },
    ["913c"] = { male = "Тебе есть чем гордиться, ведь ты одолел всех врагов, явив силу, мужество и честь. Не останавливайся, следуй дальше по своему пути. Более того, жизнь настоящего охотника – постоянная борьба. Ступай же с высоко поднятой головой по избранному тобой пути. Пора.", female = "Тебе есть чем гордиться, ведь ты одолела всех врагов, явив силу, мужество и честь. Не останавливайся, следуй дальше по своему пути. Более того, жизнь настоящего охотника – постоянная борьба. Ступай же с высоко поднятой головой по избранному тобой пути. Пора." },
    ["914a"] = { common = "Друиды в Пещерах Стенаний, Друиды Клыка поражены порчей. Когда-то они были частью ордена друидов давшего обет исцелить Степи, но теперь они хотят перекроить эти земли в соответствии со своими извращёнными мечтаниями. У Друидов Клыка четыре предводителя и каждый обладает Камнем Сновидения. Даже теперь их лица преследуют меня в кошмарах. Убей предводителей друидов, принеси мне их камни и в Степях снова воцарится мир. Иди, и разыщи их укрытия в Пещерах Стенаний." },
    ["914c"] = { male = "Ты сделал это. Ты убил друидов Клыка, теперь мои сны свободны от их присутствия. Ты спас Степи, и я благодарю тебя от своего имени, от имени друидов Громового Утёса и от имени этой земли.", female = "Ты сделала это. Ты убила друидов Клыка, теперь мои сны свободны от их присутствия. Ты спасла Степи, и я благодарю тебя от своего имени, от имени друидов Громового Утёса и от имени этой земли." },
    ["916a"] = { common = "Я пришёл в Тенистую долину, чтобы наблюдать за чащобными тенётниками, обитающими в Паучьем логове. Они – родичи более мелких разновидностей пауков. Полагаю, что Древо Жизни оказало на них сильное воздействие... Я хотел бы получить несколько вещей, чтобы изучить их и подтвердить свои догадки. Для начала мне понадобится немного их яда. Добудь ядовитые железы у пауков-тенётников в Паучьем логове и вокруг него, к северу отсюда. После этого я смогу изучить эти образцы и понять, есть ли у этого яда сходство с ядом их более мелких сородичей." },
    ["916c"] = { common = "Благодарю тебя. Когда я вернусь в Дарнасс, я первым же делом сравню образцы яда из этих желёз с ядами других пауков. Полагаю, что некоторые свойства яда связаны с ростом нового Древа Жизни." },
    ["917a"] = { common = "Теперь, когда у меня есть паучий яд, мне хотелось бы получить для изучения живой образец. Не волнуйся, я не могу просить тебя поймать гигантского паука живьём. Да и мне самому вряд ли удалось бы справиться с таким \"образцом\"! Но если ты принесёшь яйцо, из которого ещё не вылупился паучок, то получить образец будет куда легче, не говоря уж о том, чтобы содержать. В глубинах Паучьего логова должно быть гнездо. Прошу тебя, найди его, возьми оттуда яйцо паука и принеси мне." },
    ["917c"] = { common = "О, отлично. Я отправлю яйцо и яд в Дарнасс, а потом и сам вернусь туда, когда мои изыскания здесь будут завершены. Я многого ожидаю от этих образцов. Твоя помощь оказалась поистине бесценной." },
    ["918a"] = { male = "Древесники Тельдрассила – духи Природы. Они в какой-то мере отражают естественный порядок жизни растений и животных на нашем великом древе. Потому меня очень тревожит, что древесники становятся такими озлобленными. Мне кажется, что дело в почве. Я разными методами выращивал растения, и мне хотелось бы испытать эти способы на саженцах древесников. Не мог бы ты собрать для меня этих саженцев вокруг озера Аль'Амет?", female = "Древесники Тельдрассила – духи Природы. Они в какой-то мере отражают естественный порядок жизни растений и животных на нашем великом древе. Потому меня очень тревожит, что древесники становятся такими озлобленными. Мне кажется, что дело в почве. Я разными методами выращивал растения, и мне хотелось бы испытать эти способы на саженцах древесников. Не могла бы ты собрать для меня этих саженцев вокруг озера Аль'Амет?" },
    ["918c"] = { male = "Ты их добыл. Славно! Я посажу их в специально подготовленную почву. Уверен, что ростки потянутся вверх и вырастут в древесников, гораздо более послушных. Может, позже ты ещё увидишь результаты!", female = "Ты их добыла. Славно! Я посажу их в специально подготовленную почву. Уверен, что ростки потянутся вверх и вырастут в древесников, гораздо более послушных. Может, позже ты ещё увидишь результаты!" },
    ["919a"] = { common = "Вокруг вод озера Аль'Амет прорастают маленькие древесники. Боюсь, им уже не помочь, нам придётся выдернуть их из земли прежде, чем они станут слишком большими и начнут приносить беды. Когда будешь бродить вокруг озера, выдергивай каждый росток древесника, что попадётся тебе по дороге. Помоги очистить нашу землю!" },
    ["919c"] = { common = "Как много! Они распространяются с ужасающей скоростью. Надеюсь, мне удастся разгадать, что же за порча поразила их. Благодарю за помощь. Этот край благодаря твоим усилиям стал чище." },
    ["920a"] = { male = "Ты путник, не так ли? До меня доходили слухи, что тебя искал Тенарон. Ты отыщешь его в самой верхней комнате на вершине Альдрассила. Хоть мы и живём долго, не стоит заставлять Тенарона ждать.", female = "Ты путница, не так ли? До меня доходили слухи, что тебя искал Тенарон. Ты отыщешь его в самой верхней комнате на вершине Альдрассила. Хоть мы и живём долго, не стоит заставлять Тенарона ждать." },
    ["920c"] = { common = "А. Я думал, что ты быстрее откликнешься на мой призыв. У меня есть важное задание, которое я хочу поручить тебе." },
    ["921a"] = { common = "Пришло время тебе отправиться на поиски своей судьбы. Но чтобы подготовиться к встрече с миром за пределами наших зачарованных лесов, тебе нужно больше узнать о нашей недавней истории. Многое изменилось для нашего народа со времён битвы за гору Хиджал. Нордрассил ныне – лишь бледная тень того, чем он некогда был, его сила ушла на то, чтобы одолеть Архимонда и отбросить прочь Пылающий Легион... Тебе нужно исполнить важное поручение. Принеси мне воды из лунного колодца к северу от Альдрассила." },
    ["921c"] = { common = "Тебе уже довелось услышать первую часть истории о последствиях битвы за гору Хиджал, однако ещё многое нужно рассказать, и выполнение задания, данного мной тебе, будет продолжаться на протяжении всего твоего путешествия через Тельдрассил в Дарнасс." },
    ["922a"] = { male = "Не мог бы ты доставить один из тех ростков, что ты принёс мне, моему другу, Релиану Зелёному Костру? Он друид из Дарнасса. Когда мы в последний раз общались, он проявил интерес к моей работе с древесниками. У него самого кое-какие идеи есть, и он будет очень рад поработать с таким образцом. Благодарю тебя. Твоя помощь просто неоценима. Надеюсь, что однажды ты увидишь плоды моих трудов. Релиана обычно можно найти на какой-нибудь из дорожек анклава Кенария в Дарнассе, он любит там гулять.", female = "Не могла бы ты доставить один из тех ростков, что ты принесла мне, моему другу, Релиану Зелёному Костру? Он друид из Дарнасса. Когда мы в последний раз общались, он проявил интерес к моей работе с древесниками. У него самого кое-какие идеи есть, и он будет очень рад поработать с таким образцом. Благодарю тебя. Твоя помощь просто неоценима. Надеюсь, что однажды ты увидишь плоды моих трудов. Релиана обычно можно найти на какой-нибудь из дорожек анклава Кенария в Дарнассе, он любит там гулять." },
    ["922c"] = { common = "А, росток древесника? Я хотел попытаться сам вырастить древесника, чтобы помочь Деналану в его изысканиях. К сожалению, я выяснил, что множество древесников поражено порчей, и ростки таких существ также наследуют её от родителей. И не в моих силах это исправить. У Деналана великий талант работать со всем, что растёт. Если кто и найдёт исцеление для будущих древесников, то это он. Возможно, он – наша последняя надежда." },
    ["923a"] = { common = "Древесники становятся всё более злобными. Мы пытаемся найти источник этой беды, но пока... чтобы уберечь Тельдрассил, нам приходится уничтожать древесников, которым уже не поможешь. Те, что бродят вокруг Родникового озера на севере, поражены порчей сильнее всего. Их надо уничтожить! Уничтожь всех древесников, которых там найдёшь, и собери растущие на них мшистые опухоли. Принеси их мне, чтобы я мог их сжечь." },
    ["923c"] = { common = "Хорошая работа! Эти опухоли - симптом болезни древесников. Они наполнены ядом, от которого мы должны очистить наши новые земли. Я уничтожу эти опухоли. Благодарю тебя." },
    ["924a"] = { common = "Демоново семя – страшное оружие Пылающего Легиона. Оно хранится в пещере на Вершине Багрового Тумана, над демоническим алтарём Огня. Я подготовил камни силы, которые разорвут связь Семени с Легионом. Возьми камень со стола и возложи его на алтарь Огня на Вершине Багрового Тумана. Отправляйся на запад, а на развилке сверни на север. Вершина окажется по левую руку от тебя. Безопаснее всего подниматься по северному склону. Торопись: сила камня постепенно иссякает." },
    ["924c"] = { common = "Твоя цель достигнута. Тебе удалось уничтожить Демоново семя, как велел Нииру. Но это ещё не конец… После уничтожения Демонова семени по всему астралу пошли волны небывалой силы. Их почувствовала не только я. Об этом узнают те, чью игрушку мы сломали… Впрочем, невзирая на грядущие испытания, я хочу вручить тебе кое-что. Нииру велел дать это в уплату и поблагодарить тебя. Итак, я благодарю тебя." },
    ["927a"] = { common = "Сердце Черномшеца Злосмрадного поросло тёмным маслянистым мхом. Понять, что это сердце, можно лишь по тому, что оно медленно и ритмично пульсирует... Даже сейчас. Возможно, это заинтересует Деналана." },
    ["927c"] = { male = "...Это ещё что такое? Сердце древесника? Оно всё поросло вонючим мхом! Хорошо, что ты принёс его мне. Я исследую это сердце и, если удача повернётся ко мне лицом, выясню, что это за мох на нём.", female = "...Это ещё что такое? Сердце древесника? Оно всё поросло вонючим мхом! Хорошо, что ты принесла его мне. Я исследую это сердце и, если удача повернётся ко мне лицом, выясню, что это за мох на нём." },
    ["928a"] = { male = "Я мог бы поведать тебе ещё многое о лунных колодцах и о Тельдрассиле, однако тебе пора в путь. Коритрас Лунный Гнев ждёт тебя. Я перелил воду из фиала, принесённого тобой, в этот сосуд, чтобы ты отнёс его Коритрасу. Ты найдёшь Коритраса у лунного колодца в Доланааре. Иди из Тенистой долины по дороге, что на юге от Альдрассила, а когда она свернёт на запад, следуй по пути, мощенному булыжниками. И советую тебе не сходить с дороги, – в последнее время в лесу появились опасные существа.", female = "Я мог бы поведать тебе ещё многое о лунных колодцах и о Тельдрассиле, однако тебе пора в путь. Коритрас Лунный Гнев ждёт тебя. Я перелил воду из фиала, принесённого тобой, в этот сосуд, чтобы ты отнесла его Коритрасу. Ты найдёшь Коритраса у лунного колодца в Доланааре. Иди из Тенистой долины по дороге, что на юге от Альдрассила, а когда она свернёт на запад, следуй по пути, мощенному булыжниками. И советую тебе не сходить с дороги, – в последнее время в лесу появились опасные существа." },
    ["928c"] = { common = "А, понятно. Тебя послал Тенарон. Ну что ж, похоже, нам о многом нужно поговорить, многое сделать – но времени мало. Думаю, лучше не медлить и приступить к делу сейчас же." },
    ["929a"] = { common = "Сначала позволь поведать тебе, какая стоит перед тобой задача. Друиды Дарнасса пользуются водой из лунных колодцев Тельдрассила, и временами их колодцы надо пополнять. При помощи этих специально изготовленных фиалов ты сможешь набирать воду из лунных колодцев. Отнеси этот сосуд к лунному колодцу у деревни Звёздного Ветра на востоке и набери из него немного воды, а затем возвращайся ко мне. Когда ты выполнишь это задание, я продолжу свой рассказ с момента, на котором его прервал Тенарон..." },
    ["929c"] = { common = "После битвы за гору Хиджал мы не знали, что делать дальше. Нордрассил дымился, опалённый огнём, и наше бессмертие – сама сущность нашего бытия! – было утрачено. Именно в эту пору испытаний Предатель вырвался из заточения и исчез Шан'до Ярость Бури. Настали тёмные времена." },
    ["930a"] = { common = "Под ветками этого светящегося растения висит большой круглый плод. Вы уверены, что Деналану захочется его изучить." },
    ["930c"] = { male = "Ты нашёл его на Тельдрассиле? Как интересно... Такой необычный плод. Может, семена занесло издалека? Может, даже из Азерота! И что-то в нём есть такое... похоже, на него как-то странно повлияли почвы Тельдрассила. Спасибо тебе. Теперь извини, мне нужно попристальнее его поизучать...", female = "Ты нашла его на Тельдрассиле? Как интересно... Такой необычный плод. Может, семена занесло издалека? Может, даже из Азерота! И что-то в нём есть такое... похоже, на него как-то странно повлияли почвы Тельдрассила. Спасибо тебе. Теперь извини, мне нужно попристальнее его поизучать..." },
    ["931a"] = { common = "Росток этого дерева мерцает в сумраке леса, распространяя вокруг себя изменчивое, пульсирующее свечение. Наверное. Деналана интересует именно такой образец." },
    ["931c"] = { male = "Где ты это нашёл? Я не видел таких растений с тех пор, как жил на Болоте Печали. А это было много десятилетий назад! Удивительно, как он попал в Тельдрассил. Да ещё вырос до такой величины! Спасибо тебе. Прости мою немногословность, но мне не терпится провести кое-какие опыты с этим ростком...", female = "Где ты это нашла? Я не видел таких растений с тех пор, как жил на Болоте Печали. А это было много десятилетий назад! Удивительно, как он попал в Тельдрассил. Да ещё вырос до такой величины! Спасибо тебе. Прости мою немногословность, но мне не терпится провести кое-какие опыты с этим ростком..." },
    ["932a"] = { common = "Должен предупредить тебя, что это должно остаться только между нами. Сатиры и так уже причиняют нам немало неприятностей, а этот уж слишком близко к нашему дому рыщет. Его зовут лорд Меленас. Он живёт по соседству, в Пещере Бесов, где собрал шайку греллей-воинов. Его сердце чернее ночи, а замыслы – омерзительны. Найди его в пещере, прямо к северу отсюда, и принеси мне его голову!" },
    ["932c"] = { common = "Теперь, когда лорд Меленас упокоился навек, я могу заняться и другими делами. Прими мою благодарность." },
    ["933a"] = { common = "К юго-востоку от входа в Дарнасс, на берегу Арлитириэнских прудов есть ещё один лунный колодец. Стражам трудно наблюдать за этими местами из-за всё учащающихся нападений и всё большей злобности фурболгов из племени Кривой Сосны. Будь начеку во время поисков колодца и держи оружие наготове." },
    ["933c"] = { common = "Шан'до Ярость Бури так и не вернулся, и новостей про него до сих пор не поступало. Друиды были в смятении. После пропажи Малфуриона верховный друид Фэндрал Олений Шлем взял на себя руководство друидами, убедив Круг Древних на Тёмных Берегах, что нашему народу пора снова заполучить былую мощь и бессмертие. С одобрения Круга Олений Шлем и самые могучие друиды вырастили Тельдрассил, новое Древо Жизни." },
    ["934a"] = { common = "Но не всё было ладно с Тельдрассилом. Олений Шлем долго лелеял надежду вырастить новое Древо жизни и даже тщательно спланировал это мероприятие. Но была одна небольшая проблема, с которой можно связать большинство бед Тельдрассила. Однако, пока я об этом говорить не буду. Тебе нужно посетить последний лунный колодец, к северо-западу от Поляны Оракула. Под ветвями Древа-оракула находится первый и самый могучий из наших колодцев. Набери воды из него и возвращайся ко мне." },
    ["934c"] = { common = "Находиться в присутствии Древа-оракула... это всё равно что увидеть воплощённую мудрость. Позволь мне продолжить... Тельдрассил рос, и верховный друид обратился за благословением к драконам, ведь именно они благословили Нордрассил в древние времена. Однако Ноздорму, Повелитель Времени, отказал друиду, упрекнув его в самонадеянности. Алекстраза также отказала Оленьему Шлему, а без её благословения рост Тельдрассила стал непредсказуем, и в нём обнаружились изъяны..." },
    ["935a"] = { male = "Без благословения Алекстразы Хранительницы Жизни и Ноздорму Хозяина Времени Тельдрассил вырос с изъяном. Странные твари лезут из-под его корней, и бешеные фурболги нападают на проходящих мимо путников. Могу только надеяться, что верховный друид быстро найдёт то, что ищет. Я наполню все принесённые тобой фиалы, чтобы ты доставил их в Дарнасс. Отнеси их к Фэндралу Оленьему Шлему, ты найдёшь его в роще друидов.", female = "Без благословения Алекстразы Хранительницы Жизни и Ноздорму Хозяина Времени Тельдрассил вырос с изъяном. Странные твари лезут из-под его корней, и бешеные фурболги нападают на проходящих мимо путников. Могу только надеяться, что верховный друид быстро найдёт то, что ищет. Я наполню все принесённые тобой фиалы, чтобы ты доставила их в Дарнасс. Отнеси их к Фэндралу Оленьему Шлему, ты найдёшь его в роще друидов." },
    ["935c"] = { common = "О, да, это та вода, о которой я просил. Тенарон и Коритрас улучили минутку передать её... хотя гонца, может, и не самого надёжного выбрали... хм-м. Однако теперь я могу вернуться к работе. Бремя бед Тельдрассила тяжким гнётом лежит на моих плечах. Но скоро я избавлюсь от этого ярма. Вот, возьми. Может, тебе пригодится." },
    ["936a"] = { male = "Извини, герой, можно тебя на минутку? Кругу Кенария в Громовом Утёсе требуются такие закалённые путешественники, как ты, для участия в чрезвычайно важном исследовании. Подробностей я не знаю, но могу сказать, что возглавляет этот проект Хамуул Рунический Тотэм. Если тебя это интересует, отправляйся в Громовый Утёс на Вершину Старейшин и поговори с самим Хамуулом.", female = "Извини, героиня, можно тебя на минутку? Кругу Кенария в Громовом Утёсе требуются такие закалённые путешественники, как ты, для участия в чрезвычайно важном исследовании. Подробностей я не знаю, но могу сказать, что возглавляет этот проект Хамуул Рунический Тотэм. Если тебя это интересует, отправляйся в Громовый Утёс на Вершину Старейшин и поговори с самим Хамуулом." },
    ["936c"] = { male = "Привет тебе, герой! Рад, что ты хочешь помочь нам в наших исследованиях. Дел у нас много, и я оказал бы тебе дурную услугу, если бы не предупредил, что работа опасная. Надеюсь, тебя это не отпугнёт... Впрочем, судя по твоему виду, тебе не впервой встречаться с опасностями.", female = "Привет тебе, героиня! Рад, что ты хочешь помочь нам в наших исследованиях. Дел у нас много, и я оказал бы тебе дурную услугу, если бы не предупредил, что работа опасная. Надеюсь, тебя это не отпугнёт... Впрочем, судя по твоему виду, тебе не впервой встречаться с опасностями." },
    ["937a"] = { common = "Меня отправили сюда с небольшим отрядом Часовых для защиты древа-оракула от гарпий, что устроили себе гнёзда по всей поляне. Мы стараемся потихоньку вытеснить их отсюда. Когда древо-оракул попыталось послать гонца в Дарнасс, на него напала стая гарпий и растерзала. Если ты считаешь, что это задание тебе по плечу, иди к их гнездовью и принеси их пояса в доказательство своего подвига." },
    ["937c"] = { male = "Ты столького достиг за такое короткое время! Это очень впечатляет Хотелось бы мне попросить тебя задержаться здесь и помочь мне по службе... но я понимаю, что тебя ждут великие дела. Я заметила, что Древо-оракул только что сбросило кусок коры. Несомненно, оно хочет, чтобы ты выполнил какое-то поручение для него. Поговори с ним.", female = "Ты столького достигла за такое короткое время! Это очень впечатляет Хотелось бы мне попросить тебя задержаться здесь и помочь мне по службе... но я понимаю, что тебя ждут великие дела. Я заметила, что Древо-оракул только что сбросило кусок коры. Несомненно, оно хочет, чтобы ты выполнила какое-то поручение для него. Поговори с ним." },
    ["938a"] = { common = "Мех самки саблезуба имеет характерный серый цвет, сливающийся с фоном окружающего леса. Вы видите, что она сильно пострадала: глубокие рваные раны видны на её спине и брюхе. Она смотрит на вас, и в её голубых глазах читается глубокая мудрость. Похоже, она хочет следовать за вами." },
    ["938c"] = { common = "О, благодарю тебя! Я так боялась, что уж больше не увижу мою Туманну, скорбела всем сердцем о её гибели, о том, что навек разлучилась с моей верной спутницей... Я в неоплатном долгу перед тобой! Прими мою вечную благодарность." },
    ["939a"] = { common = "Вы рассматриваете простую деревянную флейту, которую подобрали, сразив Ксаварика. Узловатое дерево кажется твёрдым, но когда вы вертите её в руках, все спирали и полоски на флейте вдруг начинают вращаться и двигаться. Вас внезапно охватывает нехорошее ощущение… Вы встряхиваетесь, уверенные, что это просто игра воображения. Но, возможно, у других сатиров найдётся разгадка тайны вашей находки. Отнесите её друиду Эридане Грусти Ветра, которая живёт в южной части Осквернённого леса." },
    ["939c"] = { common = "Я чувствую страдание древних, путник… Поведения этих предметов невыносимы…" },
    ["940a"] = { common = "Шум леса донёс до меня весть о твоих подвигах. Когда я ощутила, что гарпии покинули свои гнездовья, великий покой распространился по лесу и его обитатели снова ощутили себя в безопасности. Я боялась посылать очередное сообщение верховному друиду, но теперь я знаю, что ты доставишь его ему в целости и сохранности. Передай ему письмо и знай, что лес будет охранять тебя по дороге в каменные джунгли." },
    ["940c"] = { male = "Я-то думал, почему Древо-оракул так долго не связывается со мной... Сдаётся мне, что как только мы решаем одну проблему, немедленно возникает другая, ещё более сложная. Боюсь, мне никогда не закончить мои труды с Тельдрассилом и мы так и не вернём себе бессмертие. Тем не менее, ты славно справился с заданием Древа-оракула, и за усердие тебе положена награда.", female = "Я-то думал, почему Древо-оракул так долго не связывается со мной... Сдаётся мне, что как только мы решаем одну проблему, немедленно возникает другая, ещё более сложная. Боюсь, мне никогда не закончить мои труды с Тельдрассилом и мы так и не вернём себе бессмертие. Тем не менее, ты славно справилась с заданием Древа-оракула, и за усердие тебе положена награда." },
    ["941a"] = { common = "Я удалил этот смрадный мох с сердца, но оно всё ещё остаётся запятнанным... Попытайся посадить его в мою кадку. Она наполнена плодородной землёй, которая может очистить и исцелить это сердце." },
    ["941c"] = { common = "Вы сажаете сердце в кадку, и оно быстро в неё зарывается! Через несколько секунд оно снова выкапывается из земли – уже очищенное. Оно тихонько пульсирует... и вам хочется взять его в руки." },
    ["942a"] = { common = "Эта окаменелость поразительно похожа на другую, которую я однажды видел в Стальгорне. Геолог по имени Бутылопуз приносил её на ежегодную конференцию Лиги Исследователей. Он был уверен, что в этой окаменелости скрыта мощь, которую можно каким-то образом высвободить. Последнее, что я слышал, что Бутылопуз обосновался в таверне \"Большая вода\" и ждёт, чтобы его сопроводили к раскопу Вельгара. Найдите его и покажите ему окаменелость, найденную Сомнамбулером. Может быть, он сумеет раскрыть секреты прошлого. Корабль в Менетилов отходит из Аубердина." },
    ["942c"] = { common = "О боги! Так вы говорите, эта вещь происходит из далёких земель Калимдора? Поразительно! Просто поразительно!" },
    ["943a"] = { common = "Геолог Вельгар, который сейчас находится на раскопе в Болотине, держит окаменелость у себя. Когда я обнаружил камень Релу, то был уверен, что это ключ к тайне окаменелости. Пока я шёл по дороге к Вельгару, на меня напали ящеры, и реликвия пропала. Не знаю, какая из крапчатых тварей проглотила её, но если вам удастся её вернуть, я смогу высвободить силу этих артефактов. Принесите мне и камень Релу, и окаменелость, хранящуюся у Вельгара." },
    ["943c"] = { common = "Великолепно! Теперь посмотрим, смогу ли я использовать камень, чтобы распознать силы, скрытые в окаменелостях." },
    ["944a"] = { common = "Очень странно, что наги появились здесь, на Тёмных берегах. Но ещё страннее – клан Сумеречного Молота. Они поклоняются старым, очень старым богам этой земли. Богам, давным-давно низвергнутым. Меч Властителя, что к югу отсюда, – место, где пал один из этих древних богов. Пойди туда и поищи других культистов Сумеречного Молота. Возьми этот фиал виденья. Используй его для создания гадальной чаши, когда разведаешь всё у Меча Властителя. Посредством этой чаши поговори со мной." },
    ["944c"] = { male = "Так ты обнаружил клан Сумеречного Молота у Меча Властителя? Плохо. Древний бог, пронзённый мечом, давно мёртв, но это не значит, что исчезли и остатки его могущества. Должно быть, клан Сумеречного Молота пытается найти его силу.", female = "Так ты обнаружила клан Сумеречного Молота у Меча Властителя? Плохо. Древний бог, пронзённый мечом, давно мёртв, но это не значит, что исчезли и остатки его могущества. Должно быть, клан Сумеречного Молота пытается найти его силу." },
    ["945a"] = { common = "Помогите! Я бродила у Меча Властителя, как вдруг меня окружили эти жуткие культисты. Счастье, что я умею отлично прятаться!!! Можете помочь мне отсюда выбраться? И ещё, мне нужно будет сообщить моей сестре Тересиль, что я в порядке. Она в Ясеневом лесу, к югу отсюда, у святилища Эссины." },
    ["945c"] = { common = "Моя сестра была – где? Тирелин любит бродить по всяким местам, но всё-таки! Это же очень далеко, да и Меч Властителя – вовсе не безопасное место... Ну, спасибо вам. С вашей стороны было очень любезно сообщить мне, что с ней всё в порядке." },
    ["947a"] = { common = "Я тут составляю одно зелье, для которого нужны редкие грибы, растущие в одной-единственной пещере. Пещера эта находится за водопадом Скалистый, к востоку и чуть севернее в горах. Я бы и сам туда пошёл, но в Роще Древних мне порекомендовали держаться подальше от того места. Наши почтенные союзники чувствуют, что в этой пещере таится какое-то незнакомое зло. Прошу вас, соберите для меня эти грибы. А в процессе заодно приглядитесь: может быть, вы сможете подтвердить опасения Дерев." },
    ["947c"] = { common = "Большое вам спасибо. Это отличные экземпляры! Кстати, когда вы были у водопада Скалистый, заметили ли что-нибудь, что могло подтвердить опасения Дерев? Дерева мудры, но я надеялся, что на сей раз они ошибаются." },
    ["948a"] = { common = "Ону, Древо Мудрости из Рощи Древних, знает о вашем путешествии к Скалистому водопаду и хочет поговорить с вами. Роща расположена к югу отсюда, у подножья гор. Дерева терпеливы и мудры. Но если Ону ищет вашего совета касательно того, что вы видели у водопадов, то, боюсь, дело срочное." },
    ["948c"] = { common = "Ты здесь. Хорошо. Нам есть... что обсудить. Тебе и мне." },
    ["949a"] = { common = "Что замышляет клан Сумеречного Молота у Меча Властителя, неизвестно. Но наверняка что-то недоброе Обыщите их лагерь у Меча Властителя... Ищите то, что может помочь нам понять их намерения. Ведь мы должны узнать об их целях раньше, чем они выработают план действий." },
    ["949c"] = { common = "Книга написана от руки на древнем языке и прекрасно иллюстрирована." },
    ["950a"] = { common = "Вглядываясь в сумеречный фолиант, можно сойти с ума. Буквы начинают плыть и плясать перед глазами даже после мельком брошенного взгляда, и некогда прекрасный орнамент принимает гротескные формы. Вырвать одну страницу с безумными каракулями – вот и всё, что вам удаётся сделать, пока вы не потеряли сознание." },
    ["950c"] = { common = "Неизученная первобытная магия окружает этот пергамент с письменами. Я чувствую, что над ним потрудились древние силы. Будем надеяться, мы сумеем раскрыть цель деятельности клана Сумеречного Молота на Тёмном Берегу." },
    ["951a"] = { male = "Пергамент, который ты обнаружил близ Меча Властителя, – страница древнего текста... написанная эльфами! Она отягощена проклятиями и загрязнена порчей клана Сумеречного Молота, но похоже, что служители культа используют древнюю эльфийскую магию для того, чтобы вернуть в наш мир своих древних хозяев. Направляйся к руинам Матистры, расположенным к северо-востоку отсюда, и поищи в траве и средь разбитых камней древние реликвии. Изучая их, мы сможем выяснить, каким образом в клане Сумеречного Молота намерены использовать магию эльфов.", female = "Пергамент, который ты обнаружила близ Меча Властителя, – страница древнего текста... написанная эльфами! Она отягощена проклятиями и загрязнена порчей клана Сумеречного Молота, но похоже, что служители культа используют древнюю эльфийскую магию для того, чтобы вернуть в наш мир своих древних хозяев. Направляйся к руинам Матистры, расположенным к северо-востоку отсюда, и поищи в траве и средь разбитых камней древние реликвии. Изучая их, мы сможем выяснить, каким образом в клане Сумеречного Молота намерены использовать магию эльфов." },
    ["951c"] = { common = "Благодарю тебя. Эти реликвии относятся к поре расцвета Матистры. Этот некогда могучий оплот эльфов давно разрушен, но остатки магии ещё попадаются в руинах. Будем надеяться, что нам удастся раскрыть тайны этого места раньше, чем это сделают наши враги. Будь настороже." },
    ["952a"] = { common = "Если уж у тебя нашлось время передать письмо для Древа-оракула, то, мне кажется, для тебя не составит труда отнести донесение в Рощу Древних на Тёмный Берег, прямо к югу от Аубердина. Ты наверняка сможешь свободно добраться туда на гиппогрифе, я уверен, что ты сумеешь это сделать. Отнеси это Ону, Древу Мудрости. Он ждёт от меня вести, точно так же, как я ждал вести с Поляны Оракула." },
    ["952c"] = { common = "А. Спасибо, Каззакс. Тем не менее, это странно. Верховный друид всегда так торопится. Лес знает, что всему своё время. Шан'до Ярость Бури это понимал." },
    ["953a"] = { common = "К востоку отсюда находятся руины Амет'Арана. Сейчас их населяют неупокоенные духи высокорожденных, некогда живших в его стенах, но когда-то Амет'Аран был местом, где слуги Азшары свободно практиковались в своей могучей магии. Меня послали исследовать эти руины, и я наткнулась на две большие таблички, на которых была неразборчиво начертана история Амет'Арана и его падения. Пока я пыталась прочесть руны, на меня напали призраки, и я сбежала. Пожалуйста, если можете, отправляйтесь в руины и расшифруйте таблички вместо меня." },
    ["953c"] = { common = "У нас очень немного записей, относящихся ко времени Войны Древних, а особенно – к периоду разрушения Источника Вечности. Что неудивительно, если вспомнить о том, какие ужасные события и катаклизмы тогда происходили. Спасибо вам. С вашей помощью моя работа здесь окончена, и я смогу представить Кругу Древних полный доклад." },
    ["954a"] = { common = "Руины Башал'Арана, расположенные к востоку отсюда, населены демоническими служителями зла. Злые духи и сатиры, обосновавшиеся там, питаются магическими энергиями Башал'Арана, и силы их растут от постоянной подпитки энергией. Но при этом я заметил, что к одному святилищу они не приближаются. На западной стороне руин, на вершине небольшого утёса, распространяется странное синее свечение... Там и должно быть объяснение нежеланию демонов приближаться к этому месту. Я хотел бы, чтобы вы его исследовали." },
    ["954c"] = { male = "Ахх... Кому ж моя скромная персона обязана столь лестной для меня встречей с такой личностью, как вы, любезный герой? На самом деле, не желая обижать моих гостеприимных хозяев – греллей и сатиров – это многое говорит о моих нынешних компаньонах, раз уж ваше присутствие может быть расценено как улучшение... Но, прошу вас, пусть мой грубый язык не заставит вас уйти. Очень уж много лет, а то и десятилетий, прошло с тех пор, как у меня была приличная компания.", female = "Ахх... Кому ж моя скромная персона обязана столь лестной для меня встречей с такой личностью, как вы, любезная героиня? На самом деле, не желая обижать моих гостеприимных хозяев – греллей и сатиров – это многое говорит о моих нынешних компаньонах, раз уж ваше присутствие может быть расценено как улучшение... Но, прошу вас, пусть мой грубый язык не заставит вас уйти. Очень уж много лет, а то и десятилетий, прошло с тех пор, как у меня была приличная компания." },
    ["955a"] = { male = "Если бы я решил поведать тебе о своей жизни, не сомневаюсь, что повествование превзошло бы пределы твоего терпения. Скажем так: в моей долгой жизни было много страданий, и существование в этом призрачном обличье, быть может, самая ужасная из моих мук. Хотя мои слова могут показаться лицемерием, я уверяю тебя, что был бы невероятно благодарен, если бы ты помог мне найти то, что держит меня здесь. Некая печать связывает меня, и, изучая серьги злых духов и греллей, я могу напасть на её след.", female = "Если бы я решил поведать тебе о своей жизни, не сомневаюсь, что повествование превзошло бы пределы твоего терпения. Скажем так: в моей долгой жизни было много страданий, и существование в этом призрачном обличье, быть может, самая ужасная из моих мук. Хотя мои слова могут показаться лицемерием, я уверяю тебя, что был бы невероятно благодарен, если бы ты помогла мне найти то, что держит меня здесь. Некая печать связывает меня, и, изучая серьги злых духов и греллей, я могу напасть на её след." },
    ["955c"] = { common = "И правда... Грелли Башал'Арана не владеют тем, что я ищу... Однако недавно они были в контакте с этим. Недавно... Я имею в виду по меркам твоего времени, не моего. Для меня \"недавно\" простирается глубоко в прошлое, почти что в другую эру..." },
    ["956a"] = { common = "Если грелли вступали в тесный контакт с той силой, что запечатывает мою вечную тюрьму, то, подозреваю, я знаю, в чём дело. Несомнено эта печать находится во владении сатира, предводительствующего ими. Я убеждён, что моя догадка верна. Она наверняка у одного из сатиров. Если ты сможешь её добыть, то ты почти откроешь дверь моей темницы. Мне не сдержать слёз..." },
    ["956c"] = { common = "Мне трудно поверить, что вещь, которую я сейчас держу в руках, так долго держала меня самого... Не будем тратить времени. Когда печать будет уничтожена, я снова вольно смогу бродить по лесам." },
    ["957a"] = { common = "Эта печать, заточившая меня, некогда была изготовлена руками одного из самых могущественных высокорожденных. В Амет'Аране – точно таких же руинах к югу отсюда – до сих пор горит древний синий огонь. В этом огне печать может быть уничтожена. Будь осторожнее в тех руинах..." },
    ["957c"] = { common = "Я свободен! Я могу собственными глазами видеть, какие изменения произошли с нашим миром... Я узнаю только отдельные фрагменты. Подумать только, что когда я в последний раз гулял на свободе, ещё существовал Источник и высокорожденные держали совет с Азшарой, нашей любимой королевой. Я чувствую, что мой тюремщик, мой бывший хозяин, Атрикус, ещё жив... Моё осознание безнадёжности вскоре сменится мыслями о мести." },
    ["958a"] = { male = "герой. Вот задание, которое я вам поручаю. Видели ли вы руины Амет'Арана? Если нет – их можно найти на востоке от главной дороги, несколько к югу отсюда. Когда-то Амет'Аран служил домом для многих могущественных высокорожденных, а теперь это – памятник разрушению, совершённому их жалкими подражателями. Мне говорили часовые, что духи высокорожденных по-прежнему обитают там и что они используют свои древние магические приспособления. Эти реликвии нужно конфисковать, чтобы мы могли их уничтожить.", female = "героиня. Вот задание, которое я вам поручаю. Видели ли вы руины Амет'Арана? Если нет – их можно найти на востоке от главной дороги, несколько к югу отсюда. Когда-то Амет'Аран служил домом для многих могущественных высокорожденных, а теперь это – памятник разрушению, совершённому их жалкими подражателями. Мне говорили часовые, что духи высокорожденных по-прежнему обитают там и что они используют свои древние магические приспособления. Эти реликвии нужно конфисковать, чтобы мы могли их уничтожить." },
    ["958c"] = { common = "Хотя это, безусловно, лишь игра моего воображения, я чувствую себя так, будто бы ощущаю в этих реликвиях ядовитое дыхание магии высокорожденных. Я их уничтожу, чтобы давно уснувшее зло больше никогда не пробудилось." },
    ["959a"] = { common = "Ой! Как видишь, у меня сегодня приключилась неприятность! Утром из Пиратской бухты пришла поставка. И какая! Никогда не видел столько ящиков. Я хотел побыстрее закончить, поэтому поднимал больше, чем следовало. В конце концов всё рухнуло на землю. Не успел я оглянуться, как эта тварь, Безумный Магглиш, схватил бутылку портвейна девяносто девять-летней выдержки и бросился наутёк. Я гнался за ним до самых Пещер Стенаний, но внутрь я не ходок. Может, тебе хватит пороху, чтобы найти его?" },
    ["959c"] = { common = "Великолепно! И ведь меня едва не уволили! Теперь надо поскорее отнести подарок Газлоу. Спасибо. Отличная работа!" },
    ["962a"] = { common = "Королевское фармацевтическое общество из великого Подгорода Лордерона направило меня сюда с очень необычной целью. Возможно, вы сумеете помочь мне, а, стало быть, и Тёмной Госпоже в трудах на благо Отрёкшихся. Не так давно я изучала редкий образец флоры под названием змеецвет. Я уверена, что в большом количестве это растение таит в себе великие возможности. Увы, змеецвет можно найти только в самых тёмных закоулках Пещер Стенаний, опасной системе подземелий в Степях." },
    ["962c"] = { common = "Ах, замечательные экземпляры! Вы хорошо поработали." },
    ["963a"] = { common = "После битв за Источник Вечности я узнал, что Амет'Аран разрушен, жители его погибли – в том числе и моя возлюбленная Анайя. Я никогда не думал, что и через тысячи лет воспоминания об Анайе будут тревожить мои сны. Бродя в помрачении рассудка по лесам на Тёмном Берегу, я очутился в руинах Амет'Арана... где и увидел неупокоенный дух моей любимой. Её нужно освободить, но у меня просто рука не поднимается. Нужно уничтожить её призрак." },
    ["963c"] = { common = "Благодарю тебя. Может быть, было бы лучше... если бы я сам это сделал. Но даже после прошедших тысячелетий у меня нет сил поднять руку на свою возлюбленную. Пожалуйста, оставь меня наедине с моим горем..." },
    ["964a"] = { common = "Чтобы отомкнуть двери Некроситета необходим Костяной ключ. Его делают из остатков скелета — точнее, нескольких скелетов — и вплавляют в прочнейший из металлов в подходящей форме. Чтобы ключ заработал, необходим перстень власти одного из тех существ, что могут открыть портал данной им силой. Но не будем отвлекаться, для начала нам понадобятся фрагменты скелетов. Для этой цели подойдут скелеты внутри Андорала, да и те, что снаружи." },
    ["964c"] = { common = "Отличная работа, путник! Теперь моя очередь. Я обработаю их специальным веществом, которое поможет пережить им процесс ковки. Следующим шагом будет получение соответственной пресс-формы для ключа. Я знаю одного гоблина в Танарисе, который должен нам помочь. Ранее, он делал подобные формы для таких же ужасных предметов. Но, как и все гоблины, за свою работу он потребует высокую плату." },
    ["965a"] = { male = "Привет тебе, юный герой. Меня зовут Элисса Звёздный Ветер, и моя задача – защищать Аубердин от всякого вреда. С этой целью я послала Балтула Удар Тени вести наблюдение за странными событиями, происходящими близ башни Алталакса к северо-востоку отсюда. Но он уже давно должен был вернуться. Боюсь, что он столкнулся в лесу с какой-то непредвиденной опасностью. Я была бы тебе очень благодарна, если бы ты смог найти его и удостовериться, что с ним всё в порядке.", female = "Привет тебе, юная героиня. Меня зовут Элисса Звёздный Ветер, и моя задача – защищать Аубердин от всякого вреда. С этой целью я послала Балтула Удар Тени вести наблюдение за странными событиями, происходящими близ башни Алталакса к северо-востоку отсюда. Но он уже давно должен был вернуться. Боюсь, что он столкнулся в лесу с какой-то непредвиденной опасностью. Я была бы тебе очень благодарна, если бы ты смогла найти его и удостовериться, что с ним всё в порядке." },
    ["965c"] = { common = "Тебя прислала Элисса? Это хорошо. У меня есть для неё тревожные вести, но не было возможности передать их ей." },
    ["966a"] = { common = "Группа чернокнижников обосновалась вокруг и внутри башни. Я хотел было вернуться в Аубердин и доложить Элиссе раньше, но побоялся, что могу что-то пропустить, пока буду отсутствовать. Делгрен подозревал, что подобная компания может собираться у башни, но не знал, зачем. Несколько обрывков свитков пергамента, которые носят с собой чернокнижники, попали в мои руки, но мне нужно знать больше, чтобы разгадать эту головоломку. Однако я предостерегаю вас от попытки вторгнуться в саму башню: чернокнижники, засевшие там, гораздо сильнее!" },
    ["966c"] = { common = "Большое спасибо. Это должно пролить некоторый свет на то, чем занимается это сборище чернокнижников... Хмм... Клан Тёмной Нити... Никогда раньше не слышал о такой группе. Пока у нас нет никаких сведений об их истории, практически невозможно сказать, в чём могут заключаться их планы. Больше нельзя тянуть. Нужно немедленно предупредить Делгрена." },
    ["967a"] = { common = "Мой хозяин, Делгрен Очиститель – паладин, любезно предоставивший свою помощь в защите наших лесов от сил демонов и нежити. Он многое поведал мне о Божественном Свете и воинском искусстве. Делгрен должен немедленно узнать о деятельности клана. Вы найдёте его далеко на юге отсюда, на Заставе Мейстры в Ясеневом лесу. Поторопитесь – я боюсь, что угроза клана Тёмной Нити растёт с каждым часом." },
    ["967c"] = { male = "Если позволите, я вам скажу: слишком уж вы хорошо экипированы для простого посланца, не так ли? Предполагаю, Балтул хотел быть уверенным, что его письмо действительно попадёт мне в руки. Посмотрим, что он там пишет... Да, это тревожные новости. Когда обнаруживаются силы демонов или нежити, я помогаю часовым уничтожить их. Вначале мне были непривычны манеры ночных эльфов, но постепенно я стал в высшей степени уважать их как союзников.", female = "Если позволите, я вам скажу: слишком уж вы хорошо экипированы для простой посланницы, не так ли? Предполагаю, Балтул хотел быть уверенным, что его письмо действительно попадёт мне в руки. Посмотрим, что он там пишет... Да, это тревожные новости. Когда обнаруживаются силы демонов или нежити, я помогаю часовым уничтожить их. Вначале мне были непривычны манеры ночных эльфов, но постепенно я стал в высшей степени уважать их как союзников." },
    ["968a"] = { common = "Хотя книга ужасно истрёпана и исцарапана, её название на обложке всё же можно разобрать: \"Подземные Силы\". В книге перечисляются непроизносимые имена со зловещими титулами, способами почитания и предпочтительными жертвоприношениями... И среди этих жертвоприношений числятся живые разумные создания. На внутренней стороне обложки написано: \"Руны и Жребии Костохвата, Заброшенный грот, Стальгорн. Владелец: Геррик Костохват\". Если Костохват торгует подобными книгами, может быть, он выкупит эту?" },
    ["968c"] = { male = "А, экземпляр \"Подземных сил\". Интересный текст, да уж. А кое-кто найдёт его и полезным тоже... Но эта книга в ужасном состоянии. И поглядите-ка! Заметки на полях – почти на каждой странице! Хм... Я помню этот экземпляр. Я продал его Болгару в прошлом году. Вы его... его друг? Да, должно быть, так. У вас в глазах такой же огонь горит! Ну, по определению, друг Болгара – мой друг. А мы должны поддерживать близких людей, правда?", female = "А, экземпляр \"Подземных сил\". Интересный текст, да уж. А кое-кто найдёт его и полезным тоже... Но эта книга в ужасном состоянии. И поглядите-ка! Заметки на полях – почти на каждой странице! Хм... Я помню этот экземпляр. Я продал его Болгару в прошлом году. Вы его... его подруга? Да, должно быть, так. У вас в глазах такой же огонь горит! Ну, по определению, друг Болгара – мой друг. А мы должны поддерживать близких людей, правда?" },
    ["969a"] = { common = "Ах, одного взгляда на тебя достаточно, чтобы сказать: ты захочешь себе счастливый оберег. Мау'ари всегда всё знает! На юг пойди — найдёшь ущелье, а в нём гигантов, сделанных из кусков льда. Кристаллы можно отобрать у гигантов, но можешь собирать их и сам в ущелье. Эти кристаллы имеют отличную отражающую способность. Принеси мне десять кристаллов великанов Ледяного Молота, и счастливый оберег станет твоим." },
    ["969c"] = { common = "Да, конечно… Я сделаю для тебя талисман. Только подожди секундочку." },
    ["970a"] = { common = "Письмо Балтула приводит меня в ужас. Этот клан Тёмной Нити – сущее бельмо у меня на глазу, и его надо устранить! Мне приходилось иметь дело с мерзавцами из Тёмной Нити к северо-востоку отсюда в Ордиль-Аране. У одного из них есть самоцвет Души, в котором, как я думаю, заключается секрет силы клана. Принеси его мне, а уж я сумею разгадать его тайну." },
    ["970c"] = { common = "Хмм, этот самоцвет Души наполнен какой-то тёмной магией. Давай-ка посмотрим, что в нём таится..." },
    ["971a"] = { common = "Насколько вам известно, я собираю знания. Древние знания. Могучие знания. Знания, что отворяют пути, знания, что могут пробудить Тех-Что-Спят. Ходят слухи о старинном манускрипте Лоргалиса, будто бы он покоится в Непроглядной Пучине Ясеневого леса. Некогда там жили эльфы, но они давно уже мертвы. Эльфы эти обладали великим знанием, до того как их город превратился в руины. Найдите манускрипт в Непроглядной Пучине Сделайте это, и я не забуду вашей услуги. Даже после... скончания дней." },
    ["971c"] = { common = "Вы нашли манускрипт! Что за радостный день! Мы сделаем с него копии и распространим, и древнее знание Лоргалиса станет достоянием наших братьев и сестёр! Вы даже не понимаете, какую услугу нам оказали. Но я надеюсь, что этот дар покажет вам всю глубину нашей признательности нашим союзникам." },
    ["973a"] = { common = "Илкруд Магтрулл. Да, я знаю о нём. Это могучий орочий чернокнижник, который поселился в Святилище Огненной Расщелины, месте великого зла на юго-западе Ясеневого леса. Доныне он был не более чем досадной помехой, потому я и не трогал его, но, похоже, пришла пора с ним разобраться." },
    ["973c"] = { male = "Сегодня ты сделал большое дело. Гордись – ты сразил могущественного чернокнижника. А теперь посмотрим, что сказано в записях Илкруда.", female = "Сегодня ты сделала большое дело. Гордись – ты сразила могущественного чернокнижника. А теперь посмотрим, что сказано в записях Илкруда." },
    ["974a"] = { common = "Эти горячие источники всегда были для меня загадкой! Откуда берётся жар? Если учесть, что источники расположены совсем недалеко от Вулкана Огненного Венца, можно предположить, что их подогревает вулкан. Я разработал термометр, чтобы измерять температуру вулкана, и теперь хочу выяснить, в какой точке она наиболее высока. Термометр даёт результаты по шкале Кракленгейта. Вот, держи, отправляйся на хребет и выясни, где там точка с самой высокой температурой!" },
    ["974c"] = { common = "Да, корреляция температур вулкана и горячих источников очевидна. Конечно, надо бы ещё раз проверить правильность уравнений, однако создаётся впечатление, что расстояние и температура… Хмм…" },
    ["975a"] = { common = "А теперь, прежде чем я дам тебе этот вот оберег, объясню, как им пользоваться. Если он у тебя с собой, окажется, что определённые предметы будут в добыче с тех созданий, с которыми ты бой вести будешь. А если нет, то и предметов не найдёшь. Понятно? Ты узнаешь их по имени — они называются э'ко. Если найдёшь такие — приноси Мау'ари, она поможет тебе найти им применение. Постой-ка тут, пока я твой оберег доделаю." },
    ["975c"] = { common = "Вот он, путник. И помни, он повышает твою удачу!" },
    ["976a"] = { common = "Делгрен попросил меня доставить письма и припасы часовому Звёздный Ветер в Аубердин, но мне очень не хочется ехать в одиночку. В лесу опасные враги, а я не хочу, чтобы эти припасы и информация попали не в те руки. Если ты с остальными согласитесь охранять меня, то я смогу уехать прямо сейчас. Под вашей защитой я точно доставлю всё это в Аубердин." },
    ["976c"] = { male = "Ты сегодня славно поработал, герой. То, что мы отослали в Аубердин, срочно необходимо для отражения тёмной угрозы, наводнившей лес. Прими это вместе с моей сердечной благодарностью.", female = "Ты сегодня славно поработала, героиня. То, что мы отослали в Аубердин, срочно необходимо для отражения тёмной угрозы, наводнившей лес. Прими это вместе с моей сердечной благодарностью." },
    ["977a"] = { common = "Теперь, когда мне есть чем прикрыть механические движущиеся части, мне нужна только одна вещь. Ну, точнее, две. Два рога! Самые большие рога — у патриархов и матриархов клана, так что, естественно, именно их-то я и хочу. Эта разновидность йети обитает в пещере к юго-востоку отсюда. Их там очень много, ты без труда их отыщешь. Помни, я хочу самые красивые рога — пожалуйста, не приноси ни побитых, ни сломанных!" },
    ["977c"] = { common = "Просто не могу дождаться, чтобы скорее показать своим друзьям! Погоди секунду, пока я прикреплю рога… Класс!" },
    ["978a"] = { common = "Перья дикосовухов из Внутренних земель, кажется, содержат следы магии. Эти силы… непохоже, что создания способны их контролировать, больше похоже на то, что магия просто является частью их сущности. За время моих исследований я слыхал, что большая популяция дикосовухов населяет заснеженные земли Зимних Ключей. Вдруг у этих существ есть те же свойства? Пожалуйста, путник, помогите мне найти ответ. Отправляйтесь в Зимние Ключи, соберите выпавшие перья и возвращайтесь с ними ко мне." },
    ["978c"] = { common = "Теперь я могу сравнить перья между собой… Посмотрим-ка…" },
    ["979a"] = { common = "Да-да, на эти перья, похоже, наложены точно такие же чары, как и те, что я прежде заметил… Поскольку я совершенно не уверен в том, что именно мы нашли, я очень хочу, чтобы вы продолжили поиск ответов, путник. Моя коллега недавно отправилась в Зимние Ключи изучать там дикосовухов в их естественной среде обитания. Может, вы нагоните её и выясните, что ей удалось узнать?" },
    ["979c"] = { common = "Привет! Вас прислал Эрелас?? Здорово, я как раз собиралась отправиться в пещеры, и я отнюдь не возражаю против компании." },
    ["980a"] = { common = "Слыхал я, что существуют и другие горячие источники — в местечке Зимние Ключи, далеко к северу отсюда. И вот в чём загвоздка — в тех местах нет никаких вулканов! Очень любопытно… Что ж, тут можно сделать лишь одно — отправиться в Зимние Ключи и поговорить с моей тамошней приятельницей. Её зовут Донова Снегонора, она живёт прямо рядом с источниками. Ну, счастливой дороги! Ещё раз спасибо за помощь с термометром." },
    ["980c"] = { common = "Здравствуй, путник! Да, Кракл был совершенно прав…" },
    ["981a"] = { common = "За всю проделанную вами работу вы заслужили хорошую награду. Возвращайтесь к Делгрену и скажите ему, что Атрикус Нарассин лежит, сражённый вашей рукой, а клан Тёмной Нити сокрушён, и остатки его рассеяны." },
    ["981c"] = { common = "Я знал, что вы возьмётесь за это задание. Я чувствую, вас ждут великие дела и что вам суждено исцелить многие недуги, что терзают наши земли. Примите моё благословение, и этот дар." },
    ["982a"] = { male = "У побережья Тёмного Берега, к северу от нас, есть остатки двух потерпевших крушение кораблей – \"Серебряной Зари\" и \"Туманной Пелены\". Некоторое время назад моряки обоих кораблей не поладили с отвратительными мурлоками, когда плыли по безбрежному морю в сторону Аубердина. Теперь корабли лежат на дне океана, став добычей мурлоков Оба капитана погибли в ту ночь, и их судовые журналы и ценные вещи по-прежнему лежат там, в денежных ящиках. Я хотел бы, чтобы ты добыл их для нас; это много значило бы для членов команды.", female = "У побережья Тёмного Берега, к северу от нас, есть остатки двух потерпевших крушение кораблей – \"Серебряной Зари\" и \"Туманной Пелены\". Некоторое время назад моряки обоих кораблей не поладили с отвратительными мурлоками, когда плыли по безбрежному морю в сторону Аубердина. Теперь корабли лежат на дне океана, став добычей мурлоков Оба капитана погибли в ту ночь, и их судовые журналы и ценные вещи по-прежнему лежат там, в денежных ящиках. Я хотел бы, чтобы ты добыла их для нас; это много значило бы для членов команды." },
    ["982c"] = { male = "Вы оказали нам огромную услугу, юноша. Мы позаботимся о том, чтобы за этими личными вещами был надлежащий уход. Что же касается вас, прошу вас принять это. Это самое маленькое, чем я могу отблагодарить за смелость, проявленную ради восстановления справедливости.", female = "Вы оказали нам огромную услугу, девушка. Мы позаботимся о том, чтобы за этими личными вещами был надлежащий уход. Что же касается вас, прошу вас принять это. Это самое маленькое, чем я могу отблагодарить за смелость, проявленную ради восстановления справедливости." },
    ["983a"] = { male = "Слушай! Помоги мне с моим последним изобретением, Жужжалкой. С её помощью можно общаться на расстоянии! Может быть, ты уже видел их – такие ящики с рычагами. С ними одна проблема – за ними нужен постоянный уход. У каждой из них есть своя проблема, но я нашёл хитрое решение. Я поместил все машины в районе обитания существ, части которых нужны для починки каждой конкретной машины. Сейчас неисправна Жужжалка восемьсот двадцать семь. Она находится чуть южнее Аубердина, совсем рядом с ним. Чтобы её починить, нужно шесть ножек краба. Я заплачу...", female = "Слушай! Помоги мне с моим последним изобретением, Жужжалкой. С её помощью можно общаться на расстоянии! Может быть, ты уже видела их – такие ящики с рычагами. С ними одна проблема – за ними нужен постоянный уход. У каждой из них есть своя проблема, но я нашёл хитрое решение. Я поместил все машины в районе обитания существ, части которых нужны для починки каждой конкретной машины. Сейчас неисправна Жужжалка восемьсот двадцать семь. Она находится чуть южнее Аубердина, совсем рядом с ним. Чтобы её починить, нужно шесть ножек краба. Я заплачу..." },
    ["983c"] = { male = "Когда вы кладёте ножки крабов в приёмник машины, то слышите, как шестерни начинают их перемалывать. По нескольким хлопающим звукам вы решаете, что ножки краба уже нашли своё место. Вскоре машина начинает жужжать, и вы слышите голосок, едва доносящийся из машины. \"Алло! Уфф... Алло! Ты её починил! Кстати, это Бацбах. Спасибо большое... Эй, не откажешься починить ещё одну машинку?\"", female = "Когда вы кладёте ножки крабов в приёмник машины, то слышите, как шестерни начинают их перемалывать. По нескольким хлопающим звукам вы решаете, что ножки краба уже нашли своё место. Вскоре машина начинает жужжать, и вы слышите голосок, едва доносящийся из машины. \"Алло! Уфф... Алло! Ты её починила! Кстати, это Бацбах. Спасибо большое... Эй, не откажешься починить ещё одну машинку?\"" },
    ["984a"] = { common = "Некоторые из моих собратьев спаслись от порабощённых порчей фурболгов в Тельдрассиле, а я пообещал остановить злодеяния, пока кровь не полилась рекой... или не произошло чего-то ещё хуже. Я уже вижу признаки присутствия скверны на Тёмных берегах, но она ещё не так распространилась. Я думаю, было бы логично продолжить исследования фурболгов. Может быть, ты найдёшь один из их лагерей, а затем вернёшься ко мне, если увидишь следы порчи?" },
    ["984c"] = { common = "Это и вправду ужасные новости. Поскольку фурболги находятся так близко к Аубердину, нам придётся приготовиться к неизбежному. Спасибо вам." },
    ["985a"] = { common = "Вы уже поднаторели в разведке на вражеских территориях. Но способны ли вы не только следить за врагами, но и биться с ними? Не все искатели приключений предпочитают честную битву лицом к лицу искусству скрытности и уклонения. Если вы считаете, что готовы к сражению, то наибольшую угрозу нашему народу представляют сейчас фурболги в лагере к югу от Аубердина. Вы найдёте там фурболгов Чернолесья. Убейте восемь следопытов и пять заклинателей ветра, а потом возвращайтесь сюда, ко мне." },
    ["985c"] = { common = "Смойте кровь с ваших доспехов, и не мучайтесь из-за содеянного. Вместо этого вознесите благодарность судьбе. Вы уменьшили угрозу нашему народу здесь, в Аубердине, даже если весь Тёмный Берег пока ещё находится в опасности из-за Мха Скверны." },
    ["986a"] = { common = "Ваше мастерство уже один раз сослужило мне хорошую службу в сложной ситуации. Могу ли я вновь возложить на вас задачу помочь Мрачнокогтю и его хозяину Волкору? Я могу сделать для вас волшебный плащ, который позволит вам беспрепятственно ходить вблизи враждебных существ Тёмного Берега, пока вы будете искать Волкора. Для изготовления плаща, чтобы хватило материала, мне нужно пять прекрасных шкур лунопарда, снятых со взрослых самцов или матриархов. Этих кошек можно найти около Петляющей реки, к югу отсюда, или ещё дальше на юг, близ Ясеневого леса." },
    ["986c"] = { common = "Эти шкуры отлично подойдут. Я немедленно приступаю к работе над плащом. Дайте мне немного времени, а затем возвращайтесь. Да, ещё кое-что: после того как вы задействуете чары, наложенные на плащ, вы будете ограничены в своём взаимодействии с другими лицами. Если сможете, ограничьтесь только разговорами. Всё, что сверх этого, может развеять чары." },
    ["990a"] = { common = "Моя госпожа – Раэна Волкопас – ожидает тебя в городе Астранаар, что в Ясеневом лесу. Возможно, с твоей помощью мы сможем хотя бы немного ослабить порчу, пустившую здесь корни. Отправляйся отсюда на юг и держись дороги – ты легко найдёшь путь, если будешь держаться этого направления." },
    ["990c"] = { male = "А, герой с Тёмного Берега. Хорошо, что Селарин прислала тебя так быстро. Прости, что тебе пришлось так спешить. Но с твоей помощью мы, возможно, сможем исправить положение. Я бы начала с разговоров с другими жителями Астранаара. Многим наверняка понадобится твоя помощь.", female = "А, героиня с Тёмного Берега. Хорошо, что Селарин прислала тебя так быстро. Прости, что тебе пришлось так спешить. Но с твоей помощью мы, возможно, сможем исправить положение. Я бы начала с разговоров с другими жителями Астранаара. Многим наверняка понадобится твоя помощь." },
    ["991a"] = { common = "Один мой старый друг тоже помогает часовым здесь, в Ясеневом лесу, но он ещё не вернулся. Он думает отыскать один предмет, который, по его мнению, ослабит нападения фурболгов на наш народ – это жезл, сделанный ныне покойным злым волшебником. Прежде чем уйти, он упомянул, что будет искать драгоценный камень для жезла. Он также говорил, что камень может находиться в святилище на озере Фалатим у подножия западных гор. Камень хранился там до того, как святилище было разрушено. Найди моего друга, пожалуйста." },
    ["991c"] = { common = "Покрытое ранами тело Терониса лежит на острове. По какой-то непонятной причине мурлоки бросили его здесь. Глубокие резаные раны явно оставлены оружием и когтями мурлоков." },
    ["992a"] = { common = "У нас, в Водной компании Прибамбасска, образовалась вакансия на должность младшего геодезиста на временную работу. Интересуешься? Кочевники захватили все наши колодцы, приходится искать альтернативные источники воды! В пустыне есть вода, надо только её отыскать! Возьми это устройство для поиска воды и принеси мне пробу из пруда возле Заставы Скорбных Песков. Правда, это место на виду у троллей. Когда закончишь, принеси мне включённое устройство!" },
    ["992c"] = { common = "Что такое? На тебя напали какие-то мерзкие ползучие твари? Ох, плохо это для Водной компании Прибамбасска, ох плохо… Надо было раньше тебя предупредить насчёт этих кошмарных насекомых, которые, кажется, выпивают всю воду в пустыне. Сначала я не придал им значения. Нам хватает проблем и с кочевниками, и мы решили, что это тоже их происки. Теперь мы знаем правду!" },
    ["993a"] = { male = "Плащ готов. Пришло время найти Волкора. Я могу только надеяться, что мы успеем. Магия, скрытая в плаще, если её пробудить, продержится недолго: может быть, минут пять. Сам решай, когда использовать: я бы предложил подождать, пока не найдёшь Мрачнокогтя. Если то, что он сказал мне – правда, ты найдёшь его хозяина в пещере к югу отсюда. Мрачнокоготь будет ждать тебя у дороги. Помаши ему, когда увидишь, чтобы привлечь его внимание, и он укажет тебе путь к своему хозяину.", female = "Плащ готов. Пришло время найти Волкора. Я могу только надеяться, что мы успеем. Магия, скрытая в плаще, если её пробудить, продержится недолго: может быть, минут пять. Сама решай, когда использовать: я бы предложил подождать, пока не найдёшь Мрачнокогтя. Если то, что он сказал мне – правда, ты найдёшь его хозяина в пещере к югу отсюда. Мрачнокоготь будет ждать тебя у дороги. Помаши ему, когда увидишь, чтобы привлечь его внимание, и он укажет тебе путь к своему хозяину." },
    ["993c"] = { common = "Чудесно! Терентис прислал мне помощь! О, посмотри-ка, ещё и плащ... кашляет Ох... Больно. Спасибо. Фурболги ранили меня, прежде чем я сумел от них улизнуть. Дай мне ещё минутку, и я буду в состоянии разговаривать дальше." },
    ["994a"] = { common = "Ладно, силой так силой. Давайте убираться отсюда, как только вы будете готовы. Мы пробьёмся к дороге – Мрачнокоготь должен всё ещё ждать. А там мы уже сможем разделиться. Терентис сразу же захочет услышать ваш рассказ, поэтому вы направитесь в Аубердин, когда мы отсюда выберемся." },
    ["994c"] = { male = "Рад видеть вас живым и здоровым. Ваша помощь Волкору вселила в меня веру, что мы сможем преодолеть трудности, с которыми сталкиваемся на Тёмном Берегу и за его пределами.", female = "Рад видеть вас живой и здоровой. Ваша помощь Волкору вселила в меня веру, что мы сможем преодолеть трудности, с которыми сталкиваемся на Тёмном Берегу и за его пределами." },
    ["995a"] = { common = "Ну, ладно... Если вы уверены, попробуем выскользнуть отсюда. Мы уйдём, как только вы будете готовы. Не забудьте после бегства отсюда вернуться к Терентису в Аубердин. А я туда отправлюсь сам по себе, потому что, вероятно, буду двигаться быстрее вас." },
    ["995c"] = { common = "Рад видеть вас живым и здоровым. Ваша помощь Волкору вселила в меня веру, что мы сможем преодолеть трудности, с которыми сталкиваемся на Тёмном Берегу и за его пределами." },
    ["997a"] = { male = "Так ты идёшь на юг? К озеру Аль'Амет? Если да, то не выполнишь ли ты одну мою просьбу... Мой собрат Деналан стоит лагерем у восточной оконечности озера, где изучает жизнь растений Тельдрассила и проводит свои эксперименты. Ему нужна редкая земля из Дарнасса, но её доставили в Доланаар с опозданием – только что. Не мог бы ты отнести ему эту землю?", female = "Так ты идёшь на юг? К озеру Аль'Амет? Если да, то не выполнишь ли ты одну мою просьбу... Мой собрат Деналан стоит лагерем у восточной оконечности озера, где изучает жизнь растений Тельдрассила и проводит свои эксперименты. Ему нужна редкая земля из Дарнасса, но её доставили в Доланаар с опозданием – только что. Не могла бы ты отнести ему эту землю?" },
    ["997c"] = { male = "Наконец-то! Я уже давно жду эту редкую землю. Надеюсь, она ещё свежая... Спасибо тебе за доставку. Ты – герой, не жалеющий времени на благие дела!", female = "Наконец-то! Я уже давно жду эту редкую землю. Надеюсь, она ещё свежая... Спасибо тебе за доставку. Ты – героиня, не жалеющая времени на благие дела!" },
    ["1000a"] = { common = "Внимание, герои! Круг Кенария ищет компетентных помощников для исследования нового обширного пограничья Калимдора — запретных диких краёв, полных невообразимых опасностей, что лежат к западу от Танариса и Прибамбасска! Кругу нужны добровольные и честные помощники, что будут действовать в его интересах! Все заинтересованные лица да обращаются в Круг Кенария! За дополнительной информацией обращайтесь к верховному друиду Хамуулу Руническому Тотему на вершину Старейшин Громового Утёса!" },
    ["1000c"] = { common = "Приветствую, герой. Я рад видеть тебя, рассказы о твоих деяниях опережают тебя. Видя тебя здесь, в меня вселяется чувство уверенности, что Круг Кенария получит требуемую помощь. Твоя связь с Кругом Кенария в Лунной поляне должна превосходить все расовые и политические розни. Всегда помни это, ты всегда действуешь от лица Круга." },
    ["1001a"] = { common = "Тоненький голосок пробивается откуда-то из глубины машины. \"Бацбах у аппарата! Следующая Жужжалка находится к северу от Аубердина, прямо на берегу. Итак, номер той Жужжалки – четыреста одиннадцать, и для её починки нужно три глаза крепкозуба. Эти твари водятся недалеко от берега! Крепкозубы Тёмного Берега... *И-ик!* Извини... Как и в прошлый раз, когда поместишь в Жужжалку то, что нужно, она выдаст тебе награду. *И-ик!* Что? Не, со мной всё в порядке!\"" },
    ["1001c"] = { male = "Жужжалка оживает вскоре после того, как вы помещаете в неё глаза крепкозуба. После коротких помех вы слышите знакомый голосок. \"Вино из крабов лучше всего...\" И-ик! \"Что? О, ты уже её починил! Ух, какой ты бысшшштрый. Так шшшо, согласишшшься почшшшинить ешшше одну?\" Вы уверены, что слышите, как жидкость льётся в ёмкость, а затем – звучные глотки.", female = "Жужжалка оживает вскоре после того, как вы помещаете в неё глаза крепкозуба. После коротких помех вы слышите знакомый голосок. \"Вино из крабов лучше всего...\" И-ик! \"Что? О, ты уже её починила! Ух, какая ты бысшшштрая. Так шшшо, согласишшшься почшшшинить ешшше одну?\" Вы уверены, что слышите, как жидкость льётся в ёмкость, а затем – звучные глотки." },
    ["1002a"] = { common = "Жужжалка издаёт треск статических помех, и вы слышите голос Бацбаха. \"Шшшледуюшшшая жужшшшалка – номер триста двадцать три. Она к шшшеверу от Аубердина, но... а хде жшшше эль? Шшшо? О, она шшштоит на дороге, так шшшо ты легко её найдешшшь около мосшшшт\". Бацбах что-то неразборчиво бормочет, а потом вы слышите отчётливый звук глотка. \"В эту нужшшшно положшшшить клыки лунопардов... шшшесть\"." },
    ["1002c"] = { male = "Неожидано Жужжалка начинает работать, и вы отчётливо слышите, как клыки перемалываются внутри машины в муку. \"Так шшшо, ты это шшшделал! Отлишшшные новосшшшти... И шшшо жшшше... ты не уходишшшь? А! Можшшшет, хочешшшь ешшше поработать?\"", female = "Неожидано Жужжалка начинает работать, и вы отчётливо слышите, как клыки перемалываются внутри машины в муку. \"Так шшшо, ты это шшшделала! Отлишшшные новосшшшти... И шшшо жшшше... ты не уходишшшь? А! Можшшшет, хочешшшь ешшше поработать?\"" },
    ["1003a"] = { common = "Сквозь булькающий шум и звуки капающей жидкости, исходящие от машины, вы слышите неверный голос Бацбаха. \"Шшшледуюшший далеко на юг по доррроге. Найти должно быть нетрудно... шшшразу рядом на обочшшине... возле огражшшдения. Думаю, я шшпрятал его в каких-то кусшшштах... Кусшшшты... Хи-хи... Да, Жужжшшалка пятьсот двадцать пять снимет сшшшедые шшшкальпы с этттих сшшшедых колючешшшшерстныхх медведей. Божшшшежшшш мой, шшшто за пойло. Гнусшшшные... Хи-хи-хи...\" Вы слышите звуки жадных глотков, и машина выключается. Затем, совершенно неожиданно, вновь оживает. \"Четыре!\"" },
    ["1003c"] = { common = "Так ты шшшшо, положшшил шшшкальпы внутрь? Хорошшшо... Шо? Агга, я шшшоображшшаю, шшшо могу разшшшговаривать шшш тобой и безшшш материалов в машшшине. Но я пррравду грил, когда шшшказшшшал, шшшо они шшшломались! Шшшмотри, кроме шшшредшшштв коммунимакации эти жужжшшшалки ешшшё варят и дишшштиллируют отличшшшное питьё. Просшшшти зшшша обман, но Ночшшшные эльфы не одобряют торррговли моими напитками в сшшшвоих городах. Я оставлю нечшшшто осшшшобенное в этом яшшшике, шшшобы показать мою благодарносшшшть за твои усшшшилия. Насшшшлаждайся!" },
    ["1004a"] = { common = "Внимание, герои! Круг Кенария ищет отважных, которые помогут исследовать новое пограничье Калимдора! К западу от Танариса и Прибамбасска простираются неизведанные и опасные пустоши. Круг нуждается в доблестных помощниках! Все заинтересованные лица могут обращаться в Круг Кенария. Дополнительные сведения можно получить у верховного друида Хамуула Рунического Тотема на Вершине Старейшин Громового Утёса." },
    ["1004c"] = { common = "Здравствуй, герой! Приятно видеть, что таким, как ты, небезразлично благополучие природы. Рассказы о твоих подвигах опережают тебя, и тебе здесь всегда рады. Твой приход внушает мне уверенность, что Круг Кенария получит помощь, в которой нуждается. Наша связь с Кругом Кенария на Лунной Поляне превыше расовых и политических противоречий. Помни это, когда будешь действовать от имени Круга, — и добьёшься успеха." },
    ["1007a"] = { common = "Я хотел бы дать тебе поручение. Я на своей маленькой лодочке плыл над затопленными руинами Зорама, когда на меня напали наги, выныривая из воды и вцепляясь в меня когтями! Я убежал, унеся с собой всё, что смог, и чего хватило лишь вот на этот жалкий лагерь. Но когда я добрался до берега и побежал... я потерял одну дорогую мне вещь. Прошу тебя, найди место засады – это на побережье к северу – и отыщи древнюю статуэтку. Именно из-за неё я отважился подвергнуть себя опасностям Зорамского взморья." },
    ["1007c"] = { male = "Ты её нашёл! Спасибо тебе! Древний город Зорам хранит неисчислимые тайны, и эта статуэтка может послужить ключом ко многим из них.", female = "Ты её нашла! Спасибо тебе! Древний город Зорам хранит неисчислимые тайны, и эта статуэтка может послужить ключом ко многим из них." },
    ["1008a"] = { common = "По нашему северо-западному побережью, известному как Зорамское взморье, расползается зло. Там покоятся руины злосчастного города Зорам, разрушенного при Расколе и поглощённого морем. Для ночных эльфов он был утрачен на много веков. Утрачен и почти забыт. Теперь туда вернулись наги, и мы не знаем, почему. Но причина не так важна – мы должны перебить этих тварей и загнать их обратно в глубины! Возвращайся, когда выполнишь поручение." },
    ["1008c"] = { common = "Отлично. Твои деяния против наг на Зорамском взморье достойны похвалы. Я знаю, что задание выполнить было нелегко, ибо сила и коварство наг прекрасно известны ночным эльфам. Мы это знаем, ибо у нас одна история. Но эту историю я вспоминать не желаю." },
    ["1009a"] = { common = "Боюсь, тайна этой древней статуэтки так и останется нераскрытой, если не найти ключа к этому древнему замку. Этим ключом является кольцо – кольцо Зорама. Оно принадлежало правителям этого города до того, как волны Раскола поглотили его. Долгие годы кольцо считалось утраченным, пока наги недавно не нашли его. Их предводительница, Руузель, живёт на острове на северной окраине Зорама. Прошу тебя, добудь мне это кольцо!" },
    ["1009c"] = { male = "Ты добыл кольцо! Спасибо тебе. Прошу, возьми вот это в награду и знай, что я никогда не забуду того, что ты делал сегодня.", female = "Ты добыла кольцо! Спасибо тебе. Прошу, возьми вот это в награду и знай, что я никогда не забуду того, что ты сделала сегодня." },
    ["1010a"] = { common = "Есть одна травка, что росла некогда в древних руинах Убежища Батрана на севере. Звалась эта травка Батранов волос и славилась тем, что лечила болезни души. В этой деревне болеет ребёнок, и сдаётся мне, что это болезнь не телесная. Не сходишь ли ты в Убежище Батрана и не поищешь ли Батранов волос? Мне он может понадобиться, чтобы вылечить ребёнка. Убежище Батрана лежит к северу от заставы Мейстры и прямо к югу от границы с Тёмным Берегом." },
    ["1010c"] = { male = "Ах, ты принёс эту травку! Теперь я сварю лекарство для ребёнка, и будем молиться, чтобы отвар подействовал. И... В Убежище Батрана – Отрёкшиеся? Очень тревожная весть. Поистине, очень тревожная...", female = "Ах, ты принесла эту травку! Теперь я сварю лекарство для ребёнка, и будем молиться, чтобы отвар подействовал. И... В Убежище Батрана – Отрёкшиеся? Очень тревожная весть. Поистине, очень тревожная..." },
    ["1011a"] = { common = "Отрёкшиеся, нежить из Орды, проникли в Ясеневый лес, и рыщут среди развалин и курганов. Мы уверены, что их цель – распространить чуму по землям ночных эльфов. Мы должны убедиться в этом! Отрёкшиеся разбили лагерь к югу отсюда, рядом с Обителью Дор'Данил, где они готовят яды и заразу и разливают их по бутылкам. Проложи себе путь в этот лагерь и укради бутыль с заразой. Принеси её сюда. Я исследую её и узнаю, для чего она." },
    ["1011c"] = { common = "Очень хорошо. Теперь, когда я проанализирую содержимое бутыли, станут понятны цели Отрёкшихся!" },
    ["1012a"] = { male = "Когда я боролся с ядами Отрёкшихся, мне было видение. Я узрел друидов Обители Дор'Данил, они были отравлены... убиты нежитью! Теперь они стали блуждающими духами, разлучёнными с телами и обезумевшими от этого. Чтобы души этих друидов обрели покой, ты должен войти в Обитель Дор'Данил и уничтожить её некогда могучих предводителей – Таниэля Тёмный Лес, Этиля Зов Луны и Мавориса Проблеск Солнца. Сделай это и возвращайся ко мне.", female = "Когда я боролся с ядами Отрёкшихся, мне было видение. Я узрел друидов Обители Дор'Данил, они были отравлены... убиты нежитью! Теперь они стали блуждающими духами, разлучёнными с телами и обезумевшими от этого. Чтобы души этих друидов обрели покой, ты должна войти в Обитель Дор'Данил и уничтожить её некогда могучих предводителей – Таниэля Тёмный Лес, Этиля Зов Луны и Мавориса Проблеск Солнца. Сделай это и возвращайся ко мне." },
    ["1012c"] = { male = "Я ощутил, как утихает боль обители Дор-Даниль, и понял, что ты выполнил свою задачу. Тяжёлое дело выпало тебе, ибо духи, которых ты уничтожил, всего лишь жертвы злобы Отрёкшихся. Но с их погибелью, будем надеяться, и другие безумные духи обретут покой.", female = "Я ощутил, как утихает боль обители Дор-Даниль, и понял, что ты выполнила свою задачу. Тяжёлое дело выпало тебе, ибо духи, которых ты уничтожила, всего лишь жертвы злобы Отрёкшихся. Но с их погибелью, будем надеяться, и другие безумные духи обретут покой." },
    ["1013a"] = { common = "В крепости Тёмного Клыка хранится книга – книга Ура, я хочу видеть её в своей коллекции. Ур был великим магом Даларана до того, как оказался в рядах Плети, и его труды по иным мирам представляют большой интерес... для некоторых Отрёкшихся. Отправляйся в крепость Тёмного Клыка и найди книгу. Принеси мне её, и я сообщу о твоих заслугах Тёмной Госпоже." },
    ["1013c"] = { common = "Прекрасно. Эта книга будет прекрасным дополнением моей коллекции трудов Ура. Знания его были велики, однако ограниченность его сознания не давало ему обрести настоящую силу. Именно поэтому он не смог противостоять Плети. Мы, Отрёкшиеся, не можем позволить себе роскошь быть слабыми – ведь тогда нам не выжить... И уж тем более не обрести власть." },
    ["1014a"] = { common = "Аругал по-прежнему сидит в крепости Тёмного Клыка. Мы не можем считать Серебряный бор стратегическим оплотом Тёмной Госпожи до тех пор, пока Аругал жив. Я позабочусь о том, чтобы искоренить его магию. Но сделать так, чтобы Аругал встретил заслуженную смерть – это я оставляю вам. Отправляйтесь в крепость Тёмного Клыка и положите конец скверным деяниям Аругала раз и навсегда. И принесите мне голову этого злодея!" },
    ["1014c"] = { common = "Наконец-то Серебряный бор избавлен от злодеяний Аругала. Вы сослужили огромную службу Тёмной Госпоже. Ваша стойкость будет вознаграждена." },
    ["1015a"] = { common = "Внимание, герои! Круг Кенария ищет смельчаков, готовых исследовать окраины Калимдора! Забытые пустоши, полные неизвестных опасностей, лежат к западу от Танариса и Прибамбасска. Круг Кенария призывает храбрых героев изучить эти земли. Все желающие должны пройти собеседование в Круге Кенария. Обращайтесь к верховному друиду Фэндралу Оленьему Шлему в Дарнассе!" },
    ["1015c"] = { common = "С чего ты взял, что твои докучания будут мне в радость, герой?Постой — позволь мне забросить свои важнейшие ежедневные обязанности, чтобы помочь тебе отыскать какую-то штуковину. Определённо, благосостояния в Дарнасе нет, весь Тельдрассил должен приобрести безделушки для вашей коллекции. Эти глупцы в Лунной Поляне тратят моё время своими просьбами о помощи, и я должен это терпеть?" },
    ["1016a"] = { common = "Бозьми этот гадальный свиток – он поможет определить создателя этих элементалей. Но тебе понадобится кое-что взять у этих духов для фокусировки магии свитка – их браслеты прекрасно подойдут. Хватит нескольких неповреждённых браслетов с этих существ. Другие для наших целей бесполезны, но зато у торговцев за них можно кое-что выручить, если пожелаешь продать. Как только ты добудешь неповреждённые браслеты, попытайся использовать свиток. Возвращайся ко мне с результатами, и мы продолжим." },
    ["1016c"] = { common = "Хорошая работа, это даст нам информацию, необходимую для того, чтобы раскрыть преступника. Ты не против помочь нам схватить мага, который наполнил наши пруды порчеными элементалями? У меня сердце сжимается при виде осквернённого Ясеневого леса и других мест, и я просто сгораю от нетерпения схватить волшебника, который так старается ещё сильнее навредить этому краю. Мы заставим его за всё ответить." },
    ["1017a"] = { common = "Есть только один маг из нежити в Степях, способный наслать порчу на стольких элементалей воды. И он единственный, кому хватит дури попытаться это сделать. Сарилус Грязнорожденный, наверное, сидит на вершине Вершины Багрового Тумана, да смеётся надо-мной. Тебе придётся проникнуть на вражескую территорию и уничтожить этого мерзавца. Мне надоела его бестолковость, и надо показать ему, что бывает с теми, кто донимает часовых. Уничтожь его и принеси мне его голову. Но соблюдай осторожность, Орда может подкараулить тебя." },
    ["1017c"] = { common = "Теперь эта мерзкая ухмылка навсегда стёрта с его лица. Славное, воистину славное дело. Возьми – это Свет Элуны, испей его, когда будет казаться, что всему конец, и смерть неминуема. Он спасёт тебя по воле Богини." },
    ["1018a"] = { common = "Внимание, герои! Круг Кенария ищет отважных, которые помогут исследовать обширное новое пограничье Калимдора! К западу от Танариса и Прибамбасска простираются неизведанные и опасные пустоши. Круг нуждается в доблестных помощниках! Все заинтересованные лица могут обращаться в Круг Кенария. Дополнительные сведения можно получить у верховного друида Хамуула Рунического Тотема на Вершине Старейшин Громового Утёса." },
    ["1018c"] = { common = "Здравствуй, герой! Приятно видеть, что таким, как ты, небезразлично благополучие природы. Рассказы о твоих подвигах опережают тебя, и тебе здесь всегда рады. Твой приход внушает мне уверенность, что Круг Кенария получит помощь, в которой нуждается. Наша связь с Кругом Кенария на Лунной Поляне превыше расовых и политических противоречий. Помни это, когда будешь действовать от имени Круга, — и добьёшься успеха." },
    ["1019a"] = { common = "Внимание, герои! Круг Кенария ищет компетентных помощников для исследования нового обширного пограничья Калимдора -запретных диких краев, полных невообразимых опасностей, что лежат к западу от Танариса и Прибамбасска! Кругу нужны добровольные и честные помощники, что будут действовать в его интересах! Все заинтересованные лица да обращаются в Круг Кенария! За дополнительной информацией обращайтесь к верховному друиду Фэндралу Оленьему Шлему в Дарнассе!" },
    ["1019c"] = { common = "С чего ты решил, что я буду утруждать себя беседой с таким, как ты, герой? Вот сейчас я брошу мои великие каждодневные труды и стану искать для тебя эту безделицу! Ведь благополучие Дарнасса — нет, всего Тельдрассила — в сравнение не идёт с важностью поиска этой пустяковины для твоей коллекции! Сначала эти недоумки из Лунной поляны отнимают у меня время своими просьбами о помощи, а теперь я ещё и это сносить должен?" },
    ["1020a"] = { common = "Я изготовил лекарство, которое, надеюсь, поможет больному ребёнку. Отнеси его в Астранаар отцу ребёнка, Пельтуру Белой Луне. Чтобы добраться до Астранаара, ступай по дороге сначала на юг, потом на восток." },
    ["1020c"] = { common = "Это от Орендила? Он славен знанием трав и лекарским искусством. Это лекарство вселяет в меня надежду, которой прежде у меня почти не было..." },
    ["1021a"] = { male = "Послушай, я не знаю, кто ты, но мне нужна помощь. Мои сёстры отправились отнять у одного сатира Ветвь Кенария. Они сказали, что скоро вернутся, но уже целых два дня прошло! Ты должен найти их! Они искали развалины храма ночных эльфов в Ксавиане на северо-западе. Не знаю, что и думать. Найди Анилию, это она повела их на поиски.", female = "Послушай, я не знаю, кто ты, но мне нужна помощь. Мои сёстры отправились отнять у одного сатира Ветвь Кенария. Они сказали, что скоро вернутся, но уже целых два дня прошло! Ты должна найти их! Они искали развалины храма ночных эльфов в Ксавиане на северо-западе. Не знаю, что и думать. Найди Анилию, это она повела их на поиски." },
    ["1021c"] = { common = "Судя по зияющей в боку ране, Анилия на грани смерти." },
    ["1022a"] = { common = "Хотя мы затратили много средств и сил на то, чтобы вытеснить остатки демонов из Осквернённого леса на север, успехи наши невелики. Нам удалось не допустить большую часть демонов в Ясеневый лес. На севере, у границы Осквернённого леса, разрушенное святилище Мел'Тандрис захватили загадочные волколюди. Из-за их пронзительных воплей это место называют теперь Воющей Долиной. Фолиант Мел'Тандрис, что хранится в святилище может пролить свет на появление там волколюдей." },
    ["1022c"] = { common = "Фолиант Мел'Тандрис действует странным образом. События, которые он записывает, события, которые он показывает... Никто тольком не понимает, почему он делает то, что делает. Тем не менее, понятно, что предмет, который получила жрица Звёздная Песня – эта коса Элуны – требует дальнейшего исследования." },
    ["1023a"] = { common = "Осматривая вещи Терониса, вы находите дневник, который всё ещё в неплохом состоянии. Вы берёте дневник и оставляете труп Терониса. Остаётся только найти камень, который искал Теронис. Раэна говорила, что он где-то здесь. Возможно, его забрали мурлоки..." },
    ["1023c"] = { common = "Это ужасно. Теронис мёртв?! Мы оплачем его, когда придёт пора, но сейчас надо сосредоточить усилия на другом. Я отправлю часовых за телом Терониса как можно скорее. У тебя дневник Терониса и камень, который он искал. Как думаешь – ты сумеешь завершить его дело? Моя душа успокоится, если я буду знать, что он погиб не напрасно." },
    ["1024a"] = { male = "Тебе придётся провести исследование самостоятельно, но, судя по заметкам Терониса, следующим твоим шагом, похоже, будет поиск остальных фрагментов созданного Дартолом жезла. Я бы начала поиск от лунного колодца к востоку от озера Ирис. Когда будешь готов, ступай по этой дороге и сверни на север у небольшого местечка для отдыха слева от тебя. Дриада Шаэлдрин будет тебе лучшим, чем я, проводником. Найди её. Возьми с собой этот самоцвет – он может понадобиться Шаэлдрин, если она решит помочь тебе восстановить жезл.", female = "Тебе придётся провести исследование самостоятельно, но, судя по заметкам Терониса, следующим твоим шагом, похоже, будет поиск остальных фрагментов созданного Дартолом жезла. Я бы начала поиск от лунного колодца к востоку от озера Ирис. Когда будешь готова, ступай по этой дороге и сверни на север у небольшого местечка для отдыха слева от тебя. Дриада Шаэлдрин будет тебе лучшим, чем я, проводником. Найди её. Возьми с собой этот самоцвет – он может понадобиться Шаэлдрин, если она решит помочь тебе восстановить жезл." },
    ["1024c"] = { common = "О, так тебя послала Раэна? Тогда это и правда серьёзное дело. Чем я могу тебе помочь?" },
    ["1025a"] = { male = "Если ты желаешь испытать свои умения и заодно помочь жителям Ясеневого леса, я дам тебе ещё одно поручение, прежде чем ты отправишься к лунному колодцу. На дороге, что сворачивает на восток перед рекой Фалфаррен, фурболги в последнее время нападают на путников. Их извращённый разум питается страхом, а кровожадность утоляется кровью невинных жертв. Помоги часовым защитить эти края, отплати этим чудовищам их же монетой. Думаю, их лагерь находится к югу от дороги... будь осторожен.", female = "Если ты желаешь испытать свои умения и заодно помочь жителям Ясеневого леса, я дам тебе ещё одно поручение, прежде чем ты отправишься к лунному колодцу. На дороге, что сворачивает на восток перед рекой Фалфаррен, фурболги в последнее время нападают на путников. Их извращённый разум питается страхом, а кровожадность утоляется кровью невинных жертв. Помоги часовым защитить эти края, отплати этим чудовищам их же монетой. Думаю, их лагерь находится к югу от дороги... будь осторожна." },
    ["1025c"] = { common = "Славная работа. Спасибо тебе." },
    ["1026a"] = { common = "Хотелось бы мне, чтобы у тебя были более хорошие новости. Раэна права, я знаю о творении Дартола и древнях этих краёв – или знала прежде. Они теперь все осквернены, их природа искажена. Если твоя цель – найти ещё один фрагмент жезла, то тебе придётся найти ключ, чтобы отпереть сундук, в котором он лежит. Деревянный ключ – на одном из древней к северу отсюда, близ Осквернённого леса. Как только добудешь его, ищи небольшую лощинку к западу от дороги близ границы Осквернённого леса... Сундук должен быть спрятан где-то там." },
    ["1026c"] = { common = "Я рада твоему возвращению." },
    ["1027a"] = { common = "Последний фрагмент жезла был отдан на хранение друидам Дор-Даниля. Я понятия не имею, где они его спрятали. Сожалею, что больше ничем не могу тебе помочь. Могу только сказать, что тебе следует идти по дороге, что ведёт в Степи. Друиды скрывались к востоку от этой дороги, но они тебе уже не помогут – недавно их перебили... мне не очень хочется об этом думать. Когда найдёшь последний фрагмент, принеси его мне, и я помогу тебе воссоздать жезл." },
    ["1027c"] = { male = "Ты нашёл последний фрагмент? Тебе очень повезло... И Раэне тоже. Как понимаю, нам надо попытаться собрать его, да?", female = "Ты нашла последний фрагмент? Тебе очень повезло... И Раэне тоже. Как понимаю, нам надо попытаться собрать его, да?" },
    ["1028a"] = { common = "Вот собранный жезл. Восстановить его было просто... Труднее будет найти святилище, в котором жезл можно будет наполнить силой. Но при твоих целеустремлённости и усердии, после всех твоих достижений тебе не слишком трудно будет его найти. Ступай на юго-восток – там очень мало торных дорог, так что будь осторожнее – и посматривай на север. Святилище скрыто в горах, что окружают эту долину. Как только ты окажешься там, положи жезл в святилище... а остальное сделает магия. Хе-хе." },
    ["1028c"] = { common = "Когда свечение угасает, вы видите в купели святилища заново наполненный чарами жезл." },
    ["1029a"] = { common = "Советую тебе найти Раэну и сказать ей, что жезл воссоздан. Я уверен, она знает, куда тебе направиться дальше. Удачи." },
    ["1029c"] = { male = "Ты собрал жезл, который отправил тебя искать Теронис? Это приятно слышать. Теронис был бы счастлив, узнав, что его задание выполнено даже после его трагической гибели.", female = "Ты собрала жезл, который отправил тебя искать Теронис? Это приятно слышать. Теронис был бы счастлив, узнав, что его задание выполнено даже после его трагической гибели." },
    ["1030a"] = { common = "Увы, не могу сказать, что у него было на уме. Если он сказал правду о силе жезла, то тогда ты сможешь принимать тот или иной образ. Какой – не знаю. Может, он намеревался использовать его мощь, чтобы подобраться поближе к этим мерзостным фурболгам, но даже не затронутые порчей существа убили бы его, не будь он осторожен. Дартол, превращённый при помощи жезла, должен был бы поговорить с фурболгом, не подпавшим под порчу Мха Скверны. На мой взгляд, надо начать поиски к юго-востоку от озера Мистраль." },
    ["1030c"] = { common = "Да-да... ты мой сородич, но ты здоровый. Пока ещё чистый. Не знаю, как уж тебе удалось избежать тех злодеяний, что ночные эльфы обрушили на наш народ, но я рад, что больше я не одинок. Нынче порча бежит в жилах наших сородичей, малыш, порча, насланная на нас спесивыми ночными эльфами. Это они с нами такое сделали... Они виноваты в том, что меня изгнали из племени. По ночам я по-прежнему вижу костры в темноте." },
    ["1031a"] = { common = "Анилия кладёт руки вам на плечи и привлекает вас к себе. Задыхаясь, она показывает на находящуюся на севере арку, затем глаза её закрываются, и из последних сил она шепчет: \"Он забрал её... Гелтарис...\" И в душе вы понимаете, что Анилия умирает, жаждая, чтобы Ветвь Кенария была возвращена дриадам." },
    ["1031c"] = { common = "Анилия умерла? Нет, этого не может быть! Кажется, только вчера мы вместе бегали и играли в лесах! Счастливые дни теперь миновали..." },
    ["1032a"] = { common = "Поверить не могу – Анилии нет! Как часто мы вместе резвились в лесах... Я почти ощущаю... печаль. Я знаю, от чего мне станет лучше. Пожалуйста, убей сатиров, что отняли у меня Анилию! Принеси мне их рога в доказательство своего деяния, и я буду навек тебе благодарна." },
    ["1032c"] = { male = "Спасибо тебе, добрый герой. Душа моей сестры возрадуется твоим деяниям.", female = "Спасибо тебе, добрая героиня. Душа моей сестры возрадуется твоим деяниям." },
    ["1033a"] = { common = "Я надеялся, что лекарство Орендила спасёт Релару, но, боюсь, оно лишь немного ослабило болезнь, поселившуюся в теле моей дочери. Мы должны найти более мощное средство! К счастью, Орендил говорил мне, какие ещё он попытается применить лекарства, если первое не поможет. Слеза Элуны – это такой камень, который можно найти только в одном месте – на острове в озере Ирис к востоку от Астранаара. Орендил сказал, что этот камень снимает порчу... прошу тебя, принеси мне Слезу Элуны, и да покончит она с болезнью моей дочери!" },
    ["1033c"] = { male = "О, ты нашёл её! Я опущу Слезу в отвар и буду молиться, чтобы он помог ей. Спасибо тебе! Спасибо тебе!", female = "О, ты нашла её! Я опущу Слезу в отвар и буду молиться, чтобы он помог ей. Спасибо тебе! Спасибо тебе!" },
    ["1034a"] = { common = "Слеза Элуны немного облегчила страдания моей дочери. Кошмары стали реже её мучить, хвала богине. Но... лихорадка всё ещё сжигает её. Орендил рассказал мне о морозной пыли, которую находят среди руин Звёздной Пыли. Может, она усмирит лихорадку Релары. Собери немного этой пыли, прошу тебя, и принеси её мне. Руины Звёздной Пыли находятся на юге. Да ускорит твой шаг Элуна!" },
    ["1034c"] = { common = "Ты принёс пыль! Я сделаю из неё припарки – они должны унять лихорадку Релары. Ещё раз спасибо тебе. Без твоей помощи моё дитя несомненно умерло бы." },
    ["1035a"] = { male = "Лихорадка Релары прошла, но она ещё очень слаба. Я не верю, что только время вернёт ей былую силу. Мне кажется, тут нужна мощь лунного камня. Мы обычно собирали лунный камень у озера Зеркало Небес к юго-востоку отсюда... пока не пришли чащобники. Их предводитель, Чащобный Оракул, собрал все рассыпанные лунные камни и припрятал их. Ты должен отнять лунные камни у Оракула. И, боюсь, для этого тебе придётся его убить.", female = "Лихорадка Релары прошла, но она ещё очень слаба. Я не верю, что только время вернёт ей былую силу. Мне кажется, тут нужна мощь лунного камня. Мы обычно собирали лунный камень у озера Зеркало Небес к юго-востоку отсюда... пока не пришли чащобники. Их предводитель, Чащобный Оракул, собрал все рассыпанные лунные камни и припрятал их. Ты должна отнять лунные камни у Оракула. И, боюсь, для этого тебе придётся его убить." },
    ["1035c"] = { male = "О, ты спас мою дочь! Я знаю, что сила лунного камня вернёт моей дочери силы! Мне никогда не отблагодарить тебя за всё, что ты для меня сделал, но... пожалуйста, возьми вот это. После Релары это самое дорогое, что есть у меня.", female = "О, ты спасла мою дочь! Я знаю, что сила лунного камня вернёт моей дочери силы! Мне никогда не отблагодарить тебя за всё, что ты для меня сделала, но... пожалуйста, возьми вот это. После Релары это самое дорогое, что есть у меня." },
    ["1036a"] = { common = "Путник… Да, я слышал про тебя. Говорят, что ты не друг Пиратской бухте — как и мы, пираты Кровавого Паруса. Командир флота Фираллон ищет здоровых и крепких воинов, чтобы послать их на особое задание. Звучит заманчиво? Тогда отправляйся на \"Багровый Парус\" и поговори с ним. Он в одной из кают. Корабль на стоянке на Диком берегу к востоку отсюда, рядом с \"Буруном\" и \"Госпожой Удачей\"." },
    ["1037a"] = { common = "Велинда Песнь Звёзд была моей предшественницей здесь, в Ясеневом лесу. Поначалу казалось, что она держит под контролем ситуацию в Оскверненном лесу, но понемногу её усилия стали сходить на нет. И однажды она просто исчезла. Меня послали сюда продолжить её труды. Однако, боюсь, я ничего не знаю об этой жрице. Возможно, Тин'тель Танец Клинка, одна из командиров часовых, знает подробности её исчезновения, о которых не знаю я. Наверняка она поймёт значение такой информации." },
    ["1037c"] = { common = "Велинда Песнь Звёзд? То, что эта жрица пропала некоторое время назад, известно всем. Что касается событий, окружавших её исчезновение... Чтобы поделиться такой информацией, мне нужна веская причина." },
    ["1038a"] = { male = "Значит, это ты вычитал в фолианте Мел'Тандрис? Думаю, ничего страшного не будет, если ты осмотришь её вещи. Этот ключ позволит тебе отпереть сундук, в котором она держала свои пожитки в казарме часовых. Она вела дневник, и если что-то можно узнать, то только из него. Должна тебе сказать, что часовые считают, что у неё была причина уйти, и ждут её возвращения в любой момент. Эта жрица многими своими делами заслужила наше доверие.", female = "Значит, это ты вычитала в фолианте Мел'Тандрис? Думаю, ничего страшного не будет, если ты осмотришь её вещи. Этот ключ позволит тебе отпереть сундук, в котором она держала свои пожитки в казарме часовых. Она вела дневник, и если что-то можно узнать, то только из него. Должна тебе сказать, что часовые считают, что у неё была причина уйти, и ждут её возвращения в любой момент. Эта жрица многими своими делами заслужила наше доверие." },
    ["1038c"] = { male = "Похоже, что исчезновение Велинды – не столь безобидное дело, как казалось поначалу. Но я всё равно не могу поверить, что она плохо кончила. Может, нам лучше будет найти её? Раз уж ты проявил живой интерес к этому делу, то я была бы рада заручиться твоей поддержкой.", female = "Похоже, что исчезновение Велинды – не столь безобидное дело, как казалось поначалу. Но я всё равно не могу поверить, что она плохо кончила. Может, нам лучше будет найти её? Раз уж ты проявила живой интерес к этому делу, то я была бы рада заручиться твоей поддержкой." },
    ["1039a"] = { common = "Кабестан – единственный порт в Степях. Скорее всего, Велинда нашла там торговое судно, которое шло в бухту Черноводья в Азероте. Мы ограничили сделки с гоблинами, которые руководят портом, но смотритель пристани наверняка знает, какие пассажиры взошли на борт, а какие сошли на берег. Следуй по дороге на юго-восток через Ясеневый лес, и попадёшь в Степи. Смотри по сторонам, эти края патрулируют солдаты Орды. Но в порту ты будешь в безопасности." },
    ["1039c"] = { male = "герой? Должен сказать, твоих сородичей тут у нас нечасто увидишь. Кого-то ищешь, да? Минуточку, сейчас гляну в своих учётных списках. Через порт проходит куча народу, так что подожди минутку, сделай милость.", female = "героиня? Должен сказать, твоих сородичей тут у нас нечасто увидишь. Кого-то ищешь, да? Минуточку, сейчас гляну в своих учётных списках. Через порт проходит куча народу, так что подожди минутку, сделай милость." },
    ["1040a"] = { common = "А, наконец-то, нашёл. Надо было сразу сказать, что она проезжала здесь давно. Посмотрим. Велинда. Оплатила проезд до Пиратской бухты на \"Чёрной Скопе\". Никаких дополнительных пометок нет – значит, она благополучно добралась до места назначения. Больше ничем я помочь не могу, хотя она спрашивала, какие средства передвижения есть по ту сторону моря, и я упомянул Раззгота, водящего караваны из Пиратской бухты. Быть может, Велинда отправилась с ним. Ну всё, давай, иди. Не весь же день с тобой болтать." },
    ["1040c"] = { male = "Да? Не похоже, чтобы ты хотел отправить какой-нибудь груз, так что ты либо хочешь устроиться подработать в мой караван – а сейчас работы нет, – либо не к тому обратился. Я угадал?", female = "Да? Не похоже, чтобы ты хотела отправить какой-нибудь груз, так что ты либо хочешь устроиться подработать в мой караван – а сейчас работы нет, – либо не к тому обратилась. Я угадал?" },
    ["1041a"] = { common = "Оказывается, я ошибался насчёт тебя, а я это не часто признаю. Оказывается, я помню эту Велинду. Не каждый день жрица ночных эльфов желает отправиться в путь со старым грязным – но превосходным для транспортировки товаров – караваном вроде моего. По пути на север мы разделились, и она направилась в Темнолесье. Тамошний клерк ведёт записи. Может, он знает что полезное. Осторожнее в джунглях, они даже в лучшие времена – опасное место." },
    ["1041c"] = { common = "В последние годы случилось много странного, и я стараюсь вести записи про всех чужаков. Никогда не узнаешь, что пригодится... Хотя когда эти записи оказываются нужны, добра не жди... Нет, про вашу Велинду я не хочу сказать ничего дурного." },
    ["1042a"] = { common = "Нет, у меня не сохранилось записей о пребывании Велинды Песни Звёзд в Темнолесье... Хотя, прошу прощения за прямоту, не могу представить, чтобы жрица ночных эльфов снимала комнату в гостинице, если ты понимаешь, о чём я. А вот о волко-людях я слышал, и не раз. Только недавно Калор явился в город, неся целую связку их голов. Он работает на Кэрвинов. Они охотятся на демонов и прочих чудовищ. Поговори с Джонатаном, он глава их дома." },
    ["1042c"] = { common = "Тёмные настали времена. Каждая ветвь в лесу нашёптывает дурные вести, зло таится под каждым камнем. И в такую пору незнакомец приходит в мой дом и задаёт вопросы про воргенов... Прощения за свои подозрения я просить не буду, зато потребую ответить на них. И получу ответ." },
    ["1043a"] = { male = "Кажется, ты говоришь правду... Я не до конца понимаю твои мотивы, но если ты готов избавить Сумеречный лес хотя бы от небольшой части воргенов, я не буду допытываться. Важен результат. Воргены захватили рудник на юге. Они появились внезапно, но, насколько нам известно, нашествие началось именно с рудника. Ступай по своим делам, но если найдёшь что-нибудь важное, расскажи об этом мне. Мы готовы принять любую помощь в нашей войне с силами зла.", female = "Кажется, ты говоришь правду... Я не до конца понимаю твои мотивы, но если ты готова избавить Сумеречный лес хотя бы от небольшой части воргенов, я не буду допытываться. Важен результат. Воргены захватили рудник на юге. Они появились внезапно, но, насколько нам известно, нашествие началось именно с рудника. Ступай по своим делам, но если найдёшь что-нибудь важное, расскажи об этом мне. Мы готовы принять любую помощь в нашей войне с силами зла." },
    ["1043c"] = { male = "Интересные вещи ты рассказываешь, герой. Хотя семья Карвин не настолько влиятельна, чтобы добраться до корня проблемы и решить её раз и навсегда, мы делаем всё, что в наших силах, чтобы уменьшить число воргенов в Сумеречном лесу. Я уже велел Калору уделить этому первоочередное внимание.", female = "Интересные вещи ты рассказываешь, героиня. Хотя семья Карвин не настолько влиятельна, чтобы добраться до корня проблемы и решить её раз и навсегда, мы делаем всё, что в наших силах, чтобы уменьшить число воргенов в Сумеречном лесу. Я уже велел Калору уделить этому первоочередное внимание." },
    ["1044a"] = { male = "Мы разберёмся с воргенами, не беспокойся. Искореним зло, которое твоя подруга невольно принесла в наши леса. Мы не в обиде на неё. Странные вещи творятся в наши времена, и тьма не ведает пощады. Не буду тебя задерживать. Уверен, многие захотят узнать о том, что ты обнаружил в рудниках Сумеречного леса.", female = "Мы разберёмся с воргенами, не беспокойся. Искореним зло, которое твоя подруга невольно принесла в наши леса. Мы не в обиде на неё. Странные вещи творятся в наши времена, и тьма не ведает пощады. Не буду тебя задерживать. Уверен, многие захотят узнать о том, что ты обнаружила в рудниках Сумеречного леса." },
    ["1044c"] = { common = "Так вот какова судьба Велинды? Верховная жрица огорчится, услышав об этом – они очень дружили до исчезновения Велинды. И всё же Коса Элуны несомненно была дарована Велинде нашей богиней, и очень плохо, что этот священный предмет попал в недобрые руки. Впрочем, это отдельный разговор. Я премного благодарна тебе за твои достижения." },
    ["1045a"] = { common = "Ночные эльфы стары, как время, но их надменность разрушает их собственный мир. А теперь ещё и наши жизни. Но это уже никак не получится контролировать... Я много в чём могу обвинять эльфов, но мы всё равно отвечаем за свои деяния. Даже не подвергнувшись порче, мы способны творить великое зло. Рэн Кровавый Клык – такое зло. Жаждущий мощи, алчный... порча только сделала его сильнее. Меня сжигает ненависть к эльфам, но я не хочу зла их детям, так что сами должны обуздать своих." },
    ["1045c"] = { common = "Хорошая работа. Лес всё ещё осквернён, но мы по крайней мере знаем, что сделали хоть немного для того, чтобы вернуть его прежнюю красоту. Если пожелаешь снова вернуться ко мне, я буду рад обществу сородича. Удачи тебе. Возможно, наши племена снова встретятся в не столь жестокие времена." },
    ["1046a"] = { common = "Возвращайся в своё племя и поведай им о нашей победе. Покажи им свой трофей и насладись славой..." },
    ["1046c"] = { common = "Значит, вот он – череп самого лютого фурболга в Ясеневом лесу? Я более чем довольна твоими способностями. Не знаю даже, как часовым отблагодарить тебя. Надеюсь, в будущем мы снова сможем положиться на тебя, чтобы помочь нашему народу. Я положу этот череп и жезл Дартола на почётное место, чтобы все их увидели. Теронис гордился бы тобой. Ещё раз спасибо тебе." },
    ["1047a"] = { common = "Внимание, герои! Круг Кенария ищет компетентных помощников для исследования нового обширного пограничья Калимдора -запретных диких краев, полных невообразимых опасностей, что лежат к западу от Танариса и Прибамбасска! Кругу нужны добровольные и честные помощники, что будут действовать в его интересах! Все заинтересованные лица да обращаются в Круг Кенария! За дополнительной информацией обращайтесь к верховному друиду Фэндралу Оленьему Шлему в Дарнассе!" },
    ["1047c"] = { common = "С чего ты решил, что я буду утруждать себя беседой с таким, как ты, герой? Вот сейчас я брошу мои великие каждодневные труды и стану искать для тебя эту безделицу! Ведь благополучие Дарнасса — нет, всего Тельдрассила — в сравнение не идёт с важностью поиска этой пустяковины для твоей коллекции! Сначала эти недоумки из Лунной поляны отнимают у меня время своими просьбами о помощи, а теперь я ещё и это сносить должен?" },
    ["1048a"] = { male = "Хотя Тёмную Госпожу больше всего тревожит продвижение Короля-лича на север, моё дело – заботиться о более насущных проблемах. И главная из них – человечишки, зовущие себя Алым орденом. Тирисфальские луга кишмя кишат маленькими алыми муравьишками. Отправляйся в монастырь, герой, и избавь нас от Верховного инквизитора Вайтмейн и её подчинённых.", female = "Хотя Тёмную Госпожу больше всего тревожит продвижение Короля-лича на север, моё дело – заботиться о более насущных проблемах. И главная из них – человечишки, зовущие себя Алым орденом. Тирисфальские луга кишмя кишат маленькими алыми муравьишками. Отправляйся в монастырь, героиня, и избавь нас от Верховного инквизитора Вайтмейн и её подчинённых." },
    ["1048c"] = { male = "Ты сослужил Тёмной Госпоже отличную службу, герой. Это задание было не из лёгких. Я не забуду о твоей преданности Отрёкшимся и стойкости в битве.", female = "Ты сослужила Тёмной Госпоже отличную службу, героиня. Это задание было не из лёгких. Я не забуду о твоей преданности Отрёкшимся и стойкости в битве." },
    ["1049a"] = { common = "Намерения Служителей Земли относительно наших поражённых болезнью братьев чисты. Но кому ведомы замыслы тех, кто нашёптывает всякое Совету Старейшин? У Отрёкшихся, с которым мы ныне в союзе, вся история полна лжи. Слишком мы поторопились с союзом. Возможно, Кэрн прислушается к предупреждениям из Оргриммара. В недрах Монастыря Алого ордена находится \"Компендиум павших\", который стерегут безумные фанатики-люди. В том, что они творят, сквозит безумие, однако их исследования могут оказаться для нас полезными." },
    ["1049c"] = { male = "\"Компендиум павших\"! А я уж начал было сомневаться в том, что он вообще существует! Ты сослужил добрую службу тауренам Громового Утёса. Твоя преданность не будет забыта.", female = "\"Компендиум павших\"! А я уж начал было сомневаться в том, что он вообще существует! Ты сослужила добрую службу тауренам Громового Утёса. Твоя преданность не будет забыта." },
    ["1050a"] = { common = "Будущее неотвратимо! Мы стремимся к нему подобно тому, как дождевые капли стремятся к Великому морю. Но, изучая прошедшее, мы узнаём, что ждёт нас в грядущем, и готовимся к встрече с неведомым. Прежде чем великие беды обрушились на Лордерон, в Тирисфальских лесах находился оплот знаний. Ходят слухи, что в библиотеке старого монастыря хранится книга под названием \"Мифология Титанов\". Принеси её мне – и, возможно, вместе мы сможем заглянуть в тайны прошлого!" },
    ["1050c"] = { male = "Ты спас священный текст! Твоё путешествие было долгим, а уж добыть такую книгу было несомненно трудно. Но дворфы Стальгорна от твоего успеха получат огромную выгоду. Спасибо тебе, от лица всей Лиги Исследователей.", female = "Ты спасла священный текст! Твоё путешествие было долгим, а уж добыть такую книгу было несомненно трудно. Но дворфы Стальгорна от твоего успеха получат огромную выгоду. Спасибо тебе, от лица всей Лиги Исследователей." },
    ["1051a"] = { male = "Моя воля свободна, и всё же я не могу более служить Тёмной Госпоже. Я чувствую, что время, отпущенное мне в Азероте, подходит к концу. Жизненные силы покидают меня. Дознаватель Вишас всему виной! Он пытал меня много недель! Мало того, он отобрал у меня обручальное кольцо и нацепил его на палец своей жене! Чудовище! Я жажду мести! Этот глупец похвалялся своей прекрасной женой Нэнси, что живёт у озера Лордамер. Я хочу, чтобы ты отыскал её и вытряс из неё душу вместе с моим кольцом! Верни кольцо моей жене Монике, она живёт в Мельнице Таррен. Исполни мою последнюю волю.", female = "Моя воля свободна, и всё же я не могу более служить Тёмной Госпоже. Я чувствую, что время, отпущенное мне в Азероте, подходит к концу. Жизненные силы покидают меня. Дознаватель Вишас всему виной! Он пытал меня много недель! Мало того, он отобрал у меня обручальное кольцо и нацепил его на палец своей жене! Чудовище! Я жажду мести! Этот глупец похвалялся своей прекрасной женой Нэнси, что живёт у озера Лордамер. Я хочу, чтобы ты отыскала её и вытрясла из неё душу вместе с моим кольцом! Верни кольцо моей жене Монике, она живёт в Мельнице Таррен. Исполни мою последнюю волю." },
    ["1051c"] = { common = "Воррел был мне добрым супругом... Проклятые смертные! Никогда нам более не быть вместе. По крайней мере, я найду утешение в свершённой тобой мести. Благодарю тебя. А теберь оставь меня наедине с моим горем." },
    ["1052a"] = { common = "Мы, рыцари Алого ордена, заявляем свои права на укрепления от Дольного Очага до Тирисфальских лесов. Мы гордимся нашей борьбой за чистоту Лордерона! Вы подтвердили свою репутацию, сражаясь против нежити в Пустошах. Но настоящая угроза исходит из Лордерона. Отправляйтесь в Восточные королевства, в город Южнобережье. Отнесите письмо с моими рекомендациями и печатью рыцарю Ролею Благочестивому. Он проводит вас в Монастырь Алого ордена." },
    ["1052c"] = { common = "Брат Антон по-прежнему проповедует идеи Алого ордена? О-ох..." },
    ["1053a"] = { common = "Я всегда служил Алому ордену, гордился им и почитал служение за честь. Мне было чем гордиться, ведь мы спасали Азерот от нежити. Но после некоторого времени, проведённого в монастыре Тирисфальских лесов, я понял, что не ведал об истинных намерениях высшей иерархии ордена. Каждого, кто не принадлежит к ордену, они почитают грешниками. Невинных мужчин и женщин подвергают пыткам, полагая их нечистыми. Во имя Света, Алый орден должен быть сокрушён. И вам, по силам остановить это чудовище." },
    ["1053c"] = { male = "Хотя путь Света не приемлет убийств и кровопролитий, но в подобных случаях кровавая жертва служит благу королевства и всего мира. Ваши деяния в монастыре помогли спасти множество невинных жизней. путник, я восхищаюсь вашей решительностью.", female = "Хотя путь Света не приемлет убийств и кровопролитий, но в подобных случаях кровавая жертва служит благу королевства и всего мира. Ваши деяния в монастыре помогли спасти множество невинных жизней. путница, я восхищаюсь вашей решительностью." },
    ["1054a"] = { common = "Прямо к северу от Астранаара живут фурболги Колючего Меха. Мои разведчики доносят, что в последние несколько месяцев они чрезвычайно умножились числом. Если они слишком расплодятся, то могут набраться наглости напасть на Астранаар! Убей их, сколько сможешь, главное – принеси мне череп их предводителя в знак того, что их усилия напрасны...пока. Я останусь в Астранааре и буду ждать вестей от тебя. Да пребудет с тобой Элуна." },
    ["1054c"] = { common = "Славная работа. Эти фурболги постоянно угрожают нам. По счастью, теперь они некоторое время будут сидеть тихо." },
    ["1055a"] = { common = "Воссозданный жезл у вас в руках. Шаэлдрин захочет услышать о ваших успехах." },
    ["1055c"] = { common = "У тебя получилось! Великолепно!" },
    ["1056a"] = { male = "Лесные духи говорят мне, что ты отважен и лёгок на подъём. На юге, неподалёку от озера Мистраль, находится туннель, именуемый Туннель Когтя. Через этот туннель ты попадёшь в место, называемое Утёс Ветрорезов, в Когтистых горах. Попав туда, иди на юго-запад мимо Скалистого озера, а затем на север, вверх по крутому склону, пока не доберёшься до Пика Каменного Когтя. Там ждёт хранитель Албагорм. Выслушай его просьбу, герой. Путешествие будет опасным.", female = "Лесные духи говорят мне, что ты отважна и легка на подъём. На юге, неподалёку от озера Мистраль, находится туннель, именуемый Туннель Когтя. Через этот туннель ты попадёшь в место, называемое Утёс Ветрорезов, в Когтистых горах. Попав туда, иди на юго-запад мимо Скалистого озера, а затем на север, вверх по крутому склону, пока не доберёшься до Пика Каменного Когтя. Там ждёт хранитель Албагорм. Выслушай его просьбу, героиня. Путешествие будет опасным." },
    ["1056c"] = { common = "Наконец-то! Вижу, Фальдреас прислушался к духам лесов..." },
    ["1057a"] = { common = "Несомненно, будучи защитником лесных духов, можешь догадаться, почему я так встревожен. Чтобы достигнуть этого пика, тебе пришлось пройти через горы, и, конечно же, от глаз твоих не ускользнуло искажение, постигшее эту землю. Алчность привела к уничтожению священных холмов. Обугленная долина на юге сожжена механической армией жадных промышленников. Хуже того, клан Смертельной Ярости, вторгшийся на эти земли, отказывается пропустить нас – а ведь мы могли бы начать восстановление тех краёв! Изгони прочь злобных гарпий!" },
    ["1057c"] = { common = "Теперь, когда клан Смертельной Ярости понёс большие потери, вероятно, и начнётся истинная работа по восстановлению этих земель..." },
    ["1058a"] = { common = "Я в восхищении! Три маленьких клетки для трёх маленьких эльфов. Ну-с, что бы нам сделать с нашими дорогими друзьями-древолюбами? Что ж, дадим им попробовать... как бы это они сказали... лесной магии! Мне нужна добрая порция слизи Каменного Когтя. Принеси мне несколько сумеречных усиков этих ужасных кошек. И конечно же, потребуется множество глаз бегового оленя – глаз всегда не хватает! Да, и ещё, последнее, чуть не забыл: драгоценную чешуйку волшебного дракончика. Живо в Каменный Коготь, чтобы я мог сварить немножко лесной магии!" },
    ["1058c"] = { common = "О, как счастливы будут эти маленькие лесные нимфы! Мы заставим их почувствовать себя как дома при помощи этого особого отвара!" },
    ["1059a"] = { common = "Мы одержали победу над кланом Смертельной Ярости. Но они скоро соберут силы и вернутся, если не предпринять решительные действия. Далеко на юге Пустошей находится земля, известная как Тысяча Игл. Если идти на запад Тысячи Игл до тех пор, пока не достигнешь границ густого леса Фералас, то встретишь друида по имени Фалфиндер Хранитель Дорог. Этот сильный и мудрый друид способен призвать великих лесных духов, которые помогут в восстановлении Обугленной долины. Поведай ему о нашей беде! Отправляйся на его поиски немедленно!" },
    ["1059c"] = { common = "Хранитель Албагорм поступил мудро, прислав тебя со срочным известием. Будем надеяться, что мы успеем призвать помощь, и что эта помощь из великого леса прибудет в Обугленную долину не слишком поздно." },
    ["1060a"] = { male = "Ты сделал мне много добра. Можно сказать, ты мой талисман удачи, и я хочу поручить тебе кое-что ещё. Гарпии не всегда жили в Степях, они происходят из гор Каменного Когтя, раскинувшихся на северо-западе. Хоть там и опасно, мне нужно послать письмо старому другу, живущему там, знахарю Джин'Зилу. Он будет рад, узнав о смерти Серены Кровавое Перо, а тебе в тех краях понравится. Занятное место.", female = "Ты сделала мне много добра. Можно сказать, ты мой талисман удачи, и я хочу поручить тебе кое-что ещё. Гарпии не всегда жили в Степях, они происходят из гор Каменного Когтя, раскинувшихся на северо-западе. Хоть там и опасно, мне нужно послать письмо старому другу, живущему там, знахарю Джин'Зилу. Он будет рад, узнав о смерти Серены Кровавое Перо, а тебе в тех краях понравится. Занятное место." },
    ["1060c"] = { common = "А, письмо от Дарсока. Давно от него не было вестей. Значит, последняя из Кровавых Перьев мертва? Отличные вести. Я хорошо помню, как мой друг Рохан пошёл убивать её старшую сестру с этим психом из Мок'Натала. Да, тогда я был молод, как ты сейчас." },
    ["1061a"] = { common = "Духи Когтистых гор разгневаны: гоблины и их приспешники разоряют и выжигают земли. Земля возопила, и те, кто способен слышать – услышали. В Когтистые горы отправилась Сирит Камнеломм, многообещающий шаман Орды. Она сообщает, что гоблины вырубили много леса, и просит о помощи. Отправляйся в Когтистые горы, найди там Сирит. Чтобы туда добраться, ступай от Перекрёстка в Степях по дороге на запад. Сирит стоит лагерем близ Долины Высокого леса." },
    ["1061c"] = { male = "А, герой! Очень кстати. Нам понадобится твоя помощь, чтобы управиться с этими лиходеями!", female = "А, героиня! Очень кстати. Нам понадобится твоя помощь, чтобы управиться с этими лиходеями!" },
    ["1062a"] = { common = "Торговая Компания, которой управляют гоблины, вторглась в Когтистые горы. Они валят деревья, выжигают большие участки леса. Духи этих земель вне себя от боли и ярости. Мы должны остановить Торговую Компанию! Отправляйсся на северо-запад, за Долину Высокого леса, к Утёсу Ветрорезов. Ты найдёшь гоблинов и их прислужников за работой – покажи же им, что Орда не позволит разорять Когтистые горы. Поговори с ними на том языке, который они лучше всего понимают... На языке беспощадной силы!" },
    ["1062c"] = { common = "Это подлинно отважное деяние. Вероятно, в конце концов нам понадобится мудрость тауренских старейшин, чтобы успокоить духов Каменного Когтя, но... Первый шаг в верном направлении сделан – Торговая Компания лишилась работников." },
    ["1063a"] = { common = "Чтобы узнать, как окончательно успокоить духов Когтистых гор, нам нужно посоветоваться со старейшинами тауренов. Я мало знаю о том, кто предводительствует тауренами, но одно имя мне известно: Магата. Я слышала, что она очень стара и много знает. Если кто из тауренов и может оказать нам помощь касательно духов, то это она. Магата живёт в главном городе тауренов Громовом Утёсе, на Вершине Старейшин – это северо-восточная вершина города. Поговори с Магатой и расскажи ей о том, что творится в Когтистых горах." },
    ["1063c"] = { common = "Я приветствую тебя. Ты ищешь совета?" },
    ["1064a"] = { common = "Таурены в сродстве с этой землёй, и мне больно слышать о том, что творится в Каменном Когте. Но я боюсь, что для исцеления этой земли нам прежде придётся справиться с той заразой, что терзает нас самих. Разве не удача, что Отрёкшиеся теперь с нами? Они много знают о заразных болезнях. Я уверена, что они смогут помочь нам и тем укрепят доверие между нашими народами. Поговори с аптекаршей Замой. Она – учёная и представитель Отрёкшихся. Ты найдёшь её у Прудов Видений под Уступом Духов." },
    ["1064c"] = { common = "Магата прислала о тебе весточку. Хотя сердце моё уже и не бьётся, оно всё же разрывается от горя по духам Каменного Когтя. Отрёкшиеся готовы помочь всем, чем только можно." },
    ["1065a"] = { common = "Нам придётся прибегнуть к чрезвычайным мерам, чтобы избавить Каменный Коготь от Торговой Компании. Но только без кровопролития. У одного моего коллеги может найтись то, что нам как раз для этого случая и нужно. Его зовут Лидон, он живёт в городе Мельница Таррен в предгорьях Хилсбрада, в далёком краю Лордерон. Чтобы добраться до Хилсбрада, отправляйся на дирижабле в нашу столицу, Подгород. Оттуда иди на север в Тирисфальские леса, что к юго-западу от Серебряного бора, а затем на юг, в Хилсбрад. Найди Лидона и передай ему эту записку. Там написано, что нам от него нужно." },
    ["1065c"] = { common = "Записка от Замы? Наверняка её сильно прижало, раз пишет в такую даль. Посмотрим... Замечательно! Я знаю, что ей надо!" },
    ["1066a"] = { common = "Я создам яд, который остудит пыл Торговой Компании. Они станут слабыми и покорными. Это же решит проблемы Орды в Каменном Когте, да? Но для создания отравы мне понадобится кровь невинных, а её нелегко найти. К счастью, Синдикат, группа грабителей, насчитывает в своих рядах несколько тёмных магов... а они собирают кровь невинных для своих нечистых целей. Тёмных магов Синдиката можно найти в крепости Дарнхольд на юго-востоке." },
    ["1066c"] = { common = "Очень хорошо! Надеюсь, Синдикат не причинил тебе особых проблем? Как я и говорил, кровь невинных не так уж легко добыть. Нам повезло, что трудную часть работы взяли на себя маги Синдиката. А теперь подожди, я создам мой состав..." },
    ["1067a"] = { common = "Вот отрава. Если воспользоваться ей против Торговой Компании, результаты должны оказаться весьма благоприятными – возможно, удастся добиться даже распространения новой заразы. Мне не терпится испытать свою работу в деле! Впрочем, прежде отнеси её аптекарю Заме. Она должна придумать наиболее эффективный способ использования отравы." },
    ["1067c"] = { common = "Отрава от аптекаря Лидона? Замечательно. Если я знаю Лидона, она очень хорошо подействует на Торговую Компанию..." },
    ["1068a"] = { common = "Есть связь между духовной магией шаманов и природной магией друидов. Именно поэтому мы, шаманы, можем слышать мольбы духов Каменного Когтя. Я могу разобрать не всё, что они шепчут, однако одно послание - одно видение - было чётким... В этом видении я узрела на Утёсе Ветрорезов, на северо-западе Долины Высокого леса, две человекоподобные машины, которые валили деревья с невероятной скоростью. Этих металлических тварей нужно остановить! В явленном мне видении я заметила, что машины эти отмечены странными символами: экс-ти:четыре и экс-ти:девять." },
    ["1068c"] = { common = "Уничтожение машин экс-ти:четыре и экс-ти:девять успокоило многих духов Каменного Когтя. Будем надеяться, что после потери этих машин Торговая Компания покинет эти горы. Ибо если этого не произойдёт, то бедствия, постигшие эти земли, могут оказаться бледной тенью того, что ждёт нас впереди." },
    ["1069a"] = { common = "В Пиратской бухте фантастический спрос на омлеты из паучьих яиц! Проблема в том... что яиц в Бухте нет. Я чую прибыль! На Утёсе Ветрорезов и в Сиширском каньоне, в Когтистых горах на северо-западе, живут моховые пауки. Принеси мне их яйца, и я неплохо заплачу! На Утёсе Ветрорезов паучьи кладки можно найти под оставшимися деревьями. В Сиширском каньоне... хм, если у тебя слабый желудок, можешь собирать яйца только на Утёсе Ветрорезов..." },
    ["1069c"] = { common = "Ты принёс мне яйца! Спасибо! Я пошлю их Дыбоволосу, и он переправит мой товар в Пиратскую бухту! Вот твоя доля. Без тебя мне бы не справиться." },
    ["1070a"] = { common = "Привет тебе. Судя по виду, ты много путешествуешь. Тебе приходилось бывать в Когтистых горах? Эта земля опустошена Торговой компанией и прочими врагами ночных эльфов. Недавно часовой Волкопас послала туда мою подругу Келу Копьё Тени, чтобы она узнала, что происходит в тех землях, однако до сих пор от неё нет вестей. Я ещё беспокоюсь и потому, что Альянс отправил вместе с ней гнома-мага... это, несомненно, повод для тревоги. Может быть, ты найдёшь её и пошлёшь весточку мне?" },
    ["1070c"] = { common = "А, так ты здесь по просьбе Тары из Ясеневого леса... я так скучаю по ней, по моей родине, по друзьям. Должно быть, ей хорошо среди часовых, раз прочие дела передаёт путникам. Я горжусь за неё. Рада познакомиться с тобой." },
    ["1071a"] = { common = "Понимаешь ли, я состою в Просвещённой Ассамблее Чародейства, Алхимии и Технических Наук, и моя цель... нет, мой ДОЛГ! – показать ночным эльфам, что единение магии, реактивов и механизмов поможет спасти их леса. Однако это тяжёлая война, а гоблины, похоже, плодятся, словно кролики. У меня даже нет времени воплотить в жизнь свои новые изобретения! Мне нужно время для планирования и организации. Но для этого мне потребуется твоя помощь – сдерживать натиск гоблинов у Утёса Ветрорезов к востоку отсюда..." },
    ["1071c"] = { common = "Спасибо тебе за помощь. Да и вернуться тебе удалось как раз вовремя. Кажется, я выработал идеальный план... взрывчатка. Нет, это не сам план, это его часть. Понимаешь ли, я использую сильные взрывчатые вещества – не волнуйся, они далеко не так опасны, как считается – для того, чтобы припугнуть гоблинов. Я смогу как следует нагнать на них страху, разместив в ключевых местах на границах горной местности заряды, однако в ближайшие несколько дней мне может не хватить материалов..." },
    ["1072a"] = { common = "Устройство, о котором я думаю – моя самая продвинутая версия на сегодняшний день. Но мне нужно особое зелье, чтобы это устройство заработало. Я думаю, нам нужно добыть хороший состав, поскольку эта миссия может стать для тебя последней. А для этого нам нужно мощное взрывчатое вещество: нитромирглицероний. Единственный, кто может создать НГ-пять, это мой старый приятель – Ломак Демонтирс. Поищи его в Городе Механиков. Если уговоришь его сделать для нас немного НГ-пять, то я начну работать над размещением своих устройств." },
    ["1072c"] = { common = "А-а-а... Тебя послал Гаксим, вот как? А откуда мне знать, что ты не врёшь? Ась? Ась?.." },
    ["1073a"] = { common = "Ха-ха-ха!.. Тебе нужен нитромирглицероний, чтобы остановить гоблинов, уничтожающих лес?! Мне всё равно, знаешь ты Гаксима или нет... я дам тебе этот состав, чтобы посмотреть, как кого-нибудь разнесёт на мелкие кусочки: или тебя, или гоблинов. Но есть проблемка: у меня кончились химикалии. Но вот что я тебе скажу: принесёшь мне нужные зелья, и я прямо сразу же смешаю для тебя составчик. По крайней мере, ты докажешь, что кое-что понимаешь в алхимии, прежде, чем я передам тебе образец своего величайшего творения." },
    ["1073c"] = { common = "Вот это подойдёт. Не знай я тебя, я бы сказал, что ты кое-что понимаешь в алхимии... Ладненько, ладненько... в мире есть не только мечи и колдовство, верно?" },
    ["1074a"] = { common = "Ну вот тебе, держи. Тока поосторожней... это летучая смесь. Если Гаксим тебе и вправду друг, передай ему от меня привет. А если нет – взлетишь на воздух, вот будет тебе потеха." },
    ["1074c"] = { common = "Дело сделано, и сделано отлично. НГ-пять незаменимый компонент для поджига повозок с динамитом. Что? Да, динамит... целыми повозками. Это идеальный отвлекающий манёвр, я тебе скажу... подожди и увидишь." },
    ["1075a"] = { male = "Теперь о том, что касается дистанционных взрывов, входящих в мой план... ах да, я, кажется, ещё не объяснил этого? Ну так вот, вкратце: задействовав немного магии, я смогу сделать так, чтобы взрыв произошёл почти без твоего участия. Я соберу такое устройство, что тебе останется просто нажать кнопку, а где-то там взорвётся НГ-пять. Но мне нужно заклинание, которое есть у моего друга в Штормграде – его зовут Коллин Маурен. Ты сможешь отыскать его там в квартале магов. Он человек, так что будь внимателен, не ошибись.", female = "Теперь о том, что касается дистанционных взрывов, входящих в мой план... ах да, я, кажется, ещё не объяснил этого? Ну так вот, вкратце: задействовав немного магии, я смогу сделать так, чтобы взрыв произошёл почти без твоего участия. Я соберу такое устройство, что тебе останется просто нажать кнопку, а где-то там взорвётся НГ-пять. Но мне нужно заклинание, которое есть у моего друга в Штормграде – его зовут Коллин Маурен. Ты сможешь отыскать его там в квартале магов. Он человек, так что будь внимательна, не ошибись." },
    ["1075c"] = { common = "Да, вот то заклинание, которое тебе нужно – оно позволит производить взрывы на расстоянии... хмм." },
    ["1076a"] = { common = "А, кажется, я понял. Заклинание послания... полагаю, именно этого эффекта он хочет добиться. Мне нужно создать свиток с запечатлённым на нём заклинанием. Для этого мне нужен прах Пыледемона. Пока я собираю остальные компоненты, почему бы тебе не отправиться в Западный Край и не найти там одно из этих мерзких существ? Они опасны, но я уверен, что ты со всем справишься, если желаешь участвовать в одном из экспериментов Гаксима. Когда ты вернёшься, я буду здесь." },
    ["1076c"] = { common = "Подожди несколько секунд, и нужный тебе свиток будет готов." },
    ["1077a"] = { common = "Вот. Это то, что нужно. Когда в следующий раз увидишь Гаксима, передай ему от меня привет. Хотелось бы мне узнать, как закончится эта история. Всего тебе хорошего." },
    ["1077c"] = { common = "Великолепно! Славная работа. Это заклинание вместе с НГ-пять даст идеальную дистанционную взрывчатку. У нас получится прекрасный отвлекающий манёвр, и ты прокрадёшься и сопрёшь документы и инженерные планы Торговой Компании. Тогда они не смогут вырубать леса так быстро." },
    ["1078a"] = { common = "Путешественники постоянно спрашивают меня о Когтистых горах. Похоже, все ищут там приключений, причём самых разных: кому-то нужны виверны, кому-то – элементали, а у кого-то дела с Торговой компанией. В Обугленной долине, прячущейся среди пиков Когтистых гор, некогда обитали особые виды василисков: их чешуя, размолотая в порошок, была прекрасным реактивом для некоторых заклинаний, созданных мною. Если эти василиски ещё живут там, мне надо заполучить хотя бы несколько чешуек. Если не очень торопишься, удели на это немного времени, я хорошо заплачу тебе." },
    ["1078c"] = { common = "Великолепно. Спасибо тебе огромное. Может быть, и я когда-нибудь смогу помочь тебе." },
    ["1079a"] = { common = "Так вот, смотри и слушай внимательно. Все устройства доделаны и готовы к использованию. Возьми эти листы – здесь всё объясняется про детонаторы, взрывчатку и про то, как их разместить. Помни, успех твоей миссии не зависит от того, сколько разрушений ты сможешь причинить. План \"Альфа\" увенчается успехом в том случае, если ты принесёшь технические чертежи Торговой компании, находящиеся на лесопилке к югу от Скалистого Озера." },
    ["1079c"] = { common = "Просто великолепно! Это сильный удар по Торговой Компании. Мы сможем узнать уязвимые места их машин, а также использовать их разработки для наших собственных целей. Поистине, это великий день." },
    ["1080a"] = { male = "План Бета – почти то же, что и план Альфа. путник. Мы проводим отвлекающий манёвр, а потом похищаем их драгоценные письма. Главное – получить письма... помни это. На листках, которые я дал тебе, сказано, где поместить взрывчатку. Не погибни и вернись с добытыми письмами...", female = "План Бета – почти то же, что и план Альфа. путница. Мы проводим отвлекающий манёвр, а потом похищаем их драгоценные письма. Главное – получить письма... помни это. На листках, которые я дал тебе, сказано, где поместить взрывчатку. Не погибни и вернись с добытыми письмами..." },
    ["1080c"] = { common = "Великолепно! Каэла и часовые будут счастливы. При твоих умениях да моих творениях нас никто и ничто не остановит!" },
    ["1081a"] = { common = "Я уверена, что Тиранда Шелест Ветра лично хотела бы поблагодарить тебя за участие в этой миссии. Может быть, это и незаметно с первого взгляда, но деяния, совершённые с твоей помощью, способны помочь нам закрепиться в Когтистых горах. Если хочешь и далее помогать нам в борьбе, отправляйся на встречу с Тирандой в храм Луны в Дарнассе." },
    ["1081c"] = { male = "Приветствую тебя. Мне доводилось и прежде слышать твоё имя, и я рада видеть, что, не взирая на твою молодость, ты уже избрал свой путь. Ты окажешь мне великую честь, если примешь это как дар в знак нашего уважения к тебе.", female = "Приветствую тебя. Мне доводилось и прежде слышать твоё имя, и я рада видеть, что, не взирая на твою молодость, ты уже избрала свой путь. Ты окажешь мне великую честь, если примешь это как дар в знак нашего уважения к тебе." },
    ["1082a"] = { common = "Твоя помощь здесь оказалась поистине бесценной. Часовые Ясеневого леса вознаградят тебя, если ты уведомишь их, что я и Гаксим живы. Скажи им, что мы трудимся над тем, чтобы остановить Торговую компанию и исцелить эти земли. Найди в Астранааре Тару Тенисил, она обрадуется твоему возвращению и хорошим новостям." },
    ["1082c"] = { male = "Благодарю тебя. Ты сослужил Стражам хорошую службу. Я рада узнать, что Каэла... и даже Гаксим живы и здоровы. Ты заслуживаешь нашего уважения.", female = "Благодарю тебя. Ты сослужила Стражам хорошую службу. Я рада узнать, что Каэла... и даже Гаксим живы и здоровы. Ты заслуживаешь нашего уважения." },
    ["1083a"] = { common = "Не могу сказать точно, что Торговая компания сделала с Долиной, однако ясно, что обитающие там существа взяли над ними верх. Представители Торговой компании подожгли лес, они использовали свои убийственные изобретения для того, чтобы как можно сильнее опустошить Долину. Но в невежестве своём они также освободили нечто иное: пылающих духов, элементалей огня, камня и ярости. И этой земле никогда не узреть улыбку Элуны, пока эти существа бродят на свободе. Принеси мне их дымящиеся угли, дабы доказать, что тебе удалось сократить число разъярённых духов." },
    ["1083c"] = { common = "Останки нашего врага... твоя сила сослужила нам добрую службу. Благодарю тебя." },
    ["1084a"] = { common = "Мне кажется очевидным, что защитники долины – древни – вели какие-то дела с Торговой компанией, прежде чем их оттеснили прочь. К несчастью, даже эти некогда великие охранители ныне впали в нечестие. Гаксим полагает, что их падение каким-то образом связано с оружием, которое гоблины использовали во время отступления. Я сказала ему, что возьму образец из тела раненого древня и отдам на изучение, чтобы понять, правда ли это. Принеси мне немного шрапнели, чтобы гном мог дать мне ответ..." },
    ["1084c"] = { common = "Спасибо. Этого должно быть более чем достаточно, чтобы Гаксим выяснил, каким образом скверна пала на древней. Я немедленно передам ему этот образец." },
    ["1085a"] = { common = "Положение здесь, в Каменном Когте, явно не способствует совместной работе ночного эльфа и гнома. Торговая компания опустошила эти земли, и большая часть моего времени уходит на то, чтобы положить предел уничтожению. Не суди Гаксима преждевременно; он понимает, что нам с ним необходимо трудиться вместе. Если ты хочешь помочь нам, то для начала поговори с Гаксимом. Извини, что пока не могу отослать тебя обратно к Таре с хорошими новостями. Может быть, вскоре..." },
    ["1085c"] = { common = "Предательская... предательская и опасная, вот какова эта земля. Но я тут для того, чтобы показать ночным эльфам, что ежели призвать на помощь старое доброе инженерное дело и чуточку магии, то так будет вернее. Видишь ли, если убрать магию совсем, то ночным эльфам это никак не поможет – они без неё не могут. И мир без неё не может. А вот если подкрепить магию инженерным делом да алхимией, то так оно будет правильнее. Возможностей просто масса." },
    ["1086a"] = { common = "Отрава готова. Остаётся только её доставить адресату. И это придётся сделать тебе. У Торговой Компании есть средства доставки сообщений и лёгкого груза от штаб-квартиры до Когтистых гор. Скорее всего, это маленький аэропорт, подходящий не для дирижабля, а для ветролёта. Обыщи все области Когтистых гор, находящиеся под контролем Торговой Компании, и найди этот аэропорт, если он существует. Как найдёшь, помести туда отраву. Положишь – беги оттуда." },
    ["1086c"] = { male = "Ты нашёл аэропорт? Молодец! Отличный сюрприз ждал гобинов! Будем надеяться, что яд доберётся до их штаб-квартиры. Ты оказал своему народу неоценимую услугу, и пусть тебя не мучает совесть из-за отравления Торговой Компании. Они ещё не того заслуживают. И вот какой мудрости союзникам Отрёкшихся стоит поучиться: Не бойся тёмных дорог... если они ведут к победе.", female = "Ты нашла аэропорт? Молодец! Отличный сюрприз ждал гобинов! Будем надеяться, что яд доберётся до их штаб-квартиры. Ты оказала своему народу неоценимую услугу, и пусть тебя не мучает совесть из-за отравления Торговой Компании. Они ещё не того заслуживают. И вот какой мудрости союзникам Отрёкшихся стоит поучиться: Не бойся тёмных дорог... если они ведут к победе." },
    ["1087a"] = { common = "Ты и представить себе не можешь, как я ненавижу эти омерзительные земли! Отродья Кенария и кальдорайские друиды, обитающие на этом пике, используют свою жалкую силу, чтобы подавить поток магии, даже так далеко на юг от их гнусного обиталища... их драгоценных лесов. Я так хочу вернуться в Джеденар и купаться в потоках магии, но мой господин не позволяет мне вернуться, пока моя работа здесь не будет завершена. Не сомневаюсь, что ты любишь ночных эльфов и их союзников не больше, чем я. Помоги мне, и мы оба внакладе не останемся." },
    ["1087c"] = { common = "Я уже это чувствую... да... прекрасная мощь... струящийся поток. Как же глупы кальдораи, что отвергают дары этого мира, не дают магии свободно, словно песня, струиться по жилам. Как же скучна и бесцветна жизнь без этого огненного потока!" },
    ["1088a"] = { common = "Они думали, что могут остановить течение магии. Но они ошиблись. Они думали, что смогут спрятать Хорданиуса – но я заполучу его голову! Магия даёт мне способность видеть истину. Да... вот он где. Скрещение путей... На вершине великого древа в Ясеневом лесу. Название... Приют в Ночных Лесах. Один из старших сыновей лесного бога. Они унесли его прочь с этого пика прежде, чем я смогла найти его, однако его время на исходе. Принеси мне его голову, и я поделюсь с тобой могуществом." },
    ["1088c"] = { common = "Некогда, давным-давно, я знала Хорданиуса. Он был горд, как и все его сородичи, и ставил себя даже над высокорождёнными. Однако теперь ему трудно так же высоко держать голову, не так ли? Я обещала тебе награду, и ты её получишь. Слушай меня!" },
    ["1089a"] = { common = "В Пещере Когтей друиды построили Логово Когтя, где хранят множество могущественных предметов. Они продумали сложный план, чтобы не дать этим предметам попасть в чужие руки. К счастью, мне удалось... вытянуть некоторые подробности из одного из них. В маленьком светильнике у входа в пещеру ты найдёшь спрятанный там Ключ Хранителя Врат – с его помощью ты сможешь отворить тайники, расположенные вокруг логова. А предметы из этих тайников помогут тебе открыть сокровищницу, размещённую в одном из центральных помещений." },
    ["1089c"] = { common = "Когда три ключа вошли каждый в своё отверстие, посреди мерцающего сияния появились несколько предметов." },
    ["1090a"] = { common = "Знаешь, когда-то я был второй по важности персоной во всём этом деле. Всё изменилось, когда главным стал Геренцо. Уволил моего начальника Зиза Физзикса, а меня послал работать в копях. Но Зиз велел мне оставаться здесь и собирать сведения. Его новое начальство хорошо заплатит нам, если мы узнаем, что планирует Геренцо. В любом случае, я точно знаю, что Геренцо приказал добыть как можно больше этой золотисто-зелёной руды. Я могу раздобыть образец, а ты передашь его Зизу. Но пока я этим занимаюсь, следи, не покажется ли стража." },
    ["1090c"] = { common = "Спасибо. Тут выдалось несколько опасных моментов, да и мы, наверное, были не слишком-то внимательны. Но важно то, что у нас теперь есть образец руды, и мы должны как можно скорее доставить его Зизу." },
    ["1091a"] = { common = "Отнеси эти письма Каэле. Уверен, что она захочет это узнать. По крайней мере, часовые точно захотят. И обязательно расскажи ей о наших успехах и о том, что мы не добились бы ничего без чуточки магии." },
    ["1091c"] = { common = "Это действительно интересно. Вы с Гаксимом всё сделали правильно. Благодарю." },
    ["1092a"] = { common = "Полагаю, мне тоже нужно убираться отсюда. Не пройдёт много времени. как слухи о том, что произошло здесь, распространятся достаточно высоко, и вряд ли меня в следующий раз встретят там с добром да лаской. Мне нужно выбраться наружу и встретиться с Зизом. Надеюсь, он мне подыщет новую работёнку!!! Я попытаюсь тут слегка подчистить за собой, но тебе придётся доставить образец руды Зизу немедля. Он говорил мне, что разбил свой лагерь где-то за западном склоне Утёса Ветрорезов. Удачи!" },
    ["1092c"] = { common = "А, я так и знал, что правильно сделал, когда сказал Пузнику остаться. Я уверен, что инженеры в Нижней шахте захотят на это взглянуть. Конечно, я собираюсь прихранить кусочек для себя, но если они чего-то не узнают, то это им и не повредит, верно?" },
    ["1093a"] = { common = "Ну, Торговая Компания и наломала дров! О чём они только думали? Гоблинская компания нанимает гнома! К счастью для меня, Пароклапан всегда может узнать гения с первого взгляда. Он нанял меня сразу же, как меня выгнали оттуда! Мне сказали, что компания строит какие-то огромные лесорубные машины, и Клапан хочет, чтобы я украл для него чертежи. К несчастью, Геренцо – вот ведь злобный гном! – хочет меня убить... может быть, ты вместо меня украдёшь чертежи? Они должны быть у кого-то из операторов компании." },
    ["1093c"] = { common = "Эй, это то, что я думаю? Отлично! Ну-с, посмотрим... и как мне понимать эту ерунду?.. и чем только думают эти гномы? Удивительно, что они хотя бы колесо сумели соорудить, не говоря уж об этих их обожаемых ветролётах." },
    ["1094a"] = { common = "В этом конверте – все сведения, которые я смог собрать до того, как меня выпнули за дверь... Внутренние документы Торговой Компании, кое-какие руководства, технические бумажки... О, и, конечно, чертежи \"Супер-потрошителя шесть тысяч\". Паровой Клапан обосновался в Кабестане в Степях. Тебе не доставит труда разыскать его, это такой мелкий зелёный тип." },
    ["1094c"] = { common = "Физзик, да? Не то, чтоб я ему верил, но, кажется, это правильные сведения. Что б я ни отдал, лишь бы Торговая Компания убралась подальше! Хотя они притащили с собой кое-какие хорошие машины... не буду отрицать, что от их изобретений есть польза, когда эти изобретения применяем мы, а не кто-то другой..." },
    ["1095a"] = { common = "В Нижней шахте было много разговоров про этого гнома, нанятого Торговой Компанией. Торговые олигархи не одобряют, что Раздунк связался с Геренцо. Ридлвокс велел мне позаботиться об этой проблеме, и я не сомневаюсь, что это указание от одного из олигархов. Разумеется, директор мне об этом не говорил. Скажем так, у меня такое подозрение. Как бы то ни было, Геренцо необходимо устранить, и Физзику придётся хорошо поработать." },
    ["1095c"] = { common = "Убрать Геренцо? Я только за! Гномы вообще неприятный народ, но, судя по всему, этот Геренцо хуже других. Он был одним из главных инженеров Гномрегана и работал над тайным проектом – каким именно, нам так и не удалось узнать, хоть мы и пытались пробраться в Дун Морог. В докладах говорилось, что этот тайный проект буквально взорвался им в лицо." },
    ["1096a"] = { common = "Один раз я встречал Геренцо и, скажу тебе, видок у него отвратнее некуда. Такое впечатление, что его плоть гниёт и отпадает, части его тела заменены металлическими деталями и механизмами. К северо-востоку отсюда, высоко над Скалистым озером, вблизи водяного колеса находится пункт, откуда Геренцо наблюдает за всей местностью. Я не смог бы найти дорогу наверх, не говоря уж о том, чтобы справиться с Геренцо... Но тебе, кажется, это вполне под силу. Если ты убьёшь его по моей просьбе, то получишь щедрое вознаграждение!" },
    ["1096c"] = { common = "Взгляни на эту штуковину... только гном мог с такой управляться. Не понимаю только, зачем отрезать руку и заменять её этой штукой, если можно просто сохранить обе руки и приделать третью! Гномы, я тебе скажу... Геренцо, по крайней мере, если и не мёртв, то неисправен. Надеюсь, этого доказательства будет достаточно, и Пароклапан даст мне назначение в одну из мастерских Союза ремонтников в Прибамбасске или, может быть, даже в Нижней шахте." },
    ["1097a"] = { male = "Дворфу-оружейнику Гриманду Элмору нужна помощь с доставкой ценного груза. Думаю, он хочет отправить посылку домой, на север. Ты мне кажешься опытным путешественником... Так что если ты не против взять с собой небольшой груз, то поговори с Гримандом; конечно, тебе и тут можно найти занятие, но мы стараемся поддерживать хорошие отношения с дворфами. Гриманда Элмора можно найти в оружейной лавке в Штормграде, в Квартале Дворфов. Это в северо-восточной части города.", female = "Дворфу-оружейнику Гриманду Элмору нужна помощь с доставкой ценного груза. Думаю, он хочет отправить посылку домой, на север. Ты мне кажешься опытной путешественницей... Так что если ты не против взять с собой небольшой груз, то поговори с Гримандом; конечно, тебе и тут можно найти занятие, но мы стараемся поддерживать хорошие отношения с дворфами. Гриманда Элмора можно найти в оружейной лавке в Штормграде, в Квартале Дворфов. Это в северо-восточной части города." },
    ["1097c"] = { common = "Ты поможешь мне с доставкой? Замечательно!" },
    ["1098a"] = { common = "Готовясь к нападению на крепость Тёмного Клыка, мы отправили на разведку двух стражей смерти. Они не возвращаются вот уже много дней, но без их отчёта нам не организовать успешного нападения! Итак, вот твоё задание. Отправляйся в крепость Тёмного Клыка на юге и найди стражей смерти Адаманта и Винсента. Найди их и помоги им, если сможешь. Это очень опасное и важное задание. Не подведи нас." },
    ["1098c"] = { common = "Перед вами лежит израненное тело Винсента. Страж смерти Адамант написал отчёт Хадреку... Но что бы ни хотел добавить к его словам Винсент, он унёс это с собой в могилу. В мёртвой руке зажата небольшая безделушка..." },
    ["1100a"] = { common = "Вы медленно открываете потрёпанный дневник Хенрига Хмурня..." },
    ["1100c"] = { common = "Говорите, что нашли этот дневник у мёртвого дворфа? Дайте мне на минутку, хочу взглянуть..." },
    ["1101a"] = { common = "Бедный Гералат! И этот дворф... Хмурень. Каким он был храбрецом! Нельзя, чтобы их усилия пропали даром. Эта карга... Чарлга Остробок... нужно её убить. Разумеется, поход в лабиринты Иглошкурых будет опасным, а за помощью в Дарнасс посылать некогда. Так что тебе, придётся собрать отряд самостоятельно. Принеси мне медальон Чарлги Остробок в доказательство её смерти." },
    ["1101c"] = { common = "Наконец-то старая карга умерла. Это отличная новость! В наше опасное время всегда приятно встретить такого храбреца, как ты. Теперь, когда прислужники Остробок мертвы, мы сможем продолжить наши исследования той области. Возможно, теперь мы сможем узнать, почему место упокоения Агамаггана подверглось такому осквернению. Однако, боюсь, здесь не обошлось без предательства..." },
    ["1102a"] = { common = "Кэрн – благородный вождь, объединивший наш народ здесь, в Громовом Утёсе. Но я не могу так легко простить тех, кто изгнал нас с земель наших предков. Мой народ много десятилетий прожил в южных Степях. Те края для нас священны. Но нас изгнали многочисленные враги. Месть ждёт старую ведьму Чарлгу Острый Бок, которая повелевает нечестивым воинством в Лабиринтах Иглошкурых. Принеси мне сердце этой ведьмы, и я смогу спокойно умереть." },
    ["1102c"] = { male = "Теперь мерзкое племя Иглошкурых на себе испытает страдания моего народа! Пусть это будет им уроком. Изгнание целого народа из священной земли – этот грех заслуживает самой жестокой кары! Благодарю тебя, за то, что откликнулся на мою просьбу.", female = "Теперь мерзкое племя Иглошкурых на себе испытает страдания моего народа! Пусть это будет им уроком. Изгнание целого народа из священной земли – этот грех заслуживает самой жестокой кары! Благодарю тебя, за то, что откликнулась на мою просьбу." },
    ["1103a"] = { male = "Привет, братан! Ты тута, чтобы очистить воду и доказать Ислен, что не лыком шит? Я тока что прикончил осквернённого духа воды и как раз собираюсь сунуть его браслеты и остатки воды в жаровню. А эт што? А-а-а. Тьев понимает, бывает непруха. Что ж, Тьев нехило тебе поможет, если тебе снова нужен чистый водный дух. Принеси мне сапту воды от Ислен, покажи, что готов к новому заходу, а я уж приготовлю тебе, чё нужно.", female = "Привет, сеструха! Ты тута, чтобы очистить воду и доказать Ислен, что не лыком шита? Я тока что прикончил осквернённого духа воды и как раз собираюсь сунуть его браслеты и остатки воды в жаровню. А эт што? А-а-а. Тьев понимает, бывает непруха. Что ж, Тьев нехило тебе поможет, если тебе снова нужен чистый водный дух. Принеси мне сапту воды от Ислен, покажи, что готова к новому заходу, а я уж приготовлю тебе, чё нужно." },
    ["1103c"] = { male = "Хвала тебе, смелый герой. Рифы побережья Западного Края будут освещены благодаря твоим трудам. Множество жизней будет спасено, пока горит факел. Меня постигла бессмысленная смерть на этом самом побережье. Мой долг в иной жизни – следить, чтобы никто не повторил моей судьбы.", female = "Хвала тебе, смелый героиня. Рифы побережья Западного Края будут освещены благодаря твоим трудам. Множество жизней будет спасено, пока горит факел. Меня постигла бессмысленная смерть на этом самом побережье. Мой долг в иной жизни – следить, чтобы никто не повторил моей судьбы." },
    ["1104a"] = { common = "Я нарисовал уже столько чертежей нового болида! И все их надо непременно воплотить!!! Я разрабатываю новое топливо, которое будет гореть жарко-жарко-прежарко! Пока что у меня не получается, но, кажется, я знаю, что мне может помочь... У скорпидов с Мерцающей равнины совершенно особый яд, в нём чрезвычайно много солей. Он уникален! Как раз он-то мне и нужен. Принеси мне их яда и поверь: тогда наши болиды просто взлетят!" },
    ["1104c"] = { common = "Отлично! Этот яд как раз подойдёт! Спасибо! Теперь надо его вскипятить, добавить скиппер-отомер и нега-катализатор и... Чёрт! Где мои записи?!" },
    ["1105a"] = { common = "Мой брат составляет новое топливо для болида. Он в этом деле просто гений! Правда, боюсь, его новое гениальное топливо разъест всю машину... Поэтому я хочу укрепить топливные баки. Здесь, на равнинах, живут черепахи с очень прочными панцирями. Из них-то я и хочу сделать это покрытие – оно должно выдержать топливо моего брата. Ну как, не желаешь ли взяться за эту работу и принести мне несколько панцирей?" },
    ["1105c"] = { common = "Панцири! Спасибо! Ого, да они ещё твёрже, чем я думал! Вот примусь с ними работать – так, поди, целый ящик инструментов погну!" },
    ["1106a"] = { common = "Я разрабатываю новый двигатель, с которым мой болид помчится быстрее ветра! Помчится так, что даже сможет взлететь! Осталось мне сделать поршни, которые выдержат очень, очень высокое давление. Все мои испытания провалились потому, что я не смог сделать достаточно крепких поршней! Но есть тот, кто может мне помочь. Его зовут Мартек Изгой. Он отличный кузнец и знает о металлах больше других. Вот, отвези ему это письмо, я знаю, он поможет мне! Правда, живёт он далеко – в Азероте, в Бесплодных землях, в одном лагере с гоблином! Найди его!" },
    ["1106c"] = { common = "Пшикс отправил тебя? Тогда это совсем другое дело! Конечно, я помогу тебе. Пшикс и его брат - единственные гномы, которые не хотят моей смерти! Так Пшикс отправил тебя сделать поршни, да? Поршни достаточно сильны, чтобы выдержать то, что он планирует, и если я знаю Пшикса, то его новый болид будет просто бомбой на колёсах!" },
    ["1107a"] = { common = "Наш болид – это самая быстрая машина на равнинах! Она такая быстрая, что... я боюсь, что от трения её разнесёт на куски. Чтобы этого не произошло, мне нужен материал для покрытия движущихся частей машины. Он должен быть твёрдым, но не хрупким, и выдерживать соляную коррозию, иначе на Мерцающей равнине он долго не протянет. Слышали когда-нибудь про Коварный риф? Это у побережья Тернистой долины. Там обитает племя мурлоков под названием Соляная Чешуя, и их хвостовые плавники как нельзя лучше подойдут для моего материала." },
    ["1107c"] = { common = "Спасибо! Осталось размолоть их, добавить кое-какие ингредиенты, и всё будет готово. Тогда, по крайней мере, болид не пострадает от своей собственной скорости. Ещё бы он от какого-нибудь препятствия не пострадал..." },
    ["1108a"] = { common = "Я здесь не только потому, что хочу держаться ото всех подальше. В Бесплодных землях очень много металла, но добыть его сумеет не всякий. Этот металл называется индарилий, и говорят, что он обладает удивительной сопротивляемостью к температуре и механическим воздействиям. Как раз то, что нужно Пшиксу для его машины. Но я должен всё проверить. Принесите мне немного индарилия, а я исследую его свойства. Настоящая индарилиевая руда залегает глубоко в шахтах Ульдамана, но трогги из племени Каменного Свода иногда тоже носят с собой обломки индарилия. Принесите их мне." },
    ["1108c"] = { common = "Ах да, они пойдут. Теперь давай их накалим и посмотрим, что с ними будет…" },
    ["1109a"] = { male = "Как видишь, в Королевском фармацевтическом обществе проводят весьма... любопытные эксперименты. Поскольку я мастер-аптекарь, в мои обязанности входит наблюдать за самыми интересными проектами. Работы полно, а времени в обрез! Хоть ты и герой, но, судя по всему, немало странствовал. Не поможешь мне? Нам очень нужно редкое вещество. Оно на редкость мерзкое, и его получают только от особой разновидности летучих мышей, которые водятся в дыре под названием Лабиринты Иглошкурых. Принеси мне гуано летучих мышей Лабиринтов, и мы примемся за работу...", female = "Как видишь, в Королевском фармацевтическом обществе проводят весьма... любопытные эксперименты. Поскольку я мастер-аптекарь, в мои обязанности входит наблюдать за самыми интересными проектами. Работы полно, а времени в обрез! Хоть ты и героиня, но, судя по всему, немало странствовала. Не поможешь мне? Нам очень нужно редкое вещество. Оно на редкость мерзкое, и его получают только от особой разновидности летучих мышей, которые водятся в дыре под названием Лабиринты Иглошкурых. Принеси мне гуано летучих мышей Лабиринтов, и мы примемся за работу..." },
    ["1109c"] = { common = "Превосходно! Этого нам и не хватало." },
    ["1110a"] = { common = "Хе-хе, да тут такие гонки бывают, как же без происшествий! Вы только оглянитесь – все Мерцающие равнины просто усыпаны обломками разбитых болидов. И за все эти детали гномы и гоблины могут хорошенько заплатить. Они вечно ищут, какую бы ещё рухлядь привинтить на свои тачки. Ступайте и принесите мне побольше деталей, а я вам хорошенько заплачу." },
    ["1110c"] = { common = "Ого, вы только посмотрите! Кое-что хорошее в этой горе металлолома ещё есть. Наверняка я смогу продать это за кругленькую сумму. А... это что, оторванное ухо? Ой! Не хотел бы я быть на месте того пилота. Спасибо. Вот ваша плата. И ещё бесплатный совет... Делайте вид, что вы круче всех – и тогда вам всегда удастся нагреть руки на чужой беде." },
    ["1111a"] = { common = "Моя работа – выполнять запросы покупателей, а гномы заказали у меня набор деталей. Эти детали ещё неделю назад прибыли в Кабестан, но я всё никак туда не выберусь. Может, ты туда смотаешься? Вот, надо будет найти управляющего пристанью Головокружилкинса и отдать ему этот заказ. Если выполнишь моё поручение, я смогу доверить тебе и другие поручения. Разумеется, твой труд будет достойно оплачен." },
    ["1111c"] = { common = "Ах, да! Детали для Крейвела. Хорошо, что за ними пришли! Этот хлам валяется тут уже давно, я даже начал бояться, что он проржавеет!" },
    ["1112a"] = { common = "Вот посылка для Крейвела. И когда отнесёте, скажите ему... что если ему нужны ещё особые заказы, то придётся заплатить по всем счетам!" },
    ["1112c"] = { common = "Ура, детали! Надо отнести их гномам. Но сначала... Вынем оттуда кое-что..." },
    ["1113a"] = { common = "Зачем мне редкий вид гуано, спросишь ты. Отвечаю. Я хочу выяснить в ходе эксперимента, какое воздействие окажут друг на друга два диаметрально противоположных химических вещества, особенно если оба смешать с токсичным реагентом, чтобы результаты были... погаже. В северо-восточной части Тирисфальских лесов располагается Монастырь Алого ордена. В его стенах и за их пределами живут безумные последователи Алого ордена. Убей их и принеси мне их ревностные сердца .Наше варево будет поистине ужасающим." },
    ["1113c"] = { male = "Сколько же на тебе кровищи! Я вижу, ты неплохо потрудился!", female = "Сколько же на тебе кровищи! Я вижу, ты неплохо потрудилась!" },
    ["1114a"] = { common = "Ну вот, у меня есть всё, что нужно. Осталось только отнести эти детали Пшиксу Медноштифу. Он уже давно их ждёт – полагаю, он даже не заметит отсутствие одной маленькой детальки. Не стоит даже упоминать, что я её забрал. Эта деталька совсем маленькая и ненужная. Правда-правда." },
    ["1114c"] = { common = "Вот они! Мои гидромеханизмы и усилительные болты! То, что нужно. Большое спасибо!" },
    ["1115a"] = { common = "Ну вот, гномам услугу оказали, пора и гоблинам помочь! Говорят, что гоблинского пилота, Назза Парового Котла, раньше звали не так. Интересно, почему он сменил имя? Наверное, это секрет, и, скорее всего, он дорожит этим секретом. Если кто и знает правду, то только Кразек из Пиратской бухты, на южном мысу Тернистой долины. Поговорите с Кразеком и разузнайте у него про нашего пилота-гоблина. Если вам удастся добыть у него ценную информацию, то мы все сможем извлечь из неё прибыль." },
    ["1115c"] = { common = "Хотите узнать про Назза Парового Котла? Вроде это гонщик с Мерцающей равнины? Да, я могу кое-что разузнать про него, но это будет нелегко. И не сразу. И не за бесплатно." },
    ["1116a"] = { common = "Вытащить информацию из Назза – дело непростое. Очень непростое. Но, раз уж вы ради этого приехали аж с Мерцающей равнины, то... не хотите ли попутешествовать ещё немного? Собрали бы для меня кое-что, пока я буду связываться со своими источниками, а? Хм... Что бы вам такое поручить? А, вот: сонная пыль с дракончиков из Болота Печали. Да, сонная пыль – это именно то, что мне нужно. Принесите мне её, а я взамен поделюсь с вами необходимой информацией." },
    ["1116c"] = { common = "Вот это да! Вы нашли сонную пыль! Ну, и как там, на болотах? Говорят, горячей еды днём с огнём не сыщешь!" },
    ["1117a"] = { common = "Мне пришлось кое-кому оказать услугу, кое-кому подарить бутылку редкого эльфийского вина, а кое-что даже разузнать самостоятельно! Однако я добыл вам всю необходимую информацию. Вот, я написал тут несколько интересных фактов касательно Назза Парового Молота. Делайте с ними что хотите, а для меня эта информация слишком опасна. И не говорите никому, откуда вы её достали!" },
    ["1117c"] = { common = "Так-так! Интересно... Очень интересно. Хех, возможно, мне придётся поздороваться с гоблинским пилотом при следующей встрече. Эта информация многого стоит. Думаю, Назз согласится раскошелиться за то, чтобы его секрет не стал достоянием общественности." },
    ["1118a"] = { male = "Ты – хороший герой, ты сможешь выполнить это задание и не болтать о нём налево-направо. Я разрабатываю новый план. Он довольно рискованный, но если всё получится, то мы озолотимся! А ты как раз отлично сможешь мне помочь. Для начала тебе надо вернуться в Пиратскую бухту. Прости, дорогой путник. Я знаю, что ты уже был там по моему поручению, но в этот раз тебе надо будет поговорить с Шиззи Пуззыриксом. Отдай ему это письмо, а если он попросит помочь, то не откажи ему. Поверь, оно того стоит.", female = "Ты – хорошая героиня, ты сможешь выполнить это задание и не болтать о нём налево-направо. Я разрабатываю новый план. Он довольно рискованный, но если всё получится, то мы озолотимся! А ты как раз отлично сможешь мне помочь. Для начала тебе надо вернуться в Пиратскую бухту. Прости, дорогая путница. Я знаю, что ты уже была там по моему поручению, но в этот раз тебе надо будет поговорить с Шиззи Пуззыриксом. Отдай ему это письмо, а если он попросит помочь, то не откажи ему. Поверь, оно того стоит." },
    ["1118c"] = { common = "Понятно. Крейвел придумал очень хитрую схему. Он очень умён – в этом ему не откажешь. Значит, вам нужно что-то для поднятия духа, так? Что-то сильнодействующее... Думаю, можно использовать смеси, которыми Занзил кормит своих зомби..." },
    ["1119a"] = { common = "Я понял, как смешать смесь Занзила с пивом, чтобы получилось убойное пойло – \"Дурацкое крепкое\"! Наверное, это именно то, что нужно Крейвелу. Отнесите ему, пусть попробует. Расскажете потом, как всё прошло! Кстати, эту брагу надо употребить как можно скорее – смесь Занзила оказывает на пивную закваску не очень хороший эффект, так что оно очень скоро выдохнется." },
    ["1119c"] = { common = "Отлично! Гранк здорово помог нам! Обязательно отблагодарю его при встрече. И вам спасибо. Вы сделали большое дело, и оба мы заработаем на этом огромные деньги." },
    ["1120a"] = { common = "Надо напоить \"Дурацким Крепким\" одну из команд на пит-стопах.Хочешь посмотреть, как оно подействует на гномов? Тогда возьми эль и передай его начальнику гномского гаража. И поторопись – эта бурда быстро выдыхается." },
    ["1120c"] = { common = "Крепкое пиво? Как мило! Спасибо большое! Перед гонкой, конечно, пить не стоит, но... Самую чуточку ребятам не повредит. Да и не такое уж оно крепкое, так ведь?" },
    ["1121a"] = { common = "Надо напоить \"Дурацким Крепким\" одну из команд на пит-стопах.Хочешь посмотреть, как оно подействует на гоблинов? Тогда возьми эль и передай его начальнику гномского гаража. И поторопись – эта бурда быстро выдыхается." },
    ["1121c"] = { common = "Что это? Ах, выпивка? Ну что ж, стаканчик-другой никогда не повредит..." },
    ["1122a"] = { common = "\"Дурацкое Крепкое\" отлично сработало! Я сделал ставку на следующую гонку и... надеюсь, команда, которую вы напоили, не забыла поставить на своей машине номер. У меня ещё одно задание для вас: отнесите эту записку обратно Шиззи Пуззыриксу в Пиратскую бухту. Наверняка он захочет узнать, что эксперимент удался. Надо будет заказать у него ещё этой выпивки для следующих гонок!" },
    ["1122c"] = { common = "Здесь сказано, что задумка с \"Дурацким Крепким\" удалась. Отличная новость! Если вам вдруг потребуется ещё, дайте знать, и я отправлю вас добыть ещё смеси Занзила." },
    ["1123a"] = { common = "Для этого эконом хранителя Лунной поляны Ремулоса — Рабин Сатурна — ищет помощи. Нужно обследовать обширные пустоши к западу от Танариса и Ун'Горо. Он живёт в Ночной гавани, главном поселении Лунной поляны. Я хочу, чтобы ты понимал всю важность твоего присутствия там. Между ночными эльфами Дарнасса и Кругом Кенария Лунной Поляны существуют трения. Но ты будь выше расовых предрассудков и прибегай к мудрости предков при общении с Кругом, путник. Да пребудет с тобой удача." },
    ["1123c"] = { common = "Я Рабин Сатурна и я выступаю от имени хранителя Ремулоса и я приветствую тебя от имени всех обитателей священной поляны. Я ценю твой интерес и рвение к помощи Кругу Кенария. Таурены показали невероятную склонность к принципам Кенария. Сохранение Азерота является нашей общей целью. Здесь, путник, ты среди друзей." },
    ["1124a"] = { common = "К западу от Кратера Ун'Горо, за северо-западным гребнем, лежит суровый пустынный край — Силитус. Немногие помнят, что там в древности развернулась война между ночными эльфами и злобной, чужеродной силой. Зло было повержено и заключено в оковы, но мы подозреваем, что сейчас некие силы хотят пробудить этот… невыразимый ужас. Найди Лайо Звёздный Всполох, одного из наших разведчиков в Силитусе. Ищи его в Покое Доблестных, последнем приюте павших в этих пустынных краях. Передай ему это письмо, и он доверится тебе." },
    ["1124c"] = { common = "Так тебя послал Рабин? Что же, чувствуй себя как дома… если хоть кто-то может назвать домом этот богами забытый край. Во времена великих бед меня ещё не было среди живых, но в этих краях есть места, которые наяву рисуют жуткую картину позабытого прошлого. С твоей помощью Круг Кенария, может быть, покончит с угрозой, которая, как мы думали, исчезла много поколений назад." },
    ["1125a"] = { common = "На юго-западе находится очень грустное место — деревня Южного Ветра. Именно с неё мы и начнём, путник. Судя по всему, некогда она была базой ночных эльфов для военных действий в Силитусе. Её давным-давно захватили силитиды. Страшно представить, что там творилось в момент захвата… По руинам бесцельно бродят духи павших друидов и стражниц. Исследуй эти края и освободи страдающие души, как подобает." },
    ["1125c"] = { common = "Я думаю, что возможно огромный закрученный улей сыграл большую роль в гибели деревни. Твоя работа доказала, что близость улья, представляет огромную угрозу… Я благодарю тебя, за твою доброжелательность в освобождении душ павших. Такая работа никогда не была лёгкой, я знаю. Хотелось бы попросить ещё раз твоей помощи…" },
    ["1126a"] = { common = "Пора заняться ульем в деревне Южного Ветра, и мне кажется, я знаю, как это лучше сделать. Я знаю по опыту, что ульи силитидов очень чувствительны к окружающей среде; этим объясняется их нападения при звуках призрачного воя. Средоточие силы силитидов — башня, та самая, вокруг которой вьются осы. Ступай к этой башне и пробуди весь улей. Доложи обо всём, что удастся узнать, но соблюдай осторожность! Если попадётся что-нибудь полезное, неси сюда." },
    ["1126c"] = { common = "Что за… что это? Оно имеет форму… коробки? Слишком твёрдое. Подожди, вот здесь… книга? Под ним книга? Возможно это книга или древний фрагмент, который сохранился в этой оболочке. Путник, кажется, я знаю способ, узнать, что это такое." },
    ["1127a"] = { common = "Говорите, вам нужно \"Дурацкое Крепкое\", да? Хотите снова отправиться на гонки? Ну ладно, принесите мне ещё смеси Занзила, и я наварю вам ещё." },
    ["1127c"] = { common = "Очень хорошо! Вот твоя плата. И вот ещё кое-что... за твою осмотрительность." },
    ["1130a"] = { common = "Мелор Каменное Копыто узнал о ваших подвигах и наметил для вас путь. Если вы хотите пройти его, отправляйтесь в Громовой Утёс и поговорите с Мелором. Его можно найти на вершине Охотников." },
    ["1130c"] = { male = "Итак, вы пришли... Значит, вы готовы к путешествию через дальние земли? Раз так, юный герой, то слушайте...", female = "Итак, вы пришли... Значит, вы готовы к путешествию через дальние земли? Раз так, юный героиня, то слушайте..." },
    ["1131a"] = { common = "Иногда мы охотимся ради еды. Иногда – ради чести. А иногда мы охотимся для того, чтобы усвоить уроки Матери-Земли. Но охота, на которую я хочу отправить вас, не имеет с этими вещами ничего общего. Вам нужно будет убить существо, не подчиняющееся божественной воле Матери-Земли. Гиена по кличке Сталезуб бродит по Тысяче Игл, к югу от Степей. К этой зверюге прибиваются другие гиены, и вместе они держат всех остальных более мирных животных в страхе. Найдите Сталезуба. Найдите и убейте его." },
    ["1131c"] = { common = "Убив Сталезуба, вы избавили Тысячу Игл от страшной напасти. И это, ваш урок на сегодня." },
    ["1132a"] = { male = "О, как я хочу снова вернуться на море! Почувствовать поцелуй ветра, покачаться на волнах, как в детстве на руках у моей милой мамы! Как же вам повезло, герой, вы ещё можете оказаться на морском берегу! Это моя работа – рассказывать всем неутомимым искателям приключений Калимдора о море. Если хотите, садитесь на корабль и плывите в прелестный порт Терамор. Там поговорите с моей коллегой, эльфийкой по имени Фиора Длинноушка. Она отправит вас в незабываемое путешествие по Калимдору!", female = "О, как я хочу снова вернуться на море! Почувствовать поцелуй ветра, покачаться на волнах, как в детстве на руках у моей милой мамы! Как же вам повезло, героиня, вы ещё можете оказаться на морском берегу! Это моя работа – рассказывать всем неутомимым искателям приключений Калимдора о море. Если хотите, садитесь на корабль и плывите в прелестный порт Терамор. Там поговорите с моей коллегой, эльфийкой по имени Фиора Длинноушка. Она отправит вас в незабываемое путешествие по Калимдору!" },
    ["1132c"] = { common = "Добрый день! Вы приплыли из Гавани Менетилов по поручению мистера Флинта? О, мистер Флинт разбирается в людях! Если он послал вас сюда – значит, здесь ваше место." },
    ["1133a"] = { common = "Если вы только что прибыли по морю из Менетила, отправляйтесь прямиком в Астранаар. Уверен, такому преданному члену Альянса будет, чем заняться в городе. Поговорите там с Шиндрелл Огненный Всполох и предложите ей свои услуги. Не стоит говорить ей, кто вас прислал. Шиндрелл меня не знает..." },
    ["1133c"] = { common = "Вы здесь, чтобы предложить свою помощь Альянсу? Война уже добралась до этих мест, хотя Ясеневый лес всё так же хранит свою красоту." },
    ["1134a"] = { common = "Между нами и Ордой война не объявлена, однако мир между нами очень хрупок. Мы часто обнаруживаем, что среди нас тайно действуют их агенты. Об одной такой операции мы узнали из скрытых источников в Тераморе. Эти источники утверждают, что орки собирают яд славнокрылов поблизости от Мутного Озера в Когтистых горах, на юге. А потом орочьи убийцы используют этот яд для тайных смертоносных ударов против сил Альянса! Если это правда, мы обязаны остановить их. Мы должны лишить их источника яда." },
    ["1134c"] = { common = "Благодарю тебя. Мне не хотелось отправлять тебя убивать этих созданий, которые, возможно, не по своей воле помогали нашим врагам, однако это был мой долг. Быть может, друг мой, твоё сердце оплакивает славнокрылов, которых тебе пришлось убить, однако пусть тебе принесёт утешение то, что твои союзники больше не будут погибать от яда славнокрылов." },
    ["1135a"] = { common = "Как вы уже знаете, орки часто приручают виверн в качестве ездовых животных. Но мало кто знает о том, что яд виверны порой может быть ценнее самого животного. Так что, если желаете немного поохотиться, то у меня есть для вас работа. В Тысяче Игл – это к западу отсюда – есть место под названием Скальное гнездовье. Там живут виверны, яд которых очень силён и чрезвычайно высоко ценится." },
    ["1135c"] = { common = "О-о-о, некоторые чуть ли не лопаются от яда! Такие обычно собирают с очень юных виверн или с плодовитых самок. Наверное, нелегко вам пришлось в Скальном гнездовье!" },
    ["1136a"] = { male = "Настало время тебе отправиться в далёкие земли. Ты готов к этому путешествию. Тебе поручается убить Ледочрева – йети, живущего в Альтеракских горах. Он отлично маскируется, его белая шкура сливается со снегами его горного обиталища. Увидеть его можно лишь изредка. Но я расскажу тебе, как приманить такое существо, как этот йети. Вот, возьми этот свиток: на нём я написал, как привлечь Ледочрева. А теперь ступай. Путь предстоит долгий, впереди тебя ждут испытания. Задание будет выполнено, когда ты вернёшься ко мне с гривой Ледочрева.", female = "Настало время тебе отправиться в далёкие земли. Ты готова к этому путешествию. Тебе поручается убить Ледочрева – йети, живущего в Альтеракских горах. Он отлично маскируется, его белая шкура сливается со снегами его горного обиталища. Увидеть его можно лишь изредка. Но я расскажу тебе, как приманить такое существо, как этот йети. Вот, возьми этот свиток: на нём я написал, как привлечь Ледочрева. А теперь ступай. Путь предстоит долгий, впереди тебя ждут испытания. Задание будет выполнено, когда ты вернёшься ко мне с гривой Ледочрева." },
    ["1136c"] = { common = "Для того, чтобы найти и сразить Леочрева, нужно обладать силой и смекалкой. Оба эти качества у тебя есть. Твой путь привёл тебя в долины Тысячи Игл и в высокие горы Альтерака. Однажды он проведёт тебя по всем странам матери-земли – ведь именно таков путь охотника." },
    ["1137a"] = { common = "Индарилий обладает невероятной сопротивляемостью нагреву! Наверняка он подойдёт для поршней Пшикса. Но ему потребуется настоящая индарилиевая руда, а не эти пластинки... Эту руду нужно добывать в глубине Ульдамана, на северной границе Бесплодных земель, – там её навалом. Передавайте Пшиксу Медноштифту привет и скажите ему всё, о чём я поведал вам. Счастливого пути. Думаю, мы с вами ещё увидимся: как только Пшикс прознает про индарилий, он как пить дать отправит вас в Ульдаман." },
    ["1137c"] = { male = "Ты вернулся! Ты нашёл Мартека? Вы с ним поговорили? Что он сказал? Он поможет? Говори-говори-говори!!!", female = "Ты вернулась! Ты нашла Мартека? Вы с ним поговорили? Что он сказал? Он поможет? Говори-говори-говори!!!" },
    ["1138a"] = { common = "Мне нравятся крабы. Крабы – это деликатесные дары моря! Их можно печь, жарить на гриле, варить, делать из них бульон. Ещё их можно жарить на сковороде, во фритюре и просто жарить. Есть крабовый салат, крабовый суп, краб тушёный, краб перченый, краб лимонный, краб с кнутокорнем, а также стальгорнский крабовый десерт. Вот и... ну, и всё. Я здесь сейчас рыбу ужу, потому охотиться на сочных крабов мне некогда. Можешь извлечь кусочки отличного мяса из рифовых крабов и покрытых илом крабов. Их можно печь, жарить на гриле, варить..." },
    ["1138c"] = { common = "Да-а-а, эти кусочки отличного крабьего мяса – как раз то, что мне нужно. Спасибо! Вот, это я обнаружил как-то, когда рыбачил, и мне оно без надобности. Может быть, ты сможешь как-то это использовать? В деликатесные блюда из крабов это уж точно не положишь. Я ведь уже рассказывал тебе о крабах, правда?" },
    ["1139a"] = { common = "Мы смогли сдержать клан Кузни Теней, отрезав их силы от пика Чёрной Стали, но задание Тяжелоступа ещё не выполнено. Его смерть не должна быть напрасной. Он мечтал найти табличку Воли: камень, на котором высекли магические письмена сами титаны, чтобы вдохнуть жизнь в созданных ими существ, – по крайней мере, так гласят легенды. Мы должны заполучить табличку Воли прежде, чем до неё доберётся клан Кузня Теней. Возвращайся в Ульдаман, найди табличку и принеси её мне незамедлительно." },
    ["1139c"] = { male = "При виде таблички советник Белграм изумлённо качает головой Это поразительно! Я прослежу, чтобы табличка была доставлена королевским магам как можно скорее. Они непременно пожелают проверить, что в легендах истина, а что ложь. Ты помог нашему народу более, чем я смел надеяться!", female = "При виде таблички советник Белграм изумлённо качает головой Это поразительно! Я прослежу, чтобы табличка была доставлена королевским магам как можно скорее. Они непременно пожелают проверить, что в легендах истина, а что ложь. Ты помогла нашему народу более, чем я смел надеяться!" },
    ["1140a"] = { male = "Орочьи письмена немногим лучше детских каракулей. Многие из моих собратьев по ордену кривились, когда я решил изучать их язык, но мне это сильно помогает понимать врагов. Из каракулей Илкруда можно понять, что у Атрикуса ещё оставались два самоцвета души, и они хранились на Ночной поляне и Сатирнааре, занятых сатирами местах на северо-востоке Ясеневого леса. Поосторожнее там, от вида кровавых храмов сатиров содрогнётся даже такой закалённый герой, как ты.", female = "Орочьи письмена немногим лучше детских каракулей. Многие из моих собратьев по ордену кривились, когда я решил изучать их язык, но мне это сильно помогает понимать врагов. Из каракулей Илкруда можно понять, что у Атрикуса ещё оставались два самоцвета души, и они хранились на Ночной поляне и Сатирнааре, занятых сатирами местах на северо-востоке Ясеневого леса. Поосторожнее там, от вида кровавых храмов сатиров содрогнётся даже такая закалённая героиня, как ты." },
    ["1140c"] = { common = "Возможно, мы слишком долго терпели сатиров в этом лесу. Я поговорю с Элиссой насчёт этого, когда в другой раз поеду в Аубердин. Тем не менее, раз самоцветы души уничтожены, сила Атрикуса сильно уменьшится. Мы должны воспользоваться этой возможностью и уничтожить его и его культ." },
    ["1141a"] = { common = "Мне нравится рыбачить. Семья Блумп славится своими рыбаками. Меня зовут Груббер Блумп. Я рыбак. Есть одна рыбка, которую я хотел бы поймать в этих водах – местная разновидность окуня. Я раньше ходил на окуня на лодке, но с тех пор как побережье оккупировали эти противные мурлоки, ни одна лодка в море не выходит. Боюсь, они и окуней всех съедят. Слушай, хочешь помочь мне наловить окуней? Я б тебе от чистого сердца подарил фамильную удочку семьи Блумп! Это очень хорошая удочка!" },
    ["1141c"] = { male = "Какие отличные окуни! Большое спасибо за помощь! Ты как минимум такой же хороший рыбак, как моя драгоценная родственница Граун Блумп. У неё, правда, растёт борода и от неё несёт чем-то странным, но это для неё не причина перестать рыбачить. Думаю, ты обладаешь необходимыми качествами, чтобы пользоваться удочкой семьи Блумп.", female = "Какие отличные окуни! Большое спасибо за помощь! Ты как минимум такая же хорошая рыбачка, как моя драгоценная родственница Граун Блумп. У неё, правда, растёт борода и от неё несёт чем-то странным, но это для неё не причина перестать рыбачить. Думаю, ты обладаешь необходимыми качествами, чтобы пользоваться удочкой семьи Блумп." },
    ["1142a"] = { common = "Мне недолго осталось жить... о, я так слаб... Хмурен... храбрый дворф, он отправился... предупредить Фалфиндера... Но прежде, чем я умру... Пожалуйста, верни моей жене её подвеску... её украл один из этих негодяев... Подвеска связывает нас... это очень важно... Пожалуйста, верни подвеску моей Трешале... в Дарнасс... И расскажи ей... о моей смерти." },
    ["1142c"] = { male = "О нет! Не может быть! О, я не верю! О, жестокий мир! Мне предстоит весь век нести в сердце горе... Я не позволю делу Гералата погибнуть вместе с ним! Благодарю тебя за то, что ты проделал этот опасный путь. Но теперь оставь меня. Я оплачу мужа в одиночестве...", female = "О нет! Не может быть! О, я не верю! О, жестокий мир! Мне предстоит весь век нести в сердце горе... Я не позволю делу Гералата погибнуть вместе с ним! Благодарю тебя за то, что ты проделала этот опасный путь. Но теперь оставь меня. Я оплачу мужа в одиночестве..." },
    ["1143a"] = { common = "Понятно. Ну если то, о чём ты говоришь, – правда, то сейчас самое время нанести удар. Я уверен, что Атрикус обосновался на самом верху башни. Однако будь начеку, его окружает множество сильных чернокнижников, гораздо более опасных, чем те, с кем тебе доводилось встречаться ранее." },
    ["1143c"] = { common = "Я надеюсь, что после смерти Атрикуса демонические силы в этом районе отступят. Я не сомневаюсь, что они перегруппируются и вернутся, но тогда мы будем ещё лучше подготовлены, чтобы встретить эту угрозу лицом к лицу." },
    ["1144a"] = { common = "Наконец-то, помощь пришла! Ты не представляешь, как долго я уже здесь торчу! Видишь ли, я предприниматель. Как говорится, всегда ищу выгоду. Вот, прослышал, что Мебок Миззрикс даёт хорошую цену за растущий здесь корень краснолиста. Ну я и подумал, что на этом можно обтяпать неплохие денежки. Как видишь, жестоко ошибался! Вытащи меня отсюда, я тебе хорошо заплачу!" },
    ["1144c"] = { common = "Уф... спасибо, дружище! А вот и обещанная награда – за мной не заржавеет!" },
    ["1145a"] = { common = "Многие путешественники, приходившие в Перекрёсток, помогали мне собирать яйца на Полях Великанов, а потом рассказывали, какие страшные твари там живут. Мне хватило этих рассказов, чтобы убедиться в том, что мой хозяин недооценил этих насекомых, и что на самом деле они гораздо опаснее. Мне нужен кто-то, кто отправится в Оргриммар и встретится там с Белгромом Каменной Булавой. Это очень серьёзное дело, которое можно поручить только ответственному посыльному. Белгрома почти всегда можно найти у цехового дома воинов." },
    ["1145c"] = { common = "А, записка от Коррана. Он служит уже давно и очень преданно. Я как раз собирался узнать, как у него дела в Перекрёстке." },
    ["1146a"] = { common = "Значит, Корран пришёл к похожему заключению относительно этих насекомых: они представляют собой гораздо большую угрозу, чем мы думали. Несколько дней назад из Тысячи Игл ко мне вернулся полумёртвый охотник. Его с отрядом отправили на Мерцающую равнину, чтобы выгнать оттуда бригаду дворфов-археологов, но во время боя на месте раскопок появились эти насекомые и чуть было не положили весь отряд. Главным у них был Моктар Крин, и сейчас они разбили лагерь на границе Мерцающей равнины. Отнесите ему это письмо." },
    ["1146c"] = { common = "Не обращайте внимания на это грохочущее эхо. Это всего лишь гонка гномов и гоблинов на Равнинах – они носятся на кошмарных машинах, созданных по всем правилам так называемой \"науки\". Однако в Тысяче Игл есть куда более серьёзные опасности, одна из которых недавно унесла жизни большей части моего отряда. Но мы останемся здесь до тех пор, пока не получим известие от Белгрома из Оргриммара. До этого мы будем держать позицию и стоять на страже." },
    ["1147a"] = { common = "Хмм. Значит, Белгром считает этих монстров опасными и хочет, чтобы их загнали в те глубины, из которых они некогда выползли. Ему, значит, недостаточно того, что мы убили всех дворфов из Лиги Исследователей – надо посылать полумёртвый отряд в новый бой! Сами мы не справимся, по крайней мере в таком состоянии. Карьер находится к югу отсюда, и дворфов там, скорее всего, больше нет. Не хочешь ли помочь нам своим клинком или посохом?" },
    ["1147c"] = { male = "Ха! Эта лимфа, которой ты покрыт с ног до головы, только красит тебя! Хотя воняешь ты так, что аж глаза режет... Не подходи слишком близко к кодом, а то они сбегут или набросятся на тебя. Думаю, мои товарищи согласятся принять этот запах за убедительное доказательство того, что ты помог нам справиться с этими мерзкими насекомыми. Спасибо.", female = "Ха! Эта лимфа, которой ты покрыта с ног до головы, только красит тебя! Хотя воняешь ты так, что аж глаза режет... Не подходи слишком близко к кодом, а то они сбегут или набросятся на тебя. Думаю, мои товарищи согласятся принять этот запах за убедительное доказательство того, что ты помогла нам справиться с этими мерзкими насекомыми. Спасибо." },
    ["1148a"] = { common = "Вы тщательно осматриваете панцирь. Повращав его в руках, вы видите, что полоски хитинового покрытия переплетены совершенно неповторимым образом, что делает панцирь невероятно прочным. Вы никогда в жизни не видели ничего подобного. Вы осматриваете останки дальше и понимаете, что эти существа очень сильны и высокоразвиты. Ещё раз взглянув на эти останки, вы думаете, что Коррану было бы интересно обследовать этих существ поподробнее. Это помогло бы ему понять, кто они и откуда взялись." },
    ["1148c"] = { common = "О, так вы недавно виделись с Моктаром? Он всегда заботился обо мне. Жаль слышать, что он тратит своё время на то, чтобы присматривать за своей группой, вместо того чтобы самому участвовать в бою... Но, думаю, ему нравится убивать членов Лиги Исследователей. Хорошо, что вы принесли мне эти образцы. Мы собрали и другие яйца насекомых на Полях Великанов, так что теперь у меня есть хороший материал для изучения. Скоро я смогу узнать, что это за насекомые и чего они хотят." },
    ["1149a"] = { male = "Итак, ты нашёл меня – или, возможно, тебя привела сама судьба? Это неважно. Теперь ты здесь, и перед тобой лежит новый путь. Личность складывается из многих из многих граней: души, тела и разума. Некоторые из этих аспектов определяются культурными традициями, о наличии других мы можем только догадываться. Если согласишься, я испытаю некоторые присущие тебе качества. Если ты пройдёшь испытание, то станешь сильнее, если же нет – познаешь всю бездну Пустоты. Первое испытание – это испытание веры.", female = "Итак, ты нашла меня – или, возможно, тебя привела сама судьба? Это неважно. Теперь ты здесь, и перед тобой лежит новый путь. Личность складывается из многих из многих граней: души, тела и разума. Некоторые из этих аспектов определяются культурными традициями, о наличии других мы можем только догадываться. Если согласишься, я испытаю некоторые присущие тебе качества. Если ты пройдёшь испытание, то станешь сильнее, если же нет – познаешь всю бездну Пустоты. Первое испытание – это испытание веры." },
    ["1149c"] = { male = "Истинную силу нашего духа мы можем познать лишь при встрече с непредвиденной бедой. Ты поверил в себя, хотя и не был уверен, что выживешь. Твой разум открыт, и твой дух готов встретить всё, что ждёт впереди. Если желаешь, можешь приступить к следующему испытанию.", female = "Истинную силу нашего духа мы можем познать лишь при встрече с непредвиденной бедой. Ты поверила в себя, хотя и не была уверена, что выживешь. Твой разум открыт, и твой дух готов встретить всё, что ждёт впереди. Если желаешь, можешь приступить к следующему испытанию." },
    ["1150a"] = { common = "Хорошо, что ты не теряешь смелости несмотря ни на что. Твоя вера крепка, и теперь настало время испытать твою силу. Сначала тебе надо пройти испытание выносливости. Отправляйся в Логово Легкоперых – оно к западу от Заставы Вольного Ветра. Проберись в самое сердце логова и уничтожь там все запасы еды. К тому времени местные гарпии будут в ярости, и если ты останешься в живых, с тобой прилетит сразиться их предводительница – Гренка Кровавый Визг. Убей её и принеси мне её коготь, чтобы пройти это испытание." },
    ["1150c"] = { male = "Гренка была очень сильна даже для такого героя как ты. Сегодня ты можешь по праву гордиться собой. Во время испытания веры ты показал силу своего духа, а сегодня подтвердил, что физически ты готов к битве. Гарпии Лёгкого Пера мертвы, и теперь настало время нового испытания.", female = "Гренка была очень сильна даже для такой героини как ты. Сегодня ты можешь по праву гордиться собой. Во время испытания веры ты показала силу своего духа, а сегодня подтвердила, что физически ты готова к битве. Гарпии Лёгкого Пера мертвы, и теперь настало время нового испытания." },
    ["1151a"] = { common = "Во времена Древних богов элементалей можно было встретить повсюду. Они поклонялись Древним богам, а боги своей силой поддерживали связь духов с этим миром. Когда же Древние боги были изгнаны, элементали тоже покинули этот мир и теперь являются сюда только по зову могущественных магов. Но есть и исключения. Некоторые духи были достаточно сильны для того, чтобы остаться в этом мире, и одного из них зовут Рок'Алим. Для того чтобы испытать свою силу, найди в Тысяче Игл Рок'Алима и убей его." },
    ["1151c"] = { common = "Испытание силы пройдено. Вы показали свою силу и храбрость и теперь готовы к последнему испытанию, после которого эти ритуалы завершатся." },
    ["1152a"] = { male = "Твои испытания почти закончились, но проверку знаний проводить буду не я. Тебе придётся посетить другие места и усвоить там новые уроки. Если ты готов, найди Брауга Тусклый Дух – это очень мудрый шаман. Внимательно выслушай его и выполни всё, что он скажет. Брауга можно найти около туннеля, соединяющего Когтистые горы и Ясеневый лес. И будь осторожен, ночные эльфы могут помешать тебе.", female = "Твои испытания почти закончились, но проверку знаний проводить буду не я. Тебе придётся посетить другие места и усвоить там новые уроки. Если ты готова, найди Брауга Тусклый Дух – это очень мудрый шаман. Внимательно выслушай его и выполни всё, что он скажет. Брауга можно найти около туннеля, соединяющего Когтистые горы и Ясеневый лес. И будь осторожна, ночные эльфы могут помешать тебе." },
    ["1152c"] = { common = "Гоблины терзают землю, ночные эльфы унижают младшие расы, а дни и ночи тем временем становятся всё холоднее и холоднее. Отрёкшиеся и орки – не единственные, кого нужно винить за конфликты, возникшие на землях Калимдора и Лордерона. Многие разумные расы причинили миру немало боли. Дорн знает об этом, и он отправил вас ко мне, потому что вы тоже способны это понять. Сейчас вы стоите перед Браугом." },
    ["1153a"] = { male = "герой, раньше вы часто помогали мне в разных делах. Пока что вождь доволен моими успехами и просит меня продолжать с новой решимостью. По закону чести, я должен рассказать вождю обо-всём, что вы сделали для нас, но вначале я хотел бы снова попросить вас о помощи. Недавно я встречался с путешественниками, которые пришли с юга, из места под названием Тысяча Игл. Там они убили кобольда, у которого при себе был образец необычной руды, но они отказались его продавать. А он мне очень нужен для исследования!", female = "героиня, раньше вы часто помогали мне в разных делах. Пока что вождь доволен моими успехами и просит меня продолжать с новой решимостью. По закону чести, я должен рассказать вождю обо-всём, что вы сделали для нас, но вначале я хотел бы снова попросить вас о помощи. Недавно я встречался с путешественниками, которые пришли с юга, из места под названием Тысяча Игл. Там они убили кобольда, у которого при себе был образец необычной руды, но они отказались его продавать. А он мне очень нужен для исследования!" },
    ["1153c"] = { male = "Хороший образец. Очень хороший. Вы замечательно справились с заданием, и эти путешественники больше не смогут задирать передо-мной нос. Я немедленно начну работать с ней, и если руда окажется достаточно прочной, я изготовлю из неё оружие и отправлю вождю, чтобы он посмотрел на наши успехи. Я не забуду вашей помощи, герой.", female = "Хороший образец. Очень хороший. Вы замечательно справились с заданием, и эти путешественники больше не смогут задирать передо-мной нос. Я немедленно начну работать с ней, и если руда окажется достаточно прочной, я изготовлю из неё оружие и отправлю вождю, чтобы он посмотрел на наши успехи. Я не забуду вашей помощи, героиня." },
    ["1154a"] = { male = "Ты прошёл испытание Дорна и хочешь пройти следующее? Что ж, хорошо. Но все предыдущие испытания были детскими играми. Физическую силу испытать легко – то ли дело сила разума! Ладно, объясню попроще: найди книгу, которую я назову, изучи её и ответь на мой вопрос по её содержимому. Ты спросишь, что за книга? Она называется \"Наследие Аспектов\". Её можно найти в глубине обители Дор'Данил, это в южном Ясеневом лесу. Книгу охраняют мёртвые друиды и их убийцы.", female = "Ты прошла испытание Дорна и хочешь пройти следующее? Что ж, хорошо. Но все предыдущие испытания были детскими играми. Физическую силу испытать легко – то ли дело сила разума! Ладно, объясню попроще: найди книгу, которую я назову, изучи её и ответь на мой вопрос по её содержимому. Ты спросишь, что за книга? Она называется \"Наследие Аспектов\". Её можно найти в глубине обители Дор'Данил, это в южном Ясеневом лесу. Книгу охраняют мёртвые друиды и их убийцы." },
    ["1154c"] = { male = "Это та самая книга, о которой я говорил. Полагаю, тебе известен ответ на мой вопрос – если только ты не поленился изучить книгу. Как только будешь готов, обратись ко мне, и я задам тебе вопрос.", female = "Это та самая книга, о которой я говорил. Полагаю, тебе известен ответ на мой вопрос – если только ты не поленилась изучить книгу. Как только будешь готова, обратись ко мне, и я задам тебе вопрос." },
    ["1159a"] = { male = "Отличная работа. Ты прошёл первую часть испытания знаний, но ещё один вопрос остался без ответа. Правда, задавать его буду не я. Поговори с Парквелом Финталласом в Лордероне – до того как пасть жертвой Чумы, он был великим историком среди людей. Он до сих пор стремится к просвещению, но уже по-другому. Он даст тебе задание, и только потом задаст вопрос – но до сих пор ты справлялся хорошо, и, я уверен, трудностей у тебя не возникнет.", female = "Отличная работа. Ты прошла первую часть испытания знаний, но ещё один вопрос остался без ответа. Правда, задавать его буду не я. Поговори с Парквелом Финталласом в Лордероне – до того как пасть жертвой Чумы, он был великим историком среди людей. Он до сих пор стремится к просвещению, но уже по-другому. Он даст тебе задание, и только потом задаст вопрос – но до сих пор ты справлялась хорошо, и, я уверен, трудностей у тебя не возникнет." },
    ["1159c"] = { male = "Тебя прислал Брауг? Невероятно. Парквел критически осматривает вас. Справился в Дор'Даниле, прошёл испытание веры и совладал с могущественным элементалем? Ха! Да ты, наверное, наслушался разговоров в таверне и теперь нагло врёшь мне! Думаешь, что сможешь пройти моё испытание? Ну что ж, хорошо... герой.", female = "Тебя прислал Брауг? Невероятно. Парквел критически осматривает вас. Справился в Дор'Даниле, прошёл испытание веры и совладал с могущественным элементалем? Ха! Да ты, наверное, наслушался разговоров в таверне и теперь нагло врёшь мне! Думаешь, что сможешь пройти моё испытание? Ну что ж, хорошо... героиня." },
    ["1160a"] = { common = "Я скажу тебе, что искать, и даже задам вопрос, но не потому, что тебе хочется проявить себя. Знания гораздо важнее силы. Даже если кто-то силой превосходит тебя, твои знания о мире могут оказаться куда полезнее. Отправляйся в монастырь на севере Тирисфальских лесов. В их библиотеке есть книга под названием \"Истоки угрозы нежити\" – по ней ныне обезумевшие паладины учатся истреблять моих собратьев. Принесите её мне." },
    ["1160c"] = { male = "Это та самая книга, которую я велел тебе найти. *Парквел нежно проводит рукой по обложке, разглядывая её.* Значит, ты хочешь, чтобы я задал тебе вопрос, чтобы ты мог доказать, что твой дух так же силён, как и тело? Если ты хорошо изучил книгу, то я задам тебе вопрос, и с испытаниями будет покончено.", female = "Это та самая книга, которую я велел тебе найти. *Парквел нежно проводит рукой по обложке, разглядывая её.* Значит, ты хочешь, чтобы я задал тебе вопрос, чтобы ты могла доказать, что твой дух так же силён, как и тело? Если ты хорошо изучила книгу, то я задам тебе вопрос, и с испытаниями будет покончено." },
    ["1164a"] = { common = "Воровка! Свинья! Кената всё ещё жива, её семья живёт и процветает, а я страдаю. Вот уж действительно Отрёкшаяся! Всю мою семью забрала чума. Всё наше имение тоже разорили во время войны. И теперь она и её мерзкие дети имели наглость похитить у меня последние ценные вещи. Сами вещи мне уже не нужны. Теперь я жажду мести! Убей этих проходимцев! Ступай в усадьбу Дабири в Арати, на северо-востоке от Опорного пункта." },
    ["1164c"] = { male = "Ты стоишь передо мной, словно посланник Мести, и я склоняюсь в знак признательности. Жирная корова мертва, и я, зная, что её потомки не будут топтать землю Азерота, могу потратить силы на что-нибудь более разумное. Надеюсь, прикончив их, ты ограбил усадьбу?", female = "Ты стоишь передо мной, словно посланник Мести, и я склоняюсь в знак признательности. Жирная корова мертва, и я, зная, что её потомки не будут топтать землю Азерота, могу потратить силы на что-нибудь более разумное. Надеюсь, прикончив их, ты ограбила усадьбу?" },
    ["1166a"] = { male = "Твоя кланяться властитель Мок'Морокк! Рексар назначить меня правителем клана Каменного Молота! Моя хороший вождь! Моя бережёт свой клан! Большие драконы прилетать и жечь наш старый дом. Моя – умный огр! Моя найти здесь новый дом для свой клан. Бросать старый дом так быстро, что забыть моя вещи. Маленький герой, ты идти и приносить моя вещи. Идти на юг и приносить мой вкусный грог, мой табак и мой сейф. Я благодарить твоя, когда твоя сделать это. Твоя искать в Обители Пламени и в руинах Деревни Каменного Молота. Они быть там, моя уверен.", female = "Твоя кланяться властитель Мок'Морокк! Рексар назначить меня правителем клана Каменного Молота! Моя хороший вождь! Моя бережёт свой клан! Большие драконы прилетать и жечь наш старый дом. Моя – умный огр! Моя найти здесь новый дом для свой клан. Бросать старый дом так быстро, что забыть моя вещи. Маленькая героиня, ты идти и приносить моя вещи. Идти на юг и приносить мой вкусный грог, мой табак и мой сейф. Я благодарить твоя, когда твоя сделать это. Твоя искать в Обители Пламени и в руинах Деревни Каменного Молота. Они быть там, моя уверен." },
    ["1166c"] = { male = "Хороший герой. Моя скучать по этим вещам. Моя теперь дружить с твоя.", female = "Хороший героиня. Моя скучать по этим вещам. Моя теперь дружить с твоя." },
    ["1167a"] = { common = "Прежде чем встретиться с Атрикусом, разумно было бы тебе посоветоваться с Балтулом. Не сомневаюсь, что он неусыпно следил за башней и может знать о недавних событиях." },
    ["1167c"] = { male = "А, приятно снова свидеться! Тут такие странные вещи творились, так что хорошо, что ты снова тут появился! Очень странные вещи. Всё казалось как обычно – ну, насколько тут вообще всё может быть обычно – и вдруг на верхнем этаже башни как полыхнёт! Потом начались вопли. Вопли раскалывали воздух, а в землю порой били молнии. Что всё это может значить?", female = "А, приятно снова свидеться! Тут такие странные вещи творились, так что хорошо, что ты снова тут появилась! Очень странные вещи. Всё казалось как обычно – ну, насколько тут вообще всё может быть обычно – и вдруг на верхнем этаже башни как полыхнёт! Потом начались вопли. Вопли раскалывали воздух, а в землю порой били молнии. Что всё это может значить?" },
    ["1168a"] = { common = "Мок'Морокк получил власть от Рексара. Но он больше любил власть, чем огров. Чёрные драконы убили много огров. Убили жену Тхарга. Мок'Моррокк велел нам бежать. Заставил прийти сюда. Огры должны биться. Ограм плохо бегать. Мок'Морокк думает только о Мок'Морокке. Мой дом в руинах Деревни Каменного Молота. Мне нравится там на юге. Здесь не наш дом. Помоги ограм победить войско чёрного дракона. Мы хотим отомстить. Мы хотим домой." },
    ["1168c"] = { male = "Ты убил многих из войска Чёрного дракона. Ты – отважный герой! Тхарг счастлив!", female = "Ты убила многих из войска Чёрного дракона. Ты – отважная героиня! Тхарг счастлив!" },
    ["1169a"] = { male = "Пока этот трусливый глупец Мок'Морокк упивается властью, а Тхарг борется с тоской и жаждой мести и оспаривает у него власть над кланом, – я, кажется, единственный, кто хочет установить источник бед, обрушившихся на нас. Почему ты так озадаченно смотришь на меня? Думал, я буду говорить как неотёсанный чурбан только потому, что я – огр? Но к делу. Принеси мне сердца и языки дракончиков, только что вылупившихся из яиц, и я найду корни этого зла.", female = "Пока этот трусливый глупец Мок'Морокк упивается властью, а Тхарг борется с тоской и жаждой мести и оспаривает у него власть над кланом, – я, кажется, единственный, кто хочет установить источник бед, обрушившихся на нас. Почему ты так озадаченно смотришь на меня? Думала, я буду говорить как неотёсанный чурбан только потому, что я – огр? Но к делу. Принеси мне сердца и языки дракончиков, только что вылупившихся из яиц, и я найду корни этого зла." },
    ["1169c"] = { common = "Рискованное было дельце, добывать все эти сердца и языки, а? Теперь я проникну в глубины тайн, чтобы выяснить, откуда на наш прежний дом свалилась такая напасть." },
    ["1170a"] = { common = "Деревня Каменный Молот была захвачена выводком Ониксии. Но почему дочь великого дракона Смертокрыла вторглась в наши земли? Вот что тревожнее всего! Неужели только для того, чтобы уничтожить небольшое поселение огров? Предупреди Мок'Морокка. Нельзя сидеть сложа руки!" },
    ["1170c"] = { common = "Почему ты говорить с моя про драконы? Моя не любить драконы. Моя не хотеть здесь никакие драконы." },
    ["1171a"] = { common = "Твоя уходить. Твоя идти и сказать Драз'Зилбу, мы оставаться здесь. Здесь нет никакой чёрный дракон." },
    ["1171c"] = { common = "Жалкий трус! Мок'Морокк выказывал силу, пока нашим вождём был Рексар. Но после его ухода Мок'Морокк начал сам стремиться к власти. Он предпочитал требовать, вместо того чтобы руководить. Он не заботится о своих подданых, а наоборот хочет, чтобы мы заботились о нём. С этим надо что-то делать!" },
    ["1172a"] = { common = "Выводок Ониксии расползся по всей Земле Драконов. Нельзя допустить, чтобы и остальные её отродья вылупились на свет! Поспеши в Драконьи топи на юге Пылевых топей. Наверняка она устроила там своё логово. Найди яйца злой драконихи и уничтожь их! Мы никогда не вернём себе деревню Каменного Молота, если вокруг будут продолжать плодиться драконы. А что касается Мок'Морокка... касательно этого червя у меня есть особые планы." },
    ["1172c"] = { common = "Прекрасно! Теперь Ониксия не скоро отложит очередную кладку. Благодарю тебя, от имени моего народа. Я уже о многом просил тебя, но, может, ты окажешь последнюю услугу клану Каменного Молота. Мок'Морокк не достоин править нами. Тхарг стал бы отличным вождём, но он стар и изранен. Изгони силой из этих мест Мок'Морокка. Только тогда мы сможем избрать нового вождя, который отведёт нас на родину, в южные земли." },
    ["1173a"] = { male = "Ты осмеливаешься вызвать на поединок властителя Мок'Морокка? Ха! Меня хочет сокрушить жалкий герой! Приготовишься к трепке – скажи мне.", female = "Ты осмеливаешься вызвать на поединок властителя Мок'Морокка? Ха! Меня хочет сокрушить жалкая героиня! Приготовишься к трепке – скажи мне." },
    ["1173c"] = { male = "Эта трусливая туша, Мок'Морокк, сбежал как испуганный младенец при виде розги. Ты оказал нам огромную услугу. Теперь мой народ может выбрать себе нового лидера, того, кто поможет восстановить наши жилища и защитить их.", female = "Эта трусливая туша, Мок'Морокк, сбежал как испуганный младенец при виде розги. Ты оказала нам огромную услугу. Теперь мой народ может выбрать себе нового лидера, того, кто поможет восстановить наши жилища и защитить их." },
    ["1175a"] = { common = "После того как гоблинский болид \"Красный Гром\" столкнулся с василиском, Кронкрайдер нанял меня присматривать за трассой. Не знаю, что жрут местные животные, но они вырастают просто огромными, и нужно постоянно отпугивать их, чтобы они не забредали на трек во время гонки. Знаете, что? Если желаете немного заработать, ступайте и избавьте нас от нескольких василисков." },
    ["1175c"] = { common = "Надеюсь, вы не убивали василисков прямо на трассе? Здесь тела разлагаются очень долго, а лопатой их убирать замучаешься." },
    ["1176a"] = { common = "На гонках имеет значение абсолютно всё! Будь то малейшее изменение мощности, небольшое ослабление колец натяжения или уменьшение веса болида – любую мелочь надо принимать в расчёт. Мы используем в своих болидах кости стервятников – они очень крепкие и лёгкие. К тому же их очень легко найти. Уж чего-чего – а стервятников на Мерцающих равнинах хватает. Принеси мне немного костей, и я хорошо заплачу тебе." },
    ["1176c"] = { common = "Отлично! Моя команда сейчас же начнёт работу! Спасибо." },
    ["1177a"] = { common = "Моя – большой огр. Моя голодный. Твоя идти ловить рыба. Твоя принести Дробу еда. Твоя кормить Дроб, или Дроб есть твоя." },
    ["1177c"] = { common = "Моя любить рыбья голова! Моя пока твоя не есть." },
    ["1178a"] = { common = "Наша гоночная команда – это гордость всей расы гоблинов! Вы удивитесь, узнав, что за личности в той или иной мере покровительствуют нашей команде. Знаете Газлоу? Он собирает для нас детали по всему миру, а однажды даже разработал для нас новые костюмы! Несколько недель назад он пообещал прислать новый топливный регулятор, но посылка пока не пришла. Странно, обычно Газлоу держит своё слово... Может, вы не прочь съездить в Кабестан и спросить у него? Я бы не настаивал, но эти гномы нас догоняют!" },
    ["1178c"] = { common = "Вас прислал Поззик? Когда-то ведь он был одним из самых уважаемых механиков в Нижней шахте, но потом уволился и занялся гонками. Первое, что он сделал, придя в команду, – разработал две новых модели двигателей. Дела Союза ремонтников могут пострадать без Поззика, но ему уже нет до этого дела... Гонки для него всё!" },
    ["1179a"] = { common = "Вы когда-нибудь слышали о Мерцающей равнине? Это огромное соляное плато в Калимдоре, южнее каньона Тысяча Игл. Это отличное место для гонок, потому что поверхность там совершенно... ну... равнинная! Там живёт парочка гномов – мои друзья, они строят новый болид, и говорят, он жуть какой быстрый! Настолько быстрый, что их пилоты то и дело разбиваются и калечатся... Они заказали у меня несколько защитных шлемов, но у меня дела, и я не могу их отвезти. Может быть, вы мне поможете?" },
    ["1179c"] = { common = "Ага! Длиннобородый прислал с вами наши шлемы! Ур-р-а-а-а!!! Осталось уговорить пилота сесть в наш болид..." },
    ["1180a"] = { common = "Вернёмся к делу. Я обещал Поззику привезти новый топливный регулятор, но так и не получил его. Ревилгаз из Пиратской бухты сказал, что выслал его, но, похоже, он куда-то улетучился. Коли так, ничего не попишешь, но по меньшей мере мы можем выяснить, отправляли его или нет. Поговори с управляющим пристанью Подгребаем по ту сторону моря, пусть заглянет в свои записи." },
    ["1180c"] = { common = "Поставки в Кабестан? Дай-ка я загляну в записи… Нет, последний груз, отправленный в Кабестан, если не считать оборудования и припасов, – это сапоги от Дриззлика. Никаких запчастей для гонок." },
    ["1181a"] = { common = "Боюсь, тут я помочь уже не в силах. Если ты хочешь узнать подробности, поговори с самим бароном. Никто не знает дела Ревилгаза лучше самого Ревилгаза. Он сейчас на верхнем этаже таверны на другой стороне залива." },
    ["1181c"] = { common = "А, разумеется, я понимаю, о чём ты. Нет, помочь не могу. Мои наёмники должны были добыть чертежи топливного регулятора, но вернулись с пустыми руками." },
    ["1182a"] = { common = "Видишь ли, резаки Торговой Компании возле озера Назферити (в северной части Тернистой долины) оборудовали новой моделью топливного регулятора. Я подумал, что Поззик мог бы воспользоваться им, узнай мы, как он устроен. К сожалению, Коззл, тамошний штейгер, оказался несколько умнее, чем я полагал. Может быть, тебе больше повезёт, и удастся получить чертежи. Я знаю, что он хранит их в доме, но скорее всего под замком." },
    ["1182c"] = { common = "А теперь, дай-ка я срисую чертежи для личного пользования, а эти отвези Поззику. Не хотелось бы, чтобы он подумал, будто один из спонсоров оставил его без поддержки." },
    ["1183a"] = { common = "Всё должно быть готово. Передай Поззику мои наилучшие пожелания и скажи, что если ему что понадобится, стоит только попросить. Буду ждать вестей о его новых рекордах!" },
    ["1183c"] = { common = "Я надеялся, что он прибудет в готовом виде, зато теперь у нас есть уникальная возможность усовершенствовать конструкцию на этапе сборки. Спасибо. Я нарисую план улучшенного регулятора, сделаю его и установлю." },
    ["1184a"] = { common = "Вернитесь к Белгрому в Оргриммар и скажите, что Моктар в Тысяче Игл сделает всё, что от него требуется. А ещё скажите, что я постоянно учусь и набираюсь знаний. Он будет рад это услышать." },
    ["1184c"] = { male = "Я очень ценю ваши усилия, герой. Вождю будет приятно услышать о том, как вы стараетесь для нас. О, разумеется, я назову ему ваше имя! Он часто говорит со мной и высоко ценит моё мнение. А теперь ступайте, у меня ещё много дел. И если вдруг вы встретитесь с Корраном, и он расскажет вам что-нибудь ещё об этих существах – сразу возвращайтесь ко мне. К этой угрозе нельзя относиться легкомысленно.", female = "Я очень ценю ваши усилия, героиня. Вождю будет приятно услышать о том, как вы стараетесь для нас. О, разумеется, я назову ему ваше имя! Он часто говорит со мной и высоко ценит моё мнение. А теперь ступайте, у меня ещё много дел. И если вдруг вы встретитесь с Корраном, и он расскажет вам что-нибудь ещё об этих существах – сразу возвращайтесь ко мне. К этой угрозе нельзя относиться легкомысленно." },
    ["1185c"] = { common = "Эй, это снова ты! Я имею в виду тебя — тебя, путник! Да, именно тебя! Позволь мне начать! Объект который ты нашёл в Силитусе, на самом деле книга. Этот журнал был написан на очень древнем диалекте, который теперь мы называем Дарнаский. Это займёт время, но я смогу тщательно перевести его. Я думал что тебе стоит знать, то что ты нашёл, очень ценное для Круга." },
    ["1186a"] = { common = "Мне сейчас нужно приспособить этот новый регулятор топлива на один из наших болидов, но если вы хотите ещё немного помочь нашей команде, поговорите с Раззериком. Это наш пилот, – гм, наш восемнадцатый пилот, если точнее, – и он тоже любит вносить в болид всяческие усовершенствования. Он, правда, малость двинутый, так что не удивляйтесь, если что." },
    ["1186c"] = { common = "Это ведь вы помогали Поззику, правда? Когда-то я тоже бегал по пит-лейну и выполнял мелкие поручения механиков. А теперь – взгляните на меня! Я – лучший пилот команды гоблинов!" },
    ["1187a"] = { common = "Поззик – отличный механик, это я знаю, но он боится просто прибавить мощности и вырваться вперёд! А вот я не боюсь. После того как он закончит работать с болидом, я внесу кое-какие изменения от себя: немного ослаблю ограничители, сниму кое-какие детальки с корпуса и добавлю побольше топлива! Я заказал сефориевый ускоритель у Шрива. Он работает в Гизмориуме, в Прибамбасске, но дирижабль, на котором летел мой ускоритель, разбился в Пылевых топях! А мне он нужен, как воздух!" },
    ["1187c"] = { common = "Ты только глянь на эту красотищу! Пятнадцать фунтов чистой сефориевой силы! Как только я прицеплю это к своему болиду, он понесётся так, что я обгоню гномов на два круга!" },
    ["1188a"] = { common = "Постойте-ка, что это? Шрив оставил включённым режим безопасности. Но это же ограничит мощность, которую я смогу выжать из этого ускорителя! Говорил же я ему, чтобы отключил! Плохо, плохо. Вам придётся отнести это в Гизмориум Прибамбасска и заставить Шрива всё отключить!" },
    ["1188c"] = { common = "Только Раззерик мог по одному взгляду определить, что я поставил сюда предохранитель. Этот ускоритель почти полностью состоит из взрывчатого сефория. Я модифицировал его так, что его мощность будет увеличиваться по мере использования, но Раззерик ведь не успокоится, пока не взорвётся вместе со своим драндулетом!" },
    ["1189a"] = { common = "Вот, я сделал то, что просил Раззерик. Но скажите ему, чтобы он действовал как можно осторожнее: если он допустит хотя бы малейшую ошибку, болид не покатится вперёд, а превратится в кучку пепла на треке. А нам бы совсем не хотелось искать потом девятнадцатого по счёту пилота!" },
    ["1189c"] = { common = "Так-то лучше! Вот бы увидеть рожи гномов, когда я стартую на этой малышке! Жалко, что я буду так занят установлением нового рекорда трассы!" },
    ["1190a"] = { common = "Братья Медноштиф изобрели новый материал для изготовления машин – это единственное разумное объяснение. Их машины ездят быстрее прежнего, но их внешний вид и все остальные параметры ничуть не изменились. Мы точно знаем, что Риззл Медноштиф никогда не расстаётся с чертежами своего изобретения. Я скажу Замеку, чтобы устроил диверсию, – тогда ты сможешь выкрасть планы." },
    ["1190c"] = { common = "Свиток испещрён торопливыми пометками и рисунками, касающимися переработки какого-то сырья." },
    ["1194a"] = { common = "В чертежах Риззла описывается процесс переработки индарилиевой руды. Из его каракулей можно понять, что эта руда добывается в недрах Ульдамана в Бесплодных землях. Остальные записи посвящены теплопроводным свойствам индарилия. Пачка бумаг придавлена каким-то камнем – скорее всего, это и есть необработанная индарилиевая руда." },
    ["1194c"] = { common = "Индарилий? Интересно... Если он действительно способен выдерживать такой жар, то мне понятно, почему гномы так отличились на последней гонке. Большое спасибо за этот образец, он мне очень пригодится. Я проведу с ним кое-какие испытания, но для настоящего дела мне потребуется гораздо больше." },
    ["1195a"] = { common = "Кентавры племени Галак в Тысяче Игл хранят один предмет, сохранившийся ещё со времён сотворения кентавров. Нам бы хотелось его получить, но для этого нужен фиал воды из одного из лунных колодцев ночных эльфов. Чтобы набрать воды, тебе надо сначала добыть один из фиалов дриад, что живут близ Приюта в Ночных Лесах в сердце Ясеневого леса. Лунный колодец есть у западного берега реки Фалфаррен, к югу от главной дороги, у которой ты сможешь наполнить фиал." },
    ["1195c"] = { common = "Хорошо. Это как раз то, что просил Рау. Ты можешь отнести ему фиал? Тебе понравится в Иглах, честное слово!" },
    ["1196a"] = { common = "Отнеси наполненный фиал Рау Скальному Бегуну на Заставу Вольного Ветра на юго-востоке Тысячи Игл. Туда ты можешь добраться на Великом подъёмнике, что возле южного обрыва Степей. Не удивлюсь, если ты и в дальнейшем будешь нам помогать." },
    ["1196c"] = { common = "Хм, да, этот фиал очень пригодится для наших целей. Поскольку дриады и кентавры происходят от одного корня, вода лунных колодцев поможет нам пробить брешь в стене неугасимого огня, что окружает реликвию кентавров." },
    ["1197a"] = { male = "Водой, которую ты принёс, можно будет затушить пламя, охраняющее реликвию кентавров. Однако оно погаснет лишь ненадолго, так что тебе придётся поспешить. Утёс Треснувшего Копыта – крепость кентавров – находится к северу отсюда. Огонь горит в оплоте Треснувшего Копыта – самой охраняемой части утёса. Будь осторожен – кентавров из племени Галак очень много, и они вряд ли легко расстанутся с тем, что представляет для них большую ценность.", female = "Водой, которую ты принесла, можно будет затушить пламя, охраняющее реликвию кентавров. Однако оно погаснет лишь ненадолго, так что тебе придётся поспешить. Утёс Треснувшего Копыта – крепость кентавров – находится к северу отсюда. Огонь горит в оплоте Треснувшего Копыта – самой охраняемой части утёса. Будь осторожна – кентавров из племени Галак очень много, и они вряд ли легко расстанутся с тем, что представляет для них большую ценность." },
    ["1197c"] = { common = "От этого копыта исходит странная энергия... Не сомневаюсь, что при его изучении мы узнаем много нового о кентаврах. Благодарю вас. Я немедленно приступлю к разгадке тайны, которую вы принесли мне." },
    ["1198a"] = { common = "В нынешние дни много слухов ходит о союзе Сумеречного Молота и наг в Непроглядной Пучине на побережье Ясеневого леса. Я должен собрать как можно больше сведений для Серебряного Рассвета, что бы мы могли понять, где и когда нужна наша помощь. Уже много недель прошло, как я отправил разведчика выяснить, что происходит в Непроглядной Пучине. Страж Талрид из ордена Серебряного Рассвета до сих пор не вернулся. Другие мои разведчики заняты насущными делами. Помоги мне найти Талрида." },
    ["1198c"] = { common = "Хорошо, что Рассветный дозорный Шедласс прислал вас. В этом испоганенном месте и правда затевается коварный план." },
    ["1199a"] = { common = "Черпая силу из старинных обрядов, посвящённых Древним Богам Хаоса, Сумеречный Молот пытается вернуть своих тёмных покровителей и распространить смерть и ужас по всему миру. Мы думаем, что Сумеречный Молот в союзе с нагами, и теперь они накапливают силы в Непроглядной Пучине на побережье Ясеневого леса. Что бы ни затевалось в глубинах древнего храма, этим планам нельзя дать осуществиться. Объяви же войну Молоту и вернись с доказательствами своих подвигов! Твои труды будут достойно вознаграждены." },
    ["1199c"] = { common = "Нет сомнений – в тебе течёт отважная и благородная кровь. Серебряный Рассвет благодарит тебя за содействие силам добра." },
    ["1200a"] = { common = "Силы оставили меня. Мне необходима твоя помощь! В давние времена на этом месте был храм Элуны. К несчастью, он был разрушен, когда порча Древнего бога просочилась из-под земли и осквернила священный Лунный колодец. Аку'май, слуга Древнего бога, поднялся из глубин. Сектанты Сумеречного Молота объединились с нагами в борьбе за эти земли. Сектанты, ведомые Келрисом, приносят Аку'май невинные жертвы. Убей Келриса и принеси его голову Сельгорму в Дарнасс." },
    ["1200c"] = { male = "Келрису много раз удавалось ускользнуть от нас. Мне кажется, он стоял за всем злом, происходящим в этих землях. Положив конец его власти, ты спас жизнь многих. Во имя Света! Нет прощенья тем, кто приносит невинные жертвы Древнему Богу! Ты совершил великий подвиг. Серебряный Рассвет этого не забудет.", female = "Келрису много раз удавалось ускользнуть от нас. Мне кажется, он стоял за всем злом, происходящим в этих землях. Положив конец его власти, ты спасла жизнь многих. Во имя Света! Нет прощенья тем, кто приносит невинные жертвы Древнему Богу! Ты совершила великий подвиг. Серебряный Рассвет этого не забудет." },
    ["1201a"] = { common = "Орда с Альянсом сейчас находятся в состоянии шаткого перемирия. Тайные операции предпринимаются обеими сторонами, и наша обязанность – убедиться что Орда выйдет из них победителем! Сейчас у нас есть шанс это сделать. Агенты Альянса заняли позицию к востоку от Деревни Гиблотопь. Они следят за деревней и докладывают о наших действиях в районе Терамора. Мы не станем этого терпеть. Твоя задача выследить этих шпионов и убить их. Этим мы ясно дадим понять их начальству, что не допустим шпионить у себя под носом." },
    ["1201c"] = { common = "Отличная работа. Их шпионы хитроумны, но недостаточно, чтобы спастить от всевидящих глаз Орды." },
    ["1202a"] = { common = "Мы послылали двоих разведчиков украсть бумаги с корабля в одном из тераморских доков. Они добыли их, но были обнаружены, и им пришлось выбросить добычу в море. Одному из них удалось сбежать, но поднять документы со дна он не смог. Теперь я поручаю эту задачу тебе. Бумаги лежат в сундучке, на дне моря возле тераморских доков. Найди их, и принеси мне." },
    ["1202c"] = { male = "Браво. Это было нелегко, но документы, которые ты добыл – весьма ценны.", female = "Браво. Это было нелегко, но документы, которые ты добыла – весьма ценны." },
    ["1203a"] = { common = "Мне предстоит жестокая рубка. С кем, я тебе сказать не могу, но вот то, что мне для этого просто необходим добрый клинок, это к гадалке не ходи. Некоторые называют его палашом лунной стали, а я зову пляшущий клинок. Поможешь мне, а? Может, где в городе найдёшь, а может, кузнец какой согласится его сделать. Главное, поторопись, то что я собираюсь рубить, ждать не станет..." },
    ["1203c"] = { common = "Это хороший клинок... Он хорошо танцует, – стало быть, это – хороший танцующий клинок! Спасибо-спасибо-спасибо!!! Таак. Теперь я его испробую... Позже. Я испробую его позже. Но всё равно спасибо тебе!" },
    ["1204a"] = { male = "Я тут работаю над новым блюдом, оно будет называться \"Суп из илистой черепахи с жучками\". Мне всё ещё не хватает основных ингридиентов, но я не уверен, что перенесу ещё одну прогулку по Пылевых топях. путник, ты не окажешь мне услугу? Прежде всего, мне нужны языки илистых черепах. Они водятся на побережье, в основном вокруг залива. Но мне не всякие языки сгодятся – я слышал, что у некоторых из этих черепах языки раздвоены. Вот они-то и обладают тем непередаваемым вкусом, которым я хочу порадовать своих клиентов.", female = "Я тут работаю над новым блюдом, оно будет называться \"Суп из илистой черепахи с жучками\". Мне всё ещё не хватает основных ингридиентов, но я не уверен, что перенесу ещё одну прогулку по Пылевых топях. путница, ты не окажешь мне услугу? Прежде всего, мне нужны языки илистых черепах. Они водятся на побережье, в основном вокруг залива. Но мне не всякие языки сгодятся – я слышал, что у некоторых из этих черепах языки раздвоены. Вот они-то и обладают тем непередаваемым вкусом, которым я хочу порадовать своих клиентов." },
    ["1204c"] = { common = "Отлично! Благодарю тебя! Теперь надо подумать, как именно приготовить эти языки, чтобы наилучшим образом подчеркнуть их изысканный вкус. Наконец-то у меня есть блюдо, достойное завсегдатаев \"Печального отшельника\" в Штормграде." },
    ["1205a"] = { male = "Зыбун – старый кроколиск из Пылевых топей. Ему давно уже пора сдохнуть. Скрипя старыми костями он волочёт свою огромную тушу по болоту. Хотя он всё ещё движется с силой и скоростью молодого животного, его неугасимый пламенный дух уже износил своё дряхлое тело. Ты должен освободить его от этой боли. Дай ему покой.", female = "Зыбун – старый кроколиск из Пылевых топей. Ему давно уже пора сдохнуть. Скрипя старыми костями он волочёт свою огромную тушу по болоту. Хотя он всё ещё движется с силой и скоростью молодого животного, его неугасимый пламенный дух уже износил своё дряхлое тело. Ты должна освободить его от этой боли. Дай ему покой." },
    ["1205c"] = { common = "Отлично. Я уверен – это было нелёгкое испытание, но я рад, что мучения кроколиска наконец-то прекратились." },
    ["1206a"] = { common = "Глазной сок очень вкусный, жаль только что большинство живых существ имеет всего по два глаза. Но вот у пауков их уже больше, гораздо больше. А сок из глаз пауков Мглистой пещеры обладает особенным мягким вкусом. Целёхонькие паучьи глазки... прям уже чую их на языке. Эти пауки водятся к пещере к западу отсюда. Вот как ты думаешь, это пауки были названы по своей пещере или наоборот?" },
    ["1206c"] = { male = "Ты принёс вкусные глазки... Паучьи глаза чисты как слеза. Их едят, а они глядят… Вот те, что глядят, съешь последними, а то на болотах-то другой компании и нет. Привет, глазки мои маленькие, привеет! На вкус лучше курочки, с солью, с приправками... Ммм...", female = "Ты принесла вкусные глазки... Паучьи глаза чисты как слеза. Их едят, а они глядят… Вот те, что глядят, съешь последними, а то на болотах-то другой компании и нет. Привет, глазки мои маленькие, привеет! На вкус лучше курочки, с солью, с приправками... Ммм..." },
    ["1218a"] = { common = "Люблю болотную кухню. Жареные лягушачьи лапки и всё такое... И чтобы готовить, мне нужны специи. Ароматные специи. Тогда я смогу сделать славное жаркое, да и тебя угостить Ты как насчёт тушёной лягушатинки?" },
    ["1218c"] = { common = "Ага, вот и специи. Вот теперь жабятина вполне готова." },
    ["1219a"] = { common = "Просеивая землю, мы нашли отрубленную руку орка, сжимающую резную костяную трубку. А в трубке находился заляпаный грязью пергамент. Донесение написано на орочьем... И по виду важное..." },
    ["1219c"] = { common = "Хм... Я не силён в орочьем, но это похоже... на отчёт шпиона!" },
    ["1220a"] = { common = "Капитан Ваймс должен увидеть найденное тобой орочье донесение. Он знает орочий язык, лучше чем кто либо из нас, и он должен быть осведомлён о том, что вблизи Терамора рыщут шпионы Орды. Ты найдёшь капитана в казармах в северо-восточной части острова Терамор." },
    ["1220c"] = { common = "Донесение орочьего шпиона! Как тебе удалось его раздобыть? Впрочем, неважно, – давай-ка посмотрим, о чём там говорится..." },
    ["1221a"] = { common = "Корень синелиста – признанный деликатес в любом уголке мира! Но растёт он только здесь, в Пустошах, глубоко под землёй в Лабиринтах Иглошкурых. К тому же клубни так сложно найти, если не знать точно где искать! Поэтому я специально надрессировал этих шмыгуносов, чтобы они находили корни под землёй. Обоняние у них просто невероятное – они чуют корни с пятидесяти шагов! Задачка, конечно, непростая, но если принесёшь мне корней, я хорошо заплачу." },
    ["1221c"] = { common = "Прекрасно! О, я загоню их перекупщикам за очень хорошую цену! Спасибо за работу. Ты вполне надёжный поставщик!" },
    ["1222a"] = { male = "Ура! Наконец-то нашёлся кто-то, кто не хочет меня съесть! Не могу отбиться от тутошнего зверья, а ты, парень, как раз мне в этом и поможешь. Повар Морган Штерн составляет рецепт нового блюда, и он послал меня сюда на поиски листьев болотного боба. Он, похоже, думает, что они вкусные. Как бы то ни было, пока я искал эти самые листья... меня окружили! Мне до зарезу необходим кто-то кто поможет выбраться отсюда и прикроет спину, пока я буду искать эти бобы!", female = "Ура! Наконец-то нашёлся кто-то, кто не хочет меня съесть! Не могу отбиться от тутошнего зверья, а ты, подруга, как раз мне в этом и поможешь. Повар Морган Штерн составляет рецепт нового блюда, и он послал меня сюда на поиски листьев болотного боба. Он, похоже, думает, что они вкусные. Как бы то ни было, пока я искал эти самые листья... меня окружили! Мне до зарезу необходим кто-то кто поможет выбраться отсюда и прикроет спину, пока я буду искать эти бобы!" },
    ["1222c"] = { common = "Мистер Игнац не так давно приносил листья болотного боба, и он расказал мне, что вы помогли ему выбраться из весьма затруднительной ситуации. Благодарю вас. Я попрошу своего дядю принять вас по-королевски, когда вы в следующий раз окажетесь в \"Печальном отшельнике\", в Штормграде." },
    ["1238a"] = { common = "Просеивая землю, мы нашли отрубленную руку орка, сжимающую резную костяную трубку. А в трубке находился заляпаный грязью пергамент. Это донесение шпиона, который провёл многие недели в Тераморе. Расшифровав его, мы выяснили, что это донесение должно быть доставлено командиру орков-разведчиков в Деревню Гиблотопь." },
    ["1238c"] = { common = "Отлично. Наш агент Марг Ночной Соглядатай был отправлен на разведку в Терамор. Это его последний рапорт и, видимо, уже окончательно последний – судя по твоим словам, я боюсь, Марг навсегда остался в болотах..." },
    ["1239a"] = { common = "Стоило копнуть чуть глубже, и из земли показалась отрубленная голова орка. На его лице застыл оскал, а в тёмных глазах – вызов." },
    ["1239c"] = { common = "Это голова Марга Ночного Соглядатая! Этого-то я и боялся. Посмотри на эту рану у него на шее, – как думаешь, это какое-то оружие, или он пал от клыков и когтей какого-то зверя? Мы должны выяснить это. Выяснить, не является ли его смерть делом рук Альянса." },
    ["1240a"] = { common = "Мы должны выяснить обстоятельства смерти Марга! И единственный способ это сделать, – воспользоваться магией троллей. Отнеси голову Марга Кин'вилаю в лагерь Гром'гол в Тернистой долине. Кин'вилай – самый могущественный из знахарей племени Чёрного Копья, если кто-то и сможет вызвать дух Ночного Соглядатая – то это он." },
    ["1240c"] = { common = "Да, теперь я вижу. Дух Марга застрял в нашем мире, потому что его задание не было завершено. Ну что ж, давай поговорим с этим сердитым орком..." },
    ["1241a"] = { common = "Некоторое время назад один из наших дипломатов был отправлен в Терамор для встречи с Джайной Праудмур. Он не вернулся. Я подозреваю, что к этому приложило руку Братство Справедливости, но уверенности у меня пока что нет. Пока что нам удаётся скрывать факт исчезновения дипломата, но так продолжаться не может. Агенты королевской службы рыщут по городам, но я хочу задействовать и свои связи. В Аллее Героев вы найдёте моего старого друга, его зовут Йорген. Передайте ему эту записку и во всём его слушайтесь." },
    ["1241c"] = { common = "Хм-м... Йорген смотрит на вас, прищурившись. Хорошо. Придётся вам помочь, хоть и не очень-то хочется. Долг есть долг. И запомните одну простую вещь: вы знаете куда больше, чем уместно в вашем случае. Храните наши маленькие секреты и не болтайте по тавернам о том, что обнаружите. Ясно вам?" },
    ["1242a"] = { common = "Возьмите записку для Иллинга Триаса. Ничего ему не рассказывайте, просто ведите себя вежливо и дождитесь ответа; не волнуйтесь, Триас ответит. Ещё раз напоминаю вам: дело серьёзное, так что держите рот на замке. Триаса вы найдёте в его магазине в Торговом квартале; магазин называется \"Сыры Триаса\". Удачи!" },
    ["1242c"] = { common = "Извините, письмо мне? О... не так уж часто мне приходится получать что-то, кроме ящиков и бочонков, я ведь занят делом. Ну, давайте посмотрим, что там. Открывая письмо, Эллинг смотрит на вас. Вы выглядите возбуждённо, с вами всё в порядке?" },
    ["1243a"] = { common = "Йорген, ах ты старый мерзавец... Ну и что со всем этим делать? Ладно, я разберусь... Да чтоб ему в Круговерть Пустоты угодить раньше времени! Ну что, займёмся делом? Я задействую все свои контакты, но вам придётся побегать. Отправляйтесь в поселение Темнолесье, которое находится в Сумеречном лесу, и найдите там дозорного Бакуса; он обычно патрулирует северную дорогу за городской стеной. Просто скажите ему, что Братство Справедливости опять зашевелилось, а вы присматриваете за ним по моей просьбе – и он вам поможет, чем сможет." },
    ["1243c"] = { common = "Вас послал Триас, да? Другое дело... Можете гонять чудовищ, сколько вам заблагорассудится. Уверен, что для вас это не составит особого труда, какой бы ужас ни вылез на вас из сумерек... Так чего же желает мой дорогой друг в этот пасмурный день?" },
    ["1244a"] = { common = "Опять братство?! Они вечно что-то вытворяют; даже если они затихли, мы считаем это недвусмысленной угрозой. Кстати, сейчас я вспомнил, что последнюю пару недель их агенты так и кишат вокруг участка Эддла. Это подозрительно – должно быть, назревает какая-то крупная заварушка. Не хотите порыскать там и установить, в чём же дело? Ферма находится к югу от дороги из Западного Края как раз на входе в Сумеречный лес." },
    ["1244c"] = { common = "Вы вернулись, не вляпавшись ни в какие неприятности. Это само по себе достижение, не правда ли? Ну, покажите, что принесли? Да, очень похоже на официальные документы Братства Справедливости. Но это может быть и подделкой, которую вам подсунули, чтобы одурачить и сбить со следа." },
    ["1245a"] = { common = "О-ох, для обычной попытки ввести в заблуждение это слишком сложно. Отнесите этот документ Триасу, пусть поразмыслит над ним. И никому больше об этом не говорите. Кажется, это дело ни мне, ни ему не по плечу. Ну, посмотрим... И, пожалуйста, никому не говорите, что я вам помог. Если моё начальство поймёт, что я о чём-то узнал и не поделился с ними, они могут меня запросто повесить." },
    ["1245c"] = { common = "Да-а... весьма интересно. Йорген и Делавей молодцы, что навели меня на это. Кажется, Братство Справедливости всерьёз взялось за воплощение своих планов. Хм, а это что? \"Кулак\"? Знакомое имя..." },
    ["1246a"] = { common = "Вот что я об этом думаю... Дашель... Какой-то Дашель... Как его фамилия? Кулак! Дашель Каменный Кулак! В некоторых кругах его зовут просто Кулак, наверняка потому, что он не дурак подраться... Его можно найти в Старом городе, прямо в центре. Поговорите с ним. Если понадобится, используйте меч или любой подручный тяжёлый предмет, чтобы урезонить его, и не сомневайтесь. Если он так завязан в заговоре, как можно заключить по этим бумагам, то не расстанется с информацией по доброй воле..." },
    ["1246c"] = { common = "Что?! Мои дела тебя не касаются, ясно? Проваливай, нечего тебе здесь вынюхивать!" },
    ["1247a"] = { common = "Ну... м-м... да... Я кое-что знаю о встрече на участке Эддла. Она произошла несколько недель назад. Меня туда не приглашали, моё участие закончилось с провалом плана А, проклятие этим окаянным приключенцам... Парень, с которым связан план Б, пришёл из Менетила. Его зовут Пронырой. Это всё, что мне удалось узнать из запасного плана." },
    ["1247c"] = { common = "О, приятно видеть вас в живых. Значит, с Дашелем всё прошло хорошо? Я тут ещё раз перечитал их планы, и хотя в тексте не упоминается имя дипломата, которого они преследовали, речь идёт о плане Б, который вступил в действие после провала первой попытки захватить его. Этот Проныра, о котором упомянул Дашель, кажется, не имеет другого имени – непонятно, кто он; но нам хотя бы известно, что он из Менетила." },
    ["1248a"] = { common = "Один из моих знакомых переехал в Болотину, в портовый город Менетил. Думаю, что он поможет вам, если вы передадите ему привет и скажете, что работаете на меня. Зовут его Михаил; перед отъездом он говорил, что хочет стать барменом. Поговорите с ним, найдите этого Проныру и попробуйте разузнать ещё что-нибудь насчёт похищенного дипломата. Мы должны узнать, где его держат или хотя бы имя похищенного. Увы, в декларации ничего не говорится о том, что похитители собираются сделать с пленником после захвата." },
    ["1248c"] = { male = "Привет-привет, дорогой путник. Рады вас видеть. Не желаете ли эля? Или баранины? Скажите, чего бы вам хотелось, и я постараюсь выполнить все ваши пожелания. Меня зовут Михаил, я буду рад услужить вам. Э? Что это? Триас? Прошу вас, говорите потише. Моим посетителям не обязательно слышать, о чём мы с вами говорим.", female = "Привет-привет, дорогой путница. Рады вас видеть. Не желаете ли эля? Или баранины? Скажите, чего бы вам хотелось, и я постараюсь выполнить все ваши пожелания. Меня зовут Михаил, я буду рад услужить вам. Э? Что это? Триас? Прошу вас, говорите потише. Моим посетителям не обязательно слышать, о чём мы с вами говорим." },
    ["1249a"] = { common = "Значит, вас послал Эллинг? О, это повод десятикратно умножить моё гостеприимство! Просите всего, чего пожелаете, постараюсь выполнить любую вашу просьбу! Хм-м, Проныра, говорите? Не скажу, что мне знакомо это имя, но постараюсь что-нибудь разведать... Не оборачивайтесь прямо сейчас, но вон тот господин около двери слишком внимательно смотрит на нас и прислушивается к нашему разговору. На вашем месте я бы попробовал изловить его прежде, чем он уйдёт отсюда." },
    ["1249c"] = { common = "Поймали его, да? Отлично! Знаете, а ведь это и есть тот самый Проныра! Я и сам удивился. Да, не думал я, что буду так скучать по всяким тайным расследованиям и азартным погоням. Верно говорят: сколько волка ни корми... Только не обмолвитесь про это Эллингу – он наверняка потащит меня обратно в Штормград, узнав, что я затосковал по былым денькам. Хорошо, что мне удалось оказать вам хотя бы небольшую услугу во время вашего пребывания в Менетиле. Если ещё что-нибудь понадобится, просто попросите." },
    ["1250a"] = { common = "Братство Справедливости не столько мне платит, чтобы за них умирать. Они похитили короля. Да, настоящего короля Штормграда, а не какого-то там дипломата. Он направлялся в Терамор, чтобы побеседовать с Джайной Праудмур, это большая тайна и дело тоже нешуточное. Но тут встряло братство, у них был свой осведомитель. В мои задачи входило только взять их человека на борт королевского корабля, когда он стоял у пристани. Парня звали Хендел, клянусь, это всё, что я знаю!" },
    ["1250c"] = { common = "КОРОЛЬ?! В смысле... король? Настоящий король? Вы шутите? Вы же не имеете в виду, что вы разыскиваете похитителей короля?! Я даже не в курсе, что он пропал. Теперь ясно, почему сейчас в Штормграде всем заправляет его сын. Я прямо сейчас напишу Эллингу. Он должен знать, что вы встали на след. Мне и в голову не приходило, что Джан может предать наш Штормград за деньги, пусть и немалые. Даже у вора должна быть честь! Теперь главное – найти этого Хендела – думаю, тут я могу помочь..." },
    ["1251a"] = { common = "Железный щит, почерневший в пламени бушевавшего здесь пожара, висит на остове камина – только это и осталось от таверны \"Последний привал\". Щит можно снять." },
    ["1251c"] = { common = "Люди всегда отличались странными вкусами в области украшательства. Но на кой вешать над камином простой металлический щит? Может, его повесили туда те, кто спалил таверну? Предупреждение? Угроза?" },
    ["1252a"] = { common = "Солнечный зайчик блеснул в глаза из-под обломков. Вы достаёте из-под мусора бляху с золотым якорем на белой эмали – символом Терамора. Под якорем выбито имя владельца: \"Лейтенант Павал Рит\"." },
    ["1252c"] = { common = "День, когда мне приносят бляхи погибших стражей, светлым не назовёшь. Иногда они гибнут в битве, и мне приходится сообщать об их участи семье и близким... Иногда мы так и не знаем, что с ними сталось. А иногда знаем, и это ещё хуже..." },
    ["1253a"] = { common = "Железный щит, почерневший в пламени бушевавшего здесь пожара, висит на остатках камина – только это и осталось от таверны \"Последний привал\". Щит можно снять." },
    ["1253c"] = { common = "Хмм... Я в устройстве оружия и доспехов не разбираюсь, я ими пользуюсь. Щит как щит, разве что огнём опалило." },
    ["1258a"] = { common = "Ещё один компонент моего нового рецепта – клешни гигантского краба. К сожалению, те которые водятся в Пыльной трясине, – грязнокрабы, не годятся... Зато те, что живут на Болоте Печали, – в самый раз! Оболочка клешни – важный элемент украшения блюда, поэтому они мне нужны целые и непоцарапанные. К сожалению, у краба всего две клешни, а то и одна, а мне для моих кулинарных экспериментов их нужно гораздо больше. Так что насчёт небольшой прогулки?" },
    ["1258c"] = { common = "Прекрасные экземпляры. На самих клешнях ни царапинки, а мясо как и положено, розовое и нежное. У вас несомненный талант к этому делу! Не задумывались о карьере шеф-повара?" },
    ["1259a"] = { common = "Лейтенант Павал Рит? Не припоминаю такого имени. Лучше всего вам будет поговорить с адъютантом Тезораном. У него хранятся все записи о тераморских стражниках – от их имён до предпочитаемого вооружения. Уж он-то расскажет вам об этом Павале Рите." },
    ["1259c"] = { common = "Здравствуй. Так тебе нужна информация об одном из нас? Как его бишь, Рит? Сейчас проверю по своим записям." },
    ["1260a"] = { male = "Я составляю новое меню для ресторана. Сельская кухня с болотным душком. Думаю, посетителям \"Синего отшельника\" понравится! Я послал своего племянника Моргана в Терамор, город на краю Пылевых топей. Там он собирает местные кулинарные рецепты, и мне хотелось бы знать, как его успехи. Долог путь до Терамора, и для меня тяжеловат. Но я думаю, что такой молодой герой с радостью ухватится за возможность совершить подобное путешествие.", female = "Я составляю новое меню для ресторана. Сельская кухня с болотным душком. Думаю, посетителям \"Синего отшельника\" понравится! Я послал своего племянника Моргана в Терамор, город на краю Пылевых топей. Там он собирает местные кулинарные рецепты, и мне хотелось бы знать, как его успехи. Долог путь до Терамора, и для меня тяжеловат. Но я думаю, что такая молодая героиня с радостью ухватится за возможность совершить подобное путешествие." },
    ["1260c"] = { common = "А! Так вас послал мой дядя? Ну что ж, я тут собирал для него рецепты и добился определённых успехов, но мне нужна помощь. Надеюсь, вы не боитесь ноги промочить?" },
    ["1261a"] = { male = "Ах ты, проклятый грязнокраб! Ты меня не достанешь! Ой, да я ж покойник! Видать, он всё-таки достал меня. А как же моя миссия?! Ты, должен закончить её. Я наблюдал за силами Альянса, высадившимися на берегу возле Терамора. На одном из солдат была подвеска, на которой было столько драгоценных камней, что не всякий вождь может себе позволить. Той ночью я пробрался в лагерь и украл эту подвеску. Но когда я возвращался в свой лагерь, этот проклятый грязнокраб прикончил меня! Ты должен найти эту тварь и вернуть подвеску.", female = "Ах ты, проклятый грязнокраб! Ты меня не достанешь! Ой, да я ж покойник! Видать, он всё-таки достал меня. А как же моя миссия?! Ты, должна закончить её. Я наблюдал за силами Альянса, высадившимися на берегу возле Терамора. На одном из солдат была подвеска, на которой было столько драгоценных камней, что не всякий вождь может себе позволить. Той ночью я пробрался в лагерь и украл эту подвеску. Но когда я возвращался в свой лагерь, этот проклятый грязнокраб прикончил меня! Ты должна найти эту тварь и вернуть подвеску." },
    ["1261c"] = { male = "Эта подвеска была на солдате Штормграда?? Благодарю тебя, за то, что раскрыл загадку смерти Марга. Но эта подвеска... Это новая загадка. И, возможно, она несёт угрозу и Орде и Альянсу.", female = "Эта подвеска была на солдате Штормграда?? Благодарю тебя, за то, что раскрыла загадку смерти Марга. Но эта подвеска... Это новая загадка. И, возможно, она несёт угрозу и Орде и Альянсу." },
    ["1262a"] = { common = "Странно, что украденная Маргом была у простого солдата. Возможно её владелец маскировался, или, что вероятнее, солдаты сами её стащили. Что бы там ни было, эта подвеска принадлежала лицу благородного происхождения, и мы должны найти её хозяина, если хотим разрешить эту загадку. Отнеси эту подвеску Зору Одинокое Дерево в Оргриммар. Он хорошо разбирается в интригах Альянса и, возможно, он в курсе, если эта подвеска известна в Штормграде." },
    ["1262c"] = { common = "Эта подвеска сделана удивительно тнокой и искусной работы. у такое не нужно, но многие люди головы бы не пожалели за такую драгоценность. Я изучу эту подвеску повнимательнее. Будем надеяться что в своё время мы всё про неё узнаем." },
    ["1264a"] = { common = "В начале каждого месяца стражи бухты Кул-Тираса получают жалованье и отправляются прочь из Терамора в отпуск. Многие из них приходят сюда – выпить, гульнуть, пообщаться с женщинами. Одна из таких компаний регулярно приходит в эту таверну. Мне кажется, что и этот Хендел был среди них. Командир Самаул из Терамора может вам помочь в поисках Хендела, если тот до сих пор там. Самаул всецело верен леди Джайне, но если ты упомянешь при нём имя Эллинга, он должен стать... посговорчивее." },
    ["1264c"] = { common = "Рад встрече. Я – командир Самаул, состою на службе в гвардии леди Джайны Праудмур в Тераморе. Хотя я немного занят, вы можете задавать мне любые вопросы, которые вас интересуют. Не сочтите за повод для обиды, но я попрошу вас высказаться по возможности лаконично. Надеюсь, что вы проявите должную осторожность, если соберётесь за пределы города. Там, снаружи – огры, орки и мурлоки, а в южной части болота обитают чёрные драконы." },
    ["1265a"] = { common = "Хендел? Да, я его знаю, но почему вас интересуют мои солдаты? Эллинг отправил вас разыскать его? Звучит как-то странно. Эллинг не послал бы вас ко мне, если бы всё было в порядке. Вы можете хранить свои секреты сколько угодно, только имейте в виду: мой долг – охранять эти земли. Если ваша деятельность может нарушить порядок, лучше сообщите заранее. Думаю, что Хендела вы найдёте в первой по счёту от Терамора башне. Будьте осторожны." },
    ["1265c"] = { common = "Человека, известного вам как Хендел, здесь нет. Всё остальное, что можно узнать от леди Праудмур, я думаю, вы уже знаете. Она просила меня найти вас и оказать вам помощь в расследовании. Если вы готовы принять мои услуги, я сообщу вам, где можно найти рядового Хендела. Вдвоём мы сможем предать его в руки правосудия." },
    ["1266a"] = { common = "Рядовой Хендел находится к западу отсюда, в составе гвардии, охраняющей тераморских разведчиков во время отдыха. Они пытаются выяснить местоположение деревни Папоротники, базы Орды, а заодно и приглядывают за нашими границами. Вы найдёте его без труда, просто поищите в палатках у дороги. У меня есть и другие дела, но я догоню вас так быстро, как смогу. При необходимости вы сможете найти меня в башне леди Праудмур." },
    ["1266c"] = { common = "Добрый день. Это опасное место для горожанина. Если вы цените свою жизнь, не стоит находиться здесь слишком долго. Задавайте вопросы быстро, попробую вам помочь. Только смотрите по сторонам, не покажутся ли огры. По слухам, поблизости база Орды. Разведчики пытаются найти её, но это дело небыстрое. Мы ещё не добились успеха." },
    ["1267c"] = { common = "Спасибо тебе за твою помощь, путник. Пожалуйста, возьми это в знак моей благодарности за твои усилия." },
    ["1268a"] = { common = "Цепочка следов уходит от всё ещё дымящегося остова таверны \"Последний привал\". В отличие от других следов, еле заметных на мягкой болотистой почве, эти видны отчётливо." },
    ["1268c"] = { common = "Следы копыт... Это может быть иглогрив, или даже кентавр. То, что они пришли в Степи, что-то да значит, и, сдаётся мне, они вполне способны сжечь таверну. К тому же кто бы это ни был, они не только сожгли здание, жена и детёныш владельца были убиты. Плохо дело... Ладно, я пошлю Кагоро посмотреть куда ведут следы." },
    ["1269a"] = { common = "Солнечный зайчик блеснул в глаза из под обломков. Вы достаёте из-под мусора бляху с золотым якорем на белой эмали – символом Терамора. Под якорем выбито имя владельца: \"Лейтенант Павал Рит\"." },
    ["1269c"] = { common = "Я знаю этого человека, Павала Рита. Жалкий даже по меркам собственного племени. Покинул своих товарищей и теперь скрывается в лесу. Я послал Огрона выследить его. Некоторые подозревают, что он крал припасы. Я видел что Огрон направляется на юго-восток." },
    ["1270a"] = { male = "Ура! Наконец-то нашёлся кто-то, кто не хочет меня съесть! Не могу отбиться от тутошнего зверья, а т ы, парень как раз мне в этом и поможешь. Гоблину из Кабестана по кличке Мебок Миззрикс нужны листья болотного боба для зелья или ещё какой надобности, – меня это, честно говоря, не колышет: он неплохо платит, а я неплохо знаю болота, потому и впрягся. Вот только не успел я ещё найти эти листья, как меня уже окружили. Мне до зарезу необходим кто-то кто поможет выбраться отсюда и прикроет спину, пока я буду искать для Мебока эти листья.", female = "Ура! Наконец-то нашёлся кто-то, кто не хочет меня съесть! Не могу отбиться от тутошнего зверья, а т ы, подруга как раз мне в этом и поможешь. Гоблину из Кабестана по кличке Мебок Миззрикс нужны листья болотного боба для зелья или ещё какой надобности, – меня это, честно говоря, не колышет: он неплохо платит, а я неплохо знаю болота, потому и впрягся. Вот только не успел я ещё найти эти листья, как меня уже окружили. Мне до зарезу необходим кто-то кто поможет выбраться отсюда и прикроет спину, пока я буду искать для Мебока эти листья." },
    ["1270c"] = { male = "Вонючка недавно приносил тут мне травки, и он расказал, что ты помог ему выпутаться из мерзкой ситуации. Хорошая работа! Друг Вонючки и мой друг. Перед тем как вернуться обратно на болота, он просил передать тебе это, если мы вдруг увидимся.", female = "Вонючка недавно приносил тут мне травки, и он расказал, что ты помогла ему выпутаться из мерзкой ситуации. Хорошая работа! Друг Вонючки и мой друг. Перед тем как вернуться обратно на болота, он просил передать тебе это, если мы вдруг увидимся." },
    ["1271c"] = { common = "Мой племянник сказал, что ты помог его исследованиям в Пылевых Топях, а также помог его другу в трудном положении. Ну, мы Штерны, всегда держимся вместе, и мы не игнорируем своих друзей! Итак, путник, мой руки, потому что вечером мы устроим в твою честь вечеринку!" },
    ["1273a"] = { common = "Это было непросто, но я всё-таки нашёл этот Рит. Неплохо он прятаться... Для человек. Огрон боится, что человек свихнуться, – слишком много времени на болоте, Твоя идти с Огрон и спрашивать человека всё, что хотеть." },
    ["1273c"] = { common = "Пфф. Это хорошо, что Рит больше не будет прятаться на болоте, но это плохо, что люди такие хрупкие существа, что могут помереть от одной маленькой стрелы. Сдаётся мне, что мы зашли в тупик и нужно поискать разгадку где-нибудь ещё." },
    ["1274a"] = { male = "Простите, сэр. Епископ Делавей попросил меня разыскать любителя приключений, который мог бы помочь ему, оказав услугу весьма деликатного свойства. Если вы без лишнего шума проберётесь в Крепость Штормграда и обратитесь к епископу, он наверняка примет вашу помощь. Прошу вас, храните это в тайне, ибо всё это дело большой важности.", female = "Простите, мадам. Епископ Делавей попросил меня разыскать любителя приключений, который мог бы помочь ему, оказав услугу весьма деликатного свойства. Если вы без лишнего шума проберётесь в Крепость Штормграда и обратитесь к епископу, он наверняка примет вашу помощь. Прошу вас, храните это в тайне, ибо всё это дело большой важности." },
    ["1274c"] = { common = "Здравствуйте. Я – епископ Делавей. Дайте-ка, я угадаю, почему вы здесь! Наверняка потому, что откликнулись на просьбу юного Томаса, который предложил вам оказать мне услугу. Он всегда стремится помочь мне. Боюсь, я ещё не успел всё сформулировать, так что простите мне некоторую невнятность изложения... И, прошу вас, храните всё это в тайне." },
    ["1275a"] = { common = "Безрассудные эльфы крови попали в западню демонической магии. Разве они не видели, что случилось с нагами и сатирами Калимдора? Я боюсь, что эльфы крови могут претерпеть такую же трансформацию. Азерот не может позволить себе породить ещё одну расу злобных монстров. Я хотел бы изучить ствол мозга сатиров и нагов, чтобы понять, на что обрекают себя эльфы крови. И сатиров, и нагов вы найдёте в Непроглядной Пучине, на побережье Ясеневого леса. Путь неблизкий." },
    ["1275c"] = { common = "Вы проделали долгий путь и, несомненно, столкнулись с огромной опасностью. Ваши действия были самоотверженными. Ваша помощь – на благо всему Азероту. Я благодарю вас, за всё, что вы сделали. А теперь прошу меня простить, но мне нужно работать..." },
    ["1276a"] = { common = "А, вспомнил! Мозарн – знаменитый кузнец из Громового Утёса. Я же помню, что слышал это имя прежде! Если мне не изменяет память, Служители Земли наградили меня оружием его работы, хорошее было оружие. Возможно, он расскажет тебе больше о щите, вышедшем из его рук. Я не уверен, что эта информация важна, но, поскольку мы так и не знаем ничего о Рите, пренебрегать ей было бы неразумно." },
    ["1276c"] = { male = "Да, ты прав Это моя работа. Правда, боюсь, что это всё, что я могу тебе рассказать о нём. Из моих рук вышло столько щитов и прочего оружия, что вряд ли я смог бы запомнить их все.", female = "Да, ты права Это моя работа. Правда, боюсь, что это всё, что я могу тебе рассказать о нём. Из моих рук вышло столько щитов и прочего оружия, что вряд ли я смог бы запомнить их все." },
    ["1282a"] = { common = "Ничего не могу с собой поделать, мне так жаль старину Джима... Он не всегда был таким... Когда-то он держал таверну на болотах, дивное было местечко. Слушай, я не в настроении говорить об этом. Если тебе нужна информация, поговори с капитаном Ваймсом." },
    ["1282c"] = { common = "Настоящее его имя – Джеймс Хьяль. Он открыл таверну на краю Степей, хотел сделать уютное местечко для отдыха путешественников. Может, он слишком многого хотел, но некоторое время дела в таверне шли хорошо. Потом мы потеряли контроль за дорогами через болота, и здесь стали шататься огры, а Джеймс был слишком упрям, он не захотел бросить своё детище ради безопасности. Теперь таверна \"Последний привал\" сгорела до основания. Мы пытались разобраться, но особых успехов не достигли, поэтому твою помощь примем с благодарностью. Если хочешь помочь – посмотри, вдруг что найдёшь на развалинах." },
    ["1284a"] = { common = "Цепочка следов уходит от всё ещё дымящегося остова таверны \"Последний привал\". В отличие от других следов, еле заметных на мягкой болотистой почве, эти видны отчётливо." },
    ["1284c"] = { common = "Следы копыт, говоришь? В последнее время в этих краях зашевелились кентавры. Наши разведчики во время вылазки в Степи заметили несколько их лагерей и поселений. Я пошлю одного из наших охотников, Фальграна Гастила, посмотреть, куда ведут эти следы." },
    ["1285a"] = { common = "Реддон... Редпат... А! Вот он! Лейтененат Павал Рит. Всупил в ряды тераморской стражи вместе с остальными новобранцами, которые пришли из-за моря вместе с леди Праудмур. Зачислен в морские пеходинцы Кул Тираса в возрасте шестнадцати лет. Отличная служба, поощрения... Числится пропавшим без вести." },
    ["1285c"] = { common = "Пропал без вести? В переводе с языка Тезорана, это значит – предатель. Не сомневаюсь, что это один из тех глупцов, слепо преданных адмиралу Даэлину и готовых ради него предать собственную страну. Забавно, правда? Дезертиры обвиняют нас в предательстве дела Альянса." },
    ["1286a"] = { common = "Удержаться здесь, на болотах, было нелегко. Но мы, со всей своей решимостью и отвагой, смогли возвести несколько оборонительных сторожевых башен в округе. По последним донесениям наших разведчиков, группа дезертиров засела в Разрушенной башне, к юго-востоку от таверны. За главного у них, кажется, Балос Хакен. Посмотрим, может удастся получить от него какие-то сведения. Но будь с ним осторожнее, он – тёртый вояка." },
    ["1286c"] = { common = "Тебя Ваймс прислал? Вечно он спихивает на других всю грязную работу..." },
    ["1287a"] = { common = "Рит? Этот трус? Мы вышвырнули его из лагеря, потому что он настаивал на налёте на деревню огров Гиблотопь, чтобы пограбить их запасы. Нас не так много, чтобы рассчитывать справиться с этими безмозглыми тварями. Он настолько часто зарывался, что мы решили, что с нас хватит, и прогнали его. Вот, я помог тебе, почему бы теперь тебе не забыть о нашей встрече?" },
    ["1287c"] = { common = "Я пошлю лейтенанта Келдвелла поговорить с дезертирами из Разрушенной башни. Вдобавок, я попрошу его поискать Рита. Болота не так уж велики и непроходимы, так что я уверен, он его отыщет." },
    ["1288a"] = { common = "Хорошая работа, путник. Для любителя просто отличная. Леди Праудмур просила, чтобы я держал её в курсе, но я некоторое время не имел возможности с ней пообщаться. Я собирался отправить ей рапорт позже, — но мне кажется уместным вместо этого послать к ней тебя. Ты куда лучше меня ответишь на все её вопросы." },
    ["1301a"] = { common = "Перед тем, как перебраться сюда, в \"Синий Отшельник\", я обучался, у одного из лучших поваров которых я когда-либо встречал. Его звали Джеймс Хьяль, и всё чего я добился в этой жизни, это только благодаря ему. Интересно, как-то он там сейчас? Они вместе со своим братом Винсентом работали в таверне, в Гавани Менетилов, но я давно о нём ничего не слышал. Если вдруг ненароком встретишь его, кланяйся от меня." },
    ["1301c"] = { common = "Джеймс? Так он ещё когда уехал отсюда. Волна патриотизма накрыла, наверное. Можно понять. Многие после всего этого безумия, творящегося в Лордероне, последовали за море за Джайной Праудмур." },
    ["1302a"] = { common = "Мой брат Джеймс ушёл за море с леди Праудмур. Последнее, что я слышал, было то, что по окончании боёв он открыл там таверну. Но, где бы он не находился, я уверен, что дела у него идут хорошо. Он ведь, знаете ли, великолепный повар. Я некоторое время не имел о нём известий – видать, с гостиницей было много хлопот – но я уверен, что клерк в Тераморе сможет указать вам, где его искать." },
    ["1302c"] = { common = "Джеймс Хьяль, Джеймс Хьяль... Что-то знакомое... А, точно! Случай с \"Последним привалом\". Если ты хоть что-то об этом знаешь, то пойди и расскажи капитану Ваймсу. Он ведёт расследование." },
    ["1319a"] = { common = "Увы, но я не смогу помочь тебе. Впрочем, я знаю, кто сможет. Каз Дваждыдвац – один из лучших наших кузнецов. Его можно найти на кузне. Покажи ему щит и послушай, что он скажет." },
    ["1319c"] = { common = "Хмм... Интересная железяка. Это точно не моя работа, и я не знаю ни одного кузнеца по эту сторону моря, из чьих рук она могла бы выйти." },
    ["1320a"] = { common = "Чуть было не просмотрел... Кожаный ремень на тыльной стороне щита сгорел, но, сдаётся мне, он был приспособлен под крупную руку. Скорее всего, тауренскую. Вот, в общем, и всё, что я могу тебе сказать. Передай капитану Ваймсу, что я сожалею, но больше ничем не могу ему помочь." },
    ["1320c"] = { common = "Узнать удалось немного, но и это сгодится. Будем надеяться, что вскоре прояснятся остальные части этой головоломки, и мы сможем увидеть полную картину произошедшего." },
    ["1321a"] = { common = "Хмм... Я не вижу в этом щите ничего необычного. Нужно попросить До'гола, нашего кузнеца, взглянуть на него. Может быть, До'гол сможет рассказать нам больше, хотя я бы не надеялся на это..." },
    ["1321c"] = { common = "Хороший щит. Крепкий, тяжёлый, хороший... Но До'голу он не нужен. До'гол делает щиты, а не покупает их. Теперь понятно?" },
    ["1322a"] = { common = "Хммм... Тут, на ободе щита, оказывается, есть надпись, но прочитать её трудно, она почти вся обгорела. Мне нужна кислота, чтобы отчистить её. Яд пауков-темножвалов, обитающих в топях, подойдёт. Принеси мне немного их ядовитых желёз, и я смогу отчистить этот щит." },
    ["1322c"] = { common = "Я не люблю слишком больших пауков – их не раздавишь. Спасибо. Теперь я вскрою железы и залью их содержимым щит…" },
    ["1323a"] = { common = "Сдаётся мне, что с кислотой я переборщил. Теперь осторожно потрём щит… Хмм. Прочесть сложновато, но, похоже, тут написано имя: Мозарн. Никогда о таком не слышал. Надо спросить Крога, он знаком с кучей народу." },
    ["1323c"] = { common = "Мозарн? Звучит знакомо... Но поручиться не могу. Может быть вспомню попозже. Скорее всего, это имя не имеет значения. Щит мог попасть туда откуда угодно и с какой угодно целью." },
    ["1324a"] = { common = "Что?! Вы приходите сюда, обвиняете меня в пособничестве Братству Справедливости и надеетесь, что я буду стоять столбом и позволю себя убить? Меня, между прочим, давно насчёт вас предупреждали..." },
    ["1324c"] = { common = "Уверяю вас, что мы все огорчены текущими событиями, но просим позволить забрать его назад в Терамор, чтобы задать несколько вопросов. Это поможет в поисках короля. Леди Праудмур отблагодарит вас за помощь. Обратитесь к ней при первой возможности." },
    ["1338a"] = { common = "Есть один дворф-бронник, чья работа меня глубоко восхищает. Его зовут Фьюрен Длиннобород, и такого искусника ещё поискать. Мне нужен новый щит, и я хотел бы сделать заказ у него! Проблема в том... что он живёт далеко на юге, в Квартале Дворфов в Штормграде. В человеческих землях! Представления не имею, зачем он поселился так далеко от Стальгорна. Должно быть, люди платят немалую мзду, лишь бы удержать его у себя! Если ты любишь путешествовать и не прочь подзаработать, может, передашь мой заказ Фьюрену?" },
    ["1338c"] = { common = "А, заказ от дворфа Грозовой Вершины. Это гордый клан, славный крепкими, сильными дворфами. И их богатством. Большое спасибо. Я сегодня же вечером займусь щитом для горного пехотинца Грозовой Вершины." },
    ["1339a"] = { male = "Я слышал, что горный пехотинец Грозовая Вершина ищет гонца, который совершил бы по его просьбе небольшое путешествие. Сможет ли герой вроде тебя справиться с его поручением? Если ты жаждешь приключений, ищи Грозовую Вершину на северной сторожевой башне.", female = "Я слышал, что горный пехотинец Грозовая Вершина ищет гонца, который совершил бы по его просьбе небольшое путешествие. Сможет ли героиня вроде тебя справиться с его поручением? Если ты жаждешь приключений, ищи Грозовую Вершину на северной сторожевой башне." },
    ["1339c"] = { common = "Верно. У меня есть одно дельце, но самому мне недосуг – не могу покинуть пост. Путь неблизкий, придётся поработать ногами. Зато отличная возможность поискать приключений!" },
    ["1358a"] = { common = "Мой коллега на Калимдоре, аптекарь Хелбрим, исследует воздействие лордеронских ядов на тамошних зверей. Он наверняка хотел бы иметь препарат из волчьего сердца, что мне прислал Ренферрел. Хелбрим обосновался в Степях, в деревне под названием Перекрёсток. Чтобы до него добраться, вам нужно будет на дирижабле добраться до орочьей столицы Оргриммара, а потом пешком проследовать на юг, в Дуротар. Направляйтесь на запад, в Степи, и вскоре дойдёте до Перекрёстка." },
    ["1358c"] = { common = "А, очень хорошо. Если первые результаты верны, токсические свойства этих сердец могут серьёзно продвинуть нас в наших представлениях о ядах. Это долгожданная посылка, Топот. Ваша награда за неё – совершенно заслуженная." },
    ["1359a"] = { common = "Волчьи сердца, которые вы собрали, обладают качеством, невиданным доселе в подобных образцах. Это сила яда, которая должна быть смертельной даже для тех самых волков, в груди которых бьются эти сердца! Это просто невероятно, и мы должны продолжить исследование. Я сохранил несколько полученных препаратов. Отнесите их моей коллеге, аптекарю Зинг. Её можно найти в главном представительстве нашего Общества в Подгороде." },
    ["1359c"] = { common = "Ах да, препараты сердец, о которых говорил Ренферрел. Я хочу поскорее начать экспериментировать с ними... Обнаружение новых форм ядов всегда вызывает живейший интерес в Королевском фармацевтическом обществе." },
    ["1360a"] = { common = "Я неплохо зарабатывал горнорабочим на ульдаманском раскопе в Бесплодных землях, пока не появились эти клятые трогги. Я едва сумел спасти свою шкуру, но в суматохе потерял самое дорогое, что у меня было. Уверен, что трогги не добрались до моего сокровища, поскольку оно в сундуке, но сундук-то в самой их гуще. Если ты принесёшь его мне, то не поскуплюсь ни на деньги, ни на хвалу! Сундучок с моим именем находится в конце Северного зала. Вот туда тебе и надо попасть." },
    ["1360c"] = { common = "Ах, я снова счастлив! Спасибо тебе огромное. Может, кому из дворфов дороже всего блеск металла, а кому – сверкание драгоценных камней, но Крепкорук без своей драгоценной пивной кружки вряд ли может считаться Крепкоруком!" },
    ["1361a"] = { common = "Регтар Врата Смерти, воин Орды, набирает агентов для похода в земли Пустошей. Любой желающий может поговорить с ним и попробовать записаться в отряд. Найти Регтара можно в Степях, в одном из укрытий к западу от Перекрёстка. Не следует забывать, что в Пустошах не затихают битвы, поэтому без оружия там нечего делать." },
    ["1361c"] = { common = "Да, я набираю добровольцев. Тех, кто готов отправиться в Пустоши и сражаться с кентаврами. Я изложу ситуацию вкратце, чтобы ты скорее мог приступить к выполнению задания." },
    ["1362a"] = { common = "Кентавры из клана Колкар изначально жили в Пустошах, но теперь они всё чаще появляются в Степях. Это известный факт, и Орда послала своих агентов разбираться с ними. Однако же пока клан Колкар силён в Пустошах, эти кентавры всегда будут для нас угрозой. Думаю, пора от них избавиться. Главное – безопасность! Поговори с Фелгуром Бью-Двоих: ты его найдёшь на Заставе Скитающихся Духов в Пустошах. Его отправили туда для сбора информации о кентаврах. Думаю, он лучше всех знает, как справиться с кланом Колкар." },
    ["1362c"] = { male = "Тебя Регтар сюда прислал? Значит, ты и будешь решать проблему кентавров? Что ж, хорошо. Надеюсь, ты успел отдохнуть. Не знаю уж, удастся нам разобраться с этими тварями, или нет, но за то, что это будет долгая и тяжкая драка, могу ручаться. Присядь и послушай меня...", female = "Тебя Регтар сюда прислал? Значит, ты и будешь решать проблему кентавров? Что ж, хорошо. Надеюсь, ты успела отдохнуть. Не знаю уж, удастся нам разобраться с этими тварями, или нет, но за то, что это будет долгая и тяжкая драка, могу ручаться. Присядь и послушай меня..." },
    ["1363a"] = { common = "Я слежу за тем, чтобы все фолианты и свитки в библиотеке Академии Тайных Наук и Искусств постоянно находились под присмотром. Кто знает, сколько глупостей может натворить непосвящённый, заполучив тайные трактаты по магии? Например, на прошлой неделе мой помощник Деллис допустил одну оплошность... Он неплохой работник и хорошо ориентируется в пределах библиотеки, но совершенно теряется, стоит ему выйти за ворота Штормграда... Пожалуйста, помогите Деллису разобраться с его затруднением." },
    ["1363c"] = { common = "Да не виноват я! Клянусь, не виноват!" },
    ["1364a"] = { common = "Указания мастера Мазена были совсем простыми: доставить важное сочинение дозорному Махару Ба в Крепость Стражей Пустоты. Но мне раньше не доводилось бывать в Выжженных землях! Путешествие было просто ужасным... Неподалёку от Болота Печали я свернул куда-то не туда и оказался окружён жуткими тварями, похожими на растения. Они напали на меня, и я сбежал. Представьте себе, при этом я потерял сочинение! Думаю, его забрала одна из этих тварей. Не могу ли я попросить вас найти документ и доставить его Махару Ба?" },
    ["1364c"] = { common = "Какое счастье! До сего момента я считал, что мой запрос на \"Рассуждения Кадгара о пространственной сходимости\", который я отправлял в Академию Тайных Наук и Искусств, был отклонён мастером Мазеном. Он, должно быть, просто потонул в запросах, поскольку в последнее время происходит множество странных событий. Теперь прошу меня простить – мне пора приступить к исследованиям. Понимаете, сама возможность прикоснуться к творению величайшего Кадгара повергает меня в трепет..." },
    ["1365a"] = { common = "Племя Колкар – не единственные кентавры в Пустошах. На этих пустынных равнинах поселилось множество племён, ведущих друг с другом бесконечную войну. Наше счастье, что они дерутся между собой: кентавры сильны и яростны в битве, и, если бы они объединились, нам тяжело было бы выстоять против них. Мы должны покончить с ними прежде, чем они объединятся. Твоё первое задание – расколоть племя Колкар. Для этого нужно убить их предводителя Дез'хепа. Деревня клана Колкар находится к северо-востоку отсюда. Иди, и да пребудет с тобой удача." },
    ["1365c"] = { common = "Отлично. Быстрый и точный удар по клану Колкар стал весьма эффектной демонстрацией силы, а сила – это именно то, что кентавры понимают лучше всего. Смерть вождя клана Колкар не только расколет клан, но и станет предостережением для всех прочих кентавров." },
    ["1366a"] = { common = "Тебе удалось устрашить кентавров; теперь пришло время пустить им кровь. Странствуя по Безлюдью, охоться на кентавров. Их клан меня не волнует: просто убей их и принеси мне уши. Пригоршни ушей! Чем меньше кентавров, тем слабее их решимость: пусть навсегда расстанутся с мыслью завоевать эти земли! Доброй охоты." },
    ["1366c"] = { male = "Теперь-то кентавры навсегда запомнят твоё имя! Уверен, они уважают и страшатся тебя. Уверен, благодаря тебе они не забудут и того знамени, под которым ты вступал в бой. Знамя Орды!", female = "Теперь-то кентавры навсегда запомнят твоё имя! Уверен, они уважают и страшатся тебя. Уверен, благодаря тебе они не забудут и того знамени, под которым ты вступала в бой. Знамя Орды!" },
    ["1367a"] = { common = "Чтобы победить кентавров, мы должны обратить против них их же собственную ненависть. Мы заключим союз с одним из племён, и так найдём способ одолеть всех остальных. Если ты решишь заключить союз с племенем Маграм, уничтожь их кровных врагов – племя Гелкис. Так ты завоюешь уважение племени Маграм. Когда кентавры будут достаточно доверять тебе, постарайся встретиться с Варугом. Ты найдёшь его на окраине деревни Маграм в юго-восточной части Пустошей." },
    ["1367c"] = { male = "Кентавры племени Гелкис кричат от ужаса, заслышав твоё имя. Они страшатся и ненавидят тебя. Ненавидят так же, как племя Маграм! Может, ты и не слабее нас. Может, ты даже достоин того, чтобы мы с тобой говорили. Посмотрим...", female = "Кентавры племени Гелкис кричат от ужаса, заслышав твоё имя. Они страшатся и ненавидят тебя. Ненавидят так же, как племя Маграм! Может, ты и не слабее нас. Может, ты даже достойна того, чтобы мы с тобой говорили. Посмотрим..." },
    ["1368a"] = { common = "Чтобы победить кентавров, мы должны обратить против них их же собственную ненависть. Мы заключим союз с одним из племён, и так найдём способ одолеть всех остальных. Если ты решишь заключить союз с племенем Гелкис, уничтожь их кровных врагов – племя Маграм. Так ты завоюешь уважение племени Гелкис. Когда кентавры будут достаточно доверять тебе, постарайся встретиться с Утой Мудрой. Ты найдёшь её на окраине деревни Гелкис в юго-западной части Пустошей." },
    ["1368c"] = { male = "Земля говорит со мной, земля говорит, что ты убил многих из племени Маграм. Это хорошо. Если хочешь быть другом племени Гелкис, слушай. Я буду говорить с тобой. У меня есть для тебя дело.", female = "Земля говорит со мной, земля говорит, что ты убила многих из племени Маграм. Это хорошо. Если хочешь быть другом племени Гелкис, слушай. Я буду говорить с тобой. У меня есть для тебя дело." },
    ["1369a"] = { common = "Племя Гелкис считает, что нас защищает матерь кентавров Терадрас. Они глупы. Кентавров никто не защищает. Маграм не нужна защита! Мы сильнее всех! Пусть племя Гелкис поймёт, насколько они глупы. Отправляйся в их деревню, прямиком к пещере. В этой пещере они хранят кристаллы – слёзы Терадрас. Уничтожь эти кристаллы! Принеси мне их осколки!" },
    ["1369c"] = { male = "Ага! Вот они, Слёзы! Теперь племя Гелкис поймёт, что Терадрас не защитит их. Она не станет плакать, когда мы сокрушим их! Маграм будут править здесь! Ты хорошо сделал, выбрав нашу сторону. Мы – самые сильные.", female = "Ага! Вот они, Слёзы! Теперь племя Гелкис поймёт, что Терадрас не защитит их. Она не станет плакать, когда мы сокрушим их! Маграм будут править здесь! Ты хорошо сделала, выбрав нашу сторону. Мы – самые сильные." },
    ["1370a"] = { common = "Когда мы не воюем, то охотимся, чтобы добыть мяса. Мясо даёт нам силу. Сытый воюет лучше голодного. Сытый сильнее. Сытый победит. Племя Маграм поступает так же. Они запасают мясо, чтобы воевать дольше. Если нападёшь на их деревню на востоке и заберёшь их припасы, Маграм станут слабыми." },
    ["1370c"] = { male = "Хорошо. Я слышу, как урчит в брюхе у голодных Маграм! Слышу это даже здесь! Я отдам это мясо племени Гелкис. Мы будем воевать много дней без отдыха. То, что ты сделал, хорошо для племени Гелкис.", female = "Хорошо. Я слышу, как урчит в брюхе у голодных Маграм! Слышу это даже здесь! Я отдам это мясо племени Гелкис. Мы будем воевать много дней без отдыха. То, что ты сделала, хорошо для племени Гелкис." },
    ["1371a"] = { common = "Давным-давно один маленький гном пришёл в Пустоши со своей тележной, запряжённой лошадью и нагруженной множеством странных вещей. Занятных вещей. Некоторые горели разноцветным огнём. Некоторые двигались, не будучи при этом живыми. Я убил этого маленького гнома, но перед этим... он заставил меня посмеяться. Я оставил себе одну вещицу с его тележки – ту, которая понравилась мне больше всего. Это был деревянный человек, который махал на меня руками, пока я не ударил его, да так, что тот сломался. Я хочу нового деревянного человека! Доставай его, где хочешь, но принеси мне!" },
    ["1371c"] = { common = "Да! Именно такой человек у меня и был! Он снова будет двигаться. Снова будет веселить меня!" },
    ["1372a"] = { common = "По приказу Вариматраса нашу экспедицию направили на изучение нижнего Азерота. Отправившись на разведку, я заметил лазутчика, подобравшегося к Приюту Бродяги. Не успел я скрутить его, как некоторые наши орочьи... братья... захватили его и уволокли в Каменор, крепость на Болоте Печали. Я хочу... помочь... нашим братьям-оркам. Они не заметили наш лагерь, но я всё равно собираюсь оказать им услугу. Фаустин поможет тебе сделать... сыворотку правды для нашего друга в Каменоре." },
    ["1372c"] = { common = "Зредус как раз перед твоим приходом рассказал мне об этом любопытном маленьком лазутчике. Это и правда проблема. Нам вовсе не нужен нахал, вынюхивающий, что да как. Уверен, орки Каменора с интересом выслушают его. Поскольку они, хм, наши союзники, мы должны помочь им добыть информацию от этого человека. Помоги мне, – и мы доставим в Каменор сыворотку правды. За Орду! Э-э... я правильно выразился?" },
    ["1373a"] = { common = "Тебе ещё предстоит свершить многое. Война племён Гелкис и Маграм тебя не затронет: в это время ты будешь далеко отсюда. Земля раскрывает множество тайн тем, кто умеет слушать её; и одна из них – тайна красного кристалла, который называют дренейским аметистом. Это камень нездешнего происхождения; он из тех земель, где горы парят в небе, где правят демоны... Принеси мне осколок дренейского аметиста: о, с ним сила моей магии возрастёт во много раз!.. Осколок можно отыскать на Болоте Печали: его хранит один из Заблудших, Онгеку." },
    ["1373c"] = { common = "О да, это и есть тот осколок, о котором шептала мне земля... Я ощущаю его магическую силу – ту силу, которую я направлю против врагов племени Гелкис. Тебе удалось исполнить ещё одно наше задание. Возможно, со временем племя Гелкис сможет по праву считать тебя другом." },
    ["1374a"] = { common = "Земля говорит со мной. Земля знает, что племя Маграм утратил былую силу. Пришло время покончить с их вождём! Принеси мне голову Джехна, вождя племени Маграм!" },
    ["1374c"] = { common = "Вождь Джехн был силён, но глуп. Он полагал, что наделён великой силой, но забыл, что магия Земли могущественнее любого смертного. Лишившись вождя, племя Маграм впадёт в ничтожество, и племя Гелкис восторжествует!" },
    ["1375a"] = { common = "Ты помогаешь племени Маграм. Это хорошо. Ты мне нравишься. А теперь пойди и убей вождя племени Гелкис! Вождь Шак – мне нужна его голова! Я хочу видеть его голову, я буду смотреть на неё и смеяться!" },
    ["1375c"] = { common = "Вождь Шак мёртв! Я насажу его голову на пику, чтобы любоваться ею каждый день! Пусть мёртвые глаза Шака видят мощь племени Маграм!" },
    ["1380a"] = { male = "Ты помог нам справиться с племенем Маграм; теперь помоги нам одолеть племя Мародин! Убей их предводителя! Убей Храту! Чтобы вызвать его на бой, ты должен протрубить в боевой рог племени Мародин; а рог этот ты найдёшь, поднявшись на высокий утёс в Долине Копий. Только запомни: чтобы протрубить в рог, тебе нужно разыскать мундштук, а это нелегко, потому что найти такие мундштуки можно только у кентавров, пользующихся особым доверием племени... О чём это я? Ах, да: когда ты протрубишь в рог, кентавры явятся на бой, и тебе придётся убивать их, пока не доберёшься до самого Храты. А у вождя Храты есть фрагмент... некоего ключа. Принеси его мне...", female = "Ты помогла нам справиться с племенем Маграм; теперь помоги нам одолеть племя Мародин! Убей их предводителя! Убей Храту! Чтобы вызвать его на бой, ты должна протрубить в боевой рог племени Мародин; а рог этот ты найдёшь, поднявшись на высокий утёс в Долине Копий. Только запомни: чтобы протрубить в рог, тебе нужно разыскать мундштук, а это нелегко, потому что найти такие мундштуки можно только у кентавров, пользующихся особым доверием племени... О чём это я? Ах, да: когда ты протрубишь в рог, кентавры явятся на бой, и тебе придётся убивать их, пока не доберёшься до самого Храты. А у вождя Храты есть фрагмент... некоего ключа. Принеси его мне..." },
    ["1380c"] = { common = "Он мёртв! Вождь Храта мёртв! Теперь племя Мародин падёт! И когда этой землёй станет править племя Гелкис – клянусь, мы не забудем тебя. Духи земли будут вечно славить твоё имя!" },
    ["1381a"] = { male = "Вождь племени Гелкис мёртв; пришёл черёд племени Мародин! Убей их вождя, Храту! Его не так просто отыскать, нет... Чтобы вызвать его на бой, ты должен протрубить в боевой рог клана Мародин; а рог этот ты найдёшь, поднявшись на высокий утёс в Долине Копий. Только запомни: чтобы протрубить в рог, тебе нужно убить кентавра из племени Мародин и забрать у него мундштук.И вот когда ты протрубишь в рог, кентавры явятся на бой, и тебе придётся убивать их, пока не доберёшься до самого Храты. А у Храты есть фрагмент ключа. Он нужен мне, этот фрагмент. Принеси его. Принеси мне.", female = "Вождь племени Гелкис мёртв; пришёл черёд племени Мародин! Убей их вождя, Храту! Его не так просто отыскать, нет... Чтобы вызвать его на бой, ты должна протрубить в боевой рог клана Мародин; а рог этот ты найдёшь, поднявшись на высокий утёс в Долине Копий. Только запомни: чтобы протрубить в рог, тебе нужно убить кентавра из племени Мародин и забрать у него мундштук.И вот когда ты протрубишь в рог, кентавры явятся на бой, и тебе придётся убивать их, пока не доберёшься до самого Храты. А у Храты есть фрагмент ключа. Он нужен мне, этот фрагмент. Принеси его. Принеси мне." },
    ["1381c"] = { common = "Вождь Храта мёртв! Теперь Маграм – сильнейшее из племён! Мы сокрушим всех! Мы будем править в Пустошах! Мы не забудем тебя, и в тот час, когда сотни будут гибнуть под нашими копытами, мы пощадим тебя." },
    ["1382a"] = { common = "На наше счастье, племена кентавров постоянно враждуют. Если бы они объединились, никто не сумел бы их остановить. Да, нам сильно повезло – и мы должны обратить это везение себе на пользу. Племя Гелкис ведёт жестокую войну с племенем Маграм. Если мы атакуем поселение Маграм, то, возможно, сумеем заключить союз с племенем Гелкис. В юго-западной части Пустошей, неподалёку от лагерей племени Гелкис, ты сможешь найти Уту Мудрую. Возможно, поговорив с ней, ты сумеешь заключить союз..." },
    ["1382c"] = { common = "В племени Гелкис говорят о тебе. Твои руки в крови проклятых Маграм. Это хорошо. Я буду говорить с тобой. Скажи, что ты можешь сделать для племени Гелкис – и что племя может сделать для тебя." },
    ["1383a"] = { common = "Я знаю подходящую сыворотку. Она обойдётся с правдой именно так, как с ней следует обходиться. Чтобы сделать её, мне понадобится несколько сердец пантер Тени из болота. Кроме того, мне нужен мох хозяина болота, обитающего неподалёку. Не сомневаюсь, что ты сумеешь уговорить его поделиться с тобой. И последнее, что необходимо мне для составления сыворотки, это опухоль странника глубин из отдалённых Пустошей. Эти гиганты редко болеют, а опухоли у них появляются ещё реже. А теперь иди!" },
    ["1383c"] = { common = "Великолепно! И как раз вовремя. Судя по тому, что говорит Зредус, лазутчик оправился от ран и готов к допросу. Погоди, сейчас я приготовлю отра... то есть сыворотку правды." },
    ["1384a"] = { common = "Кентавры из племени Колкар полагают, что сильны в магии. Они ничего не понимают в магии! Они не распознают её, даже если их носом в магию ткнуть!.. Кто-то должен доказать им, что в отношении магии они просто дети неразумные. Думаю, этим кем-то будешь ты. Отправляйся в деревню Колкар, что на северо-восток отсюда. Отними у кентавров их обереги и принеси их мне. Я брошу их в огонь, и это согреет мне сердце." },
    ["1384c"] = { male = "Ты сделал доброе дело для племени Гелкис. Клан Колкар слаб, он обречён и сгинет. Их жалкая магия не поможет им. Ты показал им это – и страх сделает их ещё слабее! В этих землях слабаки долго не живут.", female = "Ты сделала доброе дело для племени Гелкис. Клан Колкар слаб, он обречён и сгинет. Их жалкая магия не поможет им. Ты показала им это – и страх сделает их ещё слабее! В этих землях слабаки долго не живут." },
    ["1385a"] = { common = "Пустоши – земля, пожираемая огнём войны. Кентавры враждуют между собой; мы страшимся того, что победившее племя пойдёт войной на наши крепости и разрушит их. Мы не можем этого допустить. Мы должны научиться побеждать кентавров, а для этого нам придётся заключить союз с одним из их племён. Племя Маграм издревле враждует с племенем Гелкис. Если ты начнёшь войну с племенем Гелкис, возможно, племя Маграм задумается о том, что неплохо бы иметь такого воина на своей стороне. Завоюй расположение племени Маграм, а затем отправляйся в деревню племени в юго-восточной части Пустошей и поговори с Варугом." },
    ["1385c"] = { common = "Многие из племени Гелкис пали от твоей руки. Мне это нравится. Может, ты сумеешь сделать что-то ещё, что мне понравится. Может, ты сумеешь стать другом племени Маграм." },
    ["1386a"] = { common = "Клан Колкар полагает, что он силён; мы смеёмся над ними – и убиваем их со смехом! Ты тоже их убиваешь. Покажи, что умеешь убивать их не хуже, чем мы. Клан Колкар должен умереть. Иди на север. Убей их. Убей их всех!" },
    ["1386c"] = { male = "Теперь клан Колкар страшится тебя. Скажи, ты смеялся, когда убивал их? Когда убиваешь, надо смеяться, тогда враги увидят, что они слабы.", female = "Теперь клан Колкар страшится тебя. Скажи, ты смеялась, когда убивала их? Когда убиваешь, надо смеяться, тогда враги увидят, что они слабы." },
    ["1387a"] = { common = "Раса кентавров состоит из множества кланов. У каждого из них – свой вождь и свои законы, но есть одна черта, которая объединяет их всех: жестокость. Если мы хотим обрести мир, нам следует изгнать кентавров из этих земель. Тебе предстоит исполнить это нелёгкое задание. В своих странствиях по Безлюдью ты будешь убивать кентавров и собирать их уши. Чем больше ушей, тем лучше. Принеси их мне. Если, ты исполнишь это во славу и во имя Альянса, мы будем на шаг ближе к завершению этой войны." },
    ["1387c"] = { common = "Ах, уши... Уши! Что ж, прекрасно. Бесспорно, услуги, оказанные тобой Альянсу, весьма велики. Поверь, та кровь, что была пролита тобой в Пустошах, поможет спасти множество жизней." },
    ["1388a"] = { common = "Всё прошло точно по плану. Теперь отнеси эту сыворотку правды стражу смерти Зредусу, и он покажет, как ею... Правильно воспользоваться. Ха-ха!" },
    ["1388c"] = { male = "Я знал, что старина Фаустин что-нибудь придумает! Ты ему очень помог, я даже не сомневаюсь. А теперь к делу, верно?", female = "Я знал, что старина Фаустин что-нибудь придумает! Ты ему очень помогла, я даже не сомневаюсь. А теперь к делу, верно?" },
    ["1389a"] = { common = "Заблудшие, живущие в Болотном пристанище, на вид ничем от нас не отличаются, но на самом деле это чудовища... лишившиеся рассудка в пути до Азерота. Когда-то они были нашими братьями. Теперь они живут в Болотном пристанище, к востоку отсюда, захватывая и убивая любого, кто попадётся под руку. Сейчас они украли одну из наших святынь – кристаллы дренейского аметиста. У нас не хватает сил ворваться в Святилище и вернуть себе нашу реликвию, но без неё... мы тоже вскоре утратим свой путь." },
    ["1389c"] = { common = "Благодарю тебя. Мы перед тобой в долгу." },
    ["1391a"] = { common = "Мы должны действовать тайно. В конце концов ты же не можешь войти и заставить этого олуха выпить состав Фаустина? Но от выпивки ни один человек не откажется. Я возьму сыворотку Фаустина и замешаю её в эль. Сомнений нет, бедняга без колебаний выпьет предложенную бурду. Спеши в Каменор на Болото Печали. И никому не рассказывай о нашем задании..." },
    ["1391c"] = { male = "Ты принёс мне попить? Как мило с твоей стороны. Мне не давали даже губы смочить вот уже несколько дней. Позволь мне утолить жажду, и я расскажу обо всём, что узнал...", female = "Ты принесла мне попить? Как мило с твоей стороны. Мне не давали даже губы смочить вот уже несколько дней. Позволь мне утолить жажду, и я расскажу обо всём, что узнал..." },
    ["1392a"] = { common = "Нобору много месяцев не давал житья дренеям Прибежища, и его дубина стала символом жестокости, которую они претерпели от рук Заблудших." },
    ["1392c"] = { male = "Ты добыл оружие ужасного Нобору? Так значит он мёртв? Это праздник для всего Убежища! Нобору и его банда, многие годы терроризировали нас, бродя по болотам и убивая любого дренея, который попадался на пути. Он ставил под угрозу само наше выживание, но нам не хватало сил, справиться с ним самостоятельно. Ты оказал нам большую услугу.", female = "Ты добыла оружие ужасного Нобору? Так значит он мёртв? Это праздник для всего Убежища! Нобору и его банда, многие годы терроризировали нас, бродя по болотам и убивая любого дренея, который попадался на пути. Он ставил под угрозу само наше выживание, но нам не хватало сил, справиться с ним самостоятельно. Ты оказала нам большую услугу." },
    ["1393a"] = { common = "Помогите! Эти твари хотят меня съесть! Если ты поможешь мне выбраться отсюда, то получишь великое сокровище! Оно лежит в моём лагере, в болотах к северу от Каменора, но только я знаю, как открыть сейф, в котором оно находится. Если ты поможешь мне, я научу тебя, как открыть этот сейф." },
    ["1393c"] = { common = "Замочная скважина этого сейфа залита чёрной смолой. Открыть его невозможно. Но Гален рассказал вам о секретном замке на днище сейфа... ... Быстро осмотрев сейф, вы находите задвижку. Задвижка отодвинута, и сейф открывается." },
    ["1394a"] = { male = "Ты хорошо справился. Ты прошёл все мои испытания и те, что были до этого. Возвращайся к Дорну в Тысячу Игл. Он непременно заметит перемены, произошедшие с твоим телом, разумом и духом, и поймёт, что твои усилия достойны награды. Всегда храни в себе ту гармонию, которой ты достиг в этих испытаниях, и тогда в будущем Дорн сможет испытать тебя ещё раз.", female = "Ты хорошо справилась. Ты прошла все мои испытания и те, что были до этого. Возвращайся к Дорну в Тысячу Игл. Он непременно заметит перемены, произошедшие с твоим телом, разумом и духом, и поймёт, что твои усилия достойны награды. Всегда храни в себе ту гармонию, которой ты достигла в этих испытаниях, и тогда в будущем Дорн сможет испытать тебя ещё раз." },
    ["1394c"] = { male = "А. Давненько ты не заглядывал в мой дом. Кажется, прошло уже много лун с тех пор, как ты сделал первый шаг на своём пути. А теперь ты вернулся намного сильнее, чем раньше... И намного мудрее. Это хорошо. И тебе полагается достойная награда за все испытания.", female = "А. Давненько ты не заглядывала в мой дом. Кажется, прошло уже много лун с тех пор, как ты сделала первый шаг на своём пути. А теперь ты вернулась намного сильнее, чем раньше... И намного мудрее. Это хорошо. И тебе полагается достойная награда за все испытания." },
    ["1395a"] = { common = "Этот ящик с камнями силы нужно доставить в Крепость Стражей Пустоты, в Выжженные земли. Их сила будет сохраняться не так-то долго, так что мы не можем отправить их следующим караваном. Тебе следует отнести их как можно скорее.. Отдай их интенданту Лунгерцу в Крепости Стражей Пустоты. Чтобы достичь крепости, тебе следует направиться на восток через Первал Мёртвого Ветра, затем далее через Болото Печали, потом свернуть на юг через Выжженные земли. Однако осторожнее. Твой путь проляжет через опасные земли, но цель должна быть достигнута." },
    ["1395c"] = { common = "О, камни силы! Маги будут рады увидеть их! Большое спасибо. Я знаю, что твой путь из Темнолесья был нелёгок." },
    ["1396a"] = { common = "Мой караван направлялся к восточному побережью, но до места так и не добрался. Заблудшие атаковали нас, перебив стражу и уничтожив припасы. Выжить удалось только мне. Я обещал сохранить оставшиеся товары, но вокруг полно чудовищ. Прошу тебя, помоги мне защитить мой лагерь!" },
    ["1396c"] = { common = "Судя по звукам, твари убрались. Благодарю тебя. Теперь-то, надеюсь, они не вернутся!" },
    ["1398a"] = { common = "Я – твой должник, В твоей груди бьётся великодушное сердце. А теперь – смею ли ещё раз попросить тебя о помощи? Чтобы добраться до Стражей Пустоты, я должен починить эту повозку, а для этого мне необходимо дерево. Сухое, прямое дерево, а те не рыхлые и скрюченные кусты, которые растут на болотах. Отправляйся на восточное побережье, поищи там плавник хорошо просущеный солнцем и принеси его мне." },
    ["1398c"] = { common = "Дерево лёгкое, но крепкое. Спасибо, это подойдёт." },
    ["1418a"] = { male = "Бесплодные земли суровы. Они примыкают к территории Альянса возле озера Лок Модан, потому сообщение между Каменором и форпостом Каргата часто оказывается перерезанным. путник, у тебя есть шанс проявить себя. Отправляйся в Бесплодные земли и поговори с Никой Алый Шрам, главой разведчиков Каргатского форпоста, а затем принеси мне её доклад.", female = "Бесплодные земли суровы. Они примыкают к территории Альянса возле озера Лок Модан, потому сообщение между Каменором и форпостом Каргата часто оказывается перерезанным. путница, у тебя есть шанс проявить себя. Отправляйся в Бесплодные земли и поговори с Никой Алый Шрам, главой разведчиков Каргатского форпоста, а затем принеси мне её доклад." },
    ["1418c"] = { common = "Хелгруму нужен доклад, а? Я посылала гонца в Каменор около трёх дней назад. Он что, не добрался? Если в Каменоре нет моего донесения, сдаётся мне, гонец сгинул. Будем надеяться, что следующий, кого я пошлю, будет лучше подготовлен, ну или более удачлив." },
    ["1419a"] = { male = "Ну и как тебе Бесплодные земли, герой? Жара, пылища, стаи всяких тварей? У тебя есть шанс прочувствовать все прелести этих земель ещё лучше. Скальные койоты – наглые твари. Наглые настолько, что пробираются в Каргат и воруют наши припасы. Помоги нам избавиться от них! Принеси мне их челюсти, если ты соберёшь достаточно много, я поверю, что ты и вправду знаешь Бесплодные земли.", female = "Ну и как тебе Бесплодные земли, героиня? Жара, пылища, стаи всяких тварей? У тебя есть шанс прочувствовать все прелести этих земель ещё лучше. Скальные койоты – наглые твари. Наглые настолько, что пробираются в Каргат и воруют наши припасы. Помоги нам избавиться от них! Принеси мне их челюсти, если ты соберёшь достаточно много, я поверю, что ты и вправду знаешь Бесплодные земли." },
    ["1419c"] = { common = "Впечатляющий набор челюстей. Теперь-то эти койоты поостерегутся подбираться к нашим припасам. Отлично! Койоты из Бесплодных земель – не такая уж лёгкая добыча. Теперь я уверена – ты сможешь тут выжить." },
    ["1420a"] = { common = "Я написала новое донесение для Хелгрума из Каменора, отнеси его ему. И если ты считаешь себя гонцом – не сбейся с пути и не попадись врагам!" },
    ["1420c"] = { common = "Благодарю тебя. Из донесения Ники я понял, что Альянс озабочен собственными проблемами, и, может статься, что кое-какие враги у нас общие." },
    ["1421a"] = { male = "Я был оглушён во время атаки Заблудших, но, прежде чем потерять сознание, я видел, как одну из наших повозок угоняли к Болотному пристанищу, поселению Заблудших на севере. В этой повозке находился сундук с наиболее ценными реактивами, предназначающимися для магов Крепости Стражей Пустоты. путник, найди сундук, добудь эти реактивы и верни их мне.", female = "Я был оглушён во время атаки Заблудших, но, прежде чем потерять сознание, я видел, как одну из наших повозок угоняли к Болотному пристанищу, поселению Заблудших на севере. В этой повозке находился сундук с наиболее ценными реактивами, предназначающимися для магов Крепости Стражей Пустоты. путница, найди сундук, добудь эти реактивы и верни их мне." },
    ["1421c"] = { common = "Браво! С этими реактивами волшебники Крепости Стражей Пустоты смогут продолжить работу. Я не знаю, чем они там занимаются, знаю только, что это связано с Тёмным порталом в Бесплодных землях и напрямую касается безопасности всего Альянса." },
    ["1422a"] = { common = "Пока я буду работть над твоим оружием, почему бы тебе не поговорить с Катором? Он, говорил, что ему нужна помощь с патрулированием побережья, и тебе бы лучше поддерживать боевую форму, а не напиваться с теми недоделками, что торчат в нашем лагере." },
    ["1422c"] = { male = "Помолчи немного, герой. Даже сквозь глухой рокот моря всё ещё слышно отвратительное бульканье, заменяющее рыболюдям речь.", female = "Помолчи немного, героиня. Даже сквозь глухой рокот моря всё ещё слышно отвратительное бульканье, заменяющее рыболюдям речь." },
    ["1423a"] = { common = "Этот бочонок мал, зато прочен. Его швы заплиты жёлтым пахучим воском, а на торце выдавлены слова: ИНТЕНДАНТ ЛУНГЕРЦ КРЕПОСТЬ СТРАЖЕЙ ПУСТОТЫ" },
    ["1423c"] = { common = "Благодарю тебя. На пути из Темнолесья теряется так много провизии, Как хорошо, что кое-что удаётся вернуть." },
    ["1424a"] = { common = "Вождь послал нас разузнать, что творится в Храме Атал'Хаккара. Тролли Атал'ай – племя тёмных заклинателей, известных тем, что используют запретную магию. Можешь себе представить, как мы были поражены, когда узнали что храм затоплен. Теперь его сторожат зелёные драконы, которые утверждают, что они защитники Азерота. Мы должны выяснить, что произошло. Исследуй окрестности озера Слёз и собери артефакты Атал'ай. С их помощью я смогу собрать всю картину воедино." },
    ["1424c"] = { male = "Твоё усердие в происках артефактов Аталаи достойно похвалы, герой.", female = "Твоё усердие в происках артефактов Аталаи достойно похвалы, героиня." },
    ["1425a"] = { common = "Пока я чиню эту повозку, выполни для меня ещё одно, последнее задание. Я собрал наиболее важные припасы, уцелевшие после набегов огров. Доставь их в Крепость Стражей Пустоты. Она выстроена в холмах, на севере Выжженных земель, для наблюдения за Тёмным порталом. Добраться туда можно по восточной дороге. Когда она разветвится, сверни на юг к Выжженным землям, а потом налево на следующей развилке. Не сходи с дороги, и не теряй бдительности" },
    ["1425c"] = { common = "Что? Груз из каравана Биггса? Мы думали, он пропал вместе с караваном. Спасибо. Надеюсь там кристаллы Азоры, этот реактив, нам крайне необходим, а наш запас подходит к концу." },
    ["1426a"] = { male = "Мне не нравится ни море, ни твари, что лезут из его глубин. Море могущественно, но слепо, бесчувственно и жестоко. С какой радостью я истреблял бы этих рыболюдей сотнями, будь у меня возможность. Но мне принесёт и некоторую радость зрелище их гибели от рук тех, кто выполняет волю Орды. От твоих рук, герой. Скольких ты сможешь убить? Хочешь ли рискнуть и сразиться с сильнейшими из них?", female = "Мне не нравится ни море, ни твари, что лезут из его глубин. Море могущественно, но слепо, бесчувственно и жестоко. С какой радостью я истреблял бы этих рыболюдей сотнями, будь у меня возможность. Но мне принесёт и некоторую радость зрелище их гибели от рук тех, кто выполняет волю Орды. От твоих рук, героиня. Скольких ты сможешь убить? Хочешь ли рискнуть и сразиться с сильнейшими из них?" },
    ["1426c"] = { male = "Море безбрежно и безжалостно, но ты запятнал его кровью его собственных порождений. Рыболюди знают, что такое боль. Их тупость заставит их сплотить ряды после того разгрома, который ты им учинил, и это хорошо. Пусть их булькающие крики заглушают шум моря по ночам. А я буду улыбаться каждый раз как услышу, что кто-то из них замолк. Возвращайся ко мне, если вдруг захочется поубивать ещё рыболюдей. Я с удовольствием тебя вознагражу за это.", female = "Море безбрежно и безжалостно, но ты запятнала его кровью его собственных порождений. Рыболюди знают, что такое боль. Их тупость заставит их сплотить ряды после того разгрома, который ты им учинила, и это хорошо. Пусть их булькающие крики заглушают шум моря по ночам. А я буду улыбаться каждый раз как услышу, что кто-то из них замолк. Возвращайся ко мне, если вдруг захочется поубивать ещё рыболюдей. Я с удовольствием тебя вознагражу за это." },
    ["1427a"] = { male = "Прежде чем пойти отдохнуть, пообщайся с Ток'Каром. Пока тебя не было, он, наверняка, закончил работу над обещанным тебе оружием. Было бы неплохо, если бы ты опробовал его на рыболюдях, когда созреешь...уж доставь мне удовольствие.", female = "Прежде чем пойти отдохнуть, пообщайся с Ток'Каром. Пока тебя не было, он, наверняка, закончил работу над обещанным тебе оружием. Было бы неплохо, если бы ты опробовала его на рыболюдях, когда созреешь...уж доставь мне удовольствие." },
    ["1427c"] = { male = "О! путник, ты вернулся! Хорошо. Я как раз закончил партию оружия против мурлоков. За свежее мясо кусак и за то, что заставил Катара улыбаться, выбери себе одно.", female = "О! путница, ты вернулась! Хорошо. Я как раз закончил партию оружия против мурлоков. За свежее мясо кусак и за то, что заставила Катара улыбаться, выбери себе одно." },
    ["1428a"] = { common = "Мне приятно видеть, что ненависть, которую ты испытываешь к рыболюдям, всё растёт, как и моя. Найди их на побережье, а потом когда битва будет закончена, возвращайся, и мы решим, как вознаградить тебя за усердие." },
    ["1428c"] = { male = "Отлично, герой. Но мне мало этой крови. Пусть все рыболюди исчезнут с лица земли.", female = "Отлично, героиня. Но мне мало этой крови. Пусть все рыболюди исчезнут с лица земли." },
    ["1429a"] = { male = "Пока ты сражался с опасностями озера Слёз, один из моих разведчиков вернулся со свитком из сушёного мяса с кровавыми письменами. Мне кажется это официальный приговор жрецу племени Атал'ай. Этот жрец был приговорён племенем к участи худшей, чем смерть, – он был изгнан на север во Внутренние земли, жить среди троллей племени Сухокожих. Я соберу эти артефакты, а тебе предстоит найти изгнанника и выяснить их назначение. После этого возвращайся ко мне.", female = "Пока ты сражалась с опасностями озера Слёз, один из моих разведчиков вернулся со свитком из сушёного мяса с кровавыми письменами. Мне кажется это официальный приговор жрецу племени Атал'ай. Этот жрец был приговорён племенем к участи худшей, чем смерть, – он был изгнан на север во Внутренние земли, жить среди троллей племени Сухокожих. Я соберу эти артефакты, а тебе предстоит найти изгнанника и выяснить их назначение. После этого возвращайся ко мне." },
    ["1429c"] = { male = "Ты принёс мне артефакты призыва Атал'ай? Я вижу, Джаммал'ан Пророк ведёт своих последователей из Чертога Крови навстречу выбранному ими року. Интересно, вернулся ли Хаккар в свой храм? Встретили ли они свою судьбу?", female = "Ты принесла мне артефакты призыва Атал'ай? Я вижу, Джаммал'ан Пророк ведёт своих последователей из Чертога Крови навстречу выбранному ими року. Интересно, вернулся ли Хаккар в свой храм? Встретили ли они свою судьбу?" },
    ["1430a"] = { common = "Среди моих покупателей крайне высок спрос на сочное крабье мясо, особенно мясо чудовищного краба. Если ты планируешь направиться на побережье, то можешь ещё и с выгодой прогуляться туда, если ты принесёшь мне несколько крабьих ног, чтобы я переправил их в Оргриммар. Побережье находится к востоку отсюда, а крабы там просто кишат, что на берегу, что под водой." },
    ["1430c"] = { common = "О! Замечательно, я жду не дождусь, когда попробую крабье мясо, должным образом приготовленное на открытом огне. Возьми с собой в дорогу малую толику, вкус просто несравненный!" },
    ["1431a"] = { male = "Слушай внимательно, герой. Мне нужно рассказать тебе кое-что, очень важное для нашего народа, но далеко не очевидное. Мы – народ гордый, и война с людьми истощила даже терпение Тралла. Наш вождь мудр и рассудителен, и интересы нашего народа для него превыше всего. В то же время он тонкий дипломат. Он умеет обращаться с людьми. Если тебе это интересно, поговори с Кельдраном. Его лачуга стоит у западного входа в город.", female = "Слушай внимательно, героиня. Мне нужно рассказать тебе кое-что, очень важное для нашего народа, но далеко не очевидное. Мы – народ гордый, и война с людьми истощила даже терпение Тралла. Наш вождь мудр и рассудителен, и интересы нашего народа для него превыше всего. В то же время он тонкий дипломат. Он умеет обращаться с людьми. Если тебе это интересно, поговори с Кельдраном. Его лачуга стоит у западного входа в город." },
    ["1431c"] = { male = "Патанни, герой! Меня зовут Кельдран, я изучаю магию... и другие тайные искусства. Дело, по поводу которого ты здесь, требует большей тонкости, чем те, которыми тебе приходилось заниматься раньше. Однако это не значит, что ты не можешь нам помочь. Пожалуйста, устраивайся поудобнее. Я расскажу тебе, зачем вождю понадобилась моя... и твоя помощь. Всё начинается со впечатления. Какой себя видит Орда. Какими видят нас наши союзники. И, главное, какими нас видят наши враги.", female = "Патанни, героиня! Меня зовут Кельдран, я изучаю магию... и другие тайные искусства. Дело, по поводу которого ты здесь, требует большей тонкости, чем те, которыми тебе приходилось заниматься раньше. Однако это не значит, что ты не можешь нам помочь. Пожалуйста, устраивайся поудобнее. Я расскажу тебе, зачем вождю понадобилась моя... и твоя помощь. Всё начинается со впечатления. Какой себя видит Орда. Какими видят нас наши союзники. И, главное, какими нас видят наши враги." },
    ["1432a"] = { common = "Альянс всё расширяет свои владения в Калимдоре. Из-за этого может сложиться впечатление, что Орда вступает в союз с Пылающим Легионом. Вождь не может этого допустить. И я, с его благословения, буду отвечать за их изгнание. У меня есть свои агенты в Пустошах, на Заставе Скитающихся Духов – это к северу от большого Кладбища кодо. Ступай на юг от Обугленной долины в Когтистых горах, и увидишь заставу. Когда прибудешь туда, разыщи Такату Стального Клинка." },
    ["1432c"] = { male = "Приветствую, герой! У тебя есть вести из Оргриммара? Это хорошо. В здешних краях всё провоняло демонами – сильнее, чем кентавровым навозом. Конелюди вопят, что это их земли, но тут есть силы, с которыми им никак не справиться. Получается, что мы вроде как помогаем кентаврам. Это мне не по нутру, но всё это на благо Орды, так что я выполняю свой долг перед вождём, даже если ради этого приходится поддерживать чернокнижников.", female = "Приветствую, героиня! У тебя есть вести из Оргриммара? Это хорошо. В здешних краях всё провоняло демонами – сильнее, чем кентавровым навозом. Конелюди вопят, что это их земли, но тут есть силы, с которыми им никак не справиться. Получается, что мы вроде как помогаем кентаврам. Это мне не по нутру, но всё это на благо Орды, так что я выполняю свой долг перед вождём, даже если ради этого приходится поддерживать чернокнижников." },
    ["1433a"] = { common = "Чернокнижники из клана Пылающего Клинка преданы злу до мозга костей. Души их осквернены, и единственный способ их остановить – это уничтожить. Кельдрин отправил со мной Майрина, потому что он знает многое об Огненном Клинке и разбирается в уловках чернокнижников. Он борется с Клинком, а на мою долю остаются прочие козни демонов тут, в Пустошах. Поговори с Майрином, он посвятит тебя в свои планы." },
    ["1433c"] = { male = "Ах, да! Нам всегда пригодится помощь тех, кто предан вождю. Меня зовут Майрин. Я здесь по просьбе Кельдрина и нашего юного вождя, Тралла. Мальчику нужна помощь в борьбе против врагов, угрожающих его власти. Подойди-ка поближе, герой. Я изложу тебе свои планы касательно ликвидации этого гнойного нарыва, Пылающего Клинка.", female = "Ах, да! Нам всегда пригодится помощь тех, кто предан вождю. Меня зовут Майрин. Я здесь по просьбе Кельдрина и нашего юного вождя, Тралла. Мальчику нужна помощь в борьбе против врагов, угрожающих его власти. Подойди-ка поближе, героиня. Я изложу тебе свои планы касательно ликвидации этого гнойного нарыва, Пылающего Клинка." },
    ["1434a"] = { common = "Влияние демонов возникает не на пустом месте. Нужен какой-то изъян, который позволяет злу войти в тебя. Может быть, слабость духа, или излишнее стремление к власти, или жажда мести... Когда мы поддаёмся боли, то позволяем злу взять над нами верх – такому злу, как сатиры. Они связаны с Пылающим Клинком, и Тралл хочет, чтобы их перебили. Разыщи их на северо-востоке и возвращайся ко мне, когда сумеешь их изгнать." },
    ["1434c"] = { male = "Молодец, герой! В тебе есть доблесть и преданность делу. Когда мы покончим с нашими делами в Пустошах, вождь непременно узнает о том, что ты помогал нам выполнять его волю. Благодарю тебя!", female = "Молодец, героиня! В тебе есть доблесть и преданность делу. Когда мы покончим с нашими делами в Пустошах, вождь непременно узнает о том, что ты помогала нам выполнять его волю. Благодарю тебя!" },
    ["1435a"] = { common = "Этих жалких тварей лучше всего предать смерти. Но, когда имеешь дело с теми, кто присягнул тьме, недостаточно просто убивать. Возьми этот самоцвет. Приведи его в действие, когда один из негодяев из клана Пылающего Клинка будет близок к смерти. Заклятие вытянет осквернённый дух из жертвы, и у тебя в руках окажется одушевлённый самоцвет. Принеси мне эти одушевлённые самоцветы, я с ними разберусь. Ступай же, и постарайся избегнуть смерти!" },
    ["1435c"] = { male = "А, ты вернулся с победой! Это хорошо. Давай сюда самоцветы, я их спрячу в надёжное место… У меня больше нет для тебя поручений, герой. Отдохнёшь – поговори с Такатой. Возможно, у него найдётся для тебя дело – а может, он попросит тебя вернуться в Оргриммар и сообщить Кельдрану, как идут дела у нас в Пустошах.", female = "А, ты вернулась с победой! Это хорошо. Давай сюда самоцветы, я их спрячу в надёжное место… У меня больше нет для тебя поручений, героиня. Отдохнёшь – поговори с Такатой. Возможно, у него найдётся для тебя дело – а может, он попросит тебя вернуться в Оргриммар и сообщить Кельдрану, как идут дела у нас в Пустошах." },
    ["1436a"] = { common = "Дела идут на лад. Быть может, если мы продолжим одерживать победы над демонами и их приспешниками, вождь разрешит нам вернуться домой ещё до начала следующего сезона. Возвращайся к Кельдрану и расскажи, чего нам удалось добиться. Уверен, он вознаградит тебя за труды. Он будет горд, узнав, что вождь ценит его усилия." },
    ["1436c"] = { male = "Тебе удалось добиться успеха, да ещё какого! Спасибо тебе. Благодарю тебя за труды, за потраченное время и за то, что ты с пониманием отнёсся к моей просьбе. Тралл стремится к миру между Ордой и Альянсом и потому заботится, чтобы мы выглядели достойно в глазах противника. Не следует провоцировать новые конфликты. Я твой должник!", female = "Тебе удалось добиться успеха, да ещё какого! Спасибо тебе. Благодарю тебя за труды, за потраченное время и за то, что ты с пониманием отнеслась к моей просьбе. Тралл стремится к миру между Ордой и Альянсом и потому заботится, чтобы мы выглядели достойно в глазах противника. Не следует провоцировать новые конфликты. Я твой должник!" },
    ["1437a"] = { common = "Приветствую тебя. Я – Валарриэль. Я прибыл сюда, чтобы установить местопребывание двух пропавших торговцев из почтенной дарнасской семьи – дома Малем. Глава дома опасается самого худшего; я обязан выяснить всё, что могу, о его пропавших детях. Правда, поиски Тираниса и Далинды я ещё не начал, но надеюсь, что не задержусь здесь надолго. Последнее, что мне довелось слышать о них – то, что несколько недель назад они миновали Когтистые горы. Если найдёшь их повозку, прошу тебя, немедленно дай мне знать." },
    ["1437c"] = { common = "Судя по виду повозки, она подверглась воздействию как грубой силы, так и чар. Похоже, битва была короткой, и у одной из сторон не было никаких шансов – не было даже возможности отразить удар. Ни трупов, ни следов крови нигде не видно. Кто бы ни напал на торговцев, действовал он весьма умело..." },
    ["1438a"] = { male = "Постарайся разыскать Далинду и Тираниса. Начни поиски с той самой крепости, о которой ты говорил, а я пока что свяжусь с Дарнассом и изложу ситуацию. Что бы ты ни обнаружил, немедленно дай мне знать. Я хотел ещё кое-что сказать тебе. Дело в том, что моё начальство весьма обеспокоено действиями Тираниса и причинами, которые заставили его отправиться сюда. Чрезвычайно важно найти Далинду и доставить её домой. Целой и невредимой, по возможности. А вот Тираниса следовало бы сначала... проверить.", female = "Постарайся разыскать Далинду и Тираниса. Начни поиски с той самой крепости, о которой ты говорила, а я пока что свяжусь с Дарнассом и изложу ситуацию. Что бы ты ни обнаружила, немедленно дай мне знать. Я хотел ещё кое-что сказать тебе. Дело в том, что моё начальство весьма обеспокоено действиями Тираниса и причинами, которые заставили его отправиться сюда. Чрезвычайно важно найти Далинду и доставить её домой. Целой и невредимой, по возможности. А вот Тираниса следовало бы сначала... проверить." },
    ["1438c"] = { male = "Благодарение Элуне, хоть кто-то пришёл на помощь! Прошу тебя, герой, помоги мне. Орки Пылающего Клинка схватили меня и моего брата Тираниса и притащили сюда. Мне кажется, они собираются принести меня в жертву своим хозяевам-демонам!.. Я знала, что наше путешествие в Пустоши – это ошибка, но Тиранис так настаивал... в последнее время он особенно увлёкся потаёнными знаниями, хотя многим это не нравилось. Он решил отправиться в эти края именно после того, как узнал, что здесь появляются демоны... Боюсь, с ним случилось что-то скверное... очень скверное!", female = "Благодарение Элуне, хоть кто-то пришёл на помощь! Прошу тебя, героиня, помоги мне. Орки Пылающего Клинка схватили меня и моего брата Тираниса и притащили сюда. Мне кажется, они собираются принести меня в жертву своим хозяевам-демонам!.. Я знала, что наше путешествие в Пустоши – это ошибка, но Тиранис так настаивал... в последнее время он особенно увлёкся потаёнными знаниями, хотя многим это не нравилось. Он решил отправиться в эти края именно после того, как узнал, что здесь появляются демоны... Боюсь, с ним случилось что-то скверное... очень скверное!" },
    ["1439a"] = { common = "Орки перебили нашу охрану и слуг, а потом приволокли нас сюда. Ты представить себе не можешь, что с ними сделали! Я думала, нас тоже прикончат на месте – но, как выяснилось, у орков были на нас другие планы. Тиранис пытался поговорить с ними. Наверное, он думал, что его знания тайных искусств произведут на орков впечатление. Не знаю уж, почему. Прошу тебя, помоги! Я не могу уйти, пока не узнаю, что случилось с моим братом. Найди его – или хотя бы узнай о его судьбе. Умоляю!.." },
    ["1439c"] = { male = "Это ужасно!.. Но, полагаю, у тебя не было другого выхода. Если бы не ты, его всё равно убили бы... Наверное, я должна поблагодарить тебя. Прости, если это звучит не слишком искренне: думаю, ты понимаешь, почему. Теперь, когда я знаю, какая судьба постигла моего несчастного брата, думаю, пора бежать отсюда. Если ты ещё не передумал, я с радостью воспользуюсь твоей помощью и покину это страшное место. Когда будешь готов, скажи мне: мы тут же отправимся в путь.", female = "Это ужасно!.. Но, полагаю, у тебя не было другого выхода. Если бы не ты, его всё равно убили бы... Наверное, я должна поблагодарить тебя. Прости, если это звучит не слишком искренне: думаю, ты понимаешь, почему. Теперь, когда я знаю, какая судьба постигла моего несчастного брата, думаю, пора бежать отсюда. Если ты ещё не передумала, я с радостью воспользуюсь твоей помощью и покину это страшное место. Когда будешь готова, скажи мне: мы тут же отправимся в путь." },
    ["1440a"] = { male = "Итак, время пришло?.. Ценю твои усилия и благодарю тебя за всё, что ты сделал для меня и моей семьи. Что ж, если ты готов, то и мне тут больше нечего делать. Отправимся в путь по первому твоему слову.", female = "Итак, время пришло?.. Ценю твои усилия и благодарю тебя за всё, что ты сдалала для меня и моей семьи. Что ж, если ты готова, то и мне тут больше нечего делать. Отправимся в путь по первому твоему слову." },
    ["1440c"] = { common = "Благодарю тебя. Далинда благополучно добралась до Высоты Найджела и чувствует себя гораздо лучше, чем я смел надеяться. Я даже не надеялся на столь благополучный исход! То, что ей удалось добраться сюда своими силами – добрый знак. Надеюсь, с тобой тоже всё в порядке?.. Мне жаль, что Тиранис не вернулся; однако всё, что с ним произошло, было плодом его собственных решений. Далинде придётся с этим смириться – и, к тому же, разбираться с последствиями его действий, когда она вернётся в Дарнас." },
    ["1442a"] = { male = "День добрый. Чем могу помочь идущему путём Света? Ах да, кузнец Стилвелл... давно не виделись. Я хорошо его помню, хотя давно о нём не слышал. Он никогда не казался мне злодеем, поэтому остаётся думать, что его стремление получить самоцвет Кора благородно. Если вам и правда нужен самоцвет, то придётся направиться на северо-запад Ясеневого леса. Там, среди древних развалин, вы обнаружите Непроглядную Пучину. В их недрах таятся наги, и они до сих пор используют такие самоцветы. Не ходите туда в одиночку, герой.", female = "День добрый. Чем могу помочь идущей путём Света? Ах да, кузнец Стилвелл... давно не виделись. Я хорошо его помню, хотя давно о нём не слышал. Он никогда не казался мне злодеем, поэтому остаётся думать, что его стремление получить самоцвет Кора благородно. Если вам и правда нужен самоцвет, то придётся направиться на северо-запад Ясеневого леса. Там, среди древних развалин, вы обнаружите Непроглядную Пучину. В их недрах таятся наги, и они до сих пор используют такие самоцветы. Не ходите туда в одиночку, героиня." },
    ["1442c"] = { male = "Действительно, это тот самый камень, который хочет получить Стилвелл, но, прежде чем я отдам его вам, надо очистить камень от скверны – мерзкие наги наполняют самоцветы силой, но своей, злобной силой. Пусть Стилвелл знает, что мощь камня чиста, и он хорошо послужит в любом ритуале. Я надеюсь, вы понимаете, что делаете, герой, ибо в руках у вас не игрушка.", female = "Действительно, это тот самый камень, который хочет получить Стилвелл, но, прежде чем я отдам его вам, надо очистить камень от скверны – мерзкие наги наполняют самоцветы силой, но своей, злобной силой. Пусть Стилвелл знает, что мощь камня чиста, и он хорошо послужит в любом ритуале. Я надеюсь, вы понимаете, что делаете, героиня, ибо в руках у вас не игрушка." },
    ["1444a"] = { common = "Джаммал'ан Пророк приговорил меня к изгнанию из Храма Атал'Хаккара. Некогда я считал верховного жреца достойным главой храма. Его непоколебимая вера в своё пророчество может привести к гибели Атал'ай, если уже не привела. Но стоило мне высказать мои сомнения, я был заклеймён как еретик и изгнан из храма. Принесённые тобой артефакты безопасны... Но если Джаммал'ан нашёл нужный для ритуала призыва фетиш, то всему миру угрожает смертельная опасность." },
    ["1444c"] = { male = "Мы же виделись совсем недавно, герой. Надеюсь, твоё путешествие было удачным. Что тебе поведал изгнанник-Атал'ай во внутренних землях?", female = "Мы же виделись совсем недавно, героиня. Надеюсь, твоё путешествие было удачным. Что тебе поведал изгнанник-Атал'ай во внутренних землях?" },
    ["1445a"] = { common = "Так он говорил о пророчестве Джаммал'ана? Духовный вождь Атал'ай верит, что когда однажды, Хаккар вернётся в Азерот из Пустоты, он дарует племени бессмертие. По мне дураком надо быть, чтобы раньше срока вызывать светопреставление. Но ты говоришь, этот изгой упоминал о зачарованных амулетах? А вот это уже напрямую меня касается. Если среди них окажется ключ к ритуалу Атал'ай, который и привёл ко всей этой заварухе, мы должны понять его тайную силу. Отправляйся в Храм и добудь амулеты!" },
    ["1445c"] = { male = "Отважный герой, ты доказал, что являешься одним из лучших воинов Орды. Теперь-то мы разберёмся с этими амулетами!", female = "Отважная героиня, ты доказала, что являешься одним из лучших воинов Орды. Теперь-то мы разберёмся с этими амулетами!" },
    ["1446a"] = { common = "Мои товарищи из клана Сухокожих не любят, когда чужаки приходят к ним домой. Я? А у меня и дома-то нет. Я жил в племени Атал'ай на Болоте Печали, но был изгнан оттуда. У нашего духовного лидера по имени Джаммал'ан, было, как он сам говорил, \"видение\". Он решил, что если призвать бога Хаккара, то он дарует Атал'ай бессмертие. Я настоятельно рекомендовал ему проявить осторожность, потому что это \"видение\" могло быть всего лишь манипуляцией, обманом! Я хочу отомстить за своё изгнание. Принесите мне голову Джаммал'ана. Может быть, тогда мой народ освободится!" },
    ["1446c"] = { common = "Джаммал'ан безоговорочно верил своим бредовым видениям, и именно из-за них мой народ постигла такая страшная судьба. Спасибо, путник, что отомстил за моё изгнание. Я глубоко скорблю по своему народу. У меня нет дома, в который я мог бы вернуться." },
    ["1447a"] = { male = "В Штормград приходили многие твои коллеги, герой, были среди них умные, были и круглые дураки, но подобных тебе нет, не было и не надо... Чего ты от меня хочешь?", female = "В Штормград приходили многие твои коллеги, героиня, были среди них умные, были и круглые дураки, но подобных тебе нет, не было и не надо... Чего ты от меня хочешь?" },
    ["1447c"] = { common = "У тебя явно была причина прийти ко мне. Так в чём дело?" },
    ["1448a"] = { male = "Когда-то я был так же молод и полон сил, как вы, герой. Теперь я стар и не могу больше странствовать по миру. О, сколько я всего повидал! Но была одна загадка, которая до сих пор волнует меня. Во время моего последнего путешествия Лига Исследователей направила меня на поиски Храма Атал'Хаккара. Говорили, что он расположен где-то на Болоте Печали. Поскольку я уже был стар и немощен, то облетел эти земли на грифоне, но ничего не нашёл. Не поможете ли старому дворфу? Может быть, вам повезёт больше?", female = "Когда-то я был так же молод и полон сил, как вы, героиня. Теперь я стар и не могу больше странствовать по миру. О, сколько я всего повидал! Но была одна загадка, которая до сих пор волнует меня. Во время моего последнего путешествия Лига Исследователей направила меня на поиски Храма Атал'Хаккара. Говорили, что он расположен где-то на Болоте Печали. Поскольку я уже был стар и немощен, то облетел эти земли на грифоне, но ничего не нашёл. Не поможете ли старому дворфу? Может быть, вам повезёт больше?" },
    ["1448c"] = { male = "Храм Атал'Хаккара скрыт в глубинах озера Слёз? И охраняется зелёными драконами? Это чудесное открытие, герой! Очевидно, что-то ужасное случилось с этим храмом...", female = "Храм Атал'Хаккара скрыт в глубинах озера Слёз? И охраняется зелёными драконами? Это чудесное открытие, героиня! Очевидно, что-то ужасное случилось с этим храмом..." },
    ["1449a"] = { common = "Как я уже говорил, я пытался обнаружить храм, осматривая окрестности с высоты. Строго говоря, я был не один... Я нанял грифона в небезызвестном питомнике на Заоблачном Пике во Внутренних землях. Птицей управлял один из лучших пилотов, но в воздухе он выпал из седла и свалился в болото... Моя старая дырявая память не сохранила его имени, но хозяин питомника должен понять, о ком идёт речь. Отправляйтесь туда и найдите Фалстада Громового Молота. Хорошо бы узнать, что случилось с тем пилотом..." },
    ["1449c"] = { male = "Чего тебе, парень? Не видишь – и без тебя забот хватает? Чем болтаться тут без толку, лучше займись делом, герой. Что-что случилось... Тролли лезут из всех щелей, вот что! Ну говори уже, с чем пришёл.", female = "Чего тебе, девушка? Не видишь – и без тебя забот хватает? Чем болтаться тут без толку, лучше займись делом, героиня. Что-что случилось... Тролли лезут из всех щелей, вот что! Ну говори уже, с чем пришла." },
    ["1450a"] = { male = "Так, значит, ты тот парень, которого наняли эти старые развалины из Лиги Исследователей? Так, слушай меня, герой. Я понятия не имею, кто у них там развлекался, летая над Азеротом! Я что, похож на Разящего Когтя? Похож? Если тебя интересуют грифоны, так поговори с укротителем! Если я увижу тебя без дела, то завалю по уши настоящей работой. Давай-давай, топай отсюда.", female = "Так, значит, ты та девчонка, которую наняли эти старые развалины из Лиги Исследователей? Так, слушай меня, героиня. Я понятия не имею, кто у них там развлекался, летая над Азеротом! Я что, похож на Разящего Когтя? Похож? Если тебя интересуют грифоны, так поговори с укротителем! Если я увижу тебя без дела, то завалю по уши настоящей работой. Давай-давай, топай отсюда." },
    ["1450c"] = { common = "Да, конечно, я прекрасно помню о том, как послал одного из пилотов отвезти Брохана Бочкопуза. Лиге Исследователей всегда найдётся место в моём сердце. Мой отец участвовал в экспедиции первой исследовательской команды, обнаружившей Ульдаман. С Броханом я отправил своего лучшего пилота по имени Рапсод Землекоп. Ах, что за наездник это был! Ну, до поры..." },
    ["1451a"] = { common = "Рапсод всегда любил поддать лишнего. Не поймите меня неправильно: мы, дворфы этого питомника, все любим порой принять на грудь пинту-другую доброго эля. Но старина Землекоп любил это дело больше, чем грифоны любят летать – порой ужас что получалось. Никто не умел летать так, как Рапсод... Авария с этим вашим приятелем Броханом была только первым звоночком. После этого Землекоп покатился под горку, пришлось его уволить. Говорят, он открыл пивнушку к югу отсюда..." },
    ["1451c"] = { common = "И-ик! Я ж прям на вас смотрю, чего это вас так мотыляет из стороны в сторону? У меня аж морская болезнь начинается, ха-ха! И-ик! О! Чувствуете, дорогуша? Земля так и ходит ходуном. Надо выпить! Ик-к!" },
    ["1452a"] = { common = "Ик! Вас послал этот старый пень Брохан? Как вспомню ту историю, так... И-ик! Чтобы рассказать, что там со мной случилось над этим болотом, понадобится выпить капельку для храбрости. Полный ужас, вы не поверите! Ик! Вот что я скажу – притащите-ка мне индри... гринди... эн-гре-де-ен-ты для калимдорского коктейля, и вы обо всём услышите! Значится, что нужно мне... Потроха руха из Танариса, печень гроддока, печень железномеха из Фераласа... Да. Калимдорский коктейль развяжет мне язык!" },
    ["1452c"] = { common = "Как я погляжу, у вас этих потрошков полные карманы! И какая беда принесла вас из Калимдора-то? Сейчас подождите, я сделаю вытяжку, и тогда уж расскажу всё, что вы пожелаете. Ик! Меня дрожь пробирает, когда вспоминаю это клятое болото. Ик! Сейчас, сейчас, почти готово дело..." },
    ["1453a"] = { common = "Надо сделать одну работу в Пустошах. Это жуткое место, опоганенное кентаврами и прочими грязными тварями. Но если ты ищешь честную работёнку на неделю, то отправляйся туда, найди Крелдига Унгора и скажи, что это я тебя прислал. Ты найдёшь его на Высоте Найджела – он прячется в укромном лагере в горах северных Пустошей. Держись к востоку от выхода из Когтистых гор. Будь начеку, иначе можешь проскочить мимо лагеря." },
    ["1453c"] = { male = "Рад видеть, что у Горной корпорации нет недостатка ни в работе, ни в искателях приключений, готовых прийти на помощь. Я – Крелдиг. Это хорошо, что ты взялся помочь Горной корпорации. В эти дни все что-то ищут – кто фамильные драгоценности потерял, кто магический предмет, кто любимых. Да мало ли что. Но если за дело берётся Горная корпорация, то по сходной цене она найдёт всё что угодно.", female = "Рад видеть, что у Горной корпорации нет недостатка ни в работе, ни в искателях приключений, готовых прийти на помощь. Я – Крелдиг. Это хорошо, что ты взялась помочь Горной корпорации. В эти дни все что-то ищут – кто фамильные драгоценности потерял, кто магический предмет, кто любимых. Да мало ли что. Но если за дело берётся Горная корпорация, то по сходной цене она найдёт всё что угодно." },
    ["1454a"] = { common = "Моё первое задание касается мага Карнитола – это какой-то тип из благородных, живёт в Штормграде. Говорит, на его корабль напали морские великаны, и было это всё у северо-западного берега Пустошей. Вместе со слугами этот тип попытался вытащить на берег один из самых ценных сундуков, но когда великаны набросились на них толпой, почёл за благо телепортировать себя и своих слуг куда подальше, а сундук, натурально, бросил. Так вот, Карнитол хочет, чтобы мы нашли его сундук со всем содержимым и доставили ему в Штормград." },
    ["1454c"] = { common = "Похоже, сундук вовсе не пострадал от морской воды... Однако он взломан. Если тут и были магические охранные ловушки, то они явно успели сработать: края сундука обожжены." },
    ["1455a"] = { common = "Любопытно, кто – или что – всё же открыло этот сундук?.. Судя по длинным глубоким царапинам на боках и крышке, это был не человек и не великан... Непохоже также, чтобы отметины оставил меч или кинжал. Кроме всего прочего, сундук пуст. Абсолютно и непоправимо пуст. Делать нечего: остаётся только закрыть сундук и уйти. Крелдиг будет крайне разочарован." },
    ["1455c"] = { male = "Ну-с, с возвращением на Высоту Найджела. Расскажи-ка, что тебе удалось обнаружить... Как?! Ничего?.. Ну, дорогуша, из ничего и не выйдет ничего: боюсь, за пустой сундук никто платить не станет. Расскажи-ка мне побольше об этих самых отметинах... царапинах, которые ты заметил.", female = "Ну-с, с возвращением на Высоту Найджела. Расскажи-ка, что тебе удалось обнаружить... Как?! Ничего?.. Ну, дорогуша, из ничего и не выйдет ничего: боюсь, за пустой сундук никто платить не станет. Расскажи-ка мне побольше об этих самых отметинах... царапинах, которые ты заметила." },
    ["1456a"] = { common = "Любопытно, очень любопытно... Что ж, может, для нас ещё не всё потеряно. Если идти по тому же берегу на север, в сторону острова Раназьяр, там будут развалины построек ночных эльфов. Понятное дело, развалины эти теперь под водой; к тому же, там поселились наги из клана Скользящего Плавника. Сдаётся мне, эти наги замешаны в истории с сундуком. Если разведчики нагов решились зайти так далеко на юг, значит, по всей видимости, они очень сильны. Так что пожитки Карнитола, как мне кажется, надо поискать у сильнейших среди нагов: приливных охотников или морских ведьм." },
    ["1456c"] = { male = "Просто роскошно! Тебе удалось найти пожитки Карнитола! От этих проклятущих нагов вечно одни проблемы. Я бы предпочёл с Ордой воевать, чем с ними связываться, честно тебе говорю. Поверь, ты оказал Горной корпорации огромную услугу!", female = "Просто роскошно! Тебе удалось найти пожитки Карнитола! От этих проклятущих нагов вечно одни проблемы. Я бы предпочёл с Ордой воевать, чем с ними связываться, честно тебе говорю. Поверь, ты оказала Горной корпорации огромную услугу!" },
    ["1457a"] = { common = "Послушай, доставь-ка вещички Карнитола Ройттену в Стальгорн: он тебе неплохо заплатит. Только ты с ним поосторожнее, не то ты ему понравишься сверх всякой меры и он решит тебя взять к нам, как это называется, на полную ставку! Нет, я ничего не говорю; ты молодчина! Только будь поосторожнее на обратном пути и поторапливайся: Карнитол – не самый терпеливый тип... зато платит от души!" },
    ["1457c"] = { male = "Ах да, Карнитол... Точно, было у него такое дело в Пустошах. Великолепно! Итак, сундук уничтожен, но всё его содержимое тут, да? Что ж, поверим ему на слово, поверим... Тут какое дело? Если ко мне возникнут какие-то претензии, я всегда могу послать жалобщиков куда подальше. Они же от нас чего хотят? – правильно, чтобы мы нашли их вещи. Мы и находим, а уж сохранность и внешний вид находок – это второй вопрос. Прекрасная работа! Давай-ка посмотрим, что ты на этом заработал...", female = "Ах да, Карнитол... Точно, было у него такое дело в Пустошах. Великолепно! Итак, сундук уничтожен, но всё его содержимое тут, да? Что ж, поверим ему на слово, поверим... Тут какое дело? Если ко мне возникнут какие-то претензии, я всегда могу послать жалобщиков куда подальше. Они же от нас чего хотят? – правильно, чтобы мы нашли их вещи. Мы и находим, а уж сохранность и внешний вид находок – это второй вопрос. Прекрасная работа! Давай-ка посмотрим, что ты на этом заработала..." },
    ["1458a"] = { common = "Одна из моих задач здесь – подбор реактивов для Скрытного Кудесника, гномского мага из Караноса. Ройттен-то, небось, думает, что это – раз плюнуть, коли уж мы всё равно тут торчим, а дело-то не из простых, да и рук не хватает... Первые несколько реактивов добыть не так уж сложно, а я готов заплатить неплохие деньги тому, кто мне поможет. Мне нужны рога и когти сатиров Ярой Ненависти: они тут недалеко обитают, на востоке. Ты мне их сначала принеси, а потом мы займёмся остальным списком." },
    ["1458c"] = { common = "Отлично, отлично! Не то чтобы я был уверен в качестве этой дряни, но ежели этому Скрытному типу нужны были какие-то особые рога и когти, надо было мне об этом раньше сказать, а теперь уж пусть забирает, что дают, я так себе думаю. Ну что, посмотрим, что там дальше по списку?" },
    ["1459a"] = { common = "А следующее по списку Скрытного Кудесника у нас... Погоди-ка... А, да, вот оно. Ну, не то чтобы это было большой редкостью, но тут наш дорогой друг сподобился дать подобные разъяснения. Ему понадобился яд скорпиона и шкура кодо. А вот тут вот, меленькими буковками, видишь? – тут написано, что яд-то может быть от любого скорпиона, а шкура ему нужна непременно со старого кодо, но ни в коем случае не с умирающего или дряхлого. Ох уж эти мне маги... вечно у них какие-то заскоки." },
    ["1459c"] = { common = "Твоя помощь просто неоценима. Благодаря тебе я проведу в этих проклятущих Пустошах вдвое меньше времени. Ещё немного, и можно будет отправиться в Стальгорн: отдых мне не помешает... Когда мы покончим с этим списком и я вернусь домой, непременно загляни ко мне: я тебе поставлю пару пинт доброго эля! А пока-что давай займёмся остальными реактивами, договорились?" },
    ["1465a"] = { common = "При осмотре повозки удаётся найти подвеску, а также следы, ведущие на юг – туда, где над фортом поднимается лёгкий дымок, заставляющий думать не о пожаре и горящих домах, а об очаге или костре, на котором готовится пища. Должно быть, если Малемы ещё живы, их увели в том направлении. Валарриэль непременно должен увидеть подвеску – и об этих признаах жизни на юге ему тоже нужно рассказать..." },
    ["1465c"] = { male = "Я в ярости! Подумать только, какой провал!.. И ведь этих двоих предупреждали, что здесь крайне опасно. А теперь они оба пропали... И хорошо, если живы. Говоришь, ты видел следы, ведущие к ближнему форту?.. Что ж, возможно, у нас всё ещё есть шанс... Местные жители говорят, что в этой крепости обосновались орки Пылающего Клинка – те, что служат демонам. Я вовсе не хочу сказать, что вся Орда придерживается подобных верований – но это сейчас неважно, а важно то, что эти орки непременно убьют тебя, если увидят, что ты пытаешься что-то разведать неподалёку от их форта.", female = "Я в ярости! Подумать только, какой провал!.. И ведь этих двоих предупреждали, что здесь крайне опасно. А теперь они оба пропали... И хорошо, если живы. Говоришь, ты видела следы, ведущие к ближнему форту?.. Что ж, возможно, у нас всё ещё есть шанс... Местные жители говорят, что в этой крепости обосновались орки Пылающего Клинка – те, что служат демонам. Я вовсе не хочу сказать, что вся Орда придерживается подобных верований – но это сейчас неважно, а важно то, что эти орки непременно убьют тебя, если увидят, что ты пытаешься что-то разведать неподалёку от их форта." },
    ["1466a"] = { common = "Это последнее в списке. Врать не буду, задание не из приятных; к тому же оно наверняка займёт у тебя больше времени, чем предыдущие. Ну ладно, хватит болтать. Вот гляди: Скрытный Кудесник тут пишет, что ему нужны мозги любых пожирателей маны или охотников на магов... крылья Пустоты ему ещё нужны, от любой Девы, Сестры или Колдуньи Пустоты... и ещё... кровь Тюремщика Судеб ему ещё нужна, от лорда или капитана – не важно. Простенькое такое заданьице, точно? Слушай, я тебе вот что скажу: если ты откажешься, я пойму." },
    ["1466c"] = { male = "Честно говоря, не думал, что тебе это удастся. Ты – это что-то! Надо же, и демонов покромсал для чокнутого мага, и живым вернулся! Вот это класс! Как вернусь в Стальгорн, лично расскажу о тебе старине Ройттену!", female = "Честно говоря, не думал, что тебе это удастся. Ты – это что-то! Надо же, и демонов покромсала для чокнутого мага, и живой вернулась! Вот это класс! Как вернусь в Стальгорн, лично расскажу о тебе старине Ройттену!" },
    ["1467a"] = { common = "Хочешь плату получить? Так за этим тебе придётся вернуться в Стальгорн и потолковать со стариной Ройттеном. Думаю, он будет рад отделаться, наконец, от коробки Кудесника. Отдашь ему вот это, и получишь свою награду. Да ты не беспокойся: когда я вернусь, то всяко замолвлю за тебя словечко. Мне тоже не больно-то хочется торчать в этих самых Пустошах." },
    ["1467c"] = { male = "О, а вот и посылка для Скрытного Кудесника, прямиком из Пустошей! Прекрасно! Ценю твою работу, герой: к тому же, тебе удалось уложиться в срок. Приятно было с тобой работать. Вот тут твоя плата. И пусть все знают, что Горная корпорация всегда оплачивает услуги своих работников по высшему разряду!", female = "О, а вот и посылка для Скрытного Кудесника, прямиком из Пустошей! Прекрасно! Ценю твою работу, героиня: к тому же, тебе удалось уложиться в срок. Приятно было с тобой работать. Вот тут твоя плата. И пусть все знают, что Горная корпорация всегда оплачивает услуги своих работников по высшему разряду!" },
    ["1469a"] = { common = "Перед тем как лететь, я выпил полный бочонок портера. Ик! Что это был за полёт! Я нёсся по воздуху, а Брохан болтался за моей спиной, но храма мы не видели. Ик! И не нашли бы мы его никогда, если бы я не нагрузился так, что сверзился из седла. Упал в воду, пошёл прямо на дно. А тут, откуда ни возьмись, целое стадо отвратительных троллей! Конечно, я постарался убраться оттуда как можно быстрее. Еле выбрался, однако прихватил с собой вот этот сувенир. Держите, отнесёте его Брохану и расскажете, что храм этот его – там, под водой. Ик!" },
    ["1469c"] = { common = "Рапсод Землекоп! Точно! Как я мог забыть такое имя? Так он всё это время знал о том, что храм затонул? Что ж, это точно сэкономит вам время. Но предмет, сделанный Атал'ай... Вот это находка!" },
    ["1470a"] = { common = "Приветствую тебя, дитя. Вижу, ты только вступаешь на пути чернокнижия, мощь его не даётся тебе пока. Я чувствую, как велико твоё желание учиться. Да, ты будешь учиться. В невежестве нет силы. Знание – вот залог нашего могущества. Знания позволяют нам контролировать хаотическую магию и тварей Бездны, склоняя их к своей воле. Я покажу тебе, как подчинять себе слугу, но сначала принеси мне три черепа скелетов-костетрясов, бродящих близ покинутой кузницы." },
    ["1470c"] = { male = "Хотя ты ещё не прошёл испытаний и находишься в самом начале ученичества, ты доказал, что силы у тебя достаточно, чтобы суметь призвать беса и подчинить его своей воле. Пусть тебя не обманывают его небольшие размеры. Физической силы ему не хватает, зато хватит магического могущества и разума, чтобы хорошо служить тебе. Слушай меня внимательно, потому что повторять я не буду, и тогда придётся всё осваивать самостоятельно.", female = "Хотя ты ещё не прошла испытаний и находишься в самом начале ученичества, ты доказала, что силы у тебя достаточно, чтобы суметь призвать беса и подчинить его своей воле. Пусть тебя не обманывают его небольшие размеры. Физической силы ему не хватает, зато хватит магического могущества и разума, чтобы хорошо служить тебе. Слушай меня внимательно, потому что повторять я не буду, и тогда придётся всё осваивать самостоятельно." },
    ["1471a"] = { male = "Ты наверняка уже видел круг призыва. Только в его пределы ты можешь вызвать демона Бездны. При помощи этих рун ты вызовешь его, а потом подчинишь себе силой оружия и магии. Подчинённый демон Бездны будет неразрывно связан с тобой. Выполнив задание, возвращайся ко мне, я научу тебя заклинанию призыва. Ты сможешь пользоваться им, когда захочешь.", female = "Ты наверняка уже видела круг призыва. Только в его пределы ты можешь вызвать демона Бездны. При помощи этих рун ты вызовешь его, а потом подчинишь себе силой оружия и магии. Подчинённый демон Бездны будет неразрывно связан с тобой. Выполнив задание, возвращайся ко мне, я научу тебя заклинанию призыва. Ты сможешь пользоваться им, когда захочешь." },
    ["1471c"] = { male = "Великолепная работа. Теперь я научу тебя заклинанию, позволяющему призвать демона Бездны. Ты сможешь обратить силу, которую недавно испытал на себе, против своих врагов.", female = "Великолепная работа. Теперь я научу тебя заклинанию, позволяющему призвать демона Бездны. Ты сможешь обратить силу, которую недавно испытала на себе, против своих врагов." },
    ["1472a"] = { common = "Суккубы – пожирательницы душ, разбивающие сердца и вводящие мужчин в искушение. Существа, исполненные зла и изощрённой хитрости. Просто так их в наш мир не выманишь. Мы обратим их собственную силу в слабость. Суккуб не сможет устоять перед сердцами добрых, целомудренных и любящих мужчин, и явится в Азерот. Тогда можно побороть её и подчинить себе. Ступай в Храм и поговори с моим помощником, Годриком Фарсаном. Он поможет тебе подобрать приманку." },
    ["1472c"] = { male = "Тебя прислал Карендин? Говоришь, ты путник? Не думай, что я просто беспомощный слепец. Я вижу истинную суть вещей с недоступной прежде ясностью, и то, что было моим проклятьем, обернулось благословением.", female = "Тебя прислал Карендин? Говоришь, ты путница? Не думай, что я просто беспомощный слепец. Я вижу истинную суть вещей с недоступной прежде ясностью, и то, что было моим проклятьем, обернулось благословением." },
    ["1473a"] = { male = "Похоже, ты готов призвать демона Бездны. Эти твари появляются из Круговерти Пустоты, лежащей за пределами мира. Если ты не сможешь подчинить себе вызванного демона, он разорвёт тебя на части. Первого демона Бездны сумел вызвать Эгалин, и это подробно описано в его гримуаре. К сожалению, агент Алого ордена похитил гримуар и спрятал его в башне к западу отсюда. Принеси книгу, и я наделю тебя знаниями.", female = "Похоже, ты готова призвать демона Бездны. Эти твари появляются из Круговерти Пустоты, лежащей за пределами мира. Если ты не сможешь подчинить себе вызванного демона, он разорвёт тебя на части. Первого демона Бездны сумел вызвать Эгалин, и это подробно описано в его гримуаре. К сожалению, агент Алого ордена похитил гримуар и спрятал его в башне к западу отсюда. Принеси книгу, и я наделю тебя знаниями." },
    ["1473c"] = { common = "А, великолепно. Вероятно, Перрин не догадывался, какие знания скрывает в себе этот фолиант. Мы больше не допустим хищения книги. Смотри: вот схема заклинания, объясняющая, как следует направлять энергию." },
    ["1474a"] = { common = "При помощи этих сердец наложи заклинание на круг призыва, чтобы открыть дверь в наш мир для суккуба. Твои силы возросли, и они понадобятся тебе, чтобы одолеть демоницу. Остерегайся её чар, даже сила воли может не защитить от них. Если ты победишь, суккуб вернётся в Бездну, а я научу тебя заклинанию, которое позволит тебе вызывать её в любой момент." },
    ["1474c"] = { male = "И снова ты справился с заданием. Давно мне не встречались чернокнижники с такими задатками. Не сомневайся, я буду следить за твоими успехами и помогу тебе подготовиться к ожидающим тебя испытаниям. А теперь я хочу научить тебя заклинанию призва личного суккуба.", female = "И снова ты справилась с заданием. Давно мне не встречались чернокнижники с такими задатками. Не сомневайся, я буду следить за твоими успехами и помогу тебе подготовиться к ожидающим тебя испытаниям. А теперь я хочу научить тебя заклинанию призва личного суккуба." },
    ["1475a"] = { common = "Храм Атал'Хаккара посвящён древнему божеству Хаккару Свежевателю Душ. Храм охраняет злобное племя троллей Атал'ай, и он, если верить слухам, неприступен. Теперь, когда он затонул, добывать в нём артефакты стало ещё сложнее. Но это именно то, о чём я вас прошу. Помогите мне собрать целые таблички Атал'ай. Принесите их мне, и я вернусь в Лигу Исследователей героем. Вместе мы добьёмся успеха!" },
    ["1475c"] = { common = "Таблички Атал'ай! Благодарю! Когда я доставлю их в Лигу Исследователей, наши имена войдут в историю. Вы помогли старому дворфу выполнить его последнее задание, и я бесконечно признателен вам за это!" },
    ["1476a"] = { common = "Чтобы поймать суккуба, нужно чистое сердце. Но разве остались среди смертных непорочные сердца? После долгих поисков и расспросов мне удалось найти только двоих. Первый из них – Далин Искусник. Он посвятил свою жизнь заботе о лордеронских беженцах, которых отказалась принять родня у Стены Седогрива. Вторая – Корма Виллард. Она скорбит об утраченной дружбе и бродит по Болотине в поисках подруги. Принеси их сердца Карендину. Но сначала я покажу тебе твои жертвы." },
    ["1476c"] = { common = "А с виду доброе сердце ничем не отличается от любого другого, да? Может быть, мы просто... по-другому смотрим на мир. Но эти сердца прекрасно подойдут. Не сомневаюсь, их чистота привлечёт суккуба." },
    ["1477a"] = { common = "Наши маги проводят исследования в Крепости Стражей Пустоты, в Выжженных землях – исследования, жизненно важные для понимания Тёмного портала. Они почти постоянно требуют поставок, однако доставлять что бы то ни было в крепость крайне сложно. Мы просим твоей помощи в обеспечении прибытия поставок в Крепость Стражей Пустоты. Сдай рапорт начальнику стражи Соригелу в Темнолесье и сделай то, о чём он попросит. Но это задание приведёт тебя во враждебные земли. Приготовься к любым опасностям." },
    ["1477c"] = { common = "Тебя послал Андромах? Очень хорошо. У меня для тебя важное задание..." },
    ["1478a"] = { common = "А! Я только что получил новости от Карендина Халгара – он хочет поговорить с вами насчёт дальнейшего обучения. Можете гордиться собой! Не каждый день мастер Халгар решает самолично проинструктировать юного чернокнижника. Его можно найти в Квартале Магов Подгорода, возле Храма Проклятых." },
    ["1478c"] = { common = "Хорошо, я вижу, Агерон нашёл вас. Давайте не будем тратить время на болтовню и церемонии, а сразу же перейдём к вашему обучению. Вам ещё очень много надо узнать." },
    ["1480a"] = { common = "Эта рваная кожа пахнет гнилью, и она на удивление мягкая и гибкая для такого сухого и хрупкого на вид материала. Если её развернуть, на ней видны красные письмена на непонятном наречии. А внизу – очень отчётливый отдельный символ, должно быть, подпись. Может быть, Майрин сумеет объяснить, что это такое?" },
    ["1480c"] = { common = "Да, это действительно чужой язык, и весьма древний. Он отчасти напоминает эредан, но отличия несомненны. Если не ошибаюсь, это нечто вроде договора... Да, вот этот символ – подпись демона: лорд Азреток." },
    ["1481a"] = { common = "Пожалуй, я сумею отыскать этого повелителя демонов, если найду нужные реагенты. Однако, если он действительно так могуществен, мне понадобятся предметы, собранные со смертельно опасных тварей... Прежде всего мне придётся снять заклятия, которые защищают его от соглядатаев. Для этого нужен скальп сатира, но не первого попавшегося, а тенелова из племени Ярой Ненависти. Ищи их в древних развалинах на северо-востоке Пустошей." },
    ["1481c"] = { male = "Что, герой, тенеловы тебя не убили? Неплохо, очень неплохо. Да, этот скальп мне подходит. Пока тебя не было, мне удалось собрать остальные необходимые реагенты. Я почти готов. Мне необходима только точка приложения заклинания – тот предмет, в котором мы увидим повелителя демонов и место, где он находится.", female = "Что, героиня, тенеловы тебя не убили? Неплохо, очень неплохо. Да, этот скальп мне подходит. Пока тебя не было, мне удалось собрать остальные необходимые реагенты. Я почти готов. Мне необходима только точка приложения заклинания – тот предмет, в котором мы увидим повелителя демонов и место, где он находится." },
    ["1482a"] = { common = "Кристалл оракула нам подойдёт. Их делают наги для своих оракулов. К северо-западу отсюда, на побережье, есть обширный коралловый риф, где поселились наги. Там можно найти и оракулов. Но Скользящий Плавник смертельно опасен и встретит тебя отнюдь не с распростёртыми объятиями. Так что смотри, осторожнее, и постарайся убраться оттуда побыстрее. А когда вернёшься, мы попробуем отыскать этого лорда Азретока." },
    ["1482c"] = { male = "Драгоценный кристалл оракула! Безупречный... великолепный… Что ж, начнём немедленно. Нам следует отыскать этого повелителя демонов. Отступи на шаг, герой, и давай посмотрим, как выглядит Азреток и где его искать.", female = "Драгоценный кристалл оракула! Безупречный... великолепный… Что ж, начнём немедленно. Нам следует отыскать этого повелителя демонов. Отступи на шаг, героиня, и давай посмотрим, как выглядит Азреток и где его искать." },
    ["1483a"] = { common = "Торговая Компания переманила лучшие гоблинские умы, но порой у нас появляется возможность вернуть своё. Некоторое время назад подразделение Торговой Компании в Когтистых горах приняло на работу Геренцо Терминатрикса – гнома! Это так ошарашило другого инженера, Зиза Физзикса, что он умолял меня найти ему новую работу в Союзе ремонтников. Я дал ему несколько заданий, но ему может понадобиться помощь. Не навестишь его? Он живёт у западного края Утёса Ветрорезов." },
    ["1483c"] = { common = "Я думал, что начальство Торговой Компании – настоящие тираны, но потом я познакомился с Пароклапаном, он хуже их всех! Ха! И всё же это лучше, чем сидеть без работы... Или, хуже того, работать с этим Геренцо. Если ты хочешь мне помочь, дело для тебя найдётся." },
    ["1484a"] = { common = "Это существо куда опаснее, чем мне казалось! Неудивительно, что Таката сомневается, что мне удастся его одолеть. Он будет оскорблён, если не сообщить ему о том, что случилось. Поговори с мечником, скажи, что хочешь убить демона, если он разрешит, но особо не настаивай. Пусть думает, будто это его собственная идея." },
    ["1484c"] = { common = "Да, я видел, что только что произошло между Муарином и повелителем демонов! Похоже, это существо, даже в видении, обладает куда большим могуществом, чем мой соратник-чернокнижник. Сумеет ли он одолеть этого монстра? Лучше бы я занялся этим сам... Но вождю я нужен здесь. Я опозорю свой клан, если оставлю свои здешние обязанности и отправлюсь добывать себе славу." },
    ["1485a"] = { common = "Чернокнижники, бывшие здесь до нас, внушили Орде недоверие к нам. Нас терпят, но недолюбливают. Однако это не заставило чернокнижников сплотиться. Многие предпочитают жить и заниматься магией в уединении. Я не буду принуждать тебя избрать тот или иной путь, а всего лишь помогу тебе сделать очередной шаг. Но прежде чем я научу тебя искусству призывания, принеси мне шесть голов злобных фамильяров из той пещеры на северо-востоке." },
    ["1485c"] = { common = "Во время обучения ты научишься вызывать самых разных существ. Все они по-своему полезны, даже если на первый взгляд это не очевидно. Пусть малый рост беса тебя не смущает. Ты уже знаешь, как опасны они бывают." },
    ["1486a"] = { common = "Пока Наралекс погружался в свои кошмары всё глубже, из-под Степей в Пещеры Стенаний пришли какие-то странные животные. Эти искажённые существа наделены странными, потусторонними силами. В то время как зло в их природе, я уверен, что из их существования можно извлечь некоторую пользу здесь в Калимдоре. Я верю, что из их кожи наши кожевники смастерят что-нибудь стоящее. Если эта задача тебе по вкусу, отправляйся в пещеры и принеси мне немного искажённых шкур." },
    ["1486c"] = { common = "Твои услуги не останутся незамеченными. Протеже. Спасибо тебе за твою неоценимую помощь." },
    ["1487a"] = { common = "Цели у Наралекса были самые благие. Наш лидер стремился впасть в Изумрудный сон, и вновь превратить эти выжженные земли в тот пышный лес, которым они когда-то являлись. Но что-то пошло не так. Мечта Наралекса превратилась в кошмар, и порченые твари заселили пещеры. В то время как некоторые приспешники Наралекса стремятся пробудить нашего мастера, я забочусь о том, чтобы избавить эти пещеры от заполонивших их тварей. Отправляйся туда. и уничтожь порченое семя." },
    ["1487c"] = { common = "Как послушник Наралекса я не могу не отметить твоей храбрости. Твоя помощь – это всего лишь первый шаг в очищении Степей от порчи. Благодарю тебя, и да пребудет тобой удача." },
    ["1488a"] = { common = "Я ничего не знаю об этом лорде Азретоке, однако согласен с Маурином: его следует остановить, особенно если он пытается подчинить себе Пылающий Клинок. Твоё стремление служить вождю уже не требует доказательств, и я готов доверить тебе собрать отряд, чтобы убить Азретока и его слугу чернокнижника. Когда будете готовы выступать, отправляйтесь на юг, а покончите с ними – возвращайтесь ко мне." },
    ["1488c"] = { common = "Эта победа очень важна для нас. Все мы радуемся вашему успеху. Теперь я думаю, что наше будущее не так беспросветно, как мне казалось. Демоны будут повержены, Пылающий Клинок потерпит крах, и в один прекрасный день у нас снова будет свой дом!" },
    ["1489a"] = { common = "На раковинах, что ты мне принёс, присутствует порча, которой я никогда раньше не видел. Я уверен, что причины её возникновения кроются в воде оазиса, и я уже предчувствую, чем это грозит этим землям. Источник этой порчи в Пещерах Стенаний, но прежде чем отправиться туда, поговори с Хамуулом Руническим Тотэмом, старшим друидом. Я послал ему весточку о том, что творится в Степях. Он мудр и сможет дать тебе дельный совет. Найдёшь его в Громовом Утёсе, на Вершине Старейшин." },
    ["1489c"] = { common = "Приветствую тебя, добро пожаловать. И лучше бы тебе собрать всю волю в кулак, потому что дело, порученное тебе, будет крайне нелёгким." },
    ["1490a"] = { common = "Я вошёл в сновидения и увидел там орден друидов, обитающих в Пещерах Стенаний. Когда-то их цели были благородными. Но теперь они отклонились от первоначального пути и стали слугами порчи просачивающейся из Степей. Я уже стар, и мои силы не бесконечны. Я не мог дольше оставаться в сновидениях, хотя и хотел узнать больше об этих друидах. Но Нара молода и сильна духом, и она осталась там, когда я вынужден был уйти. Поговори с ней, ты найдёшь её в дальней палатке." },
    ["1490c"] = { male = "Всё верно, я знаю о друидах из Пещер Стенаний. Я видела их исковерканные, покрытые чешуёй лица. Я знаю об их злодеяниях, и самое главное, мне известны их планы. Ты должен остановить их.", female = "Всё верно, я знаю о друидах из Пещер Стенаний. Я видела их исковерканные, покрытые чешуёй лица. Я знаю об их злодеяниях, и самое главное, мне известны их планы. Ты должна остановить их." },
    ["1491a"] = { common = "Ладно, рога ящеров не подошли. Ничего страшного, с первого раза никому не удаётся разбогатеть. Кроме того, мне удалось придумать кое-что получше! Существует вещество, именуемое воющей субстанцией, и мне кажется, именно из-за него в Степях такие странные растения и животные. Принеси мне немного субстанции, и я попробую добавить её в напиток! Насколько я знаю, это вещество накапливается в эктоплазматических существах в Пещерах Стенаний на западе. Убей несколько существ из пещер и собери из них субстанцию." },
    ["1491c"] = { common = "Здорово, ты принёс её! Не терпится опробовать напиток. Я знаю, он принесёт мне много денег! Спасибо. Вот тебе деньги, и, разбогатев, я пришлю тебе ещё, клянусь!" },
    ["1492a"] = { male = "Мне нужно послать ящик зелий, реактивов и прочего своим партнёрам из Старого Света. У меня нет времени лично относить их в порт Кабестана, а последний караван уже отбыл. Не мог бы ты отнести ящик управляющему пристанью Головокружилкинсу? А он в свою очередь погрузит его на первый же корабль, идущий в бухту Черноводья.", female = "Мне нужно послать ящик зелий, реактивов и прочего своим партнёрам из Старого Света. У меня нет времени лично относить их в порт Кабестана, а последний караван уже отбыл. Не могла бы ты отнести ящик управляющему пристанью Головокружилкинсу? А он в свою очередь погрузит его на первый же корабль, идущий в бухту Черноводья." },
    ["1492c"] = { male = "Небольшой ящик. Да, пожалуй, для него найдётся место на корабле. Он отплывет в ближайший прилив, это достаточно скоро? Великолепно. Надо только записать его в мой регистр. Ну вот, всё готово. Пока, герой.", female = "Небольшой ящик. Да, пожалуй, для него найдётся место на корабле. Он отплывет в ближайший прилив, это достаточно скоро? Великолепно. Надо только записать его в мой регистр. Ну вот, всё готово. Пока, героиня." },
    ["1498a"] = { common = "Одна из основных задач воина... защита. Мы – щит Орды, заслоняющий собой наших более слабых братьев. Если ты хочешь вступить в наши ряды, докажи мне, что не струсишь. Ступай в Дуротар, на Громовой хребет, где живут бурешкуры и рокочущие ящерицы. Поохоться на них, докажи, что ты сильнее их! Выстой против них и принеси мне в доказательство побольше оплавленных чешуек. Как только принесёшь, я возьмусь тебя учить." },
    ["1498c"] = { male = "А, вижу, тебе удалось справиться с рокочущими ящерицами, значит, ты крепкий парень. А теперь я покажу тебе, как можно сделаться почти неуязвимым для противника благодаря толстой шкуре и ловкости. Учись хорошенько. Вскоре тебе предстоит новый урок.", female = "А, вижу, тебе удалось справиться с рокочущими ящерицами, значит, ты крепкая девчонка. А теперь я покажу тебе, как можно сделаться почти неуязвимым для противника благодаря толстой шкуре и ловкости. Учись хорошенько. Вскоре тебе предстоит новый урок." },
    ["1499a"] = { male = "Зурита часто посылает таких новичков, как ты, приструнить этих тварей. Тебе уже доводилось сражаться с коварными фамильярами. Думаю, тебе не помешает набраться опыта, помогая Зурите. Не забудь ей сказать, что ты помогал разобраться с бесами – возможно, у неё найдётся для тебя награда.", female = "Зурита часто посылает таких новичков, как ты, приструнить этих тварей. Тебе уже доводилось сражаться с коварными фамильярами. Думаю, тебе не помешает набраться опыта, помогая Зурите. Не забудь ей сказать, что ты помогала разобраться с бесами – возможно, у неё найдётся для тебя награда." },
    ["1499c"] = { common = "Молодец! Да, злобные фамильяры для воинов Пылающего Клинка – всего лишь ручные зверушки, однако же твой успех предсказывает тебе великие дела!" },
    ["1501a"] = { common = "Чернокнижников осталось так мало... Мы многим рискуем, но наш риск оправдан! Если ты хочешь принести пользу Орде и вождю, пора тебе научиться новому заклинанию призыва. Для начала добудь табличку Верги. Чернокнижники из клана Пылающего Клинка похитили её и хранят у себя в логове, под скалой Черепа к востоку от города. После этого я покажу тебе руны, необходимые для призыва демона Бездны." },
    ["1501c"] = { common = "Молодец. Надеюсь, во время твоего визита в логово чернокнижники из клана Пылающего Клинка сильно пострадали? Они причинили немало вреда вождю, да и нам, чернокнижникам, тоже." },
    ["1502a"] = { common = "Воину пристало владеть хорошим оружием. Самое лучшее оружие делает орк по имени Тун'грим Огневзор. Это отшельник, который живёт на вершине холма к востоку от Перекрёстка. Если тебе нужно оружие, воин, отправляйся к Тун'гриму. Чтобы добраться до его жилища, дойди до Перекрёстка и сверни на восток, в сторону холмов. Он разбил лагерь на самой вершине." },
    ["1502c"] = { male = "Я так долго глядел на пламя горна, что у меня высохли глаза, но кое-что я по-прежнему вижу. Например, тебе что-то от меня нужно. И раз ты добрался до моего жилища, то я могу предположить, что именно.", female = "Я так долго глядел на пламя горна, что у меня высохли глаза, но кое-что я по-прежнему вижу. Например, тебе что-то от меня нужно. И раз ты добралась до моего жилища, то я могу предположить, что именно." },
    ["1503a"] = { common = "Я дам тебе оружие, но прежде помоги мне. Несколько дней назад с северо-запада на меня напало племя Иглогривых. Биться со мной они побоялись, но зная, какое у меня плохое зрение, одни отвлекли меня своим пофыркиванием, а другие ограбили мой лагерь! Трусы! Они украли железный сундук, в котором лежали стальные слитки. Если ты сможешь вернуть их, я дам тебе нужное оружие. Найди мой сундук в одном из лагерей иглогривов и принеси мне стальные слитки." },
    ["1503c"] = { common = "Вот они! И все мои слиточки на месте, что и неудивительно. Откуда иглогривым знать, что делать с такой отличной сталью. Спасибо. Вот твоя награда. Пусть она служит тебе верой и правдой." },
    ["1504a"] = { common = "Посмотри на табличку Верги. Изображённые на ней знаки понадобятся тебе для призыва. Отнеси это в круг в шатре Нииру Огненного Клинка на другом конце пещеры. Там ты сможешь вызвать демона Бездны. Тебе нужно будет одолеть его любыми физическими и магическими средствами. А после этого возвращайся ко мне со знаками призыва, и я покажу тебе, как подчинить это существо своей воле." },
    ["1504c"] = { common = "Молодец! Я покажу тебе, как вызывать демона Бездны, подобного тому, которого тебе только что пришлось одолеть. Знай, мы на тебя очень рассчитываем, и пока что ты оправдываешь все наши надежды! Однако пусть успех не кружит тебе голову. Впереди куда более сложные задачи!" },
    ["1505a"] = { common = "Орда чтит своих воинов, потому что никто не сомневается в их силе. Но истинному величию чуждо самодовольство. Никогда не упускай случая поучиться новому. Отыщи Уззека. Он прошёл через много сражений и теперь обучает молодых воинов боевым приёмам. Он живёт на юге от Дальней заставы, орочьего гарнизона на границе Степей и Дуротара." },
    ["1505c"] = { male = "Привет, юноша. Ты учиться пришёл?", female = "Привет, девушка. Ты учиться пришла?" },
    ["1506a"] = { male = "Эй, ты! Ты ведь путник, верно? Надеюсь, сейчас у тебя нет никаких срочных дел, потому что тебя немедленно хочет видеть Гарнул. Ты найдёшь его среди старших чернокнижников в расселине Теней. Насколько я знаю Ган'рула, это сулит тебе либо что-то очень хорошее, либо что-то очень плохое.", female = "Эй, ты! Ты ведь путница, верно? Надеюсь, сейчас у тебя нет никаких срочных дел, потому что тебя немедленно хочет видеть Гарнул. Ты найдёшь его среди старших чернокнижников в расселине Теней. Насколько я знаю Ган'рула, это сулит тебе либо что-то очень хорошее, либо что-то очень плохое." },
    ["1506c"] = { common = "Ага, хорошо. Я опасался, что Офек не сумеет с тобой связаться. Тебе пора продолжить своё обучение на чернокнижника. Все прочие дела пока отложи. Надеюсь, с этим проблем не будет?" },
    ["1507a"] = { common = "Пора тебе научиться новому колдовству. Ты научишься вызывать суккуба, демона в женском обличье. Это существо способно зачаровывать и подчинять себе слабых духом. Но не бойся! Я уверен, тебя ей не одолеть. Чтобы приманить суккуба, нужен предмет, в котором воплощена искренняя любовь и преданность. Тебе нужно найти такую вещь. Где? Ну, потолкуй с Казулом. Чего не знает этот старый чернокнижник, того и знать не стоит." },
    ["1507c"] = { male = "Хм... путник. Ты ещё новичок, но я чую в тебе большие способности. У тебя врождённый дар к чернокнижию. Такими вещами не разбрасываются.", female = "Хм... путница. Ты ещё новичок, но я чую в тебе большие способности. У тебя врождённый дар к чернокнижию. Такими вещами не разбрасываются." },
    ["1508a"] = { common = "Хмм... Но ты, конечно, здесь не за этим. Раз Ган'рул отправил тебя ко мне, тебе, должно быть, нужно вызвать суккуба, и ты ищешь приманку… Ну, если ты согласишься довериться слепому поводырю, то слушай. Среди утёсов Оргриммара, к западу от башни Крыла Ветра, живёт Занкайя. Она ждёт возвращения мужа. Ступай к ней." },
    ["1508c"] = { common = "У тебя есть весточка от Дограна? Он должен был вернуться уже несколько дней тому назад, а о нём до сих пор ни слуху, ни духу..." },
    ["1509a"] = { common = "Моего супруга, Дограна, не так давно отправили служить в Перекрёсток. Это было повышение по службе, он так гордился… Мне, конечно, было грустно, но ему я этого не показывала. Грустно и тревожно. Степи – не Оргриммар, это опасное место, и я боялась худшего… Он должен был вернуться неделю назад, а от него до сих пор нет никаких вестей! Может, ты сходишь в Перекрёсток, разузнаешь о нём? Он служил вместе с Газрогом, и Газрог, наверное, до сих пор там..." },
    ["1509c"] = { common = "Занкайя? Жена Дограна, да? Слышать-то я о нём слышал, но это не те новости, которые стоит ей передавать. Да нет, не убили его. Но он ранен и сейчас в плену у иглогривов." },
    ["1510a"] = { common = "Он был в Лагере Таурахо, где мы пытались извести иглогривов. Он повёл нескольких рубак на одно из их стойбищ, и там его тяжело ранили. Остальные вернулись и попытались его выручить. Но он был в плохом состоянии, раны загноились, и ребята побоялись его трогать. Они отправили сюда послание, просили троллей из Малака'джина у Когтистых гор прислать целительное зелье. Мы послали за зельем, но гонец пока не вернулся." },
    ["1510c"] = { common = "Орк? Надеюсь, ты не за тем, другим? А то он добрался не очень... благополучно. Общение с гоблинами не довело его до добра. Он успел сказать, что приехал за целительным зельем, но больше ничего вразумительного." },
    ["1511a"] = { common = "Я так и думал, что за зельем явится кто-нибудь ещё! Вот оно, бери. Имей в виду, сразу всё ему не давай, пусть выпьет половину! Этого ему хватит, чтобы передвигаться. А иначе он истечёт кровью. На следующее утро пусть выпьет вторую половину. Отнеси это Логмару в Лагерь Таурахо. Судя по тому, что сказал мне первый гонец, Логмар знает, где Догран." },
    ["1511c"] = { common = "О, как нельзя более кстати! А то Догран уже умирает там, в плену. Это нужно доставить ему немедленно. Но большинство моих рубак сейчас на задании..." },
    ["1512a"] = { common = "Занкайя молода и красива. Зачем ей калека? Несправедливо это будет. Оставь меня. Спасибо тебе. Я предпочёл бы умереть в славной битве, а не влачить это жалкое существование. И прошу тебя, не говори об этом моей супруге... Не хочу, чтобы она чувствовала себя виноватой." },
    ["1512c"] = { common = "Ну, если ты говоришь, что этого достаточно, я тебе верю. Дай-ка я её оботру... Да, вот такая, блестящая и чистенькая, она будет куда соблазнительней для суккуба." },
    ["1513a"] = { common = "Отнеси это к кругу призыва в шатре Нииру. Вызови гнусного суккуба и покажи ему, кто здесь хозяин. Я верю в силу твоей магии. Но всё же будь осторожнее: гордость и самоуверенность погубили немало многообещающих чернокнижников. Когда подчинишь суккуба, верни подвеску мне. Нужно будет сообщить Занкайе о случившемся." },
    ["1513c"] = { common = "Получилось! Впрочем, я ничего другого и не ждал, ведь ты – мой лучший ученик. Теперь я с радостью покажу тебе, как вызывать усмиренного суккуба. Ступай, тебе многому нужно научиться. Я рассчитываю, что к нашей следующей встрече ты уже по-настоящему подчинишь своего суккуба. С печальной историей Дограна и Занкайи разберутся те, кто постарше тебя. Но ты её не забывай: она послужит хорошей защитой от хитростей тёмного демона, который явился к тебе сегодня." },
    ["1515a"] = { common = "Ну, раз уж ты здесь и хочешь завершить своё дело, останавливать тебя я не буду. Но своих воинов я с тобой отпустить не смогу, ступай в одиночку. Дограна держат в лагере иглогривов, к северу отсюда. Ищи две хижины, стоящие рядом. Иглогривы его стерегут – если, конечно, его ещё не убили, или он не умер от ран. Удачи тебе!" },
    ["1515c"] = { common = "Тьфу, гадость… Однако сил у меня прибавляется. Пожалуй, я теперь смогу уковылять отсюда... Однако похоже, что ногу мне придётся отнять. И руку тоже." },
    ["1516a"] = { male = "Что ж, герой, пора! Ты набрался сил, твой дух стоек, как сама Земля. А то, что тобою избран путь шамана – само по себе доказательство твоей мудрости. Стихия земли будет управлять твоей судьбой, станет частью тебя. Готов ли ты? Тебе придётся предстать перед самой Землёй. И тогда ты увидишь многое, что ведомо лишь шаманам. Разыщи на севере ловцов скверны и добудь два их копыта. А потом возвращайся ко мне, и мы обсудим твоё будущее.", female = "Что ж, героиня, пора! Ты набралась сил, твой дух стоек, как сама Земля. А то, что тобою избран путь шамана – само по себе доказательство твоей мудрости. Стихия земли будет управлять твоей судьбой, станет частью тебя. Готова ли ты? Тебе придётся предстать перед самой Землёй. И тогда ты увидишь многое, что ведомо лишь шаманам. Разыщи на севере ловцов скверны и добудь два их копыта. А потом возвращайся ко мне, и мы обсудим твоё будущее." },
    ["1516c"] = { male = "Великолепно! Твой успех доказывает: ты действительно готов. Среди стихий именно Земля – основа всего сущего. Это твоя сила, твоя выносливость и твоё терпение. Земля защитит тебя, если ты будешь относиться к ней с должным почтением. Но и Земля, как все прочие стихии, может быть своенравной. Теперь я сделаю для тебя сапту. Прими её – и постигнешь свой путь!", female = "Великолепно! Твой успех доказывает: ты действительно готова. Среди стихий именно Земля – основа всего сущего. Это твоя сила, твоя выносливость и твоё терпение. Земля защитит тебя, если ты будешь относиться к ней с должным почтением. Но и Земля, как все прочие стихии, может быть своенравной. Теперь я сделаю для тебя сапту. Прими её – и постигнешь свой путь!" },
    ["1517a"] = { common = "Сапта – это напиток, который связывает душу со стихией. Сама магия растворена в нём. И сильные духом благодаря ему способны зреть стихии, которых никто более не видит. Твой дух будет связан со стихией сапты. Лишь немногие избранные шаманы знают рецепт этого напитка. Запомни: сапту можно пить лишь в священном месте, и нигде более! Отыщи Священный Камень к юго-западу отсюда. Он находится в конце Потайной тропы. Выпей там сапту, а дальше... увидишь!" },
    ["1517c"] = { male = "Ах... путник... Земля ликует от того, что ты пришёл сюда. Теперь ты связан с ней духом и телом, и продолжишь свой путь, зная, что горы суть твоя сила, равнины суть твоё терпение, и весь мир – основа твоей сущности. Для прохождения этого обряда довольно было смиренно предстать перед землёй. Но другие обряды потребуют более активных действий.Они могут оказаться жестоки и непредсказуемы – но такова уж природа стихий. Тебе следует научиться управляться с вечной борьбой противоположностей, лежащей в их основе.", female = "Ах... путница... Земля ликует от того, что ты пришла сюда. Теперь ты связана с ней духом и телом, и продолжишь свой путь, зная, что горы суть твоя сила, равнины суть твоё терпение, и весь мир – основа твоей сущности. Для прохождения этого обряда довольно было смиренно предстать перед землёй. Но другие обряды потребуют более активных действий.Они могут оказаться жестоки и непредсказуемы – но такова уж природа стихий. Тебе следует научиться управляться с вечной борьбой противоположностей, лежащей в их основе." },
    ["1518a"] = { male = "Возьми этот необработанный кварц и отнеси его Канаге заклинателю земли в доказательство того, что мы с тобой встречались. Он создаст тотэм для тебя, и этот камушек будет сердцем тотэма. Он невелик, но со временем ты поймёшь, что размер не имеет значения. Иногда малое оказывается долговечнее большого. Будь терпелив. Оставайся сильным. И ищи мудрости. В конце концов ты станешь единым целым с Землёй – чти же её, и она будет чтить тебя.", female = "Возьми этот необработанный кварц и отнеси его Канаге заклинателю земли в доказательство того, что мы с тобой встречались. Он создаст тотэм для тебя, и этот камушек будет сердцем тотэма. Он невелик, но со временем ты поймёшь, что размер не имеет значения. Иногда малое оказывается долговечнее большого. Будь терпелива. Оставайся сильной. И ищи мудрости. В конце концов ты станешь единым целым с Землёй – чти же её, и она будет чтить тебя." },
    ["1518c"] = { male = "Великолепно! Тотэм, который я создам для тебя, – не просто символ нового статуса. Он обладает тайными возможностями. Его можно использовать для сосредоточения заклинаний Земли. Чем больше мудрости ты обретёшь, тем больше способностей земли станет тебе доступно. Наставники скажут тебе, когда ты будешь готов к новым знаниям. А пока возьми этот тотэм Земли.", female = "Великолепно! Тотэм, который я создам для тебя, – не просто символ нового статуса. Он обладает тайными возможностями. Его можно использовать для сосредоточения заклинаний Земли. Чем больше мудрости ты обретёшь, тем больше способностей земли станет тебе доступно. Наставники скажут тебе, когда ты будешь готова к новым знаниям. А пока возьми этот тотэм Земли." },
    ["1519a"] = { male = "Время настало, юный герой. Тело твоё возмужало, а дух закалился, как сама земля. Я вижу, ты обрёл мудрость. Земля ведёт и хранит наш народ, она говорит с нами, как однажды станет говорить с тобой. Но тебе придётся пройти испытания. Если ты готов, твоему взору откроется то, о чём известно лишь нашему народу. Найди шаманов из племени Дыбогривов в их лощине на востоке и возьми у них мазь, которую они используют в своих ритуалах. Возвращайся ко мне, когда соберёшь достаточно мази для изготовления зелья.", female = "Время настало, юная героиня. Тело твоё возмужало, а дух закалился, как сама земля. Я вижу, ты обрела мудрость. Земля ведёт и хранит наш народ, она говорит с нами, как однажды станет говорить с тобой. Но тебе придётся пройти испытания. Если ты готова, твоему взору откроется то, о чём известно лишь нашему народу. Найди шаманов из племени Дыбогривов в их лощине на востоке и возьми у них мазь, которую они используют в своих ритуалах. Возвращайся ко мне, когда соберёшь достаточно мази для изготовления зелья." },
    ["1519c"] = { male = "Отлично. Ты вернулся – а значит, готов к следующему шагу. Стихия земли – это основа всех вещей. Это твоя сила, твоя выносливость и твоё терпение. Мать-Земля защитит тебя, но к ней должно относиться с уважением. Она – основа жизни, и следуя её законам, ты приумножишь мудрость. Никогда не забывай тайны, которые она разделит с тобой. Теперь я приготовлю для тебя сапту земли, который откроет перед тобой новые пути.", female = "Отлично. Ты вернулась – а значит, готова к следующему шагу. Стихия земли – это основа всех вещей. Это твоя сила, твоя выносливость и твоё терпение. Мать-Земля защитит тебя, но к ней должно относиться с уважением. Она – основа жизни, и следуя её законам, ты приумножишь мудрость. Никогда не забывай тайны, которые она разделит с тобой. Теперь я приготовлю для тебя сапту земли, который откроет перед тобой новые пути." },
    ["1520a"] = { common = "Сапта – это напиток, призванный объединить твой дух со стихиями. Сотворённое с помощью магии зелье позволит тем, чьё сознание открыто, видеть стихии так, как их никто не видел ранее. Твой дух будет навеки связан со стихией, для которой был создан сапта – и лишь немногим из нашего племени известен секрет его изготовления. Сапта должна быть выпита в только в священном месте и более нигде. Найди шаманское святилище к востоку отсюда и выпей сапту там." },
    ["1520c"] = { male = "Ах... путник... Земля ликует от того, что ты пришёл сюда. Теперь ты связан с ней духом и телом, и продолжишь свой путь, зная, что горы суть твоя сила, равнины суть твоё терпение, и весь мир – основа твоей сущности. Для прохождения этого обряда довольно было смиренно предстать перед землёй. Но другие обряды потребуют более активных действий. Они могут оказаться жестоки и непредсказуемы – но такова уж природа стихий. Тебе следует научиться управляться с вечной борьбой противоположностей, лежащей в их основе.", female = "Ах... путница... Земля ликует от того, что ты пришла сюда. Теперь ты связана с ней духом и телом, и продолжишь свой путь, зная, что горы суть твоя сила, равнины суть твоё терпение, и весь мир – основа твоей сущности. Для прохождения этого обряда довольно было смиренно предстать перед землёй. Но другие обряды потребуют более активных действий. Они могут оказаться жестоки и непредсказуемы – но такова уж природа стихий. Тебе следует научиться управляться с вечной борьбой противоположностей, лежащей в их основе." },
    ["1521a"] = { male = "Возьми этот грубый кварц и отнеси его провидице Воронье Перо в доказательство того, что мы говорили с тобой. Она создаст для тебя тотэм, и этот камень станет его сердцем. Тебе может показаться, что он мал, но со временем ты поймёшь, что размер не имеет значения. Иногда малое оказывается долговечнее большого. Будь терпелив. Оставайся сильным. И ищи мудрости. Так угодно земле. В конце концов ты станешь единым целым с землёй – чти же её, и она будет чтить тебя.", female = "Возьми этот грубый кварц и отнеси его провидице Воронье Перо в доказательство того, что мы говорили с тобой. Она создаст для тебя тотэм, и этот камень станет его сердцем. Тебе может показаться, что он мал, но со временем ты поймёшь, что размер не имеет значения. Иногда малое оказывается долговечнее большого. Будь терпелива. Оставайся сильной. И ищи мудрости. Так угодно земле. В конце концов ты станешь единым целым с землёй – чти же её, и она будет чтить тебя." },
    ["1521c"] = { male = "Прекрасно! Тотэм, который я сделаю для тебя – не просто символ. Он обладает тайными свойствами. Его можно использовать для сосредоточения заклинаний Земли. Чем больше мудрости ты обретёшь, тем больше способностей земли станет тебе доступно. Наставники в Калимдоре скажут тебе, когда ты будешь готов к новым знаниям. А пока возьми этот тотэм Земли...", female = "Прекрасно! Тотэм, который я сделаю для тебя – не просто символ. Он обладает тайными свойствами. Его можно использовать для сосредоточения заклинаний Земли. Чем больше мудрости ты обретёшь, тем больше способностей земли станет тебе доступно. Наставники в Калимдоре скажут тебе, когда ты будешь готова к новым знаниям. А пока возьми этот тотэм Земли..." },
    ["1522a"] = { male = "Огонь с тобой, дружище! Шо, я смотрю, пути Земли тебе уже знакомы? Значит, пора тебе перетереть с Крэналом. Крэнал живёт к северу от Перекрёстка, в Степях. По части стихий он очень крут, и путям Огня тебя научит на раз... если ты, конечно, готов к этому. Найти его – как нефиг делать, только смотри, слишком далеко не ходи, а не то к эльфам занесёт.", female = "Огонь с тобой, дружище! Шо, я смотрю, пути Земли тебе уже знакомы? Значит, пора тебе перетереть с Крэналом. Крэнал живёт к северу от Перекрёстка, в Степях. По части стихий он очень крут, и путям Огня тебя научит на раз... если ты, конечно, готова к этому. Найти его – как нефиг делать, только смотри, слишком далеко не ходи, а не то к эльфам занесёт." },
    ["1522c"] = { male = "Что, тебя Сеарн прислал, да? Ну, на Сеарна положиться можно. Значит, ты уже готов вкусить следующую сапту – сапту огня. Да, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг... Однако, имей терпение. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться.", female = "Что, тебя Сеарн прислал, да? Ну, на Сеарна положиться можно. Значит, ты уже готова вкусить следующую сапту – сапту огня. Да, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг... Однако, имей терпение. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться." },
    ["1523a"] = { male = "Много времени прошло с тех пор, как тебе пришлось выдержать последнее испытание! Тебе удалось научиться терпению, но теперь тебе пришло время сделать новый шаг. Пора учиться разрушению и хаосу. Тебе следует овладеть стихией огня – если только ты готов платить за это. Отыщи в Степях Кранала Фисса. Он живёт в небольшой хижине к северу от Перекрёстка. Только осторожнее: если промахнёшься, можешь очутиться в землях ночных эльфов!", female = "Много времени прошло с тех пор, как тебе пришлось выдержать последнее испытание! Тебе удалось научиться терпению, но теперь тебе пришло время сделать новый шаг. Пора учиться разрушению и хаосу. Тебе следует овладеть стихией огня – если только ты готова платить за это. Отыщи в Степях Кранала Фисса. Он живёт в небольшой хижине к северу от Перекрёстка. Только осторожнее: если промахнёшься, можешь очутиться в землях ночных эльфов!" },
    ["1523c"] = { male = "Хм, тебя Ксанис прислал ко мне? Ну что ж, Ксанису всегда можно доверять. Должно быть ты уже готов принять участие в следующей сапе, сапте-огня. Вижу в твоих глазах, огненное желание. Ты попробовал власть на вкус, и теперь, ты готов к большему. Терпение. Помни чему учила тебя Земля. Мощь и разрушение, ты всегда должен знать, когда нужно остановить руку.", female = "Хм, тебя Ксанис прислал ко мне? Ну что ж, Ксанису всегда можно доверять. Должно быть ты уже готова принять участие в следующей сапе, сапте-огня. Вижу в твоих глазах, огненное желание. Ты попробовала власть на вкус, и теперь, ты готова к большему. Терпение. Помни чему учила тебя Земля. Мощь и разрушение, ты всегда должна знать, когда нужно остановить руку." },
    ["1524a"] = { male = "У тебя достаточно сил, чтобы управлять тотэмом огня, но это ещё не значит, что ты готов к этому. Вдоль реки Строптивой в Дуротаре, у Великого моря, лежит тайная тропа, ведущая к одному из высочайших пиков в нашей стране. Отыщи путь на вершину, и найдёшь одно из наших святилищ, которое оберегает Телф Джулам – святилище Спящего Пламени. Отнеси ему этот факел – это знак, что ты пытаешься приручить огонь. Верни мне этот факел зажжённым от жаровни в святилище, и я позабочусь, чтобы тебе был дан тотэм огня.", female = "У тебя достаточно сил, чтобы управлять тотэмом огня, но это ещё не значит, что ты готова к этому. Вдоль реки Строптивой в Дуротаре, у Великого моря, лежит тайная тропа, ведущая к одному из высочайших пиков в нашей стране. Отыщи путь на вершину, и найдёшь одно из наших святилищ, которое оберегает Телф Джулам – святилище Спящего Пламени. Отнеси ему этот факел – это знак, что ты пытаешься приручить огонь. Верни мне этот факел зажжённым от жаровни в святилище, и я позабочусь, чтобы тебе был дан тотэм огня." },
    ["1524c"] = { common = "А, я ошибся! Прошу прощения. Я не знал, что у тебя с собой этот факел. Очень рад познакомиться. Сюда забредает немало путешественников, которые ищут клады или охотятся на невиданных зверей, и мне приходится прогонять их из этого святилища, которое кажется пустым. Но мы-то с тобой знаем истину, не так ли? Это святилище скрывает от несведущих великую тайну. Для нас эта тайна священна!" },
    ["1525a"] = { common = "Но ты ведь здесь не затем, чтобы выслушивать лекции по истории, верно? Тебе нужно Неугасимое Пламя и тотэм Огня! Первый шаг – это создать сапту, чтобы связать тебя со стихией огня. Я могу изготовить тебе сапту, но для этого нужны две вещи. Во-первых – огненная смола, распространённое вещество, которое обычно носят при себе заклинатели Иглогривых в восточных Степях. А вот второй компонент добыть куда сложнее: это мешочек с реактивами, какие носят чернокнижники из клана Пылающего Клинка. Их можно отыскать в пещере над ущельями к северо-востоку от Колючего Холма." },
    ["1525c"] = { common = "Это как раз то, что надо. Огонь – это не просто хаос и разрушение. Запомни это хорошенько! Огонь – это ещё и жизнь, и творение! Всё в мире взаимосвязано подобным же образом. Противоборствующие силы противостоят друг другу, но при этом не могут существовать поодиночке. Они взаимно уничтожаются, но придают друг другу смысл. Помни об этом! Одновременное использование различных видов магии говорит не только о подлинном искусстве, но и о большой мудрости." },
    ["1526a"] = { male = "Сапта огня готова. Пришло тебе время встретиться лицом к лицу со стихией пламени! Выпей сапту в святилище и отправляйся на вершину горы, чтобы увидеть там проявление. Оно не нападёт на тебя, пока ты не будешь готов к этому, однако оно поймёт, что ты его видишь. Постарайся поразить его как можно быстрее, ибо чем дольше ты будешь тянуть, тем больше мощи оно наберёт! Когда одолеешь его, положи оставшиеся от него тлеющие уголья в жаровню и зажги факел.", female = "Сапта огня готова. Пришло тебе время встретиться лицом к лицу со стихией пламени! Выпей сапту в святилище и отправляйся на вершину горы, чтобы увидеть там проявление. Оно не нападёт на тебя, пока ты не будешь готова к этому, однако оно поймёт, что ты его видишь. Постарайся поразить его как можно быстрее, ибо чем дольше ты будешь тянуть, тем больше мощи оно наберёт! Когда одолеешь его, положи оставшиеся от него тлеющие уголья в жаровню и зажги факел." },
    ["1526c"] = { common = "Когда вы бросаете уголёк в жаровню, в чаше вспыхивает жаркое белое пламя. Вы ощущаете, как по телу разливается огонь сапты, перед глазами ритмично бьётся пламя. Вы опускаете факел в чашу, и он мгновенно вспыхивает." },
    ["1527a"] = { common = "Крепко сжимая факел, вы отступаете от жаровни, оборачиваетесь и окидываете взглядом весь Дуротар. Вас охватывает восторг. Пламя факела рвётся и трепещет на ветру. И вот вы начинаете спускаться обратно по тропе, ведущей в Степи, возвращаясь к Краналу Фиссу." },
    ["1527c"] = { common = "Твой дух пылает ярче любого факела! Тебе есть чем гордиться. Не сходи с избранного пути, и стихии будут повиноваться тебе, а наши собратья станут искать у тебя советов и наставлений. Позволь мне первым поздравить тебя и вручить тебе новый тотэм..." },
    ["1528a"] = { male = "Вода – твоё будущее, дружище. Вижу, ты уже покорил огонь и, кажись, готов поговорить с Ислен. Ислен живёт на побережье ентих Степей. Топай на юг, вдоль реки Строптивая, не промахнёшься – ищи нехилую акулу! Ислен – великая повелительница духов, и она научит тебя сути воды... если ты готов. Ты её запростяк найдёшь, только на юг слишком далеко не заходи: Ислен живёт рядом с Кабестаном.", female = "Вода – твоё будущее, дружище. Вижу, ты уже покорила огонь и, кажись, готова поговорить с Ислен. Ислен живёт на побережье ентих Степей. Топай на юг, вдоль реки Строптивая, не промахнёшься – ищи нехилую акулу! Ислен – великая повелительница духов, и она научит тебя сути воды... если ты готова. Ты её запростяк найдёшь, только на юг слишком далеко не заходи: Ислен живёт рядом с Кабестаном." },
    ["1528c"] = { common = "Ветер следует за тобой, по земле ты шагаешь твёрдо, а дух уже согрет огнём – я бы сказала, что пришло время познать чистоту воды. Путь твой был долог, и сила духа позволит тебе пройти ещё дальше. Но первый шаг делать тебе." },
    ["1529a"] = { male = "Много воды утекло со времени последнего испытания. Ты проявил немало упорства в учении, и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды. Отыщи Ислен Заклинательницу Воды. Она живёт в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи.", female = "Много воды утекло со времени последнего испытания. Ты проявила немало упорства в учении, и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды. Отыщи Ислен Заклинательницу Воды. Она живёт в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи." },
    ["1529c"] = { common = "Ветер следует за тобой, по земле ты шагаешь твёрдо, а дух уже согрет огнём – я бы сказала, что пришло время познать чистоту воды. Путь твой был долог, и сила духа позволит тебе пройти ещё дальше. Но первый шаг делать тебе." },
    ["1530a"] = { male = "Первым делом ты должен понять, что вода означает возрождение. Вода течёт, разрушает и очищает всё сущее. Ты увидишь, что вода – великий целитель, но только чистая вода. Познав, что осквернённая вода разрушает всё кругом, ты поймёшь и то, как вода важна для мироздания. Если же ты хочешь получить сапту воды, отыщи Брин в южной части Степей. На её дом постоянно нападают иглогривы.", female = "Первым делом ты должна понять, что вода означает возрождение. Вода течёт, разрушает и очищает всё сущее. Ты увидишь, что вода – великий целитель, но только чистая вода. Познав, что осквернённая вода разрушает всё кругом, ты поймёшь и то, как вода важна для мироздания. Если же ты хочешь получить сапту воды, отыщи Брин в южной части Степей. На её дом постоянно нападают иглогривы." },
    ["1530c"] = { male = "Да? М-м-м, у меня такое чувство, что я заранее знаю твой вопрос: кому взбредёт в голову жить в сердце Степей в ожидании нападения иглогривов и без защиты? У всех нас свои причины действовать так или иначе. У меня другой вопрос – что заставило простого героя отправиться в сердце Степей разговаривать с женщиной, которую не заботит собственное благополучие? Готова поспорить, что мы оба знаем ответ на этот вопрос.", female = "Да? М-м-м, у меня такое чувство, что я заранее знаю твой вопрос: кому взбредёт в голову жить в сердце Степей в ожидании нападения иглогривов и без защиты? У всех нас свои причины действовать так или иначе. У меня другой вопрос – что заставило простого героини отправиться в сердце Степей разговаривать с женщиной, которую не заботит собственное благополучие? Готова поспорить, что мы оба знаем ответ на этот вопрос." },
    ["1531a"] = { male = "Ты делаешь успехи, дружище. Я верю, что ты достоин тотэма воздуха, но сначала надо отыскать Пратту Заклинательницу Туч в Тысяче Игл. Отнесись к ней с уважением, и она расскажет, как получить тотэм. Иди на юг, через Степи, а когда попадёшь в Тысячу Игл, сверни на восток. Пратт прячется в пещере вместе со своим парнем. Ха-ха! Только не рассказывай ей, что я проболтался тебе об этом, а то она рассердится.", female = "Ты делаешь успехи, дружище. Я верю, что ты достойна тотэма воздуха, но сначала надо отыскать Пратту Заклинательницу Туч в Тысяче Игл. Отнесись к ней с уважением, и она расскажет, как получить тотэм. Иди на юг, через Степи, а когда попадёшь в Тысячу Игл, сверни на восток. Пратт прячется в пещере вместе со своим парнем. Ха-ха! Только не рассказывай ей, что я проболтался тебе об этом, а то она рассердится." },
    ["1531c"] = { male = "Сейчас я дам тебе то, что потребуется для концентрации твоих заклинаний и призывания духов воздуха. Возьми этот тотэм. Возвращайся, когда будешь готов продолжить обучение.", female = "Сейчас я дам тебе то, что потребуется для концентрации твоих заклинаний и призывания духов воздуха. Возьми этот тотэм. Возвращайся, когда будешь готова продолжить обучение." },
    ["1532a"] = { male = "Все ветра Калимдора спешат к тебе навстречу, и скоро ты займёшь достойное место среди наших самых выдающихся братьев. Я чрезвычайно горжусь твоими успехами и вижу, что тебя ждёт великое будущее. Дух воздуха покорить нелегко, но я верю, что ты сумеешь преодолеть любые препятствия на своём пути. Отправляйся на самый юг Степей, в Тысячу Игл. Там, на востоке, ты найдёшь Пратту Заклинательницу Туч, и она продолжит твоё обучение.", female = "Все ветра Калимдора спешат к тебе навстречу, и скоро ты займёшь достойное место среди наших самых выдающихся сестёр. Я чрезвычайно горжусь твоими успехами и вижу, что тебя ждёт великое будущее. Дух воздуха покорить нелегко, но я верю, что ты сумеешь преодолеть любые препятствия на своём пути. Отправляйся на самый юг Степей, в Тысячу Игл. Там, на востоке, ты найдёшь Пратту Заклинательницу Туч, и она продолжит твоё обучение." },
    ["1532c"] = { male = "Сейчас я дам тебе то, что потребуется для концентрации твоих заклинаний и призывания духов воздуха. Возьми этот тотэм. Возвращайся, когда будешь готов продолжить обучение.", female = "Сейчас я дам тебе то, что потребуется для концентрации твоих заклинаний и призывания духов воздуха. Возьми этот тотэм. Возвращайся, когда будешь готова продолжить обучение." },
    ["1534a"] = { common = "Возьми этот бурдюк и ступай в густой лес, который ночные эльфы зовут Ясеневым. Он находится далеко на севере от Степей. Добравшись до леса, отправляйся в его западную часть. Возле гряды, отделяющей Когтистые горы от Ясеневого леса, за озером Мистраль, располагается священное место, руины Звёздной Пыли. В центре озера, на островке, есть маленький фонтан. Прежде чем возвращаться к Ислен, принеси мне воду из этого источника." },
    ["1534c"] = { common = "Чудесно. Теперь у меня есть все три пробы воды, и я могу наполнить фиал чистейшей водой, которую только способно найти живое существо. Она понадобится тебе на следующем этапе. Я рада, что среди избравших наш путь есть такие, как ты. Все шаманы гордятся тобой, и я надеюсь вскоре услышать о твоих подвигах." },
    ["1535a"] = { common = "Чтобы обрести понимание и получить от меня сапту, тебе предстоит отыскать чистейшую воду. Принося мне образцы, обращай внимание на окружающий мир – какие существа зависят от этой воды и охраняют её. Как она влияет на леса и пустыни. Ты увидишь, как влага, дающая жизнь сущему, вынуждает различных существ отнимать эту жизнь у других. Начнём с малого: ниже моего домика есть пруд с драгоценной влагой." },
    ["1535c"] = { common = "Я предполагала, что если ты возьмёшься набирать воду, кровопролития не избежать. Жаль, что иглогривы не понимают, что все живые существа связаны между собой, а жадность лишь усиливает боль и страдания их собственного народа. О, сколь многого они достигли бы, забыв о спорах и объединившись. Да, для них это плохо, но для других обитателей Степей – скорее хорошо." },
    ["1536a"] = { common = "Давным-давно мы с несколькими спутниками отправились в предгорья Хилсбрада. Нам пришлось отбиваться от навязчивых людей, поселившихся в тех краях, и в итоге мы оказались в городке, захваченном Отрёкшимися, – Мельнице Таррен. И удивительное дело – в центре города обнаружился маленький источник свежей родниковой воды. Не думаю, что поражённые чумой жители города осознают его ценность – это малый луч света в царстве тьмы. Набери воду из этого источника в этот бурдюк и принеси мне." },
    ["1536c"] = { common = "Хорошо. Ты изо-всех сил стараешься выполнить порученные тебе задания и добиваешься успеха. Ещё одна проба воды, и я смогу создать реактив, необходимый для сапты. Ислен будет довольна." },
    ["1560a"] = { common = "Я заблудился! Моя жена, Торта, отправила меня за обедом, но я не туда свернул. Отведи меня обратно к Торте! Она ждёт меня на юге от Порта Картеля." },
    ["1560c"] = { common = "Он что, сам не смог найти дорогу? Как обычно. Да, видно тебе надо дать что-нибудь за труды..." },
    ["1578a"] = { common = "Горная пехота озера Лок Модан без передышки сражается с троггами! Им нужен постоянный подвоз новых доспехов и оружия, иначе с троггами не справиться. Мой коллега Торвальд как раз и поехал туда – за тем чтобы у солдат было доброе снаряжение. Так что если бы вы могли изготовить несколько медных топоров и плетёных поясов и доставить их Торвальду, он был бы очень вам благодарен. Он даже может поделиться с вами своими знаниями. Торвальда вы найдёте в южной сторожевой башне озера Лок Модан." },
    ["1578c"] = { male = "Ох, прости! Я и не понял, что ты пришёл помочь в деле вооружения наших войск. Изготовленные тобой вещи очень нам помогут! Вот чертежи кое-каких доспехов. Надеюсь, они тебе пригодятся.", female = "Ох, прости! Я и не понял, что ты пришла помочь в деле вооружения наших войск. Изготовленные тобой вещи очень нам помогут! Вот чертежи кое-каких доспехов. Надеюсь, они тебе пригодятся." },
    ["1579a"] = { common = "Я прибыл в Аубердин в поисках тишины и покоя. Я хочу заниматься своими изобретениями там, где царит покой, потому что после ночных попоек мне совсем не нравится гомон Стальгорна! Так что я отправился на корабле в Аубердин... и по дороге слегка перебрал. Я уронил за борт мой ящик с суперразъемами! Точно не знаю, где я их потерял, но если ты попытаешься выловить их в океане, может, тебе повезёт..." },
    ["1579c"] = { male = "Ах, не могу поверить, что тебе удалось их найти! Должно быть, ты самый везучий герой на Калимдоре!", female = "Ах, не могу поверить, что тебе удалось их найти! Должно быть, ты самая везучая героиня на Калимдоре!" },
    ["1580a"] = { common = "Мы знаем, что тебе везёт, но... насколько сильно везёт? Однажды ночью я бродил по дорогам Тёмного Берега. Я искал речку или озеро, пригодные для испытания моей самодвижущейся и взрывающейся подсадной утки и, думаю, был слегка пьян... поскольку потерял сознание и пришёл в себя в Аубердине спустя несколько часов. Мои волосы были опалены, а сумка с электропеллерами исчезла! Должно быть, я уронил её в воду! Мне нужны эти электропеллеры! Может быть, тебе удастся выловить их из какого-нибудь водоёма на Тёмном Берегу?.." },
    ["1580c"] = { male = "Глазам не верю! Ты их нашёл! Ты лучший рыбак на моей памяти! Спасибо тебе. И вот, возьми это. Хотя ты, наверное, в этом и не нуждаешься, оно послужит тебе подспорьем при ужении.", female = "Глазам не верю! Ты их нашла! Ты лучшая рыбачка на моей памяти! Спасибо тебе. И вот, возьми это. Хотя ты, наверное, в этом и не нуждаешься, оно послужит тебе подспорьем при ужении." },
    ["1581a"] = { common = "Наша лавочка трав и алхимических снадобий процветает, но мой муж проводит столько времени за изготовлением эликсиров, что почти забыл про личную жизнь! Ты нам не поможешь? Если ты привезёшь мне партию уже готовых эликсиров, я охотно куплю их у тебя. У меня есть некоторые редкие травы, которые могут оказаться полезными для тебя." },
    ["1581c"] = { male = "Прекрасные снадобья! Ты проявил исключительную щепетильность, что очень важно для алхимика! Вот твои травы, я только-только их собрала. Пусть они тебе пригодятся!", female = "Прекрасные снадобья! Ты проявила исключительную щепетильность, что очень важно для алхимика! Вот твои травы, я только-только их собрала. Пусть они тебе пригодятся!" },
    ["1582a"] = { common = "У нас, жителей Дарнасса, в особенности у ремесленников, работы невпроворот. Молодым искателям приключений неймётся испытать себя во всякой глухомани, так что нам постоянно нужен подвоз материалов. Если ты поможешь мне выполнить заказ на кожаные изделия, я, может, научу тебя более совершенной технике работы с кожей." },
    ["1582c"] = { common = "Да, славные изделия. У тебя искусные руки и острый глаз. Из тебя может получиться неплохой кожевник. Слушай. Давай-ка я покажу тебе выкройку жилета Лунного сияния." },
    ["1598a"] = { male = "Ах, это ты! Тебя зовут путник, верно? Надеюсь, ты точно уверен, что желаешь стать чернокнижником, поскольку если ты не умеешь постоять за себя, среди нас тебе делать нечего. Я буду тебя обучать, но сначала я должна убедиться, что ты достаточно силён. В здешнем аббатстве обучался один послушник, который сбежал и вступил в Братство Справедливости. Почему меня это волнует? А потому, что он стянул из аббатства кое-какие важные книги. Одну из них я сама хотела бы иметь. Братство прячет эту книгу – \"Силы Бездны\" – в своём шатре на виноградниках. Принеси её мне.", female = "Ах, это ты! Тебя зовут путница, верно? Надеюсь, ты точно уверена, что желаешь стать чернокнижницей, поскольку если ты не умеешь постоять за себя, среди нас тебе делать нечего. Я буду тебя обучать, но сначала я должна убедиться, что ты достаточно сильна. В здешнем аббатстве обучался один послушник, который сбежал и вступил в Братство Справедливости. Почему меня это волнует? А потому, что он стянул из аббатства кое-какие важные книги. Одну из них я сама хотела бы иметь. Братство прячет эту книгу – \"Силы Бездны\" – в своём шатре на виноградниках. Принеси её мне." },
    ["1598c"] = { male = "Замечательно... Мне никогда не удавалось добраться до этой книги, его держали в охраняемом крыле библиотеки, и было бы подозрительно, если бы я стала рыскать вокруг. Ладно, ты отлично потрудился, и я уверена, что ты сумеешь справиться со своим собственным бесом. Пора показать тебе, как его вызывать!", female = "Замечательно... Мне никогда не удавалось добраться до этой книги, его держали в охраняемом крыле библиотеки, и было бы подозрительно, если бы я стала рыскать вокруг. Ладно, ты отлично потрудилась, и я уверена, что ты сумеешь справиться со своим собственным бесом. Пора показать тебе, как его вызывать!" },
    ["1598p"] = { common = "Было бы слишком опасно самой пытаться украсть эту книгу из аббатства. Какая удача, что этот простофиля сделал всю грязную работу за меня!" },
    ["1599a"] = { common = "Тут все шепчутся о каком-то новом чернокнижнике; наверное, это ты и есть. Должно быть, ты вызываешь кое у кого сильную симпатию, раз меня попросили отвлечься от моих изысканий и посвятить некоторое время занятиям с тобой. Не беспокойся: я не ставлю это тебе в вину. Что ж, самое простое из заклинаний призыва позволяет вызвать беса. Однако, прежде чем я преподам тебе этот урок, мне хотелось бы получить доказательства того, что у тебя достаточно как физической, так и магической силы... Принеси мне три оберега из перьев. Ты получишь их, если расправишься с новобранцами племени Мерзлогривов в пещере, что к юго-западу отсюда." },
    ["1599c"] = { common = "Прекрасно, прекрасно! В самом деле, неплохая работа. Возможно, те, кто тебя рекомендовал, и не ошиблись... Впрочем, это не мне решать. Поживём – увидим. Будем надеяться, что первый же вызванный бес не вырвет тебе сердце и не сожрёт внутренности – думаю, подобное могло бы серьёзно повредить твоей карьере. Пока у меня есть основания полагать, что в качестве чернокнижника ты сумеешь прожить хотя бы несколько месяцев. Кстати, хотел тебе дать тебе совет по поводу бесов. Запомни, размер – ещё не главное: даже самый глупый таурен знает, что бесы наделены весьма сильной магией." },
    ["1618a"] = { common = "Не только мы, дворфы, сражаемся денно и нощно – люди, наши союзники, тоже не прохлаждаются! На Красногорье время от времени устраивают налёты орки Чёрной Горы, а снаряжения туда всегда мало поставляется. Если ты им поможешь, то местный кузнец Вернер Осгуд наверняка научит тебя паре хитростей." },
    ["1618c"] = { common = "Спасибо. Это чрезвычайно мне поможет. Орки Чёрной Горы нападают со стороны крепости Каменной Стражи, а гноллы Красногорья шныряют в северных предгорьях, и мне постоянно приходится чинить доспехи и делать новое оружие для наших войск. То, что ты принёс, даст мне хоть небольшую передышку. И у меня будет время кое-чему тебя научить..." },
    ["1638a"] = { common = "Ты в самом деле неплохой воин, но лет тебе мало, и ещё многому придётся научиться. Поговори с Гарри Берлгардом – обычно он сидит в \"Свинье и Свистке\", в Старом городе Штормграда. Гарри опытный боец и неплохой учитель. Он покажет тебе несколько приёмов, глядишь, и подольше проживёшь." },
    ["1638c"] = { male = "О-хо! Выпей со мной, парень. С первого взгляда ты кажешься крепким, посмотрим, что с тобой сделает несколько кружек крепкого пива!!! Или... А, да ты поучиться хочешь?", female = "О-хо! Выпей со мной, парень. С первого взгляда ты кажешься крепкой, посмотрим, что с тобой сделает несколько кружек крепкого пива!!! Или... А, да ты поучиться хочешь?" },
    ["1639a"] = { male = "Да, я могу заняться твоим обучением, но сначала хочу взглянуть, на что ты годишься. Видишь, в конце бара стоит выпивка? Бартлби тоже видишь? Добудь эту кружку. Ха, если ты знаком с ним, то догадаешься, что так просто он её не отдаст.", female = "Да, я могу заняться твоим обучением, но сначала хочу взглянуть, на что ты годишься. Видишь, в конце бара стоит выпивка? Бартлби тоже видишь? Добудь эту кружку. Ха, если ты знакома с ним, то догадаешься, что так просто он её не отдаст." },
    ["1639c"] = { male = "Эй, красавчик! Что таким как ты делать в \"Свинье и свистке\"? Осторожнее, неровен час, ноготь сломаешь...", female = "Эй, красавица! Что таким как ты делать в \"Свинье и свистке\"? Осторожнее, неровен час, ноготь сломаешь..." },
    ["1640a"] = { male = "Что ты хочешь? Да ты спятил! Эту кружку ты получишь только через мой труп...", female = "Что ты хочешь? Да ты спятила! Эту кружку ты получишь только через мой труп..." },
    ["1640c"] = { common = "А ты крепче, чем кажешься с первого взгляда." },
    ["1642a"] = { common = "Во всех своих деяниях паладин должен быть достоин того Света, которому мы служим и который дарует нам силу. Для таких, как мы, стремление к божественности не означает желания стать богами: мы лишь стремимся творить добро. Ныне наступили тяжёлые времена: мы избраны для того, чтобы сражаться со злом и повергнуть его. Однако помни: не борьба со злом отличает нас от прочих жителей Азерота. Сострадание, терпение, отвага и помощь ближним – для паладина всё это значит не меньше, чем искусство воина. Никогда не забывай об этом!" },
    ["1642c"] = { common = "И снова рад приветствовать тебя. Как идёт изучение Фолианта Божественности? Помни: тебе предстоит пройти испытание. Каждого из нас ждёт множество свершений – как в городе, так и в иных землях. Всегда есть люди, нуждающиеся в помощи, сострадании и понимании, всегда есть враждебные твари, которых необходимо уничтожать во благо людей. Докажи, что ты можешь помогать своим ближним – в особенности тем, кому меньше повезло в жизни. Тем самым ты докажешь, что твои помыслы чисты и что ты воистину служишь Свету." },
    ["1643a"] = { common = "Итак, твоя задача – найти в Штормграде того, кто нуждается в помощи. Того, кто чист сердцем и помыслами. Возможно, это тот, кто сам помогает другим. Возможно – тот, кто нуждается в наставнике. Как бы то ни было, намерения того, кого ты ищешь, будут благородны, и он во всём будет полагаться на тебя. Ты возвратишься ко мне, когда исполнишь это задание, и мы поговорим о твоём пути – а равно и о том, что значит быть паладином Света." },
    ["1643c"] = { male = "О, привет, дорогой. Что, всё ищешь приключений? Я так рада, что у тебя всё в порядке! Я? А что я? Ну, с учётом обстоятельств, у меня тоже дела идут неплохо... Правда, торговцев у нас тут прибавилось, а пожертвований на сиротский приют стало меньше: зачем отдавать даром то, что можно продать? Но ничего, мы справимся. Под \"нами\" я имею в виду себя и своего мужа, конечно. Он сейчас в Стальгорне, пытается заручиться помощью тамошних жителей...", female = "О, привет, милашка. Что, всё ищешь приключений? Я так рада, что у тебя всё в порядке! Я? А что я? Ну, с учётом обстоятельств, у меня тоже дела идут неплохо... Правда, торговцев у нас тут прибавилось, а пожертвований на сиротский приют стало меньше: зачем отдавать даром то, что можно продать? Но ничего, мы справимся. Под \"нами\" я имею в виду себя и своего мужа, конечно. Он сейчас в Стальгорне, пытается заручиться помощью тамошних жителей..." },
    ["1644a"] = { common = "Да будут благословенны эти несчастные! Многие из них потеряли родных во время набегов нежити... Мой муж Джон помогает мне доставать ткань, чтобы я могла шить сироткам одежду, но увы, на это у меня не хватает времени, ведь их нужно сначала накормить и дать им кров. Что? Правда? Ты хочешь мне помочь? Благодарение Вечному Свету! Благодарю тебя! Если бы у меня был лён на одёжки малышам, их жизнь стала бы хоть немного легче..." },
    ["1644c"] = { common = "Ах, благодарю, благодарю тебя! Детишки так рады будут, да и у меня будет побольше времени на них. Надеюсь, теперь Джон сможет возвратиться поскорее. Прими мою искреннюю признательность. Я всегда верила, что в сердцах людей есть место милосердию. Да пребудет с тобой Извечный Свет." },
    ["1646a"] = { common = "Паладин во всех делах своих должен быть проявлением Света, который есть источник нашей силы. Стремление к божественности для нас не означает стремления стать божеством – мы стремимся к добру во всех деяниях наших. Хотя в эти тяжёлые времена мы призваны сокрушать зло, тебе всегда следует помнить: лишь помогая другим, ты выделяешься среди других обитателей Азерота. Сочувствие, терпение, отвага – все эти достоинства значат для паладина не меньше, чем сила в сражении. Усвой же это и помни всегда." },
    ["1646c"] = { male = "С возвращением. Надеюсь, ты нашёл время на прочтение книги? Тогда ты должен быть готов к испытанию. Есть задания, которые необходимо сделать по всему нашему городу и на наших землях; акты сострадания и понимания; люди, которые нуждаются в помощи; существа, которых необходимо убить. Доказав что у тебя есть терпение, особенно в помощи людям, которые менее удачливы, ты докажешь, что ты слуга Света.", female = "С возвращением. Надеюсь, ты нашла время на прочтение книги? Тогда ты должна быть готова к испытанию. Есть задания, которые необходимо сделать по всему нашему городу и на наших землях; акты сострадания и понимания; люди, которые нуждаются в помощи; существа, которых необходимо убить. Доказав что у тебя есть терпение, особенно в помощи людям, которые менее удачливы, ты докажешь, что ты слуга Света." },
    ["1647a"] = { common = "Твоя задача, найти в Стальгорне кого-нибудь, кто нуждается в помощи. Того, кто чист душой и помыслами. Может быть, того, кто сам помогает другим. Того, кто нуждается в совете. Кто бы то ни был, у него должны быть благородные стремления и он должен полагаться на твою доброту. Сделай это и по выполнении возвращайся ко мне. Тогда мы ещё поговорим о твоём пути и о том, что значит быть паладином Света. Я останусь в храме до твоего возвращения. Моё наставничество нужно и другим паладинам." },
    ["1647c"] = { common = "СИРОТСКИЙ ПРИЮТ ШТОРМ... о, простите, я вовсе не хотел кричать на вас, сударь. Меня зовут Джон Тернер. Как поживаете? Рад, искренне рад слышать, что у вас всё хорошо. А у меня был трудный день, я тоскую по жене, но такова цена, которую приходится платить, чтобы накормить голодные рты и одеть нагих." },
    ["1648a"] = { common = "Мы с женой держим в Штормграде сиротский приют, по большей части для детей, потерявших родителей во время нападений Плети в последние десять лет. Я приезжаю в Стальгорн примерно раз в месяц и занимаюсь сбором средств у здешних горожан, а также прошу помощи у различных организаций. Нынешняя поездка была мучительно медленной и не слишком продуктивной. Если бы мне удалось добыть ещё немного льняной ткани для одежды, я бы смог, наконец, отправить посылку домой." },
    ["1648c"] = { common = "Это так прекрасно с вашей стороны. Снова большое вам спасибо. Вы благородный человек, что так помогли мне. Не удивительно, что вы избрали путь Света. Хотел бы я, чтобы был какой-либо способ отплатить вам за всё, что вы сделали... что? Это наименьшее что вы могли сделать? Видите? Это как раз то, о чём я говорю, вы благородны до самого конца. Берегите себя, и да охранит вас Свет в ваших путешествиях." },
    ["1649a"] = { common = "Отвага и сопутствующие ей достоинства подобны драгоценным металлам. Нужно беречь их, когда находишь, ибо цена их велика, но также необходимо копить и приумножать их. Тогда они образуют крепчайший сплав, зачастую выдерживающий даже самые сильные удары. Твои сила, вера и храбрость должны быть испытаны. Тебе надлежит научиться хранить веру в любых обстоятельствах и понять, что с помощью сил Света ты сможешь преодолеть те препятствия, которые не по силам другим." },
    ["1649c"] = { common = "Ты просишь испытать твою отвагу? Прекрасно! Для тебя в городе и в окрестностях найдётся немало заданий. Нам как раз нужен кто-нибудь с твоими способностями. Это испытание не будет лёгким! Оно, как и многое в нашей профессии, может привести к гибели. Церковь всегда готова поддержать своих слуг, но без жертв невозможно определить, достоин ли паладин служить правому делу. Чувствуешь ли ты в себе готовность к испытанию?" },
    ["1650a"] = { common = "Отлично! Отсутствие сомнений говорит о твоей готовности к испытаниям. Да будет так! В самом конце Долгого Берега стоит небольшой домик с окнами на океан. Там живёт чёта Стивеллов. Джордан – великолепный кузнец, и сейчас он собирается в Стальгорн, чтобы навестить дворфов. Но его жена Дафна остаётся дома одна, без защиты... Донесения говорят, что Братство Справедливости захватило почти весь край. Дафне может понадобиться защита от злодеев. Отправляйся туда." },
    ["1650c"] = { common = "Здравствуй. Я полагаю, что со всем этим оружием в руках ты хочешь либо захватить мои земли, либо Церковь наконец-то послала мне защитника на время поездки Джордана. Позволь представиться: я – Дафна Стилвелл. Очень приятно! Твоё прибытие очень кстати: с восхода солнца я уже прикончила с полдюжины этих мерзавцев. До этого они не особо торопились, но сейчас они наверняка заметили тебя, а значит, будут здесь с минуты на минуту..." },
    ["1651a"] = { common = "Бьюсь об заклад, они скоро вернутся – так что приготовься. В доме есть пистолет, я возьму его и при необходимости помогу тебе, но лучше рассчитывай только на свои силы. Не знаю, сколько их будет, но уверена, что больше, чем в прошлый раз. Моли Свет благословить тебя, потому что… Слышишь? Они идут! Укроемся за домом!" },
    ["1651c"] = { common = "Мы победили! Благодарю тебя за помощь. Это было просто великолепно! Я и не думала, что паладин может справиться с таким количеством врагов зараз. Твоя выдающаяся храбрость перед лицом превосходящих сил потрясла меня..." },
    ["1652a"] = { common = "Прошу, возвращайся к Даториану и передай ему, что теперь со мной всё в порядке – благодаря тебе и Церкви. Он пошлёт весть в Стальгорн, чтобы мой Джордан не волновался за меня. Ох, как я соскучилась по своему мужу! Жду не дождусь его возвращения..." },
    ["1652c"] = { common = "Вот мы и встретились снова. Я вижу, что дух твой бодр. Дом четы Стивеллов теперь в безопасности, а из твоего рассказа ясно, что ему теперь ещё долго ничего не будет угрожать. Отлично! Дафна и Джордан немало помогли Церкви. Отправить тебя на их защиту – весьма скромная ответная услуга. Ты получишь награду за проявленную отвагу." },
    ["1653a"] = { common = "Вообще я не сомневаюсь, что Джордан захочет лично отблагодарить тебя, и раз уж мне надо сообщить ему, что его жена в безопасности, то, думаю, лучше всего тебя посланником и отправить. Джордан был паладином Света, до того как приверженность отцовскому ремеслу увлекла его на другой путь, – а потому он хорошо знает наш образ жизни и считается одним из самых надёжных наших приверженцев. Он должен ещё быть в Стальгорне – он любит работать днём за воротами, там где с гор тянет холодным воздухом." },
    ["1653c"] = { common = "Добрый день. Вижу, ты служишь Свету? Что это? Тебя послал Даториан?! Моя жена, как она? Я так и знал – стоит уехать, сразу беды нагрянут. Скажи мне, она... о, хвала Свету. Я так счастлив, что она в безопасности. Это Братство Справедливости было опасным ещё до нынешних своих налётов, но теперь уж королевские советники не смогут этой угрозы отрицать. Что ещё велел передать Даториан? Именно ты и назначен был оберегать мою жену? Тогда ещё раз прими мою благодарность. Не могу придумать лучшего испытания доблести, чем это." },
    ["1654a"] = { male = "Я хотел бы отблагодарить тебя, если ты согласишься принять этот дар. Пойми меня правильно, всё будет зависеть от того, насколько ты мне поможешь, но я вижу, что от такого сотрудничества обоим нам выйдет большая выгода. Я скую для тебя оружие, достойное твоего деяния, оружие, что станет символом призвания паладина и пути Света. Но тебе придётся добыть необходимые для ковки предметы. Я уже набросал список, так что остаётся только, чтобы некто отважный и искусный принёс их мне. Что скажешь, герой?", female = "Я хотел бы отблагодарить тебя, если ты согласишься принять этот дар. Пойми меня правильно, всё будет зависеть от того, насколько ты мне поможешь, но я вижу, что от такого сотрудничества обоим нам выйдет большая выгода. Я скую для тебя оружие, достойное твоего деяния, оружие, что станет символом призвания паладина и пути Света. Но тебе придётся добыть необходимые для ковки предметы. Я уже набросал список, так что остаётся только, чтобы некто отважный и искусный принёс их мне. Что скажешь, героиня?" },
    ["1654c"] = { male = "Великолепно! Ты добыл всё необходимое. Теперь я легко изготовлю для тебя великолепное оружие! Я и так собирался когда-нибудь его выковать, просто не было возможности достать всё необходимое. Спасибо тебе. Как же приятно снова держать в руке молот моих отцов... и самоцвет Кора – я и не думал, что когда-нибудь увижу его собственными глазами!", female = "Великолепно! Ты добыла всё необходимое. Теперь я легко изготовлю для тебя великолепное оружие! Я и так собирался когда-нибудь его выковать, просто не было возможности достать всё необходимое. Спасибо тебе. Как же приятно снова держать в руке молот моих отцов... и самоцвет Кора – я и не думал, что когда-нибудь увижу его собственными глазами!" },
    ["1655a"] = { male = "Ох, и испугал ты меня, парень! Не видишь, что я в размышлениях? Это что ещё? Поставка Джордану... Стальгорн. А, да, я понял, о чём речь. Мо'грошские огры ограбили меня, и нет у меня руды для старого друга. Караван шёл сюда из Болотины и попал в засаду. Охранник, что уцелел, помер пару дней назад – целитель не поспел вовремя. Если хочешь найти эту партию руды, то придётся тебе двинуться на север, за озеро Лок. Она где-то там.", female = "Ох, и испугала ты меня, дамочка! Не видишь, что я в размышлениях? Это что ещё? Поставка Джордану... Стальгорн. А, да, я понял, о чём речь. Мо'грошские огры ограбили меня, и нет у меня руды для старого друга. Караван шёл сюда из Болотины и попал в засаду. Охранник, что уцелел, помер пару дней назад – целитель не поспел вовремя. Если хочешь найти эту партию руды, то придётся тебе двинуться на север, за озеро Лок. Она где-то там." },
    ["1655c"] = { male = "Ну-ну, надо же! Знал бы я, что ты и правда прямо туда и пойдёшь и навтыкаешь этим ограм, я бы дал тебе целый список, что оттуда принести. Но ведь ты тут не за тем, чтобы за меня работу делать, верно? А сделка есть сделка. Джордан хотел получить свою руду, и он её получит. Передай ему приветик от меня, и доброй тебе дороги, герой.", female = "Ну-ну, надо же! Знал бы я, что ты и правда прямо туда и пойдёшь и навтыкаешь этим ограм, я бы дал тебе целый список, что оттуда принести. Но ведь ты тут не за тем, чтобы за меня работу делать, верно? А сделка есть сделка. Джордан хотел получить свою руду, и он её получит. Передай ему приветик от меня, и доброй тебе дороги, героиня." },
    ["1656a"] = { common = "Умоляю, помоги мне! У меня ещё есть дело здесь, на плато - я прохожу обряд Силы, - а мой отец требует, чтобы я срочно доставила эти меха в таверну в деревне Кровавого Копыта! Как же мне выполнить сразу обе задачи - завершить ритуал и отнести меха?! Не отнесёшь ли ты их вместо меня? Таверна - такое милое и уютное местечко, там есть всё, чего может пожелать притомившийся путник. Даю слово, тебе понравится!" },
    ["1656c"] = { common = "О, а вот и мои меха! Благодарю вас. Вы доставили их даже быстрее, чем я ожидал. Они послужат отличными одеялами для моих постояльцев. Прошу вас, гостите в таверне, сколько пожелаете. Наши двери всегда открыты, и мы рады каждому. Не стоит недооценивать значение полноценного отдыха - особенно если впереди дальняя дорога." },
    ["1661a"] = { male = "Приветствую тебя! Я несказанно рад тому, что могу называть тебя Братом: твоё посвящение – радость для всех нас. Пришло время вручить тебе великий дар. Но знай: сейчас я даю его тебе, не требуя ничего взамен; но потом настанет час, когда всем паладинам придётся немало потрудиться для того, чтобы получить его. Приходи в любое время – я отдам тебе твой подарок.", female = "Приветствую тебя! Я несказанно рад тому, что могу называть тебя Сестрой: твоё посвящение – радость для всех нас. Пришло время вручить тебе великий дар. Но знай: сейчас я даю его тебе, не требуя ничего взамен; но потом настанет час, когда всем паладинам придётся немало потрудиться для того, чтобы получить его. Приходи в любое время – я отдам тебе твой подарок." },
    ["1661c"] = { common = "Поздравляю! Да пребудет с тобой Свет!" },
    ["1665a"] = { common = "Ладно, бери мою кружку. Стой! Дай-ка я хотя бы допью... Ну вот. Бери." },
    ["1665c"] = { common = "А вот и кружка! Да уж, он не хотел с ней расставаться, но ты умеешь настоять на своём. Молодец. Приступим к обучению..." },
    ["1666a"] = { male = "Ты освоил несколько новых приёмов, но без хорошего оружия тебе не обойтись. Думаю, тебе мог бы помочь маршал Хаггард. Он живёт в своём поместье в Элвиннском лесу, возле лесозаготовок Восточной Долины. Он ушёл в отставку, но за время службы собрал недурную коллекцию оружия. Скажи, что тебя прислал я, и если повезёт, он поделится лишним оружием.", female = "Ты освоила несколько новых приёмов, но без хорошего оружия тебе не обойтись. Думаю, тебе мог бы помочь маршал Хаггард. Он живёт в своём поместье в Элвиннском лесу, возле лесозаготовок Восточной Долины. Он ушёл в отставку, но за время службы собрал недурную коллекцию оружия. Скажи, что тебя прислал я, и если повезёт, он поделится лишним оружием." },
    ["1666c"] = { male = "Кто это? Баргард, это ты? Подойди поближе. Глаза у меня уже не те. Ты так подкрался, что я принял тебя за гнолла!", female = "Кто это? Баргард, это ты? Подойди поближе. Глаза у меня уже не те. Ты так подкралась, что я принял тебя за гнолла!" },
    ["1667a"] = { common = "Тебя ведь прислал Баргард? Да, у меня есть запасное оружие, но сначала я хочу дать тебе задание… Некоторое время назад меня обманул злодей из Братства Справедливости, Джек Мертвозуб. Он пришёл в темноте, одетый в гербовую накидку Штормграда, и я принял его за маршала Дугхана. Джек сказал, что ему нужен мой старый знак маршала, и я, не раздумывая, отдал его... а потом он захохотал и сбежал, прежде, чем я успел его схватить! Верни мне мой знак! Джек Мертвозуб наверняка прячет его в лагере на юге." },
    ["1667c"] = { common = "Ура, мой знак у тебя! Я боялся, что лишился его навсегда, а шваль из Братства Справедливости получила возможность изображать из себя представителей власти. Тебе же удалось предотвратить невиданный разгул преступности. Вот моё оружие, которое лежит без дела с тех времён, как я был маршалом. Я его регулярно чистил его, и оно в отличной форме, выбирай!" },
    ["1678a"] = { male = "Хорошему воину пристало быть стойким. Я научу тебя новым приёмам, но прежде докажи, что сможешь справиться с серьёзными противниками. Веджрек – один из самых сильных троллей в наших краях. Ему-то ты и бросишь вызов. Он живёт в хижине в предгорьях, чуть южнее форта Мерзлогривов. Принеси мне голову Веджрека, и я поверю, что ты не лыком шит.", female = "Хорошему воину пристало быть стойким. Я научу тебя новым приёмам, но прежде докажи, что сможешь справиться с серьёзными противниками. Веджрек – один из самых сильных троллей в наших краях. Ему-то ты и бросишь вызов. Он живёт в хижине в предгорьях, чуть южнее форта Мерзлогривов. Принеси мне голову Веджрека, и я поверю, что ты не лыком шита." },
    ["1678c"] = { male = "Ну и урод же был этот Веджрек, а? Отличная работа! У тебя есть всё, что нужно. А теперь начнём твой урок... Ты, может, и не знал, но крепкая защита — жизненно важна для герой. Она позволяет ему стоять на ногах там, где другие пали бы, — а именно этого и ждут от тебя твои союзники", female = "Ну и урод же был этот Веджрек, а? Отличная работа! У тебя есть всё, что нужно. А теперь начнём твой урок... Ты, может, и не знала, но крепкая защита — жизненно важна для героиня. Она позволяет ему стоять на ногах там, где другие пали бы, — а именно этого и ждут от тебя твои союзники" },
    ["1679a"] = { male = "Привет тебе, воин! Ты наделён многими талантами, но тебе предстоит многому научиться, и лучше учителя, чем Марен Грозовая Вершина, не найдёшь. Марен в Оружейной, в Палатах Войны Стальгорна. Как только ты решишь сделать очередной шаг на пути воина, поговори с ним.", female = "Привет тебе, воин! Ты наделена многими талантами, но тебе предстоит многому научиться, и лучше учителя, чем Марен Грозовая Вершина, не найдёшь. Марен в Оружейной, в Палатах Войны Стальгорна. Как только ты решишь сделать очередной шаг на пути воина, поговори с ним." },
    ["1679c"] = { common = "А. Я слышал твоё имя от воинов Дун Морога. Надеюсь, ты не всё время проводишь в пивных?" },
    ["1680a"] = { male = "Ты уже освоил несколько приёмов, пора заняться твоим оружием. Поговори с Тормусом Подземной Кузней. Он скуёт тебе оружие по вкусу. Тормус живёт здесь, в Стальгорне, в Великой Кузне.", female = "Ты уже освоила несколько приёмов, пора заняться твоим оружием. Поговори с Тормусом Подземной Кузней. Он скуёт тебе оружие по вкусу. Тормус живёт здесь, в Стальгорне, в Великой Кузне." },
    ["1680c"] = { common = "Тебя прислал Марен? Да, я могу сковать тебе превосходное оружие... Но услуга за услугу. Не бойся. Конечно, задание будет опасным, ты можешь погибнуть, но разве не к этому стремятся все воины?" },
    ["1681a"] = { common = "У моего наставника, Стурги Сталекрута, была мастерская на юге от озера Хельмова ложа в восточной части Дун Морога. Он был лучшим учителем кузнечного дела. Но однажды ученики принесли ему странную руду. Мастер Сталекрут назвал её мрачной рудой и с радостью с ней работал, но увы, вскоре на них напал отряд дворфов Чёрного Железа. Они поубивали всех! Ступай в мастерскую Сталекрута, и отомсти за смерть моего учителя. И принеси мне груз мрачной руды." },
    ["1681c"] = { male = "Ты нашёл её! Молодец! Надеюсь, что в ходе поисков ты убил целую толпу дворфов Чёрного Железа. Боюсь, нам придётся столкнуться с ними не только в мастерской Сталекрута. Впрочем, спасибо за руду. Я с радостью поработаю с ней и исследую её свойства.", female = "Ты нашла её! Молодец! Надеюсь, что в ходе поисков ты убила целую толпу дворфов Чёрного Железа. Боюсь, нам придётся столкнуться с ними не только в мастерской Сталекрута. Впрочем, спасибо за руду. Я с радостью поработаю с ней и исследую её свойства." },
    ["1682c"] = { common = "Вот тебе оружие, только что с наковальни. На него пошла добытая тобой мрачная руда! Что же, путник, выбирай!" },
    ["1683a"] = { common = "Прежде чем браться за твоё обучение, я хочу испытать твою храбрость. Сатир Ворлус Подлое Копыто обнаружил один из наших лунных колодцев, тот, что на юго-востоке от обители Бен'этиль. Он плещется в его светлых водах, оскверняя их своим присутствием. Отыщи Ворлуса и убей его. В доказательство принеси мне его рог, и я возьмусь учить тебя. Отыскать дорогу к колодцу очень трудно, но тот, кто ищет, тот всегда найдёт." },
    ["1683c"] = { common = "Спасибо тебе. Приятно знать, что Ворлус мёртв, а наш колодец снова чист, и не менее приятно видеть молодых воинов, которые хотят очистить наш любимый Тельдрассил от порчи. Приступим к обучению..." },
    ["1684a"] = { common = "Приветствую тебя, воин. Ты растёшь над собой, но профессия воина не так проста, как кажется. Тебе нужен хороший учитель. В Дарнассе, на террасе Воинов, живёт Эланария. Поучись у неё." },
    ["1684c"] = { common = "Приветствую тебя. В Дарнассе говорят, что ты подаёшь надежды. Впрочем, скоро мы узнаем, хватит ли тебе силы воли, чтобы следовать путём воина." },
    ["1685a"] = { common = "И вот так всегда. Я разыскивал тебя весь день, но так и не смог найти; а сейчас, когда я вовсе этого не ожидал, ты появляешься как из-под земли. Я уже и так слишком много времени потратил на твои поиски, так что буду краток. Наставник Гакин призывает тебя для дополнительных занятий – и, думаю, тебе стоит поторопиться. Ты найдёшь его в подвале таверны \"Забитый ягнёнок\". К слову сказать, не стоит много болтать об этом месте..." },
    ["1685c"] = { common = "Наконец-то ты здесь. Мне следовало послать за тобой кого-нибудь более расторопного, чем Ремен. Ну, неважно. Когда у тебя было последнее занятие? Слишком давно, слишком... А ты знаешь, что у плохо обученного чернокнижника мало шансов сохранить голову на плечах?" },
    ["1686a"] = { male = "Ты многому научился. Пора создать для тебя настоящее оружие. Оружие воина. Тебе придётся отправиться за ним на Тёмный берег. Давным-давно один корабль разбился о камни рядом с Аубердинским маяком, и по дну моря рассеялось множество сундуков с элунитовой рудой. Для начала тебе придётся одержать верх над стражем элунита, тенью Элуры. Она была капитаном затонувшего корабля, а после смерти сама обрекла себя на то, чтобы стать последним стражем груза. Победи её, забери у неё медальон и собери со дна ящики с элунитом.", female = "Ты многому научилась. Пора создать для тебя настоящее оружие. Оружие воина. Тебе придётся отправиться за ним на Тёмный берег. Давным-давно один корабль разбился о камни рядом с Аубердинским маяком, и по дну моря рассеялось множество сундуков с элунитовой рудой. Для начала тебе придётся одержать верх над стражем элунита, тенью Элуры. Она была капитаном затонувшего корабля, а после смерти сама обрекла себя на то, чтобы стать последним стражем груза. Победи её, забери у неё медальон и собери со дна ящики с элунитом." },
    ["1686c"] = { common = "Да, отваги тебе не занимать. Тень Элуры наконец-то обрела покой, а из добытого элунита тебе скуют прекрасное оружие." },
    ["1688a"] = { common = "У меня была ученица по имени Сурена Каледон. Помню, она стояла как раз там, где сейчас стоишь ты… Просила меня научить её искусству чернокнижия, а у самой даже капли таланта к этому не было. Хм, зато она была молода и довольно миловидна. Если бы я видел тогда, что это за вероломная дрянь! Распутная девка сбежала с одним из членов Братства Справедливости по имени Эрлан Драджмур. Об этой потере я нисколько не сожалею, однако колье Кровавого камня, которое я подарил ей, мне всё ещё нужно. Её жизнь для меня больше ничего не значит. Ты найдёшь девку на тыквенной ферме Бреквеллов. Верни мне моё имущество!" },
    ["1688c"] = { common = "Сурена была талантлива, но не настолько, чтобы овладеть чарами самостоятельно. Печально видеть, как погибают молодые и талантливые, но иногда без этого нельзя. Надеюсь, усилия, вложенные в тебя, прахом не пойдут..." },
    ["1689a"] = { male = "Вернув моё колье и обманув Сурену, ты доказал, что не уступаешь ей в таланте. Поэтому я уверен, что тебе не помешает обучение. Ты можешь управлять потоками магической энергии, но чернокнижник должен уметь намного больше. Я научу тебя управлять демоном Бездны, но прежде тебе нужно призвать его в круг призыва и покорить, используя любое оружие, которое имеется в твоём распоряжении. Используй магию колье в кругу призыва.", female = "Вернув моё колье и обманув Сурену, ты доказала, что не уступаешь ей в таланте. Поэтому я уверен, что тебе не помешает обучение. Ты можешь управлять потоками магической энергии, но чернокнижник должен уметь намного больше. Я научу тебя управлять демоном Бездны, но прежде тебе нужно призвать его в круг призыва и покорить, используя любое оружие, которое имеется в твоём распоряжении. Используй магию колье в кругу призыва." },
    ["1689c"] = { common = "Тебе удалось даже больше, чем я ожидал. На это я и надеялся. Теперь ты можешь научиться управлять покорённым тобой демоном. Он станет твоим помощником в предстоящих испытаниях. Сейчас мне нечему больше учить тебя, но я уверен, что мы с тобой, ещё увидимся..." },
    ["1690a"] = { common = "Эй, ты! Пора оказать услугу Водной компании Прибамбасска. Кочевники Скитальцев Пустыни захватили почти все колодцы пустыни Танарис! Без них у нас мигом закончится вода. Если ты хочешь заслужить нашу признательность, расправься с этими варварами! Ступай на восток и прикончи десять бандитов и десять воров из шайки Скитальцев Пустыни, а на обратном пути доложись мне. Никому не миновать расправы... или как там говорится... А, неважно, иди себе!" },
    ["1690c"] = { male = "Ну, вот это называется эффективность! Ты помог нам сократить число кочевников, и мы начинаем подумывать о том, чтобы отбить наши колодцы. Водная компания Прибамбасска благодарит тебя за помощь, но мы ещё не разобрались с этими проклятыми кочевниками. Слушай внимательно – вот что нам понадобится теперь...", female = "Ну, вот это называется эффективность! Ты помогла нам сократить число кочевников, и мы начинаем подумывать о том, чтобы отбить наши колодцы. Водная компания Прибамбасска благодарит тебя за помощь, но мы ещё не разобрались с этими проклятыми кочевниками. Слушай внимательно – вот что нам понадобится теперь..." },
    ["1691a"] = { male = "Теперь тебе придётся схватиться с кочевниками посильнее. Ты неплохо поработал, но если отбивать у этих гадов наши колодцы, лучше бы противников было поменьше! На сей раз выступи против разбойников, убийц и тёмных магов. Их можно найти на востоке и юго-востоке отсюда. Не буду тебе лгать – справиться с ними нелегко. Зато в случае успеха мы очень скоро сможем вернуть себе принадлежащее нам по праву!", female = "Теперь тебе придётся схватиться с кочевниками посильнее. Ты неплохо поработала, но если отбивать у этих гадов наши колодцы, лучше бы противников было поменьше! На сей раз выступи против разбойников, убийц и тёмных магов. Их можно найти на востоке и юго-востоке отсюда. Не буду тебе лгать – справиться с ними нелегко. Зато в случае успеха мы очень скоро сможем вернуть себе принадлежащее нам по праву!" },
    ["1691c"] = { male = "Первоклассная работа… первоклассная! Число кочевников сократилось настолько, что мы можем бросить им вызов! Ты уже поговорил с оператором крана Тормозиллером? Он предлагает награду за меха с водой, которые могли тебе попасться во время битвы с кочевниками!", female = "Первоклассная работа… первоклассная! Число кочевников сократилось настолько, что мы можем бросить им вызов! Ты уже поговорила с оператором крана Тормозиллером? Он предлагает награду за меха с водой, которые могли тебе попасться во время битвы с кочевниками!" },
    ["1692a"] = { common = "Я сложила собранный тобой элунит в сундук. Отнеси его кузнецу Матилю, мы сделаем из него элунитовое оружие. Матиль на юге отсюда, на другой стороне этого здания." },
    ["1692c"] = { common = "А, элунитовая руда. Работать с этим металлом – одно удовольствие, ведь он благословлён самой богиней Элуной. Выковать элунитовое оружие – великая честь. Подожди, я сейчас примусь за работу..." },
    ["1693c"] = { common = "Путник, я создам оружие из элунита, который ты принёс мне. Пожалуйста, выбери то, что тебе больше подойдёт. И я должен поблагодарить тебя. Работать с элунитом — честь и удовольствие." },
    ["1698a"] = { common = "Йорус Ячменовар бросил вызов всем воинам Альянса. Он ждёт в таверне Приозерья, что в Красногорье, и сулит щедрую награду всем, прошедшим испытание." },
    ["1698c"] = { common = "Ха! Значит, до тебя дошли вести о моём вызове, а? Что ж, садись и слушай. Пей и наслаждайся... Может быть, это твоя последняя выпивка в этой жизни." },
    ["1699a"] = { male = "Я называю моё испытание Ретбанским вызовом. Чтобы пройти его тебе всего-то нужно войти в пещеры Ретбана, дойти до первой развилки и вернуться. Элементарно! Есть, правда, несколько \"но\"… Вернуться тебе придётся в течение часа. Там полно красногорских гноллов. Перед тем, как тронуться в путь, тебе придётся глотнуть фирменного напитка моей семьи, жгучего пива семейства Ячменевец! Что скажешь? Пещеры Ретбана находятся в холмах на севере от Озёр. Ты готов принять Ретбанский вызов?", female = "Я называю моё испытание Ретбанским вызовом. Чтобы пройти его тебе всего-то нужно войти в пещеры Ретбана, дойти до первой развилки и вернуться. Элементарно! Есть, правда, несколько \"но\"… Вернуться тебе придётся в течение часа. Там полно красногорских гноллов. Перед тем, как тронуться в путь, тебе придётся глотнуть фирменного напитка моей семьи, жгучего пива семейства Ячменевец! Что скажешь? Пещеры Ретбана находятся в холмах на севере от Озёр. Ты готова принять Ретбанский вызов?" },
    ["1699c"] = { male = "Ты справился! Молодец! Трижды ура Злорфи!", female = "Ты справилась! Молодец! Трижды ура Злорфи!" },
    ["1700a"] = { common = "Работая над твоим доспехом, я делал записи, а теперь хочу отослать их копию кузнецу Гриманду Элмору. Он живёт здесь, в Квартале Дворфов, в оружейном магазине. Он гордится своим искусством, и совсем не обрадуется моему открытию..." },
    ["1700c"] = { common = "Это написал Фьюрен? Как он смёл! Да я его всему сам научил! Яйца курицу не учат! Нахал! Хм-м-м... Но в этих записях что-то есть... Надо попробовать..." },
    ["1701a"] = { common = "Ну вот, я дал тебе отличный щит, но это ещё не всё. Я знаю секрет изготовления очень прочного доспеха. Это нелегко, и мне потребуются редкие материалы, но если тебе не лень за ними поохотиться, доспех получится несравненный. Что скажешь? Если ты не боишься трудностей, я выдам тебе список необходимых материалов и где их искать." },
    ["1701c"] = { common = "Тебе удалось добыть всё необходимое? Вот это да! Я опасался, что химеры слопают тебя с потрохами! Что ж, займёмся доспехами..." },
    ["1702a"] = { male = "Да, приняв Ретбанский вызов, ты показал, на что способен. Я своё слово держу. Ты получишь обещанную награду… Только она в Штормграде. Поговори с моим другом, Фьюреном Длиннобородом. Он живёт в Квартале Дворфов. Его щиты славятся во всей округе, а мне он должен услугу. Вот, отнеси Фьюрену этот бочёнок жгучего пива Ячменевца и попроси взамен щит. Он плохого не даст.", female = "Да, приняв Ретбанский вызов, ты показала, на что способна. Я своё слово держу. Ты получишь обещанную награду… Только она в Штормграде. Поговори с моим другом, Фьюреном Длиннобородом. Он живёт в Квартале Дворфов. Его щиты славятся во всей округе, а мне он должен услугу. Вот, отнеси Фьюрену этот бочёнок жгучего пива Ячменевца и попроси взамен щит. Он плохого не даст." },
    ["1702c"] = { common = "А, жгучее пиво Ячменевца. Отличный напиток! Значит, ты от Йоруса, а? Конечно я дам тебе щит, да ещё какой! Такого нигде не найти, честное слово!" },
    ["1703a"] = { common = "Работая над твоим доспехом, я делал записи, а теперь хочу отослать их копию кузнецу Матилю. Он живёт довольно далеко, в Дарнассе, но несомненно будет рад, если я поделюсь с ним своими открытиями." },
    ["1703c"] = { common = "Это интересно, очень интересно. Мой коллега Фьюрен, сделал грандиозное открытие. Спасибо. Это будет честью для меня, применять новые технологии к моим разработкам." },
    ["1704a"] = { common = "Работая над твоим доспехом, я делал записи, а теперь хочу отослать их копию кузнецу Клацморту Гайкокруту. Он живёт в Стальгорне, и когда услышит о моём открытии... Он бороду себе выдернет от восторга!" },
    ["1704c"] = { common = "Ну и ну! Поразительные записи мне прислали! Больше того... Они ошеломляющие и невероятные, я едва на ногах стою от восторга! Фьюрен совершил прорыв в кузнечном деле! Да-да, самый настоящий прорыв! Мне не терпится испробовать новую технологию!" },
    ["1705a"] = { common = "Может, этот Фьюрен и совершил открытие, но мне надо проверить, так ли это. Попробую-ка я сделать такие доспехи. Если ты поможешь добыть все материалы, можешь забрать доспех себе. Мне понадобится горящая кровь и горящий камень. Единственное место, где можно добыть эти материалы – Сумеречный лес. Горящая кровь есть у воргенов из стаи Ночной Погибели из пещеры Роланда, а горящий камень хранит у себя их главарь, Кишкодер. И не мешкай, во имя Света." },
    ["1705c"] = { common = "Недурно! А теперь, прошу прощения, мне тоже надо поработать..." },
    ["1707a"] = { common = "Привет тебе. Меня зовут Живец, и у меня есть для тебя важная работа! Ура! Я опытный оператор крана, и ничто не порадует меня так, как бурдюки с водой Скитальцев Пустыни, которые могут попасться тебе в пустыне, у кочевников. Всё равно это наша вода – мерзкие кочевники её украли! Водная компания Прибамбасска предлагает в награду полевой набор за каждые пять бурдюков. А главное, ты поможешь Прибамбасску!" },
    ["1707c"] = { common = "Великолепно! Чем больше мехов с водой нам удастся добыть, тем ниже вероятность катастрофы! Можешь таскать их сотнями, и за каждые пять будешь получать всё ту же награду." },
    ["1708a"] = { male = "Я хочу опробовать технологию Фьюрена Длинноборода на собственных доспехах. Раз ты помог Фьюрену, а он мне, я разрешу тебе забрать их себе! Чтобы довести работу до конца, мне необходим особый коралл, выжженный. Он растёт лишь в одном месте, вдоль побережья Гавани Менетилов в Болотине. Принеси мне побольше таких кораллов, и я примусь за работу. И поторапливайся, у меня руки чешутся, так хочется взяться за дело.", female = "Я хочу опробовать технологию Фьюрена Длинноборода на собственных доспехах. Раз ты помогла Фьюрену, а он мне, я разрешу тебе забрать их себе! Чтобы довести работу до конца, мне необходим особый коралл, выжженный. Он растёт лишь в одном месте, вдоль побережья Гавани Менетилов в Болотине. Принеси мне побольше таких кораллов, и я примусь за работу. И поторапливайся, у меня руки чешутся, так хочется взяться за дело." },
    ["1708c"] = { male = "Вот, то что нужно! Молодец! А теперь дай-ка я их расплавлю и расплющу. Попробую совместить технологию Фьюрена с моей, и посмотрим что из этого выйдет! Ну-ну, я предчувствую, что доспехи получатся очень-очень-очень прочные!", female = "Вот, то что нужно! Умница! А теперь дай-ка я их расплавлю и расплющу. Попробую совместить технологию Фьюрена с моей, и посмотрим что из этого выйдет! Ну-ну, я предчувствую, что доспехи получатся очень-очень-очень прочные!" },
    ["1709c"] = { common = "Вот твоя броня, путник. Способ Фьюрена блестяще работает! Просто прекрасно! Как бы удивительно не звучало, но это так!" },
    ["1710a"] = { common = "Мой коллега, Фьюрен Долгобород, совершил многообещающее открытие. Я хотел бы испытать его на новых доспехах, мне кажется, результат превзойдёт все ожидания. Не поможешь? Если ты принесёшь мне все необходимые материалы, я и для тебя сделаю такие доспехи. Мне понадобится высохшая на солнце скорлупа яиц виверн Скального Гнездовья из Тысячи Игл. Скорлупу можно найти под их гнёздами. Как наберёшь достаточно, возвращайся." },
    ["1710c"] = { common = "Ах, спасибо тебе! Это прекрасно подойдёт! Я начну создавать броню немедленно." },
    ["1711c"] = { common = "Я завершил работу над твоей бронёй, и я очень ей доволен. Новые методы Фьюрена очень отлично себя показали, я уверен, с этой новой технологией, броня будет очень устойчивой. Спасибо, путник." },
    ["1712a"] = { common = "Я давно наблюдаю за этими местами, в надежде дожить до падения великого Циклониана. Увы, мне до сих пор не встретился герой, готовый схватиться с повелителем ветра. Может быть, этим героем окажешься ты? Докажи, что ты великий воин – собери все предметы, необходимые для призыва Циклониана. Тогда, быть может, тебе удастся одолеть его и завладеть сердцем Вихря. Если это свершится, я вложу силу сердца в оружие и вручу его тебе. Вот список нужных компонентов." },
    ["1712c"] = { male = "Ты сумел собрать всё необходимое для заклинания призыва, доказав тем самым свою силу и ловкость. Но следующий шаг будет гораздо опаснее. Будем надеяться, что сила тебя не покинет.", female = "Ты сумела собрать всё необходимое для заклинания призыва, доказав тем самым свою силу и ловкость. Но следующий шаг будет гораздо опаснее. Будем надеяться, что сила тебя не покинет." },
    ["1713a"] = { male = "Я готов провести ритуал призыва Циклониана. Потом тебе предстоит победить его и забрать у него из груди сердце Вихря. После этого я создам оружие, которое вберёт в себя силу Циклониана. готов ли ты выступить против повелителя ветра?", female = "Я готов провести ритуал призыва Циклониана. Потом тебе предстоит победить его и забрать у него из груди сердце Вихря. После этого я создам оружие, которое вберёт в себя силу Циклониана. готова ли ты выступить против повелителя ветра?" },
    ["1713c"] = { male = "Ты справился! Циклониан повержен, а у тебя в руках сердце Вихря!", female = "Ты справилась! Циклониан повержен, а у тебя в руках сердце Вихря!" },
    ["1715a"] = { common = "Хмм. В прежние времена все чернокнижники Каз Модан обучались под присмотром мастеров Гномрегана, но теперь, когда все мы вынуждены ютиться в этой крысиной норе под названием Стальгорн и Магни решил не спускать с нас глаз, нам приходится отсылать наших новичков на обучение в Штормград. По счастью, Гакин не растяпа, так что ты всё равно узнаешь всё, что тебе надо, но я просто киплю! Короче, ты найдёшь Гакина в подвале \"Забитого ягнёнка\" в Штормграде." },
    ["1715c"] = { common = "Так тебя послал Зловещая Отвёртка? Нет, пора бы уже этим стальгорнским растяпам как-то разобраться с ситуацией. Штормград не резиновый, и наставников тут сколько есть, и не больше. Если сюда повалит народ, то рано или поздно мы привлечём к себе внимание." },
    ["1716a"] = { common = "Сайаады – пожиратели душ, подавляющие волю и вводящие в искушение. Порождение чистого зла. В легкомысленных историях этих демонов называют суккубами, если речь о женщинах, и инкубами, если это мужчины. Примани демона символом любви, победи его – и он будет тебе служить. Но найти подходящий символ непросто. Поговори с Такаром Провидцем. Ты найдёшь его в калимдорских Степях возле лагеря Таурахо." },
    ["1716c"] = { common = "Как вы добрались? Вы проделали долгий путь, чтобы поговорить со мной. Но не бойтесь: я знаю, зачем Гакин прислал вас. Это было мудро с его стороны, потому что я могу вам помочь." },
    ["1717a"] = { male = "Не ожидал увидеть тебя в этих краях, но мне велели за тобой приглядывать. Ты давненько уже не проходил очередного обучения, так что тебе следует зайти к Гакину, когда в следующий раз будешь в Штормграде. Он будет тебя ждать.", female = "Не ожидал увидеть тебя в этих краях, но мне велели за тобой приглядывать. Ты давненько уже не проходила очередного обучения, так что тебе следует зайти к Гакину, когда в следующий раз будешь в Штормграде. Он будет тебя ждать." },
    ["1717c"] = { common = "Хорошо, что кто-то, наконец, поймал тебя. Я уже опасался худшего. В тебя вложено слишком много и было бы жалко тебя потерять. Мы ещё поговорим на эту тему позднее.. Твоя тренировка более важна в данный момент." },
    ["1718a"] = { common = "Ты становишься недурным воином. Пришло время помериться силой с братьями по оружию. Недалеко от побережья Степей, к югу от Кабестана, есть остров. Он называется Островом Битв. Это место встречи воинов. Место встречи и дружеских схваток. Поговори со старшим воином острова, Кланноком Маклеодом. Если он сочтёт тебя достойным дальнейшего обучения, то поможет тебе сделать очередной шаг на пути воина. До Острова Битв можно добраться по песчаной отмели вдоль Торгового побережья." },
    ["1718c"] = { common = "Привет тебе, воин. Хорошо, что тебе удалось добраться до Острова Битв. Надеюсь, он тебе нравится..." },
    ["1719a"] = { male = "Если ты хочешь учиться у меня, тебе придётся пройти испытание, Побоище. Через него проходят все молодые воины, вообразившие себя великими. А величие надо доказывать. Для начала пройди сквозь ту толпу и встань на решётку. Это будет знак Пруттику Плоскоголову, что ты готов. Он сразу пошлёт тебе поединщика. Когда ты одолеешь всех, он позовёт Большого Билла. Убей его и вернись ко мне за отведённое время.", female = "Если ты хочешь учиться у меня, тебе придётся пройти испытание, Побоище. Через него проходят все молодые воины, вообразившие себя великими. А величие надо доказывать. Для начала пройди сквозь ту толпу и встань на решётку. Это будет знак Пруттику Плоскоголову, что ты готова. Он сразу пошлёт тебе поединщика. Когда ты одолеешь всех, он позовёт Большого Билла. Убей его и вернись ко мне за отведённое время." },
    ["1719c"] = { male = "Молодец. Ты прошёл испытание Побоищем! Ты могучий воин, и учить тебя – великая честь...", female = "Молодец. Ты прошла испытание Побоищем! Ты могучий воин, и учить тебя – великая честь..." },
    ["1738a"] = { common = "Готовясь к твоему приходу, я на скорую руку оглядел весь мир, проник взглядом сквозь пелену времени и нашёл то, что тебе нужно. Во время Войны Древних двое влюблённых вместе пали в битве. Там, где перестали биться их сердца, выросло дерево, известное как сердцедрево – символ их бессмертной любви. Этого должно быть достаточно, чтобы привлечь суккуба. Руины Ордиль-Арана, где растёт сердцедрево, находятся в северо-западной части Ясеневого леса." },
    ["1738c"] = { common = "Да, сердцедрево нам подойдёт. Дай-ка я немного обработаю древесину... Такар – настоящий кладезь премудростей; с таким не пропадёшь, правда? Если б я только мог убедить его вернуться к цивилизации..." },
    ["1739a"] = { common = "С помощью сердцевины сердцедрева ты сможешь открыть портал и призвать суккуба в круг призыва. Круг находится в подвале. Не забывай об осторожности, суккубы подчиняли себе и самых стойких заклинателей. После того как вызовешь демона и вернёшь его обратно в Бездну, возвращайся ко мне и я научу тебя, как обращаться с суккубом." },
    ["1739c"] = { common = "Неплохо, неплохо... Я не ошибся, когда решил обучать тебя. Твои успехи меня не разочаровывают. Пора научить тебя обращению с только что подчинённым суккубом. Только не забывай про осторожность!" },
    ["1740a"] = { common = "Когда демоны Легиона попадают в немилость, их души заключают в сферы и раздают магам и чернокнижникам. Многих из них носили на Азероте их слуги. Даже расколотые на части, эти сферы хранят в себе силу демонов, заключённых внутри. Шар Соран'рука был расколот надвое. Одну из частей раздробили на ещё более мелкие фрагменты послушники Сумеречного Молота в Непроглядной Пучине. А другая, большая часть, досталась волшебнику из крепости Тёмного Клыка. Найди их, и я смогу воссоздать этот шар." },
    ["1740c"] = { male = "Да... Этот шар не так уж сильно раскололи, и передо-мной почти все осколки. Воссоздать их, сделав Соран'рука единым целым, несложно. Я посвятил всю жизнь изучению и восстановлению сфер Пылающего Легиона. Ты оказал мне большую услугу, позволив изучить эти осколки, и я верну их тебе, полностью восстановив, придав им любую форму по твоему выбору.", female = "Да... Этот шар не так уж сильно раскололи, и передо-мной почти все осколки. Воссоздать их, сделав Соран'рука единым целым, несложно. Я посвятил всю жизнь изучению и восстановлению сфер Пылающего Легиона. Ты оказала мне большую услугу, позволив изучить эти осколки, и я верну их тебе, полностью восстановив, придав им любую форму по твоему выбору." },
    ["1758a"] = { common = "Простой круг призыва не поможет тебе вызвать на бой охотника скверны. Я и трое моих послушников поможем тебе создать магические круги. Тебе также понадобится фолиант Заговора, который мы давно утратили. Его написала первая группа чернокнижников, умудрившихся вызвать охотника скверны без посторонней помощи. С этим тебе поможет Крому Крепкоруку. Теперь он – главный чернокнижник, и целыми днями он сидит в библиотеке Стальгорна, оберегая древние тексты." },
    ["1758c"] = { common = "Фолиант Заговора? Хм-м... Знакомое название. Я его никогда не видел – а уж поверьте, я помню все прочитанные книги. Хм… А, да! Я видел ссылки на этот фолиант в библиотечных каталогах." },
    ["1778a"] = { male = "Я намереваюсь скоро вернуться домой. Надеюсь, у Стефани в Штормграде дела идут хорошо. Не терпится снова увидеться с ней. До следующей встречи, герой.", female = "Я намереваюсь скоро вернуться домой. Надеюсь, у Стефани в Штормграде дела идут хорошо. Не терпится снова увидеться с ней. До следующей встречи, героиня." },
    ["1778c"] = { male = "Итак, ты быстро вернулся, а? И чего же ты достиг за это время? Итак, ты помог достойному делу? Возможно ты уже заслужил уважение граждан Азерота. Скажи мне кому ты помог – и я скажу кто ты… Удивительно , ты действительно следуешь пути Света. Такая жертва будет обязательно вознаграждена в своё время..", female = "Итак, ты быстро вернулась, а? И чего же ты достигла за это время? Итак, ты помогла достойному делу? Возможно ты уже заслужила уважение граждан Азерота. Скажи мне кому ты помогла – и я скажу кто ты… Удивительно , ты действительно следуешь пути Света. Такая жертва будет обязательно вознаграждена в своё время.." },
    ["1779a"] = { male = "Я хочу, чтобы ты взял это. Это называется знак Жизни. Ты показал своё милосердие и терпение, а теперь я хочу, чтобы ты проявил себя не только как воин, но и как целитель. Мой супруг Майридон Боевая Кузня недавно вернулся после стычки с дворфами Чёрного Железа. Он едва ноги унёс – сейчас лечит свои раны у одного из наших жрецов. Возьми Символ и поговори с ним. Если ты сумеешь ему помочь, мы вскоре продолжим наш разговор. Да пребудет с тобой Свет.", female = "Я хочу, чтобы ты взяла это. Это называется знак Жизни. Ты показала своё милосердие и терпение, а теперь я хочу, чтобы ты проявила себя не только как воин, но и как целительница. Мой супруг Майридон Боевая Кузня недавно вернулся после стычки с дворфами Чёрного Железа. Он едва ноги унёс – сейчас лечит свои раны у одного из наших жрецов. Возьми Символ и поговори с ним. Если ты сумеешь ему помочь, мы вскоре продолжим наш разговор. Да пребудет с тобой Свет." },
    ["1779c"] = { male = "*кашляет* Доброго тебе здравия, герой. Не волнуйся о моих ранах, добрый жрец сумеет вылечить Майридона. Так что сила твоего знака Жизни пока мне не нужна. Значит, моя жёнушка тебя послала потолковать со мной, да? Славно, славно. У меня найдётся времечко поговорить с тобой, я расскажу тебе в точности, что произошло с Майридоном и его лучшим другом Нармом, паладином вроде тебя.", female = "*кашляет* Доброго тебе здравия, героиня. Не волнуйся о моих ранах, добрый жрец сумеет вылечить Майридона. Так что сила твоего знака Жизни пока мне не нужна. Значит, моя жёнушка тебя послала потолковать со мной, да? Славно, славно. У меня найдётся времечко поговорить с тобой, я расскажу тебе в точности, что произошло с Майридоном и его лучшим другом Нармом, паладином вроде тебя." },
    ["1780a"] = { male = "Я сегодня же отнесу это детям. Ты можешь не тревожиться, герой. Конечно, такие, как ты, нечасто показываются в городе, но ты без сомнения доказал, что паладины Штормграда никогда не отвернутся от тех, кто в них нуждается. Доброго пути!", female = "Я сегодня же отнесу это детям. Ты можешь не тревожиться, героиня. Конечно, такие, как ты, нечасто показываются в городе, но ты без сомнения доказала, что паладины Штормграда никогда не отвернутся от тех, кто в них нуждается. Доброго пути!" },
    ["1780c"] = { common = "Ты уже здесь? Однако, странствия заняли у тебя не так много времени, как я полагал. И что же тебе удалось свершить за время, проведённое вдали от Храма? Может быть, тебе довелось сражаться за справедливость? Или удалось постичь смысл милосердия? Или помочь кому-либо из нуждающихся жителей Азерота? Расскажи мне всё... Что ж, это производит впечатление. Поверь, это поистине поступки того, кто следует путём Света и ставит благо других выше своего собственного. Рано или поздно такое самопожертвование всегда вознаграждается." },
    ["1781a"] = { common = "Прими этот знак Жизни. Тебе удалось обрести милосердие и терпение: пришло время узнать, хватит ли у тебя сил, чтобы воспользоваться одним из величайших даров Света. Мой друг Газин недавно вернулся из Элвиннского леса с острова Героев, где он едва не расстался с жизнью после стычки с магами Братства Справедливости. Сейчас он у алтаря: надеюсь, служителям удастся исцелить его раны. Возьми этот Символ и поговори с Газином. Если сумеешь помочь ему, мы продолжим нашу беседу. Да пребудет с тобой извечный Свет!" },
    ["1781c"] = { male = "*кашляет* Я рад встрече с тобой, герой. Не обращай внимания на мои раны: добрые служители Света смогут обо-всём позаботиться. Сила знака Жизни, которого ты держишь в руках, мне без надобности... по крайней мере пока. Значит, Даториан послал тебя поговорить со мной, да? Что ж, это правильно. Я тебе расскажу, что случилось со мной и моим другом Хензом. Если нам повезёт и тебе хватит сил и умения, ты ещё сможешь всех нас спасти...", female = "*кашляет* Я рад встрече с тобой, героиня. Не обращай внимания на мои раны: добрые служители Света смогут обо-всём позаботиться. Сила знака Жизни, которого ты держишь в руках, мне без надобности... по крайней мере пока. Значит, Даториан послал тебя поговорить со мной, да? Что ж, это правильно. Я тебе расскажу, что случилось со мной и моим другом Хензом. Если нам повезёт и тебе хватит сил и умения, ты ещё сможешь всех нас спасти..." },
    ["1782c"] = { common = "Вот твой доспех, путник. Он выстоит против самых сильных ударов! И я должен поблагодарить тебя. Я многому научился, работая с теми материалами, которые ты принёс мне." },
    ["1783a"] = { common = "Мы выслеживали дворфов Чёрного Железа, что окопались к югу от озера Хельмово Ложе. Мы знали, что они затевают недоброе, потому мы с Нармом решили подобраться поближе, чтобы посмотреть, как их капитан раздаёт приказы своим воинам. Мы с Нармом воспользовались случаем и пристукнули нескольких, но они оказались крепче, чем мы думали, и набросились на нас толпой. Нарм велел мне бежать за помощью, и вот я здесь. Нарму нужна помощь. И я не успокоюсь, пока он её не получит. Ты ведь поможешь ему?" },
    ["1783c"] = { male = "Не знаю, как мне отблагодарить тебя, брат! Видать, тебя прислали мне в подмогу Тиза с Майридоном, раз на тебе знак Жизни. Да, это правда, я пал в бою с дворфами Чёрного Железа, пытаясь получить одну из их бумаг. Я довольно долго продержался и дал Майридону уйти, но я почти уже погрузился в Свет, когда ты появился. То, что тебе хватило мощи воспользоваться знаком, очень многое значит, но мы поговорим об этом позже.", female = "Не знаю, как мне отблагодарить тебя, сестра! Видать, тебя прислали мне в подмогу Тиза с Майридоном, раз на тебе знак Жизни. Да, это правда, я пал в бою с дворфами Чёрного Железа, пытаясь получить одну из их бумаг. Я довольно долго продержался и дал Майридону уйти, но я почти уже погрузился в Свет, когда ты появилась. То, что тебе хватило мощи воспользоваться знаком, очень многое значит, но мы поговорим об этом позже." },
    ["1784a"] = { common = "Прежде чем я пал в бою, мы с Майридоном почти одолели одного из соглядатаев из клана Чёрного Железа возле того небольшого домика. Мы видели, как их капитан раздавал им бумаги с приказами, и хотели убить его и забрать эти бумаги. Кое-кто в совете Стальгорна до сих пор не верит в присутствие дворфов Чёрного Железа в Дун Морог. Захватив одну из этих бумаг, мы не только получим доказательства их вылазок, но и поймём, что они затевают. Добудь один из приказов и отнеси Майридону." },
    ["1784c"] = { male = "Хаха! Тебе удалось! Ты спас Нарма и нашёл доказательство, которое нужно моей жене, чтобы показать его в совете. Ты просто единственное благословление Света, если я в них хоть что-то понимаю... не считая, конечно, моей жены. Прими снова мою благодарность.", female = "Хаха! Тебе удалось! Ты спасла Нарма и нашла доказательство, которое нужно моей жене, чтобы показать его в совете. Ты просто единственное благословление Света, если я в них хоть что-то понимаю... не считая, конечно, моей жены. Прими снова мою благодарность." },
    ["1785a"] = { male = "Вижу, моя жёнушка прямо пышет гордостью. Я бы на твоём месте поскакал прямо к ней. Сдаётся, она хочет перекинуться с тобой парой слов. Да хранит тебя Свет, славный герой. Я буду искать тебя на поле боя против Плети и клана Чёрного Железа, когда придёт пора.", female = "Вижу, моя жёнушка прямо пышет гордостью. Я бы на твоём месте поскакал прямо к ней. Сдаётся, она хочет перекинуться с тобой парой слов. Да хранит тебя Свет, славная героиня. Я буду искать тебя на поле боя против Плети и клана Чёрного Железа, когда придёт пора." },
    ["1785c"] = { male = "Сегодня ты оказал большую услугу Стальгорну. Я горда, что ты среди нас, и если ты готов, я хотела бы благословить тебя этим свитком. Знак Жизни подействовал бы только в руках паладина, готового принять одну из самых великих благостей Света, – силу возвращать умерших к жизни. Я научу тебя возрождать к жизни твоих соратников. Используй это умение мудро, и прими благодарность от меня, моего мужа и всего Стальгорна.", female = "Сегодня ты оказала большую услугу Стальгорну. Я горда, что ты среди нас, и если ты готова, я хотела бы благословить тебя этим свитком. Знак Жизни подействовал бы только в руках паладина, готового принять одну из самых великих благостей Света, – силу возвращать умерших к жизни. Я научу тебя возрождать к жизни твоих соратников. Используй это умение мудро, и прими благодарность от меня, моего мужа и всего Стальгорна." },
    ["1786a"] = { common = "Мы с Хензом добрались до острова Героев – он находится посреди Озера Каменных Столбов, в северо-восточной части Элвиннского леса. Мы слышали, что Братство Справедливости проникло в наши земли, и должны предоставить доказательства этого вторжения королевским советникам. Мы засекли двоих из этих подонков, когда они просматривали кое-какие документы, и напали на них. Увы, магов было больше, и нас заставили отступить. Хенз прикрывал меня, и мне удалось бежать... проклятый глупец, отвагу проявить решил!.. И вот он там так и остался. Хенз, я имею в виду. Может, ты сумеешь помочь?" },
    ["1786c"] = { male = "Прими мою благодарность, брат. В твоих руках я вижу знак Жизни – тебя послал Даториан или Газин. Мы с Газином пытались похитить планы Братства Справедливости, но на нас напали их чародеи. Мне удалось продержаться достаточно долго для того, чтобы Газин успел скрыться, но в конце концов я был побеждён... Но тебе удалось вернуть меня – а далеко не всем дана способность управлять знаком Жизни, можешь мне поверить. Это свидетельство крепости твоей веры...", female = "Прими мою благодарность, сестра. В твоих руках я вижу знак Жизни – тебя послал Даториан или Газин. Мы с Газином пытались похитить планы Братства Справедливости, но на нас напали их чародеи. Мне удалось продержаться достаточно долго для того, чтобы Газин успел скрыться, но в конце концов я был побеждён... Но тебе удалось вернуть меня – а далеко не всем дана способность управлять знаком Жизни, можешь мне поверить. Это свидетельство крепости твоей веры..." },
    ["1787a"] = { common = "У нас ещё будет время поговорить о Символе. Сейчас важнее заполучить те бумаги, которые мы видели у Братства Справедливости. Если бумаги будут у нас, мы сможем доказать, что братство проникло в Элвиннский лес – а может, и узнать что-нибудь о его планах. Увы, навряд ли я сейчас могу считаться воином. Сможешь ли ты пойти в бой в одиночку? Сумеешь ли ты добыть то, что нам так необходимо? Если это тебе удастся, отнеси бумаги Газину и сообщи ему, что со мной всё хорошо." },
    ["1787c"] = { common = "Великолепно! Тебе удалось спасти Хенза и выполнить задание. Теперь я знаю: воистину, Свет озаряет твой путь!" },
    ["1788a"] = { common = "После того как Даториан ознакомится с этими бумагами, я передам их королевским советникам; однако прежде тебе стоит поговорить с Даторианом. Думаю, он тоже хотел бы поблагодарить тебя. Твоя помощь поистине неоценима. Надеюсь, это не последняя наша встреча. Я горжусь нашей дружбой." },
    ["1788c"] = { male = "Что ж, полагаю, ты можешь гордиться своими свершениями. Скажу больше: ты можешь также гордиться своими способностями. Далеко не каждый может использовать силу, которой наделён знак Жизни. Если в твоих силах призвать исцеляющую силу Света, ты достоин того, чтобы принять величайший дар паладинов, – дар воскрешения. Ты сможешь возвращать к жизни павших спутников так же, как вернул к жизни Хенза. Горний Свет озарил тебя, открой же ему душу.", female = "Что ж, полагаю, ты можешь гордиться своими свершениями. Скажу больше: ты можешь также гордиться своими способностями. Далеко не каждый может использовать силу, которой наделён знак Жизни. Если в твоих силах призвать исцеляющую силу Света, ты достойна того, чтобы принять величайший дар паладинов, – дар воскрешения. Ты сможешь возвращать к жизни павших спутников так же, как вернула к жизни Хенза. Горний Свет озарил тебя, открой же ему душу." },
    ["1791a"] = { male = "Что ж, ты освоил стойку берсерка, теперь нужно подобрать тебе оружие. Поговори с Бат'ра Ветростражем, троллем-отшельником, живущим между Альтеракскими горами и Западными Чумными землями. Он опытный оружейник и могущественный шаман. Если ты захочешь встретиться с Бат-ра, отправляйся к реке, что течёт вдоль восточного края мельницы Таррен. Иди вдоль неё на север – Бат'ра разбил лагерь рядом с руинами на берегу реки.", female = "Что ж, ты освоила стойку берсерка, теперь нужно подобрать тебе оружие. Поговори с Бат'ра Ветростражем, троллем-отшельником, живущим между Альтеракскими горами и Западными Чумными землями. Он опытный оружейник и могущественный шаман. Если ты захочешь встретиться с Бат-ра, отправляйся к реке, что течёт вдоль восточного края мельницы Таррен. Иди вдоль неё на север – Бат'ра разбил лагерь рядом с руинами на берегу реки." },
    ["1791c"] = { male = "Тебе пришлось проделать долгий путь, юный воин. Как у тебя горят глаза! Тебе ведь нужно мощное оружие? Я помогу тебе... в обмен на твою помощь.", female = "Тебе пришлось проделать долгий путь, юная воин. Как у тебя горят глаза! Тебе ведь нужно мощное оружие? Я помогу тебе... в обмен на твою помощь." },
    ["1792c"] = { common = "У меня есть сердце Вихря, и я могу подобрать ему вместилище по твоему выбору. Возьми любое оружие, путник, и знай, что его сила — сила Циклониана." },
    ["1795a"] = { male = "Если ты готов, давай приступим. Начну с объяснений. Сначала мы создадим основной круг призыва. После этого мои послушники создадут больший круг при помощи жезлов направления. Затем ты прочтёшь заклинание из фолианта Заговора, и на зов явится охотник Скверны. Будь осторожен. Охотник Скверны – сильный враг, не теряй головы.", female = "Если ты готова, давай приступим. Начну с объяснений. Сначала мы создадим основной круг призыва. После этого мои послушники создадут больший круг при помощи жезлов направления. Затем ты прочтёшь заклинание из фолианта Заговора, и на зов явится охотник Скверны. Будь осторожна. Охотник Скверны – сильный враг, не теряй головы." },
    ["1795c"] = { common = "Впечатляюще. Когда я сражался с охотником скверны, то едва выжил. Предчувствую, что ты станешь одним из сильнейших чернокнижников нашей эры." },
    ["1796a"] = { common = "Первым делом я помогу тебе создать одеяние. Ты принесёшь мне несколько необходимых составляющих, а уж работать над ними будем вместе. В итоге, если ты справишься, разумеется, ты получишь первый из многих предметов, которые одарят тебя могуществом и помогут в борьбе против сил Тьмы. Для начала тебе нужны одеяния Аркана. Их может сшить портной или их можно купить... ещё лучше сделать их самому, но это сложно. Короче, для начала принеси мне эти одеяния." },
    ["1796c"] = { common = "То, что нужно. В основе всех волшебных предметов должна лежать вещь высокого качества. Чем больше усилий и искусства вложить в предмет, тем легче напитать его магией. Редкие и дорогие составляющие также лучше держат магию. Не жалей об утрате этого одеяния: когда мы закончим, оно станет куда лучше." },
    ["1798a"] = { common = "Пришло время научить тебя вызывать охотника скверны. Здесь у меня нет ни реагентов, ни предметов, необходимых для обучения, так что придётся тебе найти другого учителя – Страхада Фарсана. Он проживает в гоблинском порту Кабестане. Я извещу его о том, что ты появишься." },
    ["1798c"] = { common = "Ах да, конечно. Наше новое чудо. Но, боюсь, настоящее чудо вряд ли успеет стать легендой при жизни. Впрочем, неважно – ты здесь для того, чтобы пройти обучение, а не слушать, как я шучу сам с собой." },
    ["1799a"] = { common = "Отлично, приступим. Первым делом ступай внутрь и поговори с моими послушниками. Тебе предстоит избрать свой путь – они объяснят подробнее. Потом придётся отправиться в Пустоши и отыскать сферу Подземного огня у одного из чернокнижников Поля Маннорок. Именно эту сферу необходимо очистить при помощи мага по имени Табета в южной части Пылевых топей. Она поможет тебе ради меня. И не возвращайся, пока не выполнишь оба задания." },
    ["1799c"] = { common = "А, так тебя послала Менара. Ну, хорошо... Располагайся, чувствуй себя как дома. Впрочем, ты, должно быть, спешишь? Быть может, ищешь утраченную силу? Может, я ошибаюсь, и скверна всё же коснулась тебя." },
    ["1801a"] = { common = "Простой круг призыва не поможет тебе вызвать на бой охотника Скверны. Я и трое моих послушников поможем тебе создать магические круги. Тебе также понадобится фолиант Заговора, который мы давно утратили. Его написала первая группа чернокнижников, умудрившихся вызвать охотника Скверны без посторонней помощи. С этим тебе поможет Йорах Аннисон. Он работает в Подгороде картографом, но всё равно знает о древних текстах куда больше моего." },
    ["1801c"] = { common = "Картография! Картинки, далёкие от реальности. Они мне не нужны. Книги – повествование, описание! В них и только в них следует искать правду. Я обменял бы все свои карты на одну книгу о возвышении некромантии или сагу о торжестве Тёмной Госпожи." },
    ["1802a"] = { common = "Он был утрачен, но есть кое-какие соображения насчёт того, где он может находиться сейчас. С него сделали только одну копию и отнеслись к ней совершенно по-варварски: большая часть книги была вырвана из переплёта. Ходят слухи, что она каким-то образом попала в руки одного кентавра из Тысячи Игл. Остальное было утрачено в прибрежных краях к западу от Южнобережья, откуда книгу должны были переправить морем в Гавань Менетилов. Судно так и не прибыло. А за мои сведения я попрошу одно: когда найдёшь книгу, дай мне заглянуть в неё хотя бы одним глазком." },
    ["1802c"] = { common = "С ума сойти! Теперь я один из немногих, что сумел хоть мельком заглянуть в неё. Не терпится повнимательнее изучить этот текст. Какой великий день! Позволь мне ещё раз заглянуть в неё прежде, чем уйдёшь. Уверен, что Страхад охотно пришлёт мне копию." },
    ["1803a"] = { common = "А! Вижу, наши вкусы сходятся. Поиски фолианта Заговора – достойное занятие. Знаешь ли ты, что он некогда хранился в стенах Лордерона? Правда, эти варвары поглумились над ним, вырвали больше половины страниц. Кто мог совершить такую мерзость? Итак, половина потеряна, хотя говорят, будто она попала в руки кентавров из Тысячи Игл. Остальную часть должны были перевезти в Стальгорн, но она потерялась при перевозке где-то на берегу озера к западу от Южнобережья." },
    ["1803c"] = { common = "Так-так-так! Что это у нас? Невероятно. Я был уверен, что это невозможно, но вот я держу в руках фолиант Заговора. Позволь мне полистать его, пока ты не ушёл." },
    ["1804a"] = { male = "Как же не хочется его выпускать из рук! Но ты его нашёл и, конечно же, свершишь при его помощи куда более важные дела. Только, сделай милость, не забудь сказать Страхаду, что я хочу получить копию. Пока тебя не было, он прислал для тебя письмо. Он пишет, что для призыва духов необходимо достать три жезла направления. Он-то не знает, где их искать, но зато я знаю! Последний раз их использовали орки клана Драконьей Пасти в Болотине. Я бы поискал у их заклинателей!", female = "Как же не хочется его выпускать из рук! Но ты его нашла и, конечно же, свершишь при его помощи куда более важные дела. Только, сделай милость, не забудь сказать Страхаду, что я хочу получить копию. Пока тебя не было, он прислал для тебя письмо. Он пишет, что для призыва духов необходимо достать три жезла направления. Он-то не знает, где их искать, но зато я знаю! Последний раз их использовали орки клана Драконьей Пасти в Болотине. Я бы поискал у их заклинателей!" },
    ["1804c"] = { common = "Отлично! Фолиант Заговора и три практически нетронутых жезла направления. Забавно выходит. Давно молодые чернокнижники не приручали охотников Скверны." },
    ["1805a"] = { male = "Это один из самых интересных текстов, что мне приходилось изучать за последние несколько лет. Выбор здесь небогат – большинство книг посвящено географии, и я всё до дыр зачитал. Надеюсь, Страхад пришлёт мне копию. Кстати, он прислал весточку, пока тебя не было. Чтобы выполнить очередную задачу, тебе понадобится три жезла направления. В благодарность за то, что ты дал мне взглянуть на этот текст, открою тайну: жезлы можно найти у орков клана Драконьей Пасти в Болотине.", female = "Это один из самых интересных текстов, что мне приходилось изучать за последние несколько лет. Выбор здесь небогат – большинство книг посвящено географии, и я всё до дыр зачитал. Надеюсь, Страхад пришлёт мне копию. Кстати, он прислал весточку, пока тебя не было. Чтобы выполнить очередную задачу, тебе понадобится три жезла направления. В благодарность за то, что ты дала мне взглянуть на этот текст, открою тайну: жезлы можно найти у орков клана Драконьей Пасти в Болотине." },
    ["1805c"] = { common = "Отлично! Фолиант Заговора и три практически нетронутых жезла направления. Забавно выходит. Давно молодые чернокнижники не приручали охотников Скверны." },
    ["1806a"] = { male = "Почему бы нам не пойти прямо в кузню и не начать работу? Я уже ждал тебя и подготовился, так что времени это много не займёт. Когда всё будет закончено, ты будешь гораздо лучше подготовлен к защите дела Света, уж за это я ручаюсь. Не утаю, я даже немного завидую твоим деяниям. Но осознание того, что я по-своему помогу тебе, и немало помогу, всё же радует меня.", female = "Почему бы нам не пойти прямо в кузню и не начать работу? Я уже ждал тебя и подготовился, так что времени это много не займёт. Когда всё будет закончено, ты будешь гораздо лучше подготовлена к защите дела Света, уж за это я ручаюсь. Не утаю, я даже немного завидую твоим деяниям. Но осознание того, что я по-своему помогу тебе, и немало помогу, всё же радует меня." },
    ["1806c"] = { common = "Вот оно. Оружие, достойное защитника Света вроде тебя. Я дал ему имя в честь великого дворфского паладина, моего друга. Его звали Вериган... Бош Вериган. Прошу, прими его в благодарность от меня и моей жены. Мы очень обязаны тебе. Мир станет лучше, если по земле ходят такие, как ты!" },
    ["1818a"] = { common = "Мне сказали, что у стража смерти Диллинджера есть работа для таких, как ты. Если ты хочешь доказать свою ценность Тёмной Госпоже, немедленно отправляйся к нему. Страж смерти Диллинджер стоит на посту в западном конце Брилла, рядом с кладбищем." },
    ["1818c"] = { common = "Ты хочешь получить задание? Отлично. У меня есть одно. Довольно важное. Заодно и свою силу нам покажешь... И решимость защищать дело Отрёкшихся." },
    ["1819a"] = { male = "Когда Тирисфальские луга наводнили воины Плети, мы поймали одного из них и подвергли пристальному изучению. Он обладал свободной волей и звал себя Улаг Колун. Впрочем, несмотря на свободу воли, его подчинил себе Король-лич. Мы надеялись избавить Улага от чар, но не смогли. Довольно ему томиться в темнице плоти. Освободи его. Для этого его придётся убить. Воспользуйся переключателем в мавзолее к северу отсюда. Это позволит снять с Улага магические путы. Сними их и... будь готов!", female = "Когда Тирисфальские луга наводнили воины Плети, мы поймали одного из них и подвергли пристальному изучению. Он обладал свободной волей и звал себя Улаг Колун. Впрочем, несмотря на свободу воли, его подчинил себе Король-лич. Мы надеялись избавить Улага от чар, но не смогли. Довольно ему томиться в темнице плоти. Освободи его. Для этого его придётся убить. Воспользуйся переключателем в мавзолее к северу отсюда. Это позволит снять с Улага магические путы. Сними их и... будь готова!" },
    ["1819c"] = { common = "Молодец. Улаг был серьёзным сторонником Плети. Тебе удалось доказать стражам смерти и через них Тёмной Госпоже, что ты опытный и умелый воин и заслуживаешь дальнейшего обучения." },
    ["1820a"] = { common = "Тебе удалось услужить Тёмной Госпоже, пришло время услужить одному из её подданных. Колману Фартингу нужен воин, который сможет отомстить врагам Отрёкшихся. Коулман сидит в таверне \"Петля висельника\", в восточной части Брилла." },
    ["1820c"] = { common = "Да, это правда. Мне нужна помощь закалённого воина. Средств у меня немного, зато ты послужишь не только мне, но и делу Отрёкшихся. Так что если ты справишься, наградой будет почёт." },
    ["1821a"] = { common = "При жизни я служил семье Агамондов, и именно из-за них и умер! Поделом им, они стали теперь безмозглыми прислужниками Короля-лича. Мне же хочется лишить их остатков чести. Ступай в Семейную усыпальницу Агамондов и принеси их фамильное оружие: меч, топор, кинжал и палицу. Склеп находится севернее мельниц Агамондов. Его стерегут бойцы Плети и сами неупокоенные Агамонды." },
    ["1821c"] = { common = "А! Вот оно! Итак, проклятые земли Агамондов лишены остатков чести и памяти. Отныне семьи воистину не существует!" },
    ["1822c"] = { common = "Я буду хранить эти три оружия, которые ты вернул мне, как память о моей боли и потере. Пожалуйста, путник, выбери одно из четырёх оружий. Пусть оно послужит тебе больше, нежели своим бывшим, проклятым владельцам." },
    ["1823a"] = { common = "Ты уже опытный воин, и имя твоё на слуху у многих. Может быть, ты хочешь пройти испытание Руги Тотэма Гнева? Коли так, отправляйся в Лагерь Таурахо, в Степи. Он ждёт всех воинов, что готовы принять его вызов." },
    ["1823c"] = { common = "Ты хочешь пройти испытание?" },
    ["1824a"] = { common = "Чтобы пройти это испытание, тебе придётся отправиться на юг, к Полям Великанов. Там ты встретишь полчища ползучих существ, похожих на насекомых. Они явились в Степи незванными, и мне они совсем не нравятся. Принеси их усики. Главное, чтобы они всё ещё дёргались, поэтому тебе придётся поторопиться. Добудь мне усики за отведённое время, и я сочту, что испытание пройдено." },
    ["1824c"] = { male = "Отличная работа! Ты прошёл испытание на Полях Великанов, сделав тем самым ещё один шаг по тропе воина.", female = "Отличная работа! Ты прошла испытание на Полях Великанов, сделав тем самым ещё один шаг по тропе воина." },
    ["1825a"] = { common = "Слухи о твоих доблестных подвигах во славу Орды дошли до знаменитого орочьего кузнеца, Тун'грима Огневзора. Он хотел бы сделать для тебя доспехи, но тебе надо как можно скорее с ним встретиться. Тун'грим живёт на востоке от Перекрёстка, что в Степях." },
    ["1825c"] = { male = "Да, ты пришёл. Отлично, нам с тобой многое придётся обсудить.", female = "Да, ты пришла. Отлично, нам с тобой многое придётся обсудить." },
    ["1838a"] = { common = "Я наслышан о твоей силе и доблести и хочу сделать для тебя броню, которая охранит тебя в бесчисленных сражениях. Впрочем, создание такой брони – само по себе подвиг. Мне понадобится твоя помощь, а также помощь других кузнецов Орды. Возьми этот список. Я составлял его не одну ночь, напряжённо вглядываясь в пергамент почти незрячими глазами. Принеси мне всё перечисленное, и я создам тебе первую часть доспеха." },
    ["1838c"] = { male = "Ты принёс всё, что я просил. Теперь дело за мной...", female = "Ты принесла всё, что я просил. Теперь дело за мной..." },
    ["1839a"] = { common = "Кузнец-тролль по имени Ула'елек готов выковать для тебя рукавицы жестокости. Он живёт в Дуротаре, в деревне Сен'джин, вместе со своими собратьями из племени Чёрного Копья, и с нетерпением ждёт твоего прихода." },
    ["1839c"] = { common = "Привет тебе. Старый Тунгрим предупредил меня о твоём приходе, но умолчи он, я не удивился бы твоему появлению. Духи следят за каждым твоим шагом, юный воин, и они говорят, что от твоей руки пало немало врагов." },
    ["1840a"] = { common = "Искусство Орма Каменного Копыта пользуется заслуженным уважением. Он и сделает тебе шлем Жестокости. Его можно найти в Громовом Утёсе, рядом с прудом и центральным тотэмом города." },
    ["1840c"] = { common = "Привет тебе, воин. Я Орм. Тунгрим сказал, что тебе нужен шлем. Это правда?" },
    ["1841a"] = { common = "Говорят, что при жизни Велора Нители была одним из лучших кузнецов Лордерона. Кажется, она и после смерти не лишилась таланта. Поговори с Велорой, она сделает тебе набедренники Жестокости. Велора трудится в Подгороде Лордерона, в торговом квартале." },
    ["1841c"] = { common = "Тебе нужны набедренники? Отлично! Хм... Тогда кто из нас будет их делать? Шутка. Смешно? Я вот не понимаю... Чувство юмора я утратила одновременно с обонянием. Примерно в те времена, как перестала дышать." },
    ["1842a"] = { common = "Я могу сделать для тебя пару рукавиц Жестокости, напитав их магической силой. Но прежде тебе придётся добыть эту самую силу. В северо-восточной части Ясеневого леса живут сатиры. Их привлекла туда сила леса. Они питаются его первозданной чистотой, искажая и оскверняя её. Сатиров, вобравших в себя особенно много магии Ясеневого леса можно отличить от других по разбухшим, нераздвоенным копытам. В этих копытах содержится великая сила. Они понадобятся мне для создания рукавиц." },
    ["1842c"] = { common = "Ага, вот и они! Сатиры похитили силу Ясеневого леса, а их сила вольётся в моё творение..." },
    ["1843c"] = { common = "Спасибо путник. Эти рукавицы, моя лучшая работа. Возьми их." },
    ["1844a"] = { male = "Я сделаю тебе шлем, но прежде докажи, что достоин его. В северной части Когтистых гор лежит Обугленная долина. Некогда она была цветущей рощей, но теперь от деревьев остался лишь пепел, а все живущие там существа исполнены боли и отчаяния. Туда тебе и придётся отправиться. Ступай в Обугленную долину и найди там химеру-матриарха. Избавь её от страданий. Принеси в доказательство её гибели гальванизированный рог, и я сделаю тебе шлем.", female = "Я сделаю тебе шлем, но прежде докажи, что достойна его. В северной части Когтистых гор лежит Обугленная долина. Некогда она была цветущей рощей, но теперь от деревьев остался лишь пепел, а все живущие там существа исполнены боли и отчаяния. Туда тебе и придётся отправиться. Ступай в Обугленную долину и найди там химеру-матриарха. Избавь её от страданий. Принеси в доказательство её гибели гальванизированный рог, и я сделаю тебе шлем." },
    ["1844c"] = { male = "Что же, задание выполнено. Теперь я не сомневаюсь в твоей решимости и храбрости. Ты заслужил шлем...", female = "Что же, задание выполнено. Теперь я не сомневаюсь в твоей решимости и храбрости. Ты заслужила шлем..." },
    ["1845c"] = { common = "Я отдаю этот шлем тебе. Великие деяния привели тебя ко мне, путник, и сама Мать-Земля готова сопутствовать тебе." },
    ["1846a"] = { common = "Чтобы создать набедренники Жестокости, мне понадобятся прочные берцовые кости. У орков из клана Драконьей Пасти крепкие ноги. Они-то мне и нужны. Но только самые прочные. Непременно проверь их, прежде чем счесть подходящими. Если ты сможешь сломать их голыми руками, значит, они не достаточно прочные." },
    ["1846c"] = { male = "Молодец! На вид они крепкие. Пожалуй, подойдут. Орки не возражали? Сильно жаловались? Опять я пошутила. Ты не смеёшься. Что-то у меня не так с чувством юмора...", female = "Умница! На вид они крепкие. Пожалуй, подойдут. Орки не возражали? Сильно жаловались? Опять я пошутила. Ты не смеёшься. Что-то у меня не так с чувством юмора..." },
    ["1847c"] = { common = "Вот твои набедренники, путник." },
    ["1848c"] = { common = "Я уверен, ты пережил не мало трудностей и пролил не мало крови, выполняя мою просьбу, путник. Вот результат твоего труда." },
    ["1858a"] = { common = "Загляни в сумку Тазана и принеси мне то, что найдёшь внутри. Замок там непростой, так что постарайся раздобыть ключ. На трупе Тазана ключа не было? Значит, он его кому-то отдал... Ах, ну да, конечно. У него был помощник, Гамон. Он пьяница, так что ищи его в тавернах. Возможно, тебе удастся потихоньку утащить у него ключ." },
    ["1858c"] = { male = "Так-так, интересно... Что ж, ты полностью оправдал моё доверие. Отныне можешь считать себя членом клана Изувеченной Длани. И возьми это. Думаю, он тебе очень пригодится в будущем.", female = "Так-так, интересно... Что ж, ты полностью оправдала моё доверие. Отныне можешь считать себя членом клана Изувеченной Длани. И возьми это. Думаю, он тебе очень пригодится в будущем." },
    ["1859a"] = { common = "Говори тише! Ну да, я знаю твоё имя. Мне сказали, чтобы я ждал одного орка, и дали описание твоей внешности. Судя по тому, что о тебе рассказывают, ты неплохо держишься в открытом бою, но можешь прибегнуть и к хитрости, верно? В общем, сходи в Оргриммар, поговори с Терзоком. У него есть для тебя предложение." },
    ["1859c"] = { common = "А, это ты! Очень хорошо, что Каплак сумел тебя перехватить. Нам нужно поговорить кое о чём, не в последнюю очередь – о твоём будущем в Раздробленной Руке." },
    ["1860a"] = { common = "У нас, магов, есть одна задача, которая жизненно важня для безопасности Штормграда и Элвиннского леса. Подробности ты можешь узнать у Джиннии Пушки. Она работает в Башне магов, в районе магов в Штормграде. Не мешкай." },
    ["1860c"] = { common = "Тебя послали мне на подмогу? Хорошо. Приятно видеть, что молодые маги рады внести свой вклад в общее дело… Какое дело, спросишь ты? Вырастешь – узнаешь. Обязательно узнаешь... со временем." },
    ["1861a"] = { common = "Этот мир пал жертвой магических войн, в результате которых нарушилось течение магической энергии. Мы попытались просчитать дальнейшие последствия, и многие из нас опасаются худшего! Но об этом мы поговорим позже. Для начала надо собрать все доступные сведения. Возьми этот сосуд, отправляйся к подножию водопада у Зеркального озера, что на юго-западе от Врат Штормграда, и принеси мне пробу тамошней воды. Я хочу исследовать её на предмет заражения тлетворной магией." },
    ["1861c"] = { common = "Спасибо. Я исследую магические свойства этой воды. Будем надеяться, что их не окажется, а то, неровен час, окажется, что магия повлияла на всех, кто пил много воды из Зеркального озера. Возьми эту сферу или этот посох в знак моей благодарности за услугу. Пускай они служат тебе верой и правдой." },
    ["1879a"] = { male = "Бинк, моя коллега-гном из Стальгорна, прислала мне весточку. У неё возникла небольшая проблема, а обращаться за помощью ни к кому, кроме мага, она не хочет. Ты готов ей помочь? Если да, то поговори с ней. Бинк проводит большую часть времени в Зале Тайн в Палатах Магии Стальгорна.", female = "Бинк, моя коллега-гном из Стальгорна, прислала мне весточку. У неё возникла небольшая проблема, а обращаться за помощью ни к кому, кроме мага, она не хочет. Ты готова ей помочь? Если да, то поговори с ней. Бинк проводит большую часть времени в Зале Тайн в Палатах Магии Стальгорна." },
    ["1879c"] = { common = "О, я вижу в тебе неплохие задатки, да-да! Но чтобы стать хорошим магом, одних задатков мало. А не сликшом хороший маг – плохой маг. А из-за плохих магов и возникают все проблемы! Ой, кажется, я немного забегаю вперёд. Начнём сначала!" },
    ["1880a"] = { common = "Мы, маги, не просто щёлкаем пальчиками и создаём забавные искорки! Мы контролируем поток магической энергии, основной ткани мироздания! Для этого требуется осторожность и решимость. И знания... Невероятно много знаний! Одно из моих устройств, маг-тастический гизмонитор, позволяет собирать и хранить множество знаний! Но увы, он утрачен! Когда мы бежали из Гномрегана, я оставила его в сундуке в одном из домишек за пределами города. Теперь там кишмя кишат лепрогномы! Прошу тебя, верни мне гизмонитор!\"" },
    ["1880c"] = { common = "О, радость! Создавая гизмонитор, я и не догадывалась, в какую зависимость от него попаду! Теперь я могу возобновить свои исследования. Спасибо! Вот, смотри. Это мой первый набор магических инструментов. Они не так блестят, как новые, зато проверены временем. Выбирай любой из них – все они могут тебе пригодиться." },
    ["1881a"] = { common = "У Анастасии Хартвелл есть задание, которое тебе как раз по плечу. Поговори с ней. Она живёт в квартале магов в Подгороде. Готовься выполнить первое задание для магов Отрёкшихся." },
    ["1881c"] = { male = "Привет тебе. Ты правильно поступил, откликнувшись на мой зов, но ещё правильнее будет меня выслушать...", female = "Привет тебе. Ты правильно поступила, откликнувшись на мой зов, но ещё правильнее будет меня выслушать..." },
    ["1882a"] = { common = "Чумные земли – гнусное место, творение Короля-лича. Он отравил землю, осквернил и убил всё живое. Хотя в убийственной силе чумы есть что-то привлекательное, мы, маги Отрёкшихся, считаем её неуправляемой и недопустимой. Для начала надо понять, проникла ли она в Тирисфаль. Отправляйся на ферму Балнира в восточной части Тирисфаля. В саду растут цветы – львиный зев. Собери их и возвращайся." },
    ["1882c"] = { common = "Отличные цветы. Я отправлю их на изучение нашим аптекарям. Пусть поищут в них скверну Проклятых земель. Молодец. Я предлагаю тебе выбрать награду – сферу или посох. И то, и другое может тебе здорово пригодиться." },
    ["1883a"] = { common = "Ун'Тува, маг деревни Сен'джин, обнаружил изменения в потоках магической энергии Дуротара и просит тебя о помощи. Поговори с ним и сделай всё, что сможешь. Приди к нему на помощь, и со временем тебе откроются великие тайны." },
    ["1883c"] = { male = "Привет тебе. Хвала тебе, ибо ты ответил на мой зов о помощи. Будем надеяться, что ты справишься с заданием...", female = "Привет тебе. Хвала тебе, ибо ты ответила на мой зов о помощи. Будем надеяться, что ты справишься с заданием..." },
    ["1884a"] = { common = "Оказывается, нормальное течение магической энергии в Дуротаре нарушил чернокнижник Залазан с островов Эха. Для этого он разместил осквернённые фетиши, груды джуджу, среди домов центрального острова Эха. Из-за этого болеет здешнее зверьё, а чернокнижники и пришельцы из преисподней, таящиеся во тьме, набираются силы. Необходимо уничтожить эти груды джуджу, прежде чем наши земли изменятся до неузнаваемости." },
    ["1884c"] = { common = "Я чувствую, что груды джуджу уничтожены. При удаче все труды Залазана пойдут насмарку и в Дуротаре восстановится нормальное течение магической энергии. Твой подвиг во имя Орды достоин всяческой хвалы!" },
    ["1885a"] = { common = "Вот уж не ожидал вас увидеть после того, как вами заинтересовался сам Каркад. Ничего нельзя сказать наперёд... В любом случае, вам лучше встретиться с ним, и поскорее. Лучше вам не знать, что стало с теми несколькими глупцами, которые проигнорировали вызов от него." },
    ["1885c"] = { common = "Хм. Несомненно, вы пришли сюда по первому моему зову, так? Не ожидал ничего иного от перспективного стража смерти." },
    ["1886a"] = { common = "Чтобы вступить в ряды стражей смерти, элитной охраны лорда Вариматраса, тебе придётся сперва доказать свои способности. Не буду лгать: это задание может окончиться твоей гибелью. Мне нужна помощь в нескольких вопросах. Во-первых, принеси мне личные вещи Астора Хадрена – это вестник, путешествующий между Серебряным бором и Подгородом. Как ты это сделаешь - тебе решать. Пока что это всё, что тебе следует знать. Справишься - узнаешь больше." },
    ["1886c"] = { common = "Неплохо. Первая часть испытания пройдена. Надеюсь, Андрон ничего не узнал о твоих действиях, и ты сможешь убедить его, что ты и есть тот вестник, которого он ждёт." },
    ["1898a"] = { common = "Рекомендательное письмо должно убедить Андрона, что ты – тот самый гонец, которого он ждал. Мне приходилось встречаться с Андроном, он не настолько умён, чтобы заподозрить неладное. Лорд Вариматрас подозревает, что Андрон тайно помогает другой группировке, и тебе предстоит выяснить, какой именно. Хорошо бы также получить доказательства. Поговори с Андроном и вытяни из него эти сведения. Его можно найти в лавке неподалёку от Района Фармацевтов." },
    ["1898c"] = { common = "Ах да, я ждал тебя. Полагаю, наши общие знакомые довольны переданными сведениями? Боюсь, тебя спрашивать без толку, вряд ли тебя обременяют лишними знаниями. К чему доверять гонцу слишком много тайн?" },
    ["1899a"] = { common = "Гроссбух с необходимой твоим нанимателям информацией стоит на книжной полке за моей спиной. Передай его заказчикам вместе с поклоном от меня и сообщи, что, если они оценят полученные сведения и захотят продолжить наше сотрудничество, я предпочёл бы иметь дело с тобой." },
    ["1899c"] = { common = "Ну и ну, я и не рассчитывал вытянуть столько информации из Андрона. Дай-ка я изучу этот гроссбух повнимательнее и дам тебе следующее задание." },
    ["1918a"] = { common = "Из убитого элементаля выпала ярко светящаяся сфера воды. Содержимое шара в лучшем случае отвратительно. Можно с уверенностью сказать, что то, что заразило воды озера Мистраль, находится в этой сфере. Так сразу и не скажешь, кого может заинтересовать эта находка – возможно, подскажет тот, кто послал вас к этому озеру, а именно Мисток Райльшип с заставы Расщеплённого Древа." },
    ["1918c"] = { male = "Ты нашёл какой-то грязный шар с водой и решил принести его мне? Я кто, по-твоему – представитель Служителей Земли или что? Вообще-то, у меня появилась кое-какая идея... может, тебе и правда понадобится помощь Служителей Земли. В смысле, если это поможет разрешить ситуацию на озере, то я к твоим услугам. Ты знаешь, кто такие Служители Земли?", female = "Ты нашла какой-то грязный шар с водой и решила принести его мне? Я кто, по-твоему – представитель Служителей Земли или что? Вообще-то, у меня появилась кое-какая идея... может, тебе и правда понадобится помощь Служителей Земли. В смысле, если это поможет разрешить ситуацию на озере, то я к твоим услугам. Ты знаешь, кто такие Служители Земли?" },
    ["1919a"] = { male = "Ты набираешься знаний и опыта, юный путник. Ты готов приступить к подлинному обучению и принять участие в непрекращающейся тайной войне? Если да, поговори с Джиннией Пушкой в Башне магов в квартале магов Штормграда. У неё есть для тебя задание, которое впервые приоткроет окно в невидимый мир.", female = "Ты набираешься знаний и опыта, юная путница. Ты готова приступить к подлинному обучению и принять участие в непрекращающейся тайной войне? Если да, поговори с Джиннией Пушкой в Башне магов в квартале магов Штормграда. У неё есть для тебя задание, которое впервые приоткроет окно в невидимый мир." },
    ["1919c"] = { common = "У меня есть для тебя задание. Да-да, прямо здесь, в квартале магов. Слушай внимательно, не будем терять время даром." },
    ["1920a"] = { common = "Сообщают о беспорядках в таверне \"Синий отшельник\", что в квартале магов. Там бродят странные невидимые существа, чувствую там образовался провал Маны. Отправляйся туда и поймай этих тварей. Чтобы они стали видимыми, воспользуйся заклятьем Проявления, одолей их и посади в шкатулки-духоловки. Как только наберёшь достаточно этих тварей, возвращайся ко мне с заполненными шкатулками, пустыми шкатулками и заклинанием." },
    ["1920c"] = { male = "Ну ты молодец! Я займусь изучением этих существ, и при удаче пойму, как они ухитрились пробраться в наш мир. Ты приносишь сообществу магов всё больше пользы.", female = "Ну ты умница! Я займусь изучением этих существ, и при удаче пойму, как они ухитрились пробраться в наш мир. Ты приносишь сообществу магов всё больше пользы." },
    ["1921a"] = { common = "За верную службу своим собратьям-магам тебе полагается одеяние волшебника. Его вполне может сшить Уинн Ларсон, если ты принесёшь ей всё необходимое. Само одеяние шьётся из льна, который легко найти, но кроме него понадобятся заряженные самоцветы Расселины, а их добывают исключительно в Руднике у Серебряного ручейка у озера Лок Модан. Горняки дворфов не смогли забрать их, и они лежат в ящиках по всему руднику. Набери льна, добудь самоцветы и принеси их Уинн Ларсон в суконную лавку Ларсона в район магов." },
    ["1921c"] = { common = "Да, превосходный лён. Из него выйдет отличная ряса. А после того, как я разошью её самоцветами, получится настоящее одеяние для мага!" },
    ["1938a"] = { common = "Давным-давно в этой башне жили три мага, и один из них поддался искушению и занялся тёмными искусствами. Его уговаривали отказаться от чёрной магии, но тщетно. И он был изгнан. Новое пристанище изгнанного мага – башня Илгалара в Красногорье. Он унёс с собой ценную книгу – Трактат Ура по тёмной магии. Мы, маги Штормграда, хотим вернуть себе эту книгу. Отправляйся в башню Илгалара, найди этот фолиант в библиотеке и принеси мне." },
    ["1938c"] = { common = "Я опасался, что Моргант спрятал книгу где-то ещё или же нашёл способ открыть её и прочесть. Хорошо, что он не успел, и что все печати, наложенные на этот трактат, сохранились в целости." },
    ["1939a"] = { common = "С тобой хочет поговорить верховный колдун Андромат. Он находится на верхнем этаже Башни магов, в квартале магов Штормграда. Обязательно поговори с ним, ведь Андромат – один из самых могущественных магов за пределами Даларана. Его совет стоит десяти других." },
    ["1939c"] = { common = "Привет тебе. Рад тебя видеть. Надеюсь, у тебя найдётся время выслушать старика..." },
    ["1940a"] = { common = "Пожалуй, следует наградить тебя за безупречную службу. Пора тебе обзавестись одеянием, которое пристало носить магу твоего уровня. Если тебе удастся собрать все необходимые материалы, одеяние у тебя будет. Ступай в Сумеречный лес и убей побольше пауков, падальщиков-отшельников. Набери их паутины, только учти, годится лишь самая лучшая. Набрав достаточно паутины, отнеси её Уинн Ларсон, которой принадлежит магазин \"Суконная лавка Ларсона\" в Квартале Магов. Она сошьёт тебе одеяние." },
    ["1940c"] = { common = "Неплохая паутина. Я немедленно примусь за работу!" },
    ["1941c"] = { common = "Вот твоё одеяние. Носи его с гордостью. Если тебя спросят, откуда достал… скажи что у Ларсона!" },
    ["1942c"] = { common = "Твоё одеяние готово! И принесённый тобою шёлк был просто прекрасен." },
    ["1943a"] = { common = "Магу Дейно нужна твоя помощь. Она живёт в Оргриммаре, в пристанище Темнотерна." },
    ["1943c"] = { common = "Хорошо, что ты здесь. Я хочу дать тебе довольно сложное задание. Оно жизненно важно для всего сообщества магов. Помоги мне, и маги отплатят тебе сторицей." },
    ["1944a"] = { common = "В восточной части Ясеневого леса раскинулся прославленный город Ксавиан. Учёные всех народов слышали легенды о хранимом в нём древнем знании. Говорят, что воды Ксавиана содержат немало магической энергии. Мне нужна проба воды из Ксавиана. Возьми этот сосуд и ступай туда. Набери воды у подножия самого большого водопада и возвращайся ко мне. Соблюдай осторожность – руины древнего города заполонили сатиры, им не нравится, когда в их дела встревают маги." },
    ["1944c"] = { common = "А, отлично. Надеюсь, сатиры Ксавиана тебе не слишком сильно помешали? Спасибо. Я немедленно займусь изучением пробы воды из Ксавиана." },
    ["1945a"] = { common = "За верную службу тебе полагается новое одеяние, если ты принесёшь все необходимые материалы. Тебе придётся вернуться в Ясеневый лес за локонами волос Смеющихся сестёр – дриад, бродящих возле Приюта в Ночных Лесах. Добыв их волосы, отнеси их Кил'хале, троллю-портному с Перекрёстка, что в Степях. Он-то и сошьёт тебе одеяние." },
    ["1945c"] = { common = "А, из этих волос выйдет отличное одеяние. Жаль, что приходится убивать Смеющихся сестёр ради добычи волос, впрочем, добровольно они их всё равно не отдали бы. Жаль, но не очень." },
    ["1946c"] = { common = "Вот твоё одеяние из кружева Пустоты, путник." },
    ["1947a"] = { common = "Пришло время заслужить магический жезл. Для начала поговори с отшельницей из Пылевых топей, человеком по имени Табета. Она живёт в хижине в глубине болота, на западе от Терамора. Её познания велики, и она сможет дать тебе добрый совет. Хижина Табеты находится чуть севернее руин Деревни Каменного Молота." },
    ["1947c"] = { common = "Тихо! Я занята очень тонкой работой и меня нельзя отвлекать! Одну минуту…" },
    ["1948a"] = { common = "Создать жезл мага не так-то просто. Приходится собирать редкие компоненты, да и конструировать его надо так, чтобы он вмещал побольше магической энергии. Собери всё необходимое и принеси мне. Я составил список компонентов и заодно указал, где их искать. Буквально следуй моим указаниям, в противном случае при попытке создать жезл может случиться большая неприятность!" },
    ["1948c"] = { male = "Ага! Тебе удалось найти нефрит и сделать шипастый жезл! Молодец! У тебя что, из ушей дым идёт? Наверное, ты подошёл слишком близко, когда молния била в заготовки. Такое случается. Не расстраивайся, получить удар молнии – хорошая примета!", female = "Ага! Тебе удалось найти нефрит и сделать шипастый жезл! Умница! У тебя что, из ушей дым идёт? Наверное, ты подошла слишком близко, когда молния била в заготовки. Такое случается. Не расстраивайся, получить удар молнии – хорошая примета!" },
    ["1949a"] = { common = "Для создания жезла мне нужно прочитать некоторые разделы одной книги. Называется она \"Ритуалы Силы\", а написал её волхв Тирт. У меня её нет, да и ни в одной библиотеке её не сыскать. Поэтому придётся тебе найти Тирта и взять её у него. Удачи. Когда-то он был великим магом и учёным, но теперь большую часть времени проводит на гоночном поле на Мерцающей равнине, пьёт и играет в азартные игры." },
    ["1949c"] = { common = "Что? Говори громче! У меня не такой острый слух, как бывало. Надеюсь, ты несёшь мне кружку свежего эля или верные сведениями о следующей гонке! Если нет, проваливай... А то у меня наготове жезл превращения!" },
    ["1950a"] = { common = "Я помогу тебе с книгой, но сначала окажи мне услугу! Нужная тебе книга заодно и магический сейф. Он открывается особой фразой, и её-то я и забыл! Обычно мне напоминает помощник, но он куда-то запропал. Если тебе нужна книга, найди моего помощника! Поспрашивай у зрителей, при удаче кто-то мог его видеть. Притащи его сюда или выбей из него волшебные слова!" },
    ["1950c"] = { common = "Ах да, припоминаю… Я и правда наложил на Джонсона проклятье. Не помню, зачем я это сделал, но так ему и надо, маленькому нахалу!" },
    ["1951a"] = { common = "Хм... Оказывается, книги-то у меня и нет! Видишь ли, мне пришлось отдать последнюю копию за игорные долги какому-то жрецу... Одному из Алого ордена. Наверное, он унёс её в монастырь в Тирисфальские леса! Если тебе так нужна книга, придётся сходить за ней в монастырь. Прости за доставленные неудобства. Я в последнее время сам не свой..." },
    ["1951c"] = { common = "Вот она! То что нужно для последнего обряда создания жезла! Надеюсь, поиски были не слишком сложными?" },
    ["1952a"] = { common = "Пойду, займусь созданием жезлов." },
    ["1952c"] = { common = "Ну вот, жезлы готовы. Выбирай любой!" },
    ["1953a"] = { common = "Пришло время поговорить с Табетой... отшельницей из Пылевых топей. Она научит тебя создавать могущественные магические инструмены. Хижина Табеты находится в глубинах Пылевых топей, западнее Терамора." },
    ["1953c"] = { common = "Ах, да. Тебе нужна сфера или жезл? Ну, хорошо. Я помогу тебе. Впрочем, знай. Это очень опасно и может привести к твоей гибели. Или моей гибели. В общем, кому-то умереть придётся… Будем надеяться, что не нам, а?" },
    ["1954a"] = { common = "Первым делом тебе нужно заполучить сферу силы. У чернокнижников из клана Пылающего Клинка очень подходящие сферы... Жаль, что в каждой из них заключён демон! Но это поправимо, и очень даже. Отправляйся в Пустоши и отбери сферу подземного огня у призывателя из клана Пылающего Клинка. Призыватели живут на поле Маннорок. Как получишь сферу, возвращайся." },
    ["1954c"] = { common = "Ага, недурная сфера. Не в том смысле недурная, как охлаждённая вода с соком в жаркий день. Более того, она вовсе НЕ недурная, если посмотреть повнимательнее. Да не вода, сфера! Сосредоточься! Иначе с этим заданием не справиться!" },
    ["1955a"] = { common = "У нас есть сфера призывателя, остаётся изгнать из неё демона.С этим я легко справлюсь. Тебе придётся куда труднее. Как только демон изойдёт из сферы, убей его. Главное – не медлить. Если ты провозишься слишком долго, он вернётся в сферу и нам придётся начать сначала! Готовься к схватке. Вспомни самые сильные заклинания и держи под рукой зелья. Если у тебя есть друг, можешь позвать его. Сражение будет нелёгким." },
    ["1955c"] = { common = "Великолепно. Тебе удалось преподать этому демону урок, который он надолго запомнит. Теперь он трижды подумает, прежде чем вновь сунуться в наш мир. Однако если это произойдёт, единственной целью демона будет найти того дерзкого смертного, что одолел его когда-то. Скорее всего, он вернётся с приятелями. Огромными, жуткими приятелями, жаждущими твоей крови. Ну что, тебе уже страшно?" },
    ["1956a"] = { common = "Демон уничтожен, остаётся завладеть источником энергии. К сожалению, самые лучшие источники энергии – старые, и заполучить их нелегко. Судьба любит над нами подшутить, а? Итак, тебе придётся отправиться в Ульдаман и победить тамошнего обсидианового часового. Он большой и сильный, а уж какой у него источник энергии! Удачи тебе. Ну, а если она от тебя отвернётся... приятно было познакомиться." },
    ["1956c"] = { male = "Ты сделал это? Молодец. Я общалась с некоторыми моими коллегами и когда я случайно назвала твоё имя, то они сказали: \"Да, мы знаем путник, и он не поддаётся стрессу, даже в критических ситуациях\". Но когда я сказала, что послала тебя в Ульдаман против обсидианового стражника, они не поверили, что ты выполнишь задачу. А я сказала им – вот увидите! Что-ж, мы им показали, не так ли?", female = "Ты сделала это? Умница. Я общалась с некоторыми моими коллегами и когда я случайно назвала твоё имя, то они сказали: \"Да, мы знаем путница, и она не поддаётся стрессу, даже в критических ситуациях\". Но когда я сказала, что послала тебя в Ульдаман против обсидианового стражника, они не поверили, что ты выполнишь задачу. А я сказала им – вот увидите! Что-ж, мы им показали, не так ли?" },
    ["1957a"] = { common = "Мы почти закончили, осталось самое опасное. Нужно вдохнуть силу в пустую сферу призывателя. Для этого придётся обуздать энергию провала Маны. Я произнесу заклинание, оно временно создаст нужный нам провал, из которого хлынут твари, волноловы маны. Тебе придётся одолеть их, и тогда я смогу собрать воедино их силу. Твоя задача – убить достаточно волноловов маны, пока провал открыт, а я уж соберу всю энергию в твою сферу." },
    ["1957c"] = { male = "Надо же, ты справился! Я в тебе не сомневалась! Ну ладно, чуть-чуть сомневалась, даже не чуть-чуть... Но не так уж сильно. Честно.", female = "Надо же, ты справилась! Я в тебе не сомневалась! Ну ладно, чуть-чуть сомневалась, даже не чуть-чуть... Но не так уж сильно. Честно." },
    ["1958c"] = { common = "Ты должен гордиться собой, путник. Не многие справились с теми трудностями, с которыми пришлось тебе столкнуться. Небесная сфера готова или я могу сделать посох. Всё зависит от тебя. Я бы предпочла сферу, но кто я такая, чтобы судить?" },
    ["1959a"] = { common = "Маги Подгорода заметили в городе выплеск магической энергии и обратились к чародеями Орды с просьбой выяснить, что же происходит. Подробности тебе расскажет Анастасия Хартвелл. Поговори с ней, она живёт в Квартале Магов Подгорода." },
    ["1959c"] = { common = "Это правда. В нашем городе произошёл выплеск магической энергии. Мы не поняли, что именно произошло, и даже к добру это или к худу. Не хватает информации… Что подводит нас к разговору о задании." },
    ["1960a"] = { common = "В лавке алхимика Алжернона, что в Районе Фармацевтов, происходит что-то странное. Там бродят странные невидимые существа, сотканные из магической энергии. Возьми у меня за спиной шкатулки-духоловки и свиток с нужным заклинанием. Воспользуйся свитком в лавке, подчини этих существ и загони их в шкатулки. Как только наберёшь достаточно, возвращайся ко мне с заполненными шкатулками, пустыми шкатулками и заклинанием." },
    ["1960c"] = { common = "Отлично. Лучшие умы Подгорода займутся изучением невидимых тварей. Мы выясним, откуда они взялись в нашем городе. Если дело в возникновении провала Маны, потребуется определить, случайно он возник или нет. Если не случайно,а в результате действий враждебных сил, нам придётся готовиться к появлению более серьёзных противников." },
    ["1961a"] = { common = "Тебе пора обзавестись первым облачением мага. Одеяние – знак твоего особого положения, свидетельство твоего достоинства. Для создания нужного одеяния тебе понадобятся самоцветы маны от даларанских магов из Серебряного бора. Они верят примерно в то же, во что и мы, поэтому убивать их нехорошо, но раз они не могут противостоять нам, значит жизни они не заслуживают. Отнеси камни и несколько кусков льна Джозефу Грегориану в суконную лавку Квартала Магов." },
    ["1961c"] = { common = "Отличный материал. Оценить качество самоцветов я не могу, но вскоре мы узнаем, подходят ли они для создания одеяний из чароткани..." },
    ["1962c"] = { common = "Вот твоё одеяние, путник. Носи с удовольствием." },
    ["1963a"] = { common = "Вождь слишком хитрит и осторожничает. Он не хочет пускать в ход всю мощь Орды. Изувеченная Длань вернёт Орде былую гордость! Мы тайно копим силы и исподтишка наносим удары неосторожным врагам. Докажи свою доблесть, выполни моё задание! Тролль по имени Тазан торгует с пиратами близ Кабестана. У него есть нужные мне сведения. Убей его и принеси мне его сумку." },
    ["1963c"] = { common = "Хм. Я, конечно, рад слышать, что Тазана больше нет в живых, однако от запертой сумки проку мало. Нам нужно то, что внутри! Вот и второе задание для того, кто стремится вступить в клан Изувеченной Длани!" },
    ["1978a"] = { male = "Синдикат? Никогда бы не подумал. Низко же пали владыки Альтерака после предательства. Лорд Вариматрас будет доволен, и раз именно ты совершил это открытие – тебе и сообщать о нём. Ах да, как я мог забыть? Добро пожаловать в ряды стражей смерти.", female = "Синдикат? Никогда бы не подумал. Низко же пали владыки Альтерака после предательства. Лорд Вариматрас будет доволен, и раз именно ты совершила это открытие – тебе и сообщать о нём. Ах да, как я мог забыть? Добро пожаловать в ряды стражей смерти." },
    ["1978c"] = { common = "Хм, любопытно. Стражи смерти превосходно справились со своими обязанностями. Судя по всему, ты ждёшь благодарности за свои подвиги. Скоро это станет для тебя привычным делом. Стражам смерти не помешают талантливые новички." },
    ["1998a"] = { male = "Лорд Вариматрас сообщил мне о грозящей Отрёкшимся опасности, с которой следует немедленно разобраться. Во всём виноват Фенвик Татрас, вождь нежити, поселившейся в Серебряном бору. Я немедленно вспомнил о тебе, и сразу понял, кому следует доверить это задание. Ты не обделён талантами и выполнишь поручение безукоризненно. По последним сведениям от стражей смерти, Татроса видели неподалёку от разрушенной пристани озера Лордамер.", female = "Лорд Вариматрас сообщил мне о грозящей Отрёкшимся опасности, с которой следует немедленно разобраться. Во всём виноват Фенвик Татрас, вождь нежити, поселившейся в Серебряном бору. Я немедленно вспомнил о тебе, и сразу понял, кому следует доверить это задание. Ты не обделена талантами и выполнишь поручение безукоризненно. По последним сведениям от стражей смерти, Татроса видели неподалёку от разрушенной пристани озера Лордамер." },
    ["1998c"] = { male = "Прекрасно. Ты оказался достойным помощником, а посему настало время продолжить твоё обучение тёмным искусствам.", female = "Прекрасно. Ты оказалась достойным помощником, а посему настало время продолжить твоё обучение тёмным искусствам." },
    ["1999a"] = { common = "Маги братства Кирин-Тора в Янтарной Мельнице хранят важные документы, касающиеся положения дел в Даларане. Эти сведения удалось вытянуть из одного пленника. Лорд Вариматрас поручил стражам смерти добыть эти документы. Честь выполнить это задание выпала тебе. Для задания понадобится кое-какое снаряжение и умение вскрывать замки. Поговори с Эстеллой Джендри, она поставляет нам обмундирование. Попроси у неё набор инструментов, перед тем как отправляться в путь." },
    ["1999c"] = { male = "Прекрасно. Тебе удалось освоить искусство вскрытия замков куда быстрее, чем я ожидал. Вижу, я был прав, положившись на тебя. Поверь, мальчик мой, ты далеко пойдёшь.", female = "Прекрасно. Тебе удалось освоить искусство вскрытия замков куда быстрее, чем я ожидал. Вижу, я был прав, положившись на тебя. Поверь, девочка моя, ты далеко пойдёшь." },
    ["2038a"] = { common = "Мало того, что они вторглись в наши края, эти трогги атаковали меня с ближайшего острова и украли мои инструменты и особую взрывчатку – сорвиголовку Покрышкинса. Без вертолёта и взрывчатки движению не обойтись! Верни мне инструменты и отыщи сорвиголовку. За Гномреган!" },
    ["2038c"] = { male = "Ты оказал движению огромную услугу. Скоро трогги и лепрогномы узнают, что такое воздушная атака!", female = "Ты оказала движению огромную услугу. Скоро трогги и лепрогномы узнают, что такое воздушная атака!" },
    ["2039a"] = { common = "Мы потеряли связь с Бинглзом! Он был отправлен в разведывательный полёт над Гномреганом, и уже неделю от него нет никаких известий. Я знаю только то, что он отправился в разведку и потерпел крушение. Последний раз его видели над озером Лок. Возможно, ты сможешь выяснить, что с ним." },
    ["2039c"] = { common = "Значит, Гноарн сомневается во мне как в разведчике? Интересно, почему... Ладно, не берите в голову, мне нужна ваша помощь! Нет! Ваша помощь нужна нашему общему делу!" },
    ["2040a"] = { common = "Гномреган захватили трогги! Ситуация крайне тяжёлая, но, быть может, вы сможете помочь. Глубоко под землёй, в Мёртвых копях, находится действующий гоблинский резак. Найдите его и принесите его источник питания. С его помощью мы сможем обеспечить наши автогиробуроройки достаточной энергией, чтобы пробиться через каменные границы Гномрегана и открыть дорогу армии гномов!" },
    ["2040c"] = { common = "Хорошая работа. Благодаря вам день освобождения Гномрегана приблизился ещё на шаг!" },
    ["2041a"] = { common = "Возможно... Возможно, вы поможете нам в битве за Гномреган. В Штормграде вы найдёте командира нашей подземной штурмовой группы, Шони Молшунью. Шони нужна помощь в сооружении автогиробуророек. Вы найдёте её среди дворфов в Штормграде. Удачи." },
    ["2041c"] = { common = "Вы с известиями от центрального командования?" },
    ["2078a"] = { male = "Эй, сухопутное создание, нужно, чтоб ты нашёл моего первого помощника. Берёшь этот ключ, вставляешь ему в башку и ведёшь сюда, чтобы он опять служил своему кэпу. Этим мурлокам и их главарю не шибко понравится, когда ими займётся мой первый помощник!", female = "Эй, сухопутное создание, нужно, чтоб ты нашла моего первого помощника. Берёшь этот ключ, вставляешь ему в башку и ведёшь сюда, чтобы он опять служил своему кэпу. Этим мурлокам и их главарю не шибко понравится, когда ими займётся мой первый помощник!" },
    ["2078c"] = { common = "Да-а-а... А ты, оказывается, больше, чем желторотая собачья акула, крыса ты сухопутная. Кэп тебя, может, даже пустит палубу драить, если так и дальше пойдёт..." },
    ["2098a"] = { common = "Жизнь пирата нелегка, сухопутное ты создание. Это не только грабежи да пьянки! Увы, мой корабль затонул совсем рядом с берегом из-за этих мерзких жесткозубов. Первое, что мне нужно, – это чтоб мой первый помощник был в рабочем состоянии! Когда меня вынесло на берег, ключ от моего первого помощника сломался от удара о скалы, и его части растащили обитающие на Тёмном Берегу звери. Краем глаза я заметил разъярённых крабов, свирепых лесных долгоходов и мурлоков, обшаривающих останки корабля..." },
    ["2098c"] = { male = "Ах ты ж, акула собачья! Тебе удалось всё найти! Скоро мой первый помощник будет в полном порядке, и эти звери не знают, что их тогда ждёт! А кстати, ты не видел моего первого помощника?", female = "Ах ты ж, акула собачья! Тебе удалось всё найти! Скоро мой первый помощник будет в полном порядке, и эти звери не знают, что их тогда ждёт! А кстати, ты не видела моего первого помощника?" },
    ["2118a"] = { common = "Болезнь расползается по Тёмному Берегу, захватывая сознания и тела всех, до кого добирается. На медведей-осотников она подействовала особенно жестоко. Некогда благородные звери стали инструментами разрушения, бешеными и неистовыми. Возможно, у меня есть средство от этой напасти. Отнеси в лес эту ловушку и положи её на землю. Любой бешеный колючешёрстный медведь, попавший в неё, станет на короткий период времени послушным. В таком состоянии он будет следовать за тобой. Приведи его сюда." },
    ["2118c"] = { common = "Наша работа только начинается. Вы готовы к следующему заданию?" },
    ["2138a"] = { common = "Как я и боялся, целительное средство не действует. Меня очень печалит, что я вынужден приговаривать к смерти создания природы, но больных колючешёрстных медведей придётся истребить. Возвращайтесь в лес и уничтожьте двадцать бешеных колючешёрстных медведей. Скорее всего, это не остановит зло, но хотя бы ненадолго замедлит наступление заразы на наш лес и его обитателей." },
    ["2138c"] = { common = "Вы сослужили большую службу Аубердину, но ваша работа на этом не закончена. Отдохните, а затем возвращайтесь ко мне. ...И, укрепитесь духом и разумом для дальнейшего кровопролития." },
    ["2139a"] = { male = "За выживание нашего народа и безопасность наших земель мы платим высокую цену. Ты пролил кровь слуг природы, сразил множество больных зверей. Народ Аубердина в долгу перед тобой, поскольку боль истерзанного леса немного утихла – пусть и ненадолго. У меня есть для тебя последнее задание, но предупреждаю: тебе снова нужно будет убивать. Надеюсь, это последний раз, когда мне приходится побуждать тебя к этому. В пещере к северо-востоку отсюда близ Башал'Арана живёт мать-медведица. Убей её.", female = "За выживание нашего народа и безопасность наших земель мы платим высокую цену. Ты пролила кровь слуг природы, сразила множество больных зверей. Народ Аубердина в долгу перед тобой, поскольку боль истерзанного леса немного утихла – пусть и ненадолго. У меня есть для тебя последнее задание, но предупреждаю: тебе снова нужно будет убивать. Надеюсь, это последний раз, когда мне приходится побуждать тебя к этому. В пещере к северо-востоку отсюда близ Башал'Арана живёт мать-медведица. Убей её." },
    ["2139c"] = { common = "Вы с честью и мужеством сражались на благо Аубердина. В наших измученных войной землях смерть и отчаяние стали нормой. Многие уже не пытаются встретить лицом к лицу испытания в нашем новом доме, их выбор – либо скрываться в своих жилищах, либо бежать в более укреплённые и безопасные земли Альянса. Спасибо вам. Может быть, вскоре мы с вами будем плечом к плечу биться против другого врага." },
    ["2158a"] = { common = "Каждому путнику рано или поздно нужно отдохнуть и восстановить силы – а для этого нет места лучше, чем таверна \"Гордость льва\". Там всем заправляет мой лучший друг Фарли. Скажи ему, что ты от меня – может, он даже скидки тебе даст на еду и выпивку. Найти \"Гордость льва\" несложно: нужно просто идти по дороге на юг. Не бойся, с пути не собьёшься!" },
    ["2158c"] = { common = "Наш девиз - покой и отдых для всех усталых и продрогших! Прошу, садись у огня, отдохни с дороги. Хочешь - отведай, чем у нас кормят, да и выпить чего-нибудь тебе не помешает..." },
    ["2159a"] = { male = "Привет тебе, юный герой. Не окажешь ли ты мне услугу? У меня тут свёрток с травами, который надо доставить в Доланаар. Но я ещё не закончил кое-какие дела с друидами Тенистой долины и пока что не могу отлучиться. Не отнесёшь ли ты посылку? Её надо доставить Кельдамиру – хозяину таверны в Доланааре. Таверна стоит у дороги к югу отсюда.", female = "Привет тебе, юная героиня. Не окажешь ли ты мне услугу? У меня тут свёрток с травами, который надо доставить в Доланаар. Но я ещё не закончил кое-какие дела с друидами Тенистой долины и пока что не могу отлучиться. Не отнесёшь ли ты посылку? Её надо доставить Кельдамиру – хозяину таверны в Доланааре. Таверна стоит у дороги к югу отсюда." },
    ["2159c"] = { common = "Ах да, травы из Тенистой долины! Жаль, что Портанниус сам не смог её доставить - нам с ним много что надо обсудить. Но я всё равно рад получить эту посылку и познакомиться с тобой. Покуда ты здесь - чувствуй себя как дома. Герои должны быть крепки телом и духом, так что если выпадает возможность отдохнуть и подлечиться, надо ей пользоваться! Забота о теле и духе только приблизит тебя к победе! Так что располагайся поудобнее..." },
    ["2160a"] = { common = "Похоже, тебе не впервой путешествовать, и трудности в дороге тебя не пугают. Что ж, раз уж ты всё равно собираешься в путь, может, заодно прихватишь и посылочку в Каранос? Её нужно отдать хозяину таверны. Ты ведь собираешь заглянуть в таверну, верно? После всего, что тебя ожидает в пути – а ожидает тебя много чего, уж можешь мне поверить, – ты наверняка захочешь отдохнуть и перевести дух. Так вот, я тебя и прошу – передай кое-что помощнику хозяина; его зовут Таннок Молот Стужи. Я сам в одиночку до Караноса не доберусь, а патруля горных пехотинцев ещё ждать и ждать..." },
    ["2160c"] = { common = "О, гляди-ка, Ручник Ржавозубчик всё-таки прислал припасы! Я уж начинал беспокоиться: с тех пор, как тут поселились трогги, из Старой Наковальни вести почти и не доходят. Я тебе очень благодарен, просто словами не передать, как. Ты тут располагайся, будь как дома, дорога-то была не из лёгких!" },
    ["2161a"] = { male = "Извини... Ты не мог бы мне помочь? У меня тут тяжеленная сумка с припасами. Я шёл по дороге, на меня нападали и скорпиды, и пауки, и ещё более страшные твари! Я нёс припасы в долину Испытаний, потому что думал, что они там нужны, а я люблю помогать. Но оказалось, что припасы им не нужны! И вот мне придётся тащить эти припасы обратно в Колючий Холм, а я так боюсь опасных тварей, обитающих тут... Не мог бы ты отнести посылку вместо меня? Я ведь простой батрак, а ты-то – герой! Ты, небось, ничего не боишься... Отнеси эту сумку хозяину таверны Гроску. Спасибо тебе большое!", female = "Извини... Ты не могла бы мне помочь? У меня тут тяжеленная сумка с припасами. Я шёл по дороге, на меня нападали и скорпиды, и пауки, и ещё более страшные твари! Я нёс припасы в долину Испытаний, потому что думал, что они там нужны, а я люблю помогать. Но оказалось, что припасы им не нужны! И вот мне придётся тащить эти припасы обратно в Колючий Холм, а я так боюсь опасных тварей, обитающих тут... Не могла бы ты отнести посылку вместо меня? Я ведь простой батрак, а ты-то – героиня! Ты, небось, ничего не боишься... Отнеси эту сумку хозяину таверны Гроску. Спасибо тебе большое!" },
    ["2161c"] = { male = "А-а, это припасы, которые Укор понёс в долину Испытаний! Что, не пригодились? Ну да, конечно, они любят морить голодом молодых героев вроде тебя. Говорят, будто это закаляет дух! Спасибо, что принёс припасы обратно. Пусть пока полежат на полочке... Погоди, не уходи, дай я тебя сначала чем-нибудь угощу! И не забудь отдохнуть у нас на постоялом дворе. Конечно, ты отважен и готов горы свернуть, но если не отдохнёшь, силёнок не будет, а это не пойдёт на пользу ни тебе, ни Орде!", female = "А-а, это припасы, которые Укор понёс в долину Испытаний! Что, не пригодились? Ну да, конечно, они любят морить голодом молодых героев вроде тебя. Говорят, будто это закаляет дух! Спасибо, что принесла припасы обратно. Пусть пока полежат на полочке... Погоди, не уходи, дай я тебя сначала чем-нибудь угощу! И не забудь отдохнуть у нас на постоялом дворе. Конечно, ты отважна и готова горы свернуть, но если не отдохнёшь, силёнок не будет, а это не пойдёт на пользу ни тебе, ни Орде!" },
    ["2178a"] = { common = "Чувствуете этот восхитительный аромат? Это мой секретный рецепт – свежесваренная похлёбка из долгонога. Настоящий деликатес! Не хотите ли узнать рецепт? Но прежде, чем я вас научу готовить это блюдо, вы должны доказать мне, что умеете управляться с долгоногами. Нет, я вовсе не жду, что вы пойдёте, приручите себе одного и приедете ко мне на нём верхом! Но если бы вы могли убить несколько птиц и принести мне их сочного мяса, это, пожалуй, убедило бы меня показать вам, как же готовится похлёбка из долгонога." },
    ["2178c"] = { common = "Фантастика! Попробуйте сами и скажите, что вы думаете об этом!" },
    ["2198a"] = { common = "Вы нашли потускневшее ожерелье, хотя даже то, что оно потускнело, не может исказить искусную, даже отчасти магическую работу создателя. Ожерелье было разрушено, поскольку в собранном виде в нём явно не хватает трёх драгоценных камней. На обратной стороне ожерелья – почти стёршаяся печать Стальгорна. Ниже печати – выгравированы три небольших буквы: \"ТдК\". Если вы хотите восстановить ожерелье, вы будете должны узнать о его происхождении. Возможно печать и эти буквы, помогут вам в этом." },
    ["2198c"] = { common = "Да, я – тот ювелир, который создал это ожерелье. Но больше ты из меня ничего клещами не вытянешь. За всё надо платить, приятель, и информация не исключение. Если ты хочешь, чтобы я тебе помог, придётся сначала помочь мне." },
    ["2199a"] = { male = "Я прославленный в нашем Стальгорне ювелир! Ну, был прославленным... У меня сейчас трудные времена, и всё из-за козней конкурента! Дурная репутация в нашем ремесле приводит к финансовому краху. И в результате моё доброе, но недавно опороченное имя теперь медного гроша не стоит. Я хочу, чтобы ты принёс мне пять серебряных слитков, чтобы я сумел закончить заказ – первый за целую вечность! Если ты принесёшь мне серебряные слитки, я отвечу на твои вопросы по поводу ожерелья.", female = "Я прославленный в нашем Стальгорне ювелир! Ну, был прославленным... У меня сейчас трудные времена, и всё из-за козней конкурента! Дурная репутация в нашем ремесле приводит к финансовому краху. И в результате моё доброе, но недавно опороченное имя теперь медного гроша не стоит. Я хочу, чтобы ты принесла мне пять серебряных слитков, чтобы я сумел закончить заказ – первый за целую вечность! Если ты принесёшь мне серебряные слитки, я отвечу на твои вопросы по поводу ожерелья." },
    ["2199c"] = { common = "Для меня теперь нет дороже друга, и плевать, что скажут другие... шучу, шучу! Правда, спасибо тебе огромное! Итак, ожерелье, которое теперь у тебя, – одно из лучших моих творений, но в нём не хватает трёх драгоценных камней, что помогали удерживать в нём магическую силу. Некоторое время назад я сделал его для одного паладина. Он по личному побуждению отправился в поход, дабы выжечь \"злую скверну\" с раскопа в Бесплодных землях, в месте, называемом Ульдаман. В общем... этот паладин погиб в Ульдамане, и это стало началом моих горестей." },
    ["2200a"] = { common = "Мой конкурент распустил слухи, что моё ожерелье проклято и что оно-то и сгубило паладина. Нечего и говорить, что покупателей на проклятые ювелирные изделия больше не нашлось. Я предлагаю тебе сделку – найди драгоценные камни, и я восстановлю ожерелье, а ты расскажешь всем, что на моих изделиях НЕТ никакого проклятия! Попытайся найти разгадку гибели паладина в Ульдамане – может, его тело всё ещё там, ведь он последний владел этим ожерельем! Когда ты найдёшь камни, воспользуйся вот этим – так ты сможешь связаться со мной в Стальгорне." },
    ["2200c"] = { common = "В дневнике говорится, что после больших усилий паладин выяснил, где находятся все три камня: Рубин спрятан дворфами Тенегорна на ограждённой завалами территории во время сражения с троггами за контроль над Ульдаманом. Топаз трогги спрятали в вазе, под боком у несколько неожиданных поселенцев Ульдамана – дворфов Альянса! Наконец, сапфир забрал себе старейшина троггов." },
    ["2201a"] = { common = "Дневник паладина даёт, скорее всего, единственную подсказку, о том, где искать камни из ожерелья. Если верить записям паладина, то придётся иметь дело с дворфами Стальгорна и троггами, борющимися за контроль над раскопками в Ульдамане. Вооружившись этим знанием, отнесись к поискам этих камней серьёзно. Когда ты найдёшь камни, сообщи об этом Талвашу через фиал Видения и следуй полученным от него инструкциям." },
    ["2201c"] = { male = "Ух ты! Да это и вправду три потерянных камня. Отличная работа! Но, к сожалению, это ещё не всё. Нет, я не пытаюсь тебя надуть, поверь мне, герой. Дело в особенностях создания магической бижутерии – настоящей магической бижутерии от Талваша де Кисселя! Для того чтобы создать подобную вещь, нужен большой запас магической энергии, которой в этом ожерелье уже не осталось.", female = "Ух ты! Да это и вправду три потерянных камня. Отличная работа! Но, к сожалению, это ещё не всё. Нет, я не пытаюсь тебя надуть, поверь мне, героиня. Дело в особенностях создания магической бижутерии – настоящей магической бижутерии от Талваша де Кисселя! Для того чтобы создать подобную вещь, нужен большой запас магической энергии, которой в этом ожерелье уже не осталось." },
    ["2202a"] = { common = "Мне рассказали о недавно открытом растении, грибе-малиновике. Этот гриб растёт целыми колониями на раскопках Ульдамана, в самой глубине. Наверное, встречается ещё где-то, но мне известно только одно место. Мне хотелось бы изучить возможности его применения в алхимии, и здесь-то ты мне и пригодишься. Отыщи эти грибы и принеси мне дюжину. Только учти: они могут выпустить облако ядовитых спор, если ты их случайно встряхнёшь. Если выполнишь моё поручение, я сделаю для тебя один из моих знаменитых восстановительных эликсиров!" },
    ["2202c"] = { male = "Молодец, ты снова показал, на что способен! Эти грибы очень пригодятся для моих исследований! А теперь, как я и обещал, можешь насладиться вкусом одного из самых действенных восстановительных составов из моих личных запасов... Если ты тоже увлекаешься алхимией, мы можем вдобавок поговорить о других делах. В любом случае, благодарю за помощь!", female = "Умница, ты снова показала, на что способна! Эти грибы очень пригодятся для моих исследований! А теперь, как я и обещал, можешь насладиться вкусом одного из самых действенных восстановительных составов из моих личных запасов... Если ты тоже увлекаешься алхимией, мы можем вдобавок поговорить о других делах. В любом случае, благодарю за помощь!" },
    ["2203a"] = { male = "Ты оказал мне неоценимую помощь, герой. Надо бы в награду дать тебе рецепт эликсира, который ты пробовал... Но прежде я дам тебе ещё одно опасное задание. Вот моя просьба. В этом сундучке находятся три волшебных сосуда; они зачарованы так, чтобы вытянуть кровь у опалённого дракона-стража. Если воспользоваться ими, зверь разозлится, поэтому соблюдай осторожность. Когда наполнишь все три, принеси их мне. Добудь мне кровь дракона, и я отдам тебе рецепт.", female = "Ты оказала мне неоценимую помощь, героиня. Надо бы в награду дать тебе рецепт эликсира, который ты пробовала... Но прежде я дам тебе ещё одно опасное задание. Вот моя просьба. В этом сундучке находятся три волшебных сосуда; они зачарованы так, чтобы вытянуть кровь у опалённого дракона-стража. Если воспользоваться ими, зверь разозлится, поэтому соблюдай осторожность. Когда наполнишь все три, принеси их мне. Добудь мне кровь дракона, и я отдам тебе рецепт." },
    ["2203c"] = { male = "Между нами, алхимиками, говоря, ты просто герой! Вот, возьми этот рецепт. Пусть он принесёт тебе успех и богатство, как и мне!", female = "Между нами, алхимиками, говоря, ты просто героиня! Вот, возьми этот рецепт. Пусть он принесёт тебе успех и богатство, как и мне!" },
    ["2204a"] = { common = "Тебе понадобится немного \"магической силы\" для ожерелья, и Ульдаман – лучшее место, чтобы её раздобыть. Там бегает множество магических созданий. Поймай самое крупное и злобное, вынь из него источник магической силы и принеси его мне. Я уверен, что смогу вплавить его в ожерелье. Без источника силы, ожерелье починить невозможно. Возвращайся ко мне в Стальгорн, когда раздобудешь что-нибудь подходящее и мы быстро наладим для тебя эту вещь." },
    ["2204c"] = { common = "Отлично! – Я рад видеть и тебя и этот источник силы в целости и сохранности. Теперь, когда драгоценные камни возвращены на сове место, восстановить само ожерелье, займёт не больше минуты... Как только я это сделаю, оно станет твоим! Волнуешься, да? просто дрожишь от нетерпения? Тааак, на чём я в прошлый раз сосредотачивал фокус заклинания..." },
    ["2205a"] = { male = "Значок? А, это ерунда, рыбка – ничего такого, что было бы тебе не по силам. Ты выглядишь так, что Матиас может принять тебя за торговца сыром. Тебя, детка, вряд ли можно счесть настоящим разбойником. Однако у меня есть для тебя работа, и я хочу, чтобы она была выполнена. К делу! Доставь этот пакет Матиасу: возможно, у него тоже найдётся для тебя пара заданий. Не задерживайся!", female = "Значок? А, это ерунда, рыбка – ничего такого, что было бы тебе не по силам. Ты выглядишь так, что Матиас может принять тебя за торговку сыром. Тебя, детка, вряд ли можно счесть настоящим разбойником. Однако у меня есть для тебя работа, и я хочу, чтобы она была выполнена. К делу! Доставь этот пакет Матиасу: возможно, у него тоже найдётся для тебя пара заданий. Не задерживайся!" },
    ["2205c"] = { common = "Итак, тебе удалось меня отыскать. Глядя на тебя, я бы сказал, что для тебя это было серьёзным испытанием как физических сил, так и умственных способностей. Ну что, попросить Рензика показать тебе, где здесь постоялый двор, или ты сразу приступишь к работе?" },
    ["2206a"] = { common = "Наши полевые агенты сообщают о серьёзной активности Братства Справедливости к югу от Златоземья. В этих донесениях указывается, что братство захватило лагерь Джерода и теперь использует его как перевалочный пункт для переправки больших партий контрабанды из Красногорья в Западный Край. Мне нужно, чтобы вы проникли в доки и добыли мне расписание поставок. Скорее всего, портовой начальник носит его при себе. ...и кстати, если вас обнаружат – вы никогда не слышали о ШРУ..." },
    ["2206c"] = { common = "Я потрясён... Потрясён, что Керин наконец-то нашла новобранца, из которого действительно может выйти толк. Возьмите этот клинок. Придёт день, когда ШРУ вновь призовёт вас на службу. Совершенствуйте своё мастерство, пусть глаза ваши будут всегда открыты, а клинок – наточен. Вы не заметите нас, но почувствуете, когда мы будем рядом..." },
    ["2218a"] = { common = "Ещё одна заблудшая душа, стало быть, ищет наставничества? Полагаю, ты хочешь найти смысл жизни – смысл твоей жизни. Я тысячу раз видел, как другие герои искали работу. Что же, сегодня тебе повезло. У Хограла найдётся лекарство для твоего недуга. Вот что ты сделаешь: иди по этой дороге до Стальгорна и там зайди в Заброшенный грот. Как окажешься там, найди воровскую гильдию и переговори с Хальфданом Чернобородом. Он укажет тебе путь к спасению." },
    ["2218c"] = { male = "Стало быть, ты считаешь себя настоящим мерзавцем? Достойным оказаться среди немногих избранных ребят Чёрной Бороды – стать офицером Тайного Круга?би Только настоящий прохвост так высоко себя ценит! Таких мы и ищем! Добро пожаловать!", female = "Стало быть, ты считаешь себя настоящей мерзавкой? Достойной оказаться среди немногих избранных ребят Чёрной Бороды – стать офицером Тайного Круга?би Только настоящая прохвостка так высоко себя ценит! Таких мы и ищем! Добро пожаловать!" },
    ["2238a"] = { male = "Понимаешь, король выгребает из шахты руду и камни. Таких богатств ни один гном за десять жизней не увидит. У Тайного Круга есть свои жизненные ценности. И эти ценности – драгоценности. Просекаешь? Теперь сдаётся нам, что королю надо бы поделиться, но так чтобы \"Вонючая Борода\" не знал, что мы берём свою долю, – ты улавливаешь нить? Нам надо, чтобы ты переговорил с Онином Макмолотом в Гномрегане и вернулся с ответом. Этот хитрый дворф спрятался среди прокажённых. Так что поосторожнее.", female = "Понимаешь, король выгребает из шахты руду и камни. Таких богатств ни один гном за десять жизней не увидит. У Тайного Круга есть свои жизненные ценности. И эти ценности – драгоценности. Просекаешь? Теперь сдаётся нам, что королю надо бы поделиться, но так чтобы \"Вонючая Борода\" не знал, что мы берём свою долю, – ты улавливаешь нить? Нам надо, чтобы ты переговорила с Онином Макмолотом в Гномрегане и вернулась с ответом. Этот хитрый дворф спрятался среди прокажённых. Так что поосторожнее." },
    ["2238c"] = { common = "Тсссс! Тише, балда. Нас подслушивают." },
    ["2239a"] = { male = "Рудник? Да, видел я, как эти жуткие бронированные паровые танки проходят к этому пункту каждый день. Мои информаторы с востока доносят, что танк выходит из Стальгорна, заходит в карьер Гол'Болар, останавливается на перезаправку в Караносе, а потом орк знает зачем делает большой крюк вокруг Гномрегана, прежде чем вернуться в Стальгорн и разгрузиться. Всё в этом донесении, герой. Отнеси его Хальфдану, чтобы он смог обдумать следующий шаг.", female = "Рудник? Да, видел я, как эти жуткие бронированные паровые танки проходят к этому пункту каждый день. Мои информаторы с востока доносят, что танк выходит из Стальгорна, заходит в карьер Гол'Болар, останавливается на перезаправку в Караносе, а потом орк знает зачем делает большой крюк вокруг Гномрегана, прежде чем вернуться в Стальгорн и разгрузиться. Всё в этом донесении, героиня. Отнеси его Хальфдану, чтобы он смог обдумать следующий шаг." },
    ["2239c"] = { male = "Большой крюк? Клянусь собственной бородой! Ты постарался на славу. Возьми вот этот кинжал и ступай. Круг призовёт тебя снова, когда будет готов третий шаг. Что такое третий шаг? Да тот, что идёт после второго, а именно – хороший пинок тебе под зад. Хочешь?", female = "Большой крюк? Клянусь собственной бородой! Ты постаралась на славу. Возьми вот этот кинжал и ступай. Круг призовёт тебя снова, когда будет готов третий шаг. Что такое третий шаг? Да тот, что идёт после второго, а именно – хороший пинок тебе под зад. Хочешь?" },
    ["2240a"] = { male = "Теперь вернёмся к насущным задачам. Тебе предстоит исследовать чертог Хаз'Мула. Проблема в том, что он находится за огромной, запертой дверью! К счастью, я знаю, как её открыть. Я записал всё в своём дневнике, здесь на столе. Моя группа и я заперты здесь... Так что ты, должен найти для нас чертог Хаз-Мула! Прочитай мой дневник и отправляйся в чертог. Потом доложи геологу Грозовой Вершине в Стальгорне.", female = "Теперь вернёмся к насущным задачам. Тебе предстоит исследовать чертог Хаз'Мула. Проблема в том, что он находится за огромной, запертой дверью! К счастью, я знаю, как её открыть. Я записал всё в своём дневнике, здесь на столе. Моя группа и я заперты здесь... Так что ты, должна найти для нас чертог Хаз-Мула! Прочитай мой дневник и отправляйся в чертог. Потом доложи геологу Грозовой Вершине в Стальгорне." },
    ["2240c"] = { common = "Вы видели чертог Хаз'Мула? Потрясающе! Бейлог был уверен, что он существовал, но я, честно говоря, сомневался. Спасибо. Теперь то, что вы обнаружили сподвигнет наших лидеров приложить все усилия к тому, чтобы отвоевать Ульдаман. А когда это место снова вернётся под руку Стальгорна, все тайны Чертога Хаз'Мула будут нашими!" },
    ["2241a"] = { common = "Говорят, что я обезумел от любви. Да, я всё время думаю о Сиарне. Да, мой дом полон рисунков и картин, с которых на меня смотрит Сиарна. Да, я часто целыми днями крошки в рот не беру, не сплю, не пью, а всё плачу о нашей несбывшейся любви. Что в этом плохого? И вот теперь она отказывается меня видеть. МЕНЯ! Я пытался письма ей писать, так она не желает ни с кем разговаривать, если только это не разбойник. Не отнесёшь ли ты ей от меня этот цветок? И не забудь сказать ей, что он от Джаннока." },
    ["2241c"] = { male = "Если собрать все цветы, что присылает мне этот зануда Джаннок, впору цветочную лавку открывать! Ладно, как бы там ни было, нынешний посланец Джаннока может мне пригодиться... Не хочешь ли подрядиться на одно дельце, герой?", female = "Если собрать все цветы, что присылает мне этот зануда Джаннок, впору цветочную лавку открывать! Ладно, как бы там ни было, нынешний посланец Джаннока может мне пригодиться... Не хочешь ли подрядиться на одно дельце, героиня?" },
    ["2242a"] = { common = "Нам кажется, что одно существо могло бы помочь нам понять, что происходит с лесами Тельдрассила. Увы, уговорить это существо может оказаться опасным делом. Это сатир. Он скрывается на ветви на опушке Поляны Оракула. Пока всех, кто подходил к этому сатиру - с угрозами или добрым словом, - постигала мрачная судьба. Может, надо подкрасться к нему незаметно? Узнай, что у Сетира Древнего в сумках, и возвращайся ко мне." },
    ["2242c"] = { male = "Дурные вести. Похоже, что зараза, охватившая леса и реки Тёмного Берега, начинает расползаться и по нашему дому. Ты сослужил добрую службу, но больше ты уже ничем не поможешь. Прими этот клинок в награду за службу Тельдрассилу.", female = "Дурные вести. Похоже, что зараза, охватившая леса и реки Тёмного Берега, начинает расползаться и по нашему дому. Ты сослужила добрую службу, но больше ты уже ничем не поможешь. Прими этот клинок в награду за службу Тельдрассилу." },
    ["2258a"] = { male = "Я хотел бы воспользоваться твоими услугами. Я довольно известный алхимик, и мне понадобились кое-какие реактивы, которые можно отыскать в Бесплодных землях. Вот что мне нужно: пять вторых желудков канюка, десять клыков скального койота и пять осколков каменных элементалей. Очевидно, что их можно добыть у самих тварей, но если ты не любитель сражений, можешь попросить о помощи друзей. Я неплохо заплачу, если ты принесёшь мне всё необходимое. Что скажешь?", female = "Я хотел бы воспользоваться твоими услугами. Я довольно известный алхимик, и мне понадобились кое-какие реактивы, которые можно отыскать в Бесплодных землях. Вот что мне нужно: пять вторых желудков канюка, десять клыков скального койота и пять осколков каменных элементалей. Очевидно, что их можно добыть у самих тварей, но если ты не любительница сражений, можешь попросить о помощи друзей. Я неплохо заплачу, если ты принесёшь мне всё необходимое. Что скажешь?" },
    ["2258c"] = { male = "Молодец. Этого мне должно хватить на некоторое время. Вот обещанная плата. Если ты не против получить новое задание, то вот – мне нужны ещё кое-какие реактивы. Некоторые из них можно найти только в глубинах ульдаманского раскопа. Добыть их нелегко, но и плата за помощь будет немалая. Может быть, кое-что получше блестящих монет!", female = "Умница. Этого мне должно хватить на некоторое время. Вот обещанная плата. Если ты не против получить новое задание, то вот – мне нужны ещё кое-какие реактивы. Некоторые из них можно найти только в глубинах ульдаманского раскопа. Добыть их нелегко, но и плата за помощь будет немалая. Может быть, кое-что получше блестящих монет!" },
    ["2259a"] = { common = "Не бойся, я не стану посылать тебя к Сиарне. Эрион требует твоего присутствия в Анклаве Кенария. Не медли!" },
    ["2259c"] = { male = "Пора идти дальше, герой, – мир ждёт.", female = "Пора идти дальше, героиня, – мир ждёт." },
    ["2260a"] = { common = "Весть о ваших деяниях получила широкую огласку. Настолько далеко, что даже разведка Штормграда желает лично побеседовать с вами. Дорога не беспошлинная и небезопасная, но возможность стажироваться в ШРУ – это вам не жук чихнул! Вас ждёт целый новый мир. Отправляйтесь в Старый город Штормграда и поговорите с Рензиком Ножом в штаб-квартире ШРУ." },
    ["2260c"] = { common = "Вы откликнулись на призыв ШРУ, и проделали долгий путь от дальних берегов, чтобы вступить в наши ряды. Однако вам многому предстоит научиться." },
    ["2278a"] = { male = "Главные сокровища этого чертога – четыре огромных платиновых диска, каждый из которых украшен многочисленными символами неизвестного происхождения. Когда ты касаешься их, у тебя покалывает пальцы, и перед тобой возникает Каменный Страж. \"Приветствую тебя! Я – хранитель знаний. Создание земельников было подробно описано и сохранено на Дисках Норганнона.\" Ты раскрыл сокровищницу никому прежде неизвестных знаний!", female = "Главные сокровища этого чертога – четыре огромных платиновых диска, каждый из которых украшен многочисленными символами неизвестного происхождения. Когда ты касаешься их, у тебя покалывает пальцы, и перед тобой возникает Каменный Страж. \"Приветствую тебя! Я – хранитель знаний. Создание земельников было подробно описано и сохранено на Дисках Норганнона.\" Ты раскрыла сокровищницу никому прежде неизвестных знаний!" },
    ["2278c"] = { common = "Прослушав инструкции каменного Стража, ты снова получаешь доступ к Дискам Норганнона, теперь уже зная историю создания земельников, троггов и дворфов. Слабый, краткий гул доносится из глубины дисков. Каменный страж говорит: \"Теперь Диски синтезировались. Дотронься до них ещё раз, чтобы получить личную копию.\"" },
    ["2279a"] = { common = "Ты прикасаешься к Дискам Норганнона, и пальцы снова покалывает. Диски издают странный скрежещущий гул, и твой мешок вдруг становится тяжелее. Внутри ты обнаруживаешь миниатюрную копию Дисков. Несомненно, для увлекающихся историей Азерота, это – неслыханная ценность. Лига Исследователей из Стальгорна как раз из таких. Возможно, они найдут применение этим дискам." },
    ["2279c"] = { male = "Что это у вас там... ох мать моя... Откуда вы это взяли? Нет, правда? Вы кому-нибудь ещё об этом расказывали? ПРАВДА?! Мой дорогой герой, Вы, возможно, только что совершили открытие года в области археологии! Богов ради! Кого я пытаюсь надуть, открытие столетия! Если эти диски – то, о чём я думаю, то они будут тем ключом, который мы так долго искали! Теперь мы сможем раз и навсегда доказать магическое происхождение дворфов!", female = "Что это у вас там... ох мать моя... Откуда вы это взяли? Нет, правда? Вы кому-нибудь ещё об этом расказывали? ПРАВДА?! Моя дорогая героиня, Вы, возможно, только что совершили открытие года в области археологии! Богов ради! Кого я пытаюсь надуть, открытие столетия! Если эти диски – то, о чём я думаю, то они будут тем ключом, который мы так долго искали! Теперь мы сможем раз и навсегда доказать магическое происхождение дворфов!" },
    ["2280a"] = { common = "Ты прикасаешься к Дискам Норганнона, и пальцы снова покалывает. Диски издают странный скрежещущий гул, и твой мешок вдруг становится тяжелее. Внутри ты обнаруживаешь миниатюрную копию Дисков. Несомненно, для увлекающихся историей Азерота, это – неслыханная ценность. Лига Исследователей из Стальгорна как раз из таких. Возможно, они найдут применение этим дискам." },
    ["2280c"] = { male = "Что это у нас тут? Невероятно, мой юный друг! На этих дисках записаны древние и давно утерянные тайны. Ты поступил мудро, принеся их мне.", female = "Что это у нас тут? Невероятно, мой юный друг! На этих дисках записаны древние и давно утерянные тайны. Ты поступила мудро, принеся их мне." },
    ["2281a"] = { common = "Посылать тебя в бой равноценно убийству. Рензику не нужны лишние покойники. Но тебе, бояться нечего: для тебя найдётся не такое опасное дело. Отправляйся в Красногорье и поговори там с Люцием – этот тип связан с ШРУ. Он постоянно отирается у пристани в Приозерье вместе с остальными бездельниками." },
    ["2281c"] = { common = "Что, не слишком-то у тебя ловкие пальчики, верно? Ну, да не беспокойся: я и не из таких делал отличных разбойников!" },
    ["2282a"] = { common = "Я долгие годы обучал молодых воров. В конце концов не всякому плуту от рождения достаётся ловкость и проворство, как у старого Люция. Рядом с дорогой стоит лесопилка Альтера. Я оставил там сундук, а в нём – кое-что важное. Принеси его мне! Возвращайся с добычей, и получишь Воровской сертификат." },
    ["2282c"] = { male = "Сумел открыть, да? Неплохая работа. Теперь если ты погибнешь, то исключительно по глупости, а не от отсутствия опыта.", female = "Сумела открыть, да? Неплохая работа. Теперь если ты погибнешь, то исключительно по глупости, а не от отсутствия опыта." },
    ["2283a"] = { common = "У нас есть для тебя работа – если у тебя, конечно, хватит пороху за неё взяться! В глубине Бесплодных земель есть раскопки Ульдамана. Говорят, недавно там откинул копыта какой-то идиот-паладин. При нём было очень ценное ожерелье с тремя самоцветами: рубином, сапфиром и топазом. Короче, нам нужно это ожерелье, и мы готовы за него заплатить – чистым серебром! Если оно попорченное – ничего, как-нибудь починим." },
    ["2283c"] = { male = "О-о, добыча! Отсюда чую, оно здесь... Дай-ка взглянуть… Эй, что это ты нам подсовываешь? Тут же камней не хватает. Ты что думал, мы не заметим? Даже Мальтон увидел бы, что камней нету! Ну, может, это и не ты их спёр... Но ведь ожерелье без них ничего не стоит! Не-ет, твоя работа ещё не окончена!", female = "О-о, добыча! Отсюда чую, оно здесь... Дай-ка взглянуть… Эй, что это ты нам подсовываешь? Тут же камней не хватает. Ты что думала, мы не заметим? Даже Мальтон увидел бы, что камней нету! Ну, может, это и не ты их спёрла... Но ведь ожерелье без них ничего не стоит! Не-ет, твоя работа ещё не окончена!" },
    ["2284a"] = { common = "Эти камни наверняка остались где-то в Ульдамане! Это так же верно, как то, что Мальтон – балбес. Вернись и разыщи их! Как я уже говорил, если то, что нам рассказывали, правда, в нём были рубин, сапфир и топаз. Найди их и вставь обратно в ожерелье. Где они? А кто ж их знает? Может, тебе повезёт отыскать труп того паладина. Может, они до сих пор при нём – если его, конечно, не обчистили." },
    ["2284c"] = { common = "Похоже, вам-таки удалось отыскать останки паладина, о которых говорил Дран. Обыскав их, вы находите дневник паладина. Дневник в плохом состоянии, большая часть страниц перепачкана запёкшейся кровью. Но и оставшийся текст – сплошная галиматья. Похоже, это язык людей. Придётся вам найти кого-то, кто сможет это перевести." },
    ["2298a"] = { common = "И вот собрались мы уже разрабатывать фазу ай-ай-ай, когда вломились несколько болванов Магни, стали нести какую-то чушь насчёт воровства и что они арестуют некоторых членов Тайного Круга. Да только поди возьми старика Чёрную Бороду! Разборка пошла нешуточная, и каким-то образом всплыло твоё имя! Хочешь совет? Бери первого грифона из Стальгорна и дуй в Штормград. Иди в Старый город и там переговори с моим старым приятелем Рензиком Ножом." },
    ["2298c"] = { common = "Всегда рад видеть в наших рядах ребят Хальфдана!" },
    ["2299a"] = { common = "Где тебя носило? Хальфдан всюду тебя искал. Мы уж подумали, что король забил тебя в кандалы. Дуй в Стальгорн как можно быстрее и поговори с Хальфданом!" },
    ["2299c"] = { common = "Говори тише, стража может услышать." },
    ["2300a"] = { common = "Слушай, рыбка, тебя тут Рензик искал. На твоём месте я не заставлял бы его ждать – всё-таки он правая рука Матиаса..." },
    ["2300c"] = { common = "Как насчёт того, чтобы приступить к работе? Или хочешь сначала вздремнуть?" },
    ["2318a"] = { common = "Зайдя в окончательный тупик, ты приходишь к выводу, что тебе нужна книга, написанная на понятном тебе языке. Перевести её, к сожалению, может далеко не каждый. Ближайший к тебе такой умелец, скорее всего, найдётся в Каргате, форпосте в Бесплодных Землях. Начать, пожалуй, стоит оттуда." },
    ["2318c"] = { male = "Могучий герой, я знаю зачем Вы здесь, в Бесплодных землях. Я знаю, что Вам нужны мои умения по части языков. Вы – в поисках частей того ожерелья, которое вы нашли в Ульдамане. Удивлены? Не стоит – знать такие вещи – моя работа. Вместо этого давайте обсудим, что Вы сделаете для того, чтобы перевести дневник. Доверяйте мне – я – единственный, кто может перевести его. Так что позвольте мне сделать вам лучшее предложение, чем может Дран Дрофферз и можете без помех продолжать переговоры с ними. Заинтригованы?", female = "Могучая героиня, я знаю зачем Вы здесь, в Бесплодных землях. Я знаю, что Вам нужны мои умения по части языков. Вы – в поисках частей того ожерелья, которое вы нашли в Ульдамане. Удивлены? Не стоит – знать такие вещи – моя работа. Вместо этого давайте обсудим, что Вы сделаете для того, чтобы перевести дневник. Доверяйте мне – я – единственный, кто может перевести его. Так что позвольте мне сделать вам лучшее предложение, чем может Дран Дрофферз и можете без помех продолжать переговоры с ними. Заинтригованы?" },
    ["2338a"] = { common = "Скупщикам Дрофферсу и Сыновьям не хватит умения, чтобы восстановить чары на ожерелье, а вот я могу это сделать. Только дай мне изучить его, чтобы я научился делать подобные. Одолжи мне его на время, а я переведу для тебя дневник. Пока будешь искать камни, я как раз успею изучить ожерелье. Это выгодно нам обоим. Ну, что скажешь?" },
    ["2338c"] = { common = "Благодарю тебя, секрет ожерелий разгадать несложно, если иметь достаточно времени, чтобы изучить всего одно из них. А теперь погоди ещё минутку, я произнесу заклинание, чтобы быстро перевести дневник с человеческого языка на понятный тебе. Я тролль слова, спроси кого хочешь в Орде, и тебе скажут: Джаркалу Замшелому Клыку можно доверять! Ну-с, приступим..." },
    ["2339a"] = { male = "Вот и перевод, ты можешь сам прочесть его. Там говорится, что рубин спрятан дворфами, топаз спрятали трогги, а сапфир прикарманил трогг по имени Гримлок. Послушай-ка, тебе потребуется источник энергии, чтобы ожерелье вновь заработало. Дран Дрофферс об этом даже не подозревает. Чтобы найти такой источник, отправляйся в Ульдаман, спустись в самую глубину и убей самую сильную тварь, которую сможешь найти. Уверен, у неё ты и найдёшь источник энергии!", female = "Вот и перевод, ты можешь сама прочесть его. Там говорится, что рубин спрятан дворфами, топаз спрятали трогги, а сапфир прикарманил трогг по имени Гримлок. Послушай-ка, тебе потребуется источник энергии, чтобы ожерелье вновь заработало. Дран Дрофферс об этом даже не подозревает. Чтобы найти такой источник, отправляйся в Ульдаман, спустись в самую глубину и убей самую сильную тварь, которую сможешь найти. Уверен, у неё ты и найдёшь источник энергии!" },
    ["2339c"] = { male = "Отлично, герой! Скоро мы пожнём плоды наших трудов. Я закончил работу над ожерельем и уверен, что теперь смогу создать такое же. Но сначала я использую специальное заклинание, чтобы быстро исследовать эти самоцветы, прежде чем ты унесёшь их и ожерелье в Оргриммар. Это займёт всего пару минут.", female = "Отлично, героиня! Скоро мы пожнём плоды наших трудов. Я закончил работу над ожерельем и уверен, что теперь смогу создать такое же. Но сначала я использую специальное заклинание, чтобы быстро исследовать эти самоцветы, прежде чем ты унесёшь их и ожерелье в Оргриммар. Это займёт всего пару минут." },
    ["2340a"] = { male = "Ожерелье будет работать, только если самоцветы будут в сродстве с металлом оправы. Этот источник энергии поможет вернуть ожерелью магическую силу... Надеюсь. Я с удовольствием предоставлю тебе камни, подходящие к ожерелью, если окажется, что источник энергии действительно работает. Отправляйся в Оргриммар и выполни, что обещал скупщикам Дрофферсу и Сыновьям. Никому не сообщай о наших договорённостях, и, возможно, к твоему возвращению я приготовлю сюрприз.", female = "Ожерелье будет работать, только если самоцветы будут в сродстве с металлом оправы. Этот источник энергии поможет вернуть ожерелью магическую силу... Надеюсь. Я с удовольствием предоставлю тебе камни, подходящие к ожерелью, если окажется, что источник энергии действительно работает. Отправляйся в Оргриммар и выполни, что обещала скупщикам Дрофферсу и Сыновьям. Никому не сообщай о наших договорённостях, и, возможно, к твоему возвращению я приготовлю сюрприз." },
    ["2340c"] = { male = "Ну, всё в порядке. Я могу оставить себе и мешок? Спасибо, премного благодарен. И всё же лучший трофей – это ожерелье! Не строй такую кислую мину, оно было бы тебе не к лицу! Сделка есть сделка, поэтому вот твоя награда за принесённые трофеи. Что ж, с этим покончено, можешь заглядывать иногда, если понадобится работа. А пока будь любезен, покинь помещение!", female = "Ну, всё в порядке. Я могу оставить себе и мешок? Спасибо, премного благодарен. И всё же лучший трофей – это ожерелье! Не строй такую кислую мину, оно было бы тебе не к лицу! Сделка есть сделка, поэтому вот твоя награда за принесённые трофеи. Что ж, с этим покончено, можешь заглядывать иногда, если понадобится работа. А пока будь любезна, покинь помещение!" },
    ["2341a"] = { common = "Полдела сделано. Дран и Мальтон Дрофферсы уже ссорятся из-за новой добычи. Теперь нужно сходить в Бесплодные земли – возможно, у Джаркала Замшелого Клыка из Каргата найдётся для вас особая награда..." },
    ["2341c"] = { common = "Источник силы, полученный от тебя, превзошёл все мои ожидания! Мне удалось сделать два ожерелья – тебе и мне, – и в нём осталось достаточно энергии, чтобы сделать как минимум ещё три! Я на этом неплохо наживусь, а семейка Дрофферсов ничего и не узнаёт! Вот, держи. Я тебе очень благодарен... а это знак моей благодарности!" },
    ["2342a"] = { common = "Гарреттам не пристало мести загоны для летучих мышей такой метлой! Мерзкая работёнка позволила мне заработать немного денег, и я хочу истратить их на улучшение своего положения. Фамильное \"оружие\" Гарреттов заперто в нашем сундуке в Южном зале Ульдамана. Там наша семья трудилась долгие годы. Без него я застряну тут навеки – в буквальном смысле – и буду мести за проклятыми летучими мышами до скончания веков. Принеси мне наше сокровище! Помоги вернуть то, что положено мне по праву рождения!" },
    ["2342c"] = { common = "Наконец-то – метла, достойная Гарретта. Не зря я потратил на тебя деньги! Вы слышите меня, летучие мыши? Теперь у меня есть истинное оружие семьи Гарреттов! Трепещите, проклятые пискуны!" },
    ["2358a"] = { common = "Много лет назад рога Незры были похищены из поместья Чёрный Ворон. Я искал их по всем морям и континентам и только теперь выяснил, что они всё время находились у этих ничтожных тварей. Убей всех орков Чёрной Горы, которые встретятся тебе на пути, забери у них рога Незры и возвращайся ко мне в Приозерье. Окажи мне эту услугу, и заслужишь благодарность всех Чёрных Воронов." },
    ["2358c"] = { common = "Отрицать существование артефакта, значит отрицать само существование Чёрного Ворона. Отличная работа, герой. Когда я был молодым разбойником и искал приключения на Тёмных берегах, я обнаружил чай, который восполняет энергию в бою. Он хорошо служил мне на протяжении многих лет, и теперь я делюсь им с тобой. Пей, когда чувствуешь усталость, путник, и сражайся с пришедшей в тебя силой!" },
    ["2359a"] = { common = "Я за этой башней уже не первую неделю наблюдаю. Недавно прошла крупная поставка из Сумеречного леса, а вместе с ней явились эти стражи. Кто такие? Мы можем только гадать. Одно я тебе скажу: это не люди. Как бы то ни было, там был сундук – и, как я полагаю, эта мерзость именно его и охраняет. А ключ от сундука – у того зомби с шипами. Добудь этот ключ, проберись в башню и выясни, что находится в том сундуке. Находку отнесёшь Матиасу." },
    ["2359c"] = { common = "Это объясняет присутствие мертвяков из Братства Справедливости, которых вы с Кеарнен видели рядом с башней. Это может объяснить и вовлеченность Торговой Компании в дела Братства Справедливости и эти странные поставки из Сумеречного леса. Как явствует из этой книги, тролли Занзила в Тернистой долине нашли возможность поднимать мёртвых с помощью зелий... выражаясь точнее – ядов. Вы бесполезны для ШРУ, если у вас нет чёткого представления о ядах, особенно когда рецепт того, как поднимать нежить, почти у нас в руках." },
    ["2360a"] = { common = "Произошло то, чего я ожидал. Разведотдел ШРУ сообщает, что Братство Справедливости что-то затевает в Западном Крае. Складывается впечатление, что братство захватило покинутую сторожевую башню Альянса к юго-востоку от Сторожевого Холма и использует её как базу для ввоза контрабанды из Красногорья. Отправляйтесь в Западный Край и свяжитесь с посланницей Кеарнен для подробного доклада. Она там прячется, неподалёку от башни. ... и кстати, если вас раскроют – вы никогда не слышали о ШРУ..." },
    ["2360c"] = { common = "Наконец-то Матиас прислал ещё одного агента мне в помощь. Ну, надеюсь, он готов к вороху неприятных новостей." },
    ["2361c"] = { common = "Я с удовольствием одариваю тебя этим ожерельем, могучий герой. Ты сделал великое дело и я благодарю тебя. Не забудь разрекламировать создателя ожерелья — то есть, меня. И если ты умолчишь о том факте что оно не проклято, буду тебе благодарен." },
    ["2378a"] = { male = "Ты много сделал для стражей смерти, но пришло время двигаться дальше. У тебя талант к искусству обмана и скрытности, но этот талант ещё следует развить. У стражей смерти есть союзники в Изувеченной Длани. Поищи среди них тех, кто готов помочь нам. Для начала поговори с Шентулом в Оргриммаре.", female = "Ты много сделала для стражей смерти, но пришло время двигаться дальше. У тебя талант к искусству обмана и скрытности, но этот талант ещё следует развить. У стражей смерти есть союзники в Изувеченной Длани. Поищи среди них тех, кто готов помочь нам. Для начала поговори с Шентулом в Оргриммаре." },
    ["2378c"] = { common = "Так вот кого могучие союзники прислали Шентулу... Не впечатляет…" },
    ["2379a"] = { common = "Одной твоей решимости ещё недостаточно, чтобы преодолеть препятствия, которые ждут впереди. Поговори с Зандо'заном, чтобы начать учиться на агента Изувеченной Длани. Лишь овладев навыками незаметности и коварства, ты сможешь сделать следующий шаг." },
    ["2379c"] = { common = "Быть может, Зандо'зан ошибся. Зандо'зан просит прощения." },
    ["2380a"] = { common = "Ты, конечно, далеко ещё не специалист по скрытности и всяким уловкам, однако же тебе есть куда расти. По крайней мере, начальство явно обратило на тебя внимание: сам великий Шентул запомнил твоё имя! Ступай на север – эта дорога ведёт в Оргриммар. Отыщи там в расселине Теней Шентула и поговори с ним." },
    ["2380c"] = { common = "Очень важно, чтобы Изувеченная Длань сохраняла бдительность перед лицом перемен, которые Тралл намеревается ввести в Орде. Числом тут не возьмёшь – для нас главное незаметность и разнообразные уловки!" },
    ["2381a"] = { common = "Не хочу тебя пугать, но последние пять воров, которым я поручил похитить сокровище Южного моря, не вернулись. Потом их нашли... Частично. В южной части побережья пришвартован пиратский корабль, \"Стрела прилива\". В трюме у него хранится то самое сокровище. На второй палубе устроен пиратский притон, в котором они натаскивают своих воров. Проникни на этот корабль, похить сокровище и принеси его мне. Если тебе надо поднатореть в воровском искусстве, можешь заглянуть в притон, но соблюдай осторожность!" },
    ["2381c"] = { common = "Немыслимо! Невероятно! Поразительно! Да ты талант. Или же ты самый везучий парень на свете! Вот твоя доля. Думаю, ты найдёшь ей лучшее применение, чем я." },
    ["2382a"] = { male = "Зандо'зан это видел! Да, день близок! Смерть Тралла... кинжал в его спине, яд в его кубке... Но Зандо'зан слишком много болтает. путник! У Зандо'зана есть поручение для тебя! путник должен отправиться в Кабестан, к востоку от Перекрёстка, и поговорить с Рениксом Презренным. Ступай!", female = "Зандо'зан это видел! Да, день близок! Смерть Тралла... кинжал в его спине, яд в его кубке... Но Зандо'зан слишком много болтает. путница! У Зандо'зана есть поручение для тебя! путница должна отправиться в Кабестан, к востоку от Перекрёстка, и поговорить с Рениксом Презренным. Ступай!" },
    ["2382c"] = { common = "Как, опять? Предыдущие пятеро, кого прислал ко мне этот чокнутый тролль, пошли на корм акулам. Ну что ж, будем надеяться, что тебе повезёт…" },
    ["2383a"] = { common = "А! Тебе тут пергамент прислали, пока тебя не было. Прочитай, когда время будет. Это, кажется, от Франга, наставника воинов. Он хочет с тобой поговорить. Он обычно сидит в тени у входа в Логово." },
    ["2383c"] = { male = "А-а, да, это я тебе написал... Я слышал, что ты скоро тут появишься. Рад, что тебе удалось добраться сюда невредимым – будем надеяться, что ты переживёшь и грядущие испытания. Наберёшься сил – приходи ко мне. Я сделаю всё, чтобы из тебя получился настоящий воин. Удачи! Возвращайся, когда будешь готов.", female = "А-а, да, это я тебе написал... Я слышал, что ты скоро тут появишься. Рад, что тебе удалось добраться сюда невредимой – будем надеяться, что ты переживёшь и грядущие испытания. Наберёшься сил – приходи ко мне. Я сделаю всё, чтобы из тебя получился настоящий воин. Удачи! Возвращайся, когда будешь готова." },
    ["2398a"] = { male = "Раскопки в Ульдамане не всегда были захвачены троггами. Изначально мы, дворфы Стальгорна, вели здесь работы, но потом... Потом появились эти твари. Они прибыли столь быстро и в таком количестве, что дворфы не смогли ничего поделать. Честно говоря, их нападение было настолько внезапным, что многие наши люди могли не успеть вырваться из осады. Боюсь, они по сей день остаются в ловушке в тылу врага. Мой друг Бейлог руководил небольшим отрядом дворфов в глубине раскопа прямо перед нападением троггов. Если он и его ребята живы, то я хочу, чтобы ты нашёл их.", female = "Раскопки в Ульдамане не всегда были захвачены троггами. Изначально мы, дворфы Стальгорна, вели здесь работы, но потом... Потом появились эти твари. Они прибыли столь быстро и в таком количестве, что дворфы не смогли ничего поделать. Честно говоря, их нападение было настолько внезапным, что многие наши люди могли не успеть вырваться из осады. Боюсь, они по сей день остаются в ловушке в тылу врага. Мой друг Бейлог руководил небольшим отрядом дворфов в глубине раскопа прямо перед нападением троггов. Если он и его ребята живы, то я хочу, чтобы ты нашла их." },
    ["2398c"] = { male = "Ты как раз вовремя! Я уже боялся, что проспорю Олафу! Он бился об заклад, что его борода достанет до колен, прежде чем мы увидим живое лицо, герой. И вот, ты здесь, а бороде Олафа ещё до колен осталась пара дюймов. Спасибо! Я обязательно поделюсь с тобой выигрышем.", female = "Ты как раз вовремя! Я уже боялся, что проспорю Олафу! Он бился об заклад, что его борода достанет до колен, прежде чем мы увидим живое лицо, героиня. И вот, ты здесь, а бороде Олафа ещё до колен осталась пара дюймов. Спасибо! Я обязательно поделюсь с тобой выигрышем." },
    ["2399c"] = { common = "Папоротник, который Деналан посадил у себя в саду, проклюнулся и вырос. Ростки так и просят, чтобы их скорее собрали…" },
    ["2418a"] = { common = "Есть у меня зуб на этих дворфов Кузни Теней! Пару лет назад они пригласили меня в Крепость Ангор, чтобы я исследовал для них два образца прелюбопытнейших камней, привезённых с ульдаманского раскопа. Я провёл исследования, и вообрази, что это было? Энергия! Каждый камень был мощнейшим источником энергии в сжатом, потенцированном виде – нужно только знать, как правильно высвободить её! Чего только не найдёшь в Ульдамане... В общем, как только я рассказал об этом дворфам, они вышвырнули меня из крепости и направились в Ульдаман за чудесными камнями. Мне бы такие, знаешь ли, тоже пригодились. Принеси мне несколько обоих видов, и я щедро вознагражу тебя." },
    ["2418c"] = { male = "Прекрасно, ты принёс их! Ты самый благонадёжный путник, которого мне приходилось встречать! Немедленно опробую эти камни на моих последних механизмах! Нутром чую, с этими камнями можно создать вечный двигатель!", female = "Прекрасно, ты принесла их! Ты самая благонадёжная путница, которую мне приходилось встречать! Немедленно опробую эти камни на моих последних механизмах! Нутром чую, с этими камнями можно создать вечный двигатель!" },
    ["2438a"] = { male = "Некогда Гэролас Талветрен, страж друидов обители Бен'этиль, подарил мне изумрудного ловца снов. Этот могучий амулет способен выкачивать энергию из Изумрудного Сна, принося удачу тому, кто его носит. Увы, мне не удалось забрать его из моего шкафчика в деревне Звёздного Ветра... Хотя эта деревня некогда была спокойным местом, ныне она поражена порчей фурболгов, что поселились там. Может, тебе удастся добыть моего ловца снов, герой?", female = "Некогда Гэролас Талветрен, страж друидов обители Бен'этиль, подарил мне изумрудного ловца снов. Этот могучий амулет способен выкачивать энергию из Изумрудного Сна, принося удачу тому, кто его носит. Увы, мне не удалось забрать его из моего шкафчика в деревне Звёздного Ветра... Хотя эта деревня некогда была спокойным местом, ныне она поражена порчей фурболгов, что поселились там. Может, тебе удастся добыть моего ловца снов, героиня?" },
    ["2438c"] = { common = "Мой изумрудный ловец снов очень много для меня значит. Такие подарки лишь немногим дарят. Прими мою благодарность за его возвращение." },
    ["2439a"] = { male = "Это невероятная находка. Согласно этим дискам, Древние Титаны, или Создатели, имеют отношение к нашему чудесному возникновению! Нам нужно уделить как можно больше времени их изучению. А вас, героический герой, прошу принять этот сертификат и отнести его Дините Каменной Мантии в хранилище. По нему вы получите то, что, на мой взгляд, будет достойной наградой за такую находку! Когда будете готовы, возвращайтесь ко мне – у Лиги Исследователей ещё много работы для вас!", female = "Это невероятная находка. Согласно этим дискам, Древние Титаны, или Создатели, имеют отношение к нашему чудесному возникновению! Нам нужно уделить как можно больше времени их изучению. А вас, героическая героиня, прошу принять этот сертификат и отнести его Дините Каменной Мантии в хранилище. По нему вы получите то, что, на мой взгляд, будет достойной наградой за такую находку! Когда будете готовы, возвращайтесь ко мне – у Лиги Исследователей ещё много работы для вас!" },
    ["2439c"] = { common = "Ах, сертификат Лиги Исследователей... и весьма ценный, смею заметить. Лига Исследователей даёт мне полномочия предложить вам выбрать себе награду прямо из хранилища. Награда ваша, так что выбирайте – либо пять наилучших целебных зелий, либо пять сильных зелий маны." },
    ["2440a"] = { male = "Я сосредоточу свои усилия на исследовании этих дисков, и со временем они раскроют мне свою тайну. А тебя путник, я награжу за то, что ты обратил на них моё внимание. Отнеси этот сертификат Бене Заиндевевшее Копыто, наставнице алхимиков в Громовом Утёсе. Она даст тебе один интересный предмет, который наверняка тебе понравится, а ещё она даст тебе на выбор зелий из моих личных запасов. Возвращайся поскорее, ибо я чувствую, что мы стоим на пороге великого открытия.", female = "Я сосредоточу свои усилия на исследовании этих дисков, и со временем они раскроют мне свою тайну. А тебя путница, я награжу за то, что ты обратила на них моё внимание. Отнеси этот сертификат Бене Заиндевевшее Копыто, наставнице алхимиков в Громовом Утёсе. Она даст тебе один интересный предмет, который наверняка тебе понравится, а ещё она даст тебе на выбор зелий из моих личных запасов. Возвращайся поскорее, ибо я чувствую, что мы стоим на пороге великого открытия." },
    ["2440c"] = { male = "Что же, ты, видать, угодил Ведуну Искателю Истины, принеся ему ту штуку. Так что вдобавок ты получишь в награду зелья из его личного хранилища. Можешь выбрать или пять наилучших целебных зелий, либо пять сильных зелий маны.", female = "Что же, ты, видать, угодила Ведуну Искателю Истины, принеся ему ту штуку. Так что вдобавок ты получишь в награду зелья из его личного хранилища. Можешь выбрать или пять наилучших целебных зелий, либо пять сильных зелий маны." },
    ["2458a"] = { common = "Торговая Компания... Доводилось тебе слышать про такую? Мы в течение года пытались внедрить агента в их ряды. Это было непросто, но мы преуспели. Недавно мы получили сведения, что Торговая Компания затевает что-то крупное. Ступай к башне Торговой Компании, которая стоит к северу от Нефтяного болота, и свяжись с нашим тайным агентом, надсмотрщиком Физзулом. Когда найдёшь башню, используй это сигнальное ружьё, потом подойди к Физзулу и покажи ему приветствие Изувеченной Длани." },
    ["2458c"] = { common = "Приятно видеть в здешних местах ещё одного агента Изувеченной Длани! Вот только боюсь, как бы твоих вспышек не заметил кто-то лишний. В следующий раз, когда тебе нужно будет со мной поговорить, дважды свистни в этот свисток, и я пойму, что это свои." },
    ["2459a"] = { common = "Изумруд... Он пропал! Мой ловец снов повреждён! К северу от деревни Звёздный Ветер засела шайка мистиков из племени Кривой Сосны. Я слышал, что их вожак, Фероситас Пожиратель Снов, носил ожерелье, которое светится зелёным в ночи. Теперь, глядя на своего ловца снов, я уверен, что это он украл мой изумруд... Он не понимает, что его сила для него бесполезна. Найди этот пропавший драгоценный камень. И раз уж ты здесь, истреби заодно и этих зловредных мистиков." },
    ["2459c"] = { common = "Теперь я восстановлю своего ловца снов! Спасибо тебе, Хлебало." },
    ["2460a"] = { common = "Теперь, когда ты – разбойник Изувеченной Длани, тебе следует обучиться особому приветствию. Это знак, по которому мы опознаем своих. Смотри и повторяй за мной." },
    ["2460c"] = { male = "Молодец! Теперь мы можем продолжать.", female = "Умница! Теперь мы можем продолжать." },
    ["2478a"] = { male = "Тебе придётся украсть ключ от башни у штейгера Силиксиза. Смотри не потеряй его: он мне ещё пригодится. Не забудь: яд ослабил всех в этой башне. Покажи, на что ты способен, неси хаос и разрушение в стены башни. Убей всех – жалости тут нет места! Когда внутри останутся лишь кровавые ошмётки, возьми денежный ящик Галливикса и укради из него запас смеси Занзила. Отнеси голову Галливикса и смесь Шентулу в Оргриммар.", female = "Тебе придётся украсть ключ от башни у штейгера Силиксиза. Смотри не потеряй его: он мне ещё пригодится. Не забудь: яд ослабил всех в этой башне. Покажи, на что ты способна, неси хаос и разрушение в стены башни. Убей всех – жалости тут нет места! Когда внутри останутся лишь кровавые ошмётки, возьми денежный ящик Галливикса и укради из него запас смеси Занзила. Отнеси голову Галливикса и смесь Шентулу в Оргриммар." },
    ["2478c"] = { male = "Бедный Физзул, он был прекрасным агентом, одним из лучших. Увы, мы заплатили за победу высокую цену. Да, работа агента Изувеченной Длани опасна. Но ты отлично справился с заданием, герой. Хорошо, что тебе удалось выжить. Ты ведь можешь и дальше служить нам.", female = "Бедный Физзул, он был прекрасным агентом, одним из лучших. Увы, мы заплатили за победу высокую цену. Да, работа агента Изувеченной Длани опасна. Но ты отлично справилась с заданием, героиня. Хорошо, что тебе удалось выжить. Ты ведь можешь и дальше служить нам." },
    ["2479a"] = { common = "Отнеси образчик этой смеси Сержу Хинотту на Мельницу Таррен. Если кто сможет тебя исцелить, так это Серж. Он тебя обучит всему, что связано с ядами, – если, конечно, выживешь." },
    ["2479c"] = { male = "О, герой, какой ты бледненький! А чем это от тебя так мерзко благоухает? Я должен выяснить!", female = "О, героиня, какая ты бледненькая! А чем это от тебя так мерзко благоухает? Я должен выяснить!" },
    ["2480a"] = { common = "Никогда не видел таких отличных результатов действия яда! Занзил, говоришь? Не слыхал о таком... Однако пора уже приступать к созданию состава. Итак, я должен вылечить тебя и научить пользоваться этим ядом? Дай мне пару минут на изучение токсина." },
    ["2480c"] = { common = "Лекарство готово! Выпей это противоядие, и наступление безумия остановится. Впрочем, с запахом ничего не поделаешь." },
    ["2498a"] = { common = "Я только что получил известие, что Деналан с озера Аль'Амет узнал, что могло послужить причиной возникновения опухоли, поражающей древесников. Пожалуйста, поговори с ним и скажи, что тебя прислал я. Торопись, ему нужна наша помощь." },
    ["2498c"] = { male = "Ах, так, значит, Релиан послал тебя мне в помощь. Хорошо, что ты так скоро пришёл. Я обнаружил нечто чрезвычайно тревожное!", female = "Ах, так, значит, Релиан послал тебя мне в помощь. Хорошо, что ты так скоро пришла. Я обнаружил нечто чрезвычайно тревожное!" },
    ["2499a"] = { male = "В пещере на южном берегу озера засел древесник по имени Дубохмур и заражает порчей всех существ, для которых окрестности озера Аль'Амет – дом родной. Я не осмелился подходить к нему близко, но даже издалека хорошо видно: Дубохмур поражён опухолью, какой я в жизни не видывал... Она просто гигантская! Ты и так уже достаточно помог мне в моих трудах, но я попрошу тебя ещё об одной услуге. Найди Дубохмура и сними эту опухоль. Избавь мою землю от источника порчи!", female = "В пещере на южном берегу озера засел древесник по имени Дубохмур и заражает порчей всех существ, для которых окрестности озера Аль'Амет – дом родной. Я не осмелился подходить к нему близко, но даже издалека хорошо видно: Дубохмур поражён опухолью, какой я в жизни не видывал... Она просто гигантская! Ты и так уже достаточно помогла мне в моих трудах, но я попрошу тебя ещё об одной услуге. Найди Дубохмура и сними эту опухоль. Избавь мою землю от источника порчи!" },
    ["2499c"] = { common = "Я так и знал, что ты сумеешь избавить озеро от этой чудовищной твари. Печальная история – Дубохмур некогда был великим вождём своих сородичей... но порча поражает всех подряд – и подлых, и благородных. Величина этой опухоли в дрожь бросает, но я обязан исследовать её, чтобы понять, какая зараза терзает древесников. Прими мою благодарность." },
    ["2500a"] = { male = "герой, я хотел бы воспользоваться твоими услугами. Я довольно известный алхимик, и мне понадобились кое-какие реактивы, которые можно отыскать в Бесплодных землях. Вот что мне нужно: пять вторых желудков канюка, десять клыков скального койота и пять осколков каменных элементалей. Очевидно, что их можно добыть у самих тварей, но если ты не любитель сражений, можешь попросить о помощи друзей. Я неплохо заплачу, если ты принесёшь мне всё необходимое. Что скажешь?", female = "героиня, я хотел бы воспользоваться твоими услугами. Я довольно известный алхимик, и мне понадобились кое-какие реактивы, которые можно отыскать в Бесплодных землях. Вот что мне нужно: пять вторых желудков канюка, десять клыков скального койота и пять осколков каменных элементалей. Очевидно, что их можно добыть у самих тварей, но если ты не любительница сражений, можешь попросить о помощи друзей. Я неплохо заплачу, если ты принесёшь мне всё необходимое. Что скажешь?" },
    ["2500c"] = { common = "Молодец. Этого мне должно хватить на некоторое время. Вот обещанная плата. Если ты не против получить новое задание, мне нужны ещё кое-какие реактивы. Некоторые из них можно найти только на ульдаманском раскопе. Добыть их нелегко, но и плата за помощь будет немалая. Может быть, кое-что получше блестящих монет!" },
    ["2501a"] = { male = "Ты не раз меня выручал. Я хотел бы дать тебе в награду рецепт зелья, которое ты уже пробовал, но взамен попрошу выполнить опасное поручение. В этом сундучке находятся три волшебных сосуда; они зачарованы так, чтобы вытянуть кровь у опалённого дракона-стража. Если воспользоваться ими, зверь разозлится, поэтому соблюдай осторожность. Когда наполнишь все три, принеси их мне. Добудь мне кровь дракона, и я отдам тебе рецепт.", female = "Ты не раз меня выручала. Я хотел бы дать тебе в награду рецепт зелья, которое ты уже пробовала, но взамен попрошу выполнить опасное поручение. В этом сундучке находятся три волшебных сосуда; они зачарованы так, чтобы вытянуть кровь у опалённого дракона-стража. Если воспользоваться ими, зверь разозлится, поэтому соблюдай осторожность. Когда наполнишь все три, принеси их мне. Добудь мне кровь дракона, и я отдам тебе рецепт." },
    ["2501c"] = { male = "Между нами, алхимиками, говоря, ты просто герой! Вот, возьми этот рецепт. Пусть он принесёт тебе успех и богатство, как и мне!", female = "Между нами, алхимиками, говоря, ты просто героиня! Вот, возьми этот рецепт. Пусть он принесёт тебе успех и богатство, как и мне!" },
    ["2518a"] = { common = "Некогда леди Сатра была дорога Элуне. Эта изящная и чистая душой паучиха ткала серебряные свои нити под светом луны, ловя в свои сети вечерний туман. Его серебристые капли обладали великой целительной силой, их хранили в этом храме. Но недавно Сатру постигло безумие. Теперь и её потомство под угрозой. Найди леди Сатру, и положи конец её страданиям. Она обитает у северных границ Тельдрассила, близ Родникового озера. Возьми её серебристые паутинные железы и принеси их мне." },
    ["2518c"] = { common = "Лес оплакивает леди Сатру, но это надо было сделать. Благодарю тебя." },
    ["2519a"] = { male = "Одному некогда великому существу из нашего леса нужна помощь, герой. Это трудное дело, но его надо сделать. Пожалуйста, разыщи нашу жрицу А'моору, она всё тебе объяснит. Ищи её к юго-востоку отсюда, в Храме Луны.", female = "Одному некогда великому существу из нашего леса нужна помощь, героиня. Это трудное дело, но его надо сделать. Пожалуйста, разыщи нашу жрицу А'моору, она всё тебе объяснит. Ищи её к юго-востоку отсюда, в Храме Луны." },
    ["2519c"] = { common = "Стало быть, тебя прислала сестра Аквинна?" },
    ["2520a"] = { male = "Теперь ты должен закончить дело, порученное тебе. Возьми эти паутинные железы и принеси их в жертву во имя Элуны. Пусть великая паучиха обретёт покой. Внутри этого храма ты найдёшь центральный фонтан. Там ты оставишь жертвоприношение. Святые воды смоют порчу, что повергла Сатру в безумие. Когда закончишь дело, возвращайся ко мне.", female = "Теперь ты должна закончить дело, порученное тебе. Возьми эти паутинные железы и принеси их в жертву во имя Элуны. Пусть великая паучиха обретёт покой. Внутри этого храма ты найдёшь центральный фонтан. Там ты оставишь жертвоприношение. Святые воды смоют порчу, что повергла Сатру в безумие. Когда закончишь дело, возвращайся ко мне." },
    ["2520c"] = { male = "Велика наша скорбь по леди Сатре, но лишь так она может возродиться с обновлённым духом. Да примет Элуна ту жертву, что ты принёс ей.", female = "Велика наша скорбь по леди Сатре, но лишь так она может возродиться с обновлённым духом. Да примет Элуна ту жертву, что ты принесла ей." },
    ["2541a"] = { common = "Шаман племени Кривой Сосны, который живёт в этих местах, нашёл способ разлучать дух спящего друида с физическим телом. Этот фурболг оживил моё тело и заставил его нападать на любого, кто пытается обследовать обитель Бен'этиль. Теперь мне не выйти из Изумрудного Сна, и я не могу прекратить это! Помоги мне! У шамана Кривой Сосны есть при себе странный оберег, который он использует во время ритуала, и я хотел бы исследовать его. Прошу тебя, принеси его мне!" },
    ["2541c"] = { common = "Прими мою благодарность. Какая странная вещица... Я чувствую злую ауру, которую она излучает. Очень мощное заклятие..." },
    ["2561a"] = { male = "Изучив этот оберег, я понял, что надо сделать. Пожалуйста, возьми его и сделай, как я прошу. Тебе придётся собраться с духом и проникнуть в самые глухие закоулки обители Бен'этиль. Там ты найдёшь моё лишённое души тело... Хотя я и скорблю о том, что мне сейчас придётся поведать тебе, я не вижу другого способа освободиться от власти племени Кривой Сосны. Чтобы я мог сбежать от них, ты должен уничтожить моё физическое тело. Как только это будет сделано, обрати на мой труп силу амулета вуду. После этого возвращайся ко мне.", female = "Изучив этот оберег, я понял, что надо сделать. Пожалуйста, возьми его и сделай, как я прошу. Тебе придётся собраться с духом и проникнуть в самые глухие закоулки обители Бен'этиль. Там ты найдёшь моё лишённое души тело... Хотя я и скорблю о том, что мне сейчас придётся поведать тебе, я не вижу другого способа освободиться от власти племени Кривой Сосны. Чтобы я мог сбежать от них, ты должна уничтожить моё физическое тело. Как только это будет сделано, обрати на мой труп силу амулета вуду. После этого возвращайся ко мне." },
    ["2561c"] = { male = "Наконец-то я свободен от власти племени Кривой Сосны! Спасибо тебе. Отныне мой дух обретёт вечный покой в объятиях Изумрудного Сна. Возможно, однажды мы снова встретимся, юный герой. Но пока прими эту награду в знак моей благодарности.", female = "Наконец-то я свободен от власти племени Кривой Сосны! Спасибо тебе. Отныне мой дух обретёт вечный покой в объятиях Изумрудного Сна. Возможно, однажды мы снова встретимся, юная героиня. Но пока прими эту награду в знак моей благодарности." },
    ["2581a"] = { common = "Хорошо известно, что челюсти гиены невероятно сильны, но чтобы они были способны прокусить три дюйма ториевой стали? Невозможно, невероятно, и тем не менее я видел это своими глазами. Отправляйся в Выжженные земли и принеси мне три челюсти гиены-ухмыльника. А пока ищешь гиен, высматривай также кабанов и скорпоков: для дополнения к изначальной эссенции требуется также два обожжённых лёгких вепря и одна клешня скорпока." },
    ["2581c"] = { common = "Как самочувствие? Ты излучаешь ауру гиены-ухмыльника – силу, с которой никто из смертных не сравнится! К несчастью, из принесённых тобой компонентов я смогу сделать эссенции только на одну таблетку. Если тебе понадобится ещё одна таблетка, мне нужно будет больше компонентов." },
    ["2582a"] = { common = "О, добро пожаловать, давно не виделись. Похоже, тебе понравился эффект крепкого, действенного зелья, извлечённого из гиены-ухмыльника. Однако осторожнее: если непосредственным эффектом является титанический прилив сил, то долгосрочный эффект, сказывающийся на твоём духе и рассудке, может быть опасным. Кстати говоря, тебе нужно ещё зелья? Тогда принеси мне ещё три челюсти гиены, два обожжённых лёгких вепря и одну клешню скорпока." },
    ["2582c"] = { common = "Вот, возьми! И помни, что использовать это зелье надо расчётливо. Если понадобится ещё, приходи ко мне после того, как израсходуешь порцию, которую я тебе только что выдал." },
    ["2583a"] = { common = "В этих опалённых землях водятся два вида кабанов: углегривый кабан и зловепрь. Судя по всему, стойкость этих тварей такова, что делает их почти неуязвимыми, поскольку другие животные считают, что вепрей слишком трудно убить, следовательно, на них не стоит даже тратить усилий. Нам нужно провести дальнейшие исследования. Если ты принесёшь мне три обожжённых лёгких вепря, две клешни скорпока и один мозг василиска, я создам отличный эликсир на основе вытяжки из этого материала. И первым делом проверю на тебе!" },
    ["2583c"] = { common = "Дух вепря озаряет твоё существование! Может быть, ты веришь, что тебе дарована неуязвимость, как и этим тварям?" },
    ["2584a"] = { common = "Когда я впервые выдал тебе этот эликсир, я уже понимал, что одна-две порции не удовлетворят твой аппетит. Даже сейчас я вижу в твоих глазах этот голод. Сей состав имеет одно побочное свойство – он даёт привыкание, которому, похоже, не может сопротивляться даже самая сильная воля. Что ж, пусть так! Если тебе требуется ещё порция смеси с лёгочной вытяжкой, отправляйся обратно в пустоши и принеси мне три обожжённых лёгких вепря, две клешни скорпока и один мозг василиска." },
    ["2584c"] = { common = "Хочу предупредить тебя, не пытайся смешивать созданные мною составы. Химические свойства состава, недавно принятого тобою, всегда возобладают над предшествующими заклинаниями, таким образом, эффект другого зелья будет сведён на нет." },
    ["2585a"] = { common = "Тебе приходилось видеть их сражение? Я имею в виду скорпоков. Видеть грациозность и ловкость, с которой они движутся? Решительность, с которой они наносят удары? Если бы мы только могли выделить эту ловкость и заключить её в оболочку, мы были бы богаты вне всякого... я хочу сказать... это было бы благо для всего научного соообщества. Помоги мне, и я выделю для тебя порцию настойки. Для того чтобы создать стабильное вещество, мне потребуется три клешни скорпока, две меры потрохов стервятника и одно обожжённое лёгкое вепря." },
    ["2585c"] = { common = "Потрясающе. Анализ этой эссенции был самым сложным. Возьми щепотку этой солевой вытяжки и положи её под язык. Ты испытаешь лёгкое чувство эйфории, после которого наступит состояние невероятной ловкости и быстроты." },
    ["2586a"] = { male = "Ты жив! Это поистине хорошая новость! Полагаю, тебе нужно ещё скорпоковой настойки? Отлично, тогда снова ступай в пустоши и не возвращайся, пока не заполучишь три клешни скорпока, две меры потрохов стервятника и одно обожжённое лёгкое вепря.", female = "Ты жива! Это поистине хорошая новость! Полагаю, тебе нужно ещё скорпоковой настойки? Отлично, тогда снова ступай в пустоши и не возвращайся, пока не заполучишь три клешни скорпока, две меры потрохов стервятника и одно обожжённое лёгкое вепря." },
    ["2586c"] = { common = "Отличная работа. Вот одна мера настойки для тебя, а оставшиеся девять будут использованы для моих исследований. В любой момент, когда тебе понадобится скорпоковая настойка, возвращайся ко мне, и мы заключим сделку." },
    ["2601a"] = { common = "Эти пустоши кишат василисками Красного камня. Эти василиски отлично приспособились к местным условиям, их тут больше, чем любых других диких животных. Я наблюдала издали, как они охотятся и ведут свою повседневную жизнь – мыслительный процесс у этих тварей, похоже, куда более сложный, чем у некоторых из тех существ, которых мы называем разумными. Я должна изучить их мозги! Раздобудь для меня десять их мозгов. Однако для опытов мне понадобятся ещё потроха двух стервятников, которые дадут основу для раствора." },
    ["2601c"] = { common = "Замечательно! Предлагаю тебе отведать на вкус внутреннюю суть василисков красного камня. Если этот состав тебе понравится, всегда можно сделать ещё... за определённую плату." },
    ["2602a"] = { common = "Твоё сосредоточение ушло так скоро? Нужно провести ещё больше исследований! Ах да, цена остаётся прежней. Отправляйся в Выжженные земли и возвращайся ко мне с десятью мозгами тварей Красного Камня и потрохами двух стервятников." },
    ["2602c"] = { common = "Да, да, дай мне минутку, и нужные тебе составы будут готовы к употреблению. Вот, возьми... и помни, что нельзя даже пытаться употреблять эти экспериментальные составы слишком часто. Результат будет катастрофическим." },
    ["2603a"] = { male = "В этих опалённых землях смерть воистину крылата, герой.Я много раз наблюдала, как чёрные убийцы и костеглоды пируют на телах павших исследователей – иногда пожирая наиболее отвратительные и разложившиеся останки трупов. Удивительно всё же, как их внутренние органы справляются с заразой, царящей в этих землях? Помоги мне в моих исследованиях! Мне нужны потроха! Понадобятся также две челюсти гиены в качестве основы для состава. Твои усилия будут вознаграждены вдвойне.", female = "В этих опалённых землях смерть воистину крылата, героиня.Я много раз наблюдала, как чёрные убийцы и костеглоды пируют на телах павших исследователей – иногда пожирая наиболее отвратительные и разложившиеся останки трупов. Удивительно всё же, как их внутренние органы справляются с заразой, царящей в этих землях? Помоги мне в моих исследованиях! Мне нужны потроха! Понадобятся также две челюсти гиены в качестве основы для состава. Твои усилия будут вознаграждены вдвойне." },
    ["2603c"] = { common = "Превосходно! Я немедленно приступаю к работе. Возможно, удастся найти лекарство от множества недугов, существующих в этом мире! Ах да, твоя награда – конечно, если тебе опять понадобится зелье, возвращайся ко мне, я дам тебе новое поручение." },
    ["2604a"] = { common = "Я вижу, внутреннее пламя угасло. Как по-твоему, длилась ли эта духовная эйфория хотя бы час? Если ты желаешь получить ещё зелья из потрошков, то изволь снабдить меня сырьём! Отправляйся обратно. И не возвращайся, пока не наберёшь десять мер потрохов и две челюсти." },
    ["2604c"] = { common = "Возможно, когда-нибудь я смогу выделить активные компоненты этой эссенции и получить куда более эффективный результат. К несчастью, пока тебе придётся довольствоваться тем, что я в состоянии сделать на настоящий момент. Если понадобится ещё зелье из потрошков, возвращайся ко мне." },
    ["2605a"] = { common = "Слышь, у меня возникла мысль. Я слышал о странных тварях, собирателях росы, живущих на юго-западе... Говорят, они хранят воду в особых железах. Мне кажется, что из этих желёз я бы сделал напиток, который утолил бы мою жажду! Ты не поможешь мне? Поищи кактусовый сад, именно там пасутся собиратели росы." },
    ["2605c"] = { common = "Чудесно! Дай мне железу – я хочу выпить её!" },
    ["2606a"] = { common = "Фу! Ну и гадость! Да, идея была неудачная… Стой, что такое? О, знаю, ты считаешь, что не стоит отказываться от этой штуки. Ладно. Эээ... У меня есть идея! Гениально! Отнеси эту росу моей подруге Поливалке – она отличный повар. Скажи, что мы тут задумали, пусть придумает, как улучшить вкус. Я хочу сказать, что такая дрянь по крайней мере, должна пробирать до мозга костей... А пока ей до мозга далеко..." },
    ["2606c"] = { common = "Синь отличный парень, не пойми меня превратно – только немного... эксцентричный, что ли. И разумеется, ему опять нужна моя помощь." },
    ["2607a"] = { common = "Похоже, что информации у вас даже больше, чем я ожидал. Как-то странно всё оборачивается. Лекарство? Хм-м... Спуститесь в подвал и поговорите с Доком Миксиль-Пиксилем – он, вероятно, сможет помочь." },
    ["2607c"] = { common = "Как раз вовремя! Просто положите сыр на стол и проваливайте. Осборн заплатит вам на выходе." },
    ["2608a"] = { male = "Ох, вы так выглядите – точь-в-точь мертвец. Поправочка – я видел мертвецов, вы выглядите ещё хуже. Вы, сударь, будете предсмертной отрыжкой самой смерти. Ха! Слышал, Ноарм? Запиши-ка это! *Кашляет.* Хмм, да, чтобы я мог помочь, мне нужно будет взять у вас немного крови. Не беспокойтесь, больно лишь первые... раз пятьдесят или около того... Ложитесь, и приступим к лечению!", female = "Ох, вы так выглядите – точь-в-точь мертвец. Поправочка – я видел мертвецов, вы выглядите ещё хуже. Вы, детка, будете предсмертной отрыжкой самой смерти. Ха! Слышал, Ноарм? Запиши-ка это! *Кашляет.* Хмм, да, чтобы я мог помочь, мне нужно будет взять у вас немного крови. Не беспокойтесь, больно лишь первые... раз пятьдесят или около того... Ложитесь, и приступим к лечению!" },
    ["2608c"] = { common = "Позвольте, я минутку посовещаюсь со своими коллегами. Доктор Монтгомери, мистер Ноарм, все на консилиум!" },
    ["2609a"] = { common = "Однозначно. У вас чтотит. К счастью, от чтотита у меня есть средство. И вот что мне понадобится для его изготовления: букетик простых полевых цветов, одна освинцованная колба, одна бронзовая трубка и последнее – но немаловажное! – нитка светлого зеленовато-жёлтого шёлка. Старушка Эмма оставила для меня катушку таких ниток в \"Тончайшей пряже\". Эту лавку можно найти, если идти вдоль каналов. А теперь поспешите, и постарайтесь ни к кому не прикасаться, пока вас не вылечат. Кстати, доктор Монтгомери сказал, что вам нужно душ принять... это его слова, не мои!" },
    ["2609c"] = { common = "Что я делаю? А на что похоже то, что я делаю? Я продумываю, как вылечить ваш чтотит! И нечего так возмущённо на меня смотреть! Ещё несколько секунд... Готово! Побрызгайте на себя этим лечебным средством с... эээ... необыкновенным запахом – и вы в полном порядке!" },
    ["2621a"] = { common = "Сожалею. Это всё, что у меня есть. Одно неверное решение, приведшее к массе плохих последствий. Если бы я только дождался тех приказов! Может быть, там было бы сказано подробно обо всех ужасах, ожидающих нас в этих проклятых землях? Может быть, нам дали бы другое задание или выслали бы подкрепление? Но в конечном итоге, это моя вина. Всё это – моя вина. И вот я стою здесь, ожидая приказов. Я должен знать. Я должен знать, каковы эти приказы. Командир-посланник Руаг находится в Каменоре. Найди его и узнай, что стало с приказами." },
    ["2621c"] = { common = "Хватка Тралла... Эта история всё ещё свежа в моей памяти. *Командир Руаг качает головой.* Ужасная вещь – то, что случилось с этим подразделением. Орда потеряла немало своих лучших солдат, когда этот батальон был уничтожен." },
    ["2622a"] = { common = "Приказы? Зачем тебе понадобились эти приказы? Что ты подразумеваешь? Конечно, я передал эти приказы! Солдаты, с которыми я их послал, попали в засаду и были безжалостно забиты до смерти мурлоками. Выжил только один – если это называется выжить. Он едва может говорить, не может ходить, его приходится кормить через трубку. Если хочешь знать, что случилось с приказами, поговори с Бенгором. Я знаю, он где-то неподалёку... и вот ещё что, следи, куда суёшь свой нос – его ведь и откусить могут." },
    ["2622c"] = { common = "Болот... ный... гово... говорун..." },
    ["2623a"] = { common = "Приказы были отданы командиром-посланником. Мы приняли… приняли приказы. На пути в Выжженные земли — засада. Мурлоки… много мурлоков… Одного звали Болотный Говорун. Вырвал приказы у меня из рук, ударил копьём мне в голову. Восток… пещера…" },
    ["2623c"] = { common = "Это хуже, чем я ожидал. Девятнадцать моих соратников были бы избавлены от мучений, которым они подвергаются. Если бы я только действовал не столь неразумно! Помоги им, путник! Я бессилен что-либо сделать." },
    ["2641a"] = { common = "Когда я была маленькая, у нас в семье готовила моя сестра. Это было ужасно! Половину её творений я даже в рот взять не могла... пока не отыскала свой \"маленький секрет\"! Добавь его в любую еду и... получится вкуснятина! Что за секрет, спросишь ты. Это гриб, называемый фиалковый траган. Если хочешь помочь мне превратить эту дрянь во что-то съедобное, отправляйся во Внутренние земли и поищи там маленькое озерцо. И не забывай, фиалковый траган растёт только под водой." },
    ["2641c"] = { common = "Ага, вот и он! Отлично выглядит, хоть сейчас... Ха-ха, шучу!" },
    ["2661a"] = { common = "Вот фиалковый порошок. Отнеси его Синю и скажи ему, что он мой должник!" },
    ["2661c"] = { common = "Фиалковый порошок, значит? Дай-ка попробую – хуже всё равно не будет, это ясно!" },
    ["2662a"] = { common = "А теперь вмешаем этот порошок в росу. Заходи через пару минут... когда я доведу до совершенства великолепный эликсир Гогельмогеля!" },
    ["2662c"] = { common = "Попробуй! Невероятно вкусно!!! Я знал, что у меня всё получится... Ещё раз спасибо за помощь, только встань в сторонке! Ты не даёшь прохода будущим покупателям. Я заработаю миллионы на неподражаемом эликсире Гогельмогеля, миллионы! Что такое? Поливалка говорит, что я её должник? Ох, такая шутница эта Поливалка!" },
    ["2681a"] = { common = "Одних лишь твоих сил не хватит, чтобы одолеть Разелиха и его приспешников. Собери подходящую группу искателей приключений и освободи моих подчинённых от вечных мук! Тебе нужно разбить восемнадцать камней. Сражайся отважно и умри с честью, путник." },
    ["2681c"] = { common = "Ты сделал это, путник! Бедные, замученные души могут наконец отдохнуть. Наша работа ещё не завершена, путник. Нам многое нужно обсудить и ещё больше сделать." },
    ["2701a"] = { common = "Пожалуйста, забери отсюда реликвию древности. Мы больше ни на что не можем использовать её. Может быть, она послужит тебе в борьбе против Легиона." },
    ["2701c"] = { common = "Вас ослепило сиянием и тысячей вспыхнувших искр." },
    ["2702a"] = { common = "Твои благородство и героизм — высокая честь для меня, путник. И для тебя — не менее высокая…" },
    ["2702c"] = { common = "Несомненно, ты впечатлил всех нас. Одних наших благодарностей не достаточно." },
    ["2721a"] = { common = "Как только завершается одна часть твоих приключений, путник, начинается другая. Один из моих подчинённых пропал без вести — затерялся где-то в Выжженных землях. Я, конечно же, говорю о лейтенанте Кирите. Как я упоминал ранее, мы оба были в плену у Аллистария и подвергались мучениям, но увы несчастному Кириту — его сила воли оказалась недостаточно велика. Из своей клетки я слышал происходящее: крики боли разносились по пещерным залам. С тех пор Кирита и след простыл." },
    ["2721c"] = { common = "Требор? Требор прислал тебя?" },
    ["2741c"] = { common = "Вы помещаете яйцо гиппогрифа в машину. Следует серия звуковых сигналов и за ней странные механические звуки. Похоже, Яйц-О-Матик взвесил, измерил и упаковал яйца. Теперь, это скоростное обслуживание!" },
    ["2742a"] = { male = "Эй, герой! Рин'джи потерял топор, и его схватили! Пожалуйста, помоги Рин'джи сбежать. Я знаю, что не каждый герой любит троллей, но я тебя очень прошу! Мне надо выйти отсюда! У меня кое-что есть, и очень хорошее, если поможешь мне, я тебе это подарю... Рин'джи спрятал свой секрет у Отвесных скал.", female = "Эй, героиня! Рин'джи потерял топор, и его схватили! Пожалуйста, помоги Рин'джи сбежать. Я знаю, что не каждая героиня любит троллей, но я тебя очень прошу! Мне надо выйти отсюда! У меня кое-что есть, и очень хорошее, если поможешь мне, я тебе это подарю... Рин'джи спрятал свой секрет у Отвесных скал." },
    ["2742c"] = { common = "Эта табличка, наверное, и есть тот самый \"секрет\", о котором говорил Рин'джи. Она покрыта странными письменами, которые вам совершенно не знакомы." },
    ["2743a"] = { common = "Не будем тратить слов, странник; моё время здесь ограничено. Тебе следует уничтожить троицу силы, связанную с повелителем демонов Разелихом. Это деяние не настолько просто, как задача по освобождению проклятой души. Видишь ли, каждый из прислужников Разелиха носит на шее треть амулета, при помощи которого был создан Разелих. Тот же самый амулет понадобится тебе для призвания сего архидемона. Возвращайся к Требору и поведай ему, что требуется для призвания Разелиха. Он подскажет тебе, что делать дальше." },
    ["2743c"] = { common = "Повелитель демонов проявляет хитрость почти столь же расчётливую, как и его жестокость, путник." },
    ["2744a"] = { common = "Эта троица находится под покровительством Разелиха. В обмен на их службу Разелих даровал каждому из них почти безграничную власть над Выжженными землями. Кусочки амулета связаны с жизненной силой их владельцев и дают им бессмертие. Пока они остаются в Выжженных землях, их нельзя убить и их жизнь продлится до конца мира. Но есть некто, способный оказать тебе помощь в дальнейшем, путник. Отправляйся в Азшару и найди там охотника на демонов, Лорамуса Многонога. Поиск следует вести на островах." },
    ["2744c"] = { common = "Я помогу тебе. Только вот сдаётся мне, ты не совсем понимаешь, против кого тебе придётся выступить." },
    ["2745a"] = { common = "Хм-м, интересная история, причём не из тех, на которые можно наплевать. Да, помочь-то я вам могу, но то, что вам нужно будет сделать, это свершить правосудие... частично незаконным путём, если уж вы хотите довести дело до конца. С Лесковаром и Марзоном нужно разобраться – и быстро. Как думаете, вы на это способны? Решать вам. Если да, то поскорее отправляйтесь в крепость и найдите там моего старинного друга – гнома по имени Тирион. Он уже пару недель как наблюдает за Лесковаром. Он сможет помочь вам покончить с этим делом." },
    ["2745c"] = { common = "Какого?! Не подкрадывайтесь ко мне вот так! И говорите тише! На кой вы, спрашивается, во имя Теней, так ко мне подкрадываетесь? Не видите, что ли – я занят, безмозглое вы создание! Что вы имеете в виду, спрашивая, что я делаю? Жду открытия следующего Тёмного портала, а вы что подумали? Выкладывайте, с чем пришли, и валите отсюда... пока стражники не заметили, что мы тут вдвоём в кустах прячемся. Мне нужно блюсти репутацию." },
    ["2746a"] = { common = "Триас хочет поторопить события, так? Ладно, мы это сделаем, но сейчас я не готов. И, кстати, сложную часть я беру на себя, а ручки пачкать будете вы, это понятно? Отлично. Значит, мне нужно, чтобы вы мне кое-что принесли, чтобы я смог воплотить в жизнь свой план. У меня есть мысль об отличной маскировке, при помощи которой этот робот-шпион пройдёт мимо стражников. Принесите мне немного шёлка и пару яблок. Где достать шёлк – думайте сами, а вот подходящие яблоки есть у Клары в её маленьком хозяйстве сразу за городской чертой." },
    ["2746c"] = { common = "Это отлично подойдёт. Прекрасная работа. Вся остальная амуниция у меня в сумке... Слава Свету, у меня есть приятель-портной, сшивший мне шёлковую сумку. А то мне бы уже некуда было рассовывать свои вещи. Прежде чем мой робот-шпион отправится куда надо, давайте обговорим детали, чтобы вы знали, что вам нужно будет делать." },
    ["2751a"] = { common = "Двадцать поколений Омошей держали в руках этот молот! Сколько тонн металла мы перековали! Но, увы, на мне наш род завершится. У меня нет потомства. Я не могу допустить, чтобы тайные чертежи и приёмы Омошей умерли вместе со мной! Докажи Орокку, что ты годишься в кузнецы. Принеси ему два узорчатых бронзовых боевых браслета, два бронзовых больших меча и два острых когтя. Принеси их Орокку, и мы продолжим обучение." },
    ["2751c"] = { common = "Наш род иссякнет, но, возможно, легенды об Омошах будут жить! Да, ты настоящий кузнец! Главная награда для кузнеца – видеть оружие и доспехи своей работы обагрёнными кровью врагов! Пусть изготовленная тобою кираса ржавеет только от вражеской крови!" },
    ["2752a"] = { common = "У тебя внимательные глаза. Ты вбираешь мудрость Омошей, точно губка! Три урока дам я тебе. Вернись к наковальне и сделай для Орокка четыре бронзовых боевых топора и четыре бронзовых боевых молота. Лишь тогда узнаешь ты, как изготовить железное оплечье!" },
    ["2752c"] = { common = "Орокк гордится тобой. Вот, читай, как изготовить железное оплечье!" },
    ["2753a"] = { common = "Орокк научит тебя ещё двум вещам. Да, я знаю, тебе тяжело, но надо продолжать – во имя Омошей! Принеси четыре зелёных железных шлема, четыре пары зелёных железных наручей и два пары зелёных железных поножей – и я научу тебя тому, что будет страшить твоих врагов!" },
    ["2753c"] = { common = "Ты напоминаешь Орокку его деда, Горокка Омоша! Вот, читай, учись делать железные сапоги." },
    ["2754a"] = { common = "Это последнее, чему научит тебя Орокк. Но прежде принеси Орокку два твёрдых железных кувалды, два пары посеребрённых бронзовых сапог и две пары посеребрённых бронзовых рукавиц. Ты узнаешь, как приятно видеть страх в глазах врагов при одном твоём появлении!" },
    ["2754c"] = { common = "Потрясающе! Теперь ты знаешь все секреты Омошей!" },
    ["2755a"] = { common = "Нет, Орокк не плачет. Это сажа в глаз попала. *Орокк утирает слезу.* Остался последний секрет семьи Омошей, которому научит тебя Орокк. Выучи танец радости Омошей, и научишься ковать железный кулак!" },
    ["2755c"] = { common = "Давненько Орокк не плясал танец Радости Омошей! Ну, смотри и учись!" },
    ["2756a"] = { male = "В былые легендарные времена Атурк сокрушил бы черепа своих врагов и истёр кости в мелкий порошок! Но эти дни давно миновали, герой. Вождь требует мира между кланами, и старых врагов мы теперь даже пальцем тронуть не смеем. Даже не верится! Но такова воля Тралла. Ну, довольно жалоб! Ты здесь, чтобы учиться – и ты будешь учиться! Принеси четыре стальные кирасы и четыре стальных латных шлема, и узнаешь вкус войны!", female = "В былые легендарные времена Атурк сокрушил бы черепа своих врагов и истёр кости в мелкий порошок! Но эти дни давно миновали, героиня. Вождь требует мира между кланами, и старых врагов мы теперь даже пальцем тронуть не смеем. Даже не верится! Но такова воля Тралла. Ну, довольно жалоб! Ты здесь, чтобы учиться – и ты будешь учиться! Принеси четыре стальные кирасы и четыре стальных латных шлема, и узнаешь вкус войны!" },
    ["2756c"] = { common = "Похоже ты ещё жив. Как разочаровывающе. Разве ты не знаешь, что самой славной наградой является смерть на поле битвы! А я вот здесь, по приказу Тралла учу детишек мастерить. Смотри и учись... дитя..." },
    ["2757a"] = { common = "Слышь, будешь болтаться здесь – так ничему и не научишься! Вот я знаю мужика, который знает мужика, который ошивается возле кузницы в Пиратской бухте. Покажи ему этот значок, и он тебе про мифрил всё расскажет! Чего-чего? Оставь это грудным младенцам, тебе пора двигаться дальше! Если тебя это интересует, его звать Макгеван." },
    ["2757c"] = { common = "Клянусь задницей Чёрного Копыта! Наконец хоть кто-то достойный Ордена мифрила!" },
    ["2758a"] = { common = "Когда я был примерно в твоём возрасте, дворф по имени Гальван взял меня под свою опеку и обучил меня способам ковки доспехов. Перед своим отъездом в Пиратскую бухту он заставил меня пообещать, что я буду до конца дней своих обучать всех, у кого будет желание и решимость овладеть кузнечным ремеслом. Так я и поступил. Итак, теперь настало твоё время чему-нибудь научиться. Сделай мне шесть пар золотых чешуйчатых наручей – и узнаешь, откуда есть пошло кузнечное дело." },
    ["2758c"] = { common = "Отлично! Слушай и впитывай. Мастерство кузнеца никогда не исходит отсюда! Хэнк указывает на молот. Мастерство кузнеца никогда не исходит и отсюда! Хэнк указывает на наковальню. Только отсюда происходит мастерство кузнеца! Хэнк указывает себе на сердце. Теперь ты знаешь, каково происхождение кузнечного искусства." },
    ["2759a"] = { male = "Хотя Гальван покинул Пиратскую бухту много лет назад, члены ордена по-прежнему остаются в городе, надеясь однажды найти кого-нибудь, достойного внимания мастера. Возьми этот знак и отдай его Макгевану в Пиратской бухте. Если ты действительно с этим справишься, он поймёт, что ты достоин. Я в тебя верю!", female = "Хотя Гальван покинул Пиратскую бухту много лет назад, члены ордена по-прежнему остаются в городе, надеясь однажды найти кого-нибудь, достойного внимания мастера. Возьми этот знак и отдай его Макгевану в Пиратской бухте. Если ты действительно с этим справишься, он поймёт, что ты достойна. Я в тебя верю!" },
    ["2759c"] = { common = "Клянусь гривой Чёрного Копыта – наконец-то появился хоть кто-то, достойный Ордена мифрила!" },
    ["2760a"] = { common = "Большинство наших новобранцев так и не добрались до Пиратской бухты. Блеска эмблемы оказывается достаточно, чтобы пробудить алчность даже в самых стойких кузнецах. Дураки, эмблема эта – капля в море по сравнению со стоимостью предметов, которые ты увидишь! Найди Гальвана Древнего и покажи ему эту булавку. Он живёт далеко на севере, междук Зул-Гурубом и холмом Мош'Огг." },
    ["2760c"] = { common = "А, прошло много лет, с тех пор, как я в последний раз видел достойных принятия в Орден мифрила. Начнём же!" },
    ["2761a"] = { male = "Многие кузнецы считают, что горное дело и кузнечное ремесло – две разные вещи; но что за кузнец без металла? Как же, это невозможно! Опытный кузнец должен быть и опытным горняком. Покажи Гальвану, на что ты способен. Принеси мне сорок слитков железа и сорок слитков серебра. За это Гальван научит тебя создавать изысканные мифриловые штаны!", female = "Многие кузнецы считают, что горное дело и кузнечное ремесло – две разные вещи; но что за кузнец без металла? Как же, это невозможно! Опытный кузнец должен быть и опытным горняком. Покажи Гальвану, на что ты способна. Принеси мне сорок слитков железа и сорок слитков серебра. За это Гальван научит тебя создавать изысканные мифриловые штаны!" },
    ["2761c"] = { common = "Твои работы безупречны! Ты начинаешь понимать основы минералогии Гальвана! Возьми это и научись всему, чему сможешь." },
    ["2762a"] = { common = "Говорят, что истинное серебро прочнее мифрила. Гальван не будет спорить с такой оценкой, но вопреки названию, истинное серебро далеко от истины! Мифрил куда благороднее! ХА! И тем не менее, на сей раз тебе придётся найти это обманное серебро. Принеси мне сорок мифриловых слитков и сорок слитков истинного серебра. Взамен я научу тебя искусству изготовления изысканных мифриловых перчаток, и что куда важнее, ты узнаешь, что истинное серебро – это лжец." },
    ["2762c"] = { common = "Нелегко с ним справиться, а? Я об истинном серебре. Гальван потратил не меньше десяти лет в горах Альтерака, прежде чем усвоил этот урок. Возьми это и научись, чему сможешь!" },
    ["2763a"] = { common = "Для нашего ремесла очень важно научиться добывать дракоценные камни. Немногие камни драгоценнее цитрина. Он во много раз усиливает ту магию, которую мы вкладываем в наши творения. На сей раз мы усилим сорок слитков мифрила четырьмя цитринами. В результате ты получишь лучшее представление о магической гемологии и научишься создавать изысканные мифриловые наплечники." },
    ["2763c"] = { common = "Да, от такой красоты взгляда не оторвёшь. Цитрин – великолепный камень. А теперь смотри внимательно, вот чему можно научиться!" },
    ["2764a"] = { male = "Если ты готов покинуть Гальвана, отправляйся в Прибамбасск. Там живёт мой лучший ученик, Трентон Молот Света. Он научит тебя обращению с изысканным мифрилом. Впрочем, можешь остаться здесь и поучиться ещё! Ах да, Прибамбасск находится в Танарисе!", female = "Если ты готова покинуть Гальвана, отправляйся в Прибамбасск. Там живёт мой лучший ученик, Трентон Молот Света. Он научит тебя обращению с изысканным мифрилом. Впрочем, можешь остаться здесь и поучиться ещё! Ах да, Прибамбасск находится в Танарисе!" },
    ["2764c"] = { male = "Тебя прислал Гальван Древний? Трентон кланяется Это большая честь – познакомиться с ещё одним из его учеников!", female = "Тебя прислал Гальван Древний? Трентон кланяется Это большая честь – познакомиться с ещё одной из его учениц!" },
    ["2765a"] = { male = "Я с первого взгляда понял, что ты станешь одним из моих лучших учеников! Ты без колебаний отдал Макгевану вещь, наделённую силой, лишь бы только встретиться со мной. Подобная слепая вера и преданность искусству должна быть вознаграждена. Ты стал настоящим экспертом в кузнечном деле. Насладись же наградой!", female = "Я с первого взгляда понял, что ты станешь одной из моих лучших учениц! Ты без колебаний отдала Макгевану вещь, наделённую силой, лишь бы только встретиться со мной. Подобная слепая вера и преданность искусству должна быть вознаграждена. Ты стала настоящим экспертом в кузнечном деле. Насладись же наградой!" },
    ["2765c"] = { male = "Что ж, ты в самом деле заслужил украшение, наделённое большей силой, чем то, которым пришлось пожертвовать на пути сюда. Пользуйся на здоровье.", female = "Что ж, ты в самом деле заслужила украшение, наделённое большей силой, чем то, которым пришлось пожертвовать на пути сюда. Пользуйся на здоровье." },
    ["2766a"] = { common = "Перед вами странный металлический предмет яйцевидной формы. Вы понажимали на кнопочки – и внезапно яйцо ожило и раскрылось. Очевидно, это какой-то гномский приборчик! Из механического яйца раздаётся искажённый разрядами голос: \"Меня зовут Карлс Пропеллерз. Мой автономный робот попал в аварию! Обнаруживший его получит награду! Прошу вас, доставьте этот маячок к роботу! Я вычислил координаты робота – он находится в пещере рядом с Долиной Свирепого Утёса!\"" },
    ["2766c"] = { common = "Вы помещаете яйцо... то есть аварийный маяк... внутрь цыплёнка... то есть автономного робота. Внутри робота слышится гудение и жужжание. Он пытается подняться на ноги. После того как робот оживает, снова слышится голос Карлса, но на этот раз изнутри робота: \"Ну что ж, по крайней мере, КПХ-двадцать два/FE работает. Однако он нуждается в серьёзном ремонте! Нести его вы не сможете, он слишком тяжёлый... О! У меня идея! Не согласитесь ли вы его проводить?\"" },
    ["2767a"] = { common = "Из динамика снова слышится искажённый разрядами голос гнома: \"Мне необходимо перегнать OOX-двадцать два/FE в просторное и безопасное место, чтобы начать длительную процедуру подготовки к взлёту. Проводите робота из того места, где вы его обнаружили, в... ну, скажем, в порт на Забытом берегу! Это самое подходящее место, и там достаточно просторно, чтобы аппарату было где развернуться. Проводите робота в порт, а затем сообщите об этом мне. Я живу в Пиратской бухте, меня зовут Карлс Пропеллерз. Конец связи!\"" },
    ["2767c"] = { common = "О, спаситель! Вы доставили на место КПХ-двадцать два/FE! У меня просто слов нет, настолько я вам благодарен! Моя серия автономных роботов постоянно нуждается в усовершенствованиях, однако ваша помощь сберегла мне немало часов кропотливой работы, и дорогостоящих деталей вдобавок! Прошу вас, выбирайте любую из этих готовых моделей. Ещё раз спасибо вам! Мы с моими роботами – ваши должники!" },
    ["2768a"] = { common = "Сержант Блай обокрал меня! Он сказал, что он только одолжит, но он украл мой драгоценный изыскательский стержень!!! Без этого стержня как я буду знать, где бурить новые скважины под воду?? Найди Блая и принеси мне мой стержень! Я услышал, что он вынудил его компашку низкопробных авантюристов идти за сокровищами в Зул'Фаррак, – город, расположенный на западе. Держу пари, там ты его и найдёшь. Надеюсь, что он уже повстречался с троллями, потому что если тебе придётся драться с ним за мой стержень, то схватка выйдет нешуточная." },
    ["2768c"] = { male = "Ты сделал это. Пришлось ли тебе убить Блая? Надеюсь, ты задал ему и его прихвостням хорошую трёпку!", female = "Ты сделала это. Пришлось ли тебе убить Блая? Надеюсь, ты задала ему и его прихвостням хорошую трёпку!" },
    ["2769a"] = { common = "Вы ещё не встречались с братьями Латунный Болт? Они на Мерцающей равнине в Калимдоре гоняют на своём болиде наперегонки с гоблинами. Обычно они выигрывают, что неудивительно: гоблинские машины взрываются так часто, что едва дотягивают до финишной черты! Но братья Латунный Болт всё равно постоянно ищут новые способы сделать свою машину ещё более скоростной, и Виззл сказал мне, что ему нужен очень редкий компонент для очередных экспериментов. Похоже, ему надо с этим помочь. Спросите его на этот счёт." },
    ["2769c"] = { male = "Так ты хочешь мне помочь? Отлично! Мне для эксперимента нужна одна штука, и отважный герой вроде тебя добудет её без труда!", female = "Так ты хочешь мне помочь? Отлично! Мне для эксперимента нужна одна штука, и отважная героиня вроде тебя добудет её без труда!" },
    ["2770a"] = { common = "В пустыне Танарис есть город троллей – Зул'Фаррак, в глубине которого находится священный бассейн. Из этого бассейна тролли призывают огромное чудовище, Газ'риллу! Злобная энергия пронизывает это чудовище насквозь, до самых кончиков его чешуи. И именно эту энергию я хочу использовать в своей машине! Принеси мне наэлектризованную чешую Газ'риллы. Но только помни, что тролли держат способ призывания этого монстра в тайне, и просто так они с ней не расстанутся." },
    ["2770c"] = { male = "Ого, да это же чешуя! Спасибо. Сейчас же начну работать с ней. Так значит, ты видел Газ'риллу? Эта тварь и правда такая большая, как про неё говорят?", female = "Ого, да это же чешуя! Спасибо. Сейчас же начну работать с ней. Так значит, ты видела Газ'риллу? Эта тварь и правда такая большая, как про неё говорят?" },
    ["2771a"] = { common = "Похоже, таков был замысел учителя. Меня он научил делать одни предметы, а тебя другие. Учитель мудр! Мы обучим друг друга! Научи меня делать мифриловые капюшоны и изысканные мифриловые наплечники, а я покажу тебе, как куётся изысканный мифриловый шлем." },
    ["2771c"] = { common = "Великолепно! Даже я говорю, что это отличный результат. Смотри и учись!" },
    ["2772a"] = { common = "На прошлогодних соревнованиях по кузнечному делу все зрители видели, как трусливый пёс из Торговой компании подставил мне подножку. Им и невдомёк, как я умудрился выиграть соревнования: правильно, благодаря изысканным мифриловым сапогам! На соревнованиях этого года мне понадобятся изысканные мифриловые штаны, потому что в конкурсе участвует крошшер Торговой компании! Научи меня делать штаны, а я научу тебя делать сапоги!" },
    ["2772c"] = { common = "Мир будет у твоих ног! Пусть все падут перед твоим величием!" },
    ["2773a"] = { common = "В этих краях меня зовут Мифриловым Парнем. Я продаю изысканный мифрил искателям приключений со всего света. *Трентон переходит на шёпот.* Им и невдомёк, что я не умею делать изысканные мифриловые перчатки. Ш-ш-ш! Пусть это останется между нами. Научи меня делать такие перчатки, а я взамен покажу тебе последнее, чему обучил меня Гальван: изысканную мифриловую кирасу." },
    ["2773c"] = { common = "Спасибо за науку. Скоро в твоих руках окажется король изысканного мифрилового доспеха. Смотри!!!" },
    ["2781a"] = { common = "РАЗЫСКИВАЕТСЯ: Калиф Жало Скорпида! Водная компания Прибамбасска предлагает награду за голову Калифа Жало Скорпида, главы Скитальцев Пустыни. Он обвиняется в: Один. Убийстве сотрудников Водной компании Прибамбасска! Два. Похищении ресурсов Водной компании Прибамбасска! Три. Захвате собственности Водной компании Прибамбасска! Принесите доказательство гибели Калифа Жало Скорпида главному инженеру Чепухастеру и получите награду!" },
    ["2781c"] = { male = "Наконец-то – правосудие свершилось! Ты нанёс суровый удар подлым кочевникам! Жало Скорпида мёртв, может быть, это отпугнёт этих надоед от колодцев Прибамбасска! От лица Водной компании Прибамбасска я вручаю тебе эту награду. Ты оказал нам большую услугу.", female = "Наконец-то – правосудие свершилось! Ты нанесла суровый удар подлым кочевникам! Жало Скорпида мёртв, может быть, это отпугнёт этих надоед от колодцев Прибамбасска! От лица Водной компании Прибамбасска я вручаю тебе эту награду. Ты оказала нам большую услугу." },
    ["2782a"] = { common = "Табличка покрыта письменами троллей из племени Сухокожих. Да, секрет Рин'джи и впрямь оказался очень загадочным. Возможно, эта табличка представляет собой немалую ценность, хотя может быть и с точностью до наоборот. Тролль из племени Сухокожих в беде мог пообещать что угодно, лишь бы его спасли..." },
    ["2782c"] = { common = "Хм, какая необычная табличка... Где вы её взяли?" },
    ["2783c"] = { common = "Альянс желает помочь? Я не думал, что этот день когда-либо наступит вновь. День, когда Альянс будет сражаться плечом к плечу с Ордой против общего врага. Да будет так… мы объединимся." },
    ["2784a"] = { male = "Выслушай мою историю, герой.", female = "Выслушай мою историю, героиня." },
    ["2784c"] = { common = "Будучи духом, я бессилен что-либо сделать. Помоги мне. Дай мне возможность снова обрести свою честь." },
    ["2801a"] = { common = "Прежде чем мы продолжим, тебе следует услышать мою историю." },
    ["2801c"] = { common = "Настало время действовать, путник." },
    ["2821a"] = { common = "У меня принцип простой: если что делаешь, делай как можно лучше – и никаких компромиссов! А тот, кто станет говорить, будто качество не имеет значения, того гляди, продаст тебе недвижимость в Дун Мороге с видом на море! И вот недавно в поисках качественных материалов я обнаружил толстые шкуры йети. Йети – это существа, которые водятся в Фераласе. Особенно много их в Долине Свирепого Утёса. За каждые десять шкур ты получишь одно из моих кожаных изделий. Ну что, по рукам?" },
    ["2821c"] = { common = "Ну что, видишь, каковы эти шкуры? Надо тебе сказать, что после специальной обработки они делаются прочнее железа! Немногие про это знают, а вот я, с помощью своих особых дубильных составов, смогу делать из них вещи несравненного качества! Ну да, и всё это – благодаря тебе. Пожалуйста, выбирай себе любое из моих готовых изделий." },
    ["2822a"] = { common = "Я горжусь своим мастерством. Мои вещи сразу видно! А тот, кто станет говорить, будто качество не имеет значения, пожалуй, захочет убедить тебя и в том, будто земля не хранит тайн! И вот недавно в поисках качественных материалов я обнаружил толстые шкуры йети. Йети – это существа, которые водятся в Фераласе. Особенно много их к западу отсюда, в Долине Свирепого Утёса. За каждые десять шкур ты получишь одно из моих кожаных изделий. Ну что, по рукам?" },
    ["2822c"] = { male = "О, отлично! Надо тебе сказать, что эти шкуры после специальной обработки делаются прочнее железа! Правда, подобрать состав для дубления не так-то просто, но всё равно, я уверен, что мои вещи, изготовленные из них, будут ещё лучше прежнего. Что до тебя, – ты воистину бесценный помощник! Пожалуйста, выбирай себе любое из моих готовых изделий.", female = "О, отлично! Надо тебе сказать, что эти шкуры после специальной обработки делаются прочнее железа! Правда, подобрать состав для дубления не так-то просто, но всё равно, я уверен, что мои вещи, изготовленные из них, будут ещё лучше прежнего. Что до тебя, – ты воистину бесценная помощница! Пожалуйста, выбирай себе любое из моих готовых изделий." },
    ["2841a"] = { common = "О-о, гномьи технологии! Ещё пару лет назад они использовались в основном в анекдотах. Да уж, времена изменились! Теперь они выстроили такую машину, которая лучше, чем все наши резаки вместе взятые! Мне нужны её чертежи! Увы, эти бумаги хранятся в сейфе Мекжинера Термоштепселя. А хуже всего, что код от сейфа известен только самому Мекжинеру Термоштепселю! Делай что хочешь, но добудь этот код, открой сейф и достань оттуда эти чертежи!" },
    ["2841c"] = { common = "Да, я знал, что у тебя всё получится! А вот Совик всё сомневался… *Ногг прочищает горло.* Ну, теперь, когда чертежи у нас в руках, разобраться в этих гномьих нововведениях – всего лишь вопрос времени. Эти изобретения очень пригодятся нам, гоблинам, для новых моделей резаков!" },
    ["2842a"] = { common = "Как только Керноби сообщил нам о новой гномьей машине, мы со Скути принялись строить \"Транстелепорт-шесть тысяч\" – лучший способ добраться до Гномрегана. Он уже готов. Если хочешь его испытать, ступай в Пиратскую бухту и поговори со Скути у Гнезда Крыльев Ветра. Из Кабестана туда можно добраться на лодке. Нет, разумеется, ты можешь попробовать добраться до Гномрегана через горы Дун Морог, кишащие дворфами!" },
    ["2842c"] = { common = "Ну, разве она не красавица? Вершина гоблинских транспортных технологий! И десяти раз не взрывалась! Ты не бойся. Больше она не взорвётся, я там всё отладил. Ну, а если тебе не повезёт, ты хотя бы умрёшь быстро и безболезненно!" },
    ["2843a"] = { common = "Пока импульсный повторитель у тебя с собой, стоит только ступить на площадку, и перенесёшься в Гномреган. Может быть, ощущения будут необычные, но ни одно из них не останется навсегда... Теперь. Чуть не забыл самое главное – как вернуться назад. Когда ты решишь уносить ноги, поднимись на площадку транстелепорта в Гномрегане! А теперь я настрою импульсный повторитель на твой рост и вес." },
    ["2843c"] = { common = "Готово! Когда соберёшься с духом, просто ступи на площадку." },
    ["2844a"] = { common = "Нет от меня никакого толку! Я должен был стеречь мою маленькую подружку, Шай, а она взяла и убежала! Я даже не знаю, как это вышло: в последний раз, как я её видел, мы шли через развалины к северу отсюда. Всё было хорошо, а потом я поворачиваюсь, а её нет! И теперь я даже и не знаю, чего мне делать-то. Что мне делать? Я так переживаю! Слушай, а может, ты сходишь её поищешь? У тебя-то ноги куда резвее моих!" },
    ["2844c"] = { male = "Ой, как хорошо, что ты меня нашёл! По правде говоря, я немножко заблудилась... Но тут очень красиво, правда?", female = "Ой, как хорошо, что ты меня нашла! По правде говоря, я немножко заблудилась... Но тут очень красиво, правда?" },
    ["2845a"] = { common = "Не поможешь ли ты мне отыскать моего друга, Камнедробителя? Он должен был следить за мной... Но со мной иногда случается, что я ухожу, куда глаза глядят. Вокруг столько интересного, я увлекаюсь, забываю обо всём на свете, и… Но есть одна вещь, которая обязательно привлекает моё внимание. В этом сундучке хранится колокольчик. Он мне очень дорог. Мне ужасно нравится его звон. Так что, если я вдруг куда-нибудь уйду, позвони в колокольчик, и я тотчас прибегу обратно!" },
    ["2845c"] = { common = "Шо? Так говоришь, этот колокольчик помогает найти Шай, когда она убежала? Вот это да! Ну, раз я стольким тебе обязан, на, держи!" },
    ["2846a"] = { common = "Давным-давно у меня была, прекрасная драгоценность, Тиара Глубин. Это была не просто красивая безделушка, она была наделена великой силой, предназначенной для тех, кто умел с ней обращаться. Когда слух о моей тиаре достиг ушей гидроманта Велраты, она решила заполучить её и послала своих подручных выкрасть её у меня! Я хочу вернуть то, что принадлежит мне. Отправляйтесь в Зул'Фаррак, город троллей в пустыне Танарис, найдите там Велрату и заберите у неё мою тиару. Возвращайтесь ко мне и заслужите мою вечную благодарность." },
    ["2846c"] = { male = "Чудно! Ты нашёл её! И, что её важнее, Велрата её лишилась! Благодарю тебя. И... Если я прежде высказывалась несколько резко, не бери в голову. К тем, кто не пытается меня обокрасть, я отношусь гораздо дружелюбнее.", female = "Чудно! Ты нашла её! И, что её важнее, Велрата её лишилась! Благодарю тебя. И... Если я прежде высказывалась несколько резко, не бери в голову. К тем, кто не пытается меня обокрасть, я отношусь гораздо дружелюбнее." },
    ["2847a"] = { male = "Ты уже опытный кожевник. Я владею искусством изготовления того, что весьма пригодилось бы и тебе. Это дикарские кожаные доспехи. В них используются загадочная и непостоянная сила дикого винограда, который можно отыскать в густых зарослях или получить от некоторых существ. Другого подобного доспеха мастер твоего уровня изготовить не в силах. Я научу тебя делать эти доспехи, но для этого тебе придётся потрудиться. Для начала мне нужно просто десять кусков плотной кожи. Принеси её, потом обсудим дальнейшее.", female = "Ты уже опытная кожевница. Я владею искусством изготовления того, что весьма пригодилось бы и тебе. Это дикарские кожаные доспехи. В них используются загадочная и непостоянная сила дикого винограда, который можно отыскать в густых зарослях или получить от некоторых существ. Другого подобного доспеха мастер твоего уровня изготовить не в силах. Я научу тебя делать эти доспехи, но для этого тебе придётся потрудиться. Для начала мне нужно просто десять кусков плотной кожи. Принеси её, потом обсудим дальнейшее." },
    ["2847c"] = { common = "Ну, я рад, что ты уже с нами, так сказать, на борту. Ты получишь начальные знания в создании дикарских кожаных доспехов и, как я говорил, практически даром. За работу же!" },
    ["2848a"] = { common = "Дикарские кожаные наплечники обеспечивают превосходную защиту как плеч, так и верхней части руки. Как и все дикарские кожаные доспехи, они прошиты диким виноградом, что придаёт им мощные, но непостоянные магические свойства. Для изготовления изделия по этой выкройке мне потребуется шесть наборов для усиления брони из толстой кожи и дикий виноград. Для тебя это не слишком сложное задание..." },
    ["2848c"] = { male = "Да, это хорошие, надёжные наборы для усиления брони. Если я чего требую не только от себя, но и от своих подмастерьев, так это высокого качества! Ты неплохо потрудился, и заслуживаешь того, чтобы получить эту выкройку. Надеюсь, она позволит тебе добиться не меньшего уважения, чем мне.", female = "Да, это хорошие, надёжные наборы для усиления брони. Если я чего требую не только от себя, но и от своих подмастерьев, так это высокого качества! Ты неплохо потрудилась, и заслуживаешь того, чтобы получить эту выкройку. Надеюсь, она позволит тебе добиться не меньшего уважения, чем мне." },
    ["2849a"] = { common = "Дикарский кожаный жилет – основа любых дикарских кожаных доспехов. Основа жилета переплетена диким виноградом, что даёт максимальную защиту торса и позволяет использовать мощную магию растения. Для изготовления изделия по этой выкройке мне потребуется две черепашьих чешуйчатых кирасы, две пары черепашьих чешуйчатых перчаток и дикий виноград. Изготовить это непросто, но, думаю, ты справишься." },
    ["2849c"] = { common = "Да, неплохие вещицы! За одно умение и старание, вложенное в них, можно получить несколько лишних серебряных монет. Ну что, мой приказ выполнен, вот и твоя награда. Теперь ты умеешь изготовлять дикарские кожаные жилеты!" },
    ["2850a"] = { common = "Дикарский кожаный шлем обеспечивает лучшую защиту головы, при этом не менее удобен, чем обычные шлемы. Как и во всех дикарских кожаных доспехах, в основу шлема вплетён дикий виноград, наделяющий его мощными, но непостоянными магическими свойствами. Тем, кто ходит в кожаных доспехах, эта вещица наверняка пригодится! Но для изготовления изделия по этой выкройке мне понадобятся два ночных мундира, два ночных головных повязки и дикий виноград. Принеси это всё, и выкройка твоя!" },
    ["2850c"] = { male = "Да, это Ночное снаряжение – именно то, что я просил тебя принести. Впрочем, от кожевника твоего уровня я другого и не ждал. Ты достоин уметь изготовлять дикарские кожаные шлемы. Вот тебе выкройка. Надеюсь, ты применишь её с пользой.", female = "Да, это Ночное снаряжение – именно то, что я просил тебя принести. Впрочем, от кожевника твоего уровня я другого и не ждал. Ты достойна уметь изготовлять дикарские кожаные шлемы. Вот тебе выкройка. Надеюсь, ты применишь её с пользой." },
    ["2851a"] = { common = "Тебе известно уже немало. Однако многое ещё остаётся постичь. Теперь ты узнаешь о дикарских кожаных сапогах – ведь без обуви не обходится ни один доспех. Ноге в них удобно и приятно, и дальний путь в них не так тяжёл. Мягкая же подошва позволяет при необходимости ступать беззвучно. Для их изготовления по выкройке мне потребуются две пары ночных штанов и две пары ночных сапог. И два экземпляра дикого винограда – запомни, два, а не один! Добудешь всё это – дай мне знать." },
    ["2851c"] = { male = "Итак, ты выполнил комплексный заказ и как всегда сделал это профессионально. Так что получи эту выкройку и мою благодарность!", female = "Итак, ты выполнила комплексный заказ и как всегда сделала это профессионально. Так что получи эту выкройку и мою благодарность!" },
    ["2852a"] = { common = "Ну, теперь, когда с простыми предметами покончено, мы можем перейти к более сложным вещам. Дикарские кожаные поножи – одна из наиболее прочных и надёжных разновидностей кожаного доспеха. Они отлично защищают и живот, и ноги, и прочие важные части тела. А поскольку в них вшит ещё и дикий виноград, дающий дополнительную защиту, любой искатель приключений скажет тебе спасибо за такие поножи. Для изготовления изделия по этой выкройке мне понадобятся два шлема из черепашьего панциря, две пары черепашьих чешуйчатых наручей, и два экземпляра дикого винограда." },
    ["2852c"] = { male = "Хм. Ты опять выполнил приказ. Возможно, в один прекрасный день я приду к тебе за знаниями, а? Вот выкройка поножей, вместе с моими благодарностями.", female = "Хм. Ты опять выполнила приказ. Возможно, в один прекрасный день я приду к тебе за знаниями, а? Вот выкройка поножей, вместе с моими благодарностями." },
    ["2853a"] = { male = "Что ж, ты – образец прилежания. Остался только один предмет из дикарских кожаных доспехов, который ты не умеешь изготовлять. Я не стану заставлять тебя трудиться, чтобы её получить: ты и так сполна расплатился за всё. Однако же сам я тебе его дать не могу. Ты получишь награду от моего наставника, того, кто посвятил в тайны нашего ремесла меня самого. Отнеси эту записку Телонису. Он обучает кожевников в Дарнассе. Покажи ему записку, и пусть он приветствует тебя как равного, подобно мне самому.", female = "Что ж, ты – образец прилежания. Остался только один предмет из дикарских кожаных доспехов, который ты не умеешь изготовлять. Я не стану заставлять тебя трудиться, чтобы её получить: ты и так сполна расплатилась за всё. Однако же сам я тебе его дать не могу. Ты получишь награду от моего наставника, того, кто посвятил в тайны нашего ремесла меня самого. Отнеси эту записку Телонису. Он обучает кожевников в Дарнассе. Покажи ему записку, и пусть он приветствует тебя как равную, подобно мне самому." },
    ["2853c"] = { common = "А, ты от Пратта! Он, конечно, человек, но временами напоминает мне нас, ночных эльфов. Он действительно гениальный кожевенник! И если он тебя так расхваливает, это говорит в твою пользу. Насколько я понимаю, он обучил тебя секретам дикарских кожаных доспехов? Позволь же, я завершу твоё обучение, дав тебе вот эту выкройку. Пользуйся ею с умом: немного на свете тех, кто владеет тайной изготовления дикарских кожаных плащей!" },
    ["2854a"] = { male = "Ты уже опытный кожевник. Я владею искусством изготовления того, что весьма пригодилось бы и тебе. Это дикарские кожаные доспехи. В них используется загадочная и непостоянная сила дикого винограда, который можно отыскать в густых зарослях или получить от некоторых существ. Другого подобного доспеха мастер твоего уровня изготовить не в силах. Я научу тебя делать эти доспехи, но для этого тебе придётся потрудиться. Для начала мне нужно просто десять кусков плотной кожи. Принеси её, потом обсудим дальнейшее.", female = "Ты уже опытная кожевница. Я владею искусством изготовления того, что весьма пригодилось бы и тебе. Это дикарские кожаные доспехи. В них используется загадочная и непостоянная сила дикого винограда, который можно отыскать в густых зарослях или получить от некоторых существ. Другого подобного доспеха мастер твоего уровня изготовить не в силах. Я научу тебя делать эти доспехи, но для этого тебе придётся потрудиться. Для начала мне нужно просто десять кусков плотной кожи. Принеси её, потом обсудим дальнейшее." },
    ["2854c"] = { male = "Ну что ж, я рад, что ты теперь мой ученик. Ты поступил разумно, избрав ремесло кожевника: когда ты научишься изготовлять дикарские кожаные доспехи, у тебя отбою не будет от тех, кто одевается в кожу. Ну, за работу! С чего мы начнём?", female = "Ну что ж, я рад, что ты теперь моя ученица. Ты поступила разумно, избрав ремесло кожевника: когда ты научишься изготовлять дикарские кожаные доспехи, у тебя отбою не будет от тех, кто одевается в кожу. Ну, за работу! С чего мы начнём?" },
    ["2855a"] = { common = "Дикарские кожаные наплечники обеспечивают превосходную защиту как плеч, так и верхней части руки. Как и все дикарские кожаные доспехи, они прошиты диким виноградом, что придаёт им мощные, но непостоянные магические свойства. Для изготовления изделия по этой выкройке мне потребуется шесть наборов для усиления брони из толстой кожи и дикий виноград. Для тебя это не слишком сложное задание..." },
    ["2855c"] = { male = "Да, это хорошие, надёжные доспехи. Если я чего требую не только от себя, но и от своих учеников, так это высокого качества! Ты неплохо потрудился, и заслуживаешь того, чтобы получить эту выкройку. Надеюсь, она позволит тебе добиться не меньшего уважения, чем мне.", female = "Да, это хорошие, надёжные доспехи. Если я чего требую не только от себя, но и от своих учеников, так это высокого качества! Ты неплохо потрудилась, и заслуживаешь того, чтобы получить эту выкройку. Надеюсь, она позволит тебе добиться не меньшего уважения, чем мне." },
    ["2856a"] = { common = "Дикарский кожаный жилет – основа любых дикарских кожаных доспехов. Основа жилета переплетена диким виноградом, что даёт максимальную защиту торса и позволяет использовать мощную магию растения. Для изготовления предмета по этой выкройке мне потребуется две черепашьих чешуйчатых кирасы, две пары черепашьих чешуйчатых перчаток и дикий виноград. Изготовить это непросто, но, думаю, ты справишься." },
    ["2856c"] = { common = "Да, неплохие вещицы! Судя по умению и старанию, с какими они изготовлены, ты всерьёз относишься к своему ремеслу. Ну что, мой приказ выполнен, вот и твоя награда. Теперь ты умеешь изготовлять дикарские кожаные жилеты!" },
    ["2857a"] = { common = "Дикарский кожаный шлем обеспечивает лучшую защиту головы, при этом не менее удобен, чем обычные шлемы. Как и во всех дикарских кожаных доспехах, в основу шлема вплетён дикий виноград, наделяющий его мощными, но непостоянными магическими свойствами. Тем, кто ходит в кожаных доспехах, эта вещица наверняка пригодится! Но для изготовления изделия по этой выкройке мне понадобятся два ночных мундира, два ночных головных повязки и дикий виноград. Принеси это всё, и выкройка твоя!" },
    ["2857c"] = { male = "Да, это Ночное снаряжение – именно то, что я просил тебя принести. Впрочем, от кожевника твоего уровня я другого и не ждал. Ты достоин того, чтобы изготовлять дикарские кожаные шлемы. Вот тебе выкройка. Надеюсь, ты применишь её с пользой.", female = "Да, это Ночное снаряжение – именно то, что я просил тебя принести. Впрочем, от кожевника твоего уровня я другого и не ждал. Ты достойна того, чтобы изготовлять дикарские кожаные шлемы. Вот тебе выкройка. Надеюсь, ты применишь её с пользой." },
    ["2858a"] = { common = "Тебе известно уже немало. Однако многое ещё остаётся постичь. Теперь ты узнаешь о дикарских кожаных сапогах – ведь без обуви не обходится ни один доспех. Ноге в них удобно и приятно, и дальний путь в них не так тяжёл. Мягкая же подошва позволяет при необходимости ступать беззвучно. Для изготовления их по выкройке мне потребуются две пары ночных штанов и две пары ночных сапог. И два экземпляра дикого винограда – запомни, два, а не один! Добудешь всё это – продолжим." },
    ["2858c"] = { male = "И снова ты выполняешь непростой заказ с искусством опытного профессионала! Ты заслужил эту выкройку, равно как и мою благодарность.", female = "И снова ты выполняешь непростой заказ с искусством опытного профессионала! Ты заслужила эту выкройку, равно как и мою благодарность." },
    ["2859a"] = { common = "Ну, теперь мы можем перейти к более сложным вещам. Дикарские кожаные поножи – одна из наиболее прочных и надёжных разновидностей кожаного доспеха. Они отлично защищают ноги. А поскольку в них вшит ещё и дикий виноград, дающий дополнительную защиту, любой искатель приключений скажет тебе спасибо за такие поножи. Для изготовления изделия по этой выкройке мне понадобятся два шлема из черепашьего панциря, две пары черепашьих чешуйчатых наручей, и два экземпляра дикого винограда." },
    ["2859c"] = { common = "Ну что, мой приказ снова выполнен отлично. Может, в один прекрасный день уже я явлюсь к тебе, как ученик к учителю, а? Вот выкройка поножей, а с ней и моя благодарность. Пусти полученные знания в дело, и пусть твои изделия будут достойны твоих способностей!" },
    ["2860a"] = { male = "Что ж, теперь ты знаешь всё, чему я мог тебя научить. Однако остался ещё один предмет из дикарских кожаных доспехов, выкройки которого у тебя нет. Я не стану заставлять тебя трудиться, чтобы её получить: ты и так сполна расплатился за всё. Однако же отдать тебе его сам я не могу. Ты получишь награду от моей наставницы, той, которая посвятила в тайны нашего ремесла меня самого. Отнеси эту записку Уне. Она обучает кожевников в Громовом Утёсе. Покажи ей записку, и пусть она приветствует тебя как равного, подобно мне самому.", female = "Что ж, теперь ты знаешь всё, чему я мог тебя научить. Однако остался ещё один предмет из дикарских кожаных доспехов, выкройки которого у тебя нет. Я не стану заставлять тебя трудиться, чтобы её получить: ты и так сполна расплатилась за всё. Однако же отдать тебе его сам я не могу. Ты получишь награду от моей наставницы, той, которая посвятила в тайны нашего ремесла меня самого. Отнеси эту записку Уне. Она обучает кожевников в Громовом Утёсе. Покажи ей записку, и пусть она приветствует тебя как равную, подобно мне самому." },
    ["2860c"] = { common = "А, ты от Джангора! Приятно видеть, что у одного из моих лучших учеников теперь свои ученики… Джангор – очень талантливый и добросовестный кожевенник. И если он тебя так расхваливает, это говорит в твою пользу. Насколько я понимаю, он обучил тебя секретам дикарских кожаных доспехов? Позволь же, я завершу твоё обучение, дав тебе вот эту выкройку. Пользуйся ею с умом: немного на свете тех, кто владеет тайной изготовления дикарских кожаных плащей!" },
    ["2861a"] = { common = "Ходят слухи, что у Табеты, мага, живущего в Пылевых топях, серьёзный зуб на одну песчаную троллиху из Зул'Фаррака. Если ты поговоришь с Табетой, она, конечно, расскажет тебя больше. И захвати с собой друзей. Если она пошлёт тебя в Зул'Фаррак, а, скорее всего, так и будет, то лучше тебе там в одиночку не появляться. Ты найдёшь дом Табеты к западу от Терамора и к северу от руин Каменного Молота." },
    ["2861c"] = { common = "Да. Верно. У меня большой зуб на эту троллиху. И не один. Хочешь помочь мне?" },
    ["2862a"] = { common = "О, эти гноллы... Сказать, что они отравляют нам жизнь – значит ничего не сказать! Мы здесь постоянно живём под угрозой нападения! Я не знаю, всегда ли они жили в Фераласе, или пришли сюда откуда-то ещё, но если мы не будем противостоять им достаточно решительно, нам здесь не жить. А в последнее время гноллы совершенно озверели! Нам необходима твоя помощь, чтобы сократить их численность. Принеси мне десяток их грив, и я щедро вознагражу тебя за труды. Ступай!" },
    ["2862c"] = { common = "Неплохое начало! Таких воинов, как ты, ещё поискать! Я ведь давал такое задание не только тебе. И до тебя немало бойцов сражались с гноллами, и в былые времена наших усилий хватало, чтобы заставить их отступить. Однако в последнее время они упорно прут на север, в наши земли. Гноллы бьются так отчаянно... как будто им некуда отступать! Однако у меня есть один план. Возможно, он позволит раз и навсегда покончить с этой войной..." },
    ["2863a"] = { common = "План состоит в том, чтобы одним махом истребить всех предводителей гноллов. Если нам удастся это сделать, в рядах гноллов воцарится хаос. А возможно, до этих блохастых тварей даже дойдёт, что с нами лучше не связываться! Тебе, я поручаю истребить пятерых вожаков гноллов. Только сделать это нужно в течение часа, иначе весь план пойдёт насмарку!" },
    ["2863c"] = { male = "Тебе удалось выполнить мою просьбу. Молодец! Вот, прими эту небольшую награду за свои труды. Теперь, когда число гноллов сократилось, и их вожаки перебиты, эти твари дважды подумают, прежде чем решатся снова напасть на лагерь! Однако проблемы это не решает... Гноллы не могли так озвереть безо всякой причины! И я хочу выяснить, в чём дело, прежде, чем они пришли в себя.", female = "Тебе удалось выполнить мою просьбу. Умница! Вот, прими эту небольшую награду за свои труды. Теперь, когда число гноллов сократилось, и их вожаки перебиты, эти твари дважды подумают, прежде чем решатся снова напасть на лагерь! Однако проблемы это не решает... Гноллы не могли так озвереть безо всякой причины! И я хочу выяснить, в чём дело, прежде, чем они пришли в себя." },
    ["2864a"] = { common = "У моего кузена Тран'река сейчас большие проблемы. Он обещал мне, партию панцирей скарабея, ещё неделю назад, но так и не поставил. Он – мой кузен, так что не хотел бы я посылать кого-то в Прибамбасск, выколачивать из него свои деньги или груз. Можешь поговорить с ним для меня? Скажите ему, что он должен мне эту поставку ну или придётся отвечать как всем остальным... Прибамбасск находится на севере пустыни Танарис в Калимдоре." },
    ["2864c"] = { male = "Привет! Так ты общался с моим кузеном Кразеком? Ну и как он там? Надеюсь, что в Бухте контрабандистов к нему хорошо относятся… Панцири скарабея, говоришь? Дай мне рассказать тебе одну историю.", female = "Привет! Так ты общалась с моим кузеном Кразеком? Ну и как он там? Надеюсь, что в Бухте контрабандистов к нему хорошо относятся… Панцири скарабея, говоришь? Дай мне рассказать тебе одну историю." },
    ["2865a"] = { common = "У скарабеев Танариса очень твёрдый панцирь, достаточно твёрдый, чтобы использовать их как строительный материал много для чего. Очень много! Эти панцири, настолько полезная вещь, что ради них скарабеев извели практически под корень. Я знаю, где они ещё водятся, и я поделюсь с тобой, если ты пообещаешь принести мне их панцири, обещаешь? Так вот. Колония скарабеев находится в Зул'Фарраке. Видимо до троллей ещё не дошло, насколько полезны их панцири. Так что все твои! Отправляйся в Зул'Фаррак и принеси мне целых панцирей скарабеев." },
    ["2865c"] = { male = "Урра! Ты достал их! Спасибо, ты мне просто жизнь спас!", female = "Урра! Ты достала их! Спасибо, ты мне просто жизнь спасла!" },
    ["2866a"] = { common = "К югу от нас находятся руины Соларсаля. Это развалины очень древнего города. Мы уже обследовали руины, но пока не нашли там ничего примечательного и оставили их в покое. Однако не так давно в этих развалинах поселились наги из клана Гребня Ненависти, причём в угрожающих количествах. Поначалу мы решили, что они готовят нападение. Возможно, они его действительно готовят, но нам кажется, что там происходит что-то ещё. Ступай туда, осмотри развалины и обрати внимание на всё, что покажется подозрительным. Удачи!" },
    ["2866c"] = { common = "Внимательно изучив беседку, вы обнаруживаете следующее. Во-первых, беседка явно новая, и не похожа на окружающие руины. Во-вторых, столбы беседки исписаны мелкими значками. Значки повторяются, но что это за письмена и что они означают, вам непонятно. Ну и, в-третьих, камень беседки – тёплый на ощупь. Да, всё это, несомненно, подозрительно!" },
    ["2867a"] = { common = "Теперь, когда вы обнаружили странную беседку в глубине руин Соларсаля, настало время вернуться в Крепость Оперённой Луны и доложить генералу Шандрисе Оперённой Луне о своём открытии." },
    ["2867c"] = { common = "С возвращением! Обнаруженная тобой беседка действительно весьма... подозрительна. Очевидно, что даже если наги и не замышляют нападения, их присутствие не сулит нам ничего хорошего. Ну, как бы то ни было, вот твоя заслуженная награда. Судя по всему, Крепость Оперённой Луны отчаянно нуждается в помощи для борьбы с нагами из клана Гребня Ненависти. Я бы хотела дать тебе ещё одно поручение, если ты не против..." },
    ["2869a"] = { common = "На данный момент самое разумное – рассчитывать на то, что наги в любом случае попытаются захватить остров. И нам нужно предотвратить эту угрозу, пока не стало поздно. Принеси мне десять штук чешуи Гребня Ненависти. Как их добыть – думаю, ясно? У тебя будет случай поохотиться на наг, и количество их воинов на острове Сардор уменьшится. И то, и другое нам на пользу!" },
    ["2869c"] = { common = "Да-да, эта чешуя вполне годится. Думаю, мы отправим её Пратту. Может быть, он сумеет изготовить из неё что-нибудь полезное. А для тебя у меня есть ещё одно задание. Но сначала вот твоя награда за труды. Твоя служба генералу и всей Крепости Оперённой Луны очень ценна перед лицом грозящей нам опасности." },
    ["2870a"] = { common = "Мы получили новые донесения разведчиков, и теперь неплохо представляем себе, как устроено войско наг. Высшее командование состоит из особ королевской крови. Именно они-то всем и заправляют. Нам стало известно имя одного из самых жестоких нагов, лорда Шалзару. Разведка докладывает, что во время недавних раскопок, которые наги проводили в пещере к югу от основных руин на острове Ужаса, он лично обнаружил некую загадочную реликвию. Его необходимо остановить. Убей его, и принеси мне этот предмет, чтобы мы могли его изучить." },
    ["2870c"] = { common = "Отлично! Гибель лорда Шалзару повергнет наг в смятение – надолго, если не навсегда. Так что теперь они представляют значительно меньшую угрозу, чем прежде, и всё это – благодаря тебе! Вот тебе новая награда из сокровищницы замка. Эта награда заслужена тобой – вся, вплоть до последней монеты! Добро пожаловать в Крепость Оперённой Луны в любое время, друг мой. Да, и прежде, чем ты уйдёшь... ещё одна просьба..." },
    ["2871a"] = { common = "Не возьмёшься ли ты доставить эту реликвию моей жене Вестии? Я был бы тебе очень признателен. Она не только почтенная жрица, но и одна из наиболее сведущих учёных. Я лично не пойму, что это за штука, хоть меня озолоти. Но уж если моя жена в ней не разберётся, значит, не разберётся никто. Она вон там, неподалёку. Занимается, небось. Спасибо!" },
    ["2871c"] = { common = "Интересно... Так говоришь, это вещь из руин Соларсаля? Ну да, Латро прав: мне следовало на это взглянуть... Такое впечатление, что эта вещь – не оттуда. С другой стороны, на работу наг это тоже не похоже. Далеко не столь чуждое… Мне потребуется некоторое время на то, чтобы с ней разобраться. А когда я завершу свои исследования, возможно, ты мне снова пригодишься – если ты, конечно, окажешься в это время поблизости. На, возьми это – у нас таких вещиц много, а тебе она, думаю, пригодится!" },
    ["2872a"] = { common = "Мой давний приятель Столи должен мне особую бутылку рома. Он держит бар в Порту Картеля в Танарисе, и клялся, что ром у него крепче, чем во всей Пиратской бухте. Он даже заявил, что удвоит свой долг мне, если я попробую его напиток и не соглашусь с ним! Думаю, он потом пожалел о своих словах, потому и не шлёт мне ром. Но я ничего не забываю, поэтому поговори с ним вместо меня..." },
    ["2872c"] = { male = "А, ты уже поговорил с МакКинли! Он ошибается! Я вовсе не боюсь угостить его Картельским ромом… Просто рома у меня нет!", female = "А, ты уже поговорила с МакКинли! Он ошибается! Я вовсе не боюсь угостить его Картельским ромом… Просто рома у меня нет!" },
    ["2873a"] = { common = "Я должен старине МакКинли из Пиратской бухты немного рома. Проблема в том, что ром у меня закончился! Капитан Куэрго украл последнюю партию и прячет в стенах огороженного пиратского поселения на юге. Если ты отыщешь мою партию рома, я смогу доказать МакКинли, что калимдорская выпивка в сто раз лучше пойла из Пиратской бухты!" },
    ["2873c"] = { common = "Здорово, спасибо за помощь! Теперь я наконец-то выиграю пари у МакКинли." },
    ["2874a"] = { common = "Ещё раз спасибо за помощь. Вот тебе бутылка Картельского рома. Отнеси её МакКинли, пора развеять его заблуждения относительно рома из Пиратской бухты." },
    ["2874c"] = { common = "Попробуем… Прямо не верится! Ужасный напиток! Потрясающий! Пожалуй, придётся простить Столи долг. Он не обманул меня насчёт Картельского рома. Эта штука густая как соус и жжёт как лава!" },
    ["2875a"] = { common = "Злобный пират Андре Огнебородый разыскивается за преступления против Картеля Хитрая Шестерёнка и Прибамбасска. Согласно указу правящего совета, все лица, прочитавшие данный документ, уполномочены применять любые меры при задержании Андре и его пособников. Согласно следующему указу, если Андре скончается или по иным причинам не сможет предстать перед судом, его может представлять его голова. Предоставление упомянутой головы начальнику отдела безопасности Чепухастеру повлечёт за собой заключение весьма выгодного и ответственного контракта." },
    ["2875c"] = { common = "А, голова Андре. Значит, суд над ним всё-таки состоялся! Большое спасибо. А теперь распишись тут, и я займусь оплатой твоих услуг. И не беспокойся из-за надписи мелким шрифтом. Ничего страшного там нет, и... Не думаю, что найдётся такое маленькое увеличительное стекло, всё равно её не прочитаешь." },
    ["2876a"] = { common = "В свитке приводится список рейсов между Портом Картеля и Пиратской бухтой. Там перечислены все прошлые и будущие грузы с указанием названий кораблей, везущих их. Напротив некоторых стоит большой крестик, напротив других заметки \"ОТЛИЧНАЯ ДОБЫЧА\" и \"СИЛЬНАЯ ОХРАНА\". Кое-кто из Порта Картеля очень заинтересуется этим документом." },
    ["2876c"] = { male = "Ох, похоже это список рейсов, причём здесь указаны дни и часы отбытия и прибытия! Если эти сведения попали в руки капитана пиратского корабля, у нас будут большие неприятности! Ты их у пирата нашёл? Дурные вести… Спасибо. Я рад, что ты нашёл этот документ и отправил пирата кормить рыб!", female = "Ох, похоже это список рейсов, причём здесь указаны дни и часы отбытия и прибытия! Если эти сведения попали в руки капитана пиратского корабля, у нас будут большие неприятности! Ты их у пирата нашла? Дурные вести… Спасибо. Я рад, что ты нашла этот документ и отправила пирата кормить рыб!" },
    ["2877a"] = { common = "Мы, клан Громового Молота, помним прошлое куда лучше, чем наши собраться из Стальгорна. Если вы хотите, чтобы к вам тут хорошо относились, то не должны бояться грязной работы! Орда забросила одну из своих баз во Внутренних землях, она находится на Осклизлой скале. Сейчас эту базу заполонили слизнюки и пиявки, у нас были на неё планы, но пока там кишат эти твари, мы не можем занять эту позицию. Вот вам, собственно, и работка! Отправляйтесь туда и убейте по десять зелёных слякочей и нефритовых слизнюков, а потом доложите мне, как всё прошло. Бегом!" },
    ["2877c"] = { common = "Нет, подумать только, как вы здорово помогли Громовому Молоту! Вы отлично работаете, а мы это ценим. Ваша маленькая зачистка куда важнее, чем может показаться на первый взгляд. Осталось ещё истребить слизнюков и пиявок, и тогда мы сможем распространить своё влияние ещё дальше. Новые друзья на Заоблочном Пике – это, конечно, хорошо, но, как говорится, не дружбой единой, так что вот вам ещё кое-что, вдобавок." },
    ["2879a"] = { common = "Это, должно быть, посох Равноденствия! Этот посох, на самом деле, является ключом, которым некогда отмыкали Монолит Равноденствия в Руинах Яростного Ветра, на материке к западу от Сонных Ветвей. Отыщите четыре огня, которые всё ещё пылают среди руин: Самха, Имбел, Бильтан и Лахасса. Добудьте их суть, встаньте перед Монолитом и зарядите посох их силой. Если это действительно посох Равноденствия, вы сумеете отпереть Монолит и достать из него священный артефакт." },
    ["2879c"] = { common = "Заряженный посох буквально вырывается из рук. Невероятная мощь отдаётся дрожью во всём теле. Вы касаетесь холодной поверхности Монолита… Отворяется небольшая дверка, за ней виднеется артефакт. Всё пространство вокруг Монолита Равноденствия озаряется светом." },
    ["2880a"] = { common = "Я скажу прямо – мы НЕ принадлежим к Альянсу! Клан Громового Молота – это независимая организация, и мы относимся хорошо только к тем, кто заслужил это своими делами, а не пустой высокопарной болтовнёй! Если вы хотите, чтобы вас тут уважали, – докажите, что вы достойны! В холмах Внутренних земель поселились мерзкие тролли, которые иногда носят племенные ожерелья. Принесите мне пять таких ожерелий, и тогда я, возможно, поверю, что с вами можно иметь дело." },
    ["2880c"] = { common = "Вот, о чём я и говорил! Эти ожерелья доказывают, что вы не боитесь чёрной работы, а клан Громового Молота это ценит. Продолжайте в том же духе, и заслужите наше уважение." },
    ["2882a"] = { common = "На карте изображена южная часть берега, а ниже имеется элегантная подпись… Южней Шестерёнки, На юге от дома Найдёшь ты флаг, мачту и кости – знакомо? Копай прямо там, если смелости хватит – За всё тебе злато Куэрго отплатит. Поищешь ты ключ и конечно найдёшь, Но прежде немало крови прольёшь." },
    ["2882c"] = { common = "Вас ждут скрытые сокровища капитана Куэрго!" },
    ["2902a"] = { common = "Гноллы, конечно, умом не блещут, но в последнее время в их деятельности прослеживаются признаки тщательного планирования. Если бы удалось добыть эти планы, возможно, нам было бы проще понять, отчего они так зашевелились в последнее время. Прошу тебя, вернись в лагеря Древолапов и попытайся найти что-нибудь похожее на боевые планы. Наверняка у них есть что-то в этом духе: в последнее время они действуют чересчур согласованно. Отыщи эти планы, и возвращайся ко мне." },
    ["2902c"] = { common = "Да, это те самые планы, которые просил отыскать Хадокен Быстрый Странник. Множество стрелок, очевидно, обозначают передвижения войск, однако большая часть этих стрелок направлена не на север, к Лагерю Мохаче, а на юг. В углу карты нарисовано нечто вроде крупного насекомого, окружённого разнообразными значками. Судя по всему, гноллов действительно донимают какие-то насекомые..." },
    ["2903a"] = { common = "Теперь, когда планы гноллов добыты, вам остаётся только вернуться с ними в Лагерь Мохаче к Хадокену Быстрому Страннику. Быть может, он или ещё кто-нибудь сумеет разобраться, что замышляют гноллы?" },
    ["2903c"] = { common = "О, это именно то, что нам нужно! Я, правда, не мастак разбирать всякие каракули, однако я на своём веку повидал достаточно планов битв, чтобы понять, что творится у гноллов. Похоже, сейчас они ведут войну на два фронта. Один противник – это мы... но, судя по всему, основные их силы брошены на юг. Тут всё не так просто! Возможно, пора выяснить, с кем же они воюют." },
    ["2904a"] = { common = "Керноби стонет Э-э... Что случилось? Последнее, что я помню, это как меня похитили дворфы Чёрного Железа, избили до полусмерти и бросили сюда, к этим омерзительным троггам. Вытащи меня отсюда! Сделаем так: выведи меня к выходу; если нам удастся выбраться живыми, пойдёшь в Пиратскую бухту и скажешь Скути, что я был в Кабестане и предупредил Оловеня, что дворфы Чёрного Железа тоже как-то связаны с работой над супер-роботом. Идём!" },
    ["2904c"] = { male = "Ты достоин награды за то, что вернул Керноби целым и невредимым. Если твой дальнейший путь ведёт в Гномреган, вот это поможет тебе расправиться с никчёмным предателем, Мекжинером Термоштепселем.", female = "Ты достойна награды за то, что вернула Керноби целым и невредимым. Если твой дальнейший путь ведёт в Гномреган, вот это поможет тебе расправиться с никчёмным предателем, Мекжинером Термоштепселем." },
    ["2922a"] = { common = "Когда пал наш родной город Гномреган, с Техботом, видимо от расстройства, приключилось короткое замыкание. Бедный мой маленький друг! Он так помогал мне и моим коллегам! В него встроена куча полезных прибамбасов на все случаи жизни, объём памяти просто огромен, но всё это теперь совершенно бесполезно – его мозг из позитронного стал негатронным! Все заложенные в него программы теперь работают наоборот. Мой бедный сумасшедший робот теперь бродит по Гномрегану. Может, тебе удастся изловить его и извлечь его ядро памяти. Тогда я смогу разобраться в причинах поломки и, возможно, устраню её." },
    ["2922c"] = { common = "О, какое счастье! Спасибо! Я немедленно начну разбираться с поломкой! Бедный мой Техбот! Потерпи, я тебя вылечу. Так, куда же я засунул свой гидропневмогайковёрт..." },
    ["2923a"] = { common = "Мехмастер Замыкалец крайне опечален судьбой своего творения – Техбота. Помнится, Техбот был когда-то для гномов весьма полезным инструментом, однако теперь Большая Искра говорит, что он сломан. Очень жаль. Однако, быть может, его ещё возможно починить. Поговори об этом с Мехмастером Замыкальцем в Городе Механиков в Стальгорне. Он будет рад любой помощи." },
    ["2923c"] = { common = "Да, это правда. Мой Техбот совсем вышел из строя! Ты сможешь мне помочь?" },
    ["2924a"] = { common = "Базовый элемент – практически универсальный механизм, широко используемый механиками и кузнецами Гномрегана. Однако в спешке покидая город, никто из нас не догадался прихватить запас этих механизмов с собой. Мне просто необходимо пополнить мои запасы! Пожалуйста, отправляйся в Гномреган и добудь мне побольше таких механизмов. Думаю, их можно найти в подземельях нашего города – обычно они хранятся в контейнерах-экстраполяторах. Умоляю тебя, поторопись!" },
    ["2924c"] = { common = "Прекрасно! Теперь я могу продолжить свои эксперименты! Не знаю как благодарить тебя! Ты спас будущее гномьей науки!" },
    ["2925a"] = { common = "Мой друг, гном Клацморт Гайкокрут из Стальгорна, прислал мне письмо, в котором сообщает, что ему необходима помощь. Ему нужно отправиться в Гномреган, некогда величайший город гномов, который был осквернён, и теперь его населяют лишь безумные гномы и их жуткие изобретения. Я не могу покинуть Дарнасс, но душа моя болит за друга. Если ты сможешь помочь ему вместо меня, благодарности моей не будет предела. Ты найдёшь Клацморта в Городе Механиков в Стальгорне." },
    ["2925c"] = { male = "Да! Да! Мне очень нужна помощь в Гномрегане! И герой вроде тебя как раз подойдёт!", female = "Да! Да! Мне очень нужна помощь в Гномрегане! И героиня вроде тебя как раз подойдёт!" },
    ["2926a"] = { common = "С самого дня нашего бегства из города Гноарном думает только о том, как выставить троггов из Гномрегана и очистить город от заражения. У нас с Раззлом есть некоторые идеи на этот счёт, однако похоже, что воплотить их в жизнь сможет только настоящий безумец. Мы ещё не знаем, сработает ли наш замысел – надо всё как следует проверить! Для этого нам потребуются радиоактивные осадки, оставляемые облучёнными троггами в Гномрегане. Это зелёная светящаяся субстанция. Наполни ею этот фиал и принеси мне!" },
    ["2926c"] = { common = "Прекрасно! Теперь пришла пора опробовать нашу новую формулу. Если этот метод сработает, я не только смогу вылечить этого несчастного лепрогнома, но и вернуть свою утраченную шевелюру! Ну-ка, отойди в сторонку!" },
    ["2927a"] = { male = "Вы ведь не думаете, что я всегда был лысым? Нет, сударь! Эту трагическую утрату волос вызвала утечка радиации в Гномрегане. До тех пор я был единственным кудрявым гномом во всём Азероте. *Гноарн потрясает в воздухе кулаком.* Будь прокляты эти проклятые грязные трогги, будь они все прокляты!!! Может, ещё не поздно. Мы ещё можем исправить дело – я хочу сказать, спасти город! Поговорите с Оззи Триггервольтом в Караносе. Они со своим партнёром Раззлом как раз пытаются решить эту проблему.", female = "Вы ведь не думаете, что я всегда был лысым? Нет, сударыня! Эту трагическую утрату волос вызвала утечка радиации в Гномрегане. До тех пор я был единственным кудрявым гномом во всём Азероте. *Гноарн потрясает в воздухе кулаком.* Будь прокляты эти проклятые грязные трогги, будь они все прокляты!!! Может, ещё не поздно. Мы ещё можем исправить дело – я хочу сказать, спасти город! Поговорите с Оззи Триггервольтом в Караносе. Они со своим партнёром Раззлом как раз пытаются решить эту проблему." },
    ["2927c"] = { common = "Я думал, что утрата волос нашим выдающимся главой убьёт его, так нет, выжил! Я стоял рядом с ним, когда тот схватил дозу. И эти замечательные коричневые локоны посыпались на пол прядями! Клочьями! Ужас произошедшего только усилился, когда у Гроана крыша поехала! Да! Гроан, не веря глазам своим, коснулся лысой головы, и во взгляде его загорелась месть! И тогда он обрушился на троггов! Оззи ёжится." },
    ["2928a"] = { common = "Это ужасно. У нас, видно, не хватит запчастей, чтобы собрать всю партию автогиробуророек, которую пора отправить в Дун Морог. Что нам точно нужно – так это детали. И для добычи этих деталей не найти места лучше, чем Гномреган! Я слышала, что роботы и механизмы, оставшиеся там, бродят по городу как овцы на вольном пастбище. Я хочу от вас, чтобы вы отправились в Гномреган и распотрошили этих роботов на запчасти. Двух дюжин деталей должно хватить." },
    ["2928c"] = { common = "Это отлично подойдёт. Считайте, что одна автогиробуроройка отремонтирована. Осталось ещё триста девяносто восемь." },
    ["2929a"] = { male = "Я доверял Термоштепселю, герой. Никогда я не думал, что он предаст меня и весь гномий род. И ради чего? Ради власти? Богатства? Всё это он и так со временем получил бы. Теперь мы лишились родного дома, а этот безумец остался там править. Король пустого места... Мы вернём себе Гномреган. Мы не остановимся, пока город снова не станет нашим! Если ты хочешь присоединиться к нашей борьбе, выполни совсем простое поручение – убей предателя. Уничтожь Мекжинера Термоштепселя.", female = "Я доверял Термоштепселю, героиня. Никогда я не думал, что он предаст меня и весь гномий род. И ради чего? Ради власти? Богатства? Всё это он и так со временем получил бы. Теперь мы лишились родного дома, а этот безумец остался там править. Король пустого места... Мы вернём себе Гномреган. Мы не остановимся, пока город снова не станет нашим! Если ты хочешь присоединиться к нашей борьбе, выполни совсем простое поручение – убей предателя. Уничтожь Мекжинера Термоштепселя." },
    ["2929c"] = { male = "Я рад, что последнее, что он видел в своей жизни, была твоя стопа, попирающая его преступную голову, герой! Теперь, когда Термоштепсель мёртв, наши планы по возвращению Гномрегана на шаг приблизились к осуществлению!", female = "Я рад, что последнее, что он видел в своей жизни, была твоя стопа, попирающая его преступную голову, героиня! Теперь, когда Термоштепсель мёртв, наши планы по возвращению Гномрегана на шаг приблизились к осуществлению!" },
    ["2930a"] = { common = "Когда мы бежали из Гномрегана, то оставили там столько данных! Жизненно важных данных! Мне нужны данные с призматической перфокарты чрезвычайно секретного терминала матричного перфографа три тысячи пять-ди, что находится в глубинах Гномрегана. Вам нужно добраться до терминала, но сначала надо получить допуск... а для этого надо добраться до терминалов низшего уровня защиты – моделей -эй, -би и -си. А для ЭТОГО вам понадобятся перфокарты допуска, начиная с белой... а все перфокарты остались в городе. Это же катастрофа! Вы можете помочь нам?" },
    ["2930c"] = { common = "У вас получилось! Вы нашли призматическую перфокарту и восстановили утраченные данные! Жизненно, критически, безмерно важные данные, без которых мы просто не смогли бы жить! Вашу услугу гномы запомнят надолго." },
    ["2931a"] = { common = "Стальгорнский главный механик Чугунотрубз ищет искателей приключений! Он собирает отряд для проникновения в Гномреган с целью возвращения данных чрезвычайной важности и секретности. Хотя Чугунотрубз и не состоит в Просвещённой ассамблее чарологии, алхимии и инженерных наук, подобно мне, но он гном толковый, и если он считает это дело важным, то, по моим подсчётам, оно с вероятностью восемьдесят четыре процента важное! Шансы хорошие!" },
    ["2931c"] = { common = "Я готовлю миссию в Гномреган для возвращения важных данных. Если вы пришли помочь, то слушайте!" },
    ["2932a"] = { common = "Когда-то тролли из племени Сухокожих были на стороне Орды, но потом они предали Тралла... и это не должно сойти им с рук! Вот, возьмите мою пику и отправляйтесь во Внутренние земли, это далеко на севере. Сначала найдите Мельницу Таррен – поселение наших союзников, Отрёкшихся, а оттуда идите на северо-восток. Во Внутренних землях убейте двадцать троллей из племени Сухокожих, насадите их черепа на мою пику и воткните её в землю в одной из их деревенек – Хири'вата или Зун'вата. Пусть видят, что за свои действия надо отвечать!" },
    ["2932c"] = { common = "До меня дошли вести о ваших подвигах. Это жестокий поступок, но почётный. Надеюсь, тролли Сухокожих внимут нашему предупреждению." },
    ["2933a"] = { common = "В этих бутылках содержится очень сильный зелёный яд. Судя по количеству бутылок в деревне, тролли Сухокожих очень дорожат им. Возможно, аптекарь на Мельнице Таррен тоже заинтересуется этим ядом." },
    ["2933c"] = { common = "О, что это? Похоже на яд... яд какого-то паукообразного, да? Где же вы его взяли?" },
    ["2934a"] = { common = "Мне нужен свежий образец того яда, что вы приносили мне. Пауки, с которых он был собран, водятся во Внутренних землях – охотьтесь на них, пока вам не удастся добыть неповреждённую ядовитую железу, а потом принесите её мне. Больше всего пауков живёт в тролльем городе Шадра'Алоре. И не задерживайтесь – ядовитая железа нужна мне предельно свежей." },
    ["2934c"] = { common = "О, замечательно! Яд свежий и, я уверен, чрезвычайно смертоносный! Спасибо!" },
    ["2935a"] = { common = "Яд этих пауков не так силён, как тот, что вы приносили раньше. Наверное, тот яд был от другого паука. Мне нужен свежий образец того яда, а чтобы узнать, откуда он, нужно поговорить с троллем, который много знает о племени Сухокожих – это мастер Гадрин в деревне Сен'джин. Отправляйтесь в Дуротар и поговорите с ним. Он вполне может знать, откуда тролли племени Сухокожих берут этот яд." },
    ["2935c"] = { common = "А, так вам нужен свежий яд пауков Сухокожих? Ну что ж, присядьте... вам не понравится то, что я сейчас скажу." },
    ["2936a"] = { common = "Тролли Сухокожих поклоняются паучьей богине, и самый сильный яд берут у неё. Так что если вам нужен этот яд, нужно будет призвать её. Для этого требуется знать её истинное имя – оно начертано на табличке в тролльем городе Зул'Фарраке, это в Танарисе. Табличка находится у гробницы, которую охраняет Тека Мученик. Сразитесь с Текой и прочитайте на табличке имя паучьей богини, а потом возвращайтесь ко мне." },
    ["2936c"] = { common = "Элорта но Шадра... Произносите это имя лишь шёпотом, потому что один его звук повергает духов в смятение. Я напишу его на бумаге и сотворю для вас заклинание призыва." },
    ["2937a"] = { common = "Возьмите этот пергамент и прочитайте написанное на нём заклинание около алтаря Шадра'Алора — это в самом сердце владений клана Сухокожих. Это заклинание призовёт Шадру — паучью богиню." },
    ["2937c"] = { common = "У тебя получилось!" },
    ["2938a"] = { common = "Этот яд, который вы нашли у троллей Сухокожих, просто поразителен! Одной капли хватило, чтобы убить две дюжины кроликов. Ну, конечно, эти кролики были такие маленькие, что все уместились у меня на ладони, так что и организмы их особо не могли сопротивляться токсину… Но, тем не менее, яд просто убойный! Я хотел бы отправить образец моему коллеге, аптекарю Фаранеллу в Подгород. Наверняка он захочет испытать его самостоятельно." },
    ["2938c"] = { common = "А, очень хорошо. Лидон говорил о том, что яд в посылке гораздо сильнее всех известных нам образцов. Так что я хочу на него взглянуть. И спасибо тебе, путник. Твоя служба королевскому фармацевтическому обществу, неоценима." },
    ["2939a"] = { male = "Руины Фераласа могут быть очень опасны, но зато они способны немало рассказать нам о том, что здесь произошло. Вот, к примеру, несколько дней тому назад, копаясь в развалинах к югу отсюда, я обнаружил одну вещицу. На вид – обычный посох, но меня не покидает ощущение, что посох этот не простой. Мы с Ангелас уже давно корпим над книгами, но так ничего о нём и не узнали. У меня есть коллега в Дарнассе, которая, возможно, сумеет сообщить нам что-нибудь полезное. путник, быть может, вы сходите к ней и попросите нам помочь?", female = "Руины Фераласа могут быть очень опасны, но зато они способны немало рассказать нам о том, что здесь произошло. Вот, к примеру, несколько дней тому назад, копаясь в развалинах к югу отсюда, я обнаружил одну вещицу. На вид – обычный посох, но меня не покидает ощущение, что посох этот не простой. Мы с Ангелас уже давно корпим над книгами, но так ничего о нём и не узнали. У меня есть коллега в Дарнассе, которая, возможно, сумеет сообщить нам что-нибудь полезное. путница, быть может, вы сходите к ней и попросите нам помочь?" },
    ["2939c"] = { common = "А, так ты от Трояса Лунного Бриза? *Бормочет себе под нос* Вот вечно он меня донимает: ему всё время кажется, что он обнаружил что-то чрезвычайно важное… Послушай, я буду говорить откровенно. Троясу каждый раз кажется, будто он нашёл в этих развалинах невесть какую диковинку. На самом же деле всё, что там было ценного, давно уже растащили огры либо гарпии. Ты, конечно, можешь порыться в библиотеке, но не думаю, что ты сумеешь найти что-то, что тебе пригодится." },
    ["2940a"] = { common = "Книга выглядит так, как будто её не открывали годами. Переплёт потёрт и запылен, страницы пожелтели... Тем не менее, проглядев её, вы убеждаетесь, что это именно то, что нужно было Троясу. Вы берёте книгу, но соображаете, что неплохо было бы спросить разрешения прежде, чем её уносить." },
    ["2940c"] = { common = "Ты хочешь взять \"Историю Фераласа\"? Дай подумать… Хорошо, я разрешу тебе позаимствовать эту книгу, если ты сначала окажешь мне одну услугу." },
    ["2941a"] = { common = "Я в своё время занималась самыми разными предметами, а вот сейчас меня очень интересуют хрустогрызы, которые обитают на побережье Внутренних земель. Мне особенно хочется посмотреть на одного из них: гигантскую черепаху, которую зовут Гаммерита. Я бы отправилась туда сама, но не могу отвлекаться от своих исследований. Добудь мне хотя бы изображение, ладно? Отнеси это письмо Кургль Поскакушке, которая живёт в Танарисе. Она изобрела для меня машинку, которая может делать картинки. Кажется, Гурдл называет это \"снимками\"..." },
    ["2941c"] = { male = "А, ты один из студентов Дарин? Она очень сведущий историк. Тебе повезло, что ты занимаешься под её руководством. Ну, давай я покажу тебе свой супер-хвататель. Он тебе понравится!", female = "А, ты одна из студенток Дарин? Она очень сведущий историк. Тебе повезло, что ты занимаешься под её руководством. Ну, давай я покажу тебе свой супер-хвататель. Он тебе понравится!" },
    ["2942a"] = { common = "Как только артефакт извлечён из Монолита, вы ощущаете, что энергия посоха Равноденствия идёт на убыль." },
    ["2942c"] = { common = "Я с самого вашего ухода не отрывался от книги. Так вот: добытый вами камень называется Завтрашний камень. Для чего он нужен, я пока точно не знаю, однако понятно, что пустяковую вещь так прятать не стали бы. Я буду продолжать свои исследования. Надеюсь, что я и в будущем смогу на вас рассчитывать. Спасибо вам за всё!" },
    ["2943a"] = { common = "Вот книга. Пожалуйста, обращайся с ней бережно! Ну, ступай. Наверно, Трояс тебя уже заждался." },
    ["2943c"] = { common = "Книга у вас! Чудесно!" },
    ["2944a"] = { male = "Ты – первый, кто увидит моё новое изобретение! Тебе нужно только навести его на предмет, который ты хочешь запечатлеть, и нажать на кнопку! Как там называется то существо из Внутренних земель, которое тебе нужно? Гаммерита? На вот, бери и снимай. Я уверена, что Дарин будет в восторге от снимка. Приятного суперхватания!", female = "Ты – первая, кто увидит моё новое изобретение! Тебе нужно только навести его на предмет, который ты хочешь запечатлеть, и нажать на кнопку! Как там называется то существо из Внутренних земель, которое тебе нужно? Гаммерита? На вот, бери и снимай. Я уверена, что Дарин будет в восторге от снимка. Приятного суперхватания!" },
    ["2944c"] = { common = "О да! Изобретение Кургль оправдало все мои ожидания! Ты только не зазнавайся, но имей в виду, что я тобой довольна. Так, где же я оставила эту книгу..." },
    ["2945a"] = { common = "С тела одного из дворфов Чёрного Железа вы сняли предмет, напоминающий кольцо. Сложно сказать, что это за кольцо, поскольку оно покрыто толстым слоем окаменевшей грязи. Носить его едва ли возможно. Однако вы уверены, что под слоем грязи скрывается драгоценный металл, а может, ещё и самоцвет. Пожалуй, стоит попытаться отчистить всю эту грязь." },
    ["2945c"] = { common = "Вы опускаете кольцо и три монеты в Чистер пять тысяч двести. Машина с яростным гудением принимается за работу, скрипя и вибрируя. Сложно представить, что происходит внутри... Наконец Чистер пять тысяч двести замирает и окошко премника со звоном открывается. В нём лежит маленькая аккуратно завёрнутая коробка с красным бантиком. Похоже, Чистер пять тысяч двести также предоставляет подарочную упаковку!" },
    ["2946a"] = { common = "Мы хотим, чтобы вы доставили диски, обнаруженные вами, к запечатанным воротам Ульдума. Мы... мы не знаем, что с вами там может случиться. Да, мы знаем, что звучит рискованно. Но может ведь и ничего не случиться? Может, вам придётся что-то с этими дисками сделать. Возможно, эти диски откроют ворота. Не бойтесь экспериментировать и будьте готовы ко всему. Когда справитесь с заданием, возвращайтесь в Стальгорн. Нам будет что проанализировать!" },
    ["2946c"] = { common = "Когда вы прикасаетесь к постаменту, ульдаманские диски в вашем заплечном мешке начинают гудеть и светиться. Знакомое покалывание ощущается в руках, и перед вратами Ульдума оживает изваяние Каменного стража. \\\\\"Приветствую вас. Я – страж входа. Среди дисков доступа не хватает Ульдумских пластин. Пожалуйста, дополните набор дисков этими пластинами и повторите последовательность доступа. Благодарю за внимание\\\\\"." },
    ["2947a"] = { common = "Открыв коробку, вы видите именно то, что и предполагали – сияющее кольцо! Вы чувствуете исходящие от него волны магической силы. На внутренней стороне кольца стоит маленькое, но вполне различимое клеймо Стальгорна, а рядом с ним выгравированы инициалы: \"ТдК\". Это могут быть инициалы владельца, а может – изготовившего кольцо ювелира... Оставить кольцо себе или вернуть владельцу... Непростое решение!" },
    ["2947c"] = { common = "Кольцо, говорите? Ну конечно, это я его сделал! До падения Гномрегана у меня была там небольшая мастерская. Видимо, кольцо осталось там, когда пришлось очень быстро давать дёру. Довольно простое кольцо – я сделал таких несколько. Говорите, сняли с дворфа Чёрного Железа? Занятно, занятно – дело пахнет весьма запутанной интригой... Возможно, следует дать знать властям, такие вещи не для нашего брата... Что касается кольца..." },
    ["2948a"] = { male = "Слушайте путник, конечно, это ваше кольцо... но я вам лучшее сделаю! Дизайн, как я уже сказал, уж очень прост. Теперь я уже намного искуснее, и всего за каких-то тридцать серебряников я вам из него шедевр сделаю! Ну, чуть побольше тридцати, честно говоря... Сейчас я в затруднении, все мои запасы материалов иссякли. Если вы принесёте мне слиток серебра и моховой агат, то я нанесу на кольцо решётчатый узор из серебра и агата, и оно станет гораздо более стильным! Поверьте мне!", female = "Слушайте путница, конечно, это ваше кольцо... но я вам лучшее сделаю! Дизайн, как я уже сказал, уж очень прост. Теперь я уже намного искуснее, и всего за каких-то тридцать серебряников я вам из него шедевр сделаю! Ну, чуть побольше тридцати, честно говоря... Сейчас я в затруднении, все мои запасы материалов иссякли. Если вы принесёте мне слиток серебра и моховой агат, то я нанесу на кольцо решётчатый узор из серебра и агата, и оно станет гораздо более стильным! Поверьте мне!" },
    ["2948c"] = { common = "Ах, именно то, что нужно! Когда нибудь, когда я выберусь из этой ямы, в которую так незаслуженно попал, я сделаю для вас, для ВСЕХ лучшие украшения во всём Азероте! А пока благодарю вас за хлопоты. Обычно я прошу в десять раз больше, чем я взял с вас за кольцо такого качества... Кстати, о кольцах – вот ваша обновка!" },
    ["2949a"] = { common = "Открыв коробку, появившуюся в окошке Чистера пять тысяч двести, вы видите сияющее кольцо! Надев кольцо на палец, вы чувствуете исходящие от него волны магической силы. На внутренней стороне кольца стоит маленькое, но вполне различимое клеймо Оргриммара, а рядом с ним выгравированы три буквы: \"НОГ\" – это явно начало имени, но даже после чистки прочесть его целиком невозможно. Это могут быть инициалы владельца, а может – изготовившего кольцо ювелира... Оставить кольцо себе или вернуть владельцу... Непростое решение!" },
    ["2949c"] = { common = "Кольцо из Гномрегана? Очень любопытно... Нет, его сделал не я. Гномреганская штучка – н-да, неплохо для горстки болванов. Подумать только, эти ходячие недоразумения вдруг научились делать машины лучше нас... Что, кольцо было у дворфа Чёрного Железа? Ещё интереснее... Возможно, гномы спёрли и подправили чертежи их жутких големов – я бы этому совсем не удивился. Значит, теперь дворфы жаждут мести. Очень любопытно..." },
    ["2950a"] = { common = "Нет-нет-нет, я не собираюсь утверждать, что это моя работа! Обычно я такого не делаю. Но твоё сообщение насчёт дворфов Чёрного Железа чрезвычайно полезно. Так и быть, я переделаю для тебя это кольцо, и оно станет куда лучше, чем мог предполагать его создатель. Наверно, это был какой-нибудь гном... Принеси мне слиток серебра, моховой агат и тридцать серебряных монет – за труды. Я украшу кольцо серебряной решёткой, вправлю в него агат, и это значительно усилит его магические свойства. Интересует?" },
    ["2950c"] = { common = "Вот оно, твоё кольцо, лучше прежнего. Ещё раз спасибо за сведения об этих дворфах Чёрного Железа. Это объясняет, откуда вдруг у гномов взялись гоблинские идеи..." },
    ["2951a"] = { common = "Этот механизм широко применяется гномами для борьбы со всеми видами загрязнений. Небольшая табличка, прикреплённая к устройству, гласит: \"Чистер пять тысяч двести\". Ваши фамильные драгоценности и просто безделушки покрывает пыль веков? Чистер пять тысяч двести легко справится с этой проблемой! Опустите в щель приёмника три серебряные монеты и подождите пару минут, пока Чистер пять тысяч двести наводит лоск на ваши украшения." },
    ["2951c"] = { common = "Вы кладёте покрытый грязью предмет и три серебряные монеты в Чистер пять тысяч двести, и машина начинает работать, с гудением отскребая въевшуюся грязь. Металлический корпус аппарата скрипит и вибрирует." },
    ["2952c"] = { common = "Проглотив кольцо, машина несколько минут с гудением вертит его в своих недрах и наконец останавливается, звенящим звуком оповестив вас о том, что работа закончена. Окошко приёмника открывается, и вы видите в нём аккуратно завёрнутую коробочку. Видимо, машина выдаёт очищенные предметы в подарочной упаковке. Ну, даже если кольцо не удалось очистить, вы получили довольно миленькую коробочку за свои деньги… Что ж, посмотрим…" },
    ["2954a"] = { common = "Приветствую. Я охраняю вход. Если в вашем наборе дисков нет Ульдумских пластин, вы не сможете посетить комплекс Ульдум.\" Должно быть, появление Каменного Стража Норганнона и есть та реакция, на которую рассчитывали те, кто послал вас в пустыню Танарис с платиновыми дисками. Прежде чем продолжить путь, вам предстоит узнать историю Каменного Стража." },
    ["2954c"] = { common = "В голосе Каменного Стража звучит сила и власть: \\\\\"Когда ты коснёшья пьедестала, диски вернутся к тебе. Получив же Ульдумские пластины и воссоединив их с имеющимися дисками, ты сможешь войти в Ульдум.\\\\\"" },
    ["2962a"] = { common = "Этого образца не только недостаточно для опытов, он ещё и загрязнён. Нам нужно более сильное зелёное свечение. Для наших целей эти трогги явно недостаточно облучены. Вам придётся отправиться в Гномреган и принести некоторое количество радиоактивных образцов прямо с носителей. Я говорю об облучённых слизнюках, шнырюках и ужасниках. Будьте начеку: образцы хранить очень трудно. Возможно, придётся сделать несколько попыток, пока вы не принесёте достаточное количество образцов." },
    ["2962c"] = { common = "Оззи рассматривает вас. Впечатляюще, у вас не отвалилась ни одна конечность! Ну-с, посмотрим, на что сгодится эта проба!" },
    ["2963a"] = { common = "И снова примите мои поздравления! Ваша ульдаманская находка привела всю Лигу Исследователей в такое возбуждение! Лига пыталась разгадать тайны найденных вами миниатюрных платиновых дисков. Ваше неожиданное прибытие сюда, в Зал, даёт мне возможность сказать вам, что мы, похоже, наткнулись на нечто великое! Историк Карник нашёл важные сведения по поводу истинного происхождения Долины Стражей в пустыне Танарис. Он хочет поговорить с вами как можно скорее!" },
    ["2963c"] = { common = "Я счастлив, что вы не оставляете интереса к исследованиям! Ваши прирождённые талант и отвага помогут нам приоткрыть завесу таких тайн, что мы и надеяться не смели! Диски Норганнона из Ульдамана служили хранилищем обширных знаний. Вы, так сказать, только чуть копнули. У Создателей, как говорят, в Азероте имелись и другие хранилища. Это подводит нас к проблеме Ульдума..." },
    ["2964a"] = { common = "Что сказать… мы зашли в тупик. Мы знаем, что нам нужно – Ульдумские пластины – но где их взять, не имеем ни малейшего понятия. Необходимо провести серьёзное исследование и выработать план действий. У меня есть пара идей, и я надеюсь, что вскоре мы наймём тебя и отправим за пластинами. Об этом необходимо сообщить старшему исследователю; он без сомнения пожелает лично поблагодарить тебя за помощь Лиге." },
    ["2964c"] = { common = "Значит, мы все согласны – лучший план действий – это выждать, пока мы сможем сузить зону поиска. Мы зашли настолько далеко благодаря тебе, и я надеюсь, что именно ты сумеешь отомкнуть для нас Ульдум! Позволь вручить тебе заслуженный гонорар и небольшую премию. Заглядывай к нам время от времени... Ульдум ждёт тебя!" },
    ["2965a"] = { male = "Ах, как удачно, что ты снова пришёл ко мне! Твоя ульдаманская находка вызвала ожесточённые споры среди мудрецов. Я сам только что спорил с друидом, Нарой Буйногривой, когда меня вдруг осенило – её недавние приключения могут быть весьма важны в смысле определения следующего нашего шага в разгадке этой тайны! Я бы хотел, чтобы ты поговорил с ней о её путешествии в Долину Стражей в пустыне Танарис. Она ждёт теба на Вершине Старейшин.", female = "Ах, как удачно, что ты снова пришла ко мне! Твоя ульдаманская находка вызвала ожесточённые споры среди мудрецов. Я сам только что спорил с друидом, Нарой Буйногривой, когда меня вдруг осенило – её недавние приключения могут быть весьма важны в смысле определения следующего нашего шага в разгадке этой тайны! Я бы хотел, чтобы ты поговорила с ней о её путешествии в Долину Стражей в пустыне Танарис. Она ждёт теба на Вершине Старейшин." },
    ["2965c"] = { male = "В глубине пустыни Танарис есть место, называемое Долиной Стражей. Эти диски, что ты нашёл... в переводе иероглифической надписи на них упоминается место под названием Ульдум. Многие считают, что это миф. Но я-то знаю, что Ульдум существует. Я была там. Ну... хотя бы рядом постояла. Но вот в чём загадка – мы думаем, что есть связь между этими дисками и Ульдумом, потому мы хотим, чтобы ты отправился туда.", female = "В глубине пустыни Танарис есть место, называемое Долиной Стражей. Эти диски, что ты нашла... в переводе иероглифической надписи на них упоминается место под названием Ульдум. Многие считают, что это миф. Но я-то знаю, что Ульдум существует. Я была там. Ну... хотя бы рядом постояла. Но вот в чём загадка – мы думаем, что есть связь между этими дисками и Ульдумом, потому мы хотим, чтобы ты отправилась туда." },
    ["2966a"] = { male = "Мы с Ведуном Искателем Истины хотели бы, чтобы ты доставил эти миниатюрные диски к запечатанным воротам Ульдума. Мы... мы не знаем, что может после этого случиться. Да, мы понимаем, это может показаться рискованным. Но может ведь и ничего не случиться? Может, тебе придётся что-то с этими дисками сделать. Возможно, эти диски откроют ворота. Не бойся испытать их и будь готов ко всему. Узнай, что получится, и возвращайся ко мне. Нам есть много о чём поговорить.", female = "Мы с Ведуном Искателем Истины хотели бы, чтобы ты доставила эти миниатюрные диски к запечатанным воротам Ульдума. Мы... мы не знаем, что может после этого случиться. Да, мы понимаем, это может показаться рискованным. Но может ведь и ничего не случиться? Может, тебе придётся что-то с этими дисками сделать. Возможно, эти диски откроют ворота. Не бойся испытать их и будь готова ко всему. Узнай, что получится, и возвращайся ко мне. Нам есть много о чём поговорить." },
    ["2966c"] = { common = "Когда вы прикасаетесь к постаменту, улдаманские диски в вашем заплечном мешке начинают гудеть и светиться. Знакомое покалывание ощущается в руках, и перед вратами Ульдума оживает изваяние Каменного стража. \"Приветствую вас. Я – страж входа. Среди дисков доступа не хватает Ульдумских пластин. Пожалуйста, дополните набор дисков этими пластинами и повторите последовательность доступа. Благодарю за внимание\"." },
    ["2967a"] = { common = "Вы снова вступаете на пьедестал; неожиданно у вас в заплечном мешке опять материализуются платиновые диски. Обретя знания Каменного Стража и вернув себе диски, вам пора возвращаться в Громовой Утёс к Наре Буйногривой, сообщить ей о совершённых открытиях." },
    ["2967c"] = { common = "Тебе не хватило дисков? Забавно. Похоже, диски Норганнона – всего лишь часть полного набора, один из ключей в связке. Если нам удастся найти Ульдумские пластины, мы можем получить доступ в сам Ульдум! Не знаю, радоваться такой возможности или ужасаться. Быть может, нам придётся пожертвовать всем ради сохранения глубинных тайн земли, грозящих нам всем великими опасностями, хм, в тайне." },
    ["2968a"] = { common = "Что сказать… мы оказались в тупиковой ситуации. Мы знаем, что нам нужно – Ульдумские пластины – но где их взять, не имеем ни малейшего понятия. Необходимо провести серьёзное исследование и выработать план действий. У меня есть пара идей, и я надеюсь, что вскоре мы наймём тебя и отправим за пластинами. Об этом необходимо сообщить Мудрому Искателю Правды; он без сомнения пожелает лично поблагодарить тебя за услышанный зов." },
    ["2968c"] = { male = "Значит, мы все согласны – лучший план действий – это выждать, пока мы сможем сузить зону поиска. Мы зашли настолько далеко благодаря тебе, и я надеюсь, что именно ты сумеешь отомкнуть для нас Ульдум! Позволь вручить тебе заслуженный гонорар и немного сверхурочных. Должно покрыть все непредвиденные расходы. Заглядывай к нам время от времени... Ульдум ждёт тебя, юноша!", female = "Значит, мы все согласны – лучший план действий – это выждать, пока мы сможем сузить зону поиска. Мы зашли настолько далеко благодаря тебе, и я надеюсь, что именно ты сумеешь отомкнуть для нас Ульдум! Позволь вручить тебе заслуженный гонорар и немного сверхурочных. Должно покрыть все непредвиденные расходы. Заглядывай к нам время от времени... Ульдум ждёт тебя, девушка!" },
    ["2969a"] = { common = "Гнусные таурены из клана Зловещего Тотэма ловят лесных дракончиков! Мы с Джер'Кай понятия не имеем, что они собираются с ними делать, но явно ничего хорошего! У нас просто не хватит сил, чтобы прорваться в лагерь и освободить пленных дракончиков, но, может быть, с твоей помощью... Если ты согласишься помочь, и у тебя есть надёжные товарищи, отопри клетку вот этим ключом и выпусти бедных зверушек на волю! Только постарайся, чтобы все сумели улететь живыми... Конечно, я тоже буду с тобой! А Джер'Кай останется здесь." },
    ["2969c"] = { common = "Хвала Элуне! Ты настоящий подарок судьбы! Нам с Джер'Кай в одиночку никогда бы не удалось спасти бедных дракончиков. Пожалуйста, поговори теперь с Джер'Кай. А мне нужно приготовиться к мести! Если дракончики на свободе, это ещё не значит, что таурены не наловят новых! Так что мы с Джер'Кай собираемся перейти в наступление." },
    ["2970a"] = { male = "Как тебе уже говорила Кайдел, мы с ней собираемся напасть на тауренов из клана Зловещего Тотэма. Мы без труда уложим несколько тауренов, не подвергаясь опасности сами, но мы были бы очень рады, если бы и ты присоединился к нам. Тот лагерь, что внизу, тебе известен, но дальше на восток есть ещё несколько. Постарайся причинить тауренам максимальный ущерб. Ну, а после того, как они отведают стрел Кайдел и твоего собственного оружия, мы можем встретиться здесь снова.", female = "Как тебе уже говорила Кайдел, мы с ней собираемся напасть на тауренов из клана Зловещего Тотэма. Мы без труда уложим несколько тауренов, не подвергаясь опасности сами, но мы были бы очень рады, если бы и ты присоединилась к нам. Тот лагерь, что внизу, тебе известен, но дальше на восток есть ещё несколько. Постарайся причинить тауренам максимальный ущерб. Ну, а после того, как они отведают стрел Кайдел и твоего собственного оружия, мы можем встретиться здесь снова." },
    ["2970c"] = { male = "Да, Кайдел была права насчёт тебя: у тебя талант к этому делу! Ты – куда более опытный искатель приключений, чем мы обе. Спасибо, что ты с нами! Этот клан Зловещего Тотэма куда опаснее остальных тауренов. Подозреваю, что их боятся даже собственные сородичи! Впрочем, об этом потом.", female = "Да, Кайдел была права насчёт тебя: у тебя талант к этому делу! Ты – куда более опытная искатель приключений, чем мы обе. Спасибо, что ты с нами! Этот клан Зловещего Тотэма куда опаснее остальных тауренов. Подозреваю, что их боятся даже собственные сородичи! Впрочем, об этом потом." },
    ["2972a"] = { common = "Здесь, в глуши, у нас с Кайдел нет особых возможностей тебя вознаградить. Но разумеется, без награды мы тебя не отпустим! Вот, возьми мой перстень с печаткой. Если когда-нибудь окажешься в ветвях Тельдрассила, зайди в храм в центре Дарнасса. Там ты найдёшь нашу верховную жрицу, Тиранду Шелест Ветра. Кольцо будет для неё знаком, что с нами всё в порядке, и что тебе можно доверять. Мы обе благодарим тебя!" },
    ["2972c"] = { male = "Прекрасная история! Мы очень рады, что ты помог не только драконьему племени, но и одной из наших жриц. Джер'Кай поступила правильно, прислав тебя к нам. Я позабочусь о том, чтобы вернуть ей её кольцо – в Фералас в ближайшее время отправятся наши разведчики. Пусть заодно разведают и это... Спасибо тебе ещё раз. Чувствуй себя у нас, как дома!", female = "Прекрасная история! Мы очень рады, что ты помогла не только драконьему племени, но и одной из наших жриц. Джер'Кай поступила правильно, прислав тебя к нам. Я позабочусь о том, чтобы вернуть ей её кольцо – в Фералас в ближайшее время отправятся наши разведчики. Пусть заодно разведают и это... Спасибо тебе ещё раз. Чувствуй себя у нас, как дома!" },
    ["2973a"] = { male = "Приятно познакомиться, герой. Мы с товарищами прибыли сюда, в Фералас, по заданию из Оргриммара. Моя супруга, Коррин, очень любит новые наряды. Я хочу пошить ей новый плащ из прозрачных крылышек лесных дракончиков. Не согласишься ли ты мне помочь? Те летучие хамелеоны с роскошными крыльями, что мне нужны, водятся к западу от Лагеря Мохаче.", female = "Приятно познакомиться, героиня. Мы с товарищами прибыли сюда, в Фералас, по заданию из Оргриммара. Моя супруга, Коррин, очень любит новые наряды. Я хочу пошить ей новый плащ из прозрачных крылышек лесных дракончиков. Не согласишься ли ты мне помочь? Те летучие хамелеоны с роскошными крыльями, что мне нужны, водятся к западу от Лагеря Мохаче." },
    ["2973c"] = { male = "Отлично, герой! Да, это то, что надо. Этого вполне хватит на плащ для Коррин, а может, и останется! Спасибо тебе. Ну что, надеюсь, охота была не очень опасной? А то ведь Фералас ошибок не прощает. Спасибо ещё раз, герой!", female = "Отлично, героиня! Да, это то, что надо. Этого вполне хватит на плащ для Коррин, а может, и останется! Спасибо тебе. Ну что, надеюсь, охота была не очень опасной? А то ведь Фералас ошибок не прощает. Спасибо ещё раз, героиня!" },
    ["2974a"] = { male = "Как? Таурены, здесь, в этих краях? Да ты шутишь! И как они выглядели? Клан Зловещего Тотэма! Тебе повстречались именно они. Белгром, один из наших старших, очень ими интересуется... Даже награду за них назначил! Возвращайся туда, герой! Возвращайся, и принеси мне их рога – чем больше, тем лучше! С кланом Зловещего Тотэма шутки плохи, и недооценивать их не стоит. Ступай и перебей их, сколько сможешь. Пусть реки Фераласа побагровеют от их тёмной крови!", female = "Как? Таурены, здесь, в этих краях? Да ты шутишь! И как они выглядели? Клан Зловещего Тотэма! Тебе повстречались именно они. Белгром, один из наших старших, очень ими интересуется... Даже награду за них назначил! Возвращайся туда, героиня! Возвращайся, и принеси мне их рога – чем больше, тем лучше! С кланом Зловещего Тотэма шутки плохи, и недооценивать их не стоит. Ступай и перебей их, сколько сможешь. Пусть реки Фераласа побагровеют от их тёмной крови!" },
    ["2974c"] = { male = "Отличные рога, герой! Молодец! Я заберу их у тебя и сообщу о твоих деяниях Белгрому, как только вернусь в Оргриммар. Ты помог мне уже дважды, и я тебя запомню. Быть может, когда-нибудь и я тебе помогу! Удачи.", female = "Отличные рога, героиня! Умница! Я заберу их у тебя и сообщу о твоих деяниях Белгрому, как только вернусь в Оргриммар. Ты помогла мне уже дважды, и я тебя запомню. Быть может, когда-нибудь и я тебе помогу! Удачи." },
    ["2975a"] = { common = "Присутствие огров из клана Гордунни не может оставаться незамеченным. Оглядись вокруг! Само их существование уродует эту землю. Необходимо оттеснить их назад, пока они не продвинулись ещё дальше в Фералас. Ступай на север вдоль реки, и увидишь их заставу. Задай им жару! Пусть видят, что им тут не рады." },
    ["2975c"] = { common = "Отлично! Ещё немного, и эта земля исцелится. Мы не сдадимся!" },
    ["2976a"] = { male = "Чего ещё? Ах, я говорил о награде? Ну что ж, поделом мне – пора бы и научиться держать язык за зубами… Ну, в конце концов, это ты сделал всю работу, тебе и награда полагается. Забирай рога. Я велю упаковать их в ящик. Отыщи на Аллее Чести Белгрома Каменной Булавы. Он расспросит тебя о том, что ты видел, и выдаст заслуженную награду. Пока, герой! Ещё раз спасибо за всё.", female = "Чего ещё? Ах, я говорил о награде? Ну что ж, поделом мне – пора бы и научиться держать язык за зубами… Ну, в конце концов, это ты сделала всю работу, тебе и награда полагается. Забирай рога. Я велю упаковать их в ящик. Отыщи на Аллее Чести Белгрома Каменной Булавы. Он расспросит тебя о том, что ты видела, и выдаст заслуженную награду. Пока, героиня! Ещё раз спасибо за всё." },
    ["2976c"] = { male = "Клан Зловещего Тотэма?! Интересно... Так говоришь, ты наткнулся на них во время охоты в Фераласе? В самом деле? Твои новости очень важны для нас, герой. Расскажи всё как было, а я пока отсчитаю твою награду. Да, и пока ты не ушёл: имей в виду, я тебе очень признателен за эту информацию.", female = "Клан Зловещего Тотэма?! Интересно... Так говоришь, ты наткнулась на них во время охоты в Фераласе? В самом деле? Твои новости очень важны для нас, героиня. Расскажи всё как было, а я пока отсчитаю твою награду. Да, и пока ты не ушла: имей в виду, я тебе очень признателен за эту информацию." },
    ["2977a"] = { common = "Вы снова вступаете на пьедестал; неожиданно у вас в заплечном мешке опять материализуются платиновые диски. Обретя знания Каменного Стража и вернув себе диски, вам пора возвращаться в Стальгорн и сообщить Лиге Исследователей о совершённых открытиях." },
    ["2977c"] = { common = "Тебе не хватило дисков? Забавно. Похоже, диски Норганнона – всего лишь часть полного набора, один из ключей в связке. Если нам удастся найти Ульдумские пластины, мы можем получить доступ в сам Ульдум! Только представь – у нас появится возможность исследовать место, где трудились Создатели, не роясь в земле! Хотя землю рыть тоже неплохо... вполне..." },
    ["2978a"] = { common = "Вы берёте в руки запачканный свиток и обнаруживаете, что на нём изображена какая-то встреча или церемония. Рока Орхан наверняка заинтересуется этим свитком и тем, что он означает для Гордунни..." },
    ["2978c"] = { male = "Этот свиток... Ты нашёл его в Поселении Гордунни?", female = "Этот свиток... Ты нашла его в Поселении Гордунни?" },
    ["2979a"] = { common = "Похоже, они готовят какой-то тёмный обряд! Насколько я понимаю, проводить его будут маги-лорды из клана Гордунни. Отыщи одного из таких магов-лордов, и добудь у него магическую сферу. В такой сфере сокрыта великая мощь, и она поможет нам больше узнать об этом обряде и о магии, которой владеют Гордунни." },
    ["2979c"] = { common = "Эта сфера поможет нам получить информацию о Гордунни... И мы используем эту информацию, чтобы разгромить их!" },
    ["2980a"] = { male = "Теперь, когда ты показал себя настоящим бойцом, я надеюсь, тебе хватит мужества выполнить и следующее задание. Отправляйся в Высокогорные дебри, к юго-западу отсюда. Это земля, которая некогда принадлежала ночным эльфам. Там увидишь заброшенные и разрушенные здания. Когда увидишь среди руин засохшие деревья и осквернённую почву, знай: там и живут Гордунни. Прогони их прочь! Эти огры куда опаснее тех, с которыми тебе, доводилось сталкиваться прежде. Так что будь осторожнее!", female = "Теперь, когда ты показала себя настоящим бойцом, я надеюсь, тебе хватит мужества выполнить и следующее задание. Отправляйся в Высокогорные дебри, к юго-западу отсюда. Это земля, которая некогда принадлежала ночным эльфам. Там увидишь заброшенные и разрушенные здания. Когда увидишь среди руин засохшие деревья и осквернённую почву, знай: там и живут Гордунни. Прогони их прочь! Эти огры куда опаснее тех, с которыми тебе, доводилось сталкиваться прежде. Так что будь осторожнее!" },
    ["2980c"] = { common = "Да, ты воистину надёжный и верный союзник!" },
    ["2981a"] = { male = "Что, герой, хочешь показать себя? Фералас для этого самое подходящее место! Главная сила там – племя огров, именуемое Гордунни, и их становится всё больше и больше. Их надо остановить, пока они не вытеснили из Фераласа нас! В Лагере Мохаче в Фераласе живёт моя знакомая воительница по имени Рока Орхан. Ступай к ней. Она подробнее расскажет тебе о создавшемся положении.", female = "Что, героиня, хочешь показать себя? Фералас для этого самое подходящее место! Главная сила там – племя огров, именуемое Гордунни, и их становится всё больше и больше. Их надо остановить, пока они не вытеснили из Фераласа нас! В Лагере Мохаче в Фераласе живёт моя знакомая воительница по имени Рока Орхан. Ступай к ней. Она подробнее расскажет тебе о создавшемся положении." },
    ["2981c"] = { male = "А, тебя прислал Белгром! Ты как нельзя более вовремя, герой. Я расскажу, что у нас тут творится, а ты уж решай, по зубам ли тебе это... Хотя если тебя прислал Белгром, значит, сомневаться в твоей доблести не приходится.", female = "А, тебя прислал Белгром! Ты как нельзя более вовремя, героиня. Я расскажу, что у нас тут творится, а ты уж решай, по зубам ли тебе это... Хотя если тебя прислал Белгром, значит, сомневаться в твоей доблести не приходится." },
    ["2982a"] = { common = "Места там опасные, и всё же мы с Троясом исследовали руины в лесах Фераласа. Но в последнее время Трояс ходил в Высокогорные дебри в одиночку. Я серьёзно за него беспокоюсь! Эти земли захвачены ограми из клана Гордунни, а они не дают спуску тем, кто забредает на их территорию! Я надеялась, что вы, может быть, согласитесь побывать в развалинах на юго-востоке и перебить часть огров? Тогда эти места станут не такими опасными. Я вам буду очень признательна!" },
    ["2982c"] = { common = "О, как я вам благодарна! Только, пожалуйста, Троясу об этом ни слова!" },
    ["2983a"] = { male = "Много времени прошло с тех пор, как ты прошёл последнее испытание. Пока тебе хватало терпения в твоих занятиях, однако пришло время обрести новую силу... подлинную силу! Стихия огня – твоя, если только ты готов заплатить за это знание. Отыщи в Степях Кранала Фисса. Он живёт в небольшой хижине к северу от Перекрёстка. Только осторожнее: если окажешься в землях этих проклятых ночных эльфов, значит, тебя занесло не туда!", female = "Много времени прошло с тех пор, как ты прошла последнее испытание. Пока тебе хватало терпения в твоих занятиях, однако пришло время обрести новую силу... подлинную силу! Стихия огня – твоя, если только ты готова заплатить за это знание. Отыщи в Степях Кранала Фисса. Он живёт в небольшой хижине к северу от Перекрёстка. Только осторожнее: если окажешься в землях этих проклятых ночных эльфов, значит, тебя занесло не туда!" },
    ["2983c"] = { male = "Что, тебя Сварт прислал, да? Ну, на Сварта положиться можно. Значит, ты уже готов вкусить следующую сапту – сапту огня. Да, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг... Но терпение. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться.", female = "Что, тебя Сварт прислал, да? Ну, на Сварта положиться можно. Значит, ты уже готова вкусить следующую сапту – сапту огня. Да, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг... Но терпение. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться." },
    ["2984a"] = { male = "Много времени прошло с тех пор, как тебе пришлось выдержать последнее испытание! Тебе удалось научиться терпению, но теперь тебе пришло время сделать новый шаг. Пора учиться разрушению и хаосу. Тебе следует овладеть стихией огня – если только ты готов платить за это. Отыщи в Степях Кранала Фисса. Он живёт в небольшой хижине к северу от Перекрёстка. Только осторожнее: если промахнёшься, можешь очутиться в землях ночных эльфов!", female = "Много времени прошло с тех пор, как тебе пришлось выдержать последнее испытание! Тебе удалось научиться терпению, но теперь тебе пришло время сделать новый шаг. Пора учиться разрушению и хаосу. Тебе следует овладеть стихией огня – если только ты готова платить за это. Отыщи в Степях Кранала Фисса. Он живёт в небольшой хижине к северу от Перекрёстка. Только осторожнее: если промахнёшься, можешь очутиться в землях ночных эльфов!" },
    ["2984c"] = { male = "Что, тебя Нарм прислал, да? Ну, на Нарма положиться можно. Значит, ты уже готов вкусить следующую сапту – сапту огня. Да, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг... Но терпение. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться.", female = "Что, тебя Нарм прислал, да? Ну, на Нарма положиться можно. Значит, ты уже готова вкусить следующую сапту – сапту огня. Да, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг... Но терпение. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться." },
    ["2985a"] = { male = "Похоже, ты готов к новому испытанию. Ты проявил немало упорства в учении, и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды. Отыщи Ислен Заклинательницу Воды. Она живёт в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи.", female = "Похоже, ты готова к новому испытанию. Ты проявила немало упорства в учении, и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды. Отыщи Ислен Заклинательницу Воды. Она живёт в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи." },
    ["2985c"] = { common = "Ветер следует за тобой, по земле ты шагаешь твёрдо, а дух уже согрет огнём – я бы сказала, что пришло время познать чистоту воды. Путь твой был долог, и сила духа позволит тебе пройти ещё дальше. Но первый шаг делать тебе." },
    ["2986a"] = { male = "Много воды утекло со времени последнего испытания. Ты проявил немало упорства в учении и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды. Отыщи Ислен Заклинательницу Воды. Она живёт в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи.", female = "Много воды утекло со времени последнего испытания. Ты проявила немало упорства в учении и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды. Отыщи Ислен Заклинательницу Воды. Она живёт в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи." },
    ["2986c"] = { common = "Ветер следует за тобой, по земле ты шагаешь твёрдо, а дух уже согрет огнём – я бы сказала, что пришло время познать чистоту воды. Путь твой был долог, и сила духа позволит тебе пройти ещё дальше. Но первый шаг делать тебе." },
    ["2987a"] = { common = "Я только что прибыл сюда, в Фералас. Я слышал, что у огров из клана Гордунни, обитающих в здешних чащобах, попадаются интересные минералы. Неизвестно, к чему они им, но уж, разумеется, по доброй воле они ими делиться не собираются! Наоборот, норовят спрятать, чтобы бизнесменам вроде меня труднее было до них добраться. Если вы согласитесь помочь, то вот вам моя лопатка. Ступайте в Поселение Гордунни к северу отсюда и накопайте мне образцов кобальта Гордунни. Ищите: где блеснёт синим, там и ройте!" },
    ["2987c"] = { common = "Отлично! Захвачу это с собой, когда снова отправлюсь в путь. Я наверняка сумею найти кого-то, кто выложит за эти образцы кругленькую сумму! Благодарю вас. Вот, возьмите за труды." },
    ["2988a"] = { common = "Пропал сын нашего самого лучшего грифона! Наследник Быстрокрыла, Остроклюв, пропал несколько дней назад, когда охотился вместе с родителями. Я думаю, его похитили тролли! Помогите нам! Остроклюва могут держать в клетке в одной из двух деревенек Сухокожих." },
    ["2988c"] = { common = "Остроклюва в деревнях нет? Хм... это плохо. От этого грифона должно было произойти их следующее поколение, и если он погибнет, то наш флот понесёт огромные потери..." },
    ["2989a"] = { common = "У троллей племени Сухокожих Остроклюва нет... Значит, его забрали тролли из клана Порочной Ветви. Поищите детёныша грифона у Алтаря Зула – это на западной границе территории этого клана." },
    ["2989c"] = { common = "Остроклюва там не было? Это плохая, но и хорошая новость... Хорошо, что его не было на алтаре Зула – там тролли из клана Порочной Ветви совершают свои жертвоприношения. Спасибо за помощь, но, боюсь, вам предстоит ещё одна, более тяжёлая работа." },
    ["2990a"] = { common = "Отнесите это перо Тадиусу Мрачной Тени, прорицателю. Он давно ушёл с Заоблачного Пика в поисках тёмных знаний, но в душе он всё ещё с нами, с кланом Громового Молота! Возможно, он поможет нам разыскать Остроклюва. Это перо нашли в гнезде, где был детёныш грифона, и если вы отдадите его Тадиусу, то он сможет при помощи своего прорицания узнать, где находится сам Остроклюв. Удачи. Тадиуса можно найти в Выжженных землях, в башне магов в Крепости Стражей Пустоты." },
    ["2990c"] = { male = "Ах, да. Это перо грифона, но не обычного, а великого, способного на великие дела... Если, конечно, он доживёт до зрелого возраста. Хотите найти его? Что ж, тогда слушайте, храбрый герой.", female = "Ах, да. Это перо грифона, но не обычного, а великого, способного на великие дела... Если, конечно, он доживёт до зрелого возраста. Хотите найти его? Что ж, тогда слушайте, храбрая героиня." },
    ["2991a"] = { common = "Я найду вам вашего грифона, но вначале вы должны кое-что сделать для меня. В Зул'Фарраке живёт тролль по имени Некрум Кишкожуй, и мне очень-очень нужен его медальон, для изучения. Принесите мне тот медальон, а я найду вам Остроклюва. Зул'Фаррак лежит за океаном, на западе, в пустыне Танарис." },
    ["2991c"] = { common = "А, медальон Некрума. Говорят, он дарует троллям удивительное долголетие, но за определённую цену. Надеюсь, мне удастся заполучить силу этого медальона и избежать его... побочных эффектов. Вы оказали мне огромную услугу. Мне осталось лишь выполнить свою часть соглашения." },
    ["2992a"] = { common = "Посторонитесь-ка, мне нужно место, чтобы выполнить ритуал прорицания. Я установлю связь между этим пером и его владельцем, а потом попытаюсь найти и самого Остроклюва. Если всё пойдёт по плану, то должно получиться, а если нет... Вы, на всякий случай, закройте глаза." },
    ["2992c"] = { common = "Ритуал прошёл успешно. Я видел Остроклюва и могу сказать, где его найти." },
    ["2993a"] = { common = "Остроклюва держат в клетке, на самом верху Джинта'Алора, что во Внутренних землях. Ключ от его клетки находится у коварной жрицы племени Порочной Ветви Ведьмисы. Ну вот, я закончил. Желаю удачи в бою." },
    ["2993c"] = { common = "Вы поговорили с Мрачной Тенью? Что он сказал? Что? Остроклюв у троллей Порочной Ветви? Это немыслимо! Мы непременно должны его спасти!" },
    ["2994a"] = { common = "Мы должны спасти Остроклюва! Пробейтесь в верхнюю часть Джинта'Алора, отберите ключ у коварной жрицы Ведьмисы, а потом найдите и освободите Остроклюва!" },
    ["2994c"] = { common = "Быстроветр и Острокоготь минуту назад вернулись вместе со своим детёнышем, и теперь от него не отходят. Ох, как гляну на них, аж слеза прошибает… Я даже не знаю, чем мы можем отблагодарить вас, путник. Грифоны Заоблачного Пика и их всадники навсегда запомнят ваше имя." },
    ["2995a"] = { common = "Сторожка Кель'Данил – центр сообщения Высших эльфов Внутренних земель. Их посланники пытаются установить отношения с другими расами и делятся с ними сведениями о троллях из племени Сухокожих, обитающих в южной части Внутренних земель. Все документы, связанные с этим, хранятся в сторожке. Мы не хотим, чтобы Высокодолье заключало союзы с другими народами. Уничтожь документы Высокодолья. Есть мнение, что рукописи не горят… у тебя есть шанс проверить, так ли это." },
    ["2995c"] = { common = "Великолепно. Пока эльфы будут восстанавливать утраченную информацию, мы сможем ещё навсегда отрезать их от остального мира…" },
    ["2996a"] = { common = "Я многому тебя научил, теперь тебе нужен новый наставник. Он живёт в Кабестане, его зовут Страхад. Он человек, но он отнюдь не слаб. Он невелик ростом, но силён! Ты уже можешь вызывать более могущественных существ, и он научит тебя этому. Ступай к нему. Он живёт в Кабестане, над портом, рядом с башней." },
    ["2996c"] = { common = "Шумный денёк в Кабестане, не так ли? Обожаю наблюдать за суетой портового города. Столько тайн, столько приключений… и столько неведения. Это что, ненависть я вижу в твоих глазах? Превосходно. Мы найдём ей достойное применение." },
    ["2997a"] = { common = "Привет. Я знаю, что ты рук не покладаешь, помогая жителям Дун Морога, но когда тебе выпадет свободная минутка, посети Стальгорн и поговори с одной из самых почитаемых наших сестёр – Тизой Кузнебой. Она одна из тех, к кому обращаются самые молодые паладины, когда приходит пора им узнать побольше о Свете и том, что ожидается от тебя. Ты можешь найти её на верхнем этаже Зала Тайн, что в Палатах Магии. Удачи тебе." },
    ["2997c"] = { common = "Привет тебе. Надеюсь, Свет укажет тебе истинный путь и сохранит тебя от зла." },
    ["2998a"] = { male = "Приветствую тебя, брат мой. Даториан Ралл, один из самых влиятельных паладинов Оплота, недавно говорил о тебе. Он считает, что тебе пора пройти некое испытание... Он вообще весьма неплохо о тебе отзывался, надо сказать. На твоём месте я бы отправился в Штормград и поговорил с ним – разумеется, если у тебя найдётся на это время. Ищи его в Соборе Света: там он проводит большую часть времени.", female = "Приветствую тебя, сестра моя. Даториан Ралл, один из самых влиятельных паладинов Оплота, недавно говорил о тебе. Он считает, что тебе пора пройти некое испытание... Он вообще весьма неплохо о тебе отзывался, надо сказать. На твоём месте я бы отправился в Штормград и поговорил с ним – разумеется, если у тебя найдётся на это время. Ищи его в Соборе Света: там он проводит большую часть времени." },
    ["2998c"] = { common = "Как красив Штормград, не правда ли?.. Твой визит в это время более чем уместен." },
    ["2999a"] = { common = "Привет. Я знаю, что ты рук не покладаешь, помогая жителям Дун Морога, но когда тебе выпадет свободная минутка, поднимись наверх и поговори с одной из наших самых почитаемых сестёр – Тизой Кузнебой. Она одна из тех, к кому обращаются самые молодые паладины, когда приходит пора им узнать побольше о Свете и том, что от тебя ожидается." },
    ["2999c"] = { common = "Привет тебе. Надеюсь, Свет укажет тебе истинный путь и сохранит тебя от зла." },
    ["3000a"] = { common = "Привет. Я знаю, что ты рук не покладаешь, помогая жителям Азерота, но когда тебе выпадет свободная минутка, вернись в Стальгорн и поговори с Тизой Кузнебой. Она одна из тех, к кому обращаются самые молодые дворфские паладины, когда приходит пора им узнать побольше о Свете и том, что ожидается от всех нас. Ты можешь найти её на верхнем этаже Зала Тайн, что в Палатах Магии." },
    ["3000c"] = { common = "Приветствую и добро пожаловать." },
    ["3001a"] = { common = "Я многому тебя научил, и теперь тебе нужен новый наставник. Он живёт в Кабестане, его зовут Страхад. Это человек, но отнюдь не слабый. Также у нас нет причин смотреть на него как на потенциального врага... по крайней мере, пока что. Он обладает силой и заслуживает уважения. Я чувствую в тебе готовность призывать более могущественных существ, и он может обучить тебя этому." },
    ["3001c"] = { common = "Всегда жизнь в Кабестане, бьёт ключом, не так ли. Ну так, на то он и порт. Столько всяких тайн, столько приключений, столько невежества… Я вижу ненависть в твоих глазах? Хорошо, мы найдём ей полезное применение." },
    ["3002a"] = { common = "Я, конечно, хорошо знаю своих врагов, и всё же я – только воительница. Я даже приблизительно не представляю, на что способна эта сфера. Но я знаю одного мага в Оргриммаре, который сможет рассказать нам о ней больше. Отнеси сферу к нему!" },
    ["3002c"] = { common = "Да, занятная вещица… Этот шар весьма могуществен, но и очень опасен!" },
    ["3022a"] = { male = "Я вижу, как ты предан сему достойному делу. Да, конечно, ты можешь мне помочь! Отнеси этот ящик с яйцами Эреласу Янтарному Нёбу. Он друид, и заботится об этих яйцах, помогает вылупиться маленьким гиппогрифам и обучает их. Его можно найти в Тельдрассиле, в маленькой деревушке Рут'теран на юге.", female = "Я вижу, как ты предана сему достойному делу. Да, конечно, ты можешь мне помочь! Отнеси этот ящик с яйцами Эреласу Янтарному Нёбу. Он друид, и заботится об этих яйцах, помогает вылупиться маленьким гиппогрифам и обучает их. Его можно найти в Тельдрассиле, в маленькой деревушке Рут'теран на юге." },
    ["3022c"] = { common = "Спасибо за помощь. Если бы не мы, гиппогрифы уже вымерли бы. Впрочем, тебе случалось бывать в Фераласе, и ты знаешь не понаслышке, как опустошили землю Гордунни. Что ж, ты видишь, как я занят. Можешь идти. Ещё раз спасибо." },
    ["3042a"] = { common = "Тролли племени Песчаной Бури в Зул'Фарраке делают состав для закалки из песчаника, и я бы не отказался заполучить себе немного этого состава. Он весьма ценится мастерами, так что если ты принесёшь мне достаточно, то и вознаграждение будет щедрым. Зул'Фаррак находится к северу от Прибамбасска. Удачи!" },
    ["3042c"] = { common = "Отлично! Так много и все отборные! Этот запас я буду расходовать долго… Благодарю тебя. Прими это в качестве оплаты." },
    ["3062a"] = { common = "Эдана Коготь Ненависти – царица гарпий из стаи Студёных Ключей, что обитают в руинах к западу отсюда. Эдана – это воплощённое зло. Я слышал, что сердце у неё каменное. Она не ведает иных чувств, кроме ненависти, которую питает ко всему живому. Сразись с Эданой и принеси мне её тёмное сердце! Я слышал, что гарпии носят при себе рог. Если затрубить в него у камней Когтя Ненависти, в северной части руин, появится царица. Представь, как она удивится, когда обнаружит, что это был зов не её сородичей, но самой смерти!" },
    ["3062c"] = { common = "Ну, вот теперь я точно знаю, что Эдана мертва! А это сердце я оставлю себе на память о твоём подвиге. Спасибо тебе!" },
    ["3063a"] = { common = "В своё время я был закалённым охотником. Не было на свете такого зверя, которого я бы боялся. До тех пор, пока… Я был один в лесу, точил свой клинок после жаркой битвы, и тут на меня напали из засады! Меня окружили гарпии, я еле сумел добраться до безопасного места. Я ещё и теперь как наяву слышу их вопли... И с тех пор я уже никогда не мог стать прежним. В душе у меня кипит ненависть – все эти годы я жажду сквитаться с ними! Гарпии из стаи Студёных Ключей водятся к западу отсюда. Отомсти за меня." },
    ["3063c"] = { common = "Спасибо тебе. Ты возвращаешь покой душе старого таурена." },
    ["3065a"] = { common = "А! Тебе тут пергамент прислали, пока тебя не было. Прочитай, когда время будет. Это, кажется, от Франга, наставника воинов. Он хочет с тобой поговорить. Он обычно сидит в тени у входа в Логово." },
    ["3065c"] = { male = "Наша долина – подходящее место, чтобы упражняться в воинских навыках. Будут вопросы – не стесняйся задавать их кому угодно, а когда решишь, что готов продолжать обучение – возвращайся ко мне. Я ничем не уступаю любому из здешних воинов и охотно обучу тебя всему... хотя и не бесплатно!", female = "Наша долина – подходящее место, чтобы упражняться в воинских навыках. Будут вопросы – не стесняйся задавать их кому угодно, а когда решишь, что готова продолжать обучение – возвращайся ко мне. Я ничем не уступаю любому из здешних воинов и охотно обучу тебя всему... хотя и не бесплатно!" },
    ["3082a"] = { common = "А! Тебе тут табличку прислали, пока тебя не было. Прочитай, когда время будет. Это, кажется, от Джен'шан, наставницы охотников. Она хочет с тобой поговорить." },
    ["3082c"] = { male = "Теперь мы учим их пути охотника, а они учат нас другим вещам. Мы теперь одна раса... почти. Мы давнишние союзники. Не забывай об этом, а Джен'шан не забудет о тебе. Джен'шан научит тебя ремеслу охотника – хорошо научит! Помни: охотника в племени всегда уважают. И тебя ждёт большое будущее – помни это! Будет надо – приходи к Джен'шан. Она тебя научит всему, чему сможет, когда ты будешь готов.", female = "Теперь мы учим их пути охотника, а они учат нас другим вещам. Мы теперь одна раса... почти. Мы давнишние союзники. Не забывай об этом, а Джен'шан не забудет о тебе. Джен'шан научит тебя ремеслу охотника – хорошо научит! Помни: охотника в племени всегда уважают. И тебя ждёт большое будущее – помни это! Будет надо – приходи к Джен'шан. Она тебя научит всему, чему сможет, когда ты будешь готова." },
    ["3083a"] = { common = "А! Тебе тут табличку прислали, пока тебя не было. Прочитай, когда время будет. Это, кажется, от Руага, наставника разбойников. Он хочет с тобой поговорить." },
    ["3083c"] = { male = "Пока не придёт время, ты будешь под моим присмотром. Я покажу тебе основы, как говорится. Когда почувствуешь, что готов — приходи ко мне, и я подумаю, чему научить тебя дальше. А до тех пор — оттачивай свои навыки и держи их наточенными, как бритву. Никогда не знаешь, когда даже самое незначительное умение может спасти тебе жизнь.", female = "Пока не придёт время, ты будешь под моим присмотром. Я покажу тебе основы, как говорится. Когда почувствуешь, что готова — приходи ко мне, и я подумаю, чему научить тебя дальше. А до тех пор — оттачивай свои навыки и держи их наточенными, как бритву. Никогда не знаешь, когда даже самое незначительное умение может спасти тебе жизнь." },
    ["3084a"] = { common = "А! Тебе тут табличку прислали, пока тебя не было. Прочитай, когда время будет. Это, кажется, от Шикрик, наставницы шаманов. Она хочет с тобой поговорить." },
    ["3084c"] = { common = "Ты, вероятно, уже знаешь, что могущество нам дают стихии. Огонь, земля, вода и воздух – вот наши орудия. Наша сила исходит от духов предков. Мы должны вести наш народ. Для городов и деревень, где мы бываем, мы должны стать тем же, чем стал Тралл для всей Орды. У нас будут просить совета и защиты. Но чтобы этого добиться, тебе потребуется немало трудов. Когда ты почувствуешь, что у тебя накопилось достаточно сил, приходи ко мне, и я научу тебя всему, чему смогу." },
    ["3085a"] = { common = "А! Тебе тут табличку прислали, пока тебя не было. Прочитай, когда время будет. Это, кажется, от Кен'джая, наставника жрецов. Он хочет с тобой поговорить." },
    ["3085c"] = { male = "Почаще пускай в ход полученные знания и увидишь, что духи повинуются тебе всё лучше и лучше... В какой-то момент тебе поможет старый Кен'джай! Приходи потолковать с мной, когда будешь готов. И если духи согласятся, мы научим тебя кое-чему ещё... но только если они согласятся! Ну, ступай, потолкуй со другими здешними жителями. И про меня не забывай.", female = "Почаще пускай в ход полученные знания и увидишь, что духи повинуются тебе всё лучше и лучше... В какой-то момент тебе поможет старый Кен'джай! Приходи потолковать с мной, когда будешь готова. И если духи согласятся, мы научим тебя кое-чему ещё... но только если они согласятся! Ну, ступай, потолкуй со другими здешними жителями. И про меня не забывай." },
    ["3086a"] = { common = "А! Тебе тут табличку прислали, пока тебя не было. Прочитай, когда время будет. Это, кажется, от Май'ах, наставницы магов. Она хочет с тобой поговорить." },
    ["3086c"] = { male = "Да, скоро ты станешь очень могущественным! И всё это узнают... некоторые – на собственной шкуре! Но берегись! Бойся не орков, не эльфов и не дворфов. Бояться надо тех, кого не увидишь простым глазом. Магия могуча. И иногда заставляет творить то, чего не хочется. А иногда заставляет считать себя сильнее, чем ты есть. Будь терпеливее. Будь умнее. Когда решишь, что готов учиться, возвращайся к Май'ах. Она тебя всему научит, не беспокойся!", female = "Да, скоро ты станешь очень могущественной! И всё это узнают... некоторые – на собственной шкуре! Но берегись! Бойся не орков, не эльфов и не дворфов. Бояться надо тех, кого не увидишь простым глазом. Магия могуча. И иногда заставляет творить то, чего не хочется. А иногда заставляет считать себя сильнее, чем ты есть. Будь терпеливее. Будь умнее. Когда решишь, что готова учиться, возвращайся к Май'ах. Она тебя всему научит, не беспокойся!" },
    ["3087a"] = { common = "А! Тебе тут пергамент прислали, пока тебя не было. Прочитай, когда время будет. Это, кажется, от Джен'шан, наставницы охотников. Она хочет с тобой поговорить." },
    ["3087c"] = { common = "Когда мы закончим беседу, поговори с остальными обитателями долины. Они будут просить тебя что-нибудь сделать для них – и каждое такое задание будет для тебя проверкой на прочность. Наберёшься мудрости и опыта – приходи к Джен'шан, она научит тебя новым приёмам и навыкам. Возвращайся к Джен'шан как можно чаще." },
    ["3088a"] = { common = "А! Тебе тут пергамент прислали, пока тебя не было. Прочитай, когда время будет. Это, кажется, от Руага, наставника разбойников. Он хочет с тобой поговорить." },
    ["3088c"] = { male = "Клан Изувеченной Длани просил меня позаботиться о тебе. Они хотят, чтобы я обучил тебя и сообщал тебе о том, что им нужно. Даже если ты пока не стремишься им помогать – хотя это было бы глупо с твоей стороны, – я обучу тебя всему, чему смогу... за умеренную плату. Возвращайся ко мне, когда решишь, что готов, и мы посмотрим, чему можно тебя научить.", female = "Клан Изувеченной Длани просил меня позаботиться о тебе. Они хотят, чтобы я обучил тебя и сообщал тебе о том, что им нужно. Даже если ты пока не стремишься им помогать – хотя это было бы глупо с твоей стороны, – я обучу тебя всему, чему смогу... за умеренную плату. Возвращайся ко мне, когда решишь, что готова, и мы посмотрим, чему можно тебя научить." },
    ["3089a"] = { common = "А! Тебе тут пергамент прислали, пока тебя не было. Прочитай, когда время будет. Это, кажется, от Шикрик, наставницы шаманов. Она хочет с тобой поговорить." },
    ["3089c"] = { male = "Ты станешь тем, через кого говорят предки. Сила стихий будет в твоей власти – достаточно лишь будет протянуть руку. Внести смятение в ряды врагов будет проще простого, а исцелять союзников станет так же просто, как дышать. Помни об этом, когда встретишься с новыми испытаниями. Возвращайся ко мне, если понадобится. Я буду учить тебя новым заклинаниям и наставлю на верный путь, когда ты будешь готов.", female = "Ты станешь той, через кого говорят предки. Сила стихий будет в твоей власти – достаточно лишь будет протянуть руку. Внести смятение в ряды врагов будет проще простого, а исцелять союзников станет так же просто, как дышать. Помни об этом, когда встретишься с новыми испытаниями. Возвращайся ко мне, если понадобится. Я буду учить тебя новым заклинаниям и наставлю на верный путь, когда ты будешь готова." },
    ["3090a"] = { common = "А! Тебе тут пергамент прислали, пока тебя не было. Я лично стараюсь не иметь дела с чернокнижниками, однако ты его всё-таки прочитай, когда время будет. Это, кажется, от твоего нового наставника, Нартока. Он хочет с тобой поговорить." },
    ["3090c"] = { common = "Теперь и ты в наших рядах! Но не обманывайся. Да, ты имеешь доступ к могуществу, которому многие завидуют, но это не означает, что к тебе будут относиться с почтением. Тралл пускает нас в Оргриммар, ведь мы его сородичи – а иначе мы стали бы такими же жалкими, как люди, что держали его в рабстве. И всё же будь осторожен. Да, в твоих руках могущество, но если будешь глуп, – погибнешь. Понадобятся новые заклинания – приходи ко мне." },
    ["3091a"] = { common = "Привет! Слушай, минуту назад ко мне подошёл посыльный и передал вот эту записку для тебя. Думаю, она от наставника воинов Харутта. На твоём месте я бы прочитал её поскорее." },
    ["3091c"] = { male = "Каждый из нас играет свою роль в племени. Каждый из нас должен проходить одни и те же обряды. Никогда не позволяй гордыне ослепить тебя и заставить думать иначе. Я тут обучаю новых воинов, желающих снискать славы в битве и последовать по пути своих предков. Возвращайся ко мне, когда будешь готов, и я научу тебя всему, что умею. Иди, и да пребудет с тобой благословение племени!", female = "Каждый из нас играет свою роль в племени. Каждый из нас должен проходить одни и те же обряды. Никогда не позволяй гордыне ослепить тебя и заставить думать иначе. Я тут обучаю новых воинов, желающих снискать славы в битве и последовать по пути своих предков. Возвращайся ко мне, когда будешь готова, и я научу тебя всему, что умею. Иди, и да пребудет с тобой благословение племени!" },
    ["3092a"] = { common = "Привет! Слушай, минуту назад ко мне подошёл посыльный и передал вот эту записку для тебя. Думаю, она от наставника охотников Ланко. На твоём месте я бы прочитал её поскорее." },
    ["3092c"] = { common = "А моя задача — подготовить тебя, обучив основам нашего ремесла: как приручать питомца, как метко стрелять из ружья и многим другим навыкам, которые тебе пригодятся. Охотники — важная часть нашей традиции и истории. Помни об этом: ты — неотъемлемая часть племени. Если будешь служить народу с честью, тебя будут уважать и почитать." },
    ["3093a"] = { common = "Привет! Слушай, минуту назад ко мне подошёл посыльный и передал вот эту записку для тебя. Думаю, она от наставницы шаманов Милы. На твоём месте я бы прочитал её поскорее." },
    ["3093c"] = { male = "Мы ещё не раз встретимся с тобой, и каждый раз ты будешь уходить от меня чуть более сильным... чуть более подготовленным. Твой дух будет пылать подобно Неугасимому пламени. А теперь ступай, испытай себя! Возвращайся, если тебе понадобится моя помощь.", female = "Мы ещё не раз встретимся с тобой, и каждый раз ты будешь уходить от меня чуть более сильной... чуть более подготовленной. Твой дух будет пылать подобно Неугасимому пламени. А теперь ступай, испытай себя! Возвращайся, если тебе понадобится моя помощь." },
    ["3094a"] = { common = "Привет! Слушай, минуту назад ко мне подошёл посыльный и передал вот эту записку для тебя. Думаю, она от наставника друидов Гарта. На твоём месте я бы прочитал её поскорее." },
    ["3094c"] = { male = "Хоть у нас и ночных эльфов есть что-то общее, не стоит ждать от них хорошего отношения. Гордыня ослепляет их, но это не твоя забота. Сосредоточь свой разум на уроках Матери-Земли, а я научу тебя тому, что знаю, когда ты будешь готов. Приходи ко мне почаще. Ты узнаешь, что Мать-Земля дарует величайшие способности тем, кто полностью посвящает себя её учению.", female = "Хоть у нас и ночных эльфов есть что-то общее, не стоит ждать от них хорошего отношения. Гордыня ослепляет их, но это не твоя забота. Сосредоточь свой разум на уроках Матери-Земли, а я научу тебя тому, что знаю, когда ты будешь готова. Приходи ко мне почаще. Ты узнаешь, что Мать-Земля дарует величайшие способности тем, кто полностью посвящает себя её учению." },
    ["3095a"] = { male = "А, вот и ты! Пока ты разбирался с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нём что-то важное, поскольку на нём, похоже, стоит печать наставника воинов Даннала. Я бы на твоём месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.", female = "А, вот и ты! Пока ты разбиралась с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нём что-то важное, поскольку на нём, похоже, стоит печать наставника воинов Даннала. Я бы на твоём месте потратил время на его изучение, прежде чем пускаться в дальнейший путь." },
    ["3095c"] = { male = "Я здесь, чтобы обучать тебя по мере того, как ты будешь набираться опыта... приходи как только захочешь. Я беру минимальную плату за уроки и научу тебя всему, чему смогу, чтобы ты был достойным бойцом. А теперь иди и проверь свои боевые навыки. Многое ты поймёшь сам со временем, а кое-что я и вовсе не вправе поведать тебе. Просто знай, что в будущем Сильване потребуются помощники – такие, как ты. Ты станешь главной опорой нашего освобождения. Помни об этом.", female = "Я здесь, чтобы обучать тебя по мере того, как ты будешь набираться опыта... приходи как только захочешь. Я беру минимальную плату за уроки и научу тебя всему, чему смогу, чтобы ты была достойной воительницей. А теперь иди и проверь свои боевые навыки. Многое ты поймёшь сама со временем, а кое-что я и вовсе не вправе поведать тебе. Просто знай, что в будущем Сильване потребуются помощники – такие, как ты. Ты станешь главной опорой нашего освобождения. Помни об этом." },
    ["3096a"] = { male = "А, вот и ты! Пока ты разбирался с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нём что-то важное, поскольку на нём, похоже, стоит печать наставника разбойников Давида Триаса. Я бы на твоём месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.", female = "А, вот и ты! Пока ты разбиралась с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нём что-то важное, поскольку на нём, похоже, стоит печать наставника разбойников Давида Триаса. Я бы на твоём месте потратил время на его изучение, прежде чем пускаться в дальнейший путь." },
    ["3096c"] = { male = "Большую часть времени я провожу здесь, в таверне, присматриваясь к новым лицам и новым возможностям. Не суй свой нос, куда не следует, а я сделаю всё возможное, чтобы научить тебя кой-чему. Возвращайся ко мне, когда захочешь – посмотрим, будешь ли ты готов выучить пару новых трюков.", female = "Большую часть времени я провожу здесь, в таверне, присматриваясь к новым лицам и новым возможностям. Не суй свой нос, куда не следует, а я сделаю всё возможное, чтобы научить тебя кой-чему. Возвращайся ко мне, когда захочешь – посмотрим, будешь ли ты готова выучить пару новых трюков." },
    ["3097a"] = { male = "А, вот и ты! Пока ты разбирался с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нём что-то важное, поскольку на нём, похоже, стоит печать наставника жрецов Дьюстена. Я бы на твоём месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.", female = "А, вот и ты! Пока ты разбиралась с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нём что-то важное, поскольку на нём, похоже, стоит печать наставника жрецов Дьюстена. Я бы на твоём месте потратил время на его изучение, прежде чем пускаться в дальнейший путь." },
    ["3097c"] = { male = "Есть лишь одно, что ты должен знать: мы выжили благодаря лишь силе воли. В нас есть вера, отличающая нас от других, и с помощью нашей силы мы сможем в корне изменить весь Азерот. Слабые придут, чтобы положиться на тебя. Прокажённые будут звать тебя Господином. А невежественный будет просить тебя об обучении. Моя обязанность – обеспечить тебя необходимыми инструментами, чтобы, когда придёт время, ты был готов. По мере накопления опыта навещай меня. Я научу тебя большему, когда настанет время.", female = "Есть лишь одно, что ты должна знать: мы выжили благодаря лишь силе воли. В нас есть вера, отличающая нас от других, и с помощью нашей силы мы сможем в корне изменить весь Азерот. Слабые придут, чтобы положиться на тебя. Прокажённые будут звать тебя Госпожой. А невежественный будет просить тебя об обучении. Моя обязанность – обеспечить тебя необходимыми инструментами, чтобы, когда придёт время, ты была готова. По мере накопления опыта навещай меня. Я научу тебя большему, когда настанет время." },
    ["3098a"] = { male = "А, вот и ты! Пока ты разбирался с безмозглыми тварями Плети, тебе тут свиток прислали. Я думаю, в нём что-то важное, поскольку на нём, похоже, стоит печать наставницы магов Изабеллы. Я бы на твоём месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.", female = "А, вот и ты! Пока ты разбиралась с безмозглыми тварями Плети, тебе тут свиток прислали. Я думаю, в нём что-то важное, поскольку на нём, похоже, стоит печать наставницы магов Изабеллы. Я бы на твоём месте потратил время на его изучение, прежде чем пускаться в дальнейший путь." },
    ["3098c"] = { common = "Тебе стоит возвращаться ко мне почаще, если ты хочешь обрести достаточно сил для уничтожения наших недругов. Законы магии по-прежнему относятся и к тебе. Ты узнаешь, что скверна следует за тобой по пятам, аки тать в ночи. Ты узнаешь, что её прикосновение сродни пагубной страсти. Она будет льнуть к тебе, как трепетная любовница. И всё же ты можешь избежать её. Скверна обретёт власть над тобой, только если ты ей это позволишь. А сейчас иди... возвращайся, когда силы твои возрастут." },
    ["3099a"] = { male = "А, вот и ты! Пока ты разбирался с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нём что-то важное, поскольку на нём, похоже, стоит печать наставника чернокнижников Максимиллиона. Я бы на твоём месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.", female = "А, вот и ты! Пока ты разбиралась с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нём что-то важное, поскольку на нём, похоже, стоит печать наставника чернокнижников Максимиллиона. Я бы на твоём месте потратил время на его изучение, прежде чем пускаться в дальнейший путь." },
    ["3099c"] = { common = "Я говорил, что раб всегда останется рабом, кто бы ни был хозяином. Помнишь? Мы оба знаем, что именно этот тип контроля – этот самый вид силы – зовёт нас. Мы хотим, чтобы существа служили нам. Мы знаем, что мы более могущественны и заслуживаем большего уважения, чем другие оказывают нам... и теперь мы хотим взять своё. Я буду твоим союзником в этой борьбе – борьбе за нашу собственную свободу. Свободу искать своих собственных союзников. Когда почувствуешь, что время настало, возвращайся ко мне – и я научу тебя всему, что знаю." },
    ["3100a"] = { common = "Меня попросили передать тебе это письмо, как только ты вернёшься из лагеря кобольдов. Похоже, что на нём стоит печать Ллана, местного наставника воинов. На твоём месте я немедленно прочёл бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве." },
    ["3100c"] = { common = "Разберись в обстановке, изучи местность и возвращайся, как только тебе потребуется обучение. Я тут в любое время дня и ночи. Рыцари Серебряной Длани постарались, чтобы эти места стали почти безопасными, но если ты поговоришь с горожанами, то, думаю, заметишь, что у всех найдутся проблемы, с которыми без помощи воина не разобраться. Удачи!" },
    ["3100p"] = { common = "А, так ты получил моё письмо, путник… Это хорошо. В последнее время в Элвине прямо-таки наплыв воинов. Для Штормграда это хорошо, а вот местным кобольдам и бандитам из Братства Справедливости приходится несладко, ха-ха." },
    ["3101a"] = { common = "Меня попросили передать тебе это письмо, как только ты вернёшься из лагеря кобольдов. Похоже, что на нём стоит печать брата Самуэля, местного наставника паладинов. На твоём месте я немедленно прочёл бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве." },
    ["3101c"] = { male = "Тебе следует усвоить ещё пару вещей. Для многих в этих краях ты станешь примером для подражания, поэтому веди себя соответственно. Отблеск Благодати лежит на тебе – это видят и друзья, и враги. Кроме того, когда ты наберёшься опыта, тебе надо будет овладеть новыми способностями. Вот тут я тебе и пригожусь. Когда ты почувствуешь, себя готовым, приходи ко мне, и я научу тебя тому, что тебе, по моему мнению, пора будет узнать. Удачи тебе, герой!", female = "Тебе следует усвоить ещё пару вещей. Для многих в этих краях ты станешь примером для подражания, поэтому веди себя соответственно. Отблеск Благодати лежит на тебе – это видят и друзья, и враги. Кроме того, когда ты наберёшься опыта, тебе надо будет овладеть новыми способностями. Вот тут я тебе и пригожусь. Когда ты почувствуешь, себя готовой, приходи ко мне, и я научу тебя тому, что тебе, по моему мнению, пора будет узнать. Удачи тебе, героиня!" },
    ["3101p"] = { male = "Наконец-то! Вот мы и встретились, брат мой. Приветствую тебя в Североземье! Это место будет твоим домом, пока ты не усвоишь азы нашего дела, но знай, что Штормград недалеко, и рано или поздно твой путь приведёт тебя туда. Ну а пока наберись терпения… рыцарь Серебряной Длани.", female = "Наконец-то! Вот мы и встретились, сестра моя. Приветствую тебя в Североземье! Это место будет твоим домом, пока ты не усвоишь азы нашего дела, но знай, что Штормград недалеко, и рано или поздно твой путь приведёт тебя туда. Ну а пока наберись терпения… рыцарь Серебряной Длани." },
    ["3102a"] = { common = "Меня попросили передать тебе это письмо, как только ты вернёшься из лагеря кобольдов. Похоже, что на нём стоит печать Джорика, одного из наших местных наставников. На твоём месте я немедленно прочёл бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве." },
    ["3102c"] = { male = "Многим очень нужны наши умения. Искатели приключений, ШРУ... ха, даже Братство Справедливости не прочь заслать пару-другую шпионов в Штормград. Но не забывай: ты сам себе хозяин. И не давай никому втягивать тебя в то, что тебе не по нраву! Кроме того, у нас все козыри... по крайней мере, пока не кончена игра. Смекаешь? Короче, я хотел всего лишь представиться и дать тебе понять, что если тебе понадобится обучение, я всегда здесь. Приходи в любое время.", female = "Многим очень нужны наши умения. Искатели приключений, ШРУ... ха, даже Братство Справедливости не прочь заслать пару-другую шпионов в Штормград. Но не забывай: ты сама себе хозяйка. И не давай никому втягивать тебя в то, что тебе не по нраву! Кроме того, у нас все козыри... по крайней мере, пока не кончена игра. Смекаешь? Короче, я хотел всего лишь представиться и дать тебе понять, что если тебе понадобится обучение, я всегда здесь. Приходи в любое время." },
    ["3102p"] = { common = "Ты добрался сюда в целости и сохранности, и вроде бы тебя никто не заметил. Это хорошо — не люблю лишнее внимание… Думаю, ты меня понимаешь. Ещё ни во что не успел вляпаться? Нет? Здорово! Но ничего, всё впереди." },
    ["3103a"] = { common = "Меня попросили передать тебе это письмо, как только ты вернёшься из лагеря кобольдов. Похоже, что на нём стоит печать Анетты, местной наставницы жрецов. На твоём месте я немедленно прочёл бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве." },
    ["3103c"] = { common = "Как только ты наберёшься опыта, возвращайся ко мне, и я, как сумею, поделюсь с тобой своими знаниями. А пока ступай с милосердием в сердце, и пусть мудрость ведёт тебя. Помни, мир станет лучше, только если мы сами исцелим его." },
    ["3103p"] = { common = "Ах, наконец-то ты пришёл. Я знала, что ты меня найдёшь. Отблеск света Благодати лежит на тебе и избранном тобой пути. Нынешние времена суровы — Пылающий Легион всё ещё оскверняет своим присутствием Азерот, Калимдор ищет пути избавления от собственных несчастий, и ты должен будешь помогать нуждающимся в меру своих сил." },
    ["3104a"] = { common = "Меня попросили передать тебе это письмо, как только ты вернёшься из лагеря кобольдов. Похоже, что на нём стоит печать Келдена, местного наставника магов. На твоём месте я немедленно прочёл бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве." },
    ["3104c"] = { male = "Ха-ха, я знал, что не ошибусь адресом! Значит, ты готов принять свою судьбу? Готов бросить вызов богам и любым другим силам, что встанут на твоём пути к знаниям и могуществу? Не скрою, тебя будут не только уважать, но и бояться. Но знай и то, что я буду ждать тебя здесь, когда тебе понадобится обучение. Приходи ко мне, когда станешь опытнее.", female = "Ха-ха, я знал, что не ошибусь адресом! Значит, ты готова принять свою судьбу? Готова бросить вызов богам и любым другим силам, что встанут на твоём пути к знаниям и могуществу? Не скрою, тебя будут не только уважать, но и бояться. Но знай и то, что я буду ждать тебя здесь, когда тебе понадобится обучение. Приходи ко мне, когда станешь опытнее." },
    ["3104p"] = { common = "Привет, путник. Я — Келден. Чем могу помочь?" },
    ["3105a"] = { common = "Меня просили передать тебе это письмо, как только ты вернёшься из лагеря кобольдов. Похоже, что на нём печать Друзиллы, одной из наших местных наставниц. На твоём месте я немедленно прочёл бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь, в аббатстве." },
    ["3105c"] = { common = "Чем могущественнее ты будешь становиться, тем сильнее будет искушение... так что не забывай обуздывать себя. Ладно, скажу тебе прямо: любой, кто занимается тайными искусствами, может пасть. Особенно тот, кто имеет дело с тварями из Круговерти Пустоты. Будь терпелив и благоразумен... но не давай благоразумию подавлять твои амбиции. Как только ты станешь опытнее, возвращайся ко мне, и я открою тебе тайны нашего мастерства." },
    ["3105p"] = { common = "Наконец-то ты пришёл, путник! Представляешь, только что мимо проходили стражники и очень подозрительно на меня косились… жалкие тупицы." },
    ["3106a"] = { common = "Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи её, когда будет время. Думаю, руну прислал Тран, наставник воинов. Если представится случай, отыщи его в Старой Наковальне." },
    ["3106c"] = { common = "Я думаю, ты это уже знаешь, но на всякий случай скажу: в бою дворфы используют магию вместо ружей. Кое-кто из нас чтит Священный Свет – так же, как и некоторые люди, и даже трогги. А вообще, тебе ещё многое предстоит узнать. Я буду учить тебя воинскому мастерству. Если захочешь узнать пару новых приёмов, приходи сюда, и мы посмотрим, что я могу для тебя сделать." },
    ["3107a"] = { common = "Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи её, когда будет время. Думаю, руну прислал Бромос, наставник паладинов. Если представится случай, отыщи его в Старой Наковальне." },
    ["3107c"] = { male = "Люди многое поведали нам о Священном Свете и о том, как орден паладинов необходим им – и всему Азероту. Мы испытываем огромное уважение к традициям ордена. Поистине поразительно, что один человек, одна жертва может обратить погибель в спасение. Думаю, нам обоим придётся немного поработать вместе. Когда ты решишь, что время пришло, возвращайся ко мне: тебе нужно будет научиться кое-чему новому, прежде чем браться за дело. Негоже отправляться в далёкие странствия неподготовленным, верно?", female = "Люди многое поведали нам о Священном Свете и о том, как орден паладинов необходим им – и всему Азероту. Мы испытываем огромное уважение к традициям ордена. Поистине поразительно, что один человек, одна жертва может обратить погибель в спасение. Думаю, нам обоим придётся немного поработать вместе. Когда ты решишь, что время пришло, возвращайся ко мне: тебе нужно будет научиться кое-чему новому, прежде чем браться за дело. Негоже отправляться в далёкие странствия неподготовленной, верно?" },
    ["3108a"] = { common = "Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи её, когда будет время. Думаю, руну прислал Торгас, наставник охотников. Если представится случай, отыщи его в Старой Наковальне." },
    ["3108c"] = { male = "Всегда нужно помнить об уважении к тому миру, в котором мы живём. Звери, которые решат сражаться на твоей стороне, сияние клинка, тяжесть брони, пронизывающий холод ветра – без всего этого твоя жизнь будет не полна. Я сделаю всё, что смогу, чтобы познакомить тебя с ремеслом охотника, но знай: самое главное зависит от тебя. Когда ты решишь, что готов, приходи ко мне, и мы займёмся твоим обучением.", female = "Всегда нужно помнить об уважении к тому миру, в котором мы живём. Звери, которые решат сражаться на твоей стороне, сияние клинка, тяжесть брони, пронизывающий холод ветра – без всего этого твоя жизнь будет не полна. Я сделаю всё, что смогу, чтобы познакомить тебя с ремеслом охотника, но знай: самое главное зависит от тебя. Когда ты решишь, что готова, приходи ко мне, и мы займёмся твоим обучением." },
    ["3109a"] = { common = "Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи её, когда будет время. Думаю, руну прислал Сольм, наставник разбойников. Если представится случай, отыщи его в Старой Наковальне." },
    ["3109c"] = { male = "Я вот думаю: если ты собираешься шататься по Холодной долине, рано или поздно тебе потребуется усовершенствовать свои навыки, согласен? Так вот, если тебе это будет нужно, приходи, и я научу тебя тому, что знаю: обманный выпад, хитрый приёмчик... Понимаешь, о чём я? Эти трюки позволят тебе остаться в живых и заработать несколько звонких монет. Да, и приглядись повнимательнее к гномам: им несладко приходится с тех пор, как Гномреган был... скажем так, захвачен. Думаю, наша помощь им пригодится.", female = "Я вот думаю: если ты собираешься шататься по Холодной долине, рано или поздно тебе потребуется усовершенствовать свои навыки, согласна? Так вот, если тебе это будет нужно, приходи, и я научу тебя тому, что знаю: обманный выпад, хитрый приёмчик... Понимаешь, о чём я? Эти трюки позволят тебе остаться в живых и заработать несколько звонких монет. Да, и приглядись повнимательнее к гномам: им несладко приходится с тех пор, как Гномреган был... скажем так, захвачен. Думаю, наша помощь им пригодится." },
    ["3110a"] = { common = "Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи её, когда будет время. Думаю, руну прислал Брансток, наставник жрецов. Если представится случай, отыщи его в Старой Наковальне." },
    ["3110c"] = { male = "Я – тот, кто будет заниматься твоим обучением. Когда будешь готов, приходи ко мне: может быть, одно-два новых заклинания помогут тебе быстрее очистить долину от этих отвратительных троггов. Свет на твоей стороне, а с ним и весь Стальгорн... Эй, ты что разволновался? Это тебя ни к чему не обязывает... ну, почти ни к чему...", female = "Я – тот, кто будет заниматься твоим обучением. Когда будешь готова, приходи ко мне: может быть, одно-два новых заклинания помогут тебе быстрее очистить долину от этих отвратительных троггов. Свет на твоей стороне, а с ним и весь Стальгорн... Эй, ты что разволновалась? Это тебя ни к чему не обязывает... ну, почти ни к чему..." },
    ["3112a"] = { common = "Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти её, когда будет время. Думаю, записку прислал Тран, наставник воинов. Если представится случай, отыщи его в Старой Наковальне." },
    ["3112c"] = { common = "Да-да, теперь я окончательно понял, чего хотят гномы. И знаешь что? Даю слово, я сделаю всё возможное, чтобы ты и твои родичи смогли отвоевать свой дом. Да, вот ещё что: когда почувствуешь, что готов к обучению, приходи к старине Трану – я с радостью поделюсь с тобой всем, что знаю. Конечно, не за просто так, но ты можешь не беспокоиться: цена невысока. Ну, до встречи!" },
    ["3113a"] = { common = "Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти её, когда будет время. Думаю, записку прислал Сольм, наставник разбойников. Если представится случай, отыщи его в Старой Наковальне." },
    ["3113c"] = { common = "Я стараюсь не привлекать к себе особого внимания, так что если где-то что-то и пропадает, наша репутация от этого не страдает. Если тебе потребуется чему-нибудь подучиться или ещё что, приходи в любое время. Ну, мы ведь с тобой друг друга понимаем? Мы-то знаем, что бывают времена, когда верить можно только семье... и такие времена сейчас настали, верно? Гномреган... захвачен, и, думаю, это была не последняя беда, которая на нас свалилась... но мы с тобой всегда прикроем друг другу спину, да?" },
    ["3114a"] = { common = "Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти её, когда будет время. Думаю, записку прислал Маррайк, наставник магов. Если представится случай, отыщи его в Старой Наковальне." },
    ["3114c"] = { common = "О, да! Тайная магия... Конечно-конечно... Первое, что тебе следует усвоить, – это очень простой урок: не ищи неприятностей. Поверь, они найдут тебя сами. А если ты сбережёшь несколько монет, то сможешь купить мне кружку эля... или какое-нибудь заклинание для себя. Да, ещё совет: держись подальше от Гномрегана. Пока, думаю, с тебя хватит. Доброго тебе пути! Захочешь подучиться – приходи в любое время." },
    ["3115a"] = { common = "Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти её, когда будет время. Думаю, записку прислал Аламар, наставник чернокнижников. Если представится случай, отыщи его в Старой Наковальне. Да, вот ещё что... будь осторожнее. Таким, как ты, тут не слишком-то доверяют." },
    ["3115c"] = { male = "Но всё это не имеет значения. Важно лишь одно — ты узрел свой собственный Святой Свет. Ты понял, откуда приходит истинная сила. Ты осознал, что иметь собственных союзников куда... разумнее. Особенных союзников. Таких, что будут повиноваться до последнего вздоха. И вот тут вступаю я. Я могу обучить тебя основам этих особых сил. Приходи ко мне почаще — и я научу тебя новым заклинаниям.", female = "Но всё это не имеет значения. Важно лишь одно — ты узрела свой собственный Святой Свет. Ты поняла, откуда приходит истинная сила. Ты осознала, что иметь собственных союзников куда... разумнее. Особенных союзников. Таких, что будут повиноваться до последнего вздоха. И вот тут вступаю я. Я могу обучить тебя основам этих особых сил. Приходи ко мне почаще — и я научу тебя новым заклинаниям." },
    ["3116a"] = { common = "Этот знак был передан мне посланником нашей наставницы воинов, Алайссии. Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Алайссии." },
    ["3116c"] = { common = "Вскоре ты увидишь на ветвях нашего дома представителей других рас – но не поддавайся предубеждению. Они здесь приняты как гости. Они помогут нам, когда смогут помочь. Не все они действуют из альтруизма, однако всем им можно в некоторой степени доверять. Но всё это сейчас не в счёт. Мы должны подумать о тебе и о том, как ты сможешь помочь нашему народу. Я здесь именно ради этого. Я буду учить тебя действовать как воин по мере того, как ты будешь обретать силу. Возвращайся ко мне, когда пожелаешь, – и я сделаю всё возможное, чтобы помочь тебе." },
    ["3117a"] = { common = "Этот знак был передан мне посланником нашей наставницы охотников, Аянны. Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Аянне." },
    ["3117c"] = { common = "Когда обретёшь достаточно опыта в Тенистой долине, приходи ко мне – я помогу тебе постичь умения охотника и осознать твои собственные возможности. Это опасные времена, и даже умения твоих питомцев нельзя принимать как должное – в мире существуют вещи куда более опасные, нежели ты можешь вообразить. Да хранит тебя Элуна, я буду ждать твоего возвращения." },
    ["3118a"] = { common = "Этот знак был передан мне посланником нашего наставника разбойников, Фрагуна. Похоже, он хотел бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Фрагуну." },
    ["3118c"] = { common = "Но до тех пор знай, что в эти трудные времена услуги разбойников востребованы гораздо больше, чем обычно. Мирные отношения с другими расами могут рухнуть в любой момент, к тому же ходят слухи о представителях Орды, ищущих, как бы посеять семена ещё большего недоверия. Помни об этом. По мере того как будешь становиться более опытной и обретать силы, приходи сюда, и я позабочусь о твоём обучении. Тебе важно знать, помимо всего прочего, как обращаться с выбранным оружием." },
    ["3119a"] = { common = "Этот знак был передан мне посланником нашей наставницы жрецов, Шанды. Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Шанде." },
    ["3119c"] = { common = "Пока что не беспокойся о мире за пределами Тельдрассила – ещё успеешь. Иди теперь и поговори с остальными, живущими в Тенистой долине, – они расскажут тебе о том, что тут происходит. Помогай им в том, в чём сможешь, и в любой момент, когда тебе нужно будет обучение, возвращайся сюда, и я научу тебя всему, что знаю сама." },
    ["3120a"] = { common = "Этот знак был передан мне посланником нашего наставника друидов, Марданта. Похоже, он хотел бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Марданту." },
    ["3120c"] = { common = "Отныне я буду твоим наставником. Мой долг не только научить тебя истолковывать то, что вещают нам духи, но и дать тебе представление о сложностях и тайнах Изумрудного Сна. По мере обучения ты узнаешь больше о нашем сонном трансе. Но пока что приходи ко мне так часто, как сочтёшь нужным, и я обучу тебя всему, следуя традициям ночных эльфов." },
    ["3121a"] = { common = "Для начала мне понадобится помощь Нииру Огненного Клинка из Оргриммара! Он изготовил состав, который нужен мне для... ну, потом увидишь. В общем, ступай в Оргриммар. Да, и захвати с собой вот это. Это мумифицированная голова, которую я обещал Нииру в обмен на его травки. Какой-то злосчастный дворф, с которым я повстречался в лесу... Думаю, Нииру останется доволен. Ищи его в расселине Теней." },
    ["3121c"] = { common = "О, я давно ждал, когда Узери её пришлёт… А вот и смесь трав, которую я изготовил для его... экспериментов." },
    ["3122a"] = { common = "Вот травы. Отнеси их знахарю Узер'и. И, пожалуйста, передай ему, что сушёная голова – то, что надо." },
    ["3122c"] = { common = "Да, это именно то, что мне нужно, чтобы изготовить сосуд уменьшения! Скоро увидим, так ли могущественны мои последние заклинания, как я рассчитывал! Так, минутку... Мне надо совершить ритуал и использовать травы..." },
    ["3123a"] = { common = "Это будет испытание – испытание созданного мною ритуала, и твоих способностей тоже. Возьми этот сосуд. С его помощью ты сможешь уменьшать и помещать внутрь него разных существ. Отправляйся во Внутренние земли и отыщи существ, которых называют дикими совухами. Они некогда были питомцами богини Элуны, которую почитают ночные эльфы. Коварные и дикие совухи станут твоей первой добычей. Убей десять и с помощью сосуда уменьшения возьми их души в плен, пока они не успели ускользнуть." },
    ["3123c"] = { common = "Дух существа, преданного насильственной смерти, может вырваться на волю и попытаться отомстить. А помещая их в сосуд уменьшения, мы препятствуем духу вырваться на свободу. И теперь мы можем использовать его, как нам угодно!" },
    ["3124a"] = { male = "Ты уже доказал, что на тебя можно положиться, и ты умеешь обращаться с сосудами уменьшения. Теперь я попрошу тебя пленить другое создание. Гиппогрифы в течение многих лет были верными спутниками ночных эльфов, и души их твёрды и преданны. Твоя задача – убить десять блеклопёрых гиппогрифов, быстро уменьшить их и загнать в сосуды, чтобы сохранить таким образом их души. Гиппогрифов можно найти в Высокогорных дебрях, к югу отсюда.", female = "Ты уже доказала, что на тебя можно положиться, и ты умеешь обращаться с сосудами уменьшения. Теперь я попрошу тебя пленить другое создание. Гиппогрифы в течение многих лет были верными спутниками ночных эльфов, и души их твёрды и преданны. Твоя задача – убить десять блеклопёрых гиппогрифов, быстро уменьшить их и загнать в сосуды, чтобы сохранить таким образом их души. Гиппогрифов можно найти в Высокогорных дебрях, к югу отсюда." },
    ["3124c"] = { common = "Если мы убьём существо и позволим его духу ускользнуть, оно может превратиться в куда более могущественное создание! И тогда оно будет вечно грозить нам местью. Я поручил тебе опасную работу. Но тебе удалось с ней справиться." },
    ["3125a"] = { common = "Теперь я попрошу тебя отловить существо, которое на вид кажется довольно хилым, но дух его могуч, а это – именно то, что нам надо. Лесные дракончики, о которых я говорю, были союзниками ночных эльфов. Нам надо поймать такого дракончика, чтобы Орда тоже могла воспользоваться силой его духа. Убей восемь летучих хамелеонов или радужных дракончиков, и плени их души. Эти существа водятся к западу отсюда." },
    ["3125c"] = { common = "Спасибо! Теперь нам будет доступна сила духа лесных дракончиков. Надеюсь, ты не откажешься поработать на меня ещё немного?" },
    ["3126a"] = { common = "Следующей нашей добычей, станут бродячие лесные великаны, живые деревья. Ночные эльфы считают древней своими союзниками в борьбе против Орды. Движения древней медлительны, но в качестве защитников они незаменимы! И вскоре мы сможем использовать их мощь в своих целях. Отыщи три бродячих лесных древней, убей их и используй этот сосуд уменьшения, чтобы пленить их души!" },
    ["3126c"] = { common = "Спасибо! Наше собрание уменьшенных существ почти готово..." },
    ["3127a"] = { common = "Последнее, что от тебя потребуется – это отправиться на северо-запад и отыскать основного противника. Когда Пылающий Легион явился в мир, горные великаны спустились с гор, чтобы помогать ночным эльфам. Ты без труда обнаружишь их: они огромного роста, и когда они поблизости, земля начинает дрожать под ногами. Я жажду подчинить себе подобную мощь! Убей семь горных великанов и используй сосуд уменьшения, чтобы пленить их могучие души!" },
    ["3127c"] = { common = "Только представь себе, какими возможностями мы теперь обладаем! С теми материалами, которые тебе удалось собрать, я могу сколько угодно уловлять души этих созданий." },
    ["3128a"] = { common = "Для выполнения моего замысла мне нужны некоторые материалы... Будешь выполнять другие мои поручения – поищи заодно и то, что я тебя попрошу. Во-первых, расколотый ствол фераласского древня. Во-вторых, покрытые коркой минералы – эти можно добыть у горных великанов и волшебных драконов на западе. Кроме этого, добудь мне упругих сухожилий совухов из Внутренних земель либо гиппогрифов из Фераласа. И, наконец, мне потребуется большое количество металлических фрагментов, какие найдутся у любого из перечисленных созданий." },
    ["3128c"] = { common = "Отлично! Всё это, вкупе с духами животных, позволит мне изготовить именно то, что нужно!" },
    ["3129a"] = { common = "Вселить дух животного в оружие – процесс непростой! Теперь, когда у меня есть все необходимые материалы и души пойманных тобой созданий, я могу приступить к делу. Погоди немного, я скоро вернусь." },
    ["3129c"] = { common = "Ну что ж, выбирай, что тебе больше по нраву! В это оружие навечно заточены души могучих созданий. Теперь их сила – твоя сила." },
    ["3130a"] = { male = "В данный момент я собираюсь направить тебя к своему заместителю, Латроникусу. Он следит за боевыми приготовлениями наг. Сама же я буду продолжать осуществлять общее наблюдение. Как бы мне ни хотелось нанести им удар всеми имеющимися у нас силами, оставить крепость беззащитной перед атаками Орды – а может быть, и кого-то похуже, – не представляется разумным. Как бы то ни было, Латроникус тебя ждёт. Пока что ты показал себя молодцом. Продолжай в том же духе! Можешь идти.", female = "В данный момент я собираюсь направить тебя к своему заместителю, Латроникусу. Он следит за боевыми приготовлениями наг. Сама же я буду продолжать осуществлять общее наблюдение. Как бы мне ни хотелось нанести им удар всеми имеющимися у нас силами, оставить крепость беззащитной перед атаками Орды – а может быть, и кого-то похуже, – не представляется разумным. Как бы то ни было, Латроникус тебя ждёт. Пока что ты показала себя молодцом. Продолжай в том же духе! Можешь идти." },
    ["3130c"] = { common = "Что ж, отлично: я ценю готовность сражаться в тех, с кем имею дело. Генерал Лунное Перо поручила мне подготовить нападение на наг. Мои планы состоят из двух частей: во-первых, мы ослабим их силы и лишим командования, а во-вторых, выясним, что же они делают в этих развалинах. С твоей помощью мы сумеем задать нагам перцу, не ослабляя защиты крепости." },
    ["3141a"] = { common = "Так ты хочешь вступить в сражение с демонами? Тебе лучше для начала услышать то, что я скажу." },
    ["3141c"] = { common = "Так и быть…" },
    ["3161a"] = { common = "Я учёный, но в душе – кладоискатель! Давным-давно, когда в этих землях жили тролли, они обожествляли Газ'риллу, огромную гидру, и создали множество украшений в форме её тела. Их вырезали из особого материала, я называю его \"газ'риллий\" в честь богини-гидры. Я и сам ухитрился найти несколько образцов, но для исследований этого не хватает – может, ты мне ещё принесёшь? Я даже создал детектор, позволяющий мигом обнаружить газ'риллий! Надень его и приступай к поискам!" },
    ["3161c"] = { common = "Отлично; как раз то, что нужно для исследований. Огромное спасибо за помощь. Можно, я заберу свой шлем?" },
    ["3181a"] = { common = "Гигантский рог испещрён многочисленными сколами и царапинами, кроме того, из него торчит непонятный металлический предмет. Осмотрев рог более внимательно, вы понимаете, что металлический предмет есть ничто иное как обух секиры, сорванный с рукояти. На нём виднеется гравировка: \"Принадлежит горному пехотинцу Щебёночке\". Когда вы пытаетесь вытащить обух секиры из рога, он рассыпается на кусочки. Опаньки..." },
    ["3181c"] = { male = "Что это у тебя? Бессовестная подделка, вестимо! Я встречалась с Марголом один на один, и могу ответственно заявить тебе – рог у него раз в восемь больше, чем вот эта твоя закорючка! Небось, выдрал её из какого-нибудь несчастного грозорыла в Степях. Нет, милый, ты не обманешь Щебёночку!", female = "Что это у тебя? Бессовестная подделка, вестимо! Я встречалась с Марголом один на один, и могу ответственно заявить тебе – рог у него раз в восемь больше, чем вот эта твоя закорючка! Небось, выдрала её из какого-нибудь несчастного грозорыла в Степях. Нет, милая, ты не обманешь Щебёночку!" },
    ["3182a"] = { common = "Ты думаешь, я поверю этим россказням? Если бы это был настоящий рог, из него до сих пор торчал бы обух моей секиры. Вот что, неси-ка свою подделку куратору Ториусу в Стальгорн. Если он признает, что твои слова – правда, он даст тебе доказательство. Принеси его мне, и я дам тебе ключ к Тлеющему ущелью. Иди, иди!" },
    ["3182c"] = { male = "Что это? Я не могу поверить! Вы понимаете, что это, герой? Это же рог Маргола Яростеня! Маргола, причины гибели множества археологов, оказавшихся в Тлеющем ущелье. Можно мне оставить его себе?", female = "Что это? Я не могу поверить! Вы понимаете, что это, героиня? Это же рог Маргола Яростеня! Маргола, причины гибели множества археологов, оказавшихся в Тлеющем ущелье. Можно мне оставить его себе?" },
    ["3201a"] = { common = "Не может быть, чтобы Щебёночка усомнилась в подлинности рога. Между нами говоря, думаю, она просто ревнует. Я знаю, она хотела убить чудовище сама. Так вам, значит, нужно доказательство. Разумеется, вы принесли музею столь ценный дар, что я почту за честь написать для вас свидетельство. *Куратор Ториус начинает заполнять огромный документ* Ну вот, можете показать его Щебёночке." },
    ["3201c"] = { male = "Не понимаю, как мог такой слабак, как ты, одолеть Маргола, но я хозяйка своего слова. Но если после этого с тобой случится что-то нехорошее, пеняй на себя!", female = "Не понимаю, как могла такая слабачка, как ты, одолеть Маргола, но я хозяйка своего слова. Но если после этого с тобой случится что-то нехорошее, пеняй на себя!" },
    ["3221a"] = { common = "Пока вы отсутствовали, помогая нашим стражам смерти, за вами приходил аптекарь Ренферрел. Он не рассказывал мне подробностей, но хотел поговорить с вами о волчьих сердцах, что вы ему передали." },
    ["3221c"] = { common = "О, хорошо, что вы пришли. Касательно тех волчьих сердец, что вы мне ранее принесли – есть один момент, требующий вашего внимания." },
    ["3261a"] = { common = "Вот и закончились наши уроки. Не останавливайся на достигнутом, ступай в Лагерь Таурахо на юге и поговори с Джорном Заклинателем Небес. Он станет твоим новым учителем." },
    ["3261c"] = { male = "Приветствую тебя, юноша. Ты избрал путь охотника? Замечательно. Начнём с азов.", female = "Приветствую тебя, девушка. Ты избрала путь охотника? Замечательно. Начнём с азов." },
    ["3281a"] = { male = "Ящеров-то ты убил, но похищенное серебро необходимо вернуть! Говорят, что ящеры гнездятся на юге от Кабестана, в Землях ящеров. Скорее всего они утащили похищенное серебро именно туда. Отправляйся логово мерзких тварей и поищи наше серебро. Как найдёшь – сразу возвращайся ко мне.", female = "Ящеров-то ты убила, но похищенное серебро необходимо вернуть! Говорят, что ящеры гнездятся на юге от Кабестана, в Землях ящеров. Скорее всего они утащили похищенное серебро именно туда. Отправляйся логово мерзких тварей и поищи наше серебро. Как найдёшь – сразу возвращайся ко мне." },
    ["3281c"] = { common = "Ага! Значит, ящеры всё же утащили его в своё логово. Трудно понять, зачем этим тварям серебро. Быть может, в байках об их уме есть зерно правды! Спасибо. Прими награду за услуги и помни, что стражи перекрёстков получили свою месячную оплату лишь благодаря тебе." },
    ["3301a"] = { common = "Одна из моих соплеменниц, Муура Рунический Тотэм, отправилась в Серебряный бор на помощь нашим союзникам-нежити. Серебряный бор – больной, вымирающий лес, и Муура надеялась вдохнуть в него новую жизнь. Может быть, необычные обитатели Степей подскажут ей, как лучше выполнить задачу. Возьми образец добытых тобой панцирей и отнеси его Мууре в Серебряный бор. Она остановилась в Гробнице. При удаче, осмотрев панцирь, она придумает, как исцелить это погибающее место." },
    ["3301c"] = { common = "Что это? Панцирь светится изнутри, словно в нём по-прежнему теплится жизнь. Удивительно! Надо изучить его внимательнее. Спасибо. Быть может, в этом панцире сокрыта тайна исцеления бедной израненной земли Серебряного бора." },
    ["3321a"] = { male = "Ты много сделал для Ордена. Обычный искатель приключений не выдержал бы такой нагруки. Ни я, ни Гальван не сомневаемся, что ты стал одним из нас. Поэтому мне кажется, что ты заслуживаешь награды. Сущий пустяк, побрякушку. Может быть, ты знаешь о её свойствах. Должно быть, именно из-за них ты и пришёл к нам.", female = "Ты много сделала для Ордена. Обычный искатель приключений не выдержал бы такой нагруки. Ни я, ни Гальван не сомневаемся, что ты стала одной из нас. Поэтому мне кажется, что ты заслуживаешь награды. Сущий пустяк, побрякушку. Может быть, ты знаешь о её свойствах. Должно быть, именно из-за них ты и пришла к нам." },
    ["3321c"] = { common = "Войди же в круг равных, кузнец Ордена Мифрила." },
    ["3341a"] = { common = "В Степях есть уголок, заросший кошмарными колючками. Он называется Курганы Иглошкурых. Хотя с первого взгляда это место не показалось нам опасным, по последним сведениям всё куда серьёзнее… Живущие в холмах свинобразы поддались злому влиянию Плети. Теперь их действиями руководит лич по имени Амненнар Хладоносец. У Амненнара прямая телепатическая связь с Нер'зулом; мы должны прервать её. Да сгинет Хладовей!" },
    ["3341c"] = { common = "Никто не смеет пойти против воли лича. Однако, такая верность может привести лишь к погибели." },
    ["3361a"] = { common = "Мы изгнали троггов из Гномрегана и уж было собрались праздновать победу, но тут всё пошло наперекосяк! Только представь: радиация кругом, а гномы – те, кто ещё жив – разбрелись по Дун Морогу... Я так торопился, что все свои вещи бросил, да и все инструменты в придачу. Вот тролли – те не растерялись: им что радиация, что грибной дождик... Прибрали всё к рукам: и сундук, и ларец, и даже ведро с винтиками не постеснялись прихватить! Всё, всё уволокли к себе в лагерь, куда-то к юго-западу от Старой Наковальни... Путешественник из меня никудышный, так я вот тут подумал: может, ты у них заберёшь мои вещи и вернёшь их мне?" },
    ["3361c"] = { common = "Ага! Есть! Есть! Тебе удалось найти мои вещи! Я спасён!.. Вот, держи: это, конечно, сущие пустяки, но должен же я тебя хоть чем-то вознаградить за все испытания." },
    ["3362a"] = { male = "Ты когда-нибудь был в долине Кактусов? Это опасное место. Там такие жуткие твари, я им ни на минуту не верю! Бугристые шипошкуры и корнеплёты, кажется так они зовутся… Так или иначе, я хочу попасть в эту долину, но пока там столько шипошкуров, ноги моей там не будет. Вот зачем ты мне нужен – если выкосить часть этих тварей, я могу и решиться на поход. Что скажешь? Поможешь мне?", female = "Ты когда-нибудь была в долине Кактусов? Это опасное место. Там такие жуткие твари, я им ни на минуту не верю! Бугристые шипошкуры и корнеплёты, кажется так они зовутся… Так или иначе, я хочу попасть в эту долину, но пока там столько шипошкуров, ноги моей там не будет. Вот зачем ты мне нужна – если выкосить часть этих тварей, я могу и решиться на поход. Что скажешь? Поможешь мне?" },
    ["3362c"] = { male = "Они такие огромные? Нет, план меняется… Но ты-то выполнил свою часть сделки, поэтому вот, держи обещанное.", female = "Они такие огромные? Нет, план меняется… Но ты-то выполнила свою часть сделки, поэтому вот, держи обещанное." },
    ["3364a"] = { common = "Я уже давно должен был доставить эту отличнейшую жгучую бражку в Старую Наковальню Дарнану Мехорезу, да только сначала мне нужно было завезти немного Грелину. Боюсь, к тому времени, как я доберусь до Старой Наковальни, остынет бражка-то! Ты на ногу полегче моего будешь, как я погляжу; вот я и подумал... эта кружка останется горячей ещё минут пять, а Дарнан вовсе не охлаждённую бражку заказывал, – не пиво, чай! – так что отправляйся-ка ты в путь. Старая Наковальня – это такое поселение в скалах к северо-востоку отсюда. Благодарю заранее... и вот ещё что: не забудь вернуть мою кружку!" },
    ["3364c"] = { common = "Отлично! Это именно то, что нужно! Ты погоди пока, эту штуку пить надо, пока не остыла, иначе вкуса того не будет." },
    ["3365a"] = { common = "Ох, хорошо-то как! Все эти прохладительные напитки – полная ерунда: в морозный денёк нет ничего лучше глотка горячей бражки! Даже на душе теплее становится! Вот, держи; сделай доброе дело, отнеси эту кружку Нори, ладно?" },
    ["3365c"] = { common = "Спасибо! Ты удивишься, если я расскажу тебе, сколько народу забывает сделать самое простое – вернуть назад кружку. А кружки-то, между прочим, на деревьях не растут! Ну, по крайней мере, в наших краях. Тут у меня есть кое-что для тебя. Я так думаю, усердие нужно вознаграждать, верно ведь?" },
    ["3366a"] = { common = "Блестящий осколок ярко-зелёный, без примесей, но под поверхностью можно видеть что-то похожее на клубы дыма. Оторвать взгляд от этих узоров в глубине невозможно, но в то же время вы осознаете какое-то беспокойство. Пожалуй, стоит поискать в Кабестане кого-нибудь, кто может знать больше об этом странном осколке." },
    ["3367a"] = { male = "Из груди Дориуса вырывается стон Я тяжело ранен, герой. Ужасно кружится голова... Думаю, у меня внутреннее кровотечение... Мне нужно добраться обратно в Стальгорн. Помоги мне.", female = "Из груди Дориуса вырывается стон Я тяжело ранен, героиня. Ужасно кружится голова... Думаю, у меня внутреннее кровотечение... Мне нужно добраться обратно в Стальгорн. Помоги мне." },
    ["3367c"] = { common = "Письмо выронил Дориус, когда падал." },
    ["3368a"] = { common = "Брат! Если ты читаешь эти строки, меня уже нет в живых. Не знаю, кто доставил тебе письмо, но непременно поблагодари и вознагради его. Теперь о камнях: они существуют и сейчас находятся у клана Чёрного Железа. С помощью этих камней их главарь, Латорик Чёрный, удерживает моих соратников по экспедиции в плену. Лишённые рассудка, они день и ночь трудятся над созданием монстра, именуемого Обсидионом. Спаси их, брат. Это моя последняя воля. Дориус." },
    ["3368c"] = { common = "*Ториус утирает слёзы*. Клянусь Светом, его воля будет исполнена. Клянусь!" },
    ["3369a"] = { common = "Этот осколок сам по себе большая загадка; Это чистая эссенция Изумрудного Сна. Однако, это осколок не сна, а скорее кошмара. Не хочу тревожить тебя, но лучше будет, отдать его кому-то из старших друидов, как только сможешь. Хамуул Рунический Тотэм с Вершины Старейшин, вот кого тебе надо найти. Отправляйся на Громовой Утёс, точнее сказать не могу." },
    ["3369c"] = { common = "Тебя послала Фалла? Давай-ка, взглянем на этот осколок… Хамуул вглядывается в осколок. Ох... Боги… Спасибо, что принёс это мне. О таких вещах вслух не говорят, но я всё же предупрежу тебя, есть вещи, с которыми ты можешь не справиться. Запомни, в Изумрудном сне всё не то, чем кажется... Возможно в будущем мы встретимся вновь." },
    ["3370a"] = { common = "Этот осколок сам по себе большая загадка; Это чистая эссенция Изумрудного Сна. Однако, это осколок не сна, а скорее кошмара. Не хочу тревожить тебя, но лучше будет, отдать его кому-то из старших друидов, как только сможешь. Матренгил Медвежья Лапа из Круга Кенария, вот кого тебе надо найти. Отправляйся в Дарнасс, точнее сказать не могу." },
    ["3370c"] = { common = "Тебя послала Фалла? Давай-ка, взглянем на этот осколок… Матренгил вглядывается в осколок. Ох... Боги… Спасибо, что принёс это мне. О таких вещах вслух не говорят, но я всё же предупрежу тебя, есть вещи, с которыми ты можешь не справиться. Запомни, в Изумрудном сне всё не то, чем кажется... Возможно в будущем мы встретимся вновь." },
    ["3371a"] = { common = "Теперь в груди моей зияет чёрная дыра — там, где было когда-то сердце… Я никогда не смогу смириться с гибелью Дориуса, путник. Я сделаю всё, чтобы его последняя воля была исполнена — тех, на ком его кровь, должна настигнуть суровая кара. Возвращайся в Тлеющее ущелье и исполни волю Дориуса — освободи его соратников." },
    ["3371c"] = { common = "Забудь обо мне, помогай другим." },
    ["3372a"] = { common = "Отпусти их, странник. Даже когда их тела совсем обессилеют, власть Сунтары заставляет их достичь цели любой ценой. Всё дело в алтаре Сунтары. Отправляйся на северо-запад, там, в холмах над пещерой… Сумеречный Молот хранит реликвию. Добудь её и возложи на алтарь Сунтары." },
    ["3372c"] = { common = "Вы размещаете таинственный артефакт на алтарь Сунтары." },
    ["3373a"] = { common = "Вы касаетесь камня и слышите голос, звучащий в вашем сознании. \"Услышь мою мольбу, о смертный. Имя мне Эраникус из народа зелёных драконов. Мои попытки положить конец богохульным деяниям троллей закончились неудачей. Я вдохнул частицу своей души в этот кристалл. Однако я чувствую, что моя связь с Изумрудным Сном теряется, и меня поглощает хаос. Пожалуйста, помести этот кристалл в купель сущности в моём логове — пусть магия очистит моё сознание от скверны и спасёт меня!\"" },
    ["3373c"] = { common = "Вы помещаете камень в купель сущности. \"Благодарю тебя, смертный, теперь я… О нет! Не может быть! Скверна проклятого бога проникла даже в эту купель! Умоляю! Я чувствую, как сознание покидает меня! БОЛЬНО! Я чувствую, как мою душу поглощает вечный кошмар!\" \"Умоляю тебя, смертный! Найди одного из зелёных драконов, чтобы он смог прекратить мои мучения! Помоги мне! Я обречён на вечную агонию… Пощади!\"" },
    ["3374a"] = { common = "Вы приводите в действие Камень клятвы и с его помощью Итар мысленно заговаривает с вами. \"Приняв силу, заключённую в камне Клятвы, ты соглашаешься помочь мне и драконьему выводку Изеры освободить истерзанную душу Эраникуса. Первая из многих жертв, на которую придётся пойти и тебе, и мне — это передать мне камень, в котором заключено то, что осталось от свободной воли Эраникуса. Сделай это, путник, и дальше мы будем действовать вместе, чтобы освободить достойную многих жертв душу.\"" },
    ["3375a"] = { male = "Хм... тебе нужен ещё один фиал виденья? Шутишь? А куда ты дел прежний?! У нас и так забот полон рот, герой. Эти фиалы на деревьях не растут! Хорошо бы, чтобы росли, я тогда пошёл бы да сорвал, потому как другого-то у меня нет! А чтобы сделать тебе новый, мне нужно следующее: зелье маны, кусок угля и немного сладкого нектара. И не спрашивай зачем, просто принеси, я и тебе сделаю новый.", female = "Хм... тебе нужен ещё один фиал виденья? Шутишь? А куда ты дела прежний?! У нас и так забот полон рот, героиня. Эти фиалы на деревьях не растут! Хорошо бы, чтобы росли, я тогда пошёл бы да сорвал, потому как другого-то у меня нет! А чтобы сделать тебе новый, мне нужно следующее: зелье маны, кусок угля и немного сладкого нектара. И не спрашивай зачем, просто принеси, я и тебе сделаю новый." },
    ["3375c"] = { male = "Могучий искатель приключений всё принёс. Слава мне! Кстати, я соврал – у меня был запасной фиал. Вот. А чего ты ожидал?! \"Нате-пожалуйста вам другой! Мне, дураку, делать больше нечего, кроме как задарма раздавать магические устройства связи искателям приключений!\" Но ты не беспокойся, всё, что ты мне дал, пойдёт на изготовление для тебя очередного фиала, когда ты и этот посеешь. Пожалуйста, пусть я ошибусь в тебе – не потеряй ещё и этот, ладно?", female = "Могучий искатель приключений всё принёс. Слава мне! Кстати, я соврал – у меня был запасной фиал. Вот. А чего ты ожидала?! \"Нате-пожалуйста вам другой! Мне, дураку, делать больше нечего, кроме как задарма раздавать магические устройства связи искателям приключений!\" Но ты не беспокойся, всё, что ты мне дала, пойдёт на изготовление для тебя очередного фиала, когда ты и этот посеешь. Пожалуйста, пусть я ошибусь в тебе – не потеряй ещё и этот, ладно?" },
    ["3376a"] = { male = "путник – я слыхала о тебе. Возможно, именно тебе удастся то, что не удалось другим. Мы, таурены, сделали это место своим домом, но это далось нам дорогой ценой. Дыбогривые свинобразы из клана Вздыбленной Щетины под предводительством вождя Остроклыка Терновой Мантии не дают нам покоя своими набегами. Я хочу, чтобы ты принёс мне голову их вождя! Ты найдёшь его в одной из кустарных хижин в Ежевичной лощине к востоку отсюда.", female = "путница – я слыхала о тебе. Возможно, именно тебе удастся то, что не удалось другим. Мы, таурены, сделали это место своим домом, но это далось нам дорогой ценой. Дыбогривые свинобразы из клана Вздыбленной Щетины под предводительством вождя Остроклыка Терновой Мантии не дают нам покоя своими набегами. Я хочу, чтобы ты принесла мне голову их вождя! Ты найдёшь его в одной из кустарных хижин в Ежевичной лощине к востоку отсюда." },
    ["3376c"] = { male = "Само правосудие сегодня направляло твою руку. Да будет твоё деяние предостережением для всех, кто осмелится угрожать нашему дому! Ты заслужил эту награду, юный герой.", female = "Само правосудие сегодня направляло твою руку. Да будет твоё деяние предостережением для всех, кто осмелится угрожать нашему дому! Ты заслужила эту награду, юная героиня." },
    ["3377a"] = { male = "Мне нужна твоя помощь, смертный. Выслушай меня!", female = "Мне нужна твоя помощь, смертная. Выслушай меня!" },
    ["3377c"] = { common = "Я смирился с тем, что отныне моя судьба – эта клетка, но молитву нужно найти!" },
    ["3378a"] = { male = "Ты поможешь мне, смертный? Ты отыщешь молитву Элуне? Как я говорил, молитва выгравирована на золотой табличке, которая теперь, видимо, у одного из этих мерзких идолопоклонников. Если ты сможешь отыскать её, отнеси табличку Астарии Ловцу Звёзд в Дарнасс. Пусть я пришёл к вере после того, как совершил много зла этому миру и его обитателям, моя молитва должна быть услышана. А на прощение своих грехов я не надеюсь...", female = "Ты поможешь мне, смертная? Ты отыщешь молитву Элуне? Как я говорил, молитва выгравирована на золотой табличке, которая теперь, видимо, у одного из этих мерзких идолопоклонников. Если ты сможешь отыскать её, отнеси табличку Астарии Ловцу Звёзд в Дарнасс. Пусть я пришёл к вере после того, как совершил много зла этому миру и его обитателям, моя молитва должна быть услышана. А на прощение своих грехов я не надеюсь..." },
    ["3378c"] = { male = "Элуна улыбается тебе. Ты возвратил к ней потерянную душу. Прими это в знак нашей благодарности.", female = "Элуна улыбается тебе. Ты возвратила к ней потерянную душу. Прими это в знак нашей благодарности." },
    ["3379a"] = { common = "Пауки, которые водятся в Тлеющем ущелье, производят бесценный тенешёлк. Как ты знаешь, тенешёлк необходим для нашего ремесла. Не так давно в этих землях появилась шайка браконьеров, бессовестно убивающих пауков в погоне за сиюминутной прибылью. Твоя задача проста: найти их и прикончить. Начни поиски с северных пределов. Если потребуется помощь, обращайся к Пожару." },
    ["3379c"] = { common = "Отличная работа. Прими это в награду – уверена, подобной работы из тенеткани тебе ещё не встречалось!" },
    ["3380a"] = { common = "Этот мир полон беспокойных духов, путник. Среди них есть такие, которые оказались скованы в местах, в которых таится древнее зло, и были поражены скверной. Слыхал я о храме, сокрытом в глубинах болот — он был погружён туда силами, величие которых недоступно сознанию простого смертного. Если хочешь узнать больше о затонувшем храме, отыщи гоблина по имени Марвон Клепальщик. Он облазал многие развалины и останки древних поселений. Слыхал я, что недавно он отправился изучать развалины строений троллей в Танарисе." },
    ["3380c"] = { common = "О да, я видел затонувший храм собственными глазами. Хочешь узнать о нём побольше? Уж я сразу узнаю настоящего искателя приключений!" },
    ["3382a"] = { common = "Мы плыли вдоль берега, в поисках места, где бросить якорь. Солнце зашло не более часа назад, и тут они на нас напали. Проклятые наги! Не знаю, что им было нужно, но они явно этого не нашли. Почему я в этом уверена? Потому что они вернулись! Я оставила пару своих людей охранять долину, чтобы они предупредили нас в случае атаки. Мне жаль, что ты оказался втянутым в эту заварушку, но увы, ничего уже нельзя сделать. Ты готов биться не на жизнь, а на смерть?" },
    ["3382c"] = { common = "Ты сделал это! Спасибо тебе! Это была одна из самых жестоких битв что я когда-либо видела! Я никогда не смогу тебя отблагодарить, как полагается! Я желаю только одного — чтобы как можно больше людей из моего экипажа пережили эту ловушку… Поговори с любыми из уцелевших пассажиров из Покорителя Горизонтов. Кое-кто из них имеет здесь дела, и ты можешь помочь им. И ещё раз благодарю тебя за твою помощь!" },
    ["3385a"] = { common = "Они называют себя Чёрным рынком – шайка головорезов, которые готовы купить, продать и украсть что угодно, если цена будет подходящей. И что ещё хуже, они устроили себе логово в Тлеющем ущелье. Искусный торговец Ковиц – их главарь. У него есть связи с местными дворфами клана Чёрного Железа. Мы должны нанести по ним мощный удар и недвусмысленно дать понять, что здесь им не рады. Убей торговца Ковица и его прихвостня Лязгуна. Принеси мне сумку торговца. Отправляйся в Котёл немедля!" },
    ["3385c"] = { male = "Ты нанёс решающий удар по Чёрному рынку. Теперь эти бандиты дважды подумают, прежде чем отправлять сюда кого-то из своих. Я осмотрела сумку – в ней нет ничего полезного. Если тебе приглянется что-то из его барахла, можешь смело оставить себе.", female = "Ты нанесла решающий удар по Чёрному рынку. Теперь эти бандиты дважды подумают, прежде чем отправлять сюда кого-то из своих. Я осмотрела сумку – в ней нет ничего полезного. Если тебе приглянется что-то из его барахла, можешь смело оставить себе." },
    ["3402a"] = { male = "Мне нужно, чтобы ты лично донёс весть о кончине Ковиса Визглику в Прибамбасск. Он будет так рад, что непременно щедро наградит тебя.", female = "Мне нужно, чтобы ты лично донесла весть о кончине Ковиса Визглику в Прибамбасск. Он будет так рад, что непременно щедро наградит тебя." },
    ["3402c"] = { common = "Ковис убит? О, счастье! Столько лет этот прохвост творил что хотел, обтяпывал незаконные сделки, устанавливал бессовестно низкие цены, разоряя нас, честных тружеников!" },
    ["3441a"] = { male = "Выслушай меня, cтранник.", female = "Выслушай меня, странница." },
    ["3441c"] = { male = "Тебе всё ясно, путник? Ты готов действовать?", female = "Тебе всё ясно, путница? Ты готова действовать?" },
    ["3442a"] = { male = "Ты принял правильное решение. Надо нанести удар по самому уязвимому месту – четырём сторожевым башням. Тебе потребуется особый факел, чтобы поджечь их. Над его изготовлением придётся потрудиться, кроме того, нужно добыть необходимые ингредиенты. Принеси мне четыре сердца пламени и четыре меры масла големов, и тогда я сделаю для тебя факел, чьё пламя будет неугасимым. Чтобы достать эти ингредиенты, ищи големов и элементалей.", female = "Ты приняла правильное решение. Надо нанести удар по самому уязвимому месту – четырём сторожевым башням. Тебе потребуется особый факел, чтобы поджечь их. Над его изготовлением придётся потрудиться, кроме того, нужно добыть необходимые ингредиенты. Принеси мне четыре сердца пламени и четыре меры масла големов, и тогда я сделаю для тебя факел, чьё пламя будет неугасимым. Чтобы достать эти ингредиенты, ищи големов и элементалей." },
    ["3442c"] = { common = "Прекрасно. Всё готово к работе." },
    ["3443a"] = { common = "Чтобы удержать неугасимое пламя факела, нам необходимо создать особое древко и наложить защитные чары. Начнём с древка. В Котловане надсмотрщики и работорговцы из клана Чёрного Железа используют оружие из зачарованного тория – особенно прочного сплава. Если ты принесёшь мне восемь окованных торием кинжалов, я смогу выплавить торий и использовать его для укрепления древка." },
    ["3443c"] = { male = "Отличная работа, я просто поражён! Ты не задумывался о смене профессии? Чтобы стать, скажем, детективом? Ну или старьёвщиком? Или примкнуть к этим глупеньким гномам, ползающим по побережьям с металлоискателями в поисках сокровищ? Это ведь наверняка твоё призвание!", female = "Отличная работа, я просто поражён! Ты не задумывалась о смене профессии? Чтобы стать, скажем, детективом? Ну или старьёвщиком? Или примкнуть к этим глупеньким гномам, ползающим по побережьям с металлоискателями в поисках сокровищ? Это ведь наверняка твоё призвание!" },
    ["3444a"] = { common = "Мне приходилось бывать в преддвериях затонувшего храма. Зло, таящееся в этом жутком месте окутывает всякого, кто входит туда. Я едва смог выбраться обратно, увязая в липкой грязи, покрывающей пол. Помню, есть там огромный круглый зал со множеством высеченных из камня змей. Не так давно мне попал в руки круглый камень, на котором была высечена подобная змея. Я велел послать его в мою мастерскую в Кабестане. Забери его оттуда, и, возможно, я смогу ответить на твои вопросы." },
    ["3444c"] = { common = "Да… этот камень… Ко мне снова возвращается память, путник…" },
    ["3445a"] = { common = "Слыхала я о храме, сокрытом в глубинах болот — он был погружён туда силами, величие которых недоступно сознанию простого смертного. Если хочешь узнать больше о затонувшем храме, отыщи гоблина по имени Марвон Клепальщик. Также как и мы с Троясом, он облазал многие развалины и останки древних поселений. Слыхала я, что он отправился изучать развалины строений троллей в Танарисе. Удачи в поисках, о нём давненько ничего не слышали!" },
    ["3445c"] = { common = "Да, Затонувший Храм, я видел его своими собственными глазами! Возможно ты хочешь услышать о нём побольше? Ха, да ты сам выглядишь как искатель приключений! У меня есть кое-что, что может тебя заинтересовать…" },
    ["3446a"] = { common = "В храме я видел круглый зал с шестью галереями, каждую из которых украшала змея, высеченная из камня. Я всего лишь дотронулся до одной из них и угодил в ловушку! Произошёл сильнейший взрыв — мне несказанно повезло, что остался цел. Лёжа там, на краю галереи, я заметил ещё одну статую в самом низу зала — что-то вроде алтаря. Алтарь Хаккара, полагаю. Положи на алтарь этот знак — думаю, это поможет открыть его секреты." },
    ["3446c"] = { common = "Вы помещаете круглый камень в углубление и слышите негромкий щелчок. Теперь камень на положенном ему месте… Но что же делать дальше? Пожалуй, стоит осмотреть алтарь…" },
    ["3447a"] = { common = "Всё, что я видел в храме, сохранилось в моей памяти лишь урывками, но я постараюсь рассказать тебе всё как можно подробней. Круг статуй, сокрытый в храме — весьма опасное место, но я уверен, что там спрятан ключ к великим сокровищам. Когда я подошёл к главному алтарю, в зале зажглись огни. Если тебе удастся разгадать, что они значат, возможно, сумеешь понять и тайны, которые скрывает эта комната. Однако я должен предупредить тебя, путник. В храме заключено великое зло. Какие бы сокровища там не скрывались, древние силы будут яростно защищать их от посягательств." },
    ["3447c"] = { common = "Глаз идола мерцает мрачно и загадочно в полутьме храма. Какое-то сияние… внутри статуи! Нужно посмотреть поближе… Сокровище Атал'ай теперь ваше!" },
    ["3448a"] = { common = "Недавно мне доверили задачу исследования Азшары — некогда прекрасного края, который эльфы называли домом. Это было в те времена, когда они занимались магией. Теперь же это место скорее опасно, чем прекрасно, но это не остановит нас. Мы перевернём его по камушку, чтобы разгадать загадки нашего прошлого. Мой товарищ Тимор предложил мне помощь в исследованиях, поскольку это и его самого особенно интересует. У него здесь в городе есть небольшой дом рядом с Залом Тайн." },
    ["3448c"] = { common = "Ах, так вас послал Карик? Я как раз ждал от него известий. Я тут такое узнал об Азшаре… Я знаю, что ночные эльфы живут невероятно долго, но все порой забывают о некоторых… неприятных событиях в их жизни. Это не критика, всего лишь замечание. Давным-давно там существовали города, возведённые эльфами, которые много знали о магии и других утраченных искусствах. Поскольку я такие вещи изучаю, я начал свои исследования. И открытия мои просто ошеломляющи." },
    ["3449a"] = { common = "Некоторые эльфы в старину почитали магию не меньше самой Элуны. Их самые могущественные маги создали руны и таблички, в которых были перечислены законы чародейства и разгадки их открытий. Они, как правило, выставляли их на всеобщее обозрение, чтобы все могли над ними поразмышлять. Я был бы очень рад получить прорисовки этих рун из руин Эльдарата. Чтобы сделать прорисовки, я дам вам готовальню, но найти их должны вы сами. Будьте осторожны, не только лига Исследователей имеет свои интересы в Эльдарате." },
    ["3449c"] = { common = "Рад видеть вас в целости и сохранности, путник. Надеюсь, дело оказалось для вас не слишком трудным. Доставлю их Тимору прямо сейчас. Он просто с ума сойдёт от радости. Да выбросьте вы это сигнальное ружье… оно всё равно вам уже ни к чему, да у меня и другое есть." },
    ["3450a"] = { common = "Я хочу, чтобы эти прорисовки были доставлены мне в башню, но вам незачем лично проделывать весь этот путь. Пусть их просто доставят из Азшары по воздуху. У Хиггса Раздувателя Горна есть перед мной должок, к тому же он скоро окажется в тех местах — он назначен патрулировать побережье. Поговорите с ним перед отъездом. Он даст вам сигнальное ружьё, чтобы вы могли подать ему сигнал. Когда добудете прорисовки, отправляйтесь в условленное место и отдайте их ему, чтобы он доставил их в мою башню в целости и сохранности. Он должен быть в ангаре в Палатах Войны." },
    ["3450c"] = { common = "Чем могу помочь, путник? Я как бы занят сейчас — готовлю аппаратик свой к долгому полёту. Я тут зашёл поговорить с водителями танков — мне нужны гривы вендиго, чтобы кабину утеплить, а у них обычно есть. Так что уделить вам могу не больше минуты… один парень только что пошёл в депо Посёлок Сталежара, чтобы посмотреть, найдутся ли у них для меня гривы." },
    ["3451a"] = { common = "А, так вас послал Тимор? Да, есть у меня перед ним должок. Это что? Ах, поганец! Ладно, я ему помогу. Значит, вам нужны сигнальное ружьё и условленная точка… да легко. Близ южного мыса Азшары есть небольшой островок, где мы соорудили посадочную площадку. Берёте ружье и даёте оттуда сигнал. Я вижу сигнал и прилетаю забрать это… ну, что ему надо." },
    ["3451c"] = { common = "Вот вам сигнальное ружьё. Когда дадите сигнал, запаситесь терпением — в нём всего два патрона, а мне потребуется несколько минут, чтобы добраться до вас, в зависимости от того, насколько далеко над морем я буду. Выстрелите из ружья — и полюбуйтесь на море." },
    ["3452a"] = { common = "Работа над факелом близится к завершению. Не хватет лишь одного компонента. В горах к северо-западу отсюда есть большой лагерь Сумеречного Молота. Говорят, они носят при себе некие символы и идолов в дань уважения своему богу. Полагаю, в этих символах и идолах заключены чары достаточной силы для создания магической брони. Принеси мне знак Рагнароса, и я попытаюсь извлечь из него его магическую силу, чтобы создать защитные чары для факела." },
    ["3452c"] = { common = "Символ источает злые чары – именно они и требуются для завершения работы над факелом." },
    ["3453a"] = { common = "Мне нужно несколько минут, чтобы сложить вместе все части и наложить чары." },
    ["3453c"] = { male = "Есть ещё одно, последнее задание, которое ты должен выполнить.", female = "Есть ещё одно, последнее задание, которое ты должна выполнить." },
    ["3454a"] = { common = "Факел готов и отныне связан со своим владельцем. Возьми его." },
    ["3454c"] = { common = "Вы хватаете факел обеими руками и ощущаете исходящие от него волны гнева и ненависти." },
    ["3461a"] = { common = "Тимор не оставил мне ничего, чтобы вам заплатить, потому предлагаю вам обсудить награду лично с ним, когда вернётесь в Стальгорн. Я уверен, что он до сих пор у себя в Палатах Магии. Постучитесь и потребуйте щедрой платы, потому как местечко-то не для пикника… это уж точно. Всё же благодарю вас, что вы ему помогли, и желаю удачи. Ой, готовальня мне ни к чему. Почему бы вам просто не отдать её лично Тимору, когда вы с ним встретитесь?" },
    ["3461c"] = { common = "Отлично! Я так рад это слышать. Как мне не терпится вернуться в мою башню и поработать над прорисовками… Я так завидую вам! Побывать в Азшаре… думаю, это мечта всех изучающих чародейские науки. Ладно, хотя мы и не говорили о награде, поскольку вы работаете на лигу Исследователей, но вы её заслуживаете." },
    ["3462a"] = { common = "Поговори с моим посыльным, оруженосцем Малтрейком. Он объяснит тебе, как использовать факел." },
    ["3462c"] = { male = "Ты готов нанести удар?", female = "Ты готова нанести удар?" },
    ["3463a"] = { common = "Слушай меня внимательно, путник. Четыре башни нельзя разрушить, но если поджечь их с помощью факела воздаяния, пламя не угаснет очень долго — и это пламя нельзя будет унять никакими силами. Пока башни горят, ни один страж или караульный не сможет подняться на них — а значит, первая линия обороны противника фактически будет прорвана. Ты должен пробраться в башни и поджечь их с помощью факела воздаяния. И берегись патрульных Чёрного Железа!" },
    ["3463c"] = { common = "Славное деяние!" },
    ["3481a"] = { common = "Похоже, сундук заперт." },
    ["3481c"] = { common = "Замок открывается, как только вы прикасаетесь к нему. Любопытно, сколько же может быть внутри сокровищ? Есть только один способ узнать." },
    ["3504a"] = { common = "Предательница и воровка! Других слов для неё у меня нет! Наверное, я сделал большую ошибку, путник. Я доверился эльфу крови. Хуже того — я доверился бабе! Она уверяла, будто в Азшаре хранятся несметные сокровища… могущественные артефакты… Всё, что нужно, — это отправить с ней нескольких воинов для охраны, и она меня щедро вознаградит. Ну, и кто остался в дураках? Она их всех перебила! Я жажду мести, путник. Но посылать туда других воинов я уже не могу. Найди Аг'тора в Храбростане, к северу от лагеря Халдарр. Он тебе скажет, что делать дальше." },
    ["3504c"] = { common = "Мы послали всех кого только могли на неё и на её прислужников… Но никто не вернулся. Часть, вероятно, погибла, но я уверен, что некоторые трусы просто сбежали! Но теперь прибыли подкрепления! И мы сразим её, за её ложь… и за то, что она предала Белгрома. Так ты с нами?" },
    ["3505a"] = { common = "Так я и думал. Мы начнём наступать на её приспешников от южных утёсов северного полуострова Азшары. Убивайте их, не зная пощады — пусть знают, кого предали! Насчёт её самой пока не тревожьтесь — она проводит большую часть времени, рыская по Азшаре вместе со своими телохранителями. После того как перебьёте её работников, стоит отыскать её личный лагерь. Нужно сначала разведать, откуда можно на неё напасть. Может быть, стоит как-нибудь выманить её из лагеря…" },
    ["3505c"] = { common = "Вы начинаете листать страницы, пока не доходите до той, что обозначена тонкой чёрной полоской шелка. Пытаясь разобрать текст, вы видите диаграмму в конце одной из страниц. Неожиданно вы понимаете, что кристаллы, круг и другие объекты на земле расставлены в порядке подобном изображённому диаграмме." },
    ["3506a"] = { common = "Вы поразмыслили ещё немного, и вам на ум пришло сразу несколько идей, одна из которых заставила улыбнуться: возможно, если вы уничтожите кристаллы, подлая эльфийка, погубившая стольких орков, достаточно разозлится? Вы продолжаете разбирать текст и рисунки и понимаете, что один из кристаллов связан с создателем круга — прочие же связаны с куда более жуткими тварями. Вы закрываете книгу и начинаете прикидывать, какой из кристаллов следует уничтожить." },
    ["3506c"] = { common = "Аргх! Невероятно! Ты сделал это! Белгром будет доволен. Наконец-то духи сотен наших воинов будут упокоены в мире. Спасибо тебе, путник." },
    ["3507a"] = { common = "Вернись в Оргриммар к Белгрому. Он захочет увидеть её голову своими глазами! Мы там тоже скоро будем. Удачный у нас денёк! Спасибо за помощь, путник." },
    ["3507c"] = { common = "А, предательница, я спляшу джигу на твоих костях! Спасибо тебе, путник! Я бы дал тебе королевство, если бы это было в моих силах! Но возможно тебя удовлетворит вот это. Ха-ха! Глупый эльф крови, посмотри на себя теперь… голова в мешке, а тело-то твоё где, глупый эльф крови? Никогда не предавай больше Белгрома!" },
    ["3508a"] = { common = "Тебе свойственна безрассудная храбрость, путник. Это ценное качество твоего рода — слепо кидаться в битву, почти не имея шансов на успех. Я помогу тебе, хотя бы только ради того, чтобы увидеть смерть приспешников Разелиха. Однако для того, чтобы пробиться через охранные чары, окружающие их, требуется время, равно как и использование редких артефактов. Не нарушай тишину, я должен исполнить ритуал просветления. Сведения, которые я получу, помогут мне отковать оружие великой мощи." },
    ["3508c"] = { common = "Имя этой твари должно быть найдено." },
    ["3509a"] = { common = "Существует лишь один способ причинить вред повелителю демонов и его приспешникам. Следует выковать оружие силы, несущее его истинное имя. Когда такое оружие будет выковано, демон и всё, кем он повелевает, станут уязвимы. В Азшаре обитает меньшее божество: лорд Арккорос. Тебе следует найти его. Однако осторожнее: его слуги не остановятся ни перед чем, чтобы убить тебя, если обнаружат. Несомненно, за такие сведения придётся заплатить." },
    ["3511c"] = { common = "Эта смесь как раз то что мне требуется для изготовления оружия. Но в его создании остался ещё один этап." },
    ["3512c"] = { common = "Итар поступил мудро, послав тебя ко мне. Пока он не мёртв… в том смысле, в каком вы понимаете смерть. Следовательно, мы можем помочь Эраникусу. Но вот как раз с этим у меня возникли определённые проблемы." },
    ["3513a"] = { common = "Свиток официального вида перевязан серебристой лентой. Несомненно, кому-то он был бы весьма интересен, но кому? На севере, рядом с границей Ясеневого леса, есть застава, и если в свитке идёт речь о ночных эльфах, именно туда его и надо отнести." },
    ["3513c"] = { male = "Та-ак... И где ты это нашёл?", female = "Та-ак... И где ты это нашла?" },
    ["3514a"] = { male = "Это послание от коварной дриады Ринтариэль, Хранительницы Ключей Пещеры Когтей на Пике Каменного Когтя. Она уже не встретится с гонцом, у которого ты нашёл этот свиток, хе-хе, но так просто им это не пройдёт. Орда не потерпит такого нахальства. Ступай в Пещеру Когтей. Убей Ринтариэль и покажи это всем. Возьми с собой флаг Орды и установи его в Пещере Когтей у всех на виду. В другой раз они трижды подумают, прежде чем снова соваться в наши земли.", female = "Это послание от коварной дриады Ринтариэль, Хранительницы Ключей Пещеры Когтей на Пике Каменного Когтя. Она уже не встретится с гонцом, у которого ты нашла этот свиток, хе-хе, но так просто им это не пройдёт. Орда не потерпит такого нахальства. Ступай в Пещеру Когтей. Убей Ринтариэль и покажи это всем. Возьми с собой флаг Орды и установи его в Пещере Когтей у всех на виду. В другой раз они трижды подумают, прежде чем снова соваться в наши земли." },
    ["3514c"] = { male = "Да ты силён! Это большое дело – лишить Логово Когтя Ринтариэль. Наши противники не сразу оправятся от потери, и в ближайшее время в Степи будет проникать меньше лазутчиков Альянса. Они подумают дважды, чем прежде чем снова соваться к нам. Спасибо.", female = "Да ты сильна! Это большое дело – лишить Логово Когтя Ринтариэль. Наши противники не сразу оправятся от потери, и в ближайшее время в Степи будет проникать меньше лазутчиков Альянса. Они подумают дважды, чем прежде чем снова соваться к нам. Спасибо." },
    ["3517a"] = { common = "Ты знаешь, путник, я, в общем, неплохо устроилась в Азшаре. У наказания Белгрома, обрушившегося на мою голову, есть свои положительные стороны. Я тут полазала по окрестностям и обнаружила просто уйму ценностей, валяющихся без дела. Если интересно, могу рассказать подробнее и даже поделюсь прибылью, если поможешь мне добыть кое-что. В руинах Эльдарата к востоку отсюда сокрыты четыре таблички. Каждая из них носит имя мага высокорожденных. Принеси мне их, и мы поговорим о дальнейшем сотрудничестве." },
    ["3517c"] = { common = "Прекрасно, путник, и они ещё в хорошем состоянии! Это означает хорошую цену у заинтересованных лиц… Так что давай не тратить больше времени чем необходимо." },
    ["3518a"] = { common = "Первую табличку нужно отнести таурену по имени Магата. Ты найдёшь её среди старейшин Громового Утёса. Она самая ярая сторонница заключения союза тауренов с Отрекшимися, ибо считает, что именно таурены и их обычаи могут помочь Отрекшимся вновь найти путь к обретению человеческой природы. Отнеси ей табличку Бет'Амары. Тауренка считает, что может найти в табличке способ, как помочь Отрекшимся… ну да, по крайней мере она в это верит." },
    ["3518c"] = { common = "А, наконец-то, Табличка Бет'Амары. Я уже беспокоилась, неужели моё соглашение с Джедигой уже не действует, или бедная оркиня нашла, наконец, свою смерть в Азшаре. Рада, что у неё получилось! Бет'Амара была одной из лучших алхимиков Высокорожденных. Один маг сказал, что она умела трансмутировать металлы, что является высшим достижением алхимии!" },
    ["3519a"] = { common = "Ох... меня сильно покусала паучиха по имени Гитьис Зловещая, когда я обследовал паучиную пещеру. Похоже, я серьёзно отравлен. Помоги мне! Пожалуйста, дай знать Дирании Серебряному Сиянию. Она сможет помочь мне. Спеши... Как голова кружится…" },
    ["3519c"] = { common = "Ох, какая беда, а я-то думала, что это сегодня Иверрона не видно... Предупреждала же я его насчёт пауков!" },
    ["3520a"] = { common = "Мне нужны духи дольных крикунов из Фераласа. Они родственники старого-престарого бога и напрямую связаны с ним. Возьми ежевичный посох и ступай в Фералас. Отыщи в южной и центральной части дольных крикунов и одержи над ними верх. Потом помаши моим посохом над их телами. Таким образом ты выманишь их души. Коснись каждой из душ и собери их сущности. Принеси мне посох и собранные сущности, и я расскажу тебе о том старом боге." },
    ["3520c"] = { common = "Молодец. Пожалуй, пришло время рассказать тебе правду… У троллей существует пророчество о возвращении на землю убитого бога, Хаккара Свежевателя Душ. Некоторые говорят, что пришествие Хаккара принесёт троллям радость и славу, другие же ждут лишь конца всего сущего. Я не верю в этот миф, но не сомневаюсь, что сущность Хаккара таит в себе великую силу, которая не должна попасть в руки недостойных..." },
    ["3521a"] = { common = "Мы могли бы помочь Иверрону: я знаю противоядие, которое нейтрализует действие яда. Но для него мне нужны некоторые ингредиенты. Мне понадобятся гиацинтовые грибы. Их можно найти под деревьями или добыть у греллей к югу отсюда – похоже, они им по вкусу. Ещё мне нужны лунные лилии, что растут только вокруг прудов. Последний ингредиент добыть сложнее всего. Это лимфа тех самых чащобных тенётников, что отравили Иверрона." },
    ["3521c"] = { male = "Хвала Элуне – ты так быстро собрал все ингредиенты! Подожди минутку, сейчас я приготовлю противоядие.", female = "Хвала Элуне – ты так быстро собрала все ингредиенты! Подожди минутку, сейчас я приготовлю противоядие." },
    ["3522a"] = { common = "Противоядие готово. Пожалуйста, проследи, чтобы Иверрон его выпил. И запомни – это важно: противоядие будет обладать своими целебными свойствами в течение пяти минут. Необходимо доставить его до истечения этого времени. Поторопись, во имя Элуны!" },
    ["3522c"] = { male = "Что это? Я знал, что Дирания поможет мне! *Иверрон выпивает противоядие.* Я всё время попадаю в переделки, а Дирания постоянно меня из них вытаскивает. Мне стало намного лучше, хотя, пожалуй, я немного посижу тут, пока совсем не приду в себя. Что ж, надеюсь, ты расчистил мне дорогу через этот лес, полный мерзостных чащобных тенётников...", female = "Что это? Я знал, что Дирания поможет мне! *Иверрон выпивает противоядие.* Я всё время попадаю в переделки, а Дирания постоянно меня из них вытаскивает. Мне стало намного лучше, хотя, пожалуй, я немного посижу тут, пока совсем не приду в себя. Что ж, надеюсь, ты расчистила мне дорогу через этот лес, полный мерзостных чащобных тенётников..." },
    ["3523a"] = { male = "Благодарю, что спас меня! Имя мне Белнистраз. Не хотелось бы закончить жизнь столь бесславно – быть сожранным одной из омерзительных тварей Плети. Да-да, ты не ослышался, Плеть вступила в союз с местными свинобразами. Послушай... вместо того, чтобы бежать, спасая собственную жизнь, я бы предпочёл вступить с врагом в бой, чтобы защитить невинных. Нек желаешь ли ты мне помочь? Это опасно, но ты явно не из тех, кто пасует перед трудностями.", female = "Благодарю, что спасла меня! Имя мне Белнистраз. Не хотелось бы закончить жизнь столь бесславно – быть сожранным одной из омерзительных тварей Плети. Да-да, ты не ослышалась, Плеть вступила в союз с местными свинобразами. Послушай... вместо того, чтобы бежать, спасая собственную жизнь, я бы предпочёл вступить с врагом в бой, чтобы защитить невинных. Нек желаешь ли ты мне помочь? Это опасно, но ты явно не из тех, кто пасует перед трудностями." },
    ["3523c"] = { common = "Весьма похвально. Я знал, что из тех, кто захочет взяться за это непростое и опасное дело. Не скрою, нам предстоит тяжёлая работа. Но мы должны приложить все усилия и справиться с ней. Послушай, я введу тебя в курс дела..." },
    ["3524a"] = { common = "Громадные морские твари выбрасываются на пески Тёмного Берега и лежат там, пока не умирают. В последнее время останки этих тварей выносит на берег всё чаще и чаще. Меня послали сюда из Храма Луны для расследования ситуации, но наличие мурлоков у береговой линии затрудняет мою задачу. Одни такие останки лежат на юге от Аубердина, совсем рядом, но вокруг очень много злобных мурлоков из клана Серой Мглы. Не могли бы вы сходить туда и принести мне для изучения кости этой твари?" },
    ["3524c"] = { common = "Я надеюсь, что мурлоки не слишком досаждали вам, пока вы собирали для нас эти кости! Я непременно следующим же гиппогрифом доставлю их в Дарнасс. Храм Луны снабдил меня некоторыми средствами, которыми я могла бы расплачиваться за помощь; пожалуйста, примите немного денег вместе с нашей благодарностью. Ваш успех побуждает меня предложить вам возможность и дальше оказывать помощь Храму Луны, если вы заинтересованы в этом..." },
    ["3525a"] = { male = "Рядом с входом ты увидишь идола – свинобразы используют его как жертвенный очаг. Эти твари на самом деле пожирают своих пленников из Степей. Я должен разбить идола, чтобы они более никогда не могли его использовать, но мне потребуется твоя помощь. Сопроводи меня к идолу. Там я проведу ритуал, но при этом я даже не смогу говорить с тобой, не говоря уж о том, чтобы самому защитить себя. Тебе придётся держать оборону, пока я буду проводить ритуал. Если меня убьют раньше, чем я закончу, это будет означать крах всех наших планов. Ты готов?", female = "Рядом с входом ты увидишь идола – свинобразы используют его как жертвенный очаг. Эти твари на самом деле пожирают своих пленников из Степей. Я должен разбить идола, чтобы они более никогда не могли его использовать, но мне потребуется твоя помощь. Сопроводи меня к идолу. Там я проведу ритуал, но при этом я даже не смогу говорить с тобой, не говоря уж о том, чтобы самому защитить себя. Тебе придётся держать оборону, пока я буду проводить ритуал. Если меня убьют раньше, чем я закончу, это будет означать крах всех наших планов. Ты готова?" },
    ["3525c"] = { common = "Белнистраз исчезает, оставив на месте себя пылающее зарево. Вы видите в пламени очертания огромного крылатого красного дракона. Рокочущий голос Белнистраза наполняет ваше сознание. \"Я всегда верил в вашу смелость, смертные. Благодаря тебе кровавым делам, вершимым здесь этими тварями, пришёл конец. Моя вера в мужественность смертных созданий сегодня укрепилась. Прими эту награду – она достойна героя.\"" },
    ["3526a"] = { common = "Инженерам-умельцам приходится выбирать между двумя школами инженерного дела: гномской и гоблинской. Очевидно, что наиболее талантливые инженеры предпочитают гоблинскую. Покори же мир с помощью отборной взрывчатки и фантастических механизмов! Прочитай этот учебник. Если ты хочешь поучиться гоблинскому инженерному делу, поговори с Никсом Шепружином в Прибамбасске. Помни: сделав выбор единожды, ты не сможешь передумать. Поэтому хорошо подумай, прежде чем браться за задание Никса." },
    ["3526c"] = { male = "Что же, ты нашёл подходящего учителя! Любой болван может освоить основы инженерного дела – как доказали гномы и их радиоактивный Гномреган. Требуется острый ум и верная рука (повторяю: ВЕРНАЯ), чтобы освоить премудрости гоблинского инженерного дела. Держи ушки на макушке, тогда чему-нибудь научишься.", female = "Что же, ты нашла подходящего учителя! Любой болван может освоить основы инженерного дела – как доказали гномы и их радиоактивный Гномреган. Требуется острый ум и верная рука (повторяю: ВЕРНАЯ), чтобы освоить премудрости гоблинского инженерного дела. Держи ушки на макушке, тогда чему-нибудь научишься." },
    ["3527a"] = { common = "Древнее пророчество Мошару повествует о том, как взять в плен сущность бога Хаккара. Пророчество записали на двух табличках и отнесли в тролльский город Зул'Фаррак, что к западу от Прибамбасска. Принеси мне таблички Мошару! Первая табличка находится у давно умершего тролля Теки Мученика. Говорят, что его истязатели превратились в скарабеев и до сих пор ползают по его святилищу. Вторая табличка – у гидроманта Велраты, рядом со священным озером Газ'риллы. Добудешь таблички – сразу приходи." },
    ["3527c"] = { common = "О, замечательно. Я соединю эти таблички и раскрою их секреты. Я давно твой должник. И, боюсь, мой долг будет только расти." },
    ["3528a"] = { common = "Пришло время брать в плен сущность аватары Хаккара. Отнеси яйцо Хаккара в святилище Падшего Бога в Затонувшем храме Азерота. Призови силу яйца и разбуди мёртвого бога. Он пошлёт против тебя своих прислужников. Одолей их и нацеди из них крови Хаккари. Угаси при помощи этой крови вечный огонь, в котором заключён дух Хаккара. Когда пламя погаснет, в мир войдёт аватара Хаккара. Победи его и помести его сущность в яйцо Хаккара." },
    ["3528c"] = { common = "Значит, сущность Хаккара заключена в яйцо! Смотри, как в Яйце пульсирует жизнь! Неужели мифы о Хаккаре правда? Не может быть, ведь в таком случае Хаккар может возродиться. Я буду хранить это яйцо как зеницу ока, чтобы оно не попало в недобрые руки. Наша совместная работа подошла к концу, путник. Ты прикоснулся к легенде, быть может, твои подвиги однажды изменят облик нашего мира." },
    ["3541a"] = { common = "В Оргриммаре есть у меня скупщик краденого. У него притон в Волоке. Этого скользкого типа нелегко найти, если не знать точно где искать. Запомни: искать следует в одном из самых высоких зданий. Только сделай мне одолжение, не ори на весь Калимдор, где он и чем занимается — это было бы… весьма неприятно для нас обоих. Он готов заплатить очень хорошую цену за табличку Джин'яэль. Не знаю, зачем уж она ему сдалась, но видел бы ты, как у него загорелись глаза, когда я упомянула, что знаю, где её найти!" },
    ["3541c"] = { common = "А, Джедига послала мне посылочки из самой Азшары. Хорошо. Я ждал её. Джедига, прекрасная женщина… Смертоносная к тому же. Что может быть лучше! Посмотрим-ка на неё, табличка в хорошем состоянии. Ты прекрасный посланник," },
    ["3542a"] = { common = "Теперь ты отправишься к Андрону Ганту. Он обретается в Подгороде, недалеко от Района Фармацевтов. Этот был более многословен, когда я спросила, зачем ему нужна табличка. Маги Подгорода хотят изучить некоторые тайные заклинания высокорожденных. Они считают, что табличка им в этом поможет. Маркри был очень талантлив в чарах призыва различных существ, особенно элементалей. Отнеси ему табличку Маркри и возвращайся за своей долей." },
    ["3542c"] = { common = "Вот, возьми пару монеток, ик… на новую броню или чего-то ещё… Это принесёт пару золотых… если знатть нужных люддей… ик." },
    ["3561a"] = { common = "Последнюю табличку надлежит доставить весьма опасному человеку, путник. Можешь не сомневаться, я доверяю ему куда меньше, чем кому-либо из тех, к кому я тебя отправляла. Верховный маг Ксилем живёт в башне в холмах, возвышающихся над Азшарой. Он человек, однако он не похож на людей, которых мне приходилось встречать… или убивать. Он необычайно властен. Я не смею спросить его, что он собирается делать с табличкой. Он сказал мне, что страж его, Санат, поможет мне попасть в его башню, когда я буду готова предстать перед ним. Ищи Саната на севере." },
    ["3561c"] = { common = "А… Табличка Саэль'Хай… долго же я ждал её… Благодарю тебя, путник. Передай Джедиге, что я ею доволен. И я даже оплачу ей её расходы." },
    ["3562a"] = { common = "Отнеси это послание Джедиге. Скажи ей, что я заплачу ей лично, когда она придёт ко мне. Ступай скорее, путник. Скажи своей госпоже, что награда ожидает её." },
    ["3562c"] = { common = "А, славно. Она вела себя куда разумнее, чем ожидалось… по крайней мере с тобой. Я бы не удивилась, если бы она наказала тебя вместо меня и отправила бы кого-то занять моё место. Похоже, что ей действительно нужна эта табличка. Интересно. Есть над чем поразмыслить." },
    ["3563a"] = { common = "Отнеси это послание Джедиге. Скажи ей, что я доволен её работой. Скажи, чтобы скорее возвращалась в Оргриммар — Джес'римон достойно наградит её. Передай ей это, и, возможно, впредь я буду давать тебе поручения, путник." },
    ["3563c"] = { common = "Судя по письму, он доволен… слишком доволен. Страшный вопрос встаёт передо мной, не продешевила ли я?? Возможно, в какой то из дней я смогу выкроить достаточно времени, чтобы узнать, сколько на самом деле я смогла бы выручить за свою работу… Вот твоя часть платы, как и договаривались." },
    ["3564a"] = { common = "Вот держи Это для Джедиги. И ты это, заходи, если что!" },
    ["3564c"] = { common = "Прекрасно, подожди минуточку. Аха! Ахха! Что ты сказал ему когда доставил табличку, а, путник? Он переплатил нам! Ты сказал ему что условия сделки изменились? Или он опять был в хлам пьяный? Ладно, неважно. Вот, возьми то, что тебе положено… с приплатой." },
    ["3565a"] = { common = "Что ещё? Ах да, оплата. Конечно. Вот, возьми и выметайся. Уверен, Джедига ждёт не дождётся твоего возвращения." },
    ["3565c"] = { common = "Нет проблем? Точно нет? Ладно, вот что я тебе скажу… Я ожидала что он по крайней мере выкинет какой-то фортель, или попытается расторгнуть нашу сделку. Хм… а он выполнил всё в точности. Ладно, не будем углубляться в это слишком. Вот твоя доля. Благодарю за помощь." },
    ["3566a"] = { common = "Это… была… ловушка… Прости… меня… Убей предателя… Отомсти за нас… За Ториуса…" },
    ["3566c"] = { common = "Этого не может быть… Мой единокровный брат! Неужели он мог это сделать?! Он предал меня, он предал Стальгорн! Видимо, влияние Древних Богов ещё сильно в этих землях. Боюсь, если даже мой брат — некогда благородный и уважаемый человек — так легко поддался воле Рагнароса, никто из нас не может чувствовать себя в безопасности!" },
    ["3568a"] = { common = "Видишь эту несчастную тауренку? Она недавно побывала в Азшаре. Среди руин Эльдарата она была ранена в бою с нагами. Отбившись от них, она решила отдохнуть на берегу и попила водички из приливной заводи. Теперь её тошнит… помимо всего прочего. Мне нужно выяснить, что она пила. Возьми этот ящик, в нём несколько помеченных фиалов. Наполни их из разных заводей и возвращайся." },
    ["3568c"] = { common = "Чудесно. Ты успел вернуться до её гибели. Славно, славно. Значит, пора приступать. Я некоторое время изучал симптомы её болезни, и теперь дело совсем плохо. Удивительно, как она на ногах держится. Её уже три или четыре раза вырвало… запах просто чудесный. Дай-ка я состряпаю что-нибудь для нашей… подруги." },
    ["3569a"] = { common = "Отнеси эликсир Терсе — вдруг он ей поможет? Пока она не выпьет его, точно не скажешь." },
    ["3569c"] = { common = "Химик Карабос — само гостеприимство… даже не по себе стало. Но если он говорит, что есть шанс излечиться, выбора нет. Искать другие лекарства нет времени. Ни жрецы, ни шаманы не смогли мне помочь. Будем надеяться, что Мать-земля сохранит мою душу." },
    ["3570c"] = { common = "Чудесно. Ты вернулся до того, как она умерла. Хорошо, хорошо. Начнём пожалуй? Я наблюдаю её симптомы и они… неприятны. Я удивлён, что она ещё в сознании. Её рвало несколько раз… Теперь, дай мне возможность испробовать кое что на нашей… подруге." },
    ["3601a"] = { common = "Ким'джаель оскорблён до глубины души! Знаешь, что на самом деле Ким'джаель значит для эльфов крови, путник? Я для них всего лишь букашка! Маленькое безвредное создание, на которое можно и наступить — не жалко! Они наняли меня, чтобы я обшарил для них место, где, как они сказали, спрятано сокровище. Ну ты понимаешь, при слове \"сокровище\" я утратил бдительность и купился на их посулы! Конечно же, они предали меня и даже пытались прикончить! Никогда нельзя верить мерзким эльфам крови! Мне удалось уйти живым, но у негодяев осталось всё моё снаряжение! Пожалуйста, забери его у них!" },
    ["3601c"] = { common = "Ха-ха! Ты проучил их, не так ли? Здорово! Ты показал этим Эльфам Крови как предавать своих партнёров! Особенно, такого как верный гоблинский торговец! Ах! Я заплачу тебе за твоё потерянное время, как я и сказал… Вот, возьми. Это может оказаться для тебя полезным!" },
    ["3602a"] = { common = "Древние скальные великаны из южных регионов Азшары для поддержания существования поглощают камни и каменные образования. Продуктом переработки такой \"пищи\" являются чрезвычайно податливые, но при этом необычайно прочные кристаллы, известные как азшарит. На южной гряде находятся целые залежи азшарита, однако его почти никому не удавалось добыть из-за чрезвычайной жестокости великанов. Тебе следует отправиться на юг и раздобыть азшарита столько, чтобы его хватило для создания оружия. Мои гончие скверны помогут в розыске кристаллов." },
    ["3602c"] = { common = "Твоя задача в Азшаре выполнена, смертный. Теперь я буду плавить эти компоненты… для следующего шага в твоём путешествии." },
    ["3621a"] = { common = "Оружие готово к отковке. Тебе следует отнести закалённый азшарит к тому, кто может обуздать энергию скверны. В Тернистой долине живёт такой кузнец. Гальван Древний, глава Ордена Мифрила, создаст оружие по твоему заказу. Ты можешь найти его становище между Зул'Гурубом и холмом Мош'Огг. Пусть решительность и вера помогут тебе пройти это испытание. А если ты погибнешь, знай, что твой Бог тебе улыбается." },
    ["3621c"] = { common = "О боги, я боюсь даже представить, через что тебе пришлось пройти, чтобы добыть эти материалы. Немногие рискнули отправиться в Азшару и вернуться живыми!" },
    ["3625a"] = { common = "Путник, для создания оружия необходимо время. Вдобавок, ты можешь использовать силу оружия Проклятия Скверны лишь раз в три минуты. Длительность действия, ослабляющего Разелиха Осквернителя и его приспешников, может быть различной. Именно поэтому следует высвобождать силу Проклятия Скверны лишь в нужный момент! Теперь дай мне время на создание оружия для тебя, путник." },
    ["3625c"] = { common = "Лучшего уничтожителя демонов этот мир ещё не видел, путник." },
    ["3626a"] = { common = "Час возмездия близок, путник. Тебе следует вернуться в Выжженные земли вместе с твоим новообретённым оружием и поговорить с Павшим героем Орды о том, как достичь твоей главной цели." },
    ["3626c"] = { common = "А ты выглядишь закалённым в боях, путник. Готов ли ты лицом к лицу встретится с Разелихом и его приспешниками?" },
    ["3627a"] = { common = "Чтобы добраться до Осквернителя, тебе следует сначала уничтожить троицу силы и собрать осколки амулета. Когда у тебя в руках будут все три осколка, возвращайся ко мне, и я скажу, что делать дальше. Иди, путник! В Выжженные земли! Севина, Аллистарий и Грол должны погибнуть!" },
    ["3627c"] = { common = "Амулет Разелиха Осквернителя ещё раз собран воедино! Однако он должен почувствовать, что его командная цепь разорвалась. Он уже знает, что ты идёшь по его следу…" },
    ["3628a"] = { common = "Логово Разелиха находится на вершине самой высокой горы Выжженных земель. Единственный способ достигнуть логова — это использовать телепортирующие руны поблизости от горы. Пока у тебя есть этот амулет, ты свободно можешь переместиться в логово. А достигнув логова, призови зверя. Ключ к этому — твой амулет, путник. Используй его на Алтаре Осквернителя. Если одолеешь Осквернителя, принеси его рог. Он станет символом надежды для всех, кто увидит его — доказательством того, что в этом раздираемом войнами мире ещё есть герои!" },
    ["3628c"] = { common = "Сегодня день, который запомнит вся вселенная! Демонический правитель Выжженных земель, наконец, повержен!" },
    ["3629a"] = { common = "В инженерном деле есть две дисциплины: гномская и гоблинская. Я – честный учитель, и только поэтому упомянул гоблинское инженерное дело. Видишь ли, гоблины обожают делать всякие взрывоопасные штучки и редко заботятся о том, что окажется на пути такой штучки – даже если это будет сам инженер. Почитай этот справочник. Если хочешь узнать, как эффектно покончить с собой, отнеси его к Никсу Шепружину в Прибамбасск. Помни – выбор твой не подлежит пересмотру, сменить дисциплину ты не сможешь; так что прежде, чем выполнить задание, что даст тебе Никс, убедись, что ты хочешь именно этого." },
    ["3629c"] = { male = "Хорошо, ты выбрал правильный путь. Не смотри на похвальбу гномов, разве они умеют обращаться с взрывчатыми веществами... в их заражённом радиацией городе Гномрегане так уже не думают, хе-хе-хе... Я покажу тебе, что такое настоящая гоблинская инженерия. Держи свои глаза широко открытыми, и учись.", female = "Хорошо, ты выбрала правильный путь. Не смотри на похвальбу гномов, разве они умеют обращаться с взрывчатыми веществами... в их заражённом радиацией городе Гномрегане так уже не думают, хе-хе-хе... Я покажу тебе, что такое настоящая гоблинская инженерия. Держи свои глаза широко открытыми, и учись." },
    ["3630a"] = { common = "В инженерном деле есть две дисциплины: гномская и гоблинская. Гномское инженерное дело пока что зарекомендовала себя лучшей из двух. В ней речь идёт о конструировании чудесных штучек и приспособлений, которые украшают жизнь! Почитай этот справочник. Если ты захочешь больше узнать о гномском инженерном деле, то отнеси его мехмастеру Замыкальцу в Стальгорн. Помни – выбор твой не подлежит пересмотру, и изучить другую дисциплину ты не сможешь, так что удостоверься в своём выборе, прежде чем выполнять его задание!" },
    ["3630c"] = { male = "А, молодой инженер, заинтересованный в освоении единственно верной школы инженерного дела! Что ж, дружище, прости мне мою мелодраматичность. Пока ситуация наша остаётся тяжёлой, день всегда кажется светлее, когда встречаешь собрата по ремеслу, откликнувшегося на трубный призыв истинного инженерного дела!", female = "А, молодая инженер, заинтересованная в освоении единственно верной школы инженерного дела! Что ж, подруга, прости мне мою мелодраматичность. Пока ситуация наша остаётся тяжёлой, день всегда кажется светлее, когда встречаешь собрата по ремеслу, откликнувшегося на трубный призыв истинного инженерного дела!" },
    ["3631a"] = { male = "Хммм. Я сказал бы, что ты ещё не готов, но тут не мне решать. Страад думает иначе, а решает он... пока. Он хочет с тобой говорить, причём срочно. Он пока всё ещё в Степях над Кабестаном, в своей маленькой башне со своими учениками. Долго не тяни.", female = "Хммм. Я сказал бы, что ты ещё не готова, но тут не мне решать. Страад думает иначе, а решает он... пока. Он хочет с тобой говорить, причём срочно. Он пока всё ещё в Степях над Кабестаном, в своей маленькой башне со своими учениками. Долго не тяни." },
    ["3631c"] = { male = "Значит, ты снова решил пожаловать меня своим визитом. Очень мило с твоей стороны. Мои помощники все гадали – придёшь или нет? Я говорил им – несомненно, придёт. Когда речь заходит о могуществе, летишь как мотылёк на свечу.", female = "Значит, ты снова решила пожаловать меня своим визитом. Очень мило с твоей стороны. Мои помощники все гадали – придёшь или нет? Я говорил им – несомненно, придёт. Когда речь заходит о могуществе, летишь как мотылёк на свечу." },
    ["3632a"] = { common = "На высоких уровнях инженерное дело расходится на два направления: на гномское и гоблинское. Гномская намного сильнее! Она занимается конструированием чудесных штучек и устройств, которые делают лучше нашу жизнь! Прочтите эту инструкцию. Если вы желаете узнать побольше о гномском инженерном деле, отнесите этот справочник мехмастеру Замыкальцу – он здесь, в Стальгорне. Помните: если выберете гномское инженерное дело, то это с концами, другим направлением вы заниматься не сможете, так что подумайте хорошенько, прежде чем выполнить его поручение!" },
    ["3632c"] = { male = "А, юный инженер желает изучать единственное истинное направление в инженерном деле! Простите мне мою горячность, любезный друг. В нашем горестном положении всегда очень радостно встретить инженера, отозвавшегося на чистый зов истинного искусства!", female = "А, юная инженер желает изучать единственное истинное направление в инженерном деле! Простите мне мою горячность, любезный друг. В нашем горестном положении всегда очень радостно встретить инженера, отозвавшегося на чистый зов истинного искусства!" },
    ["3633a"] = { common = "Инженерам-умельцам приходится выбирать между двумя школами инженерного дела: гномской и гоблинской. Очевидно, что наиболее талантливые инженеры предпочитают гоблинскую. Покори же мир с помощью отборной взрывчатки и фантастических механизмов! Прочитай этот учебник. Если ты хочешь поучиться гоблинскому инженерному делу, поговори с Никсом Шепружином в Прибамбасске. Помни: сделав выбор единожды, ты не сможешь передумать. Поэтому хорошо подумай, прежде чем браться за задание Никса." },
    ["3633c"] = { male = "Что же, ты нашёл подходящего учителя! Любой болван может освоить основы инженерного дела – как доказали гномы и их радиоактивный Гномреган. Требуется острый ум и верная рука (ключевое слово – ВЕРНАЯ), чтобы освоить премудрости гоблинского инженерного дела. Держи ушки на макушке, и чему-нибудь научишься.", female = "Что же, ты нашла подходящего учителя! Любой болван может освоить основы инженерного дела – как доказали гномы и их радиоактивный Гномреган. Требуется острый ум и верная рука (ключевое слово – ВЕРНАЯ), чтобы освоить премудрости гоблинского инженерного дела. Держи ушки на макушке, и чему-нибудь научишься." },
    ["3634a"] = { common = "На высоких уровнях инженерное дело расходится на два направления: на гномское и гоблинское. Хотя, на мой взгляд, это пустая трата времени, я должен рассказать тебе о гномском инженерном деле. Она занимается конструированием разных штучек и устройств, которые должны изменить мир, но редко работают. Прочти эту инструкцию. Если ты желаешь узнать побольше о гномском инженерном деле, отнеси этот справочник мехмастеру Замыкальцу в Стальгорн. Помни: выбрав гномское инженерное дело, ты не сможешь заниматься другим направлением, так что подумай хорошенько, прежде чем выполнить поручение Замыкальца!" },
    ["3634c"] = { male = "А, юный инженер желает изучать единственное истинное направление в инженерном деле! Простите мне мою горячность, любезный друг. В нашем горестном положении всегда очень радостно встретить инженера, отозвавшегося на чистый зов истинного искусства!", female = "А, юная инженер желает изучать единственное истинное направление в инженерном деле! Простите мне мою горячность, любезный друг. В нашем горестном положении всегда очень радостно встретить инженера, отозвавшегося на чистый зов истинного искусства!" },
    ["3635a"] = { common = "На высоких уровнях инженерное дело расходится на два направления: гномскую и гоблинскую. Хотя, на мой взгляд, это пустая трата времени, я должен рассказать тебе о гномском инженерном деле. Гномы занимаются конструированием разных штучек и устройств, которые должны изменить мир, но редко работают. Прочти этот учебник. Если ты хочешь научиться делать металлические пресс-папье, отнеси его Карлсу Пропеллерзу в Пиратскую бухту. Помни: выбрав гномское инженерное дело, ты не сможешь заниматься инженерным делом другой школы, так что подумай хорошенько, прежде чем выполнить поручение Карлса!" },
    ["3635c"] = { male = "Значит, тебе захотелось поучиться гномскому инженерному делу? Что ж, я очень подходящий гном. Хотя гномреганская правящая клика пытается преследовать тех, кто, по их мнению, слишком умный, знания нельзя посадить за решётку. Мы с ними отлично понимаем, что после того, как я покинул Гномреган, они лишились одного из величайших гномов-инженеров наших дней. Если ты – способный ученик, я обучу тебя всему, что знаю.", female = "Значит, тебе захотелось поучиться гномскому инженерному делу? Что ж, я очень подходящий гном. Хотя гномреганская правящая клика пытается преследовать тех, кто, по их мнению, слишком умный, знания нельзя посадить за решётку. Мы с ними отлично понимаем, что после того, как я покинул Гномреган, они лишились одного из величайших гномов-инженеров наших дней. Если ты – способная ученица, я обучу тебя всему, что знаю." },
    ["3636a"] = { common = "Плеть постоянно досаждает силам Альянса. Думаю, ты знаешь об этом не хуже меня. В последнее время нам удалось сделать пару интересных находок. В Степях есть жуткие заросли терновника, называемые Курганы Иглошкурых. Сначала казалось, что там обитают только иглогривы, но теперь выясняется, что в этих зарослях гнездятся самые разнообразные чудовища. Управляет ими лич по имени Амненнар Хладовей. Во имя Света! Изгони зло с холмов Иглошкурых!" },
    ["3636c"] = { common = "Спасибо. Теперь Плеть подумает дважды, прежде чем выпускать на нас своих гадов. Да хранит тебя Свет!" },
    ["3637a"] = { common = "На высоких уровнях инженерное дело расходится на два направления: на гномское и гоблинское. Хотя, на мой взгляд, это пустая трата времени, я должен рассказать тебе о гномском инженерном деле. Она занимается конструированием разных штучек и устройств, которые должны изменить мир, но редко работают. Прочти этот учебник. Если ты хочешь научиться делать металлические пресс-папье, отнеси его Карлсу Пропеллерзу в Пиратскую бухту. Помни: выбрав гномское инженерное дело, ты не сможешь заниматься инженерным делом другой школы, так что подумай хорошенько прежде, чем выполнить поручение Карлса!" },
    ["3637c"] = { male = "Значит, тебе захотелось поучиться гномскому инженерному делу? Что ж, я очень подходящий гном. Хотя гномреганская правящая клика пытается преследовать тех, кто, по их мнению, слишком умный, знания нельзя посадить за решётку. Мы с ними отлично понимаем, что после того, как я покинул Гномреган, они лишились одного из величайших гномов-инженеров наших дней. Если ты – способный ученик, я обучу тебя всему, что знаю.", female = "Значит, тебе захотелось поучиться гномскому инженерному делу? Что ж, я очень подходящий гном. Хотя гномреганская правящая клика пытается преследовать тех, кто, по их мнению, слишком умный, знания нельзя посадить за решётку. Мы с ними отлично понимаем, что после того, как я покинул Гномреган, они лишились одного из величайших гномов-инженеров наших дней. Если ты – способная ученица, я обучу тебя всему, что знаю." },
    ["3638a"] = { common = "Гоблинское инженерное дело нацелена на получение высоких прибылей и огромной взрывной силы! Наши чертежи позволяют нам создавать мощные бомбы и прочее оружие, и в справочнике, что у тебя в руках, об этом написано. Но этот справочник также содержит древнюю клятву хранить наши чертежи в тайне. Как только ты займёшься гоблинским инженерным делом, то всё. Доступа к гномскому инженерному делу не будет. Если ты по-прежнему хочешь заняться гоблинским инженерным делом, подпиши этот документ о пожизненном неразглашении тайн и снова обращайся ко мне. Но сначала подумай хорошенько." },
    ["3638c"] = { male = "Добро пожаловать в клуб! Скоро ты получишь доступ к наиболее передовым разработкам во всём Азероте. Теперь, когда ты решил посвятить себя этому искусству, пора познакомиться с гоблинским инженерным делом. С этого мгновения мы будем помогать тебе разрабатывать план предельного раскрытия талантов гоблинского инженера!", female = "Добро пожаловать в клуб! Скоро ты получишь доступ к наиболее передовым разработкам во всём Азероте. Теперь, когда ты решила посвятить себя этому искусству, пора познакомиться с гоблинским инженерным делом. С этого мгновения мы будем помогать тебе разрабатывать план предельного раскрытия талантов гоблинского инженера!" },
    ["3639a"] = { male = "Как твой наставник, я желаю увидеть образцы твоей работы. Ты опытный инженер, тут вопросов нет. Но я надеюсь проанализировать твои работы, чтобы найти способ отточить гоблинскоориентированную технику для будущих трудов. Мне нужны следующие образцы: двадцать больших железных бомб, двадцать шашек плотного динамита и пять взрывоопасных овец – и смотри сам не подорвись! Сдай мне эти предметы, и я выдам твой собственный членский билет гильдии гоблинов-инженеров – он нужен для допуска ко всем наставникам гоблинского инженерного дела!", female = "Как твой наставник, я желаю увидеть образцы твоей работы. Ты опытный инженер, тут вопросов нет. Но я надеюсь проанализировать твои работы, чтобы найти способ отточить гоблинскоориентированную технику для будущих трудов. Мне нужны следующие образцы: двадцать больших железных бомб, двадцать шашек плотного динамита и пять взрывоопасных овец – и смотри сама не подорвись! Сдай мне эти предметы, и я выдам твой собственный членский билет гильдии гоблинов-инженеров – он нужен для допуска ко всем наставникам гоблинского инженерного дела!" },
    ["3639c"] = { common = "Вот твой первый членский билет гильдии гоблинов-инженеров! Билет оплачивается вперёд за четырнадцать дней. Через две недели срок действия истечёт. Когда это произойдёт, то для продления заплати очередную пошлину любому наставнику гоблинской инженерного дела. Без билета твоё членство будет временно приостановлено, и ты не будешь иметь доступа к новым чертежам. Это никак не повлияет на уже обретённые знания: если уж стал гоблинским инженером, то это навсегда." },
    ["3640a"] = { common = "Гномское инженерное дело стоит на пороге открытия теории, которая послужит нашим нуждам! Наши чертежи позволяют нам сооружать устройства, контролирующие мир вокруг нас, и в справочнике, что у вас в руках, об этом написано. Но этот справочник также содержит древнюю клятву хранить наши чертежи в тайне. Как только вы займётесь гномским инженерным делом, то всё. Доступа к гоблинскому инженерному делу не будет. Если вы по-прежнему хотите заняться гномским инженерным делом, подпишите этот документ о пожизненном неразглашении тайн и снова обратитесь ко мне. Хорошенько подумайте." },
    ["3640c"] = { common = "Добро пожаловать в клуб! Скоро вы получите доступ к наиболее передовым разработкам во всём Азероте. Теперь, когда вы посвятили себя этому искусству, пора испытать ваши навыки гномского инженерного дела. С этого мгновения мы будем помогать вам разрабатывать план предельного раскрытия ваших талантов гномского инженера!" },
    ["3641a"] = { common = "Как ваш наставник, я желаю увидеть образцы вашей работы. Вы опытный инженер, тут вопросов нет. Но я надеюсь проанализировать ваши работы, чтобы найти способ отточить гномскоориентированную технику ваших будущих трудов. Мне нужны следующие образцы: шесть мифриловых трубок, точный прицел и два усовершенствованных манекена-мишени. Сдайте мне эти предметы, и я выдам вам ваш собственный членский билет гильдии гномов-инженеров – он нужен для допуска ко всем наставникам гномского инженерного дела!" },
    ["3641c"] = { common = "Вот ваш первый ччленский билет гильдии гномов-инженеров! Билет оплачивается вперёд за четырнадцать дней. Через две недели срок действия истечёт. Когда это произойдёт, вы заплатите очередную пошлину любому наставнику гномской инженери и получите продление. Без билета ваше членство будет временно приостановлено, и вы не будете иметь доступа к новым чертежам. Это никак не повлияет на уже обретённые вами знания: если уж стал гномским инженером, то это навсегда." },
    ["3642a"] = { common = "Гномское инженерное дело стоит на пороге открытия теории, которая послужит нашим нуждам! Наши чертежи позволяют нам сооружать устройства, контролирующие мир вокруг нас, и в справочнике, что у тебя в руках, об этом написано. Но этот справочник также содержит древнюю клятву хранить наши чертежи в тайне. Как только ты займёшься гномским инженерным делом, то всё. Доступа к гоблинскому инженерному делу не будет. Если ты по-прежнему хочешь заняться гномским инженерным делом, подпиши этот документ о пожизненном неразглашении тайн и снова обращайся ко мне. Но сначала подумай хорошенько." },
    ["3642c"] = { common = "Добро пожаловать в клуб! Скоро вы получите доступ к наиболее передовым разработкам во всём Азероте. Теперь, когда вы посвятили себя этому искусству, пора испытать ваши навыки гномского инженерного дела. С этого мгновения мы будем помогать вам разрабатывать план предельного раскрытия ваших талантов гномского инженера!" },
    ["3643a"] = { common = "Как ваш наставник, я желаю увидеть образцы вашей работы. Вы опытный инженер, тут вопросов нет. Но я надеюсь проанализировать ваши работы, чтобы найти способ отточить гномскоориентированную технику ваших будущих трудов. Мне нужны следующие образцы: шесть мифриловых трубок, точный прицел и два усовершенствованных манекена-мишени. Сдайте мне эти предметы, и я выдам вам ваш собственный членский билет гильдии гномов-инженеров – он нужен для допуска ко всем наставникам гномского инженерного дела!" },
    ["3643c"] = { common = "Вот твой первый членский билет гильдии гномов-инженеров! Билет оплачивается вперёд за четырнадцать дней. Через две недели срок действия истечёт. Когда это произойдёт, то для продления заплати очередную пошлину любому наставнику гномского инженерного дела. Без билета твоё членство будет временно приостановлено, и ты не будешь иметь доступа к новым чертежам. Это никак не повлияет на уже обретённые знания: если уж стал гномским инженером, то это навсегда." },
    ["3661a"] = { common = "Дикие совухи – очень непредсказуемые существа. Они могут быть мягкими и пушистыми, но если что-то дорогое для них окажется под угрозой, в них проснётся настоящий зверь! Говорят, что этих животных создала сама Элуна, и я хочу узнать, правда это, или нет. Много диких совухов обитает во Внутренних землях – целые популяции примитивных, злобных существ. Не хочешь отправиться туда и принести мне их перьев?" },
    ["3661c"] = { common = "Спасибо за перья. Что вам удалось узнать о диких совухах? Возможно, эти перья помогут узнать больше и сказать, являются ли они кровожадными монстрами или просто одичавшими питомцами. Надеюсь, когда-нибудь я узнаю правду. Я продолжу свои исследования, а вы, пожалуйста, по истечении некоторого времени зайдите ко мне снова." },
    ["3681a"] = { male = "Я вынужден прервать твоё путешествие, герой. Из Штормграда пришла весть о том, что всех паладинов призывают туда для продолжения обучения. Если бы меня спросили, я бы сказал, что для тебя наступает особое время – время изучения священных Фолиантов. Найди Даториана Ралла в Штормграде. Он обучает паладинов в Соборе Света.", female = "Я вынужден прервать твоё путешествие, героиня. Из Штормграда пришла весть о том, что всех паладинов призывают туда для продолжения обучения. Если бы меня спросили, я бы сказал, что для тебя наступает особое время – время изучения священных Фолиантов. Найди Даториана Ралла в Штормграде. Он обучает паладинов в Соборе Света." },
    ["3681c"] = { male = "Добро пожаловать в Собор Света, герой.", female = "Добро пожаловать в Собор Света, героиня." },
    ["3701a"] = { common = "Отправляйтесь в дымящиеся руины Тауриссана в Пылающих степях и соберите как можно больше информации. Говорят, все руины просто усыпаны таинственными реликвиями. Возможно, вам надо начать поиски здесь, путник. Опасайтесь таурисанских стражей-убийц, что стерегут руины, охраняя все тайны, какие там могут быть." },
    ["3701c"] = { common = "Ох ты! Эта информация многое объясняет касательно Тауриссана. Но предстоит узнать ещё больше!" },
    ["3702a"] = { common = "Не желаете ли услышать краткий обзор истории дворфов Чёрного Железа?" },
    ["3702c"] = { common = "Продолжим?" },
    ["3721c"] = { common = "Тебе удалось выручить всех трёх моих роботов серии КПХ! Ты сделал всё, что требовалось и даже больше, поэтому я хочу особым образом отблагодарить тебя за помощь. Это миниатюрная версия того же робота, с которым ты провёл так много времени и полюбил, КПХ! Обычно я никому не дарю такие опасные устройства, но ты оказал мне неоценимую помощь. Кроме того, у этой тварюшки отключены боевые механизмы и устройство самонаведения. А в остальном это полноценный КПХ!" },
    ["3741a"] = { common = "Моя подруга Хилари потеряла ожерелье, и мы никак не можем отыскать его. Мы весь день сидели на одном и том же месте, удили рыбу, и уже все кругом обыскали. Наверное, оно упало в воду. Родители не разрешают нам плавать в озере... Мама говорит, что под водой водятся чудовища, но вы ведь их не боитесь, правда? Пожалуйста, достаньте нам ожерелье." },
    ["3741c"] = { male = "Спасибо, что достали мне ожерелье, господин герой... Вы очень добры! Моя кошечка тоже хочет сказать \"спасибо\" – верно, Эфси?", female = "Спасибо, что достали мне ожерелье, госпожа героиня... Вы очень добры! Моя кошечка тоже хочет сказать \"спасибо\" – верно, Эфси?" },
    ["3761a"] = { common = "Говорят, что почва из Кратера Ун'Горо наделена мощными магическими свойствами. Кругу Кенария нужно много этой почвы для исследований. Ступай в страшные окрестности Ун'Горо и добудь земли побольше. Эта богатая почва порой лежит большими грудами, а иногда её находят у некоторых тварей. Относи землю к Геду – ищи кучки земли и таурена, раздающего команды. Он не злой, просто постарайся его не слишком донимать." },
    ["3761c"] = { male = "Ладно, рядовой путник, и не пытайся помогать мне сваливать эту землю в кучу! Если бы Великие духи этого хотели, то прямо тут и устроили бы чудо, что, не так?! Верховный друид Рунический Тотэм опять хочет с тобой говорить, но чтобы выполнить его очередное поручение, тебе нужно разбираться в травничестве на уровне подмастерья. Но если ты ещё не доучился, он всё равно тебе дельце подберёт.", female = "Ладно, рядовая путница, и не пытайся помогать мне сваливать эту землю в кучу! Если бы Великие духи этого хотели, то прямо тут и устроили бы чудо, что, не так?! Верховный друид Рунический Тотэм опять хочет с тобой говорить, но чтобы выполнить его очередное поручение, тебе нужно разбираться в травничестве на уровне подмастерья. Но если ты ещё не доучилась, он всё равно тебе дельце подберёт." },
    ["3762a"] = { male = "Извини, герой, можно тебя на минутку? Кругу Кенария в Громовом Утёсе требуются такие закалённые путешественники, как ты, для участия в чрезвычайно важном исследовании. Подробностей я не знаю, но могу сказать, что возглавляет этот проект Хамуул Рунический Тотэм. Если тебя это интересует, отправляйся в Громовый Утёс на Вершину Старейшин и поговори с самим Хамуулом.", female = "Извини, героиня, можно тебя на минутку? Кругу Кенария в Громовом Утёсе требуются такие закалённые путешественники, как ты, для участия в чрезвычайно важном исследовании. Подробностей я не знаю, но могу сказать, что возглавляет этот проект Хамуул Рунический Тотэм. Если тебя это интересует, отправляйся в Громовый Утёс на Вершину Старейшин и поговори с самим Хамуулом." },
    ["3762c"] = { male = "Привет тебе, герой. Я рад, что ты хочешь помочь нам в наших исследованиях. Сделать предстоит многое, и я дурно поступил бы, если бы сказал, что труды наши не сулят опасности. Надеюсь, это тебя не отпугнёт... но, судя по твоему виду, тебе и прежде приходилось сталкиваться с опасностями.", female = "Привет тебе, героиня. Я рад, что ты хочешь помочь нам в наших исследованиях. Сделать предстоит многое, и я дурно поступил бы, если бы сказал, что труды наши не сулят опасности. Надеюсь, это тебя не отпугнёт... но, судя по твоему виду, тебе и прежде приходилось сталкиваться с опасностями." },
    ["3763a"] = { male = "Простите, герой, не уделите ли вы мне крупицу вашего времени? Дарнасский Круг Кенария набирает опытных искателей приключений – вроде вас – для помощи в жизненно важном исследовательском проекте. Подробностей я не знаю, но могу сказать, что исследованиями руководит не кто иной, как сам верховный друид Фэндрал Олений Шлем. Прошу вас, если вам интересно, поговорите с ним лично в анклаве Кенария в Дарнассе.", female = "Простите, героиня, не уделите ли вы мне крупицу вашего времени? Дарнасский Круг Кенария набирает опытных искателей приключений – вроде вас – для помощи в жизненно важном исследовательском проекте. Подробностей я не знаю, но могу сказать, что исследованиями руководит не кто иной, как сам верховный друид Фэндрал Олений Шлем. Прошу вас, если вам интересно, поговорите с ним лично в анклаве Кенария в Дарнассе." },
    ["3763c"] = { male = "Что же, герой... поскольку вам сказали, что этими исследованиями руковожу лично я, то вы, несомненно, прибыли сюда так быстро, как могли. И раз уж вы здесь, постарайтесь запомнить мои пояснения с первого раза, ибо повторять я не буду.", female = "Что же, героиня... поскольку вам сказали, что этими исследованиями руковожу лично я, то вы, несомненно, прибыли сюда так быстро, как могли. И раз уж вы здесь, постарайтесь запомнить мои пояснения с первого раза, ибо повторять я не буду." },
    ["3764a"] = { common = "Говорят, что почва из Кратера Ун'Горо наделена мощными магическими свойствами. Я хочу знать, насколько эти слухи преувеличены. Ступай в заросший кратер Ун'Горо и добудь хороших образцов земли для наших исследований. Тебе может показаться, что это дело не достойно тебя, но такое поведение не завоюет тебе приязни ни с моей стороны, ни со стороны Круга Кенария. Принеси образцы земли Дженалю, который наверняка сидит без дела вон за тем деревом – ищи кучки земли, и найдёшь его. Снабжением занимается он, не я." },
    ["3764c"] = { male = "Наконец-то ты сможешь избавиться от своего драгоценного груза, благородный герой. Тяжкая, наверное, ноша... не легче ноши созерцателя, вроде меня... Вот гонорар за работу, назначенный самим верховным дуидом. Верховный друид Олений Шлем опять хочет видеть тебя, но ты получишь помощь при выполнении следующего его задания, если только будешь разбираться в травознании не хуже подмастерья. Но если даже ты и вовсе не травник, ты всё равно можешь помочь Кругу!", female = "Наконец-то ты сможешь избавиться от своего драгоценного груза, благородная героиня. Тяжкая, наверное, ноша... не легче ноши созерцателя, вроде меня... Вот гонорар за работу, назначенный самим верховным дуидом. Верховный друид Олений Шлем опять хочет видеть тебя, но ты получишь помощь при выполнении следующего его задания, если только будешь разбираться в травознании не хуже подмастерья. Но если даже ты и вовсе не травник, ты всё равно можешь помочь Кругу!" },
    ["3765a"] = { male = "Штормград – невероятно суматошный город. Я прибыл сюда издалека в поисках помощи. Говорят, отважные искатели приключений нередко бродят по этим улицам. Мой брат Гершала на Тёмном Берегу нуждается в помощи. Он обитает в приморском городке Аубердине. Это путешествие будет долгим и насыщенным. Именно по этой причине я и ищу помощи кого-то, обладающего опытом – такого, как вы, герой.", female = "Штормград – невероятно суматошный город. Я прибыл сюда издалека в поисках помощи. Говорят, отважные искатели приключений нередко бродят по этим улицам. Мой брат Гершала на Тёмном Берегу нуждается в помощи. Он обитает в приморском городке Аубердине. Это путешествие будет долгим и насыщенным. Именно по этой причине я и ищу помощи кого-то, обладающего опытом – такого, как вы, героиня." },
    ["3765c"] = { common = "О, вас прислал мой брат Аргос? Должно быть, вы устали от долгого пути. Но нам очень о многом нужно поговорить." },
    ["3781a"] = { male = "При помощи того, что мы называем сумой вечного цветения, мы посадили семена Тарлендриса в почву из Кратера Ун'Горо. Из этих семян проросло множество редких полезных трав. И одна из них – рассветница, таинственное растение, о котором мы мало что знаем. Я намерен разгадать его тайну. Отнеси это вниз, Матренгилу, и он даст тебе семена, чтобы ты мог начать работу. Если всё израсходуешь, тебе придётся купить у него ещё семян.", female = "При помощи того, что мы называем сумой вечного цветения, мы посадили семена Тарлендриса в почву из Кратера Ун'Горо. Из этих семян проросло множество редких полезных трав. И одна из них – рассветница, таинственное растение, о котором мы мало что знаем. Я намерен разгадать его тайну. Отнеси это вниз, Матренгилу, и он даст тебе семена, чтобы ты могла начать работу. Если всё израсходуешь, тебе придётся купить у него ещё семян." },
    ["3781c"] = { common = "Да, расписка на двадцать пакетиков семян. Если всё изведёшь, ещё достанем. Хотя производить семена Тарлендриса в большом количестве – дело, увы, недешёвое. Потому Круг Кенария и просит помощи в частичном возмещении стоимости. Те, кто находит рассветницу и приносит нам, видит, что награда верховного друида с лихвой окупает труды." },
    ["3782a"] = { male = "При помощи того, что мы называем сумой вечного цветения, мы посадили семена Тарлендриса в почву из Кратера Ун'Горо. Из этих семян проросло множество редких полезных трав. И одна из них – рассветница, таинственное растение, о котором мы мало что знаем. Я намерен раскрыть его тайну для Круга. Отнеси эту расписку моей дочери Башане Рунный Тотэм, и она даст тебе семена, чтобы ты мог начать работу. Если всё израсходуешь, тебе придётся купить у неё ещё семян.", female = "При помощи того, что мы называем сумой вечного цветения, мы посадили семена Тарлендриса в почву из Кратера Ун'Горо. Из этих семян проросло множество редких полезных трав. И одна из них – рассветница, таинственное растение, о котором мы мало что знаем. Я намерен раскрыть его тайну для Круга. Отнеси эту расписку моей дочери Башане Рунный Тотэм, и она даст тебе семена, чтобы ты могла начать работу. Если всё израсходуешь, тебе придётся купить у неё ещё семян." },
    ["3782c"] = { common = "Да, расписка на двадцать пакетиков семян. Если всё израсходуешь, у меня есть ещё на продажу. Увы, производить семена Тарлендриса в большом количестве дорого. Потому Круг Кенария и просит помощи в частичном возмещении стоимости. Те, кто находит рассветницу и приносит нам, видит, что награда верховного друида с лихвой окупает труды." },
    ["3783a"] = { common = "У моих друзей всегда замечательные идеи. Я никогда не думала, что смогу сравниться с ними… до сегодняшнего дня! У меня созрел потрясающий план! Если обещаешь никому не говорить, я расскажу тебе его по секрету… Я хочу сделать механического йети! Мои друзья с ума сойдут, когда увидят, что я смогла смастерить! Для начала мне понадобится толстый мех йети с холмов Ледополоха. Ты мне поможешь? Йети водятся к юго-востоку отсюда." },
    ["3783c"] = { common = "Эти меха просто чудесны, путник. Так что мы тут славно поработаем!" },
    ["3784a"] = { male = "Извини, герой, можно тебя на минутку? Кругу Кенария в Громовом Утёсе требуются такие закалённые путешественники, как ты, для участия в чрезвычайно важном исследовании. Подробностей я не знаю, но могу сказать, что возглавляет этот проект Хамуул Рунический Тотэм. Если тебя это интересует, отправляйся в Громовый Утёс на Вершину Старейшин и поговори с самим Хамуулом.", female = "Извини, героиня, можно тебя на минутку? Кругу Кенария в Громовом Утёсе требуются такие закалённые путешественники, как ты, для участия в чрезвычайно важном исследовании. Подробностей я не знаю, но могу сказать, что возглавляет этот проект Хамуул Рунический Тотэм. Если тебя это интересует, отправляйся в Громовый Утёс на Вершину Старейшин и поговори с самим Хамуулом." },
    ["3784c"] = { male = "Приветствую, герой! Я рад, что тебя заинтересовало наше исследование. Дел очень много, и я обманул бы тебя, сказав, что речь идёт о безопасном задании. Надеюсь, тебя так просто не напугать... По твоему виду можно предположить, что тебе приходилось сталкиваться с опасностями.", female = "Приветствую, героиня! Я рад, что тебя заинтересовало наше исследование. Дел очень много, и я обманул бы тебя, сказав, что речь идёт о безопасном задании. Надеюсь, тебя так просто не напугать... По твоему виду можно предположить, что тебе приходилось сталкиваться с опасностями." },
    ["3785a"] = { common = "Это сума вечного цветения для семян Тарлендриса. Ещё тебе понадобится почва из Кратера Ун'Горо как удобрение для семян. Когда достанешь всё, что надо, просто используй суму, она позаботится обо всём. Когда у тебя будет достаточно рассветницы, принеси её мне сюда в анклав. И не утруждай верховного друида: он эльф занятой, не стоит отрывать его от дела всякий раз, как кто-то приносит очередную порцию зерна!" },
    ["3785c"] = { common = "Очень хорошо, я непременно отнесу их лично верховному друиду, когда они ему понадобятся. А пока прими это в знак признательности от Круга Кенария. Нам рассветница нужна всегда. Если ты желаешь и дальше помогать нам, приноси любую рассветницу, какую сумеешь вырастить." },
    ["3786a"] = { common = "Вот сума вечного цветения для семян Тарлендриса. Ещё тебе понадобится почва из Кратера Ун'Горо как удобрение для семян. Когда достанешь всё, что надо, просто используй суму, а уж она сама позаботится обо всём. Когда у тебя будет достаточно рассветницы, принеси её мне сюда на Вершину Старейшин. И не утруждай верховного друида – он очень занят исследованиями, да и других забот у него полон рот." },
    ["3786c"] = { common = "Очень хорошо, я непременно отнесу их лично верховному друиду, когда они ему понадобятся. А пока прими это в знак признательности от Круга Кенария. Нам рассветница нужна всегда. Если ты желаешь и дальше помогать нам, приноси любую рассветницу, какую сумеешь вырастить." },
    ["3787a"] = { male = "Простите, друг мой... Мой коллега хотел бы поговорить с вами касательно проводимых вами совместно с Кругом Кенария исследований. Он друид, зовут его Квинтис Ночной Костёр, и живёт он в Крепости Оперённой Луны в Фераласе. Он хотел бы посоветоваться с вами насчёт рассветницы... и он очень хотел бы, чтобы этот разговор не дошёл до ушей верховного друида. Если вы заинтересовались, поговорите с Кинтисом; не сомневайтесь, он расскажет вам всё подробно.", female = "Простите, уважаемая госпожа... Мой коллега хотел бы поговорить с вами касательно проводимых вами совместно с Кругом Кенария исследований. Он друид, зовут его Квинтис Ночной Костёр, и живёт он в Крепости Оперённой Луны в Фераласе. Он хотел бы посоветоваться с вами насчёт рассветницы... и он очень хотел бы, чтобы этот разговор не дошёл до ушей верховного друида. Если вы заинтересовались, поговорите с Кинтисом; не сомневайтесь, он расскажет вам всё подробно." },
    ["3787c"] = { male = "Благодарю вас за ваш визит, усталый путник! Позвольте представиться: я – Квинтис Ночной Костёр, друид и скромный слуга Малфуриона и Круга Кенария. Мои коллеги (генерал Шандриса Оперённая Луна и Протекторат – вы, может быть, о нас слыхали) и я хотели бы поговорить с вами о той работе, которую вы проводите для Фэндрала Оленьего Шлема в Дарнассе. Прежде чем мы пойдём дальше, я хотел бы попросить вас, чтобы этот разговор остался строго между нами. Если вы с этим согласны, мы можем продолжать.", female = "Благодарю вас за ваш визит, усталая путница! Позвольте представиться: я – Квинтис Ночной Костёр, друид и скромный слуга Малфуриона и Круга Кенария. Мои коллеги (генерал Шандриса Оперённая Луна и Протекторат – вы, может быть, о нас слыхали) и я хотели бы поговорить с вами о той работе, которую вы проводите для Фэндрала Оленьего Шлема в Дарнассе. Прежде чем мы пойдём дальше, я хотел бы попросить вас, чтобы этот разговор остался строго между нами. Если вы с этим согласны, мы можем продолжать." },
    ["3788a"] = { common = "Простите, друг мой… Один мой коллега хотел бы побеседовать с вами об исследованиях, которые вы ведёте в сотрудничестве с Кругом Кенария. Это друид по имени Квинтис Ночной Костёр. Он проживает здесь же, в Крепости Оперённой Луны. Он хотел бы поговорить с вами насчёт рассветницы... а главное, очень просит вас, чтобы эта беседа не дошла до ушей верховного друида. Если вас это интересует, поговорите с ним, и вам всё станет ясно." },
    ["3788c"] = { male = "Благодарю вас, что явились ко мне, усталый путник! Позвольте представиться. Я – Квинтис Ночной Костёр, друид и смиренный служитель Малфуриона и Круга Кенария. Мои коллеги (генерал Шандриса Оперённая Луна и Протекторат – быть может, вы о нас слышали), и я хотел поговорить с вами о работе, которую вы ведёте в Дарнассе по поручению Фэндрала Оленьего Шлема. Но прежде, чем мы продолжим наш разговор, я хотел бы вас попросить, чтобы эта беседа осталась между нами. Если вы не против, то мы можем перейти к делу.", female = "Благодарю вас, что явились ко мне, усталая путница! Позвольте представиться. Я – Квинтис Ночной Костёр, друид и смиренный служитель Малфуриона и Круга Кенария. Мои коллеги (генерал Шандриса Оперённая Луна и Протекторат – быть может, вы о нас слышали), и я хотел поговорить с вами о работе, которую вы ведёте в Дарнассе по поручению Фэндрала Оленьего Шлема. Но прежде, чем мы продолжим наш разговор, я хотел бы вас попросить, чтобы эта беседа осталась между нами. Если вы не против, то мы можем перейти к делу." },
    ["3789a"] = { male = "герой, простите, но нельзя ли отвлечь вас на минутку от ваших дел? Круг Кенария в Дарнассе приглашает искателей приключений для участия в жизненно важном проекте. Я не знаю всех подробностей, собственно, могу сказать только, что верховный друид Фэндрал Олений Шлем рассылает это приглашение. Если вас это интересует, обратитесь к нему напрямую, вы найдёте его в дарнасском анклаве Кенария.", female = "героиня, простите, но нельзя ли отвлечь вас на минутку от ваших дел? Круг Кенария в Дарнассе приглашает искателей приключений для участия в жизненно важном проекте. Я не знаю всех подробностей, собственно, могу сказать только, что верховный друид Фэндрал Олений Шлем рассылает это приглашение. Если вас это интересует, обратитесь к нему напрямую, вы найдёте его в дарнасском анклаве Кенария." },
    ["3789c"] = { male = "Что же, герой... поскольку вам сказали, что этими исследованиями руковожу лично я, то вы, несомненно, прибыли сюда так быстро, как могли. И раз уж вы здесь, постарайтесь запомнить мои пояснения с первого раза, ибо повторять я не буду.", female = "Что же, героиня... поскольку вам сказали, что этими исследованиями руковожу лично я, то вы, несомненно, прибыли сюда так быстро, как могли. И раз уж вы здесь, постарайтесь запомнить мои пояснения с первого раза, ибо повторять я не буду." },
    ["3790a"] = { male = "Простите, герой, не уделите ли вы мне крупицу вашего времени? Дарнасский Круг Кенария набирает опытных искателей приключений – вроде вас – для помощи в жизненно важном исследовательском проекте. Подробностей я не знаю, но могу сказать, что исследованиями руководит ни кто иной, как сам верховный друид Фэндрал Олений Шлем. Прошу вас, если вам интересно, поговорите с лим лично в анклаве Кенария в Дарнассе.", female = "Простите, героиня, не уделите ли вы мне крупицу вашего времени? Дарнасский Круг Кенария набирает опытных искателей приключений – вроде вас – для помощи в жизненно важном исследовательском проекте. Подробностей я не знаю, но могу сказать, что исследованиями руководит ни кто иной, как сам верховный друид Фэндрал Олений Шлем. Прошу вас, если вам интересно, поговорите с лим лично в анклаве Кенария в Дарнассе." },
    ["3790c"] = { male = "Что же, герой... поскольку вам сказали, что этими исследованиями руковожу лично я, то вы, несомненно, прибыли сюда так быстро, как могли. И раз уж вы здесь, постарайтесь запомнить мои пояснения с первого раза, ибо повторять я не буду.", female = "Что же, героиня... поскольку вам сказали, что этими исследованиями руковожу лично я, то вы, несомненно, прибыли сюда так быстро, как могли. И раз уж вы здесь, постарайтесь запомнить мои пояснения с первого раза, ибо повторять я не буду." },
    ["3791a"] = { common = "Я буду с вами откровенен. Меня интересует – точнее, тревожит вопрос, почему верховный друид в Дарнассе пользуется именем и возможностями Круга Кенария для того, чтобы добывать огромное количество рассветницы. Я – исследователь, и специализируюсь на проклятиях. И я слышал, что рассветница в соответствующих условиях приобретает те же свойства, что и прочие травы, используемые в примитивных проклятиях. Я хотел бы узнать об этом подробнее. И мне нужна ваша помощь. Принесите мне десять рассветниц, и я буду у вас в долгу!" },
    ["3791c"] = { common = "Какое... какое странное ощущение вызывают у меня эти растения! Во имя Элуны, что же затеял Олений Шлем? Ну, как бы то ни было, спасибо вам за помощь. Вот кое-что... ну, понимаете, за труды. Мои исследования, несомненно, затянутся, и мне потребуется ещё немало такой травы. Раз уж я этим занялся, пожалуй, стоит проверить, пригодна ли рассветница для использования в алхимии. И тем не менее мне не по себе от этих растений..." },
    ["3801a"] = { common = "Привет тебе, путник. Я Франклорн Искусник. Да, тот самый Франклорн Искусник, который придумал, как тесать камень. За долгие странствия по терзаемому войнами миру тебе несомненно случалось проходить сквозь мои творения или стоять на них. Должно быть, тебе интересно, откуда я здесь и что мне от тебя нужно. Логичные вопросы. Разумеется, мне нужна твоя помощь. В обмен на неё я дарую тебе ключ, открывающий путь в глубины моего проклятого города." },
    ["3801c"] = { common = "Жадность ли привела тебя сюда или слепая верность, от твоего предприятия будет благо нам всем." },
    ["3802a"] = { common = "Точень Темнострой находится за Кольцом Закона в Зале Ремесла. Убей ничтожную тварь и забери Железного Друга. Отнеси Железного Друга в святилище Тауриссана и помести молот в предначертанное ему место: в руки статуи, воздвигнутой в мою честь. После этого откроется тайное отделение, в котором я спрятал главный ключ. А главное, Железный Друг навеки останется в моих руках. Если они предпримут попытку забрать его, то статуя и молот рассыплются и исчезнут вовек." },
    ["3802c"] = { common = "Молот легко встаёт на место, в руку массивного монумента Чёрного Железа. У основания статуи открывается тайное отделение. Внутри оказывается…" },
    ["3821a"] = { common = "Несколько недель назад Ша'ни была отправлена в Пылающие степи, чтобы исследовать странные ритуалы огров клана Огненного Чрева — что-то эти огры зашевелились в последнее время. Клинозуб сообщил мне, что от её группы с тех пор не было вестей, и что главное сейчас — заняться неотложными делами. Представляешь?! А речь, между прочим, о моей жене! Я не вправе оставить свой пост, но я должен знать, что случилось с Ша'ни! Отправляйся в Пылающие степи и найди её!" },
    ["3821c"] = { common = "Ах, мой бедный Тал'трак. Мы планировали отправиться жить к моим родителям во Внутренние земли после того как закончим службу. Теперь этим планам пришёл конец!" },
    ["3822a"] = { common = "Они захватили весь мой взвод, путник. И всех, кроме меня, убили. Их главарь, Кром'Грул, оставил меня для совершения какого-то обряда. Меня приковали к этому алтарю и жестоко пытали. Через час мучений моё физическое тело умерло. Тогда эта тварь вырвала у меня из носа обручальное кольцо и напялила на свой палец. В жизни не встречала подобного варварства! Найди Кром'Грула и убей его! отнеси моё кольцо Тал'траку. И путник, скажи ему, что мы снова встретимся… в следующей жизни." },
    ["3822c"] = { common = "Мы хотели перебраться во Внутренние земли. Она сказала тебе? Это было её последнее задание! Я не хочу его, путник. Оставь себе, мне плевать… Кольцо теперь не значит для меня ничего… Без неё…" },
    ["3823a"] = { common = "Мы должны нанести удар первыми! Буду краток. Огры Огненного Чрева — союзники орков Чёрной Горы в Пылающих степях. Рука об руку они охраняют богатую полезными ископаемыми скалу Молота Ужаса и линии снабжения. Оставь свой след в истории, путник. Смети их охрану и возвращайся ко мне. Я тебя прибью, Винкей!" },
    ["3823c"] = { common = "Великолепно, солдат! Орки и огры будут ошеломлены от твоего нападения. Они придут в себя только через несколько часов!" },
    ["3824a"] = { common = "Говорю же, они колеблются! Пора нанести решительный удар. Мы должны убить жестокого вождя, Гор'теша. И что ещё важнее, мне нужна его голова для третьей фазы операции против огров Огненного Чрева. И помни, солдат, Гор'теш правит не из скалы Молота Ужаса, но из строения орков Чёрной Горы на западе от неё. Итак, приказы тебе даны ясные. Найди Гор'теша и отруби ему башку. Потом возвращайся ко мне. ЗАТКНИСЬ, Винкей!" },
    ["3824c"] = { common = "Только посмотри на это, солдат. Круто! Когда оставшиеся огры Огненного Чрева увидят эту жирную, гнусную башку на крепкой, хорошей пике над нашей башней, у них начнётся массовая истерика!" },
    ["3825a"] = { common = "Осталось только одно задание, солдат. Я позволил себе вольность — нанизал голову Гор'теша на пику. Тебе остаётся отнести её на вершину скалы Молота Ужаса и воткнуть в землю. Стоит только сделать это, как трусливые огры бросятся куда глаза глядят! Когда ты повеселишься от души, возвращайся ко мне, и я награжу тебя за проделанную работу." },
    ["3825c"] = { common = "Отличная работа, солдат! Просто поразительно! Я получу медаль за храбрость после этого, э-э, то есть я имел в виду: тебя представят к награде!" },
    ["3841a"] = { male = "О, привет! Я так рада видеть тебя снова! Как твоё путешествие в Дарнасс? А у нас тут приятные новости! Пока тебя не было, мы сумели многого добиться. Мы даже спасли целую кладку яиц! К сожалению, самка погибла прежде, чем мы подоспели… Слушай, хочешь себе такого дракончика? Детёныши скоро должны вылупиться, и им понадобится хороший папа. Ну, что скажешь? Если тебя это действительно интересует, возьми одно из яиц и ступай к Квентину, который находится на Мерцающей равнине, возле гоночной трассы. Он тебе скажет, что делать дальше.", female = "О, привет! Я так рада видеть тебя снова! Как твоё путешествие в Дарнасс? А у нас тут приятные новости! Пока тебя не было, мы сумели многого добиться. Мы даже спасли целую кладку яиц! К сожалению, самка погибла прежде, чем мы подоспели… Слушай, хочешь себе такого дракончика? Детёныши скоро должны вылупиться, и им понадобится хорошая мама. Ну, что скажешь? Если тебя это действительно интересует, возьми одно из яиц и ступай к Квентину, который находится на Мерцающей равнине, возле гоночной трассы. Он тебе скажет, что делать дальше." },
    ["3841c"] = { common = "О, яйцо летучего хамелеона! И вот-вот должно проклюнуться, если я не ошибаюсь. Удивительно, как тебе удалось его добыть, да ещё в таком хорошем состоянии? В Фераласе в наше время эти животные почти не делают кладок... Насколько я понимаю, в тамошних лесах развелась уйма браконьеров, которые охотятся на этих прекрасных созданий и убивают их. Какая жалость, не правда ли? Но откуда у тебя это яйцо?" },
    ["3842a"] = { common = "Кайдел и Джеркай? Занятно... Жаль, что летучие хамелеоны не смогут оценить всё, что эти девушки для них делают. Очень, очень способные девочки… Так значит, они дали тебе это яйцо в подарок? Что ж, теперь оно твоё и ты за него отвечаешь. Оно, похоже, вот-вот проклюнется, но нужно ещё позаботиться о том, чтобы детёныш вылупился здоровым. Для заклинания, которое будет защищать яйцо, мне требуется только два эликсира стойкости. Остальные компоненты у меня уже есть." },
    ["3842c"] = { common = "Великолепно! Это то, что надо. Сейчас, я смешаю все компоненты, и мы поглядим, как будет себя чувствовать детёныш..." },
    ["3843a"] = { common = "Великолепный экземпляр! Если это создание благополучно вылупится на свет, у тебя будет прекрасный, здоровый питомец! Но если ты рассчитываешь оставить его себе, я бы посоветовал сделать ещё одну вещь. Отправляйся на Заоблачный Пик во Внутренних землях, и поговори там с дворфом по имени Агнар Зверопас. Он большой специалист по дрессировке животных, и объяснит тебе, что нужно делать дальше. Только ступай скорее, яйцо хрупкое и без должного ухода долго не протянет!" },
    ["3843c"] = { male = "Так-так-так... Таких мелких я даже и не видел. Лесной дракончик, если не ошибаюсь... точнее, летучий хамелеон. Отлично, отлично! Ну, чтобы этот малыш благополучно выжил и вырос крепким и здоровым, нужно раздобыть для него еды! Хорошо, что ты вовремя до меня добрался!", female = "Так-так-так... Таких мелких я даже и не видел. Лесной дракончик, если не ошибаюсь... точнее, летучий хамелеон. Отлично, отлично! Ну, чтобы этот малыш благополучно выжил и вырос крепким и здоровым, нужно раздобыть для него еды! Хорошо, что ты вовремя до меня добралась!" },
    ["3844a"] = { common = "На берегу вы видите разбитый плот. Если учесть, что пруд очень мал, непонятно, как мог оказаться в нем плот, да ещё такой побитый непогодой. Хотя, более пристальный взгляд на деревья даёт возможность предположить, что уровень воды здесь не постоянный… Возможно, если приглядеться повнимательней, можно отыскать ключ к загадке…" },
    ["3844c"] = { common = "На дне пруда виднеется какой-то свёрток." },
    ["3845a"] = { common = "Вы вытаскиваете сумку на берег, в надежде, что её содержимое укажет вам на то, откуда она могла взяться и кому бы могла принадлежать. Всё же немногие путники забредают в Укрытие Маршалла…" },
    ["3845c"] = { common = "О, а вот это, похоже, и в самом деле мне знакомо!" },
    ["3861a"] = { common = "\"... Кудах... кудах... Куд-кудааааа! Кудах...кудах-тах-тах... \" Курица смотрит на вас и начинает что-то царапать на земле лапой. Вам кажется, что это какое-то слово, но вы не уверены, какое именно. Может... С-А-Л-Ь-Д-Е-А-Н? Прежде чем вы успеваете спросить, курица уходит по своим делам." },
    ["3861c"] = { common = "\"Куд-кудааа!!!\" Курица начинает жадно клевать корм, который вы рассыпали перед ней. Через несколько мгновений она испуганно оглядывается по сторонам. Начинает скрести лапой и суетиться. Она что, яйца снести хочет? Вы думаете, что надо бы заглянуть под неё." },
    ["3881a"] = { common = "Не знаю, какими судьбами ты оказался здесь, но ты для нас желанный гость! Меня зовут Виллиден Маршал, я здесь с самостоятельной исследовательской экспедицией. Последняя и самая важная наша кампания столкнулась с многочисленными трудностями. Пожалуй, наиболее существенным нашим просчётом было то, что мы недооценили опасность, которую несёт в себе дикая природа Кратера Ун'Горо. Нам пришлось в спешке покинуть наши базовые лагеря в северо-восточной и юго-западной областях кратера, побросав жизненно-важные припасы. Ты выглядишь весьма внушительно — не поможешь ли нам вернуть их?" },
    ["3881c"] = { common = "О, ты привёз нам и нашу провизию, и наши инструменты! Ты не просто спас экспедицию, ты спас нам жизнь! Теперь-то мы сможем здесь продержаться! Не знаю, как благодарить тебя! Хоть мы тут небогаты, без награды ты не останешься. Знай, путник, в экспедиции Маршалла у тебя есть друзья, готовые помочь в любую минуту!" },
    ["3882a"] = { common = "Думаешь, раз в экспедиции Маршала я ответственный за раскопки, то мне страшно нравится копаться в земле? Нет, я, конечно, мог бы придумать более паршивое занятие, но сейчас что-то ничего не приходит в голову. Мы должны были вести раскопки в местечке под названием Путь Ужаса — неплохое название, не находишь? Искать, значит, там дохлых стегодонов и деметродонов… А их там, между прочим, и живых полным полно! Вил и Хол, видишь ли, хотят изучать это гиблое место, поэтому мы должны исправно поставлять им кости динозавров. Между нами говоря, живые для этих целей сгодились бы не хуже!" },
    ["3882c"] = { common = "Прекрасно, отличные кости, ну просто прелесть, что за кости! СПАСИБО, ЧТО ВЫРЫЛ ДЛЯ НАС ЭТИ ДРЕВНЕЙШИЕ КОСТИ И НЕ ОХОТИЛСЯ НА ЖИВОТНЫХ, ЧТО МОГЛО БЫ НАНЕСТИ НЕПОПРАВИМЫЙ УЩЕРБ ОКРУЖАЮЩЕЙ СРЕДЕ! Тихо, тихо, не спорь со мной, мне совершенно неинтересно, где ты на самом деле их взял, так что давай замнём этот вопрос за ясностью. Вот, возьми это в награду и держи рот на замке, хорошо?" },
    ["3883a"] = { common = "То, что мы потерпели неудачу, ещё не значит, что исследования надо прекратить! Мы изучали насекомых Гориши в южной части кратера, прежде чем были вынуждены ретироваться сюда. Их присутствие чуждо для экологии Ун'Горо, и мы должны разобраться почему. В их ульях должны быть инкубаторы для личинок. Эти места можно определить по свисающим гроздьям личинок. Возьми образец стены улья рядом с инкубатором вот в этот фиал и принеси его мне на исследование. Но будь осторожен!" },
    ["3883c"] = { common = "Да, прекрасная работа. Ты очень помог нам… я хотела бы дать тебе больше чем то немногое, чем я располагаю. Будь уверен — наши исследования были бы невозможны без тебя." },
    ["3884a"] = { common = "Вы обнаружили изорванный дневник. Кое-какие страницы ещё можно прочесть, в том числе и форзац, на котором значится имя Виллидена Маршала. Если верить написанному в дневнике, Виллидена можно найти где-то на севере кратера, куда он и его товарищи были вынуждены бежать от диких зверей, напавших на их базовый лагерь." },
    ["3884c"] = { male = "Вы только взгляните на это! Мой дневник! Я думал, он утерян навсегда, как в всё, что нам пришлось бросить в базовом лагере. Спасибо, что вернул мне его!", female = "Вы только взгляните на это! Мой дневник! Я думал, он утерян навсегда, как в всё, что нам пришлось бросить в базовом лагере. Спасибо, что вернула мне его!" },
    ["3901a"] = { male = "Ты уже продемонстрировал свой потенциал в обычных обстоятельствах, а теперь давай посмотрим, как ты будешь действовать под давлением. Скелеты-костетрясы – ещё одни безмозглые приспешники Короля-лича – более серьёзные враги, чем зомби, с которыми ты сталкивался до этого. Я попрошу тебя уменьшить их количество и проявить себя среди Отрёкшихся. Не мешкай! Когда всё будет сделано – возвращайся ко мне.", female = "Ты уже продемонстрировала свой потенциал в обычных обстоятельствах, а теперь давай посмотрим, как ты будешь действовать под давлением. Скелеты-костетрясы – ещё одни безмозглые приспешники Короля-лича – более серьёзные враги, чем зомби, с которыми ты сталкивалась до этого. Я попрошу тебя уменьшить их количество и проявить себя среди Отрёкшихся. Не мешкай! Когда всё будет сделано – возвращайся ко мне." },
    ["3901c"] = { male = "Отличная работа. Ты показал, что достоин свободы, которая была тебе дана. Многие будут ненавидеть тебя за то, кем ты стал, но знай: что бы они ни замышляли против нас, мы свободны, и никто не сможет вновь поработить Отрёкшихся. Вот, возьми это и ступай своей дорогой. Тебя ждут великие дела, герой.", female = "Отличная работа. Ты показала, что достойна свободы, которая была тебе дана. Многие будут ненавидеть тебя за то, кем ты стала, но знай: что бы они ни замышляли против нас, мы свободны, и никто не сможет вновь поработить Отрёкшихся. Вот, возьми это и ступай своей дорогой. Тебя ждут великие дела, героиня." },
    ["3902a"] = { common = "Эй, ты! Если ищешь, что бы такого сделать полезного, слушай сюда! Нам нужны свеженькие рекруты, только что из могилы, которых можно направить в Могильник, чтобы они поискали там что-нибудь стоящее из экипировки. Скорее всего, там будут груды ящиков. Мы надеемся, что вскоре поднимутся новые рекруты, а поскольку нам вовсе не надо, чтобы они слонялись тут голыми, надо бы поскорее чем-нибудь поживиться! А теперь за работу, несчастный ты мешок с костями! Я не собираюсь платить тем, кто еле двигается." },
    ["3902c"] = { common = "Отличная работа, я так и думал, что ты не совсем бесполезное существо. А это тебе – одна из лучших вещичек среди тех, что мы собрали." },
    ["3903a"] = { male = "Ты показал себя надёжным герой. Да и тяжёлой работы не боишься, не правда ли? У меня есть подруга, Милли Осворт. У неё какие-то проблемы. Она вместе со своим фургоном находится по другую сторону аббатства, у стойл. Думаю, ей очень пригодится твоя помощь.", female = "Ты показала себя надёжной героиня. Да и тяжёлой работы не боишься, не правда ли? У меня есть подруга, Милли Осворт. У неё какие-то проблемы. Она вместе со своим фургоном находится по другую сторону аббатства, у стойл. Думаю, ей очень пригодится твоя помощь." },
    ["3903c"] = { common = "О, заместитель судьи Виллем просил тебя поговорить со мной? Он отважный человек и всегда готов помочь, но дела не дают ему покинуть Аббатство Североземья, да к тому же, боюсь, нынешняя моя проблема ему не по плечу. Возможно, ты мне поможешь." },
    ["3904a"] = { common = "Шайка бандитов, это Братство Справедливости, проникла в Виноградники Североземья во время сбора урожая! Я сообщила об этом стражникам, и они заверили меня, что разберутся с этим делом, но... я боюсь за виноград! Если мой урожай не украдут грабители, так наши стражники потопчут! Прошу тебя, помоги мне! Я собрала большую часть винограда в корзины, но оставила их в виноградниках на юго-востоке. Принеси мне мой виноград, пожалуйста!" },
    ["3904c"] = { male = "Ох, спасибо тебе. Ты спас мой урожай! И, надеюсь, ты показал этим бандитам, что тут им хозяйничать не позволят! Может, стражи нам тут нынче и не достаёт, но зато у нас есть такие герои, как ты!!!", female = "Ох, спасибо тебе. Ты спасла мой урожай! И, надеюсь, ты показала этим бандитам, что тут им хозяйничать не позволят! Может, стражи нам тут нынче и не достаёт, но зато у нас есть такие герои, как ты!!!" },
    ["3904p"] = { common = "Ты принёс мой виноград, путник?" },
    ["3905a"] = { common = "Теперь, когда мой урожай спасён, отнеси это уведомление о поставке винограда брату Нилзу. Он ведает съестными припасами в Североземье, и я уверена, что он обрадуется, узнав, что у него будет свежий виноград. Брата Нилза ты найдёшь в аббатстве, в звоннице – он там любит... дегустировать вино." },
    ["3905c"] = { common = "Так, что у нас тут... Хвала Свету! Виноград Милли спасён! Когда она сказала мне, что эти бандиты разнесли её виноградники, я чуть не впал в уныние, но моя вера в Свет не дрогнула! И благодаря твоей отваге теперь у нас есть виноград для вина! Да хранит тебя Свет!" },
    ["3905p"] = { common = "Сдаётся мне, ты в хорошем настроении! Сядь, отдохни тут немножко. Хочешь вина?" },
    ["3906a"] = { common = "Старейшины говорят, духи стихий в последнее время неспокойны. Дворфы Чёрного Железа вызвали в наш мир злобного духа, и теперь он угрожает вечной засухой нашим землям. Мы должны найти причину беспокойства духов. Отправляйся к Чёрной горе, через пропасть Пламени, прямо в карьер. Найди там владыку огня — Подчинителя Пирона — и положи конец его злодеяниям!" },
    ["3906c"] = { common = "Этого не может быть… Уничтожение Пирона не привело к восстановлению порядка! Оказывается в глубинах Чёрной Горы есть ещё более сильный источник порчи!" },
    ["3907a"] = { common = "Я чувствую скверну в воздухе, путник! Источник её скрывается в глубинах Чёрной горы. Имя его в стонах земли и ветра: лорд Опалитель… Но это ещё не всё: кто-то или что-то повелевает им. Сам он — лишь инструмент в более могущественных руках. Найди его и выясни, где скрывается его повелитель. Возвращайся ко мне, когда всё разузнаешь." },
    ["3907c"] = { common = "Рагнарос… здесь… Старейшины были правы… Они боялись скверну Чёрной горы. Генерал Древних Богов! В НАШЕМ МИРЕ! Нам нужно переоценить нашу позицию в Каргате. Нам надо решить, будем ли мы драться, или сломя голову бежать отсюда. Аккуратнее в Чёрной горе, путник. Не разбуди ненароком древнее зло." },
    ["3908a"] = { common = "Видишь ли, я совершенно не представляю, как здесь оказался — просто тайна, покрытая мраком! Мне кажется, я вообще ничего не помню… Эти вещи всё же кажутся мне знакомыми… Мой меч. Я должен был как-то укрепить его, но совершенно не помню зачем? Мне жаль, что не могу сказать тебе больше, но я и в самом деле ничего не помню. В любом случае, я знаю куда это отнести — к Донове Снегоноре в Зимние Ключи. Она может закалить меч в местных горячих источниках." },
    ["3908c"] = { common = "Ну конечно, я могу закалить меч. А пока я работаю, расскажи мне, что так задержало Линкена. Обычно он не забывает о важных вещах." },
    ["3909a"] = { common = "Что такое? Линкен ЗАБЫЛ ВСЁ? Ясно, потеря памяти… Вот его меч. Он не закончен. Я знаю, кто может закончить его, но… Поговорить с ним — непростая задача. Однако, я знаю, кто сможет тебе помочь. Не буду вдаваться в подробности прямо сейчас, скажу только, что тебе необходимо любым способом заполучить эликсир Видере. Единственный, кто может помочь тебе в этом — Греган Пивоплюй. Его нелегко отыскать, но говорят, что недавно его видели в лесах Фераласа." },
    ["3909c"] = { common = "Мне нужен один флакон, чтобы убедиться, что это эликсир… Да… Это вещество." },
    ["3911a"] = { common = "У меня есть работа для тех, кто не боится сунуться в глубины! Клан Чёрного Железа научился создавать чрезвычайно мощных големов. Исходя из отчётов, присланных нашими шпионами, дворфы используют уникальные источники энергии, чтобы придать своим гоблинам невероятную разрушительную силу. Подумать только, что мы могли бы сделать с нашими поганищами, заполучи мы сущность Стихий, которую они используют... Можешь перевернуть город вверх дном, но я должна получить эту сущность. Без неё можешь не возвращаться! По усердию и награда." },
    ["3911c"] = { common = "Замечательно! Я немедленно отправлю их курьером в Подгород! Для вас - оплата, как и было обещано." },
    ["3912a"] = { common = "Этот эликсир позволит тебе говорить с существами, которые обычно незримы. Возьми эликсир Видере и меч Линкена и отправляйся на кладбище на окраине Прибамбасска в Танарисе. Будешь на месте, выпей эликсир. Результат может показаться тебе неожиданным, но не впадай в панику. В том обличье, которое ты примешь, отправляйся на север, в горы. Тот, кто тебе нужен, скрывается в скалистых ущельях. Его имя Гаэриан. Помни, ты сможешь поговорить с ним только переменив облик…" },
    ["3912c"] = { common = "Уже давно никто не приходил ко мне поговорить…" },
    ["3913a"] = { common = "Когда вернёшься на кладбище, путник, увидишь там могильный камень, стоящий особняком. Под ним скрываются многие секреты! Отодвинь его, и тайны откроются тебе!" },
    ["3913c"] = { common = "Вы легонько толкаете камень, и он уходит в сторону, открывая за ним маленькое углубление. Положив туда меч Линкена, вы с удивлением замечаете что он идеально вписывается в углубление!" },
    ["3914a"] = { common = "Вокруг меча вспыхивает ослепительно яркое пламя. После того как оно угасло, вы можете снова взять меч. Он изменился!" },
    ["3914c"] = { common = "Мой меч… Он закончен! Теперь, если бы я мог вспомнить, для чего он мне был нужен… Вот, держи, пока я не забыл, что должен тебе заплатить…" },
    ["3921a"] = { common = "Мне кажется, я сломал самофланж. Это плохо, потому что я успел рассказать о нём нескольким коллегам из Нижней шахты, и они очень заинтригованы. Надо починить его! Отнеси сломанный самофланж Венаки Бенике, который живёт на юге от заставы Мор'шан, лагеря Орды между Степями и Ясеневым лесом. Она очень умная и любопытная. Покажи ей самофланж, и я не сомневаюсь, что она не упустит возможности починить его." },
    ["3921c"] = { common = "Что это? Самофланж, говоришь? Что такое самофланж?? А... Посмотри, как он вибрирует, когда берёшь его в руки. А внутри жужжат сложные шестерёнки. Ух ты! Мне хочется починить его и узнать, зачем он тебе?" },
    ["3922a"] = { common = "Я готова заняться самофланжем, но для этого мне понадобятся запчасти. У меня кончились семнадцати с половиной миллиметровые заготовки для деталей, а для работы понадобится целая куча. Проще всего их достать у Нефтяного болота на востоке. Торговая Компания обычно хранит их в вёдрах с инструментами. Ступай туда и поищи эти штуковины, а набрав достаточно, возвращайся." },
    ["3922c"] = { common = "О, ты принёс их! Теперь я могу приступить к работе..." },
    ["3923a"] = { common = "Увы, у меня ничего не вышло. Я добавила в самофланж несколько новых индикаторов, чтобы проверить его структурную целостность, и согласно им, структурная целостность на нуле. Я могу добавить пару циферблатов и рычаг-другой, но... Думаю, станет только хуже. Отнеси самофланж Рилли Грязегобу. Он работал на Торговую Компанию, и уж если Рилли не сможет починить эту штуку, то пиши пропало. Он работает в механической мастерской Ногга в Оргриммаре, в Аллее Чести." },
    ["3923c"] = { male = "Что это? Надо же, самофланж. Откуда он у тебя? Неужели ты рыскал по владениям Торговой Компании в Степях? Интересно, это говорит о смелости или о глупости?", female = "Что это? Надо же, самофланж. Откуда он у тебя? Неужели ты рыскала по владениям Торговой Компании в Степях? Интересно, это говорит о смелости или о глупости?" },
    ["3924a"] = { common = "Думаю, я смогу починить самофланж, но для этого мне понадобится руководство пользователя. В Торговой Компании у меня был соперник, начальник Медноклин. Он ревностно хранил тайны самофланжа и лишь частицы знания доверял самым надёжным своим сторонникам. Я не входил в число избранных... Начальник Медноклин работает в северо-восточной части Степей, на Каменном карьере." },
    ["3924c"] = { common = "Ты принёс руководство! Мне не терпится узнать, как починить самофланж! Я говорил с Пароклапаном из Кабестана, и он просил поблагодарить тебя за услуги и вознаградить за них. Я тоже весьма признателен, и если починю-таки эту штуку, сразу тебе сообщу..." },
    ["3941a"] = { common = "Думай, голова! Думай, шапку подарю… Я помню, что явился сюда с какой-то очень серьёзной целью. Но совсем не помню с какой! Есть идея, путник! Вон там, в пещерах живёт гномесса по имени Джей Ди, я помню, она была очень добра ко мне, когда я впервые оказался здесь. Может, она сможет что-то рассказать. Спроси её! Только осторожней, она всё время возится с этими ужасными светящимися кристаллами, которых полно в этом кратере. Не знаю, зачем уж они ей нужны…" },
    ["3941c"] = { common = "Стой там, где ты стоишь,… стой, тебе говорят. Я проверяю свою новую комбинацию кристаллов." },
    ["3942a"] = { common = "О, Линкен? Да, смешной парень… Когда он впервые оказался здесь, бормотал всякую ерунду. Наверное, кто-то как следует двинул бедняге по голове! Однако кое-что из той чепухи, которую он нёс, крепко засело у меня в памяти. Помню, он говорил, что делает какой-то тотем, и что ему необходимо поговорить с какой-то Эриданой Грустью Ветра… кажется, в месте, называемом Осквернённый лес. Думаю, если хочешь узнать больше, тебе следует отправиться прямиком к этой Эридане." },
    ["3942c"] = { common = "Привет, герой. Чем я могу быть полезна?" },
    ["3961a"] = { common = "Лично я полагаю, что Линкен явился сюда, чтобы избавить нас от Яропламеня… Он кажется простым парнем, однако он совсем не интересуется моими экспериментами и механизмами, как большинство гномов. Должно быть, в глубине души он истинный воин. Отдай тотем ему. Возможно, это поможет ему вспомнить, зачем он пришёл сюда." },
    ["3961c"] = { common = "Помогла ли тебе Джей Ди?" },
    ["3962a"] = { common = "Путник, я наконец-то вспомнил… Я пришёл сюда, чтобы сразиться с Яропламенем! Это и есть цель моего путешествия! Но я больше не герой… потому что герой стоит передо мной. Теперь ты должен закончить начатое. Яропламень стережёт артефакт, именуемый Золотым пламенем. В нём кроется сила более мощная, чем что-либо мне известное, поэтому этот артефакт не должен попасть в дурные руки. И мой тебе совет — не ходи один. Один в поле не воин." },
    ["3962c"] = { common = "Спасибо тебе, путник. Золотое пламя теперь вернётся на мою родину и никогда не будет использовано для зла. Без тебя всё это не стало бы возможным… И поскольку ты столько для меня сделал, у меня есть для тебя нечто особое… Бери, выбирай любой!" },
    ["3981a"] = { common = "Бедняга Гаргал… Он даже не успел ничего понять как — бац! — стрела вонзилась прямо ему в башку… Он и прежде гением не был, а теперь уж… Когда мы вытащили стрелу, заметили записку, прикрученную к древку. В ней не было ничего, кроме грубо нацарапанной картинки, изображающей, видимо, орка за решёткой, и подписи командира Гор'шака. Если он ещё жив и находится в Глубинах, ты должен отыскать его. Ловушка? Проклятье, какая ещё ловушка, что ты несёшь?! Отправляйся немедленно!" },
    ["3981c"] = { common = "У нас немного времени осталось, очень немного… слушай меня внимательно, странник. То, что я хочу тебе сказать, это только для твоих ушей." },
    ["3982a"] = { common = "Меня прислал сюда Тралл, и я нахожусь под его покровительством. Неужели ты думаешь, что эти фигляры смогли бы меня поймать? Я разведчик, и я им поддался специально, чтобы собрать информацию. Император Тауриссан похитил принцессу Стальгорна. Она сейчас здесь, в этом городе! Надо думать, когда старый Магни об этом узнал, его чуть удар не хватил. Тихо! Слышишь? Это стражники! ЗАЩИЩАЙСЯ!" },
    ["3982c"] = { common = "Смерть была рядом… Теперь они знают о твоём присутствии здесь… И придут ещё…" },
    ["4001a"] = { common = "Пока что мне не удалось толком поговорить с Караном из темницы напротив. Однако я всё-таки смог убедить его в том, что я — то есть мы — не обидим его и не сделаем ему ничего плохого. Поговори с ним и попробуй узнать о принцессе и её похитителях. Всю информацию, которую удастся собрать, передай вождю. Тралл не хочет, чтобы с принцессой что-то случилось. У него даже есть план, как вернуть её в целости и сохранности в Стальгорн, и Карану всё это уже известно… Иди!" },
    ["4001c"] = { common = "Это шанс для Орды изменить политическую обстановку потрёпанной от войны. Слушай внимательно, путник. Провал этой миссии будет не лучшим вариантом." },
    ["4002a"] = { common = "Принесённые тобой сведения чрезвычайно ценны, путник. Я — вождь, и мой долг — действовать на благо Орды, так, чтобы грядущие поколения не были обречены на безнадёжное прозябание! И вот нам выпала возможность определить судьбу будущих союзов. Выступив на помощь дворфам, мы значительно укрепим свои взаимоотношения с Восточными королевствами. Вот почему твой долг — вернуться с победой! Готов ли ты?" },
    ["4002c"] = { common = "Теперь уже нет пути назад, путник." },
    ["4003a"] = { common = "Этот удар, нанесённый дворфам Чёрного Железа, способен потрясти их королевство до основания. Принцесса находится под контролем императора Тауриссана. Чтобы её освободить, необходимо убить императора. Имей в виду, твоя задача вдвойне опасна: пока принцесса находится во власти императора, она нападёт на тебя, не раздумывая. Ни в коем случае не причиняй ей вреда!!!" },
    ["4003c"] = { common = "Что ты наделал!" },
    ["4004a"] = { common = "Ты убил моего мужа, странник! Мой ребёнок родится на свет без отца! Истинно говорю тебе, это дитя станет следующим королём Стальгорна. И тогда берегись! Этим преступным деянием ты навлёк на себя проклятие. Возмездие настигнет тебя и твой род. Всех вас будут травить до скончания дней! Оставь меня, странник. Поторопись к своему нанимателю. Наверняка он с нетерпением ждёт вестей об исполнении его гнусных замыслов." },
    ["4004c"] = { common = "Новая угроза маячит на горизонте. С каждым годом жизни Магни сокращается, тем самым, открывая путь к трону Стальгорна ещё не родившемуся наследнику с Чёрного Железа. Ты сделал то, что я просил и за это будешь вознаграждён. А теперь, путник, оставь меня! Я должен посоветоваться с Кэрном и Сильваной." },
    ["4005a"] = { common = "Возьми этот мешок с припасами и отнеси в Танарис. Отправляйся в Бухту Сорванных Парусов и найди круг камней. Встав в этот круг, прочти заклинание из книги Аквора и вызови единственное создание, способное превратить собранные тобой предметы в тотем, с помощью которого можно сразить Яропламеня! Акваментас не любит, когда его будят, но помни, ты должен быть внутри круга, когда будешь читать заклинание!" },
    ["4005c"] = { common = "Говоришь, Яропламень… Да, я осведомлена о том, что мощный и злобный элементаль бродит в центре кратера. Но мы просто обходим его стороной, так как не в силах бороться с ним. Ты что, хочешь попробовать?" },
    ["4021a"] = { common = "Орда благодарит тебя за неустанную борьбу с кланом Колкар, но сами кентавры в ярости. Я получил сообщение, что отряд клана Колкар оставил свой дом в Пустошах и прибыл в Степи, движимый местью. Более того, они прямо сейчас подбираются к нам с запада! Выступи против захватчиков из племени Колкар и положи конец опасности, грозящей Степям. Убивай их, пока не появится их вождь, предводитель Кром'зар. Одолей его и принеси в доказательство кусок его знамени. Не подведи меня." },
    ["4021c"] = { male = "Получилось! Ты победил клан Колкар! Я непременно сообщу Траллу о твоих подвигах. Можешь гордиться собой, ты – достойный сын Орды.", female = "Получилось! Ты победила клан Колкар! Я непременно сообщу Траллу о твоих подвигах. Можешь гордиться собой, ты – достойная дочь Орды." },
    ["4061a"] = { common = "Впервые мы увидели эти машины, когда начали набеги в Тлеющее ущелье. Потом выяснилось, что их привозят из Пылающих степей, вероятно, из глубин Чёрной горы. Нам нужна твоя помощь, путник. Для выполнения первого задания отправляйся в Пылающие степи и извлеки осколки элементалей из каменных машин и малых каменных созданий, которых там найдёшь. Когда соберёшь достаточно, возвращайся ко мне, и я попробую разобраться, откуда они происходят." },
    ["4061c"] = { common = "В этих фрагментах впечатана какая-то… какие-то… инициалы!" },
    ["4062a"] = { common = "Г.Л.А. Эти инициалы выгравированы на осколках элементалей. Под ними выгравирована надпись, видимо, указующая на ранг машины. Механизмы, уничтоженные тобой в Пылающих степях, имели четвёртый ранг. Полагаю, это один из низших рангов. Возьми этот образец осколка и отнеси его Лотвилю Вериатусу в лагерь на востоке. Он учёный, весьма признанный в сферах изучения стихий. Возможно, он поможет нам советом." },
    ["4062c"] = { common = "Я… я знаю эти знаки." },
    ["4063a"] = { common = "Неужели это Аргелмах? Не может быть! Он же мёртв уже много лет! Почему я так в этом уверен? Да потому что это я убил его! Этот презренный дворф имел маниакальную страсть к извращению моих изобретений — над которыми я, к слову, корпел годами! — и использованию их для своих мерзких делишек. Надо же, самые мерзкие создания всегда самые живучие! Если это и правда работа Аргелмаха, то он должен быть уничтожен. И мне потребуются образцы его последних творений. Если у меня будут образцы, возможно, я смогу придумать, как подавить восстание. Видимо, Аргелмах теперь в глубинах Чёрной горы под охраной своих творений." },
    ["4063c"] = { common = "Что это? Эта голова из чёрного железа. Тень Аргелмаха — другая машина! Ты понимаешь, что это значит? Я подозреваю, что твоё уничтожение Аргелмаха продлится недолго — так как ещё одна машина станет на его место." },
    ["4081a"] = { common = "По приказу полководца Клинозуба, командира каргатского экспедиционного отряда: Все силы генерала Кузни Гнева в Глубинах Чёрной горы должны быть истреблены. Клан Кузни Гнева — беспощадные убийцы, ответственные за уничтожение сто девятого подразделения каргатского экспедиционного отряда. Необходимо сохранять бдительность. Тот, кто сможет разбить передовые войска генерала Кузни Гнева в Глубинах Чёрной горы, будет представлен к награде." },
    ["4081c"] = { common = "Небось, после такого Кузня Гнева в штаны наложил! Теперь проходи, проходи, солдат. У меня ещё масса дел! Смотри внимательно на объявления, для тебя может найтись ещё работёнка." },
    ["4082a"] = { common = "Приказ полководца Клинозуба, командира Каргатского экспедиционного корпуса: Глава разведывательного подразделения Каргатского экспедиционного корпуса, гроссмейстер Лекслорт вернулся с рапортом о месторасположении высокопоставленных чинов Чёрного Железа. В центре города, за закрытыми воротами они обучают своих солдат уничтожать наших собратьев. Отправляйся в Глубины Чёрной горы и уничтожь их! В случае успешного выполнения задания будешь представлен к награде." },
    ["4082c"] = { common = "Безусловно, Кузня Гнева в ярости. Вернись ко мне после своего третьего задания, и мы осуществим операцию под названием \"Смерть Кузни Гнева \". Детали — потом." },
    ["4083c"] = { common = "Призрачный кубок парит в воздухе, медленно поднимаясь и опускаясь… как будто следуя ритмам биения умирающего сердца" },
    ["4084a"] = { common = "Я не знаю, о ком ты говоришь, путник. Однако если твой друг искал меня, я знаю, что ему было нужно. В сердце Кратера Ун'Горо скрывается зло в чистейшей его форме — это элементаль, именуемый Яропламень. Он защищён аурой, разрушить которую не под силу никому… Никому, кроме обладателя ещё большей силы. Я научу тебя, как справиться с этой задачей, путник. Сначала сделай, что я попрошу. Собери и принеси мне одиннадцать серебристых когтей и одно сердце Железнолесья — ты найдёшь их у созданий Осквернённого леса." },
    ["4084c"] = { common = "Очень хорошо, путник. Помощь твоя была очень кстати." },
    ["4101a"] = { common = "Растения дают жизнь Осквернённому лесу, но даже они поражены порчей. Я знаю способ исцелить их, но эти знания я не могу передать тому, к кому не питаю доверия или кого не знаю. Докажи мне, что ты от чистого сердца помогаешь Кругу Кенария! К северу отсюда лежат Пещеры Железнолесья. Тамошние Криводревы-элементали поражены порчей так, что исцелить их уже нет надежды. Прошу тебя — принеси мне их застывший сок — его называют кровавым янтарём — чтобы я могла изучить его в надежде спасти другие формы здешней жизни." },
    ["4101c"] = { common = "Этот кровавый янтарь поможет мне найти средство борьбы с порчей, поразившей Осквернённый лес. Ты доказал мне, что готов сделать всё для Круга Кенария. Теперь я доверяю тебе. Может показаться странным, что доказательством твоей преданности послужило истребление элементалей, но наша цель — спасение бесчисленных живых существ — оправдывает средства. Теперь мы с тобой можем заняться спасением жизней при помощи бальзамов, которые я смогу сделать. Пришла пора исцелить Осквернённый лес, путник." },
    ["4102a"] = { common = "Растения дают жизнь Осквернённому лесу, но даже они поражены порчей. Я знаю способ исцелить их, но эти знания я не могу передать тому, к кому не питаю доверия или не знаю. Докажи мне, что ты от чистого сердца помогаешь Кругу Кенария! К северу отсюда лежат Пещеры Железнолесья. Тамошние Криводревы-элементали поражены порчей так, что исцелить их уже нет надежды. Прошу тебя, принеси мне их застывший сок — его называют кровавым янтарём, — чтобы я могла изучить его в надежде спасти другие формы здешней жизни." },
    ["4102c"] = { common = "Этот кровавый янтарь поможет мне найти средство борьбы с порчей, поразившей Осквернённый лес. Ты доказал мне, что готов сделать всё для Круга Кенария. Теперь я доверяю тебе. Может показаться странным, что доказательством твоей преданности послужило истребление элементалей, но наша цель — спасение бесчисленных живых существ — оправдывает средства. Теперь мы с тобой можем заняться спасением жизней при помощи бальзамов, которые я смогу сделать. Пришла пора исцелить Осквернённый лес, путник." },
    ["4120a"] = { common = "Я — охотник, и всегда стремлюсь превзойти силой своих противников. Запомни, путник: всегда можно обратить ситуацию в свою пользу, если хорошо знаешь врага. К северу от Ясеневого леса есть место, называемое Осквернённый лес. Тамошние звери запятнаны веществом, которое именуется скверной. Медведи и волки от него совершенно взбесились, но в то же время скверна сделала их сильнее обычного. Ступай, путник. Отправляйся в Осквернённый лес, чтобы встретиться с этими тварями лицом к лицу." },
    ["4120c"] = { common = "Как видно из твоего рассказа, эти существа сильны, но безумны. В общем держись настороже, путник. Лучше будет для нас всех, если ты выяснишь больше про эту порчу. Всегда надо знать больше про своих врагов." },
    ["4121a"] = { common = "Ты в самом деле надеешься добраться до точки встречи, держа меня в плену? Ты и правда рассчитываешь, ворвавшись в крепость Чёрной горы и похитив главную ценность клана, удрать незамеченным? Да тебя в порошок сотрут!" },
    ["4121c"] = { common = "Отличная работа, путник. Ты заслуживаешь уважение. Военачальник хочет поговорить с тобой." },
    ["4122a"] = { common = "Я шёл за ним через Тлеющее ущелье, через горы и Пылающие степи. Предателя поймали на месте преступления, когда тот передавал оркам Чёрной горы сверхсекретную информацию о деятельности нашего отряда. Я говорю о Грарке Лоркрубе. Он теперь в Пылающих степях, под их надёжной охраной — по крайней мере, он сам так думает. Возьми эти оковы, путник. Найди Грарка, надень на него эти оковы и доставь сюда. Награда будет достойной." },
    ["4122c"] = { common = "Разве ты не видишь силу, которую мы получим, присоединившись к легиону Чёрной горы?" },
    ["4123a"] = { common = "Сколько лет я ищу этот камень! Он называется \"сердце горы\". Размером как раз с твой кулак. Дворфы Чёрного Железа прячут его в своих тайных подвалах. Я пытался его купить, предлагал им хорошую цену, но они не продают! Придётся забрать его силой, другого способа я не вижу. Тебе надо пробиться на нижний ярус Глубин Чёрной горы, взломать потайной сейф и забрать сердце. Для того чтобы добраться до тайника, тебе придётся сразиться с тамошним стражником. Его зовут Хватка Смерти, и он появится только тогда, когда ты вскроешь все сундуки и сейфы! Удачи." },
    ["4123c"] = { common = "Ты добыл Сердце! Великолепно! Оно даже прекраснее, чем мне представлялось! Прошу тебя, путник, прими это в уплату за свои труды!" },
    ["4124a"] = { common = "Моему соратнику, Гинро Пылающему Очагу, нужна помощь. Он ищет курьера и пакеты, которые тот вёз. Курьер пропал примерно неделю назад; наши собственные поиски результата не дали. Мы зашли в тупик. Пришлось объявить курьера пропавшим без вести. Если у тебя есть свободное время, пожалуйста, поговори с Гинро. Он должен быть где-то здесь. Возможно, он у себя." },
    ["4124c"] = { common = "Ты от Латро, я так понимаю? Я думаю, что дело глухо, но готов принять любую помощь. Должен признаться... я буду рад, когда вопрос решится хоть как-то. Я каждое утро выезжаю в лес разыскивать следы Раскала, и каждый вечер возвращаюсь домой с пустыми руками!" },
    ["4125a"] = { common = "Прошла примерно неделя с тех пор, как Раскал, курьер, отправился в Таланаар. Фералас он знает, как свои пять пальцев – он был здесь с нами с самого начала, с тех пор, как генерал Лунное Перо привела сюда экспедиционный корпус. Я знаю, что он собирался взять вёсельную лодку и проплыть вдоль побережья Фераласа, чтобы миновать лагерь Орды. Его лодки я так и не обнаружил – но, возможно, тебе это удастся. Может быть, она спрятана либо потонула. А между тем именно лодка может помочь выяснить, где Раскал. Если найдёшь что-нибудь, дай мне знать." },
    ["4125c"] = { common = "Вы обнаружили затонувшую лодку. Сквозь мутноватую воду видны дыры, зияющие в левом борту. Кажется, будто лодка буквально ободрана до своего деревянного остова. Такое впечатление, что лодку пытались перекусить пополам. На правом борту нарисован небольшой герб Крепости Оперённой Луны. В иле, скопившемся на дне лодки, блеснул металл..." },
    ["4126a"] = { common = "Подонки Чёрного Железа под предводительством гнусного Харли Пьянодыха украли рецепт нашего лучшего громоварского светлого! Подлые твари! Они не достойны такого прекрасного напитка! Путник, у меня есть для тебя работа. Отправляйся в Глубины Чёрной горы в Пылающих степях, уничтожь все бочонки с громоварским светлым, какие сумеешь найти, и забери у мерзавцев наш рецепт! Переверни все Глубины, но найди этот рецепт!" },
    ["4126c"] = { common = "Рецепт у тебя! Ты молодец! Надеюсь, ты задал жару этим подонкам и Харли Пьянодыху? Так им и надо, мерзавцам! Наше семейство перед тобой в неоплатном долгу, путник. Ты настоящий герой!" },
    ["4127a"] = { common = "Копаясь в иле, вы нащупываете рукоятку ножа. Похоже, тот, кто плыл на лодке, его потерял. Рядом валяются обломки самой лодки… Вы берёте нож с собой: Гинро Пылающий Очаг из Крепости Оперённой Луны велел вам принести ему всё, что может помочь разгадать тайну. Однако вас не покидает ощущение, что вы тут не одни..." },
    ["4127c"] = { common = "Интересно... Похоже, это нож Раскала. Так говоришь, он валялся на дне, рядом с обломками его лодки? Ну, может быть, этой находки и недостаточно, чтобы делать какие-то выводы. Но у нас есть один необычный способ узнать побольше… Доводилось ли тебе слышать о сверхзнании?" },
    ["4128a"] = { common = "Здравствуй, путник. Ходят слухи, что кто-то украл у Рагнара Громовара его драгоценный эль. Бедолага рвёт и мечет! Ему нужен отважный и дерзкий наёмник, который возьмётся за это дело. Рагнар готов хорошо заплатить. Если тебе интересно, переговори с ним. Он сейчас в своей \"Громоварке\" в Караносе. Это в Дун Морог." },
    ["4128c"] = { common = "Да, я в ярости! Ну и что с этого? Украли один из наших фамильных рецептов! Да как они смели! Как будто нет других причин, чтобы ненавидеть этих с Чёрного Железа! Теперь… теперь он у них! О, нет!" },
    ["4129a"] = { common = "У нас в крепости живёт друид, Квинтис Ночной Костёр, который умеет... много всего. В частности, он владеет сверхзнанием – способностью узнавать на ощупь историю предмета. Не спрашивай, как он это делает – я в этом не разбираюсь, и разбираться не хочу. Я знаю только две вещи: во-первых, я видел, как это работает, а во-вторых, мужик у меня в долгу. Короче, тащи этот ножик к Кинту, в его жилище на дереве, и передай, что должок, который за ним числится, будет уплачен, если он разберётся с этой штукой." },
    ["4129c"] = { male = "Спасибо. Конечно, сверхзнание точным искусством не назовёшь, с какой стороны ни взгляни, но всё же в былые времена я не раз с его помощью разбирался в ситуациях, которые все прочие сочли безнадёжными. Думаю, на этот раз оно поможет нам хотя бы отчасти понять, что произошло с Раскалом. Времени это много не займёт, но лёгким и приятным это дело не назовёшь. Так что будь готов прийти мне на помощь.", female = "Спасибо. Конечно, сверхзнание точным искусством не назовёшь, с какой стороны ни взгляни, но всё же в былые времена я не раз с его помощью разбирался в ситуациях, которые все прочие сочли безнадёжными. Думаю, на этот раз оно поможет нам хотя бы отчасти понять, что произошло с Раскалом. Времени это много не займёт, но лёгким и приятным это дело не назовёшь. Так что будь готова прийти мне на помощь." },
    ["4130a"] = { common = "Извини, меня до сих пор немного пошатывает. Как бы то ни было, я сумел увидеть несколько полезных вещей. Раскал вытащил два больших кожаных заплечных мешка из своей лодки и направился прочь от воды. Однако потом вернулся к лодке. Вижу скальпы гноллов... он наткнулся на гноллов – кажется, это тот клан, который называют Древолапами. Он чем-то очень озабочен, даже вроде бы напуган. Раскал настолько поглощён своими мыслями, что не замечает, как у него за спиной материализуются элементали воды. И... и всё. Больше я ничего не увидел. Извини. Мне необходимо отдохнуть. Расскажи Гину о том, что я видел. Ему следует это знать..." },
    ["4130c"] = { male = "Спасибо, что рассказал мне о видениях Кинта. Так и быть, в следующий раз, как мы с ним сядем за карты, постараюсь быть к нему подобрее. Ну, в бою Раскал никому не уступит, и гноллы – не те, кто может его обеспокоить, тем более, напугать. Но, может быть, эти новые сведения тебе всё же пригодятся?", female = "Спасибо, что рассказала мне о видениях Кинта. Так и быть, в следующий раз, как мы с ним сядем за карты, постараюсь быть к нему подобрее. Ну, в бою Раскал никому не уступит, и гноллы – не те, кто может его обеспокоить, тем более, напугать. Но, может быть, эти новые сведения тебе всё же пригодятся?" },
    ["4131a"] = { common = "Возможно, Раскала сцапали наши \"друзья\" из клана Древолапов, но что-то мне подсказывает, что дело было не так. И всё равно начать лучше всего с их лагерей. Конечно, хотелось бы иметь более отчётливые сведения, но пока что у нас нет ничего, кроме смутного указания на лагеря гноллов. Я знаю, что гноллы хранят у себя награбленное и дерутся из-за добычи. Возможно, они просто наткнулись на заплечные мешки, которые упоминал Кинт. Прежде я не рисковал соваться к гноллам, но теперь, когда у нас есть сведения, полученные от Кинта, попробовать стоит." },
    ["4131c"] = { common = "На ближайшем дереве висят два больших кожаных мешка. На обоих виднеется метка Крепости Оперённой Луны..." },
    ["4132a"] = { common = "Ты проделал отличную работу, путник! Теперь пришло время для последнего задания. Генерал Кузня Гнева, ответственный за атаки Чёрного Железа на сто девятое подразделение Каргатского экспедиционного корпуса и массовые убийства наших солдат, должен понести наказание. Это непростое задание, но в случае успеха труды окупятся сторицей." },
    ["4132c"] = { common = "Наконец-то! Злодей был привлечён к ответственности! Ты замечательно поработал, путник. Носи этот медальон как символ своей преданности Орде и Каргатскому экспедиционному корпусу." },
    ["4133a"] = { common = "Тёмному магу Вивиане Лягроб нужна твоя помощь. Она сейчас в Бесплодных землях, на сторожевой заставе Каргат. Там недавно прошёл слух о небезызвестном напитке, сваренном дворфами Чёрного Железа в Глубинах Чёрной горы, — вот она и отправилась проверить. Поговори с Вивианой. Она тебя ждёт." },
    ["4133c"] = { common = "Спасибо, что ты пришёл, путник. Это место не лишено своеобразного сурового очарования, но ему не хватает утончённости Района Фармацевтов. Впрочем, я позвала тебя не для того, чтобы вести светские беседы. Давай сразу к делу." },
    ["4134a"] = { common = "Ходят слухи, что Харли Пьянодых из клана Чёрного Железа украл рецепт эля. Говорят, этот эль, громоварское светлое, придаёт великую силу и храбрость тому, кто его употребит. Нам хотелось бы изучить состав этого напитка. Может быть, мы найдём и другое применение его удивительным свойствам… подходящее для целей Отрекшихся. Отправляйся в Глубины Чёрной горы, найди Харли, забери у него рецепт громоварского светлого и принеси его мне. Возможно, тебе придётся выманить Харли из укрытия. Для этого пригрози ему уничтожением его драгоценного эля." },
    ["4134c"] = { common = "Очень хорошо. Я пошлю этот рецепт нашим фармацевтам, и мы найдём ключ к его секретам. В один прекрасный день дворфы Альянса обнаружат, что их же напиток работает против них! Я нахожу это ужасно смешным. Может быть, смерть воздействует на центры юмора, а?" },
    ["4135a"] = { common = "В рюкзаках находится два предмета: во-первых, посылка, адресованная в Таланаар, а во-вторых – записка, адресованная неизвестно кому. В записке, набросанной торопливым почерком, говорится об обнаружении коварных насекомоподобных существ к югу от лагерей гноллов, в лесах, известных как \"Гудящая Бездна\". Автор сообщает, что намерен лично проникнуть туда, поскольку речь может идти о серьёзной опасности, грозящей всему Фераласу. Записка подписана \"Раскал из Оперённой Луны\". Похоже, вам наконец-то удалось выяснить, куда делся Раскал..." },
    ["4135c"] = { common = "Вам удалось обнаружить огромный кокон непонятного происхождения. Сам кокон мягкий и слизистый, но изнутри в разных местах выпирает что-то твёрдое. Размеры кокона позволяют предположить, что внутри может находиться гуманоид среднего роста... и сквозь стенки кокона действительно просвечивают очертания фигуры гуманоида!" },
    ["4136a"] = { common = "Мой братец Риббли всегда только и делал, что тянул денежки из семьи и тратил их на какие-то поганые махинации. Похоже, последний его проект оказался поганее прочих, потому что барон Ревилгаз из Пиратской бухты назначил награду за голову бедняжки Риббли. Ты даже не представляешь, как возрадовались все Винтокраны! Наш малыш Риббли наконец хоть чего-то да стоит! Но сейчас он скрывается в Глубинах Чёрной горы. Найди его и приведи ко мне! А если он не пойдёт добром… ну что ж, не пойдёт — и не надо… тогда принеси мне его голову." },
    ["4136c"] = { common = "Ага! Ты нашёл его! И… как я понимаю, мой маленький братец не пожелал возвращаться в семью. Очень жаль. Посмотрела бы я на его рожу, когда он услышал о том, что мы собираемся сдать его Ревилгазу. Спасибо, путник. Ты даже не представляешь, как порадовал всё наше семейство. И Риббли сейчас такой тихий и славный… он никогда таким не был." },
    ["4141a"] = { common = "Видишь Лариона вон там? Это ОН виноват, что мы застряли здесь! Я говорил ему, что мы идём не туда, но разве он меня слушал? И представляешь, после этого он ещё и не желает со мной разговаривать! Ну, пока он не передумает, я позабавлюсь! Ты заметил здесь таких странных созданий, похожих на цветы? На самом деле это довольно умные зверушки. Думаю, их можно надрессировать на всякие фокусы. В первую очередь, мне нужны образцы для изучения. Сможешь принести мне несколько?" },
    ["4141c"] = { common = "Я надеюсь, они не принесли тебе слишком много хлопот, путник. Я стараюсь держаться от них подальше, они дикие совсем… Я перепрыгивал через одного… так он напал! Порвал мне штаны!" },
    ["4142a"] = { common = "Не знаю, что и сказать тебе, путник. У этих растений, видимо, имеются зачатки разума. Впрочем, я не специалист. Однако знаю, к кому обратиться за действительно профессиональным мнением. Отправляйся в Фералас и найди там моего приятеля по имени Греган Пивоплюй. Он на таких вещах собаку съел. Уверен, Греган сможет дать нам действительно дельный совет. Думаю, искать его лучше где-нибудь в лесу — парень никак не городской житель." },
    ["4142c"] = { common = "Кровоцвет, хм… Ладно, объясни, что ты собираешься делать, и я решу, помогать ли тебе." },
    ["4143a"] = { common = "Честно говоря, путник, мне никогда прежде не доводилось видеть подобных растений. Возможно, имеет смысл наведаться в этот кратер… В любом случае, думаю, что знаю, что именно ищет Майджин. Ему нужен туман Аталаи. Это жуткая субстанция, которую весьма сложно собрать, однако именно этот туман необходим ему, чтобы управлять маленькими монстрами. Тебе нужно найти Храм Атал'Хаккара на Болоте Печали. Туман Аталаи можно собрать с обитающих там глубинных скрытней, мракочервей и слизнюков. Удачи тебе, путник!" },
    ["4143c"] = { common = "Клянусь тебе, путник, я понятия не имею что делать со всем этим барахлом! Но если Греган говорит что оно работает, то, по крайней мере, стоит попытаться!" },
    ["4144c"] = { common = "Здесь ничего, путник! Это должно привлечь внимание Лариона!" },
    ["4145a"] = { common = "Видишь там Майджина? Это ОН виноват, что мы потерялись! Я знал дорогу, но он настоял на том, чтобы пойти \"коротким путём\" и вот! Мы застряли в этой дыре! Что ещё хуже, он теперь взялся натравливать на меня этих проклятых паразитов — кровоцветы! Я так зол, что не собираюсь говорить с ним. А эти паразиты — просто последняя капля! Думаю, в первую очередь мы перекроем ему снабжение! Пойди-ка, поохоться на кровоцветы, а потом возвращайся ко мне." },
    ["4145c"] = { common = "Спасибо за помощь, путник, однако, боюсь, у меня есть плохие новости…" },
    ["4146a"] = { common = "Тебе повезло, путник! Я тут работала над кой-какими собственными изобретениями, пока Марвон в отъезде. И вот моя последняя разработка — антижучиный шокер ближнего действия! Его надо совсем чуть-чуть поправить, и можно смело использовать против кровоцветов-паразитов. С удовольствием подарю тебе одну из моих тестовых моделей, однако для неё необходимо питание — туман Аталаи. Его можно собрать в Храме Атал'Хаккара с обитающих там трясинных скрытней, мракочервей и слизнюков." },
    ["4146c"] = { common = "Так Марвон не шнырял поблизости? Ладно, покажи мне что добыл." },
    ["4147a"] = { common = "Мне удалось проследить за Майджином — он и впрямь выращивает эти проклятые растения! Думаю единственным решением будет… Нет, говорить с ним бесполезно, надо готовиться к ответному удару! Нам потребуется помощь моего друга Марвона, у него мастерская в Кабестане." },
    ["4147c"] = { common = "Марвон отсутствует уже довольно длительное время, путник. Он поехал в Танарис изучить некие древние руины троллей. Так что ты говоришь, тебе нужно?" },
    ["4148c"] = { common = "Похоже, это отлично работает, путник. Теперь запомни, если увидишь где-то поблизости этих вредителей, используй шокер!" },
    ["4161a"] = { male = "Давным-давно ночные эльфы назывались кальдораями, \"детьми звёзд\". Изучение прошлого – важный шаг на пути героя, так что слушай внимательно всё, что я расскажу тебе. Кальдораи всегда гордились тем, что живут в гармонии с природой. Это означает, что мы берём у природы только то, что нам необходимо, и воздаём ей сторицей. Это равновесие позволяло нам вершить многое. Ступай же и принеси мне семь маленьких паучьих лапок – не более – и возвращайся ко мне.", female = "Давным-давно ночные эльфы назывались кальдораями, \"детьми звёзд\". Изучение прошлого – важный шаг на пути героини, так что слушай внимательно всё, что я расскажу тебе. Кальдораи всегда гордились тем, что живут в гармонии с природой. Это означает, что мы берём у природы только то, что нам необходимо, и воздаём ей сторицей. Это равновесие позволяло нам вершить многое. Ступай же и принеси мне семь маленьких паучьих лапок – не более – и возвращайся ко мне." },
    ["4161c"] = { common = "Всегда помни то, что я ныне показал тебе. Ты – часть того равновесия, которое ночные эльфы стремятся поддерживать даже в тревожные времена." },
    ["4181a"] = { common = "В инженерном деле есть две дисциплины: гномская и гоблинская. Я – честный учитель, и только поэтому упомянул инженерное дело. Видишь ли, гоблины обожают делать всякие взрывоопасные штучки и редко заботятся о том, что окажется на пути такой штучки – даже если это будет сам инженер. Почитай этот справочник. Если хочешь узнать, как эффектно покончить с собой, отнеси его к Никсу Шепружину в Прибамбасск. Помни – выбор твой не подлежит пересмотру, сменить дисциплину ты не сможешь; так что прежде, чем выполнить задание, что даст тебе Никс, убедись, что ты хочешь именно этого." },
    ["4181c"] = { common = "Что же, ты разумно поступаешь, прося у меня наставничества! Любой дурак может стать экспертом в азах инженерного дела – что прекрасно видно на примере гномов и их радиоактивного Гномрегана. Для овладения гоблинским инженерным делом требуется крепкая соображаловка и твёрдая (повторяю – ТВЁРДАЯ) рука. Держи ушки на макушке, может, что и усвоишь." },
    ["4182a"] = { common = "Жизнь в Пылающих степях никогда не бывает спокойной. Только посмотри вокруг! Мы не знаем, что случилось с этими строениями, но до большого взрыва всё это было частью Красногорья. Но довольно скулить! У нас есть более насущная проблема. Может быть, ты заметил драконов под этим хребтом. Необходимо вынудить их отступить. Убей как можно больше и возвращайся. Если ты добьёшься успеха, я дам тебе другое задание." },
    ["4182c"] = { common = "Отличное смертоубийство, путник! Теперь, когда мы знаем, что ты способен бороться с драконами, мы можем поговорить о других важных делах." },
    ["4183a"] = { common = "Мы всегда думали, что орки Чёрной Горы такие жестокие от природы. Оказывается, дело обстоит иначе. Да, их и правда ведёт в бой жажда крови и любовь к сражениям, но руководят ими чёрные драконы. Мы подозреваем, что именно они возбуждают в них ярость и злобу. Отнеси это письмо мировому судье Соломону. Он скажет, что делать." },
    ["4184a"] = { common = "Дурные вести, путник. Нетрудно прийти в отчаяние, узнав, что твои смертельные враги — всего лишь пешки куда более страшного противника. Приозерью не пережить натиска орков Чёрной Горы и чёрных драконов. Если падёт Приозерье, следующим будет Темнолесье, а что потом? Златоземье? Сам Штормград? Немедленно отнеси это сообщение верховному лорду Болвару Фордрагону в Штормград! Если мы и этим не добьёмся от столицы помощи, то не добьёмся никакими силами, и всё пропало." },
    ["4184c"] = { common = "Драконы? Невозможно!" },
    ["4185a"] = { common = "Грустную картину нарисовал Соломон. Тем не менее, мы не можем позволить себе посылать наши и без того скудные войска на помощь Приозерью, основываясь только на догадках. Мне понадобится доказательство правоты его заявлений, прежде чем я смогу предпринять какие-то действия. Поговорите с леди Престор, путник. Она женщина учёная и много чего знает о драконах и драконидах. Возможно, она сможет пролить какой-то свет на эту ситуацию." },
    ["4185c"] = { common = "Я, конечно, понимаю и уважаю позицию леди Престор, но я думаю, что существует способ разом разрешить все наши проблемы." },
    ["4186a"] = { common = "Я намерен наделить вас полномочиями представителя, действующего от имени Штормграда, путник. Возвращайтесь к мировому судье Соломону в Приозерье и передайте ему этот указ." },
    ["4186c"] = { common = "Я полагаю, что могло быть и хуже… Похоже что судьба Приозерья ложится на твои плечи." },
    ["4223a"] = { common = "Возвращайся в Пылающие степи, путник. Как представитель Штормграда ты должен предстать перед маршалом Максвеллом. Удачи." },
    ["4224a"] = { common = "Что? Думаешь, ты первый? Сколько же ещё мы должны потерять солдат прежде, чем Штормград начнёт шевелиться? Мы собрали целую кучу разведданных касательно угрозы со стороны Чёрной горы до того, как потеряли нашего командира, маршала Винздора. С ним пропала и вся наша бесценная информация. Нам просто необходимы эти документы. Поговори с Джоном-Оборванцем, путник. Он был при Винздоре, когда на них налетел рейд Чёрной горы. Последний раз его видели в пещере к северу отсюда." },
    ["4224c"] = { common = "Я мог предупредить тебя, но где в этом удовольствие?" },
    ["4241a"] = { common = "Значит, этот жалкий трус говорит, что Винздор жив? Готовься, тебе предстоит отправиться на его поиски. Если Винздор жив, спаси его. Если мёртв — принеси мне доказательства его гибели. Тебе, наверное, надоело это слышать?" },
    ["4241c"] = { common = "Где он! Да я убью его!" },
    ["4242a"] = { common = "Болвар — жалкий дурак. Я собирал все его драгоценные \"доказательства\" только для того, чтобы засунуть их ему же в глотку. Недоумок! Слепой идиот! Доказательство стоит в двух шагах от него, а он ушами хлопает. Что касается собранных мною сведений — вся информация утрачена, причём безвозвратно. Если я всё-таки найду Железогубитель и выберусь из этого лабиринта, я первым делом отправлюсь в Штормград и вломлю ему молотом промеж глаз, этому подлому змею. Оставь меня, путник." },
    ["4242c"] = { common = "По-видимому, он точно спятил. Очень жаль что некогда гордый и благородный воин пришёл к такому печальному концу… А вот награда за твои усилия, путник." },
    ["4243a"] = { common = "Увы, что-то случилось с одним из моих величайших изобретений. Ты ведь видел моих механических белок? Так вот, чтобы подобраться поближе к обезьянам, обитающим в Кратере Ун'Горо, я создала механическую обезьяну, которая должна была смешаться со стаей. Я назвала её Чи-Та Три. Её глаза были сделаны из магических кристаллов, так что я могла видеть всё, что видит она. Она успела добраться до Пещеры Лишайников — это логово обезьян к востоку отсюда — и там я потеряла с ней контакт. Последним, что я видела, был вожак стаи, который подбежал поздороваться с ней. Ты поможешь мне разыскать её?" },
    ["4245c"] = { common = "Ах, тебе удалось, какое счастье! Спасибо, путник. О, моя бедняжечка! Как тебе досталось! Ничего, я починю тебя, будешь как новенькая! Ещё раз благодарю тебя, путник, твоя помощь неоценима." },
    ["4261c"] = { common = "Да, путник. Осквернённый лес и я лично благодарим тебя за сделанное. В один прекрасный день мы очистим Осквернённый лес от заразы, и каждое доброе дело помогает в этом." },
    ["4262a"] = { common = "Последние пять магов, которые отправились на разведку к Чёрной горе вернулись довольно хрустящими и с перманентной завивкой — или хуже того. А больше всего неприятностей нам причиняет один тип, подчинитель Пирон. Необходимо остановить этого элементаля, чтобы наша экспедиция могла пробраться в глубины Чёрной горы. Он охраняет вход в каменоломни Чёрной горы." },
    ["4262c"] = { common = "Опалитель? О, небо…" },
    ["4263a"] = { common = "Ты уверен, что Пирон сказал перед смертью \"Опалитель\"? Ведь лорд Опалитель — прислужник Рагнароса! О небо, небо… Что же нам делать? Как ты думаешь, справишься с ещё одним заданием? Мне больше некого послать, путник! Нам никогда не одолеть врагов, если Опалитель будет и дальше воскрешать Пирона из пепла. Тебе придётся отыскать и уничтожить лорда Опалителя!" },
    ["4263c"] = { common = "Стой! Ты уверен, что Опалитель сказал \"Рагнарос?\"" },
    ["4264a"] = { common = "Лист помят и испачкан, и текст почти не читается, но вам всё-таки удалось разобрать несколько фраз: \"…по иронии судьбы… …упадок распавшегося Альянса… …если бы не усердие генерала Кузни Гнева, мы никогда не сумели бы найти ключ к шифру… …Аргелмах почти завершил расшифровку записок Винздора. Наш владыка восстанет из бездны и сокрушит всех, кто остался… Император Дагран Тауриссан\"." },
    ["4265a"] = { common = "Когда вы прикасаетесь к кокону, он немного раскрывается, и вы видите внутри ночного эльфа, который, как ни странно, всё ещё жив, и даже, кажется, цел и невредим, только в глубоком обмороке. Когда вы вытаскиваете его из кокона, он шевелится и приходит в себя. \"Слава Элуне! Я спасён! Спасибо тебе, друг. Я... Меня зовут Раскал. Эти жуки парализовали меня, и очнулся я уже в коконе. Тебя из крепости прислали, да?\" Похоже, вы нашли пропавшего курьера..." },
    ["4265c"] = { male = "С возвращением! Раскал не так давно явился ко мне и сообщил обо всём, что произошло. Я... да что там, вся наша крепость не знает, как тебя благодарить за твои подвиги. Раскал погиб бы, если бы не твоя своевременная помощь. А ведь ты помогаешь нам не ради платы, как какой-нибудь наёмник! Ты – подлинный герой. Знай, что отныне Гинро Пылающий Очаг – твой друг до скончания веков!", female = "С возвращением! Раскал не так давно явился ко мне и сообщил обо всём, что произошло. Я... да что там, вся наша крепость не знает, как тебя благодарить за твои подвиги. Раскал погиб бы, если бы не твоя своевременная помощь. А ведь ты помогаешь нам не ради платы, как какой-нибудь наёмник! Ты – подлинная героиня. Знай, что отныне Гинро Пылающий Очаг – твой друг до скончания веков!" },
    ["4266a"] = { male = "Генерал Шандриса Оперённая Луна хотела бы поговорить с тобой лично. Несомненно, она хочет поблагодарить тебя за всё, что ты сделал для крепости, но, насколько я знаю, она также хотела бы поговорить с тобой о тех насекомоподобных тварях, которых вы с Раскалом видели в южном Фераласе. Сообщения об этих насекомых, которых именуют Цуккаш, звучат... скажем так: устрашающе. Генерал Лунное Перо ждёт тебя в главном здании.", female = "Генерал Шандриса Оперённая Луна хотела бы поговорить с тобой лично. Несомненно, она хочет поблагодарить тебя за всё, что ты сделала для крепости, но, насколько я знаю, она также хотела бы поговорить с тобой о тех насекомоподобных тварях, которых вы с Раскалом видели в южном Фераласе. Сообщения об этих насекомых, которых именуют Цуккаш, звучат... скажем так: устрашающе. Генерал Лунное Перо ждёт тебя в главном здании." },
    ["4266c"] = { common = "Я от души благодарю тебя за всю оказанную тобой помощь. Твоя отвага перед лицом превосходящих сил противника достойна награды в тысячу раз большей. Тем не менее, я надеюсь, что ты примешь в дар от всей крепости хотя бы это. А теперь, если можно... я хотела бы попросить тебя ещё об одной услуге. Сейчас, когда здесь, в Фераласе, обнаружен улей Цуккаш, думаю, это задание следует поручить именно тебе..." },
    ["4267a"] = { common = "Я доверяю тебе копию отчёта Раскала о вторжении в юго-восточный Фералас. Полный доклад будет отправлен на хранение в Дарнасс, а эту копию отнеси, пожалуйста, представителю Протектората. Её зовут Грацина Сила Духа; это жрица, которая живёт в храме Луны в Дарнассе. Она обладает обширными познаниями о подобных существах, так что, если она ознакомится с этим докладом, это пойдёт на пользу всем нам. Можешь идти. Удачи тебе, и да хранит нас Элуна!" },
    ["4267c"] = { common = "Нам, ночным эльфам, немало известно об ужасах, описанных в этом докладе. Сандрис поступила мудро, отправив ко мне доклад – и тебя с ним. Эти твари стремительно заполонят весь Фералас. Можно сказать, что это одна из самых страшных опасностей, какие нам когда-либо грозили! Насекомые, с которыми столкнулись вы с курьером, называются силитидами. Они – всего лишь орудие одной из величайших угроз, с какими встречались как Альянс, так и Орда. Молюсь, чтобы у нас хватило решимости разгромить их прежде, чем они уничтожат нас!" },
    ["4281a"] = { common = "Свёрток, который вы нашли в лагере гноллов-древолапов, следовало доставить в небольшой путевой лагерь Таланаар на юго-востоке Фераласа. Неизвестно, какая судьба постигла курьера, однако свёрток так и остался недоставленным! Осмотрев пакет, вы видите на нём имя \"Хранитель дорог Фалфиндер\". Возможно, это имя адресата?" },
    ["4281c"] = { male = "Слава Элуне! Наконец-то пришла посылка из Крепости Оперённой Луны! Но раз её принёс ты, значит, с нашим курьером, Раскалом, что-то случилось? Надеюсь, что всё уладится... Насколько я знаю, в последнее время гноллы из клана Древолапов очень боятся чего-то, что происходит на юге. Может быть, Раскал заблудился в глуши? Будь осторожнее. Ну, как бы то ни было, спасибо тебе ещё раз. А вот и плата за доставку!", female = "Слава Элуне! Наконец-то пришла посылка из Крепости Оперённой Луны! Но раз её принесла ты, значит, с нашим курьером, Раскалом, что-то случилось? Надеюсь, что всё уладится... Насколько я знаю, в последнее время гноллы из клана Древолапов очень боятся чего-то, что происходит на юге. Может быть, Раскал заблудился в глуши? Будь осторожнее. Ну, как бы то ни было, спасибо тебе ещё раз. А вот и плата за доставку!" },
    ["4282a"] = { common = "Ты понимаешь, что это значит, путник? Может быть, ещё не всё потеряно! Насколько я понял, информацией завладели два дворфа Чёрного Железа — генерал Кузня Гнева и повелитель големов Аргелмах. Однако есть у меня подозрение, что они её не отдадут, даже если мы их очень вежливо попросим. Надеюсь, ты готов сражаться. Разыщи этих двоих негодяев! Убей их обоих и верни мне утерянную информацию." },
    ["4282c"] = { common = "Нам надо выбираться отсюда!" },
    ["4283a"] = { common = "Открою тебе тайну, солдат. Подойди-ка поближе. Я ЕДИНСТВЕННЫЙ, КТО ЕЩЁ НЕ СПЯТИЛ! Посмотри на остальных. Ты веришь, что они ненормальные? А так оно и есть! ПСИХИ! СУМАСШЕДШИЕ! Но пусть это останется между нами — тобой, мной и моим приятелем, капитаном Винкеем. В общем… помимо ушей огров, я собираю их солдатские медальоны. Сегодня на повестке дня орки. Пятьдесят штук. ИДИ! ЗАТКНИСЬ!" },
    ["4283c"] = { common = "Ты сделал это! Твоя награда: ПОЧЕШИ МНЕ ЖИВОТ! ДАВАЙ! ПОЧЕШИ ЕГО!" },
    ["4284a"] = { common = "Уверена, ты видел их, путник. Они повсюду! Ты не понимаешь, о чём я? О кристаллах, конечно! Большинство их просто игнорирует, но я чувствую, что в них заключена какая-то сила. Я уже давно провожу с ними эксперименты, но пока, видимо, так же далека от разгадки, как и в первые дни исследований… Впрочем, я не теряю надежды! Сейчас у меня почти вышел запас кристаллов. Не поможешь ли мне его восполнить?" },
    ["4284c"] = { common = "Теперь я продолжу эксперименты. Спасибо, путник!" },
    ["4285a"] = { common = "Что бы это могло быть? Я всё время думаю об этой загадке! Эти слухи о хрустальных пилонах просто сводят меня с ума! Можешь считать меня наивной дурочкой, но я верю почти всему, что мне рассказывают. В общем, слыхала я, что один из пилонов находится совсем неподалёку отсюда — где-то на севере. Пожалуйста, разыщи его, путник! Я уверена, пилоны существуют!" },
    ["4285c"] = { common = "Я знаю, легенды не врут, путник." },
    ["4286a"] = { common = "Капитан Винкей уверяет, что дворфы Чёрного Железа в глубинах Чёрной Скалы загребли всё лучшее добро. Верно, Винкей? Вот видишь? Иди туда и принеси мне образцы их добра. Тряхни стариной и отправляйся вглубь!" },
    ["4286c"] = { common = "ЗДОРОВО! ВКУСНОТА! Только посмотри на них! Возьми один для себя, путник, доставь мне удовольствие." },
    ["4287a"] = { common = "За время моего пребывания здесь, до меня не раз доходили странные слухи о таинственных хрустальных пилонах, сокрытых в кратере. Полагаю, они довольно велики. Не могу отделаться от мысли, что в этих слухах есть доля истины, и эти пилоны как-то связаны с обнаруженными нами кристаллами… Удовлетвори моё любопытство, поищи пилон в восточной области кратера." },
    ["4287c"] = { common = "Ун'Горо это такое странное место, путник. Когда ты попадаешь в кратер, ты словно оказываешься в совсем другом мире…" },
    ["4288a"] = { common = "Мои опыты пока не принесли никаких положительных результатов, путник. Теперь я возлагаю надежды лишь на то, что ты сможешь найти один из пилонов, о существовании которых я слыхала. Возможно, если смешать определённые цвета… Впрочем, я тороплю события. Необходимо сначала найти его. Исследуй западную область кратера, путник, говорят, пилон находится именно там." },
    ["4288c"] = { common = "Есть много скрытых площадок по краям кратера. Попробуй внимательно осмотреть их, путник." },
    ["4289a"] = { common = "В этом кратере встречается множество странных зверей — они похожи на тех, что водятся на моей родине, но выглядят более… породистыми. Я не могу объяснить это, но мне кажется, это место — средоточие силы Матери-Природы. Я воздаю ей хвалу всякий раз как встречаю одно из её прекрасных созданий в этом кратере. Если ты тоже хочешь достигнуть просветления, отправляйся на север. Там ты найдёшь огромных обезьян, помериться силами с которыми сочтёт за честь самый искусный воин. Принеси мне их шкуры, докажи свою силу!" },
    ["4289c"] = { common = "Итак, ты доказал, что силён, сильнее обезьян в Ун'Горо — это хорошо. Конечно, пока твою силу нельзя сравнить с Лар'корви, но ты честно заслужил награду. Эти шкуры прекрасно подойдут для создания одежды для моего племени. Ты помог мне. Спасибо. Прежде чем ты приступишь к новому испытанию, давай воздадим почести Матери Земле и поблагодарим души убитых обезьян — они должны знать, что их смерть не была напрасной." },
    ["4290a"] = { common = "Однажды мой брат имел неосторожность отрезать кусок мяса от добычи Лар'корви, когда того не было рядом. Однако оказалось, что Лар'корви наблюдал за моим братом из укрытия. Он преследовал моего брата долгие недели, разрушая всё на своём пути. Наконец, брат мой в страхе решил покинуть кратер. Но Лар'корви настиг его недалеко от этого места и убил его. Если хочешь привлечь к себе внимание Лар'корви, найди его свежеубитую добычу и отрежь от неё кусок мяса. Затем возвращайся ко мне." },
    ["4290c"] = { common = "Это подойдёт, путник. Кажется, в последнее время у Лар'корви сильно вырос аппетит. Хотя я никак не могу понять, как он смог найти жесткозуба в этих местах. Странно. Неважно, я сохраню мясо, пока ты будешь готовиться к встрече с этой тварью. За меня не волнуйся, я уверен, что ты уже разозлил Лар'корви так, что он не убьёт меня прежде, чем отведает на вкус твоего мяса." },
    ["4291a"] = { common = "Я удивлён, что Лар'корви не вышел к тебе, путник! И всё же у меня есть задумка, как выманить его. Поскольку Лар'корви — доминирующий самец в своей стае, он может выбирать любую самку. А выбирает он многих! Ты найдёшь много кладок равазавров к западу отсюда. Подберись к ним поближе и спровоцируй самок атаковать тебя. В их головах находятся железы, источающие жуткий запах — так эти твари оповещают своих самцов о готовности к размножению. Принеси мне две такие железы." },
    ["4291c"] = { common = "Это прекрасные образцы, путник. Двух желёз вполне хватит, чтобы выманить Лар'корви на открытую местность. Мне не терпится увидеть, чем закончится ваш бой. Не думай, что я не верю в твои силы. Но у этого чудовища исполинская сила, а его когти остры, как лезвия. Когда ты заглянешь в его глаза, ты заглянешь в глаза смерти." },
    ["4292a"] = { common = "Это самая сложная часть нашего плана. К северу отсюда есть узкая тропинка, ведущая в горы. Именно там я в последний раз видел Лар'корви. Ты легко узнаешь это место — там повсюду разбросаны дочиста обглоданные кости крупных животных, имевших неосторожность подойти слишком близко к логову Лар'корви. Положишь там принесённое с собой мясо. Затем полей мясо вот этим составом. Если это не выманит к тебе Лар'корви, то я не знаю, чем ещё его можно заманить." },
    ["4292c"] = { common = "Мать-Земля будет довольна. Ты сделал это, путник! Молодец. Ты хороший охотник, как оказалось. Твоя храбрость несравненна. Я кланяюсь тебе. Только действительно великие могут сделать такое. Поздравляю." },
    ["4293a"] = { common = "Осквернённый лес находится далеко на севере от Степей — даже дальше, чем Ясеневый лес. Вокруг тамошних заводей, благословлённых касанием Скверны, полно слизнюков. Плеть наводнила эти земли инферналами и прочими демонами. Судя по всему, в это время слизнюки и полезли из-под земли. Собери образцы слизнюков Осквернённого леса — мы проверим их при помощи моего оборудования и создадим контрольную группу, чтобы сопоставить её с другими принесёнными тобой образцами." },
    ["4293c"] = { common = "А, прекрасно, это хорошие образцы. Благодарю тебя за помощь. Теперь мы проведём серию экспериментов, потом определим компоненты, замерим показатели, проведём спектрографический анализ. И учти, что ход эксперимента контролируется лично Тёмной Леди." },
    ["4294a"] = { common = "Тебе приходилось слышать о Кратере Ун'Горо? Он расположен рядом с пустыней Танарис. Великолепное место: тамошние буйные заросли буквально кишат жизнью! А какие там растения… Именно туда тебе и следует отправиться. До меня дошли слухи, что в этих местах сохранилась практически девственная природа. Исследователи лишь недавно добрались до них, и далеко не все тайны ещё раскрыты. Я хочу, чтобы ты принёс мне образцы живущих там слизнюков. Если слухи правдивы и их не тронула порча, я смогу узнать, откуда появились эти существа." },
    ["4294c"] = { common = "Потрясающе, путник. Этот кратер Ун'Горо содержит даже больше секретов, чем я ожидал. Просто потрясающе — ты только посмотри на чистоту этих образцов. Они… они напоминают мне что-то… Древних Богов! Мы искали связь между ними и различными существами в Азероте… Надо провести дальнейшие исследования!" },
    ["4296a"] = { common = "Я прибыл в Пылающие степи из-за легенд о Семерых. Это были дворфы, прославленные знаниями и силой, а значит – и богатством. Именно к богатству я и стремлюсь! Узнай мы побольше про Семерых, могли бы оба разбогатеть. Говорят, что в руинах Тауриссана есть табличка Семерых, содержащая знания древних дворфов. Найди её, перепиши текст и принеси мне. И мы оба узнаем её тайны!" },
    ["4296c"] = { male = "А, ты нашёл табличку! И как хорошо переписан текст! Ты точно герой, а не переписчик? Вот, возьми. Это обещанные деньги.", female = "А, ты нашла табличку! И как хорошо переписан текст! Ты точно героиня, а не переписчица? Вот, возьми. Это обещанные деньги." },
    ["4297a"] = { common = "Летучие хамелеоны всеядны: это значит, что они питаются как животной, так и растительной пищей. Твоё яйцо вот-вот проклюнется, и мы должны быть к этому готовы. Лучшая еда для этих малявок – это мясо, свежее, сочное мясо! Хочешь – верь, хочешь – нет. Почему – я так и не выяснил, но, кажется, это имеет какое-то отношение к замыслу Элуны относительно эльфов. Возможно, они должны были быть защитниками... не знаю. Яйцо я пока покараулю, а ты сходи и добудь мне свеженьких окороков среброгривых бродяг. Ими-то мы и покормим малыша, когда он вылупится." },
    ["4297c"] = { male = "Да, это мясо вполне годится. А тем временем, если я не ошибаюсь, твой дракончик начинает вылупляться! Ну, как тебе это? В смысле, каково быть папой? Груз ответственности не давит пока?", female = "Да, это мясо вполне годится. А тем временем, если я не ошибаюсь, твой дракончик начинает вылупляться! Ну, как тебе это? В смысле, каково быть мамой? Груз ответственности не давит пока?" },
    ["4298a"] = { common = "Ух ты, да он уже вылупляется!" },
    ["4298c"] = { male = "Вот, бери яйцо... Тебе лучше держать его при себе, чтобы вылупившийся детёныш сразу привязался к тебе. Тогда он будет считать тебя своим папочкой. Ну всё, поздравляю! У тебя теперь всё равно что собственный ребёнок!", female = "Вот, бери яйцо... Тебе лучше держать его при себе, чтобы вылупившийся детёныш сразу привязался к тебе. Тогда он будет считать тебя своей мамочкой. Ну всё, поздравляю! У тебя теперь всё равно что собственный ребёнок!" },
    ["4300a"] = { common = "Да, если так подумать, то, пожалуй, для тебя есть работёнка. Джес'римону пригодится твоя помощь. В Кратере Ун'Горо водятся ящеры — с когтями острыми, как бритва. У большинства ящеров когти чёрные, как смерть, но у некоторых ящеров они белые. У Раздроблённой Руки имеются… клиенты, которые очень ценят оружие, изготовленное из таких когтей. Принеси побольше белых когтей, и Джес'римон заплатит тебе по совести. А если сделаешь это быстро, то получишь кое-что сверху." },
    ["4300c"] = { common = "Ага, вот этого хватит. Спасибо тебе, путник. Может быть подобрать тебе какое-то оружие, а? Что скажешь?" },
    ["4301a"] = { common = "Пока ты исследовал Ун'Горо, я встретил и других созданий, охота на которых доставит удовольствие такому мастеру как ты. Одно из них — огромная обезьяна, я видел её в стае других обезьян к северу отсюда. Ты уже бывал в этой пещере раньше, однако не могу ручаться, что выйдешь из этой схватки живым, если действительно возьмёшься за это задание. Я назвал эту обезьяну Уча, она одна из самых могучих детей Матери-Природы. Убей её, и я буду отстаивать твоё право называть себя великим охотником." },
    ["4301c"] = { common = "Очень хорошо, путник. Сегодня ты совершил великий подвиг! Уча была величайшей обезьяной, которую я когда-либо встречал. То, что ты сумел справиться с ней, говорит о твоей силе и смелости. Прими это, как знак моего уважения. Ты это заслужил." },
    ["4321a"] = { common = "То, что ты рассказал мне о пилонах, весьма интересно… Дай мне минутку, мне нужно сделать некоторые расчёты… Зайди ко мне через пару минут, я смогу дать ответ на твой вопрос." },
    ["4321c"] = { common = "Ага, отлично, путник. Это просто удивительно… надеюсь, я правильно построила все диаграммы. Я переписала все данные в это руководство и с радостью отдаю его тебе. Теперь, путник, можешь спрашивать про кристаллы." },
    ["4322a"] = { common = "Пора выбираться отсюда, путник. Помоги мне забрать мои вещи со склада и освободить моих друзей. Если у нас всё получится и нам удастся отсюда сбежать, отправляйся в Дозор Моргана и расскажи обо всём маршалу Максвеллу. Он тебе скажет, что делать дальше." },
    ["4322c"] = { common = "Впечатляюще, путник. Просто здорово. Винздор был здесь не далее как пять минут назад. Он сделал несколько громких заявлений, и утверждает, что у него есть и доказательства. Сейчас он на пути в Штормград чтобы вступить в борьбу с Болваром и… леди Престор." },
    ["4324a"] = { common = "Риббли, мой младший братец, всю жизнь был никчёмным придурком и позором для всей семьи, но в итоге оказалось, что он тоже чего-то да стоит и может пригодиться. Но понимаешь, какое дело… чтобы приставить его к работе, нам понадобится твоя помощь. Моя сестра Юка искала его почти месяц, и в итоге ей удалось узнать, что он прячется в Пылающих степях. Ей нужен наёмник, и она обратилась ко мне за помощью. Не хочешь взяться за это дело? Если берёшься, тогда тебе надо переговорить с сестрой. Ты найдёшь её в Пламенеющем Стяге, в пещере к северо-западу от скалы Молота Ужаса." },
    ["4324c"] = { common = "Да, я ищу своего брата. Мы должны найти его и заполучить его! Впрочем… если нам не удастся найти его всего, то может быть хотя бы голову." },
    ["4341a"] = { common = "Вы были в дымящихся руинах Тауриссана? А вам не попадался этот жалкий бездельник Каран Могучий Молот? Это дворф, который был должен охранять мою девочку! И теперь она пропала, путник! СМои воины обшарили всю Степь. Им удалось узнать только то, что моя дочка может быть в Глубинах. Может, она уже погибла! А Харан, видимо, сидит там в плену… найдите его! Я хочу получить ответ!" },
    ["4341c"] = { common = "Прошу, позволь мне объясниться!" },
    ["4342a"] = { common = "Пожалуйста, выслушай меня, а потом будешь судить!" },
    ["4342c"] = { common = "Как ты сам понимаешь, я ничего не мог сделать." },
    ["4361a"] = { common = "Расскажи обо всём королю Магни, путник. Он знает, что делать." },
    ["4362a"] = { common = "Похоже, и моя судьба, и судьба королевства Стальгорн ныне в руках моего старинного врага Даграна Тауриссана. Возможно, вы моя последняя надежда, путник. Вы должны спасти мою драгоценную дочь Мойру! Есть только один путь наверняка разрушить лежащее на Мойре заклятие Тауриссана — убить его. Но умоляю, путник, не причиняйте ей вреда! Помните, она под властью Тауриссана! Всё, что она будет делать или говорить, — результат злого заклятия Тауриссана!" },
    ["4362c"] = { common = "Зачем?" },
    ["4363a"] = { common = "Тауриссан был великим и доблестным дворфом. Ты разрушил мою жизнь и жизнь моего будущего ребёнка! Возвращайся в Стальгорн и скажи моему отцу, что наследником королевства будет дворф Чёрного Железа. Нравится это ему или нет, но именно так всё и будет!" },
    ["4363c"] = { common = "Похоже что даже померев, этот Тауриссан, выиграл… Свободен, путник. Перед уходом, выбери себе из сокровищницы любую награду." },
    ["4402a"] = { common = "Ну и жарища у нас в Долине Испытаний! Галгар утирает пот со лба. Были бы у меня плоды кактуса, я бы изготовил свой знаменитый кактусовый десерт! Ничто не освежает лучше этого восхитительного лакомства. Знаешь что? Принеси-ка мне десяток плодов кактуса, и я приготовлю для тебя несколько порций десерта. Пригодится в путешествиях. Плоды кактуса можно собрать с тех, что растут вокруг." },
    ["4402c"] = { common = "Чудесно! Как и было обещано, вот твой кактусовый десерт – а ещё можешь взять себе одно из этих учебных пособий. У меня их навалом." },
    ["4421a"] = { common = "Мало кто отваживается искать здесь приключений… Порча, поразившая Осквернённый лес, расползается, поражая всё без разбору. Я, состоя в Изумрудном Круге, ищу способ исцелить эти земли, но есть те, кто радуется её мучениям. Я говорю о сатирах из племени Нефритового Пламени, что живут к северо-западу отсюда, в руинах Констелласа. Ими предводительствует особенно жестокий сатир по имени Ксаватрас. Они продолжают поражать заразой любое живое существо, которое попадается им на пути. Мы должны защитить этот край — ведь некогда он был нашим. Срази Ксаватраса и уничтожь его приспешников." },
    ["4421c"] = { common = "Зачистка сатиров в Осквернённом лесу это только первый шаг… Сколько надо теперь исправлять тут… Я чувствую что есть ещё что-то более злое чем те сатиры… но пока не могу распознать это…" },
    ["4441a"] = { common = "Флейта, найденная тобой, вырезана из древесины сторожевого древа, верного союзника ночных эльфов. Сатиры поражают порчей всё, на что наталкиваются, в том числе и Дерева, для которых Осквернённый лес был домом родным. Из-за скверны духи Дерев попали в узы и теперь терзаются, не в силах освободиться. Эти узы скверны, что ты нашёл, наверняка с этим связаны. Мы должны попытаться очистить эту флейту от скверны, путник. Принеси мне благословенной воды из дарнасского Храма Луны." },
    ["4441c"] = { common = "Спасибо, путник. Теперь, нам остаётся молиться, чтобы нам удалось возместить нанесённый урон…" },
    ["4442a"] = { common = "При помощи сей воды Элуны я попытаюсь смыть скверну с этой флейты. Мы должны покончить со страданиями… Да направит мою руку Элуна и да укрепит она моё сердце. Подожди немного — потом поговорим." },
    ["4442c"] = { common = "С помощью благословенной воды я смогла сломать связь между флейтой и этим древним духом. Я полагаю, что если бы ты использовал флейту в священном месте то ты мог бы вызвать древних духов. Ты можешь попробовать сделать это в руинах в южной части Железнолесья. Много древов обитали там, в давние времена, и возможно, что они до сих пор там, но уже в форме духов." },
    ["4449a"] = { common = "Эй! Эй, ты, там! Иди скорей сюда! Помоги мне! Я спасался бегством от дворфов Чёрного Железа и попытался спрятаться от них здесь. Проклятые геологи со своей проклятой магией! Они увидели, что я здесь прячусь, и заперли меня! Проучи, проучи этих проклятых геологов! И... это... добудь мне несколько лоскутков шёлка... так... вдруг пригодится..." },
    ["4449c"] = { common = "О, какое облегчение! Как я рад! Тебе удалось отомстить проклятым геологам? Их наглость не знала границ, однако. Не знаю как благодарить тебя! Ты это... погоди минутку, мне тут надо закончить некоторые дела..." },
    ["4450a"] = { common = "Ты знаешь, мне это кое-что напоминает. Не хочешь закончить за меня одну работёнку, за которую я взялся в Танарисе? Это пара пустяков... Кринкель Сталлинн из Прибамбасска искал какие-то вещи – некоторые здесь, в Тлеющем ущелье, а некоторые в других местах. Может, глянешь на список? Ты наверняка сможешь что-нибудь найти. Если тебе это интересно, я просуну его учётную книгу под дверь. Отнесёшь её ему вместе с разыскиваемыми вещами, когда соберёшь их все." },
    ["4450c"] = { male = "Ого, да ты смог выполнить эту работу! Прекрасно. Полагаю, теперь ты попросишь меня выковать для тебя что-нибудь. У меня есть превосходное оружие и доспехи. Благодарю тебя, герой! Думаю, ты заслужил... хммм... что-нибудь полезное.", female = "Ого, да ты смогла выполнить эту работу! Прекрасно. Полагаю, теперь ты попросишь меня выковать для тебя что-нибудь. У меня есть превосходное оружие и доспехи. Благодарю тебя, героиня! Думаю, ты заслужила... хммм... что-нибудь полезное." },
    ["4451a"] = { common = "Маленький медный ключик выглядит совершенно непритязательно. Единственное, что выдаёт его значимость, – надпись, выгравированная на бородке: \"Служебные помещения Чёрного Железа – изготовление дубликатов строжайше запрещено\". У вас нет ни малейшего представления, что это за ключ и куда ведёт открываемая им дверь." },
    ["4451c"] = { male = "Вот те на! Чтоб мне провалиться! Ты нашёл ключ! Я знал, что проклятые дворфы Чёрного Железа спрятали его, после того как заперли меня в этой дыре! О, благодарю тебя! Скорее открой дверь и выпусти старика Локида на свободу!", female = "Вот те на! Чтоб мне провалиться! Ты нашла ключ! Я знал, что проклятые дворфы Чёрного Железа спрятали его, после того как заперли меня в этой дыре! О, благодарю тебя! Скорее открой дверь и выпусти старика Локида на свободу!" },
    ["4485a"] = { male = "Приветствую. Я вижу, твоя решимость по-прежнему сильна, как и твоя вера. Думаю, настало время тебе поговорить с Даторианом Раллом в Штормграде. Ты должен получить ещё несколько уроков, и я чувствую, ты к ним готов. Найди Даториана в Соборе Света – и пожалуйста, отнесись к его урокам серьёзно. Ты добился своего положения благодаря скромности и упорному труду, так не разочаруй нас – не становись высокомерным. Удачи тебе.", female = "Приветствую. Я вижу, твоя решимость по-прежнему сильна, как и твоя вера. Думаю, настало время тебе поговорить с Даторианом Раллом в Штормграде. Ты должна получить ещё несколько уроков, и я чувствую, ты к ним готова. Найди Даториана в Соборе Света – и пожалуйста, отнесись к его урокам серьёзно. Ты добилась своего положения благодаря скромности и упорному труду, так не разочаруй нас – не становись высокомерной. Удачи тебе." },
    ["4485c"] = { male = "А, вижу, ты вернулся в храм. Это хорошо. Многое случилось за последнее время, и я попрошу тебя о помощи, если ты докажешь, что способен справиться с моими поручениями. Кругом множество предателей. Мне нужна будет твоя помощь, чтобы остановить их.", female = "А, вижу, ты вернулась в храм. Это хорошо. Многое случилось за последнее время, и я попрошу тебя о помощи, если ты докажешь, что способна справиться с моими поручениями. Кругом множество предателей. Мне нужна будет твоя помощь, чтобы остановить их." },
    ["4486a"] = { male = "Ну-ка, ну-ка, поглядите на могучего паладина во всей красе! Прошу прощения, я не в обиду... Просто иногда немного завидую твоим достижениям. Тиза говорит, что в этом – моя слабость, и я обещал ей, что искореню этот недостаток. Но пока не преуспел, сам понимаешь. Но вот почему я хотел с тобой поговорить: Даториан Ралл из Штормграда сообщил, что хочет встретиться с тобой в Соборе Света, когда ты будешь к этому готов. Звучало веско. Звучало так, как будто что-то эдакое происходит.", female = "Ну-ка, ну-ка, поглядите на могучего паладина во всей красе! Прошу прощения, я не в обиду... Просто иногда немного завидую твоим достижениям. Тиза говорит, что в этом – моя слабость, и я обещал ей, что искореню этот недостаток. Но пока не преуспел, сама понимаешь. Но вот почему я хотел с тобой поговорить: Даториан Ралл из Штормграда сообщил, что хочет встретиться с тобой в Соборе Света, когда ты будешь к этому готова. Звучало веско. Звучало так, как будто что-то эдакое происходит." },
    ["4486c"] = { male = "А, вижу, ты вернулся в храм. Это хорошо. Многое случилось за последнее время, и я попрошу тебя о помощи, если ты докажешь, что способен справиться с моими поручениями. Кругом множество предателей. Мне нужна будет твоя помощь, чтобы остановить их.", female = "А, вижу, ты вернулась в храм. Это хорошо. Многое случилось за последнее время, и я попрошу тебя о помощи, если ты докажешь, что способна справиться с моими поручениями. Кругом множество предателей. Мне нужна будет твоя помощь, чтобы остановить их." },
    ["4487a"] = { male = "Ага, хорошо, что ты здесь. Я посылал суккуба за тобой, но, похоже, ты успел добраться сюда раньше, чем они добрались до тебя. Ладно. Тут недавно пошли разговоры о твоём растущем могуществе – и это очень хорошо для тебя, а для других, наверное, не очень. Короче, я думаю, что ты уже достаточно зарекомендовал себя и потому заслуживаешь...хе-хе... подарочка. В Степях над Кабестаном ты найдёшь человека по имени Страхад. Уверен, вы уже встречались.", female = "Ага, хорошо, что ты здесь. Я посылал инфернала за тобой, но, похоже, ты успела добраться сюда раньше, чем они добрались до тебя. Ладно. Тут недавно пошли разговоры о твоём растущем могуществе – и это очень хорошо для тебя, а для других, наверное, не очень. Короче, я думаю, что ты уже достаточно зарекомендовала себя и потому заслуживаешь...хе-хе... подарочка. В Степях над Кабестаном ты найдёшь человека по имени Страхад. Уверен, вы уже встречались." },
    ["4488a"] = { male = "О, ты почтил нас своим присуствием. Какая честь! Надеюсь, ты не думаешь, что мы будем тебя облизывать с ног до головы. Может, ты и быстро набираешь могущество, но ты всё ещё дитя малое в том, что касается истинного знания и мудрости. Если не поостережёшься, тебя охватит одержимость, и воля твоя ослабеет. Но ближе к делу – Страхад желает говорить с тобой. Он по-прежнему живёт в башне над Кабестаном в Степях. Советую не тянуть канитель.", female = "О, ты почтила нас своим присуствием. Какая честь! Надеюсь, ты не думаешь, что мы будем тебя облизывать с ног до головы. Может, ты и быстро набираешь могущество, но ты всё ещё дитя малое в том, что касается истинного знания и мудрости. Если не поостережёшься, тебя охватит одержимость, и воля твоя ослабеет. Но ближе к делу – Страхад желает говорить с тобой. Он по-прежнему живёт в башне над Кабестаном в Степях. Советую не тянуть канитель." },
    ["4489a"] = { male = "А, герой! Иди сюда! Тебя ведь зовут путник, не так ли? Я так и думал. Короче: твоя мощь растёт, и это было замечено. Теперь пора наградить тебя за старания. Иди в Степи. Там, над Кременником, ищи Страхада Фарсана – может, помнишь его? У него есть для тебя кое-что. Это много времени не займёт.", female = "А, героиня! Иди сюда! Тебя ведь зовут путница, не так ли? Я так и думал. Короче: твоя мощь растёт, и это было замечено. Теперь пора наградить тебя за старания. Иди в Степи. Там, над Кременником, ищи Страхада Фарсана – может, помнишь его? У него есть для тебя кое-что. Это много времени не займёт." },
    ["4489c"] = { male = "Значит, ты снова решил пожаловать меня своим визитом. Очень мило с твоей стороны. Мои помощники все гадали – придёшь или нет? Я говорил им – несомненно, придёт. Когда речь заходит о могуществе, летишь как мотылёк на свечу.", female = "Значит, ты снова решила пожаловать меня своим визитом. Очень мило с твоей стороны. Мои помощники все гадали – придёшь или нет? Я говорил им – несомненно, придёт. Когда речь заходит о могуществе, летишь как мотылёк на свечу." },
    ["4490a"] = { common = "Я бы наградил тебя за терпение да усердие. Но, знаешь ли, в будущем призывание коня Скверны будет куда труднее. Придётся заслужить награду... и это будет непросто. Пока же получи способность призывать эту тварь и пользуйся ей по своему усмотрению." },
    ["4490c"] = { common = "Удачи. Надеюсь встретиться с тобой в будущем." },
    ["4491a"] = { common = "Уф… Как здесь жарко! Я тут прогуливался по окрестностям, как вдруг накатила эта жуткая жара. Похоже, у меня тепловой удар. Помоги мне добраться до моей подруги Спрэггл в Укрытие Маршалла. Думаю, я сумею дойти, если кто-то будет вести меня. Если я вдруг потеряю сознание, просто плесни мне в лицо воды из фляги Спрэггл. Думаю, этого будет достаточно…" },
    ["4491c"] = { common = "Да, Ринго совсем плох, путник, но я рада, что он вернулся в целости и сохранности… Спасибо, что разыскал его!" },
    ["4492a"] = { common = "Помоги мне, путник! Мой друг Ринго отправился сегодня исследовать вулкан к югу отсюда, и его что-то долго нет! Я очень беспокоюсь. Ты сможешь найти его? Вот, возьми с собой эту флягу, думаю она ему пригодится!" },
    ["4492c"] = { common = "О… Я так рад, что кто-то нашёл меня…" },
    ["4493a"] = { common = "Такое впечатление, что смысл самого существования силитидов состоит в том, чтобы сожрать всё, что отлично от них. Они ведут себя очень целеустремлённо и именно поэтому представляют серьёзную опасность для всего Азерота. Всё, что мы видели до сих пор, — это только цветочки! Подозреваю, что их основные силы сосредоточены в глубине Калимдора, в Кратере Ун'Горо. Ступай в Прибамбасск в пустыне Танарис и поговори с алхимиком Пестычинсом. Расскажи ему о моей гипотезе. Он наверняка поможет нам бороться с силитидами." },
    ["4493c"] = { common = "Да я понял что Грацина послала тебя ко мне. Тебе придётся научиться биться с этими тварями. А что касается идеи Грацины про то, что кратер Ун'Горо их сердце… хм… не знаю, не знаю." },
    ["4494a"] = { common = "Такое впечатление, что намерения, более того, смысл самого существования силитидов состоит в том, чтобы сожрать всё, что отлично от них. Они ведут себя очень целеустремлённо и именно поэтому представляют серьёзную опасность для всего Азерота. Всё, что мы видели до сих пор, — это только цветочки! Подозреваю, что их основные силы сосредоточены в глубине Калимдора, в Кратере Ун'Горо. Ступай в Прибамбасск в пустыне Танарис и поговори с алхимиком Пестычинсом. Расскажи ему о моей гипотезе. Он наверняка поможет нам бороться с силитидами." },
    ["4494c"] = { common = "Да, я в курсе, что Зилзибин послал тебя ко мне. Идея Зилзибина о том, что источником этих тварей является кратер Ун'Горо… скажу так — возможно. Ун'Горо — это таинственное и мистическое место, там всё возможно." },
    ["4495a"] = { common = "Мой друг по имени Иверрон обычно навещает меня в одно и то же время каждый день. Странно, что сегодня он вообще не пришёл – он задерживается уже на несколько часов. Признаться, я несколько волнуюсь. Иверрон проводит много времени возле пещеры к северу отсюда, и я знаю, насколько там опасно – это ведь логово пауков! Послушай, если ты вдруг направляешься в ту сторону, то не поищешь ли Иверрона?" },
    ["4495c"] = { male = "Я рад, что тебе удалось найти меня. Как ты узнал, что я тут?", female = "Я рад, что тебе удалось найти меня. Как ты узнала, что я тут?" },
    ["4496a"] = { common = "Исследования показали, что силитиды подобны пчёлам — стоит убить королеву улья, и остальные без неё пропадут. Я создам приманку, которая позволит тебе выманить королеву. Выманив её, сразись с ней. Впрочем, для начала нам понадобятся некоторые составляющие. Отправляйся на запад, в ульи силитидов в Кратере Ун'Горо и принеси ароматическую железу одного из мерзких жуков. Кроме того мне понадобятся образцы почвы из кратера." },
    ["4496c"] = { common = "Железа Гориши, ах да. Мембрана не повреждена, отлично. Да думаю, что это почва как раз того типа, который мне нужен. Подожди пока я сделаю снадобье, путник. Когда оно будет готово, мы спланируем следующий шаг. Надеюсь, он поможет остановить силитидов, пока они не обрушились на Прибамбасск… и весь Калимдор." },
    ["4501a"] = { common = "Требуется: опытный боец для устранения угрозы со стороны жутедактилей, населяющих Кратер Ун'Горо. Популяция этих тварей растёт, они уже представляют серьёзную угрозу забредшим в кратер путникам. Необходимо уменьшить популяцию, убив десять жутедактилей и пятнадцать бесноватых жутедактилей. Выполнивших задание просьба обращаться за наградой к Муче Кусора." },
    ["4501c"] = { common = "Я просто в шоке от терродактилей! Спасибо тебе, путник! Теперь я хотя бы смогу спокойно высунуть нос из Укрытия Маршалла!" },
    ["4502a"] = { common = "Я многому научилась у Марвона Клепальщика. Но он уже так давно уехал, что я уж подумываю начать собственные эксперименты. Я недавно читала о Кратере Ун'Горо и странной вулканической деятельности в его центре. Мне думается, что многое можно было бы узнать, если бы мне удалось заполучить для исследований немного пепла из тамошних элементалей. Вы не против добыть немного пепла для меня, раз уж всё равно туда идёте?" },
    ["4502c"] = { common = "Эти образцы мне подходят! Благодарю тебя за весомый вклад в науку о вулканах, путник!" },
    ["4503a"] = { common = "Я работаю над вертолётом! И вот, застрял здесь и не могу выбраться! С удовольствием тормознул бы грифона или ветрокрыла, чтобы подбросили меня до Прибамбасска, да только ужасно боюсь этих тварей! Ты мне не поможешь? Мне осталось сделать только крылья, и я думаю, что чешуя жутедактиля или деметродона была бы идеальным материалом. Однако маленькому гоблину не под силу справиться со столь грозными хищниками! А ты на вид весьма крут! Может, попытаешься добыть мне чешуек?" },
    ["4503c"] = { common = "Да, эти чешуйки прекрасно подойдут. С ними я наверняка смогу поднять свою машину в воздух. Спасибо!" },
    ["4504a"] = { common = "Я всегда искал способ быстро заработать. Если ты поможешь воплотить мою последнюю идею, я поделюсь с тобой доходами. Что ты на это скажешь? Так я и думал! Ступай к смоляным ямам в северной части Кратера Ун'Горо и принеси мне смолы. Но не просто смолы, а смолы из зверей, живущих вокруг этих ям. Обычная смола недостаточно липкая. В растениеподобных существах присутствует хлорофилл, и смола, смешанная с ним, делается сверхлипкой." },
    ["4504c"] = { common = "Да, да, та самая смола… Эй, минуточку, руки мои, руки… Я не могу их разлепить… Может быть, это не такая уж хорошая идея. Впрочем, стоп! Растворитель суперлипкой смолы! Вот что разойдётся за полдня!" },
    ["4505a"] = { common = "Говорят, будто я слишком жестока… Но ведь это только потому, что я жажду добыть для Орды преимущество перед Альянсом любым способом. Сейчас меня прежде всего интересует лунный колодец в руинах Констелласа, к югу отсюда, который охраняют сатиры из племени Нефритового Пламени. Этот лунный колодец, некогда символ возрождения этих несносных ночных эльфов, ныне осквернён, и порождает всё больше сатиров. У меня есть одна мысль, путник, и мне хотелось бы получить пробу воды оттуда… для моей любимой кошечки." },
    ["4505c"] = { common = "Очень хорошо. Мы должны найти путь использовать эту порчу против наших врагов." },
    ["4506a"] = { common = "Эта осквернённая вода может помочь нам, путник. От одной её капли мои котятки выросли вдвое и даже стали сильнее… кое в чём. Эти кошечки могут оказаться полезными… Вот, путник. Возьми эту кошачью переноску и выпусти котёночка, что сидит внутри возле лунного колодца, что в руинах Констелласа. Хе-хе… результаты тебе наверняка понравятся! Потом принеси кошечку ко мне обратно, а я уж возмещу тебе затраты времени." },
    ["4506c"] = { common = "Превосходно! Отрекшиеся заплатят за такую воду немалые денежки, им нужны любые средства для борьбы с Альянсом, видишь ли." },
    ["4507a"] = { common = "Вот и приманка. Внутри улья должен быть какой-то кристалл. Мы думаем, что силитиды пользуются им для вещания по всему улью. Где он? Я бы поискал в инкубаторах. Если положить приманку на этот кристалл, непременно явится королева. Но предупреждаю, без охраны она не ходит. Убей её и вынь из неё мозг. Как ни гадко это звучит, его необходимо изучить. Удачи, путник!" },
    ["4507c"] = { common = "Превосходно, путник! Сегодня, мы достигли подлинного успеха! Нам придётся потратить время, чтобы понять, что мы обнаружили, но затем мы используем это." },
    ["4508a"] = { common = "Все исследования, да и знания, полученные нами сегодня, как можно скорее должны дойти до тех, кто в силах что либо предпринять. Прибамбасску не выстоять одному, невзирая на наши многочисленные таланты. Отнеси мой последний отчёт Грацине Силе Духа, в Дарнасс; она ведь по-прежнему в Храме Луны? У неё много друзей среди важных шишек Альянса; если удастся привлечь их внимание, быть может мы и выживем." },
    ["4508c"] = { common = "Альянс игнорирует опасность со стороны, которая намного опаснее, чем Орда. Глупцы, подобные Фендралу Оленьему Шлему строят теории, а силитиды тем временем завоёвывают своё жизненное пространство. Ты сам видел этих силитидов, путник. Мы должны их остановить!" },
    ["4509a"] = { common = "Все исследования, да и знания, полученные нами сегодня, как можно скорее должны дойти до тех, кто в силах что либо предпринять. Прибамбасску не выстоять одному, невзирая на наши многочисленные таланты. Отнеси мой последний отчёт Зилзибину Барабанному Бою, в Оргриммар; он ведь по-прежнему там? У него много друзей среди важных шишек Орды; если удастся привлечь их внимание, быть может мы и выживем." },
    ["4509c"] = { common = "Ничего не понимаю… Ну, неужели при отсутствии внимания лично Тралла эти бюрократы не могут поделать ничего? Обязательно надо отправлять доклад по инстанциям? Когда такие дела творятся… Ты же сам видел этих жутких силитидов, путник? Мы должны быть вооружены против них." },
    ["4510a"] = { male = "Путник, твоя помощь просто неоценима. Придёт время, и, думается, я снова буду вынужден обратиться к тебе за содействием в борьбе против силитидов. Мы должны осмыслить всё, что узнали в Ун'Горо. Опасаюсь, что мои предположения по поводу того, что силитиды родом из Ун'Горо, неверны… и где-то их гораздо больше. Отнеси эту бумагу Идриане в банк. Она выдаст тебе кое-что из моего хранилища в знак моей признательности. Благодарю тебя за помощь, отважный герой.", female = "Путник, твоя помощь просто неоценима. Придёт время, и, думается, я снова буду вынужден обратиться к тебе за содействием в борьбе против силитидов. Мы должны осмыслить всё, что узнали в Ун'Горо. Опасаюсь, что мои предположения по поводу того, что силитиды родом из Ун'Горо, неверны… и где-то их гораздо больше. Отнеси эту бумагу Идриане в банк. Она выдаст тебе кое-что из моего хранилища в знак моей признательности. Благодарю тебя за помощь, отважная героиня." },
    ["4510c"] = { common = "Этот банковский ваучер даёт право взять предмет со счёта Грацины Силы Духа и передать его тебе в вечное и неотъемлемое пользование. Бери и владей!" },
    ["4511a"] = { male = "Спасибо тебе, путник. Без тебя у нас бы ничего не вышло. Несомненно, вскоре придёт время, когда я снова попрошу твоей помощи в борьбе с силитидами. Придётся пересмотреть то, что известно нам по Ун'Горо. Боюсь, моё предположение, что силитиды происходят из Ун'Горо, оказалось ложным. Где-то есть другое гнездо, куда более крупное. Отнеси эту записку Карусу в банк. Он выдаст тебе кое-что, что может считаться знаком моей благодарности. Спасибо за помощь, могучий герой!", female = "Спасибо тебе, путник. Без тебя у нас бы ничего не вышло. Несомненно, вскоре придёт время, когда я снова попрошу твоей помощи в борьбе с силитидами. Придётся пересмотреть то, что известно нам по Ун'Горо. Боюсь, моё предположение, что силитиды происходят из Ун'Горо, оказалось ложным. Где-то есть другое гнездо, куда более крупное. Отнеси эту записку Карусу в банк. Он выдаст тебе кое-что, что может считаться знаком моей благодарности. Спасибо за помощь, могучая героиня!" },
    ["4511c"] = { common = "Так… этот ваучер разрешает взять один предмет со счёта Зилзибина Барабанного Боя и отдать тебе в вечное и неотъемлемое владение! Мои поздравления." },
    ["4512a"] = { common = "Но больше всего я изучал слизнюков. Я понимаю, что звучит нелепо, но их же почти не осталось! Не так давно я помогал одной даме из Менетила искать её сумку — так слизнюки эту сумку сожрали. Я видел, что члены Королевского фармацевтического общества Подгорода собирают образцы этих тварей. Я хочу понять, почему! Откуда они их берут? Я слышал, что они водятся в Осквернённом лесу. Мне нужны экземпляры этих слизнюков для продолжения исследований. Я дам вам банки, а вы возьмёте образцы мёртвых существ." },
    ["4512c"] = { common = "Блестящий результат, путник! Вы умудрились подойти достаточно близко, взять образцы этих гнилостных тварей и ничуть не пострадать! Благодарю вас. О, это как раз то, что надо. Немедленно примусь за эксперименты. Если я прав, я стану одним из величайших учёных Лиги Исследователей! Это покажет всем дворфам, что они правильно поступили, пустив нас, гномов, в Стальгорн после гномреганской катастрофы." },
    ["4513a"] = { common = "Мне, похоже, понадобятся ещё образцы, путник. Но — как бы это сказать — они должны быть чистыми. Да знаю, знаю. \"Что значит \"чистые\", Ларис?\" Я не уверен. Я знаю только, что вот эти — осквернены… прямо как Фелвуд. Потому так важно понять. Эти слизнюки словно бы приспосабливаются к условиям места, в котором находятся. Мне нужны образцы, которые не заражены. Но где их взять? Где?! Путник, возьмите эти банки на случай, если вам попадутся чистые экземпляры." },
    ["4513c"] = { common = "Так вы их нашли? Путник, вы — сущее сокровище! Ваши преданность и помощь просто неоценимы, я даже не знаю, чем вас отблагодарить! Пожалуйста, примите это за ваши труды. Мне надо кое над чем поработать, но я уверен, что, когда вы вернётесь, мне снова понадобится ваша помощь. Благодарю вас! От всего сердца благодарю!" },
    ["4521a"] = { common = "Зимние Ключи расположены как раз за Древобрюхами на северо-востоке Осквернённого леса. Приходилось там бывать? Я слышал, что эти края заселены существами, которых называют дикосовухами. Эти животные, как известно, охраняли тайны ночных эльфов. Мы должны выяснить, какие тайны хранятся в Зимних Ключах. Я слышал что лохматые совухи водятся к югу от этой дороги, а те, которых называют бешеными совухами, населяют центр Зимних Ключей. Убей их и расчисть дорогу." },
    ["4521c"] = { common = "Прекрасные новости, путник. Теперь, когда на нашем пути не стоят эти твари, мы пойдём дальше в Зимние Ключи. Ты готов?" },
    ["4542a"] = { common = "Кентавры стали всё чаще нападать на эти земли, и об этом нужно срочно доложить на Заставу Вольного Ветра! Отправляйтесь туда, найдите дозорного утёсов Долгорога и отдайте ему это письмо. Форт находится к юго-востоку отсюда. Но будьте осторожны: неподалёку есть поселение клана Зловещий Тотэм, и его члены в последнее время ведут себя беспокойно" },
    ["4542c"] = { common = "Опять плохие новости! Эти кентавры зашли слишком далеко! Они напали на один из моих караванов и убили всех погонщиков! Это неслыханно, они должны за это заплатить!" },
    ["4581a"] = { common = "Друид Кайнет Штиль прислал мне весточку. Он хотел бы получить отчёт обо-всём, что творится у нас на побережье и в лесах вокруг Астранаара. Он опасается, что по Ясеневому лесу расползается порча... Может, он и прав. Вот, отнеси ему мой отчёт. Ты найдёшь его в святилище Лесной Песни, в лесах Ночной Песни к востоку отсюда." },
    ["4581c"] = { common = "А, отчёт Шиндрелл! Премного благодарен. Шиндрелл – отличный часовой, она отважна и умна. Надо прочесть это донесение и попытаться понять, что за нечисть расползается по Ясеневому лесу." },
    ["4601a"] = { common = "Этот механизм широко применяется гномами для борьбы со всеми видами загрязнений.Небольшая табличка, прикреплённая к устройству, гласит: \"Чистер пять тысяч двести\". Ваши фамильные драгоценности и просто безделушки покрывает пыль веков? Чистер пять тысяч двести легко справится с этой проблемой! Опустите в щель приёмника три серебряные монеты и подождите пару минут, пока Чистер пять тысяч двести наводит лоск на ваши украшения." },
    ["4601c"] = { common = "Вы кладёте покрытый грязью предмет и три серебряные монеты в Чистер пять тысяч двести, и машина начинает работать, с гудением отскребая въевшуюся грязь. Металлический корпус аппарата скрипит и вибрирует." },
    ["4602a"] = { common = "Этот механизм широко применяется гномами для борьбы со всеми видами загрязнений.Небольшая табличка, прикреплённая к устройству, гласит: \"Чистер пять тысяч двести\". Ваши фамильные драгоценности и просто безделушки покрывает пыль веков? Чистер пять тысяч двести легко справится с этой проблемой! Опустите в щель приёмника три серебряные монеты и подождите пару минут, пока Чистер пять тысяч двести наводит лоск на ваши украшения." },
    ["4602c"] = { common = "Вы кладёте покрытый грязью предмет и три серебряные монеты в Чистер пять тысяч двести, и машина начинает работать, с гудением отскребая въевшуюся грязь. Металлический корпус аппарата скрипит и вибрирует." },
    ["4605c"] = { common = "Проглотив кольцо, машина несколько минут с гудением вертит его в своих недрах и наконец останавливается, звенящим звуком оповестив вас о том, что работа закончена. Окошко приёмника открывается, и вы видите в нём аккуратно завёрнутую коробочку. Видимо, машина выдаёт очищенные предметы в подарочной упаковке. Ну, даже если кольцо не удалось очистить, вы получили довольно миленькую коробочку за свои деньги… Что ж, посмотрим…" },
    ["4606c"] = { common = "Проглотив кольцо, машина несколько минут с гудением вертит его в своих недрах и наконец останавливается, звенящим звуком оповестив вас о том, что работа закончена. Окошко приёмника открывается, и вы видите в нём аккуратно завёрнутую коробочку. Видимо, машина выдаёт очищенные предметы в подарочной упаковке. Ну, даже если кольцо не удалось очистить, вы получили довольно миленькую коробочку за свои деньги… Что ж, посмотрим…" },
    ["4641a"] = { male = "Ну вот, ты и стал взрослым... достаточно взрослым, чтобы сражаться во имя Орды и во славу вождя. *Калтунк меряет вас взглядом.* Да, ты вполне годишься! Разумеется, тебе уже хочется повстречаться с огромным драконом или каким-нибудь демоном и задушить его голыми руками, но, пожалуй, начать стоит с чего-нибудь... не такого грозного. *Калтунк хохочет.* Отправляйся к Горнеку, он сумеет подыскать дело, которое будет тебе по плечу, юный герой. Горнека ты найдёшь в Логове, на западе.", female = "Ну вот, ты и стала взрослой... достаточно взрослой, чтобы сражаться во имя Орды и во славу вождя. *Калтунк меряет вас взглядом.* Да, ты вполне годишься! Разумеется, тебе уже хочется повстречаться с огромным драконом или каким-нибудь демоном и задушить его голыми руками, но, пожалуй, начать стоит с чего-нибудь... не такого грозного. *Калтунк хохочет.* Отправляйся к Горнеку, он сумеет подыскать дело, которое будет тебе по плечу, юная героиня. Горнека ты найдёшь в Логове, на западе." },
    ["4641c"] = { male = "Очередной рекрут Калтунка? Видно, плохи наши дела, если у нас нет никого получше. Ну, ничего. К тому времени, как мы решим, что тебе пора покинуть долину, из тебя получится бравый воитель Орды!", female = "Очередной рекрут Калтунка? Видно, плохи наши дела, если у нас нет никого получше. Ну, ничего. К тому времени, как мы решим, что тебе пора покинуть долину, из тебя получится бравая воительница Орды!" },
    ["4642a"] = { common = "В этом сосуде находится слизнюк, созданный из пробы, которую ты принёс из Осквернённого леса. Отнеси его к кратеру Ун'Горо и отыщи чистого слизнюка. Подберись поближе, выпусти наш экземпляр и посмотри, что они сделают друг с другом. По завершении эксперимента принеси мне пробу того, что останется. Я буду ждать тебя здесь, в Районе Фармацевтов." },
    ["4642c"] = { common = "Превосходно, путник. Это просто превосходно! Теперь нам следует изучить приспособляемость этих существ к условиям изменчивой окружающей среды. Я продолжу мои исследования. Возможно, мы ещё поговорим в дальнейшем." },
    ["4681a"] = { common = "Та тварь на берегу – не единственная на Тёмном Берегу. Вдоль побережья их ещё много, да и в воде тоже. Я хотела бы, чтобы вы исследовали другие известные нам останки. Мне сообщили, что они находятся в воде, непосредственно к западу от Аубердина, возле затонувшего судна. Возвращайтесь ко мне с тем, что вам удастся найти полезного для нас. Кстати, в ваших странствиях вы можете найти и другие подобные останки. Если вы обнаружите что-то, обязательно принесите нам для дальнейших исследований!" },
    ["4681c"] = { common = "Вы чрезвычайно помогли мне сегодня; теперь у нас есть серьёзные шансы узнать, почему эти твари выбрасываются на отмели Тёмного Берега. Мысль о том, что они бегут сюда из прибрежных вод Тельдрассила, очень беспокоит меня. Если вы наткнётесь на другие останки в ваших странствиях, пожалуйста, дайте мне знать. Наши исследования здесь пока на начальной стадии. От имени Храма Луны примите, пожалуйста, это в качестве благодарности за ваши труды. Благодарю вас!" },
    ["4701a"] = { common = "Тебе несомненно приходилось видеть воргов, которыми командуют орки Чёрной Горы. Вот что интересно — сколько мы их ни убиваем, их не делается меньше. Разведчики доносят, что воргов растят и обучают на пике Чёрной Горы, в столице орков этого клана. Отправляйся туда и поищи источник опасности. Отыщи… и уничтожь. Удачи, путник. Да хранит тебя Кенарий…" },
    ["4701c"] = { common = "Отличная работа, путник. Этот зверь — продукт тёмной магии, был повержен. Ты оказал неоценимую помощь Альянсу и за это должен быть вознаграждён." },
    ["4721a"] = { common = "Гонцы вернулись из Зимних Ключей с сообщением о том, что в его южной части есть группа небольших пещер. У них сложилось впечатление, что этот район обжили дикосовухи. Если они охраняют что-то важное, то, я думаю, именно там мы это и найдём. С этими дикосовухами вам будет справиться намного сложнее, чем в предыдущий раз, путник. Эти создания, похоже, ввергает в безумие та самая вещь, которую они столь яростно защищают." },
    ["4721c"] = { common = "Чем тяжелее задача, тем больше уважения по её выполнении, путник. Теперь мы можем двигаться вперёд, по нашим планам." },
    ["4722a"] = { common = "Вы наткнулись на останки морской черепахи, некоторое время назад выбросившейся на Тёмный Берег. Плоть её уже объели мурлоки, обосновавшиеся неподалёку от останков. Однако вы можете набрать достаточное количество образцов, которые пригодятся Гвеннид Блай'Леггонд." },
    ["4722c"] = { common = "Ещё одна находка, которую нам надо изучить. Хорошая работа! Эти останки будут исследованы должным образом, когда их доставят в Дарнасс. Пожалуйста, примите это скромное вознаграждение за те образцы, которыми вы нас снабжаете." },
    ["4723a"] = { common = "Останки гигантского крепкозуба – намного больших размеров, чем можно было бы ожидать на Тёмном Берегу, – лежат у побережья Туманного предела. Как это существо очутилось здесь, неизвестно; мурлоки, объедающие тушу, кажутся слишком слабыми и неспособными даже толпой притащить её сюда. В то время как некоторая часть костей уже начисто обглодана, останков ещё достаточно, чтобы набрать образцов для Гвеннид Блай'Леггонд." },
    ["4723c"] = { common = "Ещё одна находка, которую нам надо изучить. Хорошая работа! Эти останки будут исследованы должным образом, когда их доставят в Дарнасс. Пожалуйста, примите это скромное вознаграждение за те образцы, которыми вы нас снабжаете." },
    ["4724a"] = { common = "Ходят слухи, что ворги, управляемые орками Чёрной Горы, — создания сверхъестественных сил. Говорят также, что это не настоящие ворги, а потомство пса-демона, подаренное оркам властителем преисподней. Правда куда более проста, но не менее ужасна. Ворги Чёрной Горы — потомство Халикон, огромной праматери воргов. Каков из себя её самец? Вряд ли кто из видевших его выжил, чтобы поведать об этом. Нужно нанести удар по самому сердцу логова воргов. Уничтожь Халикон. И прошу тебя, не забывай об осторожности!" },
    ["4724c"] = { common = "Ты жив? И ещё говоришь? Невероятно!" },
    ["4725a"] = { common = "Ещё одни останки морской черепахи лежат прямо на берегу. К панцирю прикреплена упряжь. Скорее всего, черепаху выгнали на берег неизвестные нам твари; она не выбросилась на берег сама, хотя другие останки и наводят на эту мысль. Теперь останками черепахи завладели мурлоки клана Серой Мглы, питающиеся мертвечиной. Обследуя упряжь, вы обнаруживаете ящик со странными пометками. Может быть, Гвеннид Блай'Леггонд сможет что-то понять?" },
    ["4725c"] = { common = "Я слышала о такой сбруе, которую вы нашли на черепашьем панцире. Это, как я понимаю, упряжь нагов – они используют такие как в сражениях, так и для перевозок своих припасов на сушу. Пометки на ящике также сделаны нагами; это объясняет их неожиданное присутствие в северной части Тёмного Берега. Я отошлю этот ящик в Дарнасс вместе с остальными вашими находками. А это – вам, и ещё раз спасибо за вашу помощь." },
    ["4726a"] = { common = "Я уже несколько недель изучаю драконов Пылающих степей, и кажется, наконец-то наметился определённый прорыв! Я создала устройство — Драко-инкарцинатор девятьсот. Оно может поймать сущность детёныша дракона! По крайней мере, я так думаю. Возьми это устройство и испытай его на детёныше дракона в Пылающих степях. Пока он будет под воздействием инкарцинатора, одолей его и выпусти из него сущность. Если это сработает, будет замечательно! И принеси мне образцы на изучение!" },
    ["4726c"] = { common = "Сработало! Ты получил сущность! Молодец, путник! Молодец! Она окажет мне неоценимую помощь в исследованиях. Надеюсь, однажды я научусь ловить молодых дракончиков или захватывать их яйца. Если я найду способ сделать это, мне станут завидовать все исследователи драконов в мире! И мой шеф тоже будет доволен." },
    ["4727a"] = { common = "Скелет морской черепахи лежит на песчаной отмели на севере Тёмного Берега. Мурлоки клана Серой Мглы либо не нашли её тушу, либо по каким-то причинам не рискнули приблизиться к ней. В любом случае, от черепахи осталось достаточно, чтобы взять образцы для Гвеннид Блай'Леггонд, проводящей расследование по поручению Храма Луны." },
    ["4727c"] = { common = "Интересно, что мурлоков там не было. Мы будем иметь это в виду, когда начнём изучать эти останки! Благодарю вас за ваши труды; Храм Луны уполномочил меня передать вам эти деньги в качестве компенсации за потраченное время." },
    ["4728a"] = { common = "Растерзанные останки того, что на вид кажется похожим на гигантское морское млекопитающее, лежат на берегу. Около них валяется тачка и различные инструменты, как будто кто-то раньше уже пытался изучать останки. Хотя мурлоки основательно растащили скелет, останков достаточно, чтобы найти подходящий образец костей для Гвеннид Блай'Леггонд в Аубердине." },
    ["4728c"] = { common = "О, я уверена, вы обнаружили останки твари, которые уже изучались Лигой Исследователей. Они работают здесь, на Тёмном Берегу, и упоминали, что изучали одну из выбросившихся на берег тварей, пока их не прогнали мурлоки. Похоже, вам удалось добиться успеха там, где и мы, и они потерпели фиаско. Пожалуйста, примите эту скромную плату от имени Храма Луны." },
    ["4729a"] = { common = "Должно быть, тебе интересно, что я здесь делаю? Взгляни на клетки! Разве не ясно? Я очень люблю животных, но по роду занятий я торговец. Я разыскиваю и приручаю редких зверей, чтобы богатые и знаменитые клиенты могли сделать их своими питомцами. Теперь ты, наверное, хочешь спросить: \"Чем я могу тебе помочь, Киблер.\" Отвечаю: возьми эту клетку и поймай несколько щенков-воргов. За это я приручу одного из них и отдам тебе!" },
    ["4729c"] = { common = "Ты вовремя их принёс, путник. Подрасти они ещё немного, и их не удалось бы приручить! Дай мне пару минут, и одного из них можешь забирать." },
    ["4730a"] = { common = "Полуразложившиеся тело твари, похожей на огромное морское млекопитающее, лежит на берегу. Группа мурлоков, более сильных, чем обитающие ближе к Аубердину, обосновалась вокруг погибшего создания. Останков достаточно, чтобы отобрать образцы костей, которые можно отнести Гвеннид Блай'Леггонд." },
    ["4730c"] = { common = "Кости, которые вы принесли, принадлежат мирным морским млекопитающим, обитающим в водах, окружающих корни Тельдрассила. Им, насколько известно, никогда не было свойственно выбрасываться на берег, как это делают крепкозубы. Хотела бы я знать, почему они так ведут себя. Что ж, может быть, изучение их останков принесёт свои плоды, и мы что-то узнаем. И снова спасибо вам за помощь. Пожалуйста, примите это вознаграждение от имени Храма Луны." },
    ["4731a"] = { common = "Ещё одни останки морской черепахи лежат у береговой линии. На панцире есть упряжь, которая ещё частично держится. Возможно, несчастная тварь не сама выбросилась на берег (что кажется наиболее вероятным по отношению к другим погибшим тварям), а была пригнана к береговой линии неизвестными существами. Могучие мурлоки клана Серой Мглы сделали остов этой твари своим жилищем. Обследуя упряжь, вы обнаруживаете ящик со странными пометками. Возможно, Гвеннид Блай'Леггонд сумеет что-то разобрать?" },
    ["4731c"] = { common = "Я слышала о такой сбруе, которую вы нашли на черепашьем панцире. Это, как я понимаю, упряжь наг – они используют такие как в сражениях, так и для перевозок своих припасов на сушу. Пометки на ящике также сделаны нагами; это объясняет их неожиданное присутствие в северной части Тёмного Берега. Я отошлю этот ящик в Дарнасс вместе с остальными вашими находками. А это – вам, и ещё раз спасибо за вашу помощь." },
    ["4732a"] = { common = "Вы обнаружили тело морской черепахи, выбросившейся на Тёмный Берег некоторое время назад. Оно почти дочиста объедено мурлоками клана Серой Мглы – теми самыми, что поселились вокруг останков. Однако, похоже, несколько подходящих образцов для Гвиннед Блай'Леггонд вы сможете отобрать." },
    ["4732c"] = { common = "Так вы нашли и других выбросившихся на берег тварей? Морские черепахи обычно резвились в водах у подножья Нордрассила – до его гибели. Однако с рождением Тельдрассила этих созданий становится всё меньше и меньше. Некоторые, как мы уже знаем, оканчивают свою жизнь здесь – непонятно почему. Быть может, ваша помощь поможет нам раскрыть эту тайну. Пожалуйста, примите эти деньги за образцы, предоставленные нам для исследований." },
    ["4733a"] = { common = "Останки животного, похожего на гигантского крепкозуба, лежат, вынесенные на отмель в скалистой Сумрачной Излучине. Этот крепкозуб в несколько раз больше любого из тех, что обитают в здешних водах. Откуда бы это создание ни приплыло, вряд ли оно родом с Тёмного Берега. Хотя туша животного уже потеряла целостность, останков достаточно, чтобы найти подходящие образцы для Гвеннид Блай'Леггонд." },
    ["4733c"] = { common = "Размеры крепкозуба, о котором вы рассказываете, просто ошеломляют. Даже самые старые крепкозубы в этих водах – и то в несколько раз меньше. В то время как крупные крепкозубы, как известно, обитают близ Тельдрассила, их количество постоянно уменьшается. Интересно, связано ли как-то это с выбрасывающимися на берег тварями? Мы продолжим анализ костей, которые вы нам принесли, а это вам вознаграждение от имени Храма Луны. Благодарю вас." },
    ["4734a"] = { common = "Путник, я работаю над созданием нового устройства, яйцехладоскопа! Оно предназначено для того, чтобы направить сгусток холода на яйцо дракона… и заморозить его! Можешь испытать эту штуку? Говорят, что на пике Чёрной горы у драконов есть питомник, в котором полно яиц. Подходящее место для испытаний! Заморозь яйцо и расскажи, сработал прибор или нет. Не беспокойся. Замороженные драконьи яйца совершенно безобидны. А вот остальных надо опасаться!" },
    ["4734c"] = { common = "Он таки работает? Ну чудесно! Я знала! Пока ты уходил, я работала над новой версией яйцехладоскопа. У неё значительно больший радиус действия. Вот, возьми один, он пригодится тебе, если ты снова отправишься на пик Чёрной Горы." },
    ["4735a"] = { common = "Путник, я, наконец, готова исследовать настоящие яйца драконов! Возьми это устройство-коллекционер. Он предназначен для захвата драконьего яйца и подготовки его к транспортировке. Возвращайся в Гнездовье и собери при помощи этой штуки несколько яиц. Не забудь, первым делом их надо заморозить, иначе из них могут вылупиться драконы, не успеешь собрать! Как только наберёшь достаточно яиц, неси их мне!" },
    ["4735c"] = { common = "О, ты получил их! Моё устройство-коллекционер работает. Я гений! Спасибо тебе, путник. Мой покровитель будет очень доволен получить эти яйца." },
    ["4736a"] = { common = "А, привет. Твоё обучение идёт неплохо. Настолько неплохо, что, я думаю, пришло время вознаградить тебя за прилежание – и за то, что сила магии всё ещё не поработила тебя. Если тебя заинтересовали мои слова, поговори с Менарой Расщепительницей Бездны из Кабестана. В настоящий момент она живёт в башне Страхада Фарсана, построенной на утёсе над городом. Она не очень доброжелательно настроена, поэтому похвалы от неё не жди. Но если ты будешь стараться, твои усилия не пропадут втуне." },
    ["4736c"] = { male = "А, тебя прислал Остротерн. Хорошо. Значит, вести обо мне распространяются по всей земле, и ученики приходят сами. Приятно. Наш брат всегда старается держаться вместе, независимо от расы. Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля. Вижу, ты многому научился, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту.", female = "А, тебя прислал Остротерн. Хорошо. Значит, вести обо мне распространяются по всей земле, и ученики приходят сами. Приятно. Наш брат всегда старается держаться вместе, независимо от расы. Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля. Вижу, ты многому научилась, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту." },
    ["4737a"] = { male = "Ха! Я вижу, ты стремишься к могуществу. Не сомневаюсь, рано или поздно ты падёшь жертвой соблазна и жажды магии. Пфа! Ты глуп! Время покажет, что я был прав, – ничто другое, одно лишь время… Но мне кажется, что не все согласны с Зевростом. Менара готова создать предметы, которые помогут тебе обрести могущество и обуздать собственную силу. Если хочешь, ступай в Кабестан. Она живёт в башне над городом.", female = "Ха! Я вижу, ты стремишься к могуществу. Не сомневаюсь, рано или поздно ты падёшь жертвой соблазна и жажды магии. Пфа! Ты глупа! Время покажет, что я был прав, – ничто другое, одно лишь время… Но мне кажется, что не все согласны с Зевростом. Менара готова создать предметы, которые помогут тебе обрести могущество и обуздать собственную силу. Если хочешь, ступай в Кабестан. Она живёт в башне над городом." },
    ["4737c"] = { male = "А, тебя прислал Зеврост. Хорошо. Значит, вести обо мне распространяются по всей земле, и ученики приходят сами. Приятно. Наш брат всегда старается держаться вместе, независимо от расы. Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля. Вижу, ты многому научился, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту.", female = "А, тебя прислал Зеврост. Хорошо. Значит, вести обо мне распространяются по всей земле, и ученики приходят сами. Приятно. Наш брат всегда старается держаться вместе, независимо от расы. Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля. Вижу, ты многому научилась, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту." },
    ["4738a"] = { male = "Пойми одно: я считаю, что ты не готов к такой ответственности. Я уверена, что вовлекать новичков в создание любых предметов силы, тем более, непроверенных, недопустимо. Но решать не мне, а сильным мира сего, которые хотят наделить тебя такими дарами. Если ты хочешь узнать побольше, советую поговорить с Менарой Расщепительницей Бездны из Кабестана. Обычно её можно найти в башне над портом.", female = "Пойми одно: я считаю, что ты не готова к такой ответственности. Я уверена, что вовлекать новичков в создание любых предметов силы, тем более, непроверенных, недопустимо. Но решать не мне, а сильным мира сего, которые хотят наделить тебя такими дарами. Если ты хочешь узнать побольше, советую поговорить с Менарой Расщепительницей Бездны из Кабестана. Обычно её можно найти в башне над портом." },
    ["4738c"] = { male = "А, тебя прислала Демизетта. Хорошо. Значит, вести обо мне распространяются по всей земле, и ученики приходят сами. Приятно. Наш брат всегда старается держаться вместе, независимо от расы. Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля. Вижу, ты многому научился, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту.", female = "А, тебя прислала Демизетта. Хорошо. Значит, вести обо мне распространяются по всей земле, и ученики приходят сами. Приятно. Наш брат всегда старается держаться вместе, независимо от расы. Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля. Вижу, ты многому научилась, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту." },
    ["4739a"] = { male = "герой! Да, ты! Вижу, ты не полностью экипирован, хотя уверенности и поднабрался. Да-да, теперь я это понимаю. Менара Расщепительница Бездны научит тебя нескольким вещам. Она немало времени посвящает обучению молодёжи тайным искусствам. Тем, кто проходит её испытания, она даже даёт дары. Если хочешь поучиться, ступай в город Кабестан в Степях. Она живёт над городом в башне Страхада.", female = "героиня! Да, ты! Вижу, ты не полностью экипирована, хотя уверенности и поднабралась. Да-да, теперь я это понимаю. Менара Расщепительница Бездны научит тебя нескольким вещам. Она немало времени посвящает обучению молодёжи тайным искусствам. Тем, кто проходит её испытания, она даже даёт дары. Если хочешь поучиться, ступай в город Кабестан в Степях. Она живёт над городом в башне Страхада." },
    ["4739c"] = { male = "А, тебя прислал Каэл. Хорошо. Значит, вести обо мне распространяются по всей земле, и ученики приходят сами. Приятно. Наш брат всегда старается держаться вместе, независимо от расы. Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля. Вижу, ты многому научился, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту.", female = "А, тебя прислал Каэл. Хорошо. Значит, вести обо мне распространяются по всей земле, и ученики приходят сами. Приятно. Наш брат всегда старается держаться вместе, независимо от расы. Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля. Вижу, ты многому научилась, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту." },
    ["4740a"] = { common = "Внимание! Назначена награда за голову мурлока, именуемого \"Глубомрак\". Эта злобная тварь повинна в смерти как минимум одного часового и подозревается в потоплении как минимум двух грузовых судов в прибрежных водах Тёмного Берега! Глубомрака в последний раз видели в поселении мурлоков к югу от Аубердина, и, судя по всему, он охраняет хижины своих сородичей. Награда за голову Глубомрака ждёт смельчака у часового Глинды Нал'Шии в Аубердине. Совет Аубердина" },
    ["4740c"] = { male = "Что ж, похоже, вы здесь не только затем, чтобы просто узнать! Жители Аубердина будут счастливы известию, что сегодня они смогут спать немного спокойнее. Сегодня вы послужили для наших жителей орудием справедливости. И за это я хотела бы предложить вам вот это в качестве награды, подходящей... для настоящего героя народа Аубердина.", female = "Что ж, похоже, вы здесь не только затем, чтобы просто узнать! Жители Аубердина будут счастливы известию, что сегодня они смогут спать немного спокойнее. Сегодня вы послужили для наших жителей орудием справедливости. И за это я хотела бы предложить вам вот это в качестве награды, подходящей... для настоящей героини народа Аубердина." },
    ["4741a"] = { common = "В северных областях Зимних Ключей дикосовухи совсем озверели. Необходимо положить этому конец! Отправляйся на охоту, а заодно исследуешь местность, где они обитают. Места там дикие, но ты справишься. Возвращайся, когда убьёшь тринадцать совухов." },
    ["4741c"] = { common = "Тебе похоже понравилось! Я надеюсь, что и им тоже…" },
    ["4742a"] = { common = "Видишь, в этой печати есть три простых углубления. В них надо вставить три камня власти; после этого властитель Змейталак, владыка нижней крепости, должен будет закалить печать в пламени чёрных драконов. Найди эти камни! И помни, смертный: шансы, что у кого-то из трёх генералов нижней крепости будет при себе нужный нам камень, невелики. Не отступайся! Ищи, будь внимателен и не теряй решимости!" },
    ["4742c"] = { common = "Теперь простая печать Вознесения готова. Время сделать последний шаг." },
    ["4743a"] = { common = "Очень немногие чёрные драконы из верхней крепости способны закалить печать в пламени своего дыхания. Змейталак — один из них, но его волю сломить невозможно. Тебе надо добраться до Драконьих топей в Пылевых топях. Там ты найдёшь древнего дракона, известного под именем Огнебор. Ты должен сломить его волю, путник. И когда он ослабнет, тебе нужно будет воспользоваться этой сферой. Но помни, смертный: его разум силён, и ты сможешь удерживать его под контролем не более нескольких секунд. За эти секунды тебе нужно успеть закалить печать." },
    ["4743c"] = { common = "Стой спокойно, пока я создаю последнюю ступень защиты. Печать вознесения завершена… Знай, что я напитал этот артефакт несколькими слоями магической защиты… В твой худший час, когда всё будет потеряно, мощь красных драконов придёт тебе на помощь." },
    ["4761a"] = { common = "При разведке в лагере фурболгов вы обнаружили информацию, которую нужно довести до сведения Тандриса Ветропряда. Он любезно согласился исполнять обязанности старейшины в Аубердине, мудростью своей направляя повседневную жизнь деревни. Прошу вас поделиться с ним вашими находками в деле фурболгов. Я уверен, что у него есть свои идеи по поводу источника наведённой на них порчи. Может быть, вы сможете вместе с ним выработать план восстановления природного равновесия!" },
    ["4761c"] = { male = "Рад нашей встрече, герой. Ваше расследование ситуации с фурболгами как нельзя кстати. Уже в течение некоторого времени мы имеем дело не только с обитателями здешних лесов, ныне относящихся к нашему присутствию с неприкрытой враждебностью, но и с явной порчей, наведённой на сами леса. Надеюсь, вы сможете протянуть Аубердину руку помощи в эти неспокойные времена.", female = "Рад нашей встрече, героиня. Ваше расследование ситуации с фурболгами как нельзя кстати. Уже в течение некоторого времени мы имеем дело не только с обитателями здешних лесов, ныне относящихся к нашему присутствию с неприкрытой враждебностью, но и с явной порчей, наведённой на сами леса. Надеюсь, вы сможете протянуть Аубердину руку помощи в эти неспокойные времена." },
    ["4762a"] = { common = "Воды реки Скалистой исполнились злобы и порчи. Река впадает в Туманный предел, и я боюсь, что скоро беда затронет и Аубердин. Я подозреваю, что в загрязнении повинны фурболги Чернолесья, живущие в верховьях реки, но я также полагаю, что они не являются подлинной причиной этой порчи. Возьмите эту пробирку и отправляйтесь к устью реки, что к северу отсюда. Идите вверх по реке до первого водопада и там возьмите пробу воды. Ориентиром вам послужит высокий мост через реку. Когда возьмёте пробу, вернитесь ко мне в Аубердин." },
    ["4762c"] = { common = "Я не удивлён тем, насколько сильно отравлена эта вода, но поглядите, какой мерзостной она становится! Похоже, что нужно действовать как можно скорее, да? К востоку от нас находится Осквернённый лес; это и есть настоящий источник порчи, я в прошлом такой уже видел. Заранее могу сказать, что ваша проба подтвердит это. Наверное, мы могли бы найти средство для исцеления, но нам понадобится помощь, даже чтобы попытаться это сделать. Когда придёт время, я надеюсь, вы сможете нам её предоставить." },
    ["4763a"] = { common = "Мы узнали, что источником порчи, наведённой на фурболгов, являются сатиры. Они держат своих жертв в повиновении с помощью талисманов, через которые направляют магию. Если для фурболгов ещё есть шансы на спасение, мы должны выманить сатиров-поработителей и отнять у них талисманы! Наполни эту чашу из нашего лунного колодца и стащи образцы пищи фурболгов из их северного лагеря. Смешай всё и поставь чашу возле большого костра у реки; любой фурболг, поевший из этой чаши, на некоторое время очистится, что привлечёт внимание сатира... которого нужно убить!" },
    ["4763c"] = { male = "Мы только начали войну за освобождение наших лесов от порабощающих сил порчи, но сегодняшняя битва выиграна! путник, народ Аубердина в огромном и почти неоплатном долгу перед вами. Прошу вас принять это вместе с нашей благодарностью. То, что мы узнали сегодня, может в один прекрасный день навсегда освободить наших друзей-фурболгов от мучительных оков.", female = "Мы только начали войну за освобождение наших лесов от порабощающих сил порчи, но сегодняшняя битва выиграна! путница, народ Аубердина в огромном и почти неоплатном долгу перед вами. Прошу вас принять это вместе с нашей благодарностью. То, что мы узнали сегодня, может в один прекрасный день навсегда освободить наших друзей-фурболгов от мучительных оков." },
    ["4764a"] = { common = "Высоко в горах, на пике Чёрной горы, есть чертог, который некогда звался Залом Сокровищ. Именно там дворфы Чёрного Железа хранили свои реликвии, трофеи и предметы искусства. Это было давно. Говорят, что зал обрушился, и теперь используется… менее достойно. Но я думаю, что там остались дворфийские реликвии. Одна из них — пряжка Роковой оснастки. Её поверхность так плотно инкрустирована редкими самоцветами, что любой дворф начинает плакать от одного её вида. Именно эта пряжка и станет твоей целью, путник." },
    ["4764c"] = { common = "Ты нашёл её! Значит, слухи оказались правдой! Спасибо, путник. Мой клиент, граф Ремингтон Риджвелл, с радостью поместит её в свою коллекцию." },
    ["4765a"] = { common = "Я упаковала пряжку Роковой оснастки в ящик для отправки в Штормград. Путник, ты мне очень помог, но я хочу попросить ещё об одной услуге. Доставь этот ящик графу Ремингтону Риджвеллу. Он в Крепости Ветров. Не сомневаюсь, он обрадуется." },
    ["4765c"] = { common = "А, так это ты! Спасибо, путник. И… если ты ещё не знаешь об этом… благодарность дома Риджвеллов стоит королевской." },
    ["4766a"] = { common = "Мой агент, Майра, отправилась в Пылающие степи, чтобы обыскать развалины города Тауриссана. В разрушенном обиталище дворфов Чёрного Железа таится множество ценных вещей… которые украсят наш семейный музей. Майра говорит, что кое-что нашла, но ей нужна помощь. Правда, это находится не в Тауриссане. Вместо этого требуется устроить вылазку на пик Чёрной горы. Подробности мне неизвестны, но если тебя заинтересовало моё предложение, поговори с Майрой в Пылающих степях." },
    ["4766c"] = { common = "Ты из Штормграда? Чудесно — я знаю об одном предмете искусства, который Ремингтон любой ценой захочет заполучить в свой музей. Но это будет нелегко. Тут-то ты и понадобишься." },
    ["4767a"] = { common = "Мне велели набрать новых виверн, чтобы выдрессировать их и использовать в качестве ездовых животных. Их поголовье постоянно растёт, и я надеюсь, что когда-нибудь сам смогу стать воздушным всадником. Однако виверны пользуются большим спросом, и нам их постоянно не хватает. Может быть, вы, сможете мне помочь? Я хочу попросить вас отправиться в Скальное гнездовье и набрать с кладок виверн немного яиц. Отсюда ступайте на северо-запад, держитесь поближе к стене каньона – и увидите дорогу, ведущую наверх. Но будьте очень осторожны: виверны не любят чужаков, а уж за свои кладки они будут готовы разорвать кого угодно." },
    ["4767c"] = { male = "Отлично! Детёныши из этих яиц помогут мне осуществить задуманное! Возьмите это в знак моей признательности, пусть вам всегда везёт на любой охоте, герой.", female = "Отлично! Детёныши из этих яиц помогут мне осуществить задуманное! Возьмите это в знак моей признательности, пусть вам всегда везёт на любой охоте, героиня." },
    ["4768a"] = { common = "Табличка Тёмного Камня — это записки покойного дворфа Урхельда Тёмного Камня. Он был величайшим алхимиком древности, но современники считали его сумасшедшим и не придавали значения его изысканиям. Известно, что он записал результаты своих трудов. Вырезал их на табличках. И у меня есть основания предполагать, что одна из этих табличек хранится в Пике Чёрной горы, в зале, который когда-то назывался залом Удачи. Как его называют сейчас, я не знаю, ибо многие уходили в Чёрную Скалу, но немногие вернулись назад. Если тебя не пугают опасности Пика Чёрной горы, принеси мне табличку, и я щедро тебя награжу." },
    ["4768c"] = { common = "Прекрасно. Формулы на этой табличке потребуют времени на расшифровку, но я уверена, что оно себя оправдает. Спасибо тебе, путник. Ты сделал неоценимый вклад в наши исследования." },
    ["4769a"] = { common = "Вивиана Лягроб прислала мне весть из Каргата, что в Бесплодных землях. Она выяснила, что в Пике Чёрной горы хранится один древний текст, который может помочь нам в изысканиях. Однако это всего лишь догадка, требующая подтверждения. Нужно, чтобы кто-то добыл этот текст из Пика. Но сразу скажу: это будет непросто. Если возьмёшься за эту работу, обратись к Вивиане в Каргат." },
    ["4769c"] = { common = "Верно. У меня есть основания предполагать, что в Пике Чёрной горы хранится табличка, на которой записаны древние алхимические рецептуры. Я рада, что ты обратился ко мне, ибо мне нужна помощь. Я должна получить эту табличку. Садись и устраивайся поудобнее, я сейчас объясню, что к чему." },
    ["4770a"] = { male = "Пожалуйста, герой, помогите мне! Я уже несколько дней прячусь в этом Скальном гнездовье, и за это время не встретил ни одного знакомого лица! Я пришёл сюда изучать виверн и, похоже, немного переборщил – пришлось спасаться от них бегством, вот тогда-то я и заблудился. Мне срочно нужно вернуться на заставу Белого Плёса! Мотега не знает, что я потерялся, а когда узнает, что я полез в Скальное гнездовье один, он мне голову оторвёт! Застава прямо к востоку отсюда... пожалуйста, проводите меня туда!", female = "Пожалуйста, героиня, помогите мне! Я уже несколько дней прячусь в этом Скальном гнездовье, и за это время не встретил ни одного знакомого лица! Я пришёл сюда изучать виверн и, похоже, немного переборщил – пришлось спасаться от них бегством, вот тогда-то я и заблудился. Мне срочно нужно вернуться на заставу Белого Плёса! Мотега не знает, что я потерялся, а когда узнает, что я полез в Скальное гнездовье один, он мне голову оторвёт! Застава прямо к востоку отсюда... пожалуйста, проводите меня туда!" },
    ["4770c"] = { common = "Что?! Да если б я знал, что Паока Ходячая Гора полезет в Скальное гнездовье, я бы цепями приковал его к тотэму! Его отец был против того, чтобы он ехал со мной в Тысячу Игл. Мы собирались изучать различных животных, населяющих эти прекрасные земли. Я очень признателен вам за то, что вы помогли Паоке. Надеюсь, это покроет все ваши затраты." },
    ["4771a"] = { common = "Я поместила \"Рассветный гамбит\" в ящик, в котором были драконьи яйца. Ты должен отнести его в самую глубину Некроситета. Вектус, маг из нежити, руководит группой студентов Плети. Доставь \"Рассветный гамбит\" в комнату, которую они называют смотровой. Если всё пойдёт как надо, устройство уничтожит всю нежить, находящуюся в этот момент в комнате. После этого уничтожить Вектуса будет проще пареной репы. Так ведь?" },
    ["4771c"] = { common = "Великолепно, путник! Годы тщательной разведки пошли ко всем чертям! Алый Орден почувствует этот удар на себе в ближайшие недели!" },
    ["4781a"] = { common = "Следующее задание не сложнее первого, но тебе всё равно потребуется помощь. Для вышивки мне нужна золотая нить, но её не так просто найти, и мало кто знает, как её делать. К счастью, этот секрет ведом одному из тех, кто верен нашему делу и старается помогать тем, кто стремится пополнить наши ряды. Отнеси золотой слиток Зиску Ладноскрою в Пиратскую бухту. Он отличный портной и с радостью спрядёт для тебя нить. Золотые слитки могут изготавливать опытные горняки. Обратись к ним." },
    ["4781c"] = { male = "Великолепно. Я рад, что ты сумел так быстро заручиться помощью горняка. Или ты сам справился? Так или иначе, молодчина. Нить из этого слитка выйдет превосходная. На её изготовление понадобится время, поэтому возвращайся немного позже – честно говоря, я послал слиток одной принцессе, запертой в башне, которая только и делает, что прядёт золотые нити... нет, честно. Я не шучу... ладно, шучу.", female = "Великолепно. Я рад, что ты сумела так быстро заручиться помощью горняка. Или ты сама справилась? Так или иначе, молодчина. Нить из этого слитка выйдет превосходная. На её изготовление понадобится время, поэтому возвращайся немного позже – честно говоря, я послал слиток одной принцессе, запертой в башне, которая только и делает, что прядёт золотые нити... нет, честно. Я не шучу... ладно, шучу." },
    ["4782a"] = { common = "Возвращайся к Менаре и скажи ей, что работа предстоит долгая, но я постараюсь ради неё... и ради тебя. Передай ей, что пока ты собираешь остальные материалы, я закончу делать нить. Тогда ты придёшь и заберёшь её. Удачи. Ах, да, передай привет Страхаду, раз уж будешь рядом. Старый болван... как его угораздило построить башню рядом с Кабестаном?" },
    ["4782c"] = { male = "Отлично, вот и ты. А где же нитка? А, ясно. Понятно. Гоблин и его брат ни разу нас не подводили – думаю, вполне понятно, что он не смог сделать её сразу. Да будет так... Тем временем мы займёмся другими материалами. Ты готов?", female = "Отлично, вот и ты. А где же нитка? А, ясно. Понятно. Гоблин и его брат ни разу нас не подводили – думаю, вполне понятно, что он не смог сделать её сразу. Да будет так... Тем временем мы займёмся другими материалами. Ты готова?" },
    ["4783a"] = { common = "Следующие материалы можно найти в Пустошах, далеко на западе от Степей, за Когтистыми горами. Там всё ещё царит хаос со времён Раскола. Это место, где предстоит серьёзное испытание твоей силе и хитрости – там бродят омерзительные твари и приспешники Пылающего Легиона. Принеси мне кровь сатиров племени Ярой Ненависти и простой камень Преисподней от младших инферналов Поля Маннорок. И то, и другое понадобится для создания одеяния." },
    ["4783c"] = { common = "Великолепно. Отличные материалы. Я пока подготовлю их, а тебе дам другое задание: принести два оставшихся ингредиента. Готов?" },
    ["4784a"] = { common = "Осталось отыскать три составляющих, и твоё одеяние будет готово. Во-первых, нить из чистого золота, которую делает Зиск. Отправляйся к нему в Пиратскую бухту и принеси нить. Во-вторых, нужны тлеющие угли элементалей огня с нагорья Арати. Если я правильно помню, духов можно найти в западной части нагорья, рядом со стеной Торадина. И, наконец, мне нужен осколок души, созданный тобой. Собрав все составляющие, возвращайся в башню, и я закончу работу над одеянием." },
    ["4784c"] = { common = "Великолепно! Все материалы у меня есть, можно приступать. Думаю, ты будешь доволен." },
    ["4786a"] = { common = "А теперь я завершу работу над одеянием. Это займёт немного времени. Не уходи далеко." },
    ["4786c"] = { male = "Готово. Прими это одеяние и носи его с честью. Ты хорошо поработал, и я предвижу, что тебя ждут великие дела. Помни: чтобы справиться с искушением скверны, которое подстерегает каждого, ступившего на путь магии, понадобится сильная воля и немалая стойкость. Пока ты не лишился воли, тебя ждут великие успехи.", female = "Готово. Прими это одеяние и носи его с честью. Ты хорошо поработала, и я предвижу, что тебя ждут великие дела. Помни: чтобы справиться с искушением скверны, которое подстерегает каждого, ступившего на путь магии, понадобится сильная воля и немалая стойкость. Пока ты не лишилась воли, тебя ждут великие успехи." },
    ["4787a"] = { common = "В пророчестве Мошару говорится о древнем яйце. Это реликвия тех времён, когда тролли правили громадными империями, и в нём заключена сила, которая сможет сдержать сущность Хаккара. Пожалуй, это единственный способ избавить наш мир от зла. Принеси мне древнее яйцо. Говорят, оно спрятано в Джинта'Алоре, что во Внутренних землях, в пещере за амфитеатром в верхней части города." },
    ["4787c"] = { male = "А, ты добыл яйцо! Низкий тебе поклон. Твоя сила и храбрость будут воспеты в веках.", female = "А, ты добыла яйцо! Низкий тебе поклон. Твоя сила и храбрость будут воспеты в веках." },
    ["4788a"] = { common = "Пока я изучаю третью и четвёртую таблички Мошару, отыщи пятую и шестую! Это будет нелегко, потому что они в руках троллей из клана Тлеющего Терновника на пике Чёрной горы. Этот пик — огненная гора между Пылающими степями и Тлеющим ущельем. Удачи, путник. Она тебе понадобится." },
    ["4788c"] = { common = "Невероятно! Ты нашёл их! Ты, в самом деле, герой, путник! Это превосходно, я как раз заканчиваю прочтение предыдущих табличек." },
    ["4808a"] = { common = "Мне придётся попросить тебя ещё об одной услуге. В результате исследования добытых тобой сущностей, я поняла, как можно заморозить яйца драконов и сохранить их! Мне нужно испытать собственную теорию, но первым делом понадобятся кое-какие приспособления. Мой коллега, Фелнок Сталлист, умеет их делать. Отнеси это письмо Фелноку и объясни ему, что мне нужно. Фелнок живёт в городе Круговзоре, в Зимних Ключах." },
    ["4808c"] = { common = "Это не одеяло! Что это? Письмо от Тинки? И что она пишет?… А, она занимается исследованиями в Пылающих степях. В этом есть смысл — драконов там полно. Смотри-ка, ей нужны кое-какие детали для создания одного устройства. Вот зачем я ей понадобился, а?" },
    ["4809a"] = { common = "У меня есть почти всё, что нужно Тинки, не хватает только одного важного компонента — рогов стылодыхов. Рога этих химер — великолепный источник стужи, но годятся только безупречные рога без единой трещинки! Чтобы выполнить заказ Тинки мне нужно несколько таких рогов. Добудь их, и я соберу посылку для Тинки." },
    ["4809c"] = { common = "О-о, это прекрасные образцы. От них так и веет холодом, так я, пожалуй, надену перчатки, а то ещё обморожу руки, когда буду их упаковывать…" },
    ["4810a"] = { common = "Ну вот, всё готово и запаковано! Доброго пути, не забудь передать Тинки, что она мой должник!" },
    ["4810c"] = { common = "Ты принёс их! Отлично! Я сейчас же принимаюсь за работу! Огромнейшее спасибо, путник! Ты так мне помог, я думаю, что ты ещё пригодишься мне в будущем…" },
    ["4811a"] = { common = "К востоку отсюда становится всё больше враждебно настроенных лунных совухов. Когда-то их считали милыми и спокойными, почти мистическими созданиями. В то время как кое-кто продолжает почитать их, тревога о безопасности Аубердина вынуждает меня смотреть на вещи более реалистично. Я получила сообщения, что лунных совухов привлекает большой красный кристалл, находящийся в горной гряде на востоке Тёмного Берега. Никто не только не знает, что это за кристалл, но есть ли он на самом деле. Я хочу, чтобы вы установили его местонахождение и доложили мне о том, что обнаружите." },
    ["4811c"] = { common = "Так значит, кристалл существует? Как интересно... В любом случае, вы хорошо справились с заданием. Отличная работа! А какова же природа этого кристалла? Это лишь один вопрос в целом море вопросов... На ум мне приходит и другой: почему лунных совухов тянет к кристаллу? Он безвреден, или же таит в себе зло? У меня ещё много вопросов, но нам придётся пристально изучить кристалл, чтобы добиться хоть каких-то ответов." },
    ["4812a"] = { common = "Возьмите этот пустой флакон и наполните его водой из лунного колодца в Аубердине. Её могучая магия должна помочь нам разгадать структуру кристалла. Чтобы это сделать, просто облейте кристалл, а остальное должно произойти само собой. Хотя я не думаю, чтобы вам что-то угрожало, я всё же попрошу вас быть осторожнее. За горами на востоке находится Осквернённый лес, и если этот кристал как-то связан с тем местом (как я подозреваю), он может оказаться очень опасным." },
    ["4812c"] = { common = "Вы снова добрались до таинственного кристалла. Откупорив флакон с водой лунного колодца, вы аккуратно выливаете его содержимое на верхушку кристалла. Пока вода струится по его граням, вы видите, как непроглядная поверхность кристалла становится прозрачной..." },
    ["4813a"] = { common = "С помощью воды Лунного колодца выяснилось, что в кристалле заключено несколько мелких фрагментов костей, а также половина челюсти. Кажется, челюсть принадлежала гуманоиду, но точно нельзя сказать, не разбив кристалл, – а это даже для самой мощной магии может оказаться почти непосильной задачей. Задание выполнено, и всё, что вам остаётся, – это вернуться в Аубердин и доложить обо-всём часовому Глинде Нал'Шие." },
    ["4813c"] = { common = "Да, похоже, что, хотя мы и знаем теперь о кристалле больше, в результате возникло множество новых вопросов. Я пойду с добытой вами информацией в совет Аубердина. Может быть, они подскажут, что делать дальше с этим кристаллом. Если вообще есть о чём говорить – пока что угроза слишком далеко на востоке, чтобы принимать её всерьёз. Что же касается вас, возьмите это. Считайте это наградой за хорошо проделанную работу." },
    ["4821a"] = { common = "Ходят слухи, что здесь, в Тысяче Игл, появилось яйцо какого-то странного существа. Но те, кто видел его, не смогли подойти достаточно близко и рассмотреть яйцо поподробнее. Его охраняют змеи, да так, словно это яйцо – их собственное! Я хочу, чтобы вы нашли его и принесли мне для изучения. Говорят, что оно находится в логове змеев, но вообще-то таких гнёзд несколько, они разбросаны вдоль стен каньона к югу и северо-востоку от заставы." },
    ["4821c"] = { common = "Наконец-то я получил это таинственное яйцо... Дайте-ка взглянуть на него... Что... что это?!" },
    ["4841a"] = { common = "Я поручаю вам охоту на этих кентавров. Отомстите им за нас как следует – вырежьте весь их лагерь к северу от Заставы Вольного Ветра. Пусть рука ваша будет тверда!" },
    ["4841c"] = { common = "Примите это в благодарность от меня." },
    ["4842a"] = { common = "По правде говоря, хотя в Зимних Ключах вулканов нет, я думаю, для возникновения этих горячих источников есть не менее опасные причины… Впрочем, наверное, ты сам захочешь всё увидеть. Тебе нужно будет пересечь все Зимние Ключи, до самого юга этого края. Там, где воздух станет плотным и удушливым, а небо потемнеет, ты как раз и найдёшь то, что я считаю причиной возникновения горячих ключей. Сходи взглянуть. Я уверена, ты вернёшься с кучей вопросов." },
    ["4842c"] = { common = "Да, демоны там, в Теснине Зловещего Шёпота. Я полагаю что это их присутствие так влияет на эти земли. Я продолжу следить за горячими источниками и посмотрю, удастся ли мне выяснить что-то ещё. Я подожду пока ты станешь сильнее, прежде чем дать тебе поручение в Теснине Зловещего Шёпота." },
    ["4861a"] = { male = "Эй, послушай, паренёк! Меня какие-то кровожадные дикосовухи гнали всю дорогу из моего лагеря! Подозреваю, я слишком близко подобрался к разгадке того, что же они там охраняют. Я еле ноги унёс оттуда. Боюсь, мой коллега оказался менее везучим. Ты как, не против того, чтобы бросить вызов дикосовухам и отправиться в мой лагерь? Мне очень нужны мои припасы, а также я хотел бы вернуть амулет, который извлёк вчера во время раскопок.", female = "Эй, послушай, девчушка! Меня какие-то кровожадные дикосовухи гнали всю дорогу из моего лагеря! Подозреваю, я слишком близко подобрался к разгадке того, что же они там охраняют. Я еле ноги унёс оттуда. Боюсь, мой коллега оказался менее везучим. Ты как, не против того, чтобы бросить вызов дикосовухам и отправиться в мой лагерь? Мне очень нужны мои припасы, а также я хотел бы вернуть амулет, который извлёк вчера во время раскопок." },
    ["4861c"] = { common = "Среди разрушенных пожитков в лагере находится и сильно потрёпанный ящик." },
    ["4862a"] = { common = "Верь — не верь, но есть народ, который готов отлично заплатить за необычную зверушку, причём чем она злее, тем лучше! Я послал на пик Чёрной горы Блестяшку, чтобы собрать паучьи яйца, но она уже несколько недель не возвращается. Может, ты придёшь ей на выручку? Вот что, путник. Ступай-ка туда и принеси мне паучьи яйца. Я тебе не только хорошо заплачу, но ещё и приручу для тебя одного паучка!" },
    ["4862c"] = { common = "Какой урожай! Что за яйца! Они принесут мне несколько хорошеньких золотых монеток. Как и обещано, вот тебе зверушка. Смотри, чтобы она тебя не цапнула!" },
    ["4863a"] = { common = "Вы озираетесь, но не видите ничего такого, чтобы могло понадобиться Джерону. Однако, заметно, что найденный вами ящик был вскрыт силой, как будто тут побывали дикосовухи… Взглянув на восток, вы замечаете покинутый фургон. Стоит посмотреть не осталось ли там каких-то вещей Джерона." },
    ["4863c"] = { common = "Подойдя к фургону, вы думаете о том, что едва ли внутри осталось что-то полезное для Джерона. Однако, приглядевшись, вы замечаете в снегу возле фургона пару ящиков, которые выглядят неповреждёнными." },
    ["4864a"] = { common = "Изучив содержимое ящика, вы решаете, что Джерону могут пригодиться лежащие там инструменты. Однако среди них нет и следа амулета. Похоже, дикосовухи обитают к северу и к востоку отсюда, и вы решаете, что ваш следующий шаг — встретить этих существ лицом к лицу и забрать у них амулет." },
    ["4864c"] = { common = "Ну, примерно это я и ожидал услышать, путник. Я уж было думал, что свихнувшиеся звери раздраконили все мои пожитки… Но тебе удалось найти мои инструменты и, что ещё важнее, амулет! Интересно, почему дикосовухи так яростно его защищали… В любом случае, я теперь дважды подумаю, прежде чем сунуться к ним опять!" },
    ["4865a"] = { common = "Если бы я не видел это собственными глазами, то ни за что бы не поверил! Месть обрушилась на Тысячу Игл! *Хагар утирает лоб.* Надо действовать быстро! Скорее, иди и поговори с Мотегой Огненной Гривой, он на заставе Белого Плёса, это к северо-западу отсюда, прямо возле дороги. Он подскажет нам, что делать!" },
    ["4865c"] = { common = "Отмщение! Значит, легенда об Арикаре не врёт! Да, эту проблему следует разрешить немедленно." },
    ["4866a"] = { common = "Должно быть, это один из сильнейших ядов на свете! В одной из вылазок на пик Чёрной горы, я слышал, как орки говорят о его смертоносности. Они называют его \"материнское молоко\" в честь Дымной Паутины, огромной паучихи, поселившейся в одной из пещер Лабиринта. Вот что мне нужно от тебя: образец молока в твоих собственных венах. Мешочка с ядом не пойдёт! Дай ей отравить тебя, а потом возвращайся! А я тебя… подою!" },
    ["4866c"] = { common = "Это, наверное, самый лучший эль! Как ты думаешь, что я использовал? Яд или что-то ещё? Безумные дети…" },
    ["4881a"] = { common = "Таурен по имени Канати Серое Облако собрался разбить в Тысяче Игл охотничий лагерь. Мы должны убить его и опустошить лагерь, уничтожив всех его сторонников. Собираемся на маленькой заставе к юго-западу от Великого подъёмника." },
    ["4881c"] = { common = "Они хотят меня убить? Пусть приходят, я покажу им, как дерутся таурены!" },
    ["4882a"] = { common = "Вы не можете понять, важна ли ваша находка — ожерелье, упавшее с шеи недавно убитого дикосовуха. Оно источает яркий пульсирующий свет. Может быть, Трулл Баловень Судьбы сможет что-то рассказать — похоже, он очень много знает о дикосовухах. Возможно, стоит его расспросить об этом ожерелье?" },
    ["4882c"] = { common = "У тебя важная находка?" },
    ["4883a"] = { common = "Хотя я располагаю некоторыми сведениями о совухах, с которыми ты боролся в Зимних Ключах, однако об их магии мне ничего не известно. Но я знаю кое-кого, кто с удовольствием изучит это ожерелье и скорее всего сумеет рассказать тебе о его свойствах. Нара Буйногривая из Громового Утёса настоящий эксперт в подобных вещах, тебе стоит поговорить с ней. Удачи, путник!" },
    ["4883c"] = { common = "Это ожерелье может черпать силу лишь из одного источника, путник. Дикие совухи, в настоящее время, сбились с истинного пути. Раньше это было не так. Раньше у них было особое предназначение. Богиня Элуна создала их для того, чтобы они оберегали её священные места. Это может показаться тебе незначительным, но я настоятельно прошу тебя приглядеться получше. Со временем ты многое поймёшь. Спасибо, что принёс ожерелье ко мне, путник." },
    ["4901a"] = { common = "На самой вершине гребня находится, как я полагаю, алтарь богини Элуны. Насколько я знаю, нам нужно зажечь пять факелов — в каждой пещере, и тогда мы получим доступ к алтарю. Я расшифровала заклинания, вырезанные на камне в древних руинах Кел'Терила, которые, как я думаю, являются ключом к активации алтаря. Помогите мне зажечь факелы, пока я буду читать заклинание. Если у нас всё получится, вы сможете доложить Эреласу о результатах!" },
    ["4901c"] = { common = "Ты встретился с Раншаллой?" },
    ["4902a"] = { common = "Это поразительно! Мне всегда было интересно, какова же истина… Что ж, вы просто обязаны поделиться этими сведениями! Сразу же отправляйтесь к верховному друиду Фэндралу Оленьему Шлему — вы найдёте его в Дарнассе, в Круге Кенария. Расскажите ему подробно о случившемся — так же, как рассказали мне. Я уверен, что ему будет очень интересно! Это важная информация, путник!" },
    ["4902c"] = { common = "Отдышись, а теперь расскажи мне, зачем пришёл. Да? Вот как? О-о-о… Ну хорошо. Спасибо, что принёс известие так быстро. Друиды Круга Кенария знают о диких совухах уже довольно длительное время. Они были выбраны Элуной, чтобы охранять наиболее священные места. Ну, не смею тебя более задерживать. И вот, возьми это. Смею надеяться, что это будет достаточной наградой за твои усилия." },
    ["4903a"] = { common = "По приказу полководца Клинозуба следующие жители Пика Чёрной горы подлежат уничтожению: Особо опасный преступник вождь Омокк. Жестокий и беспощадный тролль воевода Вун. Повелитель Змейталак, десятник в малом городе. Также необходимо доставить в штаб все найденные при них документы. Успех — слава и награда. Поражение — позор и забвенье." },
    ["4904a"] = { common = "Арнак хотел жениться на мне, и поэтому похитил меня, когда я отвергла его предложение. Мой брат пытался остановить его, но Арнак оказался сильнее. Он... он убил моего брата и привёл меня сюда. Мой бедный брат... Не могли бы вы вывести меня с Пика Тёмного Облака? Я хочу назад, к Талье! Она, наверное, с ума сходит от беспокойства." },
    ["4904c"] = { common = "Спасибо. В глубине души я всегда верила, что она найдёт способ вернуться ко мне. Она рассказала мне о вашей храбрости и о том, как вы помогли ей сбежать. Эти вещи принадлежали её брату. Уверена, она бы сама непременно отдала их вам." },
    ["4906a"] = { common = "Другой лагерь сатиров угрожает северной части Осквернённого леса. Тамошними сатирами предводительствует жестокий Ксаварик. Эти подлые предатели и обманщики радуются, поражая порчей тварей Осквернённого леса. Ксаватрас и его приспешники — только часть большого плана по созданию осквернённого лунного колодца. А затем всем этим воспользуется Ксаварик. Теперь, когда Ксаватрас уже не мешается у нас под ногами, заверши это дело, путник. Отправляйся на север и срази Ксаварика." },
    ["4906c"] = { common = "Спасибо, путник. Да благословит тебя Элуна, за всё то, что ты сделал." },
    ["4907a"] = { common = "Привет, путник. Помнишь Тинки Кипеллер? Она-то тебя помнит! Она послала мне весточку, чтобы я передал тебе при случае. Ей снова нужна твоя помощь. Кажется, это опять связано с изучением драконов. Ступай в Пылающие степи, в Пламенеющий Стяг, и поговори с ней." },
    ["4907c"] = { common = "Фелнок был прав! Мне опять нужна твоя помощь и в этот раз поручение будет опасным. Ты готов?" },
    ["4921a"] = { male = "Мы бились в маленьком лагере тауренов и разделились в бою – на неё наседали разом три иглогрива Вздыбленной Щетины. Силы были неравны. Я отвлёк на себя очень многих и увидел, что набежали новые враги и одолевают её. Впав в ярость, я бросился на врагов, но они с лёгкостью одержали надо-мной верх. Я пришёл в себя и увидел, что таурен-друид ухаживает за мной, – он набрёл на меня на Золотом пути. Прошу тебя, герой, узнай что-нибудь о моей жене.", female = "Мы бились в маленьком лагере тауренов и разделились в бою – на неё наседали разом три иглогрива Вздыбленной Щетины. Силы были неравны. Я отвлёк на себя очень многих и увидел, что набежали новые враги и одолевают её. Впав в ярость, я бросился на врагов, но они с лёгкостью одержали надо-мной верх. Я пришёл в себя и увидел, что таурен-друид ухаживает за мной, – он набрёл на меня на Золотом пути. Прошу тебя, героиня, узнай что-нибудь о моей жене." },
    ["4921c"] = { male = "Понятно. Спасибо, герой.", female = "Понятно. Спасибо, героиня." },
    ["4941a"] = { common = "Ренд жив? Быть того не может! Я думал, он погиб несколько десятков лет назад. Тебе нужно обратиться за советом к Эйтриггу, путник! Никто не знает о Чёрной горе больше него, и если то, что написано здесь, правда, Эйтриггу стоит об этом знать. Никому нельзя отказывать в праве на месть. Когда поговоришь с Эйтриггом, ступай к вождю за указаниями." },
    ["4961a"] = { common = "А, сфера призывателя – так вот откуда исходит искажение. Если ты хочешь ей пользоваться, придётся изгнать из неё демона. С этим я легко справлюсь. Тебе придётся куда труднее. Как только демон выйдет из сферы, убей его. И спеши. Если ты будешь возиться слишком долго, он вернётся в сферу, и нам придётся начать сначала! Подготовься к схватке. Вспомни самые сильные заклинания и держи под рукой зелья. Если у тебя есть друг, можешь позвать его. Сражение будет нелёгким." },
    ["4961c"] = { male = "Великолепно. Тебе удалось преподать этому демону урок, который он надолго запомнит. Могущества и умения тебе не занимать. Полагаю, пришло время вернуться к Менаре с очищенным шаром и найти ему доброе применение. Удачи, герой. Быть может, наши пути ещё пересекутся.", female = "Великолепно. Тебе удалось преподать этому демону урок, который он надолго запомнит. Могущества и умения тебе не занимать. Полагаю, пришло время вернуться к Менаре с очищенным шаром и найти ему доброе применение. Удачи, героиня. Быть может, наши пути ещё пересекутся." },
    ["4962a"] = { male = "Итак, ты выбрал гончую скверны. Отлично. Возьми этот рубин, он позволит подчинить её душу. Делай, как обычно: когда тварь окажется на пороге смерти, воспользуйся камнем, и он всё сделает за тебя. Советую отправиться в Пустоши и попробовать подчинить одну из тамошних гончих скверны. Они отлично подойдут. Когда добьёшься успеха, отнеси пленённого духа и рубин Менаре.", female = "Итак, ты выбрала гончую скверны. Отлично. Возьми этот рубин, он позволит подчинить её душу. Делай, как обычно: когда тварь окажется на пороге смерти, воспользуйся камнем, и он всё сделает за тебя. Советую отправиться в Пустоши и попробовать подчинить одну из тамошних гончих скверны. Они отлично подойдут. Когда добьёшься успеха, отнеси пленённого духа и рубин Менаре." },
    ["4962c"] = { common = "А, дух гончей скверны. Молодец;. Когда у меня будет и дух, и очищенная сфера, я смогу слить их воедино, но не раньше." },
    ["4963a"] = { male = "Итак, ты выбрал инфернала. Отлично. Возьми этот изумруд, он позволит подчинить его душу. Делай, как обычно: когда тварь окажется на пороге смерти, воспользуйся камнем, и он всё сделает за тебя. Советую отправиться в Пустоши и попробовать подчинить одного из инферналов. Они отлично подойдут. Когда добьёшься успеха, отнеси пленённого духа и изумруд Менаре.", female = "Итак, ты выбрала инфернала. Отлично. Возьми этот изумруд, он позволит подчинить его душу. Делай, как обычно: когда тварь окажется на пороге смерти, воспользуйся камнем, и он всё сделает за тебя. Советую отправиться в Пустоши и попробовать подчинить одного из инферналов. Они отлично подойдут. Когда добьёшься успеха, отнеси пленённого духа и изумруд Менаре." },
    ["4963c"] = { common = "Аа, дух инфернала... Прекрасно сработано. Когда у меня будут и дух, и очищенное сферическое ядро, я объединю их для тебя. Но не раньше." },
    ["4964a"] = { common = "Я немедленно займусь твоим шаром. Надо вселить в него нового демона. После этого у меня будет выбор: превратить его в сферу или в посох. Я всегда считала, что соответствие избранному оружию чернокнижника – это главное... Не вижу причин менять своё мнение." },
    ["4964c"] = { common = "Готово. А теперь скажи, что ты предпочитаешь,: посох, который займёт обе руки, или шар, который позволит тебе пользоваться кинжалом или мечом. Сражение с огненным големом – суровое испытание. Нет сомнений, что этот предмет славно послужит тебе в будущем. Прилежно изучай тайные искусства. Я буду ждать вестей о твоих подвигах." },
    ["4965a"] = { male = "Так-так-так… приятно видеть, как ты набираешься могущества. Мне кажется, ты готов поговорить с Менарой Расщепительницей Бездны в Степях. Если вы раньше не встречались, то, поверь мне, другого такого специалиста по созданию предметов – особенно сфер, в которые можно заключить демона – не найти. Интересно? Тогда поищи её. Она живёт в башне Страхада над Кабестаном.", female = "Так-так-так… приятно видеть, как ты набираешься могущества. Мне кажется, ты готова поговорить с Менарой Расщепительницей Бездны в Степях. Если вы раньше не встречались, то, поверь мне, другого такого специалиста по созданию предметов – особенно сфер, в которые можно заключить демона – не найти. Интересно? Тогда поищи её. Она живёт в башне Страхада над Кабестаном." },
    ["4965c"] = { male = "А, ты ищешь чего-то более... вещественного. Я помогу тебе, если хочешь. Приятно видеть, что не все наши сородичи стремятся к одним лишь знаниям. Итак, думаешь, ты готов?", female = "А, ты ищешь чего-то более... вещественного. Я помогу тебе, если хочешь. Приятно видеть, что не все наши сородичи стремятся к одним лишь знаниям. Итак, думаешь, ты готова?" },
    ["4966a"] = { common = "Кентавров намного больше, чем я думал. Пожалуйста, помогите мне отбиться от них." },
    ["4966c"] = { common = "Спасибо за помощь. Без тебя я бы ни за что не справился." },
    ["4967a"] = { male = "Ты так и не поумнел и по-прежнему стремишься в западню. Да, говорю я дерзко. Я смотрю на тебя и смеюсь. Ты жалкий червь! Но моё мнение не имеет значения. Главное, что думают те, кто желает иметь с тобой дело! И в данном случае наделённые силой полагают, что ты заслуживаешь большего. Если ты к чему-то стремишься, поговори с Менарой Расщепительницей Бездны в башне над Кабестаном. Кажется, ты с ней уже встречался.", female = "Ты так и не поумнела и по-прежнему стремишься в западню. Да, говорю я дерзко. Я смотрю на тебя и смеюсь. Ты жалкий червь! Но моё мнение не имеет значения. Главное, что думают те, кто желает иметь с тобой дело! И в данном случае наделённые силой полагают, что ты заслуживаешь большего. Если ты к чему-то стремишься, поговори с Менарой Расщепительницей Бездны в башне над Кабестаном. Кажется, ты с ней уже встречалась." },
    ["4967c"] = { male = "А, ты ищешь чего-то более... вещественного. Я помогу тебе, если хочешь. Приятно видеть, что не все наши сородичи стремятся к одним лишь знаниям. Итак, думаешь, ты готов?", female = "А, ты ищешь чего-то более... вещественного. Я помогу тебе, если хочешь. Приятно видеть, что не все наши сородичи стремятся к одним лишь знаниям. Итак, думаешь, ты готова?" },
    ["4968a"] = { male = "Хм-м... Тебе удалось добиться немалого... Поразительно. Я думала, что ты давно сошёл с ума, раздираемый скверной магией, просочившейся в твою душу. Тогда, пожалуй, двинемся дальше? Если ты хочешь испытать своё искусство, отыщи Менару Расщепительницу Бездны в башне Страхада над Кабестаном. Она поможет тебе сделать следующий шаг.", female = "Хм-м... Тебе удалось добиться немалого... Поразительно. Я думала, что ты давно сошла с ума, раздираемая скверной магией, просочившейся в твою душу. Тогда, пожалуй, двинемся дальше? Если ты хочешь испытать своё искусство, отыщи Менару Расщепительницу Бездны в башне Страхада над Кабестаном. Она поможет тебе сделать следующий шаг." },
    ["4968c"] = { male = "А, ты ищешь чего-то более... вещественного. Я помогу тебе, если хочешь. Приятно видеть, что не все наши сородичи стремятся к одним лишь знаниям. Итак, думаешь, ты готов?", female = "А, ты ищешь чего-то более... вещественного. Я помогу тебе, если хочешь. Приятно видеть, что не все наши сородичи стремятся к одним лишь знаниям. Итак, думаешь, ты готова?" },
    ["4969a"] = { male = "Ха-ха! Ты растёшь над собой, юный герой. Со временем инферналы и повелители ужаса склонятся перед тобой! Пока же тебе приходится полагаться на оружие, скованное руками смертных. Похоже, ты готов создать ещё одно. Если хочешь, с тобой может поговорить Менара Расщепительница Бездны! Она живёт неподалёку от башни Страхада над портовым городом Кабестан. Отправляйся туда, как решишь, что время уже пришло.", female = "Ха-ха! Ты растёшь над собой, юная героиня. Со временем инферналы и повелители ужаса склонятся перед тобой! Пока же тебе приходится полагаться на оружие, скованное руками смертных. Похоже, ты готова создать ещё одно. Если хочешь, с тобой может поговорить Менара Расщепительница Бездны! Она живёт неподалёку от башни Страхада над портовым городом Кабестан. Отправляйся туда, как решишь, что время уже пришло." },
    ["4969c"] = { male = "А, ты ищешь чего-то более... вещественного. Я помогу тебе, если хочешь. Приятно видеть, что не все наши сородичи стремятся к одним лишь знаниям. Итак, думаешь, ты готов?", female = "А, ты ищешь чего-то более... вещественного. Я помогу тебе, если хочешь. Приятно видеть, что не все наши сородичи стремятся к одним лишь знаниям. Итак, думаешь, ты готова?" },
    ["4971a"] = { common = "Кто-то вмешался в ход времени в Андорале! Скорее всего, это дело рук Плети. Я могу попытаться сохранить неизменным ход времени здесь и исправить повреждения, но мне не должны мешать. В этом ты мне и поможешь. В Андорале поселились временные паразиты, падальщики, питающиеся обрывками потока времени. Их можно обнаружить только по синему сиянию. Они очень мешают мне. Пожалуйста, путник, искорени этих паразитов, воспользовавшись временным переместителем." },
    ["4971c"] = { common = "Мне стало много легче исправлять ход времени. Спасибо, путник. Хотя тебе непросто понять все опасности нарушения естественного хода событий, я рада, что ты осознаешь важность противостояния Плети, а я почти уверена, что это дело её рук. Почему бы не вознаградить тебя за помощь, смертный. Тебя ждут величайшие подвиги, и одна безделушка не заставит тебя свернуть с избранного пути. Хотя нам с драконами не помешает твоя помощь и в дальнейшем…" },
    ["4972a"] = { common = "Мне нужно отправить тебя в мир за пределами этой комнаты, путник. Сейчас всё объясню. Видишь, как эта комната отличается от остального Андорала? Мои драконы существуют во многих пластах реальности и времени. Чтобы исправить ущерб, нанесённый Андоралу, я действую из другого временного пласта, чтобы не загрязнить его сверх меры. Для продолжения работ мне необходимы особые устройства, оставшиеся со времён прихода чумы. Они находятся в сундуках в руинах некогда гордого города." },
    ["4972c"] = { common = "Вот, как раз то, что нужно, путник. Спасибо. Позволь вознаградить тебя. Быть может, ты не понимаешь, зачем тебе такое устройство. И даже для чего оно; довольно знать, что в будущем этот предмет тебе очень пригодится. А сохранишь ты его до тех времён или нет… дело твоё, дружок." },
    ["4974a"] = { common = "Ренд осмеливается делать подобные заявления, потому что он пользуется поддержкой чёрных драконов. Ты, путник, проникнешь в Залы Вознесения, найдёшь там \"вождя\" Ренда Чернорука и уничтожишь его — во имя Орды!!! В следующий раз, как я увижу тебя в своих покоях, ты торжествующе поднимешь ввысь его отрубленную голову и вручишь её своему вождю. Выполни это — и станешь одним из героев Орды!" },
    ["4974c"] = { common = "Ты нанёс сокрушительный удар по силам Чернорука, путник. Со смертью их главаря, легион Чернорука будет погружён в хаос. В честь твоей победы, народ Калимдора будет награждён!" },
    ["4975a"] = { common = "Я немедленно займусь твоим шаром. Надо вселить в него нового демона. После этого у меня будет выбор: превратить его в сферу или в посох. Я всегда считала, что соответствие избранному оружию чернокнижника – это главное... Не вижу причин менять своё мнение." },
    ["4975c"] = { common = "Готово. Просто скажи, что же ты предпочитаешь – посох, который занимает обе руки, или сферу, с которой ты можешь использовать кинжал или что-то ещё в своей правой руке. Желаю тебе всяческих успехов в совершенствовании твоих искусств." },
    ["4976a"] = { male = "Теперь, когда демон изгнан, ты можешь отнести шар Менаре в Кабестан. Передай ей от меня привет, да и сам не робей. Надеюсь, что тебе удастся противостоять искушениям порчи, которые, несомненно, будут подстерегать тебя на избранном пути. Желаю удачи.", female = "Теперь, когда демон изгнан, ты можешь отнести шар Менаре в Кабестан. Передай ей от меня привет, да и сама не робей. Надеюсь, что тебе удастся противостоять искушениям порчи, которые, несомненно, будут подстерегать тебя на избранном пути. Желаю удачи." },
    ["4976c"] = { common = "Отлично. Подходящая сфера. Осталось одно – решить, какого демона следует заключить в неё. Решишь – считай, новый предмет силы у тебя в кармане." },
    ["4981a"] = { common = "Никогда нельзя верить гоблинам! Рано или поздно все приходят к этому выводу, путник. Её зовут Блестяшка, она была одним из лучших наших агентов. Потом оказалось, что стерва вела двойную игру — работала на какого-то типа по имени Киблер, нелегально торгующего экзотическими животными в Пылающих степях, и использовала средства Орды для финансирования своих махинаций! Она должна быть доставлена ко мне живой. Последний раз её видели у Пика Чёрной горы. И смотри, чтобы она не заговорила тебе зубы!" },
    ["4981c"] = { common = "Не хочу лгать тебе, странник. Мне нужны деньги. А Киблер хорошо платит — куда лучше чем К.Э.К… Но не сомневайся в моей лояльности! Ты думаешь что я тут делаю? Ты думаешь, что я тут чтобы достать сумасшедшему гоблину яйца пауков? Только полный идиот пойдёт в Пик Чёрной горы чтобы собрать животных. Да. Я не думаю что таких найдётся много." },
    ["4982a"] = { common = "По ночам, когда городская стража не особенно ревностно исполняет свои обязанности, я незаметно брожу по улицам и беру на заметку всё, что может иметь хоть какую-то ценность для стратегических планов К.Э.К. Всё подмечаю и всё записываю. Но вчера ночью случился прокол. В темноте я запнулась о натянутую верёвку, и включился сигнал тревоги. Пришлось срочно прятать всё оборудование для разведки и мчаться в укрытие. И что самое ужасное, сейчас мне уже не удастся забрать свои вещи из тайника. В городе ввели усиленный режим патрулирования! Вся информация утрачена. Разыщи мои вещи, верни их мне, и я тихо-мирно вернусь в К.Э.К." },
    ["4982c"] = { common = "Ты сделал это! Когда Лекслорт получит эти планы, то он меня простит! Путник, ты мой герой!" },
    ["4983a"] = { common = "Передай этот рапорт Лекслорту. Теперь я верну себе доброе имя, потому что моё донесение, безусловно, сослужит хорошую службу К.Э.К. и даст им значительное стратегическое преимущество в борьбе с этими орками. Пойти с тобой, говоришь? У меня много работы, недосуг мне носиться туда-сюда. Беги, донесение надо доставить как можно скорее!" },
    ["4983c"] = { common = "Я должен отдать ей должное — она выкрутилась опять. Этот рапорт бесценен для наших усилий разобраться с орками Чёрной Горы. Конечно, ты будешь вознаграждён за свою тяжёлую работу." },
    ["4984a"] = { common = "Хотя бороться с Плетью в одиночку бесполезно, я всё равно прибыл в эти земли, чтобы лечить израненную природу. Чума поражает зверей и травы, не ведая пощады. Прошу, продолжи моё дело. Несчастных животных не спасти, остаётся прекратить их страдания. Ступай, отыщи больных волков и прикончи их. Прошу тебя, путник, избавь их от мучений — и мне тоже станет полегче." },
    ["4984c"] = { common = "Я… Чую, что души убитых волков обрели покой. Мы с ними благодарны тебе за милосердие. Но в этом проклятом месте страдают не только волки. Мне вновь придётся просить тебя о помощи." },
    ["4985a"] = { common = "На востоке отсюда, рядом с границей Восточных Чумных земель, некогда жили гордые и могучие гризли. Чума затронула и их. Теперь они бродят по округе, страдая от застывающих мышц и гниющей плоти и меха. Прошу тебя, избавь их от страданий. Единственное исцеление для них — быстрая смерть. Ты можешь даровать её." },
    ["4985c"] = { common = "Я чувствую, что гризли упокоились с миром. Вот… вот моя последняя просьба. Я записал её на этой ветви, чувствуя, что дни мои сочтены. Я не ошибся, мне и верно приходит конец. Ещё раз спасибо, брат… все живые существа этой проклятой земли обрели покой… теперь мой черёд." },
    ["4986a"] = { common = "В безжизненной руке друида-таурена — удивительно живая дубовая ветвь. Внимательно осмотрев её, вы видите вырезанные на ней друидические символы. Схватившись за ветвь, вы замечаете, что она слишком тёплая для простой ветви. У вас в подсознании возникает образ древа Тельдрассила, точнее, самого Дарнасса. Более того, в голове так и вертятся слова \"Круг Кенария\". Кажется, в ветку вложили знания, куда её лучше отнести." },
    ["4986c"] = { common = "Это… Это странно. Тот друид — друид-таурен, надо же — передал тебе ценнейшие сведения о чуме Плети. Удивительно, зачем таурену понадобилось добровольно передавать подобные сведения ). Надеюсь, ты говоришь правду. Не сомневайся, мы воспользуемся этими данными. Значит, таурены не так далеко отпали от Кенария, как полагает Фэндрал… Кхе-кхе, да. Прими это в знак признательности Круга Кенария." },
    ["4987a"] = { common = "В безжизненной руке друида-таурена — удивительно живая дубовая ветвь. Внимательно осмотрев её, вы видите вырезанные на ней друидические символы. Схватившись за ветвь, вы замечаете, что она слишком тёплая для простой ветви. У вас в подсознании возникает образ Громового Утёса в Мулгоре, точнее, Вершины Старейшин. Более того, в голове так и вертятся слова \"Круг Кенария\". Кажется, в ветку вложили знания, куда её лучше отнести." },
    ["4987c"] = { common = "Это от Мулгриса, говоришь? Мы слышали о тех ужасах что творятся с живыми существами в Чумных землях, но это довольно неожиданно. И печально… Мулгрис был хорошим другом. Был… Его усилия не пропадут зря. Мы подхватим его ветку… и выясним, что же до сих пор распространяет эпидемию Чумы по нашим землям… Выясним точнейшим образом. А ты, пожалуйста возьми это. Это минимум того чем мы можем вознаградить тебя." },
    ["5001a"] = { common = "Обычно я стараюсь не связываться с такими, как ты, странник, но, похоже, сейчас я застряла между троллем и горным завалом. Видишь ли, я выполняю важное задание для Орды. Однако та информация, которую мне удалось раздобыть, касается также и благополучия Альянса. Поверь мне, я не питаю симпатий к Альянсу, но угроза Чёрной горы — это гораздо серьёзнее, чем какая-то там толпа грязных орков. Помоги мне найти мои вещи, а я передам тебе сведения, которые могут оказаться полезными для твоих сородичей. Ну что, по рукам?" },
    ["5001c"] = { common = "Ой, спасибо! И где ж они были?!" },
    ["5002a"] = { common = "Я — честная гоблинша и хозяйка своего слова, странник. А теперь слушай внимательно… Этих орков используют в основном в качестве вьючных животных или пушечного мяса для чёрных драконов! Их предводитель не кто иной, как Нефариан, сын Смертокрыла. Также мне удалось узнать, где именно в крепости засели приспешники Нефариана. Отнеси эту карту маршалу Максвеллу в Пылающие степи. Я там отметила все места, где найти этих извергов." },
    ["5002c"] = { common = "Что ж, это лишь подтверждает уже известную нам информацию. Тем не менее здесь есть интересные сведения, которые нам пригодятся. Отметки на карте — это хорошее подспорье. Так мы быстрее разберёмся с угрозой Чёрной горы." },
    ["5021a"] = { common = "\"Доставьте посылку… Доставьте её, пока я не очутилась в ловушке!\" \"Ты хочешь доставить мою посылку? Прошу тебя, сделай это, пока хуже не стало. Я собиралась уехать отсюда. Должно быть, там всё ещё стоит мой конь… или я опоздала?\"" },
    ["5021c"] = { common = "В сарае на полу лежит посылка. Вы могли бы пройти мимо, но она бросается в глаза среди развалин. Быть может, именно о ней говорила Джанис Фелстоун…" },
    ["5022a"] = { common = "Вы берете посылку, стирая с неё слой пыли и грязи. Она адресована Эмме Фелстоун из Штормграда; посылка должна была быть доставлена четыре года назад. Хотя вы не уверены, что Эмма Фелстоун жива, всем известно, что в Штормграде существует реестр жителей города. Справки можно наводить у королевских представителей Переписи Штормграда." },
    ["5022c"] = { common = "Говорите, посылка для Эммы Фелстоун? И четыре года назад она жила в Штормграде? Посмотрим… Судя по всему, четыре года назад в городе и верно жила некая Эмма Фелстоун. Скорее всего жила. Я ориентируюсь по переписи, имевшей место пять лет назад, но никаких записей о том, что она уехала, нет. Но это не значит, что Эмма всё ещё здесь. Минуточку… уж не старушке ли Эмме адресована эта посылка?" },
    ["5023a"] = { common = "Вы берете посылку, стирая с неё слой пыли и грязи. Она адресована Иеремии Фелстоуну из Лордерона; посылка была подготовлена к отправке четыре года назад. Хотя вы не уверены, что Иеремия Фелстоун жив, всем известно, что в Подгороде, прежде именовавшемся Лордероном, существует реестр жителей города. Справки можно наводить у королевских инспекторов Переписи Подгорода." },
    ["5023c"] = { common = "Это пакет для Иеремии Фелстоуна, последний адрес — Лордерон… Да, я думаю, я смогу помочь тебе. Иеремия Фелстоун был в городе, когда началась эпидемия. Я бы сказал, бывший Иеремия Фелстоун — многие из Отрекшихся сменили свои имена. В нашем конкретном случае, Иеремия Фелстоун известен как Иеремия Пэйсон. Минутку… продавец тараканов?!" },
    ["5041a"] = { common = "Нападение на караваны лишает нас необходимых припасов. Тебе хватило храбрости выступить против племени Иглогривых, и я вновь попрошу тебя о том же, но на сей раз посматривай, нет ли где украденных у нас припасов? Может быть, они в лагерях этих тварей, и иглогривы жиреют на чужом добре? Народ Перекрёстка будет у тебя в неоплатном долгу." },
    ["5041c"] = { common = "Ха-ха! Спасибо! Ты нам очень помог. Ты неизменно спасаешь народ Перекрёстка и Орды. Если я могу что-нибудь для тебя сделать, обращайся." },
    ["5047a"] = { common = "Разыщи Малифоя Черномолота в Круговзоре, герой. Скажи ему, что с Айсом всё в порядке и что костюмчик исправно работает. И передай ему вот что… Я его вырезал из внутренностей одной зверюги во время своих вынужденных каникул. Готов поспорить, Малифой очень подробно тебе растолкует, что можно сделать с мясом этого чудища! Кстати, ты знаешь, где Круговзор? Это в Зимних Ключах." },
    ["5047c"] = { common = "Он жив? Костюм цел? А что это там у тебя?" },
    ["5048a"] = { common = "Это злобная старушенция и к тому же, весьма вероятно, уже с катушек съехала… Но записи указывают, что старушка Эмма как раз вполне может являться той самой Эммой Фелстоун. Возможно, вы видели старушку Эмму бредущей по городу — она разговаривает сама с собой, иногда неся совершенно невнятный вздор. Но она никому и ничему не мешает, так что горожане, в большинстве своём, оставили её в покое. Обдумав всё, я бы сказал, что старушка Эмма и в самом деле — Эмма Фелстоун. Можете сами спросить у неё, не Фелстоун ли её фамилия." },
    ["5048c"] = { common = "Моё имя и в самом деле Эмма Фелстоун — но меня впервые так называют за много лет. Кто… кто вы? Вы говорите, что знали… мою сестру?! Она до сих пор жива? Да что это я — конечно же, нет. Когда чума охватила Лордерон, я ожидала самого худшего. Так много моих родственников погибло… или ещё хуже того. И вот я здесь, сумасшедшая старушка Эмма, одна-одинёшенька. Кто же вы — разоритель могил или что? Ищете следующую жертву? Что… у вас посылка для меня от сестры?" },
    ["5049a"] = { common = "Мне удалось выяснить, что тот, кого ты ищешь, — он же получатель посылки — это Иеремия Пэйсон, продавец тараканов в Подгороде. Мне всегда казалось, что для торговли тараканами нужны особые личные качества. Не сомневаюсь, тебя ждут великие дела, герой. Ступай, меняй мир к лучшему. Впрочем, позволь и мне поучаствовать в столь великих событиях и приоткрыть завесу тайны: он находится недалеко от банка, в стороне от одной из дорожек." },
    ["5049c"] = { common = "Что? Я не использовал это имя годами… но я готов подтвердить что это было моим именем… последним, которое я помню. Я думаю, что ты знал мою сестру… или я так предполагаю. Они всё давно умерли. Она умерла. А ты сам вообще кто таков будешь? Чего ты явился бередить старые раны? И что за пакет у тебя, от моей сестры??" },
    ["5050a"] = { common = "Кажется, я была неправа насчёт тебя и должна извиниться. Сестра прислала мне ряд личных вещей, в том числе — ха-ха — документы на ферму Фелстоун. Я погожу предъявлять на неё права. Если призрак моей сестры не может упокоиться и привязан к ферме… может быть, ты вернёшь ей это? Это половина талисмана; вторую носил её муж. Может быть, она обретёт покой, если узнает, что я получила посылку?" },
    ["5050c"] = { common = "\"Милый, а где твоя половина талисмана? Нам не быть вместе, не собрав его воедино. Милый… Ты меня видишь?\"" },
    ["5051a"] = { common = "\"Мне холодно, Джон. Принеси мне свой оберег, и мы снова будем вместе! Скорее, Джон, пока чума не превратила нас в жутких тварей! Я не вижу тебя, Джон… Но знаю, ты рядом. Я чувствую.\"" },
    ["5051c"] = { common = "\"Ты освободил меня… Мне больше не нужен этот оберег. Возьми его, быть может он принесёт тебе не меньшее утешение, чем мне.\"" },
    ["5052a"] = { common = "Кровь повлияла не только на шипы *фыркает*, но и на другие аспекты земли: среди прочих минералов попадаются кроваво-красные камни. Племя Дыбогривов выкапывает эти осколки и носит с собой как тотэмы *фыркает*, и они дают им силы в бою и помогают творить заклинания. *фыркает* Секреты их магии мне известны. Принеси Кривозубу один кровавый осколок, и ты всё поймёшь. Принеси Кривозубу много осколков, и он благословит тебя. Сильна магия иглогривов, ведь это магия самого Агамаггана! *фыркает*" },
    ["5052c"] = { male = "Да, ты понимаешь. фыркает Мои слова для тебя – не пустой звук, герой. Быть может, Кривозуб и заключён в клетку, но что клетка для силы Агамаггана! фыркает Касание осколка, какое забытое ощущение, герой. Знаешь, каково это – чувствовать себя отрезанным от силы? Но об этом в другой раз. Я обещал поделиться с тобой сведениями. Я обещал тебе силу Агамаггана. Мой народ отвернулся от Кривозуба. Теперь они падут от твоей руки. фыркает", female = "Да, ты понимаешь. фыркает Мои слова для тебя – не пустой звук, героиня. Быть может, Кривозуб и заключён в клетку, но что клетка для силы Агамаггана! фыркает Касание осколка, какое забытое ощущение, героиня. Знаешь, каково это – чувствовать себя отрезанным от силы? Но об этом в другой раз. Я обещал поделиться с тобой сведениями. Я обещал тебе силу Агамаггана. Мой народ отвернулся от Кривозуба. Теперь они падут от твоей руки. фыркает" },
    ["5054a"] = { common = "В заснеженных горах Зимних Ключей, на северо-западе, умелый охотник идёт по следу своей добычи… Я говорю о медведе-щербозубе Урсиусе — звере ловком и умном. Я посылаю тебя в бой против него. Он бродит по холмам к северо-западу от Круговзора. Найди его и начни охоту на него — раньше, чем он поймёт твои намерения. Все, кто шли на Урсиуса, вскоре понимали, что они добыча, а отнюдь не охотники. Так что будь начеку." },
    ["5054c"] = { common = "Это была нелёгкая задача, но ты справился. Но не думай, что этим ты удивил меня, путник." },
    ["5055a"] = { common = "Быстрая и умная, Брумеран тихо скользит по заснеженным просторам южных окраин Зимних Ключей. Но пусть тебя не обманывает её грация — она отнюдь не безопасна. Все, кто встаёт у неё на пути, расплачиваются за это — частенько своими собственными жизнями. Найди Брумеран среди химер Холодного Ветра. Срази её, а затем возвращайся ко мне." },
    ["5055c"] = { common = "Да. Ты вернулся. Теперь я верю, что охота — твоё призвание. Ты встретился с самой свирепой из тварей и вернулся превзойдя мои ожидания. Теперь ты готов к моему последнему испытанию." },
    ["5056a"] = { common = "На севере Зимних Ключей, в районе, который называют Уступ Ледопардов, обитают огромные кошки. Их предводительница известна под именем Ши-Ротам. Если тебе удастся сразить матриарха ледопардов, ты завоюешь уважение в глазах своих сородичей. Отправляйся обратно в глушь. Придя на место, добудь священного мяса ледопардов. Найди камень Ши-Ротам и помести мясо на него. Мясо растерзанных подданных заставит их предводительницу Ши-Ротам явиться в гневе. Будь готов встретиться с ней лицом к лицу и сразить её." },
    ["5056c"] = { common = "Ты доказал как свою силу, так и решимость. Ещё много испытаний ждёт тебя впереди. Я показал тебе всё, что мог. Удачи, путник." },
    ["5057a"] = { common = "Ещё раньше, чем вы пришли ко мне поговорить, путник, я слышал о ваших деяниях… что у вас есть непреодолимое желание проявить себя, что вы герой с отменными способностями, и теперь я знаю, что всё это было правдой. Те, кто добивается таких успехов, заслуживают признания. Отнесите этот знак в Громовой Утёс моему другу Мелору Каменному Копыту. Уверен, что он вспомнит и вас, и ваши подвиги. Расскажите ему о своих недавних достижениях. И никогда не забывайте о том, что свершили сегодня." },
    ["5057c"] = { common = "Жизнь даёт нам опыт, путник. Как говорит мне этот знак, ты стал сильнее и мудрее. Ты вырос с момента нашего последнего разговора… Возьми это на память о том что ты совершил и знай что я всегда приму тебя радушно и гостеприимно." },
    ["5058c"] = { common = "Дневник с пожелтевшими страницами лежит открытый на последней записи. \"Я не знаю, что будет теперь, когда Гарольд начал превращаться. Потребовалось собрать все свои силы, чтобы затащить его в то единственное место, в котором я бы смогла его удерживать и заперла. Я спрятала ключ… он на мне. Надеюсь что мне удастся выбраться отсюда, но мне нужны деньги… все наши вещи в шкафчике. Но где же ключ? Неужели он у Гарольда? Я отдохну около него, я ужасно устала.\"" },
    ["5060c"] = { common = "Взятый ключ из омерзительных останков фермера Далсона, прекрасно подходит под замок. Двери шкафчика распахиваются. Несколько предметов оказываются совсем не тронутыми и могут проявлять весьма не плохую ценность." },
    ["5061a"] = { male = "Ты завершил обучение, которое проходят все начинающие друиды прежде, чем они смогут принимать водный облик. Теперь возвращайся к своему наставнику, Матренгилу Медвежьей Лапе в Дарнасс. Покажи ему свою подвеску и докажи, что ты готов усвоить его уроки. Он завершит твоё обучение, благодаря которому ты станешь единым с водой. Доброго пути, юный друид. Мы ещё встретимся.", female = "Ты завершила обучение, которое проходят все начинающие друиды прежде, чем они смогут принимать водный облик. Теперь возвращайся к своему наставнику, Матренгилу Медвежьей Лапе в Дарнасс. Покажи ему свою подвеску и докажи, что ты готова усвоить его уроки. Он завершит твоё обучение, благодаря которому ты станешь единой с водой. Доброго пути, дева-друид. Мы ещё встретимся." },
    ["5061c"] = { male = "Великолепно. Ты готов принимать водный облик, и я с радостью научу тебя. А также, в знак признания твоих успехов в двух испытаниях, я даю тебе вот это. Надеюсь, тебе приятно будет присоединить эту вещь к своему снаряжению защитника Природы и хранителя равновесия.", female = "Великолепно. Ты готова принимать водный облик, и я с радостью научу тебя. А также, в знак признания твоих успехов в двух испытаниях, я даю тебе вот это. Надеюсь, тебе приятно будет присоединить эту вещь к своему снаряжению защитника Природы и хранителя равновесия." },
    ["5062a"] = { common = "Арикара очень опасна, и мы должны как можно быстрее разделаться с ней. Для того чтобы привлечь это чудовище, тебе нужно будет разжечь священный огонь жизни. Собери немного редкой огненной агавы и отнеси её Магате Зловещий Тотэм. Она живёт в Громовом Утёсе, на Вершине Старейшин. Магата – очень могущественная шаманка, владеющая тайной приготовления зачарованного порошка из огненной агавы. Огненную агаву можно собрать на Кипящем озере, это к востоку отсюда." },
    ["5062c"] = { common = "Прекрасно, вы собрали достаточно огненной агавы. Эта редкая трава растёт лишь в Тысяче Игл, и она поможет мне разбудить священное пламя жизни. Магата начинает зачаровывать огненную агаву." },
    ["5064a"] = { common = "Вы уже помогали нам, поэтому я доверю вам ещё одно важное задание. Клан Зловещий Тотэм явно что-то замышляет: недавно мы видели, как в их поселение приходили какие-то странные путники. Потом нам удалось узнать, что важные записи они хранят в трёх разных сундуках Пика Тёмного Облака. Если вам удастся достать эти документы, я щедро вас вознагражу." },
    ["5064c"] = { common = "Великий тотэм духов! Какие ужасные новости! Я немедленно начну готовиться, кто знает, что нас ждёт... Вот, как я и обещал, это награда за вашу храбрость и услугу." },
    ["5065a"] = { common = "Тот тролль обманул тебя. В тех двух табличках шла речь о пленении сущности Хаккара, но легенда этим не исчерпывается. Я долго изучал этот вопрос, и обнаружил, что табличек Мошару шесть, а не две! Шесть! И боюсь, нас не порадует то, что в них записано. Найди третью и четвёртую таблички. Они находятся в Восточных Чумных землях, у троллей из племени Моходеров. Найди их и принеси мне." },
    ["5065c"] = { common = "Ты нашёл их! Здорово! Спасибо тебе, путник. Я проберусь через заросли этих текстов и расшифрую их значение. А у тебя, конечно же, будет другая задача…" },
    ["5066a"] = { common = "Слушайте, слушайте все! Я обращаюсь к героям, и да услышат они мою речь! Король Штормграда призывает к оружию! Все, кто способен держать в руках оружие, должны подняться на борьбу с проклятой Плетью! Спешите на северные границы Восточных королевств! Стало известно, что над Чумными землями вновь сгущаются тучи! Герои королевства! Ищите командира Ашлама Отважного Кулака! Его гарнизон вы найдёте в лагере Промозглого Ветра на севере Альтеракских гор!" },
    ["5066c"] = { common = "Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно! Если вы готовы к тяжёлому труду, то на краю Чумных земель всем героям найдётся дело." },
    ["5067a"] = { common = "В то время как изготовление такого предмета ещё никому не удавалось, считается, что это всё же возможно – при правильном стечении обстоятельств. Если искатель тайных знаний желает наделить поножи могучей силой, вот что должно быть найдено: *Безупречная звериная шкура. *Потёртый шовный материал поганища. *Арканитовые Слитки. *Бальзамировочный состав Снегошёпота. И УЗРИШЬ ТЫ ЧУДО!" },
    ["5067c"] = { common = "Никогда не видел лучших поножей! Носи с удовольствием!" },
    ["5081a"] = { common = "Эти сведения заполняют последние пробелы в наших данных о пике Чёрной Горы. Мы должны напасть со всей решительностью, путник. Первым делом нужно убить их воеводу, Вуна. Без его боевых планов орки Чёрной Горы будут ввергнуты в хаос. Следом должен умереть вождь огров, Омокк. Трусливые огры Чёрной Горы окажутся беспомощны. И, наконец, повелитель всей цитадели зла: Вурмталак. Когда он умрёт, командование будет обезглавлено." },
    ["5081c"] = { common = "Прекрасная работа, путник! Ты выиграл для нас время, бесценное время!" },
    ["5082a"] = { common = "Сюда в Зимние Ключи я пришла, чтобы изучать Источники Ледяного Пламени. Я заметила, что у воды здесь какие-то… странные свойства. Мне пока не удалось определить источник этих свойств, да и, по правде говоря, в последнее время у меня возникли кое-какие сложности, из-за фурболгов племени Зимней Спячки. Их, кажется, тянет к источникам — так же, как и меня. Они яростно защищают воду и не подпускают меня близко к двум большим ключам к северу отсюда. Я хотела бы продолжить свои изыскания. Ты не поможешь мне?" },
    ["5082c"] = { common = "Огромное спасибо, путник! Теперь я могу вернуться к работе. Нашёл что-нибудь интересное в поселении Зимней Спячки?" },
    ["5083a"] = { common = "Тот сосуд, что вы нашли у фурболга племени Зимней Спячки, пуст, но внутри осталось несколько капель странной зелёной жидкости. Он почти сияет. Обнаружили ли вы нечто важное? Возможно, Донова Снегонора могла бы что-то вам разъяснить, поскольку она уже довольно давно живёт у горячих ключей." },
    ["5083c"] = { common = "Ты нашёл это у фурболга племени Зимней Спячки?" },
    ["5084a"] = { common = "Зелёная жидкость… немного напоминает мне жижу, которую я видела, когда пробиралась через Осквернённый лес. И я видела несколько гонцов племени Зимней Спячки, входящих во владения Древобрюхов… Возможно, это имеет отношение к той склянке, что вы нашли, путник. Сразу за Крепостью Древобрюхов, в Осквернённом лесу, живёт большая группа фурболгов. Они зовутся племенем Мёртвого Леса, и давно попали под власть скверны. Да, фурболги этого племени совершенно безумны. Может, сходишь и поищешь свидетельства того, что между племенами Зимней Спячки и Мёртвого Леса есть какое-то сообщение?" },
    ["5084c"] = { common = "В котле кипит гнилостная, отвратительно пахнущая субстанция…" },
    ["5085a"] = { common = "Зелёная субстанция внутри котла кажется точно такой же, какую вы обнаружили в сосуде. Это странное слизистое вещество может оказаться таким же полным скверны, как и фурболги, что его изготовили… Если фурболги племени Зимней Спячки его используют, значит ли это, что вскоре они окажутся в таком же состоянии, как и племя Мёртвого леса? Лучше всего сообщить об этих находках Донове, прихватив и образец жидкости из котла." },
    ["5085c"] = { common = "Ты очень находчив, путник. Так ты полагаешь, что фурболги племени Зимней Спячки побывали в лагере Мёртвого Леса?" },
    ["5086a"] = { common = "Я изучила образцы, с которыми вы вернулись, и хотя точно пока ничего сказать не могу, я думаю, что в них есть следы ядовитых компонентов. Однако, единственный способ узнать наверняка — это найти что-то для сравнения. Я думаю, что фурболги Мёртвого Леса могут собирать эти компоненты с других заражённых скверной существ в Осквернённом лесу: в частности, с элементалей, населяющих Железнолесье, которых называют ядовитым ужасом. Собери для меня несколько образцов для сравнения, но будь осторожен — там очень опасно!" },
    ["5086c"] = { common = "Мне надо сравнить это с веществом, которое ты нашёл в котле, и тогда мы многое узнаем." },
    ["5087a"] = { common = "Очень интересно, путник… Если эту ядовитую субстанцию смешать с водой из горячих ключей, она потеряет свою токсичность, и остаётся лишь способность временно воздействовать на тех, кто такую смесь употребляет. Наверное, из-за этого племя Зимней Спячки и защищает источники столь яростно: они необходимы фурболгам для очистки огненной воды. Мы должны положить этому конец: прекратить контакты между племенами Зимней Спячки и Мёртвого Леса. Группа гонцов курсирует между поселением Зимней Спячки и Осквернённым лесом. Найди их, убей и забери то, что у них будет с собой." },
    ["5087c"] = { common = "Интересно, делает ли употребление этой субстанции фурболгов более агрессивными? На вид они кажутся намного крупнее…" },
    ["5088a"] = { male = "Возьмите этот зачарованный порошок и зажгите священный огонь жизни в Тысяче Игл. Сделать это нужно на Пике Тёмного Облака, на отдельной скале, где находится местное кладбище. Я зачаровала порошок так, чтобы он привлёк Арикару. Боюсь, что она охотится за Кэрном Кровавым Копытом – из-за него обычаи тауренов претерпели слишком много изменений, и это могло разозлить чудовище. Поспешите, герой, вы можете не успеть!", female = "Возьмите этот зачарованный порошок и зажгите священный огонь жизни в Тысяче Игл. Сделать это нужно на Пике Тёмного Облака, на отдельной скале, где находится местное кладбище. Я зачаровала порошок так, чтобы он привлёк Арикару. Боюсь, что она охотится за Кэрном Кровавым Копытом – из-за него обычаи тауренов претерпели слишком много изменений, и это могло разозлить чудовище. Поспешите, героиня, вы можете не успеть!" },
    ["5088c"] = { common = "Ерунда какая-то. Зачем Арикаре охотиться за Кэрном Кровавым Копытом? Но Магата не может ошибаться, она наша самая могущественная шаманка. Мотега качает головой. В любом случае, вы очень помогли Орде, и деяние ваше не останется незамеченным. Пожалуйста, выберите себе любую награду." },
    ["5089a"] = { common = "Вы обыскали труп убитого драконида и обнаружили записку, содержание которой показалось вам важным: письмо от его непосредственного начальника, генерала Драккисата, в котором упоминается некий протокол. Внутренний голос подсказывает, что это письмо следует показать маршалу Максвеллу." },
    ["5089c"] = { common = "Мда… теперь всё усложняется…" },
    ["5090a"] = { common = "Слушайте все! Все герои – слушайте! Королевство Штормграда призывает всех к оружию! Все способные держать оружие – на защиту севера Восточных королевств против чёрной угрозы Плети! Новая опасность надвигается из руин Чумных земель! Герои королевства – собирайтесь к командиру Ашламу Отважному Кулаку в лагерь Промозглого Ветра к северу от Альтеракских гор!" },
    ["5090c"] = { common = "Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно! Если вы готовы к тяжёлому труду, то на краю Чумных земель всем героям найдётся дело." },
    ["5091a"] = { common = "Слушайте все! Все герои – слушайте! Королевство Штормграда призывает всех к оружию! Все, кто способен держать оружие, – на защиту севера Восточных королевств против чёрной угрозы Плети! Новая опасность надвигается из руин Чумных земель! Герои королевства – собирайтесь к командиру Ашламу Отважному Кулаку в лагерь Промозглого Ветра к северу от Альтеракских гор!" },
    ["5091c"] = { common = "Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно! Если вы готовы к тяжёлому труду, то на краю Чумных земель всем героям найдётся дело." },
    ["5092a"] = { common = "Поскольку западная и северная дороги, ведущие в Андорал, хорошо укреплены, я подумываю о нападении с востока, как наименее защищённой стороны. Плеть рассчитывает на защиту нежити, наводнившей холм Печали. Первым заданием будет зачистка холма Печали. Убей побольше скелетов и вурдалаков; по выполнении задания возвращайся ко мне!" },
    ["5092c"] = { common = "Задание выполнено, путник! Отлично, отлично! Позволь наградить тебя за труды звонкой монетой из казны Штормграда. Советую потратить награду на подготовку к следующей битве… Ведь тебе придётся войти в руины Андорала. Готовься! Будь бдителен!" },
    ["5093a"] = { common = "Внимайте моим словам, о герои! Орда призывает к решительным действиям! Все, кто способен носить оружие, должны выступить в поход против Плети! Из руин Восточных королевств поднимается новая угроза! Ваш путь лежит на восток от Подгорода, в северные пределы земель, ныне известных как Чумные земли. Храбрецы, обращайтесь к верховному палачу Деррингтону. Он ждёт вас в лагере у Бастиона, к востоку от Тирисфальских лугов!" },
    ["5093c"] = { common = "Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно! Если вы готовы к тяжёлому труду, то на краю Чумных земель всем героям найдётся дело." },
    ["5094a"] = { common = "Внимайте моим словам, о герои! Орда призывает к решительным действиям! Все, кто способен носить оружие, должны выступить в поход против Плети! Из руин Восточных королевств поднимается новая угроза! Ваш путь лежит на восток от Подгорода, в северные пределы земель, ныне известных как Чумные земли. Храбрецы, обращайтесь к верховному палачу Деррингтону. Он ждёт вас в лагере у Бастиона, к востоку от Тирисфальских лугов!" },
    ["5094c"] = { common = "Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно! Если вы готовы к тяжёлому труду, то на краю Чумных земель всем героям найдётся дело." },
    ["5095a"] = { common = "Внимайте моим словам, о герои! Орда призывает к решительным действиям! Все, кто способен носить оружие, должны выступить в поход против Плети! Из руин Восточных королевств поднимается новая угроза! Ваш путь лежит на восток от Подгорода, в северные пределы земель, ныне известных как Чумные земли. Храбрецы, обращайтесь к верховному палачу Деррингтону. Он ждёт вас в лагере у Бастиона, к востоку от Тирисфальских лугов!" },
    ["5095c"] = { common = "Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно! Если вы готовы к тяжёлому труду, то на краю Чумных земель всем героям найдётся дело." },
    ["5096a"] = { common = "Прежде чем заняться Андоралом, мы должны разобраться с Алым орденом, обосновавшимся в Дольном Очаге. Его приспешники разбили лагерь между полем Джанис и Слезами Далсона, так что мы оказались между двух огней — нам противостоят разом и Плеть, и Алый орден. Мне кажется, надо их стравить между собой. Вот что я хочу тебе поручить: уничтожь командный шатёр. Сожги его при помощи пламени в бутылке — вот, возьми в этом ящике. Сделав это, воткни посреди лагеря знамя Плети. При удаче, нас оставят в покое и займутся Плетью." },
    ["5096c"] = { common = "Прекрасно исполнено, путник. Твоя атака на Алый Орден выиграет нам время. Я послал своих лучших разведчиков наблюдать за ними, чтобы быть уверенными, что они заглотили наживку. Ну что ж, я думаю, что теперь мы рискнём пойти на сам Андорал и я думаю, что мы достигнем успеха!" },
    ["5097a"] = { common = "Мы можем пометить будущие цели для наших войск при помощи магического устройства, сигнального факела. Мы подозреваем, что Плеть пользуется сторожевыми башнями Андорала для управления собственными войсками. Твоя цель — ворваться в Андорал и установить сигнальные факелы на всех четырёх башнях. Устанавливать факелы надо в дверных проёмах; они сами собой отметят всю башню. В сигнальном факеле всего пять зарядов, поэтому не трать их понапрасну." },
    ["5097c"] = { common = "Жрецы говорят, что со всех четырёх башен идут чёткие сигналы! Боюсь сглазить, но по-моему, ты только что выполнил очередную операцию без сучка, без задоринки! Отлично, путник! Башни помечены, и всё готово к началу атаки. Пришло время сразиться с Плетью!" },
    ["5098a"] = { common = "Мы можем пометить будущие цели для наших войск при помощи магического устройства, сигнального факела. Мы подозреваем, что Плеть пользуется сторожевыми башнями Андорала для управления собственными войсками. Твоя цель — ворваться в Андорал и установить сигнальные факелы на всех четырёх башнях. Устанавливать факелы надо в дверных проёмах; они сами собой отметят всю башню. В сигнальном факеле всего пять зарядов, поэтому не трать их понапрасну." },
    ["5098c"] = { common = "Жрецы говорят, что со всех четырёх башен идут чёткие сигналы! Боюсь сглазить, но по-моему, ты только что выполнил очередную операцию без сучка, без задоринки! Отлично, путник! Башни помечены, и всё готово к началу атаки. Пришло время сразиться с Плетью!" },
    ["5102a"] = { common = "Мы бьёмся против этих тварей на двух фронтах — из столицы, Штормграда, мы бьём их в спину, а здесь, в Пылающих степях, мы стоим у самого их порога. Не теряй бдительности, путник. Никто не избегнет нашего гнева, как никто из наших не избегнул их гнева, который обрушился на наши дома и семьи. Отыщи этого генерала Драккисата и убей его! Задание непростое, но и награда будет велика." },
    ["5102c"] = { common = "Уверен, что мы можем нанести удар по их дракон-лордам. А ты молодец, бравый солдат Альянса, вот кто ты." },
    ["5103a"] = { common = "От человека остался только обугленный скелет. Похоже, он умер буквально на расстоянии вытянутой руки от того, что пытался схватить, — неопалимых латных рукавиц. Может, вам стоит забрать рукавицы и попробовать выбраться из огня?" },
    ["5103c"] = { common = "Что это за…" },
    ["5121a"] = { common = "Хотя нам по-прежнему известно очень мало о том, зачем фурболги используют эту странную субстанцию, я думаю, что лучше всего положить конец всему этому, пока ситуация не вышла из-под контроля. Фурболги племени Зимней Спячки демонстрируют ненормальный уровень агрессии, и эта перемена в их поведении заставляет меня думать, что они, должно быть, выполняют приказ своего вождя. Скорее всего, мы не можем исправить тот вред, что уже нанесён, но я думаю, если их вождь будет убит, хуже они уж точно не станут. Тебе нужно идти на восток, в деревню Зимней Спячки." },
    ["5121c"] = { common = "Большое тебе спасибо, путник. Я надеюсь, что смогу вернуться к своим исследованиям, не опасаясь нападения из засады. Пожалуйста, прими это от меня в качестве награды." },
    ["5123a"] = { common = "Записи, которые вы нашли у верховного вождя, кажутся обширными, но просмотрев пару страниц, вы понимаете, что не можете прочитать написанное. Все заметки написаны так коряво, что вы сомневаетесь, что кто-либо сможет что-то понять в них. Но, может быть, Донова сможет?.." },
    ["5123c"] = { common = "Я даже не представляю, что это такое, я ничего не могу разобрать…" },
    ["5124a"] = { common = "Клянусь бородой Тауриссана! Откуда они у тебя? И, что ещё важнее, сможешь ли ты с ними расстаться? Само собой, я заплатил бы за столь благородный жест. Вот что я тебе скажу, путник. Если отдашь мне эти неопалимые рукавицы, я научу тебя, как сделать себе пару хороших рукавиц. Всё, что тебе нужно сделать — собрать для меня необходимое, чтобы я мог предложить тебе точный рецепт. Договорились?? Вот список того, что мне нужно. С тебя — рукавицы, а я пока займусь незачарованным торием." },
    ["5124c"] = { common = "Как я и обещал, путник, вот ваш рецепт! Я также добавлю кое-что от себя за ваши труды и самоотдачу. А то просто девать некуда!.." },
    ["5125c"] = { common = "Путник, я умираю… но моя душа будет сохранена. Я должен тебе больше, нежели пустые слова. Пожалуйста, прими это… и сражайся как храбрый герой!" },
    ["5128a"] = { common = "Племя Зимней Спячки больше не представляет для меня угрозы, но если тебе по-прежнему хочется выяснить, что побудило фурболгов готовить и использовать эту странную огненную воду, думаю, вам стоит поискать Келека Стража Неба. Он принадлежит к группе, известной как Изумрудный Круг — это группа друидов, посвятивших себя работе над исцелением Осквернённого леса от скверны. Келек много работал с фурболгами — может быть, он сможет больше меня рассказать об этих записях. И ещё раз спасибо тебе, путник." },
    ["5128c"] = { common = "Да, если ты позволишь мне взглянуть на него, то я смогу перевести, что там написано. Когда я полностью прочитаю журнал, тогда я дам тебе точный ответ. Благодарю тебя за то, что показал этот журнал мне, путник, нам очень мало известно о фурболгах Зимней Спячки. Этот журнал значительно пополнит наши знания." },
    ["5141a"] = { common = "Кожевничество школы чешуи драконов — непростое ремесло, однако весьма прибыльное. Я научу тебя изготовлять отличные кольчужные доспехи, но при одном условии. Выбрав этот путь, ты откажешься от изучения школ традиций предков и силы стихий. На пути к вершине мастерства ты должен выбрать лишь одну из трёх. Кроме того, я должен взглянуть на лучшие твои работы — в том числе на доспехи скорпида. И наконец, докажи мне, что ты способен добыть основу нашего ремесла — чешую дракона." },
    ["5141c"] = { common = "Ладно. Запомни накрепко — возможности изучить другие разделы работы с кожей у тебя больше не будет. Тренировка твоя будет осуществляться мной с большой скидкой. Просто поговори со мной, потом, в будущем." },
    ["5142a"] = { male = "Многие погибли во время битвы при Дарроушире… и многие, избежавшие смерти, позавидовали мёртвым. Когда битва началась, я спрятала мою племянницу Памелу и теперь не знаю, жива ли она. Я всего лишь странствующий дух, но моё сердце жаждет знать, всё ли у неё хорошо. Пожалуйста, добрый герой, не поищешь ли ты мою племянницу в Дарроушире? Это к востоку отсюда, за пустошью Гаррона.", female = "Многие погибли во время битвы при Дарроушире… и многие, избежавшие смерти, позавидовали мёртвым. Когда битва началась, я спрятала мою племянницу Памелу и теперь не знаю, жива ли она. Я всего лишь странствующий дух, но моё сердце жаждет знать, всё ли у неё хорошо. Пожалуйста, добрая героиня, не поищешь ли ты мою племянницу в Дарроушире? Это к востоку отсюда, за пустошью Гаррона." },
    ["5143a"] = { common = "Чтобы постичь школу традиций предков, следует обрести понимание подлинной сути дикой природы. Я знаю, что ты уже владеешь искусством изготовления дикарского кожаного доспеха, и хочу завершить твоё обучение. Знай, герой: избрав этот путь, ты отказываешься от изучения школ чешуи драконов и силы стихий, изучать можно только одну из них. А теперь принеси мне свои лучшие дикарские кожаные доспехи. С них мы и начнём твоё обучение." },
    ["5143c"] = { common = "Хорошо. Я дам тебе это знание… Не забывай заглядывать ко мне в дальнейшем… за рецептами…" },
    ["5144a"] = { common = "Я мастер кожевничества школы Стихии, и если ты хочешь открыть разум великим силам, я поделюсь с тобой всем, что знаю. Но знай, герой: выбирая этот путь, ты никогда уже не сможешь обучиться кожевничеству школы чешуи драконов и школы традиций предков, ибо из трёх школ должно выбрать одну. Кроме того, мне требуется доказательство того, что ты в гармонии со всеми стихиями. Принеси мне чистейшие субстанции огня, воды, земли и ветра." },
    ["5144c"] = { common = "Ты заслужил это искусство. Так получи же его! И кроме того, я буду тренировать тебя в будущем — и научу тебя чему смогу." },
    ["5145a"] = { common = "Кожевничество школы чешуи драконов — непростое ремесло, однако весьма прибыльное. Я научу тебя изготовлять отличные кольчужные доспехи, но при одном условии. Выбрав этот путь, ты откажешься от изучения школ традиций предков и силы стихий. На пути к вершине мастерства ты должен выбрать лишь одну из трёх. Кроме того, я должен взглянуть на лучшие твои работы — в том числе на доспехи скорпида. И наконец, докажи мне, что ты способен добыть основу нашего ремесла — чешую дракона." },
    ["5145c"] = { common = "Ладно. Запомни накрепко — возможности изучить другие разделы работы с кожей у тебя больше не будет. Тренировка твоя будет осуществляться мной с большой скидкой. Просто поговори со мной, потом, в будущем." },
    ["5146a"] = { common = "Я мастер кожевничества школы Стихии, и если ты хочешь открыть разум великим силам, я поделюсь с тобой всем, что знаю. Но знай, герой: выбирая этот путь, ты никогда уже не сможешь обучиться кожевничеству школы чешуи драконов и школы традиций предков, ибо из трёх школ должно выбрать одну. Кроме того, мне требуется доказательство того, что ты в гармонии со всеми стихиями. Принеси мне чистейшие субстанции огня, воды, земли и ветра." },
    ["5146c"] = { common = "Ты заслужил это искусство. Так получи же его! И кроме того, я буду тренировать тебя в будущем — и научу тебя чему смогу." },
    ["5147a"] = { common = "Разыскивается: Арнак Зловещий Тотэм. Арнак приговорён к смертной казни по многочисленным обвинениям в убийствах и похищениях. Достойная награда ждёт того, кто найдёт преступника и приведёт приговор в исполнение. Последний раз Арнака видели на утёсе близ Пика Тёмного Облака. Принесите доказательство его смерти стражу утёса Долгорогу на Заставу Вольного Ветра и получите свою награду." },
    ["5147c"] = { common = "Ха! Что ж, отличные новости! А я уж думал, его никогда не накажут. Держи награду... И большое спасибо. Признаться, меня приводили в ярость сообщения о его бесчинствах!" },
    ["5148a"] = { common = "Чтобы постичь школу традиций предков, следует обрести понимание подлинной сути дикой природы. Я знаю, что ты уже владеешь искусством изготовления дикарского кожаного доспеха, и хочу завершить твоё обучение. Знай, герой: избрав этот путь, ты отказываешься от изучения школ чешуи драконов и силы стихий, изучать можно только одну из них. А теперь принеси мне свои лучшие дикарские кожаные доспехи. С них мы и начнём твоё обучение." },
    ["5148c"] = { common = "Хорошо. Я дам тебе это знание… Не забывай заглядывать ко мне в дальнейшем… за рецептами…" },
    ["5151a"] = { common = "На наш караван напали кентавры, и выжить удалось только мне! А самый лучший мой механизм висел на шее могучей пантеры-охранницы! Даже кентавры дрожали, увидев эту зверюгу! Вот ключ от её клетки. Они забрали всё, а ключ оставили. Убей пантеру, принеси мне мой гипервместитель, а я хорошо заплачу за него. То, что осталось от нашего каравана, находится к северу отсюда." },
    ["5151c"] = { common = "Мой гипервместитель! Ну всё, теперь с места не сойду, пока не разберусь, зачем же эта штука нужна..." },
    ["5152c"] = { common = "Ты видел Памелу? Она жива? О, нет! Бедная моя девочка! Она была так мала, так весела и шаловлива… Она ведь не знает, что стало с её отцом? С моим братом Джозефом? Она едва ли сможет это понять… А даже если бы и могла, я не в силах сказать ей об этом." },
    ["5153a"] = { common = "Увы, Джозефу не дано воссоединиться с дочерью. Его душа была искажена Плетью, он сам стал чудовищем. Как жестока судьба! И всё же судьбу можно изменить. Отправляйся к его монументу и обыщи окрестные могилы. Тела самого Джозефа там нет, однако где-то под монументом лежит его обручальное кольцо. Отнеси кольцо Хроми. Это странная гномесса… с весьма странными способностями. Хроми живёт в развалинах таверны в северо-западной части Андорала." },
    ["5153c"] = { common = "Что это, обручальное кольцо? Дай-ка взглянуть… Когда-то оно принадлежало великому человеку, однако с ним связано великое зло… Ты хочешь помочь ему? Поздновато собрался, а впрочем… возможно, мы сможем изменить прошлое!" },
    ["5154a"] = { common = "Чтобы спасти Джозефа Редпата, придётся обратиться к его прошлому. Надо прочитать, что говорится о нём в Анналах Дарроушира — книге, хранящейся в ратуше Андорала. Принеси мне книгу. Мы узнаем о судьбе Джозефа и, если повезёт сможем… изменить её." },
    ["5154c"] = { common = "Прекрасно, ты нашёл её! Что в ней говорится? Там упоминается Джозеф Редпат? Если да, то мы сможем спасти его! О… В Анналах Дарроушира говорится, что во время битвы Джозеф Редпат пал жертвой порчи и примкнул к войскам Плети, предав защитников Дарроушира! Что за горькая судьба! Думаю, мы должны приложить все усилия, чтобы изменить её." },
    ["5155a"] = { common = "Если уж мне придётся положиться на тебя в этом деле, то прежде заслужи доверие. Я должна точно знать, что ты — враг Совета Теней, тех, кто в ответе за великие злодеяния здесь и за границами леса. Отправляйся в чащу Осквернённого леса. На западе ты увидишь тропинку в Джеденар. Именно там Совет строит свои козни вместе с Пылающим Легионом. Проникни в недра одной из населённых ими осквернённых Обителей и перебей их. Потом вернись ко мне. Тогда я увижу, что ты искренне помогаешь нам." },
    ["5155c"] = { common = "Хорошо, путник! Теперь, когда они понесли потери, мы можем развить успех. Как тебе первый вкус их сопротивления? Были ли они так сильны, как ты думал? Сильнее? Или ты разобрался с ними одной левой? Ладно, обговорим детали твоих… исследований позже. Сейчас есть другие вещи, на которых мы должны сосредоточиться." },
    ["5156a"] = { common = "На севере отсюда, если идти по восточной дороге, лежит так называемая долина Рваных Ран. Это то место, где во время последней великой войны призывали инферналов. Там до сих пор поганят землю кратеры — да и сами големы. Я хочу узнать две вещи. Во-первых, шляются ли там до сих пор эти энтропийные духи? И второе — до сих ли пор заполнены эти кратеры поганой вонючей водой, что скапливалась в них долгие годы? Поможешь ли ты мне это узнать, путник? Но будь осторожен — инферналы уничтожают всё на своём пути." },
    ["5156c"] = { common = "Хорошо что ты жив, путник. Плохо, что вода по прежнему загрязнена. Я хотел найти хотя бы один чистый источник в Осквернённом лесу, но похоже мой поиск закончился неудачей. Ах, восстановление этой земли пошло бы намного легче… Мне придётся ограничиться спасением тех лесных существ, которых ещё можно спасти, и уничтожением всех прочих…" },
    ["5157a"] = { common = "Глубоко в недрах Джеденара лежит Оплот Теней — главный оплот скверны и зла. Совет Теней окружил своё логово защитными заклятьями, заключёнными в жаровнях. Если уж мне выпала задача узнать побольше о нашем враге путём магического наблюдения, то тогда мне надо будет, чтобы кто-то потушил эти жаровни. Тогда я смогу тайно понаблюдать за Советом и выяснить, кто его возглавляет. Если сможешь — возьми эту флягу и наполни её водой из Лунного колодца в центре Джеденара. Потом вернись ко мне." },
    ["5157c"] = { common = "Ты меня порадовал, путник. Теперь для того чтобы залить жаровни, необходимо всего лишь очистить принесённую тобой воду. Это не трудно — придётся всего лишь немного попутешествовать. Надеюсь, что мы сможем сделать это быстро." },
    ["5158a"] = { common = "Отнеси эту осквернённую воду в Степи, путник. К югу от Кабестана на побережье скрытно живёт моя старая приятельница, шаманка по имени Ислен Заклинатель Воды. Она может нам помочь. Её узы с духами воды всегда были крепки. Веди себя благородно — и этого будет достаточно, чтобы убедить её и духов воды помочь нам в нашем деле. Ищи её в маленьком лагере прямо у кромки воды. А на пиратов, путник, внимания не обращай… это все мелочи жизни, тебе они не угроза." },
    ["5158c"] = { common = "А, тебе нужно очистить воду Лунного колодца. Остановить порчу в Осквернённом лесу — выглядит благородной целью, но не мне решать, будет ли очищена вода. Я должна поговорить с водяными духами. Им решать, правое ли это дело. Подожди немного, и я передам им твою просьбу. Надеюсь они отнесутся к ней с пониманием." },
    ["5159a"] = { common = "Благодари духов, путник. Это они, а не я, помогли тебе. Ныне я отдаю тебе эту очищенную воду. Передай Грете мой поклон и мои наилучшие пожелания. Она нащупала нечто более важное, чем сумели многие из нас… я уверена, что она вскоре всё узнает. С Советом Теней шутки плохи, путник. Запомни это. Теперь ступай. Бери воду и возвращайся к Грете." },
    ["5159c"] = { common = "Этого должно более чем хватить для наших целей. Я рада слышать, что Ислен смогла нам помочь. Её связь с духами воды всегда была сильной. Она также мудра и очень редко случается, что духи не согласны с её намерениями. Факт того, что и те другие благословили нашу миссию даёт мне надежду, что мы на верном пути" },
    ["5163a"] = { common = "Всё готово, путник! Итак, я уже сообщила по почте моим друзьям, что у меня для них сюрприз. И тут на сцену выходишь ты! Я дам тебе моего механического йети, а тебе нужно будет удивить их, нанеся визит каждому, включив йети и послав его по направлению к ним. Когда покажешь моё изделие Легакки в Круговзоре, Поливалке в Прибамбасске и Квикксилю в Укрытии Маршалла, возвращайся и расскажи мне, как всё было! И моего йети тоже, пожалуйста, приведи обратно." },
    ["5163c"] = { common = "Ха! Теперь они подумают дважды, прежде чем сделать что-то мне! Спасибо за помощь, путник. Я бы не смогла так повеселиться без тебя." },
    ["5164c"] = { common = "Книга состоит по большей части из сотен страниц, исписанных словами и символами." },
    ["5165a"] = { common = "Теперь тебе надо вернуться в Джеденар. Эти жаровни скорее всего расставлены в Оплоте Теней. Загаси их пламя, и защита, возведённая Советом, хотя бы на некоторое время падёт. Я буду ждать этого мгновения. Когда оно настанет, я загляну в недра оплота и попытаюсь узнать, кто стоит во главе всего этого. Тогда — и только тогда — мы попытаемся атаковать их напрямую." },
    ["5165c"] = { common = "Я смогла увидеть тебя как только пламя последней жаровни погасло, путник. Я узнала кое-что про Совет Теней, пока их колдуны не опомнились. Надеюсь, этого будет достаточно. А теперь, отдыхай. Я скажу тебе, когда ты понадобишься!" },
    ["5166a"] = { common = "По иронии судьбы, на изготовление мощной кирасы, призванной защитить от нападения всецветных драконов, идут их собственные шкуры. На безупречную шкуру всецветного дракона нашивают их же чешую. В настоящий момент этих тварей не существует, и хочется верить, что и не будет. Последний компонент, который труднее всего достать — это кровь героев. И наконец, из этих компонентов Скульптор создаёт подлинный шедевр." },
    ["5167a"] = { common = "На изготовление этих поножей идут чешуйки взрослых всецветных драконов. Переливчатую чешую закрепляют на проволочной основе и зачаровывают, окропляя кровью героев. В конце следует обтянуть поножи изнутри Шкурой Тени." },
    ["5168a"] = { common = "Герои Дарроушира навсегда поселились в моём сердце, а эта книга, Анналы Дарроушира, рассказывает об их жизни. Здесь рассказывается о паладине Дейвиле Яркосвете и о том, как Алый Марш забрал его манускрипт в ратушу Дольного Очага. Здесь также говорится о моём брате, капитане Редпате. После его предательства, его щит раскололся и развалился на куски, и теперь лежит в самом неожиданном месте — рядом с амбаром в пустоши Гаррона. Собери эти реликвии, путник." },
    ["5168c"] = { common = "Это книга и щит! Они тесно связаны с историей Дарроушира, и я уверен — эта история ещё не закончена." },
    ["5181a"] = { common = "В Анналах Дарроушира упоминается о самых мерзких воинах, бившихся в том сражении. Там рассказывается о том, как Альянс разбил силы лорда Хоргуса Опустошителя. Тело его было брошено в озеро к северу от Перекрёстка Корина, и череп его поныне там. Мардук Чёрный так и не был побеждён, но его легендарный меч был сломан и потерян. Он лежит на дне ущелья к западу от Перекрёстка Корина. Принеси мне эти предметы, путник. Не знаю почему, но твоя судьба связана с ними." },
    ["5181c"] = { common = "Ты нашёл их! Прекрасно, путник! В этих предметах заключена великая сила, и однажды ты сможешь овладеть ею. Однако они навевают на меня печальные воспоминания о потерянных близких и о предательстве…" },
    ["5202a"] = { common = "Маленький красный ключ сделан из какого-то материала, похожего на кость. Он тяжёл, но на вид кажется хрупким. Зачем прислужнику Совета Теней этот предмет? Возможно, этот странный ключ открывает какой-то замок в Джеденаре?" },
    ["5202c"] = { common = "Ты нашёл ключ! Умоляю отдай его мне, чтобы я наконец смогла спастись!" },
    ["5203a"] = { common = "Но, как бы мне это ни было тяжко, в первую очередь мне нужно сделать вот что: найти меч Трея, именуемый Светлая Сталь и сбежать из Оплота Теней, чтобы рассказать моим командирам, что здесь творится. Ты поможешь мне, путник? Наше снаряжение тут неподалёку, а ты уже показал, что сумеешь выбраться наверх. Когда мы выберемся отсюда, я направлюсь в Дарнасс, если ты сможешь найти мою подругу Джессиру на границе с Ясеневым лесом. Она должна была встретить нас у лагеря Изумрудного Круга неподалёку отсюда. Что скажешь, путник? Поможешь мне ещё раз?" },
    ["5203c"] = { common = "Ты тот, кто помог Арко сбежать? Я так рада, что ты меня нашёл. Она проходила мимо не так давно по пути в Дарнасус. Она тащила Светлую Сталь на плече, и она не потратила время даже на то, чтобы поговорить с друидами о своём лечении. Она сказала что дело слишком срочное. Но она рассказала мне о вашей встрече с духом Трея. Что за ужасная судьба для Рыцаря Серебряной Длани. Она не показывала этого, но я знаю, что это терзает её изнутри — мысль о потере одного из ближайших друзей." },
    ["5204a"] = { common = "Она делает вид, что с ней всё в порядке. Ей хочется, чтобы я думала, будто она сама сумеет справиться, но я же не слепая. Смерть Трея и его крики под пытками, которым его подвергали, долго мучили её, и мы ничем не могли ей помочь. Но мы всё же можем дать ей хоть немного покоя! Путник, вернись в Оплот Теней, убей мучителя Трея и найди его останки. Почему бы нам самим не покончить с этим, пока Арконарин плачет в глубине души?" },
    ["5204c"] = { common = "Вы собираете останки паладина в мешок, так аккуратно и почтительно, как только можете. Вам становится жалко его. Но он уже теперь в лучшем мире, и хотя бы дух его сможет упокоиться, отдыхая от боли и страданий, перенесённых им." },
    ["5206a"] = { common = "Хроми утверждает, что собранные тобой реликвии могут служить ингредиентами для мощных чар. Однако требуется ещё один ингредиент: черепа воинов Плети, участвовавших в битве при Дарроушире. Возьми этот кристалл и отправляйся за черепами лучших воителей Плети. Кристалл заколдован: он резонирует, если поднести его к черепу воителя, участвовавшего в битве. Иди, путник. Ты найдёшь воителей Плети на Ядовитой поляне к северу отсюда и в Грибной долине на западе." },
    ["5206c"] = { common = "Ты нашёл их! Чудесно! Я ещё толком не понимаю, как они могут помочь нам в нашем деле, но я чувствую их силу и я знаю что они как-то связаны с моей родной деревней Дарроушир." },
    ["5210a"] = { common = "С помощью магии я дополнила Анналы Дарроушира — теперь они содержат сведения и о том, что случилось после битвы. И там говорится, что ещё один из рода Крассенов пережил предательство Джозефа. Его имя Карлин, он сейчас в восточных пределах Чумных земель, в Часовне Последней Надежды. Отправляйся к нему и передай ему книгу." },
    ["5210c"] = { common = "Что это за книга такая? Анналы Дарроушира? Там был мой дом, до войны… До битвы, что разрушила там всё… Зачем ты принёс мне эту книгу? Но что это в ней? Тут есть описание того что случилось после битвы… даже про меня написано… и моего брата Джозефа! Но правда ли это? Нам надо узнать настоящую правду!" },
    ["5211a"] = { common = "Многие защищавшие Дарроушир пали в битве. И многие из них восстали из мёртвых, примкнув к Плети! Ты должен отыскать эти несчастные души и избавить их от страданий. Каннибалы-вурдалаки, бормочущие вурдалаки, болезненные живодёры — многие из них были добрыми жителями Дарроушира. Уничтожив их тела, ты освободишь их души. Ты найдёшь их в Проклятом лесу, Перекрёстке Корина и прочих опорных пунктах Плети в Восточных Чумных землях." },
    ["5211c"] = { common = "Рад слышать, что истерзанные души моих сородичей с твоей помощью обрели свободу. Ты пролил бальзам на мои раны — теперь я знаю, что хоть кто-то из моих павших сородичей освободился от ига Плети." },
    ["5212a"] = { common = "Аптекари Отрекшихся не единственные в этом мире, кто искушён в науках. Я уже много лет изучаю эту заразу, странник. Ранее я полагала, что активность чумы со временем уменьшается, однако то, что наблюдается в Чумных землях, поражает воображение. Здесь вирус со временем становится всё более активным! Я должна продолжать исследования! Вирус наиболее активен в первые дни после заражения, поэтому мне нужны образцы тканей, поражённых совсем недавно. Отправляйся в Стратхольм и снабди меня препаратами для исследований, путник." },
    ["5212c"] = { common = "В химическом составе вируса произошли какие-то изменения. Я должна продолжать исследования." },
    ["5213a"] = { common = "Тебе предстоит углубиться ещё дальше в кварталы Стратхольма, путник. За первыми воротами ты увидишь зиккураты. Известно, что твари Плети черпают из этих сооружений великую силу. Обыщи зиккураты и расскажи мне обо всём, что там увидишь." },
    ["5213c"] = { common = "Потрясающе! Теперь я должна как следует изучить эти данные — это может потребовать нескольких месяцев. Серебряный Рассвет приносит тебе огромную благодарность, путник. Тебе будет дарована печать Рассвета или руна Рассвета на твой выбор. И то, и другое можно использовать вместо Жетона Серебряного Рассвета для сбора знаков различия Плети. Если потеряешь, обращайся ко мне за заменой." },
    ["5214a"] = { common = "То, что произошло с Фрасом, поистине ужасно! Город осаждала нежить, но Фрас не хотел бросать свою лавку превосходного табака. Последнее, что он сказал мне: \"Я не уйду, пока не сожгу всё до последнего листочка, чтобы ничего не осталось врагу!\" Я тоже знаю толк в хорошем табаке, но не готов расстаться с жизнью ради каких-то сушёных листьев, пусть и наивысшего качества. Хотя… может там и вправду что-то уцелело? Что скажешь, путник? Не поищешь табачку для старины Дымка?" },
    ["5214c"] = { common = "О, мои милые папироски, как я по вам скучал…" },
    ["5215a"] = { common = "В пределах бывшего Лордерона спрятано восемь котлов — четыре здесь, на западе, и ещё четыре — на востоке. Они испускают ядовитые пары, распространяя чуму нежити по всей земле на радость Плети. Кел'Тузад слишком силён, чтобы взять да и угасить пламя под этими котлами, но, быть может, мы сможем придумать способ использовать их для собственной выгоды. Моя помощница, верховная жрица Макдонелл, поможет тебе выполнить задание; она продолжит инструктаж." },
    ["5215c"] = { common = "Да осияет тебя Свет в наши тёмные времена, герой. Я рада, что смогу помочь тебе в борьбе с планами Плети. Наша цель — таким образом изменить состав яда в котлах, чтобы он стал погибелью приспешников Плети. Для этого придётся взять пробы из всех котлов в Западных Чумных землях. Готовься к славной битве против жестокой Плети!" },
    ["5216a"] = { common = "Из четырёх котлов Западных Чумных земель проще всего подобраться к тому, что в поле Джанис. Его охраняют менее опытные воины Плети, хотя не стоит их недооценивать. Отправляйся на поле Джанис, что на востоке отсюда и на северо-западе от Андорала, и вступи в схватку с тамошним Хранителем котла. У него есть ключ, который даст доступ к котлу. Отперев панель доступа, набери в бутылку образец ядов из котла; они понадобятся нам, чтобы подобрать противодействующие вещества." },
    ["5216c"] = { common = "Ключ, который вы забрали у Хранителя котла Желчня, входит в замочную скважину и немедленно исчезает. И всё же, кажется, отныне вы сможете открывать панель доступа без ключа. Изнутри доносится гнусный запах. В котле бурлит смесь неизвестных веществ. Бутылка отлично помещается под небольшой кран, так что набрать в неё образец яда для верховной жрицы Макдонелл с Берега Промозглого Ветра не составляет труда." },
    ["5217a"] = { common = "Вы наполняете бутыль из котла ядовитой жижей. Вроде бы должно хватить. Заполучив яд, пора возвращаться к верховной жрице Макдонелл в лагерь Промозглого Ветра." },
    ["5217c"] = { common = "Молодец, путник! Алхимик Арбингтон мигом проведёт анализ этой дряни и составит противодействующее вещество. Надо будет внести его в котёл и постараться, чтобы побольше испарений попало в воздух. Кто знает, может удастся ослабить Плеть. Это будет нелегко — придётся постоянно устраивать набеги на котлы и добавлять в них необходимые реагенты. И всё же у нас есть шанс получить в решающей битве преимущество перед Плетью!" },
    ["5219a"] = { common = "Один из чумных котлов расположен на поле бывшей фермы, которую ныне зовут Слёзы Далсона. Но сегодня не время лить слёзы, герой. Мы должны нанести удар по котлу и получить к нему доступ! Отправляйся в Слёзы Далсона, к северу от Андорала, и убей Хранителя котла. Забери у него ключ, как и в прошлый раз и получи доступ к самому котлу. Наполни эту бутылку ядом, ведь в каждом из котлов бурлят свои яды." },
    ["5219c"] = { common = "Неприятного вида ключ, найденный в останках Хранителя котла, легко входит в замочную скважину и исчезает. Вы получили постоянный доступ к котлу. По переплетённым трубкам течёт гнусная тягучая жижа. Бутылка отлично помещается под небольшой кран, так что набрать в неё образец яда для верховной жрицы Макдонелл с Берега Промозглого Ветра не составляет труда." },
    ["5220a"] = { common = "Вы наполняете бутыль из котла зловонной жижей. Вроде бы должно хватить. Заполучив яд, пора возвращаться к верховной жрице Макдонелл в лагерь Промозглого Ветра." },
    ["5220c"] = { common = "А, мне будет чем заняться. Молодец, путник! Итак, следующий шаг ясен. Мы должны составить список компонентов, которые будет необходимо смешать с зельем чумы, чтобы добиться от него обратного действия. Для этого придётся поместить эти составляющие непосредственно в котёл. Алхимик Арбингтон знает гораздо больше чем я, поэтому в ближайшее время поговори с ним." },
    ["5222a"] = { common = "Тебе удалось открыть уже два котла; теперь у тебя к ним неограниченный доступ, но остаётся ещё два! Если справиться и с ними, то у нас будет больше шансов успешно внести противодействующее вещество! На сей раз твоя цель — котёл Удела Страданий. Он совсем рядом с разрушенными стенами Андорала, чуть восточнее. И вновь тебе придётся убить Хранителя котла и забрать у него ключ. Наполни эту бутылку из котла. Доброй охоты, путник!" },
    ["5222c"] = { common = "Коснувшись панели доступа, ключ Хранителя котла исчезает, как и в прошлый раз. Внутри бурлит омерзительно пахнущая жидкость. Бутылка отлично помещается под небольшой кран, так что набрать в неё образец яда для верховной жрицы Макдонелл с Берега Промозглого Ветра не составляет труда." },
    ["5223a"] = { common = "Вы аккуратно закручиваете бутылку. Образец гнусной жижи, бурлящей в котле, плещется в хрупкой стеклянной оболочке. Заполучив яд, пора возвращаться к верховной жрице Макдонелл в Лагерь Промозглого Ветра." },
    ["5223c"] = { common = "Ещё одно задание выполнено без сучка, без задоринки! Итак, у нас есть доступ вот уже к трём котлам! Если бы не страшная некромантская власть Кел'Тузада в этих землях, я бы сказала, что нам удастся полностью нейтрализовать их! Алхимик Арбингтон вскоре сообщит, что требуется добавить в этот котёл — и другие, подвластные нам — чтобы справиться с чумой нежити. Итак, настало время добраться до последнего из западных котлов!" },
    ["5225a"] = { common = "Последний оставшийся котёл находится на ферме, которая теперь зовётся пустошью Гаррона. Его охраняют сильные прислужники Плети, по большей части призраки и духи. С ними шутки плохи, путник. Пустошь Гаррона находится далеко на востоке от Бастиона, близко от границы Восточных Чумных земель. И вновь тебе придётся убить Хранителя котла и забрать у него ключ. Вот, возьми эту пустую бутылку, заполни её из котла и принеси мне. Да укроет тебя тьма своим крылом, герой." },
    ["5225c"] = { common = "Коснувшись панели доступа у основания, ключ Хранителя котла Душегнева исчезает. Раздаётся негромкий щелчок, и панель распахивается, открывая доступ к зловредным ядам. Бутылка отлично помещается под небольшой кран, так что набрать в неё образец яда для верховной жрицы Макдонелл с Берега Промозглого Ветра не составляет труда." },
    ["5226a"] = { common = "Вы тщательно перекрываете кран на панели управления, и остатки гнусной жижи медленно стекают в пустую бутылку. Заполучив яд, пора возвращаться к верховной жрице Макдонелл в Лагерь Промозглого Ветра." },
    ["5226c"] = { common = "Поздравляю, путник, тебе удалось обеспечить нам доступ к последнему из котлов! Алхимик Арбингтон вскоре составит список компонентов, которые необходимо добавить в него. Что до тебя, я не сомневаюсь, что командир Смелонрав пожелает лично поблагодарить тебя за помощь. Без тебя наша борьба с Плетью была обречена. Спасибо, ты настоящий герой." },
    ["5228a"] = { common = "В пределах бывшего Лордерона спрятано восемь котлов — четыре здесь, на западе, и ещё четыре — на востоке. Они испускают ядовитые пары, распространяя чуму нежити по всей земле на радость Плети. Кел'Тузад слишком силён, чтобы взять да и угасить пламя под этими котлами, но, быть может, мы сможем придумать способ использовать их для собственной выгоды. Моя помощница, жрица Тени Вандис, поможет тебе выполнить задание; она продолжит инструктаж." },
    ["5228c"] = { common = "Я радуюсь твоему успеху, брат странник. Молодец. Никто кроме тебя не смог бы так ловко обработать котлы Плети. Наша задача — нейтрализовать контрагентами ту заразу, что разносят эти котлы. Для этого тебе понадобится получить доступ к каждому из четырёх котлов в Западных Чумных землях. Время выступить против Чумы, герой." },
    ["5229a"] = { common = "Из четырёх котлов Западных Чумных земель проще всего подобраться к тому, что в поле Джанис. Его охраняют менее опытные воины Плети, хотя не стоит их недооценивать. Отправляйся на поле Джанис, что на востоке отсюда и на северо-западе от Андорала, и вступи в схватку с тамошним Хранителем котла. У него есть ключ, который даст доступ к котлу. Отперев панель доступа, набери в бутылку образец ядов из котла; они понадобятся нам, чтобы подобрать противодействующие вещества." },
    ["5229c"] = { common = "Ключ, взятый с хранителя котла Желчня прекрасно подходит к панели доступа. И он исчезает после того как панель с мягким щелчком открывается, давая вам доступ внутрь. Преодолевая отвращение от содержимого котла вы предельно осторожно подносите бутылочку к штуцеру… Проба взята и пора вернуться к жрице Тени Вандис в Бастион. Чем меньше вы будете находиться наедине с этим ядом, тем лучше." },
    ["5230a"] = { common = "Вы наполняете бутыль из котла ядовитой жижей. Вроде бы должно хватить. Заполучив яд, пора возвращаться ко жрице Тени Вандис в Бастион." },
    ["5230c"] = { common = "Отлично сработано, путник — теперь наш аптекарь Дитерс сможет изучить то, что есть в этой тяжёлой отравляющей жидкости, которая плескалась в котле. Нет сомнений в том, что нам придётся постоянно \"навещать\" котлы чтобы добавить наши реагенты в их смесь. Но если мы будем делать это достаточно долго, мы получим преимущество над Плетью, когда придёт время для битвы с ней!" },
    ["5231a"] = { common = "Один из чумных котлов расположен на поле бывшей фермы, которую ныне зовут Слёзы Далсона. Но сегодня не время лить слёзы, герой. Мы должны нанести удар по котлу и получить к нему доступ! Отправляйся в Слёзы Далсона, к северу от Андорала, и убей Хранителя котла. Забери у него ключ, как и в прошлый раз и получи доступ к самому котлу. Наполни эту бутылку ядом, ведь в каждом из котлов бурлят свои яды." },
    ["5231c"] = { common = "Ключ к котлу, найденный на мерзком зловонном теле хранителя-ключника открывает панель и исчезает, позволяя вам видеть внутренности котла. Ужасная даже на вид жидкость кипит и бурлит там, создавая завихрения и водовороты. Через маленький штуцер, стараясь не дышать вы наполняете бутылку и с ней в руках отправляетесь назад к жрице Тени Вандис в Бастион." },
    ["5232a"] = { common = "Вы наполняете бутыль из котла зловонной жижей. Вроде бы должно хватить. Заполучив яд, пора возвращаться ко жрице Тени Вандис в Бастион." },
    ["5232c"] = { common = "А, тут достаточно яда для изучения. Хорошая работа, путник! Теперь нам надо произвести реагенты, которые будучи введёнными в котёл, произведут действие, обратное тому, которое производит яд. К сожалению, у нас нет иного пути, кроме как бросать эти реагенты прямо в котёл. Аптекарь Дитерс знает об этом больше, так что поговори с ним так быстро как только сможешь." },
    ["5233a"] = { common = "Тебе удалось открыть уже два котла; теперь у тебя к ним неограниченный доступ, но остаётся ещё два! Если справиться и с ними, то у нас будет больше шансов успешно внести противодействующее вещество! На сей раз твоя цель — котёл Удела Страданий. Он совсем рядом с разрушенными стенами Андорала, чуть восточнее. И вновь тебе придётся убить Хранителя котла и забрать у него ключ. Наполни эту бутылку из котла. Доброй охоты, путник!" },
    ["5233c"] = { common = "Ключ лорда-ключника легко входит в контрольную панель этого котла и потом исчезает без следа, как и те ключи, которые вы использовали ранее. Вонючая и грязно-опалесцирующая жидкость светится в котле. Вам даже не хочется думать о том, что там плавает. Через маленький штуцер вы набираете в бутылку достаточно жидкости чтобы принести её к жрице Тени Вандис, которая ждёт вас в Бастионе." },
    ["5234a"] = { common = "Вы аккуратно закручиваете бутылку. Образец гнусной жижи, бурлящей в котле, плещется в хрупкой стеклянной оболочке. Заполучив яд, пора возвращаться ко жрице Тени Вандис в Бастион." },
    ["5234c"] = { common = "Ещё одна прекрасно исполненная миссия, путник! Это позволит нам взять под свой контроль уже три котла! И если бы не этот чёртов некромант Кел'тузад, я бы сказала что мы уже побеждаем. Аптекарь Дитерс сообщит какие контр-реагенты требуются для этого котла. А наша новая цель — последний котёл на западе." },
    ["5235a"] = { common = "Последний оставшийся котёл находится на ферме, которая теперь зовётся пустошью Гаррона. Его охраняют сильные прислужники Плети, по большей части призраки и духи. С ними шутки плохи, путник. Пустошь Гаррона находится далеко на востоке от Бастиона, близко к границам Восточных Чумных земель. И вновь тебе придётся убить Хранителя котла и забрать у него ключ. Вот, возьми эту пустую бутылку, заполни её из котла и принеси мне. Да укроет тебя тьма своим крылом, герой." },
    ["5235c"] = { common = "Ключ самоуничтожился, когда вы открыли им панель управления на платформе где установлен котёл. Слабый назойливый шум издаёт работающий котёл. Вам даже не хочется думать что за токсины там бурлят. На панели управления котлом есть штуцер через который вы отбираете пробу чтобы жрица Тени Вандис в Бастионе могла её исследовать." },
    ["5236a"] = { common = "Вы тщательно перекрываете кран на панели управления, и остатки гнусной жижи медленно стекают в пустую бутылку. Заполучив яд, пора возвращаться к жрице Тени Вандис в Бастион." },
    ["5236c"] = { common = "Поздравляю тебя, путник, ты открыл последний котёл для нас! Аптекарь Дитерс уже потирает свои руки в нетерпении — так хочется ему открыть последний реагент. Что до тебя, я просто уверена, сам верховный палач Деррингтон пожелает поблагодарить тебя лично за все твои жертвы которые ты принёс ради великого дела! Я тоже благодарю тебя, могучий герой." },
    ["5237c"] = { common = "Путник, твоё успешное завершение заданий по котлам, является огромной победой для нас. Пусть все услышат о твоих деяниях! За твою службу Отрекшимся и Орде, я выражаю тебе огромную благодарность, путник, как истинному герою Орды!" },
    ["5238c"] = { common = "Путник, твоё успешное завершение заданий по котлам, является огромной победой для нас. Пусть все услышат о твоих деяниях! За твою службу королевству Штормград и всему Альянсу, я выражаю тебе огромную благодарность, путник, как истинному герою Альянса!" },
    ["5241c"] = { common = "Ты видел Памелу? Она жива? Погибла?! Бедная моя девочка! За что твой дух осуждён скитаться в этом жестоком мире… Почему тебя не стало во цвете лет, а я всё ещё копчу небо! Как бы я хотел вместо тебя отдать жизнь и призраком бродить по руинам Дарроушира! Судьбу не изменить… Спасибо тебе, путник. Теперь мой долг — месть, я осознаю это ясно как никогда." },
    ["5242a"] = { common = "Увы, я вижу только один путь покончить с угрозой Осквернённому лесу — прямую атаку. Других путей в Оплот Теней нет, телепортировать тебя внутрь я тоже не могу. Единственный путь — прямой путь в бездну… и я также знаю, кого тебе следует искать в этой бездне. Его зовут Скверн'дан… Владыка теней Скверн'дан. Его власть там, внизу, смертоносна… Он — голова змеи. Убей его и двух его суккубов-прислужниц, и вернись ко мне. Это Скверн'дан заключил союз с Легионом. Его надо остановить!" },
    ["5242c"] = { common = "Мать-земля будет тобою довольна, путник! Совет Теней нескоро восстановит свои силы после удара, который ты нанёс сегодня. Ты можешь гордиться собой!" },
    ["5243a"] = { common = "Я склонен рассматривать своё бытие в форме нежити как род болезни, странник. Болезни, которая требует лечения. Впрочем, для Серебряного Рассвета это не болезнь, а истинное благословение. Действительно, нет лучше орудия против язычников Плети, чем нежить. Коллеги чтят меня за мои деяния, однако почести ничего не значат для меня. Если ты хочешь содействовать делу Серебряного Рассвета, у меня есть для тебя работа. Отправляйся в Стратхольм и пополни наши запасы святой воды. Искать её следует в брошенных ящиках с припасами." },
    ["5243c"] = { common = "Отлично, странник. Ты доказал, что терпим к ближнему и непримирим в борьбе против приспешников Кел'Тузада." },
    ["5244a"] = { common = "История Кел'Терила — это история проклятой расы, прикованной к месту, где был совершён неудавшийся ритуал… Высокорождённые, которых вы найдёте там, когда-то похитили священный артефакт, будучи уверенными, что смогут вытянуть его мощь, перелить её в себя и стать ещё более могущественными. Из-за их действий реликвия взорвалась, а куски её ушли под лёд озера… Если хотите узнать больше, поговорите с Джероном Гранильщиком. Он был там недавно и сможет рассказать вам обо всём." },
    ["5244c"] = { common = "Ну, конечно, я могу подробно рассказать про Кел'Терил. Имей в виду, я не историк — но могу рассказать тебе о том, что я сам там видел…" },
    ["5245a"] = { common = "Несчастные существа эти духи высокорожденных, что и говорить. Они всё ещё ищут части самой вещи, которая навсегда привязала их к Кел'Терилу, эту похищенную у них реликвию. Если тебе это интересно, можешь взять мою кирку и отправляться на юг к озеру, чтобы попытаться достать части этого артефакта изо льда. Я не могу сказать что именно ты найдёшь, но Аврора Зов Небес наверняка сможет; она живёт около башни Северного Перевала в северной части Восточных Чумных земель." },
    ["5249a"] = { common = "В Зимних Ключах, к северу отсюда, много древних эльфийских руин. Это суровая земля, но она хранит множество секретов, и там есть места, которые стоят изучения. Работа здесь отнимает всё моё время, так что у меня давно уже не было возможности самой добраться до Зимних Ключей. Но вам-то ничто не мешает! Когда будете там, поищите Вунда Ночного Охотника. Большую часть времени он проводит в деревне Звездопада и очень много знает о тех местах." },
    ["5249c"] = { common = "Друг Иви Росистой Листвы? Приятно познакомиться, путник." },
    ["5250a"] = { common = "В Зимних Ключах, к северу от Осквернённого леса, много древних эльфийских руин. Это суровая земля, но она хранит множество секретов, и там есть места, которые стоят изучения. Я так занята своими исследованиями здесь, что у меня давно уже не было возможности самой добраться до Зимних ключей. Но у вас-то нет никаких причин для отказа от путешествия туда и изучения руин. Когда будете там, поищите Вунда Ночного Охотника. Большую часть времени он проводит в Звездопаде и очень много знает о том районе. Скажите ему, что вы мой ученик." },
    ["5250c"] = { common = "Ученик Дарин Доброго Ветра? Приятно познакомиться с вами, путник." },
    ["5251a"] = { common = "Впадать в крайности всегда опасно, путник. Взять, к примеру, Алый орден. Неужели такой слепой фанатизм способен привести к чему-то хорошему? Скольких невинных убили они во имя Света. Это просто святотатство! Вот что, один из этих негодяев мне особенно интересен — это архивариус Галфорд из Стратхольма. Этот человек отвечает за самые ценные документы ордена. Уничтожь его и сожги его архивы! Если справишься с этим, получишь достойную награду." },
    ["5251c"] = { common = "Отличная работа, путник! Ты уничтожил разведданные, собираемые Алым орденом годами! Алые будут в ярости…" },
    ["5252c"] = { common = "Это то… что я думаю?" },
    ["5253a"] = { common = "Впечатляюще, путник. Кристалл Зин-Малора никогда не вернётся в храм, лежащий в руинах. Но я полагаю, что твои усилия уничтожить зло минувших лет не должны пойти прахом. Найди верховного друида Фэндрала Олений Шлем в Дарнасе, путник, и отдай ему кристалл. Он должен находится в руках тех, кто не злоупотребит его мощью. К тому же только самые сильные маги смогут управиться с артефактом такой мощи." },
    ["5253c"] = { common = "Да, я слышал про Кристалл Зин-Малора; тот, кто воспользуется этим кристаллом, будет обладать могущественной тайной энергией. Однако я настоятельно тебе не рекомендую пользоваться кристаллом самому. И спасибо тебе за то что принёс его ко мне, путник. Мы будем держать его в безопасности и может быть проклятые души наконец-то обретут покой." },
    ["5261a"] = { common = "Иган Меховщик ищет охотника на волков. Это добрая новость, поскольку в последнее время в Долине Североземья звери уж чересчур расплодились. Если тебе это интересно, то поговори с Иганом. Он за углом аббатства, если свернуть налево." },
    ["5261c"] = { common = "Что? Ищу ли я охотников на волков? Ну да, так и есть. А ты, наверное, ищешь работу?" },
    ["5262a"] = { common = "В воздухе ещё вихрится пыль, а вы пытаетесь собраться с мыслями и осознать произошедшее. И всё же весь ужас вашего положения не укладывается в голове. Верховный рыцарь оказался демоном! И не просто демоном, а братом самого Вариматраса, верховного правителя Подгорода. Вы бережно укладываете голову повелителя ужаса в суму. Разумеется, никто не поверит рассказанному вами без вещественных доказательств. Надо сообщить герцогу Николасу Зверенхоффу как можно скорее!" },
    ["5262c"] = { common = "Неужели всё это время Алым Маршем правил демон! Всё это время они служили злу, сами не подозревая об этом!" },
    ["5263a"] = { common = "Ты проявил прирождённую склонность к разрушению и умеешь следовать приказам. Эти похвальные качества весьма редко сочетаются. Полагаю, ты можешь стать совершенным орудием высшего промысла. Кел'Тузад усадил своего мальчика на побегушках править в Стратхольме. Докажи мне свою верность и доблесть. Уничтожь барона Ривендера и принеси мне его голову." },
    ["5263c"] = { common = "Прошло немало времени, с тех пор, как я видел рыцаря, равного силою тебе! Ты будешь первым удостоенным аудиенции с лордом Максвеллом за многие годы." },
    ["5264a"] = { common = "Тебе оказана большая честь, путник. Лорд Максвелл хочет наградить тебя за твои заслуги перед Серебряным Рассветом! Поверь мне, это большая честь — Максвелл уже много лет не удостаивал никого аудиенции." },
    ["5264c"] = { common = "Ты неплохой союзник, путник. Ты должен пожать плоды своей непоколебимой преданности." },
    ["5265a"] = { common = "Серебряный Оплот уже много лет закрыт и запечатан. Много лет не находилось достойных войти в него и прикоснуться к силе Серебряного Рассвета — до сегодняшнего дня. Серебряный Оплот распахнул врата перед тобой, путник." },
    ["5265c"] = { common = "Ого…" },
    ["5281a"] = { common = "Многие погибли во время битвы при Стратхольме. Многие предпочли расстаться с жизнью, бросившись в пламя пожара, чем подвергнуться порче и примкнуть к Плети. Теперь они скитаются по улицам Стратхольма в обличье бесплотных призраков. Мы должны помочь им, путник. У меня есть помощник по имени Эган, он спец по призракам и духам. Найди его. Он, вероятно, сейчас в Восточных Чумных землях близ Стратхольма, проверяет свои изобретения." },
    ["5281c"] = { common = "Неужели Ален нашёл кого-то, у кого будет довольно храбрости помочь мне?" },
    ["5282a"] = { common = "Только безграничная ненависть к Плети поддерживает во мне силы и желание жить. Но я не фанатик. Не такой, как этот сброд из Алого ордена — они скорее убьют невинную нежить, чем удостоят хоть каплей сочувствия. Возьми мой излучатель. С его помощью ты сможешь освободить истерзанные души, обречённые на скитания в Стратхольме. Стреляй в призраков, бродящих по улицам. Освободи их!" },
    ["5282c"] = { common = "Путник, ты видел мою маму? Ты освободил её? Ты яркий пример порядочности…" },
    ["5283a"] = { male = "Ты принял верное решение. Мы со стариной Железнусом друг друга не перевариваем. Этот кустарь косорукий знает, кто тут настоящий мастер. Великие войны не выигрываются без хорошего доспеха. Когда дойдёт до дела, никакой меч не спасёт. И никак иначе, так что возьмёмся-ка за работу. Тебе нужно только показать мне, что у тебя есть природный талант к делу. Потом я выкую из тебя настоящего бронника и как следует отшлифую. Знаешь, как делать узорчатый мифрил, а?", female = "Ты приняла верное решение. Мы со стариной Железнусом друг друга не перевариваем. Этот кустарь косорукий знает, кто тут настоящий мастер. Великие войны не выигрываются без хорошего доспеха. Когда дойдёт до дела, никакой меч не спасёт. И никак иначе, так что возьмёмся-ка за работу. Тебе нужно только показать мне, что у тебя есть природный талант к делу. Потом я выкую из тебя настоящего бронника и как следует отшлифую. Знаешь, как делать узорчатый мифрил, а?" },
    ["5283c"] = { male = "Самое оно. Теперь уж нельзя останавливаться. Нет, ещё не поздно перейти на отковку шпилек, э-э-э, в оружейники податься. Но я уверен, что ты сделал верный выбор.", female = "Самое оно. Теперь уж нельзя останавливаться. Нет, ещё не поздно перейти на отковку шпилек, э-э-э, в оружейники податься. Но я уверен, что ты сделала верный выбор." },
    ["5284a"] = { male = "Если станешь кузнецом, то к тебе очень часто будут обращаться за снаряжением всякие там герои и искатели приключений. Хотя порой работы невпроворот, спина ноет и дышать нечем, плата покрывает всё с лихвой. Да, вот ещё, у кузнецов всегда водится золотишко! Если хочешь стать одним из нас, тебе придётся доказать, что ты сможешь заработать для меня пару звонких монет – то есть показать, что ты усвоил всё, чтобы стать специалистом по изготовлению оружия высшего качества. Приступай к работе!", female = "Если станешь кузнецом, то к тебе очень часто будут обращаться за снаряжением всякие там герои и искатели приключений. Хотя порой работы невпроворот, спина ноет и дышать нечем, плата покрывает всё с лихвой. Да, вот ещё, у кузнецов всегда водится золотишко! Если хочешь стать одной из нас, тебе придётся доказать, что ты сможешь заработать для меня пару звонких монет – то есть показать, что ты усвоила всё, чтобы стать специалистом по изготовлению оружия высшего качества. Приступай к работе!" },
    ["5284c"] = { common = "Как раз вовремя! Заказчики уже ждут. Давай сюда свои изделия да слушай внимательнее. Сейчас ты делаешь первый шаг в карьере оружейника." },
    ["5301a"] = { male = "Моя работа приносит мне подлинное удовлетворение! Когда я вижу гордого воина Орды, защищённого моими доспехами, я понимаю, зачем родился на свет. Это как наваждение, я без этого просто жить не могу. Конечно, этому я тебя научить не смогу – я могу только указать тебе путь. Ведь кузнечное ремесло, как и любая жизненная стезя, – это путешествие. Если ты хочешь стать одним из избранных, я, конечно, готов тебя учить. Но сначала тебе нужно выполнить моё задание.", female = "Моя работа приносит мне подлинное удовлетворение! Когда я вижу гордого воина Орды, защищённого моими доспехами, я понимаю, зачем родился на свет. Это как наваждение, я без этого просто жить не могу. Конечно, этому я тебя научить не смогу – я могу только указать тебе путь. Ведь кузнечное ремесло, как и любая жизненная стезя, – это путешествие. Если ты хочешь стать одной из избранных, я, конечно, готов тебя учить. Но сначала тебе нужно выполнить моё задание." },
    ["5301c"] = { common = "Это последний шаг перед тем, как ты начнёшь свою новую карьеру в школе Брони. Если ты колеблешься, сейчас твой последний шанс отступить. А иначе готовься к жизни, полной славы!" },
    ["5302a"] = { male = "В один прекрасный день я создам легендарный молот. Молот, достойный вождя! Это труд всей моей жизни. Моё главное и единственное увлечение. Я вижу, что ты можешь стать одним из нас – оружейником! И я помогу тебе в этом, если хочешь. Тебе нужно только выполнить простое задание. При твоём мастерстве оно и впрямь несложное.", female = "В один прекрасный день я создам легендарный молот. Молот, достойный вождя! Это труд всей моей жизни. Моё главное и единственное увлечение. Я вижу, что ты можешь стать одной из нас – оружейником! И я помогу тебе в этом, если хочешь. Тебе нужно только выполнить простое задание. При твоём мастерстве оно и впрямь несложное." },
    ["5302c"] = { male = "Это последний шанс отказаться перед тем, как ты начнёшь новую карьеру. Готов ли ты к пути оружейника? Слава и почести ждут тебя.", female = "Это последний шанс отказаться перед тем, как ты начнёшь новую карьеру. готова ли ты к пути оружейника? Слава и почести ждут тебя." },
    ["5305a"] = { common = "В казематах Бастиона Алого ордена таится секрет безмятежности. Молотобоец из Багрового Легиона охраняет эту тайну. Срази его и принеси мне его фартук. За это я наделю тебя знанием о том, как изготовить зачарованный боевой молот!" },
    ["5305c"] = { common = "Вот чертежи молота, путник. Надеюсь, с его помощью ты многим даруешь безмятежность!" },
    ["5306a"] = { common = "Пусть её красота не обманывает тебя, герой. Тёмная охотница Вос'гаджин безумна и смертельно опасна. Да, это её рук дело — \"прикосновение любви\", как она выразилась. Наконец настал час отмщения. Вос'гаджин ты найдёшь на Пике Чёрной горы. Убей её и принеси мне её змеекамень. Сделай это, и я научу тебя секретам школы Топора." },
    ["5306c"] = { common = "Знание — сила!" },
    ["5307a"] = { common = "Если я краток с вами, на то есть причины. Чертежи для создания великого меча скверны были похищены Чёрной Стражей: элитным отрядом скелетов барона Ривендера. Да, именно, Ривендера из Стратхольма. Оружейник Чёрной Стражи хранит теперь эти чертежи как зеницу ока. Убейте его и принесите доказательство его смерти, и в благодарность я научу вас тому, что нужно для изготовления пылающей рапиры!" },
    ["5307c"] = { common = "Меч — самый лучший выбор, это же очевидно!" },
    ["5321a"] = { common = "Я шёл к Заставе Мейстры, чтобы встретиться с Лиладрис Лунной Рекой, но решил остановиться здесь и немного вздремнуть. С тех пор как я очнулся от Изумрудного Сна, я всё время такой сонный... Зевает И я нигде не могу найти свои вещи! Поможешь мне их отыскать? Я так понимаю, Застава Мейстры находится к югу отсюда, в Ясеневом лесу, у дороги. Я пришёл оттуда... Да, и вот ещё что: я могу заснуть по дороге, так что если тебе нужно будет меня разбудить, сделай это с помощью моего рога. Он в этом сундуке." },
    ["5321c"] = { common = "О, я так рада, что Керлониан смог сюда добраться. И я уверена, что найду его спящим где-нибудь поблизости, ведь так? Спасибо вам за то, что показали ему дорогу." },
    ["5341a"] = { common = "В Некроситете находятся сокровища семейства Баровых. Я, Алексий Баров, один из двух оставшихся наследников нашего дома. Второй — мой брат, Вэлдон. Этот жалкий трус бежал во время войны и по-прежнему длит своё никчёмное существование в человеческом обличье. Сейчас он ищет документы, чтобы унаследовать всё состояние. Доберись до этих документов раньше моего брата, и я озолочу тебя!" },
    ["5341c"] = { common = "Прекрасная работа, странник. Теперь займёмся наследством…" },
    ["5342a"] = { common = "Естественно, пока мой брат жив, могут возникать вопросы о порядке наследования. Я не допущу этого. Полагаю, ты, шваль, не побоишься замарать руки убийством. Задание простое, надеюсь, ты справишься; если хочешь получить награду. Вэлдон сидит под крылышком у Альянса в Лагере Промозглого Ветра на востоке. Убей его и принеси мне голову. Давай-давай, иди." },
    ["5342c"] = { common = "Замечательно! Теперь только я владею силой и богатством Баровых! Можешь оставить сдачу себе, грязное животное." },
    ["5343a"] = { common = "Милый братец Алекси. И зачем я, глупец, пощадил его? Я смотрел в лицо врага, нежити, и оставил его в живых. Он хочет отобрать МОЁ наследие. Не бывать тому! Найди документы на мои владения, прежде чем эта мерзость дотянется до них своими костлявыми ручками, и получишь большую награду. Документы находятся в руинах Некроситета. Спеши!" },
    ["5343c"] = { common = "Я хочу дать тебе ещё одно задание, путник." },
    ["5344a"] = { common = "Документы у меня в руках, осталось только одно. Алекси придётся убить. Когда он умрёт, я смогу вздохнуть спокойно, не ожидая гибели от руки наёмного убийцы. Задание простое. Алекси находится под покровительством Орды — в Бастионе. Нет, я не требую, чтобы ты прямо взял и убил его, мне голова нужна! А как ты её получишь… твоё дело. Подобные размышления ниже моего аристократического достоинства." },
    ["5344c"] = { common = "О радость, о счастье! Наконец-то чёрная овца в стаде семьи Баровых мертва, и я получил наследство! Возьми деньги и убирайся, деревенщина." },
    ["5361a"] = { common = "Мой брат, Натака, находится на Заставе Скитающихся Духов в Пустошах. Я хотел бы попросить вас... не доставите ли ему этот отчёт? С тех пор, как я писал ему последний раз, прошёл целый год, и вот сейчас кентавры опять что-то затевают. Мой брат должен узнать обо всём. Вам нужно будет отправиться в Каменный Коготь – это горы к северу от Перекрёстка, а потом свернуть на запад, в Обугленную долину. Пустоши находятся южнее долины. Следуйте по дороге на юг, и скоро увидите Заставу Скитающихся Духов." },
    ["5361c"] = { male = "Не знаю, как вы связаны с моим братом, но, вижу, он вам доверяет, герой. Я – Натака Длинный Рог, и я приветствую вас на Заставе Скитающихся Духов! герой нам здесь точно не помешает. Поговорите с другими, наверняка у них найдётся работа для вас.", female = "Не знаю, как вы связаны с моим братом, но, вижу, он вам доверяет, героиня. Я – Натака Длинный Рог, и я приветствую вас на Заставе Скитающихся Духов! героиня нам здесь точно не помешает. Поговорите с другими, наверняка у них найдётся работа для вас." },
    ["5381a"] = { common = "В руки клана Пылающего Клинка попала демоническая шкатулка, в которой хранится могущественный артефакт – Рука Ируксоса. Орки из клана Пылающего Клинка используют её, чтобы открывать демонические порталы на поле Маннорок. Мы должны остановить нашествие демонов, захлёстывающее наш мир! Расколи красный кристалл в крепости Громового Топора этой киркой демонов: так ты сможешь добыть демоническую шкатулку." },
    ["5381c"] = { male = "О, демоническая шкатулка... Наконец-то я увидел её. Послушай, герой, дай-ка её мне, и я её открою... и покажу тебе Руку Ируксоса.", female = "О, демоническая шкатулка... Наконец-то я увидел её. Послушай, героиня, дай-ка её мне, и я её открою... и покажу тебе Руку Ируксоса." },
    ["5382a"] = { common = "Крастинов виновен в тысячах смертей. Справедливость должна восторжествовать — пусть он вкусит собственного блюда. Найди его и заставь испытать мучения его бессчётных жертв. Когда он умрёт, сожги наши останки. Пусть обратятся в пепел, путник." },
    ["5382c"] = { common = "Душа моя исцелена, путник. Ты оказал нам с мужем огромную услугу, но это ещё не всё." },
    ["5384a"] = { common = "Вот она, путник. Кровь невинных. Чистейшая кровь, умилостивление хозяина Крастинова. При помощи этой крови можно вызвать Киртоноса, и именно она поможет его уничтожить. Отнеси эту кровь на балкон, помести в жаровню. Киртонос явится на зов — он не сможет устоять. Когда он явится, обрушь на него ярость и гнев тысяч невинно убиенных. Если ты добьёшься успеха, мы на славу отблагодарим тебя." },
    ["5384c"] = { common = "Киртонос мёртв, и страшная глава истории Некроситета подошла к концу. Но твои деяния не окончены. Многие узнали о твоих подвигах. Возьми это, путник. Это часть нашей сущности. При её помощи ты сможешь связаться с другими павшими душами Каэр Дарроу." },
    ["5385a"] = { common = "Вы осторожно поднимаете мешок и собираетесь возвращаться к Джессире Лунной Радуге на границу Ясеневого леса и Осквернённого леса. Вы надеетесь, что паладин будет с почестями погребён, когда его останки будут доставлены его друзьям." },
    ["5385c"] = { common = "Ты сделал это! Слава Элуне и её силе, путник. Я уверена что Арко'нарин будет счастлива узнать о том что ты убил тварь, которая измучила одного из её лучших друзей. Я не могу многое сделать для тебя, но вот, возьми это." },
    ["5386a"] = { common = "Давненько на Заставе Скитающихся Духов не наслаждались запахом жареной рыбки... Тролли, живущие в Деревне Ночных Охотников – отличные рыбаки, вот только из-за разбушевавшихся в наших краях кентавров мне никак не выкроить времени, чтобы добраться до них. Послушай-ка, окажи мне услугу: отправляйся в Деревню Ночных Охотников. Разыщи там Джинар'Зиллена, потолкуй с ним и принеси мне рыбок-кровобрюхов: я их просто обожаю! На юг отсюда идёт дорога: она приведёт тебя аккурат в деревню троллей." },
    ["5386c"] = { male = "Ты просто спас меня! А эти кровобрюхи так хороши, что хоть сырыми их ешь. *Натака сглатывает слюну.* Ну, давай, давай скорее, выбери один из этих предметов в уплату за рыбу!..", female = "Ты просто спасла меня! А эти кровобрюхи так хороши, что хоть сырыми их ешь. *Натака сглатывает слюну.* Ну, давай, давай скорее, выбери один из этих предметов в уплату за рыбу!.." },
    ["5401c"] = { common = "Все, кто борется со злом от имени Серебряного Рассвета, должны носить жетон. Ношение таких жетонов, позволит тебе достичь права получать награды у наших интендантов, которые они могут предложить. Так же, вы можете получать за убитую нежить, камень Плети. Эти камни ты можешь приносить мне и обменивать их на знак доблести Серебряного Рассвета. Обеспечь свою судьбу, герой — присоединяйся к борьбе уже сегодня!" },
    ["5405c"] = { common = "Все, кто борется со злом от имени Серебряного Рассвета, должны носить жетон. Ношение таких жетонов, позволит тебе достичь права получать награды у наших интендантов, которые они могут предложить. Так же, вы можете получать за убитую нежить, камень Плети. Эти камни ты можешь приносить мне и обменивать их на знак доблести Серебряного Рассвета. Обеспечь свою судьбу, герой — присоединяйся к борьбе уже сегодня!" },
    ["5421a"] = { male = "Я награжу любого, кто хоть немного облегчит мою жизнь... Чем меньше у меня работы, тем лучше, дружище! Здесь неподалёку, в деревне Ночных Охотников, прямо за пристанью, я расставил ловушки на моллюсков. Много, много ловушек! Будь так любезен, сделай за меня мою работу: собери улов и принеси мне, а я уж тебя награжу кое-чем нужным... ну, ты понял, да?", female = "Я награжу любого, кто хоть немного облегчит мою жизнь... Чем меньше у меня работы, тем лучше, дружище! Здесь неподалёку, в деревне Ночных Охотников, прямо за пристанью, я расставил ловушки на моллюсков. Много, много ловушек! Будь так любезна, сделай за меня мою работу: собери улов и принеси мне, а я уж тебя награжу кое-чем нужным... ну, ты поняла, да?" },
    ["5421c"] = { male = "Ах, дружочек, нет ничего лучше хорошо сделанной работы, особенно когда делаешь её не ты... Верно ведь?", female = "Ах, подружка, нет ничего лучше хорошо сделанной работы, особенно когда делаешь её не ты... Верно ведь?" },
    ["5441a"] = { male = "Проклятые батраки! Им велено валить лес, но они всё время пытаются отлынивать. Мне нужен кто-то, кто их приструнит. Ты, герой, мне, пожалуй, годишься. На тебе дубинку – ступай и всыпь этим бездельникам. Хороший тумак заставит их взяться за ум! Управишься – не забудь вернуть дубинку. Проклятые лентяи...", female = "Проклятые батраки! Им велено валить лес, но они всё время пытаются отлынивать. Мне нужен кто-то, кто их приструнит. Ты, героиня, мне, пожалуй, годишься. На тебе дубинку – ступай и всыпь этим бездельникам. Хороший тумак заставит их взяться за ум! Управишься – не забудь вернуть дубинку. Проклятые лентяи..." },
    ["5441c"] = { common = "Отлично, отлично! В следующий раз будут знать, как дрыхнуть на работе! Спасибо за помощь!" },
    ["5461a"] = { common = "Нежить боится жизни не меньше, чем живые — смерти. Ступившие на путь не-жизни нередко уничтожают все свидетельства прежнего бытия. К сожалению, для создания артефакта, способного превратить Раса Ледяной Шёпот в смертного, мы должны отыскать какой-то предмет, сохранившийся со времени его настоящей жизни. Отправляйся в разрушенный город Стромгард, родину Ледяного Шёпота, и найди такой предмет. Удачи тебе, путник." },
    ["5461c"] = { common = "Я даже не верил в то, что такой предмет существует! Приготовься, путник, поскольку то, о чём я попрошу, поведёт тебя в самые глубины ада!" },
    ["5462a"] = { common = "Осквернённой душе можно противопоставить особые памятные предметы. Говорят, будто Ледяной Шёпот встал под знамёна Короля-лича в Стратхольме. Он добровольно лишил себя жизни с целью влиться в ряды нежити. Именно в тех землях следует искать память о его человеческом облике. В часовне Светлых надежд ты найдёшь Леонида Барталомея Чтимого, некогда бывшего рабом Плети, освобождённого королевой банши, но отдавшего свою верность Серебряному Рассвету. Быть может, он знает больше, чем я. В путь!" },
    ["5462c"] = { common = "Ты хочешь возродить во мне воспоминания, которые я бы предпочёл похоронить навеки." },
    ["5463a"] = { common = "Рас Ледяной Шёпот некогда тоже был человеком. Я собственными глазами видел, как он вручил свою бессмертную душу Королю-личу. Он приставил к своему горлу кинжал и с улыбкой перерезал себе глотку от уха до уха. Его мёртвое тело упало в центр пентаграммы. Король-лич бросил взгляд на мёртвого мага, и в ту же секунду Рас Ледяной Шёпот восстал в обличье лича. Да, странник, я помню. У того, что ты ищешь, есть имя — Дар Менетила: это земля, благословлённая Королём-личом — священное место Плети." },
    ["5463c"] = { common = "Вы размещаете воспоминания на осквернённую землю." },
    ["5464a"] = { common = "Души падших цепляются за любое олицетворение их прежней жизни и превращают любой значимый для них предмет в Книгу Души. Вы поднимаете предмет и прячете в сумку." },
    ["5464c"] = { common = "Как душа цепляется за воспоминания, так и физическая оболочка Раса Ледяного Шёпота будет цепляться." },
    ["5465a"] = { common = "Отнеси книгу Мардуку, путник, он расскажет тебе, что делать дальше." },
    ["5465c"] = { common = "Я думал что ты присоединишься ко мне в качестве ещё одной несчастной души." },
    ["5466a"] = { common = "Осталось одно задание, путник — бросить вызов личу Расу Ледяному Шёпоту. Воспользуйся против него силой Книги — не знай пощады! Терпи удары, которые обрушит на тебя злобная тварь. Не бойся боли! Когда ритуал будет завершён, Рас снова станет смертным. Именно в этот момент его необходимо убить. Срази злодея и забери его голову." },
    ["5466c"] = { common = "Десять тысяч душ кричат в унисон, путник! Ты нанёс сокрушительный удар по хозяевам Плети." },
    ["5481a"] = { common = "Хозяину надо растения. У нас большие руки, цветы рвать никак. Ты нам помогать, мы тебя не трогать. Нам надо мракоцвет, он растёт тут и у дороги. Ты соберёшь – отнеси хозяину Холланду на кладбище в Брилл." },
    ["5481c"] = { common = "Что это? Мракоцвет?! Зачем он мне сдался?! Эта тупая гора мяса собирает ромашки и привлекает – сколько, Тёмная Госпожа знает, – к этому делу таких простаков, как ты! Без обид. Ладно, главное, что ты здесь. Я не собираюсь тратить своё время на то, чтобы объяснить этому поганищу элементарные вещи. Так что, может, ты соберёшь для меня этот проклятый погибельник?" },
    ["5482a"] = { male = "Теперь ты понимаешь, в каком затруднительном положении я нахожусь? Это нечто всё ещё ходит там и собирает не те растения. Я непременно отблагодарю тебя, если ты соберёшь то, что мне нужно. Принеси мне погибельник, и я щедро тебя награжу. Насколько я знаю, его можно найти у братских могил, к северу от кладбища Брилла. Поторопись – и будь осторожен – в тех местах полно гноллов.", female = "Теперь ты понимаешь, в каком затруднительном положении я нахожусь? Это нечто всё ещё ходит там и собирает не те растения. Я непременно отблагодарю тебя, если ты соберёшь то, что мне нужно. Принеси мне погибельник, и я щедро тебя награжу. Насколько я знаю, его можно найти у братских могил, к северу от кладбища Брилла. Поторопись – и будь осторожна – в тех местах полно гноллов." },
    ["5482c"] = { male = "А, мой погибельник! Превосходно! *Младший аптекарь Холланд жадно потирает ладони.* Он мне очень пригодится. Ты оказал мне, ой, то есть Тёмной Госпоже, большую услугу. Как я и обещал, вот твоя награда.", female = "А, мой погибельник! Превосходно! *Младший аптекарь Холланд жадно потирает ладони.* Он мне очень пригодится. Ты оказала мне, ой, то есть Тёмной Госпоже, большую услугу. Как я и обещал, вот твоя награда." },
    ["5501a"] = { common = "Мы тут на золотой жиле сидим, на золотой жиле! Знаешь, что это? Кости кодо!.. Кости кодо изменят мир раз и навсегда! У меня масса клиентов, которые делают из этих костей мебель, музыкальные инструменты – даже взрывчатый порошок, чтоб тебе знать! Сюда приходит караван, забирает у меня кости, а потом караванщики продают их в Деревне Ночных Охотников. И неплохая выручка, да, очень неплохая... Если пойдёшь на юг отсюда, то доберёшься прямиком до Кладбища кодо. Принеси мне десяток костей, а я дам тебе кое-что взамен. Ну что, идёт?" },
    ["5501c"] = { common = "Ох, вот они, мои косточки, мои драгоценные!.. Я стану самым богатым гоблином в мире, я прославлюсь, моё лицо не будет сходить с обложек \"Каравана истории\", и тогда они все ещё увидят, кто я такой! Да-да, особенно тот зелёный сморчок, который вечно твердил: \"Ничего достойного в жизни совершить не сможешь ты!\"" },
    ["5503c"] = { common = "Все, кто борется со злом от имени Серебряного Рассвета, должны носить жетон. Ношение таких жетонов, позволит тебе достичь права получать награды у наших интендантов, которые они могут предложить. Так же, вы можете получать за убитую нежить, камень Плети. Эти камни ты можешь приносить мне и обменивать их на знак доблести Серебряного Рассвета. Обеспечь свою судьбу, герой — присоединяйся к борьбе уже сегодня!" },
    ["5504a"] = { common = "Тебе причитается награда за верную службу Серебряному Рассвету, путник. Тебе удалось завоевать всеобщее почтение. Мне поручено передать — ты можешь купить один из самых наших ценных предметов — оплечье защиты от магии. Если прикрепить его к доспехам, твоё сопротивление силам одного из направлений магии возрастёт. За это оплечье я попрошу от тебя не менее десяти знаков доблести Серебряного Рассвета." },
    ["5504c"] = { common = "Поразительно — не зря всех восхищает твоя преданность Серебряному Рассвету. Теперь я с радостью предлагаю на выбор наши оплечья. Пока отношение нашего ордена к тебе не изменится, ты сможешь купить оплечья у любого интенданта Серебряного Рассвета. За Рассвет, брат мой!" },
    ["5505c"] = { common = "Удачи тебе, герой. Пусть твои победы продолжают приносить тебе славу и власть!" },
    ["5507a"] = { common = "Тебе причитается награда за верную службу Серебряному Рассвету, путник. Тебе удалось завоевать всеобщее почтение. Мне поручено передать — ты можешь купить один из самых наших ценных предметов — оплечье защиты от магии. Если прикрепить его к доспехам, твоё сопротивление силам одного из направлений магии возрастёт. За это оплечье я попрошу от тебя не менее десяти знаков доблести Серебряного Рассвета." },
    ["5507c"] = { common = "Поразительно — не зря всех восхищает твоя преданность Серебряному Рассвету. Теперь я с радостью предлагаю на выбор наши оплечья. Пока отношение нашего ордена к тебе не изменится, ты сможешь купить оплечья у любого интенданта Серебряного Рассвета. За Рассвет, брат мой!" },
    ["5511c"] = { common = "Удачи тебе, герой. Пусть твои победы продолжают приносить тебе славу и власть!" },
    ["5513a"] = { common = "Тебе причитается награда за верную службу Серебряному Рассвету, путник. Тебе удалось завоевать всеобщее почтение. Мне поручено передать — ты можешь купить один из самых ценных наших предметов — оплечье защиты от магии. Если прикрепить его к доспехам, твоё сопротивление силам одного из пяти направлений магии возрастёт. За это оплечье я попрошу от тебя не менее десяти знаков доблести Серебряного Рассвета." },
    ["5513c"] = { common = "Поразительно — не зря всех восхищает твоя преданность Серебряному Рассвету. Теперь я с радостью предлагаю на выбор наши оплечья. Пока отношение нашего ордена к тебе не изменится, ты сможешь купить оплечья у любого интенданта Серебряного Рассвета. За Рассвет, брат мой!" },
    ["5514a"] = { common = "Тебе нужно поговорить с гоблином по имени Кринкель Сталлер. Он работает в Прибамбасске, в пустыне Танарис. Ему под силу сделать такую форму, но это обойдётся недёшево. Мы просим тебя не скупиться и заплатить ему. Я алхимик, а не банкир. Будь у меня золото, я бы здесь не сидел. Ну вот, опять я брякнул что-то не то. Ладно. Тебя ждёт Прибамбасск! Удачи!" },
    ["5514c"] = { common = "Дитерс сказал, что ты выполняешь обязательства… и ты это сделал. Сделка есть сделка. Я вставлю фрагменты прямо при тебе… Дитерс уже обработал их? Хорошо, это сбережёт тебе время так как мне не придётся посылать тебя обратно в Бастион." },
    ["5515a"] = { common = "Мы сбросили с себя тяжёлое бремя, но твоё задание всё ещё не исполнено. Повелитель Крастинова, Киртонос, всё ещё жив. Впрочем, прежде чем бросить ему вызов, необходимо придумать, как его вызвать. Говорят, что кровь невинных от Крастинова к Киртоносу переправляет Джандис Баров. Найди её в затопленных коридорах Некроситета и убей. Принеси все улики, которые только найдёшь." },
    ["5515c"] = { common = "Мешок ужасов!" },
    ["5517a"] = { male = "Брат путник — нет числа твоим деяниям во славу Серебряного Рассвета. В знак признательности я готова расстаться с одним из наших знаменитых многоцветных оплечий Рассвета — тех самых, которые защищают от всех видов магии. Многоцветные оплечья Рассвета предназначены лишь для наших величайших героев! Принеси мне двадцать пять знаков доблести, и получишь одно из лучших наших изделий.", female = "Сестра путник — нет числа твоим деяниям во славу Серебряного Рассвета. В знак признательности я готова расстаться с одним из наших знаменитых многоцветных оплечий Рассвета — тех самых, которые защищают от всех видов магии. Многоцветные оплечья Рассвета предназначены лишь для наших величайших героев! Принеси мне двадцать пять знаков доблести, и получишь одно из лучших наших изделий." },
    ["5517c"] = { common = "Наиболее впечатляющая многоцветная драгоценность Рассвета теперь твоя, путник! Пока ты сохраняешь превознесение Серебряного Рассвета, ты можешь приобрести дополнительные многоцветные драгоценности! Они будут доступны тебе у любого интенданта Рассвета." },
    ["5518a"] = { common = "Если вы собираетесь сразиться с королём этой помойки — а думаю, что без этого не обойтись, — тогда вам придётся миновать капитана Давигрома. Конечно, можно его просто убить. Но возможно, вам стоит оставить его в живых. Вы спросите — каким образом? Я сижу здесь уже довольно долго, и успел придумать, как можно изготовить личину огра, которая продержится достаточно долго, чтобы обмануть этих остолопов. Но, увы, больше чем на десять минут её не хватит. Принесите мне всё, что нужно, и я вам её изготовлю. Торопиться-то мне всё равно некуда…" },
    ["5518c"] = { common = "Ага, ты уложился в срок… и доставил то что надо. Секундочку… Имей в виду — у тебя есть только десять минут пока костюм не развалится. Используй его вовремя." },
    ["5521a"] = { male = "Брат путник — твоих деяний во славу Серебряного Рассвета не счесть. В знак признательности я готов продать тебе одно из наших знаменитых многоцветных оплечий Рассвета — тех самых, которые защищают от всех видов магии. Многоцветные оплечья Рассвета предназначены лишь для наших величайших героев! Принеси мне двадцать пять знаков доблести, и получишь одно из лучших наших изделий.", female = "Сестра путник — твоих деяний во славу Серебряного Рассвета не счесть. В знак признательности я готов продать тебе одно из наших знаменитых многоцветных оплечий Рассвета — тех самых, которые защищают от всех видов магии. Многоцветные оплечья Рассвета предназначены лишь для наших величайших героев! Принеси мне двадцать пять знаков доблести, и получишь одно из лучших наших изделий." },
    ["5521c"] = { common = "Наиболее впечатляющая многоцветная драгоценность Рассвета теперь твоя, путник! Пока ты сохраняешь превознесение Серебряного Рассвета, ты можешь приобрести дополнительные многоцветные драгоценности! Они будут доступны тебе у любого интенданта Рассвета." },
    ["5522a"] = { common = "Я получила весть от своего господина Вектуса. На самом деле… не напрямую от него, но от некого Леонида Барталомея. Я не знаю его, однако он видел моего господина — а никто не может видеть моего господина, если он сам этого не пожелает. Леонид сказал мне, что Вектусу необходимы драконьи яйца. Доставь их ему в Часовню Последней Надежды в Восточные Чумные земли. Ай! За что? Разве Вектус не доверяет мне? Не обращай внимания, я не тебе. Просто доставь яйца куда следует и сообщи Леониду, что я сделала всё, как было приказано." },
    ["5522c"] = { common = "А, очень хорошо. Ты не знал, что работал на силы зла… но теперь я открою тебе правду. И боюсь, что я не служу этому хозяину. Я есть Леонид Барталомей, известный как \"Чтимый\" моему начальству в Серебряном Рассвете. Я обманул Тинки, чтобы она послала тебя и посылку с драконьими яйцами ко мне. Моя уловка удалась, яйца не достигли назначения, и громадная мощь не попала в руки врага." },
    ["5524a"] = { male = "Брат путник — твоих деяний во славу Серебряного Рассвета не счесть. В знак признательности я готова продать тебе одно из наших знаменитых многоцветных оплечий Рассвета — тех самых, которые защищают от всех видов магии. Многоцветные оплечья Рассвета предназначены лишь для наших величайших героев! Принеси мне двадцать пять знаков доблести, и получишь одно из лучших наших изделий.", female = "Сестра путник — твоих деяний во славу Серебряного Рассвета не счесть. В знак признательности я готова продать тебе одно из наших знаменитых многоцветных оплечий Рассвета — тех самых, которые защищают от всех видов магии. Многоцветные оплечья Рассвета предназначены лишь для наших величайших героев! Принеси мне двадцать пять знаков доблести, и получишь одно из лучших наших изделий." },
    ["5524c"] = { common = "Наиболее впечатляющая многоцветная драгоценность Рассвета теперь твоя, путник! Пока ты сохраняешь превознесение Серебряного Рассвета, ты можешь приобрести дополнительные многоцветные драгоценности! Они будут доступны тебе у любого интенданта Рассвета." },
    ["5525c"] = { common = "Ты занял первое место. Все остальные заняли второе или ниже. О, спасибо что освободил меня! Я знал, что моя жизнь предназначена для чего-то большего, нежели быть закуской для какого-то огра!" },
    ["5526a"] = { common = "Твои знания об Эльдре'Таласе — Забытом Городе — в Фераласе теперь очень пригодятся, путник. Именно в восточной части этого разрушенного города властвует нечестивый Алззин Перевертень. Ступай же туда со всей поспешностью и посмотри в лицо ожидающей тебя опасности. Плод Изобилия, ныне осквернённый и ставший Сквернитом, должен находиться неподалёку от Алззина. Когда он упадёт, собери столько субстанции Сквернита, сколько сможешь. Закрой его в реликварий и принеси мне. Удачи тебе, и быстроты Кенария." },
    ["5526c"] = { common = "Кончено, бравый герой, и теперь Круг Кенария в долгу перед тобой. Война конечно ещё далека от завершения, и битвы нам ещё предстоят. Пожалуйста, возьми это в знак нашей благодарности, путник. Спасибо тебе." },
    ["5527a"] = { common = "Первый шаг — найти вместилище, способное удержать чрезвычайно осквернённую субстанцию и оградить обладателя от её влияния. Единственное известное мне приспособление, в котором, возможно держать такую дрянь, как Сквернит, — это реликварий Чистоты. В сердце пустошей Силитуса находятся руины поселения Ночных эльфов, деревня Южного Ветра. Я знаю, что реликварий хранился там много лет назад. Если хочешь помочь нам достичь успеха, обыщи эти руины в надежде найти его." },
    ["5527c"] = { common = "Ого! Какое счастье — я говорю тебе это от имени всего Круга Кенария — что ты работаешь на нашей стороне… Так как Реликварий в наших руках, дальше всё видится как в чистой воде. Демона надо убить, а вещь, которой он владеет — отобрать." },
    ["5529a"] = { common = "До Серебряного Рассвета дошли слухи о том, что Плеть создаёт собственную армию драконов! Мы должны этому помешать — с помощью драконов Плеть сможет беспрепятственно перемещаться по всему Азероту! Их некроманты выращивают проклятых драконов в Некроситете, посреди озера Дарроумир. Отправляйся в Некроситет и убей как можно больше драконьих детёнышей, пока они не успели вырасти и превратиться в неуязвимых монстров!" },
    ["5529c"] = { common = "Прекрасно сделано, путник! Теперь это семейство драконов нескоро возродится… По крайней мере я так надеюсь!" },
    ["5531a"] = { common = "Яйца, которые ты принёс мне, должны были быть использованы Плетью для создания чудовищных проклятых драконов. Охлаждённые яйца чёрных драконов были бы бесценны для их опытов — это несомненно позволило бы Плети достичь своей подлой цели гораздо быстрее. Отнеси яйца Бетине Биггльцинк — она сведуща в науках и алхимии. Она обеспечила нас оружием против Плети. С твоей помощью мы нанесём этим тварям решающий удар." },
    ["5531c"] = { common = "Вот они. И в такой красивой коробочке. Отличный размер! Мы будем держать эти яйца в безопасном месте, пока не изучим их. А теперь задача для тебя. Я сконструировала устройство, которое уничтожает учёных нежити в Некроситете. Они тоже изучают драконов в попытках создать заражённого дракона, и мы должны остановить их изыскания! Я называю это устройство Рассветный гамбит, потому что… я, честно говоря, не знаю, сработает ли оно. Ну что, попробуешь?" },
    ["5533a"] = { common = "На острове Каэр Дарроу располагается Некроситет — школа, которая одновременно служит цитаделью Плети. В её недрах наши враги спокойно проводят исследования и делаются всё сильнее. Путь преграждают двери, и без подходящего ключа внутрь не войти. Алхимик Арбингтон многое знает о Некроситете и придумал, как достать ключ. Ты зарекомендовал себя как человека с большими способностями, поэтому я доверяю тебе это задание. Обсуди подробности с алхимиком." },
    ["5533c"] = { common = "Рад встрече, герой. В последнее время я посвятил большую часть времени изучению Некроситета, и, кажется, знаю способ, как добыть ключ… который отомкнёт входную дверь. Представляю, какие кошмары таятся за ней, путник. Не понимаю, как герои вроде тебя решаются на такие подвиги…" },
    ["5534a"] = { common = "Что?! Ты в уме?! Чем ты ещё недоволен?! Ты хоть представляешь, сколько стоят эти гранаты? За них дают… ладно, не важно… Хочешь денег? Хорошо. Прежде докажи мне, что ты ценный работник. Отправляйся в руины Эльдарата и принеси мне некую руну, которую искали эльфы крови. Полагаю, она у наг." },
    ["5534c"] = { common = "Хаха! Чудесно! Я был уверен, что ты найдёшь это и Волхв Римтори — это та корова, что наняла меня — уже роет копытами землю, так хочет эти руны. Ха! Я сделал вас, вонючие эльфы крови! Ким'джаель! Ха! Я покажу вам кто тут крыса! Хорошо поработал, путник. Молодец. А теперь я позолочу тебе ручку. Молодец!" },
    ["5535a"] = { common = "Давным давно, высокорождённые были самыми могущественными адептами тайной магии, когда либо существовавшими среди ночных эльфов. Порча, которая охватывает каждого, кто имеет дело с тайной магией, принесла мног зла народу ночных эльфов и всему Азероту. Я обещал Часовым, что буду освобождать встреченных мной духов от их смертных связей. Если поможешь мне в этом, я награжу тебя. Духи скитаются в святилище Песни Теней к северо-востоку отсюда." },
    ["5535c"] = { male = "Отличная работа, герой. Благодарю тебя. Теперь духи обрели покой, а опасность, которую могла навлечь их жажда магии, миновала. Думаю, обе стороны конфликта, раздирающего ныне Азерот, поймут, что ты выше этого.", female = "Отличная работа, героиня. Благодарю тебя. Теперь духи обрели покой, а опасность, которую могла навлечь их жажда магии, миновала. Думаю, обе стороны конфликта, раздирающего ныне Азерот, поймут, что ты выше этого." },
    ["5536a"] = { common = "Сатиры, искажённые и зловредные порождения ночных эльфов, ныне оскверняют священные земли, по которым некогда ступал Кенарий. Конечно, не в моих силах помочь эльфам справиться со всеми этими отвратительными созданиями, однако я поклялся Матери-Земле помочь эльфам избавиться от сатиров хотя бы здесь. Надеюсь, ты поможешь мне в этом деле. К северо-востоку отсюда ты найдёшь клан Халдарр. Возвращайся ко мне, когда испытаешь свою силу." },
    ["5536c"] = { male = "Отличная работа, герой. Вижу, ты не только силён, но и хитёр. Битва с сатирами была испытанием твоей преданности Матери-Земле, даже если ты поклоняешься другим богам. Она пронизывает всё сущее в нашем мире и за его пределами. Два ока её, тёмное и светлое, всегда взирают на нас с небес. Прошу тебя, прими эту скромную плату в знак моей признательности.", female = "Отличная работа, героиня. Вижу, ты не только сильна, но и хитра. Битва с сатирами была испытанием твоей преданности Матери-Земле, даже если ты поклоняешься другим богам. Она пронизывает всё сущее в нашем мире и за его пределами. Два ока её, тёмное и светлое, всегда взирают на нас с небес. Прошу тебя, прими эту скромную плату в знак моей признательности." },
    ["5537a"] = { common = "Чтобы отомкнуть двери Некроситета необходим Костяной ключ. Его делают из остатков скелета — точнее, нескольких скелетов — и вплавляют в прочнейший из металлов в подходящей форме. Чтобы ключ заработал, необходим перстень власти одного из тех существ, что могут открыть портал данной им силой. Но не будем отвлекаться, для начала нам понадобятся фрагменты скелетов. Для этой цели подойдут скелеты внутри Андорала, да и те, что снаружи." },
    ["5537c"] = { common = "Отличные образцы! Теперь моя очередь — я закалю их особым образом, чтобы они смогли вынести процесс отковки, через который им придётся рано или поздно пройти. Теперь придётся отыскать подходящую форму для отливки. Я знаю одного гоблина-кузнеца из Танариса, который в прошлом делал формы для не менее жутких вещей. Его девиз — как у всех гоблинов — кто платит, тот и музыку заказывает." },
    ["5538a"] = { common = "Тебе нужно поговорить с гоблином по имени Кринкель Сталлер. Он работает в Прибамбасске, в пустыне Танарис. Ему под силу сделать такую форму, но это обойдётся недёшево. Мы просим тебя не скупиться и заплатить ему. Я алхимик, а не банкир. Будь у меня золото, я бы здесь не сидел. Ну вот, опять я брякнул что-то не то. Ладно. Тебя ждёт Прибамбасск! Удачи!" },
    ["5538c"] = { common = "Арбингтон сказал, что ты принесёшь всё необходимое, и так оно и оказалось! Сделка есть сделка. Дай-ка я сложу фрагменты скелетов в форму. Арбингтон их заранее закалил? Великолепно… В противном случае тебе пришлось бы тащиться обратно на Берег Промозглого Ветра." },
    ["5541a"] = { male = "Хегнар Громострел продаёт ружья у дороги в Старую Наковальню. Стрелки и пушкари много упражняются возле его лавки, так что ему всегда нужны снаряды и патроны. Но... Последний ящик с боеприпасами, что я ему послал, пропал по дороге. Мой курьер рассказал мне, что он встал лагерем у Серой берлоги, там на него напали вендиго... и этот дурак бросил боеприпасы для Громострела! не мог бы ты найти их и вернуть Громострелу? Он их ждёт, и наверняка у него боеприпасы уже на исходе.", female = "Хегнар Громострел продаёт ружья у дороги в Старую Наковальню. Стрелки и пушкари много упражняются возле его лавки, так что ему всегда нужны снаряды и патроны. Но... Последний ящик с боеприпасами, что я ему послал, пропал по дороге. Мой курьер рассказал мне, что он встал лагерем у Серой берлоги, там на него напали вендиго... и этот дурак бросил боеприпасы для Громострела! не могла бы ты найти их и вернуть Громострелу? Он их ждёт, и наверняка у него боеприпасы уже на исходе." },
    ["5541c"] = { common = "Вот радость-то, ещё боеприпасы! Поставка старины Лослора, наконец, прибыла! Пусть и поздновато, но, как говаривал мой дедуля, лучше поздно, чем никогда! Большое тебе спасибо. Покупатели тут заждались!" },
    ["5542a"] = { common = "Если ты собираешься здесь оставаться, придётся тебе поработать в уплату за проживание. У нас есть ряд докучающих обстоятельств, с которыми неплохо бы разобраться. Начни с чумных псов и их отродий. Я не многим смогу тебе отплатить, но горячую пищу и приятную беседу гарантирую." },
    ["5542c"] = { common = "Хорошо сработано, путник. Заходи. Отдохни. Давай поедим и поговорим о давно минувших днях!" },
    ["5543a"] = { common = "Горе тем, кто в глупости своей бродит по Чумным землям. В здешних лесах таится много опасностей — от Алого ордена, который убивает всех, кроме своих сторонников, до Плети, которая всегда рада пополнить свои ряды новой нежитью. Даже звери и птицы превратились в отвратительных хищных чудовищ. Я прошу тебя уничтожить тех, что нападают с небес — чумных нетопырей." },
    ["5543c"] = { common = "Ты сияющий пример достоинства, странник! Прошло много времени с тех пор, как я чувствовал, что кровь героев течёт по моим венам. Твои подвиги вдохновляют!" },
    ["5544a"] = { common = "Странник, у меня еда на исходе. Мне стыдно признаться, но угостить тебя нечем. Не поможешь старику? Единственные твари в этих краях, которых не поразила чума, это личинки-трупоеды. Они довольно гадкие, зато их мясо хранится много месяцев. Мне необходимо запасти несколько сотен фунтов на зиму!" },
    ["5544c"] = { common = "Да пребудет с тобою свет! Благословляю тебя!" },
    ["5545a"] = { common = "У меня большие неприятности. Приближается срок поставки древесины, а я не успеваю её отправить. Самое обидное, что она уже заготовлена – но волки и медведи, расплодившиеся к северу отсюда, не дают моим работникам её забрать Я уже договорилась с заместителем судьи Рейнером насчёт зверья, но мне нужен кто-нибудь, кто доставит сюда эти дрова. Если ты принесёшь мне восемь вязанок, я всё успею." },
    ["5545c"] = { common = "Великолепно! Благодаря тебе я сумела выполнить заказ вовремя. Всякий труд должен быть оплачен, так что прошу тебя принять эту плату за беспокойство. Спасибо – и до свидания!" },
    ["5561a"] = { common = "Биббли думает, что он – единственный гоблин в Пустошах, умеющий делать деньги. Ха! Единственный караван, который осмеливается странствовать по этим землям, полностью зависит от меня. С тех самых пор, как я научился омолаживать кодо и управлять старыми и умирающими зверями при помощи моего энергетического инкапсулятора, мы трое – я, караванщик Корк и Риггер – создали что-то вроде компании. Вот, держи инкапсулятор: он действует на древних, старых и умирающих кодо, превращая их в ручных и заставляя следовать за тобой. Как сумеешь приручить кодо, веди его ко мне." },
    ["5561c"] = { common = "*Смид Заржавень начинает считать.* Три... Четыре... Ага, пять. Прекрасно! Я просил пять приручённых кодо – и получил ровно пять приручённых кодо! Я буду богат... Да, очень, очень богат! Хотелось бы мне видеть, какую кислую рожу скорчит Биббли, когда узнает об этом!" },
    ["5581a"] = { common = "Воззри: вот Рука Ируксоса. Поистине, ужасающее зрелище. Если ты намереваешься закрыть порталы демонов на Поле Маннорок, – а именно об этом я и хочу тебя попросить, – то она должна быть у тебя. Угроза со стороны демонов растёт: мы должны закрыть их порталы, дабы демоническим существам более не было доступа в этот мир. Удачи тебе в этом нелёгком деле... и берегись стражей портала." },
    ["5581c"] = { male = "Твоими стараниями нам удалось сдержать натиск врага, герой. Спасибо.", female = "Твоими стараниями нам удалось сдержать натиск врага, героиня. Спасибо." },
    ["5601a"] = { common = "Во время войны я бежала в Лордерон — мне посчастливилось спастись до того, как полчища Плети прошли по моим родным местам и превратили их в зачумлённые руины. Мне повезло, но судьба была не столь благосклонна к моей семье. Боюсь, все они погибли во время битвы при Дарроушире. Деревня Дарроушир была частью Восточных королевств, теперь это ещё одни развалины в южных пределах Восточных Чумных земель. Не мог бы ты узнать, что сталось с моей семьёй? Я так волнуюсь за них, особенно за мою сестрёнку Памелу. Пожалуйста, отыщи её!" },
    ["5621a"] = { male = "Мне нужна твоя помощь. Я должна оставаться здесь, чтобы обучать других, но ты мог бы помочь одной из наших раненых часовых к югу от Доланаара. Её ранили, когда она патрулировала город, и ей нужна наша помощь. Её зовут Шайя. Когда найдёшь её, исцели её раны и укрепи её тело заклятиями. По крайней мере, это защитит её от бед на некоторое время. Когда выполнишь свой долг перед Элуной, возвращайся ко мне.", female = "Мне нужна твоя помощь. Я должна оставаться здесь, чтобы обучать других, но ты могла бы помочь одной из наших раненых часовых к югу от Доланаара. Её ранили, когда она патрулировала город, и ей нужна наша помощь. Её зовут Шайя. Когда найдёшь её, исцели её раны и укрепи её тело заклятиями. По крайней мере, это защитит её от бед на некоторое время. Когда выполнишь свой долг перед Элуной, возвращайся ко мне." },
    ["5621c"] = { male = "Ты хорошо послужил Элуне. Я благодарю тебя за это. Пожалуйста, прими это одеяние, как символ моей благодарности. Оно символизирует то, что ты заслужил своё место в наших кругах. Если желаешь, носи его с гордостью, но мы признаём тебя своим в любом обличии. Спасибо, и да благословит тебя великая Элуна.", female = "Ты хорошо послужила Элуне. Я благодарю тебя за это. Пожалуйста, прими это одеяние, как символ моей благодарности. Оно символизирует то, что ты заслужила своё место в наших кругах. Если желаешь, носи его с гордостью, но мы признаём тебя своим в любом обличии. Спасибо, и да благословит тебя великая Элуна." },
    ["5622a"] = { male = "Тебе предстоит отправиться в Доланаар, когда завершишь свои дела здесь, в Тенистой долине. Там ты разыщешь Лорну Утренний Свет. Она расскажет тебе больше о пути Элуны, и с её помощью ты получишь своё первое облачение, говорящее о твоём статусе жреца Элуны. Будь осторожен, и да хранит тебя в пути Элуна!", female = "Тебе предстоит отправиться в Доланаар, когда завершишь свои дела здесь, в Тенистой долине. Там ты разыщешь Лорну Утренний Свет. Она расскажет тебе больше о пути Элуны, и с её помощью ты получишь своё первое облачение, говорящее о твоём статусе жрицы Элуны. Будь осторожна, и да хранит тебя в пути Элуна!" },
    ["5622c"] = { common = "Я рада знать, что Шанда послала тебя найти меня. Обучение молодых жрецов, следующих пути Луны приносит мне большое удовольствие." },
    ["5623a"] = { male = "Приветствую тебя, юный жрец. Пришло время узнать больше о нашей вере. После того как ты закончишь все дела в Североземье, разыщи в Златоземье жрицу Жозетту. Знания её велики; к тому же она уже слышала о тебе и о твоём стремлении к Истинному Свету. Она готова поделиться с тобой своей мудростью.", female = "Приветствую тебя, юная жрица. Пришло время узнать больше о нашей вере. После того как ты закончишь все дела в Североземье, разыщи в Златоземье жрицу Жозетту. Знания её велики; к тому же она уже слышала о тебе и о твоём стремлении к Истинному Свету. Она готова поделиться с тобой своей мудростью." },
    ["5623c"] = { common = "Я рада видеть тебя здесь. Нам нужно поговорить о твоём будущем и о пути Света..." },
    ["5624a"] = { common = "Обычно я подвергаю всех последователей Света небольшому испытанию. Так я выясняю, достойны ли они своего первого облачения – символа того, что церковь их принимает и поддерживает. Но сейчас ситуация немного отличается. Один из жителей Златоземья видел раненого стража на берегу озера к востоку отсюда. Этого стража зовут Робертс. Найди его, исцели его раны, придай ему стойкости и вернись сюда. Если ты справишься, я сочту твоё испытание завершённым." },
    ["5624c"] = { common = "Прекрасно. Теперь город охраняет ещё один страж. Приятно видеть, что ты учишься пользоваться своими способностями. Если захочешь узнать что-нибудь новое, возвращайся ко мне. А пока что прими это облачение. Если наденешь его, все будут знать, что ты принадлежишь к нашему ордену. Впрочем, можешь и не надевать, если не хочешь: для выполнения следующих заданий оно не нужно." },
    ["5625a"] = { male = "Как правило, примерно в эту пору послушники вроде тебя проходят испытание, в котором проверяется, достойны ли они носить облачения, говорящие об их статусе. Но, честно говоря, сейчас у меня есть и более важные дела. Горожане Караноса только что сказали мне, что к югу от городских стен они нашли раненого горного пехотинца по имени Дольф. Излечи Дольфа и наложи на него \"Слово Силы: Стойкость\", и я сочту, что ты прошёл испытание. Справишься?", female = "Как правило, примерно в эту пору послушницы вроде тебя проходят испытание, в котором проверяется, достойны ли они носить облачения, говорящие об их статусе. Но, честно говоря, сейчас у меня есть и более важные дела. Горожане Караноса только что сказали мне, что к югу от городских стен они нашли раненого горного пехотинца по имени Дольф. Излечи Дольфа и наложи на него \"Слово Силы: Стойкость\", и я сочту, что ты прошла испытание. Справишься?" },
    ["5625c"] = { common = "Прекрасно, Перш. В тебе есть Свет, и в этом нет сомнений. Вот, прими это одеяние. Оно будет показывать всем, что ты жрец, – носи его, если желаешь. В будущем тебе придётся пройти через другие испытания. Старайся узнать побольше о своих способностях и возможностях. Испытай свою силу в одном-двух одиночных боях, а потом и в группе с другими путниками. Не страшись никого: твоей силе может позавидовать любой." },
    ["5626a"] = { male = "Эй! путник! У тебя есть свободная минутка?! Ты давно уже следуешь пути Света, так ведь? Как насчёт того, чтобы сходить к Максану Ковальне в Каранос? Он расскажет тебе побольше о твоей судьбе, а если ты окажешься достойным, он тебе даст твои первые одеяния жреца. Теперь ступай! Как только закончишь все свои дела здесь, иди в Каранос через туннель – Максан будет тебя ждать.", female = "Эй! путница! У тебя есть свободная минутка?! Ты давно уже следуешь пути Света, так ведь? Как насчёт того, чтобы сходить к Максану Ковальне в Каранос? Он расскажет тебе побольше о твоей судьбе, а если ты окажешься достойной, он тебе даст твои первые одеяния жрицы. Теперь ступай! Как только закончишь все свои дела здесь, иди в Каранос через туннель – Максан будет тебя ждать." },
    ["5626c"] = { common = "О, так тебя послал Брансток? Славно, славно! Он прав, уже пора бы сделать шажок побольше в сторону Света. Это закалит твой характер и укрепит твоё тело… и дух." },
    ["5627c"] = { common = "Ты доказал, путник, что ты достоен внимание Элуны. Как будешь готов, дай знать. Я с радостью обучу тебя одному из её заклинаний, которое уникально для нашего народа." },
    ["5628a"] = { male = "Если не ошибаюсь? Рад, что ты уделил мне минутку внимания. Забраться так далеко от дома, да в такие юные годы, – мне по душе твоё рвение! Если бы мне в молодые годы хватило духу постранствовать по миру... Тут недавно тебя искала жрица из вашего ордена. Сказала, что тебе спешно надо вернуться в храм Луны в Дарнассе и поговорить со жрицей Алатеей – это как-то связано с твоим обучением. Я бы на твоём месте не тянул.", female = "Если не ошибаюсь? Рад, что ты уделила мне минутку внимания. Забраться так далеко от дома, да в такие юные годы, – мне по душе твоё рвение! Если бы мне в молодые годы хватило духу постранствовать по миру... Тут недавно тебя искала жрица из вашего ордена. Сказала, что тебе спешно надо вернуться в храм Луны в Дарнассе и поговорить со жрицей Алатеей – это как-то связано с твоим обучением. Я бы на твоём месте не тянул." },
    ["5628c"] = { male = "Хорошо, что ты вернулся домой. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твоё путешествие! Может быть, ты расскажешь мне что-нибудь о том, что ты видел после того, как мы закончим с делами.", female = "Хорошо, что ты вернулась домой. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твоё путешествие! Может быть, ты расскажешь мне что-нибудь о том, что ты видела после того, как мы закончим с делами." },
    ["5629a"] = { male = "Ещё раз приветствую тебя. Я знаю, что ты и так много помогаешь нашему народу, но надо и себе уделить хоть немного времени. Жрица Алатея прислала за тобой. Сдаётся, ты привлёк внимание наших старейшин, и они считают, что ты созрел для более великих дел. Отправляйся в дарнасский храм Луны и найди там Алатею. Удачи тебе, и да хранит тебя Элуна.", female = "Ещё раз приветствую тебя. Я знаю, что ты и так много помогаешь нашему народу, но надо и себе уделить хоть немного времени. Жрица Алатея прислала за тобой. Сдаётся, ты привлекла внимание наших старейшин, и они считают, что ты созрела для более великих дел. Отправляйся в дарнасский храм Луны и найди там Алатею. Удачи тебе, и да хранит тебя Элуна." },
    ["5629c"] = { male = "Хорошо, что ты вернулся. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твоё путешествие! Может быть, ты расскажешь мне что-нибудь о том, что ты видел после того, как мы закончим с делами.", female = "Хорошо, что ты вернулась. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твоё путешествие! Может быть, ты расскажешь мне что-нибудь о том, что ты видела после того, как мы закончим с делами." },
    ["5630a"] = { male = "Ну здравствуй, друг. Приятно видеть, что ты так далеко забрался! Без обид, но многие из ваших не слишком хорошо переносят тутошние холода. Славно, что ты слеплен из более крутого теста. Не так давно одна из ваших жриц искала тебя – говорила, чтобы ты нашёл жрицу Алатею в храме Луны в Дарнассе. Должно быть, это важно так что возвращайся туда как можно скорее.", female = "Ну здравствуй, подруга. Приятно видеть, что ты так далеко забралась! Без обид, но многие из ваших не слишком хорошо переносят тутошние холода. Славно, что ты слеплена из более крутого теста. Не так давно одна из ваших жриц искала тебя – говорила, чтобы ты нашла жрицу Алатею в храме Луны в Дарнассе. Должно быть, это важно так что возвращайся туда как можно скорее." },
    ["5630c"] = { male = "Хорошо, что ты вернулся домой. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твоё путешествие! Может быть, ты расскажешь мне что-нибудь о том, что ты видел после того, как мы закончим с делами.", female = "Хорошо, что ты вернулась домой. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твоё путешествие! Может быть, ты расскажешь мне что-нибудь о том, что ты видела после того, как мы закончим с делами." },
    ["5631a"] = { male = "Недавно в наших чертогах побывала одна жрица, и она искала вас, юный герой. Она сказала, что её послали за вами и что вы должны вернуться в храм Луны в Дарнассе как можно скорее. По прибытии найдите жрицу – она расскажет вам больше. Да пребудет с вами Свет.", female = "Недавно в наших чертогах побывала одна жрица, и она искала вас, юная героиня. Она сказала, что её послали за вами и что вы должны вернуться в храм Луны в Дарнассе как можно скорее. По прибытии найдите жрицу – она расскажет вам больше. Да пребудет с вами Свет." },
    ["5631c"] = { male = "Хорошо, что ты вернулся домой. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твоё путешествие! Может быть, ты расскажешь мне что-нибудь о том, что ты видел после того, как мы закончим с делами.", female = "Хорошо, что ты вернулась домой. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твоё путешествие! Может быть, ты расскажешь мне что-нибудь о том, что ты видела после того, как мы закончим с делами." },
    ["5632a"] = { common = "Да-да, конечно. Здравствуй. Недавно тут побывала посланница нашего ордена. Она искала тебя. Она мельком упомянула, что в Дарнассе случилось что-то важное и что тебе следует как можно скорее вернуться в храм Луны. Сразу поговори там со жрицей Алатеей. Наверняка это касается твоих успехов. В общем, возвращайся в Дарнасс, как только сможешь." },
    ["5632c"] = { common = "Хорошо что ты вернулся домой, путник. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твоё путешествие! Может быть ты расскажешь мне что-нибудь о том что ты видел после того как мы закончим с делами." },
    ["5633a"] = { male = "Добро пожаловать, друг. Приятно видеть тебя в наших чертогах. Да пребудет благость с тобой и твоим народом. Пока ты тут странствовал в наших краях, тебя разыскивала здесь жрица из вашего храма. Она сказала, что тебе надо как можно скорее возвращаться в Храм Луны. Прости, большего не скажу, но мне показалось, что дело важное. Когда доберёшься до Храма, поговори со жрицей Алатеей.", female = "Добро пожаловать, подруга. Приятно видеть тебя в наших чертогах. Да пребудет благость с тобой и твоим народом. Пока ты тут странствовала в наших краях, тебя разыскивала здесь жрица из вашего храма. Она сказала, что тебе надо как можно скорее возвращаться в Храм Луны. Прости, большего не скажу, но мне показалось, что дело важное. Когда доберёшься до Храма, поговори со жрицей Алатеей." },
    ["5633c"] = { common = "Хорошо что ты вернулся домой, путник. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твоё путешествие! Может быть ты расскажешь мне что-нибудь о том что ты видел после того как мы закончим с делами." },
    ["5634a"] = { male = "Недавно к нам заглянул жрец, которому был нужен ты, герой. Он сказал, что ему поручили отыскать тебя и как можно скорее отправить в Зал Тайн в Стальгорне. Когда прибудешь туда, отыщи верховного жреца Рохана – он всё объяснит. Да пребудет с тобой Свет.", female = "Недавно к нам заглянул жрец, которому была нужна ты, героиня. Он сказал, что ему поручили отыскать тебя и как можно скорее отправить в Зал Тайн в Стальгорне. Когда прибудешь туда, отыщи верховного жреца Рохана – он всё объяснит. Да пребудет с тобой Свет." },
    ["5634c"] = { common = "Твои услуги, оказанные силам Света, неоценимы, а твои деяния – пример блистательной храбрости для всех, кто путешествует в землях, полных опасностей. Прошу, считай этот урок наградой за всё, сделанное тобой." },
    ["5635a"] = { common = "Тобой заинтересовались наши высшие иерархи. Они желают твоего скорейшего возвращения в Собор Света Штормграда. Вероятно, они считают, что для тебя наступило время нового обучения. Когда доберёшься до собора, обратись прямо к верховной жрице Лорене, она расскажет тебе об остальном. Удачи! Да хранит тебя Свет!" },
    ["5635c"] = { common = "Я рада твоему прибытию. Есть множество вещей, которые нам нужно обсудить, но самая важная – твоё будущее обучение тайному знанию Света. Есть уроки, которые должны выучить все, кто служит Свету. Если ты чувствуешь в себе силы, мы можем начать прямо сейчас." },
    ["5636a"] = { male = "Да благословит тебя Элуна, герой! Надеюсь, что Свет не покидает тебя. Тебя недавно разыскивал один из наших жрецов. Он просил передать тебе, что в Соборе Света Штормграда тебя ожидает Верховная жрица Лорена. Не трать времени даром, твой народ нуждается в тебе.", female = "Да благословит тебя Элуна, героиня! Надеюсь, что Свет не покидает тебя. Тебя недавно разыскивал один из наших жрецов. Он просил передать тебе, что в Соборе Света Штормграда тебя ожидает Верховная жрица Лорена. Не трать времени даром, твой народ нуждается в тебе." },
    ["5636c"] = { common = "Я рада твоему прибытию. Есть множество вещей, которые нам нужно обсудить, но самая важная – твоё будущее обучение тайному знанию Света. Есть уроки, которые должны выучить все, кто служит Свету. Если ты чувствуешь в себе силы, мы можем начать прямо сейчас." },
    ["5637a"] = { common = "Тебе пора отправляться в Штормград. Верховная жрица Лорена ожидает тебя в Соборе Света, она хочет поговорить с тобой. Должно случиться что-то особенное, если тобой заинтересовалась сама Верховная жрица. Не знаю, к добру это или к худу. Думаю, что так или иначе всё это окажется полезным для тебя. Не трать много времени, собирайся быстрее." },
    ["5637c"] = { common = "Я рада тебя видеть! Нам есть о чём поговорить, но твоё обучение важнее всего, ведь это – путь Света. Есть знание, которым должны овладеть все прислужники Света. Чувствуешь ли ты в себе достаточно сил? Если да, то перейдём к обсуждению." },
    ["5638a"] = { male = "Эй, герой! Тебя недавно искал один из ваших жрецов! Он просил тебе передать, что тебя очень ждут в Соборе Света. Ещё сказал, что это очень важно, и мне кажется, что ему стоит верить. Он был настроен весьма благодушно, так что для тебя это хорошие новости. Тебе стоит поторопиться, чтобы не упустить этот шанс. Да хранит тебя Элуна, герой.", female = "Эй, героиня! Тебя недавно искал один из ваших жрецов! Он просил тебе передать, что тебя очень ждут в Соборе Света. Ещё сказал, что это очень важно, и мне кажется, что ему стоит верить. Он был настроен весьма благодушно, так что для тебя это хорошие новости. Тебе стоит поторопиться, чтобы не упустить этот шанс. Да хранит тебя Элуна, героиня." },
    ["5638c"] = { common = "Очень хорошо, что вы прибыли, путник. Нам нужно многое обсудить, но для начала, нам необходимо заняться вашим обучением в пути Света. Существуют уроки, которым должны обучаться все служители Света. Если вы готовы, тогда мы начнём обучение." },
    ["5639a"] = { common = "Тебя ждут в Штормграде! Верховная жрица Лорена говорит, что тебе пора доказать свою способность перейти на новый уровень подготовки. Не мешкай. Ты найдёшь Лорену в Соборе Света в центре города. Передай ей от меня привет и постарайся не завалить экзамен. Да хранит тебя Свет!" },
    ["5639c"] = { common = "Я рада тебя видеть! Нам есть о чём поговорить, но твоё обучение важнее всего, ведь это – путь Света. Есть знание, которым должны овладеть все прислужники Света. Чувствуешь ли ты в себе достаточно сил? Если да, то перейдём к обсуждению." },
    ["5640a"] = { common = "Благословенна будь Элуна, чей свет хранит тебя! Сейчас многие члены нашего ордена решили укрепить свои познания и веру в силу Элуны. Как я знаю, и в твоём ордене происходит то же самое. Когда закончишь свои дела в Дарнассе, отправляйся к вашей Верховной жрице, дабы получить новые знания." },
    ["5641c"] = { common = "У тебя есть великие задатки жреца, путник. Продолжай в этом же направлении! Ты доказал что готов к бою. Возможно, пришло время научить тебя чему-то большему, чем немного." },
    ["5642a"] = { common = "В Оргриммаре происходит нечто важное. Обычно посланцы, которые приезжают сюда за троллями-жрецами, держатся с ленцой. А на этот раз они, похоже, спешили! Не засиживайся в Громовом Утёсе. Думаю, тебе стоит как можно скорее вернуться на Аллею Духов." },
    ["5642c"] = { male = "Тебя ждёт один из самых важных обрядов инициации для жреца нашей веры. Я вижу, что ты готов к нему, и потому сейчас объясню всё подробнее.", female = "Тебя ждёт один из самых важных обрядов инициации для жреца нашей веры. Я вижу, что ты готова к нему, и потому сейчас объясню всё подробнее." },
    ["5643a"] = { common = "Как и многие из наших жрецов, члены твоего племени проходят обряды инициации. Эти обряды часто наделяют жрецов особыми способностями, которые помогают им выжить. Я чувствую, что тебе пришло время пройти такой обряд. Возвращайся в Аллею Духов в Оргриммаре и поговори с Ур'кьо. То, чему он тебя научит, может оказаться чрезвычайно важным в будущем." },
    ["5643c"] = { common = "Твои обряды наступят очень скоро. Сейчас я обучу тебя заклинанию, которое поможет тебе в сражении против твоих врагов." },
    ["5644a"] = { male = "Доброго тебе дня. Вижу, ты многому научился, и пришло время вернуться к Эльталисте. Есть вещи, рассказать о которых может лишь она, и то лишь самым достойным. Я не скажу, что тебя ждёт – пусть для тебя это будет сюрпризом. Хотя, помнится, когда я был молодым жрецом и только-только понял, что есть истинная сила... божественная сила... Вот это были деньки. Отправляйся в Подгород, поговори с Эльталисте. Она ждёт тебя в Квартале Воинов.", female = "Доброго тебе дня. Вижу, ты многому научилась, и пришло время вернуться к Эльталисте. Есть вещи, рассказать о которых может лишь она, и то лишь самым достойным. Я не скажу, что тебя ждёт – пусть для тебя это будет сюрпризом. Хотя, помнится, когда я был молодым жрецом и только-только понял, что есть истинная сила... божественная сила... Вот это были деньки. Отправляйся в Подгород, поговори с Эльталисте. Она ждёт тебя в Квартале Воинов." },
    ["5644c"] = { male = "Отлично, ты вернулся и даже не опоздал. Нам нужно обсудить кое-что важное. Твоя сила растёт, и надо подготовить тебя к грядущим испытаниям.", female = "Отлично, ты вернулась и даже не опоздала. Нам нужно обсудить кое-что важное. Твоя сила растёт, и надо подготовить тебя к грядущим испытаниям." },
    ["5645a"] = { male = "Ваш верховный жрец Рохан назначает вам аудиенцию в Стальгорне. Торопитесь, могучий мой друг, ибо близится срок вашего очередного испытания. Хотя я хотел бы стать свидетелем особых обрядов вашей расы, но моё место здесь. Но да пребудет с вами Свет в пути вашем. Когда вы достигнете города, Рохан будет ждать вас в Палатах Магии.", female = "Ваш верховный жрец Рохан назначает вам аудиенцию в Стальгорне. Торопитесь, могучая моя госпожа, ибо близится срок вашего очередного испытания. Хотя я хотел бы стать свидетелем особых обрядов вашей расы, но моё место здесь. Но да пребудет с вами Свет в пути вашем. Когда вы достигнете города, Рохан будет ждать вас в Палатах Магии." },
    ["5645c"] = { male = "Хорошо, что ты пришёл. Наша раса горда и могуча, и пришла пора научиться быть таким не только самому, но и вселять эти чувства в сердца других. готов ли ты, юноша?", female = "Хорошо, что ты пришла. Наша раса горда и могуча, и пришла пора научиться быть таким не только самому, но и вселять эти чувства в сердца других. готова ли ты, девушка?" },
    ["5646a"] = { common = "Эльталисте оказала моему народу большое доверие, посылая ко мне учеников, а теперь я сделаю то же для её племени. Возвращайся в Подгород. Твоя госпожа ждёт тебя в Квартале Воинов, чтобы рассказать ещё больше о твоём народе и его обычаях. Ступай, не медли." },
    ["5646c"] = { male = "Отлично, ты вернулся и даже не опоздал. Нам нужно обсудить кое-что важное. Твоя сила растёт, и надо подготовить тебя к грядущим испытаниям.", female = "Отлично, ты вернулась и даже не опоздала. Нам нужно обсудить кое-что важное. Твоя сила растёт, и надо подготовить тебя к грядущим испытаниям." },
    ["5647a"] = { common = "Твоя раса так сильна. Мы гордимся союзом с вами. С каждым закатом ты и твои сородичи не только всё ближе к разгадке вашего истинного происхождения, но и обретаете всё большую уверенность в том, что вы на верном пути во многом. Именно эта уверенность приносит вам победу. Недавно из Стальгорна пришла весть. Тебя просят вернуться и поговорить с верховным жрецом Роханом в Палатах Магии. Не стоит заставлять его ждать. Да направит твой путь Элуна." },
    ["5647c"] = { common = "У тебя есть великие задатки героя, путник. Продолжай в этом же направлении! Ты доказал что готов к бою. Возможно, пришло время научить тебя чему-то большему, чем немного." },
    ["5648a"] = { male = "Что ж, вот ты и готов к своему первому испытанию. К югу от Колючего Холма, сразу за городской чертой, лежит раненная орчиха из нашего отряда. Она сражалась с остатками прежнего Праудмурова войска, и ей не повезло в бою. Помочь ей может только кто-то из нас. Её зовут Корджа. Найди её, исцели и дай ей благословение наших предков. Сделай это – и я сочту, что ты подтвердил свою готовность ступить на путь жреца.", female = "Что ж, вот ты и готова к своему первому испытанию. К югу от Колючего Холма, сразу за городской чертой, лежит раненная орчиха из нашего отряда. Она сражалась с остатками прежнего Праудмурова войска, и ей не повезло в бою. Помочь ей может только кто-то из нас. Её зовут Корджа. Найди её, исцели и дай ей благословение наших предков. Сделай это – и я сочту, что ты подтвердила свою готовность ступить на путь жреца." },
    ["5648c"] = { male = "Отлично! Так значит, Корджа жива и может снова защищать наш город от злокозненных людей? Я люблю вспоминать дни битв, когда подлинная сила проявлялась в бою. Тогда часто случалось, что мудрые губили тех, кто недооценивал их, полагаясь лишь на мощь мышц. Я считаю, что ты молодец. Вот, возьми это одеяние. Может быть, оно тебе пригодится. Может быть, тебе всё равно, однако ты его заслужил, и я горжусь тем, что теперь могу звать тебя братом.", female = "Отлично! Так значит, Корджа жива и может снова защищать наш город от злокозненных людей? Я люблю вспоминать дни битв, когда подлинная сила проявлялась в бою. Тогда часто случалось, что мудрые губили тех, кто недооценивал их, полагаясь лишь на мощь мышц. Я считаю, что ты молодец. Вот, возьми это одеяние. Может быть, оно тебе пригодится. Может быть, тебе всё равно, однако ты его заслужила, и я горжусь тем, что теперь могу звать тебя сестрой." },
    ["5649a"] = { male = "Понимаешь, наш народ присоединился к Орде, потому что они к нам добры. Они – преданные друзья, они многому нас научили, внушили нам представление о чести... Но наши старые обычаи ещё живы. Орки не одобряют многие из них, но никто не мешает нам придерживаться их втайне. Ты это знаешь. Вот почему я посылаю тебя в Колючий Холм, к Тай'джин. Она откроет тебе мудрость нашего племени. Ступай к ней, когда будешь готов.", female = "Понимаешь, наш народ присоединился к Орде, потому что они к нам добры. Они – преданные друзья, они многому нас научили, внушили нам представление о чести... Но наши старые обычаи ещё живы. Орки не одобряют многие из них, но никто не мешает нам придерживаться их втайне. Ты это знаешь. Вот почему я посылаю тебя в Колючий Холм, к Тай'джин. Она откроет тебе мудрость нашего племени. Ступай к ней, когда будешь готова." },
    ["5649c"] = { common = "Ах-ха... наконец-то твой путь привёл тебя к Тай'джин. Это хорошо. Теперь ты знаешь, что мы уже не то племя, что когда-то присоединилось к Орде. Мы стали гораздо сильнее. Мы обрели эту силу потому, что научились приспосабливаться – это мы переняли у Орды. Прежде мы побеждали врагов и забирали их силу, теперь же мы набираемся сил, а потом побеждаем врагов. Возможно, разница не столь заметна, но ты её поймёшь. Ты увидишь. Племя рассчитывает на то, что ты научишься видеть такие вещи." },
    ["5650a"] = { common = "Мы черпаем силу из тьмы и теней, но ваше дело – не только дело тьмы. Вы поняли, что большая заслуга есть и в изучении искусства лечения. Это мудрый выбор. Но прежде чем познать тьму, вы должны познать и свет, а для этого нужно пройти испытание. К северу от кладбища находится раненый страж смерти по имени Кел – он уже очень долго защищает нас от гноллов, и ему требуется лечение. Но для того чтобы он мог и дальше исполнять свой долг, вы должны также придать ему сил. Используйте для этого свои заклинания, а потом возвращайтесь ко мне." },
    ["5650c"] = { common = "Вы с лёгкостью выдержали моё испытание. Это хорошо. Скоро вы будете готовы принять на себя ещё большую ответственность, и этот путь приведёт вас к более тёмным силам – таким, которыми не обладает ни один жрец другой расы. Примите это одеяние в знак вашего положения. Вы его заслужили. Если же вы не хотите его носить, что ж, тогда вы вольны поступить с ним так, как вам будет угодно. Я и другие и так никогда не забудем того положения, которого вы достигли в наших рядах." },
    ["5651a"] = { common = "Отрёкшиеся извлекли много уроков из своего опыта и поняли такие вещи, о которых остальные только начинают догадываться. И несмотря на то что наш путь лежит во тьме, скоро вы поймёте, что очень много вещей зависит от неё – так же как и от света. Вы научитесь использовать и то и другое... с должной осторожностью. Но никогда не забывайте того, что нас создали в тлене и бросили гнить, как какие-нибудь отбросы. Тьма – это наш дом. Когда будете готовы узнать больше, разыщите тёмного священника Берила в Брилле." },
    ["5651c"] = { common = "Наконец-то вы прибыли! Чтобы пройти испытания, одной веры не достаточно. Нужно ещё чувство долга и немного амбиций." },
    ["5652c"] = { common = "На этом уроке не мешало бы взглянуть на такое заклинание, как обессиливающий сглаз. Оно поможет тебе в твоих грядущих сражениях." },
    ["5654a"] = { common = "Пора тебе встретиться с Ур'кьо. Ты найдёшь его на аллее Духов, в городе орков. Ступай туда и поговори с ним. Пора тебе познать древнюю мудрость нашего народа. Пора вступить в круг и стать настоящим жрецом нашего племени." },
    ["5654c"] = { common = "А, ты здесь! Это хорошо. Теперь мы можем начать твоё обучение." },
    ["5655a"] = { common = "Мне нужно было удостовериться, что ты не уйдёшь слишком далеко от дома. Меня послали за тобой потому, что Ур'кьо, величайший из наших жрецов, желает поговорить с тобой. Ступай туда. Ступай в Аллею Духов в городе орков и поговори с Ур'кьо. Он ждёт тебя." },
    ["5655c"] = { common = "На этом уроке не мешало бы взглянуть на такое заклинание, как обессиливающий сглаз. Оно поможет тебе в твоих грядущих сражениях." },
    ["5656a"] = { common = "Моё нестареющее сердце всегда греет мысль о том, что по миру бродит множество жрецов всех культур. Хорошо знать, что на свете есть сила, не имеющая отношения к тайной магии и вполне доступная нам. Вот почему я сочту за честь указать тебе путь. Уркьо, ваш великий жрец в Оргриммаре, просит тебя прибыть к нему. Ты найдёшь его на аллее Духов." },
    ["5656c"] = { common = "На этом уроке не мешало бы взглянуть на такое заклинание, как обессиливающий сглаз. Оно поможет тебе в твоих грядущих сражениях." },
    ["5657a"] = { male = "Домой! Возвращайся домой, юный герой! Твой духовный наставник Ур'кьо просит тебя вернуться к нему и поговорить об избранном тобой пути. Ступай в Аллею Духов в Оргриммаре, великом городе Орды! Ты найдёшь его там.", female = "Домой! Возвращайся домой, юная героиня! Твой духовный наставник Ур'кьо просит тебя вернуться к нему и поговорить об избранном тобой пути. Ступай в Аллею Духов в Оргриммаре, великом городе Орды! Ты найдёшь его там." },
    ["5657c"] = { common = "На этом уроке не мешало бы взглянуть на такое заклинание, как обессиливающий сглаз. Оно поможет тебе в твоих грядущих сражениях." },
    ["5660a"] = { male = "Далеко же ты забрался, герой. Тебя ждут в большом городе под землёй. Твоя госпожа, Эльталисте, велит тебе вернуться. Как и в моём племени, есть вещи, которым тебя может научить лишь она. И не задерживайся попусту. Лучше лети в Квартал Воинов на самом быстром дирижабле.", female = "Далеко же ты забралась, героиня. Тебя ждут в большом городе под землёй. Твоя госпожа, Эльталисте, велит тебе вернуться. Как и в моём племени, есть вещи, которым тебя может научить лишь она. И не задерживайся попусту. Лучше лети в Квартал Воинов на самом быстром дирижабле." },
    ["5660c"] = { male = "А, вот и ещё один. Для меня время не имеет значения, но для тебя оно бежит быстро. Тебе следует многому научиться, и я хочу передать тебе побольше знаний. А пока покажи, на что способен. Выполни это условие, и награда будет велика.", female = "А, вот и ещё одна. Для меня время не имеет значения, но для тебя оно бежит быстро. Тебе следует многому научиться, и я хочу передать тебе побольше знаний. А пока покажи, на что способна. Выполни это условие, и награда будет велика." },
    ["5661a"] = { common = "Ты всего лишь гость в деревне Кровавого Копыта, а дом твой далеко. Меня послали сюда искать жрецов из моего племени. С ними хотят говорить вожди. Но и тебе я могу помочь. Говорят, что ваша главная жрица велит всем Отрёкшимся прийти к ней – видно, ей есть что сказать. Ступай, поговори с Эльталисте в Квартале воинов этого вашего города, как его там..." },
    ["5661c"] = { male = "А, хорошо, ещё один прибыл. Время для меня не имеет значения, но для других-то оно ценно. Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь вознаграждён.", female = "А, хорошо, ещё одна прибыла. Время для меня не имеет значения, но для других-то оно ценно. Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь вознаграждена." },
    ["5662a"] = { common = "Моё почтение тебе и твоему народу. Обычно я учу лишь своих соплеменников. Тебе же передала знания Эльталисте из города, некогда звавшегося Лордероном. Возвращайся к ней, ведь только она может передать тебе способности, отличающие воинов вашей веры от других. Ступай в Квартал Воинов Подгорода и отыщи там свою госпожу." },
    ["5662c"] = { male = "А, вот и ещё один. Для меня время не имеет значения, но для тебя оно бежит быстро. Тебе следует многому научиться, и я хочу передать тебе побольше знаний. А пока покажи, на что способен. Выполни это условие, и награда будет велика.", female = "А, вот и ещё одна. Для меня время не имеет значения, но для тебя оно бежит быстро. Тебе следует многому научиться, и я хочу передать тебе побольше знаний. А пока покажи, на что способна. Выполни это условие, и награда будет велика." },
    ["5663a"] = { male = "Эльталисте послала вести всем своим жрецам. Нам велено отправить молодёжь в Подгород на обучение. Если ты в самом деле считаешь себя одним из верных, возвращайся туда. Эльталисте живёт в Квартале Воинов в глубинах Подгорода.", female = "Эльталисте послала вести всем своим жрецам. Нам велено отправить молодёжь в Подгород на обучение. Если ты в самом деле считаешь себя одной из верных, возвращайся туда. Эльталисте живёт в Квартале Воинов в глубинах Подгорода." },
    ["5663c"] = { male = "А, хорошо, ещё один прибыл. Время для меня не имеет значения, но для других-то оно ценно. Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь вознаграждён.", female = "А, хорошо, ещё одна прибыла. Время для меня не имеет значения, но для других-то оно ценно. Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь вознаграждена." },
    ["5672c"] = { common = "Посвятив себя Элуне и нашему народа, ты достиг того состояния, которого не все из нас могут достичь." },
    ["5673a"] = { common = "Знай, что здесь ты можешь в любое время обратиться к любому наставнику. Впрочем, есть знания, которые мы не можем тебе предоставить. Среди них – учение вашей богини Элуны. Верным своим приверженцам она даёт особые способности, и, если я не ошибаюсь, тебе пора вернуться домой, в Храм Луны, и пройти испытание. Так что как сможешь – возвращайся и поговори со жрицей Алатеей." },
    ["5673c"] = { common = "Да благословит тебя Элуна за столь скорое возвращение. Это важный период в твоём обучении, и орден весьма серьёзно к этому относится. Когда отдохнёшь с дороги, дай мне знать. Тогда мы сможем поговорить о продолжении твоего обучения и о том, куда на сей раз приведёт тебя твой путь." },
    ["5674a"] = { male = "Настал славный день. Ты достиг возраста, когда наши жрецы изучают те способности, которые свойственны только ночным эльфам. Тебе следует вернуться в Храм Луны и поговорить со жрицей Алатеей, как только закончишь тут свои дела. Она испытает тебя, убедится в твоей готовности и лишь потом научит тебя Благодати Элуны.", female = "Настал славный день. Ты достигла возраста, когда наши жрицы изучают те способности, которые свойственны только ночным эльфам. Тебе следует вернуться в Храм Луны и поговорить со жрицей Алатеей, как только закончишь тут свои дела. Она испытает тебя, убедится в твоей готовности и лишь потом научит тебя Благодати Элуны." },
    ["5674c"] = { common = "Посвятив себя Элуне и нашему народа, ты достиг того состояния, которого не все из нас могут достичь." },
    ["5675a"] = { male = "Не тяни время, друг. Пора тебе возвращаться домой в Дарнасс. Жрица Алатея велит возвращаться на обучение. Похоже, тебя решили допустить к испытаниям вроде тех, что проходят служители Света. Так что как сможешь – иди. Алатея в своём письме говорит, что будет ждать тебя в храме Луны. Удачи.", female = "Не тяни время, подруга. Пора тебе возвращаться домой в Дарнасс. Жрица Алатея велит возвращаться на обучение. Похоже, тебя решили допустить к испытаниям вроде тех, что проходят служители Света. Так что как сможешь – иди. Алатея в своём письме говорит, что будет ждать тебя в храме Луны. Удачи." },
    ["5675c"] = { common = "Элуна благословляет тебя за столь быстрое возвращение. Важное дело ожидает тебя, и важные дела ждут твоего решения. Когда отдохнёшь от своего путешествия, повидай меня снова. Тогда мы обсудим, как именно мы начнём… точнее продолжим, твою тренировку!" },
    ["5676c"] = { common = "Я буду обучать тебя новому заклинанию, которое поможет тебе защитить себя и своих союзников." },
    ["5677a"] = { common = "Мне бы хотелось показать тебе кое-какие из наших особых методик обучения, которые направят тебя по пути Света, но меня опередили. Тебе нужно вернуться в Штормград... Прямо сейчас. Поверь мне, так будет лучше. Когда ты встретишься с Верховной жрицей Лореной из Собора Света, ты поймёшь, о чём я говорю. Для вашей расы настало время подумать о будущем и выбрать свой собственный путь." },
    ["5677c"] = { common = "Ах, у вас сейчас чудесное время. Я начал задаваться вопросом, все ли мои посланники были успешными. Я рад видеть, что это так, иначе я готов поспорить, что вы всё ещё были бы в мире, узнавая больше обо-всех угрозах, которые существуют против нашего народа. Вы готовы? Я имею в виду готовы к дальнейшим тренировкам. Ваша сила растёт быстрее, и я чувствую, что вы готовы больше узнать о нашей вере." },
    ["5678a"] = { common = "Тебе пора возвращаться в Штормград. Старшие иерархи призывают тебя продолжить тренировки. Жаль, что мне пришлось разыскивать тебя, но я делаю это во имя союза между нашими расами. Буду говорить откровенно, тайная магия не внушает мне никакого доверия, хоть по благословлению богов, хоть без них... Ты понимаешь, о чём я говорю? Вернись в Собор Света. Верховная жрица Лорена ждёт тебя." },
    ["5678c"] = { common = "Ах, у вас сейчас чудесное время. Я начал задаваться вопросом, все ли мои посланники были успешными. Я рад видеть, что это так, иначе я готов поспорить, что вы всё ещё были бы в мире, узнавая больше обо-всех угрозах, которые существуют против нашего народа. Вы готовы? Я имею в виду готовы к дальнейшим тренировкам. Ваша сила растёт быстрее, и я чувствую, что вы готовы больше узнать о нашей вере." },
    ["5680c"] = { common = "Твои обряды наступят очень скоро. Сейчас я обучу тебя заклинанию, которое поможет тебе в сражении против твоих врагов." },
    ["5713a"] = { common = "Я направлялась в Аубердин с важным донесением, когда меня атаковал фурболг Марош и его следопыты. Во время атаки я получила отравление, так что еле держусь. Я могу изготовить противоядие, но это займёт некоторое время. Хотела попросить вас защитить меня, пока я не приму противоядие. Я подсоблю вам своим луком, как смогу. Если мы выживем, то смогу доставить донесение в Аубердин, а вас попрошу поговорить с Онейей на Заставе Мейстры и проинформировать её о случившемся." },
    ["5713c"] = { male = "Вы принесли долгожданное известие, герой. Приятно слышать, что Айнаша жива и здорова благодаря вам. Смею надеяться, вы примете эту награду за вашу доблесть. Пусть Элуна заботится о вас и освещает ваш путь.", female = "Вы принесли долгожданное известие, героиня. Приятно слышать, что Айнаша жива и здорова благодаря вам. Смею надеяться, вы примете эту награду за вашу доблесть. Пусть Элуна заботится о вас и освещает ваш путь." },
    ["5721a"] = { common = "Теперь, путник, тебе предстоит принять участие в битве при Дарроушире и спасти Джозефа Редпата. Положи реликвии на городскую площадь Дарроушира, и духи его жителей восстанут из могил. Начнётся битва, и ты должен сделать всё возможное, чтобы Дейвил выжил в битве с Хоргусом, а Редпат должен подвергнуться порче и после этого быть убитым. В этом случае дух Редпата будет спасён. Поговори с ним и возвращайся к его дочери Памеле." },
    ["5722a"] = { common = "В Огненной пропасти Магату интересуют не только трогги. До неё дошли слухи, что один из её слуг, некий Маур Зловещий Тотэм, будучи в пропасти, нашёл нечто особенное, но выбраться оттуда ему не удалось. Она хочет, чтобы кто-нибудь нашёл тело Маура – если оно ещё цело – и выяснил, что же он такое нашёл, пытаясь вести переговоры с троггами. Если найдёшь что-нибудь интересное, принеси это Магате, и она наверняка не поскупится на награду. Да, пропасть ищи в самых тёмных закоулках Оргриммара." },
    ["5722c"] = { common = "Тело выглядит так, будто Маура жестоко били дубинками или кулаками, но большая часть одежды и снаряжения на месте. Похоже, троггам не сильно были нужны его пожитки. Вы начинаете осматривать тело в поисках любых предметов, которые могли бы заинтересовать Магату." },
    ["5723a"] = { common = "Назойливые твари, известные как трогги, вдруг полезли из заполненных лавой туннелей под Оргриммаром. Магата по своей доброте душевной хотела договориться с этими тварями, но они набросились на её переговорщиков и перебили их. Но такого обращения с тауренами она допустить не может, так что теперь для неё эти твари – враги Орды. Она просит тебя разделаться с этими троггами, прежде чем они начнут угрожать Орде из-под земли. Найди Огненную пропасть и уничтожь их всех!" },
    ["5723c"] = { common = "Я рад, что ты серьёзно отнёсся к просьбе Магаты. Спасибо тебе. Теперь, когда троггов поубавилось, они уже не полезут так нагло на поверхность! Может, в будущем мы сумеем узнать, откуда взялись эти твари, и что им надо." },
    ["5724a"] = { common = "Под телом погибшего таурена вы находите сумку. Убитый до сих пор крепко держит её – видимо, он пытался уберечь её во время нападения троггов. Высвободив сумку из его крепкой хватки, вы закидываете её себе на плечо и готовитесь возвращаться наружу из туннелей, чтобы отправиться к Рахауро в Громовой Утёс." },
    ["5724c"] = { common = "Прекрасно. Благодарю тебя. Магата сказала мне, что если ты найдёшь её сородича, то я должен отдать тебе вот это. Прошу, прими в знак благодарности." },
    ["5725a"] = { common = "Тебе хорошо известно, что в Легионе принято всячески одаривать идейных последователей. Некоторым из этих даров лучше бы оказаться в руках у Тёмной Госпожи, чем у... простецов. Например, в пещерах под Оргриммаром скрывается секта Совета Теней, известная как \"Огненный Клинок\". Госпожа сообщила, что они получили две могущественные книги заклинаний – она хотела бы \"позаимствовать\" их. Выполни её волю." },
    ["5725c"] = { male = "Молодец, герой. Ты оказал Тёмной Госпоже хорошую услугу. Её подданным пригодятся твои упорство и честолюбие. Заходи ко мне в будущем. Быть может, я отправлю тебя на новые подвиги, которые помогут Тёмной Госпоже свергнуть Короля-лича и освободить рабов Плети.", female = "Молодец, героиня. Ты оказала Тёмной Госпоже хорошую услугу. Её подданным пригодятся твои упорство и честолюбие. Заходи ко мне в будущем. Быть может, я отправлю тебя на новые подвиги, которые помогут Тёмной Госпоже свергнуть Короля-лича и освободить рабов Плети." },
    ["5726a"] = { male = "Чего я не потерплю, так это предательства среди своих. Однако было бы глупо действовать напролом и сразу арестовать единственного известного мне предателя – это не очистит наши земли от порчи, наоборот, зараза расползётся ещё сильнее. Но ты, юный искатель приключений, можешь проникнуть туда, куда моим агентам ходу нет. Ты можешь узнать правду... можешь обнаружить настоящего главу заговора! Если у тебя достаточно отваги, отправляйся к скале Черепа к востоку от Оргриммара, сорви с одного из чернокнижников клана Пылающего Клинка лейтенантский знак отличия и принеси его мне.", female = "Чего я не потерплю, так это предательства среди своих. Однако было бы глупо действовать напролом и сразу арестовать единственного известного мне предателя – это не очистит наши земли от порчи, наоборот, зараза расползётся ещё сильнее. Но ты, юная искательница приключений, можешь проникнуть туда, куда моим агентам ходу нет. Ты можешь узнать правду... можешь обнаружить настоящего главу заговора! Если у тебя достаточно отваги, отправляйся к скале Черепа к востоку от Оргриммара, сорви с одного из чернокнижников клана Пылающего Клинка лейтенантский знак отличия и принеси его мне." },
    ["5726c"] = { common = "Молодец! Слава духам! Быть может, именно ты – тот, кому суждено избавить меня от самых серьёзных моих опасений! Ну кто бы мог подумать, что столь юное существо, как ты, сумеет достойно защитить наше дело? Ты мне напоминаешь меня самого в молодости... Я позабочусь о том, чтобы тебя достойно вознаградили за труды – если мы оба переживём грядущую бурю. Ладно, сейчас не время рассыпаться в похвалах. То, что тебе уже удалось совершить, – пустяки в сравнении с тем, что ещё предстоит... Но начало положено хорошее." },
    ["5727a"] = { male = "Ну-ка, посмотрим, стоил ли принесённый тобой знак отличия таких усилий. В городе живёт чернокнижник, который уверен, будто я ему полностью доверяю. Он и не подозревает, что мне известно о его предательстве. На самом деле он – предводитель Пылающего Клинка... Однако не торопись вступать с ним в бой. Он нам ещё нужен, мы можем использовать его, чтобы навредить нашим врагам. Отнеси ему этот знак отличия в расселину Теней в Оргриммаре, поговори с ним и проверь, примет ли он тебя за одного из своих. А потом возвращайся ко мне.", female = "Ну-ка, посмотрим, стоил ли принесённый тобой знак отличия таких усилий. В городе живёт чернокнижник, который уверен, будто я ему полностью доверяю. Он и не подозревает, что мне известно о его предательстве. На самом деле он – предводитель Пылающего Клинка... Однако не торопись вступать с ним в бой. Он нам ещё нужен, мы можем использовать его, чтобы навредить нашим врагам. Отнеси ему этот знак отличия в расселину Теней в Оргриммаре, поговори с ним и проверь, примет ли он тебя за одну из своих. А потом возвращайся ко мне." },
    ["5727c"] = { male = "Великолепно, герой! Просто великолепно! Твоё сегодняшнее деяние – всего лишь первый шаг к куда более серьёзным делам. Возможно, это поможет нам уничтожить Совет Теней раз и навсегда. Перескажи мне всё, что он говорил, и смотри, не упусти ни слова: какой-нибудь пустяк может оказаться важнее, чем ты думаешь.", female = "Великолепно, героиня! Просто великолепно! Твоё сегодняшнее деяние – всего лишь первый шаг к куда более серьёзным делам. Возможно, это поможет нам уничтожить Совет Теней раз и навсегда. Перескажи мне всё, что он говорил, и смотри, не упусти ни слова: какой-нибудь пустяк может оказаться важнее, чем ты думаешь." },
    ["5728a"] = { male = "Хм, предводители клана Огненного Клинка... Это серьёзно. Если Нииру ими дорожит, значит, именно их и нужно ликвидировать. Этот сатир... Баззалан, и тот, второй, которого упоминал Нииру, – он кто, чернокнижник? – их следует убить. Возвращайся в расселину Теней и проникни в Огненную пропасть. Разыщи этих предводителей клана Огненного Клинка и убей их. Но будь осторожен, чтобы Нииру не узнал, что это твоих рук дело. Пусть по-прежнему считает тебя одним из братьев по оружию.", female = "Хм, предводители клана Огненного Клинка... Это серьёзно. Если Нииру ими дорожит, значит, именно их и нужно ликвидировать. Этот сатир... Баззалан, и тот, второй, которого упоминал Нииру, – он кто, чернокнижник? – их следует убить. Возвращайся в расселину Теней и проникни в Огненную пропасть. Разыщи этих предводителей клана Огненного Клинка и убей их. Но будь осторожна, чтобы Нииру не узнал, что это твоих рук дело. Пусть по-прежнему считает тебя одной из сестёр по оружию." },
    ["5728c"] = { common = "Я рад, что ты вернулся. Преданные мне агенты уже сообщили, что в пещерах под Оргриммаром воцарился хаос – теперь, когда их предводители убиты. Мне даже докладывали, что Нииру более чем взбудоражен. Похоже, мы пробили брешь в его броне. Не могу не признать, что меня это радует... Пусть небольшая, но всё же победа." },
    ["5729a"] = { common = "Думаю, теперь тебе следует попытаться войти в число приближённых Нииру. Если он действительно так взбудоражен, как мне доносят, мы убьём сразу двух зайцев. Во-первых, тебе, возможно, удастся разузнать побольше о Совете или, по крайней мере, о Пылающем Клинке, и, во-вторых, он, возможно, начнёт доверять тебе настолько, что попросит ему помогать. Ему сейчас отчаянно не хватает помощников. Возвращайся в Расселину и поговори с ним, но не особо навязывайся." },
    ["5729c"] = { male = "Ну в чём дело?! Ах, это ты, герой... Прошу прощения. Я зол, как бешеный кодо... Но, возможно, я сам во всём виноват. Отправляя путешественников в Огненную пропасть, я должен был предвидеть, что это чревато проблемами. Похоже, что Баззалана и Жергоша застиг врасплох кто-то из Тралловых доброхотов. Они оба убиты. Как это невовремя! Но тут уж ничего не поделаешь.", female = "Ну в чём дело?! Ах, это ты, героиня... Прошу прощения. Я зол, как бешеный кодо... Но, возможно, я сам во всём виноват. Отправляя путешественников в Огненную пропасть, я должен был предвидеть, что это чревато проблемами. Похоже, что Баззалана и Жергоша застиг врасплох кто-то из Тралловых доброхотов. Они оба убиты. Как это невовремя! Но тут уж ничего не поделаешь." },
    ["5730a"] = { male = "Теперь ты один из моих лейтенантов! Готовься, герой. Скоро я призову тебя. Можно считать, что с Огненным Клинком я зря потратил время, но это не значит, что другие планы Совета Теней должны пострадать. Я сделаю всё, что смогу, чтобы свести к минимуму потери здесь, в Огненной пропасти. А пока что распоряжусь, чтобы мои агенты в Степях и Ясеневом лесу начали выполнять наши последние замыслы. Возвращайся ко мне как можно скорее.", female = "Теперь ты одна из моих лейтенантов! Готовься, героиня. Скоро я призову тебя. Можно считать, что с Огненным Клинком я зря потратил время, но это не значит, что другие планы Совета Теней должны пострадать. Я сделаю всё, что смогу, чтобы свести к минимуму потери здесь, в Огненной пропасти. А пока что распоряжусь, чтобы мои агенты в Степях и Ясеневом лесу начали выполнять наши последние замыслы. Возвращайся ко мне как можно скорее." },
    ["5730c"] = { common = "Ясеневый лес? Хм. Впервые слышу о присутствии Совета или Пылающего Клинка в Ясеневом лесу. Я поручу своим агентам это проверить. А ты молодец. Пока отдыхай, занимайся другими делами. Скоро я призову тебя снова. Лок-тар Огар!" },
    ["5741a"] = { common = "Говорят, что клан Пылающего Клинка, обосновавшийся на востоке в Крепости Громового Топора, заполучил Скипетр Света, добыв его у наг. Легенда гласит, что этот скипетр обладает властью погружать целые города в пучины моря. Мы не можем позволить, чтобы такая сила оставалась в их руках. Твой долг – вырвать скипетр из недостойных рук! Сейчас он у ясновидца из клана Пылающего Клинка на одной из башен крепости Громового Топора." },
    ["5741c"] = { male = "Неуловимый Скипетр Света!.. Добыв его, ты избавил мир от великой угрозы. Прекрасно, герой, просто прекрасно!..", female = "Неуловимый Скипетр Света!.. Добыв его, ты избавила мир от великой угрозы. Прекрасно, героиня, просто прекрасно!.." },
    ["5742a"] = { common = "Ты славно поработал, друг мой. Отдохни, а я пока расскажу тебе мою историю до конца." },
    ["5742c"] = { common = "Освобождение Фордринга будет непростой задачей. Ты готов к ней?" },
    ["5761a"] = { common = "Главная задача, которую поручил мне наш великий вождь, – это извести тех тварей, которые повинны в том, что в великий город нашего владыки проникают демоны. Клан Пылающего Клинка – главная, но не единственная угроза. Есть ещё и Огненный Клинок, клан, который обосновался в Огненной пропасти и втайне смущает умы простых представителей Орды. Чтобы их остановить, нужно убить их предводителя, стража Скверны по имени Тарагаман Ненасытный. Убей его. Я уверен, Вождь будет рад получить его сердце..." },
    ["5761c"] = { male = "Ага! Тебе это удалось! Тралл, конечно, будет в восторге. Я позабочусь о том, чтобы это сердце попало по назначению. Ну, а ты можешь отпраздновать свою победу. Я сообщу Траллу о твоём успехе. Спасибо за помощь, герой.", female = "Ага! Тебе это удалось! Тралл, конечно, будет в восторге. Я позабочусь о том, чтобы это сердце попало по назначению. Ну, а ты можешь отпраздновать свою победу. Я сообщу Траллу о твоём успехе. Спасибо за помощь, героиня." },
    ["5762a"] = { common = "У меня тут посылка для одного старого покупателя, дворфа по имени Хеминг Эрнестуэй. Посылка шла очень долго, и Хеминг уехал, не дождавшись её. Говорят, что теперь он где-то в Тернистой долине, охотится там на зверей. Перед отъездом он оставил мне немного денег, чтобы я переслал ему посылку. Он очень богатый дворф, а с такими полезно водить дружбу, правда? Так что... не желаешь ли доставить Хемингу эту посылку? Говорят, он разбил лагерь в Тернистой долине, к северу от Гром'гола." },
    ["5762c"] = { common = "Отлично, посылочка от Углебрада! Спасибо! В этом ящике находится специальное измерительное оборудование, – по крайней мере так сказал мой отец, – и в джунглях оно нам очень пригодится. Вот ваша плата, и расскажите мне, как там поживает старина Углебрад? Наверняка опять замышляет какую-нибудь пакость?" },
    ["5763a"] = { common = "Давным-давно пришёл в эти земли дворф. Звали его Хеминг, и он хотел поохотиться на крупного зверя. С ружьём он умел обращаться просто великолепно, и много дней мы охотились с ним вместе, забыв даже о вражде, разделявшей наши народы… Когда он уходил в Тернистую долину, я поклялся, что, когда бы он ни вернулся, я встречу его как дорогого гостя. И вот это время пришло. Отнеси этот рог кодо в подарок Хемингу. Он поймёт, что это от меня. Ты найдёшь его в Тернистой долине, к северу от лагеря Гром'гол." },
    ["5763c"] = { common = "О, этот рог принадлежит таурену Руну Буйногривому! Отец часто рассказывал о том, как славно они вместе охотились в Пустошах. Значит, Рун приглашает меня на охоту, да? У нас сейчас дел по горло, но я всё равно благодарен тебе за добрую весть. Возможно, следующая моя экспедиция будет в Пустоши, в земли кентавров." },
    ["5781a"] = { common = "Чтобы помочь Таэлану вернуться на путь истинный, мы должны найти то, что напомнит ему о прошлом. Один из таких предметов — игрушка, которую я подарил ему на семилетие. Он очень дорожил этим маленьким боевым молотом, уменьшенной копией моего собственного оружия. Когда меня изгнали за предательство, его мать сказала сыну, что я погиб. Его отвели к моей пустой могиле в Крипте, и там он похоронил свой молот вместе со всеми воспоминаниями обо мне. Прошу тебя, отправляйся в Крипту и принеси молот Таэлана." },
    ["5781c"] = { common = "Это судьба свела нас вместе, путник. Благословение тебе!" },
    ["5801a"] = { common = "Чтобы выковать основу ключа тебе понадобится два ториевых слитка и мощный источник тепла. Торий добывай самостоятельно, а где найти подходящую плавильню, я подскажу. На западе от Кратера Ун'Горо располагается Вулкан Огненного Венца — действующий вулкан. Лава из его жерла сплавит торий и кость воедино. Твои денежки потрачены не зря — эту форму для отливки можно просто-напросто окунуть в огненное озеро, а остальное сделает лава. Вот и всё, чем я могу тебе помочь. Как доделать ключ тебе подскажет Арбингтон." },
    ["5801c"] = { common = "Недёшево обошлась тебе эта отмычка, а? И всё же работа над ней не закончена; пришло время завершающего этапа — а это самое сложное. Тебе придётся выступить против того самого врага, что ждал нас в Андорале… Злобной твари, которая правит бал в стенах разрушенного города. Я говорю об Араже Призывателе — личе, одном из самых могущественных сторонников Плети." },
    ["5802a"] = { common = "Чтобы выковать основу ключа тебе понадобится два ториевых слитка и мощный источник тепла. Торий добывай самостоятельно, а где найти подходящую плавильню, я подскажу. На западе от Кратера Ун'Горо располагается Вулкан Огненного Венца — действующий вулкан. Лава из его жерла сплавит торий и кость воедино. Твои денежки потрачены не зря — эту форму для отливки можно просто-напросто окунуть в огненное озеро, а остальное сделает лава. Вот и всё, чем я могу тебе помочь. Как доделать ключ тебе подскажет Дитерс." },
    ["5802c"] = { common = "Недёшево обошлась тебе эта отмычка, а? И всё же работа над ней не закончена; пришло время завершающего этапа — а это самое сложное. Тебе придётся выступить против того самого врага, что ждал нас в Андорале… Злобной твари, которая правит бал в стенах разрушенного города. Я говорю об Араже Призывателе — личе, одном из самых могущественных сторонников Плети." },
    ["5803a"] = { common = "Араж Призыватель правит Андоралом из самого сердца разрушенного города. Мы знаем, что он был главой Некроситета, пока не захватил целый город. Для завершения работы над ключом нам нужен его перстень — он называется скарабеем — из него мы создадим головку ключа. Проберись в сердце Андорала и лиши его власти над городом, теперь, когда с ним можно сражаться в открытую. Убив мерзавца, забери скарабея! Ключ от Некроситета ждёт тебя, путник!" },
    ["5803c"] = { common = "А, вот она! Я… поражён твоей отвагой и хитростью. У меня в голове не укладывается, на что ты готов пойти ради победы над силами тьмы. Позволь и мне сыграть свою небольшую роль в твоём подвиге. Я приготовил особый раствор, который позволит мне закрепить скарабея в верхней части ключа. Его сила отомкнёт двери Некроситета. Ну вот, остался пустячок…" },
    ["5804a"] = { common = "Араж Призыватель правит Андоралом из самого сердца разрушенного города. Мы знаем, что он был главой Некроситета, пока не захватил целый город. Для завершения работы над ключом нам нужен его перстень — он называется скарабеем — из него мы создадим головку ключа. Проберись в сердце Андорала и лиши его власти над городом, теперь, когда с ним можно сражаться в открытую. Убив мерзавца, забери скарабея! Ключ от Некроситета ждёт тебя, путник!" },
    ["5804c"] = { common = "А, вот она! Я… поражён твоей отвагой и хитростью. У меня в голове не укладывается, на что ты готов пойти ради победы над силами тьмы. Позволь и мне сыграть свою небольшую роль в твоём подвиге. Я приготовил особый раствор, который позволит мне закрепить скарабея в верхней части ключа. Его сила отомкнёт двери Некроситета. Ну вот, остался пустячок…" },
    ["5805a"] = { common = "Добро пожаловать в \"World of Warcraft\"! В знак особой благодарности за приобретение коллекционного издания \"World of Warcraft\" примите этот подарочный сертификат и передайте Мериссе Стилвелл в долине Североземья. Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе. Ещё раз благодарим вас и желаем приятного пребывания в \"World of Warcraft\"!" },
    ["5805c"] = { common = "Ну, теперь приветствую тебя в мире Азерота. Иди вперёд, к славе, наградам и почестям!" },
    ["5805p"] = { common = "Привет! Приятно видеть вас здесь. Я вижу у вас из кармана торчит Подарочный сертификат. Дайте его мне, и я дам вам кое-что взамен." },
    ["5821a"] = { male = "Обычно мы с Риггером проводим кодо мимо поселения кентавров из племени Колкар. Боевые барабаны кентавров слышно издалека, так что, едва заслышав их, мы останавливаемся, чтобы переждать опасность. Мёртвый торговец, знаешь ли, плохой торговец! Вот что я тебе скажу, герой: если ты будешь охранять нас по дороге мимо деревни Колкар, мы тебе за это хорошо заплатим. Расстояние-то небольшое, да и делать почти ничего не придётся – только проследить за тем, чтобы караван был цел. А награду ты получишь, не сомневайся: Смид Заржавень тебе сполна заплатит, мы с ним обделываем кое-какие делишки. Он живёт чуть дальше по дороге.", female = "Обычно мы с Риггером проводим кодо мимо поселения кентавров из племени Колкар. Боевые барабаны кентавров слышно издалека, так что, едва заслышав их, мы останавливаемся, чтобы переждать опасность. Мёртвый торговец, знаешь ли, плохой торговец! Вот что я тебе скажу, героиня: если ты будешь охранять нас по дороге мимо деревни Колкар, мы тебе за это хорошо заплатим. Расстояние-то небольшое, да и делать почти ничего не придётся – только проследить за тем, чтобы караван был цел. А награду ты получишь, не сомневайся: Смид Заржавень тебе сполна заплатит, мы с ним обделываем кое-какие делишки. Он живёт чуть дальше по дороге." },
    ["5821c"] = { male = "Ты знаешь, не больно-то мне улыбается платить такому как ты за защиту каравана Гизлтона. Эх, герой, если бы не мои годы, если бы мои руки могли держать ружьё, а в зубах – граната, то я бы показал кентаврам кто их батя...", female = "Ты знаешь, не больно-то мне улыбается платить такой как ты за защиту каравана Гизлтона. Эх, героиня, если бы не мои годы, если бы мои руки могли держать ружьё, а в зубах – граната, то я бы показал кентаврам кто их батя..." },
    ["5841a"] = { common = "Добро пожаловать в World of Warcraft! В знак особой благодарности за приобретение коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Йори Шлемолому в Холодной долине. Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе. Ещё раз благодарим вас и желаем приятного пребывания в World of Warcraft!" },
    ["5841c"] = { common = "Ну, теперь приветствую тебя в мире Азерота. Иди вперёд, к славе, наградам и почестям!" },
    ["5842a"] = { common = "Добро пожаловать в World of Warcraft! В качестве особой благодарности за покупку коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Орентилу Шёпоту Ветра в Тенистой долине. Вас ждёт подарок – маленький спутник, который будет сопровождать вас на пути к приключениям и славе. Ещё раз благодарим вас и желаем приятного времяпрепровождения в World of Warcraft!" },
    ["5842c"] = { common = "Ну, теперь приветствую тебя в мире Азерота. Иди вперёд, к славе, наградам и почестям!" },
    ["5843a"] = { common = "Добро пожаловать в World of Warcraft! В знак особой благодарности за приобретение коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Магге в долине Испытаний. Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе. Ещё раз благодарим вас и желаем приятного пребывания в World of Warcraft!" },
    ["5843c"] = { common = "Таких героев, как вы, мало! Приветствуем вас в мире Азерота и вручаем вам этот уникальный дар!" },
    ["5844a"] = { common = ".Добро пожаловать в World of Warcraft! В знак особой благодарности за приобретение коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Ворну Небесному Провидцу в лагере Нараче. Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе. Ещё раз благодарим вас и желаем приятного пребывания в World of Warcraft" },
    ["5844c"] = { common = "Ну, теперь приветствую тебя в мире Азерота. Иди вперёд, к славе, наградам и почестям!" },
    ["5845a"] = { common = "Со смертью Утера орден Серебряной Длани утратил боевой дух. Мой мальчик держался до последнего. Но, отступая в разорённую деревушку Северного дола, он принял окончательное решение. Выжил ли кто из ордена, подумал он, да и какая разница? С этой мыслью Таэлан бросил знамя Серебряной Длани и отрёкся от всего, что прежде было ему дорого. Его честь осталась на обагрённой кровью земле Северного дола. Отправляйся в Северный дол и принеси мне этот символ утраченной чести." },
    ["5845c"] = { common = "Он также величественен, несмотря на разорванный вид, как и в тот день, когда я впервые взглянул на него и дал клятву служения Ордену. Его искупление настанет, возможно, и моё вместе с ним…" },
    ["5846a"] = { common = "Когда Таэлан был маленьким, мы нередко ездили в Каэр Дарроу. В последний раз художница по имени Ренфри изобразила всю нашу семью на берегу. Это лучшее моё воспоминание о Таэлане и Карандре. Именно тогда, стоя рядом с женой и держа на руках сына, я чувствовал глубокую связь с собственной семьёй, которую мне не дано было почувствовать вновь. Если эта картина всё ещё существует, найди её. Отправляйся на разорённый остров Каэр Дарроу и выясни, уцелел ли художник или картина." },
    ["5846c"] = { common = "Как я могла забыть? Здесь многие духи обречены, переживать свои самые радостные мгновения жизни, прежде чем встретили свой конец. Я тоже обречена, но не так как остальные, я помню абсолютно всё… Возможно вещь, о которой ты меня спрашиваешь, причина моего блуждания на этом острове. Возможно то, что я тебе расскажу, освободит меня от моего проклятия." },
    ["5847a"] = { common = "Добро пожаловать в World of Warcraft! В качестве особой благодарности за покупку коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Клэр Вилловер в Могильник. Вас ждёт подарок – маленький спутник, который будет сопровождать вас на пути к приключениям и славе. Ещё раз благодарим вас и желаем приятного времяпрепровождения в World of Warcraft!" },
    ["5847c"] = { common = "Вы действительно незаурядная личность. Мы приветствуем вас в мире Азерота и предлагаем вам один из этих уникальных подарков!" },
    ["5848a"] = { common = "На стене моей мастерской… В казармах ордена… долгие годы висела картина. После суда над Тирионом я знала, что не смогу держать её на виду. Я спрятала её так, чтобы никто не нашёл. Отправляйся в Стратхольм и проберись в то, что ныне зовётся Бастионом Алого ордена. Найди там картину с двумя лунами. Сними лишнюю краску и увидишь мой шедевр — \"Символ семейной любви\". Да направляет Свет твою руку." },
    ["5861a"] = { common = "Ты сделал всё, о чём я тебя просил. Остался один, последний шаг на пути к спасению. Отнеси все собранные тобой предметы Таэлану. К сожалению, Таэлан и его рыцари Алого ордена нападут на тебя, едва завидев. Есть только один способ доставить моё сообщение — приняв обличье врага. На юге отсюда находится гробница Утера. Там живёт моя старая добрая подруга, Миранда. Найди её, покажи все собранные тобой предметы, и она тебе поможет." },
    ["5861c"] = { common = "Я была самой доверенной советницей Тириона, когда он носил титул лорда Марденхольдского. Я открыто отреклась от вердикта ордена Серебряной Длани и была изгнана за неповиновение. На долю Тириона выпало много боли и разочарований. Готов ли ты исправить несправедливости, обрушившиеся на Фордрингов?" },
    ["5862a"] = { common = "Я, как говорится, иллюзионистка. Хотя я могу создать иллюзию, благодаря которой ты проберёшься в Дольный Очаг, помни — сила моя не безгранична. Если ты забредёшь слишком далеко, иллюзия рассеется. Заклинание требует от меня значительного количества сил и сосредоточения, и я не слишком долго смогу поддерживать его. Когда будешь готов — обращайся." },
    ["5862c"] = { common = "Что это, солдат? Этого… Этого не может быть. Но всё, что ты мне показал…" },
    ["5863a"] = { common = "Совсем недавно в Танарисе появились огры-кочевники. Они захватили большой участок пустыни к югу отсюда и построили целую крепость. Племена поменьше бродят по пустыне, захватывая руины тролльских городов. Поселение Песчаного Молота должно пасть! Не позволим же ограм превратиться в страшную силу. Их главаря зовут Гор'марок Опустошитель. Мне кажется, что если его устранить, это станет началом конца огров." },
    ["5863c"] = { male = "Я так рада, что ты выполнил мою просьбу! Спасибо за помощь!", female = "Я так рада, что ты выполнила мою просьбу! Спасибо за помощь!" },
    ["5881a"] = { common = "Орда не даёт нам растерять силы, и это правильно! С самой Великой Войны мы здесь, в Калимдоре, живём неплохо. Я прошу тебя оказать мне услугу: один парень по имени Гриш Выносливый Гонец охраняет Великий подъёмник в западных пустошах. Передай ему это письмо: там говорится, что один из солдат запаса скоро придёт ему на смену, чтобы он мог навестить свою семью. Гриш недавно просил об этом, и он будет рад услышать эти новости." },
    ["5881c"] = { common = "Это хорошие новости; я слишком долго сижу здесь, охраняя этот кусок дерева. Теперь я смогу побыть со своими родными... Ура!" },
    ["5882c"] = { common = "Вот твой кенарийский бальзам исцеления растений. Найди в Осквернённом лесу повреждённые порчей растения, путник! Когда найдёшь, используй на них, этот бальзам." },
    ["5883c"] = { common = "Вот твой кенарийский бальзам исцеления растений. Если найдёшь ещё купорос, приноси мне! Я сделаю для тебя ещё больше бальзама." },
    ["5884c"] = { common = "Отличная работа, путник. Вот, возьми немного Кенарийского бальзама и восстанови немного осквернённых растений в Осквернённом лесу, странник!" },
    ["5885c"] = { common = "Это именно то, что мне нужно. Вот, возьми немного Кенарийского бальзама и используй его на осквернённых растениях. Если мы хотим восстановить Осквернённый лес, то нам нужно работать, путник!" },
    ["5886c"] = { common = "Вот, кенарийский бальзам исцеления растений. Для его создания мне нужна только одна простая субстанция Пустоты, путник. Если тебе потребуется ещё бальзам, ты знаешь, где меня искать." },
    ["5887c"] = { common = "Вот твой кенарийский бальзам исцеления растений. Найди в Осквернённом лесу повреждённые порчей растения, путник! Когда найдёшь, используй на них, этот бальзам." },
    ["5888c"] = { common = "Вот твой кенарийский бальзам исцеления растений. Если найдёшь ещё купорос, приноси мне! Я сделаю для тебя ещё больше бальзама." },
    ["5889c"] = { common = "Отличная работа, путник. Вот, возьми немного Кенарийского бальзама и восстанови немного осквернённых растений в Осквернённом лесу, странник!" },
    ["5890c"] = { common = "Это именно то, что мне нужно. Вот, возьми немного Кенарийского бальзама и используй его на осквернённых растениях. Если мы хотим восстановить Осквернённый лес, то нам нужно работать, путник!" },
    ["5891c"] = { common = "Вот, кенарийский бальзам исцеления растений. Для его создания мне нужна только одна простая субстанция Пустоты, путник. Если тебе потребуется ещё бальзам, ты знаешь, где меня искать." },
    ["5901a"] = { common = "Ну всё, теперь у меня есть партизанский план борьбы с Алым орденом! Для начала они расплатятся за свои деяния лесопилкой. Вот они у меня попрыгают! Посмотрим, будут ли они также лихо перестраивать всё в городе под свои нужды, когда я перекрою им поступления стройматериалов. Поможешь мне, путник? Возьми эту банку и отправляйся в Проклятый лес, что в Восточных Чумных землях. Найди термитник и набери полную банку насекомых — уж мы натравим их на Алый орден!" },
    ["5901c"] = { common = "Прекрасно сделано, путник. Спасибо. Если ты готов, то перейдём к следующему шагу." },
    ["5902a"] = { common = "Теперь у нас просто прорва термитов. Я надёжно запрятала их вот в этот окованный железом бочонок. Отнеси его на лесопилку Северного Кряжа, это к югу от Дольного Очага — сразу найдёшь, если свернёшь на запад с дороги, ведущей отсюда в город. Как будешь на лесопилке, поставь бочонок на какое-нибудь возвышение — например, на какой-нибудь ящик. Главное открыть, а уж дальше термиты сами разберутся. А потом возвращайся ко мне — я придумаю, чем тебя порадовать." },
    ["5902c"] = { common = "Термиты в бочонке были очень несчастны. Что ж, снаружи они смогут выместить свою злобу на всём, до чего только дотянутся…" },
    ["5903a"] = { common = "Я долгое время пытался бороться с Алым орденом в открытую, но без толку. Теперь я подумываю прибегнуть к некоторым партизанским методам — если не можешь одержать победу, хотя бы отрави врагу существование! Если хочешь мне помочь, слушай мой план: я собираюсь подбросить им на лесопилку самых зловредных термитов из всех существующих. Эти твари водятся в Проклятом лесу недалеко от Стратхольма — их колония пережила чуму и переродилась в новый, ещё более живучий вид. Найди термитник и набери полную банку насекомых — уж мы натравим их на Алый орден!" },
    ["5903c"] = { common = "Замечательно, путник. Благодарю тебя. Их так много… честное слово, мне даже жаль бедняг из Алого Марша! Впрочем, лесопилка-то всё равно не их, они её нагло присвоили, так ведь?" },
    ["5904a"] = { common = "Теперь у нас просто прорва термитов. Я надёжно запрятал их вот в этот окованный железом бочонок. Отнеси его на лесопилку Северного Кряжа, это к югу от Дольного Очага — сразу найдёшь, если свернёшь на запад с дороги, ведущей отсюда в город. Как будешь на лесопилке, поставь бочонок на какое-нибудь возвышение — например, на какой-нибудь ящик. Главное открыть, а уж дальше термиты сами разберутся. Едва ли Алый Марш сможет впредь использовать лесопилку!" },
    ["5904c"] = { common = "Как только бочонок оказывается открыт, водопад термитов обрушивается из-под крышки." },
    ["5921a"] = { male = "На священной земле Лунной поляны рады всем друидам, невзирая на последние разногласия в Круге Кенария между верховным друидом Оленьим Шлемом и хранителем Ремулом – стражем Лунной поляны. Теперь, когда ты встал на путь друида-медведя, я научу тебя заклинанию, которое позволит тебе переноситься в Лунную поляну. Пользуйся им, когда тебе нужно знание или уединение Лунной поляны. Вот первый урок: отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд в Ночной гавани о том пути, по которому ты ныне следуешь. Удачи тебе, юный друид.", female = "На священной земле Лунной поляны рады всем друидам, невзирая на последние разногласия в Круге Кенария между верховным друидом Оленьим Шлемом и хранителем Ремулом – стражем Лунной поляны. Теперь, когда ты встала на путь друида-медведя, я научу тебя заклинанию, которое позволит тебе переноситься в Лунную поляну. Пользуйся им, когда тебе нужно знание или уединение Лунной поляны. Вот первый урок: отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд в Ночной гавани о том пути, по которому ты ныне следуешь. Удачи тебе, юная дева-друид." },
    ["5921c"] = { common = "\"Да будет так, отец Кенарий. Да будет так.\" Дендрит делает быстрый незаметный жест в воздухе у себя над головой. Его окутывает тонкая аура силы. \"Первое обличье, которое тебе следует освоить, - это обличье медведя. Я направлю тебя на путь понимания этого аспекта бытия друида, но уж усвоить знания и усовершенствоваться на этом пути - это твоя забота! И так отныне будет всегда.\"" },
    ["5922a"] = { common = "На священной земле Лунной поляны рады всем друидам – и тауренам, и эльфам. Хранитель Ремул – страж Лунной поляны – присматривает за всеми здешними погружёнными в спячку друидами. Теперь, когда ты знаешь путь друида-медведя, я научу тебя заклинанию, которое позволит тебе переноситься в Лунную поляну. Пользуйся им всегда, когда тебе нужно знание или уединение Лунной поляны. Вот первый урок – отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд в Ночной гавани о том пути, которым ты ныне следуешь. Удачи тебе, мой юный друид." },
    ["5922c"] = { common = "Да будет так, отец Кенарий. Да будет так. Дендрит делает быстрый незаметный жест в воздухе у себя над головой. Его окутывает тонкая аура силы. Первое обличье, которое тебе следует освоить, – это обличье медведя. Я направлю тебя на путь понимания этого аспекта бытия друида, но уж усвоить знания и усовершенствоваться на этом пути – это твоя забота! И так отныне будет всегда." },
    ["5923a"] = { common = "Не уделишь мне минутку внимания?.. Дошло до меня, что Матренгил Медвежья Лапа желает побеседовать с тобой. Сдаётся, твоё друидическое обучение выходит на следующую ступень, и он лично берётся тебя обучать. Матренгил непосредственный помощник самого верховного друида, он один из самых мудрых и благородных друидов Тельдрассила. Он живёт в анклаве Кенария в Дарнассе, на втором уровне дерева Фэндрала Оленьего Шлема." },
    ["5923c"] = { male = "Я рад, что ты нашёл сюда дорогу, юный друид. Пришло тебе время вступить в большой мир. В сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты должен обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа. Готовься!", female = "Я рад, что ты нашла сюда дорогу, юная дева-друид. Пришло тебе время вступить в большой мир. В сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты должна обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа. Готовься!" },
    ["5924a"] = { common = "Не уделишь мне минутку внимания?.. До моего сведения дошло, что Матренгил Медвежья Лапа желает пообщаться с вами. Похоже, ваше обучение искусству друида переходит на новую ступень, и он лично будет учить вас. Матренгил – правая рука самого верховного друида и один из самых мудрых и благородных друидов, каких только можно встретить в Тельдрассиле. Он обитает в анклаве Кенария в Дарнассе, на втором ярусе дерева Фэндрала Оленьего Шлема." },
    ["5924c"] = { male = "Я рад, что ты добрался сюда, мой юный друид. Пришло время тебе сделать большой шаг в огромный мир. Каждый из детей Кенария слышит внутри себя призыв служить природе. Животные и растения – наши друзья, а также и наша забота. Таков наш выбор – посвятить жизни сохранению равновесия во имя блага всего живого. Твой первый шаг в этот мир будет заключаться в изучении пути медведя, в изучении силы тела и силы сердца. Приготовься!", female = "Я рад, что ты добралась сюда, моя юная дева-друид. Пришло время тебе сделать большой шаг в огромный мир. Каждый из детей Кенария слышит внутри себя призыв служить природе. Животные и растения – наши друзья, а также и наша забота. Таков наш выбор – посвятить жизни сохранению равновесия во имя блага всего живого. Твой первый шаг в этот мир будет заключаться в изучении пути медведя, в изучении силы тела и силы сердца. Приготовься!" },
    ["5925a"] = { common = "Не уделишь мне минутку внимания?.. Мне сообщили, что Матренгил Медвежья Лапа желает побеседовать с тобой. Сдаётся, твоё друидическое обучение выходит на следующую ступень, и он лично берётся тебя обучать. Матренгил – непосредственный помощник самого верховного друида, он один из самых мудрых и благородных друидов Тельдрассила. Он живёт в анклаве Кенария в Дарнассе, на втором уровне дерева Фэндрала Оленьего Шлема." },
    ["5925c"] = { male = "Я рад, что ты нашёл сюда дорогу, юный друид. Пришло тебе время вступить в большой мир. В сердце каждого из детей Кенария звучит зов природы. Животные и растения - наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты должен обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа. Готовься!", female = "Я рад, что ты нашла сюда дорогу, юная дева-друид. Пришло тебе время вступить в большой мир. В сердце каждого из детей Кенария звучит зов природы. Животные и растения - наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты должна обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа. Готовься!" },
    ["5926a"] = { male = "Извини, друг... Дошло до меня, что Тюрак Рунический Тотэм желает побеседовать с тобой. Сдаётся, твоё друидическое обучение выходит на следующую ступень, и он лично берётся тебя обучать. Тюрак – один из помощников самого верховного друида, он друид мудрый и терпеливый. Он сумеет хорошо обучить тебя. Он живёт в Громовом Утёсе, в главном шатре Круга Кенария на Вершине Старейшин.", female = "Извини, девушка... Дошло до меня, что Тюрак Рунический Тотэм желает побеседовать с тобой. Сдаётся, твоё друидическое обучение выходит на следующую ступень, и он лично берётся тебя обучать. Тюрак – один из помощников самого верховного друида, он друид мудрый и терпеливый. Он сумеет хорошо обучить тебя. Он живёт в Громовом Утёсе, в главном шатре Круга Кенария на Вершине Старейшин." },
    ["5926c"] = { male = "Я рад, что ты нашёл сюда дорогу, мой юный друид. Пришло тебе время вступить в большой мир. В сердце каждого из детей Кенария звучит зов служения природе. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Твой первый шаг в этот мир станет шагом медведя – ты познаешь, что такое сила тела и духа. Готовься!", female = "Я рад, что ты нашла сюда дорогу, моя юная дева-друид. Пришло тебе время вступить в большой мир. В сердце каждого из детей Кенария звучит зов служения природе. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Твой первый шаг в этот мир станет шагом медведя – ты познаешь, что такое сила тела и духа. Готовься!" },
    ["5927a"] = { male = "Извини, друг… Мне стало известно, что Тюрак Рунический Тотэм желает поговорить с тобой. Похоже, что тебе предстоит продолжать обучение на друида. Тюрак собирается обучать тебя лично! А ведь он – один из помощников верховного друида. Он известен как мудрый и терпеливый наставник. Ты у него многому научишься. Ты найдёшь его в Громовом Утёсе, в главном шатре Круга Кенария на Вершине Старейшин.", female = "Извини, подруга… Мне стало известно, что Тюрак Рунический Тотэм желает поговорить с тобой. Похоже, что тебе предстоит продолжать обучение на друида. Тюрак собирается обучать тебя лично! А ведь он – один из помощников верховного друида. Он известен как мудрый и терпеливый наставник. Ты у него многому научишься. Ты найдёшь его в Громовом Утёсе, в главном шатре Круга Кенария на Вершине Старейшин." },
    ["5927c"] = { male = "Я рад, что ты нашёл сюда дорогу, юный друид. Пришло тебе время вступить в большой мир. В сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты должен обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа. Готовься!", female = "Я рад, что ты нашла сюда дорогу, юная дева-друид. Пришло тебе время вступить в большой мир. В сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты должна обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа. Готовься!" },
    ["5928a"] = { common = "Прости меня, друг мой… Мне стало известно, что Тюрак Рунический Тотэм желает поговорить с тобой. Похоже, что тебе предстоит продолжать обучение на друида. Тюрак собирается обучать тебя лично! А ведь он – один из помощников верховного друида. Он известен как мудрый и терпеливый наставник. Ты у него многому научишься. Ты найдёшь его в Громовом Утёсе, в главном шатре Круга Кенария на Вершине Старейшин." },
    ["5928c"] = { male = "Я рад, что тебе удалось добраться сюда, мой юный друид. Пришла тебе пора сделать очередной большой шаг на своём славном пути! В каждом из детей Кенария живёт стремление служить природе. Животные и растения – не только наши подопечные, но и наши друзья. Мы посвящаем свою жизнь сохранению равновесия не только ради себя, но и ради них. И первым твоим шагом в этот мир природы будет изучение медведя. Благодаря ему ты обретёшь силу тела и духа. Готовься же!", female = "Я рад, что тебе удалось добраться сюда, моя юная дева-друид. Пришла тебе пора сделать очередной большой шаг на своём славном пути! В каждом из детей Кенария живёт стремление служить природе. Животные и растения – не только наши подопечные, но и наши друзья. Мы посвящаем свою жизнь сохранению равновесия не только ради себя, но и ради них. И первым твоим шагом в этот мир природы будет изучение медведя. Благодаря ему ты обретёшь силу тела и духа. Готовься же!" },
    ["5929a"] = { male = "В северо-западной части Лунной поляны обитает мудрое и благородное существо, которые мы называем духом Великого Медведя. Для всех друидов он является наставником и учителем, который даёт начала понимания истинной природы медведя. Всем друидам в определённый момент требуется мудрость этого существа, и ты не исключение. Отправляйся же прямо сейчас к духу Великого Медведя и познай всё, чему он захочет тебя научить. Когда он будет доволен тобой, возвращайся ко мне в Ночную Гавань. Тогда и посмотрим, действительно ли ты усвоил его уроки.", female = "В северо-западной части Лунной поляны обитает мудрое и благородное существо, которые мы называем духом Великого Медведя. Для всех друидов он является наставником и учителем, который даёт начала понимания истинной природы медведя. Всем друидам в определённый момент требуется мудрость этого существа, и ты не исключение. Отправляйся же прямо сейчас к духу Великого Медведя и познай всё, чему он захочет тебя научить. Когда он будет доволен тобой, возвращайся ко мне в Ночную Гавань. Тогда и посмотрим, действительно ли ты усвоила его уроки." },
    ["5929c"] = { common = "Дендрит делает ещё один неприметный жест над головой при вашем приближении. Его снова окутывает аура силы, и он еле заметно улыбается. \"Я чую мудрость в тебе, дитя, которой не было во время нашей первой встречи. Во взгляде твоём сила и осознанное стремление, хотя ещё и не столь оформленное. Ныне ты научишься сосредотачивать свою силу и привлекать к твоим трудам сущность медведя.\"" },
    ["5930a"] = { male = "В северо-западной части Лунной поляны обитает мудрое и благородное существо, которые мы называем духом Великого Медведя. Для всех друидов он является наставником и учителем, который даёт начала понимания истинной природы медведя. Всем друидам в определённый момент требуется мудрость этого существа, и ты не исключение. Отправляйся же прямо сейчас к духу Великого Медведя и познай всё, чему он захочет тебя научить. Когда он будет доволен тобой, возвращайся ко мне в Ночную Гавань. Тогда и посмотрим, действительно ли ты усвоил его уроки.", female = "В северо-западной части Лунной поляны обитает мудрое и благородное существо, которые мы называем духом Великого Медведя. Для всех друидов он является наставником и учителем, который даёт начала понимания истинной природы медведя. Всем друидам в определённый момент требуется мудрость этого существа, и ты не исключение. Отправляйся же прямо сейчас к духу Великого Медведя и познай всё, чему он захочет тебя научить. Когда он будет доволен тобой, возвращайся ко мне в Ночную Гавань. Тогда и посмотрим, действительно ли ты усвоила его уроки." },
    ["5930c"] = { common = "Дендрит делает ещё один неприметный жест над головой при вашем приближении. Его снова окутывает аура силы, и он еле заметно улыбается. Я чую мудрость в тебе, дитя, которой не было во время нашей первой встречи. Во взгляде твоём сила и осознанное стремление, хотя ещё и не столь оформленное. Ныне ты научишься сосредотачивать свою силу и привлекать к твоим трудам сущность медведя." },
    ["5931a"] = { common = "Пришла пора нашим дорогам разойтись, дитя моё, ибо для продолжения обучения тебе надо вернуться к тому, кто прислал тебя ко мне. Матренгил Медвежья Лапа живёт в истинном равновесии с природой, хотя и обитает опасно близко к тому месту, где это равновесие пошатнулось. Слушай его наставления, и скоро ты окончательно усвоишь свои первые уроки, определяющие твою роль защитника равновесия. Ступай же, дитя. Мы ещё встретимся." },
    ["5931c"] = { common = "С возвращением. Я чувствую, что твоя первая встреча с духом Великого Медведя сказалась на тебе так же, как и на прочих друидах, когда они впервые ступают на путь медведя... немного сбивает с толку, но впечатляет. То же было и со мной. Дух Великого Медведя был частью Азерота с самого его возникновения. Мы полагаемся на его мудрость и могущество в достижении наших целей. Теперь пришла пора тебе пройти первое своё испытание на этом пути. Слушай же..." },
    ["5932a"] = { common = "Пришла пора нашим дорогам разойтись, дитя моё, ибо для продолжения обучения тебе надо вернуться к тому, кто прислал тебя ко мне. Хотя таурены недавно вступили на путь Кенария, Тюрак Рунический Тотэм живёт в равновесии с природой. Слушай его наставления, и скоро ты окончательно усвоишь свои первые уроки, определяющие твою роль защитника равновесия. Ступай же, дитя. Мы ещё встретимся." },
    ["5932c"] = { common = "С возвращением. Я чувствую, что твоя первая встреча с духом Великого Медведя сказалась на тебе так же, как и на прочих друидах, когда они впервые ступают на путь медведя... немного сбивает с толку, но впечатляет. То же было и со мной. Дух Великого Медведя был частью Азерота с самого его возникновения. Мы, таурены, внимательно прислушиваемся к таким духам, и его цели ведут нас к процветанию. Теперь пришла пора тебе пройти первое своё испытание на этом пути. Слушай же..." },
    ["5941a"] = { common = "Ты собрал многие реликвии, сохранившиеся со времён битвы при Дарроушире. Они взывают ко мне… умоляют изменить судьбу жителей Дарроушира. Да, звучит абсурдно, но Хроми, странный гном, живущий в Андорале, убеждает меня, что это возможно. Она говорит, ты можешь спасти Дарроушир! Ты должен отнести эти реликвии ей, она ждёт тебя в разрушенной таверне в Андорале." },
    ["5941c"] = { common = "Ага, вот они какие. Вместе мы создадим мощнейшее заклятие, которое ни много, ни мало, поднимет души всех кто жил в Дарроушире! Ну и с помощью удачи мы даже сможем спасти Джозефа Редпата!" },
    ["5942c"] = { common = "Ключ хорошо подходит к замку и сундук открывается." },
    ["5943a"] = { male = "Вид-то у тебя надёжный, герой. Подзаработать хочешь? Мы с Корком думали, что на этом караване срубим кучу денег – но оказалось, что новое предприятие сулит гораздо больше неприятностей и опасностей, чем мы полагали. Там, впереди, находится Поле Маннорок... Обычно демоны не обращают на нас внимания, но на этот раз что-то изрядно напугало кодо. Я хорошо заплачу тебе за охрану каравана. Если нам удастся миновать Поле Маннорок без проблем, ты сможешь получить награду у Смида: это наш деловой партнёр в Лагере Заржавня.", female = "Вид-то у тебя надёжный, героиня. Подзаработать хочешь? Мы с Корком думали, что на этом караване срубим кучу денег – но оказалось, что новое предприятие сулит гораздо больше неприятностей и опасностей, чем мы полагали. Там, впереди, находится Поле Маннорок... Обычно демоны не обращают на нас внимания, но на этот раз что-то изрядно напугало кодо. Я хорошо заплачу тебе за охрану каравана. Если нам удастся миновать Поле Маннорок без проблем, ты сможешь получить награду у Смида: это наш деловой партнёр в Лагере Заржавня." },
    ["5943c"] = { male = "Ты это... не ожидай, что мы тебе много заплатим за проводку каравана Гизлтона... Корком и Риггереле – кое как зарабатывают один золотой в неделю, так что сам понимаешь...", female = "Ты это... не ожидай, что мы тебе много заплатим за проводку каравана Гизлтона... Корком и Риггереле – кое как зарабатывают один золотой в неделю, так что сама понимаешь..." },
    ["5944a"] = { common = "Как же долго я был марионеткой верховного рыцаря. И что было проку сражаться с Алым орденом? Прошли десятки лет с мнимой смерти отца, но я жил лишь воспоминаниями о нём. Мне снилось, что мы с отцом снова вместе. Он стоит рядом, с гордостью глядя, как меня принимают в орден. Мы бьёмся с Плетью плечо к плечу, принося славу Альянсу и Лордерону. Не желаю больше жить во сне. Отведи меня к отцу." },
    ["5944c"] = { common = "Убийство моего сына не пройдёт этим чудовищам даром. Пусть нас утешит мысль о возрождении Ордена. Я встану во главе обновлённого Ордена Серебряной Длани. В знак своей признательности я могу отдать тебе лишь эти вещи, символы моего прошлого. Прими их, они служили мне верой и правдой долгие годы. Да встретимся мы в лучшие дни и вспомним давнее прошлое… трудные битвы… пробуждение от сна." },
    ["5961a"] = { common = "Приятно видеть, что в наши ряды вступают закалённые бойцы. С каждым днём нас становится всё больше. Ты готов испытать собственную решимость, герой? Первый среди моих защитников — Натанос по прозвищу Гнилостень. Немногие могут превзойти его в преданности и доблести. Отыщи его в Восточных Чумных землях. Он живёт в Поместье Маррисов и порой бродит по окружающим его пустошам, истребляя всякую мразь из воинств Плети и Альянса." },
    ["5961c"] = { common = "Тёмная Госпожа считает тебя достойным встретиться с её защитником. Ты ведь прислан кормить моих псов, да? Иначе зачем ты меня тревожишь?" },
    ["6001a"] = { male = "Прямо к востоку от Аубердина находятся пещеры лунных совухов. В той, что ближе всего к Аубердину, находится камень лунного совуха. Лунокоготь, страж камня, появится перед тобой только тогда, когда ты воспользуешься лунной пылью Кенария. Лунокоготь таит в себе силу, которой ты, как один из друидов-медведей, должен овладеть. Ты заслужил право пользоваться этой лунной пылью Кенария... теперь покажи мне, что также заслужил право обладать силами тела и духа, необходимыми друиду!", female = "Прямо к востоку от Аубердина находятся пещеры лунных совухов. В той, что ближе всего к Аубердину, находится камень лунного совуха. Лунокоготь, страж камня, появится перед тобой только тогда, когда ты воспользуешься лунной пылью Кенария. Лунокоготь таит в себе силу, которой ты, как одна из друидов-медведей, должен овладеть. Ты заслужила право пользоваться этой лунной пылью Кенария... теперь покажи мне, что также заслужила право обладать силами тела и духа, необходимыми друиду!" },
    ["6001c"] = { male = "Это твой первый большой шаг на пути к великим свершениям. Я чую учение Духа Великого Медведя в тебе и вижу, что ты перенял мощь Лунокогтя. Более ничего не препятствует тебе... позволь же ныне поведать тебе, что значит быть друидом-медведем!", female = "Это твой первый большой шаг на пути к великим свершениям. Я чую учение Духа Великого Медведя в тебе и вижу, что ты переняла мощь Лунокогтя. Более ничего не препятствует тебе... позволь же ныне поведать тебе, что значит быть друидом-медведем!" },
    ["6002a"] = { male = "Прямо к западу от Таурахо в Степях – там, где они переходят в Мулгор – находится камень Лунного совуха. Лунные совухи – звери особые, в здешних краях они не живут. Лунокоготь, страж камня, появится перед тобой только когда ты воспользуешься лунной пылью Кенария. Лунокоготь таит в себе силу, который ты должен овладеть, как один из друидов-медведей. Ты заслужил право пользоваться этой лунной пылью Кенария... теперь покажи мне, что также заслужил право обладать силой тела и духа, необходимыми друиду!", female = "Прямо к западу от Таурахо в Степях – там, где они переходят в Мулгор – находится камень Лунного совуха. Лунные совухи – звери особые, в здешних краях они не живут. Лунокоготь, страж камня, появится перед тобой только когда ты воспользуешься лунной пылью Кенария. Лунокоготь таит в себе силу, который ты должна овладеть, как одна из друидов-медведей. Ты заслужила право пользоваться этой лунной пылью Кенария... теперь покажи мне, что также заслужила право обладать силой тела и духа, необходимыми друиду!" },
    ["6002c"] = { male = "Это твой первый большой шаг на пути к великим свершениям. Я чую учение Духа Великого Медведя в тебе, и вижу, что ты перенял мощь Лунокогтя. Более ничего не препятствует тебе... позволь же ныне поведать тебе, что значит быть друидом-медведем!", female = "Это твой первый большой шаг на пути к великим свершениям. Я чую учение Духа Великого Медведя в тебе, и вижу, что ты переняла мощь Лунокогтя. Более ничего не препятствует тебе... позволь же ныне поведать тебе, что значит быть друидом-медведем!" },
    ["6004a"] = { common = "У меня была разведывательная миссия — немного сократить число противников и оценить укрепления Дольного Очага. Некоторые сторонники Альянса считают, что этот город имеет не только историческое значение. Не моё дело решать, что важнее, но выполнять задание я не в силах, пока не отдохну. Если хочешь, я неплохо заплачу тебе за помощь. Начни на юге, возле лагеря Алого Марша, у небольшого бастиона. Если ты окажешься достаточно силён, я попрошу тебя помочь мне выполнить основную часть задания." },
    ["6004c"] = { common = "Молодец, путник. Как тебе удалось так быстро с ними разобраться? Спасибо. Мне пока не встречался никто, кто одобрил бы Алый орден или его методы. Я верю в Свет, также как и все жители Штормграда, но эти фанатики наглядно доказали, что стремятся лишь убивать всех, кроме своих сторонников… даже ни в чём не повинных людей." },
    ["6021a"] = { common = "Кто бы мог подумать, после всех наших злоключений в Чумных землях нам не хватало только воров! И не просто воров, а троллей! И не просто воров-троллей, а мёртвых воров-троллей! Их главарь — огромный мёртвый тролль по имени Зельдарр Изгой. Они являются по ночам, крадут тела из ямы и тащат их в своё мерзкое логово. Оно зовётся Крипта, это к западу отсюда. Отправляйся туда, путник, и разберись с Зельдарром. Я сыт по горло его проделками!" },
    ["6021c"] = { common = "Поделом ему! Надеюсь, и остальным из его шайки тоже досталось!" },
    ["6022a"] = { common = "Будь готов на умышленное убийство, если хочешь со мной работать. Для начала покорми моих псов. Возьми эту ступку и пестик и отправляйся в Перекрёсток Корина. Там у тебя будет обширный выбор тварей Плети — убей тех, какие больше приглянутся. Из их свежих туш добудь живую гниль, растолки в ступке и дай отстояться, чтобы она сгустилась. Принесёшь сгущённую гниль мне. И слушай меня, недотёпа, живая гниль — продукт скоропортящийся! Поэтому работать придётся быстро." },
    ["6022c"] = { common = "Я разочарован. Я надеялся скормить моим псам тебя. Ну, хоть что-то им поесть достанется." },
    ["6023a"] = { common = "Подлинная суть моей миссии состояла в том, чтобы подорвать мощь внешних отрядов Алого ордена, а потом проникнуть внутрь Дольного Очага и оценить их основные силы. Я пока не в форме, но, может быть, могу снова попросить о помощи? Судя по собранным сведениям, за пределами города костяк сил ордена составляют двое: охотник Радли и кавалерист Дарген. Убей их, и дело стронется с мёртвой точки. Они должны быть неподалёку от прохода, рядом с городом." },
    ["6023c"] = { common = "Спасибо, путник. Я и не рассчитывала на такую помощь. Кажется, самый воздух этих земель лишает меня воли. Я очень устала, и чем дольше здесь нахожусь, тем мне хуже. Не представляю, как я проберусь в Дольный Очаг, чтобы выяснить размер армии Алого ордена. Но это другой разговор. Погоди, возьми это… в уплату. Спасибо ещё раз." },
    ["6024a"] = { common = "Убей меня. Пока не поздно! Меня зовут Хамейя. Мы с собратьями путешествовали через Зул'Машар и, видимо, съели что-то не то. Мы заражены! Я слышу, как лич нашёптывает мне, что я должен отправиться в Зул'Машар и постараться распространить заразу. Я не могу противиться его словам, поэтому написал это послание прежде, чем разум окончательно оставит меня. Я закопал сундук с сокровищами рядом с повозкой, оставленной за этим склепом, но его можно открыть только моим ключом. Ключ у меня. Чтобы добыть сокровище, убей меня. Пока не поздно!" },
    ["6024c"] = { common = "Сундук Хамейи открыт!!" },
    ["6025a"] = { common = "Что? Правда? Ты готов меня выслушать? Но ты и так очень много для меня сделал, путник. Я не могу просить тебя отправиться в Дольный Очаг. Ты серьёзно? Дольный Очаг гораздо опаснее прохода… Я не смогу защитить тебя или даже рассказать, что тебя может ждать там. Если ты в самом деле хочешь мне помочь, то проникни в город, поднимись на гору и осмотри его с высоты. Оцени количество войск и доложи мне. Но будь осторожен…" },
    ["6025c"] = { common = "Молодец, путник! Спасибо! Я вернусь к Иллингу… точнее, в Штормград как только смогу. Возьми эту скромную сумму, должна же я тебя отблагодарить. Твой народ может тобой гордиться, путник. Спасибо и удачи." },
    ["6026a"] = { common = "Серебряный Рассвет поручил старине Дымку кой-какую работёнку. А я что, я токмо рад — денежка-то никогда не лишняя! Однако силы мои уже не те, и я бы, пожалуй, воспользовался твоей помощью, если ты тоже не прочь подзаработать. Я пойду в Проклятый лес и отмечу знаком строения, которые предстоит взорвать, а ты пока добудешь взрывчатки. Договорились? Жди меня на этом самом месте, как соберёшь всё необходимое. Ну, что скажешь?" },
    ["6026c"] = { common = "Могу заплатить тебе половину авансом, а половину, когда работа будет сделана." },
    ["6027a"] = { common = "Послушай меня: я вручаю тебе Самоцвет Змеи. Его нужно поместить на руку Статуи Змеи, что на острове Раназьяр: это небольшой островок к северо-западу отсюда. Когда сделаешь это, явится тот, кто хранит Книгу Древних. В книге можно найти вековые тайны нагов. Принеси мне эту книгу: вместе мы сумеем узнать многое о наших чешуйчатых врагах!" },
    ["6027c"] = { male = "Утраченная Книга Древних! Я прослежу за тем, чтобы она была передана высокому совету. Сегодня ты свершил великое деяние; прими же благодарность за этот подвиг!", female = "Утраченная Книга Древних! Я прослежу за тем, чтобы она была передана высокому совету. Сегодня ты свершила великое деяние; прими же благодарность за этот подвиг!" },
    ["6028a"] = { common = "Я ищу ответственного работника, способного помочь мне решить небольшую, но очень важную проблему. Я здесь как представитель интересов Серебряного Рассвета по управлению Круговзором. Я должен доложить обстановку офицеру Чистосердой в Лагерь Промозглого Ветра, расположенный на южной окраине Западных Чумных земель. Если мне это удастся, это будет прекрасный повод представить тебя моей начальнице и, возможно, устроить тебе персональное задание" },
    ["6028c"] = { common = "Грегор крайне находчив. Он некоторое время имел дело с Картелем Хитрая Шестерёнка, и стал экспертом по \"искусству\" переговоров с гоблинами. Хотя верно, что расположение гоблинов к вам напрямую зависит от толщины вашего кошелька, они также признают и уважают роль дипломатии. Если, так или иначе, она обеспечивает им повторные заказы… Во всяком случае, Серебряный Рассвет выражает вам признательность за проделанную работу. Примите это вместе с нашей благодарностью." },
    ["6029a"] = { common = "Я ищу ответственного работника, способного помочь мне решить небольшую, но очень важную проблему. Я здесь как представитель интересов Серебряного Рассвета в администрации Круговзора. Я должен доложить обстановку офицеру Гарушу в Бастион, расположенный на восточных окраинах Западных Чумных земель, к востоку от Тирисфальских лесов. Если я могу тебя об этом просить… это будет прекрасный повод представить тебя моему начальнику. И, возможно, он найдёт тебе дело!" },
    ["6029c"] = { common = "Грегор крайне находчив. Он некоторое время имел дело с Картелем Хитрой Шестерёнки, и стал экспертом по \"искусству\" переговоров с гоблинами. Хотя верно, что расположение гоблинов к вам напрямую зависит от толщины вашего кошелька, они также признают и уважают роль дипломатии. Если, так или иначе, она обеспечивает им повторные заказы… Во всяком случае, Серебряный Рассвет выражает вам признательность за проделанную работу. Примите это вместе с нашей благодарностью." },
    ["6030a"] = { common = "Отшельник-медиум по имени Умбранс, обитающий в этих краях, обеспечил Серебряный Рассвет настоящим шедевром литературы… Это самое большое собрание слухов и сплетен, которое только было когда-либо издано. Один из наиболее уважаемых лидеров Рассвета, герцог Николас Зверенхофф, является блестящим лингвистом. Ты не мог бы отнести ему эту книгу — не бесплатно, разумеется! Сейчас его можно найти в Часовне Последней Надежды, в восточной части Восточных Чумных земель." },
    ["6030c"] = { common = "Это… Вы принесли мне весьма особенную книгу. Я хотел бы сказать Вам, что \"особенная\" в этом случае означает \"уникальная и весьма познавательная\", но так ли это мы ещё проверим. Ооо? Кто это выдумал? Хорошо, я узнал об этом Умбрансе, о котором говорил Грегор, и это ваша заслуга. Я приложу все усилия, чтобы расшифровать эту книгу. Что касается Вас… Серебряный Рассвет вам бесконечно благодарен. Возможно нам ещё потребуются ваши услуги, пока вы здесь." },
    ["6041a"] = { common = "Пока ты занимался заготовкой припасов, мои люди отметили некоторые сооружения Плети, которые должны быть уничтожены. План действий таков: я дам тебе десять брусков моего особого состава, ты отправишься в Проклятый лес и оставишь их в строениях Плети, помеченных знаком. Бабах! Всё очень просто!" },
    ["6041c"] = { common = "Ты, кажется, немного чернее, чем был. Твой вид просто говорит: “меня подкоптило мощным взрывом”. В любом случае! Вот твоя доля. Я подбросил тебе кое-что, теперь тебе легче будет перенести ожоги." },
    ["6042a"] = { common = "С фермы и шагу нельзя ступить, чтобы не напороться на одну из этих проклятых летучих мышей! Я бы, знаешь ли, предпочёл заниматься истреблением Плети, не отвлекаясь на всякую мелкую шушеру. Моё время слишком дорого, чтобы тратить его на охоту за мышами. А вот твоё — нет. Что ты там бормочешь? Обучение? Вот тебе обучение — пойди поучись ловле мышей! И не смей показываться мне на глаза, пока не перебьёшь несколько десятков этих мерзких тварей." },
    ["6042c"] = { common = "Невероятно, сколького можно добиться, немного разозлившись." },
    ["6061a"] = { common = "Для нас, тауренов, важно следовать традициям предков, сражаясь с могучими зверями. Одолевая их, мы вбираем в себя их дух, делаясь всё ближе Матери-Земле. Приручив же зверя и сделав его своим помощником, мы делаем ещё один шаг навстречу природе. В конце концов ты сможешь выбрать зверя себе по вкусу. Но сначала всему приходится учиться, и этому тоже. Для начала возьми этот хлыст приручения; ступай, приручи равнинного долгонога." },
    ["6061c"] = { male = "Я уже знаю, мать-земля сказала мне, что ты справился со своей задачей.", female = "Я уже знаю, мать-земля сказала мне, что ты справилась со своей задачей." },
    ["6062a"] = { male = "Умение подчинять природу своей воле – великое искусство. Ты охотник, и тебе следует научиться использовать силу и мощь, свойственную любому избранному тобой существу. Обрести власть над животным – дело не простое, тут требуется решимость. Для начала возьми вот этот хлыст приручения и укроти с его помощью лютого пятнистого вепря. Они водятся поблизости от Колючего Холма. Попробуй поучаствовать в битве вместе с вепрем, а потом возвращайся ко мне.", female = "Умение подчинять природу своей воле – великое искусство. Ты охотница, и тебе следует научиться использовать силу и мощь, свойственную любому избранному тобой существу. Обрести власть над животным – дело не простое, тут требуется решимость. Для начала возьми вот этот хлыст приручения и укроти с его помощью лютого пятнистого вепря. Они водятся поблизости от Колючего Холма. Попробуй поучаствовать в битве вместе с вепрем, а потом возвращайся ко мне." },
    ["6062c"] = { common = "Молодец! Думаю, тебе уже можно поручить задачу посложнее..." },
    ["6063a"] = { male = "Охотнику важно помнить о том, какая перед ним стоит ответственность. Природа – не та сила, которую можно подчинить своим прихотям. Её следует почитать как нечто, без чего само твоё существование было бы невозможным. Ты должен доказать, что понимаешь это, прежде чем получишь способность превращать любое животное в своего верного спутника. Первым делом возьми этот хлыст приручения. С его помощью ты сумеешь приручить чащобного тенётника. Приручи его и поупражняйся в своём охотничьем искусстве.", female = "Охотнику важно помнить о том, какая перед ним стоит ответственность. Природа – не та сила, которую можно подчинить своим прихотям. Её следует почитать как нечто, без чего само твоё существование было бы невозможным. Ты должна доказать, что понимаешь это, прежде чем получишь способность превращать любое животное в своего верного спутника. Первым делом возьми этот хлыст приручения. С его помощью ты сумеешь приручить чащобного тенётника. Приручи его и поупражняйся в своём охотничьем искусстве." },
    ["6063c"] = { common = "Отлично! Ты и правда быстро обучаешься." },
    ["6064a"] = { male = "Привет, парень! Стало быть, хочешь узнать, как завести себе питомца? Что же, начнём. Когда доходит до охоты, нет ничего важнее снаряжения, но о моём новом шрапнельном самостреле мы поболтаем в другой раз. А пока займёмся тем, что, так интересует тебя в данный момент – питомцем! Тебе лучше всего попытаться приручить нескольких существ и посмотреть, кто тебе больше по сердцу. Итак, найди большого скального вепря, а затем используй хлыст приручения, чтобы приручить его.", female = "Привет, подруга! Стало быть, хочешь узнать, как завести себе питомца? Что же, начнём. Когда доходит до охоты, нет ничего важнее снаряжения, но о моём новом шрапнельном самостреле мы поболтаем в другой раз. А пока займёмся тем, что, так интересует тебя в данный момент – питомцем! Тебе лучше всего попытаться приручить нескольких существ и посмотреть, кто тебе больше по сердцу. Итак, найди большого скального вепря, а затем используй хлыст приручения, чтобы приручить его." },
    ["6064c"] = { common = "Знаю-знаю, тебе невтерпёж узнать, кого надо будет приручить следующим, да?" },
    ["6065a"] = { male = "Привет тебе, юный охотник. Ты кажешься мне достаточно опытным, чтобы научиться обращаться с животным и обрести верного друга. Тебе надо повидаться с Йо Колкой Гривой в Деревне Кровавого Копыта. Он научит тебя, как обрести собственного питомца и спутника.", female = "Привет тебе, юная охотница. Ты кажешься мне достаточно опытной, чтобы научиться обращаться с животным и обрести верного друга. Тебе надо повидаться с Йо Колкой Гривой в Деревне Кровавого Копыта. Он научит тебя, как обрести собственного питомца и спутника." },
    ["6065c"] = { male = "Да, я полагаю, что ты уже готов...", female = "Да, я полагаю, что ты уже готова..." },
    ["6066a"] = { male = "Привет тебе, юный охотник. Ты кажешься мне достаточно опытным, чтобы научиться обращаться с животным и обрести верного друга. Тебе надо повидаться с Йо Колкой Гривой в Деревне Кровавого Копыта. Он научит тебя, как обрести собственного питомца и спутника.", female = "Привет тебе, юная охотница. Ты кажешься мне достаточно опытной, чтобы научиться обращаться с животным и обрести верного друга. Тебе надо повидаться с Йо Колкой Гривой в Деревне Кровавого Копыта. Он научит тебя, как обрести собственного питомца и спутника." },
    ["6066c"] = { male = "Да, я полагаю, что ты уже готов...", female = "Да, я полагаю, что ты уже готова..." },
    ["6067a"] = { male = "Привет тебе, юный охотник. Ты кажешься мне достаточно опытным, чтобы научиться обращаться с животным и обрести верного друга. Тебе надо повидаться с Йо Колкой Гривой в Деревне Кровавого Копыта. Он научит тебя, как обрести собственного питомца и спутника.", female = "Привет тебе, юная охотница. Ты кажешься мне достаточно опытной, чтобы научиться обращаться с животным и обрести верного друга. Тебе надо повидаться с Йо Колкой Гривой в Деревне Кровавого Копыта. Он научит тебя, как обрести собственного питомца и спутника." },
    ["6067c"] = { male = "Да, я полагаю, что ты уже готов...", female = "Да, я полагаю, что ты уже готова..." },
    ["6068a"] = { male = "Привет тебе, юный охотник! Сдаётся мне, что у тебя уже достаточно опыта, чтобы подчинить себе зверя и сделать его своим спутником. Найди в Колючем Холме Тотара. Он научит тебя, как обзавестись собственным питомцем.", female = "Привет тебе, юная охотница! Сдаётся мне, что у тебя уже достаточно опыта, чтобы подчинить себе зверя и сделать его своим спутником. Найди в Колючем Холме Тотара. Он научит тебя, как обзавестись собственным питомцем." },
    ["6068c"] = { common = "Да, тебе, пожалуй, пора учиться дальше." },
    ["6069a"] = { male = "Привет тебе, юный охотник! Сдаётся мне, что у тебя уже достаточно опыта, чтобы подчинить себе зверя и сделать его своим спутником. Найди в Колючем Холме Тотара. Он научит тебя, как обзавестись собственным питомцем.", female = "Привет тебе, юная охотница! Сдаётся мне, что у тебя уже достаточно опыта, чтобы подчинить себе зверя и сделать его своим спутником. Найди в Колючем Холме Тотара. Он научит тебя, как обзавестись собственным питомцем." },
    ["6069c"] = { male = "Да, пожалуй, ты уже готов к обучению...", female = "Да, пожалуй, ты уже готова к обучению..." },
    ["6070a"] = { male = "Привет тебе, юный охотник! Сдаётся мне, что у тебя уже достаточно опыта, чтобы подчинить себе зверя и сделать его своим спутником. Найди в Колючем Холме Тотара. Он научит тебя, как обзавестись собственным питомцем.", female = "Привет тебе, юная охотница! Сдаётся мне, что у тебя уже достаточно опыта, чтобы подчинить себе зверя и сделать его своим спутником. Найди в Колючем Холме Тотара. Он научит тебя, как обзавестись собственным питомцем." },
    ["6070c"] = { common = "Да, тебе, пожалуй, пора учиться дальше." },
    ["6071a"] = { male = "Привет тебе, юный охотник. Ты кажешься мне достаточно опытным, чтобы научиться обращаться с животным и обрести верного друга. Тебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника.", female = "Привет тебе, юная охотница. Ты кажешься мне достаточно опытной, чтобы научиться обращаться с животным и обрести верного друга. Тебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника." },
    ["6071c"] = { male = "Да, охотник, пришла пора.", female = "Да, охотница, пришла пора." },
    ["6072a"] = { male = "Привет тебе, юный охотник. Ты кажешься мне достаточно опытным, чтобы научиться обращаться с животным и обрести верного друга. Тебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника.", female = "Привет тебе, юная охотница. Ты кажешься мне достаточно опытной, чтобы научиться обращаться с животным и обрести верного друга. Тебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника." },
    ["6072c"] = { male = "Да, пришло время, герой.", female = "Да, пришло время, героиня." },
    ["6073a"] = { male = "Привет тебе, юный охотник. Ты кажешься мне достаточно опытным, чтобы научиться обращаться с животным и обрести верного друга. Тебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника.", female = "Привет тебе, юная охотница. Ты кажешься мне достаточно опытной, чтобы научиться обращаться с животным и обрести верного друга. Тебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника." },
    ["6073c"] = { common = "Да, пора обучить тебя..." },
    ["6074a"] = { male = "Привет тебе, юный охотник. Ты кажешься мне достаточно опытным, чтобы научиться обращаться с животным и обрести верного друга. Тебе надо повидаться с Грифом Диким Сердцем из Караноса. Он научит тебя, как обрести собственного питомца и спутника.", female = "Привет тебе, юная охотница. Ты кажешься мне достаточно опытной, чтобы научиться обращаться с животным и обрести верного друга. Тебе надо повидаться с Грифом Диким Сердцем из Караноса. Он научит тебя, как обрести собственного питомца и спутника." },
    ["6074c"] = { common = "Да, думаю, пора пришла..." },
    ["6075a"] = { male = "Привет тебе, юный охотник. Ты кажешься мне достаточно опытным, чтобы научиться обращаться с животным и обрести верного друга. Тебе надо повидаться с Грифом Диким Сердцем из Караноса. Он научит тебя, как обрести собственного питомца и спутника.", female = "Привет тебе, юная охотница. Ты кажешься мне достаточно опытной, чтобы научиться обращаться с животным и обрести верного друга. Тебе надо повидаться с Грифом Диким Сердцем из Караноса. Он научит тебя, как обрести собственного питомца и спутника." },
    ["6075c"] = { common = "Да, думаю, пора тебя обучить..." },
    ["6076a"] = { male = "Привет тебе, юный охотник. Ты кажешься мне достаточно опытным, чтобы научиться обращаться с животным и обрести верного друга. Тебе надо повидаться с Грифом Диким Сердцем из Караноса. Он научит тебя, как обрести собственного питомца и спутника.", female = "Привет тебе, юная охотница. Ты кажешься мне достаточно опытной, чтобы научиться обращаться с животным и обрести верного друга. Тебе надо повидаться с Грифом Диким Сердцем из Караноса. Он научит тебя, как обрести собственного питомца и спутника." },
    ["6076c"] = { male = "Да, я думаю, что теперь ты готов...", female = "Да, я думаю, что теперь ты готова..." },
    ["6081a"] = { common = "Теперь ты умеешь приручать зверей, но тебе ещё осталось узнать, как их обучать. Ступай в Оргриммар. Там тебе нужно будет поговорить с одним из самых прославленных наших охотников, Ормаком Лютострелом. Он покажет тебе, как обучать своего нового питомца. Ты найдёшь Ормака возле Зала Отважных. Удачи!" },
    ["6081c"] = { male = "А, молодой охотник! Да, я поделюсь с тобой навыками и знаниями, необходимыми для того, чтобы обучать и дрессировать питомца. Ты сможешь не только обучать своего питомца новым способностям, но также научишься кормить его и даже оживлять, если он погибнет в бою. А теперь ступай. Мы поговорим позднее.", female = "А, молодая охотница! Да, я поделюсь с тобой навыками и знаниями, необходимыми для того, чтобы обучать и дрессировать питомца. Ты сможешь не только обучать своего питомца новым способностям, но также научишься кормить его и даже оживлять, если он погибнет в бою. А теперь ступай. Мы поговорим позднее." },
    ["6082a"] = { male = "Последнее животное, которое тебе придётся приручить, – это бронескорп. Тебе придётся частенько с ними сражаться. Но ты, будучи охотником, должен уметь повелевать и такими существами. Когда ты вернёшься, я обучу тебя всему, что потребуется, чтобы приручить животное по твоему выбору. Выбранный тобой зверь будет набираться опыта и становиться сильнее. А ещё я покажу тебе, как призывать его и отпускать на волю, когда в нём не будет надобности.", female = "Последнее животное, которое тебе придётся приручить, – это бронескорп. Тебе придётся частенько с ними сражаться. Но ты, будучи охотницей, должна уметь повелевать и такими существами. Когда ты вернёшься, я обучу тебя всему, что потребуется, чтобы приручить животное по твоему выбору. Выбранный тобой зверь будет набираться опыта и становиться сильнее. А ещё я покажу тебе, как призывать его и отпускать на волю, когда в нём не будет надобности." },
    ["6082c"] = { male = "Теперь, ты знаешь всё, чему я мог тебя обучить. Пора тебе воспользоваться полученными знаниями и выбрать себе собственного питомца. Вот, я даю тебе способность приручать зверя, а также призывать и отсылать его по собственной воле. Можешь гордиться своим новым умением, ты заслужил эти знания!", female = "Теперь, ты знаешь всё, чему я мог тебя обучить. Пора тебе воспользоваться полученными знаниями и выбрать себе собственного питомца. Вот, я даю тебе способность приручать зверя, а также призывать и отсылать его по собственной воле. Можешь гордиться своим новым умением, ты заслужила эти знания!" },
    ["6083a"] = { common = "Разумеется, питомец даёт тебе большое преимущество в бою. Подчиняя себе живое существо, ты добавляешь его силу к своей. Он становится как бы продолжением тебя. Следующее задание потребует от тебя обратиться от земли к морю. Приливный краб, которого тебе нужно будет приручить, обитает в прибрежных водах, близ деревни Сен'джин и островов Эха. Воспользуйся хлыстом приручения, чтобы усмирить зверя, а потом потренируй свои навыки." },
    ["6083c"] = { common = "Ты быстро учишься! Молодец." },
    ["6084a"] = { common = "Эти скальные вепри такие здоровенные – может, тебе хочется кого поизящнее? Ладушки, у меня есть кое-кто на примете. К югу и востоку отсюда ты найдёшь больших белых кошек, называемых снежными леопардами. Они чем-то напоминают элегантную винтовку – такие же красивые и такие же смертоносные. Они гораздо проворнее и быстрее укрощённого тобой вепря. На, держи этот хлыст приручения. Посмотрим, придётся ли тебе по душе снежный леопард." },
    ["6084c"] = { male = "Когда я увижу, что ты достаточно подготовлен, я научу тебя приручать любого понравившегося тебе зверя.", female = "Когда я увижу, что ты достаточно подготовлена, я научу тебя приручать любого понравившегося тебе зверя." },
    ["6085a"] = { common = "Возможно, тебе понравится животное, обладающее чем-то большим, чем просто грубая сила. Медведи-ледолапы – замечательные спутники для охотников-новичков, вроде тебя. Их можно найти к востоку от Караноса. Вот тебе хлыст приручения, попытайся приручить это животное и посмотри, как он тебе придётся! Когда ты вернёшься, я научу тебя, как приручать животных. Твой питомец будет вместе с тобой разделять опасности и получать опыт. Я также научу тебя призывать и отпускать животное по своему желанию." },
    ["6085c"] = { common = "Отлично. Теперь научу тебя приручать зверя, а также призывать и отпускать его по желанию. Найди себе славного верного питомца – и доброй охоты!" },
    ["6086a"] = { male = "Ты умеешь приручать зверей, но ведь надо ещё научиться тренировать своего питомца. Иди в Палаты Войны в Стальгорне и поговори там с одним из наших лучших специалистов в обучении зверей – Белией Громовым Гранитом. Она покажет тебе, как обучать питомца. Так что отправляйся в путь, парень! Белия по характеру дружелюбна, у тебя не будет проблем в нахождении с ней общего языка. Удачи.", female = "Ты умеешь приручать зверей, но ведь надо ещё научиться тренировать своего питомца. Иди в Палаты Войны в Стальгорне и поговори там с одним из наших лучших специалистов в обучении зверей – Белией Громовым Гранитом. Она покажет тебе, как обучать питомца. Так что отправляйся в путь, подруга! Белия по характеру дружелюбна, у тебя не будет проблем в нахождении с ней общего языка. Удачи." },
    ["6086c"] = { common = "Новенький? Вижу, быть тебе великим охотником. Да, я могу поделиться с тобой знаниями, необходимыми для обучения и управления питомцем. Ты сможешь не только обучить своего питомца новым способностям, но и научишься его кормить и даже воскрешать, если он погибнет в бою. Помни, лучший способ подружиться с питомцем – это обращаться с ним уважительно и хорошо за ним ухаживать. Тогда твой питомец будет безгранично предан тебе." },
    ["6087a"] = { common = "Твой дух полон огня, охотник, и ты с радостью встречаешь новые испытания. Следующее задание – приручить волка, известного как охотник прерий. Он быстр и бесстрашен, и чтобы сделать его своим спутником, тебе придётся воспитать в себе эти качества. Во время боя ты поймёшь, как вы будете сражаться бок-о-бок. Ведь вы с питомцем должны действовать очень слаженно, как единый организм. Вот хлыст приручения. Подчини себе охотника прерий, потренируйся." },
    ["6087c"] = { male = "Да... Мать-Земля полагает, что ты готов к следующему уроку.", female = "Да... Мать-Земля полагает, что ты готова к следующему уроку." },
    ["6088a"] = { common = "Последним твоим заданием станет приручение жителя неба. Перепелятник – непростой противник, но зато отличный союзник – атакует он внезапно и пугает врагов. По воле Матери-Земли, по возвращении с победой, я наделю тебя искусством приручать любого зверя и делать его своим спутником; твоему питомцу придётся встретиться с теми же испытаниями, что и тебе, и вместе с тобой набираться опыта. Я покажу тебе, как подзывать и отсылать его по собственной воле." },
    ["6088c"] = { male = "Ты изучил всё, чему я могу тебя научить. Пусть благословения Матери-Земли направляют тебя при выборе своего любимца. Вот. Теперь я дам тебе силу приручать животных, а также отпускать их на волю, когда ты сочтёшь нужным. Используй свои новые способности с гордостью и уважай Мать-Землю.", female = "Ты изучила всё, чему я могу тебя научить. Пусть благословения Матери-Земли направляют тебя при выборе своего любимца. Вот. Теперь я дам тебе силу приручать животных, а также отпускать их на волю, когда ты сочтёшь нужным. Используй свои новые способности с гордостью и уважай Мать-Землю." },
    ["6089a"] = { common = "Теперь ты знаешь, как приручать питомца, но тебе надо научиться ещё и обучать его. Отправляйся в Громовой Утёс. Там тебе нужно будет поговорить с одним из наших самых уважаемых охотников, Хольтом Громовым Рогом. Если он сочтёт тебя достойным знаний, то объяснит тебе, как обучать твоего нового питомца. Хольт одолел многих могущественных и страшных зверей Азерота и сам повелевает сильными существами. Его связь с Матерью-Землёй сильна, и он многому может научить. Удачи." },
    ["6089c"] = { male = "А, юный герой. Да, я могу наделить тебя знаниями, как обучать и направлять твоего питомца. Ты не только сможешь научить его новым способностям, но также сможешь кормить его и даже оживлять, если он падёт в бою. Ступай, Мать-Земля ещё сведёт наши пути. Поговорим позже.", female = "А, юный героиня. Да, я могу наделить тебя знаниями, как обучать и направлять твоего питомца. Ты не только сможешь научить его новым способностям, но также сможешь кормить его и даже оживлять, если он падёт в бою. Ступай, Мать-Земля ещё сведёт наши пути. Поговорим позже." },
    ["6101a"] = { common = "Природа изменчива, но на неё вполне можно положиться. Она предсказуема в том, что никогда не остаётся одной и той же, она всегда меняется. Поручения, которые я тебе дам, помогут тебе увидеть и оценить различных существ, которые впоследствии смогут стать твоими спутниками. Возьми этот хлыст приручения и приручи ночного саблезуба-охотника, которого ты найдёшь к югу отсюда. Поупражняйся в своём охотничьем искусстве. Таким образом ты начнёшь понимать сходства и различия творений природы." },
    ["6101c"] = { common = "Вижу в тебе обязательность и понимание всего, чему я научил тебя." },
    ["6102a"] = { common = "Тебе удалось приручить двух детей земли, и теперь тебе предстоит подружиться с обитателем неба. При помощи этого хлыста приручи совиного визгуна, которую найдёшь к западу отсюда. Испытай своё искусство, взяв в спутники эту могучую сову. Когда вернёшься, я наделю тебя знаниями, которые понадобятся тебе для приручения любого животного, которого ты выберешь себе в спутники. Твой спутник встретит лицом к лицу те же опасности, что и ты, и вместе с тобой будет набираться опыта. Я также научу тебя, как призывать и отпускать по желанию твоего питомца." },
    ["6102c"] = { male = "Теперь ты знаешь всё, чему я мог тебя обучить. Могу ли дать тебе ещё один совет? Хорошенько подумай прежде, чем выбрать первого питомца. Будет ли это существо, что ходит по земле, плавает в воде или рассекает небеса? Кем бы оно ни было, твой питомец, вне всякого сомнения, долго пробудет при тебе. Что же. Ныне я дам тебе умение приручать животное, а так же призывать и отпускать его, когда тебе будет нужно. Гордись своими новыми умениями – ты их честно заслужил.", female = "Теперь ты знаешь всё, чему я мог тебя обучить. Могу ли дать тебе ещё один совет? Хорошенько подумай прежде, чем выбрать первого питомца. Будет ли это существо, что ходит по земле, плавает в воде или рассекает небеса? Кем бы оно ни было, твой питомец, вне всякого сомнения, долго пробудет при тебе. Что же. Ныне я дам тебе умение приручать животное, а так же призывать и отпускать его, когда тебе будет нужно. Гордись своими новыми умениями – ты их честно заслужила." },
    ["6103a"] = { common = "Теперь ты знаешь, как приручать питомца, но тебе надо научиться ещё и обучать его. Отправляйся в Дарнасс. Там тебе нужно будет поговорить с одной из наших самых уважаемых охотниц, Иокастой. Она объяснит тебе, как обучать твоего нового питомца, так что поторопись. Хотя Иокаста и сурова, ей всегда приятно наблюдать за развитием способностей очередного охотника. Держись с ней почтительно, и она воздаст добром. Удачи." },
    ["6103c"] = { male = "Новоиспечённый герой?. Что же, я могу дать тебе знания, необходимые для обучения и управления твоим питомцем. Ты сможешь обучать своего питомца не только новым способностям, но научишься его кормить и возрождать, если он погибнет в схватке. Запомни: всегда уважай равновесие и почитай природу. Теперь ступай. Попозже ещё поговорим.", female = "Новоиспечённый героиня?. Что же, я могу дать тебе знания, необходимые для обучения и управления твоим питомцем. Ты сможешь обучать своего питомца не только новым способностям, но научишься его кормить и возрождать, если он погибнет в схватке. Запомни: всегда уважай равновесие и почитай природу. Теперь ступай. Попозже ещё поговорим." },
    ["6121a"] = { male = "Теперь, ты готов узнать о ядах и о той власти, которой мы, друиды, над ними обладаем. Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар. Однако мы должны быть уверены, что ты усвоил этот важный урок, посему тебе придётся испытать на себе силу действия яда в полной мере. Отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд – он ждёт твоего прибытия, чтобы начать обучение.", female = "Теперь, ты готова узнать о ядах и о той власти, которой мы, друиды, над ними обладаем. Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар. Однако мы должны быть уверены, что ты усвоила этот важный урок, посему тебе придётся испытать на себе силу действия яда в полной мере. Отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд – он ждёт твоего прибытия, чтобы начать обучение." },
    ["6121c"] = { common = "Добро пожаловать, юный друид, рад видеть, что ты горишь желанием узнать о нейтрализации ядов. Если в прошлом большинство друидов проходили заранее установленные испытания, то для твоей работы такого не понадобится. В Аубердине вспышка отравления животных, и в тамошней деревне справиться с этим не могут. Поэтому представитель деревни просил помощи у Лунной поляны, и мы направляем тебя к ним. Это не учёба, а серьёзное задание, имей в виду." },
    ["6122a"] = { common = "Водопад Скалистый на Тёмном Берегу – основной источник питьевой воды для всего региона, но теперь я подозреваю, что именно оттуда распространяется отрава, поражающей местную фауну – особенно оленей. Возьми эту пробирку, чтобы отобрать немного воды из устья пещеры. Осторожнее – в пещере у водопада ныне поселилась опасная нага. Как только наберёшь воды, доставь её Аландариан Песне Ночи в Аубердин. Именно она просила нашей помощи, и ты поможешь ей разобраться с этой заразой." },
    ["6122c"] = { common = "Клянусь Элуной, какая омерзительная вода! Немудрено, что оленей поразил недуг. Что-то заражает воду, и она в свою очередь поражает все грунтовые воды Тёмного Берега. Больных оленей видели повсюду, не только у реки. Даже если эта вода и есть основной источник расползающейся болезни, тут замешано что-то ещё. Хочешь – верь, хочешь – не верь, но эта вода поможет нам найти исцеление. А пока я буду исследовать жидкость, мне понадобится кое-что ещё, чтобы составить лекарство..." },
    ["6123a"] = { male = "Основой целительной мази для оленей послужит вода. Для придания ей целительных свойств мне понадобится землекорень. Травники знают, где его искать, так что, если нам не повезло и вы не травник, придётся найти кого-то, кто сможет помочь. Для усиления воздействия мне нужны лунные грибы. Найти их довольно легко: в пещерах, прямо на восток отсюда, их полным-полно. В этих пещерах обитают лунные совухи; в последнее время они стали очень раздражительны, так что будьте осторожны.", female = "Основой целительной мази для оленей послужит вода. Для придания ей целительных свойств мне понадобится землекорень. Травники знают, где его искать, так что, если нам не повезло и вы не травница, придётся найти кого-то, кто сможет помочь. Для усиления воздействия мне нужны лунные грибы. Найти их довольно легко: в пещерах, прямо на восток отсюда, их полным-полно. В этих пещерах обитают лунные совухи; в последнее время они стали очень раздражительны, так что будьте осторожны." },
    ["6123c"] = { common = "Отлично, вы принесли так много, что должно хватить на несколько больших доз мази – по крайней мере чтобы исцеление началось. Изготовление средств против ядов иногда бывает весьма сложным, поскольку каждый из них требует конкретного антидота для нейтрализации воздействия. Здорово было бы уметь в любой момент снимать отравление, не беспокоясь о конкретных ингредиентах, которые должен содержать антидот! А теперь позвольте мне приступить к работе!" },
    ["6124a"] = { common = "Мази, изготовленной из реактивов, которые вы принесли мне, хватит на десять доз. Пока я работаю здесь, в деревне, пытаясь изготовить побольше этой мази, я хотел бы, чтобы вы помогли нам начать исцеление. По всему Тёмному Берегу встречаются больные олени. Используйте мазь для исцеления их недуга. Я уверен, что Дендрит Звёздная Вспышка из Лунной Поляны захочет поговорить с вами, когда вы закончите. Пожалуйста, передайте благодарность жителей Аубердина Кругу Кенария... и позвольте мне поблагодарить вас лично за вашу помощь!" },
    ["6124c"] = { male = "Вы хорошо сделали, что позаботились о больных оленях Тёмных берегов; это невольные жертвы порчи и осквернения, расползающихся по всему краю. В Дарнассе есть те, кто признаёт наличие угрозы... и те, кто упорно игнорирует её всё усиливающиеся признаки. Я надеюсь, что вы, – один из тех, кто не собирается надевать шоры и будет смотреть в лицо фактам. Как бы там ни было, вы доказали, что являетесь другом природы и Круга Кенария, и я прошу вас принять это в качестве знака нашей дружбы.", female = "Вы хорошо сделали, что позаботились о больных оленях Тёмных берегов; это невольные жертвы порчи и осквернения, расползающихся по всему краю. В Дарнассе есть те, кто признаёт наличие угрозы... и те, кто упорно игнорирует её всё усиливающиеся признаки. Я надеюсь, что вы, – одна из тех, кто не собирается надевать шоры и будет смотреть в лицо фактам. Как бы там ни было, вы доказали, что являетесь другом природы и Круга Кенария, и я прошу вас принять это в качестве знака нашей дружбы." },
    ["6125a"] = { male = "Ты познал, что значит исцелять от действия яда без помощи духов. Помни же, что приходится претерпевать другим в борьбе против отравы, и прими свою новую власть над ядами. Тебе следует вернуться к Матренгилу Медвежьей Лапе в Дарнасс. Теперь, когда его ученик усвоил данный ему урок, он несомненно научит тебя новому могучему заклинанию. До свидания, юный друид. Мы ещё встретимся.", female = "Ты познала, что значит исцелять от действия яда без помощи духов. Помни же, что приходится претерпевать другим в борьбе против отравы, и прими свою новую власть над ядами. Тебе следует вернуться к Матренгилу Медвежьей Лапе в Дарнасс. Теперь, когда его ученица усвоила данный ей урок, он несомненно научит тебя новому могучему заклинанию. До свидания, юный друид. Мы ещё встретимся." },
    ["6125c"] = { male = "С возвращением. Я следил за твоими успехами с тех самых пор, как ты покинул нас, и, должен признаться, был изумлён, узнав о ситуации в Аубердине. Это требует дальнейшего расследования, ибо появление такого яда в окружающей среде чрезвычайно нарушает равновесие. Ты благородно поступил в трудной ситуации. И я не вижу лучшего поощрения, чем даровать тебе в награду постоянную власть над ядами. Используй её во благо... во благо.", female = "С возвращением. Я следил за твоими успехами с тех самых пор, как ты покинула нас, и, должен признаться, был изумлён, узнав о ситуации в Аубердине. Это требует дальнейшего расследования, ибо появление такого яда в окружающей среде чрезвычайно нарушает равновесие. Ты благородно поступила в трудной ситуации. И я не вижу лучшего поощрения, чем даровать тебе в награду постоянную власть над ядами. Используй её во благо... во благо." },
    ["6126a"] = { male = "Теперь, ты готов узнать о ядах и о той власти, которой мы, друиды, над ними обладаем. Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар. Однако мы должны быть уверены, что ты усвоил этот важный урок, посему тебе придётся испытать на себе силу действия яда в полной мере. Отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд – он ждёт твоего прибытия, чтобы начать обучение.", female = "Теперь, ты готова узнать о ядах и о той власти, которой мы, друиды, над ними обладаем. Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар. Однако мы должны быть уверены, что ты усвоила этот важный урок, посему тебе придётся испытать на себе силу действия яда в полной мере. Отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд – он ждёт твоего прибытия, чтобы начать обучение." },
    ["6126c"] = { common = "Привет тебе, мой юный друид, я рад, что ты жаждешь узнать, как изгонять из тела яд. В старину друиды проходили заранее установленные испытания, но тебе этого делать не придётся. В Перекрёстке и Степях вспышка отравлений животных, и справиться с ней там никак не могут. Оттуда запросили помощи Лунной поляны, так что мы посылаем тебя. Это не учёба, а серьёзное задание. Помни это." },
    ["6127a"] = { common = "Вершина Багрового Тумана, что к северо-западу от Перекрёстка – самый вероятный источник распространения этой отравы. На его вершине находятся озёра воды, влияющие на перемены погоды. Подозреваю, что вода сейчас заражена демонопоклонниками из клана Пылающего Клинка. Возьми этот пробоотборник и набери воды из озёра у самой вершины. Наполнив, доставь его Тонге Руническому Тотэму в Перекрёсток. Именно он и просил нашей помощи, и ты будешь работать вместе с ним над искоренением этой заразы." },
    ["6127c"] = { common = "Клянусь предками, какая омерзительная вода! Немудрено, что газелей поразил недуг. Что-то заражает воду, и она начинает разрушать экосистему северных Степей. Больных газелей видели повсюду к северу от тутошней дороги с востока на запад. Даже если эта вода и есть основной источник расползающейся болезни, тут замешано что-то ещё. Эта вода, верь – не верь, поможет нам найти исцеление. А пока я буду исследовать эту воду, мне понадобится кое-что ещё, чтобы составить лекарство..." },
    ["6128a"] = { male = "Основой целебной мази для газелей послужит вода. Для придания ей целебных свойств мне понадобится землекорень. Травники знают, где его отыскать, так что если нам не повезло, и ты – не травник, придётся попросить кого-то о помощи. Для силы воздействия мне нужны рога кодо – осколки и куски не подойдут. Кодо живут в северной части Степей. Убей несколько зверюг, заодно и природное равновесие восстановится. Отпили у них рога и принеси мне.", female = "Основой целебной мази для газелей послужит вода. Для придания ей целебных свойств мне понадобится землекорень. Травники знают, где его отыскать, так что если нам не повезло, и ты – не травница, придётся попросить кого-то о помощи. Для силы воздействия мне нужны рога кодо – осколки и куски не подойдут. Кодо живут в северной части Степей. Убей несколько зверюг, заодно и природное равновесие восстановится. Отпили у них рога и принеси мне." },
    ["6128c"] = { male = "Отлично, ты принёс так много составляющих, что должно хватить на несколько больших доз мази – по крайней мере, положим начало исцелению. Изготовление средств против ядов иногда бывает весьма сложным, ведь для нейтрализации каждого из них требуется отдельный антидот. Здорово было бы научиться в любой момент лечить отравления, не беспокоясь о конкретных составляющих противоядия! Ладно, пора браться за работу!", female = "Отлично, ты принесла так много составляющих, что должно хватить на несколько больших доз мази – по крайней мере, положим начало исцелению. Изготовление средств против ядов иногда бывает весьма сложным, ведь для нейтрализации каждого из них требуется отдельный антидот. Здорово было бы научиться в любой момент лечить отравления, не беспокоясь о конкретных составляющих противоядия! Ладно, пора браться за работу!" },
    ["6129a"] = { male = "Мне удалось сделать десять доз целебной мази. Пока я работаю здесь, в деревне, пытаясь изготовить побольше, я хотел бы, чтобы ты помог нам лечить бедных зверей. По всей северной части Степей бродят больные газели. Исцели их недуг при помощи этой мази. Я уверен, что Дендрит Блеск Звёзд на Лунной Поляне захочет поговорить с тобой, когда ты закончишь. Пожалуйста, передай нашу благодарность Кругу Кенария... и позволь мне поблагодарить тебя лично за неоценимую помощь!", female = "Мне удалось сделать десять доз целебной мази. Пока я работаю здесь, в деревне, пытаясь изготовить побольше, я хотел бы, чтобы ты помогла нам лечить бедных зверей. По всей северной части Степей бродят больные газели. Исцели их недуг при помощи этой мази. Я уверен, что Дендрит Блеск Звёзд на Лунной Поляне захочет поговорить с тобой, когда ты закончишь. Пожалуйста, передай нашу благодарность Кругу Кенария... и позволь мне поблагодарить тебя лично за неоценимую помощь!" },
    ["6129c"] = { common = "Вы хорошо сделали, что позаботились о больных газелях Степей; это невольные жертвы порчи и осквернения, расползающихся по всему краю. Вы, таурены, лучше прочих постигаете мудрость Кенария. И Вы, как и мудрейшие из Громового Утёса, постигаете, что необходимость достичь равновесия превыше искусственных расовых границ. Так или иначе, вы доказали, что являетесь другом природы и Круга Кенария, и я прошу вас принять это в качестве знака нашей дружбы." },
    ["6130a"] = { male = "Ты познал, что значит исцелять от действия яда без помощи духов. Помни же, что приходится претерпевать другим в борьбе против отравы, и прими свою новую власть над ядами. Тебе следует вернуться к Тюраку Руническому Тотэму в Громовой Утёс. Теперь, когда его ученик усвоил данный ему урок, он несомненно научит тебя новому могучему заклинанию. До свидания, юный друид. Мы ещё встретимся.", female = "Ты познала, что значит исцелять от действия яда без помощи духов. Помни же, что приходится претерпевать другим в борьбе против отравы, и прими свою новую власть над ядами. Тебе следует вернуться к Тюраку Руническому Тотэму в Громовой Утёс. Теперь, когда его ученица усвоила данный ей урок, он несомненно научит тебя новому могучему заклинанию. До свидания, юный друид. Мы ещё встретимся." },
    ["6130c"] = { male = "С возвращением. Я следил за твоими успехами с тех самых пор, как ты покинул нас, и, должен признаться, был изумлён, узнав о ситуации в Перекрёстке. Это требует дальнейшего расследования, ибо появление такого яда в окружающей среде чрезвычайно нарушает равновесие. Ты благородно поступил в трудной ситуации. И я не вижу лучшего поощрения, чем даровать тебе в награду постоянную власть над ядами. Используй её во благо... во благо.", female = "С возвращением. Я следил за твоими успехами с тех самых пор, как ты покинула нас, и, должен признаться, был изумлён, узнав о ситуации в Перекрёстке. Это требует дальнейшего расследования, ибо появление такого яда в окружающей среде чрезвычайно нарушает равновесие. Ты благородно поступила в трудной ситуации. И я не вижу лучшего поощрения, чем даровать тебе в награду постоянную власть над ядами. Используй её во благо... во благо." },
    ["6132a"] = { common = "Вытащи меня отсюда! Я отправилась к Долине Копий, чтобы поговорить с Мародинами. Мне казалось, с ними можно вести кое-какие дела... Но они не желают говорить со мной! Мне кажется, они... они хотят съесть меня! Только вытащи меня отсюда – вот увидишь, мой брат Хормиц тебе кучу денег отвалит! А найти-то его несложно: он в нашем лагере, к востоку отсюда, там ещё Кладбище кодо рядом. Нам лучше поторопиться: буквально пару минут назад я слышала, как два кентавра говорили, что нужно собрать дрова для готовки..." },
    ["6132c"] = { male = "Моя сестра Мелисса предупредила меня о твоём приходе. Хочу тебя поблагодарить за то, что вытащил её из очередной беды. Правда, боюсь, она уже успела вязаться во что-то новое...", female = "Моя сестра Мелисса предупредила меня о твоём приходе. Хочу тебя поблагодарить за то, что вытащила её из очередной беды. Правда, боюсь, она уже успела вязаться во что-то новое..." },
    ["6133a"] = { common = "Высшие эльфы в Сторожке Кель'Литиен присвоили себе кое-что, что принадлежит мне, герой. Это документ, описывающий мою смертную жизнь. Нет, к тебе его содержимое не имеет никакого отношения — даже не вздумай сунуть туда нос! Твоё дело маленькое, насекомое — принеси мне документ! И имей в виду, тупица, я хочу, чтобы эти негодяи пожалели, что наложили свои лапы на мою частную собственность! Нанеси им как можно больший ущерб!" },
    ["6133c"] = { common = "Я думаю, что ты не читал реестр. Никто, даже ты не сделает такой глупости." },
    ["6134a"] = { common = "На юго-востоке есть местность, именуемая Долиной Костей. Долину эту населяют призраки кентавров племени Маграм. Жутковато звучит, верно? Подумай, как это пугает Маграмов!.. Если бы нам удалось собрать энергию призраков – только представь, что за это дали бы кентавры!.. Вот, возьми эти призрачные магниты. Если поставишь такой магнит между двух скелетов, Мёртвых Гигантов, то призраки потянутся к нему. Отойди подальше, уничтожь призраков и собери их эктоплазму: позже мы продадим её Маграм." },
    ["6134c"] = { male = "А вот и она!.. Похоже, ты и сам в эктоплазме перемазался. Склизкая штука, верно? Что ж, прими мою благодарность. Эта дрянь стоит целого состояния... Конечно, если удастся убедить кентавров её купить!", female = "А вот и она!.. Похоже, ты и сама в эктоплазме перемазалась. Склизкая штука, верно? Что ж, прими мою благодарность. Эта дрянь стоит целого состояния... Конечно, если удастся убедить кентавров её купить!" },
    ["6135a"] = { common = "Пока тебе удаётся с горем пополам выполнять мои поручения. Пора бы заставить тебя сделать что-нибудь посложнее. Да, тупица, ты дозрел до настоящей работёнки. Вот что, выследи и убей Тенекрыла — это чудовищная летучая мышь-альбинос, которая хозяйничает в землях к северу отсюда. И принеси мне клок его белой шерсти — чтоб я знал, что ты не врёшь!" },
    ["6135c"] = { common = "Прекрасная работа, глупец. Я сделаю из его меха кое-что полезное." },
    ["6136a"] = { common = "За лагерем Серебряного Рассвета и часовней Светлых надежд, к западу от Северного дола обитает огромный червь, Мерзкослиз. Я потерял целые батальоны в попытках уничтожить его. Его размеры невообразимы! Чем больше он ест, тем больше растёт… Хотя я, в общем-то, мало волнуюсь по поводу того, сожрёт ли тебя червь, должен признать, что предпочёл бы, чтобы ты вышел победителем. Учти, Мерзкослиз особенно охотно жрёт тех, кто попытался напасть на него." },
    ["6136c"] = { common = "Держи вот это и ещё… я продвину тебя в ранге от имбецила, каковым ты являешься до умственно отсталого. Прогресс!" },
    ["6141a"] = { common = "Антон, мой собрат по оружию, услышал вести о нашествии нежити в далёком Калимдоре, в тех землях, что называются Пустошами. Конечно же, он немедленно собрался в путь, чтобы покончить с этой угрозой! Он ищет отважных и решительных спутников – тех, у кого хватит храбрости сражаться с ним плечом к плечу. Если ты хранишь чистоту в своём сердце, разыщи брата Антона в городе, носящем имя Высоты Найджела, в Пустошах." },
    ["6141c"] = { male = "Я получил вести о помощи, грядущей с востока. Не о тебе ли шла речь? Ты пришёл сюда, дабы помочь Алым в нашем благородном походе? Если это так, то слушай...", female = "Я получил вести о помощи, грядущей с востока. Не о тебе ли шла речь? Ты пришла сюда, дабы помочь Алым в нашем благородном походе? Если это так, то слушай..." },
    ["6142a"] = { male = "Судя по виду, герой, ты – заядлый рыбак! Обожаю ловить рыбу, всю жизнь этим занимаюсь. Можешь мне поверить, нет лучшей наживки, чем мясо мягкокожего моллюска: рыба просто не может против неё устоять, если ты понимаешь, о чём я. На север отсюда, неподалёку от берега, есть потерпевший крушение корабль: так вот, вокруг него эти моллюски так и кишат! Принесёшь мне десять кусочков мяса моллюска – а взамен я тебе дам кое-что полезное...", female = "Судя по виду, героиня, ты – заядлая рыбачка! Обожаю ловить рыбу, всю жизнь этим занимаюсь. Можешь мне поверить, нет лучшей наживки, чем мясо мягкокожего моллюска: рыба просто не может против неё устоять, если ты понимаешь, о чём я. На север отсюда, неподалёку от берега, есть потерпевший крушение корабль: так вот, вокруг него эти моллюски так и кишат! Принесёшь мне десять кусочков мяса моллюска – а взамен я тебе дам кое-что полезное..." },
    ["6142c"] = { common = "Это просто великолепно!.. Когда я спросила у знахаря, как лечить головную боль, он мне ответил: Май'Лахия, детка, попробуй половить рыбку в мутной воде; увидишь – тебе сразу полегчает! Ох, как подумаю – мне и правда сразу легче становится!" },
    ["6143a"] = { male = "Может, ты слышал, может, нет... Мы с командой рыбачили неподалёку от острова Раназьяр, к северу от разбитого корабля на северном побережье. Мы всегда там рыбачили, сколько я себя помню – а теперь я ни о чём другом не могу думать, кроме как о мести за своих друзей... Однажды утром на нас напали наги. Они убили всех, кроме меня!.. Я не могу вынести бремени этой вины, герой, пойми меня: ты нужен мне, чтобы расправиться с проклятыми нагами. Поверь, я хорошо вознагражу тебя. Ты ведь возьмёшься за это дело?", female = "Может, ты слышала, может, нет... Мы с командой рыбачили неподалёку от острова Раназьяр, к северу от разбитого корабля на северном побережье. Мы всегда там рыбачили, сколько я себя помню – а теперь я ни о чём другом не могу думать, кроме как о мести за своих друзей... Однажды утром на нас напали наги. Они убили всех, кроме меня!.. Я не могу вынести бремени этой вины, героиня, пойми меня: ты нужна мне, чтобы расправиться с проклятыми нагами. Поверь, я хорошо вознагражу тебя. Ты ведь возьмёшься за это дело?" },
    ["6143c"] = { common = "Ты говоришь, эти мерзкие твари мертвы? Да, месть сладка... Но в моём сердце по-прежнему пустота, которой ничто не заполнит. Я посвящу всю свою жизнь тому, чтобы извести нагов под корень – весь их род до последнего змеёныша!.. Вот, дружище, держи свою награду, как я и обещал – хотя она ничтожно мала в сравнении с моей благодарностью..." },
    ["6144a"] = { common = "Вот что, герой, поступил приказ по армии. Сам Вариматрас требует, чтобы я прислал ему самых способных солдат в Подгород для выполнения крайне сложной операции. Увы, самые достойные и способные давно погибли, а вместо них я располагаю кучкой жалких недоумков. Предстанешь перед Вариматрасом в Подгороде. Смотри, не опозорь меня, герой!" },
    ["6145c"] = { common = "Наконец-то! Ура! Шанс уничтожить Алого Оракула!" },
    ["6146a"] = { common = "Я тут немного подрихтовал приказ. Если наша маленькая уловка сработает, Алый Оракул на некоторое время окажется почти без защиты. Тут-то мы и нанесём удар! Теперь слушай внимательно, герой. Доставишь приказ лорду-рыцарю Валделмару. Что значит как?! Лично в руки, тупица! Держи приказ и это гнилое яблоко — съешь его, когда войдёшь в город. Оно… э-э… придаст тебе более приятный для человеческого глаза вид. Запомни, лично в руки лорду-рыцарю Валделмару!" },
    ["6146c"] = { common = "Где ты был? Мы думали что Плеть захватила тебя." },
    ["6147a"] = { common = "Верховный рыцарь прислал очень странный приказ… Однако приказы не обсуждаются. Возвращайся в Бастион Алого ордена и сообщи, что Оракул выдвигается немедленно. Мы приложим все усилия, чтобы доставить его в Стратхольм в целости и сохранности." },
    ["6147c"] = { common = "Глупцы! Мой обман остался незамеченным! Приготовься, герой. Мы должны нанести удар с холодной хитростью!" },
    ["6148a"] = { common = "Деметрия — главный советник верховного рыцаря. Её величают Оракулом за её сверхъестественные способности. Она неоднократно оказывала помощь Алому ордену в боях с Плетью. Посмотрим, в самом ли деле ей открыто будущее… Уверен, она предвидела, что её ждут неприятности. Вот ты их ей и обеспечишь! Выследи Оракула и убей её. Полагаю, сейчас она на пути к Длани Тира. Не подведи меня, насекомое!" },
    ["6148c"] = { common = "Я ждал этого момента годами… Молодец, путник! Ты не только заслужил моё уважение, но и награду!" },
    ["6161a"] = { common = "Записи Ракмора рассказывают о том, как во время плаванья к Крепости Оперённой Луны его корабль был атакован морскими тварями. Чтобы не дать врагу завладеть его сокровищем, Ракмор спрятал сундук на острове Раназьяр. Открыть сундук можно только двумя ключами, золотым и серебряным. Они были утрачены, но если разыскать и сундук, и оба ключа – кто знает, какие сокровища откроются счастливцу?" },
    ["6161c"] = { common = "Сундук открывается. Перед вами сокровище Ракмора!" },
    ["6162a"] = { common = "Мой супруг ради чести нашего клана отправился в Осквернённый лес, чтобы сразиться с Советом Теней и прочими мерзостными тварями! Он несколько раз избегал смерти. Потом я получила письмо от него, в котором он говорил, что некий друид попросил у него помощи против огромного поражённого порчей фурболга по имени Рор — и с тех пор я не слышала больше ни о муже, ни о друиде. Я хочу, чтобы ты принёс мне отрубленную когтистую лапу этого Рора, путник! Я жажду мести за моё вдовство! Эта тварь, как я знаю, засела где-то на юге, возле границы Ясеневого леса." },
    ["6162c"] = { common = "Ты человек чести… а также человек слова… Мой муж погиб в битве, но я не могла успокоиться, пока не узнала, что существо, которое погубило его, получило то же самое. Спасибо тебе, путник." },
    ["6163a"] = { common = "На этом самом месте я когда-то держал оборону Лордерона… Бесчисленное воинство Плети прошло волной по моей ферме, уничтожив всё живое на своём пути. Грязь. Скверна. Я стал беспомощной и безвольной игрушкой в руках Плети, оказавшись в рядах нежити. Сознанием моим управляла воля Короля-лича. А потом она освободила меня… Я ждал, я надеялся и наконец обрёл свободу. Теперь я хочу отомстить чудовищу, забравшему мою жизнь. Убей его!" },
    ["6163c"] = { common = "Я удивляюсь… пощада? Какая пощада может быть такому…? Я повешу голову этого уродца у себя на стене. Теперь ты равен моим чемпионам" },
    ["6164a"] = { common = "Пожалуй, я готов открыть лавку… О нет! Моя книга рецептов! Мне не обойтись без неё! Кажется я оставил её где-то в городе… да, видимо, в таверне, в которой останавливался! Принеси мне мою книгу, о умоляю, принеси мне её! Ты увидишь, цены у меня СУМАСШЕДШИЕ!" },
    ["6164c"] = { common = "Вот она! Какое счастье! Это безумно счастливый день, путник!" },
    ["6181a"] = { common = "Хотя мы не получаем серьёзной помощи напрямую из Штормграда, у меня в городе есть знакомый, снабжающий нас доспехами. Зовут его Озрик Штранг. Его магазин, \"Ограниченная неуязвимость\", находится в Старом городе. Наши запасы доспехов заканчиваются, и я должен связаться с Озриком, чтобы попросить ещё. Можете ли вы передать ему эту записку? Быстрее всего добраться до Штормграда можно с помощью Тора, нашего укротителя грифонов. Он находится прямо у подножия этого холма. Приходите к нему с моей запиской, а затем летите на грифоне в Штормград." },
    ["6181c"] = { common = "Вам нужно доставить эту записку в Штормград? Это не проблема, вы можете взять одного из моих грифонов!" },
    ["6182a"] = { common = "Натанос Маррис был первым и последним человеком-предводителем следопытов. Учеником Сильваны Ветрокрылой, ныне королевы-банши Отрекшихся. Мы думали, что Натанос погиб в бою много лет назад, при защите Лордерона. Хотя его тело не было обнаружено, считалось, что он не сумел выбраться из Восточных Чумных земель. Матиас Шоу изучил обстоятельства его исчезновения и у него может быть какая-то информация. Доложитесь ему немедленно. Он обитает в Старом городе, в казармах." },
    ["6182c"] = { common = "После появления сообщений о необычной активности Отрекшихся в Восточных Чумных землях туда были посланы агенты ШРУ для расследования ситуации. Результаты этого расследования оказались весьма тревожными." },
    ["6183a"] = { common = "Пятеро моих лучших полевых агентов занимались делом Марриса. Вернулся только один, и тот через три дня умер во сне. Та скудная информация, которую удалось из него вытрясти, звучала несусветной чушью. Мы разобрали лишь два слова: \"Натанос\" и \"Гнилостень\". У меня не хватает сотрудников, чтобы продолжить это расследование, и в \"Чёрном Вороне\" нам не помогут. Мы должны докопаться до сути, чтобы хотя бы принести какое-то утешение семьям погибших. Вы окажете нам помощь?" },
    ["6183c"] = { common = "Я и не сомневался, что Болвар пришлёт мне честных и благородных людей — самых преданных солдат Альянса." },
    ["6184a"] = { common = "Единственные сведения, которыми мы сейчас располагаем — это то, что Натаноса Марриса, возможно, убил этот тип по имени \"Гнилостень\". Мы допускаем, что тот же \"Гнилостень\" расправился и с моими агентами. Флинт Тенемор, ещё один сотрудник ШРУ, находится в лагере на Берегу Промозглого Ветра в Западных Чумных землях. Найдите его. Он расскажет вам о текущей ситуации в Чумных землях и даст задание. Удачи вам, путник." },
    ["6184c"] = { common = "Ваше первое задание будет очень простым, путник. Уйти — и вернуться. Провести разведку…" },
    ["6185a"] = { common = "Говорю же, первое задание — разведывательное. Ничего особенного, путник. Отправляйся в Восточные Чумные земли и поищи там сведения про Гнилостеня. И поглядывай, не найдёшь ли ты наших пропавших оперативников. Мы вынуждены предположить, что они погибли, но коли так, должны быть… трупы. Все агенты ШРУ носят такие знаки. Принеси мне все, какие только найдёшь." },
    ["6185c"] = { common = "Рутгер. Фредо. Турьен. Все… Мертвы… Где они были? Удалось ли тебе собрать сведения про этого мерзавца, Гниля?" },
    ["6186a"] = { common = "Это дело рук На… Натаноса? Натанос и есть Гнилостень? Но почему? Он был… таким благородным, пользовался всеобщим уважением. Единственный человек, которого согласились обучать высшие эльфы. И теперь он безжалостный сторонник Отрекшихся? Мне… жаль, что приходится просить об этом, путник, но об этих событиях должен узнать верховный лорд Фордрагон. Я прошу тебя незамедлительно вернуться в Штормград с вестями." },
    ["6186c"] = { common = "Нет. Не может… НЕТ! Как? Агент Отрекшихся? ЗАЩИТНИК Королевы банши???" },
    ["6187a"] = { common = "Знаете, сколько предводителей следопытов существует на этом свете? А сколько когда-либо существовало людей-предводителей следопытов? Достижения Натаноса необыкновенны. Он был тактическим гением, благодаря ему Альянс в течение десятилетия одерживал победы. А теперь… теперь он защитник Отрекшихся. Нет. Такого быть не должно. Порядок должен быть восстановлен. Соберите армию, путник. Возвращайтесь в Чумные земли со своими воинами и уничтожьте Гнилостеня. Желаю удачи, путник. В этом бою она вам точно понадобится." },
    ["6187c"] = { common = "Это трагедия. Я думаю что… я считаю что весь наш род проклят, путник. Мы все прокляты! Потерять наших величайших воинов, наших самых благородных героев… Мы в долгу перед тобой, и я уверяю тебя, путник, где бы Натанос сейчас ни был, он улыбается, смотря на нас сверху." },
    ["6261a"] = { common = "Я сложил в этот ящик всё, о чём просил Льюис. Можете отвезти ему ящик? С Тором в Западном Крае вы уже общались – значит, сможете нанять грифона, чтобы туда вернуться. Наш укротитель грифонов – Дунгар Долгопив, он находится в Торговом квартале. Поговорите с Дунгаром и доставьте этот ящик Льюису как можно скорее. Мы не хотим, чтобы нашим воинам в Западном Крае пришлось сражаться без новых доспехов!" },
    ["6261c"] = { common = "Нужно доставить сундук в Западный Край, да? А вы там бывали прежде? Если да, то никаких проблем, друг мой. У меня есть множество грифонов, обученных этому маршруту!" },
    ["6281a"] = { common = "За небольшую плату вы можете нанять грифона для полёта в Штормград, чтобы доставить записку Льюиса Озрику. Более быстрого пути нет. Если для вас это приемлемо, поговорите со мной снова, когда будете готовы лететь. Я, конечно, возьму с вас немного денег, но поверьте, оно того стоит!" },
    ["6281c"] = { common = "А, записка от интенданта Льюиса! Я не удивлён, что ему понадобилась дополнительная экипировка. Сторожевой Холм далеко, и в Штормграде едва помнят о нём. Что ж, спасибо вам. Вот немного денег на покрытие ваших транспортных расходов." },
    ["6282a"] = { common = "Таурен горд тем, что защищает эти земли. Несомненно, ты понимаешь, почему я обеспокоен тем, что здесь, в Каменном Когте, обитает множество гарпий. Клан Смертельной Ярости – вот откуда берутся всё новые и новые гарпии в Калимдоре. Они посягают на жизнь всех и каждого, не давая слабым даже уйти отсюда! Мне нужна твоя помощь в уничтожении гарпий!" },
    ["6282c"] = { common = "Замечательные новости! Поведай мне вновь, как тебе удалось вселить ужас в холодные сердца злобных гарпий. Клан Смертельной Ярости понёс серьёзный урон!" },
    ["6283a"] = { common = "Уменьшить число гарпий из стаи Кровавой Ярости – этого недостаточно. Единственное, чем можно извести эту заразу – это убить их предводительницу, Потрошительницу! Средь этих мерзостных существ она почти королева. Убей её, и гарпий станет меньше. Возвращайся в Обугленную долину, и ты найдёшь её у западных холмов. Её не так-то легко уничтожить, но награда будет велика." },
    ["6283c"] = { common = "Я уже чувствую, как гнев покидает меня. Что мне теперь делать? Знание о том, что зло бродило поблизости от моих земель, заставляло мои мысли течь быстро, пусть и безмолвно. Быть может, это и к лучшему... быть может, теперь я смогу обратить свои мысли в сторону добра, как и положено таурену. Прошу тебя, прими это в награду за твои труды." },
    ["6284a"] = { common = "Предупреждение: дорога отсюда на запад, в Сиширский каньон, опасна. Бесселет и её восьминогие отпрыски превратили этот каньон в своё логово, заплетённое паутиной. Маггран Связующий Землю из Приюта у Солнечного Камня назначил награду за Бесселет. Убей её и принеси доказательство её смерти Магграну – получишь награду за устранение этой восьминогой угрозы." },
    ["6284c"] = { common = "Добрая охота! Бесселет издавна была угрозой для этих земель... и я не буду по ней тосковать. Возьми эту награду в знак того, что тебе удалось защитить наш лес. Маггран потирает рану, нанесённую Бесселет. Быть может, теперь больше народа будет приходить в Приют у Солнечного Камня, не боясь того, что крадётся во мраке." },
    ["6285a"] = { common = "Укротителем грифонов в Западном Крае работает Тор. Если вы с ним уже знакомы, то можете на одном из моих грифонов к нему долететь. Полезная для вас информация: грифоны обучены так, что до столицы могут долететь всегда, а к укротителям, расположенным в других местах, полетят, только если вы там уже бывали. Вы ведь уже были у Тора, так что просто поговорите со мной ещё раз, когда будете готовы лететь в Западный Край. А там уже отнесёте ящик Озрика интенданту Льюису." },
    ["6285c"] = { male = "Отлично, вы привезли доспехи! Мы распределим их между теми, кому они срочно необходимы. Спасибо вам, сэр путник. Вы нам очень помогли. А теперь, когда вы знакомы и с нашими грифонами, я надеюсь, вы будете часто прилетать к нам и предлагать свою помощь Сторожевому холму!", female = "Отлично, вы привезли доспехи! Мы распределим их между теми, кому они срочно необходимы. Спасибо вам, леди путница. Вы нам очень помогли. А теперь, когда вы знакомы и с нашими грифонами, я надеюсь, вы будете часто прилетать к нам и предлагать свою помощь Сторожевому холму!" },
    ["6301a"] = { common = "Жадность промышленников и постоянная война опустошили земли Каменного Пика. Только благословение Матери-Земли может исцелить такие раны. Я хочу отправить тебя на поиски особого семени – семени Геи. Его можно найти только здесь, в Каменном Когте, к северу от Приюта у Солнечного Камня, у Мутного Озера, у самого края воды. Как только ты принесёшь мне эти семена, я напитаю их шаманской силой, дабы ускорить их рост." },
    ["6301c"] = { common = "О, так вот они – семена Геи! Смотри и увидишь, как благословение Матери-Земли даст этим крошечным семенам жизни возможность цвести и плодоносить. Таммра начинает читать заклинание." },
    ["6321a"] = { common = "Исполнитель Хадрик попросил меня заняться нашим арсеналом в Гробнице. По лесу рыщут силы Плети, а то и кое-что похуже, и он хочет, чтобы у наших стражей смерти было достаточно оружия, когда оно понадобится. Я выяснил, что в целом у нас всё в порядке, но нам нужно дополнительное оружие взамен потерянного в боях. Вот заявка на поставку для торговца оружием Гордона Уиндема, находящегося в Подгороде. Отнесите этот заказ нашему дрессировщику летучих мышей, Каросу Раззоку, и поговорите с ним о полёте в Подгород." },
    ["6321c"] = { common = "А, заказ на поставки. Не сомневаюсь, вам нужно доставить его в Подгород. И как можно скорее, потому что в Гробнице нельзя допустить нехватку оружия." },
    ["6322a"] = { common = "Я сложил припасы для Гробницы в этот ящик. Если вы уже бывали в Гробнице и знакомы с тамошним дрессировщиком летучих мышей, то можете туда лететь. Поговорите с дрессировщиком летучих мышей здесь, в Подгороде – с Майклом Гарреттом. Он поможет вам добраться до Гробницы." },
    ["6322c"] = { common = "Этот ящик нужно доставить в Гробницу, что в Серебряном бору? Это легко: наши мыши ежедневно туда летают." },
    ["6323a"] = { common = "Одна из моих летучих мышей может отвезти вас в Подгород, за небольшую плату. Приходите ко мне, когда будете готовы, чтобы мы могли организовать ваш полёт. Гордона Уиндема вы найдёте в Торговом квартале Подгорода. Именно там и приземлится летучая мышь." },
    ["6323c"] = { common = "Заказ из Гробницы? Отлично. Для меня честь – услужить тем, кто служит Тёмной Госпоже." },
    ["6324a"] = { common = "Дрессировщика летучих мышей в Гробнице зовут Карос Раззок. Если вы уже знакомы с ним, я могу предоставить вам одну из своих летучих мышей, чтобы вы к нему вернулись. Все наши мыши всегда могут долететь до Подгорода, но, чтобы добраться до более отдалённых мест, пассажир должен сначала посетить эти места и познакомиться с тамошними дрессировщиками. С Каросом вы уже встречались в Гробнице, так что теперь можете летать туда на мышах. Вернитесь ко мне, когда будете готовы к полёту." },
    ["6324c"] = { common = "Хорошая работа. Это оружие позволит не застать врасплох наших стражей смерти. Вы сослужили хорошую службу Тёмной Госпоже." },
    ["6341a"] = { common = "Рыбаки деревни Рут'теран живут очень хорошо: ведь рыба здесь очень крупная, и её много. Я хотела бы сравнить здешнее изобилие с ситуацией в материковых водах. Я собрала образцы рыбьих костей и чешуи, которые хотела бы отправить своему коллеге на Тёмный Берег. Его зовут Лайрд, он торгует рыбой в Аубердине. Идите с моей коллекцией образцов к нашему дрессировщику гиппогрифов, Веспристу, и поговорите с ним насчёт полёта в Аубердин." },
    ["6341c"] = { common = "А, вы хотите доставить эту посылку в Аубердин? Отлично..." },
    ["6342a"] = { common = "Из деревни Рут'теран можно добраться в Аубердин двумя путями: на пароме и на гиппогрифе. Оба способа быстры и надёжны, но если вы ещё никогда не летали в Аубердин на гиппогрифе, я бы порекомендовал вам это сделать. Мой вам добрый совет: говорите с дрессировщикам гиппогрифов в каждом городе, где они есть. Когда вы поговорите с дрессировщиком, то сможете летать в этот город из других мест. Возвращаю вам коллекцию Нессы. Поговорите со мной, когда будете готовы лететь в Аубердин и доставить коллекцию Лайрду." },
    ["6342c"] = { common = "Посылка от Нессы? Спасибо Она говорила, что собирается прислать мне образцы рыбы, пойманной близ деревни Рут'теран. Она думает, что эта рыба может серьёзно отличаться от той, что ловится здесь... Ничего себе! Эта челюсть чуть ли не вдвое больше, чем у таких же здешних рыб. А эта чешуя размером с кулак! Невероятно!" },
    ["6343a"] = { common = "Мне нужно отправить Нессе ответ. Ей будет очень интересно знать, насколько здешняя рыба отличается от той, что водится у берегов Тельдрассила. Мы можем лишь догадываться о причинах, но подозреваю, что так воздействует само Древо Жизни на окружающую его природу! Пожалуйста, отнесите мой ответ Нессе. Если хотите лететь в Рут'теран на гиппогрифе, поговорите с дрессировщиком гиппогрифов Кайлаис Лунному Перу. А если хотите добраться паромом, то он регулярно отходит от причала к северо-западу отсюда." },
    ["6343c"] = { common = "Всё это очень интересно. Рыба здесь крупная, но я не думала, что разница между обитающими в материковых и здешних водах столь велика. Для этого должна быть причина... Что ж, благодарю вас Я обсужу с земляками новости, что вы принесли. Может быть, когда-нибудь мы найдём причину этой странности. А пока будем ею пользоваться!" },
    ["6344a"] = { common = "Моя подруга, Несса Песня Теней, торгует рыбой в деревне Рут'теран. Ей нужно доставить посылку на Тёмный берег, и она ищет кого-нибудь, кто мог бы ей помочь. Если вы хотите помочь Нессе, то ступайте в деревню Рут'теран через портал в Дарнассе. Портал находится к западу от Храмовых садов." },
    ["6344c"] = { common = "Да, мне нужен курьер, который доставит посылку на Тёмный Берег. Вы мне поможете?" },
    ["6361a"] = { common = "Я хочу переслать в Громовой Утёс связку шкур степных зверей. Мой коллега, Ахану, занимается кожевенным делом и найдёт им достойное применение. Не возьмёшься доставить ему шкуры? До Громового Утёса проще всего добраться на ветрокрыле. Отнеси шкуры укротителю ветрокрылов Девраку и поговори с ним насчёт доставки в Громовой Утёс." },
    ["6361c"] = { male = "Хочешь отвезти эти шкуры в Громовой Утёс? Тогда ты обратился по адресу!", female = "Хочешь отвезти эти шкуры в Громовой Утёс? Тогда ты обратилась по адресу!" },
    ["6362a"] = { common = "За небольшую плату ты можешь полететь в Громовой Утёс на ветрокрыле. Быстрее не бывает! Если тебя устраивает цена – обращайся, когда решишь отправиться в путь. Если ты везёшь эти шкуры Ахану, думаю, ты отыщешь его в оружейной Хевы, у основания башни ветрокрылов в Громовом Утёсе. Именно там ты и приземлишься!" },
    ["6362c"] = { male = "А, новая связка шкур. Я немедленно ими займусь. Спасибо, брат. Ты оказал мне большую услугу. Возьми эти монеты, чтобы покрыть дорожные расходы и потраченное время.", female = "А, новая связка шкур. Я немедленно ими займусь. Спасибо, сестра. Ты оказала мне большую услугу. Возьми эти монеты, чтобы покрыть дорожные расходы и потраченное время." },
    ["6363a"] = { male = "Я приготовил кое-какие кожаные изделия на продажу в Перекрёстке. Не отнесёшь их Джахану? Если ты уже поговорил с укротителем ветрокрылов в Перекрёстке, можешь полететь туда на виверне. Отнеси мои товары здешнему укротителю ветрокрылов Талу и поговори с ним насчёт дороги до Перекрёстка.", female = "Я приготовил кое-какие кожаные изделия на продажу в Перекрёстке. Не отнесёшь их Джахану? Если ты уже поговорила с укротителем ветрокрылов в Перекрёстке, можешь полететь туда на виверне. Отнеси мои товары здешнему укротителю ветрокрылов Талу и поговори с ним насчёт дороги до Перекрёстка." },
    ["6363c"] = { male = "Тебе нужно в Перекрёсток? Нет проблем. Если ты там уже побывал и поговорил с Девраком, можешь лететь на одном из моих ветрокрылов.", female = "Тебе нужно в Перекрёсток? Нет проблем. Если ты там уже побывала и поговорила с Девраком, можешь лететь на одном из моих ветрокрылов." },
    ["6364a"] = { male = "Чтобы полететь в какой-нибудь город, следует прежде побывать в нём и поговорить с укротителем ветрокрылов. В Перекрёстке ты уже побывал, поэтому за небольшую плату ветрокрыл может отнести тебя туда. Обращайся, когда решишь отправиться в путь. Оказавшись в Перекрёстке, отнеси кожаные вещи Джахану Соколиному Крылу.", female = "Чтобы полететь в какой-нибудь город, следует прежде побывать в нём и поговорить с укротителем ветрокрылов. В Перекрёстке ты уже побывала, поэтому за небольшую плату ветрокрыл может отнести тебя туда. Обращайся, когда решишь отправиться в путь. Оказавшись в Перекрёстке, отнеси кожаные вещи Джахану Соколиному Крылу." },
    ["6364c"] = { common = "Ахану прислал мне готовые изделия? Очень хорошо. В Перекрёсток забредает много охотников и искателей приключений, и дела у меня идут неплохо. Спасибо за помощь. Я у тебя в долгу." },
    ["6365a"] = { common = "Я хочу послать своей подруге несколько видов превосходных мясных продуктов. Её зовут Гришка, она хозяйка таверны в Оргриммаре. Поможешь мне доставить мясо? До Оргриммара проще всего добраться на ветрокрыле. Отнеси мясные продукты Девраку, укротителю ветрокрылов, и поговори с ним насчёт доставки в Оргриммар." },
    ["6365c"] = { common = "Тебе нужно доставить мясо в Оргриммар? Нет проблем. За небольшую плату тебя отнесёт туда мой ветрокрыл." },
    ["6381a"] = { male = "Вот видишь, герой, хотя эта земля глубоко изранена, круговорот жизни – великая сила. Теперь мы должны внести свой вклад и помочь этой силе. Посади эти семена в самой сердцевине разрушения, на западе, в Обугленной долине. Но берегись – там, в полумёртвых землях, ещё встречаются гарпии и злобные элементали огня. Возьми эти зачарованные семена Геи и посади их в кучки плодородной почвы. Круговорот жизни должен продолжаться!", female = "Вот видишь, героиня, хотя эта земля глубоко изранена, круговорот жизни – великая сила. Теперь мы должны внести свой вклад и помочь этой силе. Посади эти семена в самой сердцевине разрушения, на западе, в Обугленной долине. Но берегись – там, в полумёртвых землях, ещё встречаются гарпии и злобные элементали огня. Возьми эти зачарованные семена Геи и посади их в кучки плодородной почвы. Круговорот жизни должен продолжаться!" },
    ["6381c"] = { male = "Это великая победа, свершённая ради здешних земель. Со временем произойдут и другие перемены: Торговая компания уберётся отсюда вместе со своими пилами и топорами, разгневанные духи огня успокоятся, а гарпии будут изгнаны с этих земель. Только тогда, в Каменном Когте настанет истинный мир. Ты совершил благое дело, герой; возьми один из этих предметов в награду за вклад в создание новой жизни.", female = "Это великая победа, свершённая ради здешних земель. Со временем произойдут и другие перемены: Торговая компания уберётся отсюда вместе со своими пилами и топорами, разгневанные духи огня успокоятся, а гарпии будут изгнаны с этих земель. Только тогда, в Каменном Когте настанет истинный мир. Ты совершила благое дело, героиня; возьми один из этих предметов в награду за вклад в создание новой жизни." },
    ["6382a"] = { male = "Твоя сила производит впечатление, герой, а интерес к охоте даёт надежды, что вскоре тебе можно будет поручить дичь покрупнее... И посерьёзнее. Орда стремится подчинить себе и в политическом и в духовном смысле бескрайние дикие просторы Ясеневого леса. Если ты готов проявить себя в непознанных ещё землях, обратись к Сенани Громосерд на заставе Расщеплённого Древа. Она находится к северу от тропы из Степей.", female = "Твоя сила производит впечатление, героиня, а интерес к охоте даёт надежды, что вскоре тебе можно будет поручить дичь покрупнее... И посерьёзнее. Орда стремится подчинить себе и в политическом и в духовном смысле бескрайние дикие просторы Ясеневого леса. Если ты готова проявить себя в непознанных ещё землях, обратись к Сенани Громосерд на заставе Расщеплённого Древа. Она находится к северу от тропы из Степей." },
    ["6382c"] = { male = "Добро пожаловать на новое пограничье. Ясеневый лес – край неограниченных возможностей, где юному герою вроде тебя выпадает шанс показать себя. Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть. Как понимаю, ты здесь для того, чтобы побольше узнать об охоте. Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать.", female = "Добро пожаловать на новое пограничье. Ясеневый лес – край неограниченных возможностей, где юному героине вроде тебя выпадает шанс показать себя. Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть. Как понимаю, ты здесь для того, чтобы побольше узнать об охоте. Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать." },
    ["6383c"] = { common = "Есть три легендарных существа, на которых можно охотиться во время большой охоты. Тем самым ты проверишь свою силу и волю к победе. Эти существа — медведь Топтыжень, саблезубый тигр Тенумбра и гиппогриф Острокоготь. Эти звери очень сильны и тебе может потребоваться помощь в охоте на них. Если ты преуспеешь — принеси мне доказательство." },
    ["6384a"] = { common = "Всего лишь за несколько монет ветрокрыл отнесёт тебя в Оргриммар. Оказавшись там, отнеси мясные продукты Зарга Гришке. Её постоялый двор располагается на аллее Силы неподалёку от небесной башни, где тебя высадит мой ветрокрыл. Поговори со мной, когда решишь отправиться в путь." },
    ["6384c"] = { common = "О, чудесно! Какое отличное мясо! Оно ведь от Зарга, да? Этот орк знает, как завоевать женское сердце… Ох, мне не терпится его приготовить. Но не слишком много! Мясо вкуснее, когда его подают редко, верно?" },
    ["6385a"] = { male = "Я написала Заргу письмо благодарности. Поможешь с доставкой? Если ты уже поговорил с укротителем ветрокрылов в Перекрёстке, то можешь полететь туда. Иди с моим письмом к Дорасу, оргриммарскому укротителю ветрокрылов, и поговори с ним насчёт полёта до Перекрёстка.", female = "Я написала Заргу письмо благодарности. Поможешь с доставкой? Если ты уже поговорила с укротителем ветрокрылов в Перекрёстке, то можешь полететь туда. Иди с моим письмом к Дорасу, оргриммарскому укротителю ветрокрылов, и поговори с ним насчёт полёта до Перекрёстка." },
    ["6385c"] = { common = "Тебе нужно доставить письмо в Перекрёсток? Да, мои виверны могут отнести тебя туда." },
    ["6386a"] = { male = "Мои виверны могут отвезти тебя в самые разные края – при условии, что ты сам там уже был и говорил с местным укротителем ветрокрылов. Тебе уже доводилось бывать в Перекрёстке, да и Деврака ты знаешь, так что, лети прямо к нему. Оказавшись в Перекрёстке, ты сможешь передать Заргху письмо Гришки. Как будешь готов, скажи.", female = "Мои виверны могут отвезти тебя в самые разные края – при условии, что ты сама там уже была и говорила с местным укротителем ветрокрылов. Тебе уже доводилось бывать в Перекрёстке, да и Деврака ты знаешь, так что, лети прямо к нему. Оказавшись в Перекрёстке, ты сможешь передать Заргху письмо Гришки. Как будешь готова, скажи." },
    ["6386c"] = { male = "Ха! Я так и знал, что ей понравится! Ничто так не нравится женщинам, как хороший сочный стейк! Спасибо. Ты оказал мне неоценимую услугу. Вот тебе плата за труды – и не удивляйся, если я приглашу тебя на свадьбу!", female = "Ха! Я так и знал, что ей понравится! Ничто так не нравится женщинам, как хороший сочный стейк! Спасибо. Ты оказала мне неоценимую услугу. Вот тебе плата за труды – и не удивляйся, если я приглашу тебя на свадьбу!" },
    ["6387a"] = { common = "Ко мне приходит немало молодых дворфов, мечтающих научиться горному делу. Что же нужнее всего шахтёру? Кирка! Я составил список учеников, которые хорошо проявили себя на занятиях и заслужили почётную кирку. Отнеси этот список Голниру Твердопалу в Стальгорн. Он подготовит для меня эти кирки. Проще всего добраться до Стальгорна на грифоне, поэтому ступай с этим списком к нашему укротителю грифонов, Торгруму Боррелсону, и поговори с ним насчёт полёта в Стальгорн." },
    ["6387c"] = { common = "Тебе нужно отвезти это в Стальгорн, да? За небольшую плату я позволю тебе оседлать одного из моих грифонов, и он отнесёт тебя прямо в город. Что скажешь?" },
    ["6388a"] = { male = "Вот почётные кирки для учеников Брока. Если ты уже бывал в Телсамаре, можешь полететь обратно на грифоне! Отнеси кирки нашему укротителю грифонов, Гриту Турдену, и поговори с ним насчёт полёта в Телсамар.", female = "Вот почётные кирки для учеников Брока. Если ты уже бывала в Телсамаре, можешь полететь обратно на грифоне! Отнеси кирки нашему укротителю грифонов, Гриту Турдену, и поговори с ним насчёт полёта в Телсамар." },
    ["6388c"] = { male = "Значит, тебе нужно в Телсамар? Не вопрос. Если ты там уже бывал и беседовал с Торгрумом Боррелсоном, можешь полететь к нему на грифоне.", female = "Значит, тебе нужно в Телсамар? Не вопрос. Если ты там уже бывала и беседовала с Торгрумом Боррелсоном, можешь полететь к нему на грифоне." },
    ["6389a"] = { common = "Вы оглядываетесь в поисках чего-нибудь подходящего, чтобы открыть бочонок, и обнаруживаете ломик, вполне подходящий для этой цели. Примериваясь, как бы снести крышку одним ударом, вы возносите молитвы, чтобы успеть унести ноги, когда насекомые вырвутся на свободу." },
    ["6389c"] = { common = "Ха-ха, превосходно! Ты справился! Дух моего отца наконец сможет покоиться с миром, а уж я-то как доволен! Спасибо тебе! Проси что хочешь, чем смогу — помогу!" },
    ["6390a"] = { common = "Вы оглядываетесь в поисках чего-нибудь подходящего, чтобы открыть бочонок, и обнаруживаете ломик, вполне подходящий для этой цели. Примериваясь, как бы снести крышку одним ударом, вы возносите молитвы, чтобы успеть унести ноги, когда насекомые вырвутся на свободу." },
    ["6390c"] = { common = "Благодарю тебя от всей души, путник. Вот, возьми эти деньги от меня. И извини, что не могу дать больше…" },
    ["6391a"] = { common = "Всего за несколько монет один из моих грифонов отнесёт тебя в Стальгорн. Там ты сможешь отдать список Брока Голниру Твердопалу. Его можно найти в гильдии горняков Тайной Горы. Она находится неподалёку от Великой Кузни Стальгорна, и именно там тебя высадит мой грифон! Когда решишь отправиться в путь, обращайся ко мне." },
    ["6391c"] = { common = "А, последний список лучших учеников Брока. Я уже подготовил почётные кирки, осталось выбить на них имена учеников..." },
    ["6392a"] = { male = "За небольшую плату грифон отнесёт тебя в Телсамар... если ты там уже бывал. Грифоны могут летать только туда, где ты успел побывать. Не упускай случая поговорить со всеми укротителями грифонов, и получишь возможность прилететь к ним. Торгрума, дрессировщика грифонов Телсамара, ты уже видел, поэтому можешь вернуться к нему. Оказавшись в Телсамаре, отнеси кирки Броку Камнекопу. Когда решишь тронуться в путь – обращайся ко мне.", female = "За небольшую плату грифон отнесёт тебя в Телсамар... если ты там уже бывала. Грифоны могут летать только туда, где ты успела побывать. Не упускай случая поговорить со всеми укротителями грифонов, и получишь возможность прилететь к ним. Торгрума, дрессировщика грифонов Телсамара, ты уже видела, поэтому можешь вернуться к нему. Оказавшись в Телсамаре, отнеси кирки Броку Камнекопу. Когда решишь тронуться в путь – обращайся ко мне." },
    ["6392c"] = { common = "А вот и кирки. Отлично! Я раздам их своим ученикам. Им, конечно, не терпится пустить их в ход в рудниках возле озера Лок Модан. Благодарю за помощь. Я у тебя в долгу. Возьми эти деньги, они должны покрыть стоимость перелёта." },
    ["6393a"] = { common = "Совет Приливов послал меня объявить войну элементалям огня здесь, в Каменном Когте. Нептулон Приливный Охотник, повелитель всех элементалей воды, лично заинтересован в том, чтобы узреть погибель всех наших огненных сородичей. Ты можешь помочь мне высоко подняться во мнении Совета путём уничтожения элементалей огня в Обугленной долине. После смерти от этих элементалей остаются огненные кристаллы. Отдай их мне, и ты получишь награду." },
    ["6393c"] = { male = "Духи воды внутри меня булькают от восторга. путник, я высоко ценю твой дар – славную победу, о которой я могу сообщить в Совет Приливов.", female = "Духи воды внутри меня булькают от восторга. путница, я высоко ценю твой дар – славную победу, о которой я могу сообщить в Совет Приливов." },
    ["6394a"] = { male = "Ты добросовестный герой. Можно доверить тебе ещё одно дело? Не так давно я ходил искать минералы в грот к северу отсюда и забыл там свою любимую кирку. А когда я вернулся за ней, то обнаружил, что там уже полно кровожадных зверей! Не можешь ли ты сходить в грот Пылающего Клинка и раздобыть мою кирку? Я её оставил в зале с водопадами. Кирка моя заговорённая – она светится в темноте, так что найти её будет нетрудно... только, боюсь, её уже стерегут!", female = "Ты добросовестная героиня. Можно доверить тебе ещё одно дело? Не так давно я ходил искать минералы в грот к северу отсюда и забыл там свою любимую кирку. А когда я вернулся за ней, то обнаружил, что там уже полно кровожадных зверей! Не можешь ли ты сходить в грот Пылающего Клинка и раздобыть мою кирку? Я её оставил в зале с водопадами. Кирка моя заговорённая – она светится в темноте, так что найти её будет нетрудно... только, боюсь, её уже стерегут!" },
    ["6394c"] = { common = "Она у тебя! Моя любимая кирка! Спасибо большое! Ну, теперь главное – дождаться, когда мои батраки управятся с рубкой леса, – и можно снова искать минералы!" },
    ["6395a"] = { common = "Моя подруга Марла Фиппс жила до чумы со своим мужем Самуэлем, но когда пришла чума, Самуэль погиб... и вступил в ряды Плети. Марла избежала чумы, но погибла от рук собственного мужа, лишившегося разума. Однако так велика была её любовь, что последним желанием её было, чтобы Самуэль был похоронен рядом с ней. Самуэль Фиппс обитает теперь у разорённого лагеря близ дороги на северо-восток от Могильника. Убей его и выполни желание Марлы: похорони Самуэля в её могиле, в первом ряду нашего кладбища." },
    ["6395c"] = { male = "Ты, совершил сегодня доброе дело. Хотя наша борьба против армии Плети всё ещё продолжается, будем надеяться, что Марла и Самуэль упокоятся с миром. В знак моей благодарности можешь взять одно из этих руководств.", female = "Ты, совершила сегодня доброе дело. Хотя наша борьба против армии Плети всё ещё продолжается, будем надеяться, что Марла и Самуэль упокоятся с миром. В знак моей благодарности можешь взять одно из этих руководств." },
    ["6401a"] = { common = "Передай Таммре Поле Ветров, тётушке Кайи, живущей в Приюте у Солнечного Камня, добрые новости – Кайя жива! Мы думали, что она погибла во время того жестокого нападения на нашу деревню. Иди по дороге на запад, и придёшь в Приют у Солнечного Камня." },
    ["6401c"] = { common = "Хвала духам, моя племянница Кайя жива! Это поистине добрая новость. Спасибо тебе!" },
    ["6402a"] = { common = "Вы с Винздором должны встретиться у ворот Штормграда. Винздор расскажет такое, что всё королевство содрогнётся! И не ходи туда один, путник. Собери целую армию! Позови своих земляков. К оружию!" },
    ["6402c"] = { common = "Прежде чем мы начнём, я прошу тебя собрать армию. Ведь нам придётся столкнуться с драконом!" },
    ["6403a"] = { common = "Вот это было приключение, друг мой. Я перед вами в огромном, неоплатном долгу. Может быть, когда всё будет кончено… Как уже доподлинно установлено вами, Леди Престор — это Ониксия, отродье Смертокрыла, сестра-близнец владыки Чёрной горы Нефариана. Слишком долго держала она наше королевство под контролем. Даже сам Верховный лорд — марионетка в её руках… Это колдовство будет разрушено. Не бойтесь, вместе мы победим! Вы готовы?" },
    ["6403c"] = { common = "Магия которая здесь содержится, должна заработать снова. Нужен всего лишь драконий глаз. Самопожертвование Винздора освободило наше королевство, но угроза со стороны Ониксии и её выродков всё ещё существует. Этот медальон будет держать мои мысли и моё тело в порядке. Он даст мне доступ к мыслям… самой Ониксии! И я узнаю её секреты. Видения зыбки и туманны, но кое-что я всё-таки узнаю!" },
    ["6421a"] = { male = "Что-то не так здесь, в Каменном Когте. Чувствуешь ли ты непокой, витающий в воздухе? К юго-востоку отсюда, в ущелье Камнепадов, есть пещера. Там кобольды отчаянно ищут редкие кристаллы резонита. Я прошу тебя принести оттуда образцы руды, чтобы я мог понять, что происходит в этой пещере. Помимо того, неплохо бы тебе обследовать глубины этой пещеры. Иди же, юный герой, мне очень важно знать, что за зло таится под этими горами.", female = "Что-то не так здесь, в Каменном Когте. Чувствуешь ли ты непокой, витающий в воздухе? К юго-востоку отсюда, в ущелье Камнепадов, есть пещера. Там кобольды отчаянно ищут редкие кристаллы резонита. Я прошу тебя принести оттуда образцы руды, чтобы я мог понять, что происходит в этой пещере. Помимо того, неплохо бы тебе обследовать глубины этой пещеры. Иди же, юная героиня, мне очень важно знать, что за зло таится под этими горами." },
    ["6421c"] = { common = "О да! Это оно – кристалл резонита несёт следы земной магии. Должно быть, кобольды, докопавшись до глубин, обнаружили там земельника. Легенда утверждает, что земельники – это существа, созданные титанами. Именно с их помощью создана земная твердь, по которой мы ступаем. Угроза велика, нельзя не обращать на неё внимания. Мор'рогал качает головой. Быть может, я сумею наложить заклинание на эти куски руды, чтобы нарушить затею кобольдов." },
    ["6441a"] = { common = "Привет! Я ехала через Ясеневый лес в Кабестан и решила остановиться здесь, в Расщеплённом Древе. Я никогда не упущу выгодного дельца, а тут оказывается, что рога сатира нынче пользуются в Кабестане большим спросом. Я тут поспрошала, и оказывается, что сатиры с Ночной поляны, Сатирнаара и Ксавиана как раз носят такие рога, что мне надо. Мне эти сатиры не по зубам... но вот вам – наверняка! Скажите, сколько возьмёте, добудьте мне рога, и я оплачу ваше потраченное время." },
    ["6441c"] = { common = "Изумительные рога! Спасибо за помощь! О, а это вам за труды..." },
    ["6442a"] = { male = "Зло рыщет по побережью, герой. Здесь покоится под волнами проклятый город Зорам, давно разрушенный и поглощённый морем. Разрушенный и почти забытый. Теперь в него непонятно почему вернулись наги. Но причина не так важна – мы должны защитить край, за который так упорно боролись. Принеси мне двадцать их голов! Загони наг назад, в глубины моря!", female = "Зло рыщет по побережью, героиня. Здесь покоится под волнами проклятый город Зорам, давно разрушенный и поглощённый морем. Разрушенный и почти забытый. Теперь в него непонятно почему вернулись наги. Но причина не так важна – мы должны защитить край, за который так упорно боролись. Принеси мне двадцать их голов! Загони наг назад, в глубины моря!" },
    ["6442c"] = { common = "Побольше бы нам таких, как ты. Спасибо за помощь." },
    ["6461a"] = { common = "Мы, тролли, тут, в Малака'джине, живём с земли, да и живём хорошо. В Каменном Когте есть на что поохотиться. Только вот повадились к нам в последнее время незваные гости... по ночам пауки на наши стоянки нападают, хотят украсть нашу добычу. Если поможешь нам поубивать этих злобных тварей, мы, тролли Малака'джина, будем перед тобой в долгу. Тут, в Каменном Когте, пауки повсюду – ступай на север, и увидишь, о чём я толкую." },
    ["6461c"] = { common = "О, вот и славненько! Ну хорошо, авось сегодня к нам на ужин меньше незваных гостей налезет. Тысяча благодарностей. Мы у тебя в долгу навечно." },
    ["6462a"] = { male = "Мои сородичи шли сюда со священными тролльскими оберегами, но фурболги Колючего Меха напали на них и перебили прежде, чем они успели добраться до Зорам'гара! Эти подлые фурболги! Я горюю по убитым братьям и сёстрам – но мы ещё встретимся в загробной жизни. Однако, их тролльские обереги в нашем мире весьма ценятся. Меня бесит, что ими завладели фурболги! Ты должен вернуть эти обереги! Они находятся в сундуках в Крепости Колючего Меха, в пещере на окраине Деревни Колючего Меха, к северу от Астранаара.", female = "Мои сородичи шли сюда со священными тролльскими оберегами, но фурболги Колючего Меха напали на них и перебили прежде, чем они успели добраться до Зорам'гара! Эти подлые фурболги! Я горюю по убитым братьям и сёстрам – но мы ещё встретимся в загробной жизни. Однако, их тролльские обереги в нашем мире весьма ценятся. Меня бесит, что ими завладели фурболги! Ты должна вернуть эти обереги! Они находятся в сундуках в Крепости Колючего Меха, в пещере на окраине Деревни Колючего Меха, к северу от Астранаара." },
    ["6462c"] = { male = "Ты их нашёл! О, благодарю тебя! Ты представить себе не можешь, что ты сделал для меня. Тролль без оберега что орк без боевых шрамов... Пустое место, а не тролль.", female = "Ты их нашла! О, благодарю тебя! Ты представить себе не можешь, что ты сделала для меня. Тролль без оберега что орк без боевых шрамов... Пустое место, а не тролль." },
    ["6481a"] = { male = "Благодаря тебе, герой, мы узнали, что этой земле грозит великая опасность. Резонитовая ёмкость, найденная тобою в пещере, служит вместилищем для спящего земельника по имени Гоггерок. Я изменил своей шаманской силой принесённые тобой кристаллы. Возьми кристалл резинита и разбей резонитовую ёмкость, где спит земельник. Сразу после пробуждения Гоггерок будет ослаблен... Убей его!", female = "Благодаря тебе, героиня, мы узнали, что этой земле грозит великая опасность. Резонитовая ёмкость, найденная тобою в пещере, служит вместилищем для спящего земельника по имени Гоггерок. Я изменил своей шаманской силой принесённые тобой кристаллы. Возьми кристалл резинита и разбей резонитовую ёмкость, где спит земельник. Сразу после пробуждения Гоггерок будет ослаблен... Убей его!" },
    ["6481c"] = { male = "Это хорошие новости, герой! Я опасался того, что земельник может сделать с Калимдором. Уничтожение Гоггерока было задачей, достойной истинного героя. Но тебе удалось справиться с этим, и теперь и Каменный Коготь, и Калимдор перед тобой в долгу, благородный герой. Прими это как заслуженную и достойную награду.", female = "Это хорошие новости, героиня! Я опасался того, что земельник может сделать с Калимдором. Уничтожение Гоггерока было задачей, достойной истинного героя. Но тебе удалось справиться с этим, и теперь и Каменный Коготь, и Калимдор перед тобой в долгу, благородный героиня. Прими это как заслуженную и достойную награду." },
    ["6482a"] = { male = "А? Ты кто? путник? Ты не фурболг. Они прокляты! Они подумали, что я медведь, и схватили меня, а теперь морят голодом! Я погибаю... Помоги мне сбежать, затем поговори с моей сестрой Ями на заставе Расщеплённого Древа к востоку отсюда. путник! Мне надо сбежать!", female = "А? Ты кто? путница? Ты не фурболг. Они прокляты! Они подумали, что я медведь, и схватили меня, а теперь морят голодом! Я погибаю... Помоги мне сбежать, затем поговори с моей сестрой Ями на заставе Расщеплённого Древа к востоку отсюда. путница! Мне надо сбежать!" },
    ["6482c"] = { male = "Ты нашёл моего брата! Его схватили фурболги Колючего Меха? Какая страшная весть! Хотя многие фурболги существа благородные, эти – извращённые твари. Спасибо за спасение брата. Страшно подумать, как они обходились с бедняжкой Руулом! Наверняка после таких испытаний он будет долго спать...", female = "Ты нашла моего брата! Его схватили фурболги Колючего Меха? Какая страшная весть! Хотя многие фурболги существа благородные, эти – извращённые твари. Спасибо за спасение брата. Страшно подумать, как они обходились с бедняжкой Руулом! Наверняка после таких испытаний он будет долго спать..." },
    ["6501a"] = { common = "Фрагмент расколотого амулета — это всё, что я могу вам предложить. Вам придётся найти ещё одного дракона, который согласится помочь вам в изготовлении нового ключа. Как только вы добудете этот ключ, вам нужно будет отправиться в Драконьи топи в Пылевых топях. Там вы и найдёте её логово, путник. Где найти других драконов, готовых помочь? К сожалению, я не знаю… Говорят, что такие существуют. Некоторые из них могут даже жить среди нас в обличии людей, гномов или эльфов, например. Желаю вам удачи в поиске." },
    ["6503a"] = { common = "Мы получили донесение, что вестницы Ясеневого леса не так давно покинули Аванпост Среброкрылых и теперь шныряют в лесу у наших границ. Нам не надо, чтобы они разнюхивали что да как с нашей обороной! Проникни в лес к югу отсюда и к востоку от альянсовского Аванпоста Среброкрылых. Найди и перебей лазутчиц, а потом возвращайся." },
    ["6503c"] = { common = "Очень хорошо. Твоё охотничье мастерство впечатляет... Потеря лазутчиц малость притупит нюх Альянса, а ежели им разведданных не хватит, то вряд ли они нападут." },
    ["6504a"] = { common = "Этот резак я только что получила из Кабестана и как раз возвращалась на лесозаготовки Песни Войны, на своё рабочее место. Мне дали инструкцию к резаку, но по дороге назад у меня её вырвало из рук порывом ветра. Все страницы разлетелись, и осталась у меня одна обложка. Где теперь эти страницы носит, одним предкам ведомо... Но как я резаком-то без них пользоваться буду? Не найдёшь ли их для меня?" },
    ["6504c"] = { common = "Не сильна я в чтении... Но теперь я могу вернуться к работе! Спасибо!" },
    ["6521a"] = { common = "Повелеваю тебе убить посланника Малкина – я не позволю ему выполнить волю Короля-лича. Он пишет, что ждёт встречи где-то поблизости от Курганов Иглошкурых. Его присутствие там многое объясняет. Сила тамошних иглогривов многократно увеличилась, и среди них отмечаются признаки чумы. Очевидно, они заключили с Малкином какое-то соглашение. Найди и убей Малкина. Возвращайся ко мне, когда испонишь моё повеление." },
    ["6521c"] = { male = "Прекрасно. Ты хорошо поработал, герой. Теперь, после смерти Малкина, мы по крайней мере можем быть уверенными, что продвижение Плети будет остановлено. В благодарность за преданность прими этот дар. Пока нам неизвестно, насколько прочные позиции заняла Плеть в Лабиринтах Иглошкурых, однако не сомневаюсь, что скоро нам удастся разузнать их замыслы.", female = "Прекрасно. Ты хорошо поработала, героиня. Теперь, после смерти Малкина, мы по крайней мере можем быть уверенными, что продвижение Плети будет остановлено. В благодарность за преданность прими этот дар. Пока нам неизвестно, насколько прочные позиции заняла Плеть в Лабиринтах Иглошкурых, однако не сомневаюсь, что скоро нам удастся разузнать их замыслы." },
    ["6522a"] = { common = "Госпожа моя, Наше предложение вам прекрасно известно. Для вас это отличная возможность получить безграничную власть над Степью и окрестными землями. От вас нам требуется лишь небольшое содействие – вам нужно всего лишь дать нам свободу действий в этих землях. Мы убедительно просим вас рассмотреть это предложение и обсудить его с нами. За нами великая сила, и мы с охотой поделимся ею с теми, кто достаточно мудр, чтобы примкнуть к нам. Я буду ждать вас у Курганов Иглошкурых. С наилучшими пожеланиями, Посланник Малкин." },
    ["6522c"] = { common = "Я узнаю знак на этом свитке. Говоришь, нашёл это у старухи, правящей в Лабиринтах Иглошкурых? Любопытно. Похоже, Плети мало одного континента. Посол Малкин – тот, кто написал письмо, – один из служителей Плети. Он был человеческим послом в Лордероне, прежде чем... всё переменилось. Если Плеть в самом деле пытается закрепиться в Калимдоре, нам пора что-то предпринять." },
    ["6523a"] = { common = "Спасибо большое за спасение! Мы должны уходить побыстрее, прежде чем они обнаружат, что я на свободе. Я прошу сопроводить меня до Лагеря Апарахе. Оттуда я уже знаю, куда идти. Мой отец, Макаба Плоское Копыто, наверное, уже отчаялся узнать, где я." },
    ["6523c"] = { male = "Кайя жива! путник, я благодарю тебя за её спасение!", female = "Кайя жива! путница, я благодарю тебя за её спасение!" },
    ["6541a"] = { male = "Ты когда-нибудь бывал в Ясеневом лесу, на севере? Орда недавно организовала заставу на Зорамском взморье, и нам всегда нужны новобранцы для обороны новых границ. Если тебе это по сердцу, найди Кадрака в северных Степях, в сторожевой башне. Он руководит кампанией в Ясеневом лесу и может дать тебе поручение.", female = "Ты когда-нибудь бывала в Ясеневом лесу, на севере? Орда недавно организовала заставу на Зорамском взморье, и нам всегда нужны новобранцы для обороны новых границ. Если тебе это по сердцу, найди Кадрака в северных Степях, в сторожевой башне. Он руководит кампанией в Ясеневом лесу и может дать тебе поручение." },
    ["6541c"] = { common = "Ясеневый лес – разделённый войной край, но наши недавние усилия увенчались успехом. Мы основали заставу не только на Зорамском взморье, но ещё прямо к северу отсюда построили заставу Расщеплённого Древа." },
    ["6542a"] = { male = "Ты когда-нибудь бывал в Ясеневом лесу, на севере? Орда недавно организовала заставу на Зорамском взморье, и нам всегда нужны новобранцы для обороны новых границ. Если тебе это по сердцу, найди Кадрака в северных Степях, в сторожевой башне. Он руководит кампанией в Ясеневом лесу и может дать тебе поручение.", female = "Ты когда-нибудь бывала в Ясеневом лесу, на севере? Орда недавно организовала заставу на Зорамском взморье, и нам всегда нужны новобранцы для обороны новых границ. Если тебе это по сердцу, найди Кадрака в северных Степях, в сторожевой башне. Он руководит кампанией в Ясеневом лесу и может дать тебе поручение." },
    ["6542c"] = { common = "Ясеневый лес – разделённый войной край, но наши недавние усилия увенчались успехом. Мы основали не только заставу на Зорамском взморье, но и ещё прямо к северу отсюда построили заставу Расщеплённого Древа." },
    ["6543a"] = { common = "Недавно я отправил в Ясеневый лес нескольких разведчиков. Мне нужен гонец, чтобы доставить им приказы и вернуться с отчётом об их наблюдениях. Первый твой пункт – форт Зорам'гар, что на западном побережье на Зорамском взморье. Там ты найдёшь первого гонца. Так же тебе придётся заглянуть на заставу Расщеплённого Древа, что на севере и к востоку по дороге близ Азшары. Там найдёшь разведчика и сопровождающего. Передай каждому указания и забери у них новые донесения." },
    ["6543c"] = { common = "Вижу, на тебя можно положиться. Эти новые сведения чрезвычайно важны для осуществления планов по расширению нашего присутствия в Ясеневом лесу. Теперь мы можем разработать следующий шаг." },
    ["6544a"] = { male = "Эй! герой! Иди-ка сюда! Мы с ребятами хотим напасть на Аванпост Среброкрылых на западе. Наша цель – их командир, Дариэль Лунное Пламя. Разведчики говорят, что форт здорово защищён, там полно часовых и воинов. Славная будет драка! Хочешь помочь нам, и разделить нашу славу? Если пойдёшь с нами, то когда победим, сможешь доложить о наших успехах моему начальнику, Эртогу Лютоклыку. Ты найдёшь его в Расщеплённом Дереве. Что скажешь? Пойдёшь с нами?", female = "Эй! героиня! Иди-ка сюда! Мы с ребятами хотим напасть на Аванпост Среброкрылых на западе. Наша цель – их командир, Дариэль Лунное Пламя. Разведчики говорят, что форт здорово защищён, там полно часовых и воинов. Славная будет драка! Хочешь помочь нам, и разделить нашу славу? Если пойдёшь с нами, то когда победим, сможешь доложить о наших успехах моему начальнику, Эртогу Лютоклыку. Ты найдёшь его в Расщеплённом Дереве. Что скажешь? Пойдёшь с нами?" },
    ["6544c"] = { male = "Значит, Тореку дельце удалось! Хорошая работа. Ночные эльфы – достойные враги. Худоваты на вид, но сильные да яростные! Видать, драка была красивая, посмотреть бы... Надеюсь, парочку шрамов-то ты заработал?", female = "Значит, Тореку дельце удалось! Хорошая работа. Ночные эльфы – достойные враги. Худоваты на вид, но сильные да яростные! Видать, драка была красивая, посмотреть бы... Надеюсь, парочку шрамов-то ты заработала?" },
    ["6548a"] = { common = "Клан Зловещего Тотэма напал на мою деревню и убил почти всех жителей. Я сразил столько нападавших, сколько мог, но едва спас собственную жизнь. Всё, чего я желаю – это чтобы как можно больше этих негодяев умерло. Ты найдёшь их к западу отсюда." },
    ["6548c"] = { common = "Я благодарю тебя... но я никогда не забуду того, что клан Зловещего Тотэма сделал с моей деревней." },
    ["6561a"] = { common = "Силы оставили меня. Мне необходима твоя помощь! В давние времена на этом месте был храм Элуны. К несчастью, он был разрушен, когда порча Древнего бога просочилась из-под земли и осквернила священный лунный колодец. Аку'май, слуга Древнего бога, поднялся из глубин. Сектанты Сумеречного Молота объединились с нагами в борьбе за эти земли. Сектанты, ведомые Келрисом, приносят Аку'май невинные жертвы. Убей Келриса и принеси его голову Башане в Громовой Утёс." },
    ["6561c"] = { male = "Келрису много раз удавалось ускользнуть от Серебряного Рассвета. Его считали мёртвым или пропавшим без вести. Положив конец его власти, ты спас жизнь многих. Слава Матери-Земле! Нет прощенья тем, кто приносит невинные жертвы Древнему Богу! Ты совершил великий подвиг. Келрис был порождением зла, он стремился повергнуть наш мир в хаос, поклоняясь Старым Богам. Благодарю тебя.", female = "Келрису много раз удавалось ускользнуть от Серебряного Рассвета. Его считали мёртвым или пропавшим без вести. Положив конец его власти, ты спасла жизнь многих. Слава Матери-Земле! Нет прощенья тем, кто приносит невинные жертвы Древнему Богу! Ты совершила великий подвиг. Келрис был порождением зла, он стремился повергнуть наш мир в хаос, поклоняясь Старым Богам. Благодарю тебя." },
    ["6562a"] = { male = "Дже'неу Санкри нужна помощь. Он в форте Зорам'гар в Ясеневом лесу. Этот лес ночных эльфов находится к северу от Когтистых гор. Ты можешь добраться до него через Утёс Ветрорезов или идя на север через Степи. Зорамское взморье лежит далеко на западе от леса. Будь осторожен. Там обитают такие силы, от которых тёплого приёма не жди.", female = "Дже'неу Санкри нужна помощь. Он в форте Зорам'гар в Ясеневом лесу. Этот лес ночных эльфов находится к северу от Когтистых гор. Ты можешь добраться до него через Утёс Ветрорезов или идя на север через Степи. Зорамское взморье лежит далеко на западе от леса. Будь осторожна. Там обитают такие силы, от которых тёплого приёма не жди." },
    ["6562c"] = { common = "Тебя послал Цунаман? Великолепно. Тогда нам есть что обсудить." },
    ["6563a"] = { common = "В начале туннелей Непроглядной Пучины по стенам пещер можно найти большие сапфировые друзы. Недавно было замечено, что эти кристаллы собирают наги. Пока не станет ясно, зачем им это, сдаётся мне, что надо наг этой возможности лишить. В кристаллах этих содержится великая сила стихий, и если их применить не как должно, то они могут стать мощным чародейским ингредиентом. Ты мне не поможешь? Непроглядная Пучина находится на Зорамском взморье к северу от нашей заставы." },
    ["6563c"] = { common = "Хорошая работа. Это те самые кристаллы, о которых я говорил. Как интригующе... Я чувствую в них силу. К ним тянутся духи воды. Для чего бы наги ни собирались их использовать... Ладно, хорошо, что они больше не в их руках." },
    ["6564a"] = { common = "На смятом обрывке бумаги кое-как нацарапано : \"Да, вели всем жрицам приносить мне эти кристаллы. В них обитают могучие духи элементалей воды, и они весьма помогут нашим аквамантам в призывании духов. Овладев силой, заключённой в кристаллах, мы сумеем умилостивить Аку'май. И однажды настанет день, когда мы накопим достаточно сил, чтобы вернуть Аку'май к нам, и мир вернётся в величайшую свою эпоху! Эпоху власти Древних богов!\"" },
    ["6564c"] = { common = "Это и правда интересно. Я рад, что ты принёс мне эту записку. Теперь мы знаем, как зовут причину наших бед... Лоргус Джетт!" },
    ["6565a"] = { male = "Мы не можем допустить, чтобы этот последователь Сумеречного Молота выполнил свой план. Клан Сумеречного Молота не понимает духов Природы. Они верят в Древних богов – богов хаоса и разрушения, побеждённых давным-давно. Нельзя дать этому Лоргусу добиться своего! Ты должен остановить его. Мне самому этого не сделать – я слишком слаб. Ступай в Непроглядную Пучину, найди и убей его! А потом возвращайся в Зорам'гар.", female = "Мы не можем допустить, чтобы этот последователь Сумеречного Молота выполнил свой план. Клан Сумеречного Молота не понимает духов Природы. Они верят в Древних богов – богов хаоса и разрушения, побеждённых давным-давно. Нельзя дать этому Лоргусу добиться своего! Ты должна остановить его. Мне самому этого не сделать – я слишком слаб. Ступай в Непроглядную Пучину, найди и убей его! А потом возвращайся в Зорам'гар." },
    ["6565c"] = { common = "Прекрасно!!! Хвала тебе. Может, мы и не окончательно разобрались с Сумеречным Молотом, но по крайней мере один их план по возвращению в могуществе своём Древних богов мы нарушили. Кто знает, какие ещё замыслы них на уме, но пока мы можем вздохнуть свободно." },
    ["6566a"] = { common = "Рад видеть тебя снова, путник. Ветер принёс вести из Восточных королевств. Садись и слушай." },
    ["6566c"] = { common = "Готов ли ты взять на себя эту задачу?" },
    ["6567a"] = { common = "Рексар, один из самых преданных моих защитников, нашёл путь в логово дракона. Разыщи его. Он скитается по Пустошам, что раскинулись между Когтистыми горами и Фераласом. Он уже знает, что ты придёшь." },
    ["6567c"] = { common = "Существует только один способ проникнуть в логово дракона, странник. Видишь ли, только сильнейшим из чёрных драконов разрешается входить в логово праматери! Они должны пройти немало испытаний, прежде чем получат доступ к ключу, который должен быть зачарован самим генералом Драккисатом. Поскольку ты не из рода чёрных драконов, тебе придётся столкнуться с определёнными трудностями, чтобы проникнуть туда." },
    ["6568a"] = { common = "Путник, а что ты знаешь об иллюзиях? Ведь только иллюзия поможет тебе обмануть чёрных драконов и добыть то, что ты ищешь. Я знаю, кто смог бы тебе помочь. Она не раз помогала нам и поможет тебе, если сочтёт твои цели достойными. Отправляйся в Западные Чумные земли и разыщи Миранду Колдунью. Когда-то она была мастером иллюзий Альянса Лордерона, но её изгнали. Вот, отнеси ей это послание, она всё поймёт." },
    ["6568c"] = { common = "Ну и как он? Рексар, я имею в виду. Письмо между прочим пустое. Так что на словах тебе придётся передать… Да ладно тебе, а если бы тебя захватили в плен? И письмо бы прочли? Ладно, забудь! Миранда поможет тебе, странник." },
    ["6569a"] = { common = "Значит, странник возжелал войти в Чёрное Племя? Создать необходимую тебе иллюзию — пара пустяков. Куда труднее собрать компоненты, необходимые для наложения этих чар. Раз Вождь поручил тебе такую миссию, Миранде остаётся повиноваться. Отправляйся в верхнюю часть крепости на пике Чёрной горы и убей столько чёрных драконидов, чтобы набить заплечные мешки их глазами. Когда наберёшь достаточно, возвращайся к Миранде." },
    ["6569c"] = { common = "Позволь Миранде взглянуть, странник. А да, это сработает хорошо. С этими реагентами, Миранда сделает тебе медальон, создающий иллюзию, которая обманет драконьего стража ворот." },
    ["6570a"] = { common = "Благодаря этому медальону в пределах логова Огнебора ты будешь сохранять нужный облик. Огнебор — старый дракон, древний привратник Нефариана. На него возложена обязанность испытывать тех драконов, которые должны войти в элитную стражу Ониксии. Отправляйся в Драконьи топи в Пылевых топях и войди в его логово. Оказавшись внутри, надень амулет, и следуй за своей судьбой!" },
    ["6571a"] = { common = "Нам на лесозаготовках Песни Войны страшно не хватает кое-чего! У Пиксель на заставе Расщеплённого Древа наш груз лезвий для пил. За ящиком топоров от управляющего пристанью Подгребая придётся сгонять в Пиратскую бухту. А получить груз масла и верёвок будет ещё труднее. Верёвку стянули фурболги Колючего Меха и Гиблой Чащи, а сатиры перехватили партию масла, и теперь изводят его на свои гадкие ритуалы на Ночной поляне, Сатирнааре и Ксавиане! Ты мне поможешь?" },
    ["6571c"] = { male = "Замечательно! Ты избавил меня от больших забот! Но не думай, что я буду неблагодарен!", female = "Замечательно! Ты избавила меня от больших забот! Но не думай, что я буду неблагодарен!" },
    ["6601c"] = { common = "Этот драконий разговор, путник — не более чем сотрясание воздуха. Высокопарное угрожающее поведение — это то, что от них следует ожидать." },
    ["6602a"] = { common = "Как насчёт того, чтобы нанести визит генералу? На этот раз — никаких иллюзий и прикрытий. Церемония?.. Весьма изящное определение для той кровавой бойни, которой так любят услаждать себя чёрные драконы. Всё, чего недостаёт этому амулету — кровь генерала Драккисата. Весьма примитивная защита. Я расскажу тебе, как разрешить эту маленькую проблему. Отправляйся к пику Чёрной горы и прикончи Драккисата. Принеси мне его кровь, и я активирую ключ от Логова Ониксии." },
    ["6602c"] = { common = "Победа, которая запомнится на много лет, путник. Амулет Пламени дракона откроет путь к Логову Ониксии. Собери своих союзников и принеси победу Орде!" },
    ["6603a"] = { common = "В Зимних ключах какая-то заваруха! Я некоторое время жила в тех диких местах и в этих вещах разбираюсь… Я всегда с гордостью это говорю. По мне, так время, что я прожила в холмах, прямо-таки золотое времечко. Помогает развивать быстроту рефлексов, сохранять холодную голову и держать ухо востро… Чтобы так разбираться в ситуации в диких краях, как я, надо быть зрелым и иметь хорошие мозги. Ладно, о чём, бишь, я? А, да, заваруха. Найди Донову Снегонору у горячих источников, и она расскажет тебе побольше." },
    ["6603c"] = { common = "О, привет! Значит, Мегги рассказала тебе о моих трудностях?" },
    ["6604a"] = { common = "Вы заметили заброшенный лагерь к югу отсюда? Такое впечатление, что дикосовухи сошли с ума и уничтожили всё, до чего смогли дотянуться! Я слыхал, что один из выживших после этой атаки сейчас приходит в себя в деревне Звездопада, к западу отсюда. Мне очень любопытно, что же там произошло… а вам нет?" },
    ["6604c"] = { common = "Слушаю, чем могу быть полезен?" },
    ["6605a"] = { common = "Я только что вернулся из Осквернённого леса, путник. По пути я останавливался на Заставе Отравленной Крови, и познакомился с одной очень странной дамочкой… Казалось, она зациклилась на одной вещи и, полагаю, я мог бы сказать вам, на чём именно, но думаю, лучше она сама вам это объяснит. Если вам стало интересно, отправляйтесь на Заставу Отравленной Крови, в западной части Осквернённого леса и поищите Винну Хеззард. Кто знает, может быть, ей нужна ваша помощь…" },
    ["6605c"] = { common = "О, герой. Вижу, ещё есть надежда. Ты здесь, чтобы мне помочь?" },
    ["6606a"] = { common = "Немного удачи никому не помешает, так ведь? Иногда даже крошечного преимущества достаточно, чтобы обратить всё в свою пользу… Недавно мне довелось познакомиться с одной довольно эксцентричной особой. Она сделала мне особый талисман на удачу… не бесплатно, разумеется. Но, поверь уж мне, он того стоит! Может, тебе тоже такой нужен? Найди знахарку Мау'ари в Круговзоре. Свой я тебе не отдам!" },
    ["6606c"] = { common = "Тебя Харло прислал? Как я догадываюсь, тебе нужна моя помощь?" },
    ["6607a"] = { male = "Не скажу, что мне так уж нравится рыбачить. Последний раз мне этим приходилось заниматься двадцать, а то и тридцать лет назад. Люди занимаются своим делом по разным причинам. Я не говорю, что ты должен убить на рыбалку тридцать лет, или выловить всю рыбу в этом море, чтобы стать хорошим рыбаком. Я думаю, тебе просто надо собраться и решиться несколько часов просиживать зад на берегу, ничего не делая. Вот что я тебе скажу, поймай мне несколько редких рыб из этого списка, и я взамен научу тебя кой-чему.", female = "Не скажу, что мне так уж нравится рыбачить. Последний раз мне этим приходилось заниматься двадцать, а то и тридцать лет назад. Люди занимаются своим делом по разным причинам. Я не говорю, что ты должна убить на рыбалку тридцать лет, или выловить всю рыбу в этом море, чтобы стать хорошим рыбаком. Я думаю, тебе просто надо собраться и решиться несколько часов просиживать зад на берегу, ничего не делая. Вот что я тебе скажу, поймай мне несколько редких рыб из этого списка, и я взамен научу тебя кой-чему." },
    ["6607c"] = { common = "Вот это, я понимаю, улов! Поди сюда, дай-ка я тебе покажу пару трюков." },
    ["6608a"] = { common = "Лумак больше не может тебя учить. Нечему больше учить тебя. Найди друга Лумака, Ната Пэгла. Он человек, не еда! Нат друг Лумака! Он тебя научит ловить рыбу лучше. Ната можно найти в Пылевых топях, к югу от Тераморо... как его там. Он, наверное, удит рыбу. Иди!" },
    ["6608c"] = { male = "Так ты что, друг Лумака? Рыбная ловля? Чего я о ней не знаю, того и знать не стоит!", female = "Так ты что, подруга Лумака? Рыбная ловля? Чего я о ней не знаю, того и знать не стоит!" },
    ["6609a"] = { male = "Я же дворф, парень, это ж без очков видать! Не моё дело рыбу ловить! Ты только глянь на меня! Я ж, считай, каменный! С меня больше нечего взять – всё тебе отдал! Я тебя научил всему, что умел, балда! Ещё не понял? А, да ладно. Есть у меня старый дружок в Калимдоре, который сможет тебе помочь. Его зовут Нат Пэгл, он хороший парень. Ищи его на островах к югу от Терамора. Ну, топай!", female = "Я же дворф, подруга, это ж без очков видать! Не моё дело рыбу ловить! Ты только глянь на меня! Я ж, считай, каменный! С меня больше нечего взять – всё тебе отдал! Я тебя научил всему, что умел, балда! Ещё не поняла? А, да ладно. Есть у меня старый дружок в Калимдоре, который сможет тебе помочь. Его зовут Нат Пэгл, он хороший парень. Ищи его на островах к югу от Терамора. Ну, топай!" },
    ["6609c"] = { common = "У меня на островке всегда найдётся место для гостей... Насколько помню..." },
    ["6610a"] = { male = "Тебе случалось слышать о мидиях с сюрпризом? Конечно же нет! Это мой последний кулинарный шедевр. Ах, от одной мысли слюнки текут. К сожалению, у меня кончились все припасы, и я не могу его сделать! Хочешь сделку? Принеси мне нужные продукты, а я поучу тебя готовить, и даже дам парочку омлетов с мидиями! Согласен?? Вот, что мне нужно:", female = "Тебе случалось слышать о мидиях с сюрпризом? Конечно же нет! Это мой последний кулинарный шедевр. Ах, от одной мысли слюнки текут. К сожалению, у меня кончились все припасы, и я не могу его сделать! Хочешь сделку? Принеси мне нужные продукты, а я поучу тебя готовить, и даже дам парочку омлетов с мидиями! Согласна?? Вот, что мне нужно:" },
    ["6610c"] = { common = "Вот ты полакомишься. Смотри и учись! *Дирг начинает готовить мидии с сюрпризом.*" },
    ["6611a"] = { male = "Как может Замджа научить тебя всему на свете? Ты знаешь все кулинарные заговоры Замджи и требуешь новых! Замджа ничем помочь не может. Пусть толстый герой пойдёт в Прибамбасск. Найдёшь там мелкого гоблина по имени Могиль – вот он тебе и поможет, обжора. Когда станешь великим поваром – вернёшься, научишь Замджу всему, что знаешь, а? Ну, ступай, ступай.", female = "Как может Замджа научить тебя всему на свете? Ты знаешь все кулинарные заговоры Замджи и требуешь новых! Замджа ничем помочь не может. Пусть толстая героиня пойдёт в Прибамбасск. Найдёшь там мелкого гоблина по имени Могиль – вот он тебе и поможет, обжора. Когда станешь великим поваром – вернёшься, научишь Замджу всему, что знаешь, а? Ну, ступай, ступай." },
    ["6611c"] = { common = "*Дирг выплёвывает ошмётки кожаной сандалии.* Ох! Фу! Тьфу! *Дирг долго откашливается.* В чём дело? Ты разве не знаешь, что в коже очень много белка и чрезвычайно мало углеводов? Ничего, узнаешь ещё!" },
    ["6612a"] = { male = "Судя по твоему половнику, ты знаешь, чего хочешь. Да вот научить мне тебя нечему. Но тебе свезло, я знаю одного парня. Он гоблин, и считается первым поваром Калимдора. Да, приятель, придётся тебе податься до Калимдора. Иди-ка в Прибамбасск и сыщи Могиля Быстроруба. Он тебя прямиком и направит.", female = "Судя по твоему половнику, ты знаешь, чего хочешь. Да вот научить мне тебя нечему. Но тебе свезло, я знаю одного парня. Он гоблин, и считается первым поваром Калимдора. Да, подруга, придётся тебе податься до Калимдора. Иди-ка в Прибамбасск и сыщи Могиля Быстроруба. Он тебя прямиком и направит." },
    ["6612c"] = { male = "*Дирг выплёвывает кожу.* Тьфу... *Дирг громко кашляет.* Ну? Известно ли тебе, что в коже чрезвычайно много белка и мало углеводов, герой?", female = "*Дирг выплёвывает кожу.* Тьфу... *Дирг громко кашляет.* Ну? Известно ли тебе, что в коже чрезвычайно много белка и мало углеводов, героиня?" },
    ["6621a"] = { male = "К юго-востоку от Астранаара живёт ещё одно племя фурболгов, Гиблая Чаща. Они не так многочисленны, как Колючий Мех, но их ярость в будущем может представлять угрозу. Продемонстрировав им силу, мы сможем эту угрозу ликвидировать. Бери этот штандарт, иди в деревлю Гиблой Чащи и поставь его на их тотэмном кургане. Они попытаются уничтожить штандарт, но ты держись, пока не появится их вождь, Мургут. Он захочет отстоять честь племени. Принеси мне тотэм, что будет на нём. Собирай друзей. С этим делом герой-одиночка не справится.", female = "К юго-востоку от Астранаара живёт ещё одно племя фурболгов, Гиблая Чаща. Они не так многочисленны, как Колючий Мех, но их ярость в будущем может представлять угрозу. Продемонстрировав им силу, мы сможем эту угрозу ликвидировать. Бери этот штандарт, иди в деревлю Гиблой Чащи и поставь его на их тотэмном кургане. Они попытаются уничтожить штандарт, но ты держись, пока не появится их вождь, Мургут. Он захочет отстоять честь племени. Принеси мне тотэм, что будет на нём. Собирай друзей. С этим делом героиня-одиночка не справится." },
    ["6621c"] = { male = "Хорошая работа. Бросив вызов Гиблой Чаще и победив их вождя, ты крепко вдолбил в их головы: С Ордой шутки плохи. Теперь это племя долго не осмелится досаждать нам.", female = "Хорошая работа. Бросив вызов Гиблой Чаще и победив их вождя, ты крепко вдолбила в их головы: С Ордой шутки плохи. Теперь это племя долго не осмелится досаждать нам." },
    ["6622a"] = { common = "Добрый день, доктор. Вы должны будете пройти тест на оказание срочной медицинской помощи. Если тест будет пройдён успешно, вы вольетесь в ряды наших лучших травматологов. А теперь внимание! Раненые, находящиеся в критическом состоянии, должны получить помощь первыми. После критически раненых следует перевязать тяжёлых пациентов. Потом можно заняться и обычными ранеными. Для прохождения теста вам нужно спасти пятнадцать пациентов. Если шесть пациентов умрут, так и не дождавшись перевязки, испытание будет провалено. Для этого теста вам будут предоставлены специальные бинты. Удачи, доктор." },
    ["6622c"] = { male = "Доктор путник, добро пожаловать в ряды травматологов Орды.", female = "Доктор путница, добро пожаловать в ряды травматологов Орды." },
    ["6623a"] = { male = "Доктор путник, я так понимаю? Рад новой встрече. У меня для тебя замечательные новости. Доктор Грегори Виктор, главный травматолог Орды, предлагает тебе поработать у него в Павшем Молоте. Такой шанс выпадает раз в жизни! Лично я отдал бы всё на свете за возможность поработать под руководством великого Грегори Виктора! Не упусти свою удачу!", female = "Доктор путница, я так понимаю? Рад новой встрече. У меня для тебя замечательные новости. Доктор Грегори Виктор, главный травматолог Орды, предлагает тебе поработать у него в Павшем Молоте. Такой шанс выпадает раз в жизни! Лично я отдал бы всё на свете за возможность поработать под руководством великого Грегори Виктора! Не упусти свою удачу!" },
    ["6623c"] = { common = "Отлично. Надевайте халат, работа не ждёт!" },
    ["6624a"] = { common = "Здравствуйте, доктор. Вам сегодня предстоит пройти испытание на очерёдность оказания помощи раненым. Если вы успешно пройдёте этот экзамен, вы будете приняты в ряды престижного сообщества травматологов Альянса. А теперь слушайте внимательно! Сначала необходимо оказать помощь тяжелораненным. После – тем, у кого ранения средней тяжести. Последними идут легкораненные. Вы должны оказать помощь пятнадцать пациентам. чтобы пройти этот экзамен. Если шесть ваших пациентов после оказания им помощи скончаются, экзамен будет считаться проваленным. Удачи, доктор." },
    ["6624c"] = { male = "Доктор путник, Добро пожаловать в ряды травматологов Альянса!", female = "Доктор путница, Добро пожаловать в ряды травматологов Альянса!" },
    ["6625a"] = { male = "Полагаю, вы доктор путник. Приятно познакомиться. У меня есть для вас замечательная новость! Густаф Ванхорцен, главный врач-травматолог Альянса, делает вам личное предложение приехать к нему в Терамор. Такая возможность выпадает раз в жизни! Я бы всё отдала за возможность учиться у великого доктора Густафа Ванхорцена! Не упустите возможности, доктор!", female = "Полагаю, вы доктор путница. Приятно познакомиться. У меня есть для вас замечательная новость! Густаф Ванхорцен, главный врач-травматолог Альянса, делает вам личное предложение приехать к нему в Терамор. Такая возможность выпадает раз в жизни! Я бы всё отдала за возможность учиться у великого доктора Густафа Ванхорцена! Не упустите возможности, доктор!" },
    ["6625c"] = { common = "Чудесно. Мойте руки, и сразу начнём!" },
    ["6626a"] = { common = "Отрёкшиеся не стремятся превратить смертных в себе подобных... насколько мне известно. Однако этот посланник, видимо, охотно превращает в нежить всех желающих. Я начинаю думать, что на самом деле он работает на Плеть. Однако сейчас меня больше беспокоит не он, а его последователи, число которых всё возрастает. Я вижу,что каждые день из тьмы выползают всё новые и новые его приспешники, пресмыкающиеся перед ним в жажде власти. Я слишком слаба, чтобы справиться с ними. Помоги мне." },
    ["6626c"] = { male = "Спасибо. Ты оказал мне неоценимую помощь! Я продолжу наблюдать за посланником и иглогривами. Если же ты ищешь более серьёзных противников, собери соратников и отправляйся к пещере, напоминающей кабанью утробу. Не сомневаюсь, внутри скрываются создания, с которыми будет интересно помериться силами столь великому воителю.", female = "Спасибо. Ты оказала мне неоценимую помощь! Я продолжу наблюдать за посланником и иглогривами. Если же ты ищешь более серьёзных противников, собери соратников и отправляйся к пещере, напоминающей кабанью утробу. Не сомневаюсь, внутри скрываются создания, с которыми будет интересно помериться силами столь великой воительнице." },
    ["6627a"] = { male = "Ты принёс мне книгу, и я должен задать тебе вопрос. Ты готов? Спешить нам некуда, так что не торопись. Можешь ответить мне в любое время.", female = "Ты принесла мне книгу, и я должен задать тебе вопрос. Ты готова? Спешить нам некуда, так что не торопись. Можешь ответить мне в любое время." },
    ["6627c"] = { male = "Отличная работа, герой. Ты изучил книгу как следует и прошёл ещё одно наше испытание.", female = "Отличная работа, героиня. Ты изучила книгу как следует и прошла ещё одно наше испытание." },
    ["6628a"] = { male = "Вот мы и встретились снова. Ты проявил недюжинные способности при прохождении моих испытаний, и теперь мне осталось только задать тебе последний вопрос. Когда будешь готов, подойди и поговори со мной, но перед этим как следует подготовься. Спешить нам некуда.", female = "Вот мы и встретились снова. Ты проявила недюжинные способности при прохождении моих испытаний, и теперь мне осталось только задать тебе последний вопрос. Когда будешь готова, подойди и поговори со мной, но перед этим как следует подготовься. Спешить нам некуда." },
    ["6628c"] = { common = "Отличная работа. Я сомневался, что у тебя хватит терпения изучить этот текст, но ты дал верный ответ." },
    ["6629a"] = { common = "Что ж, с негодяями из клана Зловещего Тотэма тебе удалось расправиться отлично. Но Грундиг Тёмное Облако и его личная банда громил куда хуже. Именно он возглавлял то жестокое нападение на мою деревню. Если осмелишься, то найдёшь его на Заставе Зловещего Тотэма чуть дальше по дороге на запад. Убей его, и я буду вечно тебе признателен." },
    ["6629c"] = { male = "Грундиг Тёмное Облако мёртв! путник, за это деяние я буду вечно признателен тебе!", female = "Грундиг Тёмное Облако мёртв! путница, за это деяние я буду вечно признателен тебе!" },
    ["6641a"] = { common = "Ворша Хлестунья... это омерзительная гидра, что рыщет в морях... Она нападает на нашу заставу почём зря, уничтожая всё на своём пути. Но я готов драться. Я готов уничтожить гидру и положить конец её нападениям на Зорам'гар. Наги почитают эту гадкую тварь и поддерживают в её честь пламя на жаровне, что находится на острове у побережья. Думаю, если мы её загасим, то разъярённая Ворша вылезет из моря. Нам понадобится помощь, так что приведи крепких друзей." },
    ["6641c"] = { common = "С тех пор, как я сюда прибыл, я пережил много нападений наг. Мне прямо легче на душе становится от мысли, что Ворша больше не будет разгуливать где ей вздумается. Мы в большом долгу перед тобой." },
    ["6661a"] = { common = "Эй ты, стой, да? Ррры!.. Зарррработать хочешь? У нас тут большая проблема с крысами и не хватает умелых рук. Что ты там болтаешь? Всё, что от тебя требуется – взять эту флейту крысолова и сыграть подходящую мелодию. Они пойдут за тобой хоть на край света! Но это лишнее – ты просто поймай пяток и принеси, они нужны нам живыми. Ррррр..." },
    ["6661c"] = { common = "Ха, хорошо сделанная работёнка, молодец! Моему братцу они нужны свеженькими, чтобы приготовить из них котлеты." },
    ["6662a"] = { male = "Мой братишка Нипси занимается производством котлет из подземных крыс на том конце подземки. Надо, чтобы ты доставил этот ящик с крысами к нему, пока они не протухли. Так что давай, двигай! Ты ведь ездил раньше на поезде, да? Это очень просто. Заходи, когда поезд прибудет – и наслаждайся поездкой. Главное, не высовывай руки-ноги, не то на всю жисть калекой останешься.", female = "Мой братишка Нипси занимается производством котлет из подземных крыс на том конце подземки. Надо, чтобы ты доставила этот ящик с крысами к нему, пока они не протухли. Так что давай, двигай! Ты ведь ездила раньше на поезде, да? Это очень просто. Заходи, когда поезд прибудет – и наслаждайся поездкой. Главное, не высовывай руки-ноги, не то на всю жисть калекой останешься." },
    ["6662c"] = { common = "Бедняга Монти. После того, что случилось в Гномрегане, он сам на себя не похож. Этот парень океана в жизни не видал, а туда же – в пираты метит. Нипси вздыхает. Ну, по крайней мере, он обеспечивает непрерывные поставки этих дерганых тварей." },
    ["6681a"] = { male = "Чёрный Ворон очень заинтересовался тобой, юный вор. Мы наблюдали. Тебе не хватает ловкости, но это преходяще. Если ты хочешь стать учеником мастера Чёрного Ворона и членом Лиги убийц, стоит только принести печать Чёрного Ворона (приложенную к этому письму) в поместье Чёрный Ворон. Первым заданием будет найти его среди холмов Хилсбрада и тем самым доказать свою ловкость. С уважением, Фахрад.", female = "Чёрный Ворон очень заинтересовался тобой, юная воришка. Мы наблюдали. Тебе не хватает ловкости, но это преходяще. Если ты хочешь стать ученицей мастера Чёрного Ворона и членом Лиги убийц, стоит только принести печать Чёрного Ворона (приложенную к этому письму) в поместье Чёрный Ворон. Первым заданием будет найти его среди холмов Хилсбрада и тем самым доказать свою ловкость. С уважением, Фахрад." },
    ["6681c"] = { male = "Отлично, юный вор. Вид у тебя немного побитый, но ничего особенного. Тебя ждёт долгий путь – долгий и исполненный наград. Ты готов принять свою судьбу, войдя в число мастеров Чёрного Ворона? Поговори со стражами снаружи дома. Они дадут тебе первое задание.", female = "Отлично, юная воришка. Вид у тебя немного побитый, но ничего особенного. Тебя ждёт долгий путь – долгий и исполненный наград. Ты готова принять свою судьбу, войдя в число мастеров Чёрного Ворона? Поговори со стражами снаружи дома. Они дадут тебе первое задание." },
    ["6721a"] = { male = "Привет тебе, юный охотник. Ты кажешься мне достаточно опытным, чтобы научиться обращаться с животным и обрести верного друга. Тебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника.", female = "Привет тебе, юная охотница. Ты кажешься мне достаточно опытной, чтобы научиться обращаться с животным и обрести верного друга. Тебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника." },
    ["6721c"] = { common = "Да, пора." },
    ["6722a"] = { male = "Привет тебе, юный охотник. Ты кажешься мне достаточно опытным, чтобы научиться обращаться с животным и обрести верного друга. Тебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника.", female = "Привет тебе, юная охотница. Ты кажешься мне достаточно опытной, чтобы научиться обращаться с животным и обрести верного друга. Тебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника." },
    ["6761a"] = { common = "Я поручил своему заместителю, Матренгилу Медвежьей Лапе, разобраться с призывом о помощи из Лунной поляны. Так что по этому поводу говори с ним — НЕ со мной! И позволь мне дать тебе один дружеский совет. Это я вывел нас всех из тьмы — я, а вовсе не Круг Кенария Лунной поляны, — когда наша раса потеряла всё. Тельдрассил даёт нам новую жизнь! Они наверняка попытаются внушить тебе совсем другое, но только глупец поверит их пропаганде! Ты же, вроде, не из таких. Или я ошибаюсь?" },
    ["6761c"] = { common = "Да, герой, спасибо, что пришёл. Прошу прощения за это недоразумение… но взаимное недоверие между здешним верховным друидом и хранителем Ремулом из Лунной поляны прямо-таки дрожит в воздухе. Каждый подозревает другого в кляузничестве, а ведь проблема странной порчи Тельдрассила всё ещё не решена. Но взаимное недоверие от этого не стихает. Как бы то ни было, у нас есть долг перед Кругом Кенария… даже если его предводители не ладят друг с другом." },
    ["6762a"] = { common = "Мажордом хранителя Лунной поляны Ремула — Рабин Сатурна — ищет помощи. Нужно обследовать обширные пустоши к западу от Танариса… и ещё дальше, к западу от Ун'Горо. Найди его в Ночной гавани, главном поселении Лунной поляны. Поскольку твои труды будут на благо всём нам, советую тебе вести себя осторожно. Между Дарнассом и Лунной поляной трения… и как бы они не переросли со временем в нечто большее." },
    ["6762c"] = { common = "Я Рабин Сатурна. От лица хранителя Ремула и всех обитателей сего священного места приветствую тебя. Я ценю твою заинтересованность и горячую готовность помочь Кругу Кенария. Также мне ведомо о недовольстве, с которым верховный друид Дарнаса отозвался о твоей помощи нам. Будь уверен, что всё, что делается, — делается во благо, и что тебя не коснутся необдуманные выпады, целью коих ты можешь стать. Здесь ты среди друзей, путник." },
    ["6844a"] = { common = "Здесь полно работы, но мне кажется, главное — отнести это в Круг, на анализ. Поверь мне, дела здесь не переводятся. Если внутри этого хитина находится дневник, то Круг сможет заглянуть в прошлое! Отнеси этот дневник архивариусу Круга в Ночную Гавань. Его зовут Умбер, он настоящий гений! Да, тронутый, не без того, но всё равно гений! Умбер находил манускрипты в куда более плохом состоянии. Если эти записи можно восстановить, он это сделает." },
    ["6844c"] = { common = "Ага, что тут у нас? Книга, слегка пошарпанная… Лайо послал тебя ко мне из Силитуса? Я слышал про этих жуков только несколько слушков, довольно ужасных, как я тебе замечу… Так что я с удовольствием изучу сию книгу, чтобы узнать из неё, как нам избавиться от этой напасти." },
    ["6845a"] = { common = "Короче, свяжись со мной как можно скорее… если, конечно, хочешь знать, что там внутри. Как только я это узнаю, с удовольствием поделюсь с тобой информацией — разумеется, если там действительно окажется книга. А пока я свяжусь с самой-большой-медведицей этого медвежьего угла, то есть, Рабином. Он, несомненно, пожелает узнать, что за кашу ты тут заварил. Никогда не заставляй мать-медведицу ждать, путник… ну, если только тебе неймётся искупаться в мёду. Такое бывает, уж поверь мне." },
    ["6845c"] = { common = "А, путник. Как мило, что ты согласился меня навестить. Рад видеть тебя в добром здравии. Я желаю через тебя выразить глубокую благодарность Кругу Кенария за их помощь, оказанную нам. Тут много секретов ожидают пытливых умов исследователей, и тайны ждут, чтобы их раскрыли. Возьми это, как аванс за твои будущие достижения. Благодарю тебя, благородный герой." },
    ["6921a"] = { common = "Эти негодяи из Сумеречного Молота пробрались в Руины святилища Луны Непроглядной Пучины. Их присутствие приведёт лишь к тому, что Стихии озлобятся на нас. Если это так и оставить, то они захватят эти места навсегда. Ступай в Непроглядную Пучину и найди в руинах глубинный камень. Он должен быть где-то поблизости в воде. В нём находится глубинный сердечник – устройство, которое при надлежащем считывании излагает историю всей деятельности Стихий. Если я его получу, мы со Служителями Земли, возможно, сумеем как-нибудь остановить их!" },
    ["6921c"] = { male = "Это именно то, что мне было нужно! Глубинный сердечник – неиссякаемая кладезь информации, которую мы сможем оттуда извлечь. Что бы ни затевал Сумеречный Молот – и уж поверь мне, ничего хорошего – мы с моими товарищами сумеем это выяснить. Ты сегодня хорошо потрудился, и Служители Земли весьма благодарны тебе за помощь. Ты и всей Орде помог, и имеешь право гордиться собой.", female = "Это именно то, что мне было нужно! Глубинный сердечник – неиссякаемая кладезь информации, которую мы сможем оттуда извлечь. Что бы ни затевал Сумеречный Молот – и уж поверь мне, ничего хорошего – мы с моими товарищами сумеем это выяснить. Ты сегодня хорошо потрудилась, и Служители Земли весьма благодарны тебе за помощь. Ты и всей Орде помогла, и имеешь право гордиться собой." },
    ["6922a"] = { common = "Сражённый элементаль воды оставил после себя странную сферу. Вы предполагаете, что этот предмет каким-то образом подпитывал тварь энергией. Внутри сферы плещется грязная на вид жидкость. Сама сфера вроде бы не поддаётся никаким физическим воздействиям. Если кто и сможет понять, что это за штука, то это Дже'неу Санкри из Служителей Земли. Он находится в форте Орды Зорам'гар в Ясеневом лесу." },
    ["6922c"] = { male = "Ого... вот это находка. Говоришь, ты добыл это из барона Акваниса в Чёрных Глубинах? Барон Акванис давно уже считается осквернённой силой Стихии, а этот шар даст понять, что именно повергло его в скверну. Хотя я не удивлюсь, если это окажется клан Сумеречного Молота, зато мы узнаем, как они сумели это сделать. Хорошо, что ты принёс эту штуку мне. Прошу – прими это вместе с горячей благодарностью Служителей Земли.", female = "Ого... вот это находка. Говоришь, ты добыла это из барона Акваниса в Чёрных Глубинах? Барон Акванис давно уже считается осквернённой силой Стихии, а этот шар даст понять, что именно повергло его в скверну. Хотя я не удивлюсь, если это окажется клан Сумеречного Молота, зато мы узнаем, как они сумели это сделать. Хорошо, что ты принесла эту штуку мне. Прошу – прими это вместе с горячей благодарностью Служителей Земли." },
    ["6961a"] = { male = "Весёлого Зимнего Покрова, дружок! Не забудь поздороваться с Дедушкой Зимой! Все, кто хорошо себя вёл в этом году, получат замечательные подарки в день Зимнего Покрова! Предупреждать его нужно заранее, иначе подарка не дождёшься. И сам не забудь купить подарки для тех, кто хорошо себя вёл весь год. У нас богатейший выбор подарков на любой вкус! \"Свежие фрукты от нашего села да к вашему столу – вкусная и здоровая пища от Пастбищ Дымного Леса!\"", female = "Весёлого Зимнего Покрова, дружок! Не забудь поздороваться с Дедушкой Зимой! Все, кто хорошо себя вёл в этом году, получат замечательные подарки в день Зимнего Покрова! Предупреждать его нужно заранее, иначе подарка не дождёшься. И сама не забудь купить подарки для тех, кто хорошо себя вёл весь год. У нас богатейший выбор подарков на любой вкус! \"Свежие фрукты от нашего села да к вашему столу – вкусная и здоровая пища от Пастбищ Дымного Леса!\"" },
    ["6961c"] = { common = "Хо-хо-хо! Я – Дедушка Зима, явился к вам благодаря добросердечию работников Пастбищ Дымного Леса! \"Свежие фрукты от нашего села да к вашему столу, вкусная и здоровая пища из Пастбищ Дымного Леса!\" Желаю вам чудесного Зимнего Покрова! Все, кто хорошо себя вёл в этом году, получат лакомства от Пастбищ Дымного Леса в качестве подарка на праздник Зимнего Покрова. Уррра!" },
    ["6962a"] = { male = "Эй, мальчуган, не окажешь ли услугу Дедушке Зиме? Дедушка Зима весь день провёл на ногах и сам не откажется угоститься. Немного пряников и ледяного молока, чтобы запить, будут очень кстати. Ты ведь любишь дедушку? Принесёшь мне угощение?", female = "Эй, девчушка, не окажешь ли услугу Дедушке Зиме? Дедушка Зима весь день провёл на ногах и сам не откажется угоститься. Немного пряников и ледяного молока, чтобы запить, будут очень кстати. Ты ведь любишь дедушку? Принесёшь мне угощение?" },
    ["6962c"] = { male = "Ну, спасибо! Угодил ты Дедушке Зиме! Доброго тебе праздника Зимнего Покрова. А вот тебе кое-что... ну, за труды, понимаешь.", female = "Ну, спасибо! Угодила ты Дедушке Зиме! Доброго тебе праздника Зимнего Покрова. А вот тебе кое-что... ну, за труды, понимаешь." },
    ["6964a"] = { common = "Подарки, гости, угощение... чушь собачья! Эти гоблины искажают саму суть праздника Зимнего Покрова. Это время возрождения – земля спит под покровом снега, которым её укутал Дедушка Зима, и это вовсе НЕ ТОТ косноязычный дурак в красном полушубке! Ежели вам интересно узнать, что такое на самом деле этот праздник, поспрошайте Сагорна Гривастого Странника. Уверен, он будет очень удивлён, что хоть кому-то история интереснее подарков." },
    ["6964c"] = { common = "Праздник Зимнего Покрова, говоришь? Увы, в прежние времена для нас, тауренов, он был куда важнее. А теперь, похоже, другие используют древние легенды, чтобы продать побольше сладостей и подарков. Неудивительно, что Фарманда это так огорчает. Он и остальные таурены держатся за наше прошлое, как за боевое знамя. Я лично считаю, что немного веселья никогда не помешает, но о происхождении праздника забывать нельзя." },
    ["6981a"] = { common = "Блестящий осколок ярко-зелёный, без примесей, но под поверхностью можно видеть что-то похожее на клубы дыма. Оторвать взгляд от этих узоров в глубине невозможно, но в то же время вы осознаете какое-то беспокойство. Пожалуй, стоит поискать в Кабестане кого-нибудь, кто может знать больше об этом странном осколке." },
    ["6981c"] = { common = "О... мне никогда не приходилось видеть ничего подобного..." },
    ["6983a"] = { common = "С-существо, которое зовут \"Оме-мерзительный Гри-инч\", похитило все наши лакомства! Т-только ос-стор-р-рожно! Это он с-сделал из меня с-снеговика! Ва-ва-вам понадобится помощь! Я в-видел, как он шляется тут в-в-вместе с другими йети. Он нав-верняка где-то п-поблизости! Отыщите мой груз, отвезите его в Оргриммар, П-пастбищам Дымного Леса, и п-п-передайте им, что м-меня надо разморозить!" },
    ["6983c"] = { common = "Вы нашли груз! Вы спасли наш праздник! Бедный Сакс! Конечно же, мы немедленно отправим спасателей и придумаем, как его разморозить. Надеюсь, он успеет прийти в себя к празднику... Хотя, конечно же, потом ему придётся отработать то время, которое он прогулял! Но в любом случае, если бы не вы, всё пошло бы прахом!" },
    ["7003a"] = { common = "Нет, если я собираюсь здесь остаться, мне решительно необходимо что-то сделать с великанами! Они губят весь бизнес. Я взял за основу разновидность гномского уменьшающего луча, но внёс в конструкцию превосходные гоблинские усовершенствования! Дабы самому избежать различных неудобств – например, смерти, – я поручаю его испытание вам. Испробуйте его на любых великанах, каких найдёте в Фераласе. После уменьшения вы обнаружите на месте великана остатки миниатюризации – принесите их мне!" },
    ["7003c"] = { common = "Превосхитительнейше! Я не только благодарен тебе за великанов, но и очень рад видеть, что ты вроде как в целости и добром здравии. Хотя мой Ультрасжиматель всегда был абсолютно безопасен, так ведь? Спасибо за твои старания. Теперь все гоблины будут относиться к тебе, как к другу. Вот, прими это в знак моей признательности!" },
    ["7021a"] = { male = "Весёлого Зимнего Покрова, дружок! Не забудь поздороваться с Дедушкой Зимой – он сейчас в Оргриммаре! Все, кто хорошо себя вёл в этом году, получат замечательные подарки в день Зимнего Покрова! Предупреждать его нужно заранее, иначе подарка не дождёшься. И сам не забудь купить подарки для тех, кто хорошо себя вёл весь год. У нас богатейший выбор подарков на любой вкус! От нашего села да к вашему столу – вкусная и здоровая пища от Пастбищ Дымного Леса!", female = "Весёлого Зимнего Покрова, дружок! Не забудь поздороваться с Дедушкой Зимой – он сейчас в Оргриммаре! Все, кто хорошо себя вёл в этом году, получат замечательные подарки в день Зимнего Покрова! Предупреждать его нужно заранее, иначе подарка не дождёшься. И сама не забудь купить подарки для тех, кто хорошо себя вёл весь год. У нас богатейший выбор подарков на любой вкус! От нашего села да к вашему столу – вкусная и здоровая пища от Пастбищ Дымного Леса!" },
    ["7021c"] = { common = "Хо-хо-хо! Я – Дедушка Зима, явился к вам благодаря добросердечию работников Пастбищ Дымного Леса! \"Свежие фрукты от нашего села да к вашему столу, вкусная и здоровая пища из Пастбищ Дымного Леса!\" Желаю вам чудесного Зимнего Покрова! Все, кто хорошо себя вёл в этом году, получат лакомства от Пастбищ Дымного Леса в качестве подарка на праздник Зимнего Покрова. Уррра!" },
    ["7024a"] = { male = "Весёлого Зимнего Покрова, дружок! Не забудь поздороваться с Дедушкой Зимой! Все, кто хорошо себя вёл в этом году, получат замечательные подарки в день Зимнего Покрова! Предупреждать его нужно заранее, иначе подарка не дождёшься. И сам не забудь купить подарки для тех, кто хорошо себя вёл весь год. У нас богатейший выбор подарков на любой вкус! Свежие фрукты от нашего села да к вашему столу – вкусная и здоровая пища от Пастбищ Дымного Леса!", female = "Весёлого Зимнего Покрова, дружок! Не забудь поздороваться с Дедушкой Зимой! Все, кто хорошо себя вёл в этом году, получат замечательные подарки в день Зимнего Покрова! Предупреждать его нужно заранее, иначе подарка не дождёшься. И сама не забудь купить подарки для тех, кто хорошо себя вёл весь год. У нас богатейший выбор подарков на любой вкус! Свежие фрукты от нашего села да к вашему столу – вкусная и здоровая пища от Пастбищ Дымного Леса!" },
    ["7024c"] = { common = "Хо-хо-хо! Я Дедушка Зима, и я явился к вам благодаря добросердечию Пастбищ Дымного Леса! \"Свежие фрукты от нашего села да к вашему столу, вкусная и здоровая пища из Пастбищ Дымного Леса!\" Желаю вам чудесного Зимнего Покрова! Все, кто хорошо себя вёл в этом году, получат лакомства от Пастбищ Дымного Леса в качестве подарка на праздник Зимнего Покрова. Ур-р-ра!" },
    ["7025a"] = { male = "Эй, не окажешь ли услугу Дедушке Зиме, хм, мальчуган? Нет смысла говорить о себе в третьем лице, но Дедушка Зима весь день был на ногах и хотел бы и сам полакомиться угощением. Немного пряников и ледяного молока, чтобы запить, – и будет довольно. Ты ведь любишь дедушку и принесёшь мне угощение?", female = "Эй, не окажешь ли услугу Дедушке Зиме, хм, девчушка? Нет смысла говорить о себе в третьем лице, но Дедушка Зима весь день был на ногах и хотел бы и сам полакомиться угощением. Немного пряников и ледяного молока, чтобы запить, – и будет довольно. Ты ведь любишь дедушку и принесёшь мне угощение?" },
    ["7025c"] = { male = "Ну, ты и угодил Дедушке Зиме! Доброго тебе праздника Зимнего Покрова. А вот тебе кое-что... ну, за труды, ты понимаешь.", female = "Ну, ты и угодила Дедушке Зиме! Доброго тебе праздника Зимнего Покрова. А вот тебе кое-что... ну, за труды, ты понимаешь." },
    ["7028a"] = { male = "На западе, в глубинах Мародона, раскинулись хрустальные пещеры Террамока... Это очень древнее место, герой. А я хочу наложить лапу на часть тамошних древностей. За огромными дверями скрыты реликвии древних богов. Если ты отважишься бросить вызов злу, таящемуся в Мародоне, я щедро тебе заплачу. Собери там терадрические хрестальные орнаменты и принеси их мне. Как только я доберусь до этих орнаментов, я смогу их... изучить. Слишком долго дремали скрытые силы...", female = "На западе, в глубинах Мародона, раскинулись хрустальные пещеры Террамока... Это очень древнее место, героиня. А я хочу наложить лапу на часть тамошних древностей. За огромными дверями скрыты реликвии древних богов. Если ты отважишься бросить вызов злу, таящемуся в Мародоне, я щедро тебе заплачу. Собери там терадрические хрестальные орнаменты и принеси их мне. Как только я доберусь до этих орнаментов, я смогу их... изучить. Слишком долго дремали скрытые силы..." },
    ["7028c"] = { common = "Ха-ха-ха! Я так и знала, что ты вернёшься. Ива бормочет себе под нос. ... Как легко убедить. … пойдёт на что угодно за сходную цену. Хе-хе-хе..." },
    ["7029a"] = { common = "В пещерах Мародона поселился сатир по имени Злоязыкий и оскверняет всё, до чего может дотянуться. Из-за него умирают растения. Возьми этот фиал, и наполни его из оранжевого пруда рядом с пещерами. Внутри фиала есть особое покрытие, которое превратит яд в лекарство. Отыщи в оранжевых пещерах гнусь-лозу и полей её целебной жидкостью. Растение очистится от порчи, но всё равно останется в воле Злоязыкого. Он может обратить его против тебя." },
    ["7029c"] = { male = "Спасибо, что принёс мне фиал. Я исследую остатки жидкости. Хотя впереди много работы, зло, совершённое Злоязыким в Мародоне, хотя бы отчасти исправлено. Прими это в знак моей благодарности.", female = "Спасибо, что принесла мне фиал. Я исследую остатки жидкости. Хотя впереди много работы, зло, совершённое Злоязыким в Мародоне, хотя бы отчасти исправлено. Прими это в знак моей благодарности." },
    ["7041a"] = { common = "В пещерах Мародона поселился сатир по имени Злоязыкий и оскверняет всё кругом. Из-за него там больше не растут цветы. Возьми этот фиал, и наполни его из оранжевого пруда рядом с пещерами. Внутри фиала есть особое покрытие, которое превратит яд в лекарство. Отыщи в оранжевых пещерах гнусь-лозу и полей её целебной жидкостью. Растение очистится от порчи, но всё равно останется в воле Злоязыкого. Он может обратить его против тебя." },
    ["7041c"] = { male = "Спасибо, что принёс мне фиал. Я исследую остатки жидкости. Хотя впереди много работы, зло, совершённое Злоязыким в Мародоне, хотя бы отчасти исправлено. Прими это в знак моей благодарности.", female = "Спасибо, что принесла мне фиал. Я исследую остатки жидкости. Хотя впереди много работы, зло, совершённое Злоязыким в Мародоне, хотя бы отчасти исправлено. Прими это в знак моей благодарности." },
    ["7043a"] = { common = "С-существо, которое зовут \"Оме-мерзительный Гри-инч\", похитило все наши лакомства! Т-только ос-стор-р-рожно! Это он с-сделал из меня с-снеговика! Ва-ва-вам понадобится помощь! Я в-видел, как он шляется тут в-в-вместе с другими йети. Он нав-верняка где-то п-поблизости! Отыщите мой груз, отвезите его в Стальгорн, П-пастбищам Дымного леса, и п-п-передайте им, что м-меня надо разморозить!" },
    ["7043c"] = { common = "Вы нашли груз! Вы спасли наш праздник! Бедный Сакс! Конечно же, мы немедленно отправим спасателей и придумаем, как его разморозить. Надеюсь, он успеет прийти в себя к празднику... Хотя, конечно же, потом ему придётся отработать то время, которое он прогулял! Но в любом случае, если бы не вы, всё пошло бы прахом!" },
    ["7044a"] = { common = "Повелитель сатиров, лорд Злоязыкий, сеет ужас по всем ходам-переходам этой пещеры, отравляя разум и чувства всех несчастных, оказавшихся внутри. Он живёт за лиловыми кристаллами. Кроме того, Злоязыкий создал живой символ собственного падения, Ноксиона, который живёт за оранжевыми кристаллами. Эти двое похитили скипетр моего брата. Келебрас, мой брат... бессмысленно бродит по пещерам, снедаемый порчей. Помоги ему! Найди обломки скипетра и попробуй поговорить с моим братом." },
    ["7044c"] = { common = "Теперь, когда мой жезл собран воедино, надеюсь, вскоре мы сумеем избавить Мародон от скверны." },
    ["7046a"] = { common = "Некогда скипетр был моей опорой и надёжей. Его сила позволяла мне стремительно перемещаться по этим пещерам. Я надеялся умиротворить дух моего дяди... Теперь я передам это бремя тебе. Для того же, чтобы слить воедино обе половины скипетра, мне понадобится твоя помощь. Иди за мной и пока я буду призывать энергию, чтобы воссоединить жезл с бриллиантом, выполняй мои указания. Воссоздадим же совместными усилиями скипетр Келебраса!" },
    ["7046c"] = { common = "Прошу тебя, возьми этот скипетр и знай, что заключённая в нём сила должна служить лишь добру. Не останавливайся на достигнутом, иди дальше, вглубь пещер. Надеюсь, ты сумеешь отыскать останки моего дяди. Тебя подстерегает множество опасностей. Если понадобится, можешь смело обращаться ко мне." },
    ["7062a"] = { common = "Подарки, гости, угощение... чушь собачья! Эти гоблины искажают самую суть праздника Зимнего Покрова. Это время возрождения – земля спит под покровом снега, которым её укутал Дедушка Зима, и это вовсе НЕ ТОТ косноязычный дурак в красном полушубке! Ежели вам интересно узнать, что такое на самом деле этот праздник, поспрошайте историка Карника из лиги Исследователей. Уверен, он будет очень удивлён, что кому-то история интереснее подарков." },
    ["7062c"] = { common = "Говорите, праздник Зимнего Покрова? Увы, в прежние времена для нас, дворфов, он имел гораздо более весомое значение. А теперь, похоже, другие используют легенду о Дедушке Зиме, чтобы продать побольше сладостей и подарков. Неудивительно, что Голли так огорчает эта перемена. Он и остальные дворфы держатся за наше прошлое, как за боевое знамя. Я лично считаю, что небольшой праздник никогда не помешает, но о его происхождении забывать нельзя." },
    ["7067a"] = { male = "Хотя меня изгнали из племени как еретика, меня поддерживает вера. Только ей я и живу. Впрочем, мне не исполнить предначертанное без посторонней помощи... Причём помощи чужака, а не кентавра. Кто-то должен войти в священные залы Мародона – гробницы, которую защищает мой народ, допуская внутрь лишь избранных. Если ты согласен помочь мне, стоит только кивнуть. Я отдам тебе свиток с инструкциями. прочти его и обдумай мои слова.", female = "Хотя меня изгнали из племени как еретика, меня поддерживает вера. Только ей я и живу. Впрочем, мне не исполнить предначертанное без посторонней помощи... Причём помощи чужака, а не кентавра. Кто-то должен войти в священные залы Мародона – гробницы, которую защищает мой народ, допуская внутрь лишь избранных. Если ты согласна помочь мне, стоит только кивнуть. Я отдам тебе свиток с инструкциями. прочти его и обдумай мои слова." },
    ["7067c"] = { common = "Вот он, вот амулет! Теперь мне предстоит долгое дело объединения племён. Спасибо. Вот, возьми это за услуги. Надеюсь, мы ещё встретимся в совсем другой обстановке." },
    ["7068a"] = { common = "Сильна магия в святом месте для кентавров, священном Мародоне. Племена кентавров Пустошей готовы биться за эти места до последней капли крови, но куда им! Мы своё возьмём! Ступай в ихний Мародон и найди там каменных тварей из осколков сумрака. Ты дашь Утель'наю лиловые кристаллы, а уж он тебя не обидит! Места там опасные, так что бери с собой друзей." },
    ["7068c"] = { common = "Ага, вот они. Вот, возьми один из этих предметов и ступай своей дорогой... у меня ещё много дел." },
    ["7070a"] = { common = "Я недавно начал испытания различных кристаллов и их магических свойств. Леди Праудмур позволила мне обратиться к путешественникам в Пустошах с просьбой отыскать там некое место, называющееся Мародон. В руинах храма поселились огромные каменные элементали, состоящие из лиловых кристаллов, которые я нарёк осколками сумрака. Если ты решишь направиться в ту сторону и захватишь по пути несколько кристаллов, я буду очень признателен. Более того, я могу сделать тебе из них украшение." },
    ["7070c"] = { common = "Отличные кристаллы. На самом деле некоторые искатели приключений уже принесли мне образцы этих кристаллов, и из них я сделал эти украшение... Можешь выбрать любое из них. И ещё раз спасибо. Чем больше образцов, тем лучше." },
    ["7201a"] = { common = "У меня есть работа для тех, кто не боится заглянуть в глубины, путник. Клан Чёрного Железа научился создавать чрезвычайно мощных големов. Исходя из отчётов, присланных нашими шпионами, дворфы используют уникальные источники энергии, чтобы придать своим големам невероятную разрушительную силу. Подумать только, что мы могли бы сделать с нашими поганищами, заполучи мы сущность Стихий, которую они используют… Можешь перевернуть город вверх дном, но я должна получить эту сущность. Без неё можешь не возвращаться! Награда будет сопоставима с затраченными усилиями." },
    ["7201c"] = { common = "Прекрасно! Я пошлю их с курьером в Подгород, сейчас же! Тебе же — даю твою оплату. А теперь, убирайся!" },
    ["7321a"] = { common = "Кто сказал, что нежить не понимает в кулинарии? Взять, к примеру, мой заветный рецепт нежного черепашьего супа. Да я знаю народ, что из мёртвых бы восстал, только бы скушать тарелочку! Хе-хе... Кстати, в последнее время мне ни тарелочки приготовить не удалось. Обычно я сам ходил на озеро Лордамер ловить хрустогрызов – у, грязные тварюги – но не могу сейчас бросить работу. Если ты добудешь мне немного черепашьего мяса и приправ, я научу тебя варить такой суп!" },
    ["7321c"] = { common = "Мой нежный черепаший супчик согреет тебя холодной ночью... Если, конечно, ты ещё помнишь, что такое холод." },
    ["7383a"] = { common = "Но не всё было ладно с Тельдрассилом. Олений Шлем долго лелеял надежду вырастить новое Древо жизни и даже тщательно спланировал это мероприятие. Но была одна небольшая проблема, с которой можно связать большинство бед Тельдрассила. Однако, пока я об этом говорить не буду. Тебе нужно посетить последний лунный колодец, к северо-западу от Поляны Оракула. Под ветвями Древа-оракула находится первый и самый могучий из наших колодцев. Набери воды из него и возвращайся ко мне." },
    ["7383c"] = { common = "Находиться в присутствии Древа-оракула... это всё равно что увидеть воплощённую мудрость. Позволь мне продолжить... Тельдрассил рос, и верховный друид обратился за благословением к драконам, ведь именно они благословили Нордрассил в древние времена. Однако Ноздорму, Повелитель Времени, отказал друиду, упрекнув его в самонадеянности. Алекстраза также отказала Оленьему Шлему, а без её благословения рост Тельдрассила стал непредсказуем, и в нём обнаружились изъяны..." },
    ["7441a"] = { common = "Представь себе, чужестранец: стоило мне зазеваться всего на секунду!.. я был очень занят: спасался от принца-отступника… — и меня тут же обворовали! Гнуснейший демон, бес Пузиллин, стащил мою книгу заклинаний, и ключ от некогда прекрасных чертогов Эльдре'Таласа! Ключ мне теперь ни к чему: я обменял своё бессмертие на свободу, — но книга мне нужна позарез! Отыщи мне этого беса Пузиллина, и добудь у него книгу! Ищи его в Квартале Криводревов Забытого Города." },
    ["7441c"] = { common = "Ты нашёл его! Проклятый бес. Увы, мои сбережения скудны. Но ты можешь выбрать что-то из того, что у меня есть." },
    ["7461a"] = { male = "Ну что, довольно ли ты слышал? Надеюсь, ты не устрашишься вступить в бой? Этому безумию необходимо положить конец! Время бессмертных давным-давно миновало. Уничтожь стражей, охраняющих столпы, и ликвидируй силовое поле. А потом убей Бессмер'тера. Это лишит принца большей части его силы, и тогда ты сможешь убить и его тоже. Помоги духам этого города упокоиться в мире!", female = "Ну что, довольно ли ты слышала? Надеюсь, ты не устрашишься вступить в бой? Этому безумию необходимо положить конец! Время бессмертных давным-давно миновало. Уничтожь стражей, охраняющих столпы, и ликвидируй силовое поле. А потом убей Бессмер'тера. Это лишит принца большей части его силы, и тогда ты сможешь убить и его тоже. Помоги духам этого города упокоиться в мире!" },
    ["7461c"] = { common = "Благодарим тебя, герой." },
    ["7462c"] = { common = "Вы открываете сундук, чтобы найти…" },
    ["7463a"] = { common = "А-а, странник, посвятивший себя магии! Удивительно. Я не видывал подобных тебе уже… сколько? Которое у нас тысячелетье на дворе? Да уже лет пятьсот! У меня есть кое-что, что поможет утолить твою жажду, но сначала тебе придётся выполнить одно моё поручение. В Эльдре'Таласе завелась аномалия. В восточном крыле поселился элементаль воды. Надо его… того… занести в каталог. Ступай в Квартал Криводревов, и добудь мне частицу стихийной сущности Гидротвари. Принеси её мне, а я тебя научу одной полезной штучке!" },
    ["7463c"] = { common = "Превосходно! Но кто ты? О, это не имеет значения. Что я должен был дать тебе? Хм… ну, герой, может это окажется для тебя полезным." },
    ["7481a"] = { common = "Несколько лет тому назад одинокий эльфийский мастер по имени Кариэль Винтхалус бежал из своей разорённой родной земли, унеся с собой несколько древних эльфийских артефактов. Поиски пропавшего мастера привели нас из руин Кель'Таласа через Пылающие степи и морские просторы в Фералас. Мы подозреваем, что эльф искал убежища в залах Эльдре'Таласа (ныне известного как Забытый Город). Отыщи его, странник! Жив он или мёртв, а знания, которые он унёс с собой, отыскать необходимо!" },
    ["7481c"] = { common = "О стыд… о ужас… Предметы потеряны? И никакого следа?" },
    ["7482a"] = { common = "Несколько лет тому назад одинокий эльфийский мастер по имени Кариэль Винтхалус бежал из своей разорённой родной земли, унеся с собой несколько древних эльфийских артефактов. Поиски пропавшего мастера привели нас из руин Кель'Таласа через Пылающие степи и морские просторы в Фералас. Мы подозреваем, что эльф искал убежища в залах Эльдре'Таласа (ныне известного как Забытый Город). Отыщи его, странник! Жив он или мёртв, а знания, которые он унёс с собой, отыскать необходимо!" },
    ["7482c"] = { common = "О стыд… о ужас… Предметы потеряны? И никакого следа?" },
    ["7486c"] = { common = "Голос Гидраксиса доносится от поверхности воды… \"Выбери себе то, что лучше всего подходит тебе, путник. Пусть оно защищает тебя от врагов Повелителей Вод.\"" },
    ["7488a"] = { common = "Маг Лефтендрис, злокозненная эльфийка крови, чья жестокость уступает лишь её извращённой приверженности к магии, бежала в Забытый Город! Она создала магическое устройство: сеть, улавливающую энергию этого места, — и мы опасаемся, что, если Лефтендрис не остановить, она нанесёт непоправимый урон нашему миру! Останови её, путник. Отыщи её и отними у неё эту сеть. Она, скорее всего, где-то неподалёку от сатиров в Квартале Криводревов Забытого Города. Принеси эту сеть мне, чтобы мы могли осторожно выпустить захваченную ею энергию на свободу…" },
    ["7488c"] = { common = "Тебе удалось добыть сеть! Молодец, путник! Лефтендрис, как и многие ей подобные эльфы, совершенно не задумывается о том, чем необузданное применение магии может грозить нашему миру. Они мнят себя владыками магии, не сознавая, что они всего лишь рабы своей собственной зависимости. Её смерть печалит меня, но это было необходимо. Спасибо тебе, путник. Энергию, накопившуюся в сети, мы осторожно выпустим на свободу в глуши, а саму сеть я уничтожу, чтобы она не попала в руки ещё какому-нибудь безумному магу." },
    ["7489a"] = { common = "Эльфийка крови Лефтендрис перешла все мыслимые границы! Она так жаждала всё новой магической энергии, что бросила вызов своим собратьям и создала хитроумное устройство, сеть, предназначенную для того, чтобы всасывать отравленную магию Забытого Города. Она и теперь собирает эту энергию, намереваясь использовать её против своих врагов! Лефтендрис необходимо остановить. Отыщи её в Квартале Криводревов в Забытом Городе, повергни её и принеси её сеть мне, чтобы мы могли передать её для изучения более здравомыслящим эльфам крови." },
    ["7489c"] = { common = "Хорошо, путник. Эта сеть содержит большие запасы магии из Забытого Города и я боюсь думать о повреждениях, нанесённых этой магией всем существам. За всё это ответственна Лефтендрис лично. Я сожалею, что она умерла, но она ни за что не рассталась бы со своей сетью пока была жива. Спасибо тебе, путник. Я пошлю сеть к тем исследователям магии, кто более ответственен чем Лефтендрис." },
    ["7490a"] = { common = "Тебе удалось совершить невозможное! Царица чёрных драконов лежит мёртвой у твоих ног. Отруби ей голову и отнеси её своему вождю." },
    ["7490c"] = { common = "Это великая победа для Орды, путник! Тебе уже не раз случалось постоять за честь своего вождя. Пришла пора и вождю оказать тебе честь!" },
    ["7491a"] = { common = "Властитель Рунтак ожидает тебя в Аллее Силы. Не заставляй его ждать, герой!" },
    ["7491c"] = { common = "Выбери себе награду, и мы достойно отпразднуем твою победу!" },
    ["7492a"] = { common = "Тало Терновое Копыто, тауренский старейшина, живущий в Фераласе, прислал просьбу о помощи. Подробностей он не сообщает, но говорит, что ему требуются агенты для тонкой… и опасной работы! Послужи Орде, путник. Отправляйся в Лагерь Мохаче в Фераласе и поговори с Тало." },
    ["7492c"] = { common = "А, рад видеть тебя герой. Мне нужна твоя поддержка, путник, и боюсь, что должен направить тебя навстречу опасности… А именно в Забытый Город." },
    ["7493c"] = { common = "Драконоубийца и мастер кожевенного дела? Ты не перестаёшь изумлять меня, герой. Я сражён. Пожалуйста, прими как дар то, чему я собираюсь тебя научить. Это знание окажется бесценным для тебя, если ты намерен уничтожить последних чёрных драконов. Изготовь плащ из чешуи драконьей царицы. Он будет защищать тебя и твоих союзников от опаляющего дыхания владыки Чёрной горы… Нефариана." },
    ["7494a"] = { common = "Путник! Твоя помощь нужна в Фераласе! Лефтендрис, маг, объявленный вне закона, бежала в развалины древнего эльфийского города Эльдре'Таласа, ныне именуемого Забытым Городом. Есть основания предполагать, что у неё с собой мощный магический артефакт, который необходимо вернуть. Латроникус Лунное Копьё ищет агентов, которые согласились бы отправиться в Забытый Город и отнять у Лефтендрис этот артефакт. Послужи Альянсу! Отправляйся к Латроникусу. Он находится в Крепости Оперённой Луны в Фераласе." },
    ["7494c"] = { common = "Привет тебе, путник. Рад тебя видеть, но предпочёл бы встретиться с тобой в более приятных обстоятельствах. Слушай внимательно, у меня для тебя жизненно важное задание…" },
    ["7495a"] = { common = "Вы совершили невозможное. Царица чёрных драконов лежит мёртвой у ваших ног. Возьмите её голову и передайте её Болвару Фордрагону." },
    ["7495c"] = { common = "Наконец-то, после стольких лет ожидания… Честь Штормграда восстановлена! Правосудие свершилось! Победа! Настоящая победа!" },
    ["7496a"] = { common = "Путник, найди майора Маттингли в Аллее Героев. Он будет тебя ждать…" },
    ["7496c"] = { common = "Тех кто удостоился подобной церемонии, можно по пальцам посчитать. Выбери свою награду… и начнём!" },
    ["7497c"] = { common = "Драконоубийца и мастер кожевенного дела? Ты не перестаёшь изумлять меня, герой. Я сражён. Пожалуйста, прими как дар то, чему я собираюсь тебя научить. Это знание окажется бесценным для тебя, если ты намерен уничтожить последних чёрных драконов. Изготовь плащ из чешуи драконьей царицы. Он будет защищать тебя и твоих союзников от опаляющего дыхания владыки Чёрной горы… Нефариана." },
    ["7498a"] = { common = "Том помечен печатью Читальни." },
    ["7498c"] = { common = "Отличная работа, странник. Если найдёте ещё какие-то книги, несите их нам, не раздумывая. Со временем мы подбираем всё новые награды за возвращение пропавших экземпляров!" },
    ["7499a"] = { common = "Том помечен печатью Читальни." },
    ["7499c"] = { common = "Отличная работа, странник. Если найдёте ещё какие-то книги, несите их нам, не раздумывая. Со временем мы подбираем всё новые награды за возвращение пропавших экземпляров!" },
    ["7500a"] = { common = "Том помечен печатью Читальни." },
    ["7500c"] = { common = "Отличная работа, странник. Если найдёте ещё какие-то книги, несите их нам, не раздумывая. Со временем мы подбираем всё новые награды за возвращение пропавших экземпляров!" },
    ["7501a"] = { common = "Том помечен печатью Читальни." },
    ["7501c"] = { common = "Отличная работа, странник. Если найдёте ещё какие-то книги, несите их нам, не раздумывая. Со временем мы подбираем всё новые награды за возвращение пропавших экземпляров!" },
    ["7502a"] = { common = "Том помечен печатью Читальни." },
    ["7502c"] = { common = "Отличная работа, странник. Если найдёте ещё какие-то книги, несите их нам, не раздумывая. Со временем мы подбираем всё новые награды за возвращение пропавших экземпляров!" },
    ["7503a"] = { common = "Том помечен печатью Читальни." },
    ["7503c"] = { common = "Отличная работа, странник. Если найдёте ещё какие-то книги, несите их нам, не раздумывая. Со временем мы подбираем всё новые награды за возвращение пропавших экземпляров!" },
    ["7504a"] = { common = "Том помечен печатью Читальни." },
    ["7504c"] = { common = "Отличная работа, странник. Если найдёте ещё какие-то книги, несите их нам, не раздумывая. Со временем мы подбираем всё новые награды за возвращение пропавших экземпляров!" },
    ["7505a"] = { common = "Том помечен печатью Читальни." },
    ["7505c"] = { common = "Отличная работа, странник. Если найдёте ещё какие-то книги, несите их нам, не раздумывая. Со временем мы подбираем всё новые награды за возвращение пропавших экземпляров!" },
    ["7506a"] = { common = "Том помечен печатью Читальни." },
    ["7506c"] = { common = "Отличная работа, странник. Если найдёте ещё какие-то книги, несите их нам, не раздумывая. Со временем мы подбираем всё новые награды за возвращение пропавших экземпляров!" },
    ["7507a"] = { common = "Вы обнаружили нечто очень важное. Эта книга не похожа ни на одну из тех, которые вам доводилось видеть раньше. Такое впечатление, как будто кому-то удалось испортить печать Читальни. Текст искажён и читается с трудом." },
    ["7507c"] = { common = "За эту книгу на чёрном рынке ты можешь получить весьма не мало золота, путник. К тому же, была сломана защитная печать и теперь каждый может узнать секреты этой книги." },
    ["7508a"] = { common = "Если хотите взять на себя эту задачу, отнесите тусклый клинок Лидросу." },
    ["7508c"] = { common = "Если ты хочешь войти в логово дракона, встретиться с ним лицом к лицу, и надеешься выжить после этого, то тебе нужен меч закалённый в их крови. Я могу тебе организовать такой." },
    ["7541c"] = { common = "Это займёт немного времени, чтобы изучить принесённый тобой кулон. За твою службу Орде, я бы хотел предложить тебе не большую награду. Спасибо, путник." },
    ["7562a"] = { common = "Ты хорошо изучил тёмные искусства и обрёл такую власть над существами из других миров, что… быть может, пришло время подчинить себе одного из знаменитых коней погибели. Вызвать его в наш мир нелегко, для этого потребуется великая сила и большие затраты, но если ты хочешь владеть таким скакуном, поговори с Мор'зулом Кровопуском. Он разбил лагерь рядом с Алтарём Бурь в Пылающих степях. Ступай, путник. Задание рискованное, но такие чернокнижники как ты не страшатся опасностей." },
    ["7562c"] = { common = "Привет тебе, путник, и добро пожаловать. Ты здесь чтобы учиться около Алтаря Бурь… Или ты пришёл поговорить со мной? Ага, я понял, что тебе надо… Ты хочешь быть мастером коня погибели? Неслабая задача, она тебе будет стоить немалого количества крови и пота… и не в последнюю очередь золота. Но конь погибели, это приз за который стоит побороться…" },
    ["7563a"] = { common = "Кони погибели живут в другом мире, на огненных равнинах Зорота, и чтобы подчинить себе одного из них, необходимы могущественные руны. Я могу начертать эти руны на пергаменте, но для этого нужны особые чернила. В далёких Зимних Ключах живут совухи. Некогда они были чистыми существами, но демоническое влияние Теснины Зловещего Шёпота лишило их разума, и они бродят по снегам в полном безумии. Из их крови я и сделаю чернила. Остаётся её добыть." },
    ["7563c"] = { common = "Очень хорошо. Эта кровь будет отдистиллирована и использована как чернила на пергаменте… И я ещё оставлю немного для себя, я слышал она хороша на вкус…" },
    ["7564a"] = { common = "Мой слуга, Горзиеки, довольно опытный алхимик. Он сможет приготовить чернила, о которых шла речь. Я уже подготовил принесённую тобой кровь; отнеси её Горзиеки, пусть приступает к работе." },
    ["7564c"] = { common = "А, эта кровь. Должно быть от мастера Мор'зула. Он любит это вещество и часто проливает его, хе-хе. Я однако предпочитаю его в венах маленького грызуна. Тогда она остаётся тёплой… столько, сколько понадобится. Мощная кровь. Мастер Мор'зул небось делает ещё один пергамент где написано как вызвать коня погибели! Здорово! Если это так, то ты сможешь выполнить ритуал, друг мой, но тебе понадобится нечто большее чем просто кровь." },
    ["7581a"] = { common = "Ты должен добыть у младших демонов кандалы для стражника ужаса. Кровь сатира из племени Буйного Нрава, что живут в Забытом Городе, для этого сгодится. Свернувшаяся кровь скрепит осколки Хедерины и даст силу хрустальной темнице." },
    ["7581c"] = { common = "Ах, самая подходящая кровь. Она подавит защитную магическую силу стража ужаса." },
    ["7582a"] = { common = "Демоны Хедерины, что живут у подножия горы Хиджал, выделяют яды Скверны, которые вызревают и твердеют, образуя антимагические кристаллы. Они известны как слёзы Хедерины. Даже чудовищная сила стражника ужаса не сможет разбить стены тюрьмы, сделанной из этого материала. Отправляйся в Теснину Зловещего Шёпота в Зимних ключах, и добудь этих слез." },
    ["7582c"] = { common = "Мне надо совместить кровь сатиров с этими кристаллами, и темница будет готова!" },
    ["7583a"] = { common = "Темница готова. Теперь самое трудное дело. Ты должен найти и схватить командира стражей ужаса в Гниющем Шраме при помощи этой кристаллической тюрьмы. Осторожнее! Страж ужаса — коварный и смертельный враг, он будет пытаться уничтожить тебя, как только ты начнёшь обряд заточения. Он будет отчаянно отбиваться, пытаясь избежать плена. Он будет смотреть только на тебя, путник. Потому я рекомендую взять с собой друзей, которые не дадут ему погубить тебя!" },
    ["7583c"] = { common = "Ты сделал всё так, как я и просил. Теперь ты готов получить знания для призыва и контроля зверя." },
    ["7601a"] = { male = "Если хочешь научиться у меня призывать инфернала-слугу, ты должен убить Крошиуса и добыть из его пылающих останков огненное ядро. Однако, это не так просто, как кажется. Крошиус чуть не дотла сгорел. Тебе придётся снова воспламенить его тело и поднять его из праха. Однако, для этого тебе придётся добыть другие ингредиенты из других демонических сущностей. Мой бес по имени Бесёнок, покажет тебе дорогу.", female = "Если хочешь научиться у меня призывать инфернала-слугу, ты должна убить Крошиуса и добыть из его пылающих останков огненное ядро. Однако, это не так просто, как кажется. Крошиус чуть не дотла сгорел. Тебе придётся снова воспламенить его тело и поднять его из праха. Однако, для этого тебе придётся добыть другие ингредиенты из других демонических сущностей. Мой бес по имени Бесёнок, покажет тебе дорогу." },
    ["7601c"] = { common = "Ох, опять двадцать пять..." },
    ["7603c"] = { common = "Сделка есть сделка! Быстрее, подписывай здесь и забирай вот это. У меня и так нет времени! Моё величайшее колдунство почти готово!" },
    ["7604a"] = { male = "Нижеподписавшийся со всей ответственностью заявляет, что сульфуронский слиток, переданный им братству Тория (ООО \"БТ\"), является подлинником. Нижеподписавшийся также подтверждает, что ООО \"БТ\" не несёт никакой ответственности за любой вред, могущий последовать в результате неосторожного обращения с Сульфурасом, как то: использование Сульфураса в качестве материала для ковки; самостоятельные разработки; попытки воспроизведения; продажа и употребление в пищу. Подпись под договором автоматически означает согласие подписавшегося со всеми условиями, перечисленными в документе.", female = "Нижеподписавшаяся со всей ответственностью заявляет, что сульфуронский слиток, переданный ею братству Тория (ООО \"БТ\"), является подлинником. Нижеподписавшаяся также подтверждает, что ООО \"БТ\" не несёт никакой ответственности за любой вред, могущий последовать в результате неосторожного обращения с Сульфурасом, как то: использование Сульфураса в качестве материала для ковки; самостоятельные разработки; попытки воспроизведения; продажа и употребление в пищу. Подпись под договором автоматически означает согласие подписавшейся со всеми условиями, перечисленными в документе." },
    ["7604c"] = { common = "С вами очень приятно иметь дело, путник! От имени ООО \"БТ\", я желаю вам удачи в поисках Сульфураса." },
    ["7621c"] = { male = "Герой, необходимо пройти ряд испытаний, которые проверят твои способности. Предлагаю выслушать историю, которую я должна тебе рассказать. Но будь внимателен, испытание, которое тебе необходимо пройти, нужно выполнять в одиночку. Рекомендуется чтобы все твои союзники оставались на расстоянии. Вмешательство повлечёт за собой наиболее суровое наказание. Судьба привела тебя сюда и теперь ты здесь. Сражайся с честью.", female = "Героиня, необходимо пройти ряд испытаний, которые проверят твои способности. Предлагаю выслушать историю, которую я должна тебе рассказать. Но будь внимательна, испытание, которое тебе необходимо пройти, нужно выполнять в одиночку. Рекомендуется чтобы все твои союзники оставались на расстоянии. Вмешательство повлечёт за собой наиболее суровое наказание. Судьба привела тебя сюда и теперь ты здесь. Сражайся с честью." },
    ["7622a"] = { common = "Тебе предстоит сделать то, что оказалось не под силу мне — спасти крестьян, погибших во время бегства из Стратхольма. Они выйдут на свет, и ты должен защитить их. Если ты не сможешь спасти слишком многих, мы продолжим влачить наше проклятое существование. Это настоящее испытание для всех твоих способностей. Да поможет тебе Свет, путник." },
    ["7622c"] = { male = "Твоё упорство и мужество поразительны, жрец. Ты заслужил право получить щепку Нордрассила.", female = "Твоё упорство и мужество поразительны, жрица. Ты заслужила право получить щепку Нордрассила." },
    ["7623a"] = { common = "Мор'зул говорит, что ты хочешь открыть портал в Зорот. Раз так, тебе не обойтись без зоротианской звёздной пыли. А её нелегко найти в Азероте! Она может быть лишь у одного существа — лорда Гиблопуста из Джеденара, сердца Совета Теней! Поговори с ним, вдруг он поделится звёздной пылью. Впрочем, отправляясь в Джеденар, тебе необходимо принять злое обличье, чтобы добраться до Совета Теней. Значит, тебе нужны мои зелья Теней, а они недёшевы…" },
    ["7625c"] = { common = "Да я поверить не могу! Ты разобрался с этим Повелителем Ужаса или заплатил ему денег, или и то и другое! Мор'зул получит вскоре эти чернила, и мы сможем создать свиток, и ты откроешь портал к Зороту и вытащишь через него одного из знаменитых коней погибели!" },
    ["7626a"] = { common = "Колокол Детмуры назвали в честь Детмуры Темноглазой. Это один из трёх предметов, необходимых для создания круга Великого призыва. Сопряжённый с Колесом и Свечой, он предоставит в твоё распоряжение огромный запас магической энергии. Мой слуга Горзиеки может создать такой колокол, но ему понадобится много эликсиров энергии Тьмы. Добудь их у алхимика и отнеси Горзиеки." },
    ["7626c"] = { common = "Очень хорошо! Я надеюсь, что эти эликсиры было не очень сложно достать? Некоторые алхимики здорово заламывают за свои изделия. Сделаю я тебе колокол и сохраню его пока ты не будешь готов к ритуалу." },
    ["7627a"] = { common = "Колесо Чёрного Похода содержит в себе и направляет чёрную силу, необходимую для создания круга Великого призыва. Горзиеки может создать это колесо, но ему понадобятся большие сверкающие осколки, которые получают зачаровыватели, и руда чёрного железа, которую может добыть опытный горняк. Принеси моему слуге всё необходимое." },
    ["7627c"] = { common = "Ага! Вот и они. Я слышал что руда чёрного железа находится только в глубинах Чёрной Горы, и думаю там тебе пришлось нелегко, кха-кха… Ладно, к делу. Я создам колесо и придержу его пока ты не будешь готов к ритуалу." },
    ["7628a"] = { common = "Свеча Судного Дня хранит в себе огонь, который опаляет всех, желающих прервать твой ритуал. Зажигая свечу при создании круга Великого призыва, ты сожжёшь всех упрямых демонов! Впрочем, сдержать этот огонь довольно трудно, и для этого нужна чешуя чёрного дракона. Купи её у мастера снятия шкур и принеси Горзиеки Дикоглазу." },
    ["7628c"] = { common = "А, очень хорошо. Мне было это необходимо. Теперь я сделаю свечу и выдержу её до тех пор пока ты не будешь готов начать свой ритуал круга большого призыва." },
    ["7629a"] = { common = "Для подготовки пергамента Мор'зула осталось сделать только одно — напитать бумагу зоротианской звёздной пылью. И… боюсь, здесь этого не сделать. Мне не хватит оборудования! Впрочем, я знаю об одной лаборатории, где есть всё необходимое. Она находится в Некроситете, на острове Каэр Дарроу, в Чумных землях. Я туда отправиться не смогу, но у меня есть идея. Возьми эту бутылку. В ней сидит довольно умный бес. Выпусти его в алхимической лаборатории, и он напитает пергамент звёздной пылью." },
    ["7629c"] = { common = "Славно. Д'жииви создал пергамент. И как там в Некроситете? Прекрасно, не правда ли? А жучки там… Я слышал, они вкусные! Хорошо сделано, путник, и спасибо за то что вернул кувшин. Он у меня уже давно и не продаётся!" },
    ["7630a"] = { common = "Итак, Колокол, Колесо и Свеча готовы. Осталось создать чёрный магнит. Он понадобится во время ритуала, поддерживать прочие объекты, на случай, если они подведут. Для создания магнита мне понадобится арканит. У тебя его нет? Коли так, поищи его у алхимика. Принеси мне арканит, и я создам чёрный магнит." },
    ["7630c"] = { common = "Ага, нашёл всё-таки. Я всегда говорил — надо лишь по-настоящему захотеть! Теперь я могу создать магнит. Тебе он понадобится, чтобы быть уверенным в том что ритуал создания круга большого призыва пройдёт успешно." },
    ["7631a"] = { common = "Всё готово. Пришло время провести ритуал создания круга Великого призыва и воспользоваться пергаментом с рунами, начертанными зоротианской звёздной пылью… И открыть портал в Зорот. Все инструкции по проведению ритуала я записал в тот свиток. Изучи его внимательно, потому что следует делать всё в точности так, как написано, или успеха не добиться. Удачи, путник. И да попадут души твоих врагов в твой мешочек осколков." },
    ["7637a"] = { common = "Чтобы подготовиться к этому заданию, ты должен сначала показать умение жертвовать и умение судить… в первую очередь — жертвовать. Для выполнения задания ты должен получить курильницу экзорцизма у Верховного жреца Рохана. Несмотря на то, что её использование будет продиктовано благими намерениями и существенными причинами, за неё должна быть предложена соответственная компенсация. Отправляйся в Стальгорн и поговори с Верховным жрецом. Если возьмёшь с собой достаточно звонкой монеты, чтобы компенсировать ему потерю курильницы, ты проявишь должную готовность к жертвам. А теперь иди, путник, время терять нельзя." },
    ["7637c"] = { common = "Да пребудут на тебе все благословения, друг мой! Твой дар далеко превосходит наши нужды. Твоя жертва не только поможет восстановить утраченное, но также позволит нам помочь самым бедным жителям Стальгорна. А теперь дай-ка я удостоверюсь, что как следует подготовил эту курильницу для твоих будущих свершений." },
    ["7638a"] = { male = "Пришло твоё время, путник, узнать о том, как найти то, что ты, без сомнения, хочешь заполучить уже в течение некоторого времени… твоего рыцарского коня. Поговори с лордом Грейсоном Тенеломом здесь, в Храмовом квартале Штормграда. Именно он не только раскроет тебе все секреты самого верного паладинского скакуна, но и поможет разобраться в задачах, которые встанут перед тобой, прежде чем ты сможешь раздобыть своего собственного коня. Я желаю тебе всего наилучшего в этом испытании. Во имя Света, мой благородный брат!", female = "Пришло твоё время, путник, узнать о том, как найти то, что ты, без сомнения, хочешь заполучить уже в течение некоторого времени… твоего рыцарского коня. Поговори с лордом Грейсоном Тенеломом здесь, в Храмовом квартале Штормграда. Именно он не только раскроет тебе все секреты самого верного паладинского скакуна, но и поможет разобраться в задачах, которые встанут перед тобой, прежде чем ты сможешь раздобыть своего собственного коня. Я желаю тебе всего наилучшего в этом испытании. Во имя Света, моя благородная сестра!" },
    ["7638c"] = { common = "Рад тебя видеть, путник. Я знаю как ты ждёшь своего коня, и настало время тебе получить его. Следуй пути добра, борись со злом и твой конь будет верно служить тебе. Твоё время пришло!" },
    ["7639a"] = { common = "Прими эту курильницу и будь благословен. Я сам применял её в нескольких обрядах экзорцизма, и она хорошо послужит тебе в грядущих тяжких испытаниях. Ныне возвращайся к лорду Грейсону Тенелому в Штормград, путник. Он даст тебе поручение." },
    ["7639c"] = { common = "Да, это она. Не раз вам придётся совершать этот обряд и не раз вам придётся в ходе него жертвовать собой. Я рад, что вы готовы к этому. Жертвенность — важнейшая составляющая, без которой не выполнить долга… но не мне говорить вам об этом. А теперь, путник, вам придётся проявить истинное правосудие в ваших делах. И эта курильница послужит вашим сосудом для оказания помощи истерзанным духам утраченной нами земли." },
    ["7640a"] = { common = "Я добавил в курильницу щепотку заражённой земли Долины Ужаса, что в Восточных Чумных землях. Ты должен будешь использовать курильницу для поиска мест, которые несут на себе признаки беспокойного поведения потусторонних сил. Ищи зелёное свечение, исходящее из-под земли — так физический мир проявляет себя, мучимый миром потусторонним, и используй курильницу для вызова из-под земли злых духов. Когда свершишь суд над призраками, я поставлю перед тобой новую задачу." },
    ["7640c"] = { common = "Отличная работа, путник. Свершить суд Света над теми, кто обитает во тьме — задача, к выполнению которой мы должны подходить с рвением и усердием. Именно это ты и свершил благодаря своей жертве в Стальгорне и правосудию над духами Долины Ужаса. Твои следующие шаги вновь потребуют от тебя и жертвенности, и умения вершить правосудие: ведь тебе нужно будет вернуть дух рыцарского коня, который служит сейчас рыцарю смерти, известному как Тёмный Губитель." },
    ["7641a"] = { common = "Без особого чепрака рыцарский конь паладина ничем не отличается от обычного скакуна. Чепрак для твоего скакуна не только должен быть изготовлен из наилучших материалов, но в силу сопутствующих обстоятельств нужно, чтобы он ещё был в достаточной мере настроен на призрачный мир. Но всё по порядку, путник — сначала нужно изготовить чепрак. В Квартале Дворфов Штормграда проживает один из самых лучших современных мастеров — Гриманд Элмор. Он берёт за свою работу недёшево, но качество его работы — как раз то, что нам нужно. Поговори с ним." },
    ["7641c"] = { common = "Привет-привет, паренёк — лорд Тенелом известил меня заранее о том, что ты придёшь со мной повидаться. Я с удовольствием сделаю чепрак, какой тебе нужен, но это будет нелегко, да и обойдётся недёшево. Я об этом говорю открыто и в первую очередь. Но, скажу я тебе — и Грейсон поддержит меня в этом утверждении — лучшего чепрака, чем изготовленный мной, ты во всём Азероте не найдёшь!" },
    ["7642a"] = { common = "Для чепрака тебе понадобятся четыре вещи: руническая ткань для подкладки, арканитовые слитки для покрытия, цветки слезы Артаса для настройки на призрачный мир и святая вода Стратхольма для духовного укрепления. На самом деле, вещей понадобится пять… если считать золото для меня. Эта плата — за весь мой труд, а также седло и стремена ручной работы. Когда наберёшь всё это, я смогу изготовить твой чепрак. А пока ты ищешь необходимое, я приступлю к работе." },
    ["7642c"] = { common = "Это… да, это именно то, что нужно. А ты весьма находчивый, не так ли? Ладненько, давай-ка закончим с твоим чепраком!" },
    ["7643a"] = { common = "Твоему чепраку нужно особое благословение, а его можно получить только у подходящего духа. Такой дух обитает, например, в башне Забытого Города — это Дух древнего коня. Сейчас его удерживает в плену Тендрис Криводрев. Убей эту тварь, чтобы освободить духа, путник. Только имей в виду, что просто освободить — недостаточно. Тебе нужно сначала умилостивить духа, чтобы получить его благословение. Для этого понадобится особый лошадиный корм. Ты найдёшь его в Южнобережье, если поговоришь с Меридет Карлсон." },
    ["7644c"] = { common = "Тебе пришлось немало постранствовать, друг мой! И вот наконец твой чепрак готов к последнему шагу, который тебе придётся предпринять. Этот чепрак пригодится тебе, чтобы седлать своего скакуна, когда труд искупления будет завершён. Однако до этого тебе снова придётся вступить в тяжкую борьбу. Твой час близок! Перед этим нам нужно изготовить ещё один, последний предмет. Надеюсь, твой пыл ещё не иссяк?" },
    ["7645a"] = { common = "Серебряная Длань посчитала меня ЧОКНУТОЙ, когда я сказала, что могу сделать особый конский корм, который насытит призрачных лошадей. ВСЕ считали меня чокнутой! Пришло время отыграться! Я сделаю, что тебе надо, ПАЛАДИН… ЗАЩИТНИК, тоже мне… Но обойдётся это недёшево. Мне понадобится сытное манное печенье, которое продают только в Серебряном Рассвете. Кроме того я требую — да, ТРЕБУЮ, золото в качестве компенсации за перенесённые страдания! Посмотрим, многим ли ты можешь пожертвовать, ПАЛАДИН." },
    ["7645c"] = { common = "ДА, КТО… стоп, ты и золото мне даёшь? Лично ты не называл меня чокнутой — а они дразнили меня сдвинутой, слетевшей с катушек… И ты хочешь искупить зло, причинённое не тобой? Я… я недооценила тебя, путник. Если тебе понадобится ещё корм для коней, обращайся. Я сделаю его бесплатно. Спасибо… благородный. Но деньги я себе оставлю — я не настолько чокнутая, чтобы отказаться от целого состояния." },
    ["7646a"] = { common = "Теперь мы должны сконструировать магический кристалл — так начнётся твой подвиг и освобождение пленённого духа зловещего рыцарского коня. Собственно, кристалл уже почти готов. Катализатором для него послужила курильница, которую ты использовал, изгоняя духов из Долины Ужаса; осталось только сделать подходящую подставку для нашего прибора. Да, и ещё нужны последние два компонента — азеротский алмаз и безупречный чёрный алмаз. Эти два камня станут маяком, пронзающим тьму!" },
    ["7646c"] = { common = "Отличные камни, путник. Последние фрагменты теперь установлены на свои места. Наконец-то, пришло твоё время! В глубине Главного склепа в Некроситете покоятся останки многих существ. Среди них есть кости и некогда благородного рыцарского коня. Призрачный дух скакуна теперь служит рыцарю смерти Тёмному Терзателю. Ты победишь Терзателя и свершишь правый суд над его несчастным конём. Только ты, путник, можешь даровать душе скакуна искупление и избавить её от мук ужасного служения." },
    ["7647a"] = { common = "Возьми эту суму — в ней собраны предметы, которые понадобятся тебе для выполнения задания. Используй магический кристалл в самом сердце подвала Главного склепа для вызова проклятых духов, над которыми нужно свершить суд. Во время испытания рассчитывай силы — духи могут оказаться сильнее, чем ты думаешь. После гибели духов появится сам рыцарь смерти. Срази его и верни потерянную душу рыцарского коня. Только тогда, путник, ты сможешь принести ей избавление и возложить чепрак на твоего нового скакуна. Желаю удачи!" },
    ["7648a"] = { common = "Готово, друг мой. Это одно из моих лучших изделий — не хуже, чем тот чепрак, что я собственноручно смастерил для лорда Тенелома, когда он отправлялся за своим конём. Благодарю тебя за доверие. Несомненно, и сам Грейсон захочет полюбоваться на мою работу. Покажи ему чепрак и передай мою искреннюю благодарность за его достойные дела." },
    ["7648c"] = { common = "Молодец! С возрастом мастерство Гриманда растёт. А его изделия были одними из лучших ещё в те времена, когда он делал чепрак для моего коня! Этот чепрак слишком хорош для обычного скакуна, но нам предстоит иметь дело с необычным животным. Тебе предстоит оседлать коня, и поэтому для чепрака нужно получить особое благословение. Ступай." },
    ["7649a"] = { common = "Том помечен печатью Читальни." },
    ["7649c"] = { common = "Отличная работа! На, я уверен тебе пригодится этот рецепт!" },
    ["7650a"] = { common = "Том помечен печатью Читальни." },
    ["7650c"] = { common = "Отличная работа! На, я уверен тебе пригодится этот рецепт!" },
    ["7651a"] = { common = "Том помечен печатью Читальни." },
    ["7651c"] = { common = "Отличная работа! На, я уверен тебе пригодится этот рецепт!" },
    ["7652c"] = { common = "Хорошо, у меня для тебя есть отличная сделка. Я могу предложить тебе рецепты имперских лат. Всё, что я хочу взамен, это немного ториевых слитков. Звучит заманчиво?" },
    ["7653c"] = { common = "С тобой приятно иметь дело. И путник, сотри эту гримасу со своего лица." },
    ["7654c"] = { common = "С тобой приятно иметь дело. И путник, сотри эту гримасу со своего лица." },
    ["7655c"] = { common = "С тобой приятно иметь дело. И путник, сотри эту гримасу со своего лица." },
    ["7656c"] = { common = "С тобой приятно иметь дело. И путник, сотри эту гримасу со своего лица." },
    ["7657c"] = { common = "С тобой приятно иметь дело. И путник, сотри эту гримасу со своего лица." },
    ["7658c"] = { common = "С тобой приятно иметь дело. И путник, сотри эту гримасу со своего лица." },
    ["7659c"] = { common = "С тобой приятно иметь дело. И путник, сотри эту гримасу со своего лица." },
    ["7667a"] = { common = "Путник, у меня есть срочное дело, и надеюсь, ты сумеешь мне помочь. Разреши, я объясню. В глубине Некроситета в Лордероне есть здание, которое называется Главный склеп. Мне нужно изготовить устройство, которое позволит развеять зловещие тени этого жуткого места. Но чтобы его завершить, мне нужны два алмаза, азеротский и безупречный чёрный. Найти их не так-то просто, я знаю, но самому мне их раздобыть не под силу. Не согласишься ли ты добыть для меня эти камни?" },
    ["7667c"] = { common = "Ага, молодец, путник. Благодарю тебя. Теперь я могу закончить гадальный кристалл. Не хочешь ли ты поучаствовать в его применении? Уверяю тебя, это для очень важного дела…" },
    ["7701a"] = { common = "Именем его светлости надзирателя Скользорука должно убить агента Братства Тория надзирателя Мальториуса, командира подразделения Шлаковой Ямы войск Чёрного Железа в Котле. Его голову должно принести в качестве доказательства содеянного. За наградой обращаться к дозорному капитану Лоло Долгобою." },
    ["7701c"] = { male = "Я никогда не думал, что посмотрю на эту рожу ещё раз! Она выглядит лучше без остальной части к которой прикреплена. Вот твоя награда *ик*, путник.", female = "Я никогда не думал, что посмотрю на эту рожу ещё раз! Она выглядит лучше без остальной части к которой прикреплена. Вот твоя награда *ик*, путница." },
    ["7704a"] = { common = "Ну и ну... Вот так сюрприз! У горничной была огромная вышитая подушка, и вот теперь она в ваших руках. Эвонис Сажекурке непременно захочет заполучить её. Посмотрим, что она сможет предложить взамен..." },
    ["7704c"] = { common = "На такую удачу я даже и не рассчитывала! Магическая подушка горничной теперь моя! Можешь не сомневаться, ты получишь свою награду за труды!" },
    ["7721a"] = { male = "Если я поступлю вопреки доводам разума, и всё же буду по-прежнему содержать инженерную мастерскую на Забытом берегу, мне нужно будет как-то разобраться с этими зловредными элементалями. Чтоб им провалиться, этим необузданным стихиям! Но как повезло мне – а теперь и вам, мой уважаемый помощник! Ведь эти элементали представляют собой идеальный источник энергии для моего ультрасжимателя! Так что ликвидируйте их, не стесняясь, только, смотрите, не выбрасывайте ядра элементалей воды!", female = "Если я поступлю вопреки доводам разума, и всё же буду по-прежнему содержать инженерную мастерскую на Забытом берегу, мне нужно будет как-то разобраться с этими зловредными элементалями. Чтоб им провалиться, этим необузданным стихиям! Но как повезло мне – а теперь и вам, моя уважаемая помощница! Ведь эти элементали представляют собой идеальный источник энергии для моего ультрасжимателя! Так что ликвидируйте их, не стесняясь, только, смотрите, не выбрасывайте ядра элементалей воды!" },
    ["7721c"] = { common = "Отличнобалденнейше! Уж я с этими ядрами теперь поработаю! Да и элементалей на берегу теперь стало поменьше, так что больше не придётся засыпать в слезах от мысли, что я устроил свою лавку в наихудшем месте, какое только можно себе представить! Спасибо, спасибо за все твои старания! Хоть я сейчас и не в самом лучшем финансовом положении, но всё же прими от меня понятную и полезную для тебя благодарность: ценности!" },
    ["7722a"] = { common = "Когда этот негодяй Мальториус покинул клан, он унёс с собой кое-что поважнее безупречнейшего чародейского кристалла. Он украл рецепт огненного плавня! Полагаю, это была его возможность выслужиться у дворфов Чёрного Железа. Верни нам эти секретные документы. Мальториус наверняка держит их при себе, там, в Шлаковой Яме." },
    ["7722c"] = { male = "Я надеюсь, что ты выбил ему зубы. Рагнарос знает, он это заслужил. Теперь мы можем приступить к делу.", female = "Я надеюсь, что ты выбила ему зубы. Рагнарос знает, он это заслужил. Теперь мы можем приступить к делу." },
    ["7723a"] = { common = "К несчастью, я уже не способен на столь меткие удары, как раньше, из-за проблем с пальцами. Виноват климат и низкое атмосферное давление – пальцы здесь отекают и становятся похожими на телсамарские кровяные колбаски... Так что придётся тебе поработать за меня: вышиби дух из боевых големов, которых найдёшь в ущелье." },
    ["7723c"] = { male = "А ты хороший парень. У меня для тебя есть небольшой подарок.", female = "А ты хорошая девушка. У меня для тебя есть небольшой подарок." },
    ["7724a"] = { common = "Как только старый Хансел собирается отдохнуть, нелёгкая подбрасывает ему ещё работёнки... Вот, пожалуйста, теперь большие лавовые пауки добавили проблем! Скользорук говорит, его храбрецы чуть ли не из пушек от них отстреливались... Короче, чтобы зря не пугать детишек и наших доблестных вояк, надо бы найти на пауков управу. Уверен, ты справишься." },
    ["7724c"] = { common = "Хансел чихает. Кажется я замёрз. Проклятый холодный климат!" },
    ["7727a"] = { male = "Бедные мои ножки... У меня бурсит, молодой человек. Да, большие шишки всегда наживают себе шишки. Ну и как мне заниматься истреблением всяких тварей, если пальцы моих ног в таком плачевном состоянии?В общем, тут-то ты мне и поможешь! Скрендж и Гориврат хотят, чтобы я поубивал этих проклятых ящеров, чтобы расчистить путь для их исследовательских отрядов. Они, вишь ты, желают изучать озёра лавы в Шлаковой Яме. А всякие пламезавры и прочие завры им, вишь ты, мешают. В общем, придётся тебе направиться в Шлаковую Яму и слегка ускорить процесс вымирания этих монстров.", female = "Бедные мои ножки... У меня бурсит, милочка. Да, большие шишки всегда наживают себе шишки. Ну и как мне заниматься истреблением всяких тварей, если пальцы моих ног в таком плачевном состоянии?В общем, тут-то ты мне и поможешь! Скрендж и Гориврат хотят, чтобы я поубивал этих проклятых ящеров, чтобы расчистить путь для их исследовательских отрядов. Они, вишь ты, желают изучать озёра лавы в Шлаковой Яме. А всякие пламезавры и прочие завры им, вишь ты, мешают. В общем, придётся тебе направиться в Шлаковую Яму и слегка ускорить процесс вымирания этих монстров." },
    ["7727c"] = { common = "Ох, мои ноги… Я понимаю, что у тебя ещё не было Люфы..." },
    ["7728a"] = { common = "Внимание, украдены следующие предметы: *Фурма Чёрного Железа – одна штука. *Подзорная труба наблюдателя – одна штука. Просьба вернуть за вознаграждение. Братство Тория точно знает, что эти предметы были украдены беспринципными и завистливыми дворфами Чёрного Железа из Тлеющего ущелья. Подзорная труба была великолепным прибором для наблюдения, а фурма – просто незаменимый инструмент. Нашедшему просьба вернуть указанные вещи Скренджу." },
    ["7728c"] = { common = "Фантастическая работа! Вот твоя награда." },
    ["7729a"] = { common = "Надсмотрщику Скренджу требуется опытный кандидат на должность устранителя конкурентов в Тлеющем ущелье. Пол неважен. Если вы считаете, что ваша квалификация достаточна для этой должности, отправляйтесь в Тлеющем ущелье и уничтожьте всех встреченных вами надсмотрщиков Чёрного Железа и работорговцев Чёрного Железа. Возвращайтесь к надсмотрщику Скренджу, когда ваша одежда пропитается кровью. Сами поймёте, когда настанет момент, так что вопросов не задавать." },
    ["7729c"] = { male = "Пятнадцать и девять десятых фунта! Это новый рекорд для веса крови и кишек на одежде! Поздравляю, герой!", female = "Пятнадцать и девять десятых фунта! Это новый рекорд для веса крови и кишек на одежде! Поздравляю, героиня!" },
    ["7730a"] = { common = "Судя по сведениям, полученным с помощью разведки, враги, теснящие гноллов с юга, – это раса насекомоподобных существ. Неизвестно, разумны ли они – но, откровенно говоря, это и неважно. Если гноллы их так боятся, что предпочитают переть на нас, значит, эти твари так же опасны, как гноллы, а может, и ещё опаснее. Проникни в те места, где обитают эти насекомые, Цуккаш. Это место называется \"Гудящая Бездна\". Постарайся уменьшить их численность, и доложи мне о том, что увидишь. В доказательство своих свершений принеси мне их панцири!" },
    ["7730c"] = { male = "Молодец, герой! Конечно, отпугнуть этих насекомых тебе не удалось – их не проймёшь ничем, кроме полномасштабной военной кампании. Однако с твоей помощью мы сумеем выиграть время, чтобы разработать должную стратегию. Я велю изучить эти панцири – нам нужно узнать об этих тварях как можно больше, прежде чем бороться с тем, что оказалось куда более сложной задачей, нежели мы предполагали.", female = "Молодец, героиня! Конечно, отпугнуть этих насекомых тебе не удалось – их не проймёшь ничем, кроме полномасштабной военной кампании. Однако с твоей помощью мы сумеем выиграть время, чтобы разработать должную стратегию. Я велю изучить эти панцири – нам нужно узнать об этих тварях как можно больше, прежде чем бороться с тем, что оказалось куда более сложной задачей, нежели мы предполагали." },
    ["7731a"] = { common = "Один из разведчиков, исследовавших Гудящую Бездну, доложил о виденном им гигантском насекомом – куда более крупном, чем все остальные замеченные им насекомые. Помимо необычных размеров, оно, по-видимому, окружено какой-то особой аурой, которой у прочих насекомых нет. Мы назвали его жалохвостом. Нам хотелось бы изучить внутренности этой твари, чтобы понять, как лучше бороться с этой новой угрозой. Добудь ядовитые железы жалохвоста и принеси их мне!" },
    ["7731c"] = { male = "Поразительно, герой… просто поразительно! Если Жалохвост и впрямь один из сильнейших представителей своего вида, изучение этой твари окажется более чем важным и своевременным. Теперь моя задача – сделать так, чтобы мы продержались достаточно долго и смогли воспользоваться нашими новыми знаниями. Прими это денежное вознаграждение в знак признательности всего населения лагеря.", female = "Поразительно, героиня… просто поразительно! Если Жалохвост и впрямь один из сильнейших представителей своего вида, изучение этой твари окажется более чем важным и своевременным. Теперь моя задача – сделать так, чтобы мы продержались достаточно долго и смогли воспользоваться нашими новыми знаниями. Прими это денежное вознаграждение в знак признательности всего населения лагеря." },
    ["7732a"] = { common = "Ты поступаешь весьма разумно, направляя свои усилия на борьбу с этими насекомыми, грозящими Лагерю Мохаче. Опасность далеко ещё не миновала, и мне хотелось бы попросить тебя о ещё одной услуге. Вот в этих бумагах изложены все сведения об улье Цуккаш, которые нам удалось раздобыть. Прошу тебя доставить их Зилзибину Барабанному Бою на Волок в Оргриммаре. Он специалист по подобным созданиям; надеюсь, добытые нами знания ему пригодятся." },
    ["7732c"] = { male = "А... Я этого ожидал. Эти создания, с которыми вы столкнулись, это древняя угроза, которую Орда продолжает игнорировать с упорством достойным лучшего применения. Хадокен мудро поступил, принеся это и приведя тебя – ко мне. Эти Зукк'аш ни кто иные как силитиды. Некоторые думают, что они безмозглые твари, но поверь мне, это угроза куда хуже чем угроза со стороны Альянса. Если ты достаточно силён, то мы используем тебя чтобы пролить свет на эту угрозу.", female = "А... Я этого ожидал. Эти создания, с которыми вы столкнулись, это древняя угроза, которую Орда продолжает игнорировать с упорством достойным лучшего применения. Хадокен мудро поступил, принеся это и приведя тебя – ко мне. Эти Зукк'аш ни кто иные как силитиды. Некоторые думают, что они безмозглые твари, но поверь мне, это угроза куда хуже чем угроза со стороны Альянса. Если ты достаточно сильна, то мы используем тебя чтобы пролить свет на эту угрозу." },
    ["7733a"] = { common = "Я знаю, где можно добыть шкуры ещё лучше этих – хотя в это и трудно поверить! На севере Фераласа, в глубине Пещеры Бешеного оврага, обитает другая стая йети. Они куда агрессивнее тех, с которыми тебе доводилось иметь дело прежде, так что если ты ищешь новых подвигов, тебя это наверняка заинтересует! А я хорошо вознагражу тебя за десяток шкур таких йети. Принеси их мне, и мы договоримся." },
    ["7733c"] = { common = "Отлично, отлично! Эти прекрасно подходят – я уже вижу, что если обработать их как следует, они станут ещё прочнее. Ещё раз спасибо тебе за помощь. Вот, прошу: возьми одно из моих изделий." },
    ["7734a"] = { common = "Я знаю, где можно добыть шкуры ещё лучше этих – хотя в это и трудно поверить! На севере Фераласа – в глубине Пещеры Бешеного оврага, обитает другая стая йети. Они куда агрессивнее тех, с которыми тебе доводилось иметь дело прежде, так что если ты ищешь новых подвигов, тебя это наверняка заинтересует! А я хорошо вознагражу тебя за десяток шкур таких йети. Принеси их мне, и мы договоримся." },
    ["7734c"] = { common = "Замечательно! Эти шкуры отлично подойдут: я уже вижу, что стоит их как следует обработать, и они станут куда прочнее. И снова спасибо за помощь. Вот, пожалуйста, – выбирай из моих последних шедевров." },
    ["7735a"] = { common = "Вы добыли безупречную шкуру йети, особенно толстую и прочную – даже прочнее шкур йети с Дикого утёса. Вам известно, что Пратту Макгруббену из Крепости Оперённой Луны всегда нужны шкуры йети, а уж эта его тем более заинтересует!" },
    ["7735c"] = { common = "Невероятно! Да это же самый настоящий праотец всех шкур йети! Не поверишь, сколько я тебе за неё дам. Обычно я не плачу так много за одну шкуру, но я уверен, что из этой у меня выйдет кое-что необыкновенное! Спасибо, что не забываешь меня!" },
    ["7738a"] = { common = "Вы добыли безупречную шкуру йети, особенно толстую и прочную – даже прочнее шкур йети из Пещеры Бешеного оврага. Вам известно, что Джангору Быстрому Страннику из Лагеря Мохаче всегда нужны шкуры йети, а уж эта его тем более заинтересует!" },
    ["7738c"] = { male = "Невероятно! Это, пожалуй, лучший образчик шкуры йети, какой я когда-либо видел! Да уж, конечно, за такую шкуру следует заплатить по достоинству! Обычно одна-единственная шкура стоит недорого, но из этой шкуры я наверняка сумею изготовить нечто особенное. Спасибо, что принёс её мне!", female = "Невероятно! Это, пожалуй, лучший образчик шкуры йети, какой я когда-либо видел! Да уж, конечно, за такую шкуру следует заплатить по достоинству! Обычно одна-единственная шкура стоит недорого, но из этой шкуры я наверняка сумею изготовить нечто особенное. Спасибо, что принесла её мне!" },
    ["7761a"] = { common = "Недоумок, как-то мне очень сомнительно, что ты сумеешь сдержать чужаков и не дать им проникнуть в убежище повелителя. В случае твоей смерти — а подобный исход более чем вероятен — у этой сферы есть свой собственный механизм защиты, который не даст чужакам перенестись напрямую в Крыло Тьмы. Сферой сможет воспользоваться только тот, кто отмечен меткой Драккисата. К счастью, Драккисат, в отличие от некоторых \"интендантов\", далеко не дурак и хорошо разбирается в своём деле. Он самолично охраняет клеймо! -Вождь Ренд Чернорук Постскриптум. Уничтожь это письмо, идиот!" },
    ["7761c"] = { common = "Раскалённое клеймо прожигает вам руку, но вы даже не морщитесь. Вы сильны и крепки духом! Теперь у вас есть метка Драккисата. Самое время устроить потеху и разнести этот замок ко всем чертям!" },
    ["7781a"] = { common = "Знакомое чувство ликования охватывает вас: победа!!! Перед вами лежит гигантская, покрытая боевыми шрамами голова Нефариана. Отнесите же её своему Верховному лорду!" },
    ["7781c"] = { common = "Вы понимаете значение этой победы, путник? Ваш подвиг войдёт в историю Штормграда! Подобного успеха Альянс не знал многие годы!" },
    ["7782a"] = { common = "Отправляйтесь в Аллею Героев и поговорите с фельдмаршалом Афрасиаби." },
    ["7782c"] = { common = "Выбирайте награду, и пусть начнётся празднество!" },
    ["7783a"] = { common = "Ты вновь испытываешь знакомое чувство — сладость победы! У твоих ног лежит массивная, покрытая боевыми шрамами голова Нефариана. Отнеси её своему вождю, воитель!" },
    ["7783c"] = { common = "Ты снова принёс Орде славу, путник! Сын Смертокрыла мёртв. Силам зла будет над чем задуматься!" },
    ["7784a"] = { common = "Разыщи властителя Рунтака в Аллее Силы." },
    ["7784c"] = { common = "Выбери себе награду, и я установлю голову этой твари так, чтобы её могли видеть все!" },
    ["7785a"] = { common = "Изучи Сосуд Возрождения, смертный. Из него возродится Ветроносец!" },
    ["7785c"] = { common = "Пусть поход твой увенчается успехом. Да благословит тебя мой повелитель." },
    ["7786a"] = { common = "Я рассказал тебе всё, что знаю, путник. Именно тебе предстоит отыскать элементий и уничтожить воплощение Повелителя огня. Если ты справишься, с тобой пребудет благословение Громораана." },
    ["7786c"] = { common = "Даже во сне я не чаял увидеть этот день. Зри же, смертный. УЗРИ ТОГО, КТО СТАРШЕ СУЩЕГО! УЗРИ ТОГО, КТО СРАЖАЛСЯ С ТИТАНОМ И БОГОМ! ВОССТАНЬ, МОЙ ПОВЕЛИТЕЛЬ! ОТРИНЬ ОКОВЫ!" },
    ["7787a"] = { common = "Ты одолел Искателя Ветра. Отнеси этой лживой предательской скотине, Демитриану, дремлющий клинок и заставь его воспользоваться предоставленными ему материалами и пробудить Громовую ярость." },
    ["7787c"] = { common = "Прошу, не трогай меня! Возьми, что тебе нужно! Возьми клинок! Позволь Демитриану собирать осколки своей никчёмной жизни." },
    ["7788a"] = { male = "Юный герой! Миновав этот проход, ты увидишь поле яростных сражений. Орда продолжает вырубать наши священные леса, уничтожая вечнозелёные кроны, чтобы питать свою военную машину! Отправляйся в Ущелье Песни Войны, чтобы оборонять Заставу Среброкрылых! Отражай нападения ордынских захватчиков! Наградой тебе будет талисман заслуг. Принеси мне такой талисман, и получишь награду!", female = "Юная героиня! Миновав этот проход, ты увидишь поле яростных сражений. Орда продолжает вырубать наши священные леса, уничтожая вечнозелёные кроны, чтобы питать свою военную машину! Отправляйся в Ущелье Песни Войны, чтобы оборонять Заставу Среброкрылых! Отражай нападения ордынских захватчиков! Наградой тебе будет талисман заслуг. Принеси мне такой талисман, и получишь награду!" },
    ["7789a"] = { male = "Чащобы Ясеневого леса падут пред мощью Орды, герой! Что бы ни делали Среброкрылые Часовые, им не совладать с нашим напором. Калимдор – это владения Орды! Как смеют они препятствовать нам пользоваться тем, что по праву наше? Пусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду! Разгроми Среброкрылых Часовых и заслужи почётный лощины Песни Войны. Вернись ко мне с этим знаком – и получишь награду!", female = "Чащобы Ясеневого леса падут пред мощью Орды, героиня! Что бы ни делали Среброкрылые Часовые, им не совладать с нашим напором. Калимдор – это владения Орды! Как смеют они препятствовать нам пользоваться тем, что по праву наше? Пусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду! Разгроми Среброкрылых Часовых и заслужи почётный лощины Песни Войны. Вернись ко мне с этим знаком – и получишь награду!" },
    ["7789c"] = { male = "Капитан Лободроб одобрительно порыкивает. И сколько ещё они смогут так продержаться? Сколько ещё солдат Альянса должно погибнуть, чтобы они поняли, что пора отступать? Время покажет, путник, время покажет...", female = "Капитан Лободроб одобрительно порыкивает. И сколько ещё они смогут так продержаться? Сколько ещё солдат Альянса должно погибнуть, чтобы они поняли, что пора отступать? Время покажет, путница, время покажет..." },
    ["7791c"] = { common = "Прекрасно! Путник, благодарим тебя за щедрое пожертвование!" },
    ["7792c"] = { common = "Спасибо за щедрость, путник." },
    ["7793c"] = { common = "Прекрасно! Путник, благодарим тебя за щедрое пожертвование!" },
    ["7794c"] = { common = "Прекрасно! Путник, благодарим тебя за щедрое пожертвование!" },
    ["7795c"] = { common = "Невероятно! Уверяю тебя, эти отрезки пойдут на правое дело. Ещё раз спасибо тебе за помощь! Мы бы без тебя не справились. Если ты решишь пожертвовать ещё рунической ткани, то я с радостью приму её от тебя. Только не забудь переговорить со мной, я лично проконтролирую, чтобы твои добрые дела не остались незамеченными!" },
    ["7798c"] = { common = "Спасибо за щедрость, путник." },
    ["7799c"] = { common = "Прекрасно! Путник, благодарим тебя за щедрое пожертвование!" },
    ["7800c"] = { common = "Невероятно! Уверяю тебя, эти отрезки пойдут на правое дело. Ещё раз спасибо тебе за помощь! Мы бы без тебя не справились. Если ты решишь пожертвовать ещё рунической ткани, то я с радостью приму её от тебя. Только не забудь переговорить со мной, я лично проконтролирую, чтобы твои добрые дела не остались незамеченными!" },
    ["7802c"] = { common = "Прекрасно! Путник, благодарим тебя за щедрое пожертвование!" },
    ["7803c"] = { common = "Прекрасно! Путник, благодарим тебя за щедрое пожертвование!" },
    ["7804c"] = { common = "Прекрасно! Путник, благодарим тебя за щедрое пожертвование!" },
    ["7805c"] = { common = "Невероятно! Уверяю тебя, эти отрезки пойдут на правое дело. Ещё раз спасибо тебе за помощь! Мы бы без тебя не справились. Если ты решишь пожертвовать ещё рунической ткани, то я с радостью приму её от тебя. Только не забудь переговорить со мной, я лично проконтролирую, чтобы твои добрые дела не остались незамеченными!" },
    ["7807c"] = { common = "Прекрасно! Путник, благодарим тебя за щедрое пожертвование!" },
    ["7808c"] = { common = "Прекрасно! Путник, благодарим тебя за щедрое пожертвование!" },
    ["7809c"] = { common = "Прекрасно! Путник, благодарим тебя за щедрое пожертвование!" },
    ["7810a"] = { common = "Должно быть, стать мастером арены не так просто! Быть может, пират-распорядитель на Арене Гурубаши, знает, в чём тут штука!" },
    ["7810c"] = { male = "Арр, бей-круши! Чтобы получить право называться мастером Арены, одного значка недостаточно! Пора тебе показать, на что ты действительно способен.", female = "Арр, бей-круши! Чтобы получить право называться мастером Арены, одного значка недостаточно! Пора тебе показать, на что ты действительно способна." },
    ["7811c"] = { common = "Невероятно! Уверяю тебя, эти отрезки пойдут на правое дело. Ещё раз спасибо тебе за помощь! Мы бы без тебя не справились. Если ты решишь пожертвовать ещё рунической ткани, то я с радостью приму её от тебя. Только не забудь переговорить со мной, я лично проконтролирую, чтобы твои добрые дела не остались незамеченными!" },
    ["7813c"] = { common = "Прекрасно! Путник, благодарим тебя за щедрое пожертвование!" },
    ["7814c"] = { common = "Прекрасно! Путник, благодарим тебя за щедрое пожертвование!" },
    ["7815a"] = { common = "Ты не смотри, что у них такие большие красивые глазки! Страшней морского хрустогрыза зверя нет! Только я удочку закину, как приплывают эти черепахи-переростки, жрут мне всю наживку и удилище пополам ломают! Сделай мне и всей нашей деревеньке одолжение – поубивай их всех. В смысле, хрустогрызов." },
    ["7815c"] = { common = "Ох, друг! Я не могу тебя отблагодарить! Надеюсь, этой удочки хватит за работу." },
    ["7816a"] = { common = "Йоу! Тут живёт всем черепахам черепаха – звать Гаммерита – предводительница всех морских хрустогрызов и просто наглая прожорливая рептилия, чтоб ей. Она сожрала мою лучшую блесну! Взяла и откусила прямо с удочки! С тех пор рыба совсем клевать перестала. Найди Гаммериту и вытащи у неё из брюха мою блесну!" },
    ["7816c"] = { male = "ДРУЖИЩЕ!!! Ну и дела! Блесна есть, хрустогрызов нет, да я сейчас всю рыбу в море переловлю!", female = "ПОДРУГА!!! Ну и дела! Блесна есть, хрустогрызов нет, да я сейчас всю рыбу в море переловлю!" },
    ["7817c"] = { common = "Прекрасно! Путник, благодарим тебя за щедрое пожертвование!" },
    ["7818c"] = { common = "Невероятно! Уверяю тебя, эти отрезки пойдут на правое дело. Ещё раз спасибо тебе за помощь! Мы бы без тебя не справились. Если ты решишь пожертвовать ещё рунической ткани, то я с радостью приму её от тебя. Только не забудь переговорить со мной, я лично проконтролирую, чтобы твои добрые дела не остались незамеченными!" },
    ["7820c"] = { common = "Прекрасно! Путник, благодарим тебя за щедрое пожертвование!" },
    ["7821c"] = { common = "Прекрасно! Путник, благодарим тебя за щедрое пожертвование!" },
    ["7822c"] = { common = "Прекрасно! Путник, благодарим тебя за щедрое пожертвование!" },
    ["7823c"] = { common = "Невероятно! Уверяю тебя, эти отрезки пойдут на правое дело. Ещё раз спасибо тебе за помощь! Мы бы без тебя не справились. Если ты решишь пожертвовать ещё рунической ткани, то я с радостью приму её от тебя. Только не забудь переговорить со мной, я лично проконтролирую, чтобы твои добрые дела не остались незамеченными!" },
    ["7824c"] = { common = "Невероятно! Уверяю тебя, эти отрезки пойдут на правое дело. Ещё раз спасибо тебе за помощь! Мы бы без тебя не справились. Если ты решишь пожертвовать ещё рунической ткани, то я с радостью приму её от тебя. Только не забудь переговорить со мной, я лично проконтролирую, чтобы твои добрые дела не остались незамеченными!" },
    ["7826c"] = { common = "Прекрасно! Путник, благодарим тебя за щедрое пожертвование!" },
    ["7827c"] = { common = "Прекрасно! Путник, благодарим тебя за щедрое пожертвование!" },
    ["7828a"] = { male = "В диких лесах Внутренних земель погибло много храбрых троллей, герой. Одни из самых опасных животных там – среброгривые волки. Они прячутся в высокой траве и всегда нападают неожиданно. Нельзя закрывать глаза на такую опасность! Уменьшите поголовье среброгривов!", female = "В диких лесах Внутренних земель погибло много храбрых троллей, героиня. Одни из самых опасных животных там – среброгривые волки. Они прячутся в высокой траве и всегда нападают неожиданно. Нельзя закрывать глаза на такую опасность! Уменьшите поголовье среброгривов!" },
    ["7828c"] = { male = "Великолепно, путник. Благодарю тебя от имени племени Сломанного Клыка.", female = "Великолепно, путница. Благодарю тебя от имени племени Сломанного Клыка." },
    ["7829a"] = { male = "Одни из самых мерзких существ во Внутренних землях – дикие совухи. Сколько храбрых воинов Сломанного Клыка они уже разорвали своими когтями и клювами... Убейте всех диких совухов, которых встретите, герой. Ваша помощь будет взвешена, измерена и по достоинству оценена.", female = "Одни из самых мерзких существ во Внутренних землях – дикие совухи. Сколько храбрых воинов Сломанного Клыка они уже разорвали своими когтями и клювами... Убейте всех диких совухов, которых встретите, героиня. Ваша помощь будет взвешена, измерена и по достоинству оценена." },
    ["7829c"] = { common = "Вы доказали, что вы – преданный союзник племени Сломанного Клыка. Молодец." },
    ["7830a"] = { common = "Мерзавцы из клана Громового Молота учат своих грифонов убивать троллей. Ужасно, конечно, но не беспокойтесь, мы этого так не оставим. Пока что я хочу, чтобы вы уничтожили местных предводителей грифонов. Этих остроклювов зовут ещё повелителями небес. Убейте одного из них и принесите мне его перо." },
    ["7830c"] = { common = "Мархор изучает перо. Интересно, сколько наших охотников сожрало это чудовище, прежде чем вы воздали ему по заслугам?" },
    ["7831c"] = { common = "Прекрасно! Путник, благодарим тебя за щедрое пожертвование!" },
    ["7833c"] = { common = "Прекрасно! Путник, благодарим тебя за щедрое пожертвование!" },
    ["7834c"] = { common = "Прекрасно! Путник, благодарим тебя за щедрое пожертвование!" },
    ["7835c"] = { common = "Прекрасно! Путник, благодарим тебя за щедрое пожертвование!" },
    ["7836c"] = { common = "Невероятно! Уверяю тебя, эти отрезки пойдут на правое дело. Ещё раз спасибо тебе за помощь! Мы бы без тебя не справились. Если ты решишь пожертвовать ещё рунической ткани, то я с радостью приму её от тебя. Только не забудь переговорить со мной, я лично проконтролирую, чтобы твои добрые дела не остались незамеченными!" },
    ["7839a"] = { common = "Эти негодяи из клана Порочной Ветви напали на нашу деревню и украли мои инструменты! У меня, конечно, есть запасные, но тот набор, что они уволокли, был мне дорог как память. Когда я был ещё мальчишкой, мне спас жизнь один гном, а потом он подарил мне тот набор. Я очень хочу вернуть их, я без них как без рук! Мархор сказал, что мои инструменты видели в храмах Аголвата и Шаол-Вата, они оба на северо-востоке Внутренних земель. Пожалуйста, верните мне инструменты!" },
    ["7839c"] = { common = "Мои инструменты! О, великий день! Спасибо тебе." },
    ["7840a"] = { common = "Лярд хотел устроить пикник в секретном месте, а потом пришли злые тролли Порочной Ветви и побили Лярда большими палками. Лярд убежал в деревню, но потерял свой обед. Лярд голодный... Может, сходишь в секретное место и найдёшь там мой обед? Лярд боится. Это на севере! Остров на севере, там секретное место!" },
    ["7840c"] = { male = "Лярд берёт у вас огромный кусок мяса и начинает жадно его грызть. Вот, как хорошо! Спасибо, мелкий. Лярд даст тебе в подарок эту специальную корзинку для пикника.", female = "Лярд берёт у вас огромный кусок мяса и начинает жадно его грызть. Вот, как хорошо! Спасибо, мелкая. Лярд даст тебе в подарок эту специальную корзинку для пикника." },
    ["7841a"] = { common = "Клан Громового Молота якшается с нашими врагами и заключает с ними союзы. В этот раз они спутались с высшими эльфами. Убейте любого эльфа из Высокодолья, которого только встретите – пусть их тела послужат предупреждением. С троллями шутки плохи!" },
    ["7841c"] = { male = "Похоже, Сломанный Клык тоже делает успехи в дипломатии, вступив в альянс... с тобой, друг! Хорошо сработано!", female = "Похоже, Сломанный Клык тоже делает успехи в дипломатии, вступив в альянс... с тобой, подруга! Хорошо сработано!" },
    ["7842a"] = { common = "Говорят, что дворфы Громового Молота и их грифоны – друзья не разлей вода. Хоть это и не очень красиво, но нужно воспользоваться этим преимуществом. Сделаем им ещё одно предупреждение. Убейте всех грифонов, каких только встретите во Внутренних землях – это должно подействовать." },
    ["7842c"] = { common = "О, неплохо. Ещё один шаг, и Громовой Молот полетит у нас отсюда вверх тормашками!" },
    ["7843a"] = { male = "*Отхо вручает вам длинное окровавленное копьё, обёрнутое перьями грифона* Вот, берите. Отнесите это на Заоблачный пик, в самый центр тамошнего поселения. Воткните копьё у колодца, пусть эти дворфы знают, что с нами шутки плохи! А потом возвращайтесь ко мне. Надеюсь ещё увидеть вас живым.", female = "*Отхо вручает вам длинное окровавленное копьё, обёрнутое перьями грифона* Вот, берите. Отнесите это на Заоблачный пик, в самый центр тамошнего поселения. Воткните копьё у колодца, пусть эти дворфы знают, что с нами шутки плохи! А потом возвращайтесь ко мне. Надеюсь ещё увидеть вас живой." },
    ["7843c"] = { common = "Ох, и хотел бы я посмотреть на их хари в этот момент? Надеюсь, они теперь упаковывают свои пожитки, чтобы оставить город! Хорошая работа. Отхо наградит тебя." },
    ["7844a"] = { common = "Во Внутренних землях живёт три клана троллей. На этом, собственно, сходство и заканчивается – мы все тролли и мы все живём здесь. Клан Порочной Ветви, как следует из названия, самый отвратительный – тамошние каннибалы едят и троллей, и вообще всех, кто подвернётся. Если бы Зул'джин был здесь, он бы уничтожил всё это отродье одним движением руки! Но Зул'джина с нами нет, поэтому приходится справляться самим. Вот вам задание – пойти и убить троллей из клана Порочной Ветви." },
    ["7844c"] = { male = "Прекрасно сделано, герой. Сам Зул'джин не смог бы сделать работу лучше!!", female = "Прекрасно сделано, героиня. Сам Зул'джин не смог бы сделать работу лучше!!" },
    ["7845a"] = { common = "Однажды ночью клан Порочной Ветви совершил набег на нашу деревню, и похитил моего мужа. Наши разведчики узнали, что он ещё жив и находится в плену на самом верху Джинта'Алора. Они сказали, что недобрая жрица Проклятье хочет принести его в жертву их безлицему кровавому богу Хаккару. Прошу вас, путник, спасите его! Наша деревня не переживёт такой тяжёлой потери." },
    ["7845c"] = { common = "Ты должен действовать быстро, путник. Они явно уже узнали о твоём присутствии здесь." },
    ["7846a"] = { common = "Ключ от моих кандалов у Хита'йи Хранительницы, она в пещере поблизости. Но будьте осторожны, там полно охраны! Убейте Хранительницу и возьмите у неё ключ, иначе мне отсюда не выйти." },
    ["7846c"] = { common = "Наконец-то свобода! Благодарю тебя, путник. Сломанный Клык узнает о твоих заслугах!" },
    ["7847a"] = { common = "Вернитесь к моей жене, старейшине племени Сломанного Клыка! Скажите ей, что со мной всё хорошо, и что скоро я буду дома. Она непременно наградит вас за это известие." },
    ["7847c"] = { common = "Это была хорошая работа, путник! Я вознагражу тебя за твои усилия, будь уверен." },
    ["7849a"] = { common = "Как и многие жители нашей деревни, мой близкий человек погиб в лесу. Это был мой брат-близнец Малькор – он погиб в бою с троллями Порочной Ветви, тогда же, когда пропал муж старейшей клана Зазубренный Клык. Моего брата очень быстро казнили, а его останки бросили на съедение слизнюкам и волкам. Жизнь его мы не уберегли, но душу спасти ещё можно. Пожалуйста, принесите мне его останки." },
    ["7849c"] = { male = "Мой драгоценнейший брат, как мне будет тебя не хватать… Благодарю тебя за твою помощь. Ты значительно вырос в моих глазах!", female = "Моя драгоценнейшая сестра, как мне будет тебя не хватать… Благодарю тебя за твою помощь. Ты значительно выросла в моих глазах!" },
    ["7850a"] = { common = "Тролли из клана Порочной Ветви проявляют в бою необычайную свирепость! Это всё потому, что их околдовала недобрая коварная жрица Ведьмиса. В поселении Джинта'Алор можно найти очень много сосудов с порченой кровью, которые излучают тёмную магию безлицего кровавого бога и наделяют троллей Порочной Ветви сверхъестественными силами, сводя их с ума. Украдите эти сосуды и принесите их мне, чтобы я сняла порчу и ослабила хватку кровавого бога." },
    ["7850c"] = { common = "Тёмная энергия, что собирало племя Порочной Ветви, теперь ушла. Мы должны оставаться настороже, так как наша битва против зла ещё не закончена. Даже если жрица Ведьмиса будет уничтожена, другая вскоре займёт её место." },
    ["7861a"] = { common = "По приказу старейшины племени Сломанного Клыка разыскивается коварная жрица Ведьмиса и её приспешники. Тот, кто убьёт Ведьмису и её стражей Аман'заси, получит отличную награду!" },
    ["7861c"] = { common = "Хороший удар по Порочной Ветви, в самом деле. Тебе причитается, путник, и мы не поскупимся." },
    ["7862a"] = { common = "Капитан стражи Малькор погиб, и теперь эта должность свободна. Если вы хотите стать капитаном стражи в деревне Сломанного Клыка, выполните эти задания и подайте заявление старейшине племени Сломанного Клыка. Уничтожьте берсерков из племени Порочной Ветви. Уничтожьте тёмных охотников из племени Порочной Ветви. Уничтожьте кровопийц из племени Порочной Ветви. Уничтожьте пожирателей душ из клана Порочной Ветви." },
    ["7862c"] = { common = "Вы и правда отлично подходите для такой работы, путник. Примите это в знак признательности и благодарности за ваши старания. Через год я ещё раз пересмотрю все кандидатуры." },
    ["7863c"] = { common = "Ты хорошо зарекомендовал себя, путник, тут сомнений нет! В награду возьми этот пакет! В нём паёк и бинты, которые найдёшь только в Ущелье Песни Войны. Когда в Ущелье тебя ещё больше зауважают, тебе их тут даже продадут. Паёк мы выдаём, если относимся к кому-то дружественно, а бинты — когда уважаем." },
    ["7864c"] = { common = "Ты хорошо зарекомендовал себя, путник, тут сомнений нет! В награду возьми этот пакет! В нём паёк и бинты, которые найдёшь только в Ущелье Песни Войны. Когда в Ущелье тебя ещё больше зауважают, тебе их тут даже продадут. Паёк мы выдаём, если относимся к кому-то дружественно, а бинты — когда уважаем." },
    ["7865c"] = { common = "Ты хорошо зарекомендовал себя, путник, тут сомнений нет! В награду возьми этот пакет! В нём паёк и бинты, которые найдёшь только в Ущелье Песни Войны. Когда в Ущелье тебя ещё больше зауважают, тебе их тут даже продадут. Паёк мы выдаём, если относимся к кому-то дружественно, а бинты — когда уважаем." },
    ["7866c"] = { common = "Ты хорошо зарекомендовал себя, путник, тут сомнений нет! В награду возьми этот пакет! В нём паек и бинты, которые найдёшь только в Ущелье Песни Войны. Когда в Ущелье тебя ещё больше зауважают, тебе их тут даже продадут. Паек мы выдаём, если относимся к кому-то дружественно, а бинты — когда уважаем." },
    ["7867c"] = { common = "Ты хорошо зарекомендовал себя, путник, тут сомнений нет! В награду возьми этот пакет! В нём паек и бинты, которые найдёшь только в Ущелье Песни Войны. Когда в Ущелье тебя ещё больше зауважают, тебе их тут даже продадут. Паек мы выдаём, если относимся к кому-то дружественно, а бинты — когда уважаем." },
    ["7868c"] = { common = "Ты хорошо зарекомендовал себя, путник, тут сомнений нет! В награду возьми этот пакет! В нём паек и бинты, которые найдёшь только в Ущелье Песни Войны. Когда в Ущелье тебя ещё больше зауважают, тебе их тут даже продадут. Паек мы выдаём, если относимся к кому-то дружественно, а бинты — когда уважаем." },
    ["7871a"] = { male = "Юный герой! Миновав этот проход, ты увидишь поле яростных сражений. Орда продолжает вырубать наши священные леса, уничтожая вечнозелёные кроны, чтобы питать свою военную машину! Отправляйся в Ущелье Песни Войны, чтобы оборонять Заставу Среброкрылых! Отражай нападения ордынских захватчиков! Наградой тебе будет талисман заслуг. Принеси мне такой талисман, и получишь награду!", female = "Юная героиня! Миновав этот проход, ты увидишь поле яростных сражений. Орда продолжает вырубать наши священные леса, уничтожая вечнозелёные кроны, чтобы питать свою военную машину! Отправляйся в Ущелье Песни Войны, чтобы оборонять Заставу Среброкрылых! Отражай нападения ордынских захватчиков! Наградой тебе будет талисман заслуг. Принеси мне такой талисман, и получишь награду!" },
    ["7872a"] = { male = "Юный герой! Миновав этот проход, ты увидишь поле яростных сражений. Орда продолжает вырубать наши священные леса, уничтожая вечнозелёные кроны, чтобы питать свою военную машину! Отправляйся в Ущелье Песни Войны, чтобы оборонять Заставу Среброкрылых! Отражай нападения ордынских захватчиков! Наградой тебе будет талисман заслуг. Принеси мне такой талисман, и получишь награду!", female = "Юная героиня! Миновав этот проход, ты увидишь поле яростных сражений. Орда продолжает вырубать наши священные леса, уничтожая вечнозелёные кроны, чтобы питать свою военную машину! Отправляйся в Ущелье Песни Войны, чтобы оборонять Заставу Среброкрылых! Отражай нападения ордынских захватчиков! Наградой тебе будет талисман заслуг. Принеси мне такой талисман, и получишь награду!" },
    ["7874a"] = { male = "Чащобы Ясеневого леса падут пред мощью Орды, герой! Что бы ни делали Среброкрылые Часовые, им не совладать с нашим напором. Калимдор – это владения Орды! Как смеют они препятствовать нам пользоваться тем, что по праву наше? Пусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду! Разгроми Среброкрылых Часовых и заслужи почётный знак Ущелья Песни Войны. Вернись ко мне с этим знаком – и получишь награду!", female = "Чащобы Ясеневого леса падут пред мощью Орды, героиня! Что бы ни делали Среброкрылые Часовые, им не совладать с нашим напором. Калимдор – это владения Орды! Как смеют они препятствовать нам пользоваться тем, что по праву наше? Пусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду! Разгроми Среброкрылых Часовых и заслужи почётный знак Ущелья Песни Войны. Вернись ко мне с этим знаком – и получишь награду!" },
    ["7874c"] = { male = "Капитан Лободроб одобрительно порыкивает. И сколько ещё они смогут так продержаться? Сколько ещё солдат Альянса должно погибнуть, чтобы они поняли, что пора отступать? Время покажет, путник, время покажет…", female = "Капитан Лободроб одобрительно порыкивает. И сколько ещё они смогут так продержаться? Сколько ещё солдат Альянса должно погибнуть, чтобы они поняли, что пора отступать? Время покажет, путница, время покажет…" },
    ["7875a"] = { male = "Чащобы Ясеневого леса падут пред мощью Орды, герой! Что бы ни делали часовые из клана Среброкрылых, им не совладать с нашим напором. Калимдор – это владения Орды! Как смеют они препятствовать нам пользоваться тем, что по праву наше? Пусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду! Разгроми часовых из клана Среброкрылых и заслужи почётный знак Ущелья Песни Войны. Вернись ко мне с этим знаком – и получишь награду!", female = "Чащобы Ясеневого леса падут пред мощью Орды, героиня! Что бы ни делали часовые из клана Среброкрылых, им не совладать с нашим напором. Калимдор – это владения Орды! Как смеют они препятствовать нам пользоваться тем, что по праву наше? Пусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду! Разгроми часовых из клана Среброкрылых и заслужи почётный знак Ущелья Песни Войны. Вернись ко мне с этим знаком – и получишь награду!" },
    ["7875c"] = { male = "Капитан Лободроб одобрительно порыкивает. И сколько ещё они смогут так продержаться? Сколько ещё солдат Альянса должно погибнуть, чтобы они поняли, что пора отступать? Время покажет, путник, время покажет…", female = "Капитан Лободроб одобрительно порыкивает. И сколько ещё они смогут так продержаться? Сколько ещё солдат Альянса должно погибнуть, чтобы они поняли, что пора отступать? Время покажет, путница, время покажет…" },
    ["7877a"] = { common = "В библиотеке, Читальне, ты найдёшь древний сундук, спрятанный под лестницей. Можешь взять оттуда, что тебе понравится." },
    ["7877c"] = { common = "Вы открываете сундук чтобы найти…" },
    ["7905a"] = { common = "Грядёт Ярмарка Новолуния! Готовься испытать все её чудеса и радости, когда она прибудет в наш город! Если ты поторопишься, то сможешь обменять этот сертификат на призовой купон! Надо только передать сертификат Гельвасу Угольному Шлюзу в ярмарочном лагере. Сейчас ярмарка стоит рядом со Златоземьем, в Элвиннском лесу. Не упусти шанса! Отправляйся прямо сегодня!" },
    ["7905c"] = { common = "Добро пожаловать на ярмарку Новолуния! Этот сертификат на ПЯТЬ, да, целых ПЯТЬ призовых купонов! Когда у вас будет их побольше, обратитесь ко мне, и я обменяю их на ценные призы. Чем больше вы получите купонов, тем больше выиграете призов. Вперёд!" },
    ["7908a"] = { common = "Должно быть, стать мастером арены не так просто! Быть может, пират-распорядитель на Арене Гурубаши, знает, в чём тут штука!" },
    ["7926a"] = { common = "Грядёт ярмарка Новолуния! Когда она прибудет в город, веселью и чудесам не будет конца! А если ты поторопишься, то сможешь обменять этот сертификат на бесплатные призовые купоны! Не забудь передать свой сертификат Гельвасу Угольному Шлюзу в ярмарочном лагере. Сейчас ярмарка стоит рядом с Громовым Утёсом, в Мулгоре. Не упусти свой шанс! Отправляйся прямо сегодня!" },
    ["7926c"] = { common = "Добро пожаловать на ярмарку Новолуния! Этот сертификат на ПЯТЬ, да, целых ПЯТЬ призовых купонов! Когда у вас будет их побольше, обратитесь ко мне, и я обменяю их на ценные призы. Чем больше вы получите купонов, тем больше выиграете призов. Вперёд!" },
    ["7961a"] = { common = "Кролики плодятся с бешеной скоростью! Надо что-то делать! Помоги нам, ты наша единственная надежда!" },
    ["7962a"] = { common = "Мне нужны шкурки кроликов Лекрафта. Добудь мне несколько штук. Это важно!" },
    ["8049c"] = { common = "Прими этот талисман, как знак нашей признательности, герой. Иногда возвращайся ко мне и я буду улучшать твой талисман." },
    ["8050c"] = { common = "Будь твёрд в своих начинаниях, путник." },
    ["8051c"] = { common = "Продолжай свою борьбу, путник." },
    ["8052c"] = { common = "Уничтожь их всех…" },
    ["8056a"] = { common = "Авгуры нашего племени очень гордятся своим даром предвидения. Это тебе не знахари, которые только и знают, что проклинать направо и налево! Нет, наши авгуры предсказывают будущее по костям и листьям. Тебе, как шаману, должно быть известно, на что способны авгуры. В Зандаларе их откровения очень ценятся. Покажи нам, чего ты стоишь, и принеси Знаки Силы из Зул'Гуруба. Если тебе это удастся, я отдам тебе наручи, которыми наши авгуры очень дорожат." },
    ["8056c"] = { common = "Кажется, я стала одной из немногих, кто верит в тебя. Мы знаем о твоих подвигах в Зул'Гурубе. Возьми эти наручи, путник. Ты заработал их." },
    ["8057a"] = { common = "Гаруспики играют не последнюю роль в нашем племени; если ты достаточно мудр, то обязательно прислушаешься к их предсказаниям. Они читают судьбу по внутренностям животных и приносят их в жертву духам, чтобы узнать божественную волю. Именно мудрость гаруспиков дала нам преимущество в войне с разрозненными племенами империи Гурубаши. Докажи нашему племени, чего ты стоишь. Принеси из Зул'Гуруба Знаки Силы, и я отдам тебе наручи, от которых не отказался бы никто из гаруспиков Зандалара." },
    ["8057c"] = { common = "Да, я чувствую Знак Силы, путник. Сделка есть сделка, путник… Вот твои наручи зандаларского гаруспика." },
    ["8059a"] = { common = "Чернокнижники ступают на опасную почву, заключая сделки с демонами, но наши бесноватые зашли ещё дальше. С помощью древнего ритуала они позволяют демону захватить своё тело, а потом пытаются подчинить его своей воле и использовать его силу. Совершить такой подвиг удаётся не многим. Если хочешь приобщиться к знанию бесноватых, принеси мне Знаки Силы из Зул'Гуруба." },
    ["8059c"] = { common = "Отлично… Прими эти дьявольские напульсники." },
    ["8060a"] = { common = "Маги нашего племени — это творцы иллюзий. В свои чары они вплетают заклинания, одурманивающие врагов и сбивающие их с толку. Наблюдать за работой настоящего мастера иллюзий — истинное удовольствие. Ты можешь видеть, как враг уничтожает себя сам, всё больше и больше погружаясь в безумие. Если хочешь узнать о мастерах иллюзий побольше, ступай в Зул'Гуруб и принеси мне Знаки Силы. Взамен я отдам тебе напульсники, которые использовали наши мастера иллюзий, творя свои заклинания." },
    ["8060c"] = { common = "Впечатляюще… Ты хорошо поработал сегодня — считай себя другом Зандаларов. Вот, как я и обещал, наручи." },
    ["8061a"] = { common = "В Зандаларе принято одаривать силой тех, кто общается с богами и власть имущими. Наши жрецы не просто целители — они исповедники нашего племени. Зло приходит как снаружи — из Зул'Гуруба, так и изнутри. Наши исповедники — наши судьи, которые оберегают нас от того зла, что поглотило Гурубаши. Ступай в Зул'Гуруб и принеси Знаки Силы. Узнай, что значит быть исповедником, и охрани нас от зла." },
    ["8061c"] = { common = "Превосходно, путник! Без сомнения, тобой был проделан великий подвиг. Теперь, Зандалары могут считать тебя своим другом." },
    ["8062a"] = { common = "В тёмные времена, наставшие после падения империи Гурубаши, зандаларские хищники использовали всё своё мастерство, чтобы наше племя сумело выжить. И теперь они воплощают в себе самую сущность охоты. Отправляйся в Зул'Гуруб и докажи, что ты достоин занять место среди хищников Зандалара. Принеси мне Знаки Силы из Зул'Гуруба. Тогда ты сможешь ещё на один шаг приблизиться к тому, чтобы стать одним из немногих хищников нашего племени." },
    ["8062c"] = { common = "Да, мне было видение, у тебя есть Знаки Силы. Твой успех в Зул'Гурубе, очень многих впечатлил. И мне очень приятно знать, что ты являешься другом нашему племени." },
    ["8063a"] = { common = "Безумцы Зандалара чем-то сродни разбойникам, но самое главное — они несут с собой Хаос и разрушение. В те жестокие времена, когда наши племена были раздроблены, боевое безумие помогло нам выстоять против врага. Если бы не оно, мы бы не уцелели. Принеси мне Знаки Силы из Зул'Гуруба, и одна из деталей брони безумцев станет твоей. Впусти боевое безумие в свою душу!" },
    ["8063c"] = { common = "Превосходно, путник… твои достижения в Зул'Гурубе снискали право быть другом для племени Зандалар. Прими эту награду за свои усилия." },
    ["8064a"] = { common = "Мы в Зандаларе не следуем путями друидов: мы не подстраиваемся под природу, но меняем её согласно нашим желаниям. Тем не менее и среди нас есть те, кто близок к природе. Наши гаруспики всегда умели слушать и понимать её. Чтобы понять дух животного, надо знать, что значит быть одним из них. В этом и заключается истинная сила природы. Принеси мне Знаки Силы из Зул'Гуруба, докажи племени, что тебе можно доверять. Если ты сделаешь это, я отдам тебе могущественный пояс — из тех, что некогда принадлежали гаруспикам Зандалара. В нём сокрыто могучее колдовство!" },
    ["8064c"] = { common = "Спасибо тебе. Как и было обещано, вот твоя награда." },
    ["8065a"] = { common = "Одежда гаруспиков, путник, — это символ их могущества. Например, мундир — это символ связи между гаруспиком и постигаемой им божественной мудростью. В мундир зашивают части тел животных, принесённых в жертву. Это напоминает гаруспику о связи с его дарами. Докажи племени, чего ты стоишь, и принеси Знаки Силы из Зул'Гуруба. Сделай это, и мундир гаруспиков, хранящий их силу, станет твоим." },
    ["8065c"] = { common = "Впечатляет… ты успешно собрал необходимые Знаки Силы, путник. О твоих подвигах в Зул'Гурубе, Зандалары слагают легенды. Вот твоя награда, герой!" },
    ["8066a"] = { common = "Любой хищник знает, как подкрадываться к добыче, но самый ловкий умеет выбирать лучший момент для удара. Ты должен уметь и подкрадываться, и нападать, чтобы вернуться с добычей из Зул'Гуруба. Принеси мне Знаки Силы. Я обрету могущество, заключённое в них, а ты получишь пояс зандаларского хищника — вещь, ради которой стоит потрудиться." },
    ["8066c"] = { common = "Я чувствовал твоё прибытие, путник. Я знаю о твоих успехах в Зул'Гурубе. Вот твоя награда." },
    ["8067a"] = { common = "В Зандаларе одежда рассказывает о подвигах того, кто её носит. При этом символы наших свершений не обязательно должны быть видимы глазом — излучаемая ими сила говорит сама за себя. Одежда хищников Зандалара обладает именно такими свойствами; более же всего они ценят свои оплечья. Они скрывают своего владельца от чужих взглядов, когда он желает остаться невидимым. В Зул'Гурубе тебя ждут Знаки Силы. Принеси их мне, и это оплечье станет твоим." },
    ["8067c"] = { common = "Превосходно, путник. ты отлично справился с получением Знака Силы. Вот твоя награда." },
    ["8068a"] = { common = "Магия — это бесформенная изначальная сила. Могучие маги управляют её энергией в своих целях. Мы прибегаем к ней в своих заклятиях, но, чтобы создавать иллюзии, нужно особое могущество. Как можно победить врага, который существует только в твоём воображении? В Зандаларе знают цену подобной магии, и мастера иллюзий пользуются большим уважением в племени. Принеси из Зул'Гуруба Знаки Силы, и ты заслужишь уважение племени, а также оплечье мастера иллюзий." },
    ["8068c"] = { common = "Превосходно! Сегодня Зул'Гуруб испытал мощь Зандаларов! И в награду ты получишь оплечье зандаларского иллюзиониста!" },
    ["8069a"] = { common = "В нашем племени одежда — это символ могущества и власти. Она сшита из лучших материалов и усилена заклинаниями, которые дают нам мощь. Одежды мастеров иллюзий отражают самую сущность творимых ими заклятий. Легенды гласят, что одежды мастера иллюзий постоянно меняют свой вид. Я могу дать тебе такие одежды, путник… но сначала покажи племени, на что ты способен. Принеси мне из Зул'Гуруба Знаки Силы!" },
    ["8069c"] = { common = "Неужто ли нашёлся достойный носить одеяние зандаларского иллюзиониста! Твои успехи в Зул'Гурубе приносят нам большой успех, путник!" },
    ["8070a"] = { common = "После падения империи Гурубаши ужасное зло, разъедавшее племя изнутри, охватило и Зандалар. Нас спасли исповедники, которые защищали нас от нас же самих, не давая истреблять себе подобных. До сих пор исповедники охраняют наш дух и стоят на страже наших жизней. Ступай в Зул'Гуруб и узри глубину падения Хаккара и Гурубаши. Вырви из их грязных лап Знаки Силы. В случае успеха тебя ожидает награда." },
    ["8070c"] = { common = "Превосходно! С твоей помощью, мы сделали огромный шаг вперёд. Прими это в знак нашей благодарности, путник." },
    ["8071a"] = { common = "Исповедники Зандалара носят особые оплечья, по которым каждый из нас узнает пастырей племени. Эти оплечья усилены могучими заклятиями, которые помогают почувствовать угрозу, исходящую от врагов племени. Тебе, как жрецу, они очень бы пригодились. Если ты отправишься в Зул'Гуруб, сразишься с приспешниками Хаккара и принесёшь мне нужные Знаки Силы, я отдам тебе оплечье, достойное лучших исповедников." },
    ["8071c"] = { common = "Хорошая работа, путник. Сегодня, приспешники Хаккара почувствовали возмездие Зандаларов! Пожалуйста, прими эту награду." },
    ["8072a"] = { common = "Одним из легендарных безумцев Зандалара был Карвахал Безумный. Легенды гласят, что в боях с врагами племени он применял заклинание \"волна безумия\", наложенное на его оплечья. Врагов поражал ужас, и они видели только мелькание его двойных кинжалов. До сих пор оплечья безумцев — предмет их особой гордости. Принеси мне Знаки Силы из Зул-Гуруба, и они достанутся тебе, чтобы вселять безумие и трепет в твоих врагов." },
    ["8072c"] = { common = "В этот день, победа за нами! Ты должен быть удостоен среди Зандаларов и нет лучшей награды, нежели оплечье зандаларского безумца!" },
    ["8073a"] = { common = "Мои глаза уже давно ничего не видят, но я от этого не страдаю. В нашем племени одежда — символ твоего статуса и могущества, поэтому самые могущественные предметы излучают невидимую глазами силу. Этот мундир зандаларского безумца — не исключение, он пронизан изначальной магией хаоса и безумия, присущих его владельцу. Мне нужны Знаки Силы, которые находятся в Зул'Гурубе. Принеси мне их, и я отдам тебе этот легендарный мундир, который… придётся под стать любому сеятелю безумия." },
    ["8073c"] = { common = "Впечатляюще… сегодня ты сделал то, что многим казалось не возможным. Ты заслужил эту награду." },
    ["8074a"] = { common = "Авгуры многое знают о стихиях, дружище, и используют свои знания во славу нашего племени. В тёмные времена, наступившие после падения империи Гурубаши, именно авгуры привели нас в тихую гавань Южных морей. Они же вернули нас обратно в Долину, в самое сердце зла, свившее себе гнездо в Зул'Гурубе. Принеси Знаки Силы из Зул'Гуруба и докажи племени, чего ты стоишь. Взамен я дам тебе пояс, который служил нашим авгурам. Это не простой пояс, на нём лежит могучее заклинание." },
    ["8074c"] = { common = "Я чувствую аромат победы над злом, путник. Этот сладкий запах… сегодня ты отлично потрудился За это ты удостоен награды!" },
    ["8075a"] = { common = "Все авгуры Зандалара носят хауберки. Они сшиты из лучшего шелка и укреплены прочными кольчужными звеньями. Хауберк — не только символ причастности авгуров к божественному, но и знак их власти. Никто не смеет переходить дорогу тем, кто общается с духами. Докажи свою преданность племени и принеси мне Знаки Силы из Зул'Гуруба. Если тебе удастся сделать это, я отдам тебе лучший из хауберков, который когда-либо носили наши авгуры!" },
    ["8075c"] = { common = "Превосходно, путник. Сегодня тобой было сделано великое дело и ты показал этим приспешникам Хаккара настоящую силу Зандалар. Прими эту награду, в знак нашего почтения к тебе." },
    ["8076a"] = { common = "Бесноватые стремятся полностью слиться с силой, а не просто использовать её. Многие из бесноватых проиграли бой со своим демоном. Но когда враги наступали со всех сторон — особенно в Зул'Гурубе, — победа стоила всех принесённых жертв. От того, сумеем ли мы сокрушить наших врагов, зависит наше существование, — этому нас научило падение империи Гурубаши. Ступай в Зул'Гуруб и добудь необходимые нам Знаки Силы. Наградой тебе будет оплечье бесноватого." },
    ["8076c"] = { common = "Отлично, путник. Знак Силы должен напоминать о силе Зандаларов. Вот твоя награда." },
    ["8077a"] = { common = "Одеяния, в которые мы облачаемся перед битвой, говорят о нашей силе. Одеяние бесноватого создано из рунической ткани, на которую наложено могучее заклятие. Один его вид вселяет страх в сердца врагов… Особенно его боятся демоны, зная, что рано или поздно бесноватый их одолеет и подчинит своей воле. Принеси мне Знаки Силы из Зул'Гуруба. Это непросто сделать… но в случае успеха одеяние бесноватого станет твоим." },
    ["8077c"] = { common = "Превосходная победа в Зул'Гурубе. Прими это зандаларское дьявольское одеяние в знак нашего почтения." },
    ["8101c"] = { common = "Странник, это ожерелье несёт в себе силу горы Каджаро, которая в Южных морях. Как только твоя связь с Зандаларами будет расти, так и это ожерелье будет набирать свою мощь. Используй всю силу ожерелья и нанеси удар по нашим врагам." },
    ["8102c"] = { common = "Будь сильным как гора Каджаро." },
    ["8103c"] = { common = "Продолжай истреблять троллей из Зул'Гуруба. Хаккар должен видеть, что этот мир не будет в его власти." },
    ["8104c"] = { common = "Теперь я усилил твоё ожерелье, настолько, на сколько это было возможным. Используй его, чтобы уничтожить наших врагов." },
    ["8106c"] = { common = "Прими это ожерелье, герой. Прими и используй его, чтобы нанести удар по нашим врагам." },
    ["8107c"] = { common = "Используй силу ожерелья герой. Покажи врагам своё истинное лицо!" },
    ["8108c"] = { common = "Только совместными усилиями мы остановим Свежевателя Душ." },
    ["8109c"] = { common = "Пусть сила Кезана помогает тебе в уничтожении сил Хаккара!" },
    ["8110c"] = { common = "Использовав водоросли Южных морей, мы можем придать ожерелью особой, природной силы. Используй это ожерелье, пусть сила природы поможет тебе." },
    ["8111c"] = { common = "Используй силу ожерелья, чтобы уничтожить наших врагов." },
    ["8112c"] = { common = "Теперь, покажи этим злым троллям в Зул'Гурубе на что способны твои природные силы!" },
    ["8113c"] = { common = "Путник, продолжай подавлять Хаккара и его приспешников." },
    ["8116c"] = { common = "Майвики подарит тебе магическое ожерелье, герой!" },
    ["8117c"] = { common = "Остерегайся злых духов Хаккара. Честно говоря, они очень жуткие." },
    ["8118c"] = { common = "Взгляни на это, путник. Сила твоего ожерелья протекает через тебя." },
    ["8119c"] = { common = "Однажды, ты сможешь использовать этот шар, чтобы напрямую обратится ко мне." },
    ["8141c"] = { common = "Мы снова сталкиваемся с силой Хаккара, но только без единой поддержки. Ты и твои союзники должны помочь нам в победе над Богом Крови и его приспешниками! Вот, возьми это ожерелье и пусть оно поможет тебе в твоих путешествиях." },
    ["8142c"] = { common = "Существует несколько усовершенствований этого ожерелья. Когда настанет время, я буду применять это усиление." },
    ["8143c"] = { common = "Твои враги должны научится уважать тебя!" },
    ["8144c"] = { common = "Ты знаешь, что тебе нужно делать. Возьми ожерелье и продолжи своё сражение. Хаккар никогда не должен покинуть пределы Зул'Гуруба." },
    ["8145c"] = { common = "Наши величайшие охотники, путешествовали на край Водоворота, чтобы доказать свою решительность. Они приносили оттуда водоросли, которые называются нити Водоворота и из них создавали ожерелья. Теперь, я дам тебе ожерелье, которое создано из таких растений." },
    ["8146c"] = { common = "Я смогу только применить одно из немногих улучшений, на твоё ожерелье, герой." },
    ["8147c"] = { common = "Пусть они падут от твоего оружия." },
    ["8148c"] = { common = "Твоё путешествие только начинается, герой. Возможно, в один прекрасный день, ты посетишь Водоворот и взглянешь в самое сердце мира. Желаю тебе удачи." },
    ["8151a"] = { common = "Огтинк из Азшары ищет опытных охотников вроде тебя. Огтинк — фурболг-охотник, порвавший со своим племенем ради помощи Кругу Кенария. Он стремится наставлять собратьев по оружию и учить их соблюдению природного равновесия. Тебе не помешает поговорить с ним. Огтинк живёт на скалах Азшары, на северо-востоке от руин Эльдарата." },
    ["8154a"] = { common = "Войну выигрывают солдаты – любой солдат вам это скажет. Скажет он вам и то, что битва, которую ведут с плохим оружием или на пустой желудок, проиграна прежде, чем началась! Вот почему так важна Низина Арати. В этой низине есть ключевые точки, где сосредоточены важные ресурсы. Металл, оружие, пища, древесина – всё это необходимо и всё это можно добыть там. И вот чего я хочу от вас. Отправляйтесь в Низину Арати, выиграйте битву, удержав больше баз, чем это удастся врагам, и принесите мне ящик с ресурсами." },
    ["8154c"] = { male = "У тебя есть ресурсы! Прекрасная работа! Я пошлю их нашим интендантам, которые могут быстро разогнать их по нашим войскам. Спасибо. Действительно, успешное выполнение миссий, подобных той, которую ты выполнил, - вот как действительно выигрывают войны.", female = "У тебя есть ресурсы! Прекрасная работа! Я пошлю их нашим интендантам, которые могут быстро разогнать их по нашим войскам. Спасибо. Действительно, успешное выполнение миссий, подобных той, которую ты выполнила, - вот как действительно выигрывают войны." },
    ["8155a"] = { common = "Войну выигрывают солдаты – любой солдат вам это скажет. Скажет он вам и то, что битва, которую ведут с плохим оружием или на пустой желудок, проиграна прежде, чем началась! Вот почему так важна Низина Арати. В этой низине есть ключевые точки, где сосредоточены важные ресурсы. Металл, оружие, пища, древесина – всё это необходимо и всё это можно добыть там. И вот чего я хочу от вас. Отправляйтесь в Низину Арати, выиграйте битву, удержав больше баз, чем это удастся врагам, и принесите мне ящик с ресурсами." },
    ["8155c"] = { male = "У тебя есть ресурсы! Прекрасная работа! Я пошлю их нашим интендантам, которые могут быстро разогнать их по нашим войскам. Спасибо. Действительно, успешное выполнение миссий, подобных той, которую ты выполнил, - вот как действительно выигрывают войны.", female = "У тебя есть ресурсы! Прекрасная работа! Я пошлю их нашим интендантам, которые могут быстро разогнать их по нашим войскам. Спасибо. Действительно, успешное выполнение миссий, подобных той, которую ты выполнила, - вот как действительно выигрывают войны." },
    ["8156a"] = { common = "Войну выигрывают солдаты – любой солдат вам это скажет. Скажет он вам и то, что битва, которую ведут с плохим оружием или на пустой желудок, проиграна ещё до своего начала! Вот почему так важна Низина Арати. В этой низине есть ключевые точки, где сосредоточено множество ресурсов. Металл, оружие, пища, древесина – всё это необходимо и всё это можно добыть там. И вот чего я хочу от вас. Отправляйтесь в Низину Арати, выиграйте битву, удержав больше баз, чем это удастся врагам, и принесите мне ящик с ресурсами." },
    ["8156c"] = { male = "У тебя есть ресурсы! Прекрасная работа! Я пошлю их нашим интендантам, которые могут быстро разогнать их по нашим войскам. Спасибо. Действительно, успешное выполнение миссий, подобных той, которую ты выполнил, - вот как действительно выигрывают войны.", female = "У тебя есть ресурсы! Прекрасная работа! Я пошлю их нашим интендантам, которые могут быстро разогнать их по нашим войскам. Спасибо. Действительно, успешное выполнение миссий, подобных той, которую ты выполнила, - вот как действительно выигрывают войны." },
    ["8160a"] = { common = "Лига Аратора не жалеет средств, пытаясь вновь захватить контроль над Арати. Они, вместе со всеми расами Альянса, стекаются сейчас в эту отдалённую область с намерением распространить свои владения за пределы Опорного пункта. Мы должны остановить их, а наилучшее средство для этого – захватить их припасы. Вы, можете нам помочь. Отправляйтесь в Низину Арати, известную своими богатыми рудниками, плодородными почвами и умелыми ремесленниками. Захватите и удерживайте под своим контролем те базы, которые сможете, выиграйте битву и возвращайтесь ко мне с ресурсами, которые вам удастся добыть." },
    ["8161a"] = { common = "Лига Аратора не жалеет средств в попытке вновь захватить контроль над Арати. Они, вместе со всеми расами Альянса, стекаются сейчас в эту отдалённую область, намереваясь распространить свои владения за пределы Опорного пункта. Мы должны остановить их, а наилучшее средство для этого – захватить их припасы. Вы, можете нам помочь. Отправляйтесь в Низину Арати, известную своими богатыми рудниками, плодородными почвами и умелыми ремесленниками. Захватите и удерживайте под своим контролем те базы, которые сможете, выиграйте битву и возвращайтесь ко мне с ресурсами, которые вам удастся добыть." },
    ["8162a"] = { common = "Лига Аратора не жалеет средств в попытке вновь захватить контроль над Арати. Они, вместе со всеми расами Альянса, стекаются сейчас в эту отдалённую область, намереваясь распространить свои владения за пределы Опорного пункта. Мы должны остановить их, а наилучшее средство для этого – захватить их припасы. Вы, можете нам помочь. Отправляйтесь в Низину Арати, известную своими богатыми рудниками, плодородными почвами и умелыми ремесленниками. Захватите и удерживайте под своим контролем те базы, которые сможете, выиграйте битву и возвращайтесь ко мне с ресурсами, которые вам удастся добыть." },
    ["8166a"] = { common = "Битва за Низину Арати – это битва за ресурсы и за территорию. Ключевые точки на этой местности нужно удерживать, чтобы обеспечить наши силы поставками сырья и различных припасов. Я отдаю вам приказ атаковать самые дальние от нашей базы в Низине Арати точки. Совершите нападение на ферму, рудник, лесопилку и кузницу, когда они будут находиться под контролем врага. Найдите вражеское знамя и сорвите его с флагштока! Когда сумеете сделать это на четырёх указанных базах, возвращайтесь ко мне." },
    ["8166c"] = { common = "Я получил сообщения о ваших подвигах в Низине Арати. Отлично сработано! С теми, кто, как вы, присоединяется к борьбе здесь, я верю,что однажды мы вернём наши родные земли." },
    ["8167a"] = { common = "Битва за Низину Арати – это битва за ресурсы и за территорию. Ключевые точки на этой местности нужно удерживать, чтобы обеспечить наши силы поставками сырья и различных припасов. Я отдаю вам приказ атаковать самые дальние от нашей базы в Низине Арати точки. Совершите нападение на ферму, рудник, лесопилку и кузницу, когда они будут находиться под контролем врага. Найдите вражеское знамя и сорвите его с флагштока! Когда сумеете сделать это в четырёх указанных точках, возвращайтесь ко мне." },
    ["8167c"] = { common = "Я получил сообщения о ваших подвигах в Низине Арати. Отлично сработано! С теми, кто, как вы, присоединяется к борьбе здесь, я верю,что однажды мы вернём наши родные земли." },
    ["8168a"] = { common = "Битва за Низину Арати – это битва за ресурсы и за территорию. Ключевые точки на этой местности нужно удерживать, чтобы обеспечить наши силы поставками сырья и различных припасов. Я отдаю вам приказ атаковать самые дальние от нашей базы в Низине Арати точки. Совершите нападение на ферму, рудник, лесопилку и кузницу, когда они будут находиться под контролем врага. Найдите вражеское знамя и сорвите его с флагштока! Когда сумеете сделать это в четырёх указанных точках, возвращайтесь ко мне." },
    ["8168c"] = { common = "Я получил сообщения о ваших подвигах в Низине Арати. Отлично сработано! С теми, кто, как вы, присоединяется к борьбе здесь, я верю,что однажды мы вернём наши родные земли." },
    ["8169a"] = { common = "Как вы, конечно, слышали, Лига Аратора посылает огромное количество войск в Низину Арати. Жадные до пищи и припасов, эти идиоты из Альянса намереваются захватить под свой контроль тамошние богатые источники ресурсов. Мы должны показать им, что Арати никогда больше не будет домом для людей! Отправляйтесь в Низину Арати и нападите на рудник, лесопилку, кузницу и стойла. Стащите с флагштоков вражеские знамёна, заявив о правах Орды на эти территории. Идите. Доложите мне, когда выполните задание." },
    ["8169c"] = { male = "Разведчик Осквернителя пришёл ко мне с отчётом о твоём успехе. Молодец. Как ты знаешь, чтобы выиграть битву за Низину Арати, мы должны быть всегда бдительны и пресекать любые попытки расширения Альянса. Сделаем это и наша победа здесь обеспечена.", female = "Разведчик Осквернителя пришёл ко мне с отчётом о твоём успехе. Умница. Как ты знаешь, чтобы выиграть битву за Низину Арати, мы должны быть всегда бдительны и пресекать любые попытки расширения Альянса. Сделаем это и наша победа здесь обеспечена." },
    ["8170a"] = { common = "Как вы, конечно, слышали, Лига Аратора посылает огромное количество войск в Низину Арати. Жадные до пищи и припасов, эти идиоты из Альянса намереваются захватить под свой контроль тамошние богатые источники ресурсов. Мы должны показать им, что Арати никогда больше не будет домом для людей! Отправляйтесь в Низину Арати и нападите на рудник, лесопилку, кузницу и стойла. Спустите с флагштоков вражеские знамёна, заявив о правах Орды на эти территории. Идите. Доложите мне, когда выполните задание." },
    ["8170c"] = { male = "Разведчик Осквернителя пришёл ко мне с отчётом о твоём успехе. Молодец. Как ты знаешь, чтобы выиграть битву за Низину Арати, мы должны быть всегда бдительны и пресекать любые попытки расширения Альянса. Сделаем это и наша победа здесь обеспечена.", female = "Разведчик Осквернителя пришёл ко мне с отчётом о твоём успехе. Умница. Как ты знаешь, чтобы выиграть битву за Низину Арати, мы должны быть всегда бдительны и пресекать любые попытки расширения Альянса. Сделаем это и наша победа здесь обеспечена." },
    ["8171a"] = { common = "Как вы, конечно, слышали, Лига Аратора посылает огромное количество войск в Низину Арати. Жадные до пищи и припасов, эти идиоты из Альянса намереваются захватить под свой контроль тамошние богатые источники ресурсов. Мы должны показать им, что Арати никогда больше не будет домом для людей! Отправляйтесь в Низину Арати и нападите на рудник, лесопилку, кузницу и стойла. Сорвите с флагштоков вражеские знамёна, заявив о правах Орды на эти территории. Идите. Доложите мне, когда выполните задание." },
    ["8171c"] = { male = "Разведчик Осквернителя пришёл ко мне с отчётом о твоём успехе. Молодец. Как ты знаешь, чтобы выиграть битву за Низину Арати, мы должны быть всегда бдительны и пресекать любые попытки расширения Альянса. Сделаем это и наша победа здесь обеспечена.", female = "Разведчик Осквернителя пришёл ко мне с отчётом о твоём успехе. Умница. Как ты знаешь, чтобы выиграть битву за Низину Арати, мы должны быть всегда бдительны и пресекать любые попытки расширения Альянса. Сделаем это и наша победа здесь обеспечена." },
    ["8181a"] = { common = "Дурные вести, путник. Если верить табличкам Мошару, то подлинная сущность Хаккара, то есть само божество, может родиться из того самого яйца, в которое тебе удалось его заключить. Йе'кинья обманул тебя, он хотел привести в мир Хаккара! Ступай к этому негодяю и потребуй, чтобы он вернул тебе яйцо. Остаётся молиться, чтобы можно было предотвратить возрождение Хаккара!" },
    ["8181c"] = { common = "Так ты говорил со старым дворфом Железным Башмаком и обнаружил потерянные таблички Мошару, не так ли? Ох, это вмешательство геологов… Не важно. Слишком поздно спасать этот мир. Хаккар возродился и даже сейчас набирает свою силу… глубоко в древнем королевстве троллей Зул'Гурубе! Он пришёл! И будет править в крови и ужасе! Спасибо, путник. Твоя помощь ускорила возвращение Свежевателя Душ!" },
    ["8182a"] = { common = "Все наши самые жуткие страхи сбываются. В легендах говорилось о Свежевателе Душ, правившем миром древних троллей злом и жестокостью. Сила его была беспредельна. Если его не остановить, он снова воцарится в Азероте! Тролли Зандалара могут остановить наступление тьмы. Они живут на острове Йоджамба, недалеко от побережья Тернистой долины, к западу от Руин Зул'Кунды. Поговори с их вождём, Молтором. Будем надеяться, что он знает, как одолеть Хаккара." },
    ["8182c"] = { common = "Тебя направил геолог Железный Башмак? Он выглядит мудро, особенно когда прислал тебя ко мне, ибо я и тролли Зандалар знаем способ победить Свежевателя Душ. Поговори со здешними троллями и прислушайся к их словам, чтобы подготовить себя к сражению, путник." },
    ["8183a"] = { common = "Сердце Хаккара пылает изнутри. Свежеватель Душ повержен, но ключ к его силе — всё ещё в его сердце." },
    ["8183c"] = { common = "А, то самое сердце Хаккара. Так Свежеватель Душ убит! Наш мир спасён! Путник, ты герой из героев! Герой всех времён и народов!" },
    ["8193c"] = { common = "Скорее сдавай пойманную рыбу, если хочешь заслужить звание лучшего рыболова! Я торчу здесь уже много ЧАСОВ, и даже маковой росинки во рту не было! Давай сюда вкуснорыб!" },
    ["8201a"] = { common = "Это правда. Хаккар теперь обитает в Зул'Гурубе, питаясь силой наших богов. Порабощённые им жрецы направляют энергию самых священных божеств Свежевателю Душ, и скоро сильнее его в Азероте не будет существа. Его надо остановить! Возьми этот священный шнур. Нанижи на него головы верховных жрецов, по вине которых сила наших богов утекает к Хаккару. Сделав это, возвращайся ко мне." },
    ["8201c"] = { common = "Вот это ожерелье! Тебе удалось остановить хищение силы наших богов и ослабить Хаккара! Ты совершил настоящий подвиг, путник. Пусть головы этих презренных троллей продолжают умолять тебя о пощаде — даже после того, как в них остынет кровь" },
    ["8227a"] = { common = "Среди разбросанных рыболовных инструментов лежит свёрнутая шёлковая измерительная лента. К ней прицеплена бирка с надписью: \"Нат Пэгл, Пылевые топи\"." },
    ["8227c"] = { common = "Ты нашёл мою измерительную ленту! Я люблю эту ленту… Я измерял ей самых больших рыб на свете… Но я потерял ленту в Зул'Гурубе… ты был в Зул'Гурубе? Так ты видел Газ'ранку? Ну… так хочешь поймать его?" },
    ["8233a"] = { common = "Лорд Джорах Чёрный Ворон настоятельно приглашает вас к себе. Приглашение тайное, поэтому никаких подробностей. Поместье Чёрный Ворон находится в предгорьях Хилсбрада — горная тропа начинается на северо-западе от крепости Дарнхольд." },
    ["8233c"] = { common = "Привет, привет, привет! Прошу, путник, располагайся по удобнее и давай обсудим одно простое дело. Видишь ли, путник, я потерял кое-что дорогое, и теперь желаю вернуть это любой ценой. Что скажешь, путник… готов к маленькому приключению?" },
    ["8234a"] = { common = "Начнём сначала. Я потерял небольшую сумку голубого цвета. В ней были мои личные вещи. Нет нужды искать воров — они уже мертвы. Мне известно лишь, что эти дураки не сумели открыть сумку и продали её какому-то шаману из племени Древобрюхов в Азшаре, выдав её за священную реликвию. Очень умно. Я хочу, чтобы ты отправился в Азшару и заполучил у шамана мою сумку — хитростью или силой. Полагаю, что лучше всё же хитростью. Сумку отнеси верховному магу Ксилему." },
    ["8234c"] = { male = "Вижу, у тебя сумка лорда Чёрного Ворона. Что ж ты сразу не сказал?", female = "Вижу, у тебя сумка лорда Чёрного Ворона. Что ж ты сразу не сказала?" },
    ["8235a"] = { common = "Лорд Чёрный Ворон просил нас с тобой об услуге. Он желает снять заклятие с этой сумки. К сожалению, мои книги по снятию чар были захвачены и уничтожены дикарями. Каждый клочок, оставшийся от них, невероятно ценен для меня. Если ты сможешь принести мне зашифрованные фрагменты, я попробую восстановить хотя бы часть моих книг. Чтобы найти фрагменты, поохоться на обитающих в Азшаре зверей — они обычно подбирают всё, что плохо лежит." },
    ["8235c"] = { common = "Похоже ты собрал лучшие фрагменты! Хм, возможно ты не так уж бесполезен." },
    ["8236a"] = { common = "Мне потребуется время, чтобы расшифровать фрагменты и снять заклятие. Когда я закончу, то самолично доставлю сумку лорду Чёрному Ворону. Однако нам всё ещё нужен ключ. Говорят, что ключ присвоил зелёный дракон по имени Морфаз. Его логово находится в глубинах Храма Атал'Хаккара — вход в него ты найдёшь на Болоте Печали. Собери своих сподвижников и отправляйся к логову дракона. Лорд Чёрный Ворон ждёт, когда ты принесёшь ему ключ." },
    ["8236c"] = { common = "Ключ! Я думал, что этот ключ потерян навсегда! Пожалуйста, возьми эти лучшие вещи из моего склада. Я не хочу, чтобы потом говорили, что я тебя не вознаградил по заслугам!" },
    ["8240a"] = { common = "Драгоценности Хаккари необходимо уничтожить. Это наше внутреннее дело, но оно настолько важное, что мы просим о помощи и чужеземцев. Отыщи в Зул'Гурубе все драгоценности, которые сможешь, принеси на Алтарь Занзы и уничтожь их. Если ты справишься с этим заданием, я дам тебе почётный знак нашего племени. Знай, что у нас этими знаками не разбрасываются! Ступай, и да пребудет с тобой благословение Занзы!" },
    ["8240c"] = { common = "Прекрасно… каждая драгоценность, которую мы вырываем из прислужников Кровавого Бога, приносит нас на один шаг ближе к тому, чтобы мы, наконец, покончили с ними всеми! Ты принёс честь и славу Зандаларам — и себе своими доблестными действиями. Помни путник, ты можешь уничтожать любые драгоценности которые ты найдёшь в Зул'Гурубе на алтаре. И за каждое ты получишь почётный знак! Только не забудь освободить для него в рюкзаке местечко…" },
    ["8249c"] = { common = "Да найдётся место для твоих клинков в чьём-нибудь сердце. В прямом смысле." },
    ["8250a"] = { common = "Верховный маг Ксилем ищет кого-то… Не менее опытного, чем ты. Если хочешь, поговори с ним. Он живёт в Азшаре, в башне на вершине утёса. Добраться туда можно лишь при помощи заклинания, которое известно его заносчивому слуге, Санату Лим-Йо. Санат живёт в лагере ниже башни своего хозяина. Найти его можно так: там, где главная дорога Азшары разветвляется у входа в руины Эльдарата, поворачивай строго на север и иди, пока не упрёшься в скалы." },
    ["8251a"] = { common = "Эльфы крови в Азшаре изобрели свой способ распылять магические предметы. Получаемая в результате сияющая пыль отличается от элементов, получаемых в результате обычного распыления. Я отправил ученика купить этой пыли, но эльфы безжалостно убили его. Они должны заплатить за это! Время мирных переговоров прошло, путник. Найди эльфов крови в скалах Азшары и примени к ним более… убедительные методы. Мне нужна эта пыль." },
    ["8251c"] = { common = "Прекрасно сделано, путник! Я всегда считал залп чародейских стрел неплохим средством убеждения." },
    ["8252a"] = { common = "Оглянись вокруг. Развалины и всё побережье кишат тварями Бича Злобы. Проклятые создания научились искать редкие вещества и предметы, встречающиеся в Азшаре. Например, эти твари почему-то очень интересуются заколдованными кораллами — по совершенно не ясным мне причинам. Теперь этих кораллов в бухте почти не осталось, а они так нужны мне для исследований! Прошу тебя, отбери несколько кораллов у сирен из клана Бича Злобы и принеси их мне." },
    ["8252c"] = { common = "Прекрасно! Другого я от тебя и не ожидал, путник. Ты нашёл способ как отделять коралл от этих созданий… И не думай что твои усилия остались незамеченными. Возможно ты достоин настоящей проверки твоего искусства…" },
    ["8253a"] = { common = "В глубинах Храма Атал'Хаккара скрывается зелёный дракон по имени Морфаз. Много лет назад он напал на меня из засады и проглотил целиком сопровождавшего меня ученика. Мне не впервой терять учеников, однако именно этот, проглоченный, нёс кристалл тайной магии небывалой мощи. Выбери достаточно сильных соратников и отправляйся в Затонувший храм. Уничтожь Морфаза и принеси мне мой кристалл." },
    ["8253c"] = { common = "Невероятно. Этот кристалл рос и набирался драконьей энергии долгие годы. Больше к тебе никаких поручений не будет. Мои полные способности вернулись ко мне с этим кристаллом. Моё первое творенье уже твоё, путник, и тебе надо лишь выбрать…" },
    ["8254a"] = { common = "Служителям богов пристало помогать попавшим в беду. Как именно — неважно, главное — во имя чего. Кругу Кенария необходима помощь. Если ты хочешь протянуть им руку помощи, поговори с Огтинком. Он живёт на вершинах скал на северо-востоке от руин Эльдарата в Азшаре." },
    ["8257c"] = { common = "Не могу поверить в то, что ты убил Морфаза и принёс его кровь к нам. Я просто не могу поверить в такие хорошие новости. Мы будем перерабатывать все ингредиенты вместе и будем лечить деревья и создания Осквернённого леса. Возможно, это займёт поколение, но мы сделаем это!" },
    ["8258a"] = { common = "Тёмный Терзатель, рыцарь смерти, владычествует над Главным склепом в Некроситете. Он собирается подчинить себе весь мир духов! Его необходимо остановить! Тут-то тебе и понадобится кристальный предсказатель. Приведи его в действие в Главном склепе, чтобы вызвать духов-приспешников Тёмного Терзателя. Когда ты одолеешь этих духов, явится сам рыцарь смерти. Принеси мне его голову, путник! Только его гибель способна исправить урон, нанесённый миру духов!" },
    ["8258c"] = { common = "Прекрасная победа, путник! Гибель Терзателя должна восстановить хрупкий мир духов. Ты согласился на это задание, даже не зная о его награде или сложности. Ты действительно герой. Я знаю, что ещё много нужно времени и усилий чтобы привести к балансу мир духов, но без твоей помощи, это было бы не возможно. Прими эту награду, в знак моей благодарности." },
    ["8273c"] = { common = "Очень интересно. Говоришь что нашёл эту табличку на небольшом, пустынном островке около Отвесных скал, во Внутренних землях, герой? Очень интересно. Я благодарю тебя за твои усилия. Наша Тёмная Госпожа будет очень довольна. Теперь же, позволь мне вознаградить тебя." },
    ["8275a"] = { common = "Внемлите, герои Альянса! Мы слишком долго не обращали внимания на опасность, источник которой — силитиды. Им никто не противостоял, и мерзкие насекомые подготовились к масштабному вторжению. Силы Круга Кенария собираются в Силитусе, чтобы дать отпор силитидам, пока не поздно! Мы не позволим им и дальше осквернять нашу землю! Всё на защиту Азерота! Все способные держать оружие должны пройти инструктаж у призывательницы ветров Гордый Рог в Крепости Кенария!" },
    ["8275c"] = { common = "Отлично, ещё один доброволец готов выступить против силитидов. Добро пожаловать в Крепость Кенария, герой. Я рада, что слова наших посланников привлекают героев вроде тебя. У тебя будет предостаточно возможностей помочь нам, и, думается мне, ты быстро станешь одним из сильнейших наших сторонников." },
    ["8276a"] = { common = "Внемлите, герои Орды! Мы слишком долго не обращали внимания на серьёзную угрозу. Дрожание земли рядом с ульями силитидов говорит о серьёзном возрастании их числа в связи с готовящимся нападением. Силы Круга Кенария собираются в Силитусе, чтобы дать отпор силитидам, пока не поздно! Мы не позволим им и дальше осквернять нашу землю! Все, способные держать оружие, должны обратиться к призывательнице ветров Гордый Рог в Крепости Кенария! Да сгинут силитиды!" },
    ["8276c"] = { common = "Отлично, ещё один доброволец готов выступить против силитидов. Добро пожаловать в Крепость Кенария, герой. Я рада, что слова наших посланников привлекают героев вроде тебя. У тебя будет предостаточно возможностей помочь нам, и, думается мне, ты быстро станешь одним из сильнейших наших сторонников." },
    ["8277a"] = { common = "Битисса Шаткобрус к твоим услугам! Мой кузен Ноггл зарабатывает на жизнь, продавая алхимикам из Крепости Кенария редкие травы. Точнее, зарабатывал. Из последней вылазки он вернулся отравленный страшным ядом. Я сумела замедлить действие яда, но чтобы полностью нейтрализовать его, мне понадобятся образцы яда тех тварей, что ужалили его. Ноггл вернулся с севера, поэтому я готова поспорить, что он пострадал от камнехвостых скорпидов или песчаных пауков-быстролапов. Принеси мне несколько жал и клыков, и я сделаю противоядие." },
    ["8277c"] = { common = "Скрести пальцы, дружище! Будем надеяться, что нам удастся спасти Ноггла!" },
    ["8278a"] = { common = "Проклятье! Противоядие не сработало. Наверное, Ноггла укусила одна из тварей на далёком юге, они гораздо страшнее остальных. Придётся попросить тебя отправиться за образцами, путник. В утешение могу сказать, что поскольку яд у них сильный, мне потребуется не так много образцов, как в прошлый раз. С другой стороны, на юге больше ядовитых тварей, поэтому придётся убить по несколько существ разных видов." },
    ["8278c"] = { common = "Да! Похоже, сработало, Ноггл приходит в себя. Мы у тебя в долгу!" },
    ["8279a"] = { common = "Сумеречный Молот не прощает тех, кто покидает его ряды. Они охотятся за мной, словно за диким зверем! Излишне говорить, что их враги — мои друзья! Чтобы расшифровать эту табличку, мне понадобится книга, которой пользуются их писцы при закодировании тайных посланий, Сумеречный словарь. Эта книга настолько важна, что три её главы держат в разных местах! Главы находятся у особых офицеров, именуемых сумеречными хранителями. Ищи их в лагерях Сумеречного Молота." },
    ["8279c"] = { common = "Ура! Вот они, все части книги! Приступим, путник. Заменить каждое третье слово словами из второй главы… Потом заменить каждое второе слово словами из первой главы… Стоп, я что-то путаю?" },
    ["8280a"] = { common = "Крепость Кенария имеет важнейшее стратегическое значение. Не сомневаюсь, что пока мы удерживаем её, силитидам нас не одолеть. Разумеется, если припасы будут поступать регулярно. Песчаные черви оказались даже большей помехой для наших караванов, чем сами силитиды. Например, сегодня утром землечерпы разграбили большой караван с рассветницей. Необходимо сократить число этих тварей, чтобы обеспечить бесперебойные поставки." },
    ["8280c"] = { common = "Прими мою глубочайшую благодарность. Помогая Крепости Кенария, ты проявил редкое мужество." },
    ["8281a"] = { common = "Ты великолепно себя зарекомендовал, путник. К сожалению, нашему снабжению по-прежнему грозит опасность. Землечерпов теперь нет, но их место несомненно займут их более крупные южные родственники — земляные сокрушители. Чтобы приструнить этих червяков, придётся убить их побольше. Но мы не можем подвергать опасности наше снабжение." },
    ["8281c"] = { common = "Великолепно! Ты оказался ценным союзником в подготовке к войне против силитидов." },
    ["8282a"] = { common = "Где я? Где моя сумка? Наверное, я потерял её, убегая от Смертехвата, огромного скорпида. Я мчался, не разбирая дороги, и забрёл прямо в гнездо камнехвостых живодёров. В моей сумке были ценнейшие реагенты. Без них мы с Битиссой не сможем делать зелья для Крепости Кенария. Я пока не в силах встать, но если ты сможешь вернуть мне реагенты, я тебе отплачу сторицей. На Смертехвата я наткнулся в южных горах, за лагерем Бронзоборода." },
    ["8282c"] = { common = "Да! Ты принёс мне сумку. И все ценные реагенты вместе с ней! Я твой должник на долгие годы." },
    ["8283a"] = { common = "Согласно последним сведениям, ужасный скорпион, Смертехват, отступил в южные горы перед лицом нашествия силитидов. Эта тварь представляет большую угрозу патрулям и экспедициям южных регионов. Тех, кто поспособствует её уничтожению, будет ждать неплохая награда. По вопросам получения награды обращаться к капитану Вишу Коцусу, на вершину сторожевой башни Крепости Кенария." },
    ["8283c"] = { common = "Замечательно! Смертехвата нет, и мы сможем спокойно подобраться к ульям силитидов по южным горам. Мы высоко ценим твою работу." },
    ["8284a"] = { common = "На северо-западе отсюда некогда благоденствовал лагерь служителей культа Сумеречного Молота. Теперь на месте лагеря остались лишь обломки древесины и ткани, среди которых бродят элементали. Мне удалось добыть там несколько кусочков глиняной таблички, но их слишком мало, чтобы узнать что-нибудь ценное. Не сможешь ли ты добыть остальные фрагменты? Быть может, они прольют свет на деятельность Сумеречного Молота в Силитусе." },
    ["8284c"] = { common = "Так я и думала. Я могу перевести отдельные слова, но они лишены смысла. Сумеречный Молот часто пользуется особыми шифрами, чтобы скрыть значение своих текстов от чужих; нужно найти кого-нибудь, кто разбирается в таких вещах." },
    ["8285a"] = { common = "Ходят слухи, что некто по имени Ортелл вышел из рядов Сумеречного Молота. Говорят, он прячется в горах на юге от деревни Южного Ветра и живёт в полном уединении. Может быть, имеет смысл прибегнуть к его помощи в расшифровании таблички. Возьми восстановленную табличку и отнеси её Ортеллу." },
    ["8285c"] = { common = "Вижу, ты не понаслышке знаешь о моей бывшей организации. Должно быть, ты из Крепости Кенария. Тебе нужна информация для борьбы с Сумеречным Молотом? Подойди ближе, может быть, мы сможем помочь друг другу." },
    ["8286a"] = { common = "Я уже почти очутился в объятьях смерти, и тут вмешался он. Лишь раз дохнул он на моё искалеченное тело, а затем оставалось лишь дождаться, пока пески времени исцелят мои раны. \"Навеки останешься ты, коли так нужно,\" — сказал он, и с этими словами сделал меня Стражем. Только взгляни на пустыню. Вторая война неминуема. Найди тайное укрытие бронзовых драконов. Отправляйся в Пещеры Времени и узнай, не вернулся ли повелитель. Я должен знать наверняка, иначе не смогу действовать." },
    ["8286c"] = { common = "Так и должно быть — великий поднялся. Моё время подходит к концу…" },
    ["8287a"] = { common = "Ну вот… Ценная информация, скажу я тебе! Я видел, как силы Круга Кенария прибыли в Силитус. Они планируют выбить из наших краёв Сумеречный Молот, верно? Это поспособствует воплощению их планов. Отнеси этот пергамент их главе, командиру Мар'алиту. Скоро Сумеречный Молот изгонят из этих земель и их жадные ручки до меня не дотянутся!" },
    ["8287c"] = { common = "Очень интересные сведения, путник. Они проливают свет на деятельность Сумеречного Молота в Силитусе и несомненно помогут бороться с этой сектой. Вот тебе награда за труды, герой." },
    ["8288a"] = { common = "Время у нас на исходе! Нам необходим герой! Выполнить моё задание под силу лишь целой армии, но только одному из целой толпы будущих героев суждено принять на себя тяжкую ношу ответственности — стать союзником Племени. В логове повелителя Чёрной горы живёт жестокий зверь, предводитель драконов Разящий Бич. Он охраняет Зал Раздора, перекрывая путь в покои Нефариана. Убей гнусную тварь и принеси мне её голову. Это будет первым шагом на твоём пути." },
    ["8288c"] = { common = "Может ты будешь первым, кто добьётся уважения у Бронзовых драконов?" },
    ["8290a"] = { male = "Юный герой! Миновав этот проход, ты увидишь поле яростных сражений. Орда продолжает вырубать наши священные леса, уничтожая вечнозелёные кроны, чтобы питать свою военную машину! Отправляйся в Ущелье Песни Войны, чтобы оборонять Заставу Среброкрылых! Отражай нападения ордынских захватчиков! Наградой тебе будет талисман заслуг. Принеси мне такой талисман, и получишь награду!", female = "Юная героиня! Миновав этот проход, ты увидишь поле яростных сражений. Орда продолжает вырубать наши священные леса, уничтожая вечнозелёные кроны, чтобы питать свою военную машину! Отправляйся в Ущелье Песни Войны, чтобы оборонять Заставу Среброкрылых! Отражай нападения ордынских захватчиков! Наградой тебе будет талисман заслуг. Принеси мне такой талисман, и получишь награду!" },
    ["8295a"] = { male = "Чащобы Ясеневого леса падут пред мощью Орды, герой! Что бы ни делали часовые из клана Среброкрылых, им не совладать с нашим напором. Калимдор – это владения Орды! Как смеют они препятствовать нам пользоваться тем, что по праву наше? Пусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду! Разгроми часовых из клана Среброкрылых и заслужи почётный знак Ущелья Песни Войны. Вернись ко мне с этим знаком – и получишь награду!", female = "Чащобы Ясеневого леса падут пред мощью Орды, героиня! Что бы ни делали часовые из клана Среброкрылых, им не совладать с нашим напором. Калимдор – это владения Орды! Как смеют они препятствовать нам пользоваться тем, что по праву наше? Пусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду! Разгроми часовых из клана Среброкрылых и заслужи почётный знак Ущелья Песни Войны. Вернись ко мне с этим знаком – и получишь награду!" },
    ["8301a"] = { common = "Род Ноздорму инстинктивно не верит низшим расам. Хоть ты и смог доказать мне, что у тебя задатки настоящего героя, пришло время доказать это моему повелителю. Улей Аши, улей Зора и улей Регал кишат силитидами, которые грозят нашему существованию. Убей как можно больше проклятых тварей и принеси мне фрагменты их панцирей. Когда у тебя закончится место в заплечных мешках, возвращайся и я укреплю твою решимость." },
    ["8301c"] = { common = "Ты не одинок, герой. Сейчас я дам тебе возможность, выбрать других себе на помощь. Если ты хочешь быть истинным героем, то тебе нужна помощь в твоих задачах и обязанностях." },
    ["8303a"] = { common = "Время пришло, путник. Я должен извиниться за то, что так долго держал всё в тайне. Но кругом враги, они могут оказаться у нас прямо под носом. Прошу тебя, прими этот фолиант, читай его и учись. Я с радостью делюсь с тобой знаниями. Теперь же отыщи нашего повелителя." },
    ["8304a"] = { common = "Моя милая Наталия пропала. Честно говоря, в последние недели перед исчезновением она довольно странно вела себя. Я несколько раз видел, как она говорила сама с собой. При этом Наталия уверяла, что всё в порядке и ей необходимо продолжать исследования. В последний раз я видел её, когда она направилась в лагерь Бронзоборода, на юг. У меня слишком мало солдат, путник. Сходи в лагерь Бронзоборода и допроси дворфов." },
    ["8304c"] = { common = "Жива она или мертва, она всё равно должна быть найдена. Поможешь мне ещё один раз, путник??" },
    ["8305c"] = { common = "Вы чувствуете, что кристалл исполнен великой скорби, Сила её столь велика что вам кажется, будто вы немедленно рухнете и умрёте от тоски." },
    ["8306a"] = { common = "Прошу тебя, путник, отправляйся в Улей Регал и узнай, что сталось с моей возлюбленной Наталией. Это будет очень непросто. Прежде чем нырять в бездну безумия, вернись и поговори с дворфами. Быть может, они подскажут тебе, как разобраться с силитидами из улья. И последнее, путник. Если она в самом деле безумна, как говорят… сделай, что должно." },
    ["8306c"] = { common = "К'Тун? ЧТО всё это значит? Что ещё за К'Тун? Как мог этот демон превратить мою милую Наталию в описанного тобой монстра?" },
    ["8307a"] = { common = "Приспособиться к жизни в пустыне, мягко говоря, нелегко. Мне не хватает не только птиц и деревьев Аубердина, но и нормальной еды! Я делаю всё, что в моих силах, но выбор продуктов у нас невелик. Я изучаю местные травы, но их так мало… Зато я видела, как в лагерях Сумеречного Молота охотятся на песчаных червей. Но их мясо очень горькое, и я не представляю, как сделать его съедобным. Если ты окажешься в их лагере, смотри в оба. Как узнаешь что-нибудь — сообщи мне." },
    ["8307c"] = { common = "В книге содержится несколько обычных рецептов и пара очень оригинальных. Полистав её, вы находите рецепт, в котором упоминается мясо песчаных червей." },
    ["8308a"] = { common = "Всем заинтересованным лицам: Если вы читаете это письмо, значит, я мёртв или скоро умру. Трудно сказать. Большая часть команды уже мертва. Нашёл сведения про титана. Страшная битва между ним и Древним богом. Самый настоящий Древний Бог. Нашёл древний туннель в Ан'Кираж. Иду по нему. Отнесите это письмо в мой старый лагерь. Покормите, напоите и приласкайте моих обезьянок. — Бранн Бронзобород, оперативный исследователь Постскриптум. Остерегайся безумного ночного эльфа, поклоняющегося Древнему богу." },
    ["8308c"] = { common = "Что ж, многое прояснилось. Если ты доберёшься до Ан'Киража, посматривай, нет ли там старины Бранна. Боюсь, без своих обезьян он бессилен." },
    ["8309a"] = { common = "После нашего первого рейда в ульи и последовавшего безумия госпожи Мар'алит, из этих трёх ульев так и хлынули проклятые жуки! Мне кажется, их повышенная активность связана с письменами, покрывающими эти странные кристаллы. Нам нужны оттиски с кристаллов из всех трёх ульев. Заполучив их, мы можем попытаться понять причины этого безумия. Возьми копирующее устройство геолога и ступай в ульи, путник. Без оттисков из всех ульев даже не возвращайся." },
    ["8309c"] = { common = "Ничего я не понимаю в этих письменах. Первый раз такие вижу! Надеюсь, исследования Франкала помогут пролить на них свет." },
    ["8310a"] = { common = "Мне кажется, я изобрёл эликсир, который поможет нам расшифровать письмена и язык силитидов и киражей! Что мне нужно? Хорошо, что ты спросил! Мне нужны мозги! Точнее говоря, мозги всех видов силитидов, живущих в ульях. Принеси мне мозги, и работа Рутгара не пойдёт насмарку." },
    ["8310c"] = { common = "Поразительно! Не уходи далеко, дитя. Может быть, мы поручим тебе ещё задание-другое." },
    ["8311a"] = { common = "Хотел бы я пойти потыквовинничать, но не могу – приболел. Если ты вместо меня сходишь, я обменяю тебе сладости, что ты наберёшь, на те, что у меня уже есть. Думаю, тебе они понравятся – они превратят тебя в разные смешные и страшные штуки! У каждого из хозяев таверн в больших городах есть сладости, которые они раздают на Тыквовин. Поговори с ними и выполни их задания. А ещё в Стальгорне живёт гном по имени Талваш, и он тоже раздаёт сладости. Когда соберёшь их все, принеси мне сюда!" },
    ["8311c"] = { common = "Ух ты, тебе удалось собрать их все! Просто супер! Спасибо за то, что тыквовинничал вместо меня. Вот, возьми эти тыквовинские конфетки – я уверен, ты будешь от них в восторге! Счастливого Тыквовина!" },
    ["8312a"] = { common = "Я так хотела бы пойти просить сладости! Но не могу, потому что болею... Сходи вместо меня, а? А я с тобой потом поменяюсь: отдам те конфеты, что у меня уже есть, взамен тех, которые дадут тебе! Вот эта конфетка тебе наверняка понравится: она позволяет превращаться в разных существ, забавных и страшных! У всех хозяев таверн в больших городах непременно есть конфеты, которые они дарят на Тыквовин – надо только поговорить с ними и сделать то, что они попросят. И троллиха по имени Кали Ремик в деревне Сен'джин тоже раздаёт конфеты. Когда соберёшь все конфеты, принеси их мне, ладно?" },
    ["8312c"] = { common = "Ух ты! Тебе удалось собрать их все! Ты настоящий герой! Спасибо большое. Вот, возьми эти тыквовинские конфеты – они ужасно вкусные! Счастливого Тыквовина!" },
    ["8313a"] = { common = "Хотя вам вполне понятен рецепт по приготовлению мяса песчаного червя, в нём упоминаются незнакомые травы и специи. Быть может, Каландрата хорошо разбирается в растениях пустыни и сможет помочь вам." },
    ["8313c"] = { common = "Дай-ка взглянуть… Кажется, всё просто. У них есть свои названия для некоторых видов растений, но догадаться совсем просто. Дай, я покажу!" },
    ["8314a"] = { common = "Мы на грани крупного прорыва, путник! Принесённые тобой оттиски позволили нам воссоздать письмена на хрустальной призме. Очевидно, что для киражей и прочих непонятных сущностей они имеют большое значение и позволяют передавать силитидам сообщения. К несчастью, это всё, что нам удалось понять. Необходимо прочитать послания, сокрытые в кристаллах. Отнеси покрытую письменами хрустальную призму геологу Ехидной в Крепость Кенария. Может, она сумеет тебе помочь." },
    ["8314c"] = { common = "Дворфы не смогли расшифровать письмена, потому что тут и расшифровывать нечего. Следовало просто правильно повернуть верхний слой призмы, так, чтобы он выровнялся с изображениями внутри кристалла. Тогда сообщение можно прочитать. Умно… Впрочем, хотя теперь мы можем перевести полученные данные, главное — понять их правильно. На поверхности призмы есть только одна подсказка — если я правильно перевела оттиски — и если ей верить, то дело плохо." },
    ["8315a"] = { common = "Здесь изображена встреча посланника киражей с тремя силитидами у костей большого дракона. Над рисунком я вижу надпись, судя по всему, какой-то шифр. Не исключено, что это ключевой момент призыва посланника. Я создам копию, попробуй воспользоваться ей в пустыне у Костей Граккаронда. Если я права, вожди решат, что им посылают какие-то данные и явятся на зов. Убей их и сразись с посланником. Ключ к кристаллам у него…" },
    ["8315c"] = { common = "В моих руках, история которой более двадцати тысяч лет, путник!" },
    ["8316c"] = { common = "Война на подходе, путник, а вместе с ней приходят великие ужасы. Ты сделал всё, что от тебя требовалось и за это тебя ждёт вознаграждение… Будущее может быть концом для всех нас. Это снаряжение будет иметь огромное значение для твоей кампании в этой пустыне." },
    ["8317a"] = { common = "Рецепт мне несомненно пригодится. Пора приниматься за работу, чтобы приготовить копчёные пустынные клёцки уже сегодня. Мне не помешала бы помощь, а уж я бы тебе отплатила сторицей." },
    ["8317c"] = { common = "Отлично! Ты мой спаситель. Не думала, что сторонники Сумеречного Молота могут придумать такой хороший рецепт." },
    ["8318a"] = { common = "Некоторые из служителей культа Сумеречного Молота носят с собой листы бумаги, на которых нацарапана какая-то неразборчивая писанина. Принеси мне целую пачку таких писулек. Я не могу понять, что означает эта ерунда, но дело не в том! При помощи этих бумажек происходят тайные переговоры их группировок. Чем больше текстов мы у них отнимем, тем сложнее им будет обмениваться сообщениями!" },
    ["8318c"] = { common = "Великолепно! Уберу-ка я их подальше, они мне потом пригодятся." },
    ["8320a"] = { common = "Сумеречный Молот, безумная секта, поклоняющаяся богам смерти и разрушения, разбила лагеря по всему Силитусу и день и ночь проводит свои ритуалы. Планы её сторонников нам неизвестны, но они как-то связаны с пульсирующими красными кристаллами, разбросанными по всей пустыне. Хотя, быть может, однажды нам удастся разгадать эту тайну, но сейчас главное — избавиться от угрозы. Ступай в их лагеря и найди там геолордов из культа Сумеречного Молота. Они командуют этими змеюками, поэтому нанести удар необходимо именно по ним!" },
    ["8320c"] = { common = "Ты отлично справился с этим заданием, путник. Смерть геолордов из культа Сумеречного Молота — серьёзный удар по силам культа. Будем надеяться, что мы сумели отсрочить выполнение их планов…" },
    ["8321a"] = { common = "Мы обнаружили ещё одну базу Сумеречного Молота. Она зовётся Сумеречная пещера и находится в северо-восточной части Силитуса. Их главарь, Вайрал Подлый, живёт именно в этой пещере, и его-то тебе и предстоит победить. Одолев злодея, принеси мне его перстень-печатку. Говорят, что в Сумеречной пещере можно насмотреться таких ужасов, что век не забудешь." },
    ["8321c"] = { common = "Получилось! Вайрал мёртв! Что ж, нападение Сумеречного Молота на Силитус обречено на провал. Их здесь ещё немало осталось, но они нескоро оправятся от сегодняшнего удара." },
    ["8323a"] = { common = "Теперь, когда у меня есть Сумеречный словарь, мне остаётся попросить тебя о небольшой услуге. В моей бывшей организации ежемесячно издаются тщательно закодированные сводки новостей. Если они получат новые сведения обо мне или решат перестать меня искать, об этом сообщат в \"Истинно верующем\". Хотя меня, безусловно, интересует подобная информация, в этих сводках могут быть и другие полезные сведения. Принеси мне как можно больше зашифрованных текстов, добытых у сторонников Сумеречного Молота." },
    ["8323c"] = { common = "Великолепно! Я как можно скорее займусь расшифровкой. Если мне попадётся интересная информация, я найду способ связаться с тобой." },
    ["8331a"] = { common = "Мы надеялись, что Сумеречный Молот свернёт свои операции в Силитусе… Увы, мы ошиблись. Благодаря постоянным нападениям на лагеря сектантов нам удалось выяснить, что Молот контролирует ещё более страшная сила, Совет Бездны. Для связи со служителями культа этот совет пользуется ветровыми камнями, рассеянными по лагерям Молота. Пришло время выступить против Совета Бездны. Поговори с ремесленницей Аурель Золотой Лист, в восточной части Крепости Кенария. Мы задумали одну хитрость, для которой необходимо её искусство." },
    ["8331c"] = { common = "Путник, добрый день. Мне сказали, тебя направляют против Совета Бездны? Если это так, то выслушай меня внимательно…" },
    ["8332a"] = { common = "Мы думаем, что при помощи ветрового камня можно устроить засаду на герцога Совета Бездны. Для этого придётся связаться с Советом через этот камень и убедить всех, что ты — один из командующих среднего ранга Сумеречного Молота. Чтобы эта хитрость удалась, необходим статусный медальон. Я могу создать его, но мне понадобится большой сверкающий осколок и талисманы храмовников Бездны. Принеси их мне, а остальное я сделаю сама." },
    ["8332c"] = { common = "А, очень хорошо. Я работаю над медальоном, теперь вместе с этими ингредиентами. Мне осталось совсем немного, чтобы закончить его… А, вот и он. Медальон в смысле. Ты должен носить медальон чтобы активировать ветровой камень культистов. И тогда ты сможешь замаскироваться как один из культистов и вызвать Совет Бездны." },
    ["8341a"] = { common = "Чтобы вызвать лордов Совета Бездны, необходим больший ветровой камень. К тому же они согласны беседовать лишь с самыми высокопоставленными представителями Сумеречного Молота. Но… Я придумала, как поработать над твоей маскировкой и обмануть лордов Бездны! Для этого понадобится кольцо Власти, которое носят лишь вожди культистов. Я готова создать такое кольцо, если ты принесёшь мне большие сверкающие осколки и перстни Бездны." },
    ["8341c"] = { common = "А, очень хорошо. Я работаю над кольцом, теперь вместе с этими ингредиентами. Мне осталось совсем немного, чтобы закончить его… А, вот и оно, кольцо в смысле. Ты должен носить кольцо чтобы активировать ветровой камень культистов. И тогда ты сможешь замаскироваться как один из культистов и вызвать Совет Бездны." },
    ["8343a"] = { common = "Путник, Аурель придумала, как вызвать и одолеть правящую верхушку Совета Бездны! Это опасно, но ты заслужил уважение всего Круга Кенария. Мы знаем, что ты — единственный, кому по плечу такое задание. Желаю удачи, путник. Когда решишь приняться за это задание, поговори с Аурель." },
    ["8343c"] = { common = "То, что говорит Хуум, правда. Кажется, я знаю, как вызвать правящую верхушку Совета Бездны! Слушай меня внимательно…" },
    ["8348a"] = { common = "Хуум говорит, что ты придумал, как вызвать герцогов Бездны! Это большое достижение. Знаешь, что бы ещё хорошо сделать? Убить одного из них. Это произвело бы неизгладимое впечатление на их прихвостней, если ты понимаешь, о чём я. В доказательство собственного подвига принеси перстень герцога." },
    ["8348c"] = { common = "Я знал, что ты сильный герой, как только увидел, как ты шествуешь по Крепости Кенария. Так держать!" },
    ["8349a"] = { common = "Теперь у тебя есть медальон, и ты можешь вызвать герцога Бездны. Поговори с Бором Буйногривым. Он даст тебе задание. Удачи, путник. Если тебе снова понадобятся медальоны, возвращайся ко мне." },
    ["8349c"] = { common = "Рад видеть тебя снова, герой! У тебя уже есть медальон? Отлично. Он понадобиться тебе для следующего задания…" },
    ["8351a"] = { common = "Теперь ты можешь замаскироваться под высокопоставленного представителя Сумрачного Совета, и с тобой хочет поговорить Бор Буйногривый. Ступай, поговори с ним и готовься к трудному заданию…" },
    ["8351c"] = { common = "Да, всё верно, путник. Впереди тебя ждёт очень сложное задание…" },
    ["8352a"] = { common = "Мы с Хуумом только что обсуждали тебя. Он говорит, что ты готов испытать себя и сразиться с лордом Бездны! Должен предупредить, что это очень опасно. Возьми с собой подкрепление. И не пару друзей, а хороший боевой отряд. Если твои друзья стоят тебя, кто знает, может быть, удастся одолеть этого лорда! Если ты вдруг справишься — мне как всегда потребуются доказательства — то тебя ждёт великая награда." },
    ["8352c"] = { common = "Ты… ты сделал это, путник! Вот, возьми! Это самый большой сундук, который у нас есть и я наполнил его лучшими материалами, которые мы имеем." },
    ["8361a"] = { common = "Мы видели, как сектанты проводят ритуалы и вызывают могущественных повелителей стихий. Мы не знаем, поклоняются ли им культисты или используют как посредников при общении с ещё более страшными силами. Ясно одно — они получают приказы от этих элементалей. Отыщи храмовника Бездны и задай ему хорошую трёпку! Стоит лишить войска командира, и в их рядах начинается разброд и шатания. Принеси доказательство своего подвига." },
    ["8361c"] = { common = "Ха! Ты сделал это, путник!" },
    ["8365a"] = { male = "Так это тебя Картель послал к нам на помощь? Пожалуй, ты сойдёшь. Слушай внимательно, герой. Ты ведь знаешь, что я законодатель мод Азерота? Короли и королевы, вожди и... как там Орда называет своих королев? Одним словом, все носят, что я укажу. И платят за это бешеные деньги, что особенно приятно. В общем, поступим так. Отправляйся в Бухту Сорванных Парусов и раздобудь побольше пиратских шляп. Справишься?", female = "Так это тебя Картель послал к нам на помощь? Пожалуй, ты сойдёшь. Слушай внимательно, героиня. Ты ведь знаешь, что я законодатель мод Азерота? Короли и королевы, вожди и... как там Орда называет своих королев? Одним словом, все носят, что я укажу. И платят за это бешеные деньги, что особенно приятно. В общем, поступим так. Отправляйся в Бухту Сорванных Парусов и раздобудь побольше пиратских шляп. Справишься?" },
    ["8365c"] = { male = "Ты просто душка, даже если провозился дольше, чем я привыкла. Остаётся почистить и украсить эти шляпы, и я заработаю кругленькую сумму! Я всегда считала, что за хорошую работу полагается вознаграждение. Вот, возьми. И советую потратить часть на хорошую ванну, солнышко.", female = "Ты просто душка, даже если провозилась дольше, чем я привыкла. Остаётся почистить и украсить эти шляпы, и я заработаю кругленькую сумму! Я всегда считала, что за хорошую работу полагается вознаграждение. Вот, возьми. И советую потратить часть на хорошую ванну, солнышко." },
    ["8366a"] = { common = "Они требуют от меня невозможного! Картель Хитрая Шестерёнка хочет, чтобы я преподал пиратам Южных Морей урок. Мне что, разорваться?! Я должен поддерживать здесь порядок. В последнее время пираты забыли, что Картель платит им за защиту. Нужно показать им, что к чему. Пираты поселились в Бухте Сорванных Парусов, неподалёку отсюда, на юге. Спасибо. Я твой должник!" },
    ["8366c"] = { male = "Да ты просто герой!!! Теперь-то Картель от меня отстанет, ведь эта шваль получила по заслугам! Так, что бы дать тебе в награду? Пожалуй, немного денег, да ещё выбери из этих вещей, что понравится.", female = "Да ты просто героиня!!! Теперь-то Картель от меня отстанет, ведь эта шваль получила по заслугам! Так, что бы дать тебе в награду? Пожалуй, немного денег, да ещё выбери из этих вещей, что понравится." },
    ["8367a"] = { common = "Нет выше чести, чем биться с Альянсом во имя Орды! Лучшие же наши воины — те немногие, которым довелось сразиться на ВСЕХ полях битвы. Отдельные стычки не помогут нам одолеть врага. Лишь тщательно спланировав наступление, мы сломим проклятый Альянс. Ступай в Низину Арати, Альтеракскую долину и Ущелье Песни Войны и вступи в схватку с Альянсом. За честь! За Орду!" },
    ["8367c"] = { common = "На твою долю выпали непростые испытания, но ты не лишился мужества и сила тебя не покинула. Знаки победы — пустое. Не по ним судят о твоей доблести. Выше голову, путник. Сегодня тебе подобает смотреть на других свысока, ведь ты настоящий герой!" },
    ["8368a"] = { common = "Битва со Среброкрылыми Часовыми за Ущелье Песни Войны имеет огромное значение. Под предлогом охраны леса, который им вовсе не принадлежит, бойцы Альянса пытаются лишить Орду важнейшего источника древесины. Не бывать тому! Возвращайся ко мне и приноси доказательства верной службы Орде!" },
    ["8368c"] = { male = "Великолепно! Ты показал, чего стоишь, выступив против врага в Ущелье Песни Войны! Да разнесутся вести о твоих подвигах по всем нашим землям.", female = "Великолепно! Ты показала, чего стоишь, выступив против врага в Ущелье Песни Войны! Да разнесутся вести о твоих подвигах по всем нашим землям." },
    ["8370a"] = { common = "Наш конфликт с Альянсом дошёл до открытой войны. Никто уже не ищет предлогов, чтобы вступить в бой. В Низине Арати идёт простая и открытая борьба за ресурсы. Или они попадут в руки Альянса и обратятся в оружие против нас, или их захватим мы и вооружим наши войска! Помоги нам захватить источник ресурсов!" },
    ["8371a"] = { male = "В войне против Орды решающей может оказаться любая битва, сынок. Победа на одном фронте позволит захватить ресурсы, которые помогут победить и на другом. И с точностью до наоборот — любая проигранная битва может дать нашим врагам преимущество в другой. Альянсу не хватает бойцов, которые бы хорошенько поняли это… бойцов, закалённых в битвах! Отправляйся сражаться с Ордой, а когда побываешь на всех полях битвы, возвращайся ко мне.", female = "В войне против Орды решающей может оказаться любая битва, дочка. Победа на одном фронте позволит захватить ресурсы, которые помогут победить и на другом. И с точностью до наоборот — любая проигранная битва может дать нашим врагам преимущество в другой. Альянсу не хватает бойцов, которые бы хорошенько поняли это… бойцов, закалённых в битвах! Отправляйся сражаться с Ордой, а когда побываешь на всех полях битвы, возвращайся ко мне." },
    ["8371c"] = { common = "Ты не разочаровал меня, путник! И ты получил большее, чем просто медали и отличия. Ты получил бесценный опыт и закалил свой дух. Хорошо сделано, герой. Ты настоящий герой Альянса!" },
    ["8372a"] = { common = "Среброкрылые Часовые вступили в бой со всадниками из клана Песни Войны, стараясь защитить от них лес. Впрочем, желание сохранить этот лес объсняется не только их любовью к природе. Этот лес представляет собой естественную преграду для наступления сил Орды. Без него Астранаар не продержался бы и дня, и в наши земли давно вторглась бы огромная армия Орды. Внеси свой вклад в борьбу со всадниками из клана Песни Войны! За Альянс!" },
    ["8374a"] = { common = "Чтобы выиграть войну, мало быть умнее и хитрее противника. Зачастую победа достаётся тем, в чьих руках сосредоточены все ресурсы. Ресурсов в Низине Арати – хоть отбавляй. Главное – захватить их первыми. Если победа будет за Альянсом, нашим солдатам достанется больше мечей и копий. Если Орде – те же мечи и копья обратятся против нас! Твой долг помочь Альянсу захватить Низину Арати!" },
    ["8375a"] = { common = "Не пойми меня превратно, путник. Орда совершенно справедливо считает долину Альтерака территорией клана Северного Волка. Видишь ли, экспедиция Грозовой Вершины прибыла в эти края как мирные исследователи. Они искали руду и древние реликвии, но нашли лишь смерть. Альянс не ожидал такой бессмысленной жестокости даже от клана Северного Волка. Вечная память отважным дворфам, павшим от рук вероломных орков. Ступай, герой, внеси свой вклад в битву за Альтеракскую долину. За Альянс!" },
    ["8375c"] = { common = "Ты выказал великую храбрость и силу духа перед лицом врага! Я расскажу вышестоящим о твоей отваге… и приукрашу ещё!" },
    ["8376c"] = { common = "Война на подходе, путник, а вместе с ней приходят великие ужасы. Ты сделал всё, что от тебя требовалось и за это тебя ждёт вознаграждение… Будущее может быть концом для всех нас. Это снаряжение будет иметь огромное значение для твоей кампании в этой пустыне." },
    ["8377c"] = { common = "Война на подходе, путник, а вместе с ней приходят великие ужасы. Ты сделал всё, что от тебя требовалось и за это тебя ждёт вознаграждение… Будущее может быть концом для всех нас. Это снаряжение будет иметь огромное значение для твоей кампании в этой пустыне." },
